CREATE OR REPLACE FUNCTION "booking_api"."allocate_reference"("workspace_company_id" "uuid", "requested_sequence_key" "text" DEFAULT 'default'::"text") RETURNS "text"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'quote_api', 'booking_api'
    AS $$
  select booking_api.allocate_reference(workspace_company_id, requested_sequence_key, null);
$$;


ALTER FUNCTION "booking_api"."allocate_reference"("workspace_company_id" "uuid", "requested_sequence_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."allocate_reference"("workspace_company_id" "uuid", "requested_sequence_key" "text", "requested_direction" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'quote_api', 'booking_api'
    AS $$
declare
  sequence_key_value text := coalesce(nullif(lower(btrim(requested_sequence_key)), ''), 'default');
  sequence_row quote_api.booking_reference_sequences%rowtype;
  allocated record;
begin
  insert into quote_api.booking_reference_sequences (
    company_id, sequence_key, label, pattern, next_number, enabled
  ) values (
    workspace_company_id, sequence_key_value,
    case when sequence_key_value = 'default' then 'Default booking' else initcap(replace(sequence_key_value, '_', ' ')) end,
    'B-{NUMBER:4}', 1, true
  ) on conflict (company_id, sequence_key) do nothing;
  select reference.* into strict sequence_row
  from quote_api.booking_reference_sequences reference
  where reference.company_id = workspace_company_id
    and reference.sequence_key = sequence_key_value
    and reference.enabled
  for update;
  select * into allocated from quote_api.reserve_reference(
    workspace_company_id, 'booking', sequence_key_value,
    sequence_row.pattern, sequence_row.next_number, requested_direction
  );
  update quote_api.booking_reference_sequences
  set next_number = allocated.next_number, updated_at = now()
  where company_id = workspace_company_id and sequence_key = sequence_key_value;
  return allocated.reference_value;
exception
  when no_data_found then
    raise exception 'Choose an active booking reference sequence.' using errcode = '22023';
end;
$$;


ALTER FUNCTION "booking_api"."allocate_reference"("workspace_company_id" "uuid", "requested_sequence_key" "text", "requested_direction" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."allocation_review_values"("job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $_$
  select jsonb_build_object(
    'allocations',coalesce((select jsonb_agg(booking_api.allocation_values(a)-'archived' order by a.id)
      from booking_api.cargo_equipment_allocations a where a.job_id=$1 and not a.is_deleted),'[]'::jsonb),
    'cargo',coalesce((select jsonb_agg(jsonb_build_object('id',c."JobCargo_ID",'description',c."JobCargo_Description",
      'packageQuantity',c."JobCargo_PackageQty"::text,'grossWeightKg',c."JobCargo_GrossKilos"::text,'volumeCbm',c."JobCargo_VolumeCBM"::text) order by c."JobCargo_ID")
      from public."Job_Cargo" c where c."JobCargo_JobID"=$1 and not c."JobCargo_IsDeleted"),'[]'::jsonb),
    'equipment',coalesce((select jsonb_agg(jsonb_build_object('id',e."JobContainers_ID",'number',e."JobContainer_Number",'type',e."JobContainer_TypeCodeSnapshot") order by e."JobContainers_ID")
      from public."Job_Containers" e where e."Job_ID"=$1 and not e."JobContainer_IsDeleted"),'[]'::jsonb),
    'routes',coalesce((select jsonb_agg(jsonb_build_object('id',r."JobRoute_ID",'order',r."JobRoute_OrderNo",'mode',r."JobRoute_ModeCode") order by r."JobRoute_ID")
      from public."Job_Routing" r where r."Job_ID"=$1),'[]'::jsonb))
$_$;


ALTER FUNCTION "booking_api"."allocation_review_values"("job_id" "uuid") OWNER TO "postgres";

SET default_tablespace = '';

SET default_table_access_method = "heap";


CREATE TABLE IF NOT EXISTS "booking_api"."cargo_equipment_allocations" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "job_id" "uuid" NOT NULL,
    "cargo_id" "uuid" NOT NULL,
    "container_id" "uuid" NOT NULL,
    "route_id" "uuid",
    "package_quantity" numeric(18,6),
    "gross_weight_kg" numeric(18,2),
    "volume_cbm" numeric(18,6),
    "notes" "text",
    "is_deleted" boolean DEFAULT false NOT NULL,
    "created_at" timestamp with time zone DEFAULT "clock_timestamp"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "clock_timestamp"() NOT NULL,
    "created_by" "uuid" NOT NULL,
    "updated_by" "uuid" NOT NULL,
    "active_cargo_id" "uuid" GENERATED ALWAYS AS (
CASE
    WHEN (NOT "is_deleted") THEN "cargo_id"
    ELSE NULL::"uuid"
END) STORED,
    "route_scope_id" "uuid" GENERATED ALWAYS AS (COALESCE("route_id", '00000000-0000-0000-0000-000000000000'::"uuid")) STORED,
    CONSTRAINT "allocation_notes_length" CHECK (("length"("notes") <= 2000)),
    CONSTRAINT "allocation_packages_valid" CHECK ((("package_quantity" >= (0)::numeric) AND ("package_quantity" <> 'NaN'::numeric))),
    CONSTRAINT "allocation_volume_valid" CHECK ((("volume_cbm" >= (0)::numeric) AND ("volume_cbm" <> 'NaN'::numeric))),
    CONSTRAINT "allocation_weight_valid" CHECK ((("gross_weight_kg" >= (0)::numeric) AND ("gross_weight_kg" <> 'NaN'::numeric)))
);


ALTER TABLE "booking_api"."cargo_equipment_allocations" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."allocation_values"("item" "booking_api"."cargo_equipment_allocations") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object('id',item.id,'cargoId',item.cargo_id,'containerId',item.container_id,
    'routeId',item.route_id,'packageQuantity',item.package_quantity::text,
    'grossWeightKg',item.gross_weight_kg::text,'volumeCbm',item.volume_cbm::text,
    'notes',item.notes,'archived',item.is_deleted);
$$;


ALTER FUNCTION "booking_api"."allocation_values"("item" "booking_api"."cargo_equipment_allocations") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."apply_accepted_quote_schedule_to_new_route"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  source_snapshot jsonb;
  schedule_facts jsonb;
  departure_text text;
  arrival_text text;
  valid_from_text text;
  deadline_text text;
  departure_date date;
  arrival_date date;
  legacy_departure date;
  legacy_arrival date;
begin
  if not coalesce(new."JobRoute_IsMainCarriage", false) then return new; end if;
  if exists (
    select 1 from public."Job_Routing" route
    where route."Job_ID" = new."Job_ID" and route."JobRoute_IsMainCarriage"
  ) then return new; end if;

  select job."Job_SourceSnapshotJSON"
  into source_snapshot
  from public."Job_Header" job
  where job."Job_ID" = new."Job_ID"
    and job."Job_SourceQuoteID" is not null
    and not job."Job_IsDeleted";
  if not found then return new; end if;

  schedule_facts := coalesce(
    source_snapshot #> '{acceptedSnapshot,quote,shipmentFacts}',
    source_snapshot #> '{quote,shipmentFacts}',
    '{}'::jsonb
  );
  departure_text := nullif(btrim(schedule_facts->>'estimatedDeparture'), '');
  arrival_text := nullif(btrim(schedule_facts->>'estimatedArrival'), '');
  valid_from_text := nullif(btrim(coalesce(
    source_snapshot #>> '{acceptedSnapshot,quote,validFrom}',
    source_snapshot #>> '{quote,validFrom}'
  )), '');
  deadline_text := nullif(btrim(coalesce(
    source_snapshot #>> '{acceptedSnapshot,quote,deadline}',
    source_snapshot #>> '{quote,deadline}'
  )), '');
  if departure_text ~ '^\d{4}-\d{2}-\d{2}$' then departure_date := departure_text::date; end if;
  if arrival_text ~ '^\d{4}-\d{2}-\d{2}$' then arrival_date := arrival_text::date; end if;
  if valid_from_text ~ '^\d{4}-\d{2}-\d{2}$' then legacy_departure := valid_from_text::date; end if;
  if deadline_text ~ '^\d{4}-\d{2}-\d{2}$' then legacy_arrival := deadline_text::date; end if;

  if new."JobRoute_PlannedDepartureAt" is null or new."JobRoute_PlannedDepartureAt"::date = legacy_departure then
    new."JobRoute_PlannedDepartureAt" := departure_date;
  end if;
  if new."JobRoute_PlannedArrivalAt" is null or new."JobRoute_PlannedArrivalAt"::date = legacy_arrival then
    new."JobRoute_PlannedArrivalAt" := arrival_date;
  end if;
  update public."Job_Header" set
    "Job_ReadyDate" = case
      when "Job_ReadyDate" is null or "Job_ReadyDate" = legacy_departure then departure_date
      else "Job_ReadyDate"
    end,
    "Job_RequiredDeliveryDate" = case
      when "Job_RequiredDeliveryDate" is null or "Job_RequiredDeliveryDate" = legacy_arrival then arrival_date
      else "Job_RequiredDeliveryDate"
    end,
    "Job_UpdatedAt" = now()
  where "Job_ID" = new."Job_ID"
    and (
      "Job_ReadyDate" is null or "Job_ReadyDate" = legacy_departure
      or "Job_RequiredDeliveryDate" is null or "Job_RequiredDeliveryDate" = legacy_arrival
    );
  return new;
end;
$_$;


ALTER FUNCTION "booking_api"."apply_accepted_quote_schedule_to_new_route"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."apply_directional_reference"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'quote_api', 'booking_api'
    AS $$
declare
  workspace_company_id uuid;
  sequence_pattern text;
  direction_value text;
  direction_prefix text;
  import_prefix text;
begin
  if nullif(btrim(new."Job_BookingReference"), '') is null then return new; end if;
  select office."Company_ID" into workspace_company_id from public."cmp_Offices" office
  where office."Office_ID" = coalesce(new."Job_OrgOfficeID", new."Job_OfficeID");
  select sequence.pattern into sequence_pattern from quote_api.booking_reference_sequences sequence
  where sequence.company_id = workspace_company_id
    and sequence.sequence_key = coalesce(nullif(new."Job_BookingReferenceSequenceKey", ''), 'default')
    and sequence.enabled;
  if sequence_pattern is null or sequence_pattern !~ '\{DIRECTION(?::[0-9]{1,2})?\}' then return new; end if;
  direction_value := lower(coalesce(
    (select quote."CusQuoteHeader_Direction" from public."CusQuote_Header" quote where quote."CusQuoteHeader_ID" = new."Job_SourceQuoteID"),
    new."Job_Direction", ''));
  if direction_value not in ('import', 'export') then return new; end if;
  direction_prefix := split_part(sequence_pattern, '{DIRECTION', 1);
  import_prefix := quote_api.reference_literal(direction_prefix, workspace_company_id);
  if import_prefix <> '' and left(new."Job_BookingReference", length(import_prefix) + 1) = import_prefix || 'I' then
    new."Job_BookingReference" := import_prefix || case when direction_value = 'export' then 'E' else 'I' end || substr(new."Job_BookingReference", length(import_prefix) + 2);
  end if;
  return new;
end;
$$;


ALTER FUNCTION "booking_api"."apply_directional_reference"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."apply_quote_cargo_fields"("caller_auth_user_id" "uuid", "requested_job_id" "uuid", "requested_review_id" "uuid", "requested_fields" "jsonb", "observed_booking_lines" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  app_user record; job_row record; review_row record; plan jsonb; item jsonb; target jsonb;
  selected_fields jsonb; combined_fields jsonb; remaining_count integer; cargo_id uuid;
  next_line integer; updated_count integer; before_lines jsonb; after_lines jsonb; applied_changes jsonb:='[]';
  snapshot jsonb; source_values jsonb; compatibility_errors text[]; field_prefix text; write_fields jsonb;
begin
  if caller_auth_user_id is null or not booking_api.has_permission(caller_auth_user_id,'Bookings.Write') then
    raise exception 'Booking changes are not authorised.' using errcode='42501'; end if;
  select "User_ID","Company_ID" into strict app_user from public."cmp_Users"
    where "Auth_User_ID"=caller_auth_user_id and "User_AccessStatus"='active';
  select job.* into strict job_row from public."Job_Header" job
    join public."cmp_Offices" office on office."Office_ID"=coalesce(job."Job_OrgOfficeID",job."Job_OfficeID")
    where job."Job_ID"=requested_job_id and not job."Job_IsDeleted" and office."Company_ID"=app_user."Company_ID" for update of job;
  select * into strict review_row from booking_api.quote_sync_reviews
    where review_id=requested_review_id and job_id=requested_job_id and company_id=app_user."Company_ID"
      and quote_id=job_row."Job_SourceQuoteID" and status_code in ('pending','partially_applied','applied') for update;
  if requested_fields is null or jsonb_typeof(requested_fields)<>'array' or jsonb_array_length(requested_fields) not between 1 and 8000 then
    raise exception 'Choose cargo fields to apply.' using errcode='22023'; end if;
  if (select count(distinct value) from jsonb_array_elements(requested_fields) item where jsonb_typeof(value)='string')<>jsonb_array_length(requested_fields)
    or exists(select 1 from jsonb_array_elements_text(requested_fields) field where field not like 'cargo:%'
      or not exists(select 1 from jsonb_array_elements(review_row.differences) d where d->>'key'=field)) then
    raise exception 'One or more cargo fields are not available in this review.' using errcode='22023'; end if;
  select coalesce(jsonb_agg(value),'[]'::jsonb) into selected_fields from jsonb_array_elements(requested_fields)
    where not review_row.applied_fields ? (value#>>'{}');
  -- A repeated request is a receipt, never permission to reapply stale values.
  if jsonb_array_length(selected_fields)=0 then
    return jsonb_build_object('reviewId',requested_review_id,'reused',true,'appliedFields',review_row.applied_fields,'changes','[]'::jsonb);
  end if;
  if review_row.status_code='applied' or job_row."Job_PendingQuoteVersionID" is distinct from review_row.proposed_version_id then
    raise exception 'The pending Quote review changed. Refresh before applying.' using errcode='40001'; end if;
  plan:=booking_api.plan_quote_cargo_revision(requested_job_id,review_row.applied_version_id,
    review_row.proposed_version_id,selected_fields,observed_booking_lines);
  select "CusQuoteVersion_SnapshotJSON" into strict snapshot from public."CusQuote_Versions"
    where "CusQuoteVersion_ID"=review_row.proposed_version_id;
  source_values:=quote_api.cargo_line_map(snapshot#>'{quote,shipmentFacts,cargoLines}');
  before_lines:=booking_api.current_source_cargo_lines(requested_job_id);
  select coalesce(max("JobCargo_LineNo"),0) into next_line from public."Job_Cargo" where "JobCargo_JobID"=requested_job_id;
  for item in select value from jsonb_array_elements(plan->'changes') loop
    cargo_id:=nullif(item->>'bookingCargoId','')::uuid; target:=item->'values';
    field_prefix:='cargo:'||(item->>'sourceLineId')||':';
    write_fields:=selected_fields;
    if selected_fields ? (field_prefix||'line') and item->>'operation'<>'remove' then
      select jsonb_agg(field_prefix||key) into write_fields from jsonb_object_keys(target) key;
    end if;
    if item->>'operation'<>'remove' then
      -- Validate authoritative incoming Quote values, not unselected operational
      -- text. An operator may have a longer description which must be retained.
      compatibility_errors:=quote_api.cargo_booking_missing(jsonb_build_array(
        (source_values->(item->>'sourceLineId'))||jsonb_build_object('id',item->>'sourceLineId')));
      if cardinality(compatibility_errors)>0 then raise exception 'Correct cargo before applying the Quote.' using errcode='22023',detail=to_jsonb(compatibility_errors)::text; end if;
    end if;
    if item->>'operation'='remove' then
      if cargo_id is not null then
        update public."Job_Cargo" set "JobCargo_IsDeleted"=true,"JobCargo_UpdatedAt"=now(),"JobCargo_UpdatedBy"=app_user."User_ID"
          where "JobCargo_ID"=cargo_id and "JobCargo_JobID"=requested_job_id and not "JobCargo_IsDeleted";
      end if;
    elsif cargo_id is null then
      next_line:=next_line+1;
      insert into public."Job_Cargo" (
        "JobCargo_JobID","JobCargo_LineNo","JobCargo_Description","JobCargo_Commodity","JobCargo_Qty","JobCargo_PackageQty",
        "JobCargo_PackageTypeCodeSnapshot","JobCargo_GrossKilos","JobCargo_NettKilos","JobCargo_VolumeCBM","JobCargo_ChargeableWeightKg",
        "JobCargo_Length","JobCargo_Width","JobCargo_Height","JobCargo_LengthUnit","JobCargo_HSCode","JobCargo_CountryOfOriginCodeSnapshot",
        "JobCargo_IsHazardous","JobCargo_IsTemperatureControlled","JobCargo_SourceQuoteVersionID","JobCargo_SourceQuoteLineID",
        "JobCargo_CargoJSON","JobCargo_UpdatedBy"
      ) values(requested_job_id,next_line,target->>'description',target->>'commodity',(target->>'packageQuantity')::numeric,(target->>'packageQuantity')::numeric,
        target->>'packageType',(target->>'grossWeightKg')::numeric,(target->>'netWeightKg')::numeric,(target->>'volumeCbm')::numeric,(target->>'chargeableWeightKg')::numeric,
        (target->>'length')::numeric,(target->>'width')::numeric,(target->>'height')::numeric,target->>'lengthUnit',target->>'hsCode',target->>'countryOfOrigin',
        (target->>'isHazardous')::boolean,(target->>'isTemperatureControlled')::boolean,review_row.proposed_version_id,(item->>'sourceLineId')::uuid,
        target||jsonb_build_object('source','accepted_quote_update','quoteVersionId',review_row.proposed_version_id,'quoteCargoLineId',item->>'sourceLineId'),app_user."User_ID")
      returning "JobCargo_ID" into cargo_id;
    else
      update public."Job_Cargo" set
        "JobCargo_Description"=case when write_fields ? (field_prefix||'description') then target->>'description' else "JobCargo_Description" end,
        "JobCargo_Commodity"=case when write_fields ? (field_prefix||'commodity') then target->>'commodity' else "JobCargo_Commodity" end,
        "JobCargo_Qty"=case when write_fields ? ('cargo:'||(item->>'sourceLineId')||':packageQuantity') then (target->>'packageQuantity')::numeric else "JobCargo_Qty" end,
        "JobCargo_PackageQty"=case when write_fields ? (field_prefix||'packageQuantity') then (target->>'packageQuantity')::numeric else "JobCargo_PackageQty" end,
        "JobCargo_PackageTypeCodeSnapshot"=case when write_fields ? (field_prefix||'packageType') then target->>'packageType' else "JobCargo_PackageTypeCodeSnapshot" end,
        "JobCargo_ChargeableWeightKg"=case when write_fields ? (field_prefix||'chargeableWeightKg') then (target->>'chargeableWeightKg')::numeric else "JobCargo_ChargeableWeightKg" end,
        "JobCargo_GrossKilos"=case when write_fields ? (field_prefix||'grossWeightKg') then (target->>'grossWeightKg')::numeric else "JobCargo_GrossKilos" end,
        "JobCargo_NettKilos"=case when write_fields ? (field_prefix||'netWeightKg') then (target->>'netWeightKg')::numeric else "JobCargo_NettKilos" end,
        "JobCargo_VolumeCBM"=case when write_fields ? (field_prefix||'volumeCbm') then (target->>'volumeCbm')::numeric else "JobCargo_VolumeCBM" end,
        "JobCargo_Length"=case when write_fields ? (field_prefix||'length') then (target->>'length')::numeric else "JobCargo_Length" end,
        "JobCargo_Width"=case when write_fields ? (field_prefix||'width') then (target->>'width')::numeric else "JobCargo_Width" end,
        "JobCargo_Height"=case when write_fields ? (field_prefix||'height') then (target->>'height')::numeric else "JobCargo_Height" end,
        "JobCargo_LengthUnit"=case when write_fields ? (field_prefix||'lengthUnit') then target->>'lengthUnit' else "JobCargo_LengthUnit" end,
        "JobCargo_HSCode"=case when write_fields ? (field_prefix||'hsCode') then target->>'hsCode' else "JobCargo_HSCode" end,
        "JobCargo_CountryOfOriginCodeSnapshot"=case when write_fields ? (field_prefix||'countryOfOrigin') then target->>'countryOfOrigin' else "JobCargo_CountryOfOriginCodeSnapshot" end,
        "JobCargo_IsHazardous"=case when write_fields ? (field_prefix||'isHazardous') then (target->>'isHazardous')::boolean else "JobCargo_IsHazardous" end,
        "JobCargo_IsTemperatureControlled"=case when write_fields ? (field_prefix||'isTemperatureControlled') then (target->>'isTemperatureControlled')::boolean else "JobCargo_IsTemperatureControlled" end,
        "JobCargo_CargoJSON"="JobCargo_CargoJSON"||coalesce((select jsonb_object_agg(key,value) from jsonb_each(target) where write_fields ? (field_prefix||key)),'{}'::jsonb),
        "JobCargo_UpdatedAt"=now(),"JobCargo_UpdatedBy"=app_user."User_ID"
      where "JobCargo_ID"=cargo_id and "JobCargo_JobID"=requested_job_id and not "JobCargo_IsDeleted";
      get diagnostics updated_count=row_count;
      if updated_count<>1 then raise exception 'Booking cargo changed. Refresh before applying.' using errcode='40001'; end if;
    end if;
    applied_changes:=applied_changes||jsonb_build_array(item||jsonb_build_object('bookingCargoId',cargo_id));
  end loop;
  select coalesce(jsonb_agg(distinct value),'[]'::jsonb) into combined_fields from jsonb_array_elements(review_row.applied_fields||selected_fields);
  select count(*) into remaining_count from jsonb_array_elements(review_row.differences) d where not combined_fields ? (d->>'key');
  update booking_api.quote_sync_reviews set applied_fields=combined_fields,
    status_code=case when remaining_count=0 then 'applied' else 'partially_applied' end,
    decided_by=app_user."User_ID",decided_at=case when remaining_count=0 then now() else decided_at end
    where review_id=requested_review_id;
  if remaining_count=0 then
    update public."Job_Header" set "Job_SourceQuoteVersionID"=review_row.proposed_version_id,
      "Job_SourceQuoteResponseID"=review_row.proposed_response_id,"Job_PendingQuoteVersionID"=null,"Job_PendingQuoteResponseID"=null,
      "Job_QuoteSyncStatus"='in_sync',"Job_QuoteSyncDetectedAt"=null,
      "Job_SourceSnapshotJSON"="Job_SourceSnapshotJSON"||jsonb_build_object('acceptedSnapshot',snapshot),
      "Job_UpdatedAt"=now(),"Job_UpdatedBy"=app_user."User_ID" where "Job_ID"=requested_job_id;
  else
    update public."Job_Header" set "Job_QuoteSyncStatus"='partially_applied',"Job_UpdatedAt"=now(),"Job_UpdatedBy"=app_user."User_ID" where "Job_ID"=requested_job_id;
  end if;
  after_lines:=booking_api.current_source_cargo_lines(requested_job_id);
  insert into booking_api.events(company_id,job_id,event_type,summary,metadata,actor_user_id)
    values(app_user."Company_ID",requested_job_id,
      case when remaining_count=0 then 'quote_update_applied' else 'quote_update_partially_applied' end,
      'Selected cargo changes from the accepted Quote were applied.',
      jsonb_build_object('reviewId',requested_review_id,'baselineVersionId',review_row.applied_version_id,'quoteVersionId',review_row.proposed_version_id,
        'appliedFields',selected_fields,'changes',applied_changes,'beforeCargo',before_lines,'afterCargo',after_lines,'remainingFields',remaining_count),app_user."User_ID");
  return jsonb_build_object('reviewId',requested_review_id,'reused',false,'appliedFields',combined_fields,'remainingFields',remaining_count,'changes',applied_changes);
exception when no_data_found or too_many_rows then
  raise exception 'The cargo review is unavailable in this workspace.' using errcode='42501';
end;
$$;


ALTER FUNCTION "booking_api"."apply_quote_cargo_fields"("caller_auth_user_id" "uuid", "requested_job_id" "uuid", "requested_review_id" "uuid", "requested_fields" "jsonb", "observed_booking_lines" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."apply_quote_routing_plan"("requested_job_id" "uuid", "requested_version_id" "uuid", "requested_actor_user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  proposed_routes jsonb;
  quote_route_count integer;
begin
  perform booking_api.apply_quote_routing_plan_before_labels_and_order_20260904(
    requested_job_id,requested_version_id,requested_actor_user_id
  );

  select booking_api.quote_sync_projection(version."CusQuoteVersion_SnapshotJSON")->'routing'
  into strict proposed_routes
  from public."CusQuote_Versions" version
  join public."Job_Header" job
    on job."Job_ID"=requested_job_id
   and job."Job_SourceQuoteID"=version."CusQuoteHeader_ID"
  where version."CusQuoteVersion_ID"=requested_version_id;

  quote_route_count := case when jsonb_typeof(proposed_routes)='array' then jsonb_array_length(proposed_routes) else 0 end;
  if quote_route_count=0 then return; end if;

  update public."Job_Routing" route set
    "JobRoute_RouteJSON"=route."JobRoute_RouteJSON" || jsonb_build_object(
      'carrierName', proposed_routes#>>array[(route."JobRoute_OrderNo"-1)::text,'carrierName']
    )
  where route."Job_ID"=requested_job_id
    and coalesce(route."JobRoute_Status", 'planned')<>'superseded'
    and route."JobRoute_RouteJSON"->>'source' in ('accepted_quote','accepted_quote_update')
    and route."JobRoute_OrderNo" between 1 and quote_route_count;

  with operational_order as (
    select route."JobRoute_ID",
      row_number() over (order by route."JobRoute_OrderNo",route."JobRoute_ID") as sequence_no
    from public."Job_Routing" route
    where route."Job_ID"=requested_job_id
      and coalesce(route."JobRoute_Status", 'planned')<>'superseded'
      and coalesce(route."JobRoute_RouteJSON"->>'source','') not in ('accepted_quote','accepted_quote_update')
  )
  update public."Job_Routing" route set
    "JobRoute_OrderNo"=(quote_route_count+operational_order.sequence_no)::integer,
    "JobRoute_UpdatedAt"=now(),
    "JobRoute_UpdatedBy"=requested_actor_user_id
  from operational_order
  where route."JobRoute_ID"=operational_order."JobRoute_ID";
exception when no_data_found or too_many_rows then
  raise exception 'The accepted quote routing plan is unavailable.' using errcode='P0002';
end;
$$;


ALTER FUNCTION "booking_api"."apply_quote_routing_plan"("requested_job_id" "uuid", "requested_version_id" "uuid", "requested_actor_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."apply_quote_routing_plan_before_labels_and_order_20260904"("requested_job_id" "uuid", "requested_version_id" "uuid", "requested_actor_user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  job_row record;
  version_row record;
  proposed_routes jsonb;
  leg jsonb;
  leg_order integer := 0;
  route_id uuid;
  applied_route_ids uuid[] := '{}'::uuid[];
  first_leg jsonb;
  last_leg jsonb;
  previous_routes jsonb;
begin
  select job.* into strict job_row
  from public."Job_Header" job
  where job."Job_ID"=requested_job_id and not job."Job_IsDeleted"
  for update;

  select version.* into strict version_row
  from public."CusQuote_Versions" version
  where version."CusQuoteVersion_ID"=requested_version_id
    and version."CusQuoteHeader_ID"=job_row."Job_SourceQuoteID";

  proposed_routes := booking_api.quote_sync_projection(version_row."CusQuoteVersion_SnapshotJSON")->'routing';
  if jsonb_typeof(proposed_routes) is distinct from 'array' then
    raise exception 'The accepted Quote needs a valid routing plan.' using errcode='22023'; end if;
  if jsonb_array_length(proposed_routes) not between 1 and 30 or exists(
    select 1 from jsonb_array_elements(proposed_routes) item where booking_api.normalise_mode(item->>'mode') is null) then
    raise exception 'The accepted Quote needs one to thirty routing legs with supported modes.' using errcode='22023'; end if;

  select coalesce(jsonb_agg(to_jsonb(route.*) order by route."JobRoute_OrderNo", route."JobRoute_ID"), '[]'::jsonb)
  into previous_routes
  from public."Job_Routing" route
  where route."Job_ID"=requested_job_id
    and coalesce(route."JobRoute_Status", 'planned')<>'superseded'
    and route."JobRoute_RouteJSON"->>'source' in ('accepted_quote','accepted_quote_update');

  for leg in select value from jsonb_array_elements(proposed_routes) loop
    leg_order := leg_order + 1;
    if nullif(btrim(leg->>'origin'),'') is null or nullif(btrim(leg->>'destination'),'') is null then
      raise exception 'Every quoted routing leg needs an origin and destination.' using errcode='22023';
    end if;

    select route."JobRoute_ID" into route_id
    from public."Job_Routing" route
    where route."Job_ID"=requested_job_id
      and coalesce(route."JobRoute_Status", 'planned')<>'superseded'
      and route."JobRoute_RouteJSON"->>'source' in ('accepted_quote','accepted_quote_update')
    order by route."JobRoute_OrderNo", route."JobRoute_ID"
    offset greatest(leg_order-1,0) limit 1;

    if route_id is null then
      insert into public."Job_Routing" (
        "Job_ID","JobRoute_OrderNo","JobRoute_Status","JobRoute_ModeCode",
        "JobRoute_OriginUNLocode","JobRoute_OriginNameSnapshot",
        "JobRoute_DestinationUNLocode","JobRoute_DestinationNameSnapshot",
        "JobRoute_PlannedDepartureAt","JobRoute_PlannedArrivalAt","JobRoute_Carrier",
        "JobRoute_ServiceLevel","JobRoute_IsMainCarriage","JobRoute_RouteJSON","JobRoute_UpdatedBy"
      ) values (
        requested_job_id,leg_order,'planned',booking_api.normalise_mode(leg->>'mode'),
        left(nullif(upper(btrim(leg->>'originUnlocode')),''),10),left(nullif(btrim(leg->>'origin'),''),180),
        left(nullif(upper(btrim(leg->>'destinationUnlocode')),''),10),left(nullif(btrim(leg->>'destination'),''),180),
        nullif(leg->>'plannedDepartureAt','')::timestamptz,nullif(leg->>'plannedArrivalAt','')::timestamptz,
        nullif(leg->>'carrierId','')::uuid,left(nullif(btrim(leg->>'serviceLevel'),''),80),leg_order=1,
        jsonb_build_object('source','accepted_quote_update','quoteVersionId',requested_version_id),requested_actor_user_id
      ) returning "JobRoute_ID" into route_id;
    else
      update public."Job_Routing" route set
        "JobRoute_OrderNo"=leg_order,
        "JobRoute_Status"='planned',
        "JobRoute_ModeCode"=booking_api.normalise_mode(leg->>'mode'),
        "JobRoute_OriginUNLocode"=left(nullif(upper(btrim(leg->>'originUnlocode')),''),10),
        "JobRoute_OriginNameSnapshot"=left(nullif(btrim(leg->>'origin'),''),180),
        "JobRoute_DestinationUNLocode"=left(nullif(upper(btrim(leg->>'destinationUnlocode')),''),10),
        "JobRoute_DestinationNameSnapshot"=left(nullif(btrim(leg->>'destination'),''),180),
        "JobRoute_PlannedDepartureAt"=nullif(leg->>'plannedDepartureAt','')::timestamptz,
        "JobRoute_PlannedArrivalAt"=nullif(leg->>'plannedArrivalAt','')::timestamptz,
        "JobRoute_Carrier"=nullif(leg->>'carrierId','')::uuid,
        "JobRoute_ServiceLevel"=left(nullif(btrim(leg->>'serviceLevel'),''),80),
        "JobRoute_IsMainCarriage"=leg_order=1,
        "JobRoute_RouteJSON"=route."JobRoute_RouteJSON" || jsonb_build_object(
          'source','accepted_quote_update','quoteVersionId',requested_version_id
        ),
        "JobRoute_UpdatedAt"=now(),
        "JobRoute_UpdatedBy"=requested_actor_user_id
      where route."JobRoute_ID"=route_id and route."Job_ID"=requested_job_id;
    end if;
    applied_route_ids := array_append(applied_route_ids, route_id);
    route_id := null;
  end loop;

  update public."Job_Routing" route set
    "JobRoute_Status"='superseded',
    "JobRoute_RouteJSON"=route."JobRoute_RouteJSON" || jsonb_build_object(
      'supersededByQuoteVersionId',requested_version_id,'supersededAt',now()
    ),
    "JobRoute_UpdatedAt"=now(),
    "JobRoute_UpdatedBy"=requested_actor_user_id
  where route."Job_ID"=requested_job_id
    and route."JobRoute_RouteJSON"->>'source' in ('accepted_quote','accepted_quote_update')
    and not (route."JobRoute_ID"=any(applied_route_ids));

  first_leg := proposed_routes->0;
  last_leg := proposed_routes->(jsonb_array_length(proposed_routes)-1);
  update public."Job_Header" set
    "Job_OriginUNLocode"=coalesce(nullif(first_leg->>'originUnlocode',''), "Job_OriginUNLocode"),
    "Job_OriginNameSnapshot"=coalesce(nullif(first_leg->>'origin',''), "Job_OriginNameSnapshot"),
    "Job_DestinationUNLocode"=coalesce(nullif(last_leg->>'destinationUnlocode',''), "Job_DestinationUNLocode"),
    "Job_DestinationNameSnapshot"=coalesce(nullif(last_leg->>'destination',''), "Job_DestinationNameSnapshot"),
    "Job_ReadyDate"=case when first_leg->>'plannedDepartureAt' ~ '^\d{4}-\d{2}-\d{2}$' then (first_leg->>'plannedDepartureAt')::date else "Job_ReadyDate" end,
    "Job_RequiredDeliveryDate"=case when last_leg->>'plannedArrivalAt' ~ '^\d{4}-\d{2}-\d{2}$' then (last_leg->>'plannedArrivalAt')::date else "Job_RequiredDeliveryDate" end,
    "Job_UpdatedAt"=now(),
    "Job_UpdatedBy"=requested_actor_user_id
  where "Job_ID"=requested_job_id;

  insert into booking_api.events(company_id,job_id,event_type,summary,metadata,actor_user_id)
  select office."Company_ID",job_row."Job_ID",'quote_routing_plan_applied',
    'The accepted quote routing plan was applied without changing booking-only routing legs.',
    jsonb_build_object('quoteVersionId',requested_version_id,'before',previous_routes,'after',proposed_routes),
    requested_actor_user_id
  from public."cmp_Offices" office
  where office."Office_ID"=coalesce(job_row."Job_OrgOfficeID",job_row."Job_OfficeID");
exception when no_data_found or too_many_rows then
  raise exception 'The accepted quote routing plan is unavailable.' using errcode='P0002';
end;
$_$;


ALTER FUNCTION "booking_api"."apply_quote_routing_plan_before_labels_and_order_20260904"("requested_job_id" "uuid", "requested_version_id" "uuid", "requested_actor_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."assert_cargo_allocations"("requested_job_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare invalid_cargo uuid;
begin
  if not exists(select 1 from booking_api.cargo_equipment_allocations where job_id=requested_job_id and not is_deleted) then return;end if;
  if exists(select 1 from booking_api.cargo_equipment_allocations a
    left join public."Job_Cargo" c on c."JobCargo_ID"=a.cargo_id and c."JobCargo_JobID"=a.job_id and not c."JobCargo_IsDeleted"
    left join public."Job_Containers" e on e."JobContainers_ID"=a.container_id and e."Job_ID"=a.job_id and not e."JobContainer_IsDeleted"
    left join public."Job_Routing" r on r."JobRoute_ID"=a.route_id and r."Job_ID"=a.job_id
    where a.job_id=requested_job_id and not a.is_deleted
      and (c."JobCargo_ID" is null or e."JobContainers_ID" is null or (a.route_id is not null and r."JobRoute_ID" is null))) then
    raise exception 'Remove or reassign cargo allocations before removing their cargo, equipment or routing leg.' using errcode='23514';
  end if;
  if exists(select 1 from booking_api.cargo_equipment_allocations where job_id=requested_job_id and not is_deleted
    group by cargo_id having bool_or(route_id is null) and bool_or(route_id is not null)) then
    raise exception 'Use either whole-journey or individual-leg allocations for each cargo line, not both.' using errcode='23514';
  end if;
  select a.cargo_id into invalid_cargo from booking_api.cargo_equipment_allocations a
    join public."Job_Cargo" c on c."JobCargo_ID"=a.cargo_id
    where a.job_id=requested_job_id and not a.is_deleted
    group by a.cargo_id,a.route_id,c."JobCargo_PackageQty",c."JobCargo_Qty",c."JobCargo_GrossKilos",c."JobCargo_VolumeCBM"
    having sum(a.package_quantity)>coalesce(c."JobCargo_PackageQty",c."JobCargo_Qty")
      or sum(a.gross_weight_kg)>c."JobCargo_GrossKilos" or sum(a.volume_cbm)>c."JobCargo_VolumeCBM" limit 1;
  if found then
    raise exception 'Cargo allocation exceeds its recorded packages, gross weight or volume. Review the allocations and cargo totals together.' using errcode='23514';
  end if;
end $$;


ALTER FUNCTION "booking_api"."assert_cargo_allocations"("requested_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."audit_cargo_allocation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare before_value jsonb; after_value jsonb;
begin
  before_value:=case when tg_op='UPDATE' then booking_api.allocation_values(old) else 'null'::jsonb end;
  after_value:=booking_api.allocation_values(new);
  if before_value is not distinct from after_value then return new;end if;
  insert into booking_api.events(company_id,job_id,event_type,summary,metadata,actor_user_id)
    select office."Company_ID",new.job_id,'cargo_allocation_changed','Cargo equipment allocation changed.',
      jsonb_build_object('allocationId',new.id,'before',before_value,'after',after_value),new.updated_by
    from public."Job_Header" job join public."cmp_Offices" office on office."Office_ID"=coalesce(job."Job_OrgOfficeID",job."Job_OfficeID")
    where job."Job_ID"=new.job_id;
  return new;
end $$;


