    "JobCargoDG_UNNumber" character varying(10),
    "JobCargoDG_ProperShippingName" character varying(240),
    "JobCargoDG_Class" character varying(20),
    "JobCargoDG_PackingGroup" character varying(20),
    "JobCargoDG_FlashPoint" character varying(40),
    "JobCargoDG_MarinePollutant" boolean,
    "JobCargoDG_LimitedQuantity" boolean,
    "JobCargoDG_EmergencyContact" character varying(180),
    "JobCargoDG_Notes" "text",
    "JobCargoDG_CreatedAt" timestamp with time zone DEFAULT "now"() NOT NULL,
    "JobCargoDG_Source" "text" DEFAULT 'legacy'::"text" NOT NULL,
    "JobCargoDG_SourceReference" character varying(500),
    "JobCargoDG_Status" "text" DEFAULT 'recorded'::"text" NOT NULL,
    "JobCargoDG_CreatedBy" "uuid",
    "JobCargoDG_UpdatedBy" "uuid",
    "JobCargoDG_UpdatedAt" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "booking_dg_source" CHECK (("JobCargoDG_Source" = ANY (ARRAY['legacy'::"text", 'operator'::"text"]))),
    CONSTRAINT "booking_dg_status" CHECK (("JobCargoDG_Status" = ANY (ARRAY['recorded'::"text", 'voided'::"text"])))
);


