CREATE TABLE IF NOT EXISTS "public"."Job_Cargo" (
    "JobCargo_ID" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "JobCargo_JobID" "uuid",
    "JobCargo_Commodity" character varying(50),
    "JobCargo_Qty" numeric(18,2),
    "JobCargo_Height" numeric(18,2),
    "JobCargo_Width" numeric(18,2),
    "JobCargo_Length" numeric(18,2),
    "JobCargo_GrossKilos" numeric(18,2),
    "JobCargo_NettKilos" numeric(18,2),
    "JobCargo_Packed" boolean DEFAULT false NOT NULL,
    "JobCargo_LineNo" integer,
    "JobCargo_Description" "text",
    "JobCargo_PackageTypeID" "uuid",
    "JobCargo_PackageTypeCodeSnapshot" character varying(40),
    "JobCargo_PackageQty" numeric(18,6),
    "JobCargo_MarksNumbers" "text",
    "JobCargo_HSCode" character varying(30),
    "JobCargo_CountryOfOriginCodeSnapshot" character varying(2),
    "JobCargo_VolumeCBM" numeric(18,6),
    "JobCargo_LengthUnit" character varying(20) DEFAULT 'cm'::character varying NOT NULL,
    "JobCargo_WeightUnit" character varying(20) DEFAULT 'kg'::character varying NOT NULL,
    "JobCargo_VolumeUnit" character varying(20) DEFAULT 'cbm'::character varying NOT NULL,
    "JobCargo_DeclaredValueAmount" numeric(18,4),
    "JobCargo_DeclaredValueCurrencyID" "uuid",
    "JobCargo_DeclaredValueCurrencyCodeSnapshot" character varying(3),
    "JobCargo_IsHazardous" boolean DEFAULT false NOT NULL,
    "JobCargo_IsTemperatureControlled" boolean DEFAULT false NOT NULL,
    "JobCargo_IsStackable" boolean,
    "JobCargo_CargoJSON" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "JobCargo_CreatedAt" timestamp with time zone DEFAULT "now"() NOT NULL,
    "JobCargo_UpdatedAt" timestamp with time zone DEFAULT "now"() NOT NULL,
    "JobCargo_UpdatedBy" "uuid",
    "JobCargo_IsDeleted" boolean DEFAULT false NOT NULL,
    "JobCargo_SourceQuoteVersionID" "uuid",
    "JobCargo_SourceQuoteLineID" "uuid",
    "JobCargo_ChargeableWeightKg" numeric,
    CONSTRAINT "Job_Cargo_JobCargo_ChargeableWeightKg_check" CHECK ((("JobCargo_ChargeableWeightKg" >= (0)::numeric) AND ("JobCargo_ChargeableWeightKg" <= ('999999999999'::bigint)::numeric))),
    CONSTRAINT "Job_Cargo_country_check" CHECK ((("JobCargo_CountryOfOriginCodeSnapshot" IS NULL) OR (("JobCargo_CountryOfOriginCodeSnapshot")::"text" ~ '^[A-Z]{2}$'::"text"))),
    CONSTRAINT "Job_Cargo_currency_check" CHECK ((("JobCargo_DeclaredValueCurrencyCodeSnapshot" IS NULL) OR (("JobCargo_DeclaredValueCurrencyCodeSnapshot")::"text" ~ '^[A-Z]{3}$'::"text"))),
    CONSTRAINT "Job_Cargo_line_number_check" CHECK ((("JobCargo_LineNo" IS NULL) OR ("JobCargo_LineNo" > 0)))
);


