CREATE OR REPLACE FUNCTION "booking_api"."check_allocation_job"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if tg_table_name='cargo_equipment_allocations' then
    perform booking_api.assert_cargo_allocations(new.job_id);
  elsif tg_table_name='Job_Cargo' then
    perform booking_api.assert_cargo_allocations(new."JobCargo_JobID");
  else
    perform booking_api.assert_cargo_allocations(new."Job_ID");
  end if;
  return new;
end $$;


ALTER FUNCTION "booking_api"."check_allocation_job"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."check_cargo_handling_status"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare job_id uuid; state text; missing text[];
begin
  if tg_table_name='Job_Header' then job_id:=new."Job_ID"; else job_id:=new."JobCargo_JobID"; end if;
  select "Job_Status" into state from public."Job_Header" where "Job_ID"=job_id and not "Job_IsDeleted" for update;
  if state in ('booked','in_transit','arrived','delivered','completed','ready_for_invoice','complete') then
    missing:=booking_api.cargo_handling_missing(job_id);
    if cardinality(missing)>0 then raise exception 'Resolve cargo handling TBC details before operational readiness or completion.' using errcode='22023',detail=to_jsonb(missing)::text; end if;
  end if;
  return new;
end $$;


ALTER FUNCTION "booking_api"."check_cargo_handling_status"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."complete_booking"("caller_auth_user_id" "uuid", "requested_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare app_user record; job_row record; readiness jsonb;
begin
  if caller_auth_user_id is null or not booking_api.has_permission(caller_auth_user_id, 'Bookings.Write') then
    raise exception 'Booking completion is not authorised.' using errcode = '42501';
  end if;
  select actor."User_ID", actor."Company_ID" into strict app_user from public."cmp_Users" actor
  where actor."Auth_User_ID" = caller_auth_user_id and actor."User_AccessStatus" = 'active';
  select job.* into job_row from public."Job_Header" job
  join public."cmp_Offices" office on office."Office_ID" = coalesce(job."Job_OrgOfficeID", job."Job_OfficeID")
  where job."Job_ID" = requested_job_id and office."Company_ID" = app_user."Company_ID" and not job."Job_IsDeleted" for update;
  if not found then raise exception 'That booking is outside this workspace.' using errcode = '42501'; end if;
  if job_row."Job_Status" in ('ready_for_invoice','complete') then
    return booking_api.operational_workspace(caller_auth_user_id, job_row."Job_BookingReference");
  end if;
  readiness := booking_api.completion_readiness_for_job(requested_job_id);
  if not coalesce((readiness->>'ready')::boolean, false) then
    raise exception 'Complete the job readiness items before finishing this booking.' using errcode = '22023', detail = readiness::text;
  end if;
  update public."Job_Header" set
    "Job_Status" = 'ready_for_invoice', "Job_TrackingStatus" = 'delivered', "Job_ClosedDate" = current_date,
    "Job_InvoiceStatus" = 'ready', "Job_InvoiceReadyAt" = now(), "Job_CompletedAt" = now(),
    "Job_CompletedBy" = app_user."User_ID", "Job_CompletionChecklistJSON" = readiness,
    "Job_UpdatedAt" = now(), "Job_UpdatedBy" = app_user."User_ID"
  where "Job_ID" = requested_job_id;
  insert into booking_api.events (company_id, job_id, event_type, summary, metadata, actor_user_id)
  values (app_user."Company_ID", requested_job_id, 'completed', 'Booking completed and made ready for invoice.', readiness, app_user."User_ID");
  return booking_api.operational_workspace(caller_auth_user_id, job_row."Job_BookingReference");
exception when no_data_found or too_many_rows then raise exception 'Your workspace identity is incomplete.' using errcode = '42501';
end;
$$;


ALTER FUNCTION "booking_api"."complete_booking"("caller_auth_user_id" "uuid", "requested_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."completion_readiness"("caller_auth_user_id" "uuid", "requested_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if caller_auth_user_id is null or not booking_api.has_permission(caller_auth_user_id, 'Bookings.Read') then
    raise exception 'Booking access is not authorised.' using errcode = '42501';
  end if;
  if not exists (
    select 1 from public."Job_Header" job
    join public."cmp_Offices" office on office."Office_ID" = coalesce(job."Job_OrgOfficeID", job."Job_OfficeID")
    join public."cmp_Users" actor on actor."Auth_User_ID" = caller_auth_user_id and actor."Company_ID" = office."Company_ID" and actor."User_AccessStatus" = 'active'
    where job."Job_ID" = requested_job_id and not job."Job_IsDeleted"
  ) then raise exception 'That booking is outside this workspace.' using errcode = '42501'; end if;
  return booking_api.completion_readiness_for_job(requested_job_id);
end;
$$;


ALTER FUNCTION "booking_api"."completion_readiness"("caller_auth_user_id" "uuid", "requested_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."completion_readiness_for_job"("requested_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  job_row record;
  route_row record;
  missing_value jsonb := '[]'::jsonb;
  warnings_value jsonb := '[]'::jsonb;
  total_checks integer := 8;
  missing_count integer;
  sea_container_count integer := 0;
  incomplete_container_count integer := 0;
begin
  select job.* into job_row from public."Job_Header" job
  where job."Job_ID" = requested_job_id and not job."Job_IsDeleted";
  if not found then raise exception 'That booking could not be found.' using errcode = 'P0002'; end if;

  select route.* into route_row from public."Job_Routing" route
  where route."Job_ID" = requested_job_id
  order by route."JobRoute_IsMainCarriage" desc, route."JobRoute_OrderNo" nulls last limit 1;

  if job_row."Job_Customer" is null then
    missing_value := missing_value || jsonb_build_array(jsonb_build_object('key','customer','label','Customer','section','Booking setup'));
  end if;
  if job_row."Job_Direction" is null or job_row."Job_Direction" = 'unknown'
     or job_row."Job_TransportModeSummary" is null
     or coalesce(job_row."Job_OriginNameSnapshot", job_row."Job_OriginUNLocode") is null
     or coalesce(job_row."Job_DestinationNameSnapshot", job_row."Job_DestinationUNLocode") is null then
    missing_value := missing_value || jsonb_build_array(jsonb_build_object('key','service_route','label','Direction, mode, origin and destination','section','Booking setup'));
  end if;
  if not exists (select 1 from public."Job_Cargo" cargo where cargo."JobCargo_JobID" = requested_job_id and not cargo."JobCargo_IsDeleted" and nullif(btrim(cargo."JobCargo_Description"), '') is not null) then
    missing_value := missing_value || jsonb_build_array(jsonb_build_object('key','goods_description','label','Goods description','section','Cargo & equipment'));
  end if;

  select count(*)::integer,
         count(*) filter (where nullif(btrim(container."JobContainer_Number"), '') is null or nullif(btrim(container."JobContainer_TypeCodeSnapshot"), '') is null)::integer
  into sea_container_count, incomplete_container_count
  from public."Job_Containers" container
  where container."Job_ID" = requested_job_id and not container."JobContainer_IsDeleted";
  if lower(coalesce(job_row."Job_TransportModeSummary", '')) = 'sea'
     and (sea_container_count = 0 or incomplete_container_count > 0) then
    missing_value := missing_value || jsonb_build_array(jsonb_build_object('key','container_details','label','Container type and number for every container','section','Cargo & equipment'));
  end if;
  if route_row."JobRoute_ID" is null or nullif(btrim(route_row."JobRoute_CarrierBookingReference"), '') is null then
    missing_value := missing_value || jsonb_build_array(jsonb_build_object('key','carrier_confirmation','label','Carrier booking reference','section','Routing & confirmation'));
  end if;
  if route_row."JobRoute_ActualDeliveryAt" is null then
    missing_value := missing_value || jsonb_build_array(jsonb_build_object('key','actual_delivery','label','Actual delivery date and time','section','Movement'));
  end if;
  if not exists (
    select 1 from public."Job_Documents" document
    where document."JobDoc_JobID" = requested_job_id and not document."JobDoc_IsDeleted"
      and document."JobDoc_IsCurrentVersion"
      and lower(coalesce(document."JobDoc_DocTypeCodeSnapshot", '')) in ('proof_of_delivery','pod','delivery_note','commercial_invoice','packing_list')
      and nullif(btrim(document."JobDoc_FileName"), '') is not null
  ) then
    missing_value := missing_value || jsonb_build_array(jsonb_build_object('key','job_document','label','Core job document (POD, delivery note, invoice or packing list)','section','Documents & Customs'));
  end if;
  if not exists (
    select 1 from public."Job_Costing_Lines" charge
    where charge."Job_ID" = requested_job_id
      and nullif(btrim(charge."JobCostingLine_Description"), '') is not null
      and (charge."JobCostingLine_CostAmountLocal" is not null or charge."JobCostingLine_RevenueAmountLocal" is not null)
  ) then
    missing_value := missing_value || jsonb_build_array(jsonb_build_object('key','finance','label','At least one cost or customer charge','section','Finance'));
  end if;

  if exists (
    select 1 from public."Customs_Declarations" declaration
    where declaration."CUST_JobID" = requested_job_id and not declaration."CUST_IsDeleted"
      and lower(declaration."CUST_Status") in ('draft','rejected','error')
  ) then
    warnings_value := warnings_value || jsonb_build_array(jsonb_build_object('key','customs_open','label','Customs declaration still needs attention','section','Documents & Customs'));
  end if;
  if job_row."Job_InvoiceReference" is null then
    warnings_value := warnings_value || jsonb_build_array(jsonb_build_object('key','invoice_reference','label','Invoice reference can be added after completion','section','Finance'));
  end if;


  total_checks := total_checks + 1;
  if cardinality(booking_api.cargo_handling_missing(requested_job_id))>0 then
    missing_value := missing_value || jsonb_build_array(jsonb_build_object('key','cargo_handling','label',array_to_string(booking_api.cargo_handling_missing(requested_job_id),'; '),'section','Cargo & equipment'));
  end if;
  missing_count := jsonb_array_length(missing_value);
  return jsonb_build_object(
    'ready', missing_count = 0,
    'locked', job_row."Job_Status" in ('ready_for_invoice','complete'),
    'percent', round(((total_checks - missing_count)::numeric / total_checks::numeric) * 100),
    'completeChecks', total_checks - missing_count,
    'totalChecks', total_checks,
    'missing', missing_value,
    'warnings', warnings_value,
    'evidence', jsonb_build_object(
      'status', job_row."Job_Status", 'invoiceStatus', job_row."Job_InvoiceStatus",
      'completedAt', job_row."Job_CompletedAt", 'containerCount', sea_container_count
    )
  );
end;
$$;


