CREATE OR REPLACE FUNCTION "booking_api"."convert_accepted_quote"("requested_quote_id" "uuid", "requested_actor_user_id" "uuid" DEFAULT NULL::"uuid", "requested_response_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  conversion_result jsonb;
  target_job record;
  version_snapshot jsonb;
begin
  conversion_result := booking_api.convert_accepted_quote_before_container_allocation_20260904(
    requested_quote_id,
    requested_actor_user_id,
    requested_response_id
  );

  if not coalesce((conversion_result->>'reused')::boolean, false)
     and not coalesce((conversion_result->>'outOfSync')::boolean, false) then
    select job.* into target_job
    from public."Job_Header" job
    where job."Job_ID" = (conversion_result->>'jobId')::uuid
    for update;

    if found and booking_api.normalise_mode(target_job."Job_TransportModeSummary") in ('sea', 'ocean') then
      select version."CusQuoteVersion_SnapshotJSON" into version_snapshot
      from public."CusQuote_Versions" version
      where version."CusQuoteVersion_ID" = target_job."Job_SourceQuoteVersionID";

      perform booking_api.replace_quote_containers(
        target_job."Job_ID",
        coalesce(requested_actor_user_id, target_job."Job_UpdatedBy", target_job."Job_CreatedBy"),
        version_snapshot,
        'accepted_quote',
        target_job."Job_SourceQuoteVersionID"
      );
    end if;
  end if;

  return conversion_result;
end;
$$;


ALTER FUNCTION "booking_api"."convert_accepted_quote"("requested_quote_id" "uuid", "requested_actor_user_id" "uuid", "requested_response_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "booking_api"."convert_accepted_quote"("requested_quote_id" "uuid", "requested_actor_user_id" "uuid", "requested_response_id" "uuid") IS 'Creates or reviews a booking from an accepted quote and preserves each structured sea-container request as an individual booking line.';



CREATE OR REPLACE FUNCTION "booking_api"."convert_accepted_quote_before_container_allocation_20260904"("requested_quote_id" "uuid", "requested_actor_user_id" "uuid" DEFAULT NULL::"uuid", "requested_response_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  existing_job record;
  quote_row record;
  active_review record;
begin
  select job.* into existing_job
  from public."Job_Header" job
  where job."Job_SourceQuoteID" = requested_quote_id
    and not job."Job_IsDeleted"
  order by job."Job_CreatedDate"
  limit 1
  for update;

  if found then
    select quote.* into strict quote_row
    from public."CusQuote_Header" quote
    where quote."CusQuoteHeader_ID" = requested_quote_id
      and quote."CusQuoteHeader_LifecycleCode" = 'accepted'
      and not quote."CusQuoteHeader_IsDeleted";

    select review.* into active_review
    from booking_api.quote_sync_reviews review
    where review.job_id = existing_job."Job_ID"
      and review.quote_id = requested_quote_id
      and review.proposed_version_id = quote_row."CusQuoteHeader_AcceptedVersionID"
      and review.status_code in ('pending', 'partially_applied')
    order by review.created_at desc
    limit 1
    for update;

    if found then
      if requested_response_id is not null then
        update booking_api.quote_sync_reviews
        set proposed_response_id = coalesce(proposed_response_id, requested_response_id)
        where review_id = active_review.review_id;

        update public."Job_Header"
        set "Job_PendingQuoteResponseID" = coalesce("Job_PendingQuoteResponseID", requested_response_id),
            "Job_UpdatedAt" = now()
        where "Job_ID" = existing_job."Job_ID";
      end if;

      return jsonb_build_object(
        'jobId', existing_job."Job_ID",
        'bookingReference', existing_job."Job_BookingReference",
        'status', existing_job."Job_Status",
        'requiresCustomerLink', existing_job."Job_Customer" is null,
        'reused', true,
        'outOfSync', true,
        'quoteSyncReviewId', active_review.review_id
      );
    end if;
  end if;

  return booking_api.convert_accepted_quote_before_idempotent_review_20260904(
    requested_quote_id,
    requested_actor_user_id,
    requested_response_id
  );
exception
  when no_data_found or too_many_rows then
    raise exception 'The accepted quote or booking workspace is incomplete.' using errcode = 'P0002';
end;
$$;


ALTER FUNCTION "booking_api"."convert_accepted_quote_before_container_allocation_20260904"("requested_quote_id" "uuid", "requested_actor_user_id" "uuid", "requested_response_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "booking_api"."convert_accepted_quote_before_container_allocation_20260904"("requested_quote_id" "uuid", "requested_actor_user_id" "uuid", "requested_response_id" "uuid") IS 'Creates or updates a booking from an accepted quote. Repeated conversion of the same accepted version reuses its active review, preserves the customer response link, and emits no duplicate review or notification.';



CREATE OR REPLACE FUNCTION "booking_api"."convert_accepted_quote_before_idempotent_review_20260904"("requested_quote_id" "uuid", "requested_actor_user_id" "uuid" DEFAULT NULL::"uuid", "requested_response_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  result jsonb;
  job_row record;
  quote_row record;
  snapshot jsonb;
  quote jsonb;
  facts jsonb;
  payer jsonb;
  actor_user_id uuid;
begin
  result := booking_api.convert_accepted_quote_before_payer_20260904(
    requested_quote_id,
    requested_actor_user_id,
    requested_response_id
  );

  select job.* into strict job_row
  from public."Job_Header" job
  where job."Job_ID" = (result->>'jobId')::uuid
    and not job."Job_IsDeleted";
  select quote_header.* into strict quote_row
  from public."CusQuote_Header" quote_header
  where quote_header."CusQuoteHeader_ID" = requested_quote_id
    and not quote_header."CusQuoteHeader_IsDeleted";

  if job_row."Job_SourceQuoteVersionID" = quote_row."CusQuoteHeader_AcceptedVersionID"
     and not exists (
       select 1 from public."Job_Parties" party
       where party."JobParty_JobID" = job_row."Job_ID"
         and party."JobParty_Role" = 'payer'
     ) then
    select version."CusQuoteVersion_SnapshotJSON" into strict snapshot
    from public."CusQuote_Versions" version
    where version."CusQuoteVersion_ID" = job_row."Job_SourceQuoteVersionID";
    quote := coalesce(snapshot->'quote', '{}'::jsonb);
    facts := coalesce(quote->'shipmentFacts', '{}'::jsonb);
    payer := case
      when jsonb_typeof(quote->'payer') = 'object' and quote->'payer' <> '{}'::jsonb
        then quote->'payer'
      else jsonb_strip_nulls(jsonb_build_object(
        'orgId', nullif(quote->>'customerId', ''),
        'name', nullif(btrim(quote->>'customerName'), ''),
        'address', nullif(btrim(facts->>'customerAddress'), ''),
        'contact', nullif(btrim(quote->>'contactName'), ''),
        'email', nullif(btrim(quote->>'contactEmail'), ''),
        'code', nullif(btrim(facts->>'clientCode'), '')
      ))
    end;
    actor_user_id := coalesce(requested_actor_user_id, job_row."Job_UpdatedBy", job_row."Job_CreatedBy");

    if quote_api.jsonb_has_content(payer) then
      insert into public."Job_Parties" (
        "JobParty_JobID", "JobParty_Role", "JobParty_OrgID", "JobParty_Sequence",
        "JobParty_NameSnapshot", "JobParty_AddressSnapshot", "JobParty_ContactNameSnapshot",
        "JobParty_EmailSnapshot", "JobParty_IdentifierType", "JobParty_IdentifierValueSnapshot",
        "JobParty_IsPrimary", "JobParty_RawSnapshot", "JobParty_CreatedBy"
      ) values (
        job_row."Job_ID", 'payer', nullif(payer->>'orgId', '')::uuid, 1,
        left(nullif(btrim(payer->>'name'), ''), 240), nullif(btrim(payer->>'address'), ''),
        left(nullif(btrim(payer->>'contact'), ''), 180), left(nullif(btrim(payer->>'email'), ''), 254),
        'account_code', left(nullif(btrim(payer->>'code'), ''), 120), true, payer, actor_user_id
      );
    end if;
  end if;

  return result;
exception when no_data_found or too_many_rows then
  raise exception 'The accepted quote or booking workspace is incomplete.' using errcode = 'P0002';
end;
$$;


ALTER FUNCTION "booking_api"."convert_accepted_quote_before_idempotent_review_20260904"("requested_quote_id" "uuid", "requested_actor_user_id" "uuid", "requested_response_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."convert_accepted_quote_before_payer_20260904"("requested_quote_id" "uuid", "requested_actor_user_id" "uuid" DEFAULT NULL::"uuid", "requested_response_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  result jsonb;
  accepted_version_id uuid;
  actor_user_id uuid;
begin
  result := booking_api.convert_accepted_quote_before_routing_plans_20260904(
    requested_quote_id,requested_actor_user_id,requested_response_id
  );
  if not coalesce((result->>'reused')::boolean,false) then
    select quote."CusQuoteHeader_AcceptedVersionID",
      coalesce(requested_actor_user_id,quote."CusQuoteHeader_SalesOwnerID",quote."CusQuoteHeader_LastEditedBy",quote."CusQuoteHeader_CreatedBy")
    into strict accepted_version_id,actor_user_id
    from public."CusQuote_Header" quote
    where quote."CusQuoteHeader_ID"=requested_quote_id;
    perform booking_api.apply_quote_routing_plan(
      (result->>'jobId')::uuid,accepted_version_id,actor_user_id
    );
  end if;
  return result;
exception when no_data_found or too_many_rows then
  raise exception 'The accepted quote routing plan is unavailable.' using errcode='P0002';
end;
$$;


ALTER FUNCTION "booking_api"."convert_accepted_quote_before_payer_20260904"("requested_quote_id" "uuid", "requested_actor_user_id" "uuid", "requested_response_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."convert_accepted_quote_before_routing_plans_20260904"("requested_quote_id" "uuid", "requested_actor_user_id" "uuid" DEFAULT NULL::"uuid", "requested_response_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  existing_job record;
  quote_row record;
  version_row record;
  company_id uuid;
  actor_user_id uuid;
  baseline jsonb;
  proposed jsonb;
  booking_snapshot jsonb;
  differences jsonb;
  review_id_value uuid;
  owner_user_id uuid;
begin
  select job.* into existing_job
  from public."Job_Header" job
  where job."Job_SourceQuoteID"=requested_quote_id and not job."Job_IsDeleted"
  order by job."Job_CreatedDate"
  limit 1
  for update;

  if not found then
    return booking_api.convert_accepted_quote_before_sync_review_20260904(
      requested_quote_id, requested_actor_user_id, requested_response_id
    );
  end if;

  select quote.* into strict quote_row
  from public."CusQuote_Header" quote
  where quote."CusQuoteHeader_ID"=requested_quote_id
    and quote."CusQuoteHeader_LifecycleCode"='accepted'
    and not quote."CusQuoteHeader_IsDeleted";

  select version.* into strict version_row
  from public."CusQuote_Versions" version
  where version."CusQuoteVersion_ID"=quote_row."CusQuoteHeader_AcceptedVersionID"
    and version."CusQuoteHeader_ID"=requested_quote_id;

  if existing_job."Job_SourceQuoteVersionID" = version_row."CusQuoteVersion_ID" then
    if requested_response_id is not null and existing_job."Job_SourceQuoteResponseID" is null then
      update public."Job_Header" set "Job_SourceQuoteResponseID"=requested_response_id, "Job_UpdatedAt"=now()
      where "Job_ID"=existing_job."Job_ID";
    end if;
    return jsonb_build_object(
      'jobId', existing_job."Job_ID", 'bookingReference', existing_job."Job_BookingReference",
      'status', existing_job."Job_Status", 'requiresCustomerLink', existing_job."Job_Customer" is null,
      'reused', true, 'outOfSync', false
    );
  end if;

  select office."Company_ID" into strict company_id
  from public."cmp_Offices" office
  where office."Office_ID"=coalesce(existing_job."Job_OrgOfficeID", existing_job."Job_OfficeID");
  actor_user_id := coalesce(requested_actor_user_id, quote_row."CusQuoteHeader_SalesOwnerID", quote_row."CusQuoteHeader_LastEditedBy", quote_row."CusQuoteHeader_CreatedBy");
  baseline := booking_api.quote_sync_projection(coalesce(existing_job."Job_SourceSnapshotJSON"->'acceptedSnapshot', '{}'::jsonb));
  proposed := booking_api.quote_sync_projection(version_row."CusQuoteVersion_SnapshotJSON");
  booking_snapshot := booking_api.current_quote_sync_projection(existing_job."Job_ID");
  differences := booking_api.quote_sync_differences(baseline, booking_snapshot, proposed);

  update booking_api.quote_sync_reviews
  set status_code='superseded', decided_at=now(), decided_by=actor_user_id
  where job_id=existing_job."Job_ID" and status_code in ('pending','partially_applied');

  if jsonb_array_length(differences)=0 then
    update public."Job_Header" set
      "Job_SourceQuoteVersionID"=version_row."CusQuoteVersion_ID",
      "Job_SourceQuoteResponseID"=requested_response_id,
      "Job_PendingQuoteVersionID"=null,
      "Job_PendingQuoteResponseID"=null,
      "Job_QuoteSyncStatus"='in_sync',
      "Job_QuoteSyncDetectedAt"=null,
      "Job_SourceSnapshotJSON"="Job_SourceSnapshotJSON" || jsonb_build_object('acceptedSnapshot', version_row."CusQuoteVersion_SnapshotJSON"),
      "Job_UpdatedAt"=now()
    where "Job_ID"=existing_job."Job_ID";
  else
    insert into booking_api.quote_sync_reviews (
      company_id, job_id, quote_id, applied_version_id, proposed_version_id,
      proposed_response_id, baseline_snapshot, proposed_snapshot, booking_snapshot,
      differences, created_by
    ) values (
      company_id, existing_job."Job_ID", requested_quote_id, existing_job."Job_SourceQuoteVersionID",
      version_row."CusQuoteVersion_ID", requested_response_id, baseline, proposed,
      booking_snapshot, differences, actor_user_id
    ) returning review_id into review_id_value;

    update public."Job_Header" set
      "Job_PendingQuoteVersionID"=version_row."CusQuoteVersion_ID",
      "Job_PendingQuoteResponseID"=requested_response_id,
      "Job_QuoteSyncStatus"='out_of_sync',
      "Job_QuoteSyncDetectedAt"=now(),
      "Job_UpdatedAt"=now()
    where "Job_ID"=existing_job."Job_ID";

    owner_user_id := coalesce(existing_job."Job_OperationsOwnerID", existing_job."Job_CreatedBy", actor_user_id);
    if owner_user_id is not null then
      insert into public."Comm_Notifications" (
        "CommNotif_UserID", "CommNotif_Title", "CommNotif_Body", "CommNotif_TargetTable",
        "CommNotif_TargetID", "CommNotif_LinkTypeCode", "CommNotif_MetadataJSON", "CommNotif_CreatedBy"
      ) values (
        owner_user_id,
        existing_job."Job_BookingReference" || ' has an accepted quote update',
        'Review the newer accepted quote before applying any changes to this booking.',
        'Job_Header', existing_job."Job_ID", 'booking_quote_sync',
        jsonb_build_object(
          'event_type','booking_quote_sync','action_url','/bookings/' || lower(existing_job."Job_BookingReference"),
          'action_label','Review booking','review_id',review_id_value,
          'quote_id',requested_quote_id,'quote_version_id',version_row."CusQuoteVersion_ID"
        ), actor_user_id
      );
    end if;
  end if;

  insert into booking_api.events (company_id, job_id, event_type, summary, metadata, actor_user_id)
  values (
    company_id, existing_job."Job_ID",
    case when jsonb_array_length(differences)=0 then 'quote_version_reconciled' else 'quote_update_available' end,
    case when jsonb_array_length(differences)=0
      then 'A newer accepted quote contained no booking changes and was recorded as the applied version.'
      else 'A newer accepted quote is ready for field-by-field review.' end,
    jsonb_build_object(
      'quoteId',requested_quote_id,'previousVersionId',existing_job."Job_SourceQuoteVersionID",
      'proposedVersionId',version_row."CusQuoteVersion_ID",'responseId',requested_response_id,
      'reviewId',review_id_value,'differences',differences
    ), actor_user_id
  );

  return jsonb_build_object(
    'jobId', existing_job."Job_ID", 'bookingReference', existing_job."Job_BookingReference",
    'status', existing_job."Job_Status", 'requiresCustomerLink', existing_job."Job_Customer" is null,
    'reused', true, 'outOfSync', jsonb_array_length(differences)>0,
    'quoteSyncReviewId', review_id_value
  );
exception
  when no_data_found or too_many_rows then
    raise exception 'The accepted quote or booking workspace is incomplete.' using errcode='P0002';
end;
$$;


ALTER FUNCTION "booking_api"."convert_accepted_quote_before_routing_plans_20260904"("requested_quote_id" "uuid", "requested_actor_user_id" "uuid", "requested_response_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."convert_accepted_quote_before_sync_review_20260904"("requested_quote_id" "uuid", "requested_actor_user_id" "uuid" DEFAULT NULL::"uuid", "requested_response_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  quote_row record;
  version_row record;
  actor_user_id uuid;
  company_id uuid;
  office_id uuid;
  customer_id uuid;
  job_status text;
  booking_reference text;
  job_id uuid;
  payload jsonb;
  facts jsonb;
  party jsonb;
  charge jsonb;
  charge_number integer := 0;
  mode_code text;
  direction_code text;
  existing_job record;
begin
  select job.* into existing_job
  from public."Job_Header" job
  where job."Job_SourceQuoteID" = requested_quote_id and not job."Job_IsDeleted"
  limit 1;
  if found then
    if requested_response_id is not null and existing_job."Job_SourceQuoteResponseID" is null then
      update public."Job_Header"
      set "Job_SourceQuoteResponseID" = requested_response_id, "Job_UpdatedAt" = now()
      where "Job_ID" = existing_job."Job_ID";
    end if;
    return jsonb_build_object(
      'jobId', existing_job."Job_ID", 'bookingReference', existing_job."Job_BookingReference",
      'status', existing_job."Job_Status", 'requiresCustomerLink', existing_job."Job_Customer" is null, 'reused', true
    );
  end if;

  select quote.* into quote_row
  from public."CusQuote_Header" quote
  where quote."CusQuoteHeader_ID" = requested_quote_id
    and quote."CusQuoteHeader_LifecycleCode" = 'accepted'
    and not quote."CusQuoteHeader_IsDeleted"
  for update;
  if not found then raise exception 'Only an accepted quote can create a booking.' using errcode = '22023'; end if;

  select version.* into version_row
  from public."CusQuote_Versions" version
  where version."CusQuoteVersion_ID" = coalesce(
    quote_row."CusQuoteHeader_AcceptedVersionID",
    (select current_version."CusQuoteVersion_ID" from public."CusQuote_Versions" current_version
     where current_version."CusQuoteHeader_ID" = requested_quote_id and current_version."CusQuoteVersion_IsCurrent" limit 1)
  );
  if not found then raise exception 'The accepted quote version is unavailable.' using errcode = 'P0002'; end if;

  payload := coalesce(version_row."CusQuoteVersion_SnapshotJSON"->'quote', '{}'::jsonb);
  facts := coalesce(payload->'shipmentFacts', '{}'::jsonb);
  office_id := coalesce(nullif(payload->>'officeId', '')::uuid, quote_row."CusQuoteHeader_OrgOfficeID", quote_row."OrgOffice_ID");
  select office."Company_ID" into company_id from public."cmp_Offices" office where office."Office_ID" = office_id;
  if company_id is null then raise exception 'The accepted quote office is unavailable.' using errcode = 'P0002'; end if;

  actor_user_id := coalesce(requested_actor_user_id, quote_row."CusQuoteHeader_SalesOwnerID", quote_row."CusQuoteHeader_LastEditedBy", quote_row."CusQuoteHeader_CreatedBy");
  if not exists (select 1 from public."cmp_Users" app_user where app_user."User_ID" = actor_user_id and app_user."Company_ID" = company_id) then
    select app_user."User_ID" into actor_user_id from public."cmp_Users" app_user
    where app_user."Company_ID" = company_id and app_user."User_AccessStatus" = 'active'
    order by app_user."User_ID" limit 1;
  end if;
  if actor_user_id is null then raise exception 'No active operator can own the accepted booking.' using errcode = 'P0002'; end if;

  direction_code := booking_api.normalise_direction(coalesce(
    nullif(payload->>'direction', ''), nullif(facts->>'direction', ''),
    quote_row."CusQuoteHeader_Direction", nullif(facts->>'quoteType', '')
  ));
  mode_code := booking_api.normalise_mode(coalesce(nullif(payload->>'mode', ''), quote_row."CusQuoteHeader_ModeCode"));
  customer_id := coalesce(nullif(payload->>'customerId', '')::uuid, quote_row."CusQuoteHeader_CustomerID");
  job_status := case when customer_id is null then 'draft' else 'open' end;
  booking_reference := booking_api.allocate_reference(company_id, 'default', direction_code);

  insert into public."Job_Header" (
    "Job_Period", "Job_CreatedBy", "Job_Customer", "Job_Carrier", "Job_Supplier",
    "Job_OfficeID", "Job_OrgOfficeID", "Job_Status", "Job_Direction", "Job_TransportModeSummary",
    "Job_OriginNameSnapshot", "Job_DestinationNameSnapshot", "Job_ReadyDate", "Job_RequiredDeliveryDate",
    "Job_TrackingStatus", "Job_CurrentLocationNameSnapshot", "Job_InternalNotes", "Job_UpdatedBy",
    "Job_BookingReference", "Job_BookingReferenceSequenceKey", "Job_SourceQuoteID", "Job_SourceQuoteVersionID", "Job_SourceQuoteResponseID",
    "Job_IncotermsCode", "Job_IncotermsLocation", "Job_CollectionAddress", "Job_DeliveryAddress",
    "Job_CustomerDeadline", "Job_SourceSnapshotJSON"
  ) values (
    to_char(current_date, 'YYYYMM'), actor_user_id, customer_id,
    coalesce(nullif(payload->>'carrierId', '')::uuid, quote_row."CusQuoteHeader_CarrierID"),
    coalesce(nullif(payload->>'supplierId', '')::uuid, quote_row."CusQuoteHeader_SupplierID"),
    office_id, office_id, job_status, direction_code, mode_code,
    coalesce(nullif(payload->>'loadingPoint', ''), quote_row."CusQuoteHeader_LoadingPoint"),
    coalesce(nullif(payload->>'dischargePoint', ''), quote_row."CusQuoteHeader_DischargePoint"),
    nullif(payload->>'validFrom', '')::date, nullif(payload->>'deadline', '')::date,
    'planning', 'Planning', nullif(payload->>'internalNotes', ''), actor_user_id,
    booking_reference, 'default', requested_quote_id, version_row."CusQuoteVersion_ID", requested_response_id,
    upper(nullif(payload->>'incoterm', '')), nullif(facts->>'namedPlace', ''),
    nullif(payload->>'collectionAddress', ''), nullif(payload->>'deliveryAddress', ''),
    nullif(payload->>'deadline', '')::date,
    jsonb_strip_nulls(jsonb_build_object(
      'source', 'accepted_quote', 'quoteId', requested_quote_id, 'quoteVersionId', version_row."CusQuoteVersion_ID",
      'quoteReference', coalesce(quote_row."CusQuoteHeader_CustomerReference", 'Q-' || quote_row."CusQuoteHeader_Number"),
      'customerName', coalesce(nullif(payload->>'customerName', ''), quote_row."CusQuoteHeader_CustomerNameSnapshot"),
      'contactName', coalesce(nullif(payload->>'contactName', ''), quote_row."CusQuoteHeader_ContactNameSnapshot"),
      'contactEmail', coalesce(nullif(payload->>'contactEmail', ''), quote_row."CusQuoteHeader_ContactEmailSnapshot"),
      'direction', direction_code, 'requiresCustomerLink', customer_id is null,
      'acceptedSnapshot', version_row."CusQuoteVersion_SnapshotJSON"
    ))
  ) returning "Job_ID" into job_id;
  update public."Job_Header" set
    "Job_GoodsValueAmount"=(booking_api.normalise_shipment_value(jsonb_build_object('amount',facts->'goodsValue','currency',coalesce(nullif(facts->>'goodsValueCurrency',''),payload->>'currency')))->>'amount')::numeric,
    "Job_GoodsValueCurrencyCode"=booking_api.normalise_shipment_value(jsonb_build_object('amount',facts->'goodsValue','currency',coalesce(nullif(facts->>'goodsValueCurrency',''),payload->>'currency')))->>'currency'
    where "Job_ID"=job_id;


  party := payload->'shipper';
  if quote_api.jsonb_has_content(party) then
    insert into public."Job_Parties" (
      "JobParty_JobID", "JobParty_Role", "JobParty_OrgID", "JobParty_Sequence", "JobParty_NameSnapshot",
      "JobParty_AddressSnapshot", "JobParty_ContactNameSnapshot", "JobParty_IsPrimary", "JobParty_RawSnapshot", "JobParty_CreatedBy"
    ) values (job_id, 'shipper', nullif(party->>'orgId', '')::uuid, 1, left(nullif(btrim(party->>'name'), ''), 240),
      nullif(btrim(party->>'address'), ''), left(nullif(btrim(party->>'contact'), ''), 180), true, party, actor_user_id);
  end if;
  party := payload->'consignee';
  if quote_api.jsonb_has_content(party) then
    insert into public."Job_Parties" (
      "JobParty_JobID", "JobParty_Role", "JobParty_OrgID", "JobParty_Sequence", "JobParty_NameSnapshot",
      "JobParty_AddressSnapshot", "JobParty_ContactNameSnapshot", "JobParty_IsPrimary", "JobParty_RawSnapshot", "JobParty_CreatedBy"
    ) values (job_id, 'consignee', nullif(party->>'orgId', '')::uuid, 1, left(nullif(btrim(party->>'name'), ''), 240),
      nullif(btrim(party->>'address'), ''), left(nullif(btrim(party->>'contact'), ''), 180), true, party, actor_user_id);
  end if;

  insert into public."Job_Routing" (
    "Job_ID", "JobRoute_OrderNo", "JobRoute_Status", "JobRoute_ModeCode", "JobRoute_OriginNameSnapshot",
    "JobRoute_OriginAddressSnapshot", "JobRoute_DestinationNameSnapshot", "JobRoute_DestinationAddressSnapshot",
    "JobRoute_Carrier", "JobRoute_ServiceLevel", "JobRoute_IsMainCarriage", "JobRoute_RouteJSON", "JobRoute_UpdatedBy"
  ) values (
    job_id, 1, 'planned', mode_code, coalesce(nullif(payload->>'loadingPoint', ''), quote_row."CusQuoteHeader_LoadingPoint"),
    nullif(payload->>'collectionAddress', ''), coalesce(nullif(payload->>'dischargePoint', ''), quote_row."CusQuoteHeader_DischargePoint"),
    nullif(payload->>'deliveryAddress', ''), coalesce(nullif(payload->>'carrierId', '')::uuid, quote_row."CusQuoteHeader_CarrierID"),
    nullif(payload->>'serviceLevel', ''), true, jsonb_build_object('source', 'accepted_quote', 'shipmentFacts', facts), actor_user_id
  );

  if facts ? 'cargoLines' then
    perform booking_api.insert_accepted_quote_cargo(job_id,version_row."CusQuoteVersion_ID",actor_user_id);
  elsif nullif(btrim(coalesce(facts->>'knownCargo', facts->>'commodity')), '') is not null then
    insert into public."Job_Cargo" (
      "JobCargo_JobID", "JobCargo_LineNo", "JobCargo_Description", "JobCargo_Qty", "JobCargo_PackageTypeCodeSnapshot",
      "JobCargo_PackageQty", "JobCargo_GrossKilos", "JobCargo_NettKilos", "JobCargo_HSCode", "JobCargo_VolumeCBM",
      "JobCargo_DeclaredValueAmount", "JobCargo_DeclaredValueCurrencyCodeSnapshot", "JobCargo_CargoJSON", "JobCargo_UpdatedBy"
    ) values (
      job_id, 1, coalesce(facts->>'knownCargo', facts->>'commodity'), nullif(coalesce(facts->>'pieces', facts->>'packageQuantity'), '')::numeric,
      left(nullif(facts->>'packageType', ''), 40), nullif(coalesce(facts->>'packageQuantity', facts->>'pieces'), '')::numeric,
      nullif(facts->>'grossWeightKg', '')::numeric, nullif(facts->>'netWeightKg', '')::numeric, left(nullif(facts->>'hsCode', ''), 30),
      nullif(facts->>'volumeCbm', '')::numeric, nullif(regexp_replace(coalesce(facts->>'goodsValue', ''), '[^0-9.-]', '', 'g'), '')::numeric,
      coalesce(nullif(upper(facts->>'goodsValueCurrency'), ''), nullif(upper(payload->>'currency'), '')), facts, actor_user_id
    );
  end if;

  if nullif(btrim(facts->>'container'), '') is not null then
    insert into public."Job_Containers" (
      "Job_ID", "JobContainer_TypeCodeSnapshot", "JobContainer_EquipmentKind", "JobContainer_Status", "JobContainer_JSON", "JobContainer_UpdatedBy"
    ) values (
      job_id, left(facts->>'container', 40), case when lower(coalesce(payload->>'mode', '')) in ('air','courier') then 'unit_load_device' else 'container' end,
      'planned', jsonb_build_object('description', facts->>'container', 'source', 'accepted_quote'), actor_user_id
    );
  end if;

  for charge in select value from jsonb_array_elements(case when job_status='draft' then '[]'::jsonb else coalesce(payload->'charges','[]'::jsonb) end) loop
    charge_number := charge_number + 1;
    insert into public."Job_Costing_Lines" (
      "Job_ID", "JobCostingLine_Number", "JobCostingLine_SupplierID", "JobCostingLine_Description", "JobCostingLine_InternalNotes",
      "JobCostingLine_CustomerNotes", "JobCostingLine_CostROE", "JobCostingLine_CostAmountCurrency", "JobCostingLine_CostAmountLocal",
      "JobCostingLine_RevenueROE", "JobCostingLine_RevenueAmountCurrency", "JobCostingLine_RevenueAmountLocal",
      "JobCostingLine_ShowToCustomer", "JobCostingLine_CreatedBy", "JobCostingLine_UpdatedBy", "JobCostingLine_DomainCode"
    ) values (
      job_id, charge_number, nullif(charge->>'supplierId', '')::uuid, left(coalesce(nullif(btrim(charge->>'description'), ''), 'Charge'), 240),
      nullif(charge->>'internalNotes', ''), nullif(charge->>'customerNotes', ''), greatest(coalesce(nullif(charge->>'costRoe', '')::numeric, 1), 0.00001),
      coalesce(nullif(charge->>'costAmount', '')::numeric, 0), coalesce(nullif(charge->>'costLocal', '')::numeric, 0),
      greatest(coalesce(nullif(charge->>'sellRoe', '')::numeric, 1), 0.00001), coalesce(nullif(charge->>'sellAmount', '')::numeric, 0),
      coalesce(nullif(charge->>'sellLocal', '')::numeric, 0), coalesce((charge->>'showToCustomer')::boolean, true), actor_user_id, actor_user_id, 'freight'
    );
  end loop;

  update public."CusQuote_Header" set "CusQuoteHeader_JobID" = job_id, "CusQuoteHeader_LastEditedDate" = now()
  where "CusQuoteHeader_ID" = requested_quote_id;
  insert into booking_api.events (company_id, job_id, event_type, summary, metadata, actor_user_id)
  values (company_id, job_id, 'created_from_quote', case when customer_id is null then 'Draft booking created from accepted one-off quote; link a customer before progressing.' else 'Booking created from accepted quote.' end,
    jsonb_build_object('quoteId', requested_quote_id, 'quoteVersionId', version_row."CusQuoteVersion_ID", 'status', job_status, 'direction', direction_code, 'requiresCustomerLink', customer_id is null), actor_user_id);

  return jsonb_build_object('jobId', job_id, 'bookingReference', booking_reference, 'status', job_status, 'requiresCustomerLink', customer_id is null, 'reused', false);
exception
  when unique_violation then
    select job.* into existing_job from public."Job_Header" job where job."Job_SourceQuoteID" = requested_quote_id and not job."Job_IsDeleted" limit 1;
    if found then
      return jsonb_build_object('jobId', existing_job."Job_ID", 'bookingReference', existing_job."Job_BookingReference", 'status', existing_job."Job_Status", 'requiresCustomerLink', existing_job."Job_Customer" is null, 'reused', true);
    end if;
    raise;
end;
$$;


ALTER FUNCTION "booking_api"."convert_accepted_quote_before_sync_review_20260904"("requested_quote_id" "uuid", "requested_actor_user_id" "uuid", "requested_response_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."correct_accepted_quote_booking"("requested_job_id" "uuid", "requested_actor_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  job_row record;
  payload jsonb;
  facts jsonb;
  goods_description text;
  legacy_description text;
  container_type text;
begin
  select job.* into job_row from public."Job_Header" job
  where job."Job_ID" = requested_job_id and job."Job_SourceQuoteID" is not null and not job."Job_IsDeleted"
  for update;
  if not found then return; end if;

  payload := coalesce(job_row."Job_SourceSnapshotJSON"#>'{acceptedSnapshot,quote}', '{}'::jsonb);
  facts := coalesce(payload->'shipmentFacts', '{}'::jsonb);
  goods_description := nullif(btrim(facts->>'goodsDescription'), '');
  legacy_description := nullif(btrim(coalesce(facts->>'knownCargo', facts->>'commodity')), '');
  container_type := nullif(btrim(facts->>'container'), '');
  if container_type ~* '^[0-9]+[[:space:]]+containers?$' then container_type := null; end if;

  if goods_description is not null then
    update public."Job_Cargo" cargo set
      "JobCargo_Description" = goods_description,
      "JobCargo_CargoJSON" = cargo."JobCargo_CargoJSON" || jsonb_strip_nulls(jsonb_build_object(
        'goodsDescription', goods_description,
        'handlingDescription', legacy_description,
        'source', 'accepted_quote'
      )),
      "JobCargo_UpdatedAt" = now(),
      "JobCargo_UpdatedBy" = coalesce(requested_actor_user_id, job_row."Job_UpdatedBy", job_row."Job_CreatedBy")
    where cargo."JobCargo_JobID" = requested_job_id and not cargo."JobCargo_IsDeleted"
      and (legacy_description is null or cargo."JobCargo_Description" = legacy_description);
  end if;

  update public."Job_Containers" container set
    "JobContainer_TypeCodeSnapshot" = container_type,
    "JobContainer_JSON" = (container."JobContainer_JSON" - 'description') || jsonb_strip_nulls(jsonb_build_object(
      'equipmentType', container_type,
      'source', 'accepted_quote'
    )),
    "JobContainer_UpdatedAt" = now(),
    "JobContainer_UpdatedBy" = coalesce(requested_actor_user_id, job_row."Job_UpdatedBy", job_row."Job_CreatedBy")
  where container."Job_ID" = requested_job_id and not container."JobContainer_IsDeleted"
    and coalesce(container."JobContainer_JSON"->>'source', '') = 'accepted_quote'
    and (
      container."JobContainer_TypeCodeSnapshot" is null
      or container."JobContainer_TypeCodeSnapshot" ~* '^[0-9]+[[:space:]]+containers?$'
    );
end;
$_$;


ALTER FUNCTION "booking_api"."correct_accepted_quote_booking"("requested_job_id" "uuid", "requested_actor_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."country_code_from_location"("value" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
  select case
    when regexp_replace(upper(coalesce(value, '')), '[^A-Z0-9]', '', 'g') ~ '^[A-Z]{2}[A-Z0-9]{3}$'
      then left(regexp_replace(upper(value), '[^A-Z0-9]', '', 'g'), 2)
    when upper(btrim(coalesce(value, ''))) ~ '^[A-Z]{2}$'
      then upper(btrim(value))
    else null
  end;
$_$;


ALTER FUNCTION "booking_api"."country_code_from_location"("value" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "booking_api"."country_code_from_location"("value" "text") IS 'Returns an ISO alpha-2 country code from a country code or UN/LOCODE, accepting mixed-case integration input.';



CREATE OR REPLACE FUNCTION "booking_api"."current_before_goods_value_20260905"("requested_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select booking_api.current_quote_sync_projection_before_cargo_lines_20260905(requested_job_id)
    ||jsonb_build_object('cargoLines',booking_api.current_source_cargo_lines(requested_job_id))
$$;


ALTER FUNCTION "booking_api"."current_before_goods_value_20260905"("requested_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."current_quote_sync_projection"("requested_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select booking_api.current_before_goods_value_20260905(requested_job_id)||jsonb_build_object('shipmentGoodsValue',
    jsonb_build_object('amount',job."Job_GoodsValueAmount",'currency',job."Job_GoodsValueCurrencyCode"))
  from public."Job_Header" job where job."Job_ID"=requested_job_id
$$;


ALTER FUNCTION "booking_api"."current_quote_sync_projection"("requested_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."current_quote_sync_projection_before_cargo_lines_20260905"("requested_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
  with container_groups as (
    select
      container."JobContainer_TypeCodeSnapshot" as type_code,
      count(*) as quantity,
      min(case
        when coalesce(container."JobContainer_JSON"#>>'{data,requestIndex}', '') ~ '^[0-9]+$'
          then (container."JobContainer_JSON"#>>'{data,requestIndex}')::integer
        else 2147483647
      end) as request_order,
      min(container."JobContainer_CreatedAt") as first_created
    from public."Job_Containers" container
    where container."Job_ID" = requested_job_id
      and not container."JobContainer_IsDeleted"
      and nullif(btrim(container."JobContainer_TypeCodeSnapshot"), '') is not null
    group by container."JobContainer_TypeCodeSnapshot"
  ), container_projection as (
    select
      string_agg(quantity::text || ' × ' || type_code, '; ' order by request_order, first_created, type_code) as equipment,
      coalesce(jsonb_agg(jsonb_build_object('quantity', quantity, 'type', type_code) order by request_order, first_created, type_code), '[]'::jsonb) as requests
    from container_groups
  )
  select booking_api.current_quote_sync_projection_before_container_allocation_20260904(requested_job_id)
    || jsonb_build_object('equipment', container_projection.equipment, 'containerRequests', container_projection.requests)
  from container_projection
$_$;


ALTER FUNCTION "booking_api"."current_quote_sync_projection_before_cargo_lines_20260905"("requested_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."current_quote_sync_projection_before_container_allocation_20260"("requested_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select booking_api.current_quote_sync_projection_before_payer_20260904(requested_job_id)
    || jsonb_build_object(
      'payer', coalesce(
        payer.party,
        booking_api.quote_sync_projection(
          coalesce(job."Job_SourceSnapshotJSON"->'acceptedSnapshot', '{}'::jsonb)
        )->'payer'
      )
    )
  from public."Job_Header" job
  left join lateral (
    select jsonb_strip_nulls(jsonb_build_object(
      'orgId', party."JobParty_OrgID",
      'name', party."JobParty_NameSnapshot",
      'address', party."JobParty_AddressSnapshot",
      'contact', party."JobParty_ContactNameSnapshot",
      'email', party."JobParty_EmailSnapshot",
      'code', party."JobParty_IdentifierValueSnapshot"
    )) as party
    from public."Job_Parties" party
    where party."JobParty_JobID" = job."Job_ID"
      and party."JobParty_Role" = 'payer'
    order by party."JobParty_IsPrimary" desc, party."JobParty_Sequence", party."JobParty_ID"
    limit 1
  ) payer on true
  where job."Job_ID" = requested_job_id
    and not job."Job_IsDeleted"
$$;


ALTER FUNCTION "booking_api"."current_quote_sync_projection_before_container_allocation_20260"("requested_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."current_quote_sync_projection_before_payer_20260904"("requested_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select booking_api.current_quote_sync_projection_before_routing_plans_20260904(requested_job_id)
    || jsonb_build_object(
      'routing', coalesce((
        select jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
          'order', route."JobRoute_OrderNo",
          'mode', booking_api.normalise_mode(route."JobRoute_ModeCode"),
          'origin', nullif(btrim(coalesce(route."JobRoute_OriginUNLocode", route."JobRoute_OriginNameSnapshot")), ''),
          'originUnlocode', nullif(upper(btrim(route."JobRoute_OriginUNLocode")), ''),
          'destination', nullif(btrim(coalesce(route."JobRoute_DestinationUNLocode", route."JobRoute_DestinationNameSnapshot")), ''),
          'destinationUnlocode', nullif(upper(btrim(route."JobRoute_DestinationUNLocode")), ''),
          'plannedDepartureAt', to_char(route."JobRoute_PlannedDepartureAt"::date, 'YYYY-MM-DD'),
          'plannedArrivalAt', to_char(route."JobRoute_PlannedArrivalAt"::date, 'YYYY-MM-DD'),
          'carrierId', route."JobRoute_Carrier",
          'carrierName', coalesce(carrier."Org_Name", nullif(btrim(route."JobRoute_RouteJSON"->>'carrierName'),'')),
          'serviceLevel', nullif(btrim(route."JobRoute_ServiceLevel"), '')
        )) order by route."JobRoute_OrderNo", route."JobRoute_ID")
        from public."Job_Routing" route
        left join public."Org_Master" carrier on carrier."Org_id"=route."JobRoute_Carrier"
        where route."Job_ID"=requested_job_id
          and coalesce(route."JobRoute_Status", 'planned')<>'superseded'
          and route."JobRoute_RouteJSON"->>'source' in ('accepted_quote','accepted_quote_update')
      ), '[]'::jsonb)
    )
$$;


ALTER FUNCTION "booking_api"."current_quote_sync_projection_before_payer_20260904"("requested_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."current_quote_sync_projection_before_routing_plans_20260904"("requested_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'direction', nullif(lower(btrim(job."Job_Direction")), ''),
    'mode', booking_api.normalise_mode(job."Job_TransportModeSummary"),
    'shipmentType', nullif(btrim(job."Job_EditableDetailsJSON"->>'shipmentType'), ''),
    'serviceLevel', nullif(btrim(route."JobRoute_ServiceLevel"), ''),
    'carrier', jsonb_build_object('id', job."Job_Carrier", 'name', carrier."Org_Name"),
    'supplier', jsonb_build_object('id', job."Job_Supplier", 'name', supplier."Org_Name"),
    'origin', nullif(btrim(coalesce(job."Job_OriginUNLocode", job."Job_OriginNameSnapshot")), ''),
    'destination', nullif(btrim(coalesce(job."Job_DestinationUNLocode", job."Job_DestinationNameSnapshot")), ''),
    'collectionAddress', nullif(btrim(job."Job_CollectionAddress"), ''),
    'deliveryAddress', nullif(btrim(job."Job_DeliveryAddress"), ''),
    'incoterm', nullif(upper(btrim(job."Job_IncotermsCode")), ''),
    'incotermLocation', nullif(btrim(job."Job_IncotermsLocation"), ''),
    'estimatedDeparture', to_char(coalesce(route."JobRoute_PlannedDepartureAt"::date, job."Job_ReadyDate"), 'YYYY-MM-DD'),
    'estimatedArrival', to_char(coalesce(route."JobRoute_PlannedArrivalAt"::date, job."Job_RequiredDeliveryDate"), 'YYYY-MM-DD'),
    'customerNotes', nullif(btrim(coalesce(job."Job_CustomerNotes", job."Job_EditableDetailsJSON"->>'customerNotes')), ''),
    'terms', nullif(btrim(coalesce(job."Job_TermsConditions", job."Job_EditableDetailsJSON"->>'termsAndConditions')), ''),
    'subjectToTerms', nullif(btrim(coalesce(job."Job_SubjectToTerms", job."Job_EditableDetailsJSON"->>'subjectToTerms')), ''),
    'shipper', shipper.party,
    'consignee', consignee.party,
    'cargo', cargo.cargo,
    'equipment', container.equipment,
    'charges', coalesce(charges.lines, '[]'::jsonb)
  )
  from public."Job_Header" job
  left join public."Org_Master" carrier on carrier."Org_id" = job."Job_Carrier"
  left join public."Org_Master" supplier on supplier."Org_id" = job."Job_Supplier"
  left join lateral (
    select route.* from public."Job_Routing" route
    where route."Job_ID" = job."Job_ID"
    order by route."JobRoute_IsMainCarriage" desc, route."JobRoute_OrderNo" nulls last
    limit 1
  ) route on true
  left join lateral (
    select jsonb_build_object(
      'orgId', party."JobParty_OrgID", 'name', party."JobParty_NameSnapshot",
      'address', party."JobParty_AddressSnapshot", 'contact', party."JobParty_ContactNameSnapshot"
    ) as party
    from public."Job_Parties" party
    where party."JobParty_JobID"=job."Job_ID" and party."JobParty_Role"='shipper'
    order by party."JobParty_IsPrimary" desc, party."JobParty_Sequence"
    limit 1
  ) shipper on true
  left join lateral (
    select jsonb_build_object(
      'orgId', party."JobParty_OrgID", 'name', party."JobParty_NameSnapshot",
      'address', party."JobParty_AddressSnapshot", 'contact', party."JobParty_ContactNameSnapshot"
    ) as party
    from public."Job_Parties" party
    where party."JobParty_JobID"=job."Job_ID" and party."JobParty_Role"='consignee'
    order by party."JobParty_IsPrimary" desc, party."JobParty_Sequence"
    limit 1
  ) consignee on true
  left join lateral (
    select jsonb_build_object(
      'description', item."JobCargo_Description",
      'packageQuantity', item."JobCargo_PackageQty",
      'packageType', item."JobCargo_PackageTypeCodeSnapshot",
      'grossWeightKg', item."JobCargo_GrossKilos",
      'netWeightKg', item."JobCargo_NettKilos",
      'volumeCbm', item."JobCargo_VolumeCBM",
      'goodsValue', item."JobCargo_DeclaredValueAmount",
      'goodsValueCurrency', item."JobCargo_DeclaredValueCurrencyCodeSnapshot"
    ) as cargo
    from public."Job_Cargo" item
    where item."JobCargo_JobID"=job."Job_ID" and not item."JobCargo_IsDeleted"
    order by item."JobCargo_LineNo" nulls last
    limit 1
  ) cargo on true
  left join lateral (
    select item."JobContainer_TypeCodeSnapshot" as equipment
    from public."Job_Containers" item
    where item."Job_ID"=job."Job_ID" and not item."JobContainer_IsDeleted"
    order by item."JobContainer_CreatedAt"
    limit 1
  ) container on true
  left join lateral (
    select jsonb_agg(jsonb_build_object(
      'supplierId', line."JobCostingLine_SupplierID",
      'description', line."JobCostingLine_Description",
      'internalNotes', line."JobCostingLine_InternalNotes",
      'customerNotes', line."JobCostingLine_CustomerNotes",
      'costRoe', line."JobCostingLine_CostROE",
      'costAmount', line."JobCostingLine_CostAmountCurrency",
      'costLocal', line."JobCostingLine_CostAmountLocal",
      'sellRoe', line."JobCostingLine_RevenueROE",
      'sellAmount', line."JobCostingLine_RevenueAmountCurrency",
      'sellLocal', line."JobCostingLine_RevenueAmountLocal",
      'showToCustomer', line."JobCostingLine_ShowToCustomer"
    ) order by line."JobCostingLine_Number") as lines
    from public."Job_Costing_Lines" line
    where line."Job_ID"=job."Job_ID"
  ) charges on true
  where job."Job_ID"=requested_job_id and not job."Job_IsDeleted"
$$;


ALTER FUNCTION "booking_api"."current_quote_sync_projection_before_routing_plans_20260904"("requested_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."current_source_cargo_lines"("requested_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'id',cargo."JobCargo_SourceQuoteLineID",'description',cargo."JobCargo_Description",'commodity',cargo."JobCargo_Commodity",
    'packageQuantity',cargo."JobCargo_PackageQty",'packageType',cargo."JobCargo_PackageTypeCodeSnapshot",
    'grossWeightKg',cargo."JobCargo_GrossKilos",'netWeightKg',cargo."JobCargo_NettKilos",'volumeCbm',cargo."JobCargo_VolumeCBM",
    'chargeableWeightKg',to_jsonb(cargo."JobCargo_ChargeableWeightKg"),
    'length',cargo."JobCargo_Length",'width',cargo."JobCargo_Width",'height',cargo."JobCargo_Height",'lengthUnit',cargo."JobCargo_LengthUnit",
    'hsCode',cargo."JobCargo_HSCode",'countryOfOrigin',cargo."JobCargo_CountryOfOriginCodeSnapshot",
    'isHazardous',cargo."JobCargo_IsHazardous",'isTemperatureControlled',cargo."JobCargo_IsTemperatureControlled")
    order by cargo."JobCargo_LineNo",cargo."JobCargo_ID"),'[]'::jsonb)
  from public."Job_Cargo" cargo
  where cargo."JobCargo_JobID"=requested_job_id and not cargo."JobCargo_IsDeleted"
    and cargo."JobCargo_SourceQuoteLineID" is not null
$$;


ALTER FUNCTION "booking_api"."current_source_cargo_lines"("requested_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."customs_access"("caller_auth_user_id" "uuid", "requested_declaration_id" "uuid", "require_write" boolean DEFAULT false) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (
    select 1
    from public."Customs_Declarations" declaration
    join public."cmp_Users" declaration_creator
      on declaration_creator."Auth_User_ID" = declaration."CUST_CreatedBy"
    join public."cmp_Users" caller
      on caller."Auth_User_ID" = caller_auth_user_id
    where declaration."CUST_id" = requested_declaration_id
      and not declaration."CUST_IsDeleted"
      and caller."Company_ID" is not null
      and caller."Company_ID" = declaration_creator."Company_ID"
      and coalesce(caller."User_AccessStatus", 'active') = 'active'
      and coalesce(declaration_creator."User_AccessStatus", 'active') <> 'deleted'
      and (
        (not require_write and booking_api.has_permission(caller_auth_user_id, 'Customs.Read'))
        or declaration."CUST_CreatedBy" = caller_auth_user_id
        or declaration."CUST_AssignedUserID" = caller."User_ID"
        or exists (
          select 1
          from booking_api.customs_declaration_grants scoped_grant
          where scoped_grant.declaration_id = declaration."CUST_id"
            and scoped_grant.user_id = caller."User_ID"
            and (not require_write or scoped_grant.can_write)
        )
        or (
          declaration."CUST_OwnerDepartmentID" is not null
          and exists (
            select 1
            from public."cmp_Users_Departments" membership
            join public."cmp_Departments" department
              on department."Department_ID" = membership."Department_ID"
            where membership."User_ID" = caller."User_ID"
              and membership."Department_ID" = declaration."CUST_OwnerDepartmentID"
              and department."Company_ID" = caller."Company_ID"
              and department."Department_IsActive"
          )
        )
        or (
          booking_api.has_permission(
            caller_auth_user_id,
            case when require_write then 'Customs.Write' else 'Customs.Read' end
          )
          and exists (
            select 1
            from public."cmp_Users_Roles" user_role
            join public."sys_UserRoles" role
              on role."sys_UserRole_ID" = user_role."sys_UserRole_ID"
            where user_role."User_ID" = caller."User_ID"
              and lower(role."sys_UserRole_Name") in ('administrator', 'company manager', 'operations manager')
          )
        )
      )
  )
$$;


ALTER FUNCTION "booking_api"."customs_access"("caller_auth_user_id" "uuid", "requested_declaration_id" "uuid", "require_write" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "booking_api"."customs_access"("caller_auth_user_id" "uuid", "requested_declaration_id" "uuid", "require_write" boolean) IS 'Checks tenant-safe declaration-scoped or authorised departmental Customs access.';



CREATE OR REPLACE FUNCTION "booking_api"."customs_readiness"("caller_auth_user_id" "uuid", "requested_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  result_value jsonb;
  actor_user_id uuid;
  filtered_missing jsonb;
begin
  result_value := booking_api.customs_readiness_before_handoff_initiator_access_20260821(
    caller_auth_user_id,
    requested_job_id
  );

  select app_user."User_ID" into strict actor_user_id
  from public."cmp_Users" app_user
  where app_user."Auth_User_ID" = caller_auth_user_id
    and coalesce(app_user."User_AccessStatus", 'active') = 'active';

  select coalesce(jsonb_agg(issue.value order by issue.ordinality), '[]'::jsonb)
  into filtered_missing
  from jsonb_array_elements(coalesce(result_value -> 'missing', '[]'::jsonb))
    with ordinality as issue(value, ordinality)
  where issue.value ->> 'key' <> 'customs_operator';

  result_value := jsonb_set(result_value, '{missing}', filtered_missing, true);
  result_value := jsonb_set(result_value, '{evidence,assignedUserId}', to_jsonb(actor_user_id), true);
  result_value := jsonb_set(
    result_value,
    '{ready}',
    to_jsonb(jsonb_array_length(filtered_missing) = 0),
    true
  );
  return result_value;
exception
  when no_data_found or too_many_rows then
    raise exception 'Your workspace identity is incomplete.' using errcode = '42501';
end;
$$;


ALTER FUNCTION "booking_api"."customs_readiness"("caller_auth_user_id" "uuid", "requested_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."customs_readiness_before_handoff_initiator_access_20260821"("caller_auth_user_id" "uuid", "requested_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  app_user record;
  job_row record;
  exporter_row record;
  importer_row record;
  route_row record;
  container_row record;
  missing jsonb := '[]'::jsonb;
  warnings jsonb := '[]'::jsonb;
  eligible boolean;
  direction_value text;
  mode_value text;
  incoterm_value text;
  total_packages numeric;
  total_gross numeric;
  cargo_count integer;
  commercial_invoice_id uuid;
  packing_list_id uuid;
  exporter_identifier text;
  importer_identifier text;
  transport_reference text;
  department_id_value uuid;
  assigned_user_id uuid;
begin
  if caller_auth_user_id is null
     or not booking_api.has_permission(caller_auth_user_id, 'Bookings.Read') then
    raise exception 'Booking access is not authorised.' using errcode = '42501';
  end if;
  select "User_ID", "Company_ID" into strict app_user
  from public."cmp_Users"
  where "Auth_User_ID" = caller_auth_user_id and "User_AccessStatus" = 'active';
  select job.* into job_row
  from public."Job_Header" job
  join public."cmp_Offices" office on office."Office_ID" = coalesce(job."Job_OrgOfficeID", job."Job_OfficeID")
  where job."Job_ID" = requested_job_id and office."Company_ID" = app_user."Company_ID" and not job."Job_IsDeleted";
  if not found then raise exception 'That booking is outside this workspace.' using errcode = '42501'; end if;

  direction_value := booking_api.normalise_direction(job_row."Job_Direction");
  mode_value := lower(coalesce(job_row."Job_TransportModeSummary", ''));
  incoterm_value := upper(coalesce(job_row."Job_IncotermsCode", ''));
  eligible := direction_value in ('import','export');
  if not eligible then
    missing := missing || jsonb_build_array(jsonb_build_object(
      'key', 'direction', 'label', case direction_value when 'domestic' then 'Domestic bookings do not need a Customs declaration' when 'cross_trade' then 'Cross-trade Customs handoff is not available yet' else 'Choose Import or Export' end,
      'section', 'Booking'
    ));
  end if;

  department_id_value := booking_api.find_customs_department(
    app_user."Company_ID", coalesce(job_row."Job_OrgOfficeID", job_row."Job_OfficeID")
  );
  if department_id_value is null then
    missing := missing || jsonb_build_array(jsonb_build_object(
      'key','customs_department','label','Configured Customs department for this booking office','section','Team'
    ));
  else
    select customs_user."User_ID" into assigned_user_id
    from public."cmp_Users_Departments" membership
    join public."cmp_Users" customs_user on customs_user."User_ID" = membership."User_ID"
    where membership."Department_ID" = department_id_value
      and customs_user."Company_ID" = app_user."Company_ID"
      and customs_user."User_AccessStatus" = 'active'
      and customs_user."Auth_User_ID" is not null
      and booking_api.has_permission(customs_user."Auth_User_ID", 'Customs.Read')
      and booking_api.has_permission(customs_user."Auth_User_ID", 'Customs.Write')
    order by customs_user."User_ID"
    limit 1;
    if assigned_user_id is null then
      missing := missing || jsonb_build_array(jsonb_build_object(
        'key','customs_operator','label','Active Customs operator with read and write access','section','Team'
      ));
    end if;
  end if;

  select party.* into exporter_row
  from public."Job_Parties" party
  where party."JobParty_JobID" = requested_job_id
    and lower(party."JobParty_Role") in ('exporter','shipper','consignor')
  order by party."JobParty_IsPrimary" desc, party."JobParty_Sequence" limit 1;
  select party.* into importer_row
  from public."Job_Parties" party
  where party."JobParty_JobID" = requested_job_id
    and lower(party."JobParty_Role") in ('importer','consignee')
  order by party."JobParty_IsPrimary" desc, party."JobParty_Sequence" limit 1;

  exporter_identifier := coalesce(
    case when lower(coalesce(exporter_row."JobParty_IdentifierType", '')) = 'eori' then nullif(btrim(exporter_row."JobParty_IdentifierValueSnapshot"), '') end,
    (select identifier."OrgIdentifier_Value" from public."Org_Identifiers" identifier
     where identifier."OrgIdentifier_OrgID" = exporter_row."JobParty_OrgID"
       and lower(identifier."OrgIdentifier_TypeCode") = 'eori' and identifier."OrgIdentifier_IsActive"
       and (identifier."OrgIdentifier_ValidFrom" is null or identifier."OrgIdentifier_ValidFrom" <= current_date)
       and (identifier."OrgIdentifier_ValidTo" is null or identifier."OrgIdentifier_ValidTo" >= current_date)
     order by identifier."OrgIdentifier_IsPrimary" desc, identifier."OrgIdentifier_UpdatedAt" desc limit 1)
  );
  importer_identifier := coalesce(
    case when lower(coalesce(importer_row."JobParty_IdentifierType", '')) in ('eori','vat') then nullif(btrim(importer_row."JobParty_IdentifierValueSnapshot"), '') end,
    (select identifier."OrgIdentifier_Value" from public."Org_Identifiers" identifier
     where identifier."OrgIdentifier_OrgID" = importer_row."JobParty_OrgID"
       and lower(identifier."OrgIdentifier_TypeCode") in ('eori','vat') and identifier."OrgIdentifier_IsActive"
       and (identifier."OrgIdentifier_ValidFrom" is null or identifier."OrgIdentifier_ValidFrom" <= current_date)
       and (identifier."OrgIdentifier_ValidTo" is null or identifier."OrgIdentifier_ValidTo" >= current_date)
     order by (lower(identifier."OrgIdentifier_TypeCode") = 'eori') desc, identifier."OrgIdentifier_IsPrimary" desc, identifier."OrgIdentifier_UpdatedAt" desc limit 1)
  );

  if nullif(btrim(exporter_row."JobParty_NameSnapshot"), '') is null then
    missing := missing || jsonb_build_array(jsonb_build_object('key','exporter_name','label','Consignor / shipper name','section','Parties'));
  end if;
  if nullif(btrim(exporter_row."JobParty_AddressSnapshot"), '') is null then
    missing := missing || jsonb_build_array(jsonb_build_object('key','exporter_address','label','Consignor / shipper full address','section','Parties'));
  end if;
  if direction_value = 'export' and nullif(btrim(exporter_identifier), '') is null then
    missing := missing || jsonb_build_array(jsonb_build_object('key','exporter_eori','label','Exporter EORI','section','Parties'));
  end if;
  if nullif(btrim(importer_row."JobParty_NameSnapshot"), '') is null then
    missing := missing || jsonb_build_array(jsonb_build_object('key','importer_name','label','Importer name','section','Parties'));
  end if;
  if nullif(btrim(importer_row."JobParty_AddressSnapshot"), '') is null then
    missing := missing || jsonb_build_array(jsonb_build_object('key','importer_address','label','Importer full address','section','Parties'));
  end if;
  if direction_value = 'import' and nullif(btrim(importer_identifier), '') is null then
    missing := missing || jsonb_build_array(jsonb_build_object('key','importer_identifier','label','Importer EORI or VAT number','section','Parties'));
  end if;

  select coalesce(sum(coalesce(cargo."JobCargo_PackageQty", cargo."JobCargo_Qty")), 0),
         coalesce(sum(cargo."JobCargo_GrossKilos"), 0), count(*)::integer
  into total_packages, total_gross, cargo_count
  from public."Job_Cargo" cargo
  where cargo."JobCargo_JobID" = requested_job_id and not cargo."JobCargo_IsDeleted";
  if cargo_count = 0 or not exists (
    select 1 from public."Job_Cargo" cargo where cargo."JobCargo_JobID" = requested_job_id
      and not cargo."JobCargo_IsDeleted" and nullif(btrim(cargo."JobCargo_Description"), '') is not null
  ) then missing := missing || jsonb_build_array(jsonb_build_object('key','goods_description','label','Goods description','section','Cargo')); end if;
  if total_packages <= 0 then missing := missing || jsonb_build_array(jsonb_build_object('key','packages','label','Pieces / packages','section','Cargo')); end if;
  if total_gross <= 0 then missing := missing || jsonb_build_array(jsonb_build_object('key','gross_weight','label','Gross weight','section','Cargo')); end if;

  if incoterm_value = '' then missing := missing || jsonb_build_array(jsonb_build_object('key','incoterm','label','Incoterms','section','Commercial')); end if;
  if incoterm_value in ('FOB','FCA','EXW') and (job_row."Job_FreightChargeAmount" is null or job_row."Job_FreightChargeAmount" <= 0) then
    missing := missing || jsonb_build_array(jsonb_build_object('key','freight_amount','label','Freight amount','section','Commercial'));
  end if;
  if incoterm_value in ('FOB','FCA','EXW') and nullif(btrim(job_row."Job_FreightChargeCurrencyCode"), '') is null then
    missing := missing || jsonb_build_array(jsonb_build_object('key','freight_currency','label','Freight currency','section','Commercial'));
  end if;

  select route.* into route_row from public."Job_Routing" route
  where route."Job_ID" = requested_job_id order by route."JobRoute_IsMainCarriage" desc, route."JobRoute_OrderNo" nulls last limit 1;
  select container.* into container_row from public."Job_Containers" container
  where container."Job_ID" = requested_job_id and not container."JobContainer_IsDeleted"
  order by container."JobContainer_CreatedAt" limit 1;
  if nullif(btrim(coalesce(route_row."JobRoute_OriginNameSnapshot", job_row."Job_OriginNameSnapshot", route_row."JobRoute_OriginUNLocode", job_row."Job_OriginUNLocode")), '') is null then
    missing := missing || jsonb_build_array(jsonb_build_object('key','origin','label','Origin loading point / port','section','Route'));
  end if;
  if nullif(btrim(coalesce(route_row."JobRoute_DestinationNameSnapshot", job_row."Job_DestinationNameSnapshot", route_row."JobRoute_DestinationUNLocode", job_row."Job_DestinationUNLocode")), '') is null then
    missing := missing || jsonb_build_array(jsonb_build_object('key','destination','label','Destination port / delivery point','section','Route'));
  end if;
  transport_reference := case
    when mode_value = 'air' then coalesce(nullif(btrim(route_row."JobRoute_FlightNumber"), ''), nullif(btrim(route_row."JobRoute_MasterTransportReference"), ''))
    when mode_value = 'sea' then coalesce(nullif(btrim(route_row."JobRoute_VoyageNumber"), ''), nullif(btrim(route_row."JobRoute_MasterTransportReference"), ''), nullif(btrim(route_row."JobRoute_TransportMeansName"), ''), nullif(btrim(container_row."JobContainer_Number"), ''))
    when mode_value = 'road' then coalesce(nullif(btrim(route_row."JobRoute_TrailerNumber"), ''), nullif(btrim(route_row."JobRoute_VehicleRegistration"), ''), nullif(btrim(route_row."JobRoute_MasterTransportReference"), ''))
    when mode_value = 'rail' then coalesce(nullif(btrim(route_row."JobRoute_RailService"), ''), nullif(btrim(route_row."JobRoute_MasterTransportReference"), ''), nullif(btrim(route_row."JobRoute_TrailerNumber"), ''))
    else coalesce(nullif(btrim(route_row."JobRoute_MasterTransportReference"), ''), nullif(btrim(route_row."JobRoute_TransportMeansName"), ''))
  end;
  if mode_value = '' then
    missing := missing || jsonb_build_array(jsonb_build_object('key','mode','label','Transport mode','section','Route'));
  elsif transport_reference is null then
    missing := missing || jsonb_build_array(jsonb_build_object(
      'key','transport_reference',
      'label',case mode_value when 'air' then 'Flight number' when 'sea' then 'Vessel, voyage or container number' when 'road' then 'Trailer or vehicle number' when 'rail' then 'Rail service or trailer number' else 'Transport reference' end,
      'section','Route'
    ));
  end if;

  select document."JobDoc_ID" into commercial_invoice_id
  from public."Job_Documents" document
  where document."JobDoc_JobID" = requested_job_id and not document."JobDoc_IsDeleted" and document."JobDoc_IsCurrentVersion"
    and (lower(coalesce(document."JobDoc_DocTypeCodeSnapshot", '')) in ('commercial_invoice','commercial-invoice','invoice') or lower(document."JobDoc_Title") like '%commercial invoice%')
    and (document."JobDoc_StoredObjectID" is not null or nullif(document."JobDoc_FilePath", '') is not null or nullif(document."JobDoc_FileURL", '') is not null)
  order by document."JobDoc_IsPrimary" desc, document."JobDoc_CreatedAt" desc limit 1;
  if commercial_invoice_id is null then
    missing := missing || jsonb_build_array(jsonb_build_object('key','commercial_invoice','label','Attached commercial invoice','section','Documents'));
  end if;
  select document."JobDoc_ID" into packing_list_id
  from public."Job_Documents" document
  where document."JobDoc_JobID" = requested_job_id and not document."JobDoc_IsDeleted" and document."JobDoc_IsCurrentVersion"
    and (lower(coalesce(document."JobDoc_DocTypeCodeSnapshot", '')) in ('packing_list','packing-list') or lower(document."JobDoc_Title") like '%packing list%')
  order by document."JobDoc_IsPrimary" desc, document."JobDoc_CreatedAt" desc limit 1;
  if packing_list_id is null then warnings := warnings || jsonb_build_array(jsonb_build_object('key','packing_list','label','Packing list not attached (optional)','section','Documents')); end if;

  return jsonb_build_object(
    'eligible', eligible,
    'ready', eligible and jsonb_array_length(missing) = 0,
    'direction', direction_value,
    'missing', missing,
    'warnings', warnings,
    'evidence', jsonb_strip_nulls(jsonb_build_object(
      'exporterIdentifier', exporter_identifier, 'importerIdentifier', importer_identifier,
      'totalPackages', total_packages, 'totalGrossWeightKg', total_gross,
      'transportReference', transport_reference, 'commercialInvoiceDocumentId', commercial_invoice_id,
      'packingListDocumentId', packing_list_id, 'ownerDepartmentId', department_id_value,
      'assignedUserId', assigned_user_id
    ))
  );
exception
  when no_data_found or too_many_rows then raise exception 'Your workspace identity is incomplete.' using errcode = '42501';
end;
$$;


ALTER FUNCTION "booking_api"."customs_readiness_before_handoff_initiator_access_20260821"("caller_auth_user_id" "uuid", "requested_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."dexter_route_mode_review"("company_id" "uuid", "user_id" "uuid", "arguments" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid;job public."Job_Header";leg public."Job_Routing";to_mode text;from_mode text;references_before jsonb;
  changes jsonb;field record;review jsonb;
begin
  select "Auth_User_ID" into actor from public."cmp_Users" where "User_ID"=user_id and "Company_ID"=company_id and "User_AccessStatus"='active';
  if actor is null or not booking_api.has_permission(actor,'Bookings.Read') or not booking_api.has_permission(actor,'Bookings.Write') then
    raise exception 'You do not have permission to change routing mode.' using errcode='42501';end if;
  if jsonb_typeof(arguments) is distinct from 'object'
    or not (arguments ?& array['target_id','route_id','expected_updated_at','expected_route_updated_at','mode','reason'])
    or exists(select 1 from jsonb_object_keys(arguments) key where key not in ('target_id','route_id','expected_updated_at','expected_route_updated_at','mode','reason','mode_review','_document_evidence'))
    or (arguments ? '_document_evidence' and jsonb_typeof(arguments->'_document_evidence') is distinct from 'object')
    or nullif(btrim(arguments->>'reason'),'') is null then raise exception 'Provide an exact routing mode proposal and reason.' using errcode='22023';end if;
  select j.* into job from public."Job_Header" j join public."cmp_Offices" office on office."Office_ID"=coalesce(j."Job_OrgOfficeID",j."Job_OfficeID")
    where j."Job_ID"=nullif(arguments->>'target_id','')::uuid and office."Company_ID"=company_id and not j."Job_IsDeleted";
  if not found then raise exception 'That booking is outside this workspace.' using errcode='42501';end if;
  select * into leg from public."Job_Routing" where "JobRoute_ID"=nullif(arguments->>'route_id','')::uuid and "Job_ID"=job."Job_ID";
  if not found then raise exception 'Choose an exact routing leg from this booking.' using errcode='42501';end if;
  if nullif(arguments->>'expected_updated_at','') is null or job."Job_UpdatedAt" is distinct from (arguments->>'expected_updated_at')::timestamptz
    or nullif(arguments->>'expected_route_updated_at','') is null or leg."JobRoute_UpdatedAt" is distinct from (arguments->>'expected_route_updated_at')::timestamptz then
    raise exception 'The booking or routing leg changed. Read it again and request fresh approval.' using errcode='40001';end if;
  to_mode:=booking_api.normalise_mode(arguments->>'mode');from_mode:=booking_api.normalise_mode(leg."JobRoute_ModeCode");
  if to_mode is null then raise exception 'Choose an active mode from the workspace lookup.' using errcode='22023';end if;
  if to_mode is not distinct from from_mode then raise exception 'This leg already uses that mode.' using errcode='22023';end if;
  references_before:=jsonb_build_object('masterTransportReference',nullif(btrim(leg."JobRoute_MasterTransportReference"),''),
    'houseTransportReference',nullif(btrim(leg."JobRoute_HouseTransportReference"),''),
    'carrierBookingReference',nullif(btrim(leg."JobRoute_CarrierBookingReference"),''),
    'transportMeansName',nullif(btrim(leg."JobRoute_TransportMeansName"),''));
  review:=jsonb_build_object('fromMode',from_mode,'toMode',to_mode,'beforeReferences',references_before,'beforeCutoffs',booking_api.route_cutoff_values(leg));
  changes:=jsonb_build_array(jsonb_build_object('field','Routing leg mode','before',from_mode,'after',to_mode,'value',to_mode,'beforeKnown',true,'kind','changed'));
  for field in select * from (values('masterTransportReference','Master transport reference'),('houseTransportReference','House transport reference'),
    ('carrierBookingReference','Carrier booking reference'),('transportMeansName','Transport service')) fields(key,label) loop
    changes:=changes||jsonb_build_array(jsonb_build_object('field',field.label,'before',references_before->field.key,'after',null,'value',null,'beforeKnown',true,'kind','removed'));
  end loop;
  for field in select * from (values('cargoCutoffAt','Cargo cut-off'),('documentationCutoffAt','Documentation cut-off'),('vgmCutoffAt','VGM cut-off')) fields(key,label) loop
    if booking_api.route_cutoff_values(leg)->>field.key is not null then
      changes:=changes||jsonb_build_array(jsonb_build_object('field',field.label,'before',booking_api.route_cutoff_values(leg)->field.key,'after',null,'value',null,'beforeKnown',true,'kind','removed'));
    end if;
  end loop;
  -- Optional upload provenance is retained for audit only. It cannot supply
  -- target identities, current values, the mode review or approval authority.
  return jsonb_build_object('arguments',(arguments-'mode_review')||jsonb_build_object('mode',to_mode,'mode_review',review),
    'title',format('Change %s · Leg %s mode',job."Job_BookingReference",leg."JobRoute_OrderNo"),
    'description','Warning: changing this leg mode clears its shared transport references and carrier cut-offs. Previous cut-offs remain in audit history. Previous references and mode-specific transport evidence remain in audit/history. Other legs, the overall Booking mode, cargo, equipment, documents and the accepted Quote stay unchanged. Carrier and planned dates stay as they are: review their suitability for the new mode before approving.',
    'changes',changes);
end $$;


ALTER FUNCTION "booking_api"."dexter_route_mode_review"("company_id" "uuid", "user_id" "uuid", "arguments" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."differences_before_goods_value_20260905"("baseline" "jsonb", "booking" "jsonb", "proposed" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare result jsonb; cargo_differences jsonb; old_value jsonb; new_value jsonb;
begin
  if not (baseline ? 'cargoLines' or proposed ? 'cargoLines') then
    return booking_api.quote_sync_differences_before_cargo_lines_20260905(baseline,booking,proposed); end if;
  result:=booking_api.quote_sync_differences_before_cargo_lines_20260905(baseline-'cargo',booking-'cargo',proposed-'cargo');
  cargo_differences:=booking_api.cargo_revision_differences(coalesce(baseline->'cargoLines','[]'),coalesce(booking->'cargoLines','[]'),coalesce(proposed->'cargoLines','[]'));
  if not (baseline ? 'cargoLines' and proposed ? 'cargoLines') then
    select coalesce(jsonb_agg(value||jsonb_build_object('blockedReason','Legacy cargo must be mapped to individual Quote lines before this change can be applied.',
      'requiresConfirmation',true,'recommendation','review')),'[]'::jsonb) into cargo_differences from jsonb_array_elements(cargo_differences);
  end if;
  old_value:=jsonb_build_object('goodsValue',baseline#>'{cargo,goodsValue}','currency',baseline#>'{cargo,goodsValueCurrency}');
  new_value:=jsonb_build_object('goodsValue',proposed#>'{cargo,goodsValue}','currency',proposed#>'{cargo,goodsValueCurrency}');
  if old_value is distinct from new_value then
    -- Never route aggregate shipment value through the legacy one-cargo-row
    -- replacement. Surface the still-unconnected allocation boundary honestly.
    result:=result||jsonb_build_array(jsonb_build_object('key','cargo','label','Shipment goods value','section','Goods',
      'previousQuoteValue',old_value,'newQuoteValue',new_value,'bookingValue',booking->'cargo',
      'requiresConfirmation',true,'recommendation','review','blockedReason','Shipment goods value and cargo allocations need a separate review before applying this change.'));
  end if;
  return result||cargo_differences;
end;
$$;


ALTER FUNCTION "booking_api"."differences_before_goods_value_20260905"("baseline" "jsonb", "booking" "jsonb", "proposed" "jsonb") OWNER TO "postgres";


