    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object('number',item."JobContainer_Number",'type',item."JobContainer_TypeCodeSnapshot",
    'equipmentKind',item."JobContainer_EquipmentKind",'status',item."JobContainer_Status",'archived',item."JobContainer_IsDeleted");
$$;


ALTER FUNCTION "booking_api"."equipment_identity_values"("item" "public"."Job_Containers") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."equipment_kind_for_save"("item" "jsonb", "requested_job_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare kind text; existing_kind text; existing_vgm numeric; existing_method text; field_name text;
begin
  foreach field_name in array array['number','type'] loop
    if item ? field_name and (jsonb_typeof(item->field_name) not in ('string','null')
      or length(btrim(item->>field_name))>case when field_name='number' then 50 else 40 end) then
      raise exception 'Equipment % must be text of at most % characters.',field_name,case when field_name='number' then 50 else 40 end using errcode='22023'; end if;
  end loop;
  if nullif(item->>'id','') is not null then
    select "JobContainer_EquipmentKind","JobContainer_VGMKilos","JobContainer_VGMMethod"
      into existing_kind,existing_vgm,existing_method from public."Job_Containers"
      where "JobContainers_ID"=(item->>'id')::uuid and "Job_ID"=requested_job_id and not "JobContainer_IsDeleted";
  end if;
  if item ? 'equipmentKind' and jsonb_typeof(item->'equipmentKind') is distinct from 'string' then
    raise exception 'Choose an equipment kind; it cannot be cleared.' using errcode='22023'; end if;
  kind:=case when item ? 'equipmentKind' then btrim(item->>'equipmentKind') else coalesce(existing_kind,'container') end;
  -- Retain exact pre-existing specialist values, but do not introduce unknown
  -- kinds or silently trim/truncate one kind into a different identity.
  if kind='' or length(kind)>40 or (kind not in ('container','uld','vehicle','trailer','wagon')
    and kind is distinct from existing_kind) then
    raise exception 'Choose Container, ULD, Vehicle, Trailer or Wagon. Existing specialist kinds may be retained.' using errcode='22023'; end if;
  if kind<>'container' and (
    (nullif(item->>'verifiedGrossMassKg','') is not null and (item->>'verifiedGrossMassKg')::numeric is distinct from existing_vgm)
    or (nullif(item->>'vgmMethod','') is not null and item->>'vgmMethod' is distinct from existing_method)) then
    raise exception 'VGM applies to freight containers, not this equipment kind. Existing evidence may be retained or cleared.' using errcode='22023'; end if;
  return kind;
end $$;


ALTER FUNCTION "booking_api"."equipment_kind_for_save"("item" "jsonb", "requested_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."finance_job_columns"() RETURNS TABLE("table_name" "text", "column_name" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
 select distinct c.relname::text,a.attname::text from pg_catalog.pg_constraint fk
 join pg_catalog.pg_class c on c.oid=fk.conrelid
 join pg_catalog.pg_namespace n on n.oid=c.relnamespace
 join pg_catalog.pg_attribute a on a.attrelid=c.oid and a.attnum=fk.conkey[1]
 where fk.contype='f' and fk.confrelid='public."Job_Header"'::regclass and cardinality(fk.conkey)=1
 and n.nspname='public' and (c.relname like 'FIN\_%' escape '\' or c.relname like 'Job\_Costing%' escape '\' or c.relname like 'Acc\_%' escape '\');
$$;


ALTER FUNCTION "booking_api"."finance_job_columns"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."find_customs_department"("workspace_company_id" "uuid", "requested_office_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  department_id_value uuid;
  candidates uuid[];
begin
  select mapping.department_id into department_id_value
  from booking_api.office_customs_departments mapping
  join public."cmp_Departments" department on department."Department_ID" = mapping.department_id
  where mapping.company_id = workspace_company_id and mapping.office_id = requested_office_id
    and department."Company_ID" = workspace_company_id and department."Department_IsActive";
  if department_id_value is not null then return department_id_value; end if;

  select array_agg(department."Department_ID" order by department."Department_ID") into candidates
  from public."cmp_Departments" department
  where department."Company_ID" = workspace_company_id and department."Department_IsActive"
    and lower(btrim(department."Department_Name")) in ('customs','customs & compliance','customs and compliance');
  if cardinality(candidates) = 1 then return candidates[1]; end if;
  return null;
end;
$$;


ALTER FUNCTION "booking_api"."find_customs_department"("workspace_company_id" "uuid", "requested_office_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."guard_financial_booking"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare row_data jsonb:=to_jsonb(new);costing_id uuid;costing_job uuid;
begin
 perform booking_api.require_financial_booking(nullif(row_data->>tg_argv[0],'')::uuid);
 costing_id:=nullif(coalesce(row_data->>'FINDocLineJob_JobCostingLineID',row_data->>'FINAccrual_JobCostingLineID',row_data->>'FINWIP_JobCostingLineID'),'')::uuid;
 if costing_id is not null then
  select "Job_ID" into costing_job from public."Job_Costing_Lines" where "JobCostingLine_ID"=costing_id;
  perform booking_api.require_financial_booking(costing_job);
 end if;
 -- Finance's polymorphic source cannot be used to bypass its typed job link.
 if tg_table_name='FIN_Documents' and row_data->>'FINDoc_SourceTable'='Job_Header' then
  perform booking_api.require_financial_booking(nullif(row_data->>'FINDoc_SourceID','')::uuid);
 end if;
 return new;
end $$;


ALTER FUNCTION "booking_api"."guard_financial_booking"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."guard_lifecycle_transition"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare previous text; target text;
begin
 if new."Job_Status" is not distinct from old."Job_Status" then return new;end if;
 previous:=booking_api.lifecycle_label(old."Job_Status");target:=booking_api.lifecycle_label(new."Job_Status");
 if previous in ('cancelled','archived') and target in ('Provisional','In progress','Complete') then
  raise exception 'Cancelled or archived bookings cannot be reopened through the status selector.' using errcode='22023';end if;
 if previous='Provisional' and target='Complete' then
  raise exception 'Move the booking to In progress before marking it Complete.' using errcode='22023';end if;
 if target='In progress' and previous is distinct from target then
  if new."Job_Customer" is null then raise exception 'Choose a customer in Details before moving to In progress.' using errcode='22023';end if;
  if nullif(btrim(new."Job_TransportModeSummary"),'') is null then raise exception 'Choose a transport mode in Details before moving to In progress.' using errcode='22023';end if;
  if nullif(btrim(coalesce(new."Job_OriginUNLocode",new."Job_OriginNameSnapshot")),'') is null or
     nullif(btrim(coalesce(new."Job_DestinationUNLocode",new."Job_DestinationNameSnapshot")),'') is null then
   raise exception 'Add the origin and destination in Details before moving to In progress.' using errcode='22023';end if;
 end if;
 if target='Provisional' and previous is distinct from target then
  if previous='Complete' then raise exception 'Reopen the booking as In progress before changing its planning status.' using errcode='22023';end if;
  if exists(select 1 from public."FIN_Documents" d where d."FINDoc_PostingStatusCode"='posted' and
      (d."FINDoc_SourceJobID"=new."Job_ID" or exists(select 1 from public."FIN_DocumentLineJobLinks" l where l."FINDocLineJob_DocumentID"=d."FINDoc_ID" and l."FINDocLineJob_JobID"=new."Job_ID")))
    or exists(select 1 from public."FIN_WIPItems" w where w."FINWIP_JobID"=new."Job_ID")
    or exists(select 1 from public."FIN_Accruals" a where a."FINAccrual_JobID"=new."Job_ID") then
   raise exception 'This booking has finance activity. Financial records require an In progress or Complete booking.' using errcode='22023';end if;
 end if;
 if target='Complete' and previous is distinct from target then new."Job_ClosedDate":=coalesce(new."Job_ClosedDate",current_date);
 elsif previous='Complete' and target='In progress' then new."Job_ClosedDate":=null;end if;
 return new;
end $$;


ALTER FUNCTION "booking_api"."guard_lifecycle_transition"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."guard_provisional_finance_history"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare item record; found_record boolean;
begin
 if new."Job_Status" is not distinct from old."Job_Status" or lower(new."Job_Status") not in ('draft','provisional') then return new;end if;
 for item in select * from booking_api.finance_job_columns() loop
  execute format('select exists(select 1 from public.%I where %I=$1)',item.table_name,item.column_name) into found_record using new."Job_ID";
  if found_record then raise exception 'This booking has financial records and cannot become Provisional.' using errcode='22023';end if;
 end loop;
 if exists(select 1 from public."FIN_Documents" where "FINDoc_SourceTable"='Job_Header' and "FINDoc_SourceID"=new."Job_ID") then
  raise exception 'This booking has financial records and cannot become Provisional.' using errcode='22023';end if;
 return new;
end $_$;


ALTER FUNCTION "booking_api"."guard_provisional_finance_history"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."guard_route_cutoffs"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if tg_op='UPDATE' and new."JobRoute_ModeCode" is distinct from old."JobRoute_ModeCode" then
    if new."JobRoute_CargoCutoffAt" is not distinct from old."JobRoute_CargoCutoffAt" then new."JobRoute_CargoCutoffAt":=null;end if;
    if new."JobRoute_DocumentationCutoffAt" is not distinct from old."JobRoute_DocumentationCutoffAt" then new."JobRoute_DocumentationCutoffAt":=null;end if;
    if new."JobRoute_VgmCutoffAt" is not distinct from old."JobRoute_VgmCutoffAt" then new."JobRoute_VgmCutoffAt":=null;end if;
  end if;
  if new."JobRoute_VgmCutoffAt" is not null and new."JobRoute_ModeCode" is distinct from 'sea' then
    raise exception 'A VGM cut-off belongs to a Sea routing leg only.' using errcode='22023';end if;
  return new;
end $$;


ALTER FUNCTION "booking_api"."guard_route_cutoffs"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."has_permission"("caller_auth_user_id" "uuid", "permission_value" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (
    select 1
    from public."cmp_Users" app_user
    where app_user."Auth_User_ID" = caller_auth_user_id
      and coalesce(app_user."User_AccessStatus", 'active') = 'active'
      and (
        exists (
          select 1
          from public."cmp_Users_Roles" user_role
          join public."sys_UserRole_Permissions" role_permission
            on role_permission."sys_UserRole_ID" = user_role."sys_UserRole_ID"
          join public."sys_Permissions" permission
            on permission."sys_Permission_ID" = role_permission."sys_Permission_ID"
          where user_role."User_ID" = app_user."User_ID"
            and permission."sys_Permission_Value" = permission_value
        )
        or (
          permission_value in ('Customs.Read', 'Customs.Write')
          and exists (
            select 1
            from public."cmp_Users_Departments" membership
            join public."cmp_Departments" department
              on department."Department_ID" = membership."Department_ID"
            join booking_api.office_customs_departments customs_department
              on customs_department.department_id = department."Department_ID"
             and customs_department.company_id = app_user."Company_ID"
            where membership."User_ID" = app_user."User_ID"
              and department."Department_IsActive"
          )
        )
      )
  )
$$;


ALTER FUNCTION "booking_api"."has_permission"("caller_auth_user_id" "uuid", "permission_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."hydrate_accepted_quote_booking"("requested_job_id" "uuid", "requested_actor_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  job_row record;
  payload jsonb;
  facts jsonb;
  cargo_description text;
  container_type text;
  desired_containers integer := 0;
  current_containers integer := 0;
  sequence_number integer;
begin
  select job.* into job_row
  from public."Job_Header" job
  where job."Job_ID" = requested_job_id
    and job."Job_SourceQuoteID" is not null
    and not job."Job_IsDeleted"
  for update;
  if not found then return; end if;

  payload := coalesce(job_row."Job_SourceSnapshotJSON"#>'{acceptedSnapshot,quote}', '{}'::jsonb);
  facts := coalesce(payload->'shipmentFacts', '{}'::jsonb);
  cargo_description := nullif(btrim(coalesce(facts->>'goodsDescription', facts->>'knownCargo', facts->>'commodity')), '');
  container_type := nullif(btrim(facts->>'container'), '');
  desired_containers := least(100, greatest(0, coalesce(
    nullif(regexp_replace(coalesce(facts->>'containerCount', ''), '[^0-9]', '', 'g'), '')::integer,
    case when container_type is null then 0 else 1 end
  )));

  update public."Job_Header" job set
    "Job_CustomerReference" = coalesce(job."Job_CustomerReference", nullif(btrim(payload->>'customerReference'), '')),
    "Job_SupplierReference" = coalesce(job."Job_SupplierReference", nullif(btrim(facts->>'supplierReference'), '')),
    "Job_OperationsOwnerID" = coalesce(job."Job_OperationsOwnerID", nullif(payload->>'salesOwnerId', '')::uuid, job_row."Job_CreatedBy"),
    "Job_CustomerNotes" = coalesce(job."Job_CustomerNotes", nullif(btrim(payload->>'customerNotes'), '')),
    "Job_TermsConditions" = coalesce(job."Job_TermsConditions", nullif(btrim(payload->>'terms'), '')),
    "Job_SubjectToTerms" = coalesce(job."Job_SubjectToTerms", nullif(btrim(facts->>'subjectToTerms'), '')),
    "Job_SourceSnapshotJSON" = job."Job_SourceSnapshotJSON" || jsonb_build_object(
      'operationalHydration', jsonb_build_object('version', 1, 'hydratedAt', now())
    ),
    "Job_UpdatedAt" = now(),
    "Job_UpdatedBy" = coalesce(requested_actor_user_id, job."Job_UpdatedBy", job."Job_CreatedBy")
  where job."Job_ID" = requested_job_id;

  if cargo_description is not null and not exists (
    select 1 from public."Job_Cargo" cargo
    where cargo."JobCargo_JobID" = requested_job_id and not cargo."JobCargo_IsDeleted"
  ) then
    insert into public."Job_Cargo" (
      "JobCargo_JobID", "JobCargo_LineNo", "JobCargo_Description", "JobCargo_Commodity",
      "JobCargo_Qty", "JobCargo_PackageTypeCodeSnapshot", "JobCargo_PackageQty",
      "JobCargo_GrossKilos", "JobCargo_NettKilos", "JobCargo_HSCode", "JobCargo_VolumeCBM",
      "JobCargo_DeclaredValueAmount", "JobCargo_DeclaredValueCurrencyCodeSnapshot",
      "JobCargo_CargoJSON", "JobCargo_UpdatedBy"
    ) values (
      requested_job_id, 1, cargo_description, left(nullif(btrim(facts->>'commodity'), ''), 50),
      nullif(coalesce(facts->>'pieces', facts->>'packageQuantity'), '')::numeric,
      left(nullif(btrim(facts->>'packageType'), ''), 40),
      nullif(coalesce(facts->>'packageQuantity', facts->>'pieces'), '')::numeric,
      nullif(facts->>'grossWeightKg', '')::numeric, nullif(facts->>'netWeightKg', '')::numeric,
      left(nullif(btrim(facts->>'hsCode'), ''), 30), nullif(facts->>'volumeCbm', '')::numeric,
      nullif(regexp_replace(coalesce(facts->>'goodsValue', ''), '[^0-9.-]', '', 'g'), '')::numeric,
      coalesce(nullif(upper(facts->>'goodsValueCurrency'), ''), nullif(upper(payload->>'currency'), '')),
      facts || jsonb_build_object('source', 'accepted_quote'),
      coalesce(requested_actor_user_id, job_row."Job_UpdatedBy", job_row."Job_CreatedBy")
    );
  end if;

  select count(*)::integer into current_containers
  from public."Job_Containers" container
  where container."Job_ID" = requested_job_id and not container."JobContainer_IsDeleted";

  if desired_containers > current_containers then
    for sequence_number in current_containers + 1 .. desired_containers loop
      insert into public."Job_Containers" (
        "Job_ID", "JobContainer_TypeCodeSnapshot", "JobContainer_EquipmentKind", "JobContainer_Status",
        "JobContainer_JSON", "JobContainer_UpdatedBy"
      ) values (
        requested_job_id, left(container_type, 40),
        case when lower(coalesce(payload->>'mode', '')) in ('air', 'courier') then 'unit_load_device' else 'container' end,
        'planned', jsonb_strip_nulls(jsonb_build_object(
          'description', container_type, 'sequence', sequence_number, 'source', 'accepted_quote'
        )), coalesce(requested_actor_user_id, job_row."Job_UpdatedBy", job_row."Job_CreatedBy")
      );
    end loop;
  end if;
end;
$$;


ALTER FUNCTION "booking_api"."hydrate_accepted_quote_booking"("requested_job_id" "uuid", "requested_actor_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."insert_accepted_quote_cargo"("requested_job_id" "uuid", "requested_version_id" "uuid", "actor_user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare snapshot jsonb; facts jsonb; lines jsonb; missing text[];
begin
  -- Internal-only helper, called inside initial conversion's transaction.
  -- Bind both the job and the source lines to the exact accepted version.
  select version."CusQuoteVersion_SnapshotJSON" into snapshot
    from public."CusQuote_Versions" version
    join public."Job_Header" job on job."Job_SourceQuoteVersionID"=version."CusQuoteVersion_ID"
      and job."Job_SourceQuoteID"=version."CusQuoteHeader_ID"
    join public."CusQuote_Header" quote on quote."CusQuoteHeader_ID"=version."CusQuoteHeader_ID"
      and quote."CusQuoteHeader_AcceptedVersionID"=version."CusQuoteVersion_ID"
    where job."Job_ID"=requested_job_id and not job."Job_IsDeleted"
      and version."CusQuoteVersion_ID"=requested_version_id and version."CusQuoteVersion_IsSubmitted"
      and quote."CusQuoteHeader_LifecycleCode"='accepted' and not quote."CusQuoteHeader_IsDeleted";
  if not found then raise exception 'Cargo handover requires the exact accepted quote version.' using errcode='22023'; end if;
  facts:=snapshot#>'{quote,shipmentFacts}';
  lines:=quote_api.normalise_cargo_lines(facts->'cargoLines',true);
  missing:=quote_api.cargo_booking_missing(lines);
  if cardinality(missing)>0 then raise exception 'Correct cargo before Booking handover.' using errcode='22023',detail=to_jsonb(missing)::text; end if;
  if exists(select 1 from public."Job_Cargo" where "JobCargo_JobID"=requested_job_id) then
    raise exception 'Initial cargo handover cannot replace existing Booking cargo.' using errcode='22023';
  end if;
  if (select count(*) from quote_api.version_cargo_lines where version_id=requested_version_id)<>jsonb_array_length(lines) then
    raise exception 'Accepted cargo projection is incomplete.' using errcode='22023';
  end if;
  insert into public."Job_Cargo" (
    "JobCargo_JobID","JobCargo_LineNo","JobCargo_Description","JobCargo_Commodity","JobCargo_Qty","JobCargo_PackageQty",
    "JobCargo_PackageTypeCodeSnapshot","JobCargo_GrossKilos","JobCargo_NettKilos","JobCargo_VolumeCBM","JobCargo_ChargeableWeightKg",
    "JobCargo_Length","JobCargo_Width","JobCargo_Height","JobCargo_LengthUnit","JobCargo_HSCode","JobCargo_CountryOfOriginCodeSnapshot",
    "JobCargo_IsHazardous","JobCargo_IsTemperatureControlled",
    "JobCargo_DeclaredValueAmount","JobCargo_DeclaredValueCurrencyCodeSnapshot",
    "JobCargo_SourceQuoteVersionID","JobCargo_SourceQuoteLineID","JobCargo_CargoJSON","JobCargo_UpdatedBy"
  ) select requested_job_id,line_number,description,commodity,package_quantity,package_quantity,
    package_type,gross_weight_kg,net_weight_kg,volume_cbm,chargeable_weight_kg,length,width,height,length_unit,hs_code,country_of_origin,
    is_hazardous,is_temperature_controlled,
    case when jsonb_array_length(lines)=1 then nullif(regexp_replace(coalesce(facts->>'goodsValue',''),'[^0-9.-]','','g'),'')::numeric end,
    case when jsonb_array_length(lines)=1 then coalesce(nullif(upper(facts->>'goodsValueCurrency'),''),nullif(upper(snapshot#>>'{quote,currency}'),'')) end,
    version_id,line_id,
    -- Compatibility for existing dimension/chargeable readers, not a replacement
    -- for typed provenance or an allocation of shipment-wide declared value.
    lines->(line_number-1)||jsonb_build_object('source','accepted_quote','quoteVersionId',version_id,'quoteCargoLineId',line_id),actor_user_id
    from quote_api.version_cargo_lines where version_id=requested_version_id order by line_number;
end;
$$;


ALTER FUNCTION "booking_api"."insert_accepted_quote_cargo"("requested_job_id" "uuid", "requested_version_id" "uuid", "actor_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."lifecycle_label"("status" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
 select case lower(btrim(status))
 when 'draft' then 'Provisional' when 'provisional' then 'Provisional'
 when 'complete' then 'Complete' when 'completed' then 'Complete' when 'closed' then 'Complete'
 when 'open' then 'In progress' when 'booked' then 'In progress' when 'in_transit' then 'In progress'
 when 'arrived' then 'In progress' when 'delivered' then 'In progress' when 'ready_for_invoice' then 'In progress'
 when 'in_progress' then 'In progress' else status end;
$$;


ALTER FUNCTION "booking_api"."lifecycle_label"("status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."lock_allocation_job"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare job uuid; previous_job uuid; linked boolean:=false;
begin
  if tg_table_name='cargo_equipment_allocations' then
    job:=new.job_id; if tg_op='UPDATE' then previous_job:=old.job_id;end if;
    linked:=true;
  elsif tg_table_name='Job_Cargo' then
    job:=new."JobCargo_JobID"; previous_job:=old."JobCargo_JobID";
    if job is distinct from previous_job then select exists(select 1 from booking_api.cargo_equipment_allocations where cargo_id=old."JobCargo_ID") into linked;end if;
  else
    job:=new."Job_ID"; previous_job:=old."Job_ID";
    if job is distinct from previous_job then
      if tg_table_name='Job_Containers' then
        select exists(select 1 from booking_api.cargo_equipment_allocations where container_id=old."JobContainers_ID") into linked;
      else
        select exists(select 1 from booking_api.cargo_equipment_allocations where route_id=old."JobRoute_ID") into linked;
      end if;
    end if;
  end if;
  if linked and job is distinct from previous_job and tg_op='UPDATE' then
    raise exception 'Moving cargo, equipment or allocations to another Booking is not supported.' using errcode='23514';end if;
  perform 1 from public."Job_Header" where "Job_ID"=job for update;
  return new;
end $$;


ALTER FUNCTION "booking_api"."lock_allocation_job"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."normalise_booking_direction_payload"("requested_job_id" "uuid", "payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  job_row record;
  route_count integer := case when jsonb_typeof(payload->'routes') = 'array' then jsonb_array_length(payload->'routes') else 0 end;
  origin_location text;
  destination_location text;
  expected_direction text;
begin
  select job.* into job_row
  from public."Job_Header" job
  where job."Job_ID" = requested_job_id
    and not job."Job_IsDeleted";
  if not found then return payload; end if;

  origin_location := coalesce(
    nullif(payload->>'originUnlocode', ''),
    nullif(payload#>>'{route,originUnlocode}', ''),
    case when route_count > 0 then nullif(payload->'routes'->0->>'originUnlocode', '') end,
    job_row."Job_OriginUNLocode"
  );
  destination_location := coalesce(
    nullif(payload->>'destinationUnlocode', ''),
    case when route_count > 0 then nullif(payload->'routes'->(route_count - 1)->>'destinationUnlocode', '') end,
    nullif(payload#>>'{route,destinationUnlocode}', ''),
    job_row."Job_DestinationUNLocode"
  );
  expected_direction := booking_api.direction_for_route(
    coalesce(job_row."Job_OrgOfficeID", job_row."Job_OfficeID"),
    origin_location,
    destination_location
  );
  if expected_direction is null then return payload; end if;

  return jsonb_set(coalesce(payload, '{}'::jsonb), '{direction}', to_jsonb(expected_direction), true);
end;
$$;


ALTER FUNCTION "booking_api"."normalise_booking_direction_payload"("requested_job_id" "uuid", "payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."normalise_cargo_numbers"("lines" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
declare result jsonb:='[]'; item jsonb; raw text; amount numeric; line_no integer:=0;
begin
  for item in select value from jsonb_array_elements(
    booking_api.normalise_cargo_numbers_before_chargeable_weight_20260907(lines)) loop
    line_no:=line_no+1;
    if item ? 'chargeableWeightKg' then
      if jsonb_typeof(item->'chargeableWeightKg') not in ('string','number','null') then
        raise exception 'Cargo line %: chargeable weight (kg) must be a number.',line_no using errcode='22023';
      end if;
      raw:=nullif(btrim(item->>'chargeableWeightKg'),'');
      if raw is null then
        item:=jsonb_set(item,'{chargeableWeightKg}','null');
      else
        if length(raw)>64 or (raw !~ '^[0-9]+([.][0-9]+)?$' and raw !~ '^[0-9]{1,3}(,[0-9]{3})+([.][0-9]+)?$') then
          raise exception 'Cargo line %: chargeable weight (kg) must be a non-negative decimal number.',line_no using errcode='22023';
        end if;
        amount:=replace(raw,',','')::numeric;
        -- Match the Quote cargo bound without imposing the gross-weight scale.
        if amount>999999999999 then
          raise exception 'Cargo line %: chargeable weight (kg) exceeds the supported maximum.',line_no using errcode='22023';
        end if;
        item:=jsonb_set(item,'{chargeableWeightKg}',to_jsonb(amount::text));
      end if;
    end if;
    result:=result||jsonb_build_array(item);
  end loop;
  return result;
end $_$;


ALTER FUNCTION "booking_api"."normalise_cargo_numbers"("lines" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."normalise_cargo_numbers_before_chargeable_weight_20260907"("lines" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
declare item jsonb; result jsonb:='[]'; key text; label text; raw text; amount numeric; places integer; line_no integer:=0;
begin
  if jsonb_typeof(lines) is distinct from 'array' or jsonb_array_length(lines)>200 then
    raise exception 'Booking cargo lines are invalid.' using errcode='22023'; end if;
  for item in select value from jsonb_array_elements(lines) loop
    line_no:=line_no+1;
    if jsonb_typeof(item) is distinct from 'object' then raise exception 'Cargo line % is invalid.',line_no using errcode='22023'; end if;
    foreach key in array array['pieces','packageQuantity','grossWeightKg','netWeightKg','volumeCbm','length','width','height','declaredValue'] loop
      if not item ? key then continue; end if;
      label:=case key when 'pieces' then 'pieces' when 'packageQuantity' then 'packages / pieces'
        when 'grossWeightKg' then 'gross weight (kg)' when 'netWeightKg' then 'net weight (kg)'
        when 'volumeCbm' then 'volume (CBM)' when 'declaredValue' then 'cargo line value' else key end;
      if jsonb_typeof(item->key) not in ('string','number','null') then
        raise exception 'Cargo line %: % must be a number.',line_no,label using errcode='22023'; end if;
      raw:=nullif(btrim(item->>key),'');
      if raw is null then item:=jsonb_set(item,array[key],'null'); continue; end if;
      if length(raw)>64 or (raw !~ '^[0-9]+([.][0-9]+)?$' and raw !~ '^[0-9]{1,3}(,[0-9]{3})+([.][0-9]+)?$') then
        raise exception 'Cargo line %: % must be a non-negative decimal number.',line_no,label using errcode='22023'; end if;
      amount:=replace(raw,',','')::numeric;
      places:=case when key in ('packageQuantity','volumeCbm') then 6 when key='declaredValue' then 4 else 2 end;
      if amount<>round(amount,places) or amount>=power(10::numeric,18-places) then
        raise exception 'Cargo line %: % supports up to % whole digits and % decimal places.',line_no,label,18-places,places using errcode='22023'; end if;
      item:=jsonb_set(item,array[key],to_jsonb(amount::text));
    end loop;
    result:=result||jsonb_build_array(item);
  end loop;
  return result;
end $_$;


ALTER FUNCTION "booking_api"."normalise_cargo_numbers_before_chargeable_weight_20260907"("lines" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."normalise_container_operations"("lines" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
declare item jsonb; result jsonb:='[]'; key text; raw text; amount numeric; places integer; precision_digits integer; line_no integer:=0;
begin
  if jsonb_typeof(lines) is distinct from 'array' or jsonb_array_length(lines)>100 then
    raise exception 'Booking containers are invalid.' using errcode='22023';end if;
  for item in select value from jsonb_array_elements(lines) loop
    line_no:=line_no+1;
    if jsonb_typeof(item) is distinct from 'object' then raise exception 'Container % must be an object.',line_no using errcode='22023';end if;
    foreach key in array array['grossWeightKg','tareWeightKg','verifiedGrossMassKg','reeferSetPoint'] loop
      if not item ? key then continue;end if;
      if jsonb_typeof(item->key) not in ('string','number','null') then raise exception 'Container %: % must be a number.',line_no,key using errcode='22023';end if;
      raw:=nullif(btrim(item->>key),'');
      if raw is null then item:=jsonb_set(item,array[key],'null');continue;end if;
      if length(raw)>64 or raw !~ '^-?([0-9]+|[0-9]{1,3}(,[0-9]{3})+)([.][0-9]+)?$' then
        raise exception 'Container %: enter a valid decimal for %.',line_no,key using errcode='22023';end if;
      amount:=replace(raw,',','')::numeric;
      places:=case when key='reeferSetPoint' then 3 else 6 end;
      precision_digits:=case when key='reeferSetPoint' then 10 else 18 end;
      if (key<>'reeferSetPoint' and amount<0) or amount<>round(amount,places) or abs(amount)>=power(10::numeric,precision_digits-places) then
        raise exception 'Container %: % is outside its supported range or precision.',line_no,key using errcode='22023';end if;
      item:=jsonb_set(item,array[key],to_jsonb(amount::text));
    end loop;
    foreach key in array array['vgmMethod','reeferUnit'] loop
      if not item ? key then continue;end if;
      if jsonb_typeof(item->key) not in ('string','null') then raise exception 'Container %: choose a valid %.',line_no,key using errcode='22023';end if;
      raw:=nullif(btrim(item->>key),'');
      if raw is not null and ((key='vgmMethod' and raw not in ('1','2')) or (key='reeferUnit' and raw not in ('C','F'))) then
        raise exception 'Container %: choose a valid %.',line_no,key using errcode='22023';end if;
      item:=jsonb_set(item,array[key],coalesce(to_jsonb(raw),'null'::jsonb));
    end loop;
    result:=result||jsonb_build_array(item);
  end loop;
  return result;
end $_$;


ALTER FUNCTION "booking_api"."normalise_container_operations"("lines" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."normalise_direction"("value" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case lower(replace(replace(btrim(coalesce(value, '')), '-', '_'), ' ', '_'))
    when 'import' then 'import'
    when 'export' then 'export'
    when 'domestic' then 'domestic'
    when 'cross_trade' then 'cross_trade'
    when 'crosstrade' then 'cross_trade'
    else 'unknown'
  end
$$;


ALTER FUNCTION "booking_api"."normalise_direction"("value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."normalise_mode"("value" "text") RETURNS "text"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select mode."JTM_Code"
  from public."sys_JobTransportModes" mode
  where mode."JTM_IsActive"
    and (
      lower(mode."JTM_Code") = lower(btrim(coalesce(value, '')))
      or lower(mode."JTM_Name") = lower(btrim(coalesce(value, '')))
    )
  order by mode."JTM_SortOrder", mode."JTM_Code"
  limit 1
$$;


ALTER FUNCTION "booking_api"."normalise_mode"("value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."normalise_shipment_value"("value" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
declare amount_text text; currency_text text; amount_value numeric;
begin
  if value is null or jsonb_typeof(value)<>'object' or exists(select 1 from jsonb_object_keys(value) key where key not in ('amount','currency')) then
    raise exception 'Provide shipment goods value as an amount and currency.' using errcode='22023'; end if;
  if jsonb_typeof(value->'amount') not in ('number','string','null') or jsonb_typeof(value->'currency') not in ('string','null') then
    raise exception 'Shipment goods value must contain a numeric amount and currency code.' using errcode='22023'; end if;
  amount_text:=nullif(btrim(value->>'amount'),'');currency_text:=nullif(upper(btrim(value->>'currency')),'');
  if amount_text is not null then
    if length(amount_text)>32 or amount_text !~ '^([0-9]+|[0-9]{1,3}(,[0-9]{3})+)(\.[0-9]+)?$' then
      raise exception 'Enter a non-negative shipment goods value.' using errcode='22023'; end if;
    amount_value:=replace(amount_text,',','')::numeric;
    if amount_value>=100000000000000 or amount_value<>round(amount_value,4) then
      raise exception 'Shipment goods value supports up to 14 whole digits and 4 decimal places.' using errcode='22023'; end if;
  end if;
  if currency_text is not null and currency_text !~ '^[A-Z]{3}$' then
    raise exception 'Choose a three-letter shipment goods currency.' using errcode='22023'; end if;
  if amount_value is not null and currency_text is null then
    raise exception 'Choose a currency for the shipment goods value.' using errcode='22023'; end if;
  return jsonb_build_object('amount',amount_value,'currency',currency_text);
end;
$_$;


ALTER FUNCTION "booking_api"."normalise_shipment_value"("value" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."on_quote_accepted_create_booking"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare conversion jsonb; actor_id uuid;
begin
  if current_setting('quote_api.discard_restore_quote',true)=new."CusQuoteHeader_ID"::text
    and exists(select 1 from public."CusQuote_Versions" discarded
      join public."CusQuote_Versions" restored on restored."CusQuoteVersion_ID"=discarded."CusQuoteVersion_DiscardedToID"
      where discarded."CusQuoteHeader_ID"=new."CusQuoteHeader_ID"
        and discarded."CusQuoteVersion_DiscardedAt"=transaction_timestamp()
        and restored."CusQuoteVersion_IsCurrent" and restored."CusQuoteVersion_IsSubmitted") then
    return new;
  end if;
  if new."CusQuoteHeader_LifecycleCode"='accepted'
    and old."CusQuoteHeader_LifecycleCode" is distinct from new."CusQuoteHeader_LifecycleCode" then
    actor_id:=coalesce(new."CusQuoteHeader_LastEditedBy",new."CusQuoteHeader_CreatedBy");
    conversion:=booking_api.convert_accepted_quote(new."CusQuoteHeader_ID",actor_id,null);
    perform booking_api.hydrate_accepted_quote_booking((conversion->>'jobId')::uuid,actor_id);
    perform booking_api.correct_accepted_quote_booking((conversion->>'jobId')::uuid,actor_id);
  end if;
  return new;
end;
$$;


ALTER FUNCTION "booking_api"."on_quote_accepted_create_booking"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."open_booking"("caller_auth_user_id" "uuid", "requested_idempotency_key" "uuid", "requested_sequence_key" "text" DEFAULT 'default'::"text") RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select booking_api.open_booking(caller_auth_user_id,requested_idempotency_key,requested_sequence_key,null);
$$;


ALTER FUNCTION "booking_api"."open_booking"("caller_auth_user_id" "uuid", "requested_idempotency_key" "uuid", "requested_sequence_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."open_booking"("caller_auth_user_id" "uuid", "requested_idempotency_key" "uuid", "requested_sequence_key" "text", "requested_direction" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare app_user record;office_id uuid;booking_reference text;job_id uuid;existing_job record;
begin
  if caller_auth_user_id is null or not booking_api.has_permission(caller_auth_user_id,'Bookings.Write') then
    raise exception 'Booking creation is not authorised.' using errcode='42501';end if;
  if requested_idempotency_key is null then raise exception 'A booking request key is required.' using errcode='22023';end if;
  if requested_direction is not null and requested_direction not in ('import','export','domestic','cross_trade') then
    raise exception 'Choose a valid Booking direction.' using errcode='22023';end if;
  select "User_ID","Company_ID" into strict app_user from public."cmp_Users"
    where "Auth_User_ID"=caller_auth_user_id and "User_AccessStatus"='active';
  select job.* into existing_job from public."Job_Header" job
    join public."cmp_Offices" office on office."Office_ID"=coalesce(job."Job_OrgOfficeID",job."Job_OfficeID")
    where job."Job_CreatedBy"=app_user."User_ID" and job."Job_CreateIdempotencyKey"=requested_idempotency_key
      and office."Company_ID"=app_user."Company_ID" and not job."Job_IsDeleted" limit 1;
  if found then return jsonb_build_object('jobId',existing_job."Job_ID",'bookingReference',existing_job."Job_BookingReference",'reused',true);end if;
  select office."Office_ID" into office_id from public."cmp_Offices" office
    where office."Company_ID"=app_user."Company_ID" and office."Office_IsActive" order by office."Office_ID" limit 1;
  if office_id is null then raise exception 'No active office is configured for this workspace.' using errcode='22023';end if;
  booking_reference:=booking_api.allocate_reference(app_user."Company_ID",requested_sequence_key,requested_direction);
  insert into public."Job_Header" (
    "Job_Period","Job_CreatedBy","Job_Customer","Job_OfficeID","Job_OrgOfficeID","Job_Status","Job_Direction",
    "Job_TrackingStatus","Job_CurrentLocationNameSnapshot","Job_BookingReference","Job_CreateIdempotencyKey","Job_UpdatedBy"
  ) values (
    to_char(current_date,'YYYYMM'),app_user."User_ID",null,office_id,office_id,'draft',coalesce(requested_direction,'unknown'),
    'planning','Planning',booking_reference,requested_idempotency_key,app_user."User_ID"
  ) returning "Job_ID" into job_id;
  insert into booking_api.events(company_id,job_id,event_type,summary,actor_user_id)
    values(app_user."Company_ID",job_id,'created','Draft booking created.',app_user."User_ID");
  return jsonb_build_object('jobId',job_id,'bookingReference',booking_reference,'reused',false);
exception when unique_violation then
  select job.* into existing_job from public."Job_Header" job
    join public."cmp_Offices" office on office."Office_ID"=coalesce(job."Job_OrgOfficeID",job."Job_OfficeID")
    where job."Job_CreatedBy"=app_user."User_ID" and job."Job_CreateIdempotencyKey"=requested_idempotency_key
      and office."Company_ID"=app_user."Company_ID" and not job."Job_IsDeleted" limit 1;
  if found then return jsonb_build_object('jobId',existing_job."Job_ID",'bookingReference',existing_job."Job_BookingReference",'reused',true);end if;
  raise;
end $$;


ALTER FUNCTION "booking_api"."open_booking"("caller_auth_user_id" "uuid", "requested_idempotency_key" "uuid", "requested_sequence_key" "text", "requested_direction" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."operating_country_code"("requested_office_id" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(
    upper(nullif(btrim(office."Office_CountryCode"), '')),
    upper(nullif(btrim(linked_entity."LegalEntity_CountryCode"), '')),
    upper(nullif(btrim(default_entity."LegalEntity_CountryCode"), ''))
  )
  from public."cmp_Offices" office
  left join public."cmp_LegalEntities" linked_entity
    on linked_entity."LegalEntity_ID" = office."Office_LegalEntityID"
   and linked_entity."Company_ID" = office."Company_ID"
   and linked_entity."LegalEntity_IsActive"
  left join lateral (
    select entity."LegalEntity_CountryCode"
    from public."cmp_LegalEntities" entity
    where entity."Company_ID" = office."Company_ID"
      and entity."LegalEntity_IsActive"
      and nullif(btrim(entity."LegalEntity_CountryCode"), '') is not null
    order by entity."LegalEntity_IsDefault" desc, entity."LegalEntity_UpdatedAt" desc nulls last
    limit 1
  ) default_entity on true
  where office."Office_ID" = requested_office_id
    and office."Office_IsActive";
$$;


ALTER FUNCTION "booking_api"."operating_country_code"("requested_office_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."operational_workspace"("caller_auth_user_id" "uuid", "requested_reference" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  workspace_value jsonb;
  job_id uuid;
  booking_extra jsonb;
  routes_value jsonb;
  containers_value jsonb;
begin
  workspace_value := booking_api.workspace(caller_auth_user_id, requested_reference);
  job_id := (workspace_value#>>'{booking,jobId}')::uuid;

  select jsonb_strip_nulls(jsonb_build_object(
    'customerReference', job."Job_CustomerReference", 'supplierReference', job."Job_SupplierReference",
    'operationsOwnerId', job."Job_OperationsOwnerID",
    'operationsOwner', nullif(concat_ws(' ', owner."User_Firstname", owner."User_Lastname"), ''),
    'customerNotes', job."Job_CustomerNotes", 'terms', job."Job_TermsConditions",
    'subjectToTerms', job."Job_SubjectToTerms", 'invoiceReference', job."Job_InvoiceReference",
    'invoiceStatus', job."Job_InvoiceStatus", 'invoiceReadyAt', job."Job_InvoiceReadyAt",
    'completedAt', job."Job_CompletedAt", 'completionChecklist', job."Job_CompletionChecklistJSON",
    'locked', job."Job_Status" in ('ready_for_invoice','complete')
  )) into booking_extra
  from public."Job_Header" job
  left join public."cmp_Users" owner on owner."User_ID" = job."Job_OperationsOwnerID"
  where job."Job_ID" = job_id;

  select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
    'id', route."JobRoute_ID", 'order', route."JobRoute_OrderNo", 'status', route."JobRoute_Status",
    'mode', route."JobRoute_ModeCode", 'origin', route."JobRoute_OriginNameSnapshot",
    'originUnlocode', route."JobRoute_OriginUNLocode", 'originAddress', route."JobRoute_OriginAddressSnapshot",
    'originTerminal', route."JobRoute_OriginTerminal", 'destination', route."JobRoute_DestinationNameSnapshot",
    'destinationUnlocode', route."JobRoute_DestinationUNLocode", 'destinationAddress', route."JobRoute_DestinationAddressSnapshot",
    'destinationTerminal', route."JobRoute_DestinationTerminal", 'plannedPickupAt', route."JobRoute_PlannedPickupAt",
    'estimatedPickupAt', route."JobRoute_EstimatedPickupAt", 'actualPickupAt', route."JobRoute_ActualPickupAt",
    'plannedDepartureAt', route."JobRoute_PlannedDepartureAt", 'estimatedDepartureAt', route."JobRoute_EstimatedDepartureAt",
    'actualDepartureAt', route."JobRoute_ActualDepartureAt", 'plannedArrivalAt', route."JobRoute_PlannedArrivalAt",
    'estimatedArrivalAt', route."JobRoute_EstimatedArrivalAt", 'actualArrivalAt', route."JobRoute_ActualArrivalAt",
    'plannedDeliveryAt', route."JobRoute_PlannedDeliveryAt", 'estimatedDeliveryAt', route."JobRoute_EstimatedDeliveryAt",
    'actualDeliveryAt', route."JobRoute_ActualDeliveryAt", 'carrierId', route."JobRoute_Carrier",
    'carrierBookingReference', route."JobRoute_CarrierBookingReference",
    'masterTransportReference', route."JobRoute_MasterTransportReference",
    'houseTransportReference', route."JobRoute_HouseTransportReference", 'serviceLevel', route."JobRoute_ServiceLevel",
    'transportMeansName', route."JobRoute_TransportMeansName", 'vessel', route."JobRoute_Vessel",
    'voyageNumber', route."JobRoute_VoyageNumber", 'flightNumber', route."JobRoute_FlightNumber",
    'vehicleRegistration', route."JobRoute_VehicleRegistration", 'trailerNumber', route."JobRoute_TrailerNumber",
    'railService', route."JobRoute_RailService", 'isMainCarriage', route."JobRoute_IsMainCarriage",
    'internalNotes', route."JobRoute_InternalNotes", 'routeData', route."JobRoute_RouteJSON"
  )) order by route."JobRoute_OrderNo" nulls last), '[]'::jsonb) into routes_value
  from public."Job_Routing" route where route."Job_ID" = job_id;

  select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
    'id', container."JobContainers_ID", 'number', container."JobContainer_Number",
    'type', container."JobContainer_TypeCodeSnapshot", 'equipmentKind', container."JobContainer_EquipmentKind",
    'status', container."JobContainer_Status", 'tareWeightKg', container."JobContainer_TareKilos",
    'grossWeightKg', container."JobContainer_GrossKilos", 'vgmWeightKg', container."JobContainer_VGMKilos",
    'vgmMethod', container."JobContainer_VGMMethod", 'reeferSetPoint', container."JobContainer_ReeferSetPoint",
    'reeferUnit', container."JobContainer_ReeferUnit", 'isShipperOwned', container."JobContainer_IsShipperOwned",
    'sealNumber', seal."JobContainerSeal_Number", 'notes', container."JobContainer_Notes", 'data', container."JobContainer_JSON"
  )) order by container."JobContainer_CreatedAt"), '[]'::jsonb) into containers_value
  from public."Job_Containers" container
  left join lateral (
    select s."JobContainerSeal_Number" from public."Job_ContainerSeals" s
    where s."JobContainerSeal_JobContainerID" = container."JobContainers_ID" and s."JobContainerSeal_RemovedAt" is null
    order by s."JobContainerSeal_CreatedAt" desc limit 1
  ) seal on true
  where container."Job_ID" = job_id and not container."JobContainer_IsDeleted";

  return workspace_value || jsonb_build_object(
    'booking', (workspace_value->'booking') || coalesce(booking_extra, '{}'::jsonb),
    'routes', routes_value,
    'containers', containers_value,
    'completion', booking_api.completion_readiness_for_job(job_id)
  );
end;
$$;


ALTER FUNCTION "booking_api"."operational_workspace"("caller_auth_user_id" "uuid", "requested_reference" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."parse_milestone_time"("value" "jsonb") RETURNS timestamp with time zone
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    SET "TimeZone" TO 'UTC'
    AS $_$
declare text_value text;
begin
  if value is null or value = 'null'::jsonb then return null; end if;
  if jsonb_typeof(value) <> 'string' then
    raise exception 'A milestone time needs a date, time and explicit timezone, or can be cleared.' using errcode = '22023'; end if;
  text_value := nullif(btrim(value #>> '{}'), '');
  if text_value is null then return null; end if;
  if text_value !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T([01][0-9]|2[0-3]):[0-5][0-9](:[0-5][0-9]([.][0-9]{1,6})?)?(Z|[+-]((0[0-9]|1[0-3]):[0-5][0-9]|14:00))$' then
    raise exception 'Enter the complete milestone date and time with an explicit timezone.' using errcode = '22023'; end if;
  return text_value::timestamptz;
exception when invalid_datetime_format or datetime_field_overflow or invalid_time_zone_displacement_value then
  raise exception 'That milestone date, time or timezone is invalid.' using errcode = '22023';
end $_$;


ALTER FUNCTION "booking_api"."parse_milestone_time"("value" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."parse_route_cutoff"("value" "jsonb") RETURNS timestamp with time zone
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    SET "TimeZone" TO 'UTC'
    AS $_$
declare text_value text;
begin
  if value is null or value='null'::jsonb then return null;end if;
  if jsonb_typeof(value)<>'string' then
    raise exception 'A cut-off needs a date, time and explicit timezone, or can be cleared.' using errcode='22023';end if;
  text_value:=nullif(btrim(value#>>'{}'),'');
  if text_value is null then return null;end if;
  if text_value !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T([01][0-9]|2[0-3]):[0-5][0-9](:[0-5][0-9]([.][0-9]{1,6})?)?(Z|[+-]((0[0-9]|1[0-3]):[0-5][0-9]|14:00))$' then
    raise exception 'Enter the complete cut-off date and time with an explicit timezone. A date alone is not a deadline.' using errcode='22023';end if;
  return text_value::timestamptz;
exception when invalid_datetime_format or datetime_field_overflow or invalid_time_zone_displacement_value then
  raise exception 'That cut-off date, time or timezone is invalid.' using errcode='22023';
end $_$;


ALTER FUNCTION "booking_api"."parse_route_cutoff"("value" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."plan_quote_cargo_revision"("requested_job_id" "uuid", "baseline_version_id" "uuid", "proposed_version_id" "uuid", "selected_fields" "jsonb", "observed_booking_lines" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  job_row record; baseline_lines jsonb; proposed_lines jsonb; current_lines jsonb;
  current_map jsonb; proposed_map jsonb; observed_differences jsonb; current_differences jsonb;
  item jsonb; observed_item jsonb; line_id text; field_name text; target jsonb; plans jsonb:='{}';
  selected text; selected_count integer; cargo_id uuid;
begin
  -- Private only: the future public review action must still check the caller,
  -- workspace and explicit selections. Lock order matches canonical Booking save.
  select * into strict job_row from public."Job_Header" where "Job_ID"=requested_job_id and not "Job_IsDeleted" for update;
  if job_row."Job_SourceQuoteVersionID" is distinct from baseline_version_id then
    raise exception 'The applied Quote version changed. Refresh the review.' using errcode='40001'; end if;
  select version."CusQuoteVersion_SnapshotJSON"#>'{quote,shipmentFacts,cargoLines}' into baseline_lines
    from public."CusQuote_Versions" version where version."CusQuoteVersion_ID"=baseline_version_id
      and version."CusQuoteHeader_ID"=job_row."Job_SourceQuoteID" and version."CusQuoteVersion_IsSubmitted";
  select version."CusQuoteVersion_SnapshotJSON"#>'{quote,shipmentFacts,cargoLines}' into proposed_lines
    from public."CusQuote_Versions" version join public."CusQuote_Header" quote on quote."CusQuoteHeader_ID"=version."CusQuoteHeader_ID"
    where version."CusQuoteVersion_ID"=proposed_version_id and version."CusQuoteHeader_ID"=job_row."Job_SourceQuoteID"
      and version."CusQuoteVersion_IsSubmitted" and version."CusQuoteVersion_StatusCode"='accepted'
      and not quote."CusQuoteHeader_IsDeleted"
      and not exists(select 1 from public."CusQuote_Versions" newer
        where newer."CusQuoteHeader_ID"=version."CusQuoteHeader_ID" and newer."CusQuoteVersion_IsSubmitted"
          and newer."CusQuoteVersion_StatusCode"='accepted' and newer."CusQuoteVersion_Number">version."CusQuoteVersion_Number");
  if baseline_lines is null or proposed_lines is null then
    raise exception 'Cargo revision needs structured submitted versions from this Booking and its latest accepted Quote.' using errcode='22023'; end if;
  if selected_fields is null or jsonb_typeof(selected_fields)<>'array' or jsonb_array_length(selected_fields) not between 1 and 8000 then
    raise exception 'Choose cargo fields to review.' using errcode='22023'; end if;
  select count(distinct value) into selected_count from jsonb_array_elements(selected_fields) item where jsonb_typeof(value)='string';
  if selected_count<>jsonb_array_length(selected_fields) then raise exception 'Cargo selections must be unique field keys.' using errcode='22023'; end if;
  current_lines:=booking_api.current_source_cargo_lines(requested_job_id);
  current_map:=booking_api.cargo_comparison_map(current_lines); proposed_map:=quote_api.cargo_line_map(proposed_lines);
  observed_differences:=booking_api.cargo_revision_differences(baseline_lines,observed_booking_lines,proposed_lines);
  current_differences:=booking_api.cargo_revision_differences(baseline_lines,current_lines,proposed_lines);
  for selected in select value from jsonb_array_elements_text(selected_fields) loop
    select value into item from jsonb_array_elements(current_differences) where value->>'key'=selected;
    select value into observed_item from jsonb_array_elements(observed_differences) where value->>'key'=selected;
    if item is null then raise exception 'That cargo field is not changed by this Quote revision.' using errcode='22023'; end if;
    if observed_item is null or item->'bookingValue' is distinct from observed_item->'bookingValue'
      or item->>'operation' is distinct from observed_item->>'operation' then
      raise exception 'Booking cargo changed since it was reviewed. Refresh before applying.' using errcode='40001'; end if;
    line_id:=item->>'sourceLineId'; field_name:=item->>'field';
    target:=coalesce(plans#>array[line_id,'values'],current_map->line_id);
    if field_name='line' then target:=proposed_map->line_id;
    else target:=jsonb_set(target,array[field_name],coalesce(item->'newQuoteValue','null'::jsonb),true); end if;
    select "JobCargo_ID" into cargo_id from public."Job_Cargo" where "JobCargo_JobID"=requested_job_id
      and "JobCargo_SourceQuoteLineID"=line_id::uuid and not "JobCargo_IsDeleted";
    plans:=jsonb_set(plans,array[line_id],jsonb_build_object('sourceLineId',line_id,'bookingCargoId',cargo_id,
      'operation',item->>'operation','values',target),true);
  end loop;
  -- The plan is not execution. It carries complete current values for each
  -- selected line, so unselected Booking changes are retained on persistence.
  return jsonb_build_object('jobId',requested_job_id,'baselineVersionId',baseline_version_id,'proposedVersionId',proposed_version_id,
    'selectedFields',selected_fields,'changes',(select coalesce(jsonb_agg(value order by key),'[]'::jsonb) from jsonb_each(plans)));
end;
$$;


ALTER FUNCTION "booking_api"."plan_quote_cargo_revision"("requested_job_id" "uuid", "baseline_version_id" "uuid", "proposed_version_id" "uuid", "selected_fields" "jsonb", "observed_booking_lines" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."preserve_route_mode_references"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  from_mode text := booking_api.normalise_mode(old."JobRoute_ModeCode");
  to_mode text := booking_api.normalise_mode(new."JobRoute_ModeCode");
  before_refs jsonb;
  after_refs jsonb;
  review jsonb;
  reviewed boolean := false;
  company uuid;
begin
  before_refs := jsonb_build_object(
    'masterTransportReference',nullif(btrim(old."JobRoute_MasterTransportReference"),''),
    'houseTransportReference',nullif(btrim(old."JobRoute_HouseTransportReference"),''),
    'carrierBookingReference',nullif(btrim(old."JobRoute_CarrierBookingReference"),''),
    'transportMeansName',nullif(btrim(old."JobRoute_TransportMeansName"),''));
  review := coalesce(new."JobRoute_RouteJSON"->'modeChangeReview',new."JobRoute_RouteJSON"#>'{routeData,modeChangeReview}');

  if from_mode is distinct from to_mode then
    if review is not null then
      if jsonb_typeof(review) is distinct from 'object'
        or review->>'fromMode' is distinct from from_mode
        or review->>'toMode' is distinct from to_mode
        or review->'beforeReferences' is distinct from before_refs then
        raise exception 'This routing step changed since the mode review. Reload the Booking and review the mode change again.' using errcode='40001';
      end if;
      reviewed := true;
    end if;
    -- Reviewed manual changes start blank in the editor; explicitly re-entered
    -- values can be retained, including a deliberately reused identical value.
    -- Older and accepted-Quote paths must not inherit unchanged references.
    if not reviewed then
      if new."JobRoute_MasterTransportReference" is not distinct from old."JobRoute_MasterTransportReference" then new."JobRoute_MasterTransportReference":=null; end if;
      if new."JobRoute_HouseTransportReference" is not distinct from old."JobRoute_HouseTransportReference" then new."JobRoute_HouseTransportReference":=null; end if;
      if new."JobRoute_CarrierBookingReference" is not distinct from old."JobRoute_CarrierBookingReference" then new."JobRoute_CarrierBookingReference":=null; end if;
      if new."JobRoute_TransportMeansName" is not distinct from old."JobRoute_TransportMeansName" then new."JobRoute_TransportMeansName":=null; end if;
    end if;
  end if;

  after_refs := jsonb_build_object(
    'masterTransportReference',nullif(btrim(new."JobRoute_MasterTransportReference"),''),
    'houseTransportReference',nullif(btrim(new."JobRoute_HouseTransportReference"),''),
    'carrierBookingReference',nullif(btrim(new."JobRoute_CarrierBookingReference"),''),
    'transportMeansName',nullif(btrim(new."JobRoute_TransportMeansName"),''));
  if from_mode is not distinct from to_mode and before_refs is not distinct from after_refs and review is null then
    return new;
  end if;
  -- A review is one-use request evidence, never a permanent approval flag.
  new."JobRoute_RouteJSON" := (coalesce(new."JobRoute_RouteJSON",'{}'::jsonb)-'modeChangeReview') || after_refs;
  if jsonb_typeof(new."JobRoute_RouteJSON"->'routeData')='object' then
    new."JobRoute_RouteJSON" := jsonb_set(new."JobRoute_RouteJSON",'{routeData}',
      (new."JobRoute_RouteJSON"->'routeData'-'modeChangeReview') || after_refs);
  end if;

  if from_mode is distinct from to_mode or before_refs is distinct from after_refs then
    select office."Company_ID" into company from public."Job_Header" job
      join public."cmp_Offices" office on office."Office_ID"=coalesce(job."Job_OrgOfficeID",job."Job_OfficeID")
      where job."Job_ID"=new."Job_ID";
    if company is null then raise exception 'Routing history needs a valid Booking workspace.' using errcode='42501'; end if;
    insert into booking_api.events(company_id,job_id,event_type,summary,metadata,actor_user_id)
      values(company,new."Job_ID",
        case when from_mode is distinct from to_mode then 'route_mode_changed' else 'route_references_updated' end,
        case when from_mode is distinct from to_mode then format('Routing step %s mode changed from %s to %s; previous references retained in audit history.',new."JobRoute_OrderNo",from_mode,to_mode)
          else format('Routing step %s transport references updated.',new."JobRoute_OrderNo") end,
        jsonb_build_object('routeId',new."JobRoute_ID",'fromMode',from_mode,'toMode',to_mode,
          'beforeReferences',before_refs,'afterReferences',after_refs,'reviewed',reviewed,
          'previousTransport',jsonb_build_object('vessel',old."JobRoute_Vessel",'voyageNumber',old."JobRoute_VoyageNumber",
            'flightNumber',old."JobRoute_FlightNumber",'vehicleRegistration',old."JobRoute_VehicleRegistration",
            'trailerNumber',old."JobRoute_TrailerNumber",'railService',old."JobRoute_RailService")),new."JobRoute_UpdatedBy");
  end if;
  return new;
end;
$$;


ALTER FUNCTION "booking_api"."preserve_route_mode_references"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."projection_before_goods_value_20260905"("snapshot" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select booking_api.quote_sync_projection_before_cargo_lines_20260905(snapshot)
    ||case when snapshot#>'{quote,shipmentFacts,cargoLines}' is not null then
      jsonb_build_object('cargoLines',quote_api.normalise_cargo_lines(snapshot#>'{quote,shipmentFacts,cargoLines}',false)) else '{}'::jsonb end
$$;


ALTER FUNCTION "booking_api"."projection_before_goods_value_20260905"("snapshot" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."quote_container_rows"("snapshot" "jsonb", "source_code" "text" DEFAULT 'accepted_quote'::"text", "quote_version_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
declare
  payload jsonb;
  facts jsonb;
  cargo jsonb;
  requests jsonb;
  normalised_requests jsonb := '[]'::jsonb;
  result_rows jsonb := '[]'::jsonb;
  request_item jsonb;
  request_type text;
  request_quantity integer;
  request_index integer;
  unit_index integer;
  total_quantity integer := 0;
  summary_value text;
  summary_part text;
  summary_match text[];
  package_quantity text;
  package_type text;
  gross_weight text;
  volume_cbm text;
begin
  snapshot := coalesce(snapshot, '{}'::jsonb);
  payload := case when jsonb_typeof(snapshot->'quote') = 'object' then snapshot->'quote' else snapshot end;
  facts := case when jsonb_typeof(payload->'shipmentFacts') = 'object' then payload->'shipmentFacts' else payload end;
  cargo := case when jsonb_typeof(snapshot->'cargo') = 'object' then snapshot->'cargo' else '{}'::jsonb end;
  requests := case
    when jsonb_typeof(facts->'containerRequests') = 'array' then facts->'containerRequests'
    when jsonb_typeof(snapshot->'containerRequests') = 'array' then snapshot->'containerRequests'
    else '[]'::jsonb
  end;

  request_index := 0;
  for request_item in select item.value from jsonb_array_elements(requests) item loop
    request_type := nullif(btrim(request_item->>'type'), '');
    request_quantity := case
      when coalesce(request_item->>'quantity', '') ~ '^[0-9]+$' then (request_item->>'quantity')::integer
      else 0
    end;
    if request_type is not null and request_quantity > 0 then
      request_index := request_index + 1;
      total_quantity := total_quantity + request_quantity;
      if total_quantity > 100 then
        raise exception 'A quote cannot create more than 100 booking container lines.' using errcode = '22023';
      end if;
      normalised_requests := normalised_requests || jsonb_build_array(jsonb_build_object(
        'type', left(request_type, 40),
        'quantity', request_quantity,
        'requestIndex', request_index
      ));
    end if;
  end loop;

  if total_quantity = 0 then
    summary_value := nullif(btrim(coalesce(facts->>'container', facts->>'equipment', snapshot->>'equipment')), '');
    if summary_value is not null then
      for summary_part in select part from regexp_split_to_table(summary_value, '\s*;\s*') part loop
        summary_match := regexp_match(summary_part, '^\s*([0-9]+)\s*[xX×]\s*(.+?)\s*$');
        request_quantity := case when summary_match is null then 1 else summary_match[1]::integer end;
        request_type := left(nullif(btrim(case when summary_match is null then summary_part else summary_match[2] end), ''), 40);
        if request_type is not null and request_quantity > 0 then
          request_index := request_index + 1;
          total_quantity := total_quantity + request_quantity;
          if total_quantity > 100 then
            raise exception 'A quote cannot create more than 100 booking container lines.' using errcode = '22023';
          end if;
          normalised_requests := normalised_requests || jsonb_build_array(jsonb_build_object(
            'type', request_type,
            'quantity', request_quantity,
            'requestIndex', request_index
          ));
        end if;
      end loop;
    end if;
  end if;

  package_quantity := nullif(coalesce(cargo->>'packageQuantity', facts->>'packageQuantity', facts->>'pieces'), '');
  package_type := nullif(btrim(coalesce(cargo->>'packageType', facts->>'packageType')), '');
  gross_weight := nullif(coalesce(cargo->>'grossWeightKg', facts->>'grossWeightKg'), '');
  volume_cbm := nullif(coalesce(cargo->>'volumeCbm', facts->>'volumeCbm'), '');

  for request_item in select item.value from jsonb_array_elements(normalised_requests) item loop
    request_quantity := (request_item->>'quantity')::integer;
    for unit_index in 1..request_quantity loop
      result_rows := result_rows || jsonb_build_array(jsonb_strip_nulls(jsonb_build_object(
        'type', request_item->>'type',
        'equipmentKind', 'container',
        'status', 'planned',
        'packages', case when total_quantity = 1 then package_quantity end,
        'packageType', case when total_quantity = 1 then package_type end,
        'grossWeightKg', case when total_quantity = 1 then gross_weight end,
        'volumeCbm', case when total_quantity = 1 then volume_cbm end,
        'data', jsonb_strip_nulls(jsonb_build_object(
          'source', coalesce(nullif(btrim(source_code), ''), 'accepted_quote'),
          'quoteVersionId', quote_version_id,
          'requestIndex', (request_item->>'requestIndex')::integer,
          'unitIndex', unit_index,
          'requestedQuantity', request_quantity,
          'packageType', case when total_quantity = 1 then package_type end,
          'packages', case when total_quantity = 1 then package_quantity end,
          'volumeCbm', case when total_quantity = 1 then volume_cbm end
        ))
      )));
    end loop;
  end loop;

  return result_rows;
end;
$_$;


ALTER FUNCTION "booking_api"."quote_container_rows"("snapshot" "jsonb", "source_code" "text", "quote_version_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "booking_api"."quote_container_rows"("snapshot" "jsonb", "source_code" "text", "quote_version_id" "uuid") IS 'Expands structured quote container quantities into one booking row per physical container. Copies quote goods totals only when exactly one container was requested.';



CREATE OR REPLACE FUNCTION "booking_api"."quote_container_summary"("snapshot" "jsonb") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  with expanded as (
    select item.value->>'type' as type_code, item.ordinality
    from jsonb_array_elements(booking_api.quote_container_rows(snapshot, 'projection', null)) with ordinality item(value, ordinality)
  ), grouped as (
    select type_code, count(*) as quantity, min(ordinality) as first_position
    from expanded
    where nullif(btrim(type_code), '') is not null
    group by type_code
  )
  select string_agg(quantity::text || ' × ' || type_code, '; ' order by first_position)
  from grouped
$$;


ALTER FUNCTION "booking_api"."quote_container_summary"("snapshot" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."quote_readiness"("requested_quote_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare result jsonb; snapshot jsonb; facts jsonb; current_value jsonb; saved_value jsonb; missing jsonb;
begin
  result:=booking_api.readiness_before_goods_value_20260905(requested_quote_id);
  select "CusQuoteHeader_ShipmentFactsJSON" into facts from public."CusQuote_Header" where "CusQuoteHeader_ID"=requested_quote_id;
  select "CusQuoteVersion_SnapshotJSON" into snapshot from public."CusQuote_Versions" where "CusQuoteHeader_ID"=requested_quote_id
    order by "CusQuoteVersion_Number" desc limit 1;
  current_value:=booking_api.quote_shipment_value(jsonb_build_object('quote',jsonb_build_object('shipmentFacts',facts,'currency',snapshot#>'{quote,currency}')));
  saved_value:=booking_api.quote_shipment_value(snapshot);
  missing:=coalesce(result->'missing','[]'::jsonb);
  if current_value->>'invalidReason' is not null then
    missing:=missing||jsonb_build_array('Shipment goods value: '||(current_value->>'invalidReason'));
  elsif saved_value->>'invalidReason' is not null then
    missing:=missing||jsonb_build_array('Saved Quote goods value: '||(saved_value->>'invalidReason'));
  elsif current_value is distinct from saved_value then
    missing:=missing||jsonb_build_array('Save the current shipment goods value before sending');
  end if;
  return result||jsonb_build_object('missing',missing,'ready',coalesce((result->>'ready')::boolean,false) and jsonb_array_length(missing)=0);
end;
$$;


ALTER FUNCTION "booking_api"."quote_readiness"("requested_quote_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."quote_shipment_value"("snapshot" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare value jsonb:=jsonb_build_object('amount',snapshot#>'{quote,shipmentFacts,goodsValue}',
  'currency',coalesce(nullif(snapshot#>>'{quote,shipmentFacts,goodsValueCurrency}',''),snapshot#>>'{quote,currency}'));
begin
  return booking_api.normalise_shipment_value(value);
exception when invalid_parameter_value then
  return value||jsonb_build_object('invalidReason',sqlerrm);
end;
$$;


ALTER FUNCTION "booking_api"."quote_shipment_value"("snapshot" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."quote_sync_differences"("baseline" "jsonb", "booking" "jsonb", "proposed" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select coalesce(jsonb_agg(case
    when value->>'key'='routing' and booking_api.routing_mode_review_required(booking->'routing',proposed->'routing')
      then value || jsonb_build_object('requiresConfirmation',true,'warningCode','mode_change','recommendation','review',
        'reviewNote','The routing plan changes transport modes. Review each leg before applying; previous references remain in Booking audit history.')
    else value end order by ordinality),'[]'::jsonb)
  from jsonb_array_elements(booking_api.quote_sync_differences_before_route_mode_review_20260905(baseline,booking,proposed)) with ordinality
$$;


ALTER FUNCTION "booking_api"."quote_sync_differences"("baseline" "jsonb", "booking" "jsonb", "proposed" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."quote_sync_differences_before_cargo_lines_20260905"("baseline" "jsonb", "booking" "jsonb", "proposed" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  with comparison as (
    select
      (booking->'payer') is distinct from (baseline->'payer') as booking_changed,
      (booking->'payer') is distinct from (baseline->'payer')
        and (booking->'payer') is distinct from (proposed->'payer') as has_conflict
  )
  select booking_api.quote_sync_differences_before_payer_20260904(baseline, booking, proposed)
    || case when (proposed->'payer') is distinct from (baseline->'payer') then
      jsonb_build_array(jsonb_build_object(
        'key', 'payer',
        'label', 'Bill to / payer',
        'section', 'Parties',
        'previousQuoteValue', baseline->'payer',
        'bookingValue', booking->'payer',
        'newQuoteValue', proposed->'payer',
        'bookingChanged', booking_changed,
        'conflict', has_conflict,
        'requiresConfirmation', has_conflict,
        'warningCode', case when has_conflict then 'booking_changed' else null end,
        'recommendation', case when has_conflict then 'review' else 'apply' end
      ))
    else '[]'::jsonb end
  from comparison
$$;


ALTER FUNCTION "booking_api"."quote_sync_differences_before_cargo_lines_20260905"("baseline" "jsonb", "booking" "jsonb", "proposed" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."quote_sync_differences_before_payer_20260904"("baseline" "jsonb", "booking" "jsonb", "proposed" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  with route_context as (
    select greatest(
      coalesce(jsonb_array_length(case when jsonb_typeof(baseline->'routing')='array' then baseline->'routing' else '[]'::jsonb end),0),
      coalesce(jsonb_array_length(case when jsonb_typeof(proposed->'routing')='array' then proposed->'routing' else '[]'::jsonb end),0)
    )>1
      or coalesce(baseline->'routingIsExplicit'='true'::jsonb, false)
      or coalesce(proposed->'routingIsExplicit'='true'::jsonb, false) as has_multi_leg_plan
  ), fields(order_no, field_key, label, section_name) as (values
    (1,'direction','Direction','Job data'), (2,'mode','Mode','Job data'),
    (3,'shipmentType','Shipment type','Service'), (4,'serviceLevel','Service level','Service'),
    (5,'carrier','Carrier','Carrier & supplier'), (6,'supplier','Supplier','Carrier & supplier'),
    (7,'origin','Origin','Route & service'), (8,'destination','Destination','Route & service'),
    (9,'collectionAddress','Collection address','Route & service'), (10,'deliveryAddress','Delivery address','Route & service'),
    (11,'incoterm','Incoterm','Route & service'), (12,'incotermLocation','Named place','Route & service'),
    (13,'estimatedDeparture','ETD','Route & service'), (14,'estimatedArrival','ETA','Route & service'),
    (15,'routing','Routing plan','Route & service'),
    (16,'shipper','Shipper','Parties'), (17,'consignee','Consignee','Parties'),
    (18,'cargo','Goods','Goods'), (19,'equipment','Equipment / container','Goods'),
    (20,'customerNotes','Customer notes','Customer terms'), (21,'terms','Terms and conditions','Customer terms'),
    (22,'subjectToTerms','Subject to terms','Customer terms'), (23,'charges','Quote charges','Financials')
  ), comparison as (
    select
      fields.*,
      (booking->field_key) is distinct from (baseline->field_key) as booking_changed,
      (booking->field_key) is distinct from (baseline->field_key)
        and (booking->field_key) is distinct from (proposed->field_key) as has_conflict
    from fields cross join route_context
    where (proposed->field_key) is distinct from (baseline->field_key)
      and (field_key<>'routing' or has_multi_leg_plan)
      and not (
        has_multi_leg_plan
        and field_key in ('serviceLevel','carrier','origin','destination','estimatedDeparture','estimatedArrival')
      )
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'key', field_key,
    'label', label,
    'section', section_name,
    'previousQuoteValue', baseline->field_key,
    'bookingValue', booking->field_key,
    'newQuoteValue', proposed->field_key,
    'bookingChanged', booking_changed,
    'conflict', has_conflict,
    'requiresConfirmation', field_key='mode' or has_conflict,
    'warningCode', case
      when field_key='mode' then 'mode_change'
      when has_conflict then 'booking_changed'
      else null
    end,
    'recommendation', case when field_key='mode' or has_conflict then 'review' else 'apply' end
  ) order by order_no), '[]'::jsonb)
  from comparison
$$;


ALTER FUNCTION "booking_api"."quote_sync_differences_before_payer_20260904"("baseline" "jsonb", "booking" "jsonb", "proposed" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."quote_sync_differences_before_route_mode_review_20260905"("baseline" "jsonb", "booking" "jsonb", "proposed" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare result jsonb;
begin
  result:=booking_api.differences_before_goods_value_20260905(
    baseline #- '{cargo,goodsValue}' #- '{cargo,goodsValueCurrency}',
    booking #- '{cargo,goodsValue}' #- '{cargo,goodsValueCurrency}',
    proposed #- '{cargo,goodsValue}' #- '{cargo,goodsValueCurrency}');
  if baseline->'shipmentGoodsValue' is distinct from proposed->'shipmentGoodsValue' then
    result:=result||jsonb_build_array(jsonb_build_object('key','shipmentGoodsValue','label','Shipment goods value','section','Goods',
      'previousQuoteValue',baseline->'shipmentGoodsValue','bookingValue',booking->'shipmentGoodsValue','newQuoteValue',proposed->'shipmentGoodsValue',
      'conflict',booking->'shipmentGoodsValue' is distinct from baseline->'shipmentGoodsValue',
      'requiresConfirmation',true,'recommendation','review',
      'reviewNote','Changes the shipment total only. Existing cargo-line values and currencies are retained; review their allocations separately.')
      ||case when proposed#>>'{shipmentGoodsValue,invalidReason}' is not null then jsonb_build_object('blockedReason',proposed#>>'{shipmentGoodsValue,invalidReason}') else '{}'::jsonb end);
  end if;
  return result;
end;
$$;


