CREATE OR REPLACE FUNCTION "booking_api"."readiness_before_goods_value_20260905"("requested_quote_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  quote_row record;
  facts jsonb;
  routing_legs jsonb;
  version_facts jsonb;
  missing text[] := '{}'::text[];
  warnings text[] := '{}'::text[];
  incoterm_value text;
  incoterm_code text;
  incoterm_not_supplied boolean;
  mode_value text;
  shipment_value text;
  service_value text;
  has_customs boolean;
  is_containerised boolean;
begin
  select quote.* into quote_row
  from public."CusQuote_Header" quote
  where quote."CusQuoteHeader_ID" = requested_quote_id
    and not quote."CusQuoteHeader_IsDeleted";
  if not found then
    raise exception 'That quote could not be found.' using errcode = 'P0002';
  end if;

  facts := coalesce(quote_row."CusQuoteHeader_ShipmentFactsJSON", '{}'::jsonb);
  routing_legs := case when jsonb_typeof(facts->'routingLegs')='array' then facts->'routingLegs' else '[]'::jsonb end;
  incoterm_value := upper(btrim(coalesce(quote_row."CusQuoteHeader_Incoterm", '')));
  incoterm_code := split_part(incoterm_value, ' ', 1);
  incoterm_not_supplied := incoterm_value in ('N/A', 'NA', 'NOT SUPPLIED', 'NOT APPLICABLE', 'NOT SUPPLIED / NOT APPLICABLE');
  mode_value := lower(coalesce(quote_row."CusQuoteHeader_ModeCode", ''));
  shipment_value := lower(coalesce(quote_row."CusQuoteHeader_ShipmentTypeCode", ''));
  service_value := lower(coalesce(quote_row."CusQuoteHeader_ServiceLevel", ''));
  has_customs := lower(coalesce(facts->>'customsIncluded', 'no')) in ('true', 'yes', '1');
  is_containerised := shipment_value like '%fcl%' or shipment_value like '%container%';

  if quote_row."CusQuoteHeader_CustomerID" is null then missing := array_append(missing, 'Customer'); end if;
  -- Delivery validates the selected saved/manual recipient; a saved contact email is not a shipment requirement.
  if nullif(btrim(quote_row."CusQuoteHeader_LoadingPoint"), '') is null then missing := array_append(missing, 'Origin / loading point'); end if;
  if nullif(btrim(quote_row."CusQuoteHeader_DischargePoint"), '') is null then missing := array_append(missing, 'Destination / discharge point'); end if;
  if quote_row."CusQuoteHeader_CreatedDate" is null then missing := array_append(missing, 'Quote date'); end if;
  if quote_row."CusQuoteHeader_ValidFrom" is null then missing := array_append(missing, 'Validity start'); end if;
  if quote_row."CusQuoteHeader_ValidTo" is null then missing := array_append(missing, 'Validity end'); end if;
  if quote_row."CusQuoteHeader_ValidFrom" is not null and quote_row."CusQuoteHeader_ValidTo" is not null
     and quote_row."CusQuoteHeader_ValidTo" < quote_row."CusQuoteHeader_ValidFrom" then
    missing := array_append(missing, 'A validity end on or after the start');
  end if;
  if mode_value = '' then missing := array_append(missing, 'Transport mode'); end if;
  if shipment_value = '' then missing := array_append(missing, 'Shipment / equipment type'); end if;
  if nullif(btrim(coalesce(facts->>'knownCargo', facts->>'commodity')), '') is null then missing := array_append(missing, 'Goods description'); end if;

  if incoterm_value = '' then
    missing := array_append(missing, 'Incoterm or Not supplied / not applicable');
  elsif incoterm_not_supplied then
    if lower(coalesce(facts->>'collectionRequired', '')) not in ('true', 'false', 'yes', 'no', '1', '0') then
      missing := array_append(missing, 'Collection scope');
    end if;
    if lower(coalesce(facts->>'deliveryRequired', '')) not in ('true', 'false', 'yes', 'no', '1', '0') then
      missing := array_append(missing, 'Delivery scope');
    end if;
    if lower(coalesce(facts->>'customsIncluded', '')) not in ('true', 'false', 'yes', 'no', '1', '0') then
      missing := array_append(missing, 'Customs clearance scope');
    end if;
  elsif not incoterm_not_supplied
        and incoterm_code not in ('EXW', 'FCA', 'CPT', 'CIP', 'DAP', 'DPU', 'DDP', 'FAS', 'FOB', 'CFR', 'CIF') then
    missing := array_append(missing, 'A supported Incoterm or Not supplied / not applicable');
  elsif incoterm_code = 'EXW'
        and coalesce(
          nullif(btrim(facts->>'namedPlace'), ''),
          nullif(btrim(quote_row."CusQuoteHeader_CollectionAddress"), ''),
          nullif(btrim(facts->>'shipperAddress'), '')
        ) is null then
    missing := array_append(missing, 'EXW named place or collection address');
  elsif incoterm_code in ('DAP', 'DPU', 'DDP')
        and coalesce(
          nullif(btrim(facts->>'namedPlace'), ''),
          nullif(btrim(quote_row."CusQuoteHeader_DeliveryAddress"), ''),
          nullif(btrim(facts->>'consigneeAddress'), '')
        ) is null then
    missing := array_append(missing, 'Incoterm named place or delivery address');
  elsif incoterm_code in ('FCA', 'CPT', 'CIP', 'FAS', 'FOB', 'CFR', 'CIF')
        and nullif(btrim(facts->>'namedPlace'), '') is null then
    missing := array_append(missing, 'Incoterm named place / port');
  end if;

  -- N/A is an explicit commercial-scope decision. The included/not-included
  -- answers remain visible on the quote, but do not silently turn the Incoterm
  -- named-place field back into a send blocker.
  if not incoterm_not_supplied
     and (lower(coalesce(facts->>'collectionRequired', 'false')) in ('true','yes','1')
     or service_value like '%door%') then
    if coalesce(
      nullif(btrim(quote_row."CusQuoteHeader_CollectionAddress"), ''),
      nullif(btrim(facts->>'namedPlace'), ''),
      nullif(btrim(facts->>'shipperAddress'), '')
    ) is null then
      missing := array_append(missing, 'Collection address or Incoterm named place');
    end if;
  end if;
  if not incoterm_not_supplied
     and (lower(coalesce(facts->>'deliveryRequired', 'false')) in ('true','yes','1')
     or service_value like '%door%') then
    if coalesce(
      nullif(btrim(quote_row."CusQuoteHeader_DeliveryAddress"), ''),
      nullif(btrim(facts->>'namedPlace'), ''),
      nullif(btrim(facts->>'consigneeAddress'), '')
    ) is null then
      missing := array_append(missing, 'Delivery address or Incoterm named place');
    end if;
  end if;

  if jsonb_array_length(routing_legs)>1 and exists (
    select 1 from jsonb_array_elements(routing_legs) item(leg)
    where nullif(btrim(coalesce(leg#>>'{origin,unlocode}',leg#>>'{origin,place}')),'') is null
       or nullif(btrim(coalesce(leg#>>'{destination,unlocode}',leg#>>'{destination,place}')),'') is null
       or nullif(btrim(leg->>'mode'),'') is null
  ) then
    missing := array_append(missing, 'Complete every routing leg');
  end if;

  if mode_value in ('sea','ocean') and is_containerised
     and nullif(btrim(facts->>'container'), '') is null then
    missing := array_append(missing, 'Container details');
  end if;
  if not is_containerised and nullif(btrim(facts->>'packageQuantity'), '') is null then
    missing := array_append(missing, 'Package / piece quantity');
  end if;
  if not is_containerised and nullif(btrim(facts->>'packageType'), '') is null then
    missing := array_append(missing, 'Package type');
  end if;
  if mode_value in ('air','courier')
     and nullif(btrim(coalesce(facts->>'chargeableWeightKg', facts->>'grossWeightKg')), '') is null then
    missing := array_append(missing, 'Chargeable or gross weight');
  end if;
  if mode_value in ('sea','road','rail')
     and not is_containerised
     and nullif(btrim(coalesce(facts->>'volumeCbm', facts->>'grossWeightKg')), '') is null then
    missing := array_append(missing, 'Volume or gross weight');
  end if;
  if has_customs and (
    case when coalesce(facts->>'entries', '') ~ '^\d+$' then (facts->>'entries')::integer else 0 end
  ) < 1 then
    missing := array_append(missing, 'Customs entry-line count');
  end if;
  if not exists (
    select 1 from public."CusQuote_Lines" line
    where line."CusQuoteHeader_ID" = requested_quote_id
      and line."CusQuoteLine_ShowToCustomer"
      and coalesce(line."CusQuoteLine_RevenueAmountLocal", 0) <> 0
  ) then missing := array_append(missing, 'At least one customer charge'); end if;


  -- Both header and version must refer to the same saved cargo. Comparing the
  -- normalised values permits benign numeric/country formatting differences.
  select version."CusQuoteVersion_SnapshotJSON" #> '{quote,shipmentFacts}'
    into version_facts from public."CusQuote_Versions" version
    where version."CusQuoteHeader_ID"=requested_quote_id and version."CusQuoteVersion_IsCurrent";
  if facts ? 'cargoLines' or coalesce(version_facts ? 'cargoLines',false) then
    select coalesce(array_agg(value order by position),'{}'::text[]) into missing
      from unnest(missing) with ordinality as item(value,position)
      where value <> all(array['Goods description','Package / piece quantity','Package type',
        'Chargeable or gross weight','Volume or gross weight']);
    if not facts ? 'cargoLines' or not coalesce(version_facts ? 'cargoLines',false) then
      missing := array_append(missing,'Save cargo lines to the current quote version before sending');
    else
      begin
        if quote_api.normalise_cargo_lines(facts->'cargoLines',false)
          is distinct from quote_api.normalise_cargo_lines(version_facts->'cargoLines',false) then
          missing := array_append(missing,'Save cargo changes to the current quote version before sending');
        end if;
      exception when invalid_parameter_value then
        missing := array_append(missing,'Correct and save cargo line data before sending');
      end;
    end if;
    missing := missing || quote_api.cargo_issue_missing(
      coalesce(version_facts->'cargoLines',facts->'cargoLines'),mode_value,shipment_value);
    missing := missing || quote_api.cargo_booking_missing(coalesce(version_facts->'cargoLines',facts->'cargoLines'));
  end if;
  return jsonb_build_object(
    'ready', cardinality(missing) = 0,
    'missing', to_jsonb(missing),
    'warnings', to_jsonb(warnings)
  );
end;
$_$;


ALTER FUNCTION "booking_api"."readiness_before_goods_value_20260905"("requested_quote_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."refreshed_cargo_review"("requested_review_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare review_row record; baseline jsonb; proposed jsonb; booking jsonb; differences jsonb; token text;
begin
  select * into strict review_row from booking_api.quote_sync_reviews where review_id=requested_review_id;
  select booking_api.quote_sync_projection("CusQuoteVersion_SnapshotJSON") into baseline from public."CusQuote_Versions" where "CusQuoteVersion_ID"=review_row.applied_version_id;
  select booking_api.quote_sync_projection("CusQuoteVersion_SnapshotJSON") into strict proposed from public."CusQuote_Versions" where "CusQuoteVersion_ID"=review_row.proposed_version_id;
  baseline:=coalesce(baseline,review_row.baseline_snapshot);
  booking:=booking_api.current_quote_sync_projection(review_row.job_id);
  differences:=booking_api.quote_sync_differences(baseline,booking,proposed);
  -- Keep immutable decision receipts visible after partial application, even
  -- when a later operational edit changes the remaining comparison's shape.
  select coalesce(jsonb_agg(value order by value->>'key'),'[]') into differences from (
    select value from jsonb_array_elements(review_row.differences) where review_row.applied_fields ? (value->>'key')
    union all select value from jsonb_array_elements(differences) where not review_row.applied_fields ? (value->>'key')
  ) items;
  token:=encode(sha256(convert_to(jsonb_build_object('reviewId',requested_review_id,'booking',booking,
    'differences',differences,'appliedFields',review_row.applied_fields)::text,'UTF8')),'hex');
  return jsonb_build_object('differences',differences,'reviewToken',token,'booking',booking,'baseline',baseline,'proposed',proposed);
end;
$$;


ALTER FUNCTION "booking_api"."refreshed_cargo_review"("requested_review_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."release_provisional_quote_charges"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare charge jsonb; charge_number integer:=0;job_id uuid:=new."Job_ID";actor_user_id uuid:=new."Job_UpdatedBy";payload jsonb;
begin
 if lower(old."Job_Status") not in ('draft','provisional') or booking_api.lifecycle_label(new."Job_Status") <> 'In progress'
   or new."Job_SourceQuoteID" is null or coalesce((new."Job_SourceSnapshotJSON"->>'provisionalChargesReleased')::boolean,false) then return new;end if;
 -- Existing historical charges are preserved, never copied a second time.
 if exists(select 1 from public."Job_Costing_Lines" where "Job_ID"=job_id) then return new;end if;
 payload:=coalesce(new."Job_SourceSnapshotJSON"#>'{acceptedSnapshot,quote}','{}'::jsonb);
 for charge in select value from jsonb_array_elements(coalesce(payload->'charges','[]'::jsonb)) loop
  charge_number:=charge_number+1;
    insert into public."Job_Costing_Lines" (
      "Job_ID", "JobCostingLine_Number", "JobCostingLine_SupplierID", "JobCostingLine_Description", "JobCostingLine_InternalNotes",
      "JobCostingLine_CustomerNotes", "JobCostingLine_CostROE", "JobCostingLine_CostAmountCurrency", "JobCostingLine_CostAmountLocal",
      "JobCostingLine_RevenueROE", "JobCostingLine_RevenueAmountCurrency", "JobCostingLine_RevenueAmountLocal",
      "JobCostingLine_ShowToCustomer", "JobCostingLine_CreatedBy", "JobCostingLine_UpdatedBy"
    ) values (
      job_id, charge_number, nullif(charge->>'supplierId', '')::uuid, left(coalesce(nullif(btrim(charge->>'description'), ''), 'Charge'), 240),
      nullif(charge->>'internalNotes', ''), nullif(charge->>'customerNotes', ''), greatest(coalesce(nullif(charge->>'costRoe', '')::numeric, 1), 0.00001),
      coalesce(nullif(charge->>'costAmount', '')::numeric, 0), coalesce(nullif(charge->>'costLocal', '')::numeric, 0),
      greatest(coalesce(nullif(charge->>'sellRoe', '')::numeric, 1), 0.00001), coalesce(nullif(charge->>'sellAmount', '')::numeric, 0),
      coalesce(nullif(charge->>'sellLocal', '')::numeric, 0), coalesce((charge->>'showToCustomer')::boolean, true), actor_user_id, actor_user_id
    );
 end loop;
 update public."Job_Header" set "Job_SourceSnapshotJSON"=coalesce("Job_SourceSnapshotJSON",'{}'::jsonb)||'{"provisionalChargesReleased":true}'::jsonb where "Job_ID"=job_id;
 return new;
end $$;


ALTER FUNCTION "booking_api"."release_provisional_quote_charges"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."reopen_booking"("caller_auth_user_id" "uuid", "requested_job_id" "uuid", "requested_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare app_user record; job_row record;
begin
  if caller_auth_user_id is null or not booking_api.has_permission(caller_auth_user_id, 'Bookings.Write') then
    raise exception 'Booking reopening is not authorised.' using errcode = '42501';
  end if;
  if nullif(btrim(requested_reason), '') is null then raise exception 'Explain why this booking is being reopened.' using errcode = '22023'; end if;
  select actor."User_ID", actor."Company_ID" into strict app_user from public."cmp_Users" actor
  where actor."Auth_User_ID" = caller_auth_user_id and actor."User_AccessStatus" = 'active';
  select job.* into job_row from public."Job_Header" job
  join public."cmp_Offices" office on office."Office_ID" = coalesce(job."Job_OrgOfficeID", job."Job_OfficeID")
  where job."Job_ID" = requested_job_id and office."Company_ID" = app_user."Company_ID" and not job."Job_IsDeleted" for update;
  if not found then raise exception 'That booking is outside this workspace.' using errcode = '42501'; end if;
  if job_row."Job_InvoiceStatus" in ('raised','paid') then
    raise exception 'This booking has an issued invoice. Reverse or cancel that invoice before reopening the operational job.' using errcode = '22023';
  end if;
  update public."Job_Header" set
    "Job_Status" = 'open', "Job_ClosedDate" = null, "Job_InvoiceStatus" = 'not_raised',
    "Job_InvoiceReadyAt" = null, "Job_CompletedAt" = null, "Job_CompletedBy" = null,
    "Job_ReopenedAt" = now(), "Job_UpdatedAt" = now(), "Job_UpdatedBy" = app_user."User_ID"
  where "Job_ID" = requested_job_id;
  insert into booking_api.events (company_id, job_id, event_type, summary, metadata, actor_user_id)
  values (app_user."Company_ID", requested_job_id, 'reopened', 'Booking reopened for operational changes.', jsonb_build_object('reason', btrim(requested_reason)), app_user."User_ID");
  return booking_api.operational_workspace(caller_auth_user_id, job_row."Job_BookingReference");
exception when no_data_found or too_many_rows then raise exception 'Your workspace identity is incomplete.' using errcode = '42501';
end;
$$;


ALTER FUNCTION "booking_api"."reopen_booking"("caller_auth_user_id" "uuid", "requested_job_id" "uuid", "requested_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."replace_cargo_allocations"("caller_auth_user_id" "uuid", "requested_job_id" "uuid", "payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare before_value jsonb;after_value jsonb;result jsonb;company uuid;reference text;
begin
  perform booking_api.cargo_allocation_state(caller_auth_user_id,requested_job_id);
  select o."Company_ID",j."Job_BookingReference" into company,reference from public."Job_Header" j
    join public."cmp_Offices" o on o."Office_ID"=coalesce(j."Job_OrgOfficeID",j."Job_OfficeID")
    where j."Job_ID"=requested_job_id for update of j;
  before_value:=booking_api.allocation_review_values(requested_job_id)->'allocations';
  result:=booking_api.replace_cargo_allocations_before_watches_20260906(caller_auth_user_id,requested_job_id,payload);
  after_value:=booking_api.allocation_review_values(requested_job_id)->'allocations';
  if before_value is distinct from after_value and exists(select 1 from public."AI_DexterWatches" w
    where w."AIDexterWatch_CompanyID"=company and w."AIDexterWatch_CapabilityCode"='booking_allocations'
      and w."AIDexterWatch_TargetID"=requested_job_id and w."AIDexterWatch_StatusCode"='active') then
    insert into public."AI_DexterWatchSignals"("AIDexterWatchSignal_CompanyID","AIDexterWatchSignal_CapabilityCode",
      "AIDexterWatchSignal_SourceTable","AIDexterWatchSignal_SourceID","AIDexterWatchSignal_OldJSON","AIDexterWatchSignal_NewJSON")
    values(company,'booking_allocations','booking_api.cargo_equipment_allocations',requested_job_id,
      jsonb_build_object('allocations',before_value),jsonb_build_object('allocations',after_value,'bookingReference',reference,
        'bookingId',requested_job_id,'sourceUrl','/bookings/'||lower(reference)));
  end if;
  return result;
end $$;


ALTER FUNCTION "booking_api"."replace_cargo_allocations"("caller_auth_user_id" "uuid", "requested_job_id" "uuid", "payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."replace_cargo_allocations_before_watches_20260906"("caller_auth_user_id" "uuid", "requested_job_id" "uuid", "payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare actor record; job_row public."Job_Header"; line jsonb; lines jsonb:='[]'; key text; raw text; amount numeric;
  item_id uuid; cargo uuid; equipment uuid; route uuid; old_item booking_api.cargo_equipment_allocations;
  retained uuid[]:='{}'; changed boolean:=false; did_change boolean; field_scale integer;
begin
  if caller_auth_user_id is null or not booking_api.has_permission(caller_auth_user_id,'Bookings.Read')
    or not booking_api.has_permission(caller_auth_user_id,'Bookings.Write') then
    raise exception 'Booking changes are not authorised.' using errcode='42501';end if;
  if jsonb_typeof(payload) is distinct from 'object' or exists(select 1 from jsonb_object_keys(payload) k where k not in ('expectedUpdatedAt','allocations'))
    or jsonb_typeof(payload->'allocations') is distinct from 'array' or jsonb_array_length(payload->'allocations')>1000
    or jsonb_typeof(payload->'expectedUpdatedAt') is distinct from 'string' then
    raise exception 'Provide the saved Booking timestamp and cargo allocations.' using errcode='22023';end if;
  select "User_ID","Company_ID" into actor from public."cmp_Users"
    where "Auth_User_ID"=caller_auth_user_id and "User_AccessStatus"='active';
  select job.* into job_row from public."Job_Header" job
    join public."cmp_Offices" office on office."Office_ID"=coalesce(job."Job_OrgOfficeID",job."Job_OfficeID")
    where job."Job_ID"=requested_job_id and office."Company_ID"=actor."Company_ID" and not job."Job_IsDeleted" for update of job;
  if not found then raise exception 'That booking is outside this workspace.' using errcode='42501';end if;
  if (payload->>'expectedUpdatedAt')::timestamptz is distinct from job_row."Job_UpdatedAt" then
    raise exception 'Booking changed. Reload before saving cargo allocations.' using errcode='40001';end if;
  for line in select value from jsonb_array_elements(payload->'allocations') loop
    if jsonb_typeof(line) is distinct from 'object' or exists(select 1 from jsonb_object_keys(line) k
      where k not in ('id','cargoId','containerId','routeId','packageQuantity','grossWeightKg','volumeCbm','notes')) then
      raise exception 'Cargo allocation contains unsupported fields.' using errcode='22023';end if;
    -- Stable client-generated UUIDs make the reviewed identity unambiguous.
    foreach key in array array['id','cargoId','containerId','routeId'] loop
      if key='routeId' and (not line ? key or line->key='null'::jsonb) then continue;end if;
      if jsonb_typeof(line->key) is distinct from 'string' or (line->>key) !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        or (line->>key)::uuid='00000000-0000-0000-0000-000000000000'::uuid then
        raise exception 'Choose a saved cargo line, equipment and optional routing leg.' using errcode='22023';end if;
    end loop;
    item_id:=(line->>'id')::uuid; cargo:=(line->>'cargoId')::uuid; equipment:=(line->>'containerId')::uuid; route:=(line->>'routeId')::uuid;
    if item_id=any(retained) then raise exception 'Each cargo allocation needs a distinct identity.' using errcode='22023';end if;
    retained:=array_append(retained,item_id);
    select * into old_item from booking_api.cargo_equipment_allocations where id=item_id;
    if found and (old_item.job_id<>requested_job_id or old_item.is_deleted) then
      raise exception 'That cargo allocation is unavailable in this Booking.' using errcode='42501';end if;
    if not exists(select 1 from public."Job_Cargo" where "JobCargo_ID"=cargo and "JobCargo_JobID"=requested_job_id and not "JobCargo_IsDeleted")
      or not exists(select 1 from public."Job_Containers" where "JobContainers_ID"=equipment and "Job_ID"=requested_job_id and not "JobContainer_IsDeleted")
      or (route is not null and not exists(select 1 from public."Job_Routing" where "JobRoute_ID"=route and "Job_ID"=requested_job_id)) then
      raise exception 'Choose cargo, equipment and routing from this Booking.' using errcode='42501';end if;
    foreach key in array array['packageQuantity','grossWeightKg','volumeCbm'] loop
      if line ? key and jsonb_typeof(line->key) not in ('string','null') then
        raise exception 'Allocation quantities must use exact decimal text.' using errcode='22023';end if;
      raw:=nullif(btrim(line->>key),'');
      if raw is null then line:=jsonb_set(line,array[key],'null');continue;end if;
      if length(raw)>64 or raw !~ '^[0-9]+([.][0-9]+)?$' then
        raise exception 'Enter a non-negative allocation quantity.' using errcode='22023';end if;
      amount:=raw::numeric; field_scale:=case key when 'grossWeightKg' then 2 else 6 end;
      if amount<>round(amount,field_scale) or amount>=power(10::numeric,18-field_scale) then
        raise exception 'Allocation quantity exceeds the supported range or precision.' using errcode='22023';end if;
      line:=jsonb_set(line,array[key],to_jsonb(amount::text));
    end loop;
    if line ? 'notes' and jsonb_typeof(line->'notes') not in ('string','null') then
      raise exception 'Allocation notes must be text.' using errcode='22023';end if;
    if length(line->>'notes')>2000 then raise exception 'Allocation notes must be 2000 characters or fewer.' using errcode='22023';end if;
    lines:=lines||jsonb_build_array(line);
  end loop;
  if exists(select 1 from jsonb_array_elements(lines) a group by (a->>'cargoId')::uuid,(a->>'containerId')::uuid,(a->>'routeId')::uuid having count(*)>1) then
    raise exception 'Use one allocation per cargo line, equipment and routing scope.' using errcode='22023';end if;
  update booking_api.cargo_equipment_allocations set is_deleted=true,updated_by=actor."User_ID",updated_at=clock_timestamp()
    where job_id=requested_job_id and not is_deleted and not(id=any(retained));
  changed:=found;
  for line in select value from jsonb_array_elements(lines) loop
    insert into booking_api.cargo_equipment_allocations(id,job_id,cargo_id,container_id,route_id,package_quantity,gross_weight_kg,volume_cbm,notes,created_by,updated_by)
      values((line->>'id')::uuid,requested_job_id,(line->>'cargoId')::uuid,(line->>'containerId')::uuid,(line->>'routeId')::uuid,
        (line->>'packageQuantity')::numeric,(line->>'grossWeightKg')::numeric,(line->>'volumeCbm')::numeric,nullif(btrim(line->>'notes'),''),actor."User_ID",actor."User_ID")
      on conflict (id) do update set cargo_id=excluded.cargo_id,container_id=excluded.container_id,route_id=excluded.route_id,
        package_quantity=excluded.package_quantity,gross_weight_kg=excluded.gross_weight_kg,volume_cbm=excluded.volume_cbm,
        notes=excluded.notes,updated_by=excluded.updated_by,updated_at=clock_timestamp()
      where cargo_equipment_allocations.job_id=requested_job_id and not cargo_equipment_allocations.is_deleted
        and (cargo_equipment_allocations.cargo_id,cargo_equipment_allocations.container_id,cargo_equipment_allocations.route_id,
        cargo_equipment_allocations.package_quantity,cargo_equipment_allocations.gross_weight_kg,cargo_equipment_allocations.volume_cbm,cargo_equipment_allocations.notes)
        is distinct from (excluded.cargo_id,excluded.container_id,excluded.route_id,excluded.package_quantity,excluded.gross_weight_kg,excluded.volume_cbm,excluded.notes);
    did_change:=found;changed:=changed or did_change;
    if not exists(select 1 from booking_api.cargo_equipment_allocations where id=(line->>'id')::uuid and job_id=requested_job_id and not is_deleted) then
      raise exception 'That cargo allocation is unavailable in this Booking.' using errcode='42501';end if;
  end loop;
  perform booking_api.assert_cargo_allocations(requested_job_id);
  if changed then update public."Job_Header" set "Job_UpdatedAt"=clock_timestamp(),"Job_UpdatedBy"=actor."User_ID" where "Job_ID"=requested_job_id;end if;
  return booking_api.cargo_allocation_state(caller_auth_user_id,requested_job_id)||jsonb_build_object('changed',changed);
end $_$;


ALTER FUNCTION "booking_api"."replace_cargo_allocations_before_watches_20260906"("caller_auth_user_id" "uuid", "requested_job_id" "uuid", "payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."replace_quote_containers"("requested_job_id" "uuid", "actor_user_id" "uuid", "snapshot" "jsonb", "source_code" "text", "quote_version_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  rows_value jsonb;
  line jsonb;
  inserted_count integer := 0;
begin
  rows_value := booking_api.quote_container_rows(snapshot, source_code, quote_version_id);

  update public."Job_Containers"
  set "JobContainer_IsDeleted" = true,
      "JobContainer_UpdatedAt" = now(),
      "JobContainer_UpdatedBy" = actor_user_id
  where "Job_ID" = requested_job_id
    and not "JobContainer_IsDeleted";

  for line in select item.value from jsonb_array_elements(rows_value) item loop
    insert into public."Job_Containers" (
      "Job_ID", "JobContainer_Number", "JobContainer_TypeCodeSnapshot", "JobContainer_EquipmentKind",
      "JobContainer_Status", "JobContainer_GrossKilos", "JobContainer_Notes", "JobContainer_JSON", "JobContainer_UpdatedBy"
    ) values (
      requested_job_id,
      left(nullif(btrim(line->>'number'), ''), 50),
      left(nullif(btrim(line->>'type'), ''), 40),
      coalesce(left(nullif(btrim(line->>'equipmentKind'), ''), 40), 'container'),
      coalesce(left(nullif(btrim(line->>'status'), ''), 40), 'planned'),
      nullif(line->>'grossWeightKg', '')::numeric,
      nullif(btrim(line->>'notes'), ''),
      line,
      actor_user_id
    );
    inserted_count := inserted_count + 1;
  end loop;

  return inserted_count;
end;
$$;


ALTER FUNCTION "booking_api"."replace_quote_containers"("requested_job_id" "uuid", "actor_user_id" "uuid", "snapshot" "jsonb", "source_code" "text", "quote_version_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "booking_api"."replace_quote_containers"("requested_job_id" "uuid", "actor_user_id" "uuid", "snapshot" "jsonb", "source_code" "text", "quote_version_id" "uuid") IS 'Audit-preserving replacement of active booking container placeholders from an accepted quote snapshot.';



CREATE OR REPLACE FUNCTION "booking_api"."require_financial_booking"("job_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare status text;
begin
 if job_id is null then return;end if;
 -- Serialises finance capture with a concurrent return to Provisional.
 select "Job_Status" into status from public."Job_Header" where "Job_ID"=job_id for update;
 if not found then raise exception 'Choose an existing booking.' using errcode='22023';end if;
 if lower(status) in ('draft','provisional') then
  raise exception 'Provisional bookings cannot have financial records. Move the booking to In progress first.' using errcode='22023';end if;
end $$;


ALTER FUNCTION "booking_api"."require_financial_booking"("job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."resolve_customs_department"("workspace_company_id" "uuid", "requested_office_id" "uuid", "actor_user_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  department_id_value uuid;
begin
  department_id_value := booking_api.find_customs_department(workspace_company_id, requested_office_id);
  if department_id_value is null then
    raise exception 'Configure one Customs department for this booking office before sending the job.' using errcode = '22023';
  end if;
  insert into booking_api.office_customs_departments (office_id, company_id, department_id, updated_by)
  values (requested_office_id, workspace_company_id, department_id_value, actor_user_id)
  on conflict (office_id) do update set department_id = excluded.department_id, company_id = excluded.company_id, updated_at = now(), updated_by = excluded.updated_by;
  return department_id_value;
end;
$$;


ALTER FUNCTION "booking_api"."resolve_customs_department"("workspace_company_id" "uuid", "requested_office_id" "uuid", "actor_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."resolve_freight_direction"("operating_country_code" "text", "origin_country_code" "text", "destination_country_code" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
  select case
    when not coalesce(upper(nullif(btrim(operating_country_code), '')) ~ '^[A-Z]{2}$', false)
      or not coalesce(upper(nullif(btrim(origin_country_code), '')) ~ '^[A-Z]{2}$', false)
      or not coalesce(upper(nullif(btrim(destination_country_code), '')) ~ '^[A-Z]{2}$', false)
      then null
    when upper(btrim(origin_country_code)) = upper(btrim(operating_country_code))
      and upper(btrim(destination_country_code)) = upper(btrim(operating_country_code))
      then 'domestic'
    when upper(btrim(origin_country_code)) = upper(btrim(operating_country_code))
      then 'export'
    when upper(btrim(destination_country_code)) = upper(btrim(operating_country_code))
      then 'import'
    else 'cross_trade'
  end;
$_$;


ALTER FUNCTION "booking_api"."resolve_freight_direction"("operating_country_code" "text", "origin_country_code" "text", "destination_country_code" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "booking_api"."resolve_freight_direction"("operating_country_code" "text", "origin_country_code" "text", "destination_country_code" "text") IS 'Calculates Export, Import, Domestic or Cross trade from the operating branch country and the shipment overall origin/final destination.';



