CREATE OR REPLACE FUNCTION "booking_api"."routing_mode_review_required"("current_routes" "jsonb", "proposed_routes" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare current_modes text[]; proposed_modes text[];
begin
  if jsonb_typeof(current_routes) is distinct from 'array'
    or jsonb_typeof(proposed_routes) is distinct from 'array' then return true; end if;
  select coalesce(array_agg(booking_api.normalise_mode(value->>'mode') order by ordinality),'{}')
    into current_modes from jsonb_array_elements(current_routes) with ordinality;
  select coalesce(array_agg(booking_api.normalise_mode(value->>'mode') order by ordinality),'{}')
    into proposed_modes from jsonb_array_elements(proposed_routes) with ordinality;
  -- An unknown mode is not evidence of an unchanged mode. Never infer Road.
  if array_position(current_modes,null) is not null or array_position(proposed_modes,null) is not null then return true; end if;
  -- Application matches existing Quote-owned rows in route order. Detect any
  -- changed overlapping position, plus introducing/removing a distinct mode.
  -- Another same-mode leg at the end is not by itself a mode change.
  return exists(select 1 from generate_series(1,least(cardinality(current_modes),cardinality(proposed_modes))) n
      where current_modes[n] is distinct from proposed_modes[n])
    or not (current_modes @> proposed_modes and current_modes <@ proposed_modes);
end;
$$;


ALTER FUNCTION "booking_api"."routing_mode_review_required"("current_routes" "jsonb", "proposed_routes" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."save_before_cargo_decimals_20260905"("caller_auth_user_id" "uuid", "requested_job_id" "uuid", "payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare result jsonb; money jsonb; before_value jsonb; actor_id uuid; company_id uuid; reference text;
begin
  -- The canonical save validates the actor/job and holds the Job lock for this
  -- whole transaction. Omitted values remain untouched, including old clients.
  result:=booking_api.save_before_goods_value_20260905(caller_auth_user_id,requested_job_id,payload);
  if not payload ? 'shipmentGoodsValue' then return result; end if;
  money:=booking_api.normalise_shipment_value(payload->'shipmentGoodsValue');
  select actor."User_ID",actor."Company_ID",job."Job_BookingReference",
    jsonb_build_object('amount',job."Job_GoodsValueAmount",'currency',job."Job_GoodsValueCurrencyCode")
    into strict actor_id,company_id,reference,before_value
    from public."Job_Header" job join public."cmp_Offices" office on office."Office_ID"=coalesce(job."Job_OrgOfficeID",job."Job_OfficeID")
    join public."cmp_Users" actor on actor."Company_ID"=office."Company_ID" and actor."Auth_User_ID"=caller_auth_user_id and actor."User_AccessStatus"='active'
    where job."Job_ID"=requested_job_id and not job."Job_IsDeleted";
  if before_value is distinct from money then
    update public."Job_Header" set "Job_GoodsValueAmount"=(money->>'amount')::numeric,"Job_GoodsValueCurrencyCode"=money->>'currency',
      "Job_UpdatedAt"=now(),"Job_UpdatedBy"=actor_id where "Job_ID"=requested_job_id;
    insert into booking_api.events(company_id,job_id,event_type,summary,metadata,actor_user_id)
      values(company_id,requested_job_id,'booking_updated','Shipment goods value updated; cargo allocations retained.',
        jsonb_build_object('field','shipmentGoodsValue','before',before_value,'after',money),actor_id);
  end if;
  return booking_api.workspace(caller_auth_user_id,reference);
end;
$$;


ALTER FUNCTION "booking_api"."save_before_cargo_decimals_20260905"("caller_auth_user_id" "uuid", "requested_job_id" "uuid", "payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."save_before_goods_value_20260905"("caller_auth_user_id" "uuid", "requested_job_id" "uuid", "payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  app_user record;
  job_row record;
  route_id uuid;
  cargo_id uuid;
  container_id uuid;
  customer_id uuid;
  direction_value text;
  mode_value text;
  status_value text;
  party jsonb;
  line jsonb;
  line_number integer;
  retained_ids uuid[];
begin
  if caller_auth_user_id is null
     or not booking_api.has_permission(caller_auth_user_id, 'Bookings.Write') then
    raise exception 'Booking changes are not authorised.' using errcode = '42501';
  end if;
  if payload is null or jsonb_typeof(payload) <> 'object' then
    raise exception 'Booking details are required.' using errcode = '22023';
  end if;
  select "User_ID", "Company_ID" into strict app_user
  from public."cmp_Users"
  where "Auth_User_ID" = caller_auth_user_id and "User_AccessStatus" = 'active';
  select job.* into job_row
  from public."Job_Header" job
  join public."cmp_Offices" office on office."Office_ID" = coalesce(job."Job_OrgOfficeID", job."Job_OfficeID")
  where job."Job_ID" = requested_job_id and office."Company_ID" = app_user."Company_ID" and not job."Job_IsDeleted"
  for update;
  if not found then raise exception 'That booking is outside this workspace.' using errcode = '42501'; end if;

  customer_id := case when payload ? 'customerId' then nullif(payload->>'customerId', '')::uuid else job_row."Job_Customer" end;
  if customer_id is not null and not exists (select 1 from public."Org_Master" organisation where organisation."Org_id" = customer_id) then
    raise exception 'Choose a valid customer.' using errcode = '22023';
  end if;
  direction_value := case when payload ? 'direction' then booking_api.normalise_direction(payload->>'direction') else coalesce(job_row."Job_Direction", 'unknown') end;
  mode_value := case when payload ? 'mode' then booking_api.normalise_mode(payload->>'mode') else job_row."Job_TransportModeSummary" end;
  status_value := case when payload ? 'status' then lower(btrim(payload->>'status')) else job_row."Job_Status" end;
  if status_value not in (select status."JS_Code" from public."sys_JobStatuses" status where status."JS_IsActive") then
    raise exception 'Choose a valid booking status.' using errcode = '22023';
  end if;
  if status_value <> 'draft' and customer_id is null then
    raise exception 'Choose a customer before moving this booking out of draft.' using errcode = '22023';
  end if;

  update public."Job_Header" job set
    "Job_Customer" = customer_id,
    "Job_Carrier" = case when payload ? 'carrierId' then nullif(payload->>'carrierId', '')::uuid else job."Job_Carrier" end,
    "Job_Supplier" = case when payload ? 'supplierId' then nullif(payload->>'supplierId', '')::uuid else job."Job_Supplier" end,
    "Job_Status" = status_value,
    "Job_Direction" = direction_value,
    "Job_TransportModeSummary" = mode_value,
    "Job_OriginUNLocode" = case when payload ? 'originUnlocode' then upper(nullif(btrim(payload->>'originUnlocode'), '')) else job."Job_OriginUNLocode" end,
    "Job_OriginNameSnapshot" = case when payload ? 'origin' then nullif(btrim(payload->>'origin'), '') else job."Job_OriginNameSnapshot" end,
    "Job_DestinationUNLocode" = case when payload ? 'destinationUnlocode' then upper(nullif(btrim(payload->>'destinationUnlocode'), '')) else job."Job_DestinationUNLocode" end,
    "Job_DestinationNameSnapshot" = case when payload ? 'destination' then nullif(btrim(payload->>'destination'), '') else job."Job_DestinationNameSnapshot" end,
    "Job_ReadyDate" = case when payload ? 'readyDate' then nullif(payload->>'readyDate', '')::date else job."Job_ReadyDate" end,
    "Job_RequiredDeliveryDate" = case when payload ? 'requiredDeliveryDate' then nullif(payload->>'requiredDeliveryDate', '')::date else job."Job_RequiredDeliveryDate" end,
    "Job_CustomerDeadline" = case when payload ? 'customerDeadline' then nullif(payload->>'customerDeadline', '')::date else job."Job_CustomerDeadline" end,
    "Job_PredictedDeliveryAt" = case when payload ? 'predictedDeliveryAt' then nullif(payload->>'predictedDeliveryAt', '')::timestamptz else job."Job_PredictedDeliveryAt" end,
    "Job_TrackingStatus" = case when payload ? 'trackingStatus' then nullif(btrim(payload->>'trackingStatus'), '') else job."Job_TrackingStatus" end,
    "Job_CurrentLocationNameSnapshot" = case when payload ? 'currentLocation' then nullif(btrim(payload->>'currentLocation'), '') else job."Job_CurrentLocationNameSnapshot" end,
    "Job_InternalNotes" = case when payload ? 'internalNotes' then nullif(btrim(payload->>'internalNotes'), '') else job."Job_InternalNotes" end,
    "Job_IncotermsCode" = case when payload ? 'incoterm' then upper(nullif(btrim(payload->>'incoterm'), '')) else job."Job_IncotermsCode" end,
    "Job_IncotermsLocation" = case when payload ? 'incotermLocation' then nullif(btrim(payload->>'incotermLocation'), '') else job."Job_IncotermsLocation" end,
    "Job_FreightChargeAmount" = case when payload ? 'freightChargeAmount' then nullif(payload->>'freightChargeAmount', '')::numeric else job."Job_FreightChargeAmount" end,
    "Job_FreightChargeCurrencyCode" = case when payload ? 'freightChargeCurrency' then upper(nullif(btrim(payload->>'freightChargeCurrency'), '')) else job."Job_FreightChargeCurrencyCode" end,
    "Job_CollectionAddress" = case when payload ? 'collectionAddress' then nullif(btrim(payload->>'collectionAddress'), '') else job."Job_CollectionAddress" end,
    "Job_DeliveryAddress" = case when payload ? 'deliveryAddress' then nullif(btrim(payload->>'deliveryAddress'), '') else job."Job_DeliveryAddress" end,
    "Job_UpdatedAt" = now(), "Job_UpdatedBy" = app_user."User_ID"
  where job."Job_ID" = requested_job_id;

  if payload ? 'route' and jsonb_typeof(payload->'route') = 'object' then
    select route."JobRoute_ID" into route_id from public."Job_Routing" route
    where route."Job_ID" = requested_job_id order by route."JobRoute_OrderNo" nulls last limit 1;
    if route_id is null then
      insert into public."Job_Routing" (
        "Job_ID", "JobRoute_OrderNo", "JobRoute_Status", "JobRoute_ModeCode",
        "JobRoute_OriginUNLocode", "JobRoute_OriginNameSnapshot", "JobRoute_OriginAddressSnapshot",
        "JobRoute_DestinationUNLocode", "JobRoute_DestinationNameSnapshot", "JobRoute_DestinationAddressSnapshot",
        "JobRoute_PlannedPickupAt", "JobRoute_PlannedDepartureAt", "JobRoute_PlannedArrivalAt", "JobRoute_PlannedDeliveryAt",
        "JobRoute_Carrier", "JobRoute_CarrierBookingReference", "JobRoute_MasterTransportReference",
        "JobRoute_HouseTransportReference", "JobRoute_ServiceLevel", "JobRoute_TransportMeansName",
        "JobRoute_Vessel", "JobRoute_VoyageNumber", "JobRoute_FlightNumber", "JobRoute_VehicleRegistration",
        "JobRoute_TrailerNumber", "JobRoute_RailService", "JobRoute_IsMainCarriage", "JobRoute_RouteJSON", "JobRoute_UpdatedBy"
      ) values (
        requested_job_id, 1, 'planned', case
          when nullif(btrim(payload#>>'{route,mode}'),'') is not null
            then booking_api.normalise_mode(payload#>>'{route,mode}')
          else mode_value end,
        upper(nullif(payload#>>'{route,originUnlocode}', '')), nullif(payload#>>'{route,origin}', ''), nullif(payload#>>'{route,originAddress}', ''),
        upper(nullif(payload#>>'{route,destinationUnlocode}', '')), nullif(payload#>>'{route,destination}', ''), nullif(payload#>>'{route,destinationAddress}', ''),
        nullif(payload#>>'{route,plannedPickupAt}', '')::timestamptz, nullif(payload#>>'{route,plannedDepartureAt}', '')::timestamptz,
        nullif(payload#>>'{route,plannedArrivalAt}', '')::timestamptz, nullif(payload#>>'{route,plannedDeliveryAt}', '')::timestamptz,
        nullif(payload#>>'{route,carrierId}', '')::uuid, nullif(payload#>>'{route,carrierBookingReference}', ''),
        nullif(payload#>>'{route,masterTransportReference}', ''), nullif(payload#>>'{route,houseTransportReference}', ''),
        nullif(payload#>>'{route,serviceLevel}', ''), nullif(payload#>>'{route,transportMeansName}', ''),
        nullif(payload#>>'{route,vessel}', ''), nullif(payload#>>'{route,voyageNumber}', ''),
        nullif(payload#>>'{route,flightNumber}', ''), nullif(payload#>>'{route,vehicleRegistration}', ''),
        nullif(payload#>>'{route,trailerNumber}', ''), nullif(payload#>>'{route,railService}', ''),
        true, coalesce(payload->'route', '{}'::jsonb), app_user."User_ID"
      ) returning "JobRoute_ID" into route_id;
    else
      update public."Job_Routing" route set
        "JobRoute_ModeCode" = case
          when nullif(btrim(payload#>>'{route,mode}'),'') is not null
            then booking_api.normalise_mode(payload#>>'{route,mode}')
          else route."JobRoute_ModeCode" end,
        "JobRoute_OriginUNLocode" = case when payload#>>'{route,originUnlocode}' is not null then upper(nullif(payload#>>'{route,originUnlocode}', '')) else route."JobRoute_OriginUNLocode" end,
        "JobRoute_OriginNameSnapshot" = case when payload#>>'{route,origin}' is not null then nullif(payload#>>'{route,origin}', '') else route."JobRoute_OriginNameSnapshot" end,
        "JobRoute_OriginAddressSnapshot" = case when payload#>>'{route,originAddress}' is not null then nullif(payload#>>'{route,originAddress}', '') else route."JobRoute_OriginAddressSnapshot" end,
        "JobRoute_DestinationUNLocode" = case when payload#>>'{route,destinationUnlocode}' is not null then upper(nullif(payload#>>'{route,destinationUnlocode}', '')) else route."JobRoute_DestinationUNLocode" end,
        "JobRoute_DestinationNameSnapshot" = case when payload#>>'{route,destination}' is not null then nullif(payload#>>'{route,destination}', '') else route."JobRoute_DestinationNameSnapshot" end,
        "JobRoute_DestinationAddressSnapshot" = case when payload#>>'{route,destinationAddress}' is not null then nullif(payload#>>'{route,destinationAddress}', '') else route."JobRoute_DestinationAddressSnapshot" end,
        "JobRoute_PlannedPickupAt" = case when payload#>>'{route,plannedPickupAt}' is not null then nullif(payload#>>'{route,plannedPickupAt}', '')::timestamptz else route."JobRoute_PlannedPickupAt" end,
        "JobRoute_PlannedDepartureAt" = case when payload#>>'{route,plannedDepartureAt}' is not null then nullif(payload#>>'{route,plannedDepartureAt}', '')::timestamptz else route."JobRoute_PlannedDepartureAt" end,
        "JobRoute_PlannedArrivalAt" = case when payload#>>'{route,plannedArrivalAt}' is not null then nullif(payload#>>'{route,plannedArrivalAt}', '')::timestamptz else route."JobRoute_PlannedArrivalAt" end,
        "JobRoute_PlannedDeliveryAt" = case when payload#>>'{route,plannedDeliveryAt}' is not null then nullif(payload#>>'{route,plannedDeliveryAt}', '')::timestamptz else route."JobRoute_PlannedDeliveryAt" end,
        "JobRoute_Carrier" = case when payload#>>'{route,carrierId}' is not null then nullif(payload#>>'{route,carrierId}', '')::uuid else route."JobRoute_Carrier" end,
        "JobRoute_CarrierBookingReference" = case when payload#>>'{route,carrierBookingReference}' is not null then nullif(payload#>>'{route,carrierBookingReference}', '') else route."JobRoute_CarrierBookingReference" end,
        "JobRoute_MasterTransportReference" = case when payload#>>'{route,masterTransportReference}' is not null then nullif(payload#>>'{route,masterTransportReference}', '') else route."JobRoute_MasterTransportReference" end,
        "JobRoute_HouseTransportReference" = case when payload#>>'{route,houseTransportReference}' is not null then nullif(payload#>>'{route,houseTransportReference}', '') else route."JobRoute_HouseTransportReference" end,
        "JobRoute_ServiceLevel" = case when payload#>>'{route,serviceLevel}' is not null then nullif(payload#>>'{route,serviceLevel}', '') else route."JobRoute_ServiceLevel" end,
        "JobRoute_TransportMeansName" = case when payload#>>'{route,transportMeansName}' is not null then nullif(payload#>>'{route,transportMeansName}', '') else route."JobRoute_TransportMeansName" end,
        "JobRoute_Vessel" = case when payload#>>'{route,vessel}' is not null then nullif(payload#>>'{route,vessel}', '') else route."JobRoute_Vessel" end,
        "JobRoute_VoyageNumber" = case when payload#>>'{route,voyageNumber}' is not null then nullif(payload#>>'{route,voyageNumber}', '') else route."JobRoute_VoyageNumber" end,
        "JobRoute_FlightNumber" = case when payload#>>'{route,flightNumber}' is not null then nullif(payload#>>'{route,flightNumber}', '') else route."JobRoute_FlightNumber" end,
        "JobRoute_VehicleRegistration" = case when payload#>>'{route,vehicleRegistration}' is not null then nullif(payload#>>'{route,vehicleRegistration}', '') else route."JobRoute_VehicleRegistration" end,
        "JobRoute_TrailerNumber" = case when payload#>>'{route,trailerNumber}' is not null then nullif(payload#>>'{route,trailerNumber}', '') else route."JobRoute_TrailerNumber" end,
        "JobRoute_RailService" = case when payload#>>'{route,railService}' is not null then nullif(payload#>>'{route,railService}', '') else route."JobRoute_RailService" end,
        "JobRoute_RouteJSON" = route."JobRoute_RouteJSON" || coalesce(payload->'route', '{}'::jsonb),
        "JobRoute_UpdatedAt" = now(), "JobRoute_UpdatedBy" = app_user."User_ID"
      where route."JobRoute_ID" = route_id;
    end if;
  end if;

  if payload ? 'parties' then
    if jsonb_typeof(payload->'parties') <> 'array' or jsonb_array_length(payload->'parties') > 30 then
      raise exception 'Booking parties are invalid.' using errcode = '22023';
    end if;
    delete from public."Job_Parties" where "JobParty_JobID" = requested_job_id;
    for party in select value from jsonb_array_elements(payload->'parties') loop
      if nullif(btrim(party->>'role'), '') is null then raise exception 'Each booking party needs a role.' using errcode = '22023'; end if;
      insert into public."Job_Parties" (
        "JobParty_JobID", "JobParty_Role", "JobParty_OrgID", "JobParty_AddressID", "JobParty_ContactID",
        "JobParty_Sequence", "JobParty_NameSnapshot", "JobParty_AddressSnapshot", "JobParty_ContactNameSnapshot",
        "JobParty_EmailSnapshot", "JobParty_PhoneSnapshot", "JobParty_CountryCodeSnapshot",
        "JobParty_IdentifierType", "JobParty_IdentifierValueSnapshot", "JobParty_IsPrimary",
        "JobParty_RawSnapshot", "JobParty_CreatedBy"
      ) values (
        requested_job_id, left(lower(btrim(party->>'role')), 60), nullif(party->>'organisationId', '')::uuid,
        nullif(party->>'addressId', '')::uuid, nullif(party->>'contactId', '')::uuid,
        greatest(coalesce(nullif(party->>'sequence', '')::integer, 1), 1), left(nullif(btrim(party->>'name'), ''), 240),
        nullif(btrim(party->>'address'), ''), left(nullif(btrim(party->>'contactName'), ''), 180),
        left(nullif(btrim(party->>'email'), ''), 254), left(nullif(btrim(party->>'phone'), ''), 80),
        upper(left(nullif(btrim(party->>'countryCode'), ''), 2)), left(nullif(btrim(party->>'identifierType'), ''), 80),
        left(nullif(btrim(party->>'identifierValue'), ''), 120), coalesce((party->>'isPrimary')::boolean, false),
        party, app_user."User_ID"
      );
    end loop;
  end if;

  if payload ? 'cargo' then
    if jsonb_typeof(payload->'cargo') <> 'array' or jsonb_array_length(payload->'cargo') > 200 then
      raise exception 'Booking cargo lines are invalid.' using errcode = '22023';
    end if;
    -- Validate identities before retiring omitted items. Never accept another job's ID,
    -- resurrect archived cargo, or let a duplicate ID silently collapse two rows.
    retained_ids := '{}'::uuid[];
    for line in select value from jsonb_array_elements(payload->'cargo') loop
      if jsonb_typeof(line) is distinct from 'object' or nullif(btrim(line->>'description'), '') is null then
        raise exception 'Every cargo line needs a goods description.' using errcode = '22023';
      end if;
      cargo_id := nullif(line->>'id', '')::uuid;
      if cargo_id is not null then
        if cargo_id = any(retained_ids) then
          raise exception 'Duplicate cargo identity.' using errcode = '22023';
        end if;
        if not exists (
          select 1 from public."Job_Cargo"
          where "JobCargo_ID" = cargo_id and "JobCargo_JobID" = requested_job_id
            and not "JobCargo_IsDeleted"
        ) then
          raise exception 'That cargo record is no longer active in this booking. Reload before saving.' using errcode = '42501';
        end if;
        retained_ids := array_append(retained_ids, cargo_id);
      end if;
    end loop;
    -- Soft retirement preserves historical documents and allocations. Retained IDs
    -- are updated in place, including fields not exposed by the current editor.
    update public."Job_Cargo" set "JobCargo_IsDeleted" = true,
      "JobCargo_UpdatedAt" = now(), "JobCargo_UpdatedBy" = app_user."User_ID"
    where "JobCargo_JobID" = requested_job_id and not "JobCargo_IsDeleted"
      and not ("JobCargo_ID" = any(retained_ids));
    -- Release active line numbers inside the same locked transaction so reordering is safe.
    update public."Job_Cargo" set "JobCargo_LineNo" = null
    where "JobCargo_JobID" = requested_job_id and not "JobCargo_IsDeleted";
    line_number := 0;
    for line in select value from jsonb_array_elements(payload->'cargo') loop
      if nullif(btrim(line->>'description'), '') is not null then
        line_number := line_number + 1;
        insert into public."Job_Cargo" (
          "JobCargo_ID",
          "JobCargo_JobID", "JobCargo_LineNo", "JobCargo_Description", "JobCargo_Commodity", "JobCargo_Qty",
          "JobCargo_PackageTypeCodeSnapshot", "JobCargo_PackageQty", "JobCargo_GrossKilos", "JobCargo_NettKilos",
          "JobCargo_HSCode", "JobCargo_CountryOfOriginCodeSnapshot", "JobCargo_VolumeCBM",
          "JobCargo_DeclaredValueAmount", "JobCargo_DeclaredValueCurrencyCodeSnapshot",
          "JobCargo_ChargeableWeightKg", "JobCargo_IsHazardous", "JobCargo_IsTemperatureControlled", "JobCargo_CargoJSON", "JobCargo_UpdatedBy"
        ) values (
          coalesce(nullif(line->>'id', '')::uuid, gen_random_uuid()),
          requested_job_id, line_number, btrim(line->>'description'), left(nullif(btrim(line->>'commodity'), ''), 50),
          nullif(line->>'pieces', '')::numeric, left(nullif(btrim(line->>'packageType'), ''), 40),
          nullif(line->>'packageQuantity', '')::numeric, nullif(line->>'grossWeightKg', '')::numeric,
          nullif(line->>'netWeightKg', '')::numeric, left(nullif(btrim(line->>'hsCode'), ''), 30),
          upper(left(nullif(btrim(line->>'countryOfOrigin'), ''), 2)), nullif(line->>'volumeCbm', '')::numeric,
          nullif(line->>'declaredValue', '')::numeric, upper(left(nullif(btrim(line->>'declaredValueCurrency'), ''), 3)),
          (line->>'chargeableWeightKg')::numeric, coalesce((line->>'isHazardous')::boolean, false), coalesce((line->>'isTemperatureControlled')::boolean, false),
          line, app_user."User_ID"
        ) on conflict ("JobCargo_ID") do update set
          "JobCargo_LineNo" = excluded."JobCargo_LineNo",
          "JobCargo_Description" = excluded."JobCargo_Description",
          "JobCargo_Commodity" = excluded."JobCargo_Commodity",
          "JobCargo_Qty" = excluded."JobCargo_Qty",
          "JobCargo_PackageTypeCodeSnapshot" = excluded."JobCargo_PackageTypeCodeSnapshot",
          "JobCargo_PackageQty" = excluded."JobCargo_PackageQty",
          "JobCargo_GrossKilos" = excluded."JobCargo_GrossKilos",
          "JobCargo_NettKilos" = excluded."JobCargo_NettKilos",
          "JobCargo_HSCode" = excluded."JobCargo_HSCode",
          "JobCargo_CountryOfOriginCodeSnapshot" = excluded."JobCargo_CountryOfOriginCodeSnapshot",
          "JobCargo_VolumeCBM" = excluded."JobCargo_VolumeCBM",
          "JobCargo_DeclaredValueAmount" = excluded."JobCargo_DeclaredValueAmount",
          "JobCargo_DeclaredValueCurrencyCodeSnapshot" = excluded."JobCargo_DeclaredValueCurrencyCodeSnapshot",
          "JobCargo_IsHazardous" = excluded."JobCargo_IsHazardous",
          "JobCargo_IsTemperatureControlled" = excluded."JobCargo_IsTemperatureControlled",
          "JobCargo_ChargeableWeightKg" = case when excluded."JobCargo_CargoJSON" ? 'chargeableWeightKg' then excluded."JobCargo_ChargeableWeightKg" else public."Job_Cargo"."JobCargo_ChargeableWeightKg" end,
          "JobCargo_CargoJSON" = public."Job_Cargo"."JobCargo_CargoJSON" || excluded."JobCargo_CargoJSON",
          "JobCargo_UpdatedBy" = excluded."JobCargo_UpdatedBy",
          "JobCargo_UpdatedAt" = now();
      end if;
    end loop;
  end if;

  if payload ? 'containers' then
    payload:=jsonb_set(payload,'{containers}',booking_api.normalise_container_operations(payload->'containers'));
    if jsonb_typeof(payload->'containers') <> 'array' or jsonb_array_length(payload->'containers') > 100 then
      raise exception 'Booking containers are invalid.' using errcode = '22023';
    end if;
    -- Validate identities before retiring omitted items. Never accept another job's ID,
    -- resurrect archived cargo, or let a duplicate ID silently collapse two rows.
    retained_ids := '{}'::uuid[];
    for line in select value from jsonb_array_elements(payload->'containers') loop
      if jsonb_typeof(line) is distinct from 'object' then
        raise exception 'Every equipment line must be an object.' using errcode = '22023';
      end if;
      container_id := nullif(line->>'id', '')::uuid;
      if container_id is not null then
        if container_id = any(retained_ids) then
          raise exception 'Duplicate containers identity.' using errcode = '22023';
        end if;
        if not exists (
          select 1 from public."Job_Containers"
          where "JobContainers_ID" = container_id and "Job_ID" = requested_job_id
            and not "JobContainer_IsDeleted"
        ) then
          raise exception 'That containers record is no longer active in this booking. Reload before saving.' using errcode = '42501';
        end if;
        retained_ids := array_append(retained_ids, container_id);
      end if;
    end loop;
    -- Soft retirement preserves historical documents and allocations. Retained IDs
    -- are updated in place, including fields not exposed by the current editor.
    update public."Job_Containers" set "JobContainer_IsDeleted" = true,
      "JobContainer_UpdatedAt" = now(), "JobContainer_UpdatedBy" = app_user."User_ID"
    where "Job_ID" = requested_job_id and not "JobContainer_IsDeleted"
      and not ("JobContainers_ID" = any(retained_ids));
    for line in select value from jsonb_array_elements(payload->'containers') loop
      if quote_api.jsonb_has_content(line) then
        insert into public."Job_Containers" (
          "JobContainers_ID",
          "Job_ID", "JobContainer_Number", "JobContainer_TypeCodeSnapshot", "JobContainer_EquipmentKind",
          "JobContainer_Status", "JobContainer_GrossKilos", "JobContainer_ReeferUnit", "JobContainer_ReeferSetPoint", "JobContainer_VGMMethod", "JobContainer_VGMKilos", "JobContainer_TareKilos", "JobContainer_Notes", "JobContainer_JSON", "JobContainer_UpdatedBy"
        ) values (
          coalesce(nullif(line->>'id', '')::uuid, gen_random_uuid()),
          requested_job_id, left(nullif(btrim(line->>'number'), ''), 50), left(nullif(btrim(line->>'type'), ''), 40),
          booking_api.equipment_kind_for_save(line, requested_job_id),
          coalesce(left(nullif(btrim(line->>'status'), ''), 40), 'planned'), nullif(line->>'grossWeightKg', '')::numeric, nullif(line->>'reeferUnit', '')::text, nullif(line->>'reeferSetPoint', '')::numeric, nullif(line->>'vgmMethod', '')::text, nullif(line->>'verifiedGrossMassKg', '')::numeric, nullif(line->>'tareWeightKg', '')::numeric,
          nullif(btrim(line->>'notes'), ''), line, app_user."User_ID"
        ) on conflict ("JobContainers_ID") do update set
          "JobContainer_Number" = case when line ? 'number' then excluded."JobContainer_Number" else public."Job_Containers"."JobContainer_Number" end,
          "JobContainer_TypeCodeSnapshot" = case when line ? 'type' then excluded."JobContainer_TypeCodeSnapshot" else public."Job_Containers"."JobContainer_TypeCodeSnapshot" end,
          "JobContainer_EquipmentKind" = excluded."JobContainer_EquipmentKind",
          "JobContainer_Status" = case when line ? 'status' then excluded."JobContainer_Status" else public."Job_Containers"."JobContainer_Status" end,
          "JobContainer_GrossKilos" = case when line ? 'grossWeightKg' then excluded."JobContainer_GrossKilos" else public."Job_Containers"."JobContainer_GrossKilos" end,
          "JobContainer_ReeferUnit" = case when line ? 'reeferUnit' then excluded."JobContainer_ReeferUnit" else public."Job_Containers"."JobContainer_ReeferUnit" end,
          "JobContainer_ReeferSetPoint" = case when line ? 'reeferSetPoint' then excluded."JobContainer_ReeferSetPoint" else public."Job_Containers"."JobContainer_ReeferSetPoint" end,
          "JobContainer_VGMMethod" = case when line ? 'vgmMethod' then excluded."JobContainer_VGMMethod" else public."Job_Containers"."JobContainer_VGMMethod" end,
          "JobContainer_VGMKilos" = case when line ? 'verifiedGrossMassKg' then excluded."JobContainer_VGMKilos" else public."Job_Containers"."JobContainer_VGMKilos" end,
          "JobContainer_TareKilos" = case when line ? 'tareWeightKg' then excluded."JobContainer_TareKilos" else public."Job_Containers"."JobContainer_TareKilos" end,
          "JobContainer_Notes" = case when line ? 'notes' then excluded."JobContainer_Notes" else public."Job_Containers"."JobContainer_Notes" end,
          "JobContainer_JSON" = public."Job_Containers"."JobContainer_JSON" || excluded."JobContainer_JSON",
          "JobContainer_UpdatedBy" = excluded."JobContainer_UpdatedBy",
          "JobContainer_UpdatedAt" = now();
      end if;
    end loop;
  end if;

  insert into booking_api.events (company_id, job_id, event_type, summary, metadata, actor_user_id)
  values (
    app_user."Company_ID", requested_job_id, 'saved', 'Booking changes saved.',
    jsonb_build_object('fields', (select jsonb_agg(field_name) from jsonb_object_keys(payload) as field_name)),
    app_user."User_ID"
  );

  return booking_api.workspace(caller_auth_user_id, job_row."Job_BookingReference");
exception
  when no_data_found or too_many_rows then raise exception 'Your workspace identity is incomplete.' using errcode = '42501';
end;
$$;


ALTER FUNCTION "booking_api"."save_before_goods_value_20260905"("caller_auth_user_id" "uuid", "requested_job_id" "uuid", "payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."save_booking"("caller_auth_user_id" "uuid", "requested_job_id" "uuid", "payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if payload ? 'cargo' then payload:=jsonb_set(payload,'{cargo}',booking_api.normalise_cargo_numbers(payload->'cargo')); end if;
  return booking_api.save_before_cargo_decimals_20260905(caller_auth_user_id,requested_job_id,payload);
end $$;


ALTER FUNCTION "booking_api"."save_booking"("caller_auth_user_id" "uuid", "requested_job_id" "uuid", "payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."save_booking_cargo_measurements"("caller_auth_user_id" "uuid", "requested_job_id" "uuid", "payload" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if payload ? 'cargo' then payload:=jsonb_set(payload,'{cargo}',booking_api.normalise_cargo_numbers(payload->'cargo')); end if;
  perform booking_api.save_cargo_measurements_before_decimals_20260905(caller_auth_user_id,requested_job_id,payload);
end $$;


ALTER FUNCTION "booking_api"."save_booking_cargo_measurements"("caller_auth_user_id" "uuid", "requested_job_id" "uuid", "payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."save_booking_detail_fields"("caller_auth_user_id" "uuid", "requested_job_id" "uuid", "payload" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  app_user record;
  job_row record;
  details jsonb;
begin
  if caller_auth_user_id is null
     or not booking_api.has_permission(caller_auth_user_id, 'Bookings.Write') then
    raise exception 'Booking changes are not authorised.' using errcode = '42501';
  end if;
  if payload is null or jsonb_typeof(payload) <> 'object' then
    raise exception 'Booking details are required.' using errcode = '22023';
  end if;
  if payload ? 'editableDetails' and jsonb_typeof(payload->'editableDetails') <> 'object' then
    raise exception 'Booking detail overrides are invalid.' using errcode = '22023';
  end if;
  select "User_ID", "Company_ID" into strict app_user
  from public."cmp_Users"
  where "Auth_User_ID" = caller_auth_user_id and "User_AccessStatus" = 'active';
  select job.* into job_row
  from public."Job_Header" job
  join public."cmp_Offices" office on office."Office_ID" = coalesce(job."Job_OrgOfficeID", job."Job_OfficeID")
  where job."Job_ID" = requested_job_id
    and office."Company_ID" = app_user."Company_ID"
    and not job."Job_IsDeleted"
  for update;
  if not found then
    raise exception 'That booking is outside this workspace.' using errcode = '42501';
  end if;

  if (payload->'editableDetails') ? 'chargeableWeightKg' then
    begin
      payload:=jsonb_set(payload,'{editableDetails,chargeableWeightKg}',
        booking_api.normalise_cargo_numbers(jsonb_build_array(jsonb_build_object(
          'chargeableWeightKg',payload#>'{editableDetails,chargeableWeightKg}')))#>'{0,chargeableWeightKg}');
    exception when invalid_parameter_value then
      raise exception 'Shipment override (kg) must be a non-negative decimal up to 999999999999, or blank to clear.' using errcode='22023';
    end;
  end if;
  details := coalesce(job_row."Job_EditableDetailsJSON", '{}'::jsonb) || coalesce((
    select jsonb_object_agg(entry.key, entry.value)
    from jsonb_each(coalesce(payload->'editableDetails', '{}'::jsonb)) entry
    where entry.key in (
      'jobReference', 'carrierName', 'ownerName', 'invoiceReference',
      'customerReference', 'supplierReference', 'shipmentType', 'quoteType',
      'customerPO', 'shipperReference', 'consigneeReference', 'hblMode',
      'incoterms', 'routingVia', 'chargeableWeightKg', 'customsIncluded',
      'termsAndConditions', 'subjectToTerms', 'customerNotes',
      'responseDeadline', 'isFavourite', 'progress', 'lastUpdated',
      'sourceId', 'documentsStatus', 'workflowStatus', 'routeSummary',
      'customFields'
    )
      or (entry.key like 'customField:%' and length(entry.key) <= 180)
  ), '{}'::jsonb);
  update public."Job_Header"
  set "Job_EditableDetailsJSON" = details,
      "Job_UpdatedAt" = now(),
      "Job_UpdatedBy" = app_user."User_ID"
  where "Job_ID" = requested_job_id;
end;
$$;


ALTER FUNCTION "booking_api"."save_booking_detail_fields"("caller_auth_user_id" "uuid", "requested_job_id" "uuid", "payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."save_booking_route_legs"("caller_auth_user_id" "uuid", "requested_job_id" "uuid", "payload" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  app_user record;
  job_row record;
  leg jsonb;
  leg_id uuid;
  leg_order integer := 0;
  mode_value text;
  route_json jsonb;
begin
  if not (payload ? 'routes') then return; end if;
  if caller_auth_user_id is null
     or not booking_api.has_permission(caller_auth_user_id, 'Bookings.Write') then
    raise exception 'Booking changes are not authorised.' using errcode = '42501';
  end if;
  if jsonb_typeof(payload->'routes') <> 'array' or jsonb_array_length(payload->'routes') > 30 then
    raise exception 'Booking routing steps are invalid.' using errcode = '22023';
  end if;

  select "User_ID", "Company_ID" into strict app_user
  from public."cmp_Users"
  where "Auth_User_ID" = caller_auth_user_id and "User_AccessStatus" = 'active';

  select job.* into job_row
  from public."Job_Header" job
  join public."cmp_Offices" office on office."Office_ID" = coalesce(job."Job_OrgOfficeID", job."Job_OfficeID")
  where job."Job_ID" = requested_job_id
    and office."Company_ID" = app_user."Company_ID"
    and not job."Job_IsDeleted"
  for update;
  if not found then
    raise exception 'That booking is outside this workspace.' using errcode = '42501';
  end if;

  for leg in select value from jsonb_array_elements(payload->'routes') loop
    leg_order := leg_order + 1;
    if coalesce(nullif(btrim(leg->>'originUnlocode'), ''), nullif(btrim(leg->>'origin'), '')) is null
       or coalesce(nullif(btrim(leg->>'destinationUnlocode'), ''), nullif(btrim(leg->>'destination'), '')) is null then
      raise exception 'Each routing step needs an origin and destination.' using errcode = '22023';
    end if;
    leg_id := nullif(leg->>'id', '')::uuid;
    mode_value := booking_api.normalise_mode(coalesce(nullif(leg->>'mode', ''), job_row."Job_TransportModeSummary", 'road'));
    route_json := case when jsonb_typeof(leg->'routeData') = 'object' then leg->'routeData' else '{}'::jsonb end;

    if leg_id is not null and not exists (
      select 1 from public."Job_Routing" route
      where route."JobRoute_ID" = leg_id and route."Job_ID" = requested_job_id
    ) then
      raise exception 'That routing step does not belong to this booking.' using errcode = '42501';
    end if;

    if leg_id is null then
      insert into public."Job_Routing" (
        "Job_ID", "JobRoute_OrderNo", "JobRoute_Status", "JobRoute_ModeCode",
        "JobRoute_OriginUNLocode", "JobRoute_OriginNameSnapshot", "JobRoute_OriginAddressSnapshot",
        "JobRoute_DestinationUNLocode", "JobRoute_DestinationNameSnapshot", "JobRoute_DestinationAddressSnapshot",
        "JobRoute_PlannedPickupAt", "JobRoute_PlannedDepartureAt", "JobRoute_PlannedArrivalAt", "JobRoute_PlannedDeliveryAt",
        "JobRoute_CargoCutoffAt", "JobRoute_DocumentationCutoffAt", "JobRoute_VgmCutoffAt", "JobRoute_Carrier", "JobRoute_CarrierBookingReference", "JobRoute_MasterTransportReference",
        "JobRoute_HouseTransportReference", "JobRoute_ServiceLevel", "JobRoute_TransportMeansName",
        "JobRoute_Vessel", "JobRoute_VoyageNumber", "JobRoute_FlightNumber", "JobRoute_VehicleRegistration",
        "JobRoute_TrailerNumber", "JobRoute_RailService", "JobRoute_IsMainCarriage", "JobRoute_RouteJSON", "JobRoute_UpdatedBy"
      ) values (
        requested_job_id, leg_order, coalesce(left(nullif(btrim(leg->>'status'), ''), 40), 'planned'), mode_value,
        upper(left(nullif(btrim(leg->>'originUnlocode'), ''), 10)), left(nullif(btrim(leg->>'origin'), ''), 180), nullif(btrim(leg->>'originAddress'), ''),
        upper(left(nullif(btrim(leg->>'destinationUnlocode'), ''), 10)), left(nullif(btrim(leg->>'destination'), ''), 180), nullif(btrim(leg->>'destinationAddress'), ''),
        nullif(leg->>'plannedPickupAt', '')::timestamptz, nullif(leg->>'plannedDepartureAt', '')::timestamptz,
        nullif(leg->>'plannedArrivalAt', '')::timestamptz, nullif(leg->>'plannedDeliveryAt', '')::timestamptz,
        booking_api.parse_route_cutoff(leg->'cargoCutoffAt'), booking_api.parse_route_cutoff(leg->'documentationCutoffAt'), booking_api.parse_route_cutoff(leg->'vgmCutoffAt'), nullif(leg->>'carrierId', '')::uuid, left(nullif(btrim(leg->>'carrierBookingReference'), ''), 160),
        left(nullif(btrim(leg->>'masterTransportReference'), ''), 160), left(nullif(btrim(leg->>'houseTransportReference'), ''), 160),
        left(nullif(btrim(leg->>'serviceLevel'), ''), 80), left(nullif(btrim(leg->>'transportMeansName'), ''), 160),
        left(nullif(btrim(leg->>'vessel'), ''), 50), left(nullif(btrim(leg->>'voyageNumber'), ''), 50),
        left(nullif(btrim(leg->>'flightNumber'), ''), 40), left(nullif(btrim(leg->>'vehicleRegistration'), ''), 80),
        left(nullif(btrim(leg->>'trailerNumber'), ''), 80), left(nullif(btrim(leg->>'railService'), ''), 80),
        coalesce((leg->>'isMainCarriage')::boolean, leg_order = 1), route_json, app_user."User_ID"
      );
    else
      update public."Job_Routing" route set
        "JobRoute_OrderNo" = leg_order,
        "JobRoute_Status" = coalesce(left(nullif(btrim(leg->>'status'), ''), 40), route."JobRoute_Status"),
        "JobRoute_ModeCode" = mode_value,
        "JobRoute_OriginUNLocode" = upper(left(nullif(btrim(leg->>'originUnlocode'), ''), 10)),
        "JobRoute_OriginNameSnapshot" = left(nullif(btrim(leg->>'origin'), ''), 180),
        "JobRoute_OriginAddressSnapshot" = nullif(btrim(leg->>'originAddress'), ''),
        "JobRoute_DestinationUNLocode" = upper(left(nullif(btrim(leg->>'destinationUnlocode'), ''), 10)),
        "JobRoute_DestinationNameSnapshot" = left(nullif(btrim(leg->>'destination'), ''), 180),
        "JobRoute_DestinationAddressSnapshot" = nullif(btrim(leg->>'destinationAddress'), ''),
        "JobRoute_PlannedPickupAt" = nullif(leg->>'plannedPickupAt', '')::timestamptz,
        "JobRoute_PlannedDepartureAt" = nullif(leg->>'plannedDepartureAt', '')::timestamptz,
        "JobRoute_PlannedArrivalAt" = nullif(leg->>'plannedArrivalAt', '')::timestamptz,
        "JobRoute_PlannedDeliveryAt" = nullif(leg->>'plannedDeliveryAt', '')::timestamptz,
        "JobRoute_CargoCutoffAt" = case when leg ? 'cargoCutoffAt' then booking_api.parse_route_cutoff(leg->'cargoCutoffAt') else route."JobRoute_CargoCutoffAt" end,
        "JobRoute_DocumentationCutoffAt" = case when leg ? 'documentationCutoffAt' then booking_api.parse_route_cutoff(leg->'documentationCutoffAt') else route."JobRoute_DocumentationCutoffAt" end,
        "JobRoute_VgmCutoffAt" = case when leg ? 'vgmCutoffAt' then booking_api.parse_route_cutoff(leg->'vgmCutoffAt') else route."JobRoute_VgmCutoffAt" end,
        "JobRoute_Carrier" = nullif(leg->>'carrierId', '')::uuid,
        "JobRoute_CarrierBookingReference" = left(nullif(btrim(leg->>'carrierBookingReference'), ''), 160),
        "JobRoute_MasterTransportReference" = left(nullif(btrim(leg->>'masterTransportReference'), ''), 160),
        "JobRoute_HouseTransportReference" = left(nullif(btrim(leg->>'houseTransportReference'), ''), 160),
        "JobRoute_ServiceLevel" = left(nullif(btrim(leg->>'serviceLevel'), ''), 80),
        "JobRoute_TransportMeansName" = left(nullif(btrim(leg->>'transportMeansName'), ''), 160),
        "JobRoute_Vessel" = left(nullif(btrim(leg->>'vessel'), ''), 50),
        "JobRoute_VoyageNumber" = left(nullif(btrim(leg->>'voyageNumber'), ''), 50),
        "JobRoute_FlightNumber" = left(nullif(btrim(leg->>'flightNumber'), ''), 40),
        "JobRoute_VehicleRegistration" = left(nullif(btrim(leg->>'vehicleRegistration'), ''), 80),
        "JobRoute_TrailerNumber" = left(nullif(btrim(leg->>'trailerNumber'), ''), 80),
        "JobRoute_RailService" = left(nullif(btrim(leg->>'railService'), ''), 80),
        "JobRoute_IsMainCarriage" = coalesce((leg->>'isMainCarriage')::boolean, leg_order = 1),
        "JobRoute_RouteJSON" = route."JobRoute_RouteJSON" || route_json,
        "JobRoute_UpdatedAt" = now(),
        "JobRoute_UpdatedBy" = app_user."User_ID"
      where route."JobRoute_ID" = leg_id and route."Job_ID" = requested_job_id;
    end if;
  end loop;
end;
$$;


ALTER FUNCTION "booking_api"."save_booking_route_legs"("caller_auth_user_id" "uuid", "requested_job_id" "uuid", "payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."save_cargo_dangerous_goods"("caller_auth_user_id" "uuid", "requested_job_id" "uuid", "payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    SET "TimeZone" TO 'UTC'
    AS $_$
declare
  actor record; job_row public."Job_Header"; cargo_row public."Job_Cargo";
  before_row public."Job_CargoDangerousGoods"; item public."Job_CargoDangerousGoods";
  record_id uuid; cargo_id uuid; changes jsonb; key text; value jsonb; text_value text;
  is_new boolean; before_values jsonb; after_values jsonb;
begin
  select "User_ID","Company_ID" into actor from public."cmp_Users"
    where "Auth_User_ID"=caller_auth_user_id and "User_AccessStatus"='active';
  if not found or booking_api.has_permission(caller_auth_user_id,'Bookings.Read') is not true
    or booking_api.has_permission(caller_auth_user_id,'Bookings.Write') is not true then
    raise exception 'You do not have permission to record Booking dangerous goods.' using errcode='42501'; end if;
  if jsonb_typeof(payload) is distinct from 'object'
    or not(payload ?& array['id','cargoId','expectedUpdatedAt','expectedCargoUpdatedAt','expectedRecordUpdatedAt','changes','reason'])
    or exists(select 1 from jsonb_object_keys(payload) k where k not in
      ('id','cargoId','expectedUpdatedAt','expectedCargoUpdatedAt','expectedRecordUpdatedAt','changes','reason'))
    or jsonb_typeof(payload->'reason') is distinct from 'string'
    or nullif(btrim(payload->>'reason'),'') is null or length(payload->>'reason')>2000
    or jsonb_typeof(payload->'changes') is distinct from 'object' then
    raise exception 'Choose the exact cargo record and provide its changes and reason.' using errcode='22023'; end if;
  if jsonb_typeof(payload->'id') is distinct from 'string' or jsonb_typeof(payload->'cargoId') is distinct from 'string'
    or payload->>'id' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    or payload->>'cargoId' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    raise exception 'Choose valid cargo and dangerous-goods identities.' using errcode='22023'; end if;
  record_id:=(payload->>'id')::uuid; cargo_id:=(payload->>'cargoId')::uuid; changes:=payload->'changes';
  if changes='{}'::jsonb or exists(select 1 from jsonb_object_keys(changes) k where k not in
    ('unNumber','properShippingName','class','packingGroup','flashPoint','marinePollutant','limitedQuantity',
      'emergencyContact','notes','sourceReference','status')) then
    raise exception 'That dangerous-goods field is not available for editing.' using errcode='22023'; end if;
  select j.* into job_row from public."Job_Header" j
    join public."cmp_Offices" o on o."Office_ID"=coalesce(j."Job_OrgOfficeID",j."Job_OfficeID")
    where j."Job_ID"=requested_job_id and o."Company_ID"=actor."Company_ID" and not j."Job_IsDeleted" for update of j;
  if not found then raise exception 'That Booking is outside this workspace.' using errcode='42501'; end if;
  select * into cargo_row from public."Job_Cargo"
    where "JobCargo_ID"=cargo_id and "JobCargo_JobID"=requested_job_id and not "JobCargo_IsDeleted" for update;
  if not found then raise exception 'Choose active cargo from this Booking.' using errcode='42501'; end if;
  if booking_api.parse_milestone_time(payload->'expectedUpdatedAt') is null
    or job_row."Job_UpdatedAt" is distinct from booking_api.parse_milestone_time(payload->'expectedUpdatedAt')
    or booking_api.parse_milestone_time(payload->'expectedCargoUpdatedAt') is null
    or cargo_row."JobCargo_UpdatedAt" is distinct from booking_api.parse_milestone_time(payload->'expectedCargoUpdatedAt') then
    raise exception 'The Booking or cargo changed. Reload before recording dangerous goods.' using errcode='PT409'; end if;
  select * into before_row from public."Job_CargoDangerousGoods" where "JobCargoDG_ID"=record_id for update;
  is_new:=not found;
  if is_new then
    if payload->'expectedRecordUpdatedAt'<>'null'::jsonb then
      raise exception 'That dangerous-goods record no longer exists. Reload the Booking.' using errcode='PT409'; end if;
    item."JobCargoDG_ID":=record_id; item."JobCargoDG_JobCargoID":=cargo_id;
    item."JobCargoDG_Source":='operator'; item."JobCargoDG_Status":='recorded';
    item."JobCargoDG_CreatedBy":=actor."User_ID"; item."JobCargoDG_CreatedAt":=clock_timestamp();
  else
    if before_row."JobCargoDG_JobCargoID"<>cargo_id or before_row."JobCargoDG_Source"<>'operator'
      or before_row."JobCargoDG_CreatedBy" is null then
      raise exception 'Keep the original supplied evidence. Record a new operator entry instead.' using errcode='42501'; end if;
    if before_row."JobCargoDG_UpdatedAt" is distinct from booking_api.parse_milestone_time(payload->'expectedRecordUpdatedAt') then
      raise exception 'This dangerous-goods record changed. Reload before correcting it.' using errcode='PT409'; end if;
    if before_row."JobCargoDG_Status"='voided' then
      raise exception 'Voided evidence is read-only. Record a new entry instead.' using errcode='22023'; end if;
    item:=before_row;
  end if;
  for key,value in select * from jsonb_each(changes) loop
    if key in ('marinePollutant','limitedQuantity') then
      if jsonb_typeof(value) not in ('boolean','null') then
        raise exception 'Choose Yes, No or Not recorded for dangerous-goods flags.' using errcode='22023'; end if;
      if key='marinePollutant' then item."JobCargoDG_MarinePollutant":=(value#>>'{}')::boolean;
      else item."JobCargoDG_LimitedQuantity":=(value#>>'{}')::boolean; end if;
      continue;
    end if;
    if jsonb_typeof(value) not in ('string','null') then
      raise exception 'Dangerous-goods values must be supplied text or an explicit clear.' using errcode='22023'; end if;
    text_value:=nullif(btrim(value#>>'{}'),'');
    if length(text_value)>(case key when 'unNumber' then 10 when 'class' then 20 when 'packingGroup' then 20
      when 'flashPoint' then 40 when 'properShippingName' then 240 when 'emergencyContact' then 180
      when 'sourceReference' then 500 when 'notes' then 8000 else 20 end) then
      raise exception 'That dangerous-goods value exceeds its supported length.' using errcode='22023'; end if;
    case key
      when 'unNumber' then item."JobCargoDG_UNNumber":=text_value;
      when 'properShippingName' then item."JobCargoDG_ProperShippingName":=text_value;
      when 'class' then item."JobCargoDG_Class":=text_value;
      when 'packingGroup' then item."JobCargoDG_PackingGroup":=text_value;
      when 'flashPoint' then item."JobCargoDG_FlashPoint":=text_value;
      when 'emergencyContact' then item."JobCargoDG_EmergencyContact":=text_value;
      when 'notes' then item."JobCargoDG_Notes":=text_value;
      when 'sourceReference' then item."JobCargoDG_SourceReference":=text_value;
      when 'status' then
        if text_value is null or text_value not in ('recorded','voided') or (is_new and text_value<>'recorded') then
          raise exception 'Choose Recorded or void an existing record.' using errcode='22023'; end if;
        item."JobCargoDG_Status":=text_value;
    end case;
  end loop;
  if item."JobCargoDG_SourceReference" is null or
    (item."JobCargoDG_UNNumber" is null and item."JobCargoDG_ProperShippingName" is null and item."JobCargoDG_Class" is null) then
    raise exception 'Record the source and at least one supplied UN number, shipping name or class. This does not certify completeness.' using errcode='22023'; end if;
  if item."JobCargoDG_Status"='voided' and changes<>'{"status":"voided"}'::jsonb then
    raise exception 'Void the retained record without rewriting its supplied values.' using errcode='22023'; end if;
  before_values:=case when is_new then null else booking_api.cargo_dangerous_goods_values(before_row) end;
  if not is_new and before_values=booking_api.cargo_dangerous_goods_values(item) then return before_values; end if;
  item."JobCargoDG_UpdatedAt":=clock_timestamp(); item."JobCargoDG_UpdatedBy":=actor."User_ID";
  if is_new then
    insert into public."Job_CargoDangerousGoods" select (item).*;
  else
    update public."Job_CargoDangerousGoods" set
      "JobCargoDG_UNNumber"=item."JobCargoDG_UNNumber","JobCargoDG_ProperShippingName"=item."JobCargoDG_ProperShippingName",
      "JobCargoDG_Class"=item."JobCargoDG_Class","JobCargoDG_PackingGroup"=item."JobCargoDG_PackingGroup",
      "JobCargoDG_FlashPoint"=item."JobCargoDG_FlashPoint","JobCargoDG_MarinePollutant"=item."JobCargoDG_MarinePollutant",
      "JobCargoDG_LimitedQuantity"=item."JobCargoDG_LimitedQuantity","JobCargoDG_EmergencyContact"=item."JobCargoDG_EmergencyContact",
      "JobCargoDG_Notes"=item."JobCargoDG_Notes","JobCargoDG_SourceReference"=item."JobCargoDG_SourceReference",
      "JobCargoDG_Status"=item."JobCargoDG_Status","JobCargoDG_UpdatedAt"=item."JobCargoDG_UpdatedAt",
      "JobCargoDG_UpdatedBy"=item."JobCargoDG_UpdatedBy" where "JobCargoDG_ID"=record_id;
  end if;
  update public."Job_Header" set "Job_UpdatedAt"=item."JobCargoDG_UpdatedAt","Job_UpdatedBy"=actor."User_ID"
    where "Job_ID"=requested_job_id;
  after_values:=booking_api.cargo_dangerous_goods_values(item);
  insert into booking_api.events(company_id,job_id,event_type,summary,metadata,actor_user_id)
    values(actor."Company_ID",requested_job_id,'cargo_dangerous_goods_recorded',
      case when is_new then 'Dangerous-goods evidence recorded' when item."JobCargoDG_Status"='voided'
        then 'Dangerous-goods evidence voided' else 'Dangerous-goods evidence corrected' end,
      jsonb_build_object('cargoId',cargo_id,'dangerousGoodsId',record_id,'before',before_values,'after',after_values,
        'reason',btrim(payload->>'reason'),'source','operator'),actor."User_ID");
  return after_values;
end $_$;


ALTER FUNCTION "booking_api"."save_cargo_dangerous_goods"("caller_auth_user_id" "uuid", "requested_job_id" "uuid", "payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."save_cargo_measurements_before_decimals_20260905"("caller_auth_user_id" "uuid", "requested_job_id" "uuid", "payload" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  app_user record;
  job_row record;
  line jsonb;
  line_number integer := 0;
begin
  if not (payload ? 'cargo') then return; end if;
  if caller_auth_user_id is null
     or not booking_api.has_permission(caller_auth_user_id, 'Bookings.Write') then
    raise exception 'Booking changes are not authorised.' using errcode = '42501';
  end if;
  select "User_ID", "Company_ID" into strict app_user
  from public."cmp_Users"
  where "Auth_User_ID" = caller_auth_user_id and "User_AccessStatus" = 'active';
  select job.* into job_row
  from public."Job_Header" job
  join public."cmp_Offices" office on office."Office_ID" = coalesce(job."Job_OrgOfficeID", job."Job_OfficeID")
  where job."Job_ID" = requested_job_id
    and office."Company_ID" = app_user."Company_ID"
    and not job."Job_IsDeleted";
  if not found then
    raise exception 'That booking is outside this workspace.' using errcode = '42501';
  end if;

  for line in select value from jsonb_array_elements(coalesce(payload->'cargo', '[]'::jsonb)) loop
    if nullif(btrim(line->>'description'), '') is not null then
      line_number := line_number + 1;
      update public."Job_Cargo" cargo set
        "JobCargo_Length" = nullif(line->>'length', '')::numeric,
        "JobCargo_Width" = nullif(line->>'width', '')::numeric,
        "JobCargo_Height" = nullif(line->>'height', '')::numeric,
        "JobCargo_LengthUnit" = coalesce(left(nullif(lower(btrim(line->>'lengthUnit')), ''), 20), 'cm'),
        "JobCargo_UpdatedAt" = now(),
        "JobCargo_UpdatedBy" = app_user."User_ID"
      where cargo."JobCargo_JobID" = requested_job_id
        and cargo."JobCargo_LineNo" = line_number
        and not cargo."JobCargo_IsDeleted";
    end if;
  end loop;
end;
$$;


ALTER FUNCTION "booking_api"."save_cargo_measurements_before_decimals_20260905"("caller_auth_user_id" "uuid", "requested_job_id" "uuid", "payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."save_cargo_security_evidence"("caller_auth_user_id" "uuid", "requested_job_id" "uuid", "payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    SET "TimeZone" TO 'UTC'
    AS $_$
declare
  actor record; job public."Job_Header"; cargo public."Job_Cargo";
  previous booking_api.cargo_security_evidence; item booking_api.cargo_security_evidence;
  record_id uuid; cargo_id uuid; changes jsonb; key text; value jsonb; supplied text;
  is_new boolean; before_values jsonb; after_values jsonb;
begin
  select "User_ID","Company_ID" into actor from public."cmp_Users"
    where "Auth_User_ID"=caller_auth_user_id and "User_AccessStatus"='active';
  if not found or booking_api.has_permission(caller_auth_user_id,'Bookings.Read') is not true
    or booking_api.has_permission(caller_auth_user_id,'Bookings.Write') is not true then
    raise exception 'You do not have permission to record Booking screening evidence.' using errcode='42501'; end if;
  if jsonb_typeof(payload) is distinct from 'object'
    or not(payload ?& array['id','cargoId','expectedUpdatedAt','expectedCargoUpdatedAt','expectedRecordUpdatedAt','changes','reason'])
    or exists(select 1 from jsonb_object_keys(payload) k where k not in
      ('id','cargoId','expectedUpdatedAt','expectedCargoUpdatedAt','expectedRecordUpdatedAt','changes','reason'))
    or jsonb_typeof(payload->'reason') is distinct from 'string'
    or nullif(btrim(payload->>'reason'),'') is null or length(payload->>'reason')>2000
    or jsonb_typeof(payload->'changes') is distinct from 'object' then
    raise exception 'Choose exact cargo and supply the evidence changes and reason.' using errcode='22023'; end if;
  if jsonb_typeof(payload->'id') is distinct from 'string' or jsonb_typeof(payload->'cargoId') is distinct from 'string'
    or payload->>'id' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    or payload->>'cargoId' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    raise exception 'Choose valid cargo and screening-evidence identities.' using errcode='22023'; end if;
  record_id:=(payload->>'id')::uuid; cargo_id:=(payload->>'cargoId')::uuid; changes:=payload->'changes';
  if changes='{}'::jsonb or exists(select 1 from jsonb_object_keys(changes) k where k not in
    ('securityStatus','screeningMethod','screenedByName','agentReference','screenedAt','sourceReference','notes','recordStatus')) then
    raise exception 'That screening-evidence field is not available for editing.' using errcode='22023'; end if;
  select j.* into job from public."Job_Header" j
    join public."cmp_Offices" o on o."Office_ID"=coalesce(j."Job_OrgOfficeID",j."Job_OfficeID")
    where j."Job_ID"=requested_job_id and o."Company_ID"=actor."Company_ID" and not j."Job_IsDeleted" for update of j;
  if not found then raise exception 'That Booking is outside this workspace.' using errcode='42501'; end if;
  select * into cargo from public."Job_Cargo"
    where "JobCargo_ID"=cargo_id and "JobCargo_JobID"=requested_job_id and not "JobCargo_IsDeleted" for update;
  if not found then raise exception 'Choose active cargo from this Booking.' using errcode='42501'; end if;
  if booking_api.parse_milestone_time(payload->'expectedUpdatedAt') is null
    or job."Job_UpdatedAt" is distinct from booking_api.parse_milestone_time(payload->'expectedUpdatedAt')
    or booking_api.parse_milestone_time(payload->'expectedCargoUpdatedAt') is null
    or cargo."JobCargo_UpdatedAt" is distinct from booking_api.parse_milestone_time(payload->'expectedCargoUpdatedAt') then
    raise exception 'The Booking or cargo changed. Reload before recording screening evidence.' using errcode='PT409'; end if;
  select * into previous from booking_api.cargo_security_evidence where id=record_id for update;
  is_new:=not found;
  if is_new then
    if payload->'expectedRecordUpdatedAt'<>'null'::jsonb then
      raise exception 'That evidence no longer exists. Reload the Booking.' using errcode='PT409'; end if;
    item.id:=record_id; item.cargo_id:=cargo_id; item.record_status:='recorded';
    item.created_by:=actor."User_ID"; item.created_at:=clock_timestamp();
  else
    if previous.cargo_id<>cargo_id then
      raise exception 'That evidence belongs to different cargo.' using errcode='42501'; end if;
    if previous.updated_at is distinct from booking_api.parse_milestone_time(payload->'expectedRecordUpdatedAt') then
      raise exception 'This evidence changed. Reload before correcting it.' using errcode='PT409'; end if;
    if previous.record_status='voided' then
      raise exception 'Voided evidence is read-only. Record a new entry instead.' using errcode='22023'; end if;
    item:=previous;
  end if;
  for key,value in select * from jsonb_each(changes) loop
    if key='screenedAt' then item.screened_at:=booking_api.parse_milestone_time(value); continue; end if;
    if jsonb_typeof(value) not in ('string','null') then
      raise exception 'Screening evidence must be supplied text or an explicit clear.' using errcode='22023'; end if;
    -- Keep supplied text verbatim. Only blank/whitespace-only input becomes unknown.
    supplied:=case when nullif(btrim(value#>>'{}'),'') is null then null else value#>>'{}' end;
    if length(supplied)>(case key when 'screenedByName' then 180 when 'sourceReference' then 500
      when 'notes' then 8000 when 'recordStatus' then 20 else 80 end) then
      raise exception 'That screening-evidence value exceeds its supported length.' using errcode='22023'; end if;
    case key
      when 'securityStatus' then item.security_status:=supplied;
      when 'screeningMethod' then item.screening_method:=supplied;
      when 'screenedByName' then item.screened_by_name:=supplied;
      when 'agentReference' then item.agent_reference:=supplied;
      when 'sourceReference' then item.source_reference:=supplied;
      when 'notes' then item.notes:=supplied;
      when 'recordStatus' then
        if supplied is null or supplied not in ('recorded','voided') or (is_new and supplied<>'recorded') then
          raise exception 'Record supplied evidence or void an existing entry.' using errcode='22023'; end if;
        item.record_status:=supplied;
    end case;
  end loop;
  if item.source_reference is null or (item.security_status is null and item.screening_method is null and item.screened_at is null) then
    raise exception 'Record the source and at least one supplied status, method or screening time. This is not clearance.' using errcode='22023'; end if;
  if item.record_status='voided' and changes<>'{"recordStatus":"voided"}'::jsonb then
    raise exception 'Void the retained entry without rewriting its supplied evidence.' using errcode='22023'; end if;
  before_values:=case when is_new then null else booking_api.cargo_security_evidence_values(previous) end;
  if not is_new and before_values=booking_api.cargo_security_evidence_values(item) then return before_values; end if;
  item.updated_at:=clock_timestamp(); item.updated_by:=actor."User_ID";
  if is_new then insert into booking_api.cargo_security_evidence select (item).*;
  else
    update booking_api.cargo_security_evidence set record_status=item.record_status,security_status=item.security_status,
      screening_method=item.screening_method,screened_by_name=item.screened_by_name,agent_reference=item.agent_reference,
      screened_at=item.screened_at,source_reference=item.source_reference,notes=item.notes,
      updated_at=item.updated_at,updated_by=item.updated_by where id=record_id;
  end if;
  update public."Job_Header" set "Job_UpdatedAt"=item.updated_at,"Job_UpdatedBy"=actor."User_ID" where "Job_ID"=requested_job_id;
  after_values:=booking_api.cargo_security_evidence_values(item);
  insert into booking_api.events(company_id,job_id,event_type,summary,metadata,actor_user_id)
    values(actor."Company_ID",requested_job_id,'cargo_security_evidence_recorded',
      case when is_new then 'Screening evidence recorded' when item.record_status='voided' then 'Screening evidence voided'
        else 'Screening evidence corrected' end,
      jsonb_build_object('cargoId',cargo_id,'evidenceId',record_id,'before',before_values,'after',after_values,
        'reason',payload->>'reason','source','operator'),actor."User_ID");
  return after_values;
end $_$;


ALTER FUNCTION "booking_api"."save_cargo_security_evidence"("caller_auth_user_id" "uuid", "requested_job_id" "uuid", "payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."save_job_customs_draft"("caller_auth_user_id" "uuid", "p_declaration_id" "uuid", "p_draft" "jsonb") RETURNS TABLE("declaration_id" "uuid", "local_reference_number" "text", "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  auth_user_id uuid := caller_auth_user_id;
  declaration_row record;
  updated_at_value timestamptz := clock_timestamp();
begin
  if auth_user_id is null then raise exception 'Authentication is required to save a Customs draft.' using errcode='42501'; end if;
  if p_declaration_id is null or p_draft is null or jsonb_typeof(p_draft)<>'object' then raise exception 'A valid job-related Customs draft is required.' using errcode='22023'; end if;
  if jsonb_typeof(coalesce(p_draft->'items','[]'::jsonb))<>'array' then raise exception 'Customs draft items must be an array.' using errcode='22023'; end if;
  select declaration.* into declaration_row from public."Customs_Declarations" declaration
  where declaration."CUST_id"=p_declaration_id and declaration."CUST_JobID" is not null and declaration."CUST_Status"='draft'
    and declaration."CUST_Direction" in ('import','export') and declaration."CUST_DeclarationKind"='cds_'||declaration."CUST_Direction"
    and not declaration."CUST_IsDeleted" for update;
  if not found or not booking_api.customs_access(auth_user_id,p_declaration_id,true) then raise exception 'This Customs draft is unavailable or can no longer be edited.' using errcode='42501'; end if;
  if coalesce(p_draft->>'direction',declaration_row."CUST_Direction")<>declaration_row."CUST_Direction" then raise exception 'The declaration direction cannot be changed.' using errcode='22023'; end if;

  update public."Customs_Declarations" set
    "CUST_UCR"=nullif(btrim(p_draft->>'ucn'),''), "CUST_TraderReference"=nullif(btrim(p_draft->>'traderReference'),''),
    "CUST_DeclarantIdentifierSnapshot"=nullif(btrim(p_draft->>'declarant'),''),
    "CUST_ImporterIdentifierSnapshot"=nullif(btrim(p_draft->>'importer'),''),
    "CUST_ExporterIdentifierSnapshot"=nullif(btrim(p_draft->>'exporter'),''),
    "CUST_RepresentativeIdentifierSnapshot"=nullif(btrim(p_draft->>'representative'),''),
    "CUST_CustomsOfficeOfEntry"=case when declaration_row."CUST_Direction"='import' then nullif(btrim(p_draft->>'presentationOffice'),'') else "CUST_CustomsOfficeOfEntry" end,
    "CUST_CustomsOfficeOfExit"=case when declaration_row."CUST_Direction"='export' then nullif(btrim(p_draft->>'exitOffice'),'') else "CUST_CustomsOfficeOfExit" end,
    "CUST_GoodsLocationCode"=nullif(btrim(p_draft->>'goodsLocationIdentifier'),''),
    "CUST_CountryOfDispatchCodeSnapshot"=nullif(btrim(p_draft->>'exportCountry'),''),
    "CUST_CountryOfDestinationCodeSnapshot"=nullif(btrim(p_draft->>'destinationCountry'),''),
    "CUST_TotalPackages"=case when coalesce(p_draft->>'totalPackages','')~'^\d+$' then (p_draft->>'totalPackages')::integer end,
    "CUST_GrossMass"=case when coalesce(p_draft->>'totalGrossMass','')~'^\d+(\.\d+)?$' then (p_draft->>'totalGrossMass')::numeric end,
    "CUST_InvoiceAmount"=case when coalesce(p_draft->>'totalAmount','')~'^\d+(\.\d+)?$' then (p_draft->>'totalAmount')::numeric end,
    "CUST_InvoiceCurrencyCodeSnapshot"=nullif(btrim(p_draft->>'currency'),''),
    "CUST_IncotermsCode"=nullif(btrim(p_draft->>'tradeTerms'),''),
    "CUST_GenericPayloadJSON"=p_draft,"CUST_Status"='draft',"CUST_UpdatedAt"=updated_at_value,"CUST_UpdatedBy"=auth_user_id
  where "CUST_id"=p_declaration_id;
  delete from public."Customs_Items" where "CUSTI_CustomsID"=p_declaration_id;
  insert into public."Customs_Items" (
    "CUSTI_CustomsID","CUSTI_ItemNumber","CUSTI_CommodityCode","CUSTI_DescriptionOfGoods",
    "CUSTI_CountryOfOriginCodeSnapshot","CUSTI_CountryOfDestinationCodeSnapshot","CUSTI_NetMass","CUSTI_GrossMass",
    "CUSTI_SupplementaryUnits","CUSTI_ItemValueAmount","CUSTI_ItemValueCurrencyCodeSnapshot","CUSTI_ProcedureCode",
    "CUSTI_AdditionalProcedureCodesJSON","CUSTI_ItemPayloadJSON","CUSTI_JobCargoID"
  ) select p_declaration_id,item.ordinality::integer,nullif(btrim(item.value->>'commodityCode'),''),coalesce(item.value->>'description',''),
    nullif(btrim(item.value->>'nonPreferentialOrigin'),''),nullif(btrim(coalesce(item.value->>'destinationCountry',p_draft->>'destinationCountry')),''),
    case when coalesce(item.value->>'netMass','')~'^\d+(\.\d+)?$' then (item.value->>'netMass')::numeric end,
    case when coalesce(item.value->>'grossMass','')~'^\d+(\.\d+)?$' then (item.value->>'grossMass')::numeric end,
    case when coalesce(item.value->>'tariffQuantity','')~'^\d+(\.\d+)?$' then (item.value->>'tariffQuantity')::numeric end,
    case when coalesce(item.value->>'itemPrice','')~'^\d+(\.\d+)?$' then (item.value->>'itemPrice')::numeric end,
    nullif(btrim(item.value->>'currency'),''),nullif(btrim(item.value->>'procedureCode'),''),
    case when nullif(btrim(item.value->>'additionalProcedureCode'),'') is null then '[]'::jsonb else jsonb_build_array(item.value->>'additionalProcedureCode') end,
    item.value,nullif(item.value->>'sourceJobCargoId','')::uuid
  from jsonb_array_elements(coalesce(p_draft->'items','[]'::jsonb)) with ordinality item(value,ordinality);
  return query select p_declaration_id,declaration_row."CUST_LocalReferenceNumber"::text,updated_at_value;
end;
$_$;


ALTER FUNCTION "booking_api"."save_job_customs_draft"("caller_auth_user_id" "uuid", "p_declaration_id" "uuid", "p_draft" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."save_operational_booking"("caller_auth_user_id" "uuid", "requested_job_id" "uuid", "payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  app_user record;
  job_row record;
  route_id uuid;
  container_id_value uuid;
  line jsonb;
  line_number integer := 0;
  saved jsonb;
begin
  if caller_auth_user_id is null or not booking_api.has_permission(caller_auth_user_id, 'Bookings.Write') then
    raise exception 'Booking changes are not authorised.' using errcode = '42501';
  end if;
  select actor."User_ID", actor."Company_ID" into strict app_user
  from public."cmp_Users" actor
  where actor."Auth_User_ID" = caller_auth_user_id and actor."User_AccessStatus" = 'active';
  select job.* into job_row from public."Job_Header" job
  join public."cmp_Offices" office on office."Office_ID" = coalesce(job."Job_OrgOfficeID", job."Job_OfficeID")
  where job."Job_ID" = requested_job_id and office."Company_ID" = app_user."Company_ID" and not job."Job_IsDeleted"
  for update;
  if not found then raise exception 'That booking is outside this workspace.' using errcode = '42501'; end if;
  if job_row."Job_Status" in ('ready_for_invoice','complete') then
    raise exception 'This booking is locked. Reopen it before making operational changes.' using errcode = '22023';
  end if;

  saved := booking_api.save_booking(caller_auth_user_id, requested_job_id, payload);

  update public."Job_Header" job set
    "Job_CustomerReference" = case when payload ? 'customerReference' then left(nullif(btrim(payload->>'customerReference'), ''), 180) else job."Job_CustomerReference" end,
    "Job_SupplierReference" = case when payload ? 'supplierReference' then left(nullif(btrim(payload->>'supplierReference'), ''), 180) else job."Job_SupplierReference" end,
    "Job_OperationsOwnerID" = case when payload ? 'operationsOwnerId' then nullif(payload->>'operationsOwnerId', '')::uuid else job."Job_OperationsOwnerID" end,
    "Job_CustomerNotes" = case when payload ? 'customerNotes' then nullif(btrim(payload->>'customerNotes'), '') else job."Job_CustomerNotes" end,
    "Job_TermsConditions" = case when payload ? 'terms' then nullif(btrim(payload->>'terms'), '') else job."Job_TermsConditions" end,
    "Job_SubjectToTerms" = case when payload ? 'subjectToTerms' then nullif(btrim(payload->>'subjectToTerms'), '') else job."Job_SubjectToTerms" end,
    "Job_InvoiceReference" = case when payload ? 'invoiceReference' then left(nullif(btrim(payload->>'invoiceReference'), ''), 180) else job."Job_InvoiceReference" end,
    "Job_InvoiceStatus" = case when payload ? 'invoiceStatus' then lower(nullif(btrim(payload->>'invoiceStatus'), '')) else job."Job_InvoiceStatus" end,
    "Job_UpdatedAt" = now(), "Job_UpdatedBy" = app_user."User_ID"
  where job."Job_ID" = requested_job_id;

  if payload ? 'route' and jsonb_typeof(payload->'route') = 'object' then
    select route."JobRoute_ID" into route_id from public."Job_Routing" route
    where route."Job_ID" = requested_job_id order by route."JobRoute_IsMainCarriage" desc, route."JobRoute_OrderNo" nulls last limit 1;
    update public."Job_Routing" route set
      "JobRoute_Status" = case when payload#>>'{route,status}' is not null then coalesce(nullif(btrim(payload#>>'{route,status}'), ''), route."JobRoute_Status") else route."JobRoute_Status" end,
      "JobRoute_OriginTerminal" = case when payload#>>'{route,originTerminal}' is not null then nullif(btrim(payload#>>'{route,originTerminal}'), '') else route."JobRoute_OriginTerminal" end,
      "JobRoute_DestinationTerminal" = case when payload#>>'{route,destinationTerminal}' is not null then nullif(btrim(payload#>>'{route,destinationTerminal}'), '') else route."JobRoute_DestinationTerminal" end,
      "JobRoute_EstimatedPickupAt" = case when payload#>>'{route,estimatedPickupAt}' is not null then nullif(payload#>>'{route,estimatedPickupAt}', '')::timestamptz else route."JobRoute_EstimatedPickupAt" end,
      "JobRoute_ActualPickupAt" = case when payload#>>'{route,actualPickupAt}' is not null then nullif(payload#>>'{route,actualPickupAt}', '')::timestamptz else route."JobRoute_ActualPickupAt" end,
      "JobRoute_EstimatedDepartureAt" = case when payload#>>'{route,estimatedDepartureAt}' is not null then nullif(payload#>>'{route,estimatedDepartureAt}', '')::timestamptz else route."JobRoute_EstimatedDepartureAt" end,
      "JobRoute_ActualDepartureAt" = case when payload#>>'{route,actualDepartureAt}' is not null then nullif(payload#>>'{route,actualDepartureAt}', '')::timestamptz else route."JobRoute_ActualDepartureAt" end,
      "JobRoute_EstimatedArrivalAt" = case when payload#>>'{route,estimatedArrivalAt}' is not null then nullif(payload#>>'{route,estimatedArrivalAt}', '')::timestamptz else route."JobRoute_EstimatedArrivalAt" end,
      "JobRoute_ActualArrivalAt" = case when payload#>>'{route,actualArrivalAt}' is not null then nullif(payload#>>'{route,actualArrivalAt}', '')::timestamptz else route."JobRoute_ActualArrivalAt" end,
      "JobRoute_EstimatedDeliveryAt" = case when payload#>>'{route,estimatedDeliveryAt}' is not null then nullif(payload#>>'{route,estimatedDeliveryAt}', '')::timestamptz else route."JobRoute_EstimatedDeliveryAt" end,
      "JobRoute_ActualDeliveryAt" = case when payload#>>'{route,actualDeliveryAt}' is not null then nullif(payload#>>'{route,actualDeliveryAt}', '')::timestamptz else route."JobRoute_ActualDeliveryAt" end,
      "JobRoute_InternalNotes" = case when payload#>>'{route,internalNotes}' is not null then nullif(btrim(payload#>>'{route,internalNotes}'), '') else route."JobRoute_InternalNotes" end,
      "JobRoute_UpdatedAt" = now(), "JobRoute_UpdatedBy" = app_user."User_ID"
    where route."JobRoute_ID" = route_id;
  end if;

  -- The canonical saver replaces container rows. Promote the extended values
  -- preserved in each row's JSON back into their typed operational columns.
  update public."Job_Containers" container set
    "JobContainer_TareKilos" = nullif(container."JobContainer_JSON"->>'tareWeightKg', '')::numeric,
    "JobContainer_VGMKilos" = nullif(container."JobContainer_JSON"->>'vgmWeightKg', '')::numeric,
    "JobContainer_VGMMethod" = left(nullif(btrim(container."JobContainer_JSON"->>'vgmMethod'), ''), 40),
    "JobContainer_ReeferSetPoint" = nullif(container."JobContainer_JSON"->>'reeferSetPoint', '')::numeric,
    "JobContainer_ReeferUnit" = left(nullif(btrim(container."JobContainer_JSON"->>'reeferUnit'), ''), 10),
    "JobContainer_IsShipperOwned" = nullif(container."JobContainer_JSON"->>'isShipperOwned', '')::boolean
  where container."Job_ID" = requested_job_id and not container."JobContainer_IsDeleted";

  if payload ? 'containers' then
    delete from public."Job_ContainerSeals" seal
    using public."Job_Containers" container
    where seal."JobContainerSeal_JobContainerID" = container."JobContainers_ID" and container."Job_ID" = requested_job_id;
    for line in select value || jsonb_build_object('_ordinal', ordinality)
      from jsonb_array_elements(payload->'containers') with ordinality
    loop
      select container."JobContainers_ID" into container_id_value
      from public."Job_Containers" container
      where container."Job_ID" = requested_job_id and not container."JobContainer_IsDeleted"
      order by container."JobContainer_CreatedAt", container."JobContainers_ID"
      offset greatest((line->>'_ordinal')::integer - 1, 0) limit 1;
      if container_id_value is not null and nullif(btrim(line->>'sealNumber'), '') is not null then
        insert into public."Job_ContainerSeals" ("JobContainerSeal_JobContainerID", "JobContainerSeal_Number", "JobContainerSeal_Type")
        values (container_id_value, left(btrim(line->>'sealNumber'), 80), 'carrier');
      end if;
    end loop;
  end if;

  if payload ? 'charges' then
    if jsonb_typeof(payload->'charges') <> 'array' or jsonb_array_length(payload->'charges') > 300 then
      raise exception 'Booking finance lines are invalid.' using errcode = '22023';
    end if;
    delete from public."Job_Costing_Lines" where "Job_ID" = requested_job_id;
    for line in select value from jsonb_array_elements(payload->'charges') loop
      if nullif(btrim(line->>'description'), '') is not null then
        line_number := line_number + 1;
        insert into public."Job_Costing_Lines" (
          "Job_ID", "JobCostingLine_Number", "JobCostingLine_SupplierID", "JobCostingLine_Description",
          "JobCostingLine_InternalNotes", "JobCostingLine_CustomerNotes", "JobCostingLine_CostROE",
          "JobCostingLine_CostAmountCurrency", "JobCostingLine_CostAmountLocal", "JobCostingLine_RevenueROE",
          "JobCostingLine_RevenueAmountCurrency", "JobCostingLine_RevenueAmountLocal", "JobCostingLine_ShowToCustomer",
          "JobCostingLine_CreatedBy", "JobCostingLine_UpdatedBy"
        ) values (
          requested_job_id, line_number, nullif(line->>'supplierId', '')::uuid, left(btrim(line->>'description'), 240),
          nullif(btrim(line->>'internalNotes'), ''), nullif(btrim(line->>'customerNotes'), ''),
          greatest(coalesce(nullif(line->>'costRoe', '')::numeric, 1), 0.00001), coalesce(nullif(line->>'costAmount', '')::numeric, 0),
          coalesce(nullif(line->>'costLocal', '')::numeric, nullif(line->>'costAmount', '')::numeric, 0),
          greatest(coalesce(nullif(line->>'sellRoe', '')::numeric, 1), 0.00001), coalesce(nullif(line->>'sellAmount', '')::numeric, 0),
          coalesce(nullif(line->>'sellLocal', '')::numeric, nullif(line->>'sellAmount', '')::numeric, 0),
          coalesce((line->>'showToCustomer')::boolean, true), app_user."User_ID", app_user."User_ID"
        );
      end if;
    end loop;
  end if;

  return booking_api.operational_workspace(caller_auth_user_id, job_row."Job_BookingReference");
exception
  when no_data_found or too_many_rows then raise exception 'Your workspace identity is incomplete.' using errcode = '42501';
end;
$$;


ALTER FUNCTION "booking_api"."save_operational_booking"("caller_auth_user_id" "uuid", "requested_job_id" "uuid", "payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."save_route_milestone"("caller_auth_user_id" "uuid", "requested_job_id" "uuid", "payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    SET "TimeZone" TO 'UTC'
    AS $_$
declare
  actor record; job_row public."Job_Header"; route_row public."Job_Routing";
  before_row public."Job_RouteMilestones"; item public."Job_RouteMilestones";
  milestone_id uuid; route_id uuid; changes jsonb; key text; value jsonb; text_value text; stamp timestamptz;
  is_new boolean; before_values jsonb; after_values jsonb;
begin
  select "User_ID", "Company_ID" into actor from public."cmp_Users"
  where "Auth_User_ID" = caller_auth_user_id and "User_AccessStatus" = 'active';
  if not found or booking_api.has_permission(caller_auth_user_id, 'Bookings.Read') is not true
    or booking_api.has_permission(caller_auth_user_id, 'Bookings.Write') is not true then
    raise exception 'You do not have permission to record Booking milestones.' using errcode = '42501'; end if;
  if jsonb_typeof(payload) is distinct from 'object'
    or not (payload ?& array['id','routeId','expectedUpdatedAt','expectedRouteUpdatedAt','expectedMilestoneUpdatedAt','changes','reason'])
    or exists(select 1 from jsonb_object_keys(payload) k where k not in
      ('id','routeId','expectedUpdatedAt','expectedRouteUpdatedAt','expectedMilestoneUpdatedAt','type','changes','reason'))
    or jsonb_typeof(payload->'reason') is distinct from 'string'
    or nullif(btrim(payload->>'reason'), '') is null or length(payload->>'reason') > 2000
    or jsonb_typeof(payload->'changes') is distinct from 'object' then
    raise exception 'Choose an exact milestone and provide its changes and reason.' using errcode = '22023'; end if;
  if jsonb_typeof(payload->'id') is distinct from 'string' or jsonb_typeof(payload->'routeId') is distinct from 'string'
    or payload->>'id' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    or payload->>'routeId' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    raise exception 'Choose valid milestone and routing leg identities.' using errcode = '22023'; end if;
  milestone_id := (payload->>'id')::uuid; route_id := (payload->>'routeId')::uuid;
  if milestone_id is null or route_id is null then
    raise exception 'Milestone and routing leg identities are required.' using errcode = '22023'; end if;
  changes := payload->'changes';
  if changes = '{}'::jsonb or exists(select 1 from jsonb_object_keys(changes) k where k not in
    ('status','plannedAt','estimatedAt','actualAt','locationUnlocode','location','externalReference','notes')) then
    raise exception 'That milestone field is not available for editing.' using errcode = '22023'; end if;
  select j.* into job_row from public."Job_Header" j
    join public."cmp_Offices" o on o."Office_ID" = coalesce(j."Job_OrgOfficeID", j."Job_OfficeID")
    where j."Job_ID" = requested_job_id and o."Company_ID" = actor."Company_ID" and not j."Job_IsDeleted" for update of j;
  if not found then raise exception 'That Booking is outside this workspace.' using errcode = '42501'; end if;
  select * into route_row from public."Job_Routing"
    where "JobRoute_ID" = route_id and "Job_ID" = requested_job_id for update;
  if not found then raise exception 'Choose a routing leg from this Booking.' using errcode = '42501'; end if;
  if booking_api.parse_milestone_time(payload->'expectedUpdatedAt') is null
    or job_row."Job_UpdatedAt" is distinct from booking_api.parse_milestone_time(payload->'expectedUpdatedAt')
    or booking_api.parse_milestone_time(payload->'expectedRouteUpdatedAt') is null
    or route_row."JobRoute_UpdatedAt" is distinct from booking_api.parse_milestone_time(payload->'expectedRouteUpdatedAt') then
    raise exception 'The Booking or leg changed. Reload before recording this milestone.' using errcode = 'PT409'; end if;
  select * into before_row from public."Job_RouteMilestones" where "JobRouteMilestone_ID" = milestone_id for update;
  is_new := not found;
  if is_new then
    if payload->'expectedMilestoneUpdatedAt' <> 'null'::jsonb then
      raise exception 'That milestone no longer exists. Reload the Booking.' using errcode = 'PT409'; end if;
    if jsonb_typeof(payload->'type') is distinct from 'string' or not exists (
      select 1 from public."sys_JobMilestoneTypes" where "JMT_Code" = payload->>'type' and "JMT_IsActive" and "JMT_Code" <> 'customs_released') then
      raise exception 'Choose an active operational milestone. Customs release is not available here.' using errcode = '22023'; end if;
    item."JobRouteMilestone_ID" := milestone_id; item."JobRouteMilestone_JobRouteID" := route_id;
    item."JobRouteMilestone_Type" := payload->>'type'; item."JobRouteMilestone_Status" := 'planned';
    item."JobRouteMilestone_Source" := 'operator'; item."JobRouteMilestone_PayloadJSON" := '{}';
    item."JobRouteMilestone_CreatedBy" := actor."User_ID"; item."JobRouteMilestone_CreatedAt" := clock_timestamp();
    item."JobRouteMilestone_RecordedMode" := route_row."JobRoute_ModeCode";
  else
    if before_row."JobRouteMilestone_JobRouteID" <> route_id
      or before_row."JobRouteMilestone_Source" is distinct from 'operator'
      or before_row."JobRouteMilestone_CreatedBy" is null
      or before_row."JobRouteMilestone_TrackingEventID" is not null
      or before_row."JobRouteMilestone_Type" = 'customs_released' then
      raise exception 'That milestone is outside this editable operational evidence.' using errcode = '42501'; end if;
    if before_row."JobRouteMilestone_UpdatedAt" is distinct from booking_api.parse_milestone_time(payload->'expectedMilestoneUpdatedAt') then
      raise exception 'This milestone changed. Reload before making a correction.' using errcode = 'PT409'; end if;
    if (payload ? 'type' and payload->>'type' is distinct from before_row."JobRouteMilestone_Type")
      or before_row."JobRouteMilestone_Status" = 'voided' then
      raise exception 'Keep the original evidence. Record a new milestone instead.' using errcode = '22023'; end if;
    if before_row."JobRouteMilestone_RecordedMode" is distinct from route_row."JobRoute_ModeCode"
      and changes <> '{"status":"voided"}'::jsonb then
      raise exception 'The leg mode changed. Retain or void the old evidence and record a new milestone.' using errcode = '22023'; end if;
    item := before_row;
  end if;
  for key, value in select * from jsonb_each(changes) loop
    if jsonb_typeof(value) not in ('string','null') then
      raise exception 'Milestone values must be text or an explicit clear.' using errcode = '22023'; end if;
    text_value := nullif(btrim(value #>> '{}'), '');
    if key in ('plannedAt','estimatedAt','actualAt') then
      stamp := booking_api.parse_milestone_time(value);
      if key = 'plannedAt' then item."JobRouteMilestone_PlannedAt" := stamp;
      elsif key = 'estimatedAt' then item."JobRouteMilestone_EstimatedAt" := stamp;
      else item."JobRouteMilestone_ActualAt" := stamp; end if;
    elsif key = 'status' then
      if text_value is null or text_value not in ('planned','completed','exception','voided') then
        raise exception 'Choose Planned, Completed, Exception or Voided.' using errcode = '22023'; end if;
      item."JobRouteMilestone_Status" := text_value;
    else
      if length(text_value) > (case when key = 'locationUnlocode' then 10 when key = 'notes' then 8000 else 180 end) then
        raise exception 'That milestone value exceeds its supported length.' using errcode = '22023'; end if;
      case key
        when 'locationUnlocode' then item."JobRouteMilestone_LocationUNLocode" := upper(text_value);
        when 'location' then item."JobRouteMilestone_LocationNameSnapshot" := text_value;
        when 'externalReference' then item."JobRouteMilestone_ExternalReference" := text_value;
        when 'notes' then item."JobRouteMilestone_Notes" := text_value;
      end case;
    end if;
  end loop;
  if item."JobRouteMilestone_Status" = 'completed' and item."JobRouteMilestone_ActualAt" is null then
    raise exception 'A completed milestone needs its actual event time.' using errcode = '22023'; end if;
  if is_new and item."JobRouteMilestone_Status" = 'voided' then
    raise exception 'Record a milestone before voiding it.' using errcode = '22023'; end if;
  before_values := case when is_new then '{}'::jsonb else booking_api.route_milestone_values(before_row) end;
  if not is_new and booking_api.route_milestone_values(item) = before_values then return before_values; end if;
  item."JobRouteMilestone_UpdatedBy" := actor."User_ID";
  item."JobRouteMilestone_UpdatedAt" := clock_timestamp();
  if is_new then
    insert into public."Job_RouteMilestones" select (item).*;
  else
    update public."Job_RouteMilestones" set
      "JobRouteMilestone_Status" = item."JobRouteMilestone_Status",
      "JobRouteMilestone_PlannedAt" = item."JobRouteMilestone_PlannedAt",
      "JobRouteMilestone_EstimatedAt" = item."JobRouteMilestone_EstimatedAt",
      "JobRouteMilestone_ActualAt" = item."JobRouteMilestone_ActualAt",
      "JobRouteMilestone_LocationUNLocode" = item."JobRouteMilestone_LocationUNLocode",
      "JobRouteMilestone_LocationNameSnapshot" = item."JobRouteMilestone_LocationNameSnapshot",
      "JobRouteMilestone_ExternalReference" = item."JobRouteMilestone_ExternalReference",
      "JobRouteMilestone_Notes" = item."JobRouteMilestone_Notes",
      "JobRouteMilestone_UpdatedBy" = item."JobRouteMilestone_UpdatedBy",
      "JobRouteMilestone_UpdatedAt" = item."JobRouteMilestone_UpdatedAt"
    where "JobRouteMilestone_ID" = milestone_id;
  end if;
  update public."Job_Header" set "Job_UpdatedAt" = item."JobRouteMilestone_UpdatedAt", "Job_UpdatedBy" = actor."User_ID"
    where "Job_ID" = requested_job_id;
  after_values := booking_api.route_milestone_values(item);
  insert into booking_api.events(company_id, job_id, event_type, summary, metadata, actor_user_id)
    values(actor."Company_ID", requested_job_id, 'route_milestone_recorded',
      case when is_new then 'Routing milestone recorded' else 'Routing milestone corrected' end,
      jsonb_build_object('routeId', route_id, 'milestoneId', milestone_id, 'before', before_values, 'after', after_values,
        'reason', btrim(payload->>'reason'), 'source', 'operator'), actor."User_ID");
  return after_values;
end $_$;


ALTER FUNCTION "booking_api"."save_route_milestone"("caller_auth_user_id" "uuid", "requested_job_id" "uuid", "payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."secure_dexter_route_mode_proposal"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare review jsonb;
begin
  if tg_op='UPDATE' then
    if old."AIDexterPrepared_ActionCode"='change_booking_route_mode' or new."AIDexterPrepared_ActionCode"='change_booking_route_mode' then
      if row(old."AIDexterPrepared_ActionCode",old."AIDexterPrepared_ArgumentsJSON",old."AIDexterPrepared_Title",old."AIDexterPrepared_Description",old."AIDexterPrepared_ChangesJSON",old."AIDexterPrepared_CompanyID",old."AIDexterPrepared_UserID",old."AIDexterPrepared_TargetID",old."AIDexterPrepared_TargetJSON",
          old."AIDexterPrepared_ConversationID",old."AIDexterPrepared_ClientSessionID",old."AIDexterPrepared_IntentID",old."AIDexterPrepared_GrantID",old."AIDexterPrepared_AccessMode")
        is distinct from row(new."AIDexterPrepared_ActionCode",new."AIDexterPrepared_ArgumentsJSON",new."AIDexterPrepared_Title",new."AIDexterPrepared_Description",new."AIDexterPrepared_ChangesJSON",new."AIDexterPrepared_CompanyID",new."AIDexterPrepared_UserID",new."AIDexterPrepared_TargetID",new."AIDexterPrepared_TargetJSON",
          new."AIDexterPrepared_ConversationID",new."AIDexterPrepared_ClientSessionID",new."AIDexterPrepared_IntentID",new."AIDexterPrepared_GrantID",new."AIDexterPrepared_AccessMode") then
        raise exception 'A routing mode review cannot be changed after preparation. Create a fresh proposal.' using errcode='42501';end if;
    end if;
    return new;
  end if;
  if new."AIDexterPrepared_ActionCode"<>'change_booking_route_mode' then return new;end if;
  review:=booking_api.dexter_route_mode_review(new."AIDexterPrepared_CompanyID",new."AIDexterPrepared_UserID",new."AIDexterPrepared_ArgumentsJSON");
  new."AIDexterPrepared_ArgumentsJSON":=review->'arguments';
  new."AIDexterPrepared_Title":=review->>'title';new."AIDexterPrepared_Description":=review->>'description';new."AIDexterPrepared_ChangesJSON":=review->'changes';
  new."AIDexterPrepared_TargetID":=(review#>>'{arguments,target_id}')::uuid;
  new."AIDexterPrepared_TargetJSON":=jsonb_build_object('recordId',review#>>'{arguments,target_id}','recordIds',jsonb_build_array(review#>>'{arguments,target_id}',review#>>'{arguments,route_id}'));
  return new;
end $$;


ALTER FUNCTION "booking_api"."secure_dexter_route_mode_proposal"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."send_to_customs"("caller_auth_user_id" "uuid", "requested_job_id" "uuid", "requested_idempotency_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  app_user record;
  job_row record;
  readiness jsonb;
  direction_value text;
  mode_value text;
  customs_mode_code text;
  department_id_value uuid;
  declaration_id uuid;
  declaration_reference text;
  existing_declaration record;
  exporter_row record;
  importer_row record;
  route_row record;
  container_row record;
  commercial_invoice_id uuid;
  packing_list_id uuid;
  exporter_identifier text;
  importer_identifier text;
  total_packages numeric;
  total_gross numeric;
  total_net numeric;
  payload jsonb;
  items jsonb;
  source_snapshot jsonb;
  sender_name text;
  recipient record;
  assigned_user_id uuid;
begin
  if caller_auth_user_id is null or not booking_api.has_permission(caller_auth_user_id, 'Bookings.Write') then
    raise exception 'Sending a booking to Customs is not authorised.' using errcode = '42501';
  end if;
  if requested_idempotency_key is null then raise exception 'A Customs handoff request key is required.' using errcode = '22023'; end if;
  select "User_ID", "Company_ID", "User_Firstname", "User_Lastname" into strict app_user
  from public."cmp_Users" where "Auth_User_ID" = caller_auth_user_id and "User_AccessStatus" = 'active';
  sender_name := nullif(concat_ws(' ', app_user."User_Firstname", app_user."User_Lastname"), '');
  sender_name := coalesce(sender_name, 'A Multideck user');
  select job.* into job_row
  from public."Job_Header" job
  join public."cmp_Offices" office on office."Office_ID" = coalesce(job."Job_OrgOfficeID", job."Job_OfficeID")
  where job."Job_ID" = requested_job_id and office."Company_ID" = app_user."Company_ID" and not job."Job_IsDeleted"
  for update;
  if not found then raise exception 'That booking is outside this workspace.' using errcode = '42501'; end if;

  select declaration.* into existing_declaration
  from public."Customs_Declarations" declaration
  left join public."sys_CustomsDeclarationStatuses" status on status."CDST_Code" = declaration."CUST_Status"
  where declaration."CUST_JobID" = requested_job_id and not declaration."CUST_IsDeleted"
    and (declaration."CUST_HandoffIdempotencyKey" = requested_idempotency_key or not coalesce(status."CDST_IsFinal", false))
  order by (declaration."CUST_HandoffIdempotencyKey" = requested_idempotency_key) desc, declaration."CUST_CreatedAt" desc limit 1;
  if found then
    insert into booking_api.customs_declaration_grants (
      declaration_id, user_id, can_write, reason
    ) values (
      existing_declaration."CUST_id", app_user."User_ID", true, 'booking_handoff_initiator'
    )
    on conflict (declaration_id, user_id) do update
      set can_write = true,
          reason = excluded.reason;

    return jsonb_build_object(
      'declarationId', existing_declaration."CUST_id",
      'reference', existing_declaration."CUST_LocalReferenceNumber",
      'direction', existing_declaration."CUST_Direction",
      'route', '/customs/job-related/' || existing_declaration."CUST_Direction" || '/' || existing_declaration."CUST_id",
      'canOpen', booking_api.customs_access(caller_auth_user_id, existing_declaration."CUST_id", false),
      'reused', true
    );
  end if;

  readiness := booking_api.customs_readiness(caller_auth_user_id, requested_job_id);
  if not coalesce((readiness->>'eligible')::boolean, false) then
    raise exception 'This booking is not eligible for a UK import or export Customs handoff.' using errcode = '22023';
  end if;
  if not coalesce((readiness->>'ready')::boolean, false) then
    raise exception 'Complete the required Customs fields before sending this booking.' using errcode = '22023', detail = readiness::text;
  end if;
  direction_value := readiness->>'direction';
  mode_value := lower(btrim(coalesce(job_row."Job_TransportModeSummary", '')));
  select nullif(btrim(mode."JTM_CustomsTransportModeCode"), '')
  into customs_mode_code
  from public."sys_JobTransportModes" mode
  where mode."JTM_IsActive"
    and (
      lower(mode."JTM_Code") = mode_value
      or lower(mode."JTM_Name") = mode_value
    )
  order by mode."JTM_SortOrder", mode."JTM_Code"
  limit 1;
  customs_mode_code := coalesce(
    customs_mode_code,
    case mode_value
      when 'sea' then '1'
      when 'rail' then '2'
      when 'road' then '3'
      when 'air' then '4'
      when 'courier' then '4'
      else null
    end
  );
  department_id_value := booking_api.resolve_customs_department(
    app_user."Company_ID", coalesce(job_row."Job_OrgOfficeID", job_row."Job_OfficeID"), app_user."User_ID"
  );
  -- The operator handing the booking off owns the initial review and can edit
  -- the declaration they create without receiving tenant-wide Customs access.
  assigned_user_id := app_user."User_ID";

  select party.* into exporter_row from public."Job_Parties" party
  where party."JobParty_JobID" = requested_job_id and lower(party."JobParty_Role") in ('exporter','shipper','consignor')
  order by party."JobParty_IsPrimary" desc, party."JobParty_Sequence" limit 1;
  select party.* into importer_row from public."Job_Parties" party
  where party."JobParty_JobID" = requested_job_id and lower(party."JobParty_Role") in ('importer','consignee')
  order by party."JobParty_IsPrimary" desc, party."JobParty_Sequence" limit 1;
  exporter_identifier := readiness#>>'{evidence,exporterIdentifier}';
  importer_identifier := readiness#>>'{evidence,importerIdentifier}';
  commercial_invoice_id := nullif(readiness#>>'{evidence,commercialInvoiceDocumentId}', '')::uuid;
  packing_list_id := nullif(readiness#>>'{evidence,packingListDocumentId}', '')::uuid;
  select route.* into route_row from public."Job_Routing" route where route."Job_ID" = requested_job_id
  order by route."JobRoute_IsMainCarriage" desc, route."JobRoute_OrderNo" nulls last limit 1;
  select container.* into container_row from public."Job_Containers" container where container."Job_ID" = requested_job_id and not container."JobContainer_IsDeleted"
  order by container."JobContainer_CreatedAt" limit 1;
  select coalesce(sum(coalesce(cargo."JobCargo_PackageQty", cargo."JobCargo_Qty")),0),
    coalesce(sum(cargo."JobCargo_GrossKilos"),0), coalesce(sum(cargo."JobCargo_NettKilos"),0),
    coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
      'id', 'item-' || coalesce(cargo."JobCargo_LineNo", 1),
      'commodityCode', cargo."JobCargo_HSCode", 'description', cargo."JobCargo_Description",
      'packageKind', cargo."JobCargo_PackageTypeCodeSnapshot",
      'packageCount', coalesce(cargo."JobCargo_PackageQty", cargo."JobCargo_Qty")::text,
      'grossMass', cargo."JobCargo_GrossKilos"::text, 'netMass', cargo."JobCargo_NettKilos"::text,
      'itemPrice', cargo."JobCargo_DeclaredValueAmount"::text,
      'currency', cargo."JobCargo_DeclaredValueCurrencyCodeSnapshot",
      'nonPreferentialOrigin', cargo."JobCargo_CountryOfOriginCodeSnapshot",
      'destinationCountry', null,
      'containerId', container_row."JobContainer_Number",
      'sourceJobCargoId', cargo."JobCargo_ID"
    )) order by cargo."JobCargo_LineNo" nulls last), '[]'::jsonb)
  into total_packages, total_gross, total_net, items
  from public."Job_Cargo" cargo where cargo."JobCargo_JobID" = requested_job_id and not cargo."JobCargo_IsDeleted";

  payload := jsonb_strip_nulls(jsonb_build_object(
    'direction', direction_value,
    'multideckReference', '',
    'iCustomsCorrelationId', null,
    'traderReference', coalesce(job_row."Job_BookingReference", 'MD-' || job_row."Job_Number"),
    'internalReference', 'JOB-' || job_row."Job_Number",
    'totalAmount', (select coalesce(sum(cargo."JobCargo_DeclaredValueAmount"),0)::text from public."Job_Cargo" cargo where cargo."JobCargo_JobID"=requested_job_id and not cargo."JobCargo_IsDeleted"),
    'currency', (select max(cargo."JobCargo_DeclaredValueCurrencyCodeSnapshot") from public."Job_Cargo" cargo where cargo."JobCargo_JobID"=requested_job_id and not cargo."JobCargo_IsDeleted"),
    'totalPackages', total_packages::text, 'totalGrossMass', total_gross::text, 'totalNetMass', total_net::text,
    'exporter', exporter_identifier, 'exporterName', exporter_row."JobParty_NameSnapshot",
    'exporterAddressLine', exporter_row."JobParty_AddressSnapshot", 'exporterCountry', exporter_row."JobParty_CountryCodeSnapshot",
    'importer', importer_identifier, 'importerName', importer_row."JobParty_NameSnapshot",
    'importerAddressLine', importer_row."JobParty_AddressSnapshot", 'importerCountry', importer_row."JobParty_CountryCodeSnapshot",
    'consignee', importer_identifier, 'consigneeName', importer_row."JobParty_NameSnapshot",
    'consigneeAddressLine', importer_row."JobParty_AddressSnapshot", 'consigneeCountry', importer_row."JobParty_CountryCodeSnapshot",
    'exportCountry', exporter_row."JobParty_CountryCodeSnapshot",
    'destinationCountry', importer_row."JobParty_CountryCodeSnapshot",
    'borderMode', customs_mode_code,
    'borderIdentificationNumber', readiness#>>'{evidence,transportReference}',
    'departureIdentificationNumber', case when direction_value = 'export' then readiness#>>'{evidence,transportReference}' end,
    'arrivalIdentificationNumber', case when direction_value = 'import' then readiness#>>'{evidence,transportReference}' end,
    'isContainerised', case when container_row."JobContainers_ID" is null then '0' else '1' end,
    'containerId', container_row."JobContainer_Number",
    'tradeTerms', job_row."Job_IncotermsCode",
    'transactionNature', '11',
    'freightChargeAmount', job_row."Job_FreightChargeAmount"::text,
    'freightChargeCurrency', job_row."Job_FreightChargeCurrencyCode",
    'items', items,
    'prefillReviewRequired', true,
    'prefillSource', 'booking_customs_handoff'
  ));

  source_snapshot := jsonb_build_object(
    'source', 'booking_customs_handoff', 'capturedAt', now(),
    'jobId', requested_job_id, 'bookingReference', coalesce(job_row."Job_BookingReference", 'MD-' || job_row."Job_Number"),
    'jobUpdatedAt', job_row."Job_UpdatedAt", 'submittedByUserId', app_user."User_ID",
    'ownerDepartmentId', department_id_value, 'readiness', readiness,
    'commercialInvoiceDocumentId', commercial_invoice_id, 'packingListDocumentId', packing_list_id,
    'payload', payload
  );
  declaration_reference := 'MD-CDS-' || case direction_value when 'import' then 'IM' else 'EX' end || '-'
    || to_char(now() at time zone 'UTC','YYYYMMDD') || '-' || lpad(nextval('public."Customs_DeclarationReferenceSeq"')::text,4,'0');

  insert into public."Customs_Declarations" (
    "CUST_JobID", "CUST_OrgOfficeID", "CUST_JurisdictionCode", "CUST_Direction", "CUST_DeclarationKind",
    "CUST_Status", "CUST_LocalReferenceNumber", "CUST_TraderReference",
    "CUST_ImporterOrgID", "CUST_ExporterOrgID", "CUST_CarrierOrgID",
    "CUST_ImporterIdentifierSnapshot", "CUST_ExporterIdentifierSnapshot",
    "CUST_TotalPackages", "CUST_GrossMass", "CUST_InvoiceAmount", "CUST_InvoiceCurrencyCodeSnapshot",
    "CUST_IncotermsCode", "CUST_IncotermsLocation", "CUST_GenericPayloadJSON", "CUST_SourceSnapshot",
    "CUST_CreatedBy", "CUST_UpdatedBy", "CUST_OwnerDepartmentID", "CUST_SubmittedByUserID",
    "CUST_AssignedUserID", "CUST_HandoffIdempotencyKey", "CUST_SourceJobUpdatedAt", "CUST_HandoffAt"
  ) values (
    requested_job_id, coalesce(job_row."Job_OrgOfficeID",job_row."Job_OfficeID"), 'GB', direction_value, 'cds_' || direction_value,
    'draft', declaration_reference, coalesce(job_row."Job_BookingReference", 'MD-' || job_row."Job_Number"),
    importer_row."JobParty_OrgID", exporter_row."JobParty_OrgID", job_row."Job_Carrier",
    importer_identifier, exporter_identifier, total_packages::integer, total_gross,
    nullif(payload->>'totalAmount','')::numeric, nullif(payload->>'currency',''),
    job_row."Job_IncotermsCode", job_row."Job_IncotermsLocation", payload, source_snapshot,
    caller_auth_user_id, caller_auth_user_id, department_id_value, app_user."User_ID",
    assigned_user_id, requested_idempotency_key, job_row."Job_UpdatedAt", now()
  ) returning "CUST_id" into declaration_id;

  insert into booking_api.customs_declaration_grants (
    declaration_id, user_id, can_write, reason
  ) values (
    declaration_id, app_user."User_ID", true, 'booking_handoff_initiator'
  )
  on conflict (declaration_id, user_id) do update
    set can_write = true,
        reason = excluded.reason;

  insert into public."Customs_Items" (
    "CUSTI_CustomsID", "CUSTI_ItemNumber", "CUSTI_CommodityCode", "CUSTI_DescriptionOfGoods",
    "CUSTI_CountryOfOriginCodeSnapshot", "CUSTI_CountryOfDestinationCodeSnapshot",
    "CUSTI_NetMass", "CUSTI_GrossMass", "CUSTI_ItemValueAmount", "CUSTI_ItemValueCurrencyCodeSnapshot",
    "CUSTI_ItemPayloadJSON", "CUSTI_JobCargoID"
  ) select declaration_id, item.ordinality::integer, nullif(item.value->>'commodityCode',''), coalesce(item.value->>'description',''),
    nullif(item.value->>'nonPreferentialOrigin',''), nullif(payload->>'destinationCountry',''),
    nullif(item.value->>'netMass','')::numeric, nullif(item.value->>'grossMass','')::numeric,
    nullif(item.value->>'itemPrice','')::numeric, nullif(item.value->>'currency',''), item.value,
    nullif(item.value->>'sourceJobCargoId','')::uuid
  from jsonb_array_elements(items) with ordinality item(value, ordinality);

  insert into public."Customs_Parties" (
    "CUSTP_CustomsID", "CUSTP_Role", "CUSTP_OrgID", "CUSTP_NameSnapshot",
    "CUSTP_IdentifierType", "CUSTP_IdentifierValueSnapshot", "CUSTP_AddressJSON",
    "CUSTP_CountryCodeSnapshot", "CUSTP_SortOrder"
  ) values
    (declaration_id,'exporter',exporter_row."JobParty_OrgID",exporter_row."JobParty_NameSnapshot",'eori',exporter_identifier,
      jsonb_build_object('formatted',exporter_row."JobParty_AddressSnapshot"),exporter_row."JobParty_CountryCodeSnapshot",10),
    (declaration_id,'importer',importer_row."JobParty_OrgID",importer_row."JobParty_NameSnapshot",
      case when direction_value='import' then 'eori_or_vat' else importer_row."JobParty_IdentifierType" end,importer_identifier,
      jsonb_build_object('formatted',importer_row."JobParty_AddressSnapshot"),importer_row."JobParty_CountryCodeSnapshot",20);

  insert into public."Customs_Documents" (
    "CUSTD_CustomsID", "CUSTD_DocumentRole", "CUSTD_DocumentCode", "CUSTD_DocumentStatusCode",
    "CUSTD_DocumentPayloadJSON", "CUSTD_JobDocumentID"
  ) values (
    declaration_id, 'supporting', 'commercial_invoice', 'attached',
    jsonb_build_object('source','job_document','required',true), commercial_invoice_id
  );
  if packing_list_id is not null then
    insert into public."Customs_Documents" (
      "CUSTD_CustomsID", "CUSTD_DocumentRole", "CUSTD_DocumentCode", "CUSTD_DocumentStatusCode",
      "CUSTD_DocumentPayloadJSON", "CUSTD_JobDocumentID"
    ) values (declaration_id,'supporting','packing_list','attached',jsonb_build_object('source','job_document','required',false),packing_list_id);
  end if;

  insert into booking_api.events (company_id,job_id,event_type,summary,metadata,actor_user_id)
  values (app_user."Company_ID",requested_job_id,'sent_to_customs','Booking sent to Customs.',
    jsonb_build_object('declarationId',declaration_id,'direction',direction_value,'departmentId',department_id_value),app_user."User_ID");

  for recipient in
    select user_row."User_ID"
    from public."cmp_Users_Departments" membership
    join public."cmp_Users" user_row on user_row."User_ID"=membership."User_ID"
    where membership."Department_ID"=department_id_value and user_row."Company_ID"=app_user."Company_ID"
      and user_row."User_AccessStatus"='active'
      and user_row."Auth_User_ID" is not null
      and booking_api.has_permission(user_row."Auth_User_ID", 'Customs.Read')
  loop
    insert into public."Comm_Notifications" (
      "CommNotif_UserID","CommNotif_Title","CommNotif_Body","CommNotif_TargetTable","CommNotif_TargetID",
      "CommNotif_LinkTypeCode","CommNotif_MetadataJSON","CommNotif_CreatedBy"
    ) values (
      recipient."User_ID", 'Booking sent to Customs',
      sender_name || ' sent booking ' || coalesce(job_row."Job_BookingReference", 'MD-' || job_row."Job_Number"),
      'Customs_Declarations',declaration_id,'customs_handoff',jsonb_build_object(
        'event_type','customs_handoff',
        'action_url','/customs/job-related/'||direction_value||'/'||declaration_id,
        'action_label','Open declaration','eyebrow','Customs handoff',
        'booking_reference',coalesce(job_row."Job_BookingReference", 'MD-' || job_row."Job_Number"),
        'sender_name',sender_name,'declaration_id',declaration_id
      ),app_user."User_ID"
    );
  end loop;

  return jsonb_build_object(
    'declarationId',declaration_id,'reference',declaration_reference,'direction',direction_value,
    'route','/customs/job-related/'||direction_value||'/'||declaration_id,
    'canOpen',booking_api.customs_access(caller_auth_user_id,declaration_id,false),'reused',false
  );
exception
  when unique_violation then
    select declaration.* into existing_declaration from public."Customs_Declarations" declaration
    where declaration."CUST_JobID"=requested_job_id and declaration."CUST_HandoffIdempotencyKey"=requested_idempotency_key and not declaration."CUST_IsDeleted" limit 1;
    if found then
      insert into booking_api.customs_declaration_grants (
        declaration_id, user_id, can_write, reason
      ) values (
        existing_declaration."CUST_id", app_user."User_ID", true, 'booking_handoff_initiator'
      )
      on conflict (declaration_id, user_id) do update
        set can_write = true,
            reason = excluded.reason;

      return jsonb_build_object('declarationId',existing_declaration."CUST_id",'reference',existing_declaration."CUST_LocalReferenceNumber",'direction',existing_declaration."CUST_Direction",'route','/customs/job-related/'||existing_declaration."CUST_Direction"||'/'||existing_declaration."CUST_id",'canOpen',booking_api.customs_access(caller_auth_user_id,existing_declaration."CUST_id",false),'reused',true);
    end if;
    raise;
end;
$$;


