CREATE TABLE IF NOT EXISTS "public"."Job_Header" (
    "Job_ID" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "Job_Type" integer,
    "Job_Number" integer NOT NULL,
    "Job_Period" character varying(6) NOT NULL,
    "Job_CreatedDate" timestamp without time zone DEFAULT "now"() NOT NULL,
    "Job_CreatedBy" "uuid" NOT NULL,
    "Job_RevRecognitionDate" "date",
    "Job_Customer" "uuid",
    "Job_CustomerAddress" "uuid",
    "Job_Shipper" "uuid",
    "Job_ShipperAddress" "uuid",
    "Job_Consignee" "uuid",
    "Job_ConsigneeAddress" "uuid",
    "Job_ImportBroker" "uuid",
    "Job_ExportBroker" "uuid",
    "Job_Carrier" "uuid",
    "Job_Supplier" "uuid",
    "Job_OfficeID" "uuid" NOT NULL,
    "Job_OrgOfficeID" "uuid",
    "Job_Status" character varying(40) DEFAULT 'open'::character varying NOT NULL,
    "Job_Direction" character varying(40),
    "Job_TransportModeSummary" character varying(40),
    "Job_OriginUNLocode" character varying(10),
    "Job_OriginNameSnapshot" character varying(180),
    "Job_DestinationUNLocode" character varying(10),
    "Job_DestinationNameSnapshot" character varying(180),
    "Job_ReadyDate" "date",
    "Job_RequiredDeliveryDate" "date",
    "Job_ClosedDate" "date",
    "Job_TrackingStatus" character varying(80),
    "Job_CurrentLocationUNLocode" character varying(10),
    "Job_CurrentLocationNameSnapshot" character varying(180),
    "Job_LastTrackedAt" timestamp with time zone,
    "Job_PredictedDeliveryAt" timestamp with time zone,
    "Job_TrackingRiskScore" numeric(5,4),
    "Job_InternalNotes" "text",
    "Job_UpdatedAt" timestamp with time zone DEFAULT "now"() NOT NULL,
    "Job_UpdatedBy" "uuid",
    "Job_IsDeleted" boolean DEFAULT false NOT NULL,
    "Job_LegalEntityID" "uuid",
    "Job_BrandID" "uuid",
    "Job_LegalEntityNameSnapshot" character varying(240),
    "Job_BrandNameSnapshot" character varying(240),
    "Job_BookingReference" character varying(80),
    "Job_SourceQuoteID" "uuid",
    "Job_SourceQuoteVersionID" "uuid",
    "Job_SourceQuoteResponseID" "uuid",
    "Job_CreateIdempotencyKey" "uuid",
    "Job_IncotermsCode" character varying(10),
    "Job_IncotermsLocation" character varying(180),
    "Job_FreightChargeAmount" numeric(18,4),
    "Job_FreightChargeCurrencyCode" character varying(3),
    "Job_CollectionAddress" "text",
    "Job_DeliveryAddress" "text",
    "Job_CustomerDeadline" "date",
    "Job_SourceSnapshotJSON" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "Job_BookingReferenceSequenceKey" character varying(40) DEFAULT 'default'::character varying NOT NULL,
    "Job_BookingReferenceSequenceValue" bigint,
    "Job_CustomerReference" character varying(180),
    "Job_SupplierReference" character varying(180),
    "Job_OperationsOwnerID" "uuid",
    "Job_CustomerNotes" "text",
    "Job_TermsConditions" "text",
    "Job_SubjectToTerms" "text",
    "Job_InvoiceReference" character varying(180),
    "Job_InvoiceStatus" character varying(40) DEFAULT 'not_raised'::character varying NOT NULL,
    "Job_InvoiceReadyAt" timestamp with time zone,
    "Job_CompletedAt" timestamp with time zone,
    "Job_CompletedBy" "uuid",
    "Job_CompletionChecklistJSON" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "Job_ReopenedAt" timestamp with time zone,
    "Job_DomainCode" character varying(24) DEFAULT 'freight'::character varying NOT NULL,
    "Job_EditableDetailsJSON" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "Job_PendingQuoteVersionID" "uuid",
    "Job_PendingQuoteResponseID" "uuid",
    "Job_QuoteSyncStatus" character varying(30) DEFAULT 'in_sync'::character varying NOT NULL,
    "Job_QuoteSyncDetectedAt" timestamp with time zone,
    "Job_GoodsValueAmount" numeric(18,4),
    "Job_GoodsValueCurrencyCode" "text",
    CONSTRAINT "CK_Job_Header_QuoteSyncStatus" CHECK ((("Job_QuoteSyncStatus")::"text" = ANY ((ARRAY['in_sync'::character varying, 'out_of_sync'::character varying, 'partially_applied'::character varying])::"text"[]))),
    CONSTRAINT "CK_Job_Header_completion_checklist" CHECK (("jsonb_typeof"("Job_CompletionChecklistJSON") = 'object'::"text")),
    CONSTRAINT "CK_Job_Header_customer_after_draft" CHECK (((("Job_Status")::"text" = 'draft'::"text") OR ("Job_Customer" IS NOT NULL))),
    CONSTRAINT "CK_Job_Header_domain" CHECK ((("Job_DomainCode")::"text" = ANY ((ARRAY['freight'::character varying, 'warehouse'::character varying, 'customs'::character varying, 'shared'::character varying])::"text"[]))),
    CONSTRAINT "CK_Job_Header_freight_currency" CHECK ((("Job_FreightChargeCurrencyCode" IS NULL) OR (("Job_FreightChargeCurrencyCode")::"text" ~ '^[A-Z]{3}$'::"text"))),
    CONSTRAINT "CK_Job_Header_invoice_status" CHECK ((("Job_InvoiceStatus")::"text" = ANY ((ARRAY['not_raised'::character varying, 'ready'::character varying, 'raised'::character varying, 'paid'::character varying, 'cancelled'::character varying])::"text"[]))),
    CONSTRAINT "CK_Job_Header_management_period" CHECK ((("Job_Period")::"text" ~ '^[0-9]{6}$'::"text")),
    CONSTRAINT "CK_Job_Header_source_snapshot" CHECK (("jsonb_typeof"("Job_SourceSnapshotJSON") = 'object'::"text")),
    CONSTRAINT "Job_goods_value_currency" CHECK (("Job_GoodsValueCurrencyCode" ~ '^[A-Z]{3}$'::"text")),
    CONSTRAINT "Job_goods_value_nonnegative" CHECK ((("Job_GoodsValueAmount" >= (0)::numeric) AND ("Job_GoodsValueAmount" < ('100000000000000'::bigint)::numeric)))
);


