CREATE OR REPLACE FUNCTION "booking_api"."workspace"("caller_auth_user_id" "uuid", "requested_reference" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare result jsonb; money jsonb; job_id uuid;
begin
  result:=booking_api.workspace_before_goods_value_20260905(caller_auth_user_id,requested_reference);
  job_id:=nullif(result#>>'{booking,jobId}','')::uuid;
  if job_id is null then return result; end if;
  select jsonb_build_object('amount',job."Job_GoodsValueAmount"::text,'currency',job."Job_GoodsValueCurrencyCode") into money
    from public."Job_Header" job join public."cmp_Offices" office on office."Office_ID"=coalesce(job."Job_OrgOfficeID",job."Job_OfficeID")
    join public."cmp_Users" actor on actor."Company_ID"=office."Company_ID" and actor."Auth_User_ID"=caller_auth_user_id and actor."User_AccessStatus"='active'
    where job."Job_ID"=job_id and not job."Job_IsDeleted" and booking_api.has_permission(caller_auth_user_id,'Bookings.Read');
  if not found then raise exception 'Shipment goods value is outside this workspace.' using errcode='42501'; end if;
  return jsonb_set(result,'{booking}',(result->'booking')||jsonb_build_object('shipmentGoodsValue',money));
end;
$$;


ALTER FUNCTION "booking_api"."workspace"("caller_auth_user_id" "uuid", "requested_reference" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."workspace_before_allocations_20260905"("caller_auth_user_id" "uuid", "requested_reference" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare result jsonb; job_id uuid; rows jsonb; source_rows jsonb;
begin
  if caller_auth_user_id is null or not booking_api.has_permission(caller_auth_user_id,'Bookings.Read') then
    raise exception 'Booking access is not authorised.' using errcode='42501';end if;
  result:=booking_api.workspace_before_container_ops_20260905(caller_auth_user_id,requested_reference);
  job_id:=nullif(result#>>'{booking,jobId}','')::uuid;
  if not exists(select 1 from public."Job_Header" job
    join public."cmp_Offices" office on office."Office_ID"=coalesce(job."Job_OrgOfficeID",job."Job_OfficeID")
    join public."cmp_Users" actor on actor."Company_ID"=office."Company_ID" and actor."Auth_User_ID"=caller_auth_user_id and actor."User_AccessStatus"='active'
    where job."Job_ID"=job_id and not job."Job_IsDeleted") then
    raise exception 'That booking is outside this workspace.' using errcode='42501';end if;
  source_rows:=coalesce(nullif(result->'containers','null'::jsonb),'[]'::jsonb);
  if jsonb_typeof(source_rows) is distinct from 'array' then raise exception 'Equipment changed while loading. Reload the Booking.' using errcode='40001';end if;
  select coalesce(jsonb_agg(entry.value||booking_api.container_operational_values(container) order by entry.ordinal),'[]') into rows
    from jsonb_array_elements(source_rows) with ordinality entry(value,ordinal)
    join public."Job_Containers" container on container."JobContainers_ID"=nullif(entry.value->>'id','')::uuid
      and container."Job_ID"=job_id and not container."JobContainer_IsDeleted";
  if jsonb_array_length(rows)<>jsonb_array_length(source_rows) then raise exception 'Equipment changed while loading. Reload the Booking.' using errcode='40001';end if;
  return jsonb_set(result,'{containers}',rows);
end $$;


ALTER FUNCTION "booking_api"."workspace_before_allocations_20260905"("caller_auth_user_id" "uuid", "requested_reference" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."workspace_before_cargo_decimals_20260905"("caller_auth_user_id" "uuid", "requested_reference" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  result jsonb;
  booking_value jsonb;
  details jsonb;
  job_id uuid;
  is_favourite boolean;
  owner_name text;
  cargo_value jsonb;
begin
  result := booking_api.workspace(caller_auth_user_id, requested_reference);
  job_id := nullif(result->'booking'->>'jobId', '')::uuid;
  select
    coalesce(job."Job_EditableDetailsJSON", '{}'::jsonb),
    coalesce(nullif(btrim(concat_ws(' ', owner_user."User_Firstname", owner_user."User_Lastname")), ''), owner_user."User_Email")
  into details, owner_name
  from public."Job_Header" job
  join public."cmp_Offices" office on office."Office_ID" = coalesce(job."Job_OrgOfficeID", job."Job_OfficeID")
  join public."cmp_Users" app_user on app_user."Company_ID" = office."Company_ID"
    and app_user."Auth_User_ID" = caller_auth_user_id
    and app_user."User_AccessStatus" = 'active'
  left join public."cmp_Users" owner_user on owner_user."User_ID" = job."Job_CreatedBy"
  where job."Job_ID" = job_id and not job."Job_IsDeleted";
  if details is null then details := '{}'::jsonb; end if;

  details := details || jsonb_strip_nulls(jsonb_build_object(
    'ownerName', coalesce(nullif(details->>'ownerName', ''), owner_name),
    'quoteType', coalesce(nullif(details->>'quoteType', ''), initcap(replace(result->'booking'->>'direction', '_', ' ')))
  ));

  select exists(
    select 1 from public."App_UserJobStars" star
    where star."User_ID" = caller_auth_user_id and star."Job_ID" = job_id
  ) into is_favourite;

  select coalesce(jsonb_agg(
    item.value || jsonb_strip_nulls(jsonb_build_object(
      'length', cargo."JobCargo_Length",
      'width', cargo."JobCargo_Width",
      'height', cargo."JobCargo_Height",
      'lengthUnit', cargo."JobCargo_LengthUnit"
    )) order by cargo."JobCargo_LineNo" nulls last
  ), result->'cargo')
  into cargo_value
  from jsonb_array_elements(coalesce(result->'cargo', '[]'::jsonb)) as item(value)
  left join public."Job_Cargo" cargo
    on cargo."JobCargo_ID" = nullif(item.value->>'id', '')::uuid
    and cargo."JobCargo_JobID" = job_id
    and not cargo."JobCargo_IsDeleted";

  booking_value := coalesce(result->'booking', '{}'::jsonb) || jsonb_build_object(
    'jobReference', coalesce(nullif(details->>'jobReference', ''), result->'booking'->>'jobReference'),
    'editableDetails', details || jsonb_build_object('isFavourite', coalesce(is_favourite, false))
  );
  result := jsonb_set(result, '{booking}', booking_value, true);
  return jsonb_set(result, '{cargo}', coalesce(cargo_value, '[]'::jsonb), true);
end;
$$;


ALTER FUNCTION "booking_api"."workspace_before_cargo_decimals_20260905"("caller_auth_user_id" "uuid", "requested_reference" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."workspace_before_container_ops_20260905"("caller_auth_user_id" "uuid", "requested_reference" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare result jsonb; job_id uuid; exact_cargo jsonb; source_cargo jsonb;
begin
  if caller_auth_user_id is null or not booking_api.has_permission(caller_auth_user_id,'Bookings.Read') then
    raise exception 'Booking access is not authorised.' using errcode='42501'; end if;
  result:=booking_api.workspace_before_cargo_decimals_20260905(caller_auth_user_id,requested_reference);
  job_id:=nullif(result#>>'{booking,jobId}','')::uuid;
  if not exists(select 1 from public."Job_Header" job
    join public."cmp_Offices" office on office."Office_ID"=coalesce(job."Job_OrgOfficeID",job."Job_OfficeID")
    join public."cmp_Users" actor on actor."Company_ID"=office."Company_ID" and actor."Auth_User_ID"=caller_auth_user_id and actor."User_AccessStatus"='active'
    where job."Job_ID"=job_id and not job."Job_IsDeleted") then
    raise exception 'That booking is outside this workspace.' using errcode='42501'; end if;
  source_cargo:=coalesce(nullif(result->'cargo','null'::jsonb),'[]'::jsonb);
  if jsonb_typeof(source_cargo) is distinct from 'array' then
    raise exception 'Cargo changed while loading. Reload the Booking.' using errcode='40001'; end if;
  select coalesce(jsonb_agg(entry.value||booking_api.cargo_decimal_values(cargo) order by entry.ordinal),'[]') into exact_cargo
    from jsonb_array_elements(source_cargo) with ordinality entry(value,ordinal)
    join public."Job_Cargo" cargo on cargo."JobCargo_ID"=nullif(entry.value->>'id','')::uuid and cargo."JobCargo_JobID"=job_id and not cargo."JobCargo_IsDeleted";
  if jsonb_array_length(exact_cargo)<>jsonb_array_length(source_cargo) then
    raise exception 'Cargo changed while loading. Reload the Booking.' using errcode='40001'; end if;
  return jsonb_set(result,'{cargo}',exact_cargo);
end $$;


ALTER FUNCTION "booking_api"."workspace_before_container_ops_20260905"("caller_auth_user_id" "uuid", "requested_reference" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."workspace_before_cutoffs_20260906"("caller_auth_user_id" "uuid", "requested_reference" "text") RETURNS "jsonb"
