CREATE OR REPLACE FUNCTION "booking_api"."workspace_before_dangerous_goods_20260907"("caller_auth_user_id" "uuid", "requested_reference" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare result jsonb; routes jsonb; job_id uuid; types jsonb;
begin
  result := booking_api.workspace_before_milestones_20260906(caller_auth_user_id, requested_reference);
  job_id := nullif(result #>> '{booking,jobId}', '')::uuid;
  if job_id is null then return result; end if;
  select coalesce(jsonb_agg(line || jsonb_build_object('updatedAt', route."JobRoute_UpdatedAt", 'milestones', (
    select coalesce(jsonb_agg(booking_api.route_milestone_values(m) || jsonb_build_object(
      'name', coalesce(t."JMT_Name", m."JobRouteMilestone_Type"))
      order by t."JMT_SortOrder", m."JobRouteMilestone_CreatedAt", m."JobRouteMilestone_ID"), '[]'::jsonb)
    from public."Job_RouteMilestones" m left join public."sys_JobMilestoneTypes" t on t."JMT_Code" = m."JobRouteMilestone_Type"
    where m."JobRouteMilestone_JobRouteID" = route."JobRoute_ID"
  )) order by ordinal), '[]'::jsonb) into routes
  from jsonb_array_elements(coalesce(result->'routes', '[]'::jsonb)) with ordinality entries(line, ordinal)
  join public."Job_Routing" route on route."JobRoute_ID"::text = line->>'id' and route."Job_ID" = job_id;
  select coalesce(jsonb_agg(jsonb_build_object('code', "JMT_Code", 'name', "JMT_Name") order by "JMT_SortOrder", "JMT_Code"), '[]'::jsonb)
  into types from public."sys_JobMilestoneTypes" where "JMT_IsActive" and "JMT_Code" <> 'customs_released';
  return jsonb_set(result, '{routes}', routes) || jsonb_build_object('routeMilestonesSupported', true, 'milestoneTypes', types);
end $$;


ALTER FUNCTION "booking_api"."workspace_before_dangerous_goods_20260907"("caller_auth_user_id" "uuid", "requested_reference" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."workspace_before_goods_value_20260905"("caller_auth_user_id" "uuid", "requested_reference" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  app_user record;
  job_row record;
  booking_value jsonb;
  parties_value jsonb;
  cargo_value jsonb;
  containers_value jsonb;
  routes_value jsonb;
  documents_value jsonb;
  declarations_value jsonb;
  charges_value jsonb;
  events_value jsonb;
  source_quote_value jsonb;
begin
  if caller_auth_user_id is null
     or not booking_api.has_permission(caller_auth_user_id, 'Bookings.Read') then
    raise exception 'Booking access is not authorised.' using errcode = '42501';
  end if;
  select "User_ID", "Company_ID" into strict app_user
  from public."cmp_Users"
  where "Auth_User_ID" = caller_auth_user_id
    and "User_AccessStatus" = 'active';

  select job.* into job_row
  from public."Job_Header" job
  join public."cmp_Offices" office
    on office."Office_ID" = coalesce(job."Job_OrgOfficeID", job."Job_OfficeID")
  where office."Company_ID" = app_user."Company_ID"
    and not job."Job_IsDeleted"
    and (
      upper(job."Job_BookingReference") = upper(btrim(requested_reference))
      or job."Job_ID"::text = btrim(requested_reference)
      or ('MD-' || job."Job_Number") = upper(btrim(requested_reference))
      or ('JOB-' || job."Job_Number") = upper(btrim(requested_reference))
    )
  limit 1;
  if not found then
    raise exception 'That booking could not be found in this workspace.' using errcode = 'P0002';
  end if;

  select jsonb_strip_nulls(jsonb_build_object(
    'jobId', job_row."Job_ID",
    'bookingReference', coalesce(job_row."Job_BookingReference", 'MD-' || job_row."Job_Number"),
    'jobReference', 'JOB-' || job_row."Job_Number",
    'jobNumber', job_row."Job_Number",
    'status', job_row."Job_Status",
    'direction', job_row."Job_Direction",
    'mode', job_row."Job_TransportModeSummary",
    'customerId', job_row."Job_Customer",
    'customerName', customer."Org_Name",
    'customerCode', customer."Org_AccCode",
    'carrierId', job_row."Job_Carrier",
    'carrierName', carrier."Org_Name",
    'supplierId', job_row."Job_Supplier",
    'supplierName', supplier."Org_Name",
    'officeId', coalesce(job_row."Job_OrgOfficeID", job_row."Job_OfficeID"),
    'origin', coalesce(job_row."Job_OriginNameSnapshot", job_row."Job_OriginUNLocode"),
    'originUnlocode', job_row."Job_OriginUNLocode",
    'destination', coalesce(job_row."Job_DestinationNameSnapshot", job_row."Job_DestinationUNLocode"),
    'destinationUnlocode', job_row."Job_DestinationUNLocode",
    'readyDate', job_row."Job_ReadyDate",
    'requiredDeliveryDate', job_row."Job_RequiredDeliveryDate",
    'customerDeadline', job_row."Job_CustomerDeadline",
    'predictedDeliveryAt', job_row."Job_PredictedDeliveryAt",
    'trackingStatus', job_row."Job_TrackingStatus",
    'currentLocation', job_row."Job_CurrentLocationNameSnapshot",
    'trackingRiskScore', job_row."Job_TrackingRiskScore",
    'internalNotes', job_row."Job_InternalNotes",
    'incoterm', job_row."Job_IncotermsCode",
    'incotermLocation', job_row."Job_IncotermsLocation",
    'freightChargeAmount', job_row."Job_FreightChargeAmount",
    'freightChargeCurrency', job_row."Job_FreightChargeCurrencyCode",
    'collectionAddress', job_row."Job_CollectionAddress",
    'deliveryAddress', job_row."Job_DeliveryAddress",
    'sourceQuoteId', job_row."Job_SourceQuoteID",
    'sourceQuoteVersionId', job_row."Job_SourceQuoteVersionID",
    'sourceQuoteResponseId', job_row."Job_SourceQuoteResponseID",
    'sourceSnapshot', job_row."Job_SourceSnapshotJSON",
    'createdAt', job_row."Job_CreatedDate",
    'updatedAt', job_row."Job_UpdatedAt"
  )) into booking_value
  from (select 1 as marker) base
  left join public."Org_Master" customer on customer."Org_id" = job_row."Job_Customer"
  left join public."Org_Master" carrier on carrier."Org_id" = job_row."Job_Carrier"
  left join public."Org_Master" supplier on supplier."Org_id" = job_row."Job_Supplier"
  limit 1;

  -- A right join above keeps the JSON row available for blank drafts. If a
  -- legacy customer reference is broken, build the same record without names.
  if booking_value is null then
    booking_value := jsonb_strip_nulls(jsonb_build_object(
      'jobId', job_row."Job_ID",
      'bookingReference', coalesce(job_row."Job_BookingReference", 'MD-' || job_row."Job_Number"),
      'jobReference', 'JOB-' || job_row."Job_Number",
      'jobNumber', job_row."Job_Number",
      'status', job_row."Job_Status",
      'direction', job_row."Job_Direction",
      'mode', job_row."Job_TransportModeSummary",
      'customerId', job_row."Job_Customer",
      'carrierId', job_row."Job_Carrier",
      'supplierId', job_row."Job_Supplier",
      'officeId', coalesce(job_row."Job_OrgOfficeID", job_row."Job_OfficeID"),
      'origin', coalesce(job_row."Job_OriginNameSnapshot", job_row."Job_OriginUNLocode"),
      'destination', coalesce(job_row."Job_DestinationNameSnapshot", job_row."Job_DestinationUNLocode"),
      'trackingStatus', job_row."Job_TrackingStatus",
      'currentLocation', job_row."Job_CurrentLocationNameSnapshot",
      'internalNotes', job_row."Job_InternalNotes",
      'incoterm', job_row."Job_IncotermsCode",
      'incotermLocation', job_row."Job_IncotermsLocation",
      'collectionAddress', job_row."Job_CollectionAddress",
      'deliveryAddress', job_row."Job_DeliveryAddress",
      'sourceQuoteId', job_row."Job_SourceQuoteID",
      'sourceQuoteVersionId', job_row."Job_SourceQuoteVersionID",
      'sourceQuoteResponseId', job_row."Job_SourceQuoteResponseID",
      'sourceSnapshot', job_row."Job_SourceSnapshotJSON",
      'createdAt', job_row."Job_CreatedDate",
      'updatedAt', job_row."Job_UpdatedAt"
    ));
  end if;

  select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
    'id', party."JobParty_ID", 'role', party."JobParty_Role", 'organisationId', party."JobParty_OrgID",
    'addressId', party."JobParty_AddressID", 'contactId', party."JobParty_ContactID",
    'sequence', party."JobParty_Sequence", 'name', party."JobParty_NameSnapshot",
    'address', party."JobParty_AddressSnapshot", 'contactName', party."JobParty_ContactNameSnapshot",
    'email', party."JobParty_EmailSnapshot", 'phone', party."JobParty_PhoneSnapshot",
    'countryCode', party."JobParty_CountryCodeSnapshot", 'identifierType', party."JobParty_IdentifierType",
    'identifierValue', party."JobParty_IdentifierValueSnapshot", 'isPrimary', party."JobParty_IsPrimary",
    'rawSnapshot', party."JobParty_RawSnapshot"
  )) order by party."JobParty_Sequence", party."JobParty_Role"), '[]'::jsonb)
  into parties_value
  from public."Job_Parties" party where party."JobParty_JobID" = job_row."Job_ID";

  select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
    'id', cargo."JobCargo_ID", 'lineNumber', cargo."JobCargo_LineNo", 'description', cargo."JobCargo_Description",
    'commodity', cargo."JobCargo_Commodity", 'pieces', cargo."JobCargo_Qty",
    'packageType', cargo."JobCargo_PackageTypeCodeSnapshot", 'packageQuantity', cargo."JobCargo_PackageQty",
    'grossWeightKg', cargo."JobCargo_GrossKilos", 'netWeightKg', cargo."JobCargo_NettKilos",
    'volumeCbm', cargo."JobCargo_VolumeCBM", 'hsCode', cargo."JobCargo_HSCode",
    'countryOfOrigin', cargo."JobCargo_CountryOfOriginCodeSnapshot",
    'declaredValue', cargo."JobCargo_DeclaredValueAmount",
    'declaredValueCurrency', cargo."JobCargo_DeclaredValueCurrencyCodeSnapshot",
    'isHazardous', cargo."JobCargo_IsHazardous", 'isTemperatureControlled', cargo."JobCargo_IsTemperatureControlled",
    'cargoData', cargo."JobCargo_CargoJSON"
  )) order by cargo."JobCargo_LineNo" nulls last, cargo."JobCargo_CreatedAt"), '[]'::jsonb)
  into cargo_value from public."Job_Cargo" cargo
  where cargo."JobCargo_JobID" = job_row."Job_ID" and not cargo."JobCargo_IsDeleted";

  select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
    'id', container."JobContainers_ID", 'number', container."JobContainer_Number",
    'type', container."JobContainer_TypeCodeSnapshot", 'equipmentKind', container."JobContainer_EquipmentKind",
    'status', container."JobContainer_Status", 'grossWeightKg', container."JobContainer_GrossKilos",
    'notes', container."JobContainer_Notes", 'data', container."JobContainer_JSON"
  )) order by container."JobContainer_CreatedAt"), '[]'::jsonb)
  into containers_value from public."Job_Containers" container
  where container."Job_ID" = job_row."Job_ID" and not container."JobContainer_IsDeleted";

  select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
    'id', route."JobRoute_ID", 'order', route."JobRoute_OrderNo", 'status', route."JobRoute_Status",
    'mode', route."JobRoute_ModeCode", 'origin', route."JobRoute_OriginNameSnapshot",
    'originUnlocode', route."JobRoute_OriginUNLocode", 'originAddress', route."JobRoute_OriginAddressSnapshot",
    'originTerminal', route."JobRoute_OriginTerminal", 'destination', route."JobRoute_DestinationNameSnapshot",
    'destinationUnlocode', route."JobRoute_DestinationUNLocode", 'destinationAddress', route."JobRoute_DestinationAddressSnapshot",
    'destinationTerminal', route."JobRoute_DestinationTerminal", 'plannedPickupAt', route."JobRoute_PlannedPickupAt",
    'plannedDepartureAt', route."JobRoute_PlannedDepartureAt", 'plannedArrivalAt', route."JobRoute_PlannedArrivalAt",
    'plannedDeliveryAt', route."JobRoute_PlannedDeliveryAt", 'carrierId', route."JobRoute_Carrier",
    'carrierBookingReference', route."JobRoute_CarrierBookingReference",
    'masterTransportReference', route."JobRoute_MasterTransportReference",
    'houseTransportReference', route."JobRoute_HouseTransportReference",
    'serviceLevel', route."JobRoute_ServiceLevel", 'transportMeansName', route."JobRoute_TransportMeansName",
    'vessel', route."JobRoute_Vessel", 'voyageNumber', route."JobRoute_VoyageNumber",
    'flightNumber', route."JobRoute_FlightNumber", 'vehicleRegistration', route."JobRoute_VehicleRegistration",
    'trailerNumber', route."JobRoute_TrailerNumber", 'railService', route."JobRoute_RailService",
    'isMainCarriage', route."JobRoute_IsMainCarriage",
    'routeData', route."JobRoute_RouteJSON"
  )) order by route."JobRoute_OrderNo" nulls last), '[]'::jsonb)
  into routes_value from public."Job_Routing" route where route."Job_ID" = job_row."Job_ID";

  select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
    'id', document."JobDoc_ID", 'typeCode', document."JobDoc_DocTypeCodeSnapshot",
    'title', document."JobDoc_Title", 'description', document."JobDoc_Description",
    'status', document."JobDoc_Status", 'source', document."JobDoc_Source",
    'fileName', document."JobDoc_FileName", 'mimeType', document."JobDoc_FileMimeType",
    'fileSizeBytes', document."JobDoc_FileSizeBytes", 'version', document."JobDoc_VersionNo",
    'isCurrent', document."JobDoc_IsCurrentVersion", 'documentDate', document."JobDoc_DocumentDate",
    'receivedAt', document."JobDoc_ReceivedAt", 'metadata', document."JobDoc_MetadataJSON"
  )) order by document."JobDoc_CreatedAt" desc), '[]'::jsonb)
  into documents_value from public."Job_Documents" document
  where document."JobDoc_JobID" = job_row."Job_ID" and not document."JobDoc_IsDeleted";

  select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
    'id', declaration."CUST_id", 'direction', declaration."CUST_Direction",
    'kind', declaration."CUST_DeclarationKind", 'status', declaration."CUST_Status",
    'localReference', declaration."CUST_LocalReferenceNumber",
    'customsReference', declaration."CUST_CustomsReferenceNumber",
    'mrn', declaration."CUST_MasterReferenceNumber", 'providerStatus', declaration."CUST_iCustomsStatusSnapshot",
    'createdAt', declaration."CUST_CreatedAt", 'updatedAt', declaration."CUST_UpdatedAt"
  )) order by declaration."CUST_CreatedAt" desc), '[]'::jsonb)
  into declarations_value from public."Customs_Declarations" declaration
  where declaration."CUST_JobID" = job_row."Job_ID" and not declaration."CUST_IsDeleted";

  select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
    'id', charge."JobCostingLine_ID", 'lineNumber', charge."JobCostingLine_Number",
    'supplierId', charge."JobCostingLine_SupplierID", 'description', charge."JobCostingLine_Description",
    'internalNotes', charge."JobCostingLine_InternalNotes", 'customerNotes', charge."JobCostingLine_CustomerNotes",
    'costRoe', charge."JobCostingLine_CostROE", 'costAmount', charge."JobCostingLine_CostAmountCurrency",
    'costLocal', charge."JobCostingLine_CostAmountLocal", 'sellRoe', charge."JobCostingLine_RevenueROE",
    'sellAmount', charge."JobCostingLine_RevenueAmountCurrency", 'sellLocal', charge."JobCostingLine_RevenueAmountLocal",
    'showToCustomer', charge."JobCostingLine_ShowToCustomer"
  )) order by charge."JobCostingLine_Number"), '[]'::jsonb)
  into charges_value from public."Job_Costing_Lines" charge where charge."Job_ID" = job_row."Job_ID";

  select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
    'id', event.event_id, 'type', event.event_type, 'summary', event.summary,
    'metadata', event.metadata, 'occurredAt', event.occurred_at,
    'actor', nullif(concat_ws(' ', actor."User_Firstname", actor."User_Lastname"), '')
  )) order by event.occurred_at desc), '[]'::jsonb)
  into events_value from booking_api.events event
  left join public."cmp_Users" actor on actor."User_ID" = event.actor_user_id
  where event.job_id = job_row."Job_ID";

  if job_row."Job_SourceQuoteID" is not null then
    select jsonb_strip_nulls(jsonb_build_object(
      'id', quote."CusQuoteHeader_ID",
      'reference', coalesce(quote."CusQuoteHeader_CustomerReference", 'Q-' || quote."CusQuoteHeader_Number"),
      'lifecycle', quote."CusQuoteHeader_LifecycleCode",
      'acceptedVersionId', quote."CusQuoteHeader_AcceptedVersionID"
    )) into source_quote_value
    from public."CusQuote_Header" quote where quote."CusQuoteHeader_ID" = job_row."Job_SourceQuoteID";
  end if;

  return jsonb_build_object(
    'booking', booking_value,
    'parties', parties_value,
    'cargo', cargo_value,
    'containers', containers_value,
    'routes', routes_value,
    'documents', documents_value,
    'declarations', declarations_value,
    'charges', charges_value,
    'events', events_value,
    'sourceQuote', source_quote_value
  );
exception
  when no_data_found or too_many_rows then
    raise exception 'Your workspace identity is incomplete.' using errcode = '42501';
end;
$$;


ALTER FUNCTION "booking_api"."workspace_before_goods_value_20260905"("caller_auth_user_id" "uuid", "requested_reference" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."workspace_before_lifecycle_20260910"("caller_auth_user_id" "uuid", "requested_reference" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  result jsonb;
  job_id uuid;
  source_quote jsonb;
  applied_version_number integer;
  pending_version_number integer;
  sync_status text;
begin
  result := booking_api.workspace_extended(caller_auth_user_id, requested_reference);
  job_id := nullif(result->'booking'->>'jobId', '')::uuid;
  result := jsonb_set(
    result,
    '{documents}',
    booking_api.workspace_documents(caller_auth_user_id, job_id),
    true
  );

  if nullif(result->'booking'->>'sourceQuoteId', '') is not null then
    select
      applied."CusQuoteVersion_Number",
      pending."CusQuoteVersion_Number",
      job."Job_QuoteSyncStatus"
    into applied_version_number, pending_version_number, sync_status
    from public."Job_Header" job
    left join public."CusQuote_Versions" applied
      on applied."CusQuoteVersion_ID"=job."Job_SourceQuoteVersionID"
    left join public."CusQuote_Versions" pending
      on pending."CusQuoteVersion_ID"=job."Job_PendingQuoteVersionID"
    where job."Job_ID"=job_id and not job."Job_IsDeleted";

    source_quote := coalesce(result->'sourceQuote', '{}'::jsonb) || jsonb_strip_nulls(jsonb_build_object(
      'appliedVersionNumber', applied_version_number,
      'pendingVersionNumber', pending_version_number,
      'syncStatus', sync_status
    ));
    result := jsonb_set(result, '{sourceQuote}', source_quote, true);
  end if;

  return result;
end;
$$;


ALTER FUNCTION "booking_api"."workspace_before_lifecycle_20260910"("caller_auth_user_id" "uuid", "requested_reference" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."workspace_before_milestones_20260906"("caller_auth_user_id" "uuid", "requested_reference" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare result jsonb;routes jsonb;job_id uuid;
begin
  result:=booking_api.workspace_before_cutoffs_20260906(caller_auth_user_id,requested_reference);
  job_id:=nullif(result#>>'{booking,jobId}','')::uuid;
  if job_id is null then return result;end if;
  select coalesce(jsonb_agg(line||booking_api.route_cutoff_values(route) order by ordinal),'[]'::jsonb) into routes
    from jsonb_array_elements(coalesce(result->'routes','[]'::jsonb)) with ordinality entries(line,ordinal)
    join public."Job_Routing" route on route."JobRoute_ID"::text=line->>'id' and route."Job_ID"=job_id;
  return jsonb_set(result,'{routes}',routes)||'{"routeCutoffsSupported":true}'::jsonb;
end $$;


ALTER FUNCTION "booking_api"."workspace_before_milestones_20260906"("caller_auth_user_id" "uuid", "requested_reference" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."workspace_before_security_evidence_20260907"("caller_auth_user_id" "uuid", "requested_reference" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare result jsonb; cargo jsonb; job_id uuid;
begin
  result:=booking_api.workspace_before_dangerous_goods_20260907(caller_auth_user_id,requested_reference);
  job_id:=nullif(result#>>'{booking,jobId}','')::uuid;
  if job_id is null then return result; end if;
  select coalesce(jsonb_agg(line||jsonb_build_object('updatedAt',c."JobCargo_UpdatedAt",'dangerousGoods',(
    select coalesce(jsonb_agg(booking_api.cargo_dangerous_goods_values(d)
      order by d."JobCargoDG_CreatedAt",d."JobCargoDG_ID"),'[]'::jsonb)
    from public."Job_CargoDangerousGoods" d where d."JobCargoDG_JobCargoID"=c."JobCargo_ID"
  )) order by ordinal),'[]'::jsonb) into cargo
  from jsonb_array_elements(coalesce(result->'cargo','[]'::jsonb)) with ordinality entries(line,ordinal)
  join public."Job_Cargo" c on c."JobCargo_ID"::text=line->>'id' and c."JobCargo_JobID"=job_id
    and not c."JobCargo_IsDeleted";
  return jsonb_set(result,'{cargo}',cargo)||jsonb_build_object('dangerousGoodsSupported',true);
end $$;


ALTER FUNCTION "booking_api"."workspace_before_security_evidence_20260907"("caller_auth_user_id" "uuid", "requested_reference" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "booking_api"."workspace_documents"("caller_auth_user_id" "uuid", "requested_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  app_user record;
  job_row record;
  quote_reference text;
  documents_value jsonb;
begin
  if caller_auth_user_id is null
     or not booking_api.has_permission(caller_auth_user_id, 'Bookings.Read') then
    raise exception 'Booking access is not authorised.' using errcode = '42501';
  end if;

  select "User_ID", "Company_ID" into strict app_user
  from public."cmp_Users"
  where "Auth_User_ID" = caller_auth_user_id
    and "User_AccessStatus" = 'active';

  select job.* into job_row
  from public."Job_Header" job
  join public."cmp_Offices" office
    on office."Office_ID" = coalesce(job."Job_OrgOfficeID", job."Job_OfficeID")
  where job."Job_ID" = requested_job_id
    and office."Company_ID" = app_user."Company_ID"
    and not job."Job_IsDeleted";

  if not found then
    raise exception 'That booking is outside this workspace.' using errcode = '42501';
  end if;

  if job_row."Job_SourceQuoteID" is not null then
    select coalesce(
      nullif(btrim(quote."CusQuoteHeader_CustomerReference"), ''),
      'Q-' || quote."CusQuoteHeader_Number"::text
    ) into quote_reference
    from public."CusQuote_Header" quote
    join public."cmp_Offices" quote_office
      on quote_office."Office_ID" = coalesce(quote."CusQuoteHeader_OrgOfficeID", quote."OrgOffice_ID")
    where quote."CusQuoteHeader_ID" = job_row."Job_SourceQuoteID"
      and quote_office."Company_ID" = app_user."Company_ID"
      and not quote."CusQuoteHeader_IsDeleted";
  end if;

  with job_documents as (
    select
      case
        when linked_customs.is_linked
          or lower(coalesce(document."JobDoc_Source", '')) like '%customs%'
          or lower(coalesce(document."JobDoc_DocTypeCodeSnapshot", '')) in (
            'commercial_invoice', 'commercial-invoice', 'invoice',
            'packing_list', 'packing-list', 'certificate_of_origin',
            'customs_declaration', 'import_declaration', 'export_declaration'
          )
          or lower(coalesce(document."JobDoc_DocTypeCodeSnapshot", '')) like 'customs_%'
        then 'customs'
        else 'job'
      end as category,
      coalesce(document."JobDoc_ReceivedAt", document."JobDoc_CreatedAt") as created_at,
      jsonb_strip_nulls(jsonb_build_object(
        'id', document."JobDoc_ID",
        'category', case
          when linked_customs.is_linked
            or lower(coalesce(document."JobDoc_Source", '')) like '%customs%'
            or lower(coalesce(document."JobDoc_DocTypeCodeSnapshot", '')) in (
              'commercial_invoice', 'commercial-invoice', 'invoice',
              'packing_list', 'packing-list', 'certificate_of_origin',
              'customs_declaration', 'import_declaration', 'export_declaration'
            )
            or lower(coalesce(document."JobDoc_DocTypeCodeSnapshot", '')) like 'customs_%'
          then 'customs'
          else 'job'
        end,
        'typeCode', document."JobDoc_DocTypeCodeSnapshot",
        'title', document."JobDoc_Title",
        'description', document."JobDoc_Description",
        'status', document."JobDoc_Status",
        'source', document."JobDoc_Source",
        'fileName', document."JobDoc_FileName",
        'mimeType', document."JobDoc_FileMimeType",
        'fileSizeBytes', document."JobDoc_FileSizeBytes",
        'version', document."JobDoc_VersionNo",
        'isCurrent', document."JobDoc_IsCurrentVersion",
        'documentDate', document."JobDoc_DocumentDate",
        'receivedAt', document."JobDoc_ReceivedAt",
        'createdAt', document."JobDoc_CreatedAt",
        'sourceRecordId', requested_job_id,
        'sourceReference', coalesce(
          linked_customs.reference,
          job_row."Job_BookingReference",
          'JOB-' || job_row."Job_Number"::text
        ),
        'metadata', document."JobDoc_MetadataJSON"
      )) as payload
    from public."Job_Documents" document
    left join lateral (
      select
        true as is_linked,
        coalesce(
          nullif(btrim(declaration."CUST_CustomsReferenceNumber"), ''),
          nullif(btrim(declaration."CUST_MasterReferenceNumber"), ''),
          nullif(btrim(declaration."CUST_LocalReferenceNumber"), '')
        ) as reference
      from public."Customs_Documents" customs_document
      join public."Customs_Declarations" declaration
        on declaration."CUST_id" = customs_document."CUSTD_CustomsID"
      where customs_document."CUSTD_JobDocumentID" = document."JobDoc_ID"
        and declaration."CUST_JobID" = requested_job_id
        and not declaration."CUST_IsDeleted"
      order by declaration."CUST_UpdatedAt" desc, customs_document."CUSTD_CreatedAt" desc
      limit 1
    ) linked_customs on true
    where document."JobDoc_JobID" = requested_job_id
      and not document."JobDoc_IsDeleted"
  ),
  quote_documents as (
    select
      'quote'::text as category,
      stored."DOCStoredObject_CreatedAt" as created_at,
      jsonb_strip_nulls(jsonb_build_object(
        'id', stored."DOCStoredObject_ID",
        'category', 'quote',
        'typeCode', 'quote_pdf',
        'title', stored."DOCStoredObject_OriginalFileName",
        'status', stored."DOCStoredObject_StatusCode",
        'source', 'quote_workflow',
        'fileName', stored."DOCStoredObject_OriginalFileName",
        'mimeType', stored."DOCStoredObject_MimeType",
        'fileSizeBytes', stored."DOCStoredObject_FileSizeBytes",
        'version', version."CusQuoteVersion_Number",
        'isCurrent', version."CusQuoteVersion_ID" = job_row."Job_SourceQuoteVersionID",
        'createdAt', stored."DOCStoredObject_CreatedAt",
        'sourceRecordId', job_row."Job_SourceQuoteID",
        'sourceReference', quote_reference,
        'metadata', jsonb_build_object(
          'storageProvider', stored."DOCStoredObject_ProviderCode",
          'aggregateType', stored."DOCStoredObject_AggregateType",
          'quoteVersionId', version."CusQuoteVersion_ID",
          'quoteVersionNumber', version."CusQuoteVersion_Number",
          'responseLinkId', link.response_link_id,
          'appliedToBooking', version."CusQuoteVersion_ID" = job_row."Job_SourceQuoteVersionID"
        )
      )) as payload
    from quote_api.customer_response_links link
    join public."CusQuote_Versions" version
      on version."CusQuoteVersion_ID" = link.quote_version_id
     and version."CusQuoteHeader_ID" = link.quote_id
    join public."DOC_StoredObjects" stored
      on stored."DOCStoredObject_ID" = link.quote_document_id
    join public."cmp_Users" creator
      on creator."User_ID" = stored."DOCStoredObject_CreatedBy"
    where job_row."Job_SourceQuoteID" is not null
      and link.quote_id = job_row."Job_SourceQuoteID"
      and link.company_id = app_user."Company_ID"
      and link.delivery_status_code = 'sent'
      and version."CusQuoteVersion_StatusCode" = 'accepted'
      and stored."DOCStoredObject_ConcernCode" = 'quote'
      and stored."DOCStoredObject_AggregateType" = 'CusQuote_Header'
      and stored."DOCStoredObject_AggregateID" = job_row."Job_SourceQuoteID"
      and stored."DOCStoredObject_MimeType" = 'application/pdf'
      and stored."DOCStoredObject_StatusCode" = 'active'
      and stored."DOCStoredObject_DeletedAt" is null
      and creator."Company_ID" = app_user."Company_ID"
  ),
  all_documents as (
    select category, created_at, payload from quote_documents
    union all
    select category, created_at, payload from job_documents
  )
  select coalesce(
    jsonb_agg(payload order by
      case category when 'quote' then 1 when 'job' then 2 else 3 end,
      created_at desc nulls last
    ),
    '[]'::jsonb
  ) into documents_value
  from all_documents;

  return documents_value;
exception
  when no_data_found or too_many_rows then
    raise exception 'Your workspace identity is incomplete.' using errcode = '42501';
end;
$$;


ALTER FUNCTION "booking_api"."workspace_documents"("caller_auth_user_id" "uuid", "requested_job_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "booking_api"."workspace_documents"("caller_auth_user_id" "uuid", "requested_job_id" "uuid") IS 'Returns tenant-scoped booking documents. Quote PDFs are included only for submitted versions that have been accepted; historic accepted PDFs remain visible and metadata identifies the version currently applied to the booking.';



CREATE OR REPLACE FUNCTION "booking_api"."workspace_extended"("caller_auth_user_id" "uuid", "requested_reference" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare result jsonb; cargo jsonb; job_id uuid;
begin
  result:=booking_api.workspace_before_security_evidence_20260907(caller_auth_user_id,requested_reference);
  job_id:=nullif(result#>>'{booking,jobId}','')::uuid;
  if job_id is null then return result; end if;
  select coalesce(jsonb_agg(line||jsonb_build_object('securityEvidence',(
    select coalesce(jsonb_agg(booking_api.cargo_security_evidence_values(e) order by e.created_at,e.id),'[]'::jsonb)
    from booking_api.cargo_security_evidence e where e.cargo_id=c."JobCargo_ID"
  )) order by ordinal),'[]'::jsonb) into cargo
  from jsonb_array_elements(coalesce(result->'cargo','[]'::jsonb)) with ordinality entries(line,ordinal)
  join public."Job_Cargo" c on c."JobCargo_ID"::text=line->>'id' and c."JobCargo_JobID"=job_id and not c."JobCargo_IsDeleted";
  return jsonb_set(result,'{cargo}',cargo)||jsonb_build_object('securityEvidenceSupported',true);
end $$;


