    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
 select booking_api.workspace_before_lifecycle_20260910(caller_auth_user_id,requested_reference) || '{"lifecycleSupported":true}'::jsonb;
$$;


ALTER FUNCTION "booking_api"."workspace_with_document_groups"("caller_auth_user_id" "uuid", "requested_reference" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "document_api"."advance_draft_template_to_saved_version"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new."DOCBTV_StatusCode" = 'draft' then
    update public."DOCB_DocumentTemplates" template
    set "DOCBT_CurrentVersionNo" = new."DOCBTV_VersionNo",
        "DOCBT_UpdatedAt" = now()
    where template."DOCBT_ID" = new."DOCBTV_TemplateID"
      and template."DOCBT_StatusCode" = 'draft'
      and template."DOCBT_CurrentVersionNo" < new."DOCBTV_VersionNo";
  end if;
  return new;
end;
$$;


ALTER FUNCTION "document_api"."advance_draft_template_to_saved_version"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "document_api"."apply_job_render_content_selection"("caller_auth_user_id" "uuid", "requested_render_job_id" "uuid", "requested_content_sections" "text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  app_user_id uuid;
  render_job record;
  allowed_sections constant text[] := array['job', 'customer', 'shipper', 'consignee', 'cargo', 'routing'];
  selected_sections text[];
  selected_snapshot jsonb;
begin
  if caller_auth_user_id is null then
    raise exception 'authentication required' using errcode = '42501';
  end if;

  select user_row."User_ID"
  into strict app_user_id
  from public."cmp_Users" user_row
  where user_row."Auth_User_ID" = caller_auth_user_id;

  select render.*
  into strict render_job
  from public."DOCB_RenderJobs" render
  where render."DOCBRJ_ID" = requested_render_job_id
    and render."DOCBRJ_CreatedBy" = app_user_id
    and render."DOCBRJ_StatusCode" = 'rendering'
  for update;

  if requested_content_sections is null
     or cardinality(requested_content_sections) = 0
     or cardinality(requested_content_sections) > cardinality(allowed_sections)
     or not ('job' = any(requested_content_sections))
     or exists (
       select 1
       from unnest(requested_content_sections) requested(section_code)
       where requested.section_code is null
          or not (requested.section_code = any(allowed_sections))
     )
     or cardinality(requested_content_sections) <> (
       select count(distinct requested.section_code)
       from unnest(requested_content_sections) requested(section_code)
     ) then
    raise exception 'invalid document content selection' using errcode = '22023';
  end if;

  select array_agg(allowed.section_code order by allowed.ordinality)
  into selected_sections
  from unnest(allowed_sections) with ordinality allowed(section_code, ordinality)
  where allowed.section_code = any(requested_content_sections);

  selected_snapshot := jsonb_strip_nulls(jsonb_build_object(
    'meta', render_job."DOCBRJ_InputSnapshotJSON" -> 'meta',
    'selection', jsonb_build_object(
      'job', 'job' = any(selected_sections),
      'customer', 'customer' = any(selected_sections),
      'shipper', 'shipper' = any(selected_sections),
      'consignee', 'consignee' = any(selected_sections),
      'cargo', 'cargo' = any(selected_sections),
      'routing', 'routing' = any(selected_sections)
    ),
    'job', render_job."DOCBRJ_InputSnapshotJSON" -> 'job',
    'customer', case when 'customer' = any(selected_sections) then render_job."DOCBRJ_InputSnapshotJSON" -> 'customer' end,
    'shipper', case when 'shipper' = any(selected_sections) then render_job."DOCBRJ_InputSnapshotJSON" -> 'shipper' end,
    'consignee', case when 'consignee' = any(selected_sections) then render_job."DOCBRJ_InputSnapshotJSON" -> 'consignee' end,
    'cargo', case when 'cargo' = any(selected_sections) then render_job."DOCBRJ_InputSnapshotJSON" -> 'cargo' end,
    'routing', case when 'routing' = any(selected_sections) then render_job."DOCBRJ_InputSnapshotJSON" -> 'routing' end
  ));

  update public."DOCB_RenderJobs"
  set "DOCBRJ_InputSnapshotJSON" = selected_snapshot,
      "DOCBRJ_RenderSettingsJSON" = "DOCBRJ_RenderSettingsJSON" || jsonb_build_object('contentSections', to_jsonb(selected_sections))
  where "DOCBRJ_ID" = requested_render_job_id;

  return selected_snapshot;
exception
  when no_data_found or too_many_rows then
    raise exception 'document render selection is not authorised' using errcode = '42501';
end;
$$;


ALTER FUNCTION "document_api"."apply_job_render_content_selection"("caller_auth_user_id" "uuid", "requested_render_job_id" "uuid", "requested_content_sections" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "document_api"."approve_studio_template_version"("caller_auth_user_id" "uuid", "requested_template_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  app_user_id uuid;
  selected_template record;
  selected_version record;
begin
  if caller_auth_user_id is null
     or not document_api.has_permission(caller_auth_user_id, 'Documents.Manage') then
    raise exception 'document template approval is not authorised' using errcode = '42501';
  end if;

  select user_row."User_ID"
  into strict app_user_id
  from public."cmp_Users" user_row
  where user_row."Auth_User_ID" = caller_auth_user_id;

  select template.*
  into strict selected_template
  from public."DOCB_DocumentTemplates" template
  where template."DOCBT_ID" = requested_template_id
    and template."DOCBT_StatusCode" = 'draft'
    and template."DOCBT_IsActive" = true
    and template."DOCBT_IsUserEditable" = true
    and template."DOCBT_DefaultRenderEngineCode" = 'carbone'
  for update;

  select version.*
  into strict selected_version
  from public."DOCB_TemplateVersions" version
  where version."DOCBTV_TemplateID" = selected_template."DOCBT_ID"
    and version."DOCBTV_VersionNo" = selected_template."DOCBT_CurrentVersionNo"
    and version."DOCBTV_StatusCode" = 'draft'
    and version."DOCBTV_RenderEngineCode" = 'carbone'
    and version."DOCBTV_TemplateSnapshotJSON" #>> '{carbone,versionId}' ~ '^[0-9a-f]{64}$'
    and version."DOCBTV_TemplateSnapshotJSON" #>> '{source,provider}' = 'supabase_storage'
    and version."DOCBTV_TemplateSnapshotJSON" #>> '{source,path}' is not null
  for update;

  update public."DOCB_TemplateVersions" version
  set "DOCBTV_StatusCode" = 'published',
      "DOCBTV_PublishedAt" = now(),
      "DOCBTV_PublishedBy" = app_user_id,
      "DOCBTV_ChangeReason" = coalesce(version."DOCBTV_ChangeReason", 'Approved in the Multideck document builder.')
  where version."DOCBTV_ID" = selected_version."DOCBTV_ID";

  update public."DOCB_DocumentTemplates" template
  set "DOCBT_StatusCode" = 'published',
      "DOCBT_CurrentVersionNo" = selected_version."DOCBTV_VersionNo",
      "DOCBT_UpdatedAt" = now(),
      "DOCBT_UpdatedBy" = app_user_id
  where template."DOCBT_ID" = selected_template."DOCBT_ID";

  return jsonb_build_object(
    'templateCode', selected_template."DOCBT_Code",
    'templateVersion', selected_version."DOCBTV_VersionNo",
    'status', 'published'
  );
exception
  when no_data_found or too_many_rows then
    raise exception 'document template approval is not authorised' using errcode = '42501';
end;
$_$;


ALTER FUNCTION "document_api"."approve_studio_template_version"("caller_auth_user_id" "uuid", "requested_template_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "document_api"."authorize_download"("caller_auth_user_id" "uuid", "requested_generated_document_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  result jsonb;
begin
  if not document_api.has_permission(caller_auth_user_id, 'Documents.Read') then
    raise exception 'document download is not authorised' using errcode = '42501';
  end if;

  select jsonb_build_object(
    'bucket', generated."DOCBGD_StorageBucket",
    'path', generated."DOCBGD_StoragePath",
    'fileName', generated."DOCBGD_FileName"
  )
  into strict result
  from public."DOCB_GeneratedDocuments" generated
  join public."DOCB_RenderJobs" render on render."DOCBRJ_ID" = generated."DOCBGD_RenderJobID"
  join public."Job_Header" job on job."Job_ID" = render."DOCBRJ_JobID" and job."Job_IsDeleted" = false
  join public."cmp_Users" app_user on app_user."Auth_User_ID" = caller_auth_user_id
  join public."cmp_Users_Offices" user_office
    on user_office."User_ID" = app_user."User_ID" and user_office."Office_ID" = job."Job_OrgOfficeID"
  join public."cmp_Offices" office
    on office."Office_ID" = user_office."Office_ID" and office."Company_ID" = app_user."Company_ID"
  where generated."DOCBGD_ID" = requested_generated_document_id
    and generated."DOCBGD_IsCurrentVersion" = true
    and generated."DOCBGD_StorageBucket" is not null
    and generated."DOCBGD_StoragePath" is not null;

  return result;
exception
  when no_data_found or too_many_rows then
    raise exception 'document download is not authorised' using errcode = '42501';
end;
$$;


ALTER FUNCTION "document_api"."authorize_download"("caller_auth_user_id" "uuid", "requested_generated_document_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "document_api"."authorize_studio_template_save"("caller_auth_user_id" "uuid", "requested_template_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  result jsonb;
begin
  if caller_auth_user_id is null
     or not document_api.has_permission(caller_auth_user_id, 'Documents.Manage') then
    raise exception 'document template management is not authorised' using errcode = '42501';
  end if;

  select jsonb_strip_nulls(jsonb_build_object(
    'templateId', template."DOCBT_ID",
    'templateCode', template."DOCBT_Code",
    'templateName', template."DOCBT_Name",
    'carboneTemplateId', case
      when template."DOCBT_SettingsJSON" #>> '{carbone,templateId}' ~ '^[0-9]{1,20}$'
        then template."DOCBT_SettingsJSON" #>> '{carbone,templateId}'
      else null
    end
  ))
  into strict result
  from public."DOCB_DocumentTemplates" template
  where template."DOCBT_ID" = requested_template_id
    and template."DOCBT_IsActive" = true
    and template."DOCBT_IsUserEditable" = true
    and template."DOCBT_DefaultRenderEngineCode" = 'carbone';

  return result;
exception
  when no_data_found or too_many_rows then
    raise exception 'document template management is not authorised' using errcode = '42501';
end;
$_$;


ALTER FUNCTION "document_api"."authorize_studio_template_save"("caller_auth_user_id" "uuid", "requested_template_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "document_api"."complete_job_render"("caller_auth_user_id" "uuid", "requested_render_job_id" "uuid", "generated_document_id" "uuid", "storage_bucket" "text", "storage_path" "text", "original_file_name" "text", "mime_type" "text", "file_size_bytes" bigint, "sha256" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  render_job record;
  actor_user_id uuid;
  customer_organisation_id uuid;
  stored_object_id uuid := gen_random_uuid();
begin
  select app_user."User_ID" into strict actor_user_id
  from public."cmp_Users" app_user
  where app_user."Auth_User_ID" = caller_auth_user_id;

  select render.* into strict render_job
  from public."DOCB_RenderJobs" render
  where render."DOCBRJ_ID" = requested_render_job_id
    and render."DOCBRJ_CreatedBy" = actor_user_id
    and render."DOCBRJ_StatusCode" = 'rendering';

  customer_organisation_id := (render_job."DOCBRJ_InputSnapshotJSON" #>> '{customer,id}')::uuid;

  insert into public."DOCB_GeneratedDocuments" (
    "DOCBGD_ID", "DOCBGD_RenderJobID", "DOCBGD_TemplateID", "DOCBGD_TemplateVersionID",
    "DOCBGD_OutputFormatCode", "DOCBGD_FileName", "DOCBGD_StorageBucket", "DOCBGD_StoragePath",
    "DOCBGD_MimeType", "DOCBGD_FileSizeBytes", "DOCBGD_SHA256", "DOCBGD_VersionNo",
    "DOCBGD_IsCurrentVersion", "DOCBGD_MetadataJSON", "DOCBGD_CreatedBy"
  ) values (
    generated_document_id, render_job."DOCBRJ_ID", render_job."DOCBRJ_TemplateID", render_job."DOCBRJ_TemplateVersionID",
    render_job."DOCBRJ_OutputFormatCode", original_file_name, storage_bucket, storage_path,
    mime_type, file_size_bytes, sha256, 1, true,
    jsonb_build_object('storedObjectId', stored_object_id, 'targetType', 'Job_Header', 'targetId', render_job."DOCBRJ_TargetID"),
    actor_user_id
  );

  insert into public."DOC_StoredObjects" (
    "DOCStoredObject_ID", "DOCStoredObject_ConcernCode", "DOCStoredObject_OrganisationID",
    "DOCStoredObject_AggregateType", "DOCStoredObject_AggregateID", "DOCStoredObject_ProviderCode",
    "DOCStoredObject_Container", "DOCStoredObject_BlobName", "DOCStoredObject_OriginalFileName",
    "DOCStoredObject_MimeType", "DOCStoredObject_FileSizeBytes", "DOCStoredObject_SHA256",
    "DOCStoredObject_StatusCode", "DOCStoredObject_CreatedBy"
  ) values (
    stored_object_id, 'generated', customer_organisation_id,
    'DOCB_GeneratedDocument', generated_document_id, 'supabase_storage',
    storage_bucket, storage_path, original_file_name,
    mime_type, file_size_bytes, sha256, 'active', actor_user_id
  );

  update public."DOCB_RenderJobs"
  set "DOCBRJ_StatusCode" = 'completed', "DOCBRJ_CompletedAt" = now(), "DOCBRJ_ErrorMessage" = null
  where "DOCBRJ_ID" = requested_render_job_id;

  return jsonb_build_object('generatedDocumentId', generated_document_id, 'storedObjectId', stored_object_id);
exception
  when no_data_found or too_many_rows then
    raise exception 'render completion is not authorised' using errcode = '42501';
end;
$$;


ALTER FUNCTION "document_api"."complete_job_render"("caller_auth_user_id" "uuid", "requested_render_job_id" "uuid", "generated_document_id" "uuid", "storage_bucket" "text", "storage_path" "text", "original_file_name" "text", "mime_type" "text", "file_size_bytes" bigint, "sha256" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "document_api"."create_studio_template"("caller_auth_user_id" "uuid", "requested_template_code" "text", "requested_template_name" "text", "requested_description" "text" DEFAULT NULL::"text", "requested_language_code" "text" DEFAULT 'en'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  app_user_id uuid;
  template_code text := upper(trim(coalesce(requested_template_code, '')));
  template_name text := trim(coalesce(requested_template_name, ''));
  language_code text := lower(trim(coalesce(requested_language_code, 'en')));
  template_id uuid;
  existing_created_by uuid;
  existing_status text;
begin
  if caller_auth_user_id is null
     or not document_api.has_permission(caller_auth_user_id, 'Documents.Manage') then
    raise exception 'document template management is not authorised' using errcode = '42501';
  end if;

  if template_code !~ '^[A-Z0-9][A-Z0-9_-]{1,99}$' then
    raise exception 'Choose a valid template code.' using errcode = '22023';
  end if;
  if length(template_name) < 2 or length(template_name) > 180 then
    raise exception 'Choose a template name between 2 and 180 characters.' using errcode = '22023';
  end if;
  if language_code !~ '^[a-z]{2,10}$' then
    raise exception 'Choose a valid template language.' using errcode = '22023';
  end if;

  select user_row."User_ID"
  into strict app_user_id
  from public."cmp_Users" user_row
  where user_row."Auth_User_ID" = caller_auth_user_id;

  select template."DOCBT_ID", template."DOCBT_CreatedBy", template."DOCBT_StatusCode"
  into template_id, existing_created_by, existing_status
  from public."DOCB_DocumentTemplates" template
  where upper(template."DOCBT_Code") = template_code
  limit 1;

  if template_id is not null then
    if existing_created_by <> app_user_id or existing_status <> 'draft' then
      raise exception 'A template with this code already exists.' using errcode = '23505';
    end if;

    update public."DOCB_DocumentTemplates"
    set "DOCBT_Name" = template_name,
        "DOCBT_LanguageCode" = language_code,
        "DOCBT_Description" = nullif(trim(requested_description), ''),
        "DOCBT_UpdatedBy" = app_user_id
    where "DOCBT_ID" = template_id;
  else
    insert into public."DOCB_DocumentTemplates" (
      "DOCBT_Code",
      "DOCBT_Name",
      "DOCBT_DataScopeCode",
      "DOCBT_StatusCode",
      "DOCBT_CurrentVersionNo",
      "DOCBT_DefaultRenderEngineCode",
      "DOCBT_DefaultOutputFormatCode",
      "DOCBT_LanguageCode",
      "DOCBT_Description",
      "DOCBT_SettingsJSON",
      "DOCBT_IsSystem",
      "DOCBT_IsUserEditable",
      "DOCBT_IsActive",
      "DOCBT_CreatedBy",
      "DOCBT_UpdatedBy"
    ) values (
      template_code,
      template_name,
      'job',
      'draft',
      1,
      'carbone',
      'pdf',
      language_code,
      nullif(trim(requested_description), ''),
      jsonb_build_object(
        'outputFormats', jsonb_build_array('pdf', 'docx'),
        'source', jsonb_build_object('origin', 'operator-upload', 'status', 'draft')
      ),
      false,
      true,
      true,
      app_user_id,
      app_user_id
    )
    returning "DOCBT_ID" into template_id;

    insert into public."DOCB_TemplateVersions" (
      "DOCBTV_TemplateID",
      "DOCBTV_VersionNo",
      "DOCBTV_StatusCode",
      "DOCBTV_RenderEngineCode",
      "DOCBTV_OutputFormatCode",
      "DOCBTV_TemplateSnapshotJSON",
      "DOCBTV_ChangeReason",
      "DOCBTV_CreatedBy"
    ) values (
      template_id,
      1,
      'draft',
      'carbone',
      'pdf',
      jsonb_build_object(
        'schemaVersion', 1,
        'source', jsonb_build_object('origin', 'operator-upload', 'status', 'draft')
      ),
      'Created from the Multideck template upload flow.',
      app_user_id
    );
  end if;

  return jsonb_build_object(
    'multideckTemplateId', template_id,
    'templateCode', template_code,
    'templateName', template_name,
    'multideckVersion', coalesce((select "DOCBT_CurrentVersionNo" from public."DOCB_DocumentTemplates" where "DOCBT_ID" = template_id), 1),
    'status', 'draft'
  );
exception
  when no_data_found or too_many_rows then
    raise exception 'document template management is not authorised' using errcode = '42501';
end;
$_$;


ALTER FUNCTION "document_api"."create_studio_template"("caller_auth_user_id" "uuid", "requested_template_code" "text", "requested_template_name" "text", "requested_description" "text", "requested_language_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "document_api"."fail_job_render"("caller_auth_user_id" "uuid", "requested_render_job_id" "uuid", "safe_error_message" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_user_id uuid;
begin
  select app_user."User_ID" into strict actor_user_id
  from public."cmp_Users" app_user
  where app_user."Auth_User_ID" = caller_auth_user_id;

  update public."DOCB_RenderJobs"
  set "DOCBRJ_StatusCode" = 'failed',
      "DOCBRJ_CompletedAt" = now(),
      "DOCBRJ_ErrorMessage" = left(coalesce(safe_error_message, 'Document render failed'), 1000)
  where "DOCBRJ_ID" = requested_render_job_id
    and "DOCBRJ_CreatedBy" = actor_user_id
    and "DOCBRJ_StatusCode" in ('queued', 'rendering');
end;
$$;


ALTER FUNCTION "document_api"."fail_job_render"("caller_auth_user_id" "uuid", "requested_render_job_id" "uuid", "safe_error_message" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "document_api"."generated_documents_page"("caller_auth_user_id" "uuid", "p_search" "text" DEFAULT NULL::"text", "p_sort_column" "text" DEFAULT 'created'::"text", "p_sort_direction" "text" DEFAULT 'desc'::"text", "p_limit" integer DEFAULT 20, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  app_user record;
  search_term text := nullif(left(trim(coalesce(p_search, '')), 120), '');
  sort_column text := case when p_sort_column in ('document', 'job', 'customer', 'created', 'status') then p_sort_column else 'created' end;
  sort_direction text := case when lower(p_sort_direction) = 'asc' then 'asc' else 'desc' end;
  page_limit integer := greatest(1, least(coalesce(p_limit, 20), 50));
  page_offset integer := greatest(coalesce(p_offset, 0), 0);
  total_count bigint;
  page_rows jsonb;
begin
  select user_row."User_ID", user_row."Company_ID"
  into strict app_user
  from public."cmp_Users" user_row
  where user_row."Auth_User_ID" = caller_auth_user_id;

  if not document_api.has_permission(caller_auth_user_id, 'Documents.Read') then
    raise exception 'document access is not authorised' using errcode = '42501';
  end if;

  select count(*)
  into total_count
  from public."DOCB_GeneratedDocuments" generated
  join public."DOCB_RenderJobs" render on render."DOCBRJ_ID" = generated."DOCBGD_RenderJobID"
  join public."DOCB_DocumentTemplates" template on template."DOCBT_ID" = generated."DOCBGD_TemplateID"
  join public."Job_Header" job on job."Job_ID" = render."DOCBRJ_JobID" and job."Job_IsDeleted" = false
  join public."cmp_Users_Offices" user_office
    on user_office."User_ID" = app_user."User_ID" and user_office."Office_ID" = job."Job_OrgOfficeID"
  join public."cmp_Offices" office
    on office."Office_ID" = user_office."Office_ID" and office."Company_ID" = app_user."Company_ID"
  left join public."Org_Master" customer on customer."Org_id" = job."Job_Customer"
  where search_term is null
    or generated."DOCBGD_FileName" ilike '%' || search_term || '%'
    or template."DOCBT_Name" ilike '%' || search_term || '%'
    or concat(job."Job_Period", '-', job."Job_Number") ilike '%' || search_term || '%'
    or customer."Org_Name" ilike '%' || search_term || '%';

  select coalesce(jsonb_agg(document_row), '[]'::jsonb)
  into page_rows
  from (
    select jsonb_build_object(
      'id', generated."DOCBGD_ID",
      'renderJobId', generated."DOCBGD_RenderJobID",
      'templateCode', template."DOCBT_Code",
      'templateName', template."DOCBT_Name",
      'targetType', render."DOCBRJ_TargetTable",
      'targetId', render."DOCBRJ_TargetID",
      'targetReference', concat(job."Job_Period", '-', job."Job_Number"),
      'customerName', customer."Org_Name",
      'fileName', generated."DOCBGD_FileName",
      'outputFormat', generated."DOCBGD_OutputFormatCode",
      'mimeType', generated."DOCBGD_MimeType",
      'fileSizeBytes', generated."DOCBGD_FileSizeBytes",
      'status', case render."DOCBRJ_StatusCode"
        when 'completed' then 'ready'
        when 'completed_with_warnings' then 'ready'
        when 'rendering' then 'rendering'
        when 'queued' then 'queued'
        else 'failed'
      end,
      'createdAt', generated."DOCBGD_CreatedAt",
      'createdBy', concat_ws(' ', creator."User_Firstname", creator."User_Lastname"),
      'failureReason', render."DOCBRJ_ErrorMessage"
    ) as document_row
    from public."DOCB_GeneratedDocuments" generated
    join public."DOCB_RenderJobs" render on render."DOCBRJ_ID" = generated."DOCBGD_RenderJobID"
    join public."DOCB_DocumentTemplates" template on template."DOCBT_ID" = generated."DOCBGD_TemplateID"
    join public."Job_Header" job on job."Job_ID" = render."DOCBRJ_JobID" and job."Job_IsDeleted" = false
    join public."cmp_Users_Offices" user_office
      on user_office."User_ID" = app_user."User_ID" and user_office."Office_ID" = job."Job_OrgOfficeID"
    join public."cmp_Offices" office
      on office."Office_ID" = user_office."Office_ID" and office."Company_ID" = app_user."Company_ID"
    left join public."Org_Master" customer on customer."Org_id" = job."Job_Customer"
    left join public."cmp_Users" creator on creator."User_ID" = generated."DOCBGD_CreatedBy"
    where search_term is null
      or generated."DOCBGD_FileName" ilike '%' || search_term || '%'
      or template."DOCBT_Name" ilike '%' || search_term || '%'
      or concat(job."Job_Period", '-', job."Job_Number") ilike '%' || search_term || '%'
      or customer."Org_Name" ilike '%' || search_term || '%'
    order by
      case when sort_column = 'document' and sort_direction = 'asc' then lower(generated."DOCBGD_FileName") end asc,
      case when sort_column = 'document' and sort_direction = 'desc' then lower(generated."DOCBGD_FileName") end desc,
      case when sort_column = 'job' and sort_direction = 'asc' then concat(job."Job_Period", '-', job."Job_Number") end asc,
      case when sort_column = 'job' and sort_direction = 'desc' then concat(job."Job_Period", '-', job."Job_Number") end desc,
      case when sort_column = 'customer' and sort_direction = 'asc' then lower(coalesce(customer."Org_Name", '')) end asc,
      case when sort_column = 'customer' and sort_direction = 'desc' then lower(coalesce(customer."Org_Name", '')) end desc,
      case when sort_column = 'created' and sort_direction = 'asc' then generated."DOCBGD_CreatedAt" end asc,
      case when sort_column = 'created' and sort_direction = 'desc' then generated."DOCBGD_CreatedAt" end desc,
      case when sort_column = 'status' and sort_direction = 'asc' then render."DOCBRJ_StatusCode" end asc,
      case when sort_column = 'status' and sort_direction = 'desc' then render."DOCBRJ_StatusCode" end desc,
      generated."DOCBGD_CreatedAt" desc,
      generated."DOCBGD_ID" desc
    limit page_limit
    offset page_offset
  ) page;

  return jsonb_build_object(
    'rows', page_rows,
    'total', total_count,
    'offset', page_offset,
    'limit', page_limit
  );
exception
  when no_data_found or too_many_rows then
    raise exception 'document identity is ambiguous' using errcode = '42501';
end;
$$;


ALTER FUNCTION "document_api"."generated_documents_page"("caller_auth_user_id" "uuid", "p_search" "text", "p_sort_column" "text", "p_sort_direction" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "document_api"."generated_documents_page"("caller_auth_user_id" "uuid", "p_search" "text", "p_sort_column" "text", "p_sort_direction" "text", "p_limit" integer, "p_offset" integer) IS 'Service-role-only, office-scoped generated-document register page capped at 50 rows.';



CREATE OR REPLACE FUNCTION "document_api"."has_permission"("caller_auth_user_id" "uuid", "permission_value" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (
    select 1
    from public."cmp_Users" app_user
    join public."cmp_Users_Roles" user_role
      on user_role."User_ID" = app_user."User_ID"
    join public."sys_UserRole_Permissions" role_permission
      on role_permission."sys_UserRole_ID" = user_role."sys_UserRole_ID"
    join public."sys_Permissions" permission
      on permission."sys_Permission_ID" = role_permission."sys_Permission_ID"
    where app_user."Auth_User_ID" = caller_auth_user_id
      and permission."sys_Permission_Value" = permission_value
  );
$$;


ALTER FUNCTION "document_api"."has_permission"("caller_auth_user_id" "uuid", "permission_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "document_api"."party_json"("party_id" "uuid", "address_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select case when organisation."Org_id" is null then null else jsonb_strip_nulls(jsonb_build_object(
    'id', organisation."Org_id",
    'name', organisation."Org_Name",
    'address', case when address."OrgAdd_ID" is null then null else jsonb_strip_nulls(jsonb_build_object(
      'id', address."OrgAdd_ID",
      'name', address."Org_NameOverride",
      'line1', address."OrgAdd_Line1",
      'line2', address."OrgAdd_Line2",
      'city', address."OrgAdd_TownCity",
      'countyOrState', address."OrgAdd_CountyState",
      'postalCode', address."OrgAdd_PostZipCode",
      'countryCode', address."OrgAdd_Country",
      'unlocode', address."OrgAdd_UNLOCODE",
      'email', address."OrgAdd_MainEmail",
      'phone', address."OrgAdd_MainPhone"
    )) end
  )) end
  from (select 1) seed
  left join public."Org_Master" organisation on organisation."Org_id" = party_id
  left join public."Org_Addresses" address
    on address."OrgAdd_ID" = address_id
   and address."Org_ID" = organisation."Org_id";
$$;


ALTER FUNCTION "document_api"."party_json"("party_id" "uuid", "address_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "document_api"."prepare_job_render"("caller_auth_user_id" "uuid", "requested_template_code" "text", "requested_job_number" "text", "requested_output_format" "text", "requested_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select document_api.prepare_job_render(
    caller_auth_user_id => caller_auth_user_id,
    requested_template_code => requested_template_code,
    requested_job_id => document_api.resolve_authorised_job_id_by_number(
      caller_auth_user_id,
      requested_job_number
    ),
    requested_output_format => requested_output_format,
    requested_reason => requested_reason
  );
$$;


ALTER FUNCTION "document_api"."prepare_job_render"("caller_auth_user_id" "uuid", "requested_template_code" "text", "requested_job_number" "text", "requested_output_format" "text", "requested_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "document_api"."prepare_job_render"("caller_auth_user_id" "uuid", "requested_template_code" "text", "requested_job_id" "uuid", "requested_output_format" "text", "requested_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  app_user record;
  job record;
  selected_template record;
  selected_version record;
  candidate_template_id uuid;
  candidate_count integer;
  max_specificity integer;
  carbone_reference text;
  input_snapshot jsonb;
  render_job_id uuid := gen_random_uuid();
  correlation_id uuid := gen_random_uuid();
begin
  if caller_auth_user_id is null then
    raise exception 'authentication required' using errcode = '42501';
  end if;

  select user_row."User_ID", user_row."Company_ID"
  into strict app_user
  from public."cmp_Users" user_row
  where user_row."Auth_User_ID" = caller_auth_user_id;

  if app_user."Company_ID" is null
     or not document_api.has_permission(caller_auth_user_id, 'Documents.Generate') then
    raise exception 'document generation is not authorised' using errcode = '42501';
  end if;

  select job_row.*
  into strict job
  from public."Job_Header" job_row
  join public."cmp_Offices" office
    on office."Office_ID" = job_row."Job_OrgOfficeID"
   and office."Company_ID" = app_user."Company_ID"
   and office."Office_IsActive" = true
  join public."cmp_Users_Offices" user_office
    on user_office."Office_ID" = office."Office_ID"
   and user_office."User_ID" = app_user."User_ID"
  where job_row."Job_ID" = requested_job_id
    and job_row."Job_IsDeleted" = false;

  if requested_output_format not in ('pdf', 'docx') then
    raise exception 'unsupported output format' using errcode = '22023';
  end if;

  select max(
    (case when template."DOCBT_OrgOfficeID" is not null then 8 else 0 end) +
    (case when template."DOCBT_LegalEntityID" is not null then 4 else 0 end) +
    (case when template."DOCBT_BrandID" is not null then 2 else 0 end) +
    (case when template."DOCBT_CustomerOrgID" is not null then 1 else 0 end)
  )
  into max_specificity
  from public."DOCB_DocumentTemplates" template
  where template."DOCBT_Code" = requested_template_code
    and template."DOCBT_StatusCode" = 'published'
    and template."DOCBT_IsActive" = true
    and template."DOCBT_DefaultRenderEngineCode" = 'carbone'
    and (template."DOCBT_OrgOfficeID" is null or template."DOCBT_OrgOfficeID" = job."Job_OrgOfficeID")
    and (template."DOCBT_LegalEntityID" is null or template."DOCBT_LegalEntityID" = job."Job_LegalEntityID")
    and (template."DOCBT_BrandID" is null or template."DOCBT_BrandID" = job."Job_BrandID")
    and (template."DOCBT_CustomerOrgID" is null or template."DOCBT_CustomerOrgID" = job."Job_Customer");

  if max_specificity is null then
    raise exception 'no published template matches the requested job' using errcode = 'P0002';
  end if;

  select count(*), min(template."DOCBT_ID"::text)::uuid
  into candidate_count, candidate_template_id
  from public."DOCB_DocumentTemplates" template
  where template."DOCBT_Code" = requested_template_code
    and template."DOCBT_StatusCode" = 'published'
    and template."DOCBT_IsActive" = true
    and template."DOCBT_DefaultRenderEngineCode" = 'carbone'
    and (template."DOCBT_OrgOfficeID" is null or template."DOCBT_OrgOfficeID" = job."Job_OrgOfficeID")
    and (template."DOCBT_LegalEntityID" is null or template."DOCBT_LegalEntityID" = job."Job_LegalEntityID")
    and (template."DOCBT_BrandID" is null or template."DOCBT_BrandID" = job."Job_BrandID")
    and (template."DOCBT_CustomerOrgID" is null or template."DOCBT_CustomerOrgID" = job."Job_Customer")
    and (
      (case when template."DOCBT_OrgOfficeID" is not null then 8 else 0 end) +
      (case when template."DOCBT_LegalEntityID" is not null then 4 else 0 end) +
      (case when template."DOCBT_BrandID" is not null then 2 else 0 end) +
      (case when template."DOCBT_CustomerOrgID" is not null then 1 else 0 end)
    ) = max_specificity;

  if candidate_count <> 1 then
    raise exception 'template resolution is ambiguous' using errcode = '21000';
  end if;

  select template.*
  into strict selected_template
  from public."DOCB_DocumentTemplates" template
  where template."DOCBT_ID" = candidate_template_id;

  select version.*
  into strict selected_version
  from public."DOCB_TemplateVersions" version
  where version."DOCBTV_TemplateID" = selected_template."DOCBT_ID"
    and version."DOCBTV_VersionNo" = selected_template."DOCBT_CurrentVersionNo"
    and version."DOCBTV_StatusCode" = 'published'
    and version."DOCBTV_RenderEngineCode" = 'carbone';

  if requested_output_format <> selected_template."DOCBT_DefaultOutputFormatCode"
     and not coalesce(selected_template."DOCBT_SettingsJSON" -> 'outputFormats', '[]'::jsonb) ? requested_output_format then
    raise exception 'output format is not enabled for this template' using errcode = '22023';
  end if;

  carbone_reference := coalesce(
    selected_version."DOCBTV_TemplateSnapshotJSON" #>> '{carbone,versionId}',
    selected_version."DOCBTV_TemplateSnapshotJSON" #>> '{carbone,templateId}',
    selected_template."DOCBT_SettingsJSON" #>> '{carbone,templateId}'
  );

  if carbone_reference is null or carbone_reference !~ '^[A-Za-z0-9._-]{8,128}$' then
    raise exception 'published template has no valid Carbone template reference' using errcode = '22023';
  end if;

  input_snapshot := jsonb_build_object(
    'meta', jsonb_build_object(
      'schemaVersion', 1,
      'generatedAt', now(),
      'correlationId', correlation_id,
      'templateCode', selected_template."DOCBT_Code",
      'templateVersion', selected_version."DOCBTV_VersionNo",
      'languageCode', selected_template."DOCBT_LanguageCode"
    ),
    'job', jsonb_strip_nulls(jsonb_build_object(
      'id', job."Job_ID",
      'number', job."Job_Number",
      'period', job."Job_Period",
      'createdAt', job."Job_CreatedDate",
      'status', job."Job_Status",
      'direction', job."Job_Direction",
      'transportMode', job."Job_TransportModeSummary",
      'origin', jsonb_strip_nulls(jsonb_build_object('unlocode', job."Job_OriginUNLocode", 'name', job."Job_OriginNameSnapshot")),
      'destination', jsonb_strip_nulls(jsonb_build_object('unlocode', job."Job_DestinationUNLocode", 'name', job."Job_DestinationNameSnapshot")),
      'readyDate', job."Job_ReadyDate",
      'requiredDeliveryDate', job."Job_RequiredDeliveryDate",
      'officeId', job."Job_OrgOfficeID",
      'legalEntityName', job."Job_LegalEntityNameSnapshot",
      'brandName', job."Job_BrandNameSnapshot"
    )),
    'customer', document_api.party_json(job."Job_Customer", job."Job_CustomerAddress"),
    'shipper', document_api.party_json(job."Job_Shipper", job."Job_ShipperAddress"),
    'consignee', document_api.party_json(job."Job_Consignee", job."Job_ConsigneeAddress"),
    'cargo', coalesce((
      select jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
        'id', cargo."JobCargo_ID",
        'lineNumber', cargo."JobCargo_LineNo",
        'commodity', cargo."JobCargo_Commodity",
        'description', cargo."JobCargo_Description",
        'packageType', cargo."JobCargo_PackageTypeCodeSnapshot",
        'packageQuantity', cargo."JobCargo_PackageQty",
        'grossWeight', cargo."JobCargo_GrossKilos",
        'netWeight', cargo."JobCargo_NettKilos",
        'weightUnit', cargo."JobCargo_WeightUnit",
        'volume', cargo."JobCargo_VolumeCBM",
        'volumeUnit', cargo."JobCargo_VolumeUnit",
        'marksAndNumbers', cargo."JobCargo_MarksNumbers",
        'hsCode', cargo."JobCargo_HSCode",
        'countryOfOrigin', cargo."JobCargo_CountryOfOriginCodeSnapshot",
        'isHazardous', cargo."JobCargo_IsHazardous"
      )) order by cargo."JobCargo_LineNo" nulls last, cargo."JobCargo_ID")
      from public."Job_Cargo" cargo
      where cargo."JobCargo_JobID" = job."Job_ID" and cargo."JobCargo_IsDeleted" = false
    ), '[]'::jsonb),
    'routing', coalesce((
      select jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
        'id', route."JobRoute_ID",
        'sequence', route."JobRoute_OrderNo",
        'status', route."JobRoute_Status",
        'mode', route."JobRoute_ModeCode",
        'origin', jsonb_strip_nulls(jsonb_build_object('unlocode', route."JobRoute_OriginUNLocode", 'name', route."JobRoute_OriginNameSnapshot", 'terminal', route."JobRoute_OriginTerminal")),
        'destination', jsonb_strip_nulls(jsonb_build_object('unlocode', route."JobRoute_DestinationUNLocode", 'name', route."JobRoute_DestinationNameSnapshot", 'terminal', route."JobRoute_DestinationTerminal")),
        'plannedDepartureAt', route."JobRoute_PlannedDepartureAt",
        'estimatedDepartureAt', route."JobRoute_EstimatedDepartureAt",
        'actualDepartureAt', route."JobRoute_ActualDepartureAt",
        'plannedArrivalAt', route."JobRoute_PlannedArrivalAt",
        'estimatedArrivalAt', route."JobRoute_EstimatedArrivalAt",
        'actualArrivalAt', route."JobRoute_ActualArrivalAt",
        'vessel', route."JobRoute_Vessel",
        'voyageNumber', route."JobRoute_VoyageNumber",
        'flightNumber', route."JobRoute_FlightNumber",
        'carrierBookingReference', route."JobRoute_CarrierBookingReference",
        'masterTransportReference', route."JobRoute_MasterTransportReference",
        'houseTransportReference', route."JobRoute_HouseTransportReference",
        'isMainCarriage', route."JobRoute_IsMainCarriage"
      )) order by route."JobRoute_OrderNo" nulls last, route."JobRoute_ID")
      from public."Job_Routing" route
      where route."Job_ID" = job."Job_ID"
    ), '[]'::jsonb)
  );

  if input_snapshot #>> '{customer,id}' is null then
    raise exception 'job customer identity is missing or invalid' using errcode = '42501';
  end if;

  insert into public."DOCB_RenderJobs" (
    "DOCBRJ_ID", "DOCBRJ_TemplateID", "DOCBRJ_TemplateVersionID", "DOCBRJ_StatusCode",
    "DOCBRJ_RenderEngineCode", "DOCBRJ_OutputFormatCode", "DOCBRJ_TargetTable",
    "DOCBRJ_TargetID", "DOCBRJ_JobID", "DOCBRJ_InputSnapshotJSON",
    "DOCBRJ_RenderSettingsJSON", "DOCBRJ_StartedAt", "DOCBRJ_CreatedBy"
  ) values (
    render_job_id, selected_template."DOCBT_ID", selected_version."DOCBTV_ID", 'rendering',
    selected_version."DOCBTV_RenderEngineCode", requested_output_format, 'Job_Header',
    job."Job_ID", job."Job_ID", input_snapshot,
    jsonb_strip_nulls(jsonb_build_object('provider', 'carbone', 'correlationId', correlation_id, 'reason', nullif(trim(requested_reason), ''))),
    now(), app_user."User_ID"
  );

  return jsonb_build_object(
    'renderJobId', render_job_id,
    'templateId', selected_template."DOCBT_ID",
    'templateVersionId', selected_version."DOCBTV_ID",
    'templateCode', selected_template."DOCBT_Code",
    'carboneTemplateReference', carbone_reference,
    'outputFormat', requested_output_format,
    'languageCode', selected_template."DOCBT_LanguageCode",
    'jobId', job."Job_ID",
    'jobReference', concat(job."Job_Period", '-', job."Job_Number"),
    'companyId', app_user."Company_ID",
    'customerOrganisationId', job."Job_Customer",
    'customerName', input_snapshot #>> '{customer,name}',
    'actorUserId', app_user."User_ID",
    'dataset', input_snapshot
  );
exception
  when no_data_found or too_many_rows then
    raise exception 'document identity or access is ambiguous' using errcode = '42501';
end;
$_$;


ALTER FUNCTION "document_api"."prepare_job_render"("caller_auth_user_id" "uuid", "requested_template_code" "text", "requested_job_id" "uuid", "requested_output_format" "text", "requested_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "document_api"."prepare_studio_job_session"("caller_auth_user_id" "uuid", "requested_template_code" "text", "requested_job_number" "text", "requested_content_sections" "text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  session_data jsonb;
  selected_template record;
  current_reference text;
  stable_template_id text;
  version_id text;
begin
  session_data := document_api.prepare_studio_job_session(
    caller_auth_user_id => caller_auth_user_id,
    requested_template_code => requested_template_code,
    requested_job_id => document_api.resolve_authorised_job_id_by_number(
      caller_auth_user_id,
      requested_job_number
    ),
    requested_content_sections => requested_content_sections
  );

  current_reference := session_data ->> 'carboneTemplateReference';

  select
    template."DOCBT_ID",
    template."DOCBT_DataScopeCode",
    template."DOCBT_SettingsJSON" #>> '{carbone,templateId}' as provider_template_id,
    version."DOCBTV_TemplateSnapshotJSON" #>> '{carbone,versionId}' as provider_version_id
  into strict selected_template
  from public."DOCB_DocumentTemplates" template
  join public."DOCB_TemplateVersions" version
    on version."DOCBTV_TemplateID" = template."DOCBT_ID"
   and version."DOCBTV_VersionNo" = template."DOCBT_CurrentVersionNo"
  where template."DOCBT_Code" = session_data ->> 'templateCode'
    and coalesce(
      version."DOCBTV_TemplateSnapshotJSON" #>> '{carbone,versionId}',
      version."DOCBTV_TemplateSnapshotJSON" #>> '{carbone,templateId}',
      template."DOCBT_SettingsJSON" #>> '{carbone,templateId}'
    ) = current_reference;

  stable_template_id := case
    when selected_template.provider_template_id ~ '^[0-9]{1,20}$'
      then selected_template.provider_template_id
    else null
  end;
  version_id := coalesce(
    selected_template.provider_version_id,
    case when current_reference ~ '^[0-9a-f]{64}$' then current_reference end
  );

  return session_data || jsonb_strip_nulls(jsonb_build_object(
    'multideckTemplateId', selected_template."DOCBT_ID",
    'dataModuleCode', selected_template."DOCBT_DataScopeCode",
    'dataModuleName', case selected_template."DOCBT_DataScopeCode"
      when 'job' then 'Jobs'
      else initcap(replace(selected_template."DOCBT_DataScopeCode", '_', ' '))
    end,
    'carboneTemplateId', stable_template_id,
    'carboneVersionId', version_id
  ));
exception
  when no_data_found or too_many_rows then
    raise exception 'document studio template identity is ambiguous' using errcode = '42501';
end;
$_$;


ALTER FUNCTION "document_api"."prepare_studio_job_session"("caller_auth_user_id" "uuid", "requested_template_code" "text", "requested_job_number" "text", "requested_content_sections" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "document_api"."prepare_studio_job_session"("caller_auth_user_id" "uuid", "requested_template_code" "text", "requested_job_id" "uuid", "requested_content_sections" "text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  app_user record;
  job record;
  selected_template record;
  selected_version record;
  candidate_template_id uuid;
  candidate_count integer;
  max_specificity integer;
  carbone_reference text;
  input_snapshot jsonb;
  selected_snapshot jsonb;
  allowed_sections constant text[] := array['job', 'customer', 'shipper', 'consignee', 'cargo', 'routing'];
  selected_sections text[];
begin
  if caller_auth_user_id is null then
    raise exception 'authentication required' using errcode = '42501';
  end if;

  select user_row."User_ID", user_row."Company_ID"
  into strict app_user
  from public."cmp_Users" user_row
  where user_row."Auth_User_ID" = caller_auth_user_id;

  if app_user."Company_ID" is null
     or not document_api.has_permission(caller_auth_user_id, 'Documents.Generate') then
    raise exception 'document studio access is not authorised' using errcode = '42501';
  end if;

  if requested_content_sections is null
     or cardinality(requested_content_sections) = 0
     or cardinality(requested_content_sections) > cardinality(allowed_sections)
     or not ('job' = any(requested_content_sections))
     or exists (
       select 1
       from unnest(requested_content_sections) requested(section_code)
       where requested.section_code is null
          or not (requested.section_code = any(allowed_sections))
     )
     or cardinality(requested_content_sections) <> (
       select count(distinct requested.section_code)
       from unnest(requested_content_sections) requested(section_code)
     ) then
    raise exception 'invalid document studio content selection' using errcode = '22023';
  end if;

  select array_agg(allowed.section_code order by allowed.ordinality)
  into selected_sections
  from unnest(allowed_sections) with ordinality allowed(section_code, ordinality)
  where allowed.section_code = any(requested_content_sections);

  select job_row.*
  into strict job
  from public."Job_Header" job_row
  join public."cmp_Offices" office
    on office."Office_ID" = job_row."Job_OrgOfficeID"
   and office."Company_ID" = app_user."Company_ID"
   and office."Office_IsActive" = true
  join public."cmp_Users_Offices" user_office
    on user_office."Office_ID" = office."Office_ID"
   and user_office."User_ID" = app_user."User_ID"
  where job_row."Job_ID" = requested_job_id
    and job_row."Job_IsDeleted" = false;

  select max(
    (case when template."DOCBT_OrgOfficeID" is not null then 8 else 0 end) +
    (case when template."DOCBT_LegalEntityID" is not null then 4 else 0 end) +
    (case when template."DOCBT_BrandID" is not null then 2 else 0 end) +
    (case when template."DOCBT_CustomerOrgID" is not null then 1 else 0 end)
  )
  into max_specificity
  from public."DOCB_DocumentTemplates" template
  where template."DOCBT_Code" = requested_template_code
    and template."DOCBT_StatusCode" = 'published'
    and template."DOCBT_IsActive" = true
    and template."DOCBT_DefaultRenderEngineCode" = 'carbone'
    and (template."DOCBT_OrgOfficeID" is null or template."DOCBT_OrgOfficeID" = job."Job_OrgOfficeID")
    and (template."DOCBT_LegalEntityID" is null or template."DOCBT_LegalEntityID" = job."Job_LegalEntityID")
    and (template."DOCBT_BrandID" is null or template."DOCBT_BrandID" = job."Job_BrandID")
    and (template."DOCBT_CustomerOrgID" is null or template."DOCBT_CustomerOrgID" = job."Job_Customer");

  if max_specificity is null then
    raise exception 'no published template matches the requested job' using errcode = 'P0002';
  end if;

  select count(*), min(template."DOCBT_ID"::text)::uuid
  into candidate_count, candidate_template_id
  from public."DOCB_DocumentTemplates" template
  where template."DOCBT_Code" = requested_template_code
    and template."DOCBT_StatusCode" = 'published'
    and template."DOCBT_IsActive" = true
    and template."DOCBT_DefaultRenderEngineCode" = 'carbone'
    and (template."DOCBT_OrgOfficeID" is null or template."DOCBT_OrgOfficeID" = job."Job_OrgOfficeID")
    and (template."DOCBT_LegalEntityID" is null or template."DOCBT_LegalEntityID" = job."Job_LegalEntityID")
    and (template."DOCBT_BrandID" is null or template."DOCBT_BrandID" = job."Job_BrandID")
    and (template."DOCBT_CustomerOrgID" is null or template."DOCBT_CustomerOrgID" = job."Job_Customer")
    and (
      (case when template."DOCBT_OrgOfficeID" is not null then 8 else 0 end) +
      (case when template."DOCBT_LegalEntityID" is not null then 4 else 0 end) +
      (case when template."DOCBT_BrandID" is not null then 2 else 0 end) +
      (case when template."DOCBT_CustomerOrgID" is not null then 1 else 0 end)
    ) = max_specificity;

  if candidate_count <> 1 then
    raise exception 'template resolution is ambiguous' using errcode = '21000';
  end if;

  select template.*
  into strict selected_template
  from public."DOCB_DocumentTemplates" template
  where template."DOCBT_ID" = candidate_template_id;

  select version.*
  into strict selected_version
  from public."DOCB_TemplateVersions" version
  where version."DOCBTV_TemplateID" = selected_template."DOCBT_ID"
    and version."DOCBTV_VersionNo" = selected_template."DOCBT_CurrentVersionNo"
    and version."DOCBTV_StatusCode" = 'published'
    and version."DOCBTV_RenderEngineCode" = 'carbone';

  carbone_reference := coalesce(
    selected_version."DOCBTV_TemplateSnapshotJSON" #>> '{carbone,versionId}',
    selected_version."DOCBTV_TemplateSnapshotJSON" #>> '{carbone,templateId}',
    selected_template."DOCBT_SettingsJSON" #>> '{carbone,templateId}'
  );

  if carbone_reference is null or carbone_reference !~ '^[A-Za-z0-9._-]{8,128}$' then
    raise exception 'published template has no valid Carbone template reference' using errcode = '22023';
  end if;

  input_snapshot := jsonb_build_object(
    'meta', jsonb_build_object(
      'schemaVersion', 1,
      'generatedAt', now(),
      'templateCode', selected_template."DOCBT_Code",
      'templateVersion', selected_version."DOCBTV_VersionNo",
      'languageCode', selected_template."DOCBT_LanguageCode"
    ),
    'job', jsonb_strip_nulls(jsonb_build_object(
      'id', job."Job_ID",
      'number', job."Job_Number",
      'period', job."Job_Period",
      'createdAt', job."Job_CreatedDate",
      'status', job."Job_Status",
      'direction', job."Job_Direction",
      'transportMode', job."Job_TransportModeSummary",
      'origin', jsonb_strip_nulls(jsonb_build_object('unlocode', job."Job_OriginUNLocode", 'name', job."Job_OriginNameSnapshot")),
      'destination', jsonb_strip_nulls(jsonb_build_object('unlocode', job."Job_DestinationUNLocode", 'name', job."Job_DestinationNameSnapshot")),
      'readyDate', job."Job_ReadyDate",
      'requiredDeliveryDate', job."Job_RequiredDeliveryDate",
      'officeId', job."Job_OrgOfficeID",
      'legalEntityName', job."Job_LegalEntityNameSnapshot",
      'brandName', job."Job_BrandNameSnapshot"
    )),
    'customer', document_api.party_json(job."Job_Customer", job."Job_CustomerAddress"),
    'shipper', document_api.party_json(job."Job_Shipper", job."Job_ShipperAddress"),
    'consignee', document_api.party_json(job."Job_Consignee", job."Job_ConsigneeAddress"),
    'cargo', coalesce((
      select jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
        'id', cargo."JobCargo_ID",
        'lineNumber', cargo."JobCargo_LineNo",
        'commodity', cargo."JobCargo_Commodity",
        'description', cargo."JobCargo_Description",
        'packageType', cargo."JobCargo_PackageTypeCodeSnapshot",
        'packageQuantity', cargo."JobCargo_PackageQty",
        'grossWeight', cargo."JobCargo_GrossKilos",
        'netWeight', cargo."JobCargo_NettKilos",
        'weightUnit', cargo."JobCargo_WeightUnit",
        'volume', cargo."JobCargo_VolumeCBM",
        'volumeUnit', cargo."JobCargo_VolumeUnit",
        'marksAndNumbers', cargo."JobCargo_MarksNumbers",
        'hsCode', cargo."JobCargo_HSCode",
        'countryOfOrigin', cargo."JobCargo_CountryOfOriginCodeSnapshot",
        'isHazardous', cargo."JobCargo_IsHazardous"
      )) order by cargo."JobCargo_LineNo" nulls last, cargo."JobCargo_ID")
      from public."Job_Cargo" cargo
      where cargo."JobCargo_JobID" = job."Job_ID" and cargo."JobCargo_IsDeleted" = false
    ), '[]'::jsonb),
    'routing', coalesce((
      select jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
        'id', route."JobRoute_ID",
        'sequence', route."JobRoute_OrderNo",
        'status', route."JobRoute_Status",
        'mode', route."JobRoute_ModeCode",
        'origin', jsonb_strip_nulls(jsonb_build_object('unlocode', route."JobRoute_OriginUNLocode", 'name', route."JobRoute_OriginNameSnapshot", 'terminal', route."JobRoute_OriginTerminal")),
        'destination', jsonb_strip_nulls(jsonb_build_object('unlocode', route."JobRoute_DestinationUNLocode", 'name', route."JobRoute_DestinationNameSnapshot", 'terminal', route."JobRoute_DestinationTerminal")),
        'plannedDepartureAt', route."JobRoute_PlannedDepartureAt",
        'estimatedDepartureAt', route."JobRoute_EstimatedDepartureAt",
        'actualDepartureAt', route."JobRoute_ActualDepartureAt",
        'plannedArrivalAt', route."JobRoute_PlannedArrivalAt",
        'estimatedArrivalAt', route."JobRoute_EstimatedArrivalAt",
        'actualArrivalAt', route."JobRoute_ActualArrivalAt",
        'vessel', route."JobRoute_Vessel",
        'voyageNumber', route."JobRoute_VoyageNumber",
        'flightNumber', route."JobRoute_FlightNumber",
        'carrierBookingReference', route."JobRoute_CarrierBookingReference",
        'masterTransportReference', route."JobRoute_MasterTransportReference",
        'houseTransportReference', route."JobRoute_HouseTransportReference",
        'isMainCarriage', route."JobRoute_IsMainCarriage"
      )) order by route."JobRoute_OrderNo" nulls last, route."JobRoute_ID")
      from public."Job_Routing" route
      where route."Job_ID" = job."Job_ID"
    ), '[]'::jsonb)
  );

  if input_snapshot #>> '{customer,id}' is null then
    raise exception 'job customer identity is missing or invalid' using errcode = '42501';
  end if;

  selected_snapshot := jsonb_strip_nulls(jsonb_build_object(
    'meta', input_snapshot -> 'meta',
    'selection', jsonb_build_object(
      'job', true,
      'customer', 'customer' = any(selected_sections),
      'shipper', 'shipper' = any(selected_sections),
      'consignee', 'consignee' = any(selected_sections),
      'cargo', 'cargo' = any(selected_sections),
      'routing', 'routing' = any(selected_sections)
    ),
    'job', input_snapshot -> 'job',
    'customer', case when 'customer' = any(selected_sections) then input_snapshot -> 'customer' end,
    'shipper', case when 'shipper' = any(selected_sections) then input_snapshot -> 'shipper' end,
    'consignee', case when 'consignee' = any(selected_sections) then input_snapshot -> 'consignee' end,
    'cargo', case when 'cargo' = any(selected_sections) then input_snapshot -> 'cargo' end,
    'routing', case when 'routing' = any(selected_sections) then input_snapshot -> 'routing' end
  ));

  return jsonb_build_object(
    'templateCode', selected_template."DOCBT_Code",
    'templateName', selected_template."DOCBT_Name",
    'templateVersion', selected_version."DOCBTV_VersionNo",
    'carboneTemplateReference', carbone_reference,
    'languageCode', selected_template."DOCBT_LanguageCode",
    'jobReference', concat(job."Job_Period", '-', job."Job_Number"),
    'dataset', selected_snapshot
  );
exception
  when no_data_found or too_many_rows then
    raise exception 'document studio identity or access is ambiguous' using errcode = '42501';
end;
$_$;


ALTER FUNCTION "document_api"."prepare_studio_job_session"("caller_auth_user_id" "uuid", "requested_template_code" "text", "requested_job_id" "uuid", "requested_content_sections" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "document_api"."record_studio_template"("caller_auth_user_id" "uuid", "requested_render_job_id" "uuid", "template_sha256" "text", "template_size_bytes" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  app_user_id uuid;
begin
  select user_row."User_ID"
  into strict app_user_id
  from public."cmp_Users" user_row
  where user_row."Auth_User_ID" = caller_auth_user_id;

  if template_sha256 !~ '^[a-f0-9]{64}$'
     or template_size_bytes <= 0
     or template_size_bytes > 15728640 then
    raise exception 'invalid studio template audit details' using errcode = '22023';
  end if;

  update public."DOCB_RenderJobs"
  set "DOCBRJ_RenderSettingsJSON" = "DOCBRJ_RenderSettingsJSON" || jsonb_build_object(
    'studioCustomized', true,
    'studioTemplateSha256', template_sha256,
    'studioTemplateSizeBytes', template_size_bytes
  )
  where "DOCBRJ_ID" = requested_render_job_id
    and "DOCBRJ_CreatedBy" = app_user_id
    and "DOCBRJ_StatusCode" = 'rendering';

  if not found then
    raise exception 'document render is not authorised' using errcode = '42501';
  end if;
exception
  when no_data_found or too_many_rows then
    raise exception 'document render is not authorised' using errcode = '42501';
end;
$_$;


ALTER FUNCTION "document_api"."record_studio_template"("caller_auth_user_id" "uuid", "requested_render_job_id" "uuid", "template_sha256" "text", "template_size_bytes" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "document_api"."record_template_source"("caller_auth_user_id" "uuid", "requested_template_id" "uuid", "requested_version_no" integer, "source_bucket" "text", "source_path" "text", "source_file_name" "text", "source_mime_type" "text", "source_size_bytes" bigint, "source_sha256" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  app_user_id uuid;
  template_version_id uuid;
  stored_object_id uuid;
  stored_size_bytes bigint;
  source_extension text := lower(split_part(source_file_name, '.', array_length(string_to_array(source_file_name, '.'), 1)));
begin
  if caller_auth_user_id is null
     or not document_api.has_permission(caller_auth_user_id, 'Documents.Manage') then
    raise exception 'document template management is not authorised' using errcode = '42501';
  end if;

  if requested_version_no < 1
     or source_bucket <> 'multideck-template-sources'
     or source_extension not in ('pdf', 'doc', 'docx', 'xls', 'xlsx')
     or source_path <> concat('templates/', requested_template_id, '/source/', source_sha256, '.', source_extension)
     or length(source_file_name) < 5
     or length(source_file_name) > 255
     or position('/' in source_file_name) > 0
     or position(chr(92) in source_file_name) > 0
     or source_mime_type not in (
       'application/pdf',
       'application/msword',
       'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
       'application/vnd.ms-excel',
       'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
     )
     or source_size_bytes <= 0
     or source_size_bytes > 15728640
     or source_sha256 !~ '^[0-9a-f]{64}$' then
    raise exception 'invalid template source metadata' using errcode = '22023';
  end if;

  select user_row."User_ID"
  into strict app_user_id
  from public."cmp_Users" user_row
  where user_row."Auth_User_ID" = caller_auth_user_id;

  select version."DOCBTV_ID"
  into strict template_version_id
  from public."DOCB_TemplateVersions" version
  join public."DOCB_DocumentTemplates" template
    on template."DOCBT_ID" = version."DOCBTV_TemplateID"
  where template."DOCBT_ID" = requested_template_id
    and version."DOCBTV_VersionNo" = requested_version_no
  for update of version;

  select nullif(source_object.metadata ->> 'size', '')::bigint
  into stored_size_bytes
  from storage.objects source_object
  where source_object.bucket_id = source_bucket
    and source_object.name = source_path;

  if stored_size_bytes is null or stored_size_bytes <> source_size_bytes then
    raise exception 'template source object is unavailable or inconsistent' using errcode = '22023';
  end if;

  insert into public."DOC_StoredObjects" (
    "DOCStoredObject_ConcernCode",
    "DOCStoredObject_AggregateType",
    "DOCStoredObject_AggregateID",
    "DOCStoredObject_ProviderCode",
    "DOCStoredObject_Container",
    "DOCStoredObject_BlobName",
    "DOCStoredObject_OriginalFileName",
    "DOCStoredObject_MimeType",
    "DOCStoredObject_FileSizeBytes",
    "DOCStoredObject_SHA256",
    "DOCStoredObject_CreatedBy"
  ) values (
    'document-builder',
    'document_template_version_source',
    template_version_id,
    'supabase_storage',
    source_bucket,
    source_path,
    source_file_name,
    source_mime_type,
    source_size_bytes,
    source_sha256,
    app_user_id
  )
  on conflict ("DOCStoredObject_Container", "DOCStoredObject_BlobName") do update
  set "DOCStoredObject_OriginalFileName" = excluded."DOCStoredObject_OriginalFileName",
      "DOCStoredObject_MimeType" = excluded."DOCStoredObject_MimeType",
      "DOCStoredObject_FileSizeBytes" = excluded."DOCStoredObject_FileSizeBytes",
      "DOCStoredObject_SHA256" = excluded."DOCStoredObject_SHA256",
      "DOCStoredObject_StatusCode" = 'active'
  returning "DOCStoredObject_ID" into stored_object_id;

  update public."DOCB_TemplateVersions" version
  set "DOCBTV_TemplateSnapshotJSON" = jsonb_set(
    version."DOCBTV_TemplateSnapshotJSON",
    '{source}',
    coalesce(version."DOCBTV_TemplateSnapshotJSON" -> 'source', '{}'::jsonb) || jsonb_build_object(
      'provider', 'supabase_storage',
      'bucket', source_bucket,
      'path', source_path,
      'storedObjectId', stored_object_id,
      'fileName', source_file_name,
      'mimeType', source_mime_type,
      'sizeBytes', source_size_bytes,
      'sha256', source_sha256
    ),
    true
  )
  where version."DOCBTV_ID" = template_version_id;

  return jsonb_build_object(
    'storedObjectId', stored_object_id,
    'bucket', source_bucket,
    'path', source_path,
    'sha256', source_sha256
  );
exception
  when no_data_found or too_many_rows then
    raise exception 'document template management is not authorised' using errcode = '42501';
end;
$_$;


ALTER FUNCTION "document_api"."record_template_source"("caller_auth_user_id" "uuid", "requested_template_id" "uuid", "requested_version_no" integer, "source_bucket" "text", "source_path" "text", "source_file_name" "text", "source_mime_type" "text", "source_size_bytes" bigint, "source_sha256" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "document_api"."register_studio_template_version"("caller_auth_user_id" "uuid", "requested_template_id" "uuid", "provider_template_id" "text", "provider_version_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  app_user_id uuid;
  selected_template record;
  matching_version record;
  next_version_no integer;
  saved_status text;
begin
  if caller_auth_user_id is null
     or not document_api.has_permission(caller_auth_user_id, 'Documents.Manage') then
    raise exception 'document template management is not authorised' using errcode = '42501';
  end if;
  if provider_template_id !~ '^[0-9]{1,20}$'
     or provider_version_id !~ '^[0-9a-f]{64}$' then
    raise exception 'invalid Carbone template identifiers' using errcode = '22023';
  end if;

  select user_row."User_ID"
  into strict app_user_id
  from public."cmp_Users" user_row
  where user_row."Auth_User_ID" = caller_auth_user_id;

  select template.*
  into strict selected_template
  from public."DOCB_DocumentTemplates" template
  where template."DOCBT_ID" = requested_template_id
    and template."DOCBT_IsActive" = true
    and template."DOCBT_IsUserEditable" = true
    and template."DOCBT_DefaultRenderEngineCode" = 'carbone'
  for update;

  saved_status := case
    when selected_template."DOCBT_StatusCode" = 'published' then 'published'
    else 'draft'
  end;

  select version."DOCBTV_ID", version."DOCBTV_VersionNo", version."DOCBTV_StatusCode"
  into matching_version
  from public."DOCB_TemplateVersions" version
  where version."DOCBTV_TemplateID" = selected_template."DOCBT_ID"
    and coalesce(
      version."DOCBTV_TemplateSnapshotJSON" #>> '{carbone,versionId}',
      case
        when version."DOCBTV_TemplateSnapshotJSON" #>> '{carbone,templateId}' ~ '^[0-9a-f]{64}$'
          then version."DOCBTV_TemplateSnapshotJSON" #>> '{carbone,templateId}'
      end
    ) = provider_version_id
  order by version."DOCBTV_VersionNo" desc
  limit 1;

  if matching_version."DOCBTV_ID" is not null then
    update public."DOCB_TemplateVersions" version
    set "DOCBTV_StatusCode" = case
          when saved_status = 'published' then 'published'
          else version."DOCBTV_StatusCode"
        end,
        "DOCBTV_PublishedAt" = case
          when saved_status = 'published' then coalesce(version."DOCBTV_PublishedAt", now())
          else version."DOCBTV_PublishedAt"
        end,
        "DOCBTV_PublishedBy" = case
          when saved_status = 'published' then coalesce(version."DOCBTV_PublishedBy", app_user_id)
          else version."DOCBTV_PublishedBy"
        end,
        "DOCBTV_TemplateSnapshotJSON" = version."DOCBTV_TemplateSnapshotJSON" || jsonb_build_object(
          'carbone', coalesce(version."DOCBTV_TemplateSnapshotJSON" -> 'carbone', '{}'::jsonb) || jsonb_build_object(
            'templateId', provider_template_id,
            'versionId', provider_version_id
          )
        )
    where version."DOCBTV_ID" = matching_version."DOCBTV_ID";

    next_version_no := matching_version."DOCBTV_VersionNo";
  else
    select coalesce(max(version."DOCBTV_VersionNo"), 0) + 1
    into next_version_no
    from public."DOCB_TemplateVersions" version
    where version."DOCBTV_TemplateID" = selected_template."DOCBT_ID";

    insert into public."DOCB_TemplateVersions" (
      "DOCBTV_TemplateID",
      "DOCBTV_VersionNo",
      "DOCBTV_StatusCode",
      "DOCBTV_RenderEngineCode",
      "DOCBTV_OutputFormatCode",
      "DOCBTV_TemplateSnapshotJSON",
      "DOCBTV_ChangeReason",
      "DOCBTV_CreatedBy",
      "DOCBTV_PublishedAt",
      "DOCBTV_PublishedBy"
    ) values (
      selected_template."DOCBT_ID",
      next_version_no,
      saved_status,
      'carbone',
      selected_template."DOCBT_DefaultOutputFormatCode",
      jsonb_build_object(
        'carbone', jsonb_build_object(
          'templateId', provider_template_id,
          'versionId', provider_version_id
        ),
        'source', jsonb_build_object(
          'origin', 'multideck-document-builder',
          'savedAt', now()
        )
      ),
      case
        when saved_status = 'published' then 'Saved as the current Multideck template version.'
        else 'Saved from the Multideck document builder.'
      end,
      app_user_id,
      case when saved_status = 'published' then now() else null end,
      case when saved_status = 'published' then app_user_id else null end
    );
  end if;

  update public."DOCB_DocumentTemplates" template
  set "DOCBT_CurrentVersionNo" = case
        when saved_status = 'published' then next_version_no
        else template."DOCBT_CurrentVersionNo"
      end,
      "DOCBT_SettingsJSON" = template."DOCBT_SettingsJSON" || jsonb_build_object(
        'carbone', coalesce(template."DOCBT_SettingsJSON" -> 'carbone', '{}'::jsonb) || jsonb_build_object(
          'templateId', provider_template_id
        )
      ),
      "DOCBT_UpdatedAt" = now(),
      "DOCBT_UpdatedBy" = app_user_id
  where template."DOCBT_ID" = selected_template."DOCBT_ID";

  return jsonb_build_object(
    'multideckTemplateId', selected_template."DOCBT_ID",
    'templateCode', selected_template."DOCBT_Code",
    'carboneTemplateId', provider_template_id,
    'carboneVersionId', provider_version_id,
    'multideckVersion', next_version_no,
    'status', saved_status
  );
exception
  when no_data_found or too_many_rows then
    raise exception 'document template management is not authorised' using errcode = '42501';
end;
$_$;


ALTER FUNCTION "document_api"."register_studio_template_version"("caller_auth_user_id" "uuid", "requested_template_id" "uuid", "provider_template_id" "text", "provider_version_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "document_api"."resolve_authorised_job_id_by_number"("caller_auth_user_id" "uuid", "requested_job_number" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  app_user record;
  resolved_job_id uuid;
  normalised_job_number text := upper(btrim(requested_job_number));
begin
  if caller_auth_user_id is null then
    raise exception 'authentication required' using errcode = '42501';
  end if;

  if normalised_job_number is null
     or normalised_job_number !~ '^[A-Z0-9][A-Z0-9._/-]{0,49}$' then
    raise exception 'invalid job number' using errcode = '22023';
  end if;

  select user_row."User_ID", user_row."Company_ID"
  into strict app_user
  from public."cmp_Users" user_row
  where user_row."Auth_User_ID" = caller_auth_user_id;

  if app_user."Company_ID" is null
     or not document_api.has_permission(caller_auth_user_id, 'Documents.Generate') then
    raise exception 'document generation is not authorised' using errcode = '42501';
  end if;

  select job_row."Job_ID"
  into strict resolved_job_id
  from public."Job_Header" job_row
  join public."cmp_Offices" office
    on office."Office_ID" = job_row."Job_OrgOfficeID"
   and office."Company_ID" = app_user."Company_ID"
   and office."Office_IsActive" = true
  join public."cmp_Users_Offices" user_office
    on user_office."Office_ID" = office."Office_ID"
   and user_office."User_ID" = app_user."User_ID"
  where upper(btrim(job_row."Job_Number"::text)) = normalised_job_number
    and job_row."Job_IsDeleted" = false;

  return resolved_job_id;
exception
  when no_data_found then
    raise exception 'no authorised job matches the requested job number' using errcode = 'MD404';
  when too_many_rows then
    raise exception 'more than one authorised job matches the requested job number' using errcode = 'MD409';
end;
$_$;


ALTER FUNCTION "document_api"."resolve_authorised_job_id_by_number"("caller_auth_user_id" "uuid", "requested_job_number" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "document_api"."workspace"("caller_auth_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  app_user record;
  can_generate boolean;
  can_manage boolean;
begin
  select user_row."User_ID", user_row."Company_ID"
  into strict app_user
  from public."cmp_Users" user_row
  where user_row."Auth_User_ID" = caller_auth_user_id;

  can_generate := document_api.has_permission(caller_auth_user_id, 'Documents.Generate');
  can_manage := document_api.has_permission(caller_auth_user_id, 'Documents.Manage');

  if not document_api.has_permission(caller_auth_user_id, 'Documents.Read') then
    raise exception 'document access is not authorised' using errcode = '42501';
  end if;

  return jsonb_build_object(
    'permissions', jsonb_build_object('canGenerate', can_generate, 'canManageTemplates', can_manage),
    'templates', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', template."DOCBT_ID",
        'code', template."DOCBT_Code",
        'name', template."DOCBT_Name",
        'description', template."DOCBT_Description",
        'targetType', 'Job_Header',
        'outputFormats', case
          when jsonb_typeof(template."DOCBT_SettingsJSON" -> 'outputFormats') = 'array'
            then template."DOCBT_SettingsJSON" -> 'outputFormats'
          else jsonb_build_array(template."DOCBT_DefaultOutputFormatCode")
        end,
        'defaultOutputFormat', template."DOCBT_DefaultOutputFormatCode",
        'status', template."DOCBT_StatusCode",
        'version', template."DOCBT_CurrentVersionNo",
        'languageCode', template."DOCBT_LanguageCode",
        'updatedAt', template."DOCBT_UpdatedAt",
        'updatedBy', concat_ws(' ', updater."User_Firstname", updater."User_Lastname")
      ) order by template."DOCBT_StatusCode" desc, template."DOCBT_Name")
      from public."DOCB_DocumentTemplates" template
      left join public."cmp_Users" updater on updater."User_ID" = template."DOCBT_UpdatedBy"
      where (template."DOCBT_StatusCode" = 'published' or (can_manage and template."DOCBT_StatusCode" = 'draft'))
        and template."DOCBT_IsActive" = true
        and template."DOCBT_DefaultRenderEngineCode" = 'carbone'
        and (
          template."DOCBT_OrgOfficeID" is null
          or exists (
            select 1 from public."cmp_Users_Offices" user_office
            join public."cmp_Offices" office on office."Office_ID" = user_office."Office_ID"
            where user_office."User_ID" = app_user."User_ID"
              and office."Company_ID" = app_user."Company_ID"
              and user_office."Office_ID" = template."DOCBT_OrgOfficeID"
          )
        )
    ), '[]'::jsonb),
    'generatedDocuments', coalesce((
      select jsonb_agg(document_row order by "createdAt" desc)
      from (
        select jsonb_build_object(
          'id', generated."DOCBGD_ID",
          'renderJobId', generated."DOCBGD_RenderJobID",
          'templateCode', template."DOCBT_Code",
          'templateName', template."DOCBT_Name",
          'targetType', render."DOCBRJ_TargetTable",
          'targetId', render."DOCBRJ_TargetID",
          'targetReference', concat(job."Job_Period", '-', job."Job_Number"),
          'customerName', customer."Org_Name",
          'fileName', generated."DOCBGD_FileName",
          'outputFormat', generated."DOCBGD_OutputFormatCode",
          'mimeType', generated."DOCBGD_MimeType",
          'fileSizeBytes', generated."DOCBGD_FileSizeBytes",
          'status', case render."DOCBRJ_StatusCode"
            when 'completed' then 'ready'
            when 'completed_with_warnings' then 'ready'
            when 'rendering' then 'rendering'
            when 'queued' then 'queued'
            else 'failed'
          end,
          'createdAt', generated."DOCBGD_CreatedAt",
          'createdBy', concat_ws(' ', creator."User_Firstname", creator."User_Lastname"),
          'failureReason', render."DOCBRJ_ErrorMessage"
        ) as document_row,
        generated."DOCBGD_CreatedAt" as "createdAt"
        from public."DOCB_GeneratedDocuments" generated
        join public."DOCB_RenderJobs" render on render."DOCBRJ_ID" = generated."DOCBGD_RenderJobID"
        join public."DOCB_DocumentTemplates" template on template."DOCBT_ID" = generated."DOCBGD_TemplateID"
        join public."Job_Header" job on job."Job_ID" = render."DOCBRJ_JobID" and job."Job_IsDeleted" = false
        join public."cmp_Users_Offices" user_office
          on user_office."User_ID" = app_user."User_ID" and user_office."Office_ID" = job."Job_OrgOfficeID"
        join public."cmp_Offices" office
          on office."Office_ID" = user_office."Office_ID" and office."Company_ID" = app_user."Company_ID"
        left join public."Org_Master" customer on customer."Org_id" = job."Job_Customer"
        left join public."cmp_Users" creator on creator."User_ID" = generated."DOCBGD_CreatedBy"
        order by generated."DOCBGD_CreatedAt" desc
        limit 50
      ) recent
    ), '[]'::jsonb)
  );
exception
  when no_data_found or too_many_rows then
    raise exception 'document identity is ambiguous' using errcode = '42501';
end;
$$;


ALTER FUNCTION "document_api"."workspace"("caller_auth_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "document_api"."workspace_overview"("caller_auth_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  app_user record;
  can_generate boolean;
  can_manage boolean;
begin
  select user_row."User_ID", user_row."Company_ID"
  into strict app_user
  from public."cmp_Users" user_row
  where user_row."Auth_User_ID" = caller_auth_user_id;

  can_generate := document_api.has_permission(caller_auth_user_id, 'Documents.Generate');
  can_manage := document_api.has_permission(caller_auth_user_id, 'Documents.Manage');

  if not document_api.has_permission(caller_auth_user_id, 'Documents.Read') then
    raise exception 'document access is not authorised' using errcode = '42501';
  end if;

  return jsonb_build_object(
    'permissions', jsonb_build_object('canGenerate', can_generate, 'canManageTemplates', can_manage),
    'templates', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', template."DOCBT_ID",
        'code', template."DOCBT_Code",
        'name', template."DOCBT_Name",
        'description', template."DOCBT_Description",
        'targetType', 'Job_Header',
        'outputFormats', case
          when jsonb_typeof(template."DOCBT_SettingsJSON" -> 'outputFormats') = 'array'
            then template."DOCBT_SettingsJSON" -> 'outputFormats'
          else jsonb_build_array(template."DOCBT_DefaultOutputFormatCode")
        end,
        'defaultOutputFormat', template."DOCBT_DefaultOutputFormatCode",
        'status', template."DOCBT_StatusCode",
        'version', template."DOCBT_CurrentVersionNo",
        'languageCode', template."DOCBT_LanguageCode",
        'updatedAt', template."DOCBT_UpdatedAt",
        'updatedBy', concat_ws(' ', updater."User_Firstname", updater."User_Lastname")
      ) order by template."DOCBT_StatusCode" desc, template."DOCBT_Name")
      from public."DOCB_DocumentTemplates" template
      left join public."cmp_Users" updater on updater."User_ID" = template."DOCBT_UpdatedBy"
      where (template."DOCBT_StatusCode" = 'published' or (can_manage and template."DOCBT_StatusCode" = 'draft'))
        and template."DOCBT_IsActive" = true
        and template."DOCBT_DefaultRenderEngineCode" = 'carbone'
        and (
          template."DOCBT_OrgOfficeID" is null
          or exists (
            select 1
            from public."cmp_Users_Offices" user_office
            join public."cmp_Offices" office on office."Office_ID" = user_office."Office_ID"
            where user_office."User_ID" = app_user."User_ID"
              and office."Company_ID" = app_user."Company_ID"
              and user_office."Office_ID" = template."DOCBT_OrgOfficeID"
          )
        )
    ), '[]'::jsonb)
  );
exception
  when no_data_found or too_many_rows then
    raise exception 'document identity is ambiguous' using errcode = '42501';
end;
$$;


ALTER FUNCTION "document_api"."workspace_overview"("caller_auth_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "document_api"."workspace_overview"("caller_auth_user_id" "uuid") IS 'Service-role-only Documents templates and permission overview without generated history.';



CREATE OR REPLACE FUNCTION "private"."apply_contact_card_crm_field_mappings"("p_card_id" "uuid", "p_lead_id" "uuid", "p_input" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  v_card record;
  v_config jsonb := '{}'::jsonb;
  v_custom_notes text;
begin
  select * into v_card
  from public."CRM_ContactCards"
  where "ContactCard_ID" = p_card_id
    and "ContactCard_DeletedAt" is null;

  if not found then
    raise exception 'Contact card not found.' using errcode = 'P0002';
  end if;

  select coalesce("Action_Config", '{}'::jsonb) into v_config
  from public."CRM_ContactCardAutomationActions"
  where "ContactCard_ID" = p_card_id
    and "Action_Kind" = 'add-to-crm'
  order by "Action_SortOrder", "Action_ID"
  limit 1;

  v_custom_notes := nullif(left(btrim(coalesce(v_config ->> 'customNotes', '')), 12000), '');

  update public."CRM_Leads"
  set
    "CRMLead_PersonName" = left(btrim(concat_ws(' ', p_input ->> 'firstName', p_input ->> 'lastName')), 255),
    "CRMLead_Email" = left(lower(btrim(p_input ->> 'email')), 255),
    "CRMLead_CompanyName" = left(btrim(p_input ->> 'company'), 255),
    "CRMLead_Phone" = coalesce(nullif(left(btrim(coalesce(p_input ->> 'phone', '')), 80), ''), "CRMLead_Phone"),
    "CRMLead_MetadataJSON" = (coalesce("CRMLead_MetadataJSON", '{}'::jsonb) - 'mappedFields')
      || jsonb_build_object(
        'contactCardId', p_card_id,
        'contactCardSlug', v_card."ContactCard_Slug",
        'leadSource', coalesce(v_card."ContactCard_LeadSource", ''),
        'marketingConsent', coalesce((p_input ->> 'marketingConsent')::boolean, false)
      ),
    "CRMLead_UpdatedAt" = now(),
    "CRMLead_UpdatedBy" = v_card."Owner_User_ID"
  where "CRMLead_ID" = p_lead_id
    and not "CRMLead_IsDeleted";

  if not found then
    raise exception 'Lead not found.' using errcode = 'P0002';
  end if;

  if v_custom_notes is not null and not exists (
    select 1
    from public."CRM_Notes"
    where "CRMNote_LeadID" = p_lead_id
      and "CRMNote_SourceTable" = 'CRM_ContactCards'
      and "CRMNote_SourceID" = p_card_id
      and "CRMNote_Body" = v_custom_notes
      and not "CRMNote_IsDeleted"
  ) then
    insert into public."CRM_Notes" (
      "CRMNote_LeadID",
      "CRMNote_SourceTable",
      "CRMNote_SourceID",
      "CRMNote_Title",
      "CRMNote_Body",
      "CRMNote_SensitivityCode",
      "CRMNote_IsCustomerVisible",
      "CRMNote_IsTrainingAllowed",
      "CRMNote_CreatedBy",
      "CRMNote_UpdatedBy"
    ) values (
      p_lead_id,
      'CRM_ContactCards',
      p_card_id,
      'Contact card context',
      v_custom_notes,
      'internal',
      false,
      false,
      v_card."Owner_User_ID",
      v_card."Owner_User_ID"
    );
  end if;
end;
$$;


ALTER FUNCTION "private"."apply_contact_card_crm_field_mappings"("p_card_id" "uuid", "p_lead_id" "uuid", "p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."can_read_profile_photo"("p_object_name" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (
    select 1
    from public."cmp_Users" as viewer
    join public."cmp_Users" as photo_owner
      on photo_owner."Auth_User_ID"::text = (storage.foldername(p_object_name))[1]
    where viewer."Auth_User_ID" = (select auth.uid())
      and viewer."Company_ID" is not null
      and photo_owner."Company_ID" = viewer."Company_ID"
  );
$$;


