CREATE OR REPLACE FUNCTION "private"."is_valid_keyboard_shortcuts"("p_shortcuts" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare
  v_entry record;
begin
  if p_shortcuts is null then
    return true;
  end if;

  if jsonb_typeof(p_shortcuts) <> 'object' then
    return false;
  end if;

  if (select count(*) from jsonb_object_keys(p_shortcuts)) > 120 then
    return false;
  end if;

  for v_entry in select key, value from jsonb_each(p_shortcuts) loop
    if length(v_entry.key) not between 1 and 120 then
      return false;
    end if;

    if jsonb_typeof(v_entry.value) <> 'string' then
      return false;
    end if;

    if length(v_entry.value #>> '{}') > 120 then
      return false;
    end if;
  end loop;

  return true;
end
$$;


ALTER FUNCTION "private"."is_valid_keyboard_shortcuts"("p_shortcuts" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."is_valid_sidebar_layout"("p_layout" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare
  v_scope record;
  v_list_name text;
  v_list jsonb;
  v_entry jsonb;
begin
  if p_layout is null then
    return true;
  end if;

  if jsonb_typeof(p_layout) <> 'object' then
    return false;
  end if;

  if (select count(*) from jsonb_object_keys(p_layout)) > 40 then
    return false;
  end if;

  for v_scope in select key, value from jsonb_each(p_layout) loop
    if length(v_scope.key) not between 1 and 120 then
      return false;
    end if;

    if jsonb_typeof(v_scope.value) <> 'object' then
      return false;
    end if;

    if (select count(*) from jsonb_object_keys(v_scope.value)) <> 2 then
      return false;
    end if;

    foreach v_list_name in array array['order', 'pinned'] loop
      v_list := v_scope.value -> v_list_name;

      if v_list is null or jsonb_typeof(v_list) <> 'array' then
        return false;
      end if;

      if jsonb_array_length(v_list) > 200 then
        return false;
      end if;

      for v_entry in select value from jsonb_array_elements(v_list) loop
        if jsonb_typeof(v_entry) <> 'string' then
          return false;
        end if;

        if length(v_entry #>> '{}') not between 1 and 120 then
          return false;
        end if;
      end loop;
    end loop;
  end loop;

  return true;
end
$$;


ALTER FUNCTION "private"."is_valid_sidebar_layout"("p_layout" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."is_valid_table_pinned_columns"("p_preferences" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare
  v_table record;
  v_column jsonb;
begin
  if p_preferences is null then
    return true;
