CREATE OR REPLACE FUNCTION "private_live_gateway"."product_details"("input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
declare k text; v jsonb; n numeric; result jsonb := '{}';
begin
 if jsonb_typeof(input) is distinct from 'object' then raise exception 'Product details must be an object' using errcode='22023'; end if;
 for k,v in select * from jsonb_each(input) loop
  if k in ('commodityDescription','hsCode','countryOfOriginCode') then
   if jsonb_typeof(v)<>'string' or length(btrim(input->>k))>(case k when 'commodityDescription' then 500 when 'hsCode' then 20 else 2 end) then raise exception 'Invalid product text: %',k using errcode='22023'; end if;
   if k='countryOfOriginCode' and btrim(input->>k)!~'^[A-Za-z]{2}$' then raise exception 'Use a two-letter country code' using errcode='22023'; end if;
   result:=result||jsonb_build_object(k,case when k='countryOfOriginCode' then upper(btrim(input->>k)) else btrim(input->>k) end);
  elsif k in ('lengthM','widthM','heightM','netWeightKg','grossWeightKg','temperatureMinC','temperatureMaxC') then
   if jsonb_typeof(v) not in ('string','number') or (input->>k)!~'^-?[0-9]{1,12}(\.[0-9]{1,6})?$' then raise exception 'Enter a valid decimal for %',k using errcode='22023'; end if;
   n:=(input->>k)::numeric;
   if k in ('temperatureMinC','temperatureMaxC') then
    if n < -273.15 or n > 999999.999 or n<>round(n,3) then raise exception 'Invalid temperature' using errcode='22023'; end if;
   elsif n<0 or n>999999999999.999999 then raise exception 'Dimensions and weights must be non-negative' using errcode='22023'; end if;
   result:=result||jsonb_build_object(k,n);
  elsif k in ('isDangerousGoods','isExciseGoods','isHighValue','requiresLot','requiresSerial','requiresExpiry') then
   if jsonb_typeof(v)<>'boolean' then raise exception 'Invalid handling flag: %',k using errcode='22023'; end if;
   result:=result||jsonb_build_object(k,v);
  else raise exception 'Unsupported product detail: %',k using errcode='22023'; end if;
 end loop;
 if (result->>'grossWeightKg')::numeric < (result->>'netWeightKg')::numeric then raise exception 'Gross weight cannot be less than net weight' using errcode='22023'; end if;
 if (result->>'temperatureMaxC')::numeric < (result->>'temperatureMinC')::numeric then raise exception 'Maximum temperature cannot be below the minimum' using errcode='22023'; end if;
 return result;
end;
$_$;


ALTER FUNCTION "private_live_gateway"."product_details"("input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private_live_gateway"."scope"("p_grant_id" "text") RETURNS TABLE("customer_id" bigint, "customer_name" "text", "organisation_id" "uuid", "facility_id" "uuid")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
select null::bigint,o."Org_Name"::text,g.organisation_id,f."WMSFacility_ID"
from private_live_gateway.customer_grants g join public."Org_Master" o on o."Org_id"=g.organisation_id
join public."WMS_CustomerFacilityAccess" a on a."WMSCustomerFacilityAccess_CustomerOrgID"=g.organisation_id and a."WMSCustomerFacilityAccess_IsActive"
join public."WMS_Facilities" f on f."WMSFacility_ID"=a."WMSCustomerFacilityAccess_FacilityID" and f."WMSFacility_ID"=any(g.facility_ids)
where g.id=p_grant_id and g.enabled and f."WMSFacility_IsActive" and not f."WMSFacility_IsDeleted";
$$;


