CREATE OR REPLACE FUNCTION "public"."Admin_AuditLog"("p_actor_user_id" "uuid", "p_detailed" boolean DEFAULT false, "p_limit" integer DEFAULT 200) RETURNS TABLE("id" "text", "occurred_at" timestamp with time zone, "category" "text", "action" "text", "title" "text", "actor_name" "text", "actor_email" "text", "source" "text", "record_type" "text", "record_id" "text", "record_key" "jsonb", "ip_address" "text", "outcome" "text", "detail" "text", "field_name" "text", "old_value" "jsonb", "new_value" "jsonb", "request_id" "text", "correlation_id" "text", "is_sensitive" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_limit integer := least(greatest(coalesce(p_limit, 200), 1), 500);
begin
  if not private.is_tenant_administrator(p_actor_user_id) then
    raise exception 'Only tenant administrators can view the audit log.' using errcode = '42501';
  end if;

  if p_detailed then
    return query
    with recent_app_events as (
      select event.*
      from public."Audit_Events" as event
      order by event."AuditEvent_OccurredAt" desc
      limit v_limit
    ),
    app_rows as (
      select
        'app:' || event."AuditEvent_ID"::text || coalesce(':' || field_change."AuditFieldChange_ID"::text, '') as id,
        event."AuditEvent_OccurredAt" as occurred_at,
        'application'::text as category,
        coalesce(event."AuditEvent_Action"::text, event."AuditEvent_EventTypeCode"::text) as action,
        coalesce(
          event."AuditEvent_Title"::text,
          case event."AuditEvent_EventTypeCode"
            when 'row_insert' then 'Record created'
            when 'row_update' then 'Record updated'
            when 'row_delete' then 'Record deleted'
            when 'row_soft_delete' then 'Record archived'
            when 'row_restore' then 'Record restored'
            else initcap(replace(event."AuditEvent_EventTypeCode"::text, '_', ' '))
          end
        ) as title,
        nullif(concat_ws(' ', workspace_user."User_Firstname", workspace_user."User_Lastname"), '')::text as actor_name,
        workspace_user."User_Email"::text as actor_email,
        coalesce(event."AuditEvent_SourceModule"::text, event."AuditEvent_SourceTableName"::text, event."AuditEvent_SourceApp"::text, 'Multideck') as source,
        event."AuditEvent_RecordTypeCode"::text as record_type,
        event."AuditEvent_RecordID"::text as record_id,
        event."AuditEvent_RecordKeyJSON" as record_key,
        request_context."AuditRequest_IPHash"::text as ip_address,
        event."AuditEvent_OutcomeStatusCode"::text as outcome,
        event."AuditEvent_Reason"::text as detail,
        field_change."AuditFieldChange_ColumnName"::text as field_name,
        field_change."AuditFieldChange_OldValueJSON" as old_value,
        field_change."AuditFieldChange_NewValueJSON" as new_value,
        event."AuditEvent_RequestID"::text as request_id,
        event."AuditEvent_CorrelationID"::text as correlation_id,
        (event."AuditEvent_IsSensitive" or coalesce(field_change."AuditFieldChange_IsSensitive", false)) as is_sensitive
      from recent_app_events as event
      left join public."Audit_FieldChanges" as field_change
        on field_change."AuditFieldChange_EventID" = event."AuditEvent_ID"
      left join public."Audit_RequestContexts" as request_context
        on request_context."AuditRequest_ID" = event."AuditEvent_RequestContextID"
      left join public."cmp_Users" as workspace_user
        on workspace_user."User_ID" = coalesce(event."AuditEvent_UserID", request_context."AuditRequest_UserID")
        or workspace_user."Auth_User_ID" = coalesce(event."AuditEvent_AuthUserID", request_context."AuditRequest_AuthUserID")
    ),
    auth_rows as (
      select
        'auth:' || auth_event.id::text as id,
        auth_event.created_at as occurred_at,
        'authentication'::text as category,
        coalesce(auth_event.payload->>'action', 'authentication_event')::text as action,
        case auth_event.payload->>'action'
          when 'login' then 'Signed in'
          when 'logout' then 'Signed out'
          when 'token_revoked' then 'Session revoked'
          when 'token_refreshed' then 'Session refreshed'
          when 'user_invited' then 'User invited'
          when 'invited' then 'User invited'
          when 'invite_accepted' then 'Invitation accepted'
          when 'user_recovery_requested' then 'Password recovery requested'
          when 'recovery' then 'Password recovery requested'
          when 'user_updated_password' then 'Password updated'
          when 'user_modified' then 'User account updated'
          when 'modified' then 'User account updated'
          when 'user_deleted' then 'User account deleted'
          when 'deleted' then 'User account deleted'
          when 'signedup' then 'User account created'
          else initcap(replace(coalesce(auth_event.payload->>'action', 'authentication event'), '_', ' '))
        end::text as title,
        coalesce(nullif(concat_ws(' ', workspace_user."User_Firstname", workspace_user."User_Lastname"), ''), auth_event.payload->>'actor_name')::text as actor_name,
        coalesce(workspace_user."User_Email", auth_event.payload->>'actor_username')::text as actor_email,
        'Supabase Auth'::text as source,
        'user_session'::text as record_type,
        auth_event.payload->>'actor_id' as record_id,
        jsonb_build_object('auth_user_id', auth_event.payload->>'actor_id') as record_key,
        auth_event.ip_address::text as ip_address,
        'success'::text as outcome,
        nullif(auth_event.payload->'traits'->>'provider', '')::text as detail,
        null::text as field_name,
        null::jsonb as old_value,
        null::jsonb as new_value,
        null::text as request_id,
        null::text as correlation_id,
        false as is_sensitive
      from auth.audit_log_entries as auth_event
      left join public."cmp_Users" as workspace_user
        on (
          coalesce(workspace_user."Auth_User_ID", workspace_user."User_RetainedAuthUserID") =
          case
            when coalesce(auth_event.payload->>'actor_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              then (auth_event.payload->>'actor_id')::uuid
            else null
          end
        )
      order by auth_event.created_at desc
      limit v_limit
    )
    select combined.*
    from (
      select * from app_rows
      union all
      select * from auth_rows
    ) as combined
    order by combined.occurred_at desc
    limit v_limit;
  else
    return query
    with recent_app_events as (
      select event.*
      from public."Audit_Events" as event
      order by event."AuditEvent_OccurredAt" desc
      limit v_limit
    ),
    app_rows as (
      select
        'app:' || event."AuditEvent_ID"::text as id,
        event."AuditEvent_OccurredAt" as occurred_at,
        'application'::text as category,
        coalesce(event."AuditEvent_Action"::text, event."AuditEvent_EventTypeCode"::text) as action,
        coalesce(
          event."AuditEvent_Title"::text,
          case event."AuditEvent_EventTypeCode"
            when 'row_insert' then 'Record created'
            when 'row_update' then 'Record updated'
            when 'row_delete' then 'Record deleted'
            when 'row_soft_delete' then 'Record archived'
            when 'row_restore' then 'Record restored'
            else initcap(replace(event."AuditEvent_EventTypeCode"::text, '_', ' '))
          end
        ) as title,
        nullif(concat_ws(' ', workspace_user."User_Firstname", workspace_user."User_Lastname"), '')::text as actor_name,
        workspace_user."User_Email"::text as actor_email,
        coalesce(event."AuditEvent_SourceModule"::text, event."AuditEvent_SourceTableName"::text, event."AuditEvent_SourceApp"::text, 'Multideck') as source,
        event."AuditEvent_RecordTypeCode"::text as record_type,
        event."AuditEvent_RecordID"::text as record_id,
        event."AuditEvent_RecordKeyJSON" as record_key,
        request_context."AuditRequest_IPHash"::text as ip_address,
        event."AuditEvent_OutcomeStatusCode"::text as outcome,
        event."AuditEvent_Reason"::text as detail,
        null::text as field_name,
        null::jsonb as old_value,
        null::jsonb as new_value,
        event."AuditEvent_RequestID"::text as request_id,
        event."AuditEvent_CorrelationID"::text as correlation_id,
        event."AuditEvent_IsSensitive" as is_sensitive
      from recent_app_events as event
      left join public."Audit_RequestContexts" as request_context
        on request_context."AuditRequest_ID" = event."AuditEvent_RequestContextID"
      left join public."cmp_Users" as workspace_user
        on workspace_user."User_ID" = coalesce(event."AuditEvent_UserID", request_context."AuditRequest_UserID")
        or workspace_user."Auth_User_ID" = coalesce(event."AuditEvent_AuthUserID", request_context."AuditRequest_AuthUserID")
    ),
    auth_rows as (
      select
        'auth:' || auth_event.id::text as id,
        auth_event.created_at as occurred_at,
        'authentication'::text as category,
        coalesce(auth_event.payload->>'action', 'authentication_event')::text as action,
        case auth_event.payload->>'action'
          when 'login' then 'Signed in'
          when 'logout' then 'Signed out'
          when 'token_revoked' then 'Session revoked'
          when 'user_invited' then 'User invited'
          when 'invited' then 'User invited'
          when 'invite_accepted' then 'Invitation accepted'
          when 'user_recovery_requested' then 'Password recovery requested'
          when 'recovery' then 'Password recovery requested'
          when 'user_updated_password' then 'Password updated'
          when 'user_modified' then 'User account updated'
          when 'modified' then 'User account updated'
          when 'user_deleted' then 'User account deleted'
          when 'deleted' then 'User account deleted'
          when 'signedup' then 'User account created'
          else initcap(replace(coalesce(auth_event.payload->>'action', 'authentication event'), '_', ' '))
        end::text as title,
        coalesce(nullif(concat_ws(' ', workspace_user."User_Firstname", workspace_user."User_Lastname"), ''), auth_event.payload->>'actor_name')::text as actor_name,
        coalesce(workspace_user."User_Email", auth_event.payload->>'actor_username')::text as actor_email,
        'Supabase Auth'::text as source,
        'user_session'::text as record_type,
        auth_event.payload->>'actor_id' as record_id,
        jsonb_build_object('auth_user_id', auth_event.payload->>'actor_id') as record_key,
        auth_event.ip_address::text as ip_address,
        'success'::text as outcome,
        nullif(auth_event.payload->'traits'->>'provider', '')::text as detail,
        null::text as field_name,
        null::jsonb as old_value,
        null::jsonb as new_value,
        null::text as request_id,
        null::text as correlation_id,
        false as is_sensitive
      from auth.audit_log_entries as auth_event
      left join public."cmp_Users" as workspace_user
        on (
          coalesce(workspace_user."Auth_User_ID", workspace_user."User_RetainedAuthUserID") =
          case
            when coalesce(auth_event.payload->>'actor_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              then (auth_event.payload->>'actor_id')::uuid
            else null
          end
        )
      where coalesce(auth_event.payload->>'action', '') not in ('token_refreshed', 'token_revoked')
      order by auth_event.created_at desc
      limit v_limit
    )
    select combined.*
    from (
      select * from app_rows
      union all
      select * from auth_rows
    ) as combined
    order by combined.occurred_at desc
    limit v_limit;
  end if;
end;
$_$;


ALTER FUNCTION "public"."Admin_AuditLog"("p_actor_user_id" "uuid", "p_detailed" boolean, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."Admin_AuditLogPage"("p_actor_user_id" "uuid", "p_detailed" boolean DEFAULT false, "p_query" "text" DEFAULT NULL::"text", "p_category" "text" DEFAULT 'all'::"text", "p_start_date" "date" DEFAULT NULL::"date", "p_end_date" "date" DEFAULT NULL::"date", "p_sort_direction" "text" DEFAULT 'desc'::"text", "p_limit" integer DEFAULT 25, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_query text := nullif(lower(left(trim(coalesce(p_query, '')), 120)), '');
  v_category text := case when p_category in ('authentication', 'application') then p_category else 'all' end;
  v_start_at timestamptz := p_start_date::timestamptz;
  v_end_at timestamptz := (p_end_date + 1)::timestamptz;
  v_direction text := case when lower(coalesce(p_sort_direction, 'desc')) = 'asc' then 'asc' else 'desc' end;
  v_limit integer := least(greatest(coalesce(p_limit, 25), 1), 50);
  v_offset integer := least(greatest(coalesce(p_offset, 0), 0), 1000000);
  v_candidate_limit integer;
  v_application_total bigint := 0;
  v_authentication_total bigint := 0;
  v_total bigint := 0;
  v_rows jsonb := '[]'::jsonb;
begin
  if not private.is_tenant_administrator(p_actor_user_id) then
    raise exception 'Only tenant administrators can view the audit log.' using errcode = '42501';
  end if;

  v_candidate_limit := least(v_offset + v_limit, 1000050);

  -- The ordinary, unsearched register gets exact totals from narrow count
  -- queries and only enriches enough chronological candidates for this page.
  if v_query is null then
    if v_category in ('all', 'application') then
      if p_detailed then
        select count(*)
        into v_application_total
        from public."Audit_Events" as event
        left join public."Audit_FieldChanges" as field_change
          on field_change."AuditFieldChange_EventID" = event."AuditEvent_ID"
        where (v_start_at is null or event."AuditEvent_OccurredAt" >= v_start_at)
          and (v_end_at is null or event."AuditEvent_OccurredAt" < v_end_at);
      else
        select count(*) into v_application_total
        from public."Audit_Events" as event
        where (v_start_at is null or event."AuditEvent_OccurredAt" >= v_start_at)
          and (v_end_at is null or event."AuditEvent_OccurredAt" < v_end_at);
      end if;
    end if;

    if v_category in ('all', 'authentication') then
      select count(*)
      into v_authentication_total
      from auth.audit_log_entries as auth_event
      where (p_detailed
        or coalesce(auth_event.payload->>'action', '') not in ('token_refreshed', 'token_revoked'))
        and (v_start_at is null or auth_event.created_at >= v_start_at)
        and (v_end_at is null or auth_event.created_at < v_end_at);
    end if;

    v_total := v_application_total + v_authentication_total;

    with app_candidates as (
      select event.*
      from public."Audit_Events" as event
      where v_category in ('all', 'application')
        and (v_start_at is null or event."AuditEvent_OccurredAt" >= v_start_at)
        and (v_end_at is null or event."AuditEvent_OccurredAt" < v_end_at)
      order by
        case when v_direction = 'asc' then event."AuditEvent_OccurredAt" end asc,
        case when v_direction = 'asc' then event."AuditEvent_ID" end asc,
        case when v_direction = 'desc' then event."AuditEvent_OccurredAt" end desc,
        case when v_direction = 'desc' then event."AuditEvent_ID" end desc
      limit v_candidate_limit
    ),
    app_rows as (
      select
        'app:' || event."AuditEvent_ID"::text || case when p_detailed and field_change."AuditFieldChange_ID" is not null then ':' || field_change."AuditFieldChange_ID"::text else '' end as id,
        event."AuditEvent_OccurredAt" as occurred_at,
        'application'::text as category,
        coalesce(event."AuditEvent_Action"::text, event."AuditEvent_EventTypeCode"::text) as action,
        coalesce(
          event."AuditEvent_Title"::text,
          case event."AuditEvent_EventTypeCode"
            when 'row_insert' then 'Record created'
            when 'row_update' then 'Record updated'
            when 'row_delete' then 'Record deleted'
            when 'row_soft_delete' then 'Record archived'
            when 'row_restore' then 'Record restored'
            else initcap(replace(event."AuditEvent_EventTypeCode"::text, '_', ' '))
          end
        ) as title,
        coalesce(event."AuditEvent_UserID", request_context."AuditRequest_UserID")::text as actor_id,
        nullif(concat_ws(' ', workspace_user."User_Firstname", workspace_user."User_Lastname"), '')::text as actor_name,
        workspace_user."User_Email"::text as actor_email,
        coalesce(event."AuditEvent_SourceModule"::text, event."AuditEvent_SourceTableName"::text, event."AuditEvent_SourceApp"::text, 'Multideck') as source,
        event."AuditEvent_RecordTypeCode"::text as record_type,
        event."AuditEvent_RecordID"::text as record_id,
        event."AuditEvent_RecordKeyJSON" as record_key,
        request_context."AuditRequest_IPHash"::text as ip_address,
        null::text as user_agent,
        event."AuditEvent_OutcomeStatusCode"::text as outcome,
        event."AuditEvent_Reason"::text as detail,
        case when p_detailed then field_change."AuditFieldChange_ColumnName"::text else null end as field_name,
        case when p_detailed then field_change."AuditFieldChange_OldValueJSON" else null end as old_value,
        case when p_detailed then field_change."AuditFieldChange_NewValueJSON" else null end as new_value,
        event."AuditEvent_RequestID"::text as request_id,
        event."AuditEvent_CorrelationID"::text as correlation_id,
        (event."AuditEvent_IsSensitive" or (p_detailed and coalesce(field_change."AuditFieldChange_IsSensitive", false))) as is_sensitive
      from app_candidates as event
      left join public."Audit_FieldChanges" as field_change
        on p_detailed and field_change."AuditFieldChange_EventID" = event."AuditEvent_ID"
      left join public."Audit_RequestContexts" as request_context
        on request_context."AuditRequest_ID" = event."AuditEvent_RequestContextID"
      left join public."cmp_Users" as workspace_user
        on workspace_user."User_ID" = coalesce(event."AuditEvent_UserID", request_context."AuditRequest_UserID")
        or workspace_user."Auth_User_ID" = coalesce(event."AuditEvent_AuthUserID", request_context."AuditRequest_AuthUserID")
    ),
    auth_candidates as (
      select auth_event.*
      from auth.audit_log_entries as auth_event
      where v_category in ('all', 'authentication')
        and (p_detailed or coalesce(auth_event.payload->>'action', '') not in ('token_refreshed', 'token_revoked'))
        and (v_start_at is null or auth_event.created_at >= v_start_at)
        and (v_end_at is null or auth_event.created_at < v_end_at)
      order by
        case when v_direction = 'asc' then auth_event.created_at end asc,
        case when v_direction = 'asc' then auth_event.id end asc,
        case when v_direction = 'desc' then auth_event.created_at end desc,
        case when v_direction = 'desc' then auth_event.id end desc
      limit v_candidate_limit
    ),
    auth_rows as (
      select
        'auth:' || auth_event.id::text as id,
        auth_event.created_at as occurred_at,
        'authentication'::text as category,
        coalesce(auth_event.payload->>'action', 'authentication_event')::text as action,
        case auth_event.payload->>'action'
          when 'login' then 'Signed in'
          when 'logout' then 'Signed out'
          when 'token_revoked' then 'Session revoked'
          when 'token_refreshed' then 'Session refreshed'
          when 'user_invited' then 'User invited'
          when 'invited' then 'User invited'
          when 'invite_accepted' then 'Invitation accepted'
          when 'user_recovery_requested' then 'Password recovery requested'
          when 'recovery' then 'Password recovery requested'
          when 'user_updated_password' then 'Password updated'
          when 'user_modified' then 'User account updated'
          when 'modified' then 'User account updated'
          when 'user_deleted' then 'User account deleted'
          when 'deleted' then 'User account deleted'
          when 'signedup' then 'User account created'
          else initcap(replace(coalesce(auth_event.payload->>'action', 'authentication event'), '_', ' '))
        end::text as title,
        auth_event.payload->>'actor_id' as actor_id,
        coalesce(nullif(concat_ws(' ', workspace_user."User_Firstname", workspace_user."User_Lastname"), ''), auth_event.payload->>'actor_name')::text as actor_name,
        coalesce(workspace_user."User_Email", auth_event.payload->>'actor_username')::text as actor_email,
        'Supabase Auth'::text as source,
        'user_session'::text as record_type,
        auth_event.payload->>'actor_id' as record_id,
        jsonb_build_object('auth_user_id', auth_event.payload->>'actor_id') as record_key,
        auth_event.ip_address::text as ip_address,
        null::text as user_agent,
        'success'::text as outcome,
        nullif(auth_event.payload->'traits'->>'provider', '')::text as detail,
        null::text as field_name,
        null::jsonb as old_value,
        null::jsonb as new_value,
        null::text as request_id,
        null::text as correlation_id,
        false as is_sensitive
      from auth_candidates as auth_event
      left join public."cmp_Users" as workspace_user
        on coalesce(workspace_user."Auth_User_ID", workspace_user."User_RetainedAuthUserID") =
          case
            when coalesce(auth_event.payload->>'actor_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              then (auth_event.payload->>'actor_id')::uuid
            else null
          end
    ),
    page_rows as (
      select combined.*
      from (
        select * from app_rows
        union all
        select * from auth_rows
      ) as combined
      order by
        case when v_direction = 'asc' then combined.occurred_at end asc,
        case when v_direction = 'asc' then combined.id end asc,
        case when v_direction = 'desc' then combined.occurred_at end desc,
        case when v_direction = 'desc' then combined.id end desc
      offset v_offset
      limit v_limit
    )
    select coalesce(jsonb_agg(to_jsonb(page_rows) order by
      case when v_direction = 'asc' then page_rows.occurred_at end asc,
      case when v_direction = 'asc' then page_rows.id end asc,
      case when v_direction = 'desc' then page_rows.occurred_at end desc,
      case when v_direction = 'desc' then page_rows.id end desc
    ), '[]'::jsonb)
    into v_rows
    from page_rows;
  else
    -- Search is intentionally exact across both evidence sources. It may scan
    -- more rows than the ordinary register, but still sends only one page to
    -- the browser and never silently truncates matching history.
    with app_rows as (
      select
        'app:' || event."AuditEvent_ID"::text || case when p_detailed and field_change."AuditFieldChange_ID" is not null then ':' || field_change."AuditFieldChange_ID"::text else '' end as id,
        event."AuditEvent_OccurredAt" as occurred_at,
        'application'::text as category,
        coalesce(event."AuditEvent_Action"::text, event."AuditEvent_EventTypeCode"::text) as action,
        coalesce(
          event."AuditEvent_Title"::text,
          case event."AuditEvent_EventTypeCode"
            when 'row_insert' then 'Record created'
            when 'row_update' then 'Record updated'
            when 'row_delete' then 'Record deleted'
            when 'row_soft_delete' then 'Record archived'
            when 'row_restore' then 'Record restored'
            else initcap(replace(event."AuditEvent_EventTypeCode"::text, '_', ' '))
          end
        ) as title,
        coalesce(event."AuditEvent_UserID", request_context."AuditRequest_UserID")::text as actor_id,
        nullif(concat_ws(' ', workspace_user."User_Firstname", workspace_user."User_Lastname"), '')::text as actor_name,
        workspace_user."User_Email"::text as actor_email,
        coalesce(event."AuditEvent_SourceModule"::text, event."AuditEvent_SourceTableName"::text, event."AuditEvent_SourceApp"::text, 'Multideck') as source,
        event."AuditEvent_RecordTypeCode"::text as record_type,
        event."AuditEvent_RecordID"::text as record_id,
        event."AuditEvent_RecordKeyJSON" as record_key,
        request_context."AuditRequest_IPHash"::text as ip_address,
        null::text as user_agent,
        event."AuditEvent_OutcomeStatusCode"::text as outcome,
        event."AuditEvent_Reason"::text as detail,
        case when p_detailed then field_change."AuditFieldChange_ColumnName"::text else null end as field_name,
        case when p_detailed then field_change."AuditFieldChange_OldValueJSON" else null end as old_value,
        case when p_detailed then field_change."AuditFieldChange_NewValueJSON" else null end as new_value,
        event."AuditEvent_RequestID"::text as request_id,
        event."AuditEvent_CorrelationID"::text as correlation_id,
        (event."AuditEvent_IsSensitive" or (p_detailed and coalesce(field_change."AuditFieldChange_IsSensitive", false))) as is_sensitive
      from public."Audit_Events" as event
      left join public."Audit_FieldChanges" as field_change
        on p_detailed and field_change."AuditFieldChange_EventID" = event."AuditEvent_ID"
      left join public."Audit_RequestContexts" as request_context
        on request_context."AuditRequest_ID" = event."AuditEvent_RequestContextID"
      left join public."cmp_Users" as workspace_user
        on workspace_user."User_ID" = coalesce(event."AuditEvent_UserID", request_context."AuditRequest_UserID")
        or workspace_user."Auth_User_ID" = coalesce(event."AuditEvent_AuthUserID", request_context."AuditRequest_AuthUserID")
      where v_category in ('all', 'application')
        and (v_start_at is null or event."AuditEvent_OccurredAt" >= v_start_at)
        and (v_end_at is null or event."AuditEvent_OccurredAt" < v_end_at)
    ),
    auth_rows as (
      select
        'auth:' || auth_event.id::text as id,
        auth_event.created_at as occurred_at,
        'authentication'::text as category,
        coalesce(auth_event.payload->>'action', 'authentication_event')::text as action,
        case auth_event.payload->>'action'
          when 'login' then 'Signed in'
          when 'logout' then 'Signed out'
          when 'token_revoked' then 'Session revoked'
          when 'token_refreshed' then 'Session refreshed'
          when 'user_invited' then 'User invited'
          when 'invited' then 'User invited'
          when 'invite_accepted' then 'Invitation accepted'
          when 'user_recovery_requested' then 'Password recovery requested'
          when 'recovery' then 'Password recovery requested'
          when 'user_updated_password' then 'Password updated'
          when 'user_modified' then 'User account updated'
          when 'modified' then 'User account updated'
          when 'user_deleted' then 'User account deleted'
          when 'deleted' then 'User account deleted'
          when 'signedup' then 'User account created'
          else initcap(replace(coalesce(auth_event.payload->>'action', 'authentication event'), '_', ' '))
        end::text as title,
        auth_event.payload->>'actor_id' as actor_id,
        coalesce(nullif(concat_ws(' ', workspace_user."User_Firstname", workspace_user."User_Lastname"), ''), auth_event.payload->>'actor_name')::text as actor_name,
        coalesce(workspace_user."User_Email", auth_event.payload->>'actor_username')::text as actor_email,
        'Supabase Auth'::text as source,
        'user_session'::text as record_type,
        auth_event.payload->>'actor_id' as record_id,
        jsonb_build_object('auth_user_id', auth_event.payload->>'actor_id') as record_key,
        auth_event.ip_address::text as ip_address,
        null::text as user_agent,
        'success'::text as outcome,
        nullif(auth_event.payload->'traits'->>'provider', '')::text as detail,
        null::text as field_name,
        null::jsonb as old_value,
        null::jsonb as new_value,
        null::text as request_id,
        null::text as correlation_id,
        false as is_sensitive
      from auth.audit_log_entries as auth_event
      left join public."cmp_Users" as workspace_user
        on coalesce(workspace_user."Auth_User_ID", workspace_user."User_RetainedAuthUserID") =
          case
            when coalesce(auth_event.payload->>'actor_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              then (auth_event.payload->>'actor_id')::uuid
            else null
          end
      where v_category in ('all', 'authentication')
        and (p_detailed or coalesce(auth_event.payload->>'action', '') not in ('token_refreshed', 'token_revoked'))
        and (v_start_at is null or auth_event.created_at >= v_start_at)
        and (v_end_at is null or auth_event.created_at < v_end_at)
    ),
    filtered_rows as materialized (
      select combined.*
      from (
        select * from app_rows
        union all
        select * from auth_rows
      ) as combined
      where lower(concat_ws(' ',
        combined.title,
        combined.action,
        combined.actor_name,
        combined.actor_email,
        combined.source,
        combined.record_type,
        combined.record_id,
        combined.field_name,
        combined.ip_address,
        combined.detail,
        combined.old_value::text,
        combined.new_value::text
      )) like '%' || v_query || '%'
    ),
    page_rows as (
      select filtered_rows.*
      from filtered_rows
      order by
        case when v_direction = 'asc' then filtered_rows.occurred_at end asc,
        case when v_direction = 'asc' then filtered_rows.id end asc,
        case when v_direction = 'desc' then filtered_rows.occurred_at end desc,
        case when v_direction = 'desc' then filtered_rows.id end desc
      offset v_offset
      limit v_limit
    )
    select
      (select count(*) from filtered_rows),
      coalesce((select jsonb_agg(to_jsonb(page_rows) order by
        case when v_direction = 'asc' then page_rows.occurred_at end asc,
        case when v_direction = 'asc' then page_rows.id end asc,
        case when v_direction = 'desc' then page_rows.occurred_at end desc,
        case when v_direction = 'desc' then page_rows.id end desc
      ) from page_rows), '[]'::jsonb)
    into v_total, v_rows;
  end if;

  return jsonb_build_object(
    'rows', v_rows,
    'total', v_total,
    'offset', v_offset,
    'limit', v_limit
  );
end;
$_$;


ALTER FUNCTION "public"."Admin_AuditLogPage"("p_actor_user_id" "uuid", "p_detailed" boolean, "p_query" "text", "p_category" "text", "p_start_date" "date", "p_end_date" "date", "p_sort_direction" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."Admin_AuditLogPage"("p_actor_user_id" "uuid", "p_detailed" boolean, "p_query" "text", "p_category" "text", "p_start_date" "date", "p_end_date" "date", "p_sort_direction" "text", "p_limit" integer, "p_offset" integer) IS 'Service-role-only, tenant-administrator-gated, bounded Admin audit register page. Sensitive audit evidence remains unavailable to Dexter and Watching for you.';



CREATE OR REPLACE FUNCTION "public"."Audit_CurrentUserID"() RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE
    AS $$
DECLARE
  v_user text;
BEGIN
  v_user := nullif(current_setting('app.user_id', true), '');
  IF v_user IS NOT NULL THEN
    RETURN v_user::uuid;
  END IF;

  v_user := nullif(current_setting('request.jwt.claim.sub', true), '');
  IF v_user IS NOT NULL THEN
    RETURN v_user::uuid;
  END IF;

  RETURN NULL;
EXCEPTION WHEN invalid_text_representation THEN
  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."Audit_CurrentUserID"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."Audit_DisableTableAudit"("p_table_schema" character varying, "p_table_name" character varying) RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  UPDATE public."Audit_TablePolicies"
  SET "AuditPolicy_IsEnabled" = false,
      "AuditPolicy_UpdatedAt" = now()
  WHERE "AuditPolicy_TableSchema" = p_table_schema
    AND "AuditPolicy_TableName" = p_table_name;

  EXECUTE format('DROP TRIGGER IF EXISTS "zz_audit_row_change" ON %I.%I;', p_table_schema, p_table_name);
END;
$$;


ALTER FUNCTION "public"."Audit_DisableTableAudit"("p_table_schema" character varying, "p_table_name" character varying) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."Audit_EnableTableAudit"("p_table_schema" character varying, "p_table_name" character varying, "p_record_type_code" character varying DEFAULT NULL::character varying, "p_mode_code" character varying DEFAULT 'all_changes'::character varying, "p_retention_class_code" character varying DEFAULT 'standard_7y'::character varying, "p_sensitivity_code" character varying DEFAULT 'normal'::character varying, "p_track_row_snapshots" boolean DEFAULT false, "p_key_columns" "text"[] DEFAULT NULL::"text"[], "p_include_columns" "text"[] DEFAULT NULL::"text"[], "p_ignore_columns" "text"[] DEFAULT NULL::"text"[], "p_redact_columns" "text"[] DEFAULT NULL::"text"[]) RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_policy_id uuid;
  v_table_regclass regclass;
BEGIN
  IF p_table_schema = 'public' AND p_table_name LIKE 'Audit\_%' ESCAPE '\' THEN
    RAISE EXCEPTION 'Audit tables cannot be audited by Audit_RowChangeTrigger to avoid recursion.';
  END IF;

  SELECT to_regclass(format('%I.%I', p_table_schema, p_table_name)) INTO v_table_regclass;
  IF v_table_regclass IS NULL THEN
    RAISE EXCEPTION 'Table %.% does not exist.', p_table_schema, p_table_name;
  END IF;

  INSERT INTO public."Audit_TablePolicies"
    (
      "AuditPolicy_TableSchema",
      "AuditPolicy_TableName",
      "AuditPolicy_RecordTypeCode",
      "AuditPolicy_ModeCode",
      "AuditPolicy_RetentionClassCode",
      "AuditPolicy_SensitivityCode",
      "AuditPolicy_TrackFieldChanges",
      "AuditPolicy_TrackRowSnapshots",
      "AuditPolicy_KeyColumnsJSON",
      "AuditPolicy_IncludeColumnsJSON",
      "AuditPolicy_IgnoreColumnsJSON",
      "AuditPolicy_RedactColumnsJSON",
      "AuditPolicy_IsEnabled"
    )
  VALUES
    (
      p_table_schema,
      p_table_name,
      p_record_type_code,
      p_mode_code,
      p_retention_class_code,
      p_sensitivity_code,
      p_mode_code IN ('key_fields', 'all_changes', 'full_snapshot'),
      p_track_row_snapshots OR p_mode_code = 'full_snapshot',
      coalesce(to_jsonb(p_key_columns), '[]'::jsonb),
      coalesce(to_jsonb(p_include_columns), '[]'::jsonb),
      coalesce(to_jsonb(p_ignore_columns), '[]'::jsonb),
      coalesce(to_jsonb(p_redact_columns), '[]'::jsonb),
      true
    )
  ON CONFLICT ("AuditPolicy_TableSchema", "AuditPolicy_TableName") DO UPDATE SET
    "AuditPolicy_RecordTypeCode" = EXCLUDED."AuditPolicy_RecordTypeCode",
    "AuditPolicy_ModeCode" = EXCLUDED."AuditPolicy_ModeCode",
    "AuditPolicy_RetentionClassCode" = EXCLUDED."AuditPolicy_RetentionClassCode",
    "AuditPolicy_SensitivityCode" = EXCLUDED."AuditPolicy_SensitivityCode",
    "AuditPolicy_TrackFieldChanges" = EXCLUDED."AuditPolicy_TrackFieldChanges",
    "AuditPolicy_TrackRowSnapshots" = EXCLUDED."AuditPolicy_TrackRowSnapshots",
    "AuditPolicy_KeyColumnsJSON" = EXCLUDED."AuditPolicy_KeyColumnsJSON",
    "AuditPolicy_IncludeColumnsJSON" = EXCLUDED."AuditPolicy_IncludeColumnsJSON",
    "AuditPolicy_IgnoreColumnsJSON" = EXCLUDED."AuditPolicy_IgnoreColumnsJSON",
    "AuditPolicy_RedactColumnsJSON" = EXCLUDED."AuditPolicy_RedactColumnsJSON",
    "AuditPolicy_IsEnabled" = true,
    "AuditPolicy_UpdatedAt" = now()
  RETURNING "AuditPolicy_ID" INTO v_policy_id;

  EXECUTE format('DROP TRIGGER IF EXISTS "zz_audit_row_change" ON %I.%I;', p_table_schema, p_table_name);
  EXECUTE format(
    'CREATE TRIGGER "zz_audit_row_change" AFTER INSERT OR UPDATE OR DELETE ON %I.%I FOR EACH ROW EXECUTE FUNCTION public."Audit_RowChangeTrigger"();',
    p_table_schema,
    p_table_name
  );

  RETURN v_policy_id;
END;
$$;


ALTER FUNCTION "public"."Audit_EnableTableAudit"("p_table_schema" character varying, "p_table_name" character varying, "p_record_type_code" character varying, "p_mode_code" character varying, "p_retention_class_code" character varying, "p_sensitivity_code" character varying, "p_track_row_snapshots" boolean, "p_key_columns" "text"[], "p_include_columns" "text"[], "p_ignore_columns" "text"[], "p_redact_columns" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."Audit_LogBusinessEvent"("p_event_type_code" character varying, "p_record_type_code" character varying DEFAULT NULL::character varying, "p_record_id" "uuid" DEFAULT NULL::"uuid", "p_source_table_name" character varying DEFAULT NULL::character varying, "p_action" character varying DEFAULT NULL::character varying, "p_title" character varying DEFAULT NULL::character varying, "p_reason" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_event_id uuid;
  v_request_id text;
  v_request_context_id uuid;
BEGIN
  v_request_id := nullif(current_setting('app.request_id', true), '');
  IF v_request_id IS NOT NULL THEN
    SELECT "AuditRequest_ID"
    INTO v_request_context_id
    FROM public."Audit_RequestContexts"
    WHERE "AuditRequest_RequestID" = v_request_id;
  END IF;

  INSERT INTO public."Audit_Events"
    (
      "AuditEvent_EventTypeCode",
      "AuditEvent_ActorTypeCode",
      "AuditEvent_UserID",
      "AuditEvent_AuthUserID",
      "AuditEvent_RequestContextID",
      "AuditEvent_RequestID",
      "AuditEvent_SessionID",
      "AuditEvent_CorrelationID",
      "AuditEvent_SourceApp",
      "AuditEvent_SourceModule",
      "AuditEvent_SourceTableSchema",
      "AuditEvent_SourceTableName",
      "AuditEvent_RecordTypeCode",
      "AuditEvent_RecordID",
      "AuditEvent_Action",
      "AuditEvent_Title",
      "AuditEvent_Reason",
      "AuditEvent_MetadataJSON"
    )
  VALUES
    (
      p_event_type_code,
      coalesce(nullif(current_setting('app.actor_type', true), ''), 'user'),
      public."Audit_CurrentUserID"(),
      nullif(current_setting('app.auth_user_id', true), '')::uuid,
      v_request_context_id,
      v_request_id,
      nullif(current_setting('app.session_id', true), ''),
      nullif(current_setting('app.correlation_id', true), ''),
      nullif(current_setting('app.source_app', true), ''),
      nullif(current_setting('app.source_module', true), ''),
      'public',
      p_source_table_name,
      p_record_type_code,
      p_record_id,
      p_action,
      p_title,
      p_reason,
      coalesce(p_metadata, '{}'::jsonb)
    )
  RETURNING "AuditEvent_ID" INTO v_event_id;

  RETURN v_event_id;
END;
$$;


ALTER FUNCTION "public"."Audit_LogBusinessEvent"("p_event_type_code" character varying, "p_record_type_code" character varying, "p_record_id" "uuid", "p_source_table_name" character varying, "p_action" character varying, "p_title" character varying, "p_reason" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."Audit_RecordAccessEvent"("p_access_type_code" character varying, "p_record_type_code" character varying DEFAULT NULL::character varying, "p_record_id" "uuid" DEFAULT NULL::"uuid", "p_source_table_name" character varying DEFAULT NULL::character varying, "p_document_id" "uuid" DEFAULT NULL::"uuid", "p_file_path_hash" character varying DEFAULT NULL::character varying, "p_reason" "text" DEFAULT NULL::"text", "p_was_allowed" boolean DEFAULT true, "p_denied_reason" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_event_type varchar(60);
  v_event_id uuid;
  v_access_id uuid;
BEGIN
  v_event_type := CASE p_access_type_code
    WHEN 'download' THEN 'document_download'
    WHEN 'export' THEN 'data_export'
    WHEN 'print' THEN 'print'
    WHEN 'share' THEN 'share'
    ELSE 'data_read'
  END;

  v_event_id := public."Audit_LogBusinessEvent"(
    v_event_type,
    p_record_type_code,
    p_record_id,
    p_source_table_name,
    p_access_type_code,
    initcap(replace(p_access_type_code, '_', ' ')),
    p_reason,
    p_metadata
  );

  INSERT INTO public."Audit_AccessEvents"
    (
      "AuditAccess_EventID",
      "AuditAccess_AccessTypeCode",
      "AuditAccess_RecordTypeCode",
      "AuditAccess_RecordID",
      "AuditAccess_SourceTableName",
      "AuditAccess_DocumentID",
      "AuditAccess_FilePathHash",
      "AuditAccess_UserID",
      "AuditAccess_AuthUserID",
      "AuditAccess_RequestID",
      "AuditAccess_SessionID",
      "AuditAccess_Reason",
      "AuditAccess_WasAllowed",
      "AuditAccess_DeniedReason",
      "AuditAccess_MetadataJSON"
    )
  VALUES
    (
      v_event_id,
      p_access_type_code,
      p_record_type_code,
      p_record_id,
      p_source_table_name,
      p_document_id,
      p_file_path_hash,
      public."Audit_CurrentUserID"(),
      nullif(current_setting('app.auth_user_id', true), '')::uuid,
      nullif(current_setting('app.request_id', true), ''),
      nullif(current_setting('app.session_id', true), ''),
      p_reason,
      p_was_allowed,
      p_denied_reason,
      coalesce(p_metadata, '{}'::jsonb)
    )
  RETURNING "AuditAccess_ID" INTO v_access_id;

  RETURN v_access_id;
END;
$$;


ALTER FUNCTION "public"."Audit_RecordAccessEvent"("p_access_type_code" character varying, "p_record_type_code" character varying, "p_record_id" "uuid", "p_source_table_name" character varying, "p_document_id" "uuid", "p_file_path_hash" character varying, "p_reason" "text", "p_was_allowed" boolean, "p_denied_reason" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."Audit_RecordExportEvent"("p_export_type" character varying, "p_record_type_code" character varying DEFAULT NULL::character varying, "p_source_table_name" character varying DEFAULT NULL::character varying, "p_filter_summary" "text" DEFAULT NULL::"text", "p_query_hash" character varying DEFAULT NULL::character varying, "p_row_count" integer DEFAULT NULL::integer, "p_file_name" character varying DEFAULT NULL::character varying, "p_file_path_hash" character varying DEFAULT NULL::character varying, "p_file_hash" character varying DEFAULT NULL::character varying, "p_format" character varying DEFAULT NULL::character varying, "p_reason" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_event_id uuid;
  v_export_id uuid;
BEGIN
  v_event_id := public."Audit_LogBusinessEvent"(
    'data_export',
    p_record_type_code,
    NULL,
    p_source_table_name,
    p_export_type,
    'Data export',
    p_reason,
    p_metadata
  );

  INSERT INTO public."Audit_ExportEvents"
    (
      "AuditExport_EventID",
      "AuditExport_ExportType",
      "AuditExport_RecordTypeCode",
      "AuditExport_SourceTableName",
      "AuditExport_FilterSummary",
      "AuditExport_QueryHash",
      "AuditExport_RowCount",
      "AuditExport_FileName",
      "AuditExport_FilePathHash",
      "AuditExport_FileHash",
      "AuditExport_Format",
      "AuditExport_UserID",
      "AuditExport_RequestID",
      "AuditExport_Reason",
      "AuditExport_MetadataJSON"
    )
  VALUES
    (
      v_event_id,
      p_export_type,
      p_record_type_code,
      p_source_table_name,
      p_filter_summary,
      p_query_hash,
      p_row_count,
      p_file_name,
      p_file_path_hash,
      p_file_hash,
      p_format,
      public."Audit_CurrentUserID"(),
      nullif(current_setting('app.request_id', true), ''),
      p_reason,
      coalesce(p_metadata, '{}'::jsonb)
    )
  RETURNING "AuditExport_ID" INTO v_export_id;

  RETURN v_export_id;
END;
$$;


ALTER FUNCTION "public"."Audit_RecordExportEvent"("p_export_type" character varying, "p_record_type_code" character varying, "p_source_table_name" character varying, "p_filter_summary" "text", "p_query_hash" character varying, "p_row_count" integer, "p_file_name" character varying, "p_file_path_hash" character varying, "p_file_hash" character varying, "p_format" character varying, "p_reason" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."Audit_RowChangeTrigger"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public', 'extensions'
    AS $_$
DECLARE
  v_policy public."Audit_TablePolicies"%rowtype;
  v_old_row jsonb;
  v_new_row jsonb;
  v_work_row jsonb;
  v_event_type varchar(60);
  v_event_id uuid;
  v_pk_cols text[];
  v_pk_col text;
  v_record_key jsonb := '{}'::jsonb;
  v_record_id uuid;
  v_field_name text;
  v_old_value jsonb;
  v_new_value jsonb;
  v_data_type varchar(120);
  v_changed_count integer := 0;
  v_redact boolean;
  v_sensitive boolean;
  v_include_has_values boolean;
  v_old_hash varchar(128);
  v_new_hash varchar(128);
  v_request_context_id uuid;
  v_request_id text;
  v_actor_type varchar(40);
  v_auth_user_id uuid;
  v_org_office_id uuid;
  v_legal_entity_id uuid;
  v_brand_id uuid;
BEGIN
  SELECT *
  INTO v_policy
  FROM public."Audit_TablePolicies"
  WHERE "AuditPolicy_TableSchema" = TG_TABLE_SCHEMA
    AND "AuditPolicy_TableName" = TG_TABLE_NAME
    AND "AuditPolicy_IsEnabled" = true
    AND "AuditPolicy_ModeCode" <> 'off';

  IF NOT FOUND THEN
    IF TG_OP = 'DELETE' THEN
      RETURN OLD;
    END IF;
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' AND NOT v_policy."AuditPolicy_TrackInserts" THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' AND NOT v_policy."AuditPolicy_TrackUpdates" THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'DELETE' AND NOT v_policy."AuditPolicy_TrackDeletes" THEN
    RETURN OLD;
  END IF;

  v_old_row := CASE WHEN TG_OP IN ('UPDATE', 'DELETE') THEN to_jsonb(OLD) ELSE NULL END;
  v_new_row := CASE WHEN TG_OP IN ('INSERT', 'UPDATE') THEN to_jsonb(NEW) ELSE NULL END;
  v_work_row := coalesce(v_new_row, v_old_row);

  IF TG_OP = 'UPDATE' AND v_old_row = v_new_row AND NOT v_policy."AuditPolicy_TrackUnchangedUpdates" THEN
    RETURN NEW;
  END IF;

  v_event_type := CASE TG_OP
    WHEN 'INSERT' THEN 'row_insert'
    WHEN 'DELETE' THEN 'row_delete'
    ELSE
      CASE
        WHEN (v_old_row ? 'IsDeleted') AND (v_new_row ? 'IsDeleted') AND coalesce((v_old_row->>'IsDeleted')::boolean, false) = false AND coalesce((v_new_row->>'IsDeleted')::boolean, false) = true THEN 'row_soft_delete'
        WHEN (v_old_row ? 'IsDeleted') AND (v_new_row ? 'IsDeleted') AND coalesce((v_old_row->>'IsDeleted')::boolean, false) = true AND coalesce((v_new_row->>'IsDeleted')::boolean, false) = false THEN 'row_restore'
        ELSE 'row_update'
      END
  END;

  IF jsonb_array_length(v_policy."AuditPolicy_KeyColumnsJSON") > 0 THEN
    SELECT array_agg(x.value)
    INTO v_pk_cols
    FROM jsonb_array_elements_text(v_policy."AuditPolicy_KeyColumnsJSON") AS x(value);
  ELSE
    SELECT array_agg(a.attname ORDER BY array_position(c.conkey, a.attnum))
    INTO v_pk_cols
    FROM pg_constraint c
    JOIN pg_class cl ON cl.oid = c.conrelid
    JOIN pg_namespace n ON n.oid = cl.relnamespace
    JOIN pg_attribute a ON a.attrelid = cl.oid AND a.attnum = ANY(c.conkey)
    WHERE c.contype = 'p'
      AND n.nspname = TG_TABLE_SCHEMA
      AND cl.relname = TG_TABLE_NAME;
  END IF;

  IF v_pk_cols IS NOT NULL THEN
    FOREACH v_pk_col IN ARRAY v_pk_cols LOOP
      v_record_key := v_record_key || jsonb_build_object(v_pk_col, v_work_row -> v_pk_col);
    END LOOP;
    IF array_length(v_pk_cols, 1) = 1 AND coalesce(v_work_row ->> v_pk_cols[1], '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_record_id := (v_work_row ->> v_pk_cols[1])::uuid;
    END IF;
  END IF;

  v_old_hash := CASE WHEN v_old_row IS NULL THEN NULL ELSE encode(digest(v_old_row::text, 'sha256'), 'hex') END;
  v_new_hash := CASE WHEN v_new_row IS NULL THEN NULL ELSE encode(digest(v_new_row::text, 'sha256'), 'hex') END;

  v_request_id := nullif(current_setting('app.request_id', true), '');
  v_actor_type := coalesce(nullif(current_setting('app.actor_type', true), ''), 'user');
  BEGIN
    v_auth_user_id := nullif(current_setting('app.auth_user_id', true), '')::uuid;
  EXCEPTION WHEN invalid_text_representation THEN
    v_auth_user_id := NULL;
  END;
  BEGIN
    v_org_office_id := nullif(current_setting('app.org_office_id', true), '')::uuid;
  EXCEPTION WHEN invalid_text_representation THEN
    v_org_office_id := NULL;
  END;
  BEGIN
    v_legal_entity_id := nullif(current_setting('app.legal_entity_id', true), '')::uuid;
  EXCEPTION WHEN invalid_text_representation THEN
    v_legal_entity_id := NULL;
  END;
  BEGIN
    v_brand_id := nullif(current_setting('app.brand_id', true), '')::uuid;
  EXCEPTION WHEN invalid_text_representation THEN
    v_brand_id := NULL;
  END;

  IF v_request_id IS NOT NULL THEN
    SELECT "AuditRequest_ID"
    INTO v_request_context_id
    FROM public."Audit_RequestContexts"
    WHERE "AuditRequest_RequestID" = v_request_id;
  END IF;

  v_include_has_values := jsonb_array_length(v_policy."AuditPolicy_IncludeColumnsJSON") > 0;

  INSERT INTO public."Audit_Events"
    (
      "AuditEvent_EventTypeCode",
      "AuditEvent_ActorTypeCode",
      "AuditEvent_UserID",
      "AuditEvent_AuthUserID",
      "AuditEvent_OrgOfficeID",
      "AuditEvent_LegalEntityID",
      "AuditEvent_BrandID",
      "AuditEvent_RequestContextID",
      "AuditEvent_RequestID",
      "AuditEvent_SessionID",
      "AuditEvent_CorrelationID",
      "AuditEvent_SourceApp",
      "AuditEvent_SourceModule",
      "AuditEvent_SourceTableSchema",
      "AuditEvent_SourceTableName",
      "AuditEvent_RecordTypeCode",
      "AuditEvent_RecordID",
      "AuditEvent_RecordKeyJSON",
      "AuditEvent_Action",
      "AuditEvent_OldRowHash",
      "AuditEvent_NewRowHash",
      "AuditEvent_HasFieldChanges",
      "AuditEvent_HasRowSnapshot",
      "AuditEvent_IsSensitive",
      "AuditEvent_SensitivityCode",
      "AuditEvent_RetentionClassCode",
      "AuditEvent_MetadataJSON"
    )
  VALUES
    (
      v_event_type,
      v_actor_type,
      public."Audit_CurrentUserID"(),
      v_auth_user_id,
      v_org_office_id,
      v_legal_entity_id,
      v_brand_id,
      v_request_context_id,
      v_request_id,
      nullif(current_setting('app.session_id', true), ''),
      nullif(current_setting('app.correlation_id', true), ''),
      nullif(current_setting('app.source_app', true), ''),
      nullif(current_setting('app.source_module', true), ''),
      TG_TABLE_SCHEMA,
      TG_TABLE_NAME,
      v_policy."AuditPolicy_RecordTypeCode",
      v_record_id,
      v_record_key,
      TG_OP,
      v_old_hash,
      v_new_hash,
      v_policy."AuditPolicy_TrackFieldChanges" AND v_policy."AuditPolicy_ModeCode" IN ('key_fields', 'all_changes', 'full_snapshot'),
      v_policy."AuditPolicy_TrackRowSnapshots" OR v_policy."AuditPolicy_ModeCode" = 'full_snapshot',
      v_policy."AuditPolicy_SensitivityCode" IN ('confidential', 'restricted', 'secret'),
      v_policy."AuditPolicy_SensitivityCode",
      v_policy."AuditPolicy_RetentionClassCode",
      jsonb_build_object('trigger', TG_NAME, 'operation', TG_OP)
    )
  RETURNING "AuditEvent_ID" INTO v_event_id;

  IF v_policy."AuditPolicy_TrackRowSnapshots" OR v_policy."AuditPolicy_ModeCode" = 'full_snapshot' THEN
    IF v_old_row IS NOT NULL THEN
      INSERT INTO public."Audit_RowSnapshots"
        ("AuditSnapshot_EventID", "AuditSnapshot_SnapshotType", "AuditSnapshot_RowJSON", "AuditSnapshot_RowHash", "AuditSnapshot_IsRedacted")
      VALUES
        (v_event_id, 'old', v_old_row, v_old_hash, false);
    END IF;
    IF v_new_row IS NOT NULL THEN
      INSERT INTO public."Audit_RowSnapshots"
        ("AuditSnapshot_EventID", "AuditSnapshot_SnapshotType", "AuditSnapshot_RowJSON", "AuditSnapshot_RowHash", "AuditSnapshot_IsRedacted")
      VALUES
        (v_event_id, 'new', v_new_row, v_new_hash, false);
    END IF;
  END IF;

  IF v_policy."AuditPolicy_TrackFieldChanges" AND v_policy."AuditPolicy_ModeCode" IN ('key_fields', 'all_changes', 'full_snapshot') THEN
    FOR v_field_name IN
      SELECT DISTINCT key
      FROM (
        SELECT jsonb_object_keys(coalesce(v_old_row, '{}'::jsonb)) AS key
        UNION
        SELECT jsonb_object_keys(coalesce(v_new_row, '{}'::jsonb)) AS key
      ) keys
      ORDER BY key
    LOOP
      IF v_policy."AuditPolicy_IgnoreColumnsJSON" ? v_field_name THEN
        CONTINUE;
      END IF;

      IF v_policy."AuditPolicy_ModeCode" = 'key_fields' AND NOT (v_policy."AuditPolicy_KeyColumnsJSON" ? v_field_name) THEN
        CONTINUE;
      END IF;

      IF v_include_has_values AND NOT (v_policy."AuditPolicy_IncludeColumnsJSON" ? v_field_name) THEN
        CONTINUE;
      END IF;

      v_old_value := CASE WHEN v_old_row IS NULL THEN NULL ELSE v_old_row -> v_field_name END;
      v_new_value := CASE WHEN v_new_row IS NULL THEN NULL ELSE v_new_row -> v_field_name END;

      IF v_old_value IS NOT DISTINCT FROM v_new_value THEN
        CONTINUE;
      END IF;

      v_redact :=
        v_policy."AuditPolicy_RedactColumnsJSON" ? v_field_name
        OR v_field_name ~* '(password|secret|token|api.?key|private.?key|credential|connectionuri|connection_string)';
      v_sensitive := v_redact OR v_policy."AuditPolicy_SensitivityCode" IN ('restricted', 'secret');

      SELECT format_type(a.atttypid, a.atttypmod)
      INTO v_data_type
      FROM pg_attribute a
      JOIN pg_class cl ON cl.oid = a.attrelid
      JOIN pg_namespace n ON n.oid = cl.relnamespace
      WHERE n.nspname = TG_TABLE_SCHEMA
        AND cl.relname = TG_TABLE_NAME
        AND a.attname = v_field_name
        AND a.attnum > 0
        AND NOT a.attisdropped;

      INSERT INTO public."Audit_FieldChanges"
        (
          "AuditFieldChange_EventID",
          "AuditFieldChange_ColumnName",
          "AuditFieldChange_DataType",
          "AuditFieldChange_OldValueJSON",
          "AuditFieldChange_NewValueJSON",
          "AuditFieldChange_OldValueHash",
          "AuditFieldChange_NewValueHash",
          "AuditFieldChange_IsRedacted",
          "AuditFieldChange_IsSensitive",
          "AuditFieldChange_SensitivityCode"
        )
      VALUES
        (
          v_event_id,
          v_field_name,
          v_data_type,
          CASE WHEN v_redact AND v_old_value IS NOT NULL THEN to_jsonb('[REDACTED]'::text) ELSE v_old_value END,
          CASE WHEN v_redact AND v_new_value IS NOT NULL THEN to_jsonb('[REDACTED]'::text) ELSE v_new_value END,
          CASE WHEN v_old_value IS NULL THEN NULL ELSE encode(digest(v_old_value::text, 'sha256'), 'hex') END,
          CASE WHEN v_new_value IS NULL THEN NULL ELSE encode(digest(v_new_value::text, 'sha256'), 'hex') END,
          v_redact,
          v_sensitive,
          CASE WHEN v_redact THEN 'secret' WHEN v_sensitive THEN v_policy."AuditPolicy_SensitivityCode" ELSE 'normal' END
        );

      v_changed_count := v_changed_count + 1;
    END LOOP;
  END IF;

  UPDATE public."Audit_Events"
  SET "AuditEvent_ChangedFieldCount" = v_changed_count
  WHERE "AuditEvent_ID" = v_event_id;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  IF coalesce(v_policy."AuditPolicy_FailClosed", true) THEN
    RAISE;
  END IF;
  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$_$;


ALTER FUNCTION "public"."Audit_RowChangeTrigger"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."Audit_SetContext"("p_user_id" "uuid" DEFAULT NULL::"uuid", "p_auth_user_id" "uuid" DEFAULT NULL::"uuid", "p_actor_type_code" character varying DEFAULT 'user'::character varying, "p_request_id" character varying DEFAULT NULL::character varying, "p_session_id" character varying DEFAULT NULL::character varying, "p_correlation_id" character varying DEFAULT NULL::character varying, "p_org_office_id" "uuid" DEFAULT NULL::"uuid", "p_legal_entity_id" "uuid" DEFAULT NULL::"uuid", "p_brand_id" "uuid" DEFAULT NULL::"uuid", "p_source_app" character varying DEFAULT NULL::character varying, "p_source_module" character varying DEFAULT NULL::character varying, "p_client_version" character varying DEFAULT NULL::character varying, "p_ip_hash" character varying DEFAULT NULL::character varying, "p_user_agent" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_request_context_id uuid;
BEGIN
  PERFORM set_config('app.user_id', coalesce(p_user_id::text, ''), true);
  PERFORM set_config('app.auth_user_id', coalesce(p_auth_user_id::text, ''), true);
  PERFORM set_config('app.actor_type', coalesce(p_actor_type_code, 'user'), true);
  PERFORM set_config('app.request_id', coalesce(p_request_id, ''), true);
  PERFORM set_config('app.session_id', coalesce(p_session_id, ''), true);
  PERFORM set_config('app.correlation_id', coalesce(p_correlation_id, ''), true);
  PERFORM set_config('app.org_office_id', coalesce(p_org_office_id::text, ''), true);
  PERFORM set_config('app.legal_entity_id', coalesce(p_legal_entity_id::text, ''), true);
  PERFORM set_config('app.brand_id', coalesce(p_brand_id::text, ''), true);
  PERFORM set_config('app.source_app', coalesce(p_source_app, ''), true);
  PERFORM set_config('app.source_module', coalesce(p_source_module, ''), true);
  PERFORM set_config('app.client_version', coalesce(p_client_version, ''), true);
  PERFORM set_config('app.ip_hash', coalesce(p_ip_hash, ''), true);
  PERFORM set_config('app.user_agent', coalesce(p_user_agent, ''), true);

  IF p_request_id IS NOT NULL THEN
    INSERT INTO public."Audit_RequestContexts"
      (
        "AuditRequest_RequestID",
        "AuditRequest_SessionID",
        "AuditRequest_CorrelationID",
        "AuditRequest_ActorTypeCode",
        "AuditRequest_UserID",
        "AuditRequest_AuthUserID",
        "AuditRequest_OrgOfficeID",
        "AuditRequest_LegalEntityID",
        "AuditRequest_BrandID",
        "AuditRequest_SourceApp",
        "AuditRequest_SourceModule",
        "AuditRequest_ClientVersion",
        "AuditRequest_IPHash",
        "AuditRequest_UserAgent"
      )
    VALUES
      (
        p_request_id,
        p_session_id,
        p_correlation_id,
        coalesce(p_actor_type_code, 'user'),
        p_user_id,
        p_auth_user_id,
        p_org_office_id,
        p_legal_entity_id,
        p_brand_id,
        p_source_app,
        p_source_module,
        p_client_version,
        p_ip_hash,
        p_user_agent
      )
    ON CONFLICT ("AuditRequest_RequestID") DO UPDATE SET
      "AuditRequest_SessionID" = EXCLUDED."AuditRequest_SessionID",
      "AuditRequest_CorrelationID" = EXCLUDED."AuditRequest_CorrelationID",
      "AuditRequest_ActorTypeCode" = EXCLUDED."AuditRequest_ActorTypeCode",
      "AuditRequest_UserID" = EXCLUDED."AuditRequest_UserID",
      "AuditRequest_AuthUserID" = EXCLUDED."AuditRequest_AuthUserID",
      "AuditRequest_OrgOfficeID" = EXCLUDED."AuditRequest_OrgOfficeID",
      "AuditRequest_LegalEntityID" = EXCLUDED."AuditRequest_LegalEntityID",
      "AuditRequest_BrandID" = EXCLUDED."AuditRequest_BrandID",
      "AuditRequest_SourceApp" = EXCLUDED."AuditRequest_SourceApp",
      "AuditRequest_SourceModule" = EXCLUDED."AuditRequest_SourceModule",
      "AuditRequest_ClientVersion" = EXCLUDED."AuditRequest_ClientVersion",
      "AuditRequest_IPHash" = EXCLUDED."AuditRequest_IPHash",
      "AuditRequest_UserAgent" = EXCLUDED."AuditRequest_UserAgent"
    RETURNING "AuditRequest_ID" INTO v_request_context_id;
  END IF;

  RETURN v_request_context_id;
END;
$$;


ALTER FUNCTION "public"."Audit_SetContext"("p_user_id" "uuid", "p_auth_user_id" "uuid", "p_actor_type_code" character varying, "p_request_id" character varying, "p_session_id" character varying, "p_correlation_id" character varying, "p_org_office_id" "uuid", "p_legal_entity_id" "uuid", "p_brand_id" "uuid", "p_source_app" character varying, "p_source_module" character varying, "p_client_version" character varying, "p_ip_hash" character varying, "p_user_agent" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."CLM_AddClaimEvent"("p_claim_id" "uuid", "p_event_type_code" character varying, "p_title" character varying, "p_details" "text" DEFAULT NULL::"text", "p_status_to_code" character varying DEFAULT NULL::character varying, "p_actor_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_event_id uuid;
  v_status_from varchar(60);
BEGIN
  SELECT "CLMClaim_StatusCode"
  INTO v_status_from
  FROM public."CLM_Claims"
  WHERE "CLMClaim_ID" = p_claim_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Claim % not found', p_claim_id;
  END IF;

  INSERT INTO public."CLM_ClaimEvents" (
    "CLMEvent_ClaimID",
    "CLMEvent_EventTypeCode",
    "CLMEvent_StatusFromCode",
    "CLMEvent_StatusToCode",
    "CLMEvent_Title",
    "CLMEvent_Details",
    "CLMEvent_ActorUserID"
  )
  VALUES (
    p_claim_id,
    p_event_type_code,
    v_status_from,
    p_status_to_code,
    p_title,
    p_details,
    p_actor_user_id
  )
  RETURNING "CLMEvent_ID" INTO v_event_id;

  IF p_status_to_code IS NOT NULL AND p_status_to_code <> v_status_from THEN
    UPDATE public."CLM_Claims"
    SET
      "CLMClaim_StatusCode" = p_status_to_code,
      "CLMClaim_SubmittedAt" = CASE WHEN p_status_to_code = 'submitted' THEN COALESCE("CLMClaim_SubmittedAt", now()) ELSE "CLMClaim_SubmittedAt" END,
      "CLMClaim_AcknowledgedAt" = CASE WHEN p_status_to_code = 'acknowledged' THEN COALESCE("CLMClaim_AcknowledgedAt", now()) ELSE "CLMClaim_AcknowledgedAt" END,
      "CLMClaim_SettledAt" = CASE WHEN p_status_to_code = 'settled' THEN COALESCE("CLMClaim_SettledAt", now()) ELSE "CLMClaim_SettledAt" END,
      "CLMClaim_ClosedAt" = CASE WHEN p_status_to_code IN ('closed', 'cancelled', 'rejected') THEN COALESCE("CLMClaim_ClosedAt", now()) ELSE "CLMClaim_ClosedAt" END,
      "CLMClaim_UpdatedAt" = now(),
      "CLMClaim_UpdatedBy" = p_actor_user_id
    WHERE "CLMClaim_ID" = p_claim_id;
  END IF;

  RETURN v_event_id;
END;
$$;


ALTER FUNCTION "public"."CLM_AddClaimEvent"("p_claim_id" "uuid", "p_event_type_code" character varying, "p_title" character varying, "p_details" "text", "p_status_to_code" character varying, "p_actor_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."CLM_AddReserveMovement"("p_claim_id" "uuid", "p_reserve_type_code" character varying, "p_new_amount" numeric, "p_currency_code" character varying DEFAULT NULL::character varying, "p_reason" "text" DEFAULT NULL::"text", "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_reserve_id uuid;
  v_previous_amount numeric(18,4);
  v_currency varchar(3);
  v_total_reserve numeric(18,4);
  v_expense_reserve numeric(18,4);
  v_recovery_expected numeric(18,4);
BEGIN
  SELECT COALESCE(p_currency_code, "CLMClaim_CurrencyCodeSnapshot")
  INTO v_currency
  FROM public."CLM_Claims"
  WHERE "CLMClaim_ID" = p_claim_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Claim % not found', p_claim_id;
  END IF;

  SELECT COALESCE("CLMReserve_NewAmount", 0)
  INTO v_previous_amount
  FROM public."CLM_ClaimReserves"
  WHERE "CLMReserve_ClaimID" = p_claim_id
    AND "CLMReserve_TypeCode" = p_reserve_type_code
  ORDER BY "CLMReserve_CreatedAt" DESC
  LIMIT 1;

  v_previous_amount := COALESCE(v_previous_amount, 0);

  INSERT INTO public."CLM_ClaimReserves" (
    "CLMReserve_ClaimID",
    "CLMReserve_TypeCode",
    "CLMReserve_PreviousAmount",
    "CLMReserve_NewAmount",
    "CLMReserve_DeltaAmount",
    "CLMReserve_CurrencyCodeSnapshot",
    "CLMReserve_Reason",
    "CLMReserve_CreatedBy"
  )
  VALUES (
    p_claim_id,
    p_reserve_type_code,
    v_previous_amount,
    COALESCE(p_new_amount, 0),
    COALESCE(p_new_amount, 0) - v_previous_amount,
    COALESCE(v_currency, 'GBP'),
    p_reason,
    p_created_by
  )
  RETURNING "CLMReserve_ID" INTO v_reserve_id;

  WITH latest AS (
    SELECT DISTINCT ON ("CLMReserve_TypeCode")
      "CLMReserve_TypeCode",
      "CLMReserve_NewAmount"
    FROM public."CLM_ClaimReserves"
    WHERE "CLMReserve_ClaimID" = p_claim_id
    ORDER BY "CLMReserve_TypeCode", "CLMReserve_CreatedAt" DESC
  )
  SELECT
    COALESCE(SUM("CLMReserve_NewAmount") FILTER (WHERE "CLMReserve_TypeCode" IN ('indemnity', 'deductible', 'legal', 'other')), 0),
    COALESCE(SUM("CLMReserve_NewAmount") FILTER (WHERE "CLMReserve_TypeCode" = 'expense'), 0),
    COALESCE(SUM("CLMReserve_NewAmount") FILTER (WHERE "CLMReserve_TypeCode" = 'recovery'), 0)
  INTO v_total_reserve, v_expense_reserve, v_recovery_expected
  FROM latest;

  UPDATE public."CLM_Claims"
  SET
    "CLMClaim_ReserveAmount" = v_total_reserve,
    "CLMClaim_ExpenseReserveAmount" = v_expense_reserve,
    "CLMClaim_RecoveryExpectedAmount" = v_recovery_expected,
    "CLMClaim_UpdatedAt" = now(),
    "CLMClaim_UpdatedBy" = p_created_by
  WHERE "CLMClaim_ID" = p_claim_id;

  PERFORM public."CLM_AddClaimEvent"(
    p_claim_id,
    'reserve_changed',
    'Reserve changed',
    p_reason,
    NULL,
    p_created_by
  );

  RETURN v_reserve_id;
END;
$$;


ALTER FUNCTION "public"."CLM_AddReserveMovement"("p_claim_id" "uuid", "p_reserve_type_code" character varying, "p_new_amount" numeric, "p_currency_code" character varying, "p_reason" "text", "p_created_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."CLM_CreateIncident"("p_job_id" "uuid", "p_incident_type_code" character varying, "p_severity_code" character varying, "p_title" character varying, "p_description" "text" DEFAULT NULL::"text", "p_occurred_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_reported_by" "uuid" DEFAULT NULL::"uuid", "p_org_office_id" "uuid" DEFAULT NULL::"uuid", "p_customer_org_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_incident_id uuid;
  v_number varchar(80);
  v_job_office_id uuid;
  v_job_customer_id uuid;
BEGIN
  IF p_job_id IS NOT NULL THEN
    SELECT "Job_OrgOfficeID", "Job_Customer"
    INTO v_job_office_id, v_job_customer_id
    FROM public."Job_Header"
    WHERE "Job_ID" = p_job_id;
  END IF;

  v_number := 'CLM-INC-' || to_char(now(), 'YYYYMMDD-HH24MISS') || '-' || upper(substr(gen_random_uuid()::text, 1, 8));

  INSERT INTO public."CLM_Incidents" (
    "CLMIncident_Number",
    "CLMIncident_JobID",
    "CLMIncident_OrgOfficeID",
    "CLMIncident_CustomerOrgID",
    "CLMIncident_TypeCode",
    "CLMIncident_StatusCode",
    "CLMIncident_SeverityCode",
    "CLMIncident_Title",
    "CLMIncident_Description",
    "CLMIncident_OccurredAt",
    "CLMIncident_OwnerUserID",
    "CLMIncident_CreatedBy"
  )
  VALUES (
    v_number,
    p_job_id,
    COALESCE(p_org_office_id, v_job_office_id),
    COALESCE(p_customer_org_id, v_job_customer_id),
    p_incident_type_code,
    'reported',
    COALESCE(p_severity_code, 'medium'),
    p_title,
    p_description,
    p_occurred_at,
    p_reported_by,
    p_reported_by
  )
  RETURNING "CLMIncident_ID" INTO v_incident_id;

  RETURN v_incident_id;
END;
$$;


ALTER FUNCTION "public"."CLM_CreateIncident"("p_job_id" "uuid", "p_incident_type_code" character varying, "p_severity_code" character varying, "p_title" character varying, "p_description" "text", "p_occurred_at" timestamp with time zone, "p_reported_by" "uuid", "p_org_office_id" "uuid", "p_customer_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."CLM_LinkClaimFinancialDocument"("p_claim_id" "uuid", "p_fin_document_id" "uuid", "p_link_type_code" character varying, "p_amount" numeric DEFAULT 0, "p_currency_code" character varying DEFAULT 'GBP'::character varying, "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
