ALTER FUNCTION "public"."CLM_LinkClaimFinancialDocument"("p_claim_id" "uuid", "p_fin_document_id" "uuid", "p_link_type_code" character varying, "p_amount" numeric, "p_currency_code" character varying, "p_created_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."CLM_OpenClaimFromIncident"("p_incident_id" "uuid", "p_policy_id" "uuid" DEFAULT NULL::"uuid", "p_claim_type_code" character varying DEFAULT 'cargo_damage'::character varying, "p_claimed_amount" numeric DEFAULT 0, "p_currency_code" character varying DEFAULT 'GBP'::character varying, "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_claim_id uuid;
  v_number varchar(80);
  v_incident public."CLM_Incidents"%ROWTYPE;
BEGIN
  SELECT *
  INTO v_incident
  FROM public."CLM_Incidents"
  WHERE "CLMIncident_ID" = p_incident_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Incident % not found', p_incident_id;
  END IF;

  v_number := 'CLM-CLAIM-' || to_char(now(), 'YYYYMMDD-HH24MISS') || '-' || upper(substr(gen_random_uuid()::text, 1, 8));

  INSERT INTO public."CLM_Claims" (
    "CLMClaim_Number",
    "CLMClaim_IncidentID",
    "CLMClaim_PolicyID",
    "CLMClaim_JobID",
    "CLMClaim_JobRouteID",
    "CLMClaim_JobCargoID",
    "CLMClaim_JobContainerID",
    "CLMClaim_OrgOfficeID",
    "CLMClaim_LegalEntityID",
    "CLMClaim_BrandID",
    "CLMClaim_CustomerOrgID",
    "CLMClaim_TypeCode",
    "CLMClaim_StatusCode",
    "CLMClaim_Title",
    "CLMClaim_ClaimantOrgID",
    "CLMClaim_CurrencyCodeSnapshot",
    "CLMClaim_ClaimedAmount",
    "CLMClaim_LocalClaimedAmount",
    "CLMClaim_LossDescription",
    "CLMClaim_OwnerUserID",
    "CLMClaim_CreatedBy"
  )
  VALUES (
    v_number,
    p_incident_id,
    p_policy_id,
    v_incident."CLMIncident_JobID",
    v_incident."CLMIncident_JobRouteID",
    v_incident."CLMIncident_JobCargoID",
    v_incident."CLMIncident_JobContainerID",
    v_incident."CLMIncident_OrgOfficeID",
    v_incident."CLMIncident_LegalEntityID",
    v_incident."CLMIncident_BrandID",
    v_incident."CLMIncident_CustomerOrgID",
    p_claim_type_code,
    'draft',
    v_incident."CLMIncident_Title",
    v_incident."CLMIncident_CustomerOrgID",
    COALESCE(p_currency_code, v_incident."CLMIncident_CurrencyCodeSnapshot", 'GBP'),
    COALESCE(p_claimed_amount, 0),
    COALESCE(p_claimed_amount, 0),
    v_incident."CLMIncident_Description",
    COALESCE(p_created_by, v_incident."CLMIncident_OwnerUserID"),
    p_created_by
  )
  RETURNING "CLMClaim_ID" INTO v_claim_id;

  UPDATE public."CLM_Incidents"
  SET
    "CLMIncident_StatusCode" = 'claim_opened',
    "CLMIncident_HasClaim" = true,
    "CLMIncident_UpdatedAt" = now(),
    "CLMIncident_UpdatedBy" = p_created_by
  WHERE "CLMIncident_ID" = p_incident_id;

  PERFORM public."CLM_AddClaimEvent"(
    v_claim_id,
    'created',
    'Claim opened from incident',
    'Claim opened from incident ' || v_incident."CLMIncident_Number",
    NULL,
    p_created_by
  );

  RETURN v_claim_id;
END;
$$;


ALTER FUNCTION "public"."CLM_OpenClaimFromIncident"("p_incident_id" "uuid", "p_policy_id" "uuid", "p_claim_type_code" character varying, "p_claimed_amount" numeric, "p_currency_code" character varying, "p_created_by" "uuid") OWNER TO "postgres";


