CREATE OR REPLACE FUNCTION "public"."CMP_ConfigureScreeningListWorkerSchedule"() RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_endpoint text;
begin
  select decrypted_secret
  into v_endpoint
  from vault.decrypted_secrets
  where name = 'multideck_screening_list_worker_endpoint'
  limit 1;

  if nullif(btrim(v_endpoint), '') is null then
    return false;
  end if;

  perform cron.schedule(
    'multideck-screening-list-worker',
    '20 6,18 * * *',
    format(
      $command$
        select net.http_post(
          url := %L,
          headers := jsonb_build_object(
            'Content-Type', 'application/json',
            'x-multideck-screening-list-secret', (
              select decrypted_secret
              from vault.decrypted_secrets
              where name = 'multideck_screening_list_worker_secret'
              limit 1
            )
          ),
          body := jsonb_build_object('source', 'cron', 'requestedAt', now()),
          timeout_milliseconds := 120000
        );
      $command$,
      btrim(v_endpoint)
    )
  );

  return true;
end;
$_$;


ALTER FUNCTION "public"."CMP_ConfigureScreeningListWorkerSchedule"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."CMP_GetScreeningListWorkerSecret"() RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'vault'
    AS $$
  select decrypted_secret
  from vault.decrypted_secrets
  where name = 'multideck_screening_list_worker_secret'
  limit 1;
$$;


ALTER FUNCTION "public"."CMP_GetScreeningListWorkerSecret"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."CRM_AcceptCallActionCandidate"("p_candidate_id" "uuid", "p_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_candidate record;
  v_review record;
  v_task_id uuid;
BEGIN
  SELECT * INTO v_candidate
  FROM public."CRM_CallActionCandidates"
  WHERE "CRMCallAction_ID" = p_candidate_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Call action candidate % was not found.', p_candidate_id;
  END IF;

  SELECT * INTO v_review
  FROM public."CRM_CallReviews"
  WHERE "CRMCallReview_ID" = v_candidate."CRMCallAction_CallReviewID";

  INSERT INTO public."Workflow_Tasks" (
    "WorkflowTask_Title",
    "WorkflowTask_Description",
    "WorkflowTask_TypeCode",
    "WorkflowTask_StatusCode",
    "WorkflowTask_PriorityCode",
    "WorkflowTask_RecordTypeCode",
    "WorkflowTask_RecordID",
    "WorkflowTask_AssignedUserID",
    "WorkflowTask_DueAt",
    "WorkflowTask_IsSystemGenerated",
    "WorkflowTask_ContextJSON",
    "WorkflowTask_CreatedBy"
  )
  VALUES (
    v_candidate."CRMCallAction_Title",
    v_candidate."CRMCallAction_Description",
    'customer_update',
    'ready',
    'normal',
    'crm_call_review',
    v_candidate."CRMCallAction_CallReviewID",
    COALESCE(v_candidate."CRMCallAction_SuggestedOwnerUserID", v_review."CRMCallReview_OwnerUserID", p_user_id),
    v_candidate."CRMCallAction_SuggestedDueAt",
    true,
    jsonb_build_object('source', 'CRM_CallActionCandidates', 'candidate_id', p_candidate_id),
    p_user_id
  )
  RETURNING "WorkflowTask_ID" INTO v_task_id;

  UPDATE public."CRM_CallActionCandidates"
  SET "CRMCallAction_DecisionStatus" = 'accepted',
      "CRMCallAction_WorkflowTaskID" = v_task_id,
      "CRMCallAction_DecidedAt" = now(),
      "CRMCallAction_DecidedBy" = p_user_id
  WHERE "CRMCallAction_ID" = p_candidate_id;

  INSERT INTO public."CRM_CallReviewDecisions" (
    "CRMCallDecision_CallReviewID",
    "CRMCallDecision_ActionCandidateID",
    "CRMCallDecision_Decision",
    "CRMCallDecision_OriginalText",
    "CRMCallDecision_DecidedBy"
  )
  VALUES (
    v_candidate."CRMCallAction_CallReviewID",
    p_candidate_id,
    'accepted',
    v_candidate."CRMCallAction_Description",
    p_user_id
  );

  RETURN v_task_id;
END;
$$;


ALTER FUNCTION "public"."CRM_AcceptCallActionCandidate"("p_candidate_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."CRM_ApplyFieldUpdate"("p_field_update_id" "uuid", "p_user_id" "uuid" DEFAULT NULL::"uuid", "p_force" boolean DEFAULT false) RETURNS boolean
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  v_update record;
  v_cast_type text;
  v_old_value text;
  v_row_count integer;
  v_sql text;
BEGIN
  SELECT *
  INTO v_update
  FROM public."CRM_FieldUpdateQueue"
  WHERE "CRMFieldUpdate_ID" = p_field_update_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'CRM field update % was not found.', p_field_update_id;
  END IF;

  IF NOT p_force AND v_update."CRMFieldUpdate_StatusCode" NOT IN ('ready', 'approved', 'needs_review', 'pending') THEN
    RAISE EXCEPTION 'CRM field update % is not in an applyable status (%).', p_field_update_id, v_update."CRMFieldUpdate_StatusCode";
  END IF;

  IF to_regclass(format('public.%I', v_update."CRMFieldUpdate_TargetTable")) IS NULL THEN
    RAISE EXCEPTION 'Target table public.% does not exist.', v_update."CRMFieldUpdate_TargetTable";
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM information_schema.columns
    WHERE table_schema = 'public'
      AND table_name = v_update."CRMFieldUpdate_TargetTable"
      AND column_name = v_update."CRMFieldUpdate_TargetPKColumn"
  ) THEN
    RAISE EXCEPTION 'Target primary key column public.%.% does not exist.', v_update."CRMFieldUpdate_TargetTable", v_update."CRMFieldUpdate_TargetPKColumn";
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM information_schema.columns
    WHERE table_schema = 'public'
      AND table_name = v_update."CRMFieldUpdate_TargetTable"
      AND column_name = v_update."CRMFieldUpdate_TargetColumn"
  ) THEN
    RAISE EXCEPTION 'Target update column public.%.% does not exist.', v_update."CRMFieldUpdate_TargetTable", v_update."CRMFieldUpdate_TargetColumn";
  END IF;

  SELECT COALESCE("CRMDataFieldType_PostgresCastType", 'text')
  INTO v_cast_type
  FROM public."sys_CRMDataFieldTypes"
  WHERE "CRMDataFieldType_Code" = v_update."CRMFieldUpdate_FieldTypeCode";

  EXECUTE format(
    'select %I::text from public.%I where %I = $1',
    v_update."CRMFieldUpdate_TargetColumn",
    v_update."CRMFieldUpdate_TargetTable",
    v_update."CRMFieldUpdate_TargetPKColumn"
  )
  USING v_update."CRMFieldUpdate_TargetID"
  INTO v_old_value;

  IF v_update."CRMFieldUpdate_FieldTypeCode" = 'json' THEN
    v_sql := format(
      'update public.%I set %I = $1::jsonb where %I = $2',
      v_update."CRMFieldUpdate_TargetTable",
      v_update."CRMFieldUpdate_TargetColumn",
      v_update."CRMFieldUpdate_TargetPKColumn"
    );
    EXECUTE v_sql USING v_update."CRMFieldUpdate_NewValueJSON", v_update."CRMFieldUpdate_TargetID";
  ELSE
    v_sql := format(
      'update public.%I set %I = $1::%s where %I = $2',
      v_update."CRMFieldUpdate_TargetTable",
      v_update."CRMFieldUpdate_TargetColumn",
      v_cast_type,
      v_update."CRMFieldUpdate_TargetPKColumn"
    );
    EXECUTE v_sql USING v_update."CRMFieldUpdate_NewValueText", v_update."CRMFieldUpdate_TargetID";
  END IF;

  GET DIAGNOSTICS v_row_count = ROW_COUNT;
  IF v_row_count <> 1 THEN
    RAISE EXCEPTION 'Expected to update one row in public.% for target %, updated % rows.',
      v_update."CRMFieldUpdate_TargetTable",
      v_update."CRMFieldUpdate_TargetID",
      v_row_count;
  END IF;

  UPDATE public."CRM_FieldUpdateQueue"
  SET "CRMFieldUpdate_StatusCode" = 'applied',
      "CRMFieldUpdate_OldValueText" = v_old_value,
      "CRMFieldUpdate_AppliedAt" = now(),
      "CRMFieldUpdate_AppliedBy" = p_user_id,
      "CRMFieldUpdate_ErrorMessage" = NULL
  WHERE "CRMFieldUpdate_ID" = p_field_update_id;

  INSERT INTO public."CRM_FieldUpdateAudit" (
    "CRMFieldAudit_FieldUpdateID",
    "CRMFieldAudit_Action",
    "CRMFieldAudit_FromStatusCode",
    "CRMFieldAudit_ToStatusCode",
    "CRMFieldAudit_OldValueText",
    "CRMFieldAudit_NewValueText",
    "CRMFieldAudit_CreatedBy"
  )
  VALUES (
    p_field_update_id,
    'applied',
    v_update."CRMFieldUpdate_StatusCode",
    'applied',
    v_old_value,
    v_update."CRMFieldUpdate_NewValueText",
    p_user_id
  );

  RETURN true;
EXCEPTION WHEN OTHERS THEN
  UPDATE public."CRM_FieldUpdateQueue"
  SET "CRMFieldUpdate_StatusCode" = 'failed',
      "CRMFieldUpdate_ErrorMessage" = SQLERRM
  WHERE "CRMFieldUpdate_ID" = p_field_update_id;
  RAISE;
END;
$_$;


ALTER FUNCTION "public"."CRM_ApplyFieldUpdate"("p_field_update_id" "uuid", "p_user_id" "uuid", "p_force" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."CRM_ApprovePersonalMessageDraft"("p_draft_id" "uuid", "p_user_id" "uuid" DEFAULT NULL::"uuid", "p_recipient_address" character varying DEFAULT NULL::character varying, "p_queue_for_sending" boolean DEFAULT false) RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_draft record;
  v_send_id uuid;
  v_status varchar(40);
BEGIN
  SELECT *
  INTO v_draft
  FROM public."CRM_PersonalMessageDrafts"
  WHERE "CRMPMsg_ID" = p_draft_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Personal message draft % was not found.', p_draft_id;
  END IF;

  v_status := CASE WHEN p_queue_for_sending THEN 'queued' ELSE 'draft' END;

  INSERT INTO public."Comm_SendRequests" (
    "CommSend_ChannelCode",
    "CommSend_StatusCode",
    "CommSend_SourceTypeCode",
    "CommSend_PriorityCode",
    "CommSend_SensitivityCode",
    "CommSend_RequestedBy",
    "CommSend_ApprovedBy",
    "CommSend_ApprovedAt",
    "CommSend_Subject",
    "CommSend_BodyText",
    "CommSend_BodyHTML",
    "CommSend_PayloadJSON"
  )
  VALUES (
    v_draft."CRMPMsg_ChannelCode",
    v_status,
    'ai',
    'normal',
    'public',
    COALESCE(p_user_id, v_draft."CRMPMsg_AssignedUserID"),
    CASE WHEN p_queue_for_sending THEN COALESCE(p_user_id, v_draft."CRMPMsg_AssignedUserID") ELSE NULL END,
    CASE WHEN p_queue_for_sending THEN now() ELSE NULL END,
    v_draft."CRMPMsg_Subject",
    v_draft."CRMPMsg_BodyText",
    v_draft."CRMPMsg_BodyHTML",
    jsonb_build_object('source', 'CRM_PersonalMessageDrafts', 'draft_id', p_draft_id, 'intent', v_draft."CRMPMsg_MessageIntentCode")
  )
  RETURNING "CommSend_ID" INTO v_send_id;

  IF p_recipient_address IS NOT NULL THEN
    INSERT INTO public."Comm_SendRequestRecipients" (
      "CommSendRecipient_SendID",
      "CommSendRecipient_RecipientTypeCode",
      "CommSendRecipient_ChannelCode",
      "CommSendRecipient_Address",
      "CommSendRecipient_NormalizedAddress",
      "CommSendRecipient_OrgID",
      "CommSendRecipient_ContactID"
    )
    VALUES (
      v_send_id,
      'to',
      v_draft."CRMPMsg_ChannelCode",
      p_recipient_address,
      lower(p_recipient_address),
      v_draft."CRMPMsg_CustomerOrgID",
      v_draft."CRMPMsg_ContactID"
    );
  END IF;

  UPDATE public."CRM_PersonalMessageDrafts"
  SET "CRMPMsg_CommSendID" = v_send_id,
      "CRMPMsg_DecisionStatusCode" = CASE WHEN p_queue_for_sending THEN 'sent' ELSE 'accepted' END,
      "CRMPMsg_IsApprovedForSend" = p_queue_for_sending,
      "CRMPMsg_DecidedAt" = now(),
      "CRMPMsg_DecidedBy" = p_user_id,
      "CRMPMsg_UpdatedAt" = now(),
      "CRMPMsg_UpdatedBy" = p_user_id
  WHERE "CRMPMsg_ID" = p_draft_id;

  UPDATE public."CRM_MessageVariationHistory"
  SET "CRMPVar_CommSendID" = v_send_id,
      "CRMPVar_WasSent" = p_queue_for_sending,
      "CRMPVar_SentAt" = CASE WHEN p_queue_for_sending THEN now() ELSE NULL END
  WHERE "CRMPVar_MessageDraftID" = p_draft_id;

  RETURN v_send_id;
END;
$$;


ALTER FUNCTION "public"."CRM_ApprovePersonalMessageDraft"("p_draft_id" "uuid", "p_user_id" "uuid", "p_recipient_address" character varying, "p_queue_for_sending" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."CRM_ConvertLeadToOpportunity"("p_lead_id" "uuid", "p_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_lead record;
  v_org_id uuid;
  v_account_id uuid;
  v_opportunity_id uuid;
  v_name varchar(240);
BEGIN
  SELECT * INTO v_lead
  FROM public."CRM_Leads"
  WHERE "CRMLead_ID" = p_lead_id
    AND "CRMLead_IsDeleted" = false;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Lead % was not found.', p_lead_id;
  END IF;

  v_org_id := v_lead."CRMLead_OrgID";
  v_name := COALESCE(NULLIF(v_lead."CRMLead_CompanyName", ''), NULLIF(v_lead."CRMLead_PersonName", ''), 'Converted CRM lead');

  IF v_org_id IS NULL THEN
    INSERT INTO public."Org_Master" (
      "Org_Name",
      "Org_CRMRelationshipStatusCode",
      "Org_CRMIsLead",
      "Org_CRMIsPotentialCustomer"
    )
    VALUES (v_name, 'prospect', true, true)
    RETURNING "Org_ID" INTO v_org_id;

    UPDATE public."CRM_Leads"
    SET "CRMLead_OrgID" = v_org_id,
        "CRMLead_UpdatedAt" = now(),
        "CRMLead_UpdatedBy" = p_user_id
    WHERE "CRMLead_ID" = p_lead_id;
  ELSE
    UPDATE public."Org_Master"
    SET "Org_CRMRelationshipStatusCode" = COALESCE("Org_CRMRelationshipStatusCode", 'prospect'),
        "Org_CRMIsLead" = true,
        "Org_CRMIsPotentialCustomer" = true,
        "Org_CRMUpdatedAt" = now()
    WHERE "Org_ID" = v_org_id;
  END IF;

  INSERT INTO public."CRM_AccountProfiles" (
    "CRMAccount_OrgID",
    "CRMAccount_RelationshipStatusCode",
    "CRMAccount_OwnerUserID",
    "CRMAccount_OrgOfficeID",
    "CRMAccount_LegalEntityID",
    "CRMAccount_BrandID",
    "CRMAccount_PrimaryModeCode",
    "CRMAccount_PrimaryTradeLane",
    "CRMAccount_CustomerCentricSummary",
    "CRMAccount_CreatedBy"
  )
  VALUES (
    v_org_id,
    'prospect',
    COALESCE(v_lead."CRMLead_OwnerUserID", p_user_id),
    v_lead."CRMLead_OrgOfficeID",
    v_lead."CRMLead_LegalEntityID",
    v_lead."CRMLead_BrandID",
    v_lead."CRMLead_ModeCode",
    v_lead."CRMLead_TradeLane",
    v_lead."CRMLead_CustomerCentricNeed",
    p_user_id
  )
  ON CONFLICT ("CRMAccount_OrgID") DO UPDATE
  SET "CRMAccount_RelationshipStatusCode" = excluded."CRMAccount_RelationshipStatusCode",
      "CRMAccount_OwnerUserID" = COALESCE(public."CRM_AccountProfiles"."CRMAccount_OwnerUserID", excluded."CRMAccount_OwnerUserID"),
      "CRMAccount_UpdatedAt" = now(),
      "CRMAccount_UpdatedBy" = p_user_id
  RETURNING "CRMAccount_ID" INTO v_account_id;

  INSERT INTO public."CRM_OrgLifecycleTags" (
    "CRMOrgLifeTag_OrgID",
    "CRMOrgLifeTag_TagCode",
    "CRMOrgLifeTag_SourceTable",
    "CRMOrgLifeTag_SourceID",
    "CRMOrgLifeTag_CreatedBy"
  )
  VALUES
    (v_org_id, 'potential_customer', 'CRM_Leads', p_lead_id, p_user_id),
    (v_org_id, 'prospect', 'CRM_Leads', p_lead_id, p_user_id)
  ON CONFLICT ("CRMOrgLifeTag_OrgID", "CRMOrgLifeTag_TagCode") DO UPDATE
  SET "CRMOrgLifeTag_IsActive" = true;

  INSERT INTO public."CRM_Opportunities" (
    "CRMOppty_AccountID",
    "CRMOppty_OrgID",
    "CRMOppty_PrimaryContactID",
    "CRMOppty_SourceLeadID",
    "CRMOppty_OwnerUserID",
    "CRMOppty_OrgOfficeID",
    "CRMOppty_LegalEntityID",
    "CRMOppty_BrandID",
    "CRMOppty_Name",
    "CRMOppty_ModeCode",
    "CRMOppty_DirectionCode",
    "CRMOppty_TradeLane",
    "CRMOppty_ServiceInterest",
    "CRMOppty_ExpectedValueAmount",
    "CRMOppty_CurrencyCode",
    "CRMOppty_CustomerNeed",
    "CRMOppty_CreatedBy"
  )
  VALUES (
    v_account_id,
    v_org_id,
    v_lead."CRMLead_PrimaryContactID",
    p_lead_id,
    COALESCE(v_lead."CRMLead_OwnerUserID", p_user_id),
    v_lead."CRMLead_OrgOfficeID",
    v_lead."CRMLead_LegalEntityID",
    v_lead."CRMLead_BrandID",
    v_name || ' opportunity',
    v_lead."CRMLead_ModeCode",
    v_lead."CRMLead_DirectionCode",
    v_lead."CRMLead_TradeLane",
    v_lead."CRMLead_ServiceInterest",
    v_lead."CRMLead_EstimatedValueAmount",
    v_lead."CRMLead_EstimatedValueCurrencyCode",
    v_lead."CRMLead_CustomerCentricNeed",
    p_user_id
  )
  RETURNING "CRMOppty_ID" INTO v_opportunity_id;

  UPDATE public."CRM_Leads"
  SET "CRMLead_StatusCode" = 'converted',
      "CRMLead_UpdatedAt" = now(),
      "CRMLead_UpdatedBy" = p_user_id
  WHERE "CRMLead_ID" = p_lead_id;

  INSERT INTO public."CRM_LeadStatusHistory" (
    "CRMLeadStatus_LeadID",
    "CRMLeadStatus_ToStatusCode",
    "CRMLeadStatus_Reason",
    "CRMLeadStatus_ChangedBy"
  )
  VALUES (p_lead_id, 'converted', 'Converted to opportunity.', p_user_id);

  INSERT INTO public."CRM_LeadConversions" (
    "CRMLeadConv_LeadID",
    "CRMLeadConv_OrgID",
    "CRMLeadConv_AccountID",
    "CRMLeadConv_OpportunityID",
    "CRMLeadConv_ConvertedBy"
  )
  VALUES (p_lead_id, v_org_id, v_account_id, v_opportunity_id, p_user_id);

  RETURN v_opportunity_id;
END;
$$;


ALTER FUNCTION "public"."CRM_ConvertLeadToOpportunity"("p_lead_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."CRM_CreateDataCaptureSession"("p_run_id" "uuid", "p_assigned_user_id" "uuid" DEFAULT NULL::"uuid", "p_method_code" character varying DEFAULT 'wizard'::character varying) RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_session_id uuid;
BEGIN
  INSERT INTO public."CRM_DataCaptureSessions" (
    "CRMDataCapSession_RunID",
    "CRMDataCapSession_MethodCode",
    "CRMDataCapSession_StatusCode",
    "CRMDataCapSession_AssignedUserID"
  )
  VALUES (p_run_id, p_method_code, 'ready', p_assigned_user_id)
  RETURNING "CRMDataCapSession_ID" INTO v_session_id;

  RETURN v_session_id;
END;
$$;


ALTER FUNCTION "public"."CRM_CreateDataCaptureSession"("p_run_id" "uuid", "p_assigned_user_id" "uuid", "p_method_code" character varying) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."CRM_CreateDataRequestFromRun"("p_run_id" "uuid", "p_request_text" "text", "p_channel_code" character varying DEFAULT 'email'::character varying, "p_assigned_user_id" "uuid" DEFAULT NULL::"uuid", "p_due_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_run record;
  v_request_id uuid;
BEGIN
  SELECT *
  INTO v_run
  FROM public."CRM_AutomationRuns"
  WHERE "CRMAutoRun_ID" = p_run_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Automation run % was not found.', p_run_id;
  END IF;

  INSERT INTO public."CRM_DataRequests" (
    "CRMDataReq_RunID",
    "CRMDataReq_StatusCode",
    "CRMDataReq_MethodCode",
    "CRMDataReq_ChannelCode",
    "CRMDataReq_CustomerOrgID",
    "CRMDataReq_AssignedUserID",
    "CRMDataReq_RequestText",
    "CRMDataReq_DueAt",
    "CRMDataReq_CreatedBy"
  )
  VALUES (
    p_run_id,
    'draft',
    CASE
      WHEN p_channel_code = 'whatsapp' THEN 'whatsapp_reply'
      WHEN p_channel_code = 'sms' THEN 'sms_reply'
      ELSE 'email_reply'
    END,
    p_channel_code,
    v_run."CRMAutoRun_CustomerOrgID",
    COALESCE(p_assigned_user_id, v_run."CRMAutoRun_AssignedUserID"),
    p_request_text,
    p_due_at,
    p_created_by
  )
  RETURNING "CRMDataReq_ID" INTO v_request_id;

  INSERT INTO public."CRM_DataRequestFields" (
    "CRMDataReqField_RequestID",
    "CRMDataReqField_FieldDefID",
    "CRMDataReqField_TargetTable",
    "CRMDataReqField_TargetPKColumn",
    "CRMDataReqField_TargetColumn",
    "CRMDataReqField_TargetID",
    "CRMDataReqField_QuestionText",
    "CRMDataReqField_IsRequired",
    "CRMDataReqField_SortOrder"
  )
  SELECT
    v_request_id,
    field."CRMAutoField_ID",
    field."CRMAutoField_TargetTable",
    field."CRMAutoField_TargetPKColumn",
    field."CRMAutoField_TargetColumn",
    v_run."CRMAutoRun_TargetID",
    field."CRMAutoField_QuestionText",
    field."CRMAutoField_IsRequired",
    field."CRMAutoField_SortOrder"
  FROM public."CRM_AutomationFieldDefinitions" field
  WHERE field."CRMAutoField_PlaybookID" = v_run."CRMAutoRun_PlaybookID"
    AND field."CRMAutoField_IsActive" = true
  ORDER BY field."CRMAutoField_SortOrder";

  UPDATE public."CRM_AutomationRuns"
  SET "CRMAutoRun_StatusCode" = 'waiting_reply'
  WHERE "CRMAutoRun_ID" = p_run_id;

  RETURN v_request_id;
END;
$$;


ALTER FUNCTION "public"."CRM_CreateDataRequestFromRun"("p_run_id" "uuid", "p_request_text" "text", "p_channel_code" character varying, "p_assigned_user_id" "uuid", "p_due_at" timestamp with time zone, "p_created_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."CRM_CreatePersonalMessageDraft"("p_run_id" "uuid", "p_quick_task_id" "uuid", "p_intent_code" character varying, "p_channel_code" character varying, "p_assigned_user_id" "uuid" DEFAULT NULL::"uuid", "p_customer_org_id" "uuid" DEFAULT NULL::"uuid", "p_contact_id" "uuid" DEFAULT NULL::"uuid", "p_subject" character varying DEFAULT NULL::character varying, "p_body_text" "text" DEFAULT NULL::"text", "p_personalisation_prompt" "text" DEFAULT NULL::"text", "p_evidence_json" "jsonb" DEFAULT '{}'::"jsonb", "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_draft_id uuid;
  v_hash varchar(64);
BEGIN
  v_hash := encode(digest(coalesce(p_body_text, ''), 'sha256'), 'hex');

  INSERT INTO public."CRM_PersonalMessageDrafts" (
    "CRMPMsg_RunID",
    "CRMPMsg_QuickTaskID",
    "CRMPMsg_MessageIntentCode",
    "CRMPMsg_ChannelCode",
    "CRMPMsg_PersonalisationModeCode",
    "CRMPMsg_CustomerOrgID",
    "CRMPMsg_ContactID",
    "CRMPMsg_AssignedUserID",
    "CRMPMsg_Subject",
    "CRMPMsg_BodyText",
    "CRMPMsg_PersonalisationPrompt",
    "CRMPMsg_PersonalisationEvidenceJSON",
    "CRMPMsg_BodyHashSHA256",
    "CRMPMsg_IsTemplateBased",
    "CRMPMsg_CreatedBy"
  )
  VALUES (
    p_run_id,
    p_quick_task_id,
    p_intent_code,
    p_channel_code,
    'ai_personal',
    p_customer_org_id,
    p_contact_id,
    p_assigned_user_id,
    p_subject,
    p_body_text,
    p_personalisation_prompt,
    COALESCE(p_evidence_json, '{}'::jsonb),
    v_hash,
    false,
    p_created_by
  )
  RETURNING "CRMPMsg_ID" INTO v_draft_id;

  INSERT INTO public."CRM_MessageVariationHistory" (
    "CRMPVar_MessageDraftID",
    "CRMPVar_CustomerOrgID",
    "CRMPVar_UserID",
    "CRMPVar_MessageIntentCode",
    "CRMPVar_ChannelCode",
    "CRMPVar_BodyHashSHA256",
    "CRMPVar_BodyPreview",
    "CRMPVar_WasSent"
  )
  VALUES (
    v_draft_id,
    p_customer_org_id,
    p_assigned_user_id,
    p_intent_code,
    p_channel_code,
    v_hash,
    left(coalesce(p_body_text, ''), 1000),
    false
  );

  RETURN v_draft_id;
END;
$$;


ALTER FUNCTION "public"."CRM_CreatePersonalMessageDraft"("p_run_id" "uuid", "p_quick_task_id" "uuid", "p_intent_code" character varying, "p_channel_code" character varying, "p_assigned_user_id" "uuid", "p_customer_org_id" "uuid", "p_contact_id" "uuid", "p_subject" character varying, "p_body_text" "text", "p_personalisation_prompt" "text", "p_evidence_json" "jsonb", "p_created_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."CRM_CreateQuickTask"("p_task_type_code" character varying, "p_title" character varying, "p_assigned_user_id" "uuid" DEFAULT NULL::"uuid", "p_description" "text" DEFAULT NULL::"text", "p_priority_code" character varying DEFAULT 'normal'::character varying, "p_due_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_run_id" "uuid" DEFAULT NULL::"uuid", "p_account_id" "uuid" DEFAULT NULL::"uuid", "p_lead_id" "uuid" DEFAULT NULL::"uuid", "p_opportunity_id" "uuid" DEFAULT NULL::"uuid", "p_quote_followup_id" "uuid" DEFAULT NULL::"uuid", "p_call_review_id" "uuid" DEFAULT NULL::"uuid", "p_job_id" "uuid" DEFAULT NULL::"uuid", "p_customer_org_id" "uuid" DEFAULT NULL::"uuid", "p_action_target_table" character varying DEFAULT NULL::character varying, "p_action_target_id" "uuid" DEFAULT NULL::"uuid", "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_quick_task_id uuid;
  v_workflow_task_id uuid;
  v_workflow_task_type varchar(60);
BEGIN
  SELECT COALESCE("CRMQuickTaskType_DefaultWorkflowTaskTypeCode", 'general_task')
  INTO v_workflow_task_type
  FROM public."sys_CRMQuickTaskTypes"
  WHERE "CRMQuickTaskType_Code" = p_task_type_code;

  INSERT INTO public."CRM_QuickTasks" (
    "CRMQuickTask_RunID",
    "CRMQuickTask_TaskTypeCode",
    "CRMQuickTask_AccountID",
    "CRMQuickTask_LeadID",
    "CRMQuickTask_OpportunityID",
    "CRMQuickTask_QuoteFollowupID",
    "CRMQuickTask_CallReviewID",
    "CRMQuickTask_JobID",
    "CRMQuickTask_CustomerOrgID",
    "CRMQuickTask_AssignedUserID",
    "CRMQuickTask_Title",
    "CRMQuickTask_Description",
    "CRMQuickTask_PriorityCode",
    "CRMQuickTask_DueAt",
    "CRMQuickTask_ActionTargetTable",
    "CRMQuickTask_ActionTargetID",
    "CRMQuickTask_CreatedBy"
  )
  VALUES (
    p_run_id,
    p_task_type_code,
    p_account_id,
    p_lead_id,
    p_opportunity_id,
    p_quote_followup_id,
    p_call_review_id,
    p_job_id,
    p_customer_org_id,
    p_assigned_user_id,
    p_title,
    p_description,
    COALESCE(p_priority_code, 'normal'),
    p_due_at,
    p_action_target_table,
    p_action_target_id,
    p_created_by
  )
  RETURNING "CRMQuickTask_ID" INTO v_quick_task_id;

  INSERT INTO public."Workflow_Tasks" (
    "WorkflowTask_Title",
    "WorkflowTask_Description",
    "WorkflowTask_TypeCode",
    "WorkflowTask_StatusCode",
    "WorkflowTask_PriorityCode",
    "WorkflowTask_RecordTypeCode",
    "WorkflowTask_RecordID",
    "WorkflowTask_AssignedUserID",
    "WorkflowTask_DueAt",
    "WorkflowTask_IsSystemGenerated",
    "WorkflowTask_SourceTriggerTypeCode",
    "WorkflowTask_ContextJSON",
    "WorkflowTask_CreatedBy"
  )
  VALUES (
    p_title,
    p_description,
    COALESCE(v_workflow_task_type, 'general_task'),
    'ready',
    COALESCE(p_priority_code, 'normal'),
    'crm_quick_task',
    v_quick_task_id,
    p_assigned_user_id,
    p_due_at,
    true,
    'crm_activity',
    jsonb_build_object(
      'run_id', p_run_id,
      'task_type', p_task_type_code,
      'action_target_table', p_action_target_table,
      'action_target_id', p_action_target_id
    ),
    p_created_by
  )
  RETURNING "WorkflowTask_ID" INTO v_workflow_task_id;

  UPDATE public."CRM_QuickTasks"
  SET "CRMQuickTask_WorkflowTaskID" = v_workflow_task_id
  WHERE "CRMQuickTask_ID" = v_quick_task_id;

  RETURN v_quick_task_id;
END;
$$;


ALTER FUNCTION "public"."CRM_CreateQuickTask"("p_task_type_code" character varying, "p_title" character varying, "p_assigned_user_id" "uuid", "p_description" "text", "p_priority_code" character varying, "p_due_at" timestamp with time zone, "p_run_id" "uuid", "p_account_id" "uuid", "p_lead_id" "uuid", "p_opportunity_id" "uuid", "p_quote_followup_id" "uuid", "p_call_review_id" "uuid", "p_job_id" "uuid", "p_customer_org_id" "uuid", "p_action_target_table" character varying, "p_action_target_id" "uuid", "p_created_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."CRM_CreateQuoteFollowup"("p_cusquote_header_id" "uuid", "p_cusquote_rev_id" "uuid" DEFAULT NULL::"uuid", "p_owner_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_followup_id uuid;
  v_customer_org_id uuid;
  v_customer_contact_id uuid;
  v_due_at timestamptz;
BEGIN
  SELECT
    "CusQuoteHeader_CustomerID",
    "CusQuoteHeader_CustomerContact",
    COALESCE("CusQuoteHeader_Deadline"::timestamptz, now() + interval '24 hours')
  INTO v_customer_org_id, v_customer_contact_id, v_due_at
  FROM public."CusQuote_Header"
  WHERE "CusQuoteHeader_ID" = p_cusquote_header_id;

  IF v_customer_org_id IS NULL THEN
    RAISE EXCEPTION 'Quote header % was not found or has no customer.', p_cusquote_header_id;
  END IF;

  INSERT INTO public."CRM_QuoteFollowups" (
    "CRMQF_CusQuoteHeaderID",
    "CRMQF_CusQuoteRevID",
    "CRMQF_CustomerOrgID",
    "CRMQF_CustomerContactID",
    "CRMQF_OwnerUserID",
    "CRMQF_StatusCode",
    "CRMQF_NextActionDueAt",
    "CRMQF_CreatedBy"
  )
  VALUES (
    p_cusquote_header_id,
    p_cusquote_rev_id,
    v_customer_org_id,
    v_customer_contact_id,
    p_owner_user_id,
    'pending',
    v_due_at,
    p_owner_user_id
  )
  RETURNING "CRMQF_ID" INTO v_followup_id;

  RETURN v_followup_id;
END;
$$;


ALTER FUNCTION "public"."CRM_CreateQuoteFollowup"("p_cusquote_header_id" "uuid", "p_cusquote_rev_id" "uuid", "p_owner_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."CRM_LinkQuoteToOpportunity"("p_opportunity_id" "uuid", "p_quote_header_id" "uuid", "p_quote_rev_id" "uuid" DEFAULT NULL::"uuid", "p_cost_revenue_link_id" "uuid" DEFAULT NULL::"uuid", "p_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
