    INTO v_cost_opt_id, v_revenue_opt_id
    FROM public."CusQuote_CostRevenueLinks"
    WHERE "CQCRL_ID" = p_cost_revenue_link_id;
  END IF;

  INSERT INTO public."CRM_OpportunityQuoteLinks" (
    "CRMOpptyQuote_OpportunityID",
    "CRMOpptyQuote_CusQuoteHeaderID",
