ALTER FUNCTION "public"."CRM_LinkQuoteToOpportunity"("p_opportunity_id" "uuid", "p_quote_header_id" "uuid", "p_quote_rev_id" "uuid", "p_cost_revenue_link_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."CRM_QueueFieldUpdate"("p_run_id" "uuid", "p_field_def_id" "uuid", "p_target_id" "uuid", "p_value_text" "text" DEFAULT NULL::"text", "p_value_json" "jsonb" DEFAULT NULL::"jsonb", "p_confidence_score" numeric DEFAULT NULL::numeric, "p_reason" "text" DEFAULT NULL::"text", "p_created_by" "uuid" DEFAULT NULL::"uuid", "p_data_request_id" "uuid" DEFAULT NULL::"uuid", "p_data_request_field_id" "uuid" DEFAULT NULL::"uuid", "p_capture_response_id" "uuid" DEFAULT NULL::"uuid", "p_response_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_field record;
  v_update_id uuid;
  v_status varchar(60);
BEGIN
  SELECT *
  INTO v_field
  FROM public."CRM_AutomationFieldDefinitions"
  WHERE "CRMAutoField_ID" = p_field_def_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Automation field definition % was not found.', p_field_def_id;
  END IF;

  v_status := CASE WHEN v_field."CRMAutoField_AutoApplyAllowed" THEN 'ready' ELSE 'needs_review' END;

  INSERT INTO public."CRM_FieldUpdateQueue" (
    "CRMFieldUpdate_RunID",
    "CRMFieldUpdate_DataRequestID",
    "CRMFieldUpdate_DataRequestFieldID",
    "CRMFieldUpdate_CaptureResponseID",
    "CRMFieldUpdate_ResponseID",
    "CRMFieldUpdate_FieldDefID",
    "CRMFieldUpdate_StatusCode",
    "CRMFieldUpdate_TargetRecordTypeCode",
    "CRMFieldUpdate_TargetTable",
    "CRMFieldUpdate_TargetPKColumn",
    "CRMFieldUpdate_TargetColumn",
    "CRMFieldUpdate_TargetID",
    "CRMFieldUpdate_FieldTypeCode",
    "CRMFieldUpdate_NewValueText",
    "CRMFieldUpdate_NewValueJSON",
    "CRMFieldUpdate_ConfidenceScore",
    "CRMFieldUpdate_RequiresApproval",
    "CRMFieldUpdate_Reason",
    "CRMFieldUpdate_CreatedBy"
  )
  VALUES (
    p_run_id,
    p_data_request_id,
    p_data_request_field_id,
    p_capture_response_id,
    p_response_id,
    p_field_def_id,
    v_status,
    v_field."CRMAutoField_TargetRecordTypeCode",
    v_field."CRMAutoField_TargetTable",
    v_field."CRMAutoField_TargetPKColumn",
    v_field."CRMAutoField_TargetColumn",
    p_target_id,
    v_field."CRMAutoField_FieldTypeCode",
    p_value_text,
    p_value_json,
    p_confidence_score,
    NOT v_field."CRMAutoField_AutoApplyAllowed",
    p_reason,
    p_created_by
  )
  RETURNING "CRMFieldUpdate_ID" INTO v_update_id;

  RETURN v_update_id;
END;
$$;


ALTER FUNCTION "public"."CRM_QueueFieldUpdate"("p_run_id" "uuid", "p_field_def_id" "uuid", "p_target_id" "uuid", "p_value_text" "text", "p_value_json" "jsonb", "p_confidence_score" numeric, "p_reason" "text", "p_created_by" "uuid", "p_data_request_id" "uuid", "p_data_request_field_id" "uuid", "p_capture_response_id" "uuid", "p_response_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."CRM_RecordActivity"("p_activity_type_code" character varying, "p_subject" character varying, "p_account_id" "uuid" DEFAULT NULL::"uuid", "p_lead_id" "uuid" DEFAULT NULL::"uuid", "p_opportunity_id" "uuid" DEFAULT NULL::"uuid", "p_quote_followup_id" "uuid" DEFAULT NULL::"uuid", "p_summary" "text" DEFAULT NULL::"text", "p_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_activity_id uuid;
BEGIN
  INSERT INTO public."CRM_Activities" (
    "CRMActivity_ActivityTypeCode",
    "CRMActivity_AccountID",
    "CRMActivity_LeadID",
    "CRMActivity_OpportunityID",
    "CRMActivity_QuoteFollowupID",
    "CRMActivity_Subject",
    "CRMActivity_Summary",
    "CRMActivity_OwnerUserID",
    "CRMActivity_CreatedBy"
  )
  VALUES (
    p_activity_type_code,
    p_account_id,
    p_lead_id,
    p_opportunity_id,
    p_quote_followup_id,
    p_subject,
    p_summary,
    p_user_id,
    p_user_id
  )
  RETURNING "CRMActivity_ID" INTO v_activity_id;

  IF p_lead_id IS NOT NULL THEN
    UPDATE public."CRM_Leads"
    SET "CRMLead_LastInteractionAt" = now(),
        "CRMLead_UpdatedAt" = now(),
        "CRMLead_UpdatedBy" = p_user_id
    WHERE "CRMLead_ID" = p_lead_id;
  END IF;

  IF p_opportunity_id IS NOT NULL THEN
    UPDATE public."CRM_Opportunities"
    SET "CRMOppty_LastActivityAt" = now(),
        "CRMOppty_UpdatedAt" = now(),
        "CRMOppty_UpdatedBy" = p_user_id
    WHERE "CRMOppty_ID" = p_opportunity_id;
  END IF;

  RETURN v_activity_id;
END;
$$;


ALTER FUNCTION "public"."CRM_RecordActivity"("p_activity_type_code" character varying, "p_subject" character varying, "p_account_id" "uuid", "p_lead_id" "uuid", "p_opportunity_id" "uuid", "p_quote_followup_id" "uuid", "p_summary" "text", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."CRM_RecordDataRequestFieldValue"("p_request_field_id" "uuid", "p_value_text" "text" DEFAULT NULL::"text", "p_value_json" "jsonb" DEFAULT NULL::"jsonb", "p_method_code" character varying DEFAULT 'email_reply'::character varying, "p_raw_text" "text" DEFAULT NULL::"text", "p_confidence_score" numeric DEFAULT NULL::numeric, "p_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_field record;
  v_request record;
  v_response_id uuid;
  v_update_id uuid;
BEGIN
  SELECT rf.*, fd."CRMAutoField_ID"
  INTO v_field
  FROM public."CRM_DataRequestFields" rf
  JOIN public."CRM_AutomationFieldDefinitions" fd ON fd."CRMAutoField_ID" = rf."CRMDataReqField_FieldDefID"
  WHERE rf."CRMDataReqField_ID" = p_request_field_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Data request field % was not found.', p_request_field_id;
  END IF;

  SELECT *
  INTO v_request
  FROM public."CRM_DataRequests"
  WHERE "CRMDataReq_ID" = v_field."CRMDataReqField_RequestID";

  INSERT INTO public."CRM_DataRequestResponses" (
    "CRMDataReqResp_RequestID",
    "CRMDataReqResp_MethodCode",
    "CRMDataReqResp_RawText",
    "CRMDataReqResp_RawJSON",
    "CRMDataReqResp_ConfidenceScore",
    "CRMDataReqResp_CreatedBy"
  )
  VALUES (
    v_request."CRMDataReq_ID",
    p_method_code,
    p_raw_text,
    jsonb_build_object('field_id', p_request_field_id, 'value_text', p_value_text, 'value_json', p_value_json),
    p_confidence_score,
    p_user_id
  )
  RETURNING "CRMDataReqResp_ID" INTO v_response_id;

  v_update_id := public."CRM_QueueFieldUpdate"(
    v_request."CRMDataReq_RunID",
    v_field."CRMDataReqField_FieldDefID",
    v_field."CRMDataReqField_TargetID",
    p_value_text,
    p_value_json,
    p_confidence_score,
    'Captured from data request response.',
    p_user_id,
    v_request."CRMDataReq_ID",
    p_request_field_id,
    NULL,
    v_response_id
  );

  UPDATE public."CRM_DataRequestFields"
  SET "CRMDataReqField_StatusCode" = 'received',
      "CRMDataReqField_ResponseValueText" = p_value_text,
      "CRMDataReqField_ResponseValueJSON" = p_value_json,
      "CRMDataReqField_FieldUpdateID" = v_update_id,
      "CRMDataReqField_ReceivedAt" = now()
  WHERE "CRMDataReqField_ID" = p_request_field_id;

  UPDATE public."CRM_DataRequests"
  SET "CRMDataReq_StatusCode" = CASE
        WHEN EXISTS (
          SELECT 1
          FROM public."CRM_DataRequestFields" f
          WHERE f."CRMDataReqField_RequestID" = v_request."CRMDataReq_ID"
            AND f."CRMDataReqField_StatusCode" <> 'received'
        ) THEN 'partially_received'
        ELSE 'received'
      END,
      "CRMDataReq_ReceivedAt" = now()
  WHERE "CRMDataReq_ID" = v_request."CRMDataReq_ID";

  RETURN v_update_id;
END;
$$;


ALTER FUNCTION "public"."CRM_RecordDataRequestFieldValue"("p_request_field_id" "uuid", "p_value_text" "text", "p_value_json" "jsonb", "p_method_code" character varying, "p_raw_text" "text", "p_confidence_score" numeric, "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."CRM_RecordQuickTaskDecision"("p_quick_task_id" "uuid", "p_decision_status_code" character varying, "p_user_id" "uuid" DEFAULT NULL::"uuid", "p_option_id" "uuid" DEFAULT NULL::"uuid", "p_reason" "text" DEFAULT NULL::"text", "p_snoozed_until" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_decision_id uuid;
  v_task_status varchar(60);
BEGIN
  v_task_status := CASE
    WHEN p_decision_status_code IN ('accepted', 'edited', 'sent') THEN 'completed'
    WHEN p_decision_status_code = 'ignored' THEN 'ignored'
    WHEN p_decision_status_code = 'snoozed' THEN 'snoozed'
    WHEN p_decision_status_code = 'rejected' THEN 'cancelled'
    ELSE 'pending'
  END;

  INSERT INTO public."CRM_QuickTaskDecisions" (
    "CRMQuickDecision_QuickTaskID",
    "CRMQuickDecision_OptionID",
    "CRMQuickDecision_DecisionStatusCode",
    "CRMQuickDecision_DecisionReason",
    "CRMQuickDecision_DecidedBy"
  )
  VALUES (
    p_quick_task_id,
    p_option_id,
    p_decision_status_code,
    p_reason,
    p_user_id
  )
  RETURNING "CRMQuickDecision_ID" INTO v_decision_id;

  UPDATE public."CRM_QuickTasks"
  SET "CRMQuickTask_StatusCode" = v_task_status,
      "CRMQuickTask_DecisionStatusCode" = p_decision_status_code,
      "CRMQuickTask_SnoozedUntil" = p_snoozed_until,
      "CRMQuickTask_UserDecisionReason" = p_reason,
      "CRMQuickTask_CompletedAt" = CASE WHEN v_task_status IN ('completed', 'ignored', 'cancelled') THEN now() ELSE "CRMQuickTask_CompletedAt" END,
      "CRMQuickTask_CompletedBy" = CASE WHEN v_task_status IN ('completed', 'ignored', 'cancelled') THEN p_user_id ELSE "CRMQuickTask_CompletedBy" END,
      "CRMQuickTask_UpdatedAt" = now(),
      "CRMQuickTask_UpdatedBy" = p_user_id
  WHERE "CRMQuickTask_ID" = p_quick_task_id;

  IF p_option_id IS NOT NULL THEN
    UPDATE public."CRM_QuickTaskOptions"
    SET "CRMQuickOpt_DecisionStatusCode" = p_decision_status_code,
        "CRMQuickOpt_DecidedAt" = now(),
        "CRMQuickOpt_DecidedBy" = p_user_id
    WHERE "CRMQuickOpt_ID" = p_option_id;
  END IF;

  RETURN v_decision_id;
END;
$$;


ALTER FUNCTION "public"."CRM_RecordQuickTaskDecision"("p_quick_task_id" "uuid", "p_decision_status_code" character varying, "p_user_id" "uuid", "p_option_id" "uuid", "p_reason" "text", "p_snoozed_until" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."CRM_RecordWizardFieldValue"("p_session_id" "uuid", "p_field_def_id" "uuid", "p_value_text" "text" DEFAULT NULL::"text", "p_value_json" "jsonb" DEFAULT NULL::"jsonb", "p_user_id" "uuid" DEFAULT NULL::"uuid", "p_confidence_score" numeric DEFAULT 1) RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_session record;
  v_run record;
  v_response_id uuid;
  v_update_id uuid;
BEGIN
  SELECT *
  INTO v_session
  FROM public."CRM_DataCaptureSessions"
  WHERE "CRMDataCapSession_ID" = p_session_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Data capture session % was not found.', p_session_id;
  END IF;

  SELECT *
  INTO v_run
  FROM public."CRM_AutomationRuns"
  WHERE "CRMAutoRun_ID" = v_session."CRMDataCapSession_RunID";

  INSERT INTO public."CRM_DataCaptureResponses" (
    "CRMDataCapResp_SessionID",
    "CRMDataCapResp_FieldDefID",
    "CRMDataCapResp_ValueText",
    "CRMDataCapResp_ValueJSON",
    "CRMDataCapResp_ConfidenceScore",
    "CRMDataCapResp_IsConfirmed",
    "CRMDataCapResp_CapturedBy"
  )
  VALUES (
    p_session_id,
    p_field_def_id,
    p_value_text,
    p_value_json,
    p_confidence_score,
    true,
    p_user_id
  )
  RETURNING "CRMDataCapResp_ID" INTO v_response_id;

  v_update_id := public."CRM_QueueFieldUpdate"(
    v_run."CRMAutoRun_ID",
    p_field_def_id,
    v_run."CRMAutoRun_TargetID",
    p_value_text,
    p_value_json,
    p_confidence_score,
    'Captured by quick wizard.',
    p_user_id,
    NULL,
    NULL,
    v_response_id,
    NULL
  );

  UPDATE public."CRM_DataCaptureResponses"
  SET "CRMDataCapResp_FieldUpdateID" = v_update_id
  WHERE "CRMDataCapResp_ID" = v_response_id;

  UPDATE public."CRM_AutomationRuns"
  SET "CRMAutoRun_StatusCode" = 'in_review'
  WHERE "CRMAutoRun_ID" = v_run."CRMAutoRun_ID";

  RETURN v_update_id;
END;
$$;


ALTER FUNCTION "public"."CRM_RecordWizardFieldValue"("p_session_id" "uuid", "p_field_def_id" "uuid", "p_value_text" "text", "p_value_json" "jsonb", "p_user_id" "uuid", "p_confidence_score" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."CRM_RegisterActivityWorkflowEvent"("p_trigger_type_code" character varying, "p_source_table" character varying, "p_source_id" "uuid", "p_activity_id" "uuid" DEFAULT NULL::"uuid", "p_account_id" "uuid" DEFAULT NULL::"uuid", "p_lead_id" "uuid" DEFAULT NULL::"uuid", "p_opportunity_id" "uuid" DEFAULT NULL::"uuid", "p_quote_followup_id" "uuid" DEFAULT NULL::"uuid", "p_call_review_id" "uuid" DEFAULT NULL::"uuid", "p_job_id" "uuid" DEFAULT NULL::"uuid", "p_customer_org_id" "uuid" DEFAULT NULL::"uuid", "p_owner_user_id" "uuid" DEFAULT NULL::"uuid", "p_context_json" "jsonb" DEFAULT '{}'::"jsonb", "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_rule record;
  v_run_id uuid;
  v_quick_task_id uuid;
  v_email_draft_id uuid;
  v_whatsapp_draft_id uuid;
  v_due_at timestamptz;
  v_message_count integer := 0;
  v_task_count integer := 0;
BEGIN
  SELECT *
  INTO v_rule
  FROM public."CRM_ActivityWorkflowRules"
  WHERE "CRMAWRule_TriggerTypeCode" = p_trigger_type_code
    AND "CRMAWRule_IsActive" = true
    AND ("CRMAWRule_SourceTable" IS NULL OR "CRMAWRule_SourceTable" = p_source_table)
  ORDER BY "CRMAWRule_SortOrder", "CRMAWRule_CreatedAt"
  LIMIT 1;

  v_due_at := now() + make_interval(mins => COALESCE(v_rule."CRMAWRule_DueOffsetMinutes", 0));

  INSERT INTO public."CRM_ActivityWorkflowRuns" (
    "CRMAWRun_RuleID",
    "CRMAWRun_TriggerTypeCode",
    "CRMAWRun_SourceTable",
    "CRMAWRun_SourceID",
    "CRMAWRun_ActivityID",
    "CRMAWRun_AccountID",
    "CRMAWRun_LeadID",
    "CRMAWRun_OpportunityID",
    "CRMAWRun_QuoteFollowupID",
    "CRMAWRun_CallReviewID",
    "CRMAWRun_JobID",
    "CRMAWRun_CustomerOrgID",
    "CRMAWRun_OwnerUserID",
    "CRMAWRun_ContextJSON",
    "CRMAWRun_CreatedBy"
  )
  VALUES (
    v_rule."CRMAWRule_ID",
    p_trigger_type_code,
    p_source_table,
    p_source_id,
    p_activity_id,
    p_account_id,
    p_lead_id,
    p_opportunity_id,
    p_quote_followup_id,
    p_call_review_id,
    p_job_id,
    p_customer_org_id,
    COALESCE(p_owner_user_id, v_rule."CRMAWRule_DefaultOwnerUserID"),
    COALESCE(p_context_json, '{}'::jsonb),
    p_created_by
  )
  RETURNING "CRMAWRun_ID" INTO v_run_id;

  IF p_trigger_type_code IN ('booking_created', 'booking_confirmed') THEN
    v_quick_task_id := public."CRM_CreateQuickTask"(
      'send_personal_booking_thanks',
      'Send a personal thank-you for the booking',
      p_owner_user_id,
      'Customer has made a booking. Review the suggested note, send by the best channel, or ignore if it is not appropriate.',
      'normal',
      v_due_at,
      v_run_id,
      p_account_id,
      p_lead_id,
      p_opportunity_id,
      p_quote_followup_id,
      p_call_review_id,
      p_job_id,
      p_customer_org_id,
      p_source_table,
      p_source_id,
      p_created_by
    );
    v_task_count := v_task_count + 1;

    v_email_draft_id := public."CRM_CreatePersonalMessageDraft"(
      v_run_id,
      v_quick_task_id,
      'booking_thank_you',
      'email',
      p_owner_user_id,
      p_customer_org_id,
      NULL,
      'Thank you for the booking',
      'Thanks for the booking. I will keep an eye on this and make sure you are updated as it moves.',
      'Rewrite this so it sounds personal to the customer, job, lane, mode and recent conversation. Do not reuse standard wording.',
      COALESCE(p_context_json, '{}'::jsonb),
      p_created_by
    );
    v_message_count := v_message_count + 1;

    v_whatsapp_draft_id := public."CRM_CreatePersonalMessageDraft"(
      v_run_id,
      v_quick_task_id,
      'booking_thank_you',
      'whatsapp',
      p_owner_user_id,
      p_customer_org_id,
      NULL,
      NULL,
      'Thanks for the booking. I will keep this moving and update you shortly.',
      'Rewrite as a short personal WhatsApp using the customer and job context. Do not use fixed template wording.',
      COALESCE(p_context_json, '{}'::jsonb),
      p_created_by
    );
    v_message_count := v_message_count + 1;

    INSERT INTO public."CRM_QuickTaskOptions"
      ("CRMQuickOpt_QuickTaskID", "CRMQuickOpt_OptionTypeCode", "CRMQuickOpt_Label", "CRMQuickOpt_ChannelCode", "CRMQuickOpt_MessageDraftID", "CRMQuickOpt_IsRecommended", "CRMQuickOpt_SortOrder")
    VALUES
      (v_quick_task_id, 'send_email', 'Review/send email', 'email', v_email_draft_id, true, 10),
      (v_quick_task_id, 'send_whatsapp', 'Review/send WhatsApp', 'whatsapp', v_whatsapp_draft_id, false, 20),
      (v_quick_task_id, 'open_record', 'Open booking/job', NULL, NULL, false, 30),
      (v_quick_task_id, 'ignore', 'No message needed', NULL, NULL, false, 90);

  ELSIF p_trigger_type_code = 'phone_call_completed' THEN
    v_quick_task_id := public."CRM_CreateQuickTask"(
      'review_call_summary',
      'Review call summary and action points',
      p_owner_user_id,
      'Open the call summary, check the AI action points and decide what should become real work.',
      'normal',
      v_due_at,
      v_run_id,
      p_account_id,
      p_lead_id,
      p_opportunity_id,
      p_quote_followup_id,
      p_call_review_id,
      p_job_id,
      p_customer_org_id,
      'CRM_CallReviews',
      p_call_review_id,
      p_created_by
    );
    v_task_count := v_task_count + 1;

    INSERT INTO public."CRM_QuickTaskOptions"
      ("CRMQuickOpt_QuickTaskID", "CRMQuickOpt_OptionTypeCode", "CRMQuickOpt_Label", "CRMQuickOpt_TargetTable", "CRMQuickOpt_TargetID", "CRMQuickOpt_IsRecommended", "CRMQuickOpt_SortOrder")
    VALUES
      (v_quick_task_id, 'open_call_review', 'Open call review', 'CRM_CallReviews', p_call_review_id, true, 10),
      (v_quick_task_id, 'create_task', 'Create follow-up task', 'CRM_CallReviews', p_call_review_id, false, 20),
      (v_quick_task_id, 'ignore', 'No action needed', 'CRM_CallReviews', p_call_review_id, false, 90);

  ELSIF p_trigger_type_code = 'quote_sent' THEN
    v_quick_task_id := public."CRM_CreateQuickTask"(
      'follow_up_quote',
      'Follow up sent quote',
      p_owner_user_id,
      'Review whether this quote should be followed up personally, then send/edit/ignore.',
      'normal',
      v_due_at,
      v_run_id,
      p_account_id,
      p_lead_id,
      p_opportunity_id,
      p_quote_followup_id,
      p_call_review_id,
      p_job_id,
      p_customer_org_id,
      p_source_table,
      p_source_id,
      p_created_by
    );
    v_task_count := v_task_count + 1;

    v_email_draft_id := public."CRM_CreatePersonalMessageDraft"(
      v_run_id,
      v_quick_task_id,
      'quote_followup',
      'email',
      p_owner_user_id,
      p_customer_org_id,
      NULL,
      'Following up on the quote',
      'I wanted to check whether the quote works for you or if you would like me to adjust anything.',
      'Rewrite this follow-up personally using quote, customer, mode, lane and previous interaction context. Avoid generic chasing wording.',
      COALESCE(p_context_json, '{}'::jsonb),
      p_created_by
    );
    v_message_count := v_message_count + 1;

    INSERT INTO public."CRM_QuickTaskOptions"
      ("CRMQuickOpt_QuickTaskID", "CRMQuickOpt_OptionTypeCode", "CRMQuickOpt_Label", "CRMQuickOpt_ChannelCode", "CRMQuickOpt_MessageDraftID", "CRMQuickOpt_IsRecommended", "CRMQuickOpt_SortOrder")
    VALUES
      (v_quick_task_id, 'send_email', 'Review/send follow-up email', 'email', v_email_draft_id, true, 10),
      (v_quick_task_id, 'snooze', 'Snooze follow-up', NULL, NULL, false, 30),
      (v_quick_task_id, 'ignore', 'No follow-up needed', NULL, NULL, false, 90);

  ELSE
    v_quick_task_id := public."CRM_CreateQuickTask"(
      'manual_quick_task',
      'Review CRM activity',
      p_owner_user_id,
      'Review this activity and decide whether any follow-up is needed.',
      'normal',
      v_due_at,
      v_run_id,
      p_account_id,
      p_lead_id,
      p_opportunity_id,
      p_quote_followup_id,
      p_call_review_id,
      p_job_id,
      p_customer_org_id,
      p_source_table,
      p_source_id,
      p_created_by
    );
    v_task_count := v_task_count + 1;

    INSERT INTO public."CRM_QuickTaskOptions"
      ("CRMQuickOpt_QuickTaskID", "CRMQuickOpt_OptionTypeCode", "CRMQuickOpt_Label", "CRMQuickOpt_TargetTable", "CRMQuickOpt_TargetID", "CRMQuickOpt_IsRecommended", "CRMQuickOpt_SortOrder")
    VALUES
      (v_quick_task_id, 'open_record', 'Open record', p_source_table, p_source_id, true, 10),
      (v_quick_task_id, 'ignore', 'No action needed', p_source_table, p_source_id, false, 90);
  END IF;

  UPDATE public."CRM_ActivityWorkflowRuns"
  SET "CRMAWRun_GeneratedQuickTaskCount" = v_task_count,
      "CRMAWRun_GeneratedMessageDraftCount" = v_message_count
  WHERE "CRMAWRun_ID" = v_run_id;

  RETURN v_run_id;
END;
$$;


ALTER FUNCTION "public"."CRM_RegisterActivityWorkflowEvent"("p_trigger_type_code" character varying, "p_source_table" character varying, "p_source_id" "uuid", "p_activity_id" "uuid", "p_account_id" "uuid", "p_lead_id" "uuid", "p_opportunity_id" "uuid", "p_quote_followup_id" "uuid", "p_call_review_id" "uuid", "p_job_id" "uuid", "p_customer_org_id" "uuid", "p_owner_user_id" "uuid", "p_context_json" "jsonb", "p_created_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."CRM_StartAutomationRun"("p_playbook_code" character varying, "p_target_table" character varying, "p_target_pk_column" character varying, "p_target_id" "uuid", "p_assigned_user_id" "uuid" DEFAULT NULL::"uuid", "p_quick_task_id" "uuid" DEFAULT NULL::"uuid", "p_customer_org_id" "uuid" DEFAULT NULL::"uuid", "p_job_id" "uuid" DEFAULT NULL::"uuid", "p_account_id" "uuid" DEFAULT NULL::"uuid", "p_context_json" "jsonb" DEFAULT '{}'::"jsonb", "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_playbook record;
  v_run_id uuid;
BEGIN
  SELECT *
  INTO v_playbook
  FROM public."CRM_AutomationPlaybooks"
  WHERE "CRMAutoPlaybook_Code" = p_playbook_code
    AND "CRMAutoPlaybook_IsActive" = true
    AND ("CRMAutoPlaybook_CustomerOrgID" IS NULL OR "CRMAutoPlaybook_CustomerOrgID" = p_customer_org_id)
  ORDER BY "CRMAutoPlaybook_CustomerOrgID" NULLS LAST,
           "CRMAutoPlaybook_OrgOfficeID" NULLS LAST,
           "CRMAutoPlaybook_CreatedAt"
  LIMIT 1;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'CRM automation playbook % was not found.', p_playbook_code;
  END IF;

  INSERT INTO public."CRM_AutomationRuns" (
    "CRMAutoRun_PlaybookID",
    "CRMAutoRun_StatusCode",
    "CRMAutoRun_QuickTaskID",
    "CRMAutoRun_AccountID",
    "CRMAutoRun_JobID",
    "CRMAutoRun_CustomerOrgID",
    "CRMAutoRun_TargetTable",
    "CRMAutoRun_TargetPKColumn",
    "CRMAutoRun_TargetID",
    "CRMAutoRun_AssignedUserID",
    "CRMAutoRun_ContextJSON",
    "CRMAutoRun_StartedBy"
  )
  VALUES (
    v_playbook."CRMAutoPlaybook_ID",
    CASE WHEN v_playbook."CRMAutoPlaybook_RequiresWizard" THEN 'needs_data' ELSE 'ready' END,
    p_quick_task_id,
    p_account_id,
    p_job_id,
    p_customer_org_id,
    p_target_table,
    p_target_pk_column,
    p_target_id,
    p_assigned_user_id,
    COALESCE(p_context_json, '{}'::jsonb),
    p_created_by
  )
  RETURNING "CRMAutoRun_ID" INTO v_run_id;

  INSERT INTO public."CRM_AutomationRunSteps" (
    "CRMAutoRunStep_RunID",
    "CRMAutoRunStep_PlaybookStepID",
    "CRMAutoRunStep_ActionTypeCode",
    "CRMAutoRunStep_StatusCode",
    "CRMAutoRunStep_SortOrder"
  )
  SELECT
    v_run_id,
    step."CRMAutoStep_ID",
    step."CRMAutoStep_ActionTypeCode",
    'ready',
    step."CRMAutoStep_SortOrder"
  FROM public."CRM_AutomationPlaybookSteps" step
  WHERE step."CRMAutoStep_PlaybookID" = v_playbook."CRMAutoPlaybook_ID"
  ORDER BY step."CRMAutoStep_SortOrder";

  RETURN v_run_id;
END;
$$;


ALTER FUNCTION "public"."CRM_StartAutomationRun"("p_playbook_code" character varying, "p_target_table" character varying, "p_target_pk_column" character varying, "p_target_id" "uuid", "p_assigned_user_id" "uuid", "p_quick_task_id" "uuid", "p_customer_org_id" "uuid", "p_job_id" "uuid", "p_account_id" "uuid", "p_context_json" "jsonb", "p_created_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."Comm_AcquireMailboxSyncLease"("p_mailbox_id" "uuid", "p_lease_token" "uuid", "p_lease_seconds" integer DEFAULT 180) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  affected_rows integer;
begin
  update public."Comm_Mailboxes"
  set
    "CommMailbox_SyncLeaseToken" = p_lease_token,
    "CommMailbox_SyncLeaseUntil" = now() + make_interval(secs => greatest(15, least(p_lease_seconds, 300)))
  where "CommMailbox_ID" = p_mailbox_id
    and "CommMailbox_IsDeleted" = false
    and (
      "CommMailbox_SyncLeaseUntil" is null
      or "CommMailbox_SyncLeaseUntil" <= now()
      or "CommMailbox_SyncLeaseToken" = p_lease_token
    );

  get diagnostics affected_rows = row_count;
  return affected_rows = 1;
end;
$$;


ALTER FUNCTION "public"."Comm_AcquireMailboxSyncLease"("p_mailbox_id" "uuid", "p_lease_token" "uuid", "p_lease_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."Comm_ConfigureEmailWatchWorkerSchedule"() RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_endpoint text;
  v_job_id bigint;
begin
  select decrypted_secret
  into v_endpoint
  from vault.decrypted_secrets
  where name = 'multideck_email_watch_worker_endpoint'
  limit 1;

  if nullif(btrim(v_endpoint), '') is null then
    return false;
  end if;

  for v_job_id in
    select jobid
    from cron.job
    where jobname in (
      'multideck-email-watch-worker',
      'multideck-email-live-sync',
      'multideck-email-index-backfill'
    )
  loop
    perform cron.unschedule(v_job_id);
  end loop;

  perform cron.schedule(
    'multideck-email-live-sync',
    '10 seconds',
    format(
      $command$
        select net.http_post(
          url := %L,
          headers := jsonb_build_object(
            'Content-Type', 'application/json',
            'x-multideck-email-watch-secret', (
              select decrypted_secret
              from vault.decrypted_secrets
              where name = 'multideck_email_watch_worker_secret'
              limit 1
            )
          ),
          body := jsonb_build_object('source', 'cron', 'mode', 'live', 'requestedAt', now()),
          timeout_milliseconds := 55000
        );
      $command$,
      btrim(v_endpoint)
    )
  );

  perform cron.schedule(
    'multideck-email-index-backfill',
    '* * * * *',
    format(
      $command$
        select net.http_post(
          url := %L,
          headers := jsonb_build_object(
            'Content-Type', 'application/json',
            'x-multideck-email-watch-secret', (
              select decrypted_secret
              from vault.decrypted_secrets
              where name = 'multideck_email_watch_worker_secret'
              limit 1
            )
          ),
          body := jsonb_build_object('source', 'cron', 'mode', 'backfill', 'requestedAt', now()),
          timeout_milliseconds := 55000
        );
      $command$,
      btrim(v_endpoint)
    )
  );

  return true;
end;
$_$;


ALTER FUNCTION "public"."Comm_ConfigureEmailWatchWorkerSchedule"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."Comm_CreateNotification"("p_user_id" "uuid", "p_title" character varying, "p_body" "text" DEFAULT NULL::"text", "p_target_table" character varying DEFAULT NULL::character varying, "p_target_id" "uuid" DEFAULT NULL::"uuid", "p_link_type_code" character varying DEFAULT NULL::character varying, "p_thread_id" "uuid" DEFAULT NULL::"uuid", "p_message_id" "uuid" DEFAULT NULL::"uuid", "p_workflow_task_id" "uuid" DEFAULT NULL::"uuid", "p_priority_code" character varying DEFAULT 'normal'::character varying) RETURNS "uuid"
    LANGUAGE "plpgsql"
