CREATE OR REPLACE FUNCTION "public"."Comm_LinkThreadRecord"("p_thread_id" "uuid", "p_link_type_code" character varying, "p_target_table" character varying, "p_target_id" "uuid", "p_target_display_snapshot" character varying DEFAULT NULL::character varying, "p_role" character varying DEFAULT NULL::character varying, "p_is_primary" boolean DEFAULT false) RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_link_id uuid;
BEGIN
  INSERT INTO public."Comm_ThreadLinks" (
    "CommThreadLink_ThreadID",
    "CommThreadLink_LinkTypeCode",
    "CommThreadLink_TargetTable",
    "CommThreadLink_TargetID",
    "CommThreadLink_TargetDisplaySnapshot",
    "CommThreadLink_Role",
    "CommThreadLink_IsPrimary"
  )
  VALUES (
    p_thread_id,
    p_link_type_code,
    p_target_table,
    p_target_id,
    p_target_display_snapshot,
    p_role,
    coalesce(p_is_primary, false)
  )
  ON CONFLICT ("CommThreadLink_ThreadID", "CommThreadLink_LinkTypeCode", "CommThreadLink_TargetTable", "CommThreadLink_TargetID", "CommThreadLink_Role")
