CREATE OR REPLACE FUNCTION "public"."DOCB_FindAssetCandidates"("p_asset_type_code" character varying DEFAULT NULL::character varying, "p_org_office_id" "uuid" DEFAULT NULL::"uuid", "p_legal_entity_id" "uuid" DEFAULT NULL::"uuid", "p_brand_id" "uuid" DEFAULT NULL::"uuid", "p_customer_org_id" "uuid" DEFAULT NULL::"uuid", "p_language_code" character varying DEFAULT 'en'::character varying) RETURNS TABLE("DOCBAS_ID" "uuid", "DOCBAS_Code" character varying, "DOCBAS_Name" character varying, "DOCBAS_AssetTypeCode" character varying, "DOCBAS_LanguageCode" character varying, "DOCBAS_FileName" character varying, "DOCBAS_StorageBucket" character varying, "DOCBAS_StoragePath" "text", "DOCBAS_FileURL" "text", "DOCBAS_IsApproved" boolean, "MatchScore" integer, "MatchLevel" "text")
    LANGUAGE "sql" STABLE
    AS $$
  SELECT
    asset."DOCBAS_ID",
    asset."DOCBAS_Code",
    asset."DOCBAS_Name",
    asset."DOCBAS_AssetTypeCode",
    asset."DOCBAS_LanguageCode",
    asset."DOCBAS_FileName",
    asset."DOCBAS_StorageBucket",
    asset."DOCBAS_StoragePath",
    asset."DOCBAS_FileURL",
    asset."DOCBAS_IsApproved",
    (
      CASE WHEN asset."DOCBAS_CustomerOrgID" IS NOT NULL AND asset."DOCBAS_CustomerOrgID" = p_customer_org_id THEN 64 ELSE 0 END +
      CASE WHEN asset."DOCBAS_BrandID" IS NOT NULL AND asset."DOCBAS_BrandID" = p_brand_id THEN 32 ELSE 0 END +
      CASE WHEN asset."DOCBAS_LegalEntityID" IS NOT NULL AND asset."DOCBAS_LegalEntityID" = p_legal_entity_id THEN 16 ELSE 0 END +
      CASE WHEN asset."DOCBAS_OrgOfficeID" IS NOT NULL AND asset."DOCBAS_OrgOfficeID" = p_org_office_id THEN 8 ELSE 0 END +
      CASE WHEN p_language_code IS NOT NULL AND asset."DOCBAS_LanguageCode" = p_language_code THEN 4 ELSE 0 END
    )::int AS "MatchScore",
    CASE
      WHEN asset."DOCBAS_CustomerOrgID" IS NOT NULL AND asset."DOCBAS_CustomerOrgID" = p_customer_org_id THEN 'customer'
      WHEN asset."DOCBAS_BrandID" IS NOT NULL AND asset."DOCBAS_BrandID" = p_brand_id THEN 'brand'
      WHEN asset."DOCBAS_LegalEntityID" IS NOT NULL AND asset."DOCBAS_LegalEntityID" = p_legal_entity_id THEN 'legal_entity'
      WHEN asset."DOCBAS_OrgOfficeID" IS NOT NULL AND asset."DOCBAS_OrgOfficeID" = p_org_office_id THEN 'office'
      ELSE 'system'
    END AS "MatchLevel"
  FROM public."DOCB_AssetLibrary" asset
  WHERE asset."DOCBAS_IsActive" = true
    AND (p_asset_type_code IS NULL OR asset."DOCBAS_AssetTypeCode" = p_asset_type_code)
    AND (p_language_code IS NULL OR asset."DOCBAS_LanguageCode" = p_language_code OR asset."DOCBAS_LanguageCode" = 'en')
    AND (asset."DOCBAS_CustomerOrgID" IS NULL OR asset."DOCBAS_CustomerOrgID" = p_customer_org_id)
    AND (asset."DOCBAS_BrandID" IS NULL OR asset."DOCBAS_BrandID" = p_brand_id)
    AND (asset."DOCBAS_LegalEntityID" IS NULL OR asset."DOCBAS_LegalEntityID" = p_legal_entity_id)
    AND (asset."DOCBAS_OrgOfficeID" IS NULL OR asset."DOCBAS_OrgOfficeID" = p_org_office_id)
  ORDER BY "MatchScore" DESC,
           asset."DOCBAS_IsApproved" DESC,
           asset."DOCBAS_UpdatedAt" DESC NULLS LAST,
           asset."DOCBAS_Code";
$$;


ALTER FUNCTION "public"."DOCB_FindAssetCandidates"("p_asset_type_code" character varying, "p_org_office_id" "uuid", "p_legal_entity_id" "uuid", "p_brand_id" "uuid", "p_customer_org_id" "uuid", "p_language_code" character varying) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."DOCB_FindLibraryPackCandidates"("p_pack_code" character varying DEFAULT NULL::character varying, "p_data_scope_code" character varying DEFAULT NULL::character varying, "p_org_office_id" "uuid" DEFAULT NULL::"uuid", "p_legal_entity_id" "uuid" DEFAULT NULL::"uuid", "p_brand_id" "uuid" DEFAULT NULL::"uuid", "p_customer_org_id" "uuid" DEFAULT NULL::"uuid", "p_language_code" character varying DEFAULT 'en'::character varying) RETURNS TABLE("DOCBLP_ID" "uuid", "DOCBLP_Code" character varying, "DOCBLP_Name" character varying, "DOCBLP_DataScopeCode" character varying, "DOCBLP_LanguageCode" character varying, "DOCBLP_OrgOfficeID" "uuid", "DOCBLP_LegalEntityID" "uuid", "DOCBLP_BrandID" "uuid", "DOCBLP_CustomerOrgID" "uuid", "ItemCount" integer, "RequiredItemCount" integer, "GeneratedByDefaultCount" integer, "MatchScore" integer, "MatchLevel" "text")
    LANGUAGE "sql" STABLE
    AS $$
  SELECT
    pack."DOCBLP_ID",
    pack."DOCBLP_Code",
    pack."DOCBLP_Name",
    pack."DOCBLP_DataScopeCode",
    pack."DOCBLP_LanguageCode",
    pack."DOCBLP_OrgOfficeID",
    pack."DOCBLP_LegalEntityID",
    pack."DOCBLP_BrandID",
    pack."DOCBLP_CustomerOrgID",
    pack."ItemCount",
    pack."RequiredItemCount",
    pack."GeneratedByDefaultCount",
    (
      CASE WHEN pack."DOCBLP_CustomerOrgID" IS NOT NULL AND pack."DOCBLP_CustomerOrgID" = p_customer_org_id THEN 64 ELSE 0 END +
      CASE WHEN pack."DOCBLP_BrandID" IS NOT NULL AND pack."DOCBLP_BrandID" = p_brand_id THEN 32 ELSE 0 END +
      CASE WHEN pack."DOCBLP_LegalEntityID" IS NOT NULL AND pack."DOCBLP_LegalEntityID" = p_legal_entity_id THEN 16 ELSE 0 END +
      CASE WHEN pack."DOCBLP_OrgOfficeID" IS NOT NULL AND pack."DOCBLP_OrgOfficeID" = p_org_office_id THEN 8 ELSE 0 END +
      CASE WHEN p_language_code IS NOT NULL AND pack."DOCBLP_LanguageCode" = p_language_code THEN 4 ELSE 0 END +
      CASE WHEN p_pack_code IS NOT NULL AND pack."DOCBLP_Code" = p_pack_code THEN 4 ELSE 0 END
    )::int AS "MatchScore",
    CASE
      WHEN pack."DOCBLP_CustomerOrgID" IS NOT NULL AND pack."DOCBLP_CustomerOrgID" = p_customer_org_id THEN 'customer'
      WHEN pack."DOCBLP_BrandID" IS NOT NULL AND pack."DOCBLP_BrandID" = p_brand_id THEN 'brand'
      WHEN pack."DOCBLP_LegalEntityID" IS NOT NULL AND pack."DOCBLP_LegalEntityID" = p_legal_entity_id THEN 'legal_entity'
      WHEN pack."DOCBLP_OrgOfficeID" IS NOT NULL AND pack."DOCBLP_OrgOfficeID" = p_org_office_id THEN 'office'
      ELSE 'system'
    END AS "MatchLevel"
  FROM public."DOCB_LibraryPackSummary" pack
  WHERE pack."DOCBLP_IsActive" = true
    AND pack."DOCBLP_StatusCode" = 'published'
    AND (p_pack_code IS NULL OR pack."DOCBLP_Code" = p_pack_code)
    AND (p_data_scope_code IS NULL OR pack."DOCBLP_DataScopeCode" = p_data_scope_code)
    AND (p_language_code IS NULL OR pack."DOCBLP_LanguageCode" = p_language_code OR pack."DOCBLP_LanguageCode" = 'en')
    AND (pack."DOCBLP_CustomerOrgID" IS NULL OR pack."DOCBLP_CustomerOrgID" = p_customer_org_id)
    AND (pack."DOCBLP_BrandID" IS NULL OR pack."DOCBLP_BrandID" = p_brand_id)
    AND (pack."DOCBLP_LegalEntityID" IS NULL OR pack."DOCBLP_LegalEntityID" = p_legal_entity_id)
    AND (pack."DOCBLP_OrgOfficeID" IS NULL OR pack."DOCBLP_OrgOfficeID" = p_org_office_id)
  ORDER BY "MatchScore" DESC,
           CASE WHEN p_language_code IS NOT NULL AND pack."DOCBLP_LanguageCode" = p_language_code THEN 0 ELSE 1 END,
           pack."DOCBLP_UpdatedAt" DESC NULLS LAST,
           pack."DOCBLP_Code";
$$;


ALTER FUNCTION "public"."DOCB_FindLibraryPackCandidates"("p_pack_code" character varying, "p_data_scope_code" character varying, "p_org_office_id" "uuid", "p_legal_entity_id" "uuid", "p_brand_id" "uuid", "p_customer_org_id" "uuid", "p_language_code" character varying) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."DOCB_FindTemplateCandidates"("p_doc_type_id" "uuid" DEFAULT NULL::"uuid", "p_document_code" character varying DEFAULT NULL::character varying, "p_data_scope_code" character varying DEFAULT NULL::character varying, "p_org_office_id" "uuid" DEFAULT NULL::"uuid", "p_legal_entity_id" "uuid" DEFAULT NULL::"uuid", "p_brand_id" "uuid" DEFAULT NULL::"uuid", "p_customer_org_id" "uuid" DEFAULT NULL::"uuid", "p_language_code" character varying DEFAULT 'en'::character varying) RETURNS TABLE("DOCBT_ID" "uuid", "DOCBT_Code" character varying, "DOCBT_Name" character varying, "DOCBT_LibraryDocumentCode" character varying, "DOCBT_DocTypeID" "uuid", "DOCBT_DataScopeCode" character varying, "DOCBT_LanguageCode" character varying, "DOCBT_OrgOfficeID" "uuid", "DOCBT_LegalEntityID" "uuid", "DOCBT_BrandID" "uuid", "DOCBT_CustomerOrgID" "uuid", "CurrentTemplateVersionID" "uuid", "DefaultRenderEngineCode" character varying, "DefaultOutputFormatCode" character varying, "MatchScore" integer, "MatchLevel" "text")
    LANGUAGE "sql" STABLE
    AS $$
  SELECT
    template."DOCBT_ID",
    template."DOCBT_Code",
    template."DOCBT_Name",
    template."DOCBT_LibraryDocumentCode",
    template."DOCBT_DocTypeID",
    template."DOCBT_DataScopeCode",
    template."DOCBT_LanguageCode",
    template."DOCBT_OrgOfficeID",
    template."DOCBT_LegalEntityID",
    template."DOCBT_BrandID",
    template."DOCBT_CustomerOrgID",
    template."CurrentTemplateVersionID",
    template."DOCBT_DefaultRenderEngineCode" AS "DefaultRenderEngineCode",
    template."DOCBT_DefaultOutputFormatCode" AS "DefaultOutputFormatCode",
    (
      CASE WHEN template."DOCBT_CustomerOrgID" IS NOT NULL AND template."DOCBT_CustomerOrgID" = p_customer_org_id THEN 64 ELSE 0 END +
      CASE WHEN template."DOCBT_BrandID" IS NOT NULL AND template."DOCBT_BrandID" = p_brand_id THEN 32 ELSE 0 END +
      CASE WHEN template."DOCBT_LegalEntityID" IS NOT NULL AND template."DOCBT_LegalEntityID" = p_legal_entity_id THEN 16 ELSE 0 END +
      CASE WHEN template."DOCBT_OrgOfficeID" IS NOT NULL AND template."DOCBT_OrgOfficeID" = p_org_office_id THEN 8 ELSE 0 END +
      CASE WHEN p_language_code IS NOT NULL AND template."DOCBT_LanguageCode" = p_language_code THEN 4 ELSE 0 END +
      CASE WHEN p_doc_type_id IS NOT NULL AND template."DOCBT_DocTypeID" = p_doc_type_id THEN 2 ELSE 0 END +
      CASE WHEN p_document_code IS NOT NULL AND (
        template."DOCBT_Code" = p_document_code OR
        template."DOCBT_LibraryDocumentCode" = p_document_code OR
        template."DOCBT_DocTypeCodeSnapshot" = p_document_code OR
        template."DocTypeCode" = p_document_code
      ) THEN 2 ELSE 0 END
    )::int AS "MatchScore",
    CASE
      WHEN template."DOCBT_CustomerOrgID" IS NOT NULL AND template."DOCBT_CustomerOrgID" = p_customer_org_id THEN 'customer'
      WHEN template."DOCBT_BrandID" IS NOT NULL AND template."DOCBT_BrandID" = p_brand_id THEN 'brand'
      WHEN template."DOCBT_LegalEntityID" IS NOT NULL AND template."DOCBT_LegalEntityID" = p_legal_entity_id THEN 'legal_entity'
      WHEN template."DOCBT_OrgOfficeID" IS NOT NULL AND template."DOCBT_OrgOfficeID" = p_org_office_id THEN 'office'
      ELSE 'system'
    END AS "MatchLevel"
  FROM public."DOCB_TemplateSummary" template
  WHERE template."DOCBT_IsActive" = true
    AND template."DOCBT_StatusCode" = 'published'
    AND (p_data_scope_code IS NULL OR template."DOCBT_DataScopeCode" = p_data_scope_code)
    AND (p_doc_type_id IS NULL OR template."DOCBT_DocTypeID" = p_doc_type_id)
    AND (
      p_document_code IS NULL OR
      template."DOCBT_Code" = p_document_code OR
      template."DOCBT_LibraryDocumentCode" = p_document_code OR
      template."DOCBT_DocTypeCodeSnapshot" = p_document_code OR
      template."DocTypeCode" = p_document_code
    )
    AND (p_language_code IS NULL OR template."DOCBT_LanguageCode" = p_language_code OR template."DOCBT_LanguageCode" = 'en')
    AND (template."DOCBT_CustomerOrgID" IS NULL OR template."DOCBT_CustomerOrgID" = p_customer_org_id)
    AND (template."DOCBT_BrandID" IS NULL OR template."DOCBT_BrandID" = p_brand_id)
    AND (template."DOCBT_LegalEntityID" IS NULL OR template."DOCBT_LegalEntityID" = p_legal_entity_id)
    AND (template."DOCBT_OrgOfficeID" IS NULL OR template."DOCBT_OrgOfficeID" = p_org_office_id)
  ORDER BY "MatchScore" DESC,
           CASE WHEN p_language_code IS NOT NULL AND template."DOCBT_LanguageCode" = p_language_code THEN 0 ELSE 1 END,
           template."DOCBT_UpdatedAt" DESC NULLS LAST,
           template."DOCBT_Code";
$$;


ALTER FUNCTION "public"."DOCB_FindTemplateCandidates"("p_doc_type_id" "uuid", "p_document_code" character varying, "p_data_scope_code" character varying, "p_org_office_id" "uuid", "p_legal_entity_id" "uuid", "p_brand_id" "uuid", "p_customer_org_id" "uuid", "p_language_code" character varying) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."DOCB_SectionGridIssues"("p_section_version_id" "uuid") RETURNS TABLE("DOCBSLR_ID" "uuid", "RowNo" integer, "IssueCode" character varying, "IssueMessage" "text")
    LANGUAGE "sql" STABLE
    AS $$
  WITH cells AS (
    SELECT
      row_def."DOCBSLR_ID",
      row_def."DOCBSLR_RowNo",
      cell."DOCBSLC_ID",
      cell."DOCBSLC_ColumnStart",
      (cell."DOCBSLC_ColumnStart" + cell."DOCBSLC_ColumnSpan" - 1) AS column_end
    FROM public."DOCB_SectionLayoutRows" row_def
    JOIN public."DOCB_SectionLayoutCells" cell
      ON cell."DOCBSLC_RowID" = row_def."DOCBSLR_ID"
    WHERE row_def."DOCBSLR_SectionVersionID" = p_section_version_id
  )
  SELECT DISTINCT
    a."DOCBSLR_ID",
    a."DOCBSLR_RowNo",
    'overlapping_cells'::varchar AS "IssueCode",
    ('Cells overlap in row ' || a."DOCBSLR_RowNo")::text AS "IssueMessage"
  FROM cells a
  JOIN cells b
    ON b."DOCBSLR_ID" = a."DOCBSLR_ID"
   AND b."DOCBSLC_ID" <> a."DOCBSLC_ID"
   AND a."DOCBSLC_ColumnStart" <= b.column_end
   AND b."DOCBSLC_ColumnStart" <= a.column_end;
$$;


ALTER FUNCTION "public"."DOCB_SectionGridIssues"("p_section_version_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."DOCSEC_FindVerification"("p_public_code" character varying) RETURNS TABLE("PublicCode" character varying, "TokenStatusCode" character varying, "TokenStatusName" character varying, "IsValidForPublicVerification" boolean, "DocumentNumber" character varying, "TargetTable" character varying, "BLNumber" character varying, "BLStatus" character varying, "FileSHA256" character varying, "CanonicalPayloadSHA256" character varying, "SignatureIsValid" boolean, "ValidFrom" timestamp with time zone, "ExpiresAt" timestamp with time zone, "RevokedAt" timestamp with time zone, "VerificationCount" integer, "LastVerifiedAt" timestamp with time zone, "OpenIssueCount" integer)
    LANGUAGE "sql" STABLE
    AS $$
  SELECT
    public_summary."DOCSECVT_PublicCode",
    public_summary."DOCSECVT_StatusCode",
    public_summary."TokenStatusName",
    public_summary."TokenIsValidForPublicVerification",
    public_summary."DOCSECVT_DocumentNumberSnapshot",
    public_summary."DOCSECVT_TargetTable",
    public_summary."BLNumber",
    public_summary."BLStatus",
    public_summary."DOCSECF_FileSHA256",
    public_summary."DOCSECF_CanonicalPayloadSHA256",
    public_summary."SignatureIsValid",
    public_summary."DOCSECVT_ValidFrom",
    public_summary."DOCSECVT_ExpiresAt",
    public_summary."DOCSECVT_RevokedAt",
    public_summary."DOCSECVT_VerificationCount",
    public_summary."DOCSECVT_LastVerifiedAt",
    public_summary."OpenIssueCount"
  FROM public."DOCSEC_PublicVerificationSummary" public_summary
  WHERE public_summary."DOCSECVT_PublicCode" = p_public_code
  LIMIT 1;
$$;


ALTER FUNCTION "public"."DOCSEC_FindVerification"("p_public_code" character varying) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."DOCSEC_RecordVerificationEvent"("p_public_code" character varying, "p_status_code" character varying, "p_verification_method" character varying DEFAULT 'scan'::character varying, "p_document_hash_submitted_sha256" character varying DEFAULT NULL::character varying, "p_ip_address_hash_sha256" character varying DEFAULT NULL::character varying, "p_user_agent" "text" DEFAULT NULL::"text", "p_country_code" character varying DEFAULT NULL::character varying, "p_metadata_json" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_token_id uuid;
  v_risk_level varchar(40);
  v_fingerprint_id uuid;
  v_event_id uuid;
BEGIN
  SELECT
    token."DOCSECVT_ID",
    status."DOCSECVS_RiskLevelCode",
    token."DOCSECVT_FingerprintID"
  INTO v_token_id, v_risk_level, v_fingerprint_id
  FROM public."DOCSEC_VerificationTokens" token
  LEFT JOIN public."sys_DocumentSecurityVerificationStatuses" status
    ON status."DOCSECVS_Code" = p_status_code
  WHERE token."DOCSECVT_PublicCode" = p_public_code
  LIMIT 1;

  IF v_risk_level IS NULL THEN
    SELECT status."DOCSECVS_RiskLevelCode"
    INTO v_risk_level
    FROM public."sys_DocumentSecurityVerificationStatuses" status
    WHERE status."DOCSECVS_Code" = p_status_code
    LIMIT 1;
  END IF;

  INSERT INTO public."DOCSEC_VerificationEvents" (
    "DOCSECVE_VerificationTokenID",
    "DOCSECVE_PublicCodeSnapshot",
    "DOCSECVE_StatusCode",
    "DOCSECVE_RiskLevelCode",
    "DOCSECVE_VerificationMethod",
    "DOCSECVE_DocumentHashSubmittedSHA256",
    "DOCSECVE_MatchedFingerprintID",
    "DOCSECVE_IPAddressHashSHA256",
    "DOCSECVE_UserAgent",
    "DOCSECVE_CountryCode",
    "DOCSECVE_MetadataJSON"
  )
  VALUES (
    v_token_id,
    p_public_code,
    p_status_code,
    coalesce(v_risk_level, 'medium'),
    coalesce(p_verification_method, 'scan'),
    p_document_hash_submitted_sha256,
    v_fingerprint_id,
    p_ip_address_hash_sha256,
    p_user_agent,
    p_country_code,
    coalesce(p_metadata_json, '{}'::jsonb)
  )
  RETURNING "DOCSECVE_ID" INTO v_event_id;

  IF v_token_id IS NOT NULL THEN
    UPDATE public."DOCSEC_VerificationTokens"
    SET
      "DOCSECVT_VerificationCount" = "DOCSECVT_VerificationCount" + 1,
      "DOCSECVT_LastVerifiedAt" = now(),
      "DOCSECVT_UpdatedAt" = now()
    WHERE "DOCSECVT_ID" = v_token_id;

    UPDATE public."BL_SecurityControls" bl_security
    SET
      "BLSC_VerificationCount" = "BLSC_VerificationCount" + 1,
      "BLSC_LastVerificationAt" = now(),
      "BLSC_UpdatedAt" = now()
    WHERE bl_security."BLSC_CurrentVerificationTokenID" = v_token_id;
  END IF;

  RETURN v_event_id;
END;
$$;


ALTER FUNCTION "public"."DOCSEC_RecordVerificationEvent"("p_public_code" character varying, "p_status_code" character varying, "p_verification_method" character varying, "p_document_hash_submitted_sha256" character varying, "p_ip_address_hash_sha256" character varying, "p_user_agent" "text", "p_country_code" character varying, "p_metadata_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."DOCSEC_VerifyDocumentHash"("p_public_code" character varying, "p_file_sha256" character varying) RETURNS TABLE("StatusCode" character varying, "RiskLevelCode" character varying, "Message" "text", "FingerprintID" "uuid")
    LANGUAGE "sql" STABLE
    AS $$
  SELECT
    CASE
      WHEN token."DOCSECVT_ID" IS NULL THEN 'not_found'
      WHEN token."DOCSECVT_StatusCode" = 'revoked' THEN 'revoked'
      WHEN token."DOCSECVT_StatusCode" = 'superseded' THEN 'superseded'
      WHEN token."DOCSECVT_StatusCode" = 'expired' OR (token."DOCSECVT_ExpiresAt" IS NOT NULL AND token."DOCSECVT_ExpiresAt" < now()) THEN 'expired'
      WHEN lower(fingerprint."DOCSECF_FileSHA256") = lower(p_file_sha256) THEN 'valid_hash_match'
      ELSE 'hash_mismatch'
    END::varchar AS "StatusCode",
    CASE
      WHEN token."DOCSECVT_ID" IS NULL THEN 'high'
      WHEN token."DOCSECVT_StatusCode" IN ('revoked', 'blocked') THEN 'critical'
      WHEN token."DOCSECVT_StatusCode" = 'superseded' THEN 'medium'
      WHEN token."DOCSECVT_StatusCode" = 'expired' OR (token."DOCSECVT_ExpiresAt" IS NOT NULL AND token."DOCSECVT_ExpiresAt" < now()) THEN 'medium'
      WHEN lower(fingerprint."DOCSECF_FileSHA256") = lower(p_file_sha256) THEN 'none'
      ELSE 'critical'
    END::varchar AS "RiskLevelCode",
    CASE
      WHEN token."DOCSECVT_ID" IS NULL THEN 'Verification code was not found.'
      WHEN token."DOCSECVT_StatusCode" = 'revoked' THEN 'Document verification token has been revoked.'
      WHEN token."DOCSECVT_StatusCode" = 'superseded' THEN 'Document has been superseded by a later version.'
      WHEN token."DOCSECVT_StatusCode" = 'expired' OR (token."DOCSECVT_ExpiresAt" IS NOT NULL AND token."DOCSECVT_ExpiresAt" < now()) THEN 'Document verification token has expired.'
      WHEN lower(fingerprint."DOCSECF_FileSHA256") = lower(p_file_sha256) THEN 'Document hash matches the issued fingerprint.'
      ELSE 'Document hash does not match the issued fingerprint.'
    END::text AS "Message",
    fingerprint."DOCSECF_ID" AS "FingerprintID"
  FROM (SELECT 1) seed
  LEFT JOIN public."DOCSEC_VerificationTokens" token
    ON token."DOCSECVT_PublicCode" = p_public_code
  LEFT JOIN public."DOCSEC_DocumentFingerprints" fingerprint
    ON fingerprint."DOCSECF_ID" = token."DOCSECVT_FingerprintID";
$$;


ALTER FUNCTION "public"."DOCSEC_VerifyDocumentHash"("p_public_code" character varying, "p_file_sha256" character varying) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."EDI_QueueOutboundMessage"("p_message_profile_id" "uuid", "p_job_id" "uuid" DEFAULT NULL::"uuid", "p_generated_from_table" character varying DEFAULT NULL::character varying, "p_generated_from_id" "uuid" DEFAULT NULL::"uuid", "p_document_reference" character varying DEFAULT NULL::character varying, "p_payload_json" "jsonb" DEFAULT '{}'::"jsonb", "p_payload_text" "text" DEFAULT NULL::"text", "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_profile record;
  v_message_id uuid;
  v_ack_status varchar(60);
BEGIN
  SELECT *
  INTO v_profile
  FROM public."EDI_MessageProfiles"
  WHERE "EDIMP_ID" = p_message_profile_id
    AND "EDIMP_IsActive" = true;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'EDI message profile % was not found or is inactive.', p_message_profile_id;
  END IF;

  IF v_profile."EDIMP_DirectionCode" NOT IN ('outbound', 'bidirectional') THEN
    RAISE EXCEPTION 'EDI message profile % is not outbound-capable.', p_message_profile_id;
  END IF;

  v_ack_status := CASE WHEN v_profile."EDIMP_RequiresAcknowledgement" THEN 'pending' ELSE 'not_required' END;

  INSERT INTO public."EDI_Messages" (
    "EDIMessage_MessageProfileID",
    "EDIMessage_ConnectionID",
    "EDIMessage_TradingPartnerID",
    "EDIMessage_DirectionCode",
    "EDIMessage_MessageTypeCode",
    "EDIMessage_StandardCode",
    "EDIMessage_StatusCode",
    "EDIMessage_AcknowledgementStatusCode",
    "EDIMessage_DocumentReference",
    "EDIMessage_JobID",
    "EDIMessage_RawPayloadText",
    "EDIMessage_CanonicalJSON",
    "EDIMessage_GeneratedFromTable",
    "EDIMessage_GeneratedFromID",
    "EDIMessage_AckDueAt",
    "EDIMessage_CreatedBy"
  )
  VALUES (
    v_profile."EDIMP_ID",
    v_profile."EDIMP_ConnectionID",
    v_profile."EDIMP_TradingPartnerID",
    'outbound',
    v_profile."EDIMP_MessageTypeCode",
    v_profile."EDIMP_StandardCode",
    'queued',
    v_ack_status,
    p_document_reference,
    p_job_id,
    p_payload_text,
    COALESCE(p_payload_json, '{}'::jsonb),
    p_generated_from_table,
    p_generated_from_id,
    CASE
      WHEN v_profile."EDIMP_RequiresAcknowledgement" AND v_profile."EDIMP_AcknowledgementDueMinutes" IS NOT NULL
      THEN now() + make_interval(mins => v_profile."EDIMP_AcknowledgementDueMinutes")
      ELSE NULL
    END,
    p_created_by
  )
  RETURNING "EDIMessage_ID" INTO v_message_id;

  INSERT INTO public."EDI_OutboundQueue" (
    "EDIOutQ_MessageID",
    "EDIOutQ_MessageProfileID",
    "EDIOutQ_ConnectionID",
    "EDIOutQ_StatusCode"
  )
  VALUES (
    v_message_id,
    v_profile."EDIMP_ID",
    v_profile."EDIMP_ConnectionID",
    'queued'
  );

  INSERT INTO public."EDI_ProcessingEvents" (
    "EDIEvent_MessageID",
    "EDIEvent_EventTypeCode",
    "EDIEvent_StatusCode",
    "EDIEvent_EventText",
    "EDIEvent_CreatedBy"
  )
  VALUES (
    v_message_id,
    'queued',
    'queued',
    'Outbound EDI message queued.',
    p_created_by
  );

  RETURN v_message_id;
END;
$$;


ALTER FUNCTION "public"."EDI_QueueOutboundMessage"("p_message_profile_id" "uuid", "p_job_id" "uuid", "p_generated_from_table" character varying, "p_generated_from_id" "uuid", "p_document_reference" character varying, "p_payload_json" "jsonb", "p_payload_text" "text", "p_created_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."EDI_RecordAcknowledgement"("p_original_message_id" "uuid", "p_ack_type_code" character varying, "p_ack_status_code" character varying, "p_direction_code" character varying DEFAULT 'inbound'::character varying, "p_control_number" character varying DEFAULT NULL::character varying, "p_response_code" character varying DEFAULT NULL::character varying, "p_response_text" "text" DEFAULT NULL::"text", "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_ack_id uuid;
BEGIN
  INSERT INTO public."EDI_Acknowledgements" (
    "EDIAck_OriginalMessageID",
    "EDIAck_AcknowledgementTypeCode",
    "EDIAck_StatusCode",
    "EDIAck_DirectionCode",
    "EDIAck_ControlNumber",
    "EDIAck_ResponseCode",
    "EDIAck_ResponseText",
    "EDIAck_ReceivedAt",
    "EDIAck_SentAt",
    "EDIAck_CreatedBy"
  )
  VALUES (
    p_original_message_id,
    p_ack_type_code,
    p_ack_status_code,
    p_direction_code,
    p_control_number,
    p_response_code,
    p_response_text,
    CASE WHEN p_direction_code = 'inbound' THEN now() ELSE NULL END,
    CASE WHEN p_direction_code = 'outbound' THEN now() ELSE NULL END,
    p_created_by
  )
  RETURNING "EDIAck_ID" INTO v_ack_id;

  UPDATE public."EDI_Messages"
  SET "EDIMessage_AcknowledgementStatusCode" = p_ack_status_code,
      "EDIMessage_StatusCode" = CASE
        WHEN p_ack_status_code IN ('accepted', 'accepted_with_errors') THEN 'acknowledged'
        WHEN p_ack_status_code = 'rejected' THEN 'rejected'
        ELSE "EDIMessage_StatusCode"
      END,
      "EDIMessage_UpdatedAt" = now(),
      "EDIMessage_UpdatedBy" = p_created_by
  WHERE "EDIMessage_ID" = p_original_message_id;

  INSERT INTO public."EDI_ProcessingEvents" (
    "EDIEvent_MessageID",
    "EDIEvent_EventTypeCode",
    "EDIEvent_StatusCode",
    "EDIEvent_EventText",
    "EDIEvent_CreatedBy"
  )
  VALUES (
    p_original_message_id,
    'acknowledged',
    CASE WHEN p_ack_status_code = 'rejected' THEN 'rejected' ELSE 'acknowledged' END,
    COALESCE(p_response_text, 'EDI acknowledgement recorded.'),
    p_created_by
  );

  RETURN v_ack_id;
END;
$$;


ALTER FUNCTION "public"."EDI_RecordAcknowledgement"("p_original_message_id" "uuid", "p_ack_type_code" character varying, "p_ack_status_code" character varying, "p_direction_code" character varying, "p_control_number" character varying, "p_response_code" character varying, "p_response_text" "text", "p_created_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."EDI_RecordValidationIssue"("p_message_id" "uuid", "p_severity_code" character varying, "p_issue_code" character varying, "p_description" "text", "p_field_path" "text" DEFAULT NULL::"text", "p_segment_ref" character varying DEFAULT NULL::character varying, "p_suggested_fix" "text" DEFAULT NULL::"text", "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_issue_id uuid;
  v_is_blocking boolean;
BEGIN
  SELECT "EDIVS_IsBlocking"
  INTO v_is_blocking
  FROM public."sys_EDIValidationSeverities"
  WHERE "EDIVS_Code" = p_severity_code;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'EDI validation severity % was not found.', p_severity_code;
  END IF;

  INSERT INTO public."EDI_ValidationIssues" (
    "EDIVI_MessageID",
    "EDIVI_SeverityCode",
    "EDIVI_IssueCode",
    "EDIVI_FieldPath",
    "EDIVI_SegmentRef",
    "EDIVI_Description",
    "EDIVI_SuggestedFix",
    "EDIVI_IsBlocking",
    "EDIVI_CreatedBy"
  )
  VALUES (
    p_message_id,
    p_severity_code,
    p_issue_code,
    p_field_path,
    p_segment_ref,
    p_description,
    p_suggested_fix,
    v_is_blocking,
    p_created_by
  )
  RETURNING "EDIVI_ID" INTO v_issue_id;

  IF v_is_blocking THEN
    UPDATE public."EDI_Messages"
    SET "EDIMessage_StatusCode" = 'failed',
        "EDIMessage_LastErrorText" = p_description,
        "EDIMessage_UpdatedAt" = now(),
        "EDIMessage_UpdatedBy" = p_created_by
    WHERE "EDIMessage_ID" = p_message_id;
  END IF;

  INSERT INTO public."EDI_ProcessingEvents" (
    "EDIEvent_MessageID",
    "EDIEvent_EventTypeCode",
    "EDIEvent_StatusCode",
    "EDIEvent_EventText",
    "EDIEvent_CreatedBy"
  )
  VALUES (
    p_message_id,
    CASE WHEN v_is_blocking THEN 'error' ELSE 'validated' END,
    CASE WHEN v_is_blocking THEN 'failed' ELSE 'validated' END,
    p_description,
    p_created_by
  );

  RETURN v_issue_id;
END;
$$;


ALTER FUNCTION "public"."EDI_RecordValidationIssue"("p_message_id" "uuid", "p_severity_code" character varying, "p_issue_code" character varying, "p_description" "text", "p_field_path" "text", "p_segment_ref" character varying, "p_suggested_fix" "text", "p_created_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."EDI_RegisterInboundMessage"("p_connection_id" "uuid", "p_message_type_code" character varying, "p_standard_code" character varying, "p_payload_text" "text" DEFAULT NULL::"text", "p_file_name" character varying DEFAULT NULL::character varying, "p_control_number" character varying DEFAULT NULL::character varying, "p_received_at" timestamp with time zone DEFAULT "now"(), "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_connection record;
  v_profile_id uuid;
  v_batch_id uuid;
  v_message_id uuid;
BEGIN
  SELECT *
  INTO v_connection
  FROM public."EDI_Connections"
  WHERE "EDIC_ID" = p_connection_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'EDI connection % was not found.', p_connection_id;
  END IF;

  SELECT "EDIMP_ID"
  INTO v_profile_id
  FROM public."EDI_MessageProfiles"
  WHERE "EDIMP_ConnectionID" = p_connection_id
    AND "EDIMP_MessageTypeCode" = p_message_type_code
    AND "EDIMP_StandardCode" = p_standard_code
    AND "EDIMP_DirectionCode" IN ('inbound', 'bidirectional')
    AND "EDIMP_IsActive" = true
  ORDER BY "EDIMP_CreatedAt" DESC
  LIMIT 1;

  INSERT INTO public."EDI_Batches" (
    "EDIBatch_ConnectionID",
    "EDIBatch_TradingPartnerID",
    "EDIBatch_DirectionCode",
    "EDIBatch_StandardCode",
    "EDIBatch_StatusCode",
    "EDIBatch_InterchangeControlNumber",
    "EDIBatch_FileName",
    "EDIBatch_PayloadStorageTypeCode",
    "EDIBatch_ReceivedAt",
    "EDIBatch_MessageCount",
    "EDIBatch_CreatedBy"
  )
  VALUES (
    p_connection_id,
    v_connection."EDIC_TradingPartnerID",
    'inbound',
    p_standard_code,
    'received',
    p_control_number,
    p_file_name,
    'database_text',
    COALESCE(p_received_at, now()),
    1,
    p_created_by
  )
  RETURNING "EDIBatch_ID" INTO v_batch_id;

  INSERT INTO public."EDI_Messages" (
    "EDIMessage_BatchID",
    "EDIMessage_MessageProfileID",
    "EDIMessage_ConnectionID",
    "EDIMessage_TradingPartnerID",
    "EDIMessage_DirectionCode",
    "EDIMessage_MessageTypeCode",
    "EDIMessage_StandardCode",
    "EDIMessage_StatusCode",
    "EDIMessage_AcknowledgementStatusCode",
    "EDIMessage_ControlNumber",
    "EDIMessage_RawPayloadText",
    "EDIMessage_ReceivedAt",
    "EDIMessage_CreatedBy"
  )
  VALUES (
    v_batch_id,
    v_profile_id,
    p_connection_id,
    v_connection."EDIC_TradingPartnerID",
    'inbound',
    p_message_type_code,
    p_standard_code,
    'received',
    'not_required',
    p_control_number,
    p_payload_text,
    COALESCE(p_received_at, now()),
    p_created_by
  )
  RETURNING "EDIMessage_ID" INTO v_message_id;

  INSERT INTO public."EDI_InboundQueue" (
    "EDIInQ_ConnectionID",
    "EDIInQ_BatchID",
    "EDIInQ_MessageID",
    "EDIInQ_StatusCode",
    "EDIInQ_SourceFileName",
    "EDIInQ_RawPayloadText",
    "EDIInQ_ReceivedAt"
  )
  VALUES (
    p_connection_id,
    v_batch_id,
    v_message_id,
    'received',
    p_file_name,
    p_payload_text,
    COALESCE(p_received_at, now())
  );

  INSERT INTO public."EDI_ProcessingEvents" (
    "EDIEvent_MessageID",
    "EDIEvent_BatchID",
    "EDIEvent_EventTypeCode",
    "EDIEvent_StatusCode",
    "EDIEvent_EventText",
    "EDIEvent_CreatedBy"
  )
  VALUES (
    v_message_id,
    v_batch_id,
    'received',
    'received',
    'Inbound EDI message registered.',
    p_created_by
  );

  RETURN v_message_id;
END;
$$;


ALTER FUNCTION "public"."EDI_RegisterInboundMessage"("p_connection_id" "uuid", "p_message_type_code" character varying, "p_standard_code" character varying, "p_payload_text" "text", "p_file_name" character varying, "p_control_number" character varying, "p_received_at" timestamp with time zone, "p_created_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."FIN_CalculatePulledRate"("p_base_rate" numeric, "p_adjustment_method_code" "text", "p_adjustment_amount" numeric DEFAULT 0, "p_adjustment_percent" numeric DEFAULT 0, "p_rounding_precision" integer DEFAULT 6) RETURNS numeric
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_method text := coalesce(lower(p_adjustment_method_code), 'none');
  v_rate numeric;
BEGIN
  IF p_base_rate IS NULL THEN
    RETURN NULL;
  END IF;

  v_rate := CASE v_method
    WHEN 'amount_add' THEN p_base_rate + coalesce(p_adjustment_amount, 0)
    WHEN 'amount_subtract' THEN p_base_rate - coalesce(p_adjustment_amount, 0)
    WHEN 'percent_add' THEN p_base_rate * (1 + coalesce(p_adjustment_percent, 0) / 100)
    WHEN 'percent_subtract' THEN p_base_rate * (1 - coalesce(p_adjustment_percent, 0) / 100)
    WHEN 'spread_buy_sell' THEN p_base_rate + coalesce(p_adjustment_amount, 0) + (p_base_rate * coalesce(p_adjustment_percent, 0) / 100)
    ELSE p_base_rate
  END;

  RETURN round(v_rate, greatest(coalesce(p_rounding_precision, 6), 0));
END;
$$;


ALTER FUNCTION "public"."FIN_CalculatePulledRate"("p_base_rate" numeric, "p_adjustment_method_code" "text", "p_adjustment_amount" numeric, "p_adjustment_percent" numeric, "p_rounding_precision" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."FIN_GetNextOpenPeriod"("p_legal_entity_id" "uuid", "p_org_office_id" "uuid", "p_ledger_type_code" "text", "p_accounting_date" "date") RETURNS "uuid"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  SELECT p."FINPeriod_ID"
  FROM public."FIN_Periods" p
  WHERE p."FINPeriod_StatusCode" = 'open'
    AND (p_legal_entity_id IS NULL OR p."FINPeriod_LegalEntityID" IS NULL OR p."FINPeriod_LegalEntityID" = p_legal_entity_id)
    AND (p_org_office_id IS NULL OR p."FINPeriod_OrgOfficeID" IS NULL OR p."FINPeriod_OrgOfficeID" = p_org_office_id)
    AND p."FINPeriod_EndDate" >= coalesce(p_accounting_date, current_date)
  ORDER BY
    CASE WHEN coalesce(p_accounting_date, current_date) BETWEEN p."FINPeriod_StartDate" AND p."FINPeriod_EndDate" THEN 0 ELSE 1 END,
    p."FINPeriod_StartDate"
  LIMIT 1;
$$;


ALTER FUNCTION "public"."FIN_GetNextOpenPeriod"("p_legal_entity_id" "uuid", "p_org_office_id" "uuid", "p_ledger_type_code" "text", "p_accounting_date" "date") OWNER TO "postgres";


