CREATE OR REPLACE FUNCTION "public"."RATE_CreateRateRequest"("p_code" character varying, "p_customer_org_id" "uuid" DEFAULT NULL::"uuid", "p_carrier_org_id" "uuid" DEFAULT NULL::"uuid", "p_job_id" "uuid" DEFAULT NULL::"uuid", "p_cus_quote_rev_id" "uuid" DEFAULT NULL::"uuid", "p_mode_code" character varying DEFAULT NULL::character varying, "p_shipment_type_code" character varying DEFAULT NULL::character varying, "p_direction_code" character varying DEFAULT 'any'::character varying, "p_origin_unlocode" character varying DEFAULT NULL::character varying, "p_destination_unlocode" character varying DEFAULT NULL::character varying, "p_currency_code" character varying DEFAULT NULL::character varying, "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_request_id uuid;
BEGIN
  INSERT INTO public."RATE_RateRequests" (
    "RATERequest_Code",
    "RATERequest_StatusCode",
    "RATERequest_CustomerOrgID",
    "RATERequest_CarrierOrgID",
    "RATERequest_JobID",
    "RATERequest_CusQuoteRevID",
    "RATERequest_ModeCode",
    "RATERequest_ShipmentTypeCode",
    "RATERequest_DirectionCode",
    "RATERequest_OriginUNLocode",
    "RATERequest_DestinationUNLocode",
    "RATERequest_CurrencyCodeSnapshot",
    "RATERequest_CreatedBy"
  ) VALUES (
    p_code,
    'draft',
    p_customer_org_id,
    p_carrier_org_id,
    p_job_id,
    p_cus_quote_rev_id,
    p_mode_code,
    p_shipment_type_code,
    COALESCE(p_direction_code, 'any'),
    p_origin_unlocode,
    p_destination_unlocode,
    p_currency_code,
    p_created_by
  )
  RETURNING "RATERequest_ID" INTO v_request_id;

  PERFORM public."RATE_RecordAuditEvent"(
    'rate_request_created',
    'RATE_RateRequests',
    v_request_id,
    NULL,
    v_request_id,
    NULL,
    'Rate request created',
    '{}'::jsonb,
    p_created_by
  );

  RETURN v_request_id;
END;
$$;


