CREATE OR REPLACE FUNCTION "public"."RPT_RecordKPIResult"("p_kpi_code" "text", "p_period_start" "date", "p_period_end" "date", "p_value" numeric, "p_target_value" numeric DEFAULT NULL::numeric, "p_org_office_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  kpi_id uuid;
  result_id uuid;
BEGIN
  SELECT "RPTKPI_ID"
  INTO kpi_id
  FROM public."RPT_KPIs"
  WHERE "RPTKPI_Code" = p_kpi_code;

  IF kpi_id IS NULL THEN
    RAISE EXCEPTION 'Unknown KPI code: %', p_kpi_code;
  END IF;

  INSERT INTO public."RPT_KPIResults" (
    "RPTKPIResult_KPIID",
    "RPTKPIResult_OrgOfficeID",
    "RPTKPIResult_PeriodStartDate",
    "RPTKPIResult_PeriodEndDate",
    "RPTKPIResult_Value",
    "RPTKPIResult_TargetValue"
  )
  VALUES (
    kpi_id,
    p_org_office_id,
    p_period_start,
    p_period_end,
    p_value,
    p_target_value
  )
  ON CONFLICT (
    "RPTKPIResult_KPIID",
    "RPTKPIResult_OrgOfficeID",
    "RPTKPIResult_LegalEntityID",
    "RPTKPIResult_BrandID",
    "RPTKPIResult_PeriodStartDate",
    "RPTKPIResult_PeriodEndDate"
  ) DO UPDATE SET
    "RPTKPIResult_Value" = EXCLUDED."RPTKPIResult_Value",
    "RPTKPIResult_TargetValue" = EXCLUDED."RPTKPIResult_TargetValue",
    "RPTKPIResult_CalculatedAt" = now()
  RETURNING "RPTKPIResult_ID" INTO result_id;

  RETURN result_id;
END;
$$;


