CREATE OR REPLACE FUNCTION "public"."_crm_drive_enqueue_cleanup"("p_company_id" "uuid", "p_user_id" "uuid", "p_paths" "text"[]) RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  insert into public."CRM_DriveObjectCleanupQueue"(
    "Company_ID", "DriveCleanup_Path", "DriveCleanup_RequestedBy"
  )
  select p_company_id, path, p_user_id
  from unnest(coalesce(p_paths, array[]::text[])) path
  where nullif(btrim(path), '') is not null
    and path like p_company_id::text || '/%'
  on conflict ("Company_ID", "DriveCleanup_Path") do update set
    "DriveCleanup_RequestedAt" = now(),
    "DriveCleanup_RequestedBy" = excluded."DriveCleanup_RequestedBy",
    "DriveCleanup_CleanedAt" = null
$$;


ALTER FUNCTION "public"."_crm_drive_enqueue_cleanup"("p_company_id" "uuid", "p_user_id" "uuid", "p_paths" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_crm_drive_file_path_allowed"("p_file_id" "uuid", "p_path" "text", "p_thumbnail" boolean) RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
  select p_file_id is not null
    and p_path is not null
    and p_path ~ (
      '^' || case when p_thumbnail then '.*/thumbs/' else '.*/files/' end
      || p_file_id::text
      || case when p_thumbnail then '\\.webp$' else '\\.[a-z0-9]{1,8}$' end
    );
$_$;


ALTER FUNCTION "public"."_crm_drive_file_path_allowed"("p_file_id" "uuid", "p_path" "text", "p_thumbnail" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_crm_drive_file_path_allowed_v2"("p_file_id" "uuid", "p_path" "text", "p_thumbnail" boolean) RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
  select p_file_id is not null
    and p_path is not null
    and case when p_thumbnail then
      split_part(p_path, '/', 2) = 'thumbs'
      and split_part(p_path, '/', 3) = p_file_id::text || '.webp'
    else
      split_part(p_path, '/', 2) = 'files'
      and split_part(p_path, '/', 3) like p_file_id::text || '.%'
      and substring(split_part(p_path, '/', 3) from length(p_file_id::text) + 2) ~ '^[a-z0-9]{1,8}$'
    end;
$_$;


ALTER FUNCTION "public"."_crm_drive_file_path_allowed_v2"("p_file_id" "uuid", "p_path" "text", "p_thumbnail" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_crm_drive_has_permission"("p_permission" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
  select exists (
    select 1
    from public."cmp_Users" as workspace_user
    join public."cmp_Users_Roles" as user_role
      on user_role."User_ID" = workspace_user."User_ID"
    join public."sys_UserRole_Permissions" as role_permission
      on role_permission."sys_UserRole_ID" = user_role."sys_UserRole_ID"
    join public."sys_Permissions" as permission
      on permission."sys_Permission_ID" = role_permission."sys_Permission_ID"
    where workspace_user."User_ID" = public.app_current_workspace_user_id()
      and coalesce(workspace_user."User_AccessStatus", 'active') = 'active'
      and permission."sys_Permission_Value" = p_permission
  );
$$;


ALTER FUNCTION "public"."_crm_drive_has_permission"("p_permission" "text") OWNER TO "postgres";


