CREATE OR REPLACE FUNCTION "public"."_crm_drive_touch"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if tg_table_name = 'CRM_DriveFolders' then
    new."DriveFolder_UpdatedAt" := now();
    new."Company_ID" := old."Company_ID";
  else
    new."DriveFile_UpdatedAt" := now();
    new."Company_ID" := old."Company_ID";
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."_crm_drive_touch"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_crm_drive_watch_signal"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_company_id uuid;
  v_source_id uuid;
  v_folder_id uuid;
  v_old jsonb := '{}'::jsonb;
  v_new jsonb := '{}'::jsonb;
begin
  if tg_table_name = 'CRM_DriveFiles' then
    if tg_op = 'INSERT' then
      v_company_id := new."Company_ID";
      v_source_id := new."DriveFile_ID";
      v_folder_id := new."DriveFile_FolderID";
      v_new := jsonb_build_object(
        'changeType', 'file_added',
        'fileName', new."DriveFile_Name",
        'mimeType', new."DriveFile_MimeType",
        'sizeBytes', new."DriveFile_SizeBytes"
      );
    else
      v_company_id := old."Company_ID";
      v_source_id := old."DriveFile_ID";
      v_folder_id := old."DriveFile_FolderID";
      v_old := jsonb_build_object('fileName', old."DriveFile_Name");
      v_new := jsonb_build_object('changeType', 'file_removed', 'fileName', old."DriveFile_Name");
    end if;
  else
    v_company_id := new."Company_ID";
    v_source_id := new."DriveFolder_ID";
    v_folder_id := new."DriveFolder_ID";
    v_new := jsonb_build_object('changeType', 'folder_added', 'folderName', new."DriveFolder_Name");
  end if;

  if v_company_id is not null and exists (
    select 1 from public."AI_DexterWatches" as watch
    where watch."AIDexterWatch_CompanyID" = v_company_id
      and watch."AIDexterWatch_CapabilityCode" = 'drive'
      and watch."AIDexterWatch_StatusCode" = 'active'
      and (watch."AIDexterWatch_TargetID" is null or watch."AIDexterWatch_TargetID" = v_folder_id)
  ) then
    insert into public."AI_DexterWatchSignals" (
      "AIDexterWatchSignal_CompanyID",
      "AIDexterWatchSignal_CapabilityCode",
      "AIDexterWatchSignal_SourceTable",
      "AIDexterWatchSignal_SourceID",
      "AIDexterWatchSignal_OldJSON",
      "AIDexterWatchSignal_NewJSON"
    )
    values (
      v_company_id,
      'drive',
      tg_table_name,
      v_source_id,
      v_old,
      v_new
        || jsonb_build_object(
             'folderId', v_folder_id,
             'folderName', coalesce(
               (select folder."DriveFolder_Name" from public."CRM_DriveFolders" as folder where folder."DriveFolder_ID" = v_folder_id),
               'Drive root'
             )
           )
    );
  end if;

  return null;
end;
$$;


ALTER FUNCTION "public"."_crm_drive_watch_signal"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_dexter_calendar_window"("p_search" "text") RETURNS TABLE("starts_at" timestamp with time zone, "ends_at" timestamp with time zone)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pg_catalog'
    AS $_$
 select case when btrim(p_search) ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}(@[A-Za-z_]+(/[A-Za-z0-9_+-]+)*)?$' then split_part(btrim(p_search),'@',1)::date::timestamp at time zone coalesce(nullif(split_part(btrim(p_search),'@',2),''),'UTC') end,
 case when btrim(p_search) ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}(@[A-Za-z_]+(/[A-Za-z0-9_+-]+)*)?$' then (split_part(btrim(p_search),'@',1)::date+1)::timestamp at time zone coalesce(nullif(split_part(btrim(p_search),'@',2),''),'UTC') end;
$_$;


ALTER FUNCTION "public"."_dexter_calendar_window"("p_search" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_dexter_task_action_completed"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare a public."AI_DexterTaskAssignments"; metadata jsonb; ids jsonb;
begin
 if new."AIDexterPrepared_Status"<>'succeeded' then return new;end if;
 select * into a from public."AI_DexterTaskAssignments" where conversation_id=new."AIDexterPrepared_ConversationID" and owner_id=new."AIDexterPrepared_UserID" and company_id=new."AIDexterPrepared_CompanyID" and status='ready' for update;
 if not found then return new;end if;
 select "AIMSG_ContentJSON"->'metadata' into metadata from public."AI_Messages" where "AIMSG_ID"=a.message_id;
 if a.outcome='send_email' then
  if new."AIDexterPrepared_ActionCode"<>'send_email' or new."AIDexterPrepared_ResultJSON"->'emailDraft'->'delivery'->>'status' is distinct from 'sent'
   or metadata->'emailDraft'->>'id' is null or new."AIDexterPrepared_ArgumentsJSON"->'draft'->>'id' is distinct from metadata->'emailDraft'->>'id' then return new;end if;
 elsif a.outcome='apply_changes' then
  ids:=metadata->'pendingActions';
  if jsonb_typeof(ids) is distinct from 'array' or jsonb_array_length(ids)=0 then return new;end if;
  if exists(select 1 from jsonb_array_elements(ids) item left join public."AI_DexterPreparedActions" p on p."AIDexterPrepared_ID"::text=item->>'id' and p."AIDexterPrepared_UserID"=a.owner_id and p."AIDexterPrepared_CompanyID"=a.company_id and p."AIDexterPrepared_ConversationID"=a.conversation_id where p."AIDexterPrepared_Status" is distinct from 'succeeded') then return new;end if;
 else return new;end if;
 perform public._multideck_todo_update_for_actor(a.company_id,a.owner_id,a.task_id,'{"status":"completed"}');
 update public."AI_DexterTaskAssignments" set summary=case when a.outcome='send_email' then 'The mail provider confirmed the reply was sent' else 'All prepared changes were saved' end,viewed_revision=result_revision,updated_at=now() where id=a.id;
 return new;
end $$;


ALTER FUNCTION "public"."_dexter_task_action_completed"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_dexter_task_changed"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
 if new."TodoTask_StatusCode"='completed' or new."TodoTask_IsDeleted" then
  update public."AI_DexterTaskRuns" set state='cancelled',lease_token=null,lease_until=null where assignment_id in(select id from public."AI_DexterTaskAssignments" where task_id=new."TodoTask_ID") and state in ('queued','running');
  update public."AI_DexterWatches" set "AIDexterWatch_StatusCode"='paused' where "AIDexterWatch_ID" in(select watch_id from public."AI_DexterTaskAssignments" where task_id=new."TodoTask_ID");
  update public."AI_DexterTaskAssignments" set status=case when new."TodoTask_IsDeleted" then 'cancelled' else 'completed' end,version=version+1 where task_id=new."TodoTask_ID";
  if new."TodoTask_IsDeleted" then
   update public."AI_Conversations" set "AICNV_Status"='closed',"AICNV_EndedAt"=clock_timestamp(),"AICNV_UpdatedAt"=clock_timestamp(),"AICNV_UpdatedBy"=new."TodoTask_OwnerUserID"
   where "AICNV_ID" in(select conversation_id from public."AI_DexterTaskAssignments" where task_id=new."TodoTask_ID") and "AICNV_EndedAt" is null;
  end if;
 end if;
 return new;
end $$;


ALTER FUNCTION "public"."_dexter_task_changed"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_dexter_task_conversation_closing"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
 if new."AICNV_EndedAt" is not null and old."AICNV_EndedAt" is null and exists(
  select 1 from public."AI_DexterTaskAssignments" a join public."OPS_UserTasks" t on t."TodoTask_ID"=a.task_id
  where a.conversation_id=new."AICNV_ID" and not t."TodoTask_IsDeleted"
 ) then raise exception 'This conversation belongs to a task. Delete the task in Tasks to remove it and stop its background work.' using errcode='55000';end if;
 return new;
end $$;


ALTER FUNCTION "public"."_dexter_task_conversation_closing"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_dexter_task_icons"("p_owner" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare a record; used integer[]:='{}'; chosen integer;
begin
 perform pg_advisory_xact_lock(hashtextextended('dexter-tasks:'||p_owner,0));
 -- Reserve icons for working agents and the three visible unread results, not the archive.
 for a in select * from public."AI_DexterTaskAssignments" where owner_id=p_owner and
 (status='working' or id in (select id from public."AI_DexterTaskAssignments" where owner_id=p_owner
 and result_revision>viewed_revision and status in ('ready','needs_input','failed','completed')
 order by case when status in ('needs_input','failed') then 0 else 1 end,updated_at desc,id limit 3))
 order by case when status='working' then 0 else 1 end,created_at,id loop
  chosen:=a.icon;
  if chosen is null or chosen=any(used) then
   select i into chosen from generate_series(0,8) i where not(i=any(used)) order by random() limit 1;
   update public."AI_DexterTaskAssignments" set icon=chosen where id=a.id;
  end if;
  used:=array_append(used,chosen);
 end loop;
end $$;


ALTER FUNCTION "public"."_dexter_task_icons"("p_owner" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_dexter_task_kick"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare endpoint text; secret text;
begin
 select s.endpoint into endpoint from public."AI_DexterTaskSettings" s where s.enabled;
 if endpoint is null then return;end if;
 select decrypted_secret into secret from vault.decrypted_secrets where name='multideck_task_worker_secret' limit 1;
 if secret is null then return;end if;
 perform net.http_post(url:=endpoint,headers:=jsonb_build_object('Content-Type','application/json','x-multideck-task-secret',secret),body:='{}'::jsonb,timeout_milliseconds:=5000);
end $$;


ALTER FUNCTION "public"."_dexter_task_kick"() OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."AI_DexterTaskAssignments" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "task_id" "uuid" NOT NULL,
    "owner_id" "uuid" NOT NULL,
    "company_id" "uuid" NOT NULL,
    "conversation_id" "uuid" NOT NULL,
    "name" "text" DEFAULT 'Dexter'::"text" NOT NULL,
    "icon" integer,
    "instruction" "text" NOT NULL,
    "time_zone" "text" DEFAULT 'Europe/London'::"text" NOT NULL,
    "status" "text" DEFAULT 'queued'::"text" NOT NULL,
    "summary" "text" DEFAULT 'Queued for Dexter'::"text" NOT NULL,
    "outcome" "text",
    "watch_id" "uuid",
    "result_revision" integer DEFAULT 0 NOT NULL,
    "viewed_revision" integer DEFAULT 0 NOT NULL,
    "message_id" "uuid",
    "version" integer DEFAULT 1 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "AI_DexterTaskAssignments_icon_check" CHECK ((("icon" >= 0) AND ("icon" <= 8))),
    CONSTRAINT "AI_DexterTaskAssignments_instruction_check" CHECK ((("length"("instruction") >= 1) AND ("length"("instruction") <= 8000))),
    CONSTRAINT "AI_DexterTaskAssignments_outcome_check" CHECK (("outcome" = ANY (ARRAY['deliver_result'::"text", 'send_email'::"text", 'apply_changes'::"text"]))),
    CONSTRAINT "AI_DexterTaskAssignments_status_check" CHECK (("status" = ANY (ARRAY['queued'::"text", 'scheduled'::"text", 'waiting'::"text", 'working'::"text", 'ready'::"text", 'needs_input'::"text", 'failed'::"text", 'cancelled'::"text", 'completed'::"text"])))
);


ALTER TABLE "public"."AI_DexterTaskAssignments" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_dexter_task_lease"("p_run" "uuid", "p_token" "uuid") RETURNS "public"."AI_DexterTaskAssignments"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare a public."AI_DexterTaskAssignments";
begin
 if auth.role() is distinct from 'service_role' then raise exception 'Worker only.' using errcode='42501';end if;
 select assignment.* into a from public."AI_DexterTaskAssignments" assignment join public."AI_DexterTaskRuns" r on r.assignment_id=assignment.id
 join public."cmp_Users" u on u."User_ID"=assignment.owner_id and u."Company_ID"=assignment.company_id and coalesce(u."User_AccessStatus",'active')='active'
 join public."OPS_UserTasks" t on t."TodoTask_ID"=assignment.task_id and not t."TodoTask_IsDeleted" and t."TodoTask_StatusCode"='open'
 where r.id=p_run and r.lease_token=p_token and r.state='running' and r.lease_until>now() and assignment.status='working';
 if not found then raise exception 'This task lease is unavailable.' using errcode='42501';end if;
 return a;
end $$;


ALTER FUNCTION "public"."_dexter_task_lease"("p_run" "uuid", "p_token" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_dexter_task_notification"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
 if new."CommNotif_TargetTable"='AI_DexterWatches' and exists(select 1 from public."AI_DexterTaskAssignments" where watch_id=new."CommNotif_TargetID" and owner_id=new."CommNotif_UserID") then return null;end if;
 return new;
end $$;


ALTER FUNCTION "public"."_dexter_task_notification"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_dexter_task_signal"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
 if old.status is not distinct from new.status and old.name is not distinct from new.name then return new;end if;
 if exists(select 1 from public."AI_DexterWatches" where "AIDexterWatch_CapabilityCode"='todo' and "AIDexterWatch_TargetID"=new.task_id and "AIDexterWatch_OwnerUserID"=new.owner_id and "AIDexterWatch_StatusCode"='active') then
  insert into public."AI_DexterWatchSignals"("AIDexterWatchSignal_CompanyID","AIDexterWatchSignal_CapabilityCode","AIDexterWatchSignal_SourceTable","AIDexterWatchSignal_SourceID","AIDexterWatchSignal_OldJSON","AIDexterWatchSignal_NewJSON") values(new.company_id,'todo','OPS_UserTasks',new.task_id,jsonb_build_object('agentStatus',old.status,'agentName',old.name,'ownerUserId',new.owner_id),jsonb_build_object('agentStatus',new.status,'agentName',new.name,'ownerUserId',new.owner_id));
 end if;
 return new;
end $$;


ALTER FUNCTION "public"."_dexter_task_signal"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_dexter_task_watch_fired"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare a public."AI_DexterTaskAssignments";
begin
 select * into a from public."AI_DexterTaskAssignments" where watch_id=new."AIDexterWatchEvent_WatchID" and owner_id=new."AIDexterWatchEvent_OwnerUserID" and status='waiting' for update;
 if found then
  insert into public."AI_DexterTaskRuns"(assignment_id,input,phase) values(a.id,a.instruction,'execute') on conflict do nothing;
  update public."AI_DexterTaskAssignments" set status='queued',summary='The event arrived. Queued for Dexter',version=version+1,updated_at=now() where id=a.id;
  update public."AI_DexterWatches" set "AIDexterWatch_StatusCode"='paused' where "AIDexterWatch_ID"=a.watch_id;
  perform public._dexter_task_kick();
 end if;
 return new;
end $$;


ALTER FUNCTION "public"."_dexter_task_watch_fired"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_add_lifecycle_note"("p_auth_user_id" "uuid", "p_subject_type" "text", "p_subject_id" "uuid", "p_body" "text", "p_mentions" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth', 'booking_api', 'quote_api'
    AS $$
declare
  v_context record;
  v_note public."OPS_LifecycleNotes";
  v_mention jsonb;
  v_target_id uuid;
  v_target_type text;
  v_label text;
  v_mentions jsonb;
  v_body text := btrim(coalesce(p_body, ''));
  v_action_url text;
  v_target_table text;
  v_direction text;
begin
  select * into strict v_context
  from public._multideck_lifecycle_note_context(p_auth_user_id, p_subject_type, p_subject_id, true);

  if v_body = '' then
    raise exception 'Write a note before adding it.' using errcode = '22023';
  end if;
  if char_length(v_body) > 4000 then
    raise exception 'Keep the note to 4,000 characters or fewer.' using errcode = '22023';
  end if;
  if jsonb_typeof(coalesce(p_mentions, '[]'::jsonb)) <> 'array' then
    raise exception 'Note mentions must be a list.' using errcode = '22023';
  end if;
  if jsonb_array_length(coalesce(p_mentions, '[]'::jsonb)) > 20 then
    raise exception 'Tag up to 20 people or departments in one note.' using errcode = '22023';
  end if;

  perform set_config('app.user_id', v_context.actor_user_id::text, true);
  perform set_config('app.auth_user_id', p_auth_user_id::text, true);
  perform set_config('app.actor_type', 'user', true);
  perform set_config('app.source_app', 'Multideck App', true);
  perform set_config('app.source_module', 'lifecycle_notes', true);

  insert into public."OPS_LifecycleNotes" (
    "LifecycleNote_CompanyID", "LifecycleNote_SubjectType", "LifecycleNote_SubjectID",
    "LifecycleNote_QuoteID", "LifecycleNote_JobID", "LifecycleNote_CustomsID",
    "LifecycleNote_Body", "LifecycleNote_AuthorUserID", "LifecycleNote_AuthorNameSnapshot"
  )
  select
    v_context.company_id, lower(btrim(p_subject_type)), p_subject_id,
    v_context.quote_id, v_context.job_id, v_context.customs_id,
    v_body, v_context.actor_user_id,
    coalesce(nullif(btrim(concat_ws(' ', actor."User_Firstname", actor."User_Lastname")), ''), actor."User_Email")
  from public."cmp_Users" actor
  where actor."User_ID" = v_context.actor_user_id
  returning * into v_note;

  for v_mention in select value from jsonb_array_elements(coalesce(p_mentions, '[]'::jsonb)) value loop
    v_target_type := lower(btrim(coalesce(v_mention->>'type', '')));
    begin
      v_target_id := nullif(v_mention->>'id', '')::uuid;
    exception when invalid_text_representation then
      raise exception 'One of the note tags is invalid.' using errcode = '22023';
    end;

    if v_target_type = 'user' then
      select coalesce(
        nullif(btrim(concat_ws(' ', workspace_user."User_Firstname", workspace_user."User_Lastname")), ''),
        workspace_user."User_Email"
      ) into v_label
      from public."cmp_Users" workspace_user
      where workspace_user."User_ID" = v_target_id
        and workspace_user."Company_ID" = v_context.company_id
        and workspace_user."User_AccessStatus" = 'active'
        and workspace_user."Auth_User_ID" is not null
        and public.multideck_lifecycle_note_recipient_authorised(
          workspace_user."Auth_User_ID", p_subject_type, p_subject_id
        );
      if v_label is null then
        raise exception 'That person is not active or cannot read this record.' using errcode = '22023';
      end if;
      insert into public."OPS_LifecycleNoteMentions" (
        "LifecycleNoteMention_NoteID", "LifecycleNoteMention_TargetType",
        "LifecycleNoteMention_TargetID", "LifecycleNoteMention_LabelSnapshot"
      ) values (v_note."LifecycleNote_ID", 'user', v_target_id, v_label)
      on conflict do nothing;
    elsif v_target_type = 'department' then
      select department."Department_Name" into v_label
      from public."cmp_Departments" department
      where department."Department_ID" = v_target_id
        and department."Company_ID" = v_context.company_id
        and department."Department_IsActive"
        and exists (
          select 1
          from public."cmp_Users_Departments" membership
          join public."cmp_Users" member on member."User_ID" = membership."User_ID"
          where membership."Department_ID" = department."Department_ID"
            and member."Company_ID" = v_context.company_id
            and member."User_AccessStatus" = 'active'
            and member."Auth_User_ID" is not null
            and public.multideck_lifecycle_note_recipient_authorised(
              member."Auth_User_ID", p_subject_type, p_subject_id
            )
        );
      if v_label is null then
        raise exception 'That department has no active member who can read this record.' using errcode = '22023';
      end if;
      insert into public."OPS_LifecycleNoteMentions" (
        "LifecycleNoteMention_NoteID", "LifecycleNoteMention_TargetType",
        "LifecycleNoteMention_TargetID", "LifecycleNoteMention_LabelSnapshot"
      ) values (v_note."LifecycleNote_ID", 'department', v_target_id, v_label)
      on conflict do nothing;
    else
      raise exception 'Tag a workspace person or department.' using errcode = '22023';
    end if;
  end loop;

  select coalesce(jsonb_agg(jsonb_build_object(
    'type', mention."LifecycleNoteMention_TargetType",
    'id', mention."LifecycleNoteMention_TargetID",
    'label', mention."LifecycleNoteMention_LabelSnapshot"
  ) order by mention."LifecycleNoteMention_CreatedAt", mention."LifecycleNoteMention_ID"), '[]'::jsonb)
  into v_mentions
  from public."OPS_LifecycleNoteMentions" mention
  where mention."LifecycleNoteMention_NoteID" = v_note."LifecycleNote_ID";

  if v_note."LifecycleNote_SubjectType" = 'company' then
    v_target_table := 'Org_Master';
    v_action_url := '/crm/accounts/' || p_subject_id;
  elsif v_note."LifecycleNote_SubjectType" = 'quote' then
    v_target_table := 'CusQuote_Header';
    v_action_url := '/quotes/' || v_context.reference;
  elsif v_note."LifecycleNote_SubjectType" = 'booking' then
    v_target_table := 'Job_Header';
    v_action_url := '/bookings/' || lower(v_context.reference);
  else
    v_target_table := 'Customs_Declarations';
    select lower(coalesce(nullif(btrim(declaration."CUST_Direction"), ''), 'export'))
    into v_direction
    from public."Customs_Declarations" declaration
    where declaration."CUST_id" = v_context.customs_id;
    v_action_url := '/customs/' || case when v_context.job_id is null then 'standalone' else 'job-related' end
      || '/' || v_direction || '/' || v_context.customs_id;
  end if;

  with tagged_recipients as (
    select mention."LifecycleNoteMention_TargetID" as user_id
    from public."OPS_LifecycleNoteMentions" mention
    where mention."LifecycleNoteMention_NoteID" = v_note."LifecycleNote_ID"
      and mention."LifecycleNoteMention_TargetType" = 'user'
    union
    select membership."User_ID"
    from public."OPS_LifecycleNoteMentions" mention
    join public."cmp_Users_Departments" membership
      on membership."Department_ID" = mention."LifecycleNoteMention_TargetID"
    where mention."LifecycleNoteMention_NoteID" = v_note."LifecycleNote_ID"
      and mention."LifecycleNoteMention_TargetType" = 'department'
  ), eligible_recipients as (
    select distinct recipient."User_ID"
    from tagged_recipients tagged
    join public."cmp_Users" recipient on recipient."User_ID" = tagged.user_id
    where recipient."Company_ID" = v_context.company_id
      and recipient."User_ID" <> v_context.actor_user_id
      and recipient."User_AccessStatus" = 'active'
      and recipient."Auth_User_ID" is not null
      and public.multideck_lifecycle_note_recipient_authorised(
        recipient."Auth_User_ID", p_subject_type, p_subject_id
      )
  )
  insert into public."Comm_Notifications" (
    "CommNotif_UserID", "CommNotif_Title", "CommNotif_Body", "CommNotif_TargetTable",
    "CommNotif_TargetID", "CommNotif_MetadataJSON", "CommNotif_CreatedBy"
  )
  select
    recipient."User_ID", 'You were tagged in a note',
    v_note."LifecycleNote_AuthorNameSnapshot" || ' tagged you on ' || v_context.reference || ': ' || left(v_body, 220),
    v_target_table, p_subject_id,
    jsonb_build_object(
      'event_type', 'lifecycle_note_mention',
      'action_url', v_action_url,
      'action_label', 'Open note',
      'eyebrow', 'Operational note',
      'note_id', v_note."LifecycleNote_ID",
      'subject_type', v_note."LifecycleNote_SubjectType",
      'reference', v_context.reference
    ),
    v_context.actor_user_id
  from eligible_recipients recipient;

  insert into public."AI_DexterWatchSignals" (
    "AIDexterWatchSignal_CompanyID", "AIDexterWatchSignal_CapabilityCode",
    "AIDexterWatchSignal_SourceTable", "AIDexterWatchSignal_SourceID",
    "AIDexterWatchSignal_OldJSON", "AIDexterWatchSignal_NewJSON"
  )
  select distinct
    v_context.company_id, 'lifecycle_notes', 'OPS_LifecycleNotes', watch."AIDexterWatch_TargetID", '{}'::jsonb,
    jsonb_build_object(
      'subjectType', v_note."LifecycleNote_SubjectType",
      'reference', coalesce(
        (select 'Q-' || quote."CusQuoteHeader_Number" from public."CusQuote_Header" quote where quote."CusQuoteHeader_ID" = watch."AIDexterWatch_TargetID"),
        (select coalesce(nullif(btrim(job."Job_BookingReference"), ''), 'MD-' || job."Job_Number") from public."Job_Header" job where job."Job_ID" = watch."AIDexterWatch_TargetID"),
        (select coalesce(nullif(btrim(declaration."CUST_LocalReferenceNumber"), ''), declaration."CUST_id"::text) from public."Customs_Declarations" declaration where declaration."CUST_id" = watch."AIDexterWatch_TargetID"),
        v_context.reference
      ),
      'body', v_body,
      'author', v_note."LifecycleNote_AuthorNameSnapshot",
      'mentionedUsers', coalesce((select jsonb_agg(value->>'label') from jsonb_array_elements(v_mentions) value where value->>'type' = 'user'), '[]'::jsonb),
      'mentionedDepartments', coalesce((select jsonb_agg(value->>'label') from jsonb_array_elements(v_mentions) value where value->>'type' = 'department'), '[]'::jsonb),
      'createdAt', v_note."LifecycleNote_CreatedAt"
    )
  from public."AI_DexterWatches" watch
  where watch."AIDexterWatch_CompanyID" = v_context.company_id
    and watch."AIDexterWatch_CapabilityCode" = 'lifecycle_notes'
    and watch."AIDexterWatch_StatusCode" = 'active'
    and (
      watch."AIDexterWatch_TargetID" = p_subject_id
      or (
        v_note."LifecycleNote_SubjectType" = 'quote'
        and exists (
          select 1
          from public."Job_Header" job
          where job."Job_SourceQuoteID" = v_context.quote_id
            and not job."Job_IsDeleted"
            and (
              watch."AIDexterWatch_TargetID" = job."Job_ID"
              or exists (
                select 1
                from public."Customs_Declarations" declaration
                where declaration."CUST_JobID" = job."Job_ID"
                  and declaration."CUST_id" = watch."AIDexterWatch_TargetID"
                  and not declaration."CUST_IsDeleted"
              )
            )
        )
      )
      or (
        v_note."LifecycleNote_SubjectType" = 'booking'
        and exists (
          select 1
          from public."Customs_Declarations" declaration
          where declaration."CUST_JobID" = v_context.job_id
            and declaration."CUST_id" = watch."AIDexterWatch_TargetID"
            and not declaration."CUST_IsDeleted"
        )
      )
    );

  return jsonb_build_object(
    'id', v_note."LifecycleNote_ID",
    'subjectType', v_note."LifecycleNote_SubjectType",
    'subjectId', v_note."LifecycleNote_SubjectID",
    'body', v_note."LifecycleNote_Body",
    'author', jsonb_build_object('id', v_note."LifecycleNote_AuthorUserID", 'name', v_note."LifecycleNote_AuthorNameSnapshot"),
    'mentions', v_mentions,
    'createdAt', v_note."LifecycleNote_CreatedAt"
  );
end;
$$;


