CREATE OR REPLACE FUNCTION "public"."_multideck_calendar_apply_booking_hosts"("p_company_id" "uuid", "p_owner_id" "uuid", "p_link_id" "uuid", "p_kind" "text", "p_host_emails" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_email text; v_user uuid; v_order integer := 0; v_count integer;
begin
  if p_kind not in ('one_on_one','round_robin','collective') then
    raise exception 'Choose a one-to-one, round robin or collective booking link.' using errcode='22023';
  end if;
  delete from public."CAL_BookingLinkHosts" where "CALBookingLinkHost_BookingLinkID"=p_link_id;
  if p_kind = 'one_on_one' then return; end if;
  for v_email in select lower(btrim(value#>>'{}')) from jsonb_array_elements(coalesce(p_host_emails,'[]'::jsonb)) loop
    select "User_ID" into v_user from public."cmp_Users" where "Company_ID"=p_company_id and lower("User_Email")=v_email and "User_AccessStatus"='active' limit 1;
    if v_user is null then
      raise exception 'Host % is not an active member of this workspace.', v_email using errcode='22023';
    end if;
    insert into public."CAL_BookingLinkHosts" ("CALBookingLinkHost_BookingLinkID","CALBookingLinkHost_UserID","CALBookingLinkHost_SortOrder")
    values (p_link_id, v_user, v_order) on conflict do nothing;
    v_order := v_order + 1;
  end loop;
  insert into public."CAL_BookingLinkHosts" ("CALBookingLinkHost_BookingLinkID","CALBookingLinkHost_UserID","CALBookingLinkHost_SortOrder")
  values (p_link_id, p_owner_id, -1) on conflict do nothing;
  select count(*) into v_count from public."CAL_BookingLinkHosts" where "CALBookingLinkHost_BookingLinkID"=p_link_id;
  if v_count < 2 then
    raise exception 'Round robin and collective booking links need at least two hosts.' using errcode='22023';
  end if;
end;
$$;


ALTER FUNCTION "public"."_multideck_calendar_apply_booking_hosts"("p_company_id" "uuid", "p_owner_id" "uuid", "p_link_id" "uuid", "p_kind" "text", "p_host_emails" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_calendar_delete_management_secret"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
begin
  if old."CALManagementToken_SecretRef" ~ '^supabase-vault:[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
    delete from vault.secrets as secret
    where secret.id = substring(old."CALManagementToken_SecretRef" from 16)::uuid;
  end if;
  return old;
end;
$_$;


ALTER FUNCTION "public"."_multideck_calendar_delete_management_secret"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_calendar_has_permission"("p_user_id" "uuid", "p_permission" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select exists (
    select 1
    from public."cmp_Users_Roles" user_role
    join public."sys_UserRole_Permissions" role_permission
      on role_permission."sys_UserRole_ID" = user_role."sys_UserRole_ID"
    join public."sys_Permissions" permission
      on permission."sys_Permission_ID" = role_permission."sys_Permission_ID"
    where user_role."User_ID" = p_user_id
      and permission."sys_Permission_Value" = p_permission
  );
$$;


