    "AIDexterWatchSignal_CompanyID","AIDexterWatchSignal_CapabilityCode","AIDexterWatchSignal_SourceTable",
    "AIDexterWatchSignal_SourceID","AIDexterWatchSignal_OldJSON","AIDexterWatchSignal_NewJSON"
  ) select new."CALProviderEvent_CompanyID",'calendar','CAL_ProviderEvents',new."CALProviderEvent_ID",
      jsonb_build_object('response',old."CALProviderEvent_ResponseCode"),
      jsonb_build_object('response',new."CALProviderEvent_ResponseCode")
    where exists (
      select 1 from public."AI_DexterWatches" watch
      where watch."AIDexterWatch_CompanyID"=new."CALProviderEvent_CompanyID"
        and watch."AIDexterWatch_OwnerUserID"=new."CALProviderEvent_OwnerUserID"
        and watch."AIDexterWatch_CapabilityCode"='calendar'
        and watch."AIDexterWatch_StatusCode"='active'
        and (watch."AIDexterWatch_TargetID" is null or watch."AIDexterWatch_TargetID"=new."CALProviderEvent_ID")
    );
  return new;
end;
$$;


ALTER FUNCTION "public"."_multideck_calendar_provider_response_watch_signal"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_calendar_queue_external_event_change"("p_company_id" "uuid", "p_user_id" "uuid", "p_event_id" "uuid", "p_cancel" boolean, "p_change" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_event public."CAL_ProviderEvents"; v_connection public."CAL_ProviderConnections"; v_key text;
begin
  if not public._multideck_calendar_has_permission(p_user_id,'Calendar.ManageOwn') then
    raise exception 'You do not have permission to change calendar events.' using errcode='42501';
  end if;
  select * into v_event from public."CAL_ProviderEvents"
  where "CALProviderEvent_ID"=p_event_id and "CALProviderEvent_CompanyID"=p_company_id and "CALProviderEvent_OwnerUserID"=p_user_id for update;
  if not found then raise exception 'That calendar event is not available to change.' using errcode='42501'; end if;
  if v_event."CALProviderEvent_MeetingID" is not null then raise exception 'That event is a Multideck meeting. Use the meeting actions instead.' using errcode='22023'; end if;
  if v_event."CALProviderEvent_IsCancelled" then raise exception 'That event was already removed from the provider.' using errcode='22023'; end if;
  select * into v_connection from public."CAL_ProviderConnections" where "CALConnection_ID"=v_event."CALProviderEvent_ConnectionID";
  if not found or v_connection."CALConnection_StatusCode"<>'connected' or v_connection."CALConnection_ProviderCode" not in ('google','microsoft') then
    raise exception 'Reconnect the calendar this event came from before changing it.' using errcode='22023';
  end if;
  if not p_cancel then
    if p_change->>'title' is not null and v_event."CALProviderEvent_IsPrivate" then
      raise exception 'Private provider events keep their title. You can still move or delete them.' using errcode='22023';
    end if;
    if p_change->>'title' is null and p_change->>'startAt' is null then
      raise exception 'Nothing to change on this event.' using errcode='22023';
    end if;
    if p_change->>'startAt' is not null and ((p_change->>'endAt')::timestamptz <= (p_change->>'startAt')::timestamptz) then
      raise exception 'The event must finish after it starts.' using errcode='22023';
    end if;
  end if;
  v_key := 'external-event:'||p_event_id||':'||case when p_cancel then 'cancel' else 'update' end||':'||to_char(clock_timestamp(),'YYYYMMDDHH24MISSMS');
  insert into public."CAL_Deliveries" ("CALDelivery_CompanyID","CALDelivery_KindCode","CALDelivery_IdempotencyKey","CALDelivery_RenderedJSON")
  values (p_company_id, case when p_cancel then 'external_event_cancel' else 'external_event_update' end, v_key,
    jsonb_strip_nulls(jsonb_build_object('providerEventId',p_event_id,'requestedBy',p_user_id,'title',p_change->>'title','startAt',p_change->>'startAt','endAt',p_change->>'endAt','timeZone',p_change->>'timeZone')));
  return jsonb_build_object('id',p_event_id,'source',v_connection."CALConnection_ProviderCode",'status','sync_pending',
    'title',case when v_event."CALProviderEvent_IsPrivate" then 'Busy' else v_event."CALProviderEvent_Title" end,
    'currentStartAt',v_event."CALProviderEvent_StartAt",'currentEndAt',v_event."CALProviderEvent_EndAt",
    'requestedStartAt',p_change->>'startAt','requestedEndAt',p_change->>'endAt');
end;
$$;


ALTER FUNCTION "public"."_multideck_calendar_queue_external_event_change"("p_company_id" "uuid", "p_user_id" "uuid", "p_event_id" "uuid", "p_cancel" boolean, "p_change" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_calendar_refresh_reminders"("p_meeting_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_meeting public."CAL_Meetings"%rowtype;
  v_participant record;
  v_value text;
  v_minutes integer;
  v_send_after timestamptz;
begin
  select * into v_meeting
  from public."CAL_Meetings"
  where "CALMeeting_ID" = p_meeting_id;

  if not found then return; end if;

  update public."CAL_Deliveries"
  set "CALDelivery_StatusCode" = 'cancelled',
      "CALDelivery_LeaseUntil" = null,
      "CALDelivery_CompletedAt" = now()
  where "CALDelivery_MeetingID" = p_meeting_id
    and "CALDelivery_KindCode" = 'reminder'
    and "CALDelivery_StatusCode" in ('pending','leased');

  if not (
       v_meeting."CALMeeting_StatusCode" = 'confirmed'
       or (v_meeting."CALMeeting_StatusCode" in ('sync_pending','sync_failed') and v_meeting."CALMeeting_ProviderEventID" is not null)
     )
     or v_meeting."CALMeeting_StartAt" <= now() then
    return;
  end if;

  for v_participant in
    select participant."CALParticipant_ID"
    from public."CAL_MeetingParticipants" participant
    where participant."CALParticipant_MeetingID" = p_meeting_id
      and participant."CALParticipant_ResponseCode" <> 'declined'
  loop
    for v_value in
      select value
      from jsonb_array_elements_text(v_meeting."CALMeeting_RemindersJSON") value
    loop
      if v_value ~ '^[0-9]{1,5}$' then
        v_minutes := v_value::integer;
        if v_minutes between 5 and 10080 then
          v_send_after := v_meeting."CALMeeting_StartAt" - make_interval(mins => v_minutes);
          if v_send_after > now() then
            insert into public."CAL_Deliveries" (
              "CALDelivery_CompanyID", "CALDelivery_MeetingID", "CALDelivery_ParticipantID",
              "CALDelivery_KindCode", "CALDelivery_SendAfter", "CALDelivery_IdempotencyKey",
              "CALDelivery_RenderedJSON"
            ) values (
              v_meeting."CALMeeting_CompanyID", p_meeting_id, v_participant."CALParticipant_ID",
              'reminder', v_send_after,
              'meeting:'||p_meeting_id::text||':participant:'||v_participant."CALParticipant_ID"::text||':reminder:v'||v_meeting."CALMeeting_EditVersion"::text||':'||v_minutes::text||':at:'||extract(epoch from v_meeting."CALMeeting_StartAt")::bigint::text,
              jsonb_build_object('meetingVersion',v_meeting."CALMeeting_EditVersion",'reminderMinutes',v_minutes)
            ) on conflict ("CALDelivery_IdempotencyKey") do update set
              "CALDelivery_SendAfter" = excluded."CALDelivery_SendAfter",
              "CALDelivery_RenderedJSON" = excluded."CALDelivery_RenderedJSON",
              "CALDelivery_StatusCode" = case when public."CAL_Deliveries"."CALDelivery_StatusCode" = 'delivered' then 'delivered' else 'pending' end,
              "CALDelivery_LeaseUntil" = null,
              "CALDelivery_CompletedAt" = case when public."CAL_Deliveries"."CALDelivery_StatusCode" = 'delivered' then public."CAL_Deliveries"."CALDelivery_CompletedAt" else null end,
              "CALDelivery_LastError" = null;
          end if;
        end if;
      end if;
    end loop;
  end loop;
end;
$_$;


ALTER FUNCTION "public"."_multideck_calendar_refresh_reminders"("p_meeting_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_calendar_watch_signal"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_company uuid; v_owner uuid; v_source uuid; v_capability text; v_old jsonb := '{}'::jsonb; v_new jsonb := '{}'::jsonb;
begin
  if tg_table_name = 'CAL_Meetings' then
    v_company := new."CALMeeting_CompanyID"; v_owner := new."CALMeeting_OrganiserUserID"; v_source := new."CALMeeting_ID"; v_capability := 'calendar';
    if tg_op='UPDATE' then v_old := jsonb_build_object('status',old."CALMeeting_StatusCode",'startAt',old."CALMeeting_StartAt",'endAt',old."CALMeeting_EndAt",'syncError',old."CALMeeting_LastSyncError"); end if;
    v_new := jsonb_build_object('status',new."CALMeeting_StatusCode",'startAt',new."CALMeeting_StartAt",'endAt',new."CALMeeting_EndAt",'syncError',new."CALMeeting_LastSyncError");
  elsif tg_table_name = 'CAL_BookingLinks' then
    v_company := new."CALBookingLink_CompanyID"; v_owner := new."CALBookingLink_OwnerUserID"; v_source := new."CALBookingLink_ID"; v_capability := 'booking_links';
    if tg_op='UPDATE' then v_old := jsonb_build_object('status',old."CALBookingLink_StatusCode",'kind',old."CALBookingLink_KindCode"); end if;
    v_new := jsonb_build_object('status',new."CALBookingLink_StatusCode",'kind',new."CALBookingLink_KindCode");
  elsif tg_table_name = 'CAL_MeetingParticipants' then
    select meeting."CALMeeting_CompanyID",meeting."CALMeeting_OrganiserUserID",meeting."CALMeeting_ID" into v_company,v_owner,v_source
    from public."CAL_Meetings" meeting where meeting."CALMeeting_ID"=new."CALParticipant_MeetingID";
    v_capability := 'calendar';
    if tg_op='UPDATE' then v_old := jsonb_build_object('response',old."CALParticipant_ResponseCode"); end if;
    v_new := jsonb_build_object('response',new."CALParticipant_ResponseCode",'participantId',new."CALParticipant_ID");
  elsif tg_table_name = 'CAL_ChangeRequests' then
    select meeting."CALMeeting_CompanyID",meeting."CALMeeting_OrganiserUserID",meeting."CALMeeting_ID" into v_company,v_owner,v_source
    from public."CAL_Meetings" meeting where meeting."CALMeeting_ID"=new."CALChangeRequest_MeetingID";
    v_capability := 'calendar';
    if tg_op='UPDATE' then v_old := jsonb_build_object('changeRequest',old."CALChangeRequest_StatusCode"); end if;
    v_new := jsonb_build_object('changeRequest',new."CALChangeRequest_StatusCode",'requestId',new."CALChangeRequest_ID");
  elsif tg_table_name = 'CAL_ProviderEvents' then
    if new."CALProviderEvent_MeetingID" is not null then return new; end if;
    if tg_op='UPDATE' and old."CALProviderEvent_StartAt"=new."CALProviderEvent_StartAt" and old."CALProviderEvent_EndAt"=new."CALProviderEvent_EndAt"
      and old."CALProviderEvent_IsCancelled"=new."CALProviderEvent_IsCancelled" and coalesce(old."CALProviderEvent_Title",'')=coalesce(new."CALProviderEvent_Title",'') then
      return new;
    end if;
    v_company := new."CALProviderEvent_CompanyID"; v_owner := new."CALProviderEvent_OwnerUserID"; v_source := new."CALProviderEvent_ID"; v_capability := 'calendar';
    if tg_op='UPDATE' then v_old := jsonb_build_object('externalEvent',case when old."CALProviderEvent_IsCancelled" then 'cancelled' else 'active' end,'startAt',old."CALProviderEvent_StartAt",'endAt',old."CALProviderEvent_EndAt"); end if;
    v_new := jsonb_build_object('externalEvent',case when new."CALProviderEvent_IsCancelled" then 'cancelled' else 'active' end,'startAt',new."CALProviderEvent_StartAt",'endAt',new."CALProviderEvent_EndAt",
      'title',case when new."CALProviderEvent_IsPrivate" then 'Busy' else coalesce(new."CALProviderEvent_Title",'Busy') end);
  else return new; end if;
  insert into public."AI_DexterWatchSignals" (
    "AIDexterWatchSignal_CompanyID","AIDexterWatchSignal_CapabilityCode","AIDexterWatchSignal_SourceTable",
    "AIDexterWatchSignal_SourceID","AIDexterWatchSignal_OldJSON","AIDexterWatchSignal_NewJSON"
  ) select v_company,v_capability,tg_table_name,v_source,v_old,v_new
  where exists (
    select 1 from public."AI_DexterWatches" watch
    where watch."AIDexterWatch_CompanyID"=v_company and watch."AIDexterWatch_OwnerUserID"=v_owner
      and watch."AIDexterWatch_CapabilityCode"=v_capability and watch."AIDexterWatch_StatusCode"='active'
      and (watch."AIDexterWatch_TargetID" is null or watch."AIDexterWatch_TargetID"=v_source)
  );
  return new;
end;
$$;


ALTER FUNCTION "public"."_multideck_calendar_watch_signal"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_contact_card_analytics"("p_card_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_scans bigint := 0;
  v_unique_scans bigint := 0;
  v_converted_sessions bigint := 0;
  v_started bigint := 0;
  v_exchanges bigint := 0;
  v_leads_created bigint := 0;
  v_leads_matched bigint := 0;
  v_runs_today bigint := 0;
  v_failed_runs bigint := 0;
  v_timeline_hour jsonb := '[]'::jsonb;
  v_timeline_day jsonb := '[]'::jsonb;
  v_devices jsonb := '[]'::jsonb;
  v_browsers jsonb := '[]'::jsonb;
  v_channels jsonb := '[]'::jsonb;
  v_locations jsonb := '[]'::jsonb;
  v_suppressed_regions integer := 0;
  v_suppressed_scans bigint := 0;
  v_automation_outcomes jsonb := '[]'::jsonb;
begin
  select
    count(*),
    count(*) filter (where scan."Scan_StartedAt" is not null)
  into v_scans, v_started
  from public."CRM_ContactCardScans" scan
  where scan."ContactCard_ID" = p_card_id;

  -- Never merge unrelated people merely because they use the same browser.
  -- Historical visits have no session ID and count individually.
  select count(distinct coalesce(scan."Scan_SessionID", scan."Scan_ID")),
    count(distinct coalesce(scan."Scan_SessionID", scan."Scan_ID")) filter (where scan."Scan_ExchangedAt" is not null)
  into v_unique_scans, v_converted_sessions
  from public."CRM_ContactCardScans" scan
  where scan."ContactCard_ID" = p_card_id;

  select
    count(*),
    count(*) filter (where exchange."Exchange_Outcome" = 'created'),
    count(*) filter (where exchange."Exchange_Outcome" = 'matched')
  into v_exchanges, v_leads_created, v_leads_matched
  from public."CRM_ContactCardExchanges" exchange
  where exchange."ContactCard_ID" = p_card_id;

  select
    count(*) filter (
      where not run."AutomationRun_IsTest"
        and run."AutomationRun_StartedAt" >= date_trunc('day', now())
        and run."AutomationRun_StartedAt" < date_trunc('day', now()) + interval '1 day'
    ),
    count(*) filter (where run."AutomationRun_Status" = 'failed')
  into v_runs_today, v_failed_runs
  from public."CRM_ContactCardAutomationRuns" run
  where run."ContactCard_ID" = p_card_id;

  select coalesce(jsonb_agg(jsonb_build_object(
    'iso', bucket.bucket,
    'scans', bucket.scans,
    'exchanges', bucket.exchanges
  ) order by bucket.bucket), '[]'::jsonb)
  into v_timeline_hour
  from (
    select
      date_trunc('hour', scan."Scan_At") as bucket,
      count(*) as scans,
      count(*) filter (where scan."Scan_ExchangedAt" is not null) as exchanges
    from public."CRM_ContactCardScans" scan
    where scan."ContactCard_ID" = p_card_id
    group by date_trunc('hour', scan."Scan_At")
    order by bucket desc
    limit 168
  ) bucket;

  select coalesce(jsonb_agg(jsonb_build_object(
    'iso', bucket.bucket,
    'scans', bucket.scans,
    'exchanges', bucket.exchanges
  ) order by bucket.bucket), '[]'::jsonb)
  into v_timeline_day
  from (
    select
      date_trunc('day', scan."Scan_At") as bucket,
      count(*) as scans,
      count(*) filter (where scan."Scan_ExchangedAt" is not null) as exchanges
    from public."CRM_ContactCardScans" scan
    where scan."ContactCard_ID" = p_card_id
    group by date_trunc('day', scan."Scan_At")
    order by bucket desc
    limit 90
  ) bucket;

  select coalesce(jsonb_agg(jsonb_build_object(
    'name', breakdown.name,
    'value', breakdown.value,
    'share', case when v_scans = 0 then 0 else breakdown.value::numeric / v_scans end
  ) order by breakdown.value desc, breakdown.name), '[]'::jsonb)
  into v_devices
  from (
    select case scan."Scan_Device"
      when 'mobile' then 'Mobile'
      when 'tablet' then 'Tablet'
      when 'desktop' then 'Desktop'
      else 'Unknown'
    end as name, count(*) as value
    from public."CRM_ContactCardScans" scan
    where scan."ContactCard_ID" = p_card_id
    group by scan."Scan_Device"
  ) breakdown;

  select coalesce(jsonb_agg(jsonb_build_object(
    'name', breakdown.name,
    'value', breakdown.value,
    'share', case when v_scans = 0 then 0 else breakdown.value::numeric / v_scans end
  ) order by breakdown.value desc, breakdown.name), '[]'::jsonb)
  into v_browsers
  from (
    select coalesce(nullif(btrim(scan."Scan_Browser"), ''), 'Unknown') as name, count(*) as value
    from public."CRM_ContactCardScans" scan
    where scan."ContactCard_ID" = p_card_id
    group by coalesce(nullif(btrim(scan."Scan_Browser"), ''), 'Unknown')
  ) breakdown;

  select coalesce(jsonb_agg(jsonb_build_object(
    'name', breakdown.name,
    'value', breakdown.value,
    'share', case when v_scans = 0 then 0 else breakdown.value::numeric / v_scans end
  ) order by breakdown.value desc, breakdown.name), '[]'::jsonb)
  into v_channels
  from (
    select case scan."Scan_Channel"
      when 'direct-scan' then case when scan."Scan_RequestID" is null then 'Unattributed (legacy)' else 'QR code link' end
      when 'shared-link' then 'Shared link'
      when 'in-app-browser' then 'In-app browser'
      else 'Unknown'
    end as name, count(*) as value
    from public."CRM_ContactCardScans" scan
    where scan."ContactCard_ID" = p_card_id
    group by 1
  ) breakdown;

  with location_counts as (
    select
      coalesce(
        nullif(btrim(concat_ws(', ', nullif(btrim(scan."Scan_Region"), ''), nullif(btrim(scan."Scan_Country"), ''))), ''),
        'Unknown'
      ) as name,
      count(*) as value
    from public."CRM_ContactCardScans" scan
    where scan."ContactCard_ID" = p_card_id
    group by 1
  ), location_rollup as (
    select name, value from location_counts where value >= 5
    union all
    select 'Other regions', sum(value) from location_counts where value < 5
    having count(*) > 0
  )
  select
    coalesce(jsonb_agg(jsonb_build_object(
      'name', location_rollup.name,
      'value', location_rollup.value,
      'share', case when v_scans = 0 then 0 else location_rollup.value::numeric / v_scans end
    ) order by location_rollup.value desc, location_rollup.name), '[]'::jsonb),
    (select count(*)::integer from location_counts where value < 5),
    coalesce((select sum(value) from location_counts where value < 5), 0)
  into v_locations, v_suppressed_regions, v_suppressed_scans
  from location_rollup;

  select coalesce(jsonb_agg(jsonb_build_object(
    'name', breakdown.name,
    'value', breakdown.value,
    'share', case when v_exchanges = 0 then 0 else breakdown.value::numeric / v_exchanges end
  ) order by breakdown.value desc, breakdown.name), '[]'::jsonb)
  into v_automation_outcomes
  from (
    select case exchange."Exchange_AutomationOutcome"
      when 'ran' then 'Ran'
      when 'skipped' then 'Skipped by a condition'
      when 'failed' then 'Failed'
      else 'Automation off'
    end as name, count(*) as value
    from public."CRM_ContactCardExchanges" exchange
    where exchange."ContactCard_ID" = p_card_id
    group by exchange."Exchange_AutomationOutcome"
  ) breakdown;

  return jsonb_build_object(
    'totals', jsonb_build_object(
      'scans', v_scans,
      'uniqueScans', v_unique_scans,
      'started', v_started,
      'exchanges', v_exchanges,
      'leadsCreated', v_leads_created,
      'leadsMatched', v_leads_matched,
      'conversion', case when v_unique_scans = 0 then null else v_converted_sessions::numeric / v_unique_scans end
    ),
    'timelineHour', v_timeline_hour,
    'timelineDay', v_timeline_day,
    'devices', v_devices,
    'browsers', v_browsers,
    'channels', v_channels,
    'location', jsonb_build_object(
      'rows', v_locations,
      'suppressedRegions', v_suppressed_regions,
      'suppressedScans', v_suppressed_scans
    ),
    'automationOutcomes', v_automation_outcomes,
    'automationRunsToday', v_runs_today,
    'automationFailures', v_failed_runs
  );
end;
$$;


ALTER FUNCTION "public"."_multideck_contact_card_analytics"("p_card_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_multideck_contact_card_analytics"("p_card_id" "uuid") IS 'Private database-owned contact-card analytics used by the authenticated workspace RPC.';



CREATE OR REPLACE FUNCTION "public"."_multideck_contact_card_capture_marketing_consent"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_owner uuid;
begin
  if new."Exchange_MarketingConsent" is true and new."CRMLead_ID" is not null then
    select "Owner_User_ID" into v_owner
    from public."CRM_ContactCards" where "ContactCard_ID" = new."ContactCard_ID";
    perform public._multideck_set_marketing_consent(
      'lead', new."CRMLead_ID", true, 'contact_card', 'Opted in on the public contact-card form.', v_owner,
      jsonb_build_object('exchangeId', new."Exchange_ID", 'contactCardId', new."ContactCard_ID")
    );
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."_multideck_contact_card_capture_marketing_consent"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_contact_card_execute_automation"("p_card_id" "uuid", "p_exchange_id" "uuid", "p_lead_id" "uuid", "p_input" "jsonb", "p_existing_lead" boolean, "p_is_test" boolean DEFAULT false, "p_rerun_of" "uuid" DEFAULT NULL::"uuid", "p_start_order" integer DEFAULT 0) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  v_card record; v_automation record; v_run uuid; v_started timestamptz:=clock_timestamp();
  v_condition record; v_action record; v_match boolean; v_domain text; v_detail text;
  v_actions integer:=0; v_step_started timestamptz; v_pipeline uuid; v_stage uuid; v_owner uuid;
  v_record_type text; v_duplicate text; v_deal uuid; v_deal_name text; v_lead record;
  v_type text; v_status text; v_forecast text; v_opportunity_stage text;
begin
  select * into v_card from public."CRM_ContactCards" where "ContactCard_ID"=p_card_id and "ContactCard_DeletedAt" is null;
  if not found then raise exception 'Contact card not found.' using errcode='P0002'; end if;
  select * into v_automation from public."CRM_ContactCardAutomations" where "ContactCard_ID"=p_card_id;

  insert into public."CRM_ContactCardAutomationRuns"("ContactCard_ID","Exchange_ID","CRMLead_ID","AutomationRun_Status","AutomationRun_Input","AutomationRun_ExistingLead","AutomationRun_RerunOf","AutomationRun_IsTest")
  values(p_card_id,p_exchange_id,p_lead_id,'running',p_input,p_existing_lead,p_rerun_of,p_is_test) returning "AutomationRun_ID" into v_run;
  insert into public."CRM_ContactCardAutomationRunSteps"("AutomationRun_ID","AutomationRunStep_SortOrder","AutomationRunStep_Kind","AutomationRunStep_Label","AutomationRunStep_Status","AutomationRunStep_Detail")
  values(v_run,0,'trigger','Lead submitted','succeeded',case when p_is_test then 'Test input accepted. No CRM record was changed.' else 'The contact card received valid details.' end);

  if not p_is_test and p_rerun_of is null and coalesce(v_automation."Automation_State",'off')<>'active' then
    update public."CRM_ContactCardAutomationRuns" set "AutomationRun_Status"='skipped',"AutomationRun_CompletedAt"=clock_timestamp(),"AutomationRun_DurationMs"=greatest(0,(extract(epoch from(clock_timestamp()-v_started))*1000)::integer) where "AutomationRun_ID"=v_run;
    return v_run;
  end if;

  for v_condition in select * from public."CRM_ContactCardAutomationConditions" where "ContactCard_ID"=p_card_id and "Condition_Enabled" order by "Condition_SortOrder" loop
    v_step_started:=clock_timestamp(); v_domain:=lower(split_part(coalesce(p_input->>'email',''),'@',2));
    if p_rerun_of is not null then v_match:=true; v_detail:='Matched in the original run.';
    elsif p_is_test then
      v_match:=v_condition."Condition_Kind"<>'within-dates' or v_condition."Condition_Value" ~ '^\d{4}-\d{2}-\d{2}\.\.\d{4}-\d{2}-\d{2}$';
      v_detail:=case when v_match then 'Condition configuration is valid.' else 'Use dates in the format YYYY-MM-DD..YYYY-MM-DD.' end;
    elsif v_condition."Condition_Kind"='free-email' then
      v_match:=v_domain=any(array['gmail.com','googlemail.com','outlook.com','hotmail.com','live.com','icloud.com','yahoo.com','aol.com','proton.me','protonmail.com']); v_detail:='Checked the submitted email provider.';
    elsif v_condition."Condition_Kind"='new-lead' then v_match:=not p_existing_lead; v_detail:=case when v_match then 'This email was not already in the CRM.' else 'This email already exists in the CRM.' end;
    elsif v_condition."Condition_Kind"='email-domain' then v_match:=v_domain=lower(replace(v_condition."Condition_Value",'@','')); v_detail:='Compared the submitted email domain.';
    elsif v_condition."Condition_Kind"='known-company' then
      v_match:=exists(select 1 from public."Org_Master" organisation where lower(btrim(organisation."Org_Name"))=lower(btrim(coalesce(p_input->>'company','')))); v_detail:='Compared the company with existing organisations.';
    elsif v_condition."Condition_Kind"='within-dates' then
      if v_condition."Condition_Value" ~ '^\d{4}-\d{2}-\d{2}\.\.\d{4}-\d{2}-\d{2}$' then
        v_match:=current_date between split_part(v_condition."Condition_Value",'..',1)::date and split_part(v_condition."Condition_Value",'..',2)::date;
      else
        v_match:=false;
      end if;
      v_detail:='Checked today against the saved event dates.';
    else v_match:=false; v_detail:='This condition is not supported.'; end if;
    if v_condition."Condition_Negated" then v_match:=not v_match; end if;
    insert into public."CRM_ContactCardAutomationRunSteps"("AutomationRun_ID","AutomationRunStep_SortOrder","AutomationRunStep_Kind","AutomationRunStep_Label","AutomationRunStep_Status","AutomationRunStep_Detail","AutomationRunStep_StartedAt","AutomationRunStep_DurationMs")
    values(v_run,10+v_condition."Condition_SortOrder",'condition',v_condition."Condition_Kind",case when v_match then 'succeeded' else 'skipped' end,v_detail,v_step_started,greatest(0,(extract(epoch from(clock_timestamp()-v_step_started))*1000)::integer));
    if not v_match then
      update public."CRM_ContactCardAutomationRuns" set "AutomationRun_Status"='skipped',"AutomationRun_CompletedAt"=clock_timestamp(),"AutomationRun_DurationMs"=greatest(0,(extract(epoch from(clock_timestamp()-v_started))*1000)::integer) where "AutomationRun_ID"=v_run;
      return v_run;
    end if;
  end loop;

  for v_action in select * from public."CRM_ContactCardAutomationActions" where "ContactCard_ID"=p_card_id and "Action_Enabled" order by "Action_SortOrder" loop
    if v_action."Action_SortOrder"<p_start_order then
      insert into public."CRM_ContactCardAutomationRunSteps"("AutomationRun_ID","Action_ID","AutomationRunStep_SortOrder","AutomationRunStep_Kind","AutomationRunStep_Label","AutomationRunStep_Status","AutomationRunStep_Detail") values(v_run,v_action."Action_ID",100+v_action."Action_SortOrder",v_action."Action_Kind",v_action."Action_Kind",'skipped','Completed in the original run.');
      continue;
    end if;
    v_step_started:=clock_timestamp();
    begin
      v_pipeline:=v_action."Action_PipelineID"; v_stage:=v_action."Action_PipelineStageID"; v_owner:=v_action."Action_OwnerUserID";
      if v_pipeline is not null and not exists(select 1 from public."CRM_Pipelines" p join public."CRM_PipelineStages" s on s."CRMPipeline_ID"=p."CRMPipeline_ID" where p."Company_ID"=v_card."Company_ID" and p."CRMPipeline_ID"=v_pipeline and s."CRMPipelineStage_ID"=v_stage and not p."Is_Deleted" and not s."Is_Deleted") then raise exception 'The saved pipeline or stage is no longer available.'; end if;
      if v_owner is not null and not exists(select 1 from public."cmp_Users" where "User_ID"=v_owner and "Company_ID"=v_card."Company_ID") then raise exception 'The saved owner is no longer available.'; end if;

      if p_is_test then
        if v_action."Action_Kind" not in ('add-to-crm','assign-owner','pipeline-stage') then raise exception 'This action is not connected to a live Multideck operation yet.'; end if;
        if v_action."Action_Kind"='add-to-crm' and coalesce(v_action."Action_Config"->>'recordType','lead')='deal' and (v_pipeline is null or v_stage is null) then raise exception 'Choose a pipeline and deal stage.'; end if;
        v_detail:='Configuration checked. No CRM record was changed.';
      elsif v_action."Action_Kind"='assign-owner' then
        if v_owner is null then raise exception 'Choose an owner.'; end if;
        update public."CRM_Leads" set "CRMLead_OwnerUserID"=v_owner,"CRMLead_UpdatedAt"=now(),"CRMLead_UpdatedBy"=v_card."Owner_User_ID" where "CRMLead_ID"=p_lead_id;
        v_actions:=v_actions+1; v_detail:='Lead owner updated in the CRM.';
      elsif v_action."Action_Kind"='pipeline-stage' then
        if v_pipeline is null or v_stage is null then raise exception 'Choose a pipeline and stage.'; end if;
        insert into public."CRM_LeadPipelinePlacements"("CRMLead_ID","CRMPipeline_ID","CRMPipelineStage_ID","ContactCard_ID") values(p_lead_id,v_pipeline,v_stage,p_card_id)
        on conflict("CRMLead_ID") do update set "CRMPipeline_ID"=excluded."CRMPipeline_ID","CRMPipelineStage_ID"=excluded."CRMPipelineStage_ID","ContactCard_ID"=excluded."ContactCard_ID","Placed_At"=now();
        v_actions:=v_actions+1; v_detail:='Lead placed in the selected pipeline stage.';
      elsif v_action."Action_Kind"='add-to-crm' then
        v_record_type:=coalesce(v_action."Action_Config"->>'recordType','lead'); v_duplicate:=coalesce(v_action."Action_Config"->>'duplicateHandling','update');
        if p_existing_lead and v_duplicate='fail' then raise exception 'This email already exists in the CRM.'; end if;
        if p_existing_lead and v_duplicate='skip' then
          insert into public."CRM_ContactCardAutomationRunSteps"("AutomationRun_ID","Action_ID","AutomationRunStep_SortOrder","AutomationRunStep_Kind","AutomationRunStep_Label","AutomationRunStep_Status","AutomationRunStep_Detail","AutomationRunStep_StartedAt","AutomationRunStep_DurationMs") values(v_run,v_action."Action_ID",100+v_action."Action_SortOrder",v_action."Action_Kind",case when v_record_type='deal' then 'Add deal to CRM' else 'Add lead to CRM' end,'skipped','The email already existed, so the saved duplicate rule skipped this step.',v_step_started,greatest(0,(extract(epoch from(clock_timestamp()-v_step_started))*1000)::integer));
          continue;
        end if;
        if v_owner is not null then update public."CRM_Leads" set "CRMLead_OwnerUserID"=v_owner,"CRMLead_UpdatedAt"=now(),"CRMLead_UpdatedBy"=v_card."Owner_User_ID" where "CRMLead_ID"=p_lead_id; end if;
        if v_record_type='deal' then
          select * into v_lead from public."CRM_Leads" where "CRMLead_ID"=p_lead_id and not "CRMLead_IsDeleted";
          if v_lead."CRMLead_OrgID" is null then raise exception 'Link this lead to an organisation before creating a deal.'; end if;
          if v_pipeline is null or v_stage is null then raise exception 'Choose a pipeline and deal stage.'; end if;
          select "CRMOpptyType_Code" into v_type from public."sys_CRMOpportunityTypes" where "CRMOpptyType_IsActive" order by "CRMOpptyType_SortOrder" limit 1;
          select "CRMOpptyStatus_Code" into v_status from public."sys_CRMOpportunityStatuses" where "CRMOpptyStatus_IsActive" and "CRMOpptyStatus_IsOpen" order by "CRMOpptyStatus_SortOrder" limit 1;
          select "CRMForecast_Code" into v_forecast from public."sys_CRMForecastCategories" where "CRMForecast_IsActive" order by "CRMForecast_SortOrder" limit 1;
          select "CRMStage_Code" into v_opportunity_stage from public."sys_CRMOpportunityStages" where "CRMStage_IsActive" and "CRMStage_IsOpen" order by "CRMStage_SortOrder" limit 1;
          v_deal_name:=replace(coalesce(nullif(v_action."Action_Config"->>'dealName',''),'{company} enquiry'),'{company}',coalesce(p_input->>'company','New'));
          select "CRMOppty_ID" into v_deal from public."CRM_Opportunities" where "CRMOppty_SourceLeadID"=p_lead_id and "CRMOppty_PipelineID"=v_pipeline and not "CRMOppty_IsDeleted" order by "CRMOppty_CreatedAt" desc limit 1;
          if v_deal is null then
            insert into public."CRM_Opportunities"("CRMOppty_OrgID","CRMOppty_SourceLeadID","CRMOppty_OwnerUserID","CRMOppty_PipelineID","CRMOppty_PipelineStageID","CRMOppty_Name","CRMOppty_TypeCode","CRMOppty_StageCode","CRMOppty_StatusCode","CRMOppty_ForecastCategoryCode","CRMOppty_MetadataJSON","CRMOppty_CreatedBy","CRMOppty_UpdatedBy")
            values(v_lead."CRMLead_OrgID",p_lead_id,coalesce(v_owner,v_lead."CRMLead_OwnerUserID",v_card."Owner_User_ID"),v_pipeline,v_stage,left(v_deal_name,240),v_type,v_opportunity_stage,v_status,v_forecast,jsonb_build_object('contactCardId',p_card_id,'automationRunId',v_run),v_card."Owner_User_ID",v_card."Owner_User_ID") returning "CRMOppty_ID" into v_deal;
          else
            update public."CRM_Opportunities" set "CRMOppty_PipelineStageID"=v_stage,"CRMOppty_UpdatedAt"=now(),"CRMOppty_UpdatedBy"=v_card."Owner_User_ID" where "CRMOppty_ID"=v_deal;
          end if;
          v_detail:='Deal saved in the selected CRM pipeline.';
        else
          update public."CRM_Leads" set
            "CRMLead_PersonName"=left(btrim(concat_ws(' ',p_input->>'firstName',p_input->>'lastName')),255),
            "CRMLead_CompanyName"=left(btrim(coalesce(p_input->>'company','')),255),
            "CRMLead_Phone"=left(btrim(coalesce(p_input->>'phone','')),80),
            "CRMLead_UpdatedAt"=now(),"CRMLead_UpdatedBy"=v_card."Owner_User_ID"
          where "CRMLead_ID"=p_lead_id;
          if v_pipeline is not null and v_stage is not null then insert into public."CRM_LeadPipelinePlacements"("CRMLead_ID","CRMPipeline_ID","CRMPipelineStage_ID","ContactCard_ID") values(p_lead_id,v_pipeline,v_stage,p_card_id) on conflict("CRMLead_ID") do update set "CRMPipeline_ID"=excluded."CRMPipeline_ID","CRMPipelineStage_ID"=excluded."CRMPipelineStage_ID","ContactCard_ID"=excluded."ContactCard_ID","Placed_At"=now(); end if;
          v_detail:=case when p_existing_lead then 'Existing CRM lead updated from the submitted fields.' else 'New CRM lead created from the submitted fields.' end;
        end if;
        v_actions:=v_actions+1;
      else raise exception 'This action is saved but its live integration is not connected yet.'; end if;

      insert into public."CRM_ContactCardAutomationRunSteps"("AutomationRun_ID","Action_ID","AutomationRunStep_SortOrder","AutomationRunStep_Kind","AutomationRunStep_Label","AutomationRunStep_Status","AutomationRunStep_Detail","AutomationRunStep_StartedAt","AutomationRunStep_DurationMs") values(v_run,v_action."Action_ID",100+v_action."Action_SortOrder",v_action."Action_Kind",case when v_action."Action_Kind"='add-to-crm' then 'Add to CRM' when v_action."Action_Kind"='assign-owner' then 'Assign owner' when v_action."Action_Kind"='pipeline-stage' then 'Add to pipeline' else v_action."Action_Kind" end,'succeeded',v_detail,v_step_started,greatest(0,(extract(epoch from(clock_timestamp()-v_step_started))*1000)::integer));
    exception when others then
      insert into public."CRM_ContactCardAutomationRunSteps"("AutomationRun_ID","Action_ID","AutomationRunStep_SortOrder","AutomationRunStep_Kind","AutomationRunStep_Label","AutomationRunStep_Status","AutomationRunStep_Detail","AutomationRunStep_StartedAt","AutomationRunStep_DurationMs") values(v_run,v_action."Action_ID",100+v_action."Action_SortOrder",v_action."Action_Kind",case when v_action."Action_Kind"='add-to-crm' then 'Add to CRM' else v_action."Action_Kind" end,'failed',sqlerrm,v_step_started,greatest(0,(extract(epoch from(clock_timestamp()-v_step_started))*1000)::integer));
      update public."CRM_ContactCardAutomationRuns" set "AutomationRun_Status"='failed',"AutomationRun_CompletedAt"=clock_timestamp(),"AutomationRun_DurationMs"=greatest(0,(extract(epoch from(clock_timestamp()-v_started))*1000)::integer),"AutomationRun_RecordsAffected"=v_actions,"AutomationRun_ErrorSummary"=sqlerrm,"AutomationRun_Recovery"=case when v_action."Action_Kind"='add-to-crm' then 'Open Add to CRM, correct the owner, pipeline, duplicate rule or mapping, publish the change, then rerun the failed steps.' else 'Open the failed step, correct its setup, publish the change, then rerun the failed steps.' end where "AutomationRun_ID"=v_run;
      return v_run;
    end;
  end loop;
  update public."CRM_ContactCardAutomationRuns" set "AutomationRun_Status"='succeeded',"AutomationRun_CompletedAt"=clock_timestamp(),"AutomationRun_DurationMs"=greatest(0,(extract(epoch from(clock_timestamp()-v_started))*1000)::integer),"AutomationRun_RecordsAffected"=v_actions where "AutomationRun_ID"=v_run;
  update public."CRM_ContactCardAutomations" set "Automation_LastRunAt"=case when p_is_test then "Automation_LastRunAt" else now() end,"Automation_AutoPausedReason"=null,"Automation_UpdatedAt"=now() where "ContactCard_ID"=p_card_id;
  return v_run;
end;
$_$;


ALTER FUNCTION "public"."_multideck_contact_card_execute_automation"("p_card_id" "uuid", "p_exchange_id" "uuid", "p_lead_id" "uuid", "p_input" "jsonb", "p_existing_lead" boolean, "p_is_test" boolean, "p_rerun_of" "uuid", "p_start_order" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_contact_card_watch_signal"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_card uuid; v_company uuid; v_old jsonb:='{}'; v_new jsonb:='{}';
begin
  if tg_table_name='CRM_ContactCards' then v_card:=new."ContactCard_ID"; v_company:=new."Company_ID"; v_old:=case when tg_op='INSERT' then '{}' else jsonb_build_object('status',old."ContactCard_Status") end; v_new:=jsonb_build_object('status',new."ContactCard_Status");
  elsif tg_table_name='CRM_ContactCardExchanges' then v_card:=new."ContactCard_ID"; select "Company_ID" into v_company from public."CRM_ContactCards" where "ContactCard_ID"=v_card; v_new:=jsonb_build_object('exchangeOutcome',new."Exchange_Outcome",'automationStatus',new."Exchange_AutomationOutcome");
  else v_card:=new."ContactCard_ID"; select "Company_ID" into v_company from public."CRM_ContactCards" where "ContactCard_ID"=v_card; v_new:=jsonb_build_object('automationStatus',new."AutomationRun_Status",'errorSummary',new."AutomationRun_ErrorSummary",'recordsAffected',new."AutomationRun_RecordsAffected"); end if;
  if v_company is not null and exists(select 1 from public."AI_DexterWatches" watch where watch."AIDexterWatch_CompanyID"=v_company and watch."AIDexterWatch_CapabilityCode"='contact_cards' and watch."AIDexterWatch_StatusCode"='active' and (watch."AIDexterWatch_TargetID" is null or watch."AIDexterWatch_TargetID"=v_card)) then insert into public."AI_DexterWatchSignals"("AIDexterWatchSignal_CompanyID","AIDexterWatchSignal_CapabilityCode","AIDexterWatchSignal_SourceTable","AIDexterWatchSignal_SourceID","AIDexterWatchSignal_OldJSON","AIDexterWatchSignal_NewJSON") values(v_company,'contact_cards',tg_table_name,v_card,v_old,v_new); end if;
  return new;
end; $$;


ALTER FUNCTION "public"."_multideck_contact_card_watch_signal"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_crm_account_code"("p_value" "text", "p_scope" "text") RETURNS "text"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_code text; v_supplied text:=btrim(coalesce(p_value,''));
begin
  if lower(coalesce(nullif(btrim(p_scope), ''), 'standard')) not in ('standard','national','global') then
    raise exception 'Choose a standard, national or global organisation scope.' using errcode = '22023';
  end if;
  -- A pre-existing imported code is compatibility data, even when it predates
  -- the Sage 50 rule. Preserve that exact value until the operator edits it.
  if length(regexp_replace(upper(v_supplied),'[^A-Z0-9]','','g'))>8 and exists(
    select 1 from public."Org_Master" where lower(btrim("Org_AccCode"))=lower(v_supplied)
  ) then return v_supplied; end if;
  v_code := left(regexp_replace(upper(v_supplied), '[^A-Z0-9]', '', 'g'), 8);
  if length(v_code) < 2 then raise exception 'Enter an organisation code with at least two letters or numbers.' using errcode = '22023'; end if;
  return v_code;
end;
$$;


ALTER FUNCTION "public"."_multideck_crm_account_code"("p_value" "text", "p_scope" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_crm_account_profile_company"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if tg_op = 'UPDATE' and old."CRMAccount_CompanyID" is not null then
    new."CRMAccount_CompanyID" := old."CRMAccount_CompanyID";
  elsif new."CRMAccount_CompanyID" is null then
    select actor."Company_ID" into new."CRMAccount_CompanyID"
    from public."cmp_Users" actor
    where actor."User_ID" in (new."CRMAccount_OwnerUserID", new."CRMAccount_CreatedBy", new."CRMAccount_UpdatedBy")
      and actor."Company_ID" is not null
    order by case actor."User_ID"
      when new."CRMAccount_OwnerUserID" then 0
      when new."CRMAccount_CreatedBy" then 1
      else 2
    end
    limit 1;
  end if;
  if new."CRMAccount_CompanyID" is null then
    raise exception 'CRM account company ownership is required.' using errcode = '23502';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."_multideck_crm_account_profile_company"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_crm_actor_company"("p_actor_user_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_company_id uuid;
begin
  select actor."Company_ID" into v_company_id
  from public."cmp_Users" actor
  where actor."User_ID" = p_actor_user_id
    and actor."Auth_User_ID" is not null
    and coalesce(actor."User_AccessStatus", 'active') = 'active';
  if v_company_id is null then
    raise exception 'The CRM operator is not linked to an active company.' using errcode = '42501';
  end if;
  return v_company_id;
end;
$$;


ALTER FUNCTION "public"."_multideck_crm_actor_company"("p_actor_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_crm_apply_lead_transfer"("p_lead_id" "uuid", "p_expected_owner_id" "uuid", "p_target_user_id" "uuid", "p_actor_user_id" "uuid", "p_company_id" "uuid", "p_reason" "text", "p_request_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_lead public."CRM_Leads"%rowtype; v_activity_type text; v_now timestamptz := now();
begin
  perform pg_advisory_xact_lock(hashtextextended(p_lead_id::text, 7231));
  select * into v_lead from public."CRM_Leads" where "CRMLead_ID" = p_lead_id and not "CRMLead_IsDeleted" for update;
  if not found then raise exception 'This lead no longer exists.' using errcode = 'P0002'; end if;
  if v_lead."CRMLead_OwnerUserID" is distinct from p_expected_owner_id then
    raise exception 'The lead owner changed while this request was open. Refresh and try again.' using errcode = '40001';
  end if;
  if not exists (select 1 from public."cmp_Users" where "User_ID" = p_target_user_id and "Company_ID" = p_company_id and "Auth_User_ID" is not null) then
    raise exception 'Choose an active user in this workspace.' using errcode = '22023';
  end if;
  if p_target_user_id = p_expected_owner_id then raise exception 'This user already owns the lead.' using errcode = '22023'; end if;

  update public."CRM_LeadAssignments" set "CRMLeadAssign_IsActive" = false, "CRMLeadAssign_EndedAt" = v_now
  where "CRMLeadAssign_LeadID" = p_lead_id and "CRMLeadAssign_IsActive";
  insert into public."CRM_LeadAssignments" ("CRMLeadAssign_LeadID", "CRMLeadAssign_AssignedUserID", "CRMLeadAssign_AssignmentRole", "CRMLeadAssign_AssignedAt", "CRMLeadAssign_AssignedBy")
  values (p_lead_id, p_target_user_id, 'owner', v_now, p_actor_user_id);
  update public."CRM_Leads" set "CRMLead_OwnerUserID" = p_target_user_id, "CRMLead_UpdatedAt" = v_now, "CRMLead_UpdatedBy" = p_actor_user_id
  where "CRMLead_ID" = p_lead_id;
  update public."CRM_Opportunities" opportunity
  set "CRMOppty_OwnerUserID" = p_target_user_id, "CRMOppty_UpdatedAt" = v_now, "CRMOppty_UpdatedBy" = p_actor_user_id
  from public."sys_CRMOpportunityStatuses" status
  where opportunity."CRMOppty_SourceLeadID" = p_lead_id and opportunity."CRMOppty_StatusCode" = status."CRMOpptyStatus_Code"
    and status."CRMOpptyStatus_IsOpen" and not opportunity."CRMOppty_IsDeleted";

  update public."CRM_LeadTransferRequests"
  set "CRMLeadTransfer_Status" = case when "CRMLeadTransfer_ID" = p_request_id then 'approved' else 'superseded' end,
      "CRMLeadTransfer_DecisionReason" = case when "CRMLeadTransfer_ID" = p_request_id then nullif(btrim(p_reason), '') else 'Ownership changed before this request was decided.' end,
      "CRMLeadTransfer_DecidedAt" = v_now, "CRMLeadTransfer_DecidedBy" = p_actor_user_id, "CRMLeadTransfer_UpdatedAt" = v_now
  where "CRMLeadTransfer_LeadID" = p_lead_id and "CRMLeadTransfer_Status" = 'pending';

  select "CRMActType_Code" into v_activity_type from public."sys_CRMActivityTypes" where "CRMActType_IsActive" order by "CRMActType_SortOrder" limit 1;
  if v_activity_type is not null then
    insert into public."CRM_Activities" ("CRMActivity_ActivityTypeCode", "CRMActivity_LeadID", "CRMActivity_Subject", "CRMActivity_Summary", "CRMActivity_OwnerUserID", "CRMActivity_MetadataJSON", "CRMActivity_CreatedBy", "CRMActivity_UpdatedBy")
    values (v_activity_type, p_lead_id, 'Lead ownership changed', nullif(btrim(p_reason), ''), p_target_user_id,
      jsonb_build_object('event', 'lead_ownership_changed', 'fromUserId', p_expected_owner_id, 'toUserId', p_target_user_id, 'requestId', p_request_id), p_actor_user_id, p_actor_user_id);
  end if;
  insert into public."Comm_Notifications" ("CommNotif_UserID", "CommNotif_Title", "CommNotif_Body", "CommNotif_TargetTable", "CommNotif_TargetID", "CommNotif_LinkTypeCode", "CommNotif_MetadataJSON", "CommNotif_CreatedBy")
  select recipient_id, 'CRM lead ownership changed', coalesce(nullif(btrim(p_reason), ''), 'The lead owner was updated.'), 'CRM_Leads', p_lead_id, null,
    jsonb_build_object('event', 'lead_ownership_changed', 'fromUserId', p_expected_owner_id, 'toUserId', p_target_user_id), p_actor_user_id
  from (values (p_expected_owner_id), (p_target_user_id)) recipients(recipient_id)
  where recipient_id is not null;
  return public._multideck_crm_lead_json(p_lead_id) || jsonb_build_object('pendingTransfer', null);
end;
$$;


ALTER FUNCTION "public"."_multideck_crm_apply_lead_transfer"("p_lead_id" "uuid", "p_expected_owner_id" "uuid", "p_target_user_id" "uuid", "p_actor_user_id" "uuid", "p_company_id" "uuid", "p_reason" "text", "p_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_crm_contact_profile_company"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if tg_op = 'UPDATE' and old."CRMContact_CompanyID" is not null then
    new."CRMContact_CompanyID" := old."CRMContact_CompanyID";
  elsif new."CRMContact_CompanyID" is null then
    select coalesce(
      (
        select account."CRMAccount_CompanyID"
        from public."Org_Contacts" contact
        join public."CRM_AccountProfiles" account
          on account."CRMAccount_OrgID" = contact."Org_ID"
         and not account."CRMAccount_IsDeleted"
        where contact."OrgContact_ID" = new."CRMContact_OrgContactID"
          and account."CRMAccount_CompanyID" is not null
        order by account."CRMAccount_ID"
        limit 1
      ),
      (
        select actor."Company_ID"
        from public."cmp_Users" actor
        where actor."User_ID" = new."CRMContact_CreatedBy"
          and actor."Company_ID" is not null
        limit 1
      ),
      (
        select actor."Company_ID"
        from public."cmp_Users" actor
        where actor."User_ID" = new."CRMContact_UpdatedBy"
          and actor."Company_ID" is not null
        limit 1
      )
    ) into new."CRMContact_CompanyID";
  end if;
  if new."CRMContact_CompanyID" is null then
    raise exception 'CRM contact company ownership is required.' using errcode = '23502';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."_multideck_crm_contact_profile_company"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_crm_context"() RETURNS TABLE("user_id" "uuid", "company_id" "uuid")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
begin
  if auth.uid() is null then
    raise exception 'Sign in again to use CRM.' using errcode = '42501';
  end if;

  return query
  select u."User_ID", u."Company_ID"
  from public."cmp_Users" u
  where u."Auth_User_ID" = auth.uid()
  limit 1;

  if not found then
    raise exception 'Your signed-in account is not linked to this Multideck workspace.' using errcode = '42501';
  end if;
end;
$$;


ALTER FUNCTION "public"."_multideck_crm_context"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_crm_convert_lead_with_org_20260818"("p_lead_id" "uuid", "p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_context record;
  v_lead record;
  v_existing_id uuid;
  v_deal_id uuid := gen_random_uuid();
  v_name text := nullif(btrim(p_input ->> 'name'), '');
  v_type_code text := nullif(btrim(p_input ->> 'opportunityTypeCode'), '');
  v_primary_contact_id uuid := nullif(p_input ->> 'primaryContactId', '')::uuid;
  v_expected_close_date date := nullif(p_input ->> 'expectedCloseDate', '')::date;
  v_expected_value numeric := nullif(p_input ->> 'expectedValueAmount', '')::numeric;
  v_expected_margin numeric := nullif(p_input ->> 'expectedMarginAmount', '')::numeric;
  v_currency text := upper(nullif(btrim(p_input ->> 'currencyCode'), ''));
  v_probability numeric := coalesce(nullif(p_input ->> 'probabilityPct', '')::numeric, 0);
  v_next_action timestamptz := nullif(p_input ->> 'nextActionDueAt', '')::timestamptz;
  v_customer_need text := nullif(btrim(p_input ->> 'customerNeed'), '');
  v_pipeline record;
  v_pipeline_stage record;
  v_stage_code text;
  v_status_code text;
  v_forecast_code text;
  v_converted_status text;
  v_account_id uuid;
begin
  select * into v_context from public._multideck_crm_context();
  perform pg_advisory_xact_lock(hashtextextended(p_lead_id::text, 0));

  select deal."CRMOppty_ID" into v_existing_id
  from public."CRM_Opportunities" deal
  join public."CRM_Pipelines" pipeline
    on pipeline."CRMPipeline_ID" = deal."CRMOppty_PipelineID"
  where deal."CRMOppty_SourceLeadID" = p_lead_id
    and not deal."CRMOppty_IsDeleted"
    and pipeline."Company_ID" = v_context.company_id
    and not pipeline."Is_Deleted"
  limit 1;

  if v_existing_id is not null then
    return public._multideck_crm_deal_json(v_existing_id, v_context.company_id)
      || jsonb_build_object('wasAlreadyConverted', true);
  end if;

  select * into v_lead
  from public."CRM_Leads"
  where "CRMLead_ID" = p_lead_id and not "CRMLead_IsDeleted"
  for update;

  if not found then
    raise exception 'Lead not found.' using errcode = 'P0002';
  end if;
  if v_lead."CRMLead_OrgID" is null then
    raise exception 'Add a company to this lead before converting it to a deal.' using errcode = '22023';
  end if;
  if v_name is null then
    raise exception 'Give the deal a name.' using errcode = '22023';
  end if;
  if length(v_name) > 240 then
    raise exception 'Deal names must be 240 characters or fewer.' using errcode = '22023';
  end if;
  if v_type_code is null then
    raise exception 'Choose a deal type.' using errcode = '22023';
  end if;
  if v_expected_close_date is null or v_expected_close_date < current_date then
    raise exception 'Expected close date cannot be in the past.' using errcode = '22023';
  end if;
  if coalesce(v_expected_value, 0) < 0 then
    raise exception 'Expected value cannot be negative.' using errcode = '22023';
  end if;
  if coalesce(v_expected_margin, 0) < 0 then
    raise exception 'Expected margin cannot be negative.' using errcode = '22023';
  end if;
  if (v_expected_value is not null or v_expected_margin is not null) and v_currency is null then
    raise exception 'Choose a currency for the commercial values.' using errcode = '22023';
  end if;
  if v_probability < 0 or v_probability > 100 then
    raise exception 'Probability must be between 0 and 100.' using errcode = '22023';
  end if;
  if v_customer_need is null then
    raise exception 'Describe what the customer needs from this deal.' using errcode = '22023';
  end if;
  if v_next_action is null or v_next_action <= now() then
    raise exception 'Next action must be in the future.' using errcode = '22023';
  end if;

  if v_primary_contact_id is not null and not exists (
    select 1
    from public."Org_Contacts"
    where "OrgContact_ID" = v_primary_contact_id
      and "Org_ID" = v_lead."CRMLead_OrgID"
  ) then
    raise exception 'Choose a contact linked to this lead''s company.' using errcode = '22023';
  end if;

  if not exists (
    select 1
    from public."sys_CRMOpportunityTypes"
    where "CRMOpptyType_Code" = v_type_code
      and "CRMOpptyType_IsActive"
  ) then
    raise exception 'Choose an active deal type.' using errcode = '22023';
  end if;

  select * into v_pipeline
  from public."CRM_Pipelines"
  where "Company_ID" = v_context.company_id and not "Is_Deleted"
  order by "CRMPipeline_SortOrder"
  limit 1;
  if not found then
    raise exception 'Create a deal pipeline before converting this lead.' using errcode = '22023';
  end if;

  select * into v_pipeline_stage
  from public."CRM_PipelineStages"
  where "Company_ID" = v_context.company_id
    and "CRMPipeline_ID" = v_pipeline."CRMPipeline_ID"
    and not "Is_Deleted"
  order by "CRMPipelineStage_IsDefaultEntry" desc, "CRMPipelineStage_SortOrder"
  limit 1;
  if not found then
    raise exception 'Add an entry stage to this deal pipeline before converting this lead.' using errcode = '22023';
  end if;

  select "CRMStage_Code" into v_stage_code
  from public."sys_CRMOpportunityStages"
  where "CRMStage_IsActive" and "CRMStage_IsOpen"
  order by "CRMStage_SortOrder"
  limit 1;

  select "CRMOpptyStatus_Code" into v_status_code
  from public."sys_CRMOpportunityStatuses"
  where "CRMOpptyStatus_IsActive" and "CRMOpptyStatus_IsOpen"
  order by "CRMOpptyStatus_SortOrder"
  limit 1;

  select "CRMForecast_Code" into v_forecast_code
  from public."sys_CRMForecastCategories"
  where "CRMForecast_IsActive" and "CRMForecast_IsIncluded"
  order by "CRMForecast_SortOrder"
  limit 1;

  select "CRMLeadStatus_Code" into v_converted_status
  from public."sys_CRMLeadStatuses"
  where "CRMLeadStatus_IsActive" and "CRMLeadStatus_IsConverted"
  order by "CRMLeadStatus_SortOrder"
  limit 1;

  if v_stage_code is null or v_status_code is null or v_forecast_code is null or v_converted_status is null then
    raise exception 'The workspace CRM lookups are incomplete.' using errcode = '55000';
  end if;

  select "CRMAccount_ID" into v_account_id
  from public."CRM_AccountProfiles"
  where "CRMAccount_OrgID" = v_lead."CRMLead_OrgID"
    and not "CRMAccount_IsDeleted"
  limit 1;

  insert into public."CRM_Opportunities" (
    "CRMOppty_ID",
    "CRMOppty_AccountID",
    "CRMOppty_OrgID",
    "CRMOppty_PrimaryContactID",
    "CRMOppty_SourceLeadID",
    "CRMOppty_OwnerUserID",
    "CRMOppty_OrgOfficeID",
    "CRMOppty_LegalEntityID",
    "CRMOppty_BrandID",
    "CRMOppty_PipelineID",
    "CRMOppty_PipelineStageID",
    "CRMOppty_Name",
    "CRMOppty_TypeCode",
    "CRMOppty_StageCode",
    "CRMOppty_StatusCode",
    "CRMOppty_ForecastCategoryCode",
    "CRMOppty_ModeCode",
    "CRMOppty_DirectionCode",
    "CRMOppty_OriginNameSnapshot",
    "CRMOppty_DestinationNameSnapshot",
    "CRMOppty_TradeLane",
    "CRMOppty_ServiceInterest",
    "CRMOppty_ExpectedCloseDate",
    "CRMOppty_ProbabilityPct",
    "CRMOppty_ExpectedValueAmount",
    "CRMOppty_ExpectedMarginAmount",
    "CRMOppty_CurrencyCode",
    "CRMOppty_WeightedValueAmount",
    "CRMOppty_NextActionDueAt",
    "CRMOppty_LastActivityAt",
    "CRMOppty_CustomerNeed",
    "CRMOppty_ValueProposition",
    "CRMOppty_MetadataJSON",
    "CRMOppty_CreatedAt",
    "CRMOppty_CreatedBy",
    "CRMOppty_UpdatedAt",
    "CRMOppty_UpdatedBy",
    "CRMOppty_IsDeleted"
  )
  values (
    v_deal_id,
    v_account_id,
    v_lead."CRMLead_OrgID",
    coalesce(v_primary_contact_id, v_lead."CRMLead_PrimaryContactID"),
    p_lead_id,
    coalesce(v_lead."CRMLead_OwnerUserID", v_context.user_id),
    v_lead."CRMLead_OrgOfficeID",
    v_lead."CRMLead_LegalEntityID",
    v_lead."CRMLead_BrandID",
    v_pipeline."CRMPipeline_ID",
    v_pipeline_stage."CRMPipelineStage_ID",
    v_name,
    v_type_code,
    v_stage_code,
    v_status_code,
    v_forecast_code,
    coalesce(nullif(btrim(p_input ->> 'modeCode'), ''), v_lead."CRMLead_ModeCode"),
    coalesce(nullif(btrim(p_input ->> 'directionCode'), ''), v_lead."CRMLead_DirectionCode"),
    nullif(btrim(p_input ->> 'originName'), ''),
    nullif(btrim(p_input ->> 'destinationName'), ''),
    coalesce(nullif(btrim(p_input ->> 'tradeLane'), ''), v_lead."CRMLead_TradeLane"),
    coalesce(nullif(btrim(p_input ->> 'serviceInterest'), ''), v_lead."CRMLead_ServiceInterest"),
    v_expected_close_date,
    round(v_probability, 2),
    v_expected_value,
    v_expected_margin,
    v_currency,
    case when v_expected_value is null then null else round(v_expected_value * v_probability / 100, 4) end,
    v_next_action,
    v_lead."CRMLead_LastInteractionAt",
    v_customer_need,
    nullif(btrim(p_input ->> 'valueProposition'), ''),
    jsonb_build_object('convertedFromLeadId', p_lead_id, 'conversionSource', 'lead_conversion_wizard'),
    now(),
    v_context.user_id,
    now(),
    v_context.user_id,
    false
  );

  insert into public."CRM_OpportunityStageHistory" (
    "CRMOpptyStage_ID",
    "CRMOpptyStage_OpportunityID",
    "CRMOpptyStage_ToStageCode",
    "CRMOpptyStage_ProbabilityPct",
    "CRMOpptyStage_Reason",
    "CRMOpptyStage_ChangedAt",
    "CRMOpptyStage_ChangedBy"
  )
  values (
    gen_random_uuid(),
    v_deal_id,
    v_stage_code,
    v_probability,
    'Created from lead conversion',
    now(),
    v_context.user_id
  );

  insert into public."CRM_LeadConversions" (
    "CRMLeadConv_ID",
    "CRMLeadConv_LeadID",
    "CRMLeadConv_OrgID",
    "CRMLeadConv_AccountID",
    "CRMLeadConv_OpportunityID",
    "CRMLeadConv_ConvertedAt",
    "CRMLeadConv_ConvertedBy",
    "CRMLeadConv_ConversionNotes"
  )
  values (
    gen_random_uuid(),
    p_lead_id,
    v_lead."CRMLead_OrgID",
    v_account_id,
    v_deal_id,
    now(),
    v_context.user_id,
    nullif(btrim(p_input ->> 'conversionNotes'), '')
  );

  insert into public."CRM_LeadStatusHistory" (
    "CRMLeadStatus_ID",
    "CRMLeadStatus_LeadID",
    "CRMLeadStatus_FromStatusCode",
    "CRMLeadStatus_ToStatusCode",
    "CRMLeadStatus_Reason",
    "CRMLeadStatus_ChangedAt",
    "CRMLeadStatus_ChangedBy"
  )
  values (
    gen_random_uuid(),
    p_lead_id,
    v_lead."CRMLead_StatusCode",
    v_converted_status,
    'Converted to deal',
    now(),
    v_context.user_id
  );

  update public."CRM_Leads"
  set
    "CRMLead_StatusCode" = v_converted_status,
    "CRMLead_UpdatedAt" = now(),
    "CRMLead_UpdatedBy" = v_context.user_id
  where "CRMLead_ID" = p_lead_id;

  return public._multideck_crm_deal_json(v_deal_id, v_context.company_id);
end;
$$;


ALTER FUNCTION "public"."_multideck_crm_convert_lead_with_org_20260818"("p_lead_id" "uuid", "p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_crm_create_account_pre_reference_rules_20260820"("p_actor_user_id" "uuid", "p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_result jsonb;
  v_org_id uuid;
  v_profile public."CRM_AccountProfiles"%rowtype;
  v_address_id uuid;
  v_type_id integer;
  v_scope text := lower(coalesce(nullif(btrim(p_input ->> 'scopeCode'), ''), 'standard'));
begin
  v_result := public._multideck_crm_create_account_prefoundation_20260820(p_actor_user_id, p_input);
  v_org_id := (v_result ->> 'id')::uuid;
  select * into v_profile from public."CRM_AccountProfiles"
  where "CRMAccount_OrgID" = v_org_id and not "CRMAccount_IsDeleted"
  order by "CRMAccount_ID" limit 1;

  update public."CRM_AccountProfiles"
  set "CRMAccount_ScopeCode" = v_scope
  where "CRMAccount_ID" = v_profile."CRMAccount_ID";
  if nullif(btrim(p_input ->> 'accountCode'), '') is not null then
    update public."Org_Master"
    set "Org_AccCode" = public._multideck_crm_account_code(p_input ->> 'accountCode', v_scope)
    where "Org_id" = v_org_id;
  end if;
  if v_profile."CRMAccount_OrgOfficeID" is not null then
    insert into public."CRM_AccountOfficeAssignments"(
      "CRMAccountOffice_AccountID", "CRMAccountOffice_CompanyID", "CRMAccountOffice_OrgOfficeID",
      "CRMAccountOffice_IsPrimary", "CRMAccountOffice_CreatedBy"
    ) values (
      v_profile."CRMAccount_ID", v_profile."CRMAccount_CompanyID", v_profile."CRMAccount_OrgOfficeID", true, p_actor_user_id
    ) on conflict ("CRMAccountOffice_AccountID", "CRMAccountOffice_OrgOfficeID") do update
      set "CRMAccountOffice_IsPrimary" = true;
  end if;
  select "OrgAdd_ID" into v_address_id from public."Org_Addresses"
  where "Org_ID" = v_org_id and "OrgAdd_IsActive" order by "OrgAdd_ID" limit 1;
  select "sys_AddressType_ID" into v_type_id from public."sys_AddressTypes"
  where "sys_AddressType_Code" = 'main' limit 1;
  if v_address_id is not null and v_type_id is not null then
    insert into public."Org_AddressTypes"(
      "OrgAdd_ID", "OrgAddType_Type", "OrgAddType_IsDefault", "OrgAddType_OrgID"
    ) values (v_address_id, v_type_id, true, v_org_id)
    on conflict ("OrgAdd_ID", "OrgAddType_Type") do update set "OrgAddType_IsDefault" = true;
  end if;
  return v_result || jsonb_build_object('scopeCode', v_scope);
end;
$$;


ALTER FUNCTION "public"."_multideck_crm_create_account_pre_reference_rules_20260820"("p_actor_user_id" "uuid", "p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_crm_create_account_pre_sage8_20260820"("p_actor_user_id" "uuid", "p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'quote_api'
    AS $$
declare
  v_result jsonb;
  v_org uuid;
  v_company uuid;
  v_candidate text;
begin
  v_result := public._multideck_crm_create_account_pre_reference_rules_20260820(p_actor_user_id, p_input);
  v_org := (v_result ->> 'id')::uuid;
  if nullif(btrim(p_input ->> 'accountCode'), '') is not null then
    select "Org_AccCode" into v_candidate from public."Org_Master" where "Org_id" = v_org;
    return v_result || jsonb_build_object('accountCode', v_candidate);
  end if;
  select "Company_ID" into v_company
  from public."cmp_Users"
  where "User_ID" = p_actor_user_id and "User_AccessStatus" = 'active';
  if v_company is null then
    raise exception 'The workspace company could not be resolved.' using errcode = '42501';
  end if;
  v_candidate := quote_api.allocate_customer_reference(v_company);
  update public."Org_Master" set "Org_AccCode" = v_candidate where "Org_id" = v_org;
  return v_result || jsonb_build_object('accountCode', v_candidate);
end;
$$;


ALTER FUNCTION "public"."_multideck_crm_create_account_pre_sage8_20260820"("p_actor_user_id" "uuid", "p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_crm_create_account_prefoundation_20260820"("p_actor_user_id" "uuid", "p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_result jsonb;
  v_type_ids uuid[];
  v_legacy_input jsonb;
  v_is_customer boolean;
begin
  perform public._multideck_crm_actor_company(p_actor_user_id);
  if jsonb_typeof(p_input -> 'orgTypeIds') <> 'array' then
    raise exception 'Choose at least one company type.' using errcode = '22023';
  end if;
  select array_agg(distinct value::uuid) into v_type_ids
  from jsonb_array_elements_text(p_input -> 'orgTypeIds') item(value);
  if coalesce(cardinality(v_type_ids), 0) < 1 or cardinality(v_type_ids) > 12 then
    raise exception 'Choose between 1 and 12 company types.' using errcode = '22023';
  end if;
  if (select count(*) from public."Org_Types" where "OrgType_ID" = any(v_type_ids)) <> cardinality(v_type_ids) then
    raise exception 'Choose valid company types.' using errcode = '22023';
  end if;

  v_legacy_input := jsonb_set(p_input - 'orgTypeIds', '{orgTypeId}', to_jsonb(v_type_ids[1]::text), true);
  v_result := public._multideck_crm_create_account_unscoped_20260818(p_actor_user_id, v_legacy_input);

  insert into public."Org_Master_Type"("Org_ID", "OrgType_ID")
  select (v_result ->> 'id')::uuid, type_id
  from unnest(v_type_ids) type_id
  on conflict ("OrgType_ID", "Org_ID") do nothing;

  select exists (
    select 1 from public."Org_Types" type
    where type."OrgType_ID" = any(v_type_ids)
      and lower(type."OrgType_Name") in ('customer', 'potential customer', 'key customer account')
  ) into v_is_customer;
  update public."Org_Master"
  set "Org_CRMIsPotentialCustomer" = v_is_customer,
      "Org_CRMUpdatedAt" = now()
  where "Org_id" = (v_result ->> 'id')::uuid;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."_multideck_crm_create_account_prefoundation_20260820"("p_actor_user_id" "uuid", "p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_crm_create_account_unscoped_20260818"("p_actor_user_id" "uuid", "p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  v_name text := nullif(btrim(p_input ->> 'name'), '');
  v_org_id uuid := gen_random_uuid();
  v_account_id uuid := gen_random_uuid();
  v_contact_id uuid;
  v_email text := lower(nullif(btrim(p_input ->> 'contactEmail'), ''));
  v_country text := upper(nullif(btrim(p_input ->> 'countryCode'), ''));
  v_currency uuid;
  v_now timestamptz := now();
begin
  perform public._multideck_crm_write_actor(p_actor_user_id);
  if v_name is null then raise exception 'Enter an account name.' using errcode = '22023'; end if;
  if v_country is not null and v_country !~ '^[A-Z]{2}$' then raise exception 'Enter a two-letter ISO country code, such as GB.' using errcode = '22023'; end if;
  if p_input ->> 'orgTypeId' is null or not exists (select 1 from public."Org_Types" where "OrgType_ID" = (p_input ->> 'orgTypeId')::uuid) then
    raise exception 'Choose a valid organisation type.' using errcode = '22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(lower(v_name), 0));
  if exists (select 1 from public."Org_Master" where lower(btrim("Org_Name")) = lower(v_name)) then
    raise exception 'An account named ''%'' already exists.', v_name using errcode = '23505';
  end if;
  if v_email is not null then
    perform pg_advisory_xact_lock(hashtextextended(v_email, 0));
    if exists (select 1 from public."OrgContact_Emails" where lower(btrim("OrgContactEmail_Email")) = v_email) then
      raise exception 'This email is already connected to a contact.' using errcode = '23505';
    end if;
  end if;
  select "Currency_ID" into v_currency
  from public."sys_Currency"
  order by case when "Currency_Code" = 'GBP' then 0 else 1 end, "Currency_Code"
  limit 1;
  if v_currency is null then raise exception 'No base currency is configured for this workspace.' using errcode = '23503'; end if;

  insert into public."Org_Master"(
    "Org_id", "Org_Name", "Org_BaseCurrency", "Org_AccCode", "Org_CRMRelationshipStatusCode",
    "Org_CRMIsPotentialCustomer", "Org_CRMIsLead", "Org_CRMUpdatedAt"
  ) values (
    v_org_id, v_name, v_currency,
    coalesce(nullif(left(regexp_replace(upper(v_name), '[^A-Z0-9]', '', 'g'), 11), ''), 'ACCOUNT') || '-' || upper(left(replace(v_org_id::text, '-', ''), 6)),
    'active_customer', true, false, v_now
  );
  insert into public."Org_Master_Type"("Org_ID", "OrgType_ID") values (v_org_id, (p_input ->> 'orgTypeId')::uuid);
  insert into public."CRM_AccountProfiles"(
    "CRMAccount_ID", "CRMAccount_OrgID", "CRMAccount_RelationshipStatusCode",
    "CRMAccount_OwnerUserID", "CRMAccount_CreatedBy", "CRMAccount_UpdatedBy", "CRMAccount_EditVersion"
  ) values (v_account_id, v_org_id, 'active_customer', p_actor_user_id, p_actor_user_id, p_actor_user_id, 1);
  if coalesce(nullif(btrim(p_input ->> 'addressLine1'), ''), nullif(btrim(p_input ->> 'townCity'), ''), v_country) is not null then
    insert into public."Org_Addresses"("OrgAdd_ID", "Org_ID", "OrgAdd_Line1", "OrgAdd_TownCity", "OrgAdd_PostZipCode", "OrgAdd_Country")
    values (gen_random_uuid(), v_org_id, nullif(btrim(p_input ->> 'addressLine1'), ''), nullif(btrim(p_input ->> 'townCity'), ''), nullif(btrim(p_input ->> 'postZipCode'), ''), v_country);
  end if;
  if nullif(btrim(p_input ->> 'contactFirstName'), '') is not null or nullif(btrim(p_input ->> 'contactLastName'), '') is not null or v_email is not null then
    v_contact_id := gen_random_uuid();
    insert into public."Org_Contacts"("OrgContact_ID", "Org_ID", "OrgContact_FirstName", "OrgContact_LastName")
    values (v_contact_id, v_org_id, nullif(btrim(p_input ->> 'contactFirstName'), ''), nullif(btrim(p_input ->> 'contactLastName'), ''));
    insert into public."CRM_ContactProfiles"("CRMContact_ID", "CRMContact_OrgContactID", "CRMContact_AccountID", "CRMContact_CreatedBy", "CRMContact_UpdatedBy", "CRMContact_EditVersion")
    values (gen_random_uuid(), v_contact_id, v_account_id, p_actor_user_id, p_actor_user_id, 1);
    if v_email is not null then
      insert into public."OrgContact_Emails"("OrgContactEmail_ID", "OrgContact_ID", "OrgContactEmail_Email", "OrgContactEmail_Type")
      values (gen_random_uuid(), v_contact_id, v_email, 1);
    end if;
  end if;
  return jsonb_build_object('id', v_org_id, 'editVersion', 1);
end;
$_$;


ALTER FUNCTION "public"."_multideck_crm_create_account_unscoped_20260818"("p_actor_user_id" "uuid", "p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_crm_create_contact_prefoundation_20260820"("p_actor_user_id" "uuid", "p_account_id" "uuid", "p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  perform public._multideck_crm_require_account_access(p_actor_user_id, p_account_id);
  return public._multideck_crm_create_contact_unscoped_20260818(p_actor_user_id, p_account_id, p_input);
end;
$$;


ALTER FUNCTION "public"."_multideck_crm_create_contact_prefoundation_20260820"("p_actor_user_id" "uuid", "p_account_id" "uuid", "p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_crm_create_contact_unscoped_20260818"("p_actor_user_id" "uuid", "p_account_id" "uuid", "p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_contact_id uuid := gen_random_uuid();
  v_email text := lower(nullif(btrim(p_input ->> 'email'), ''));
  v_first text := nullif(btrim(p_input ->> 'firstName'), '');
  v_last text := nullif(btrim(p_input ->> 'lastName'), '');
  v_account_id uuid;
begin
  perform public._multideck_crm_write_actor(p_actor_user_id);
  if v_email is null then raise exception 'Enter a contact email address.' using errcode = '22023'; end if;
  if v_first is null and v_last is null then raise exception 'Enter the contact''s name.' using errcode = '22023'; end if;
  perform pg_advisory_xact_lock(hashtextextended(v_email, 0));
  select account."CRMAccount_ID" into v_account_id
  from public."CRM_AccountProfiles" account
  join public."Org_Master" org on org."Org_id" = account."CRMAccount_OrgID"
  where org."Org_id" = p_account_id and not account."CRMAccount_IsDeleted"
  limit 1;
  if v_account_id is null then raise exception 'Choose an existing account.' using errcode = 'P0002'; end if;
  if exists (select 1 from public."OrgContact_Emails" where lower(btrim("OrgContactEmail_Email")) = v_email) then
    raise exception 'This email is already connected to a contact.' using errcode = '23505';
  end if;
  insert into public."Org_Contacts"("OrgContact_ID", "Org_ID", "OrgContact_FirstName", "OrgContact_LastName")
  values (v_contact_id, p_account_id, v_first, v_last);
  insert into public."OrgContact_Emails"("OrgContactEmail_ID", "OrgContact_ID", "OrgContactEmail_Email", "OrgContactEmail_Type")
  values (gen_random_uuid(), v_contact_id, v_email, 1);
  insert into public."CRM_ContactProfiles"("CRMContact_ID", "CRMContact_OrgContactID", "CRMContact_AccountID", "CRMContact_CreatedBy", "CRMContact_UpdatedBy", "CRMContact_EditVersion")
  values (gen_random_uuid(), v_contact_id, v_account_id, p_actor_user_id, p_actor_user_id, 1);

  -- Additional fields use the same atomic update path, preserving one response
  -- contract and one activity entry for a fully populated contact.
  if p_input ? 'role' or p_input ? 'jobTitle' or p_input ? 'department' or p_input ? 'marketingOptIn' or p_input ? 'phone' then
    return public.multideck_crm_update_contact(p_actor_user_id, v_contact_id, 1, p_input);
  end if;
  return jsonb_build_object('id', v_contact_id, 'accountId', p_account_id, 'editVersion', 1);
end;
$$;


ALTER FUNCTION "public"."_multideck_crm_create_contact_unscoped_20260818"("p_actor_user_id" "uuid", "p_account_id" "uuid", "p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_crm_customer_watch_signal"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_company uuid;
  v_source uuid;
  v_old jsonb := '{}'::jsonb;
  v_new jsonb := '{}'::jsonb;
begin
  if tg_table_name = 'Org_Master' then
    v_source := new."Org_id";
    select profile."CRMAccount_CompanyID" into v_company
    from public."CRM_AccountProfiles" profile
    where profile."CRMAccount_OrgID" = new."Org_id"
      and not profile."CRMAccount_IsDeleted"
    order by profile."CRMAccount_ID"
    limit 1;
    if tg_op <> 'INSERT' then
      v_old := jsonb_build_object('recordType', 'account', 'name', old."Org_Name", 'relationshipStatus', old."Org_CRMRelationshipStatusCode");
    end if;
    v_new := jsonb_build_object('recordType', 'account', 'name', new."Org_Name", 'relationshipStatus', new."Org_CRMRelationshipStatusCode");
  elsif tg_table_name = 'CRM_AccountProfiles' then
    v_company := new."CRMAccount_CompanyID";
    v_source := new."CRMAccount_OrgID";
    if tg_op <> 'INSERT' then
      v_old := jsonb_build_object('recordType', 'account', 'relationshipStatus', old."CRMAccount_RelationshipStatusCode", 'tier', old."CRMAccount_Tier", 'segment', old."CRMAccount_Segment", 'healthScore', old."CRMAccount_HealthScore", 'churnRiskScore', old."CRMAccount_ChurnRiskScore", 'lastContactAt', old."CRMAccount_LastContactAt", 'nextActionDueAt', old."CRMAccount_NextActionDueAt");
    end if;
    v_new := jsonb_build_object('recordType', 'account', 'relationshipStatus', new."CRMAccount_RelationshipStatusCode", 'tier', new."CRMAccount_Tier", 'segment', new."CRMAccount_Segment", 'healthScore', new."CRMAccount_HealthScore", 'churnRiskScore', new."CRMAccount_ChurnRiskScore", 'lastContactAt', new."CRMAccount_LastContactAt", 'nextActionDueAt', new."CRMAccount_NextActionDueAt");
  elsif tg_table_name = 'Org_Contacts' then
    v_source := new."OrgContact_ID";
    select profile."CRMContact_CompanyID" into v_company
    from public."CRM_ContactProfiles" profile
    where profile."CRMContact_OrgContactID" = new."OrgContact_ID"
    order by profile."CRMContact_ID"
    limit 1;
    if tg_op <> 'INSERT' then
      v_old := jsonb_build_object('recordType', 'contact', 'name', nullif(btrim(concat_ws(' ', old."OrgContact_FirstName", old."OrgContact_LastName")), ''));
    end if;
    v_new := jsonb_build_object('recordType', 'contact', 'name', nullif(btrim(concat_ws(' ', new."OrgContact_FirstName", new."OrgContact_LastName")), ''));
  elsif tg_table_name = 'CRM_ContactProfiles' then
    v_company := new."CRMContact_CompanyID";
    v_source := new."CRMContact_OrgContactID";
    if tg_op <> 'INSERT' then
      v_old := jsonb_build_object('recordType', 'contact', 'role', old."CRMContact_RoleCode", 'influenceLevel', old."CRMContact_InfluenceLevel", 'relationshipStrength', old."CRMContact_RelationshipStrength", 'preferredChannel', old."CRMContact_PreferredChannelCode", 'salesContactAllowed', old."CRMContact_ConsentSalesContact", 'lastContactAt', old."CRMContact_LastContactAt");
    end if;
    v_new := jsonb_build_object('recordType', 'contact', 'role', new."CRMContact_RoleCode", 'influenceLevel', new."CRMContact_InfluenceLevel", 'relationshipStrength', new."CRMContact_RelationshipStrength", 'preferredChannel', new."CRMContact_PreferredChannelCode", 'salesContactAllowed', new."CRMContact_ConsentSalesContact", 'lastContactAt', new."CRMContact_LastContactAt");
  else
    return new;
  end if;

  if (
    tg_table_name in ('Org_Master', 'CRM_AccountProfiles')
    and exists (
      select 1 from public."CRM_AccountProfiles" fixture
      where fixture."CRMAccount_OrgID" = v_source
        and not fixture."CRMAccount_IsDeleted"
        and lower(coalesce(fixture."CRMAccount_MetadataJSON" ->> 'developmentFixture', 'false')) = 'true'
    )
  ) or (
    tg_table_name in ('Org_Contacts', 'CRM_ContactProfiles')
    and exists (
      select 1 from public."CRM_ContactProfiles" fixture
      where fixture."CRMContact_OrgContactID" = v_source
        and lower(coalesce(fixture."CRMContact_MetadataJSON" ->> 'developmentFixture', 'false')) = 'true'
    )
  ) then
    return new;
  end if;

  if v_company is not null and v_source is not null and v_new is distinct from v_old then
    insert into public."AI_DexterWatchSignals"(
      "AIDexterWatchSignal_CompanyID", "AIDexterWatchSignal_CapabilityCode", "AIDexterWatchSignal_SourceTable",
      "AIDexterWatchSignal_SourceID", "AIDexterWatchSignal_OldJSON", "AIDexterWatchSignal_NewJSON"
    )
    select distinct v_company, 'customers', tg_table_name, v_source, v_old, v_new
    from public."AI_DexterWatches" watch
    where watch."AIDexterWatch_CompanyID" = v_company
      and watch."AIDexterWatch_CapabilityCode" = 'customers'
      and watch."AIDexterWatch_StatusCode" = 'active'
      and watch."AIDexterWatch_IsArmed"
      and (watch."AIDexterWatch_TargetID" is null or watch."AIDexterWatch_TargetID" = v_source);
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."_multideck_crm_customer_watch_signal"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_crm_deal_conversion_state"("p_deal_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select jsonb_build_object(
    'isWon', opportunity."CRMOppty_WonAt" is not null,
    'wonAt', opportunity."CRMOppty_WonAt",
    'customerOrgId', case when customer_type."Org_ID" is not null then opportunity."CRMOppty_OrgID" else null end,
    'isCustomer', customer_type."Org_ID" is not null
  )
  from public."CRM_Opportunities" opportunity
  left join lateral (
    select link."Org_ID" from public."Org_Master_Type" link join public."Org_Types" type on type."OrgType_ID" = link."OrgType_ID"
    where link."Org_ID" = opportunity."CRMOppty_OrgID" and lower(type."OrgType_Name") = 'customer' limit 1
  ) customer_type on true
  where opportunity."CRMOppty_ID" = p_deal_id;
$$;


ALTER FUNCTION "public"."_multideck_crm_deal_conversion_state"("p_deal_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_crm_deal_is_fixture"("p_deal_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select exists (
    select 1
    from public."CRM_Opportunities" deal
    left join public."CRM_Leads" source_lead
      on source_lead."CRMLead_ID" = deal."CRMOppty_SourceLeadID"
    where deal."CRMOppty_ID" = p_deal_id
      and (
        lower(coalesce(deal."CRMOppty_MetadataJSON" ->> 'developmentFixture', 'false')) = 'true'
        or lower(coalesce(deal."CRMOppty_MetadataJSON" ->> 'isDemo', 'false')) = 'true'
        or deal."CRMOppty_MetadataJSON" ->> 'seed' = 'multideck-development-crm-deals-v1'
        or lower(coalesce(source_lead."CRMLead_MetadataJSON" ->> 'isDemo', 'false')) = 'true'
        or exists (
          select 1
          from public."CRM_AccountProfiles" fixture
          where not fixture."CRMAccount_IsDeleted"
            and lower(coalesce(fixture."CRMAccount_MetadataJSON" ->> 'developmentFixture', 'false')) = 'true'
            and (
              fixture."CRMAccount_ID" = deal."CRMOppty_AccountID"
              or fixture."CRMAccount_OrgID" = deal."CRMOppty_OrgID"
            )
        )
      )
  )
$$;


ALTER FUNCTION "public"."_multideck_crm_deal_is_fixture"("p_deal_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_crm_deal_is_operator_visible"("p_deal_id" "uuid", "p_company_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select exists (
    select 1
    from public."CRM_Opportunities" deal
    join public."CRM_Pipelines" pipeline
      on pipeline."CRMPipeline_ID" = deal."CRMOppty_PipelineID"
     and pipeline."Company_ID" = p_company_id
     and not pipeline."Is_Deleted"
    join public."CRM_PipelineStages" stage
      on stage."CRMPipelineStage_ID" = deal."CRMOppty_PipelineStageID"
     and stage."CRMPipeline_ID" = pipeline."CRMPipeline_ID"
     and not stage."Is_Deleted"
    where deal."CRMOppty_ID" = p_deal_id
      and not deal."CRMOppty_IsDeleted"
      and not public._multideck_crm_deal_is_fixture(deal."CRMOppty_ID")
  )
$$;


ALTER FUNCTION "public"."_multideck_crm_deal_is_operator_visible"("p_deal_id" "uuid", "p_company_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_crm_deal_json"("p_deal_id" "uuid", "p_company_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select case
    when public._multideck_crm_deal_is_operator_visible(p_deal_id, p_company_id)
      then public._multideck_crm_deal_json_unfiltered_20260818(p_deal_id, p_company_id)
    else null
  end
$$;


ALTER FUNCTION "public"."_multideck_crm_deal_json"("p_deal_id" "uuid", "p_company_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_crm_deal_json_unfiltered_20260818"("p_deal_id" "uuid", "p_company_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select jsonb_build_object(
    'id', deal."CRMOppty_ID",
    'organisationId', deal."CRMOppty_OrgID",
    'companyName', coalesce(
      nullif(btrim(source_lead."CRMLead_CompanyName"), ''),
      nullif(btrim(organisation."Org_Name"), ''),
      'Organisation'
    ),
    'sourceLeadId', coalesce(deal."CRMOppty_SourceLeadID", '00000000-0000-0000-0000-000000000000'::uuid),
    'name', deal."CRMOppty_Name",
    'pipelineId', deal."CRMOppty_PipelineID",
    'pipelineName', pipeline."CRMPipeline_Name",
    'pipelineStageId', deal."CRMOppty_PipelineStageID",
    'pipelineStageName', pipeline_stage."CRMPipelineStage_Name",
    'opportunityTypeCode', deal."CRMOppty_TypeCode",
    'opportunityTypeName', opportunity_type."CRMOpptyType_Name",
    'stageCode', deal."CRMOppty_StageCode",
    'stageName', opportunity_stage."CRMStage_Name",
    'statusCode', deal."CRMOppty_StatusCode",
    'statusName', opportunity_status."CRMOpptyStatus_Name",
    'primaryContactId', deal."CRMOppty_PrimaryContactID",
    'primaryContactName', nullif(btrim(concat_ws(' ', contact."OrgContact_FirstName", contact."OrgContact_LastName")), ''),
    'ownerId', deal."CRMOppty_OwnerUserID",
    'ownerName', coalesce(
      nullif(btrim(concat_ws(' ', owner."User_Firstname", owner."User_Lastname")), ''),
      nullif(btrim(owner."User_Email"), '')
    ),
    'expectedCloseDate', deal."CRMOppty_ExpectedCloseDate",
    'expectedValueAmount', deal."CRMOppty_ExpectedValueAmount",
    'expectedMarginAmount', deal."CRMOppty_ExpectedMarginAmount",
    'currencyCode', nullif(btrim(deal."CRMOppty_CurrencyCode"), ''),
    'probabilityPct', deal."CRMOppty_ProbabilityPct",
    'modeCode', nullif(btrim(deal."CRMOppty_ModeCode"), ''),
    'directionCode', nullif(btrim(deal."CRMOppty_DirectionCode"), ''),
    'originName', nullif(btrim(deal."CRMOppty_OriginNameSnapshot"), ''),
    'destinationName', nullif(btrim(deal."CRMOppty_DestinationNameSnapshot"), ''),
    'tradeLane', nullif(btrim(deal."CRMOppty_TradeLane"), ''),
    'serviceInterest', nullif(btrim(deal."CRMOppty_ServiceInterest"), ''),
    'customerNeed', nullif(btrim(deal."CRMOppty_CustomerNeed"), ''),
    'valueProposition', nullif(btrim(deal."CRMOppty_ValueProposition"), ''),
    'nextActionDueAt', deal."CRMOppty_NextActionDueAt",
    'createdAt', deal."CRMOppty_CreatedAt",
    'wasAlreadyConverted', false
  )
  from public."CRM_Opportunities" deal
  join public."CRM_Pipelines" pipeline
    on pipeline."CRMPipeline_ID" = deal."CRMOppty_PipelineID"
    and pipeline."Company_ID" = p_company_id
    and not pipeline."Is_Deleted"
  join public."CRM_PipelineStages" pipeline_stage
    on pipeline_stage."CRMPipelineStage_ID" = deal."CRMOppty_PipelineStageID"
    and pipeline_stage."CRMPipeline_ID" = pipeline."CRMPipeline_ID"
    and not pipeline_stage."Is_Deleted"
  join public."sys_CRMOpportunityTypes" opportunity_type
    on opportunity_type."CRMOpptyType_Code" = deal."CRMOppty_TypeCode"
  join public."sys_CRMOpportunityStages" opportunity_stage
    on opportunity_stage."CRMStage_Code" = deal."CRMOppty_StageCode"
  join public."sys_CRMOpportunityStatuses" opportunity_status
    on opportunity_status."CRMOpptyStatus_Code" = deal."CRMOppty_StatusCode"
  left join public."CRM_Leads" source_lead
    on source_lead."CRMLead_ID" = deal."CRMOppty_SourceLeadID"
  left join public."Org_Master" organisation
    on organisation."Org_id" = deal."CRMOppty_OrgID"
  left join public."Org_Contacts" contact
    on contact."OrgContact_ID" = deal."CRMOppty_PrimaryContactID"
  left join public."cmp_Users" owner
    on owner."User_ID" = deal."CRMOppty_OwnerUserID"
  where deal."CRMOppty_ID" = p_deal_id
    and not deal."CRMOppty_IsDeleted";
$$;


ALTER FUNCTION "public"."_multideck_crm_deal_json_unfiltered_20260818"("p_deal_id" "uuid", "p_company_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_crm_get_dashboard_unfiltered_deals_20260818"("p_inactivity_days" integer DEFAULT 90, "p_area" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_context record;
  v_area text := nullif(lower(btrim(coalesce(p_area, ''))), '');
  v_result jsonb;
begin
  select * into v_context from public._multideck_crm_context();
  if p_inactivity_days not in (30, 90, 180) then
    raise exception 'Choose an inactivity threshold of 30, 90 or 180 days.' using errcode = '22023';
  end if;

  with owned_leads as (
    select
      lead.*,
      status."CRMLeadStatus_Name" as status_name,
      status."CRMLeadStatus_IsOpen" as is_open,
      coalesce(nullif(btrim(lead."CRMLead_CompanyName"), ''), organisation."Org_Name", nullif(btrim(lead."CRMLead_PersonName"), ''), 'Unnamed lead') as company_name,
      coalesce(nullif(btrim(lead."CRMLead_PersonName"), ''), nullif(btrim(concat_ws(' ', contact."OrgContact_FirstName", contact."OrgContact_LastName")), '')) as contact_name,
      coalesce(nullif(btrim(lead."CRMLead_Email"), ''), contact_email.email, organisation_address."OrgAdd_MainEmail") as email,
      greatest(lead."CRMLead_LastInteractionAt", activity.last_activity_at) as last_contact_at,
      activity.last_subject,
      coalesce(
        nullif(concat_ws(' · ', nullif(btrim(lead."CRMLead_TownCity"), ''), nullif(btrim(lead."CRMLead_CountyState"), ''),
          nullif(split_part(btrim(lead."CRMLead_PostZipCode"), ' ', 1), ''), nullif(upper(btrim(lead."CRMLead_CountryCode")), '')), ''),
        organisation_address.area_label
      ) as area_label,
      coalesce(
        lower(nullif(concat_ws('|', nullif(btrim(lead."CRMLead_TownCity"), ''), nullif(btrim(lead."CRMLead_CountyState"), ''),
          nullif(split_part(btrim(lead."CRMLead_PostZipCode"), ' ', 1), ''), nullif(upper(btrim(lead."CRMLead_CountryCode")), '')), '')),
        organisation_address.area_key
      ) as area_key,
      coalesce(lead."CRMLead_EstimatedValueCurrencyCode", 'GBP') as currency_code
    from public."CRM_Leads" lead
    join public."sys_CRMLeadStatuses" status on status."CRMLeadStatus_Code" = lead."CRMLead_StatusCode"
    left join public."Org_Master" organisation on organisation."Org_id" = lead."CRMLead_OrgID"
    left join public."Org_Contacts" contact on contact."OrgContact_ID" = lead."CRMLead_PrimaryContactID"
    left join lateral (
      select nullif(btrim(email_row."OrgContactEmail_Email"), '') as email
      from public."OrgContact_Emails" email_row
      where email_row."OrgContact_ID" = contact."OrgContact_ID"
      order by email_row."OrgContactEmail_Type", email_row."OrgContactEmail_ID"
      limit 1
    ) contact_email on true
    left join lateral (
      select
        nullif(concat_ws(' · ', nullif(btrim(a."OrgAdd_TownCity"), ''), nullif(btrim(a."OrgAdd_CountyState"), ''),
          nullif(split_part(btrim(a."OrgAdd_PostZipCode"), ' ', 1), ''), nullif(upper(btrim(a."OrgAdd_Country")), '')), '') as area_label,
        lower(nullif(concat_ws('|', nullif(btrim(a."OrgAdd_TownCity"), ''), nullif(btrim(a."OrgAdd_CountyState"), ''),
          nullif(split_part(btrim(a."OrgAdd_PostZipCode"), ' ', 1), ''), nullif(upper(btrim(a."OrgAdd_Country")), '')), '')) as area_key,
        a."OrgAdd_MainEmail"
      from public."Org_Addresses" a
      where a."Org_ID" = lead."CRMLead_OrgID"
      order by a."OrgAdd_ID"
      limit 1
    ) organisation_address on true
    left join lateral (
      select max(a."CRMActivity_ActivityAt") as last_activity_at,
             (array_agg(a."CRMActivity_Subject" order by a."CRMActivity_ActivityAt" desc))[1] as last_subject
      from public."CRM_Activities" a
      where a."CRMActivity_LeadID" = lead."CRMLead_ID" and not a."CRMActivity_IsDeleted"
    ) activity on true
    where lead."CRMLead_OwnerUserID" = v_context.user_id
      and not lead."CRMLead_IsDeleted"
      and lower(coalesce(lead."CRMLead_MetadataJSON" ->> 'isDemo', 'false')) <> 'true'
  ), filtered_leads as (
    select * from owned_leads where v_area is null or area_key = v_area
  ), company_deals as (
    select opportunity.*,
           stage."CRMPipelineStage_Name" as pipeline_stage_name,
           pipeline."CRMPipeline_Name" as pipeline_name
    from public."CRM_Opportunities" opportunity
    join public."CRM_Pipelines" pipeline on pipeline."CRMPipeline_ID" = opportunity."CRMOppty_PipelineID"
      and pipeline."Company_ID" = v_context.company_id and not pipeline."Is_Deleted"
    join public."CRM_PipelineStages" stage on stage."CRMPipelineStage_ID" = opportunity."CRMOppty_PipelineStageID"
      and stage."CRMPipeline_ID" = pipeline."CRMPipeline_ID" and not stage."Is_Deleted"
    where not opportunity."CRMOppty_IsDeleted"
  )
  select jsonb_build_object(
    'summary', jsonb_build_object(
      'openLeads', (select count(*) from filtered_leads where is_open),
      'staleLeads', (select count(*) from filtered_leads where is_open and (last_contact_at is null or last_contact_at < now() - make_interval(days => p_inactivity_days))),
      'openDeals', (select count(*) from company_deals where "CRMOppty_WonAt" is null and "CRMOppty_LostAt" is null),
      'pipelineValue', coalesce((select sum("CRMOppty_ExpectedValueAmount") from company_deals where "CRMOppty_WonAt" is null and "CRMOppty_LostAt" is null), 0),
      'currencyCode', coalesce((select nullif(btrim("CRMOppty_CurrencyCode"), '') from company_deals where "CRMOppty_ExpectedValueAmount" is not null order by "CRMOppty_CreatedAt" desc limit 1), 'GBP'),
      'dueFollowUps', (select count(*) from filtered_leads where is_open and "CRMLead_NextActionDueAt" <= now())
    ),
    'areas', coalesce((select jsonb_agg(jsonb_build_object('key', area_key, 'label', area_label, 'count', lead_count) order by area_label)
      from (select area_key, area_label, count(*) lead_count from owned_leads where area_key is not null group by area_key, area_label) areas), '[]'::jsonb),
    'followUps', coalesce((select jsonb_agg(jsonb_build_object(
      'id', "CRMLead_ID", 'companyName', company_name, 'decisionMaker', contact_name, 'email', email,
      'location', area_label, 'lastContactAt', last_contact_at, 'previousConversation', last_subject,
      'laneContext', coalesce(nullif(btrim("CRMLead_TradeLane"), ''), nullif(btrim("CRMLead_ServiceInterest"), '')),
      'nextActionAt', "CRMLead_NextActionDueAt", 'stage', status_name,
      'opportunityValue', "CRMLead_EstimatedValueAmount", 'currencyCode', currency_code,
      'contactAgeDays', case when last_contact_at is null then null else floor(extract(epoch from (now() - last_contact_at)) / 86400)::integer end,
      'neverContacted', last_contact_at is null
    ) order by (last_contact_at is not null), last_contact_at asc, "CRMLead_CreatedAt" asc)
    from filtered_leads where is_open and (last_contact_at is null or last_contact_at < now() - make_interval(days => p_inactivity_days))), '[]'::jsonb),
    'pipeline', coalesce((select jsonb_agg(jsonb_build_object(
      'stageId', "CRMOppty_PipelineStageID", 'stage', pipeline_stage_name, 'pipeline', pipeline_name,
      'count', deal_count, 'value', deal_value, 'currencyCode', currency_code
    ) order by stage_order)
    from (select "CRMOppty_PipelineStageID", pipeline_stage_name, pipeline_name, min("CRMOppty_CurrencyCode") currency_code,
      count(*) deal_count, coalesce(sum("CRMOppty_ExpectedValueAmount"), 0) deal_value,
      min((select s."CRMPipelineStage_SortOrder" from public."CRM_PipelineStages" s where s."CRMPipelineStage_ID" = company_deals."CRMOppty_PipelineStageID")) stage_order
      from company_deals where "CRMOppty_WonAt" is null and "CRMOppty_LostAt" is null
      group by "CRMOppty_PipelineStageID", pipeline_stage_name, pipeline_name) pipeline_groups), '[]'::jsonb),
    'activity', coalesce((select jsonb_agg(jsonb_build_object(
      'id', activity."CRMActivity_ID", 'leadId', activity."CRMActivity_LeadID", 'dealId', activity."CRMActivity_OpportunityID",
      'subject', activity."CRMActivity_Subject", 'summary', activity."CRMActivity_Summary", 'at', activity."CRMActivity_ActivityAt"
    ) order by activity."CRMActivity_ActivityAt" desc)
    from (select activity.* from public."CRM_Activities" activity
      where not activity."CRMActivity_IsDeleted" and activity."CRMActivity_OwnerUserID" = v_context.user_id
      order by activity."CRMActivity_ActivityAt" desc limit 12) activity), '[]'::jsonb)
  ) into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."_multideck_crm_get_dashboard_unfiltered_deals_20260818"("p_inactivity_days" integer, "p_area" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_crm_get_lead_essential_unversioned_20260818"("p_lead_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_context record;
  v_result jsonb;
  v_contacts jsonb;
  v_native_address jsonb;
  v_native_address_label text;
begin
  select * into v_context from public._multideck_crm_context();

  if not public._multideck_crm_has_permission(v_context.user_id, 'CRM.Read') then
    raise exception 'You do not have permission to view CRM.' using errcode = '42501';
  end if;

  if not public._multideck_crm_lead_is_reachable(p_lead_id, v_context.company_id) then
    raise exception 'Lead not found.' using errcode = 'P0002';
  end if;

  v_result := public.multideck_crm_get_lead(p_lead_id)
    || public._multideck_crm_lead_transfer_state(p_lead_id);
  v_native_address := public._multideck_crm_lead_native_address(p_lead_id);

  if v_native_address is not null then
    v_native_address_label := nullif(concat_ws(', ',
      v_native_address ->> 'line1',
      v_native_address ->> 'line2',
      v_native_address ->> 'townCity',
      v_native_address ->> 'countyState',
      v_native_address ->> 'postZipCode',
      v_native_address ->> 'countryCode'
    ), '');
    v_result := jsonb_set(
      v_result,
      '{company,address}',
      to_jsonb(v_native_address_label),
      true
    ) || jsonb_build_object('address', v_native_address);
  end if;

  select coalesce(jsonb_agg(
    item || jsonb_build_object(
      'marketingOptIn', coalesce(contact."OrgContact_MarketingOptIn", false),
      'marketingConsentSource', contact."OrgContact_MarketingConsentSource",
      'marketingConsentUpdatedAt', contact."OrgContact_MarketingConsentUpdatedAt"
    ) order by item_index
  ), '[]'::jsonb)
  into v_contacts
  from jsonb_array_elements(coalesce(v_result -> 'contacts', '[]'::jsonb))
    with ordinality as rows(item, item_index)
  left join public."Org_Contacts" contact
    on contact."OrgContact_ID" = (item ->> 'id')::uuid;

  return v_result || coalesce((
    select jsonb_build_object(
      'marketingOptIn', lead."CRMLead_MarketingOptIn",
      'marketingConsentSource', lead."CRMLead_MarketingConsentSource",
      'marketingConsentUpdatedAt', lead."CRMLead_MarketingConsentUpdatedAt",
      'contacts', v_contacts
    )
    from public."CRM_Leads" lead
    where lead."CRMLead_ID" = p_lead_id
      and not lead."CRMLead_IsDeleted"
  ), '{}'::jsonb);
end;
$$;


ALTER FUNCTION "public"."_multideck_crm_get_lead_essential_unversioned_20260818"("p_lead_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_crm_guard_pipeline_retirement"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if not old."Is_Deleted" and new."Is_Deleted" then
    perform public._multideck_crm_lock_pipeline_stage(new."CRMPipeline_ID", null);
    if exists (
      select 1
      from public."CRM_Opportunities" deal
      where deal."CRMOppty_PipelineID" = new."CRMPipeline_ID"
        and not deal."CRMOppty_IsDeleted"
        and public._multideck_crm_deal_is_operator_visible(
          deal."CRMOppty_ID",
          new."Company_ID"
        )
    ) then
      raise exception 'Deals in this pipeline must be moved before removal.' using errcode = '22023';
    end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."_multideck_crm_guard_pipeline_retirement"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_crm_guard_stage_retirement"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if not old."Is_Deleted" and new."Is_Deleted" then
    perform public._multideck_crm_lock_pipeline_stage(null, new."CRMPipelineStage_ID");
    if exists (
      select 1
      from public."CRM_Opportunities" deal
      where deal."CRMOppty_PipelineStageID" = new."CRMPipelineStage_ID"
        and not deal."CRMOppty_IsDeleted"
        and public._multideck_crm_deal_is_operator_visible(
          deal."CRMOppty_ID",
          new."Company_ID"
        )
    ) then
      raise exception 'Deals in this stage must be moved before removal.' using errcode = '22023';
    end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."_multideck_crm_guard_stage_retirement"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_crm_has_permission"("p_user_id" "uuid", "p_permission" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select exists (
    select 1
    from public."cmp_Users_Roles" user_role
    join public."sys_UserRole_Permissions" role_permission
      on role_permission."sys_UserRole_ID" = user_role."sys_UserRole_ID"
    join public."sys_Permissions" permission
      on permission."sys_Permission_ID" = role_permission."sys_Permission_ID"
    where user_role."User_ID" = p_user_id
      and permission."sys_Permission_Value" = p_permission
  );
$$;


