CREATE OR REPLACE FUNCTION "public"."_multideck_crm_initials"("p_value" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
  select upper(
    coalesce(left((regexp_split_to_array(btrim(coalesce(p_value, '')), '\s+'))[1], 1), '') ||
    coalesce(left((regexp_split_to_array(btrim(coalesce(p_value, '')), '\s+'))[2], 1), '')
  );
$$;


ALTER FUNCTION "public"."_multideck_crm_initials"("p_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_crm_json_bool"("p_input" "jsonb", "p_key" "text", "p_fallback" boolean) RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
  select case lower(coalesce(p_input ->> p_key, ''))
    when 'true' then true
    when 'false' then false
    else p_fallback
  end;
$$;


ALTER FUNCTION "public"."_multideck_crm_json_bool"("p_input" "jsonb", "p_key" "text", "p_fallback" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_crm_json_number"("p_input" "jsonb", "p_key" "text", "p_fallback" numeric) RETURNS numeric
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $_$
  select case
    when coalesce(p_input ->> p_key, '') ~ '^[+-]?[0-9]+([.][0-9]+)?$'
      then (p_input ->> p_key)::numeric
    when p_input ? p_key then null
    else p_fallback
  end;
$_$;


ALTER FUNCTION "public"."_multideck_crm_json_number"("p_input" "jsonb", "p_key" "text", "p_fallback" numeric) OWNER TO "postgres";


