CREATE OR REPLACE FUNCTION "public"."_multideck_crm_move_deal_stage_unfiltered_20260818"("p_deal_id" "uuid", "p_pipeline_id" "uuid", "p_pipeline_stage_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_context record;
  v_stage record;
  v_deal record;
begin
  select * into v_context from public._multideck_crm_context();

  select stage.* into v_stage
  from public."CRM_PipelineStages" stage
  join public."CRM_Pipelines" pipeline
    on pipeline."CRMPipeline_ID" = stage."CRMPipeline_ID"
  where stage."CRMPipelineStage_ID" = p_pipeline_stage_id
    and stage."CRMPipeline_ID" = p_pipeline_id
    and stage."Company_ID" = v_context.company_id
    and pipeline."Company_ID" = v_context.company_id
    and not stage."Is_Deleted"
    and not pipeline."Is_Deleted";

  if not found then
    raise exception 'Choose a stage from an active pipeline in this workspace.' using errcode = '22023';
  end if;

  select deal.* into v_deal
  from public."CRM_Opportunities" deal
  join public."CRM_Pipelines" pipeline
    on pipeline."CRMPipeline_ID" = deal."CRMOppty_PipelineID"
  where deal."CRMOppty_ID" = p_deal_id
    and not deal."CRMOppty_IsDeleted"
    and pipeline."Company_ID" = v_context.company_id
    and not pipeline."Is_Deleted"
  for update of deal;

  if not found then
    raise exception 'Deal not found.' using errcode = 'P0002';
  end if;

  update public."CRM_Opportunities"
  set
    "CRMOppty_PipelineID" = p_pipeline_id,
    "CRMOppty_PipelineStageID" = p_pipeline_stage_id,
    "CRMOppty_ProbabilityPct" = v_stage."CRMPipelineStage_ProbabilityPct",
    "CRMOppty_WeightedValueAmount" =
      case
        when v_deal."CRMOppty_ExpectedValueAmount" is null then null
        else round(
          v_deal."CRMOppty_ExpectedValueAmount" * v_stage."CRMPipelineStage_ProbabilityPct" / 100,
          4
        )
      end,
    "CRMOppty_UpdatedAt" = now(),
    "CRMOppty_UpdatedBy" = v_context.user_id
  where "CRMOppty_ID" = p_deal_id;

  insert into public."CRM_OpportunityStageHistory" (
    "CRMOpptyStage_ID",
    "CRMOpptyStage_OpportunityID",
    "CRMOpptyStage_FromStageCode",
    "CRMOpptyStage_ToStageCode",
    "CRMOpptyStage_ProbabilityPct",
    "CRMOpptyStage_Reason",
    "CRMOpptyStage_ChangedAt",
    "CRMOpptyStage_ChangedBy"
  )
  values (
    gen_random_uuid(),
    p_deal_id,
    v_deal."CRMOppty_StageCode",
    v_deal."CRMOppty_StageCode",
    v_stage."CRMPipelineStage_ProbabilityPct",
    'Moved to ' || v_stage."CRMPipelineStage_Name",
    now(),
    v_context.user_id
  );

  return public._multideck_crm_deal_json(p_deal_id, v_context.company_id);
end;
$$;


ALTER FUNCTION "public"."_multideck_crm_move_deal_stage_unfiltered_20260818"("p_deal_id" "uuid", "p_pipeline_id" "uuid", "p_pipeline_stage_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_crm_organisation_foundation_watch_signal"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_row jsonb := case when tg_op = 'DELETE' then to_jsonb(old) else to_jsonb(new) end;
  v_old jsonb := case when tg_op = 'INSERT' then '{}'::jsonb else to_jsonb(old) end;
  v_new jsonb := case when tg_op = 'DELETE' then '{}'::jsonb else to_jsonb(new) end;
  v_company_id uuid;
  v_source_id uuid;
  v_account_profile_id uuid;
  v_address_id uuid;
  v_contact_id uuid;
begin
  if tg_table_name = 'CRM_AccountOfficeAssignments' then
    v_company_id := (v_row ->> 'CRMAccountOffice_CompanyID')::uuid;
    v_account_profile_id := (v_row ->> 'CRMAccountOffice_AccountID')::uuid;
    select "CRMAccount_OrgID" into v_source_id from public."CRM_AccountProfiles" where "CRMAccount_ID" = v_account_profile_id;
  elsif tg_table_name = 'CRM_ContactOrganisationAssignments' then
    v_company_id := (v_row ->> 'CRMContactOrg_CompanyID')::uuid;
    v_source_id := (v_row ->> 'CRMContactOrg_ContactID')::uuid;
  elsif tg_table_name = 'OrgContact_Emails' then
    v_contact_id := (v_row ->> 'OrgContact_ID')::uuid; v_source_id := v_contact_id;
    select profile."CRMAccount_CompanyID" into v_company_id
    from public."Org_Contacts" contact
    join public."CRM_AccountProfiles" profile on profile."CRMAccount_OrgID" = contact."Org_ID" and not profile."CRMAccount_IsDeleted"
    where contact."OrgContact_ID" = v_contact_id limit 1;
    v_old := v_old - 'OrgContactEmail_Email'; v_new := v_new - 'OrgContactEmail_Email';
  elsif tg_table_name = 'Org_RelatedPartyDefaults' then
    v_company_id := (v_row ->> 'OrgRelatedDefault_CompanyID')::uuid;
    v_source_id := (v_row ->> 'OrgRelatedDefault_SourceOrgID')::uuid;
  else
    if tg_table_name = 'Org_Addresses' then v_address_id := (v_row ->> 'OrgAdd_ID')::uuid;
    elsif tg_table_name = 'Org_AddressTypes' then v_address_id := (v_row ->> 'OrgAdd_ID')::uuid;
    elsif tg_table_name = 'Org_AddressOpeningHours' then v_address_id := (v_row ->> 'OrgAddHours_OrgAddID')::uuid;
    elsif tg_table_name = 'Org_AddressOpeningOverrides' then v_address_id := (v_row ->> 'OrgAddOverride_OrgAddID')::uuid;
    end if;
    select address."Org_ID", profile."CRMAccount_CompanyID" into v_source_id, v_company_id
    from public."Org_Addresses" address
    join public."CRM_AccountProfiles" profile on profile."CRMAccount_OrgID" = address."Org_ID" and not profile."CRMAccount_IsDeleted"
    where address."OrgAdd_ID" = v_address_id limit 1;
    v_old := v_old - 'OrgAdd_MainEmail' - 'OrgAdd_MainPhone';
    v_new := v_new - 'OrgAdd_MainEmail' - 'OrgAdd_MainPhone';
  end if;
  if v_company_id is not null and v_source_id is not null and v_old is distinct from v_new and exists (
    select 1 from public."AI_DexterWatches" watch
    where watch."AIDexterWatch_CompanyID" = v_company_id
      and watch."AIDexterWatch_CapabilityCode" = 'customers'
      and watch."AIDexterWatch_StatusCode" = 'active'
      and (watch."AIDexterWatch_TargetID" is null or watch."AIDexterWatch_TargetID" = v_source_id)
  ) then
    insert into public."AI_DexterWatchSignals"(
      "AIDexterWatchSignal_CompanyID", "AIDexterWatchSignal_CapabilityCode", "AIDexterWatchSignal_SourceTable",
      "AIDexterWatchSignal_SourceID", "AIDexterWatchSignal_OldJSON", "AIDexterWatchSignal_NewJSON"
    ) values (v_company_id, 'customers', tg_table_name, v_source_id, v_old, v_new);
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."_multideck_crm_organisation_foundation_watch_signal"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_crm_pipeline_json"("p_pipeline_id" "uuid", "p_company_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select jsonb_build_object(
    'id', pipeline."CRMPipeline_ID",
    'name', pipeline."CRMPipeline_Name",
    'owner', coalesce(pipeline."CRMPipeline_Owner", ''),
    'automation', coalesce(pipeline."CRMPipeline_Automation", ''),
    'sortOrder', pipeline."CRMPipeline_SortOrder",
    'defaultStage', coalesce(
      (
        select stage."CRMPipelineStage_Name"
        from public."CRM_PipelineStages" stage
        where stage."CRMPipeline_ID" = pipeline."CRMPipeline_ID"
          and not stage."Is_Deleted"
        order by stage."CRMPipelineStage_IsDefaultEntry" desc, stage."CRMPipelineStage_SortOrder"
        limit 1
      ),
      ''
    ),
    'conversionStage', coalesce(
      (
        select stage."CRMPipelineStage_Name"
        from public."CRM_PipelineStages" stage
        where stage."CRMPipeline_ID" = pipeline."CRMPipeline_ID"
          and not stage."Is_Deleted"
        order by stage."CRMPipelineStage_IsConversion" desc, stage."CRMPipelineStage_SortOrder" desc
        limit 1
      ),
      ''
    ),
    'stages', coalesce(
      (
        select jsonb_agg(
          jsonb_build_object(
            'id', stage."CRMPipelineStage_ID",
            'name', stage."CRMPipelineStage_Name",
            'tone', stage."CRMPipelineStage_Tone",
            'rule', coalesce(stage."CRMPipelineStage_EntryRule", ''),
            'probability', stage."CRMPipelineStage_ProbabilityPct",
            'sortOrder', stage."CRMPipelineStage_SortOrder",
            'isDefaultEntry', stage."CRMPipelineStage_IsDefaultEntry",
            'isConversion', stage."CRMPipelineStage_IsConversion"
          )
          order by stage."CRMPipelineStage_SortOrder"
        )
        from public."CRM_PipelineStages" stage
        where stage."CRMPipeline_ID" = pipeline."CRMPipeline_ID"
          and not stage."Is_Deleted"
      ),
      '[]'::jsonb
    )
  )
  from public."CRM_Pipelines" pipeline
  where pipeline."CRMPipeline_ID" = p_pipeline_id
    and pipeline."Company_ID" = p_company_id
    and not pipeline."Is_Deleted";
$$;


