CREATE OR REPLACE FUNCTION "public"."_multideck_crm_update_account_unscoped_20260818"("p_actor_user_id" "uuid", "p_account_id" "uuid", "p_expected_version" bigint, "p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  v_org public."Org_Master"%rowtype;
  v_profile public."CRM_AccountProfiles"%rowtype;
  v_address public."Org_Addresses"%rowtype;
  v_engagement public."CRM_CustomerEngagementPreferences"%rowtype;
  v_address_input jsonb := case when jsonb_typeof(p_input -> 'address') = 'object' then p_input -> 'address' else '{}'::jsonb end;
  v_engagement_input jsonb := case when jsonb_typeof(p_input -> 'engagement') = 'object' then p_input -> 'engagement' else '{}'::jsonb end;
  v_name text := nullif(btrim(p_input ->> 'name'), '');
  v_country text := upper(nullif(btrim(v_address_input ->> 'countryCode'), ''));
  v_now timestamptz := now();
  v_marketing boolean;
  v_reason text;
  v_next_version bigint;
  v_profile_id uuid;
  v_engagement_id uuid;
  v_activity_type text;
begin
  perform public._multideck_crm_write_actor(p_actor_user_id);
  if v_name is null then
    raise exception 'Enter an account name.' using errcode = '22023';
  end if;
  if v_country is not null and v_country !~ '^[A-Z]{2}$' then
    raise exception 'Enter a two-letter ISO country code, such as GB.' using errcode = '22023';
  end if;

  -- Serialise the name check so two simultaneous creates/renames cannot pass
  -- the same case-insensitive duplicate check.
  perform pg_advisory_xact_lock(hashtextextended(lower(v_name), 0));
  if exists (
    select 1 from public."Org_Master"
    where lower(btrim("Org_Name")) = lower(v_name)
      and "Org_id" <> p_account_id
  ) then
    raise exception 'An account named ''%'' already exists.', v_name using errcode = '23505';
  end if;

  select * into v_org
  from public."Org_Master"
  where "Org_id" = p_account_id
  for update;
  if not found then
    raise exception 'Account not found.' using errcode = 'P0002';
  end if;

  select * into v_profile
  from public."CRM_AccountProfiles"
  where "CRMAccount_OrgID" = p_account_id
    and not "CRMAccount_IsDeleted"
  order by "CRMAccount_ID"
  limit 1
  for update;

  if not found then
    if p_expected_version is not null and p_expected_version <> 1 then
      raise exception 'CRM_CONFLICT:This account changed since it was loaded.' using errcode = 'P0001';
    end if;
    v_profile_id := gen_random_uuid();
    insert into public."CRM_AccountProfiles"(
      "CRMAccount_ID", "CRMAccount_OrgID", "CRMAccount_RelationshipStatusCode",
      "CRMAccount_CreatedBy", "CRMAccount_UpdatedBy", "CRMAccount_EditVersion"
    ) values (
      v_profile_id, p_account_id, coalesce(nullif(btrim(p_input ->> 'relationshipStatus'), ''), 'active_customer'),
      p_actor_user_id, p_actor_user_id, 1
    );
    select * into v_profile from public."CRM_AccountProfiles" where "CRMAccount_ID" = v_profile_id for update;
  elsif p_expected_version is not null and v_profile."CRMAccount_EditVersion" <> p_expected_version then
    raise exception 'CRM_CONFLICT:This account changed since it was loaded.' using errcode = 'P0001';
  end if;

  v_next_version := coalesce(v_profile."CRMAccount_EditVersion", 1) + 1;
  v_marketing := case when p_input ? 'marketingOptIn' then public._multideck_crm_json_bool(p_input, 'marketingOptIn', v_org."Org_MarketingOptIn") else v_org."Org_MarketingOptIn" end;
  if v_marketing is distinct from v_org."Org_MarketingOptIn" then
    v_reason := nullif(btrim(p_input ->> 'marketingConsentReason'), '');
    if v_reason is null then
      raise exception 'Explain the source or evidence for this consent change.' using errcode = '22023';
    end if;
  end if;

  update public."Org_Master"
  set "Org_Name" = v_name,
      "Org_CRMRelationshipStatusCode" = coalesce(nullif(btrim(p_input ->> 'relationshipStatus'), ''), "Org_CRMRelationshipStatusCode"),
      "Org_CRMUpdatedAt" = v_now
  where "Org_id" = p_account_id;

  update public."CRM_AccountProfiles"
  set "CRMAccount_RelationshipStatusCode" = coalesce(nullif(btrim(p_input ->> 'relationshipStatus'), ''), "CRMAccount_RelationshipStatusCode"),
      "CRMAccount_Tier" = case when p_input ? 'tier' then nullif(btrim(p_input ->> 'tier'), '') else "CRMAccount_Tier" end,
      "CRMAccount_Segment" = case when p_input ? 'segment' then nullif(btrim(p_input ->> 'segment'), '') else "CRMAccount_Segment" end,
      "CRMAccount_Vertical" = case when p_input ? 'vertical' then nullif(btrim(p_input ->> 'vertical'), '') else "CRMAccount_Vertical" end,
      "CRMAccount_PrimaryModeCode" = case when p_input ? 'primaryMode' then nullif(btrim(p_input ->> 'primaryMode'), '') else "CRMAccount_PrimaryModeCode" end,
      "CRMAccount_PrimaryTradeLane" = case when p_input ? 'primaryTradeLane' then nullif(btrim(p_input ->> 'primaryTradeLane'), '') else "CRMAccount_PrimaryTradeLane" end,
      "CRMAccount_GrowthState" = case when p_input ? 'growthState' then nullif(btrim(p_input ->> 'growthState'), '') else "CRMAccount_GrowthState" end,
      "CRMAccount_HealthScore" = public._multideck_crm_json_number(p_input, 'healthScore', "CRMAccount_HealthScore"),
      "CRMAccount_ChurnRiskScore" = public._multideck_crm_json_number(p_input, 'churnRiskScore', "CRMAccount_ChurnRiskScore"),
      "CRMAccount_CustomerCentricSummary" = case when p_input ? 'summary' then nullif(btrim(p_input ->> 'summary'), '') else "CRMAccount_CustomerCentricSummary" end,
      "CRMAccount_IsStrategic" = case when p_input ? 'strategic' then public._multideck_crm_json_bool(p_input, 'strategic', "CRMAccount_IsStrategic") else "CRMAccount_IsStrategic" end,
      "CRMAccount_IsTrainingAllowed" = case when p_input ? 'trainingAllowed' then public._multideck_crm_json_bool(p_input, 'trainingAllowed', "CRMAccount_IsTrainingAllowed") else "CRMAccount_IsTrainingAllowed" end,
      "CRMAccount_MetadataJSON" = case when jsonb_typeof(p_input -> 'metadata') = 'object' then p_input -> 'metadata' else "CRMAccount_MetadataJSON" end,
      "CRMAccount_UpdatedAt" = v_now,
      "CRMAccount_UpdatedBy" = p_actor_user_id,
      "CRMAccount_EditVersion" = v_next_version
  where "CRMAccount_ID" = v_profile."CRMAccount_ID";

  select * into v_address from public."Org_Addresses" where "Org_ID" = p_account_id order by "OrgAdd_ID" limit 1 for update;
  if found then
    update public."Org_Addresses"
    set "OrgAdd_Line1" = case when v_address_input ? 'line1' then nullif(btrim(v_address_input ->> 'line1'), '') else "OrgAdd_Line1" end,
        "OrgAdd_Line2" = case when v_address_input ? 'line2' then nullif(btrim(v_address_input ->> 'line2'), '') else "OrgAdd_Line2" end,
        "OrgAdd_TownCity" = case when v_address_input ? 'townCity' then nullif(btrim(v_address_input ->> 'townCity'), '') else "OrgAdd_TownCity" end,
        "OrgAdd_CountyState" = case when v_address_input ? 'countyState' then nullif(btrim(v_address_input ->> 'countyState'), '') else "OrgAdd_CountyState" end,
        "OrgAdd_PostZipCode" = case when v_address_input ? 'postZipCode' then nullif(btrim(v_address_input ->> 'postZipCode'), '') else "OrgAdd_PostZipCode" end,
        "OrgAdd_Country" = case when v_address_input ? 'countryCode' then v_country else "OrgAdd_Country" end,
        "OrgAdd_MainEmail" = case when v_address_input ? 'mainEmail' then lower(nullif(btrim(v_address_input ->> 'mainEmail'), '')) else "OrgAdd_MainEmail" end,
        "OrgAdd_MainPhone" = case when v_address_input ? 'mainPhone' then nullif(btrim(v_address_input ->> 'mainPhone'), '') else "OrgAdd_MainPhone" end
    where "OrgAdd_ID" = v_address."OrgAdd_ID";
  elsif jsonb_typeof(p_input -> 'address') = 'object' then
    insert into public."Org_Addresses"(
      "OrgAdd_ID", "Org_ID", "OrgAdd_Line1", "OrgAdd_Line2", "OrgAdd_TownCity", "OrgAdd_CountyState",
      "OrgAdd_PostZipCode", "OrgAdd_Country", "OrgAdd_MainEmail", "OrgAdd_MainPhone"
    ) values (
      gen_random_uuid(), p_account_id, nullif(btrim(v_address_input ->> 'line1'), ''), nullif(btrim(v_address_input ->> 'line2'), ''),
      nullif(btrim(v_address_input ->> 'townCity'), ''), nullif(btrim(v_address_input ->> 'countyState'), ''),
      nullif(btrim(v_address_input ->> 'postZipCode'), ''), v_country,
      lower(nullif(btrim(v_address_input ->> 'mainEmail'), '')), nullif(btrim(v_address_input ->> 'mainPhone'), '')
    );
  end if;

  select * into v_engagement from public."CRM_CustomerEngagementPreferences"
  where "CRMCustEngPref_CustomerOrgID" = p_account_id
  order by "CRMCustEngPref_UpdatedAt" desc, "CRMCustEngPref_ID" desc
  limit 1 for update;
  if found then
    update public."CRM_CustomerEngagementPreferences"
    set "CRMCustEngPref_PreferredChannelCode" = case when v_engagement_input ? 'preferredChannel' then nullif(btrim(v_engagement_input ->> 'preferredChannel'), '') else "CRMCustEngPref_PreferredChannelCode" end,
        "CRMCustEngPref_AllowThankYouMessages" = case when v_engagement_input ? 'allowThankYouMessages' then public._multideck_crm_json_bool(v_engagement_input, 'allowThankYouMessages', "CRMCustEngPref_AllowThankYouMessages") else "CRMCustEngPref_AllowThankYouMessages" end,
        "CRMCustEngPref_AllowFollowupMessages" = case when v_engagement_input ? 'allowFollowupMessages' then public._multideck_crm_json_bool(v_engagement_input, 'allowFollowupMessages', "CRMCustEngPref_AllowFollowupMessages") else "CRMCustEngPref_AllowFollowupMessages" end,
        "CRMCustEngPref_AllowWhatsApp" = case when v_engagement_input ? 'allowWhatsApp' then public._multideck_crm_json_bool(v_engagement_input, 'allowWhatsApp', "CRMCustEngPref_AllowWhatsApp") else "CRMCustEngPref_AllowWhatsApp" end,
        "CRMCustEngPref_DoNotOverContact" = case when v_engagement_input ? 'doNotOverContact' then public._multideck_crm_json_bool(v_engagement_input, 'doNotOverContact', "CRMCustEngPref_DoNotOverContact") else "CRMCustEngPref_DoNotOverContact" end,
        "CRMCustEngPref_MinHoursBetweenNonUrgentMessages" = greatest(0, coalesce(public._multideck_crm_json_number(v_engagement_input, 'minHoursBetweenNonUrgentMessages', "CRMCustEngPref_MinHoursBetweenNonUrgentMessages"), 24))::integer,
        "CRMCustEngPref_Notes" = case when v_engagement_input ? 'notes' then nullif(btrim(v_engagement_input ->> 'notes'), '') else "CRMCustEngPref_Notes" end,
        "CRMCustEngPref_UpdatedAt" = v_now
    where "CRMCustEngPref_ID" = v_engagement."CRMCustEngPref_ID";
  elsif jsonb_typeof(p_input -> 'engagement') = 'object' then
    v_engagement_id := gen_random_uuid();
    insert into public."CRM_CustomerEngagementPreferences"(
      "CRMCustEngPref_ID", "CRMCustEngPref_CustomerOrgID", "CRMCustEngPref_PreferredChannelCode",
      "CRMCustEngPref_AllowThankYouMessages", "CRMCustEngPref_AllowFollowupMessages", "CRMCustEngPref_AllowWhatsApp",
      "CRMCustEngPref_DoNotOverContact", "CRMCustEngPref_MinHoursBetweenNonUrgentMessages", "CRMCustEngPref_Notes"
    ) values (
      v_engagement_id, p_account_id, nullif(btrim(v_engagement_input ->> 'preferredChannel'), ''),
      public._multideck_crm_json_bool(v_engagement_input, 'allowThankYouMessages', true),
      public._multideck_crm_json_bool(v_engagement_input, 'allowFollowupMessages', true),
      public._multideck_crm_json_bool(v_engagement_input, 'allowWhatsApp', false),
      public._multideck_crm_json_bool(v_engagement_input, 'doNotOverContact', false),
      greatest(0, coalesce(public._multideck_crm_json_number(v_engagement_input, 'minHoursBetweenNonUrgentMessages', 24), 24))::integer,
      nullif(btrim(v_engagement_input ->> 'notes'), '')
    );
  end if;

  if v_marketing is distinct from v_org."Org_MarketingOptIn" then
    perform public._multideck_set_marketing_consent(
      'customer', p_account_id, v_marketing, 'account_detail', v_reason, p_actor_user_id,
      jsonb_build_object('surface', 'crm_account_detail')
    );
  end if;

  select "CRMActType_Code" into v_activity_type
  from public."sys_CRMActivityTypes"
  where "CRMActType_IsActive"
  order by case when "CRMActType_Code" = 'review' then 0 else 1 end, "CRMActType_SortOrder", "CRMActType_Code"
  limit 1;
  if v_activity_type is null then
    raise exception 'No active CRM activity type is configured.' using errcode = '23503';
  end if;

  insert into public."CRM_Activities"(
    "CRMActivity_ID", "CRMActivity_ActivityTypeCode", "CRMActivity_AccountID", "CRMActivity_Subject",
    "CRMActivity_Summary", "CRMActivity_ActivityAt", "CRMActivity_OwnerUserID", "CRMActivity_CreatedBy", "CRMActivity_UpdatedBy"
  ) values (
    gen_random_uuid(), v_activity_type, v_profile."CRMAccount_ID", 'Account details updated',
    coalesce(nullif(btrim(p_input ->> 'changeSummary'), ''), 'The account profile and communication preferences were reviewed.'),
    v_now, p_actor_user_id, p_actor_user_id, p_actor_user_id
  );

  return jsonb_build_object('id', p_account_id, 'editVersion', v_next_version);
end;
$_$;


ALTER FUNCTION "public"."_multideck_crm_update_account_unscoped_20260818"("p_actor_user_id" "uuid", "p_account_id" "uuid", "p_expected_version" bigint, "p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_crm_update_contact_unscoped_20260818"("p_actor_user_id" "uuid", "p_contact_id" "uuid", "p_expected_version" bigint, "p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_contact public."Org_Contacts"%rowtype;
  v_profile public."CRM_ContactProfiles"%rowtype;
  v_existing_email public."OrgContact_Emails"%rowtype;
  v_identity public."Comm_Identities"%rowtype;
  v_account_id uuid;
  v_first text := case when p_input ? 'firstName' then nullif(btrim(p_input ->> 'firstName'), '') end;
  v_last text := case when p_input ? 'lastName' then nullif(btrim(p_input ->> 'lastName'), '') end;
  v_email text := lower(nullif(btrim(p_input ->> 'email'), ''));
  v_phone text := nullif(btrim(p_input ->> 'phone'), '');
  v_now timestamptz := now();
  v_marketing boolean;
  v_reason text;
  v_next_version bigint;
  v_metadata jsonb;
  v_activity_id uuid;
  v_activity_type text;
begin
  perform public._multideck_crm_write_actor(p_actor_user_id);

  select * into v_contact from public."Org_Contacts" where "OrgContact_ID" = p_contact_id for update;
  if not found then
    raise exception 'Contact not found.' using errcode = 'P0002';
  end if;
  v_first := case when p_input ? 'firstName' then nullif(btrim(p_input ->> 'firstName'), '') else v_contact."OrgContact_FirstName" end;
  v_last := case when p_input ? 'lastName' then nullif(btrim(p_input ->> 'lastName'), '') else v_contact."OrgContact_LastName" end;
  v_email := case when p_input ? 'email' then lower(nullif(btrim(p_input ->> 'email'), '')) else null end;
  if v_first is null and v_last is null then
    raise exception 'Enter the contact''s name.' using errcode = '22023';
  end if;

  select * into v_profile from public."CRM_ContactProfiles"
  where "CRMContact_OrgContactID" = p_contact_id
  order by "CRMContact_ID"
  limit 1 for update;
  if not found then
    if p_expected_version is not null and p_expected_version <> 1 then
      raise exception 'CRM_CONFLICT:This contact changed since it was loaded.' using errcode = 'P0001';
    end if;
    insert into public."CRM_ContactProfiles"(
      "CRMContact_ID", "CRMContact_OrgContactID", "CRMContact_CreatedBy", "CRMContact_UpdatedBy", "CRMContact_EditVersion"
    ) values (gen_random_uuid(), p_contact_id, p_actor_user_id, p_actor_user_id, 1)
    returning * into v_profile;
  elsif p_expected_version is not null and v_profile."CRMContact_EditVersion" <> p_expected_version then
    raise exception 'CRM_CONFLICT:This contact changed since it was loaded.' using errcode = 'P0001';
  end if;
  v_next_version := coalesce(v_profile."CRMContact_EditVersion", 1) + 1;

  if v_email is not null then
    perform pg_advisory_xact_lock(hashtextextended(v_email, 0));
    if exists (
      select 1 from public."OrgContact_Emails" email
      where lower(btrim(email."OrgContactEmail_Email")) = v_email
        and email."OrgContact_ID" <> p_contact_id
    ) then
      raise exception 'This email is already connected to a contact.' using errcode = '23505';
    end if;
  end if;

  v_marketing := case when p_input ? 'marketingOptIn' then public._multideck_crm_json_bool(p_input, 'marketingOptIn', v_contact."OrgContact_MarketingOptIn") else v_contact."OrgContact_MarketingOptIn" end;
  if v_marketing is distinct from v_contact."OrgContact_MarketingOptIn" then
    v_reason := nullif(btrim(p_input ->> 'marketingConsentReason'), '');
    if v_reason is null then
      raise exception 'Explain the source or evidence for this consent change.' using errcode = '22023';
    end if;
  end if;

  update public."Org_Contacts"
  set "OrgContact_FirstName" = case when p_input ? 'firstName' then v_first else "OrgContact_FirstName" end,
      "OrgContact_LastName" = case when p_input ? 'lastName' then v_last else "OrgContact_LastName" end
  where "OrgContact_ID" = p_contact_id;

  select * into v_existing_email from public."OrgContact_Emails"
  where "OrgContact_ID" = p_contact_id
  order by "OrgContactEmail_Type", "OrgContactEmail_ID"
  limit 1 for update;
  if p_input ? 'email' then
    if v_email is null and found then
      delete from public."OrgContact_Emails" where "OrgContactEmail_ID" = v_existing_email."OrgContactEmail_ID";
    elsif v_email is not null and found then
      update public."OrgContact_Emails" set "OrgContactEmail_Email" = v_email where "OrgContactEmail_ID" = v_existing_email."OrgContactEmail_ID";
    elsif v_email is not null then
      insert into public."OrgContact_Emails"("OrgContactEmail_ID", "OrgContact_ID", "OrgContactEmail_Email", "OrgContactEmail_Type")
      values (gen_random_uuid(), p_contact_id, v_email, 1);
    end if;
  end if;

  v_metadata := case when jsonb_typeof(p_input -> 'metadata') = 'object' then p_input -> 'metadata' else coalesce(v_profile."CRMContact_MetadataJSON", '{}'::jsonb) end;
  v_metadata := v_metadata || jsonb_build_object(
    'jobTitle', case when p_input ? 'jobTitle' then nullif(btrim(p_input ->> 'jobTitle'), '') else v_metadata ->> 'jobTitle' end,
    'department', case when p_input ? 'department' then nullif(btrim(p_input ->> 'department'), '') else v_metadata ->> 'department' end,
    'phone', case when p_input ? 'phone' then v_phone else v_metadata ->> 'phone' end
  );

  select account."CRMAccount_ID" into v_account_id
  from public."CRM_AccountProfiles" account
  where account."CRMAccount_OrgID" = v_contact."Org_ID"
    and not account."CRMAccount_IsDeleted"
  order by account."CRMAccount_ID"
  limit 1;

  update public."CRM_ContactProfiles"
  set "CRMContact_AccountID" = coalesce(v_profile."CRMContact_AccountID", v_account_id),
      "CRMContact_RoleCode" = case when p_input ? 'role' then nullif(btrim(p_input ->> 'role'), '') else "CRMContact_RoleCode" end,
      "CRMContact_InfluenceLevel" = case when p_input ? 'influenceLevel' then nullif(btrim(p_input ->> 'influenceLevel'), '') else "CRMContact_InfluenceLevel" end,
      "CRMContact_RelationshipStrength" = public._multideck_crm_json_number(p_input, 'relationshipStrength', "CRMContact_RelationshipStrength"),
      "CRMContact_PreferredChannelCode" = case when p_input ? 'preferredChannel' then nullif(btrim(p_input ->> 'preferredChannel'), '') else "CRMContact_PreferredChannelCode" end,
      "CRMContact_PreferredLanguageCode" = case when p_input ? 'preferredLanguage' then nullif(btrim(p_input ->> 'preferredLanguage'), '') else "CRMContact_PreferredLanguageCode" end,
      "CRMContact_ConsentSalesContact" = case when p_input ? 'consentSalesContact' then public._multideck_crm_json_bool(p_input, 'consentSalesContact', "CRMContact_ConsentSalesContact") else "CRMContact_ConsentSalesContact" end,
      "CRMContact_ConsentMarketing" = v_marketing,
      "CRMContact_Notes" = case when p_input ? 'notes' then nullif(btrim(p_input ->> 'notes'), '') else "CRMContact_Notes" end,
      "CRMContact_IsTrainingAllowed" = case when p_input ? 'trainingAllowed' then public._multideck_crm_json_bool(p_input, 'trainingAllowed', "CRMContact_IsTrainingAllowed") else "CRMContact_IsTrainingAllowed" end,
      "CRMContact_MetadataJSON" = v_metadata,
      "CRMContact_UpdatedAt" = v_now,
      "CRMContact_UpdatedBy" = p_actor_user_id,
      "CRMContact_EditVersion" = v_next_version
  where "CRMContact_ID" = v_profile."CRMContact_ID";

  if p_input ? 'phone' then
    select * into v_identity from public."Comm_Identities"
    where "CommIdentity_ContactID" = p_contact_id
      and "CommIdentity_ChannelCode" in ('phone', 'sms', 'whatsapp')
      and not "CommIdentity_IsDeleted"
    order by "CommIdentity_ID"
    limit 1
    for update;
    if v_phone is null and found then
      update public."Comm_Identities" set "CommIdentity_IsDeleted" = true, "CommIdentity_UpdatedAt" = v_now where "CommIdentity_ID" = v_identity."CommIdentity_ID";
    elsif v_phone is not null then
      if found then
        update public."Comm_Identities"
        set "CommIdentity_ChannelCode" = case when nullif(btrim(p_input ->> 'preferredChannel'), '') = 'whatsapp' then 'whatsapp' else 'phone' end,
            "CommIdentity_Address" = v_phone,
            "CommIdentity_NormalizedAddress" = regexp_replace(v_phone, '[^+0-9]', '', 'g'),
            "CommIdentity_DisplayName" = btrim(concat_ws(' ', coalesce(v_first, v_contact."OrgContact_FirstName"), coalesce(v_last, v_contact."OrgContact_LastName"))),
            "CommIdentity_UpdatedAt" = v_now
        where "CommIdentity_ID" = v_identity."CommIdentity_ID";
      else
        insert into public."Comm_Identities"(
          "CommIdentity_ID", "CommIdentity_ChannelCode", "CommIdentity_Address", "CommIdentity_NormalizedAddress",
          "CommIdentity_DisplayName", "CommIdentity_ParticipantTypeCode", "CommIdentity_OrgID", "CommIdentity_ContactID",
          "CommIdentity_Source", "CommIdentity_UpdatedAt"
        ) values (
          gen_random_uuid(), case when nullif(btrim(p_input ->> 'preferredChannel'), '') = 'whatsapp' then 'whatsapp' else 'phone' end,
          v_phone, regexp_replace(v_phone, '[^+0-9]', '', 'g'),
          btrim(concat_ws(' ', coalesce(v_first, v_contact."OrgContact_FirstName"), coalesce(v_last, v_contact."OrgContact_LastName"))),
          'external', v_contact."Org_ID", p_contact_id, 'crm_contact_detail', v_now
        );
      end if;
    end if;
  end if;

  if v_marketing is distinct from v_contact."OrgContact_MarketingOptIn" then
    perform public._multideck_set_marketing_consent(
      'contact', p_contact_id, v_marketing, 'contact_detail', v_reason, p_actor_user_id,
      jsonb_build_object('surface', 'crm_contact_detail')
    );
  end if;

  select "CRMActType_Code" into v_activity_type
  from public."sys_CRMActivityTypes"
  where "CRMActType_IsActive"
  order by case when "CRMActType_Code" = 'note' then 0 else 1 end, "CRMActType_SortOrder", "CRMActType_Code"
  limit 1;
  if v_activity_type is null then
    raise exception 'No active CRM activity type is configured.' using errcode = '23503';
  end if;

  v_activity_id := gen_random_uuid();
  insert into public."CRM_Activities"(
    "CRMActivity_ID", "CRMActivity_ActivityTypeCode", "CRMActivity_AccountID", "CRMActivity_Subject",
    "CRMActivity_Summary", "CRMActivity_ActivityAt", "CRMActivity_OwnerUserID", "CRMActivity_CreatedBy", "CRMActivity_UpdatedBy"
  ) values (
    v_activity_id, v_activity_type, coalesce(v_profile."CRMContact_AccountID", v_account_id), 'Contact details updated',
    coalesce(nullif(btrim(p_input ->> 'changeSummary'), ''), 'The contact profile and communication preferences were reviewed.'),
    v_now, p_actor_user_id, p_actor_user_id, p_actor_user_id
  );
  insert into public."CRM_ActivityParticipants"(
    "CRMActPart_ID", "CRMActPart_ActivityID", "CRMActPart_OrgID", "CRMActPart_OrgContactID",
    "CRMActPart_NameSnapshot", "CRMActPart_EmailSnapshot", "CRMActPart_Role", "CRMActPart_IsExternal"
  ) values (
    gen_random_uuid(), v_activity_id, v_contact."Org_ID", p_contact_id,
    btrim(concat_ws(' ', coalesce(v_first, v_contact."OrgContact_FirstName"), coalesce(v_last, v_contact."OrgContact_LastName"))),
    v_email, nullif(btrim(p_input ->> 'role'), ''), true
  );

  return jsonb_build_object('id', p_contact_id, 'accountId', v_contact."Org_ID", 'editVersion', v_next_version);
end;
$$;


ALTER FUNCTION "public"."_multideck_crm_update_contact_unscoped_20260818"("p_actor_user_id" "uuid", "p_contact_id" "uuid", "p_expected_version" bigint, "p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_crm_update_deal_unversioned_20260818"("p_deal_id" "uuid", "p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_context record;
  v_deal record;
  v_probability numeric;
  v_value numeric;
begin
  select * into v_context from public._multideck_crm_context();

  if not public._multideck_crm_has_permission(v_context.user_id, 'CRM.Write') then
    raise exception 'You do not have permission to change CRM.' using errcode = '42501';
  end if;

  if coalesce(jsonb_typeof(p_input), '') <> 'object' then
    raise exception 'Deal changes must be an object.' using errcode = '22023';
  end if;

  select deal.* into v_deal
  from public."CRM_Opportunities" deal
  join public."CRM_Pipelines" pipeline
    on pipeline."CRMPipeline_ID" = deal."CRMOppty_PipelineID"
  where deal."CRMOppty_ID" = p_deal_id
    and not deal."CRMOppty_IsDeleted"
    and pipeline."Company_ID" = v_context.company_id
    and not pipeline."Is_Deleted"
  for update of deal;

  if not found then
    raise exception 'Deal not found.' using errcode = 'P0002';
  end if;

  if p_input ? 'name' and coalesce(btrim(p_input ->> 'name'), '') = '' then
    raise exception 'A deal needs a name.' using errcode = '22023';
  end if;

  if p_input ? 'primaryContactId'
     and nullif(p_input ->> 'primaryContactId', '') is not null
     and not exists (
       select 1
       from public."Org_Contacts" contact
       where contact."OrgContact_ID" = (p_input ->> 'primaryContactId')::uuid
         and contact."Org_ID" = v_deal."CRMOppty_OrgID"
     ) then
    raise exception 'Choose a contact from this deal account.' using errcode = '22023';
  end if;

  if p_input ? 'ownerId'
     and nullif(p_input ->> 'ownerId', '') is not null
     and not exists (
       select 1
       from public."cmp_Users" owner
       where owner."User_ID" = (p_input ->> 'ownerId')::uuid
         and owner."Company_ID" = v_context.company_id
         and coalesce(owner."User_AccessStatus", 'active') = 'active'
     ) then
    raise exception 'Choose an active owner from this workspace.' using errcode = '22023';
  end if;

  update public."CRM_Opportunities"
  set
    "CRMOppty_Name" = case when p_input ? 'name' then btrim(p_input ->> 'name') else "CRMOppty_Name" end,
    "CRMOppty_PrimaryContactID" = case when p_input ? 'primaryContactId' then nullif(p_input ->> 'primaryContactId', '')::uuid else "CRMOppty_PrimaryContactID" end,
    "CRMOppty_OwnerUserID" = case when p_input ? 'ownerId' then nullif(p_input ->> 'ownerId', '')::uuid else "CRMOppty_OwnerUserID" end,
    "CRMOppty_ExpectedCloseDate" = case when p_input ? 'expectedCloseDate' then nullif(p_input ->> 'expectedCloseDate', '')::date else "CRMOppty_ExpectedCloseDate" end,
    "CRMOppty_ExpectedValueAmount" = case when p_input ? 'expectedValueAmount' then nullif(p_input ->> 'expectedValueAmount', '')::numeric else "CRMOppty_ExpectedValueAmount" end,
    "CRMOppty_ExpectedMarginAmount" = case when p_input ? 'expectedMarginAmount' then nullif(p_input ->> 'expectedMarginAmount', '')::numeric else "CRMOppty_ExpectedMarginAmount" end,
    "CRMOppty_CurrencyCode" = case when p_input ? 'currencyCode' then upper(nullif(btrim(p_input ->> 'currencyCode'), '')) else "CRMOppty_CurrencyCode" end,
    "CRMOppty_ModeCode" = case when p_input ? 'modeCode' then nullif(btrim(p_input ->> 'modeCode'), '') else "CRMOppty_ModeCode" end,
    "CRMOppty_DirectionCode" = case when p_input ? 'directionCode' then nullif(btrim(p_input ->> 'directionCode'), '') else "CRMOppty_DirectionCode" end,
    "CRMOppty_OriginNameSnapshot" = case when p_input ? 'originName' then nullif(btrim(p_input ->> 'originName'), '') else "CRMOppty_OriginNameSnapshot" end,
    "CRMOppty_DestinationNameSnapshot" = case when p_input ? 'destinationName' then nullif(btrim(p_input ->> 'destinationName'), '') else "CRMOppty_DestinationNameSnapshot" end,
    "CRMOppty_TradeLane" = case when p_input ? 'tradeLane' then nullif(btrim(p_input ->> 'tradeLane'), '') else "CRMOppty_TradeLane" end,
    "CRMOppty_ServiceInterest" = case when p_input ? 'serviceInterest' then nullif(btrim(p_input ->> 'serviceInterest'), '') else "CRMOppty_ServiceInterest" end,
    "CRMOppty_CustomerNeed" = case when p_input ? 'customerNeed' then nullif(btrim(p_input ->> 'customerNeed'), '') else "CRMOppty_CustomerNeed" end,
    "CRMOppty_ValueProposition" = case when p_input ? 'valueProposition' then nullif(btrim(p_input ->> 'valueProposition'), '') else "CRMOppty_ValueProposition" end,
    "CRMOppty_NextActionDueAt" = case when p_input ? 'nextActionDueAt' then nullif(p_input ->> 'nextActionDueAt', '')::timestamptz else "CRMOppty_NextActionDueAt" end,
    "CRMOppty_UpdatedAt" = now(),
    "CRMOppty_UpdatedBy" = v_context.user_id
  where "CRMOppty_ID" = p_deal_id
  returning "CRMOppty_ExpectedValueAmount", "CRMOppty_ProbabilityPct"
  into v_value, v_probability;

  update public."CRM_Opportunities"
  set "CRMOppty_WeightedValueAmount" =
    case
      when v_value is null or v_probability is null then null
      else round(v_value * v_probability / 100, 4)
    end
  where "CRMOppty_ID" = p_deal_id;

  return public._multideck_crm_deal_json(p_deal_id, v_context.company_id);
end;
$$;


ALTER FUNCTION "public"."_multideck_crm_update_deal_unversioned_20260818"("p_deal_id" "uuid", "p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_crm_update_deal_visible_guard_20260818"("p_deal_id" "uuid", "p_expected_version" bigint, "p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_context record;
  v_current_version bigint;
  v_result jsonb;
begin
  select * into v_context from public._multideck_crm_context();
  if not public._multideck_crm_has_permission(v_context.user_id, 'CRM.Write') then
    raise exception 'You do not have permission to change CRM.' using errcode = '42501';
  end if;
  if p_expected_version is null or p_expected_version < 1 then
    raise exception 'A valid deal version is required.' using errcode = '22023';
  end if;

  select deal."CRMOppty_EditVersion" into v_current_version
  from public."CRM_Opportunities" deal
  join public."CRM_Pipelines" pipeline
    on pipeline."CRMPipeline_ID" = deal."CRMOppty_PipelineID"
   and pipeline."Company_ID" = v_context.company_id
   and not pipeline."Is_Deleted"
  where deal."CRMOppty_ID" = p_deal_id
    and not deal."CRMOppty_IsDeleted"
  for update of deal;

  if not found then
    raise exception 'Deal not found.' using errcode = 'P0002';
  end if;
  if v_current_version <> p_expected_version then
    raise exception 'CRM_CONFLICT: This deal changed elsewhere. Latest values have been reloaded.' using errcode = 'P0001';
  end if;

  v_result := public._multideck_crm_update_deal_unversioned_20260818(p_deal_id, p_input);
  select deal."CRMOppty_EditVersion" into v_current_version
  from public."CRM_Opportunities" deal
  where deal."CRMOppty_ID" = p_deal_id;
  return v_result || jsonb_build_object('editVersion', v_current_version);
end;
$$;


ALTER FUNCTION "public"."_multideck_crm_update_deal_visible_guard_20260818"("p_deal_id" "uuid", "p_expected_version" bigint, "p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_crm_update_lead_unversioned_20260818"("p_lead_id" "uuid", "p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_context record;
begin
  select * into v_context from public._multideck_crm_context();

  if not public._multideck_crm_has_permission(v_context.user_id, 'CRM.Write') then
    raise exception 'You do not have permission to change CRM.' using errcode = '42501';
  end if;

  if coalesce(jsonb_typeof(p_input), '') <> 'object' then
    raise exception 'Lead changes must be an object.' using errcode = '22023';
  end if;

  if not public._multideck_crm_lead_is_reachable(p_lead_id, v_context.company_id) then
    raise exception 'Lead not found.' using errcode = 'P0002';
  end if;

  perform 1
  from public."CRM_Leads"
  where "CRMLead_ID" = p_lead_id
    and not "CRMLead_IsDeleted"
  for update;

  if not found then
    raise exception 'Lead not found.' using errcode = 'P0002';
  end if;

  if p_input ? 'companyName' and coalesce(btrim(p_input ->> 'companyName'), '') = '' then
    raise exception 'A lead needs a company name.' using errcode = '22023';
  end if;

  update public."CRM_Leads"
  set
    "CRMLead_CompanyName" = case when p_input ? 'companyName' then btrim(p_input ->> 'companyName') else "CRMLead_CompanyName" end,
    "CRMLead_PersonName" = case when p_input ? 'primaryContactName' then nullif(btrim(p_input ->> 'primaryContactName'), '') else "CRMLead_PersonName" end,
    "CRMLead_Email" = case when p_input ? 'primaryContactEmail' then nullif(btrim(p_input ->> 'primaryContactEmail'), '') else "CRMLead_Email" end,
    "CRMLead_CountryCode" = case when p_input ? 'countryCode' then upper(nullif(btrim(p_input ->> 'countryCode'), '')) else "CRMLead_CountryCode" end,
    "CRMLead_TradeLane" = case when p_input ? 'tradeLane' then nullif(btrim(p_input ->> 'tradeLane'), '') else "CRMLead_TradeLane" end,
    "CRMLead_ServiceInterest" = case when p_input ? 'serviceInterest' then nullif(btrim(p_input ->> 'serviceInterest'), '') else "CRMLead_ServiceInterest" end,
    "CRMLead_EstimatedValueAmount" = case when p_input ? 'valueAmount' then nullif(p_input ->> 'valueAmount', '')::numeric else "CRMLead_EstimatedValueAmount" end,
    "CRMLead_EstimatedValueCurrencyCode" = case when p_input ? 'valueCurrencyCode' then upper(nullif(btrim(p_input ->> 'valueCurrencyCode'), '')) else "CRMLead_EstimatedValueCurrencyCode" end,
    "CRMLead_NextActionDueAt" = case when p_input ? 'nextFollowUpAt' then nullif(p_input ->> 'nextFollowUpAt', '')::timestamptz else "CRMLead_NextActionDueAt" end,
    "CRMLead_UpdatedAt" = now(),
    "CRMLead_UpdatedBy" = v_context.user_id
  where "CRMLead_ID" = p_lead_id;

  return public._multideck_crm_lead_json(p_lead_id);
end;
$$;


ALTER FUNCTION "public"."_multideck_crm_update_lead_unversioned_20260818"("p_lead_id" "uuid", "p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_crm_validate_account_finance_preferences"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  v_preferences jsonb := coalesce(new."CRMAccountOps_InvoicePreferencesJSON", '{}'::jsonb);
  v_bank jsonb;
  v_key text;
  v_value text;
  v_entity_id uuid;
  v_effective_from date;
  v_effective_to date;
begin
  if jsonb_typeof(v_preferences) <> 'object' then
    raise exception 'Organisation finance preferences must be an object.' using errcode = '22023';
  end if;

  if coalesce(nullif(v_preferences ->> 'customerAccountingStatusCode', ''), 'active') not in ('active','on_hold','blocked') then
    raise exception 'Choose a valid customer accounting status.' using errcode = '22023';
  end if;
  if coalesce(nullif(v_preferences ->> 'supplierAccountingStatusCode', ''), 'active') not in ('active','on_hold','blocked') then
    raise exception 'Choose a valid supplier accounting status.' using errcode = '22023';
  end if;
  if coalesce(nullif(v_preferences ->> 'preferredReceiptMethodCode', ''), 'bank_transfer') not in ('bank_transfer','direct_debit','card','cheque','cash','offset')
    or coalesce(nullif(v_preferences ->> 'preferredPaymentMethodCode', ''), 'bank_transfer') not in ('bank_transfer','direct_debit','card','cheque','cash','offset') then
    raise exception 'Choose a valid receipt and payment method.' using errcode = '22023';
  end if;
  if coalesce(nullif(v_preferences ->> 'salesInvoiceGroupingCode', ''), 'per_job') not in ('per_job','daily','weekly','monthly') then
    raise exception 'Choose a valid invoice grouping rule.' using errcode = '22023';
  end if;
  if coalesce(nullif(v_preferences ->> 'statementFrequencyCode', ''), 'monthly') not in ('never','weekly','monthly') then
    raise exception 'Choose a valid statement frequency.' using errcode = '22023';
  end if;
  if coalesce(nullif(v_preferences ->> 'paymentRunGroupCode', ''), 'weekly') not in ('manual','daily','weekly','monthly') then
    raise exception 'Choose a valid payment run group.' using errcode = '22023';
  end if;
  if coalesce(nullif(v_preferences ->> 'purchaseInvoiceMatchingCode', ''), 'two_way') not in ('none','two_way','three_way') then
    raise exception 'Choose a valid purchase invoice matching rule.' using errcode = '22023';
  end if;

  foreach v_key in array array['defaultSalesLegalEntityId','defaultPurchaseLegalEntityId'] loop
    v_value := nullif(btrim(v_preferences ->> v_key), '');
    if v_value is not null then
      begin v_entity_id := v_value::uuid;
      exception when invalid_text_representation then
        raise exception 'Choose a valid legal entity for organisation finance.' using errcode = '22023';
      end;
      if not exists (
        select 1 from public."cmp_LegalEntities" e
        where e."LegalEntity_ID" = v_entity_id
          and e."Company_ID" = new."CRMAccountOps_CompanyID"
      ) then
        raise exception 'The selected finance legal entity is outside this workspace.' using errcode = '42501';
      end if;
    end if;
  end loop;

  foreach v_key in array array[
    'creditHold','requiresCustomerPurchaseOrder','requiresJobReferenceOnInvoice','sendStatements',
    'receivableEndOfMonth','supplierPaymentHold','purchaseOrderRequired','selfBillingAllowed',
    'separateRemittanceAdvice','payableEndOfMonth'
  ] loop
    if v_preferences ? v_key and jsonb_typeof(v_preferences -> v_key) <> 'boolean' then
      raise exception 'Organisation finance switch % must be true or false.', v_key using errcode = '22023';
    end if;
  end loop;

  foreach v_key in array array[
    'creditLimit','receivableTermDays','receivableDueDay','payableTermDays','payableDueDay','purchaseMatchTolerancePercent'
  ] loop
    v_value := nullif(btrim(v_preferences ->> v_key), '');
    if v_value is not null and v_value !~ '^[0-9]+([.][0-9]{1,4})?$' then
      raise exception 'Organisation finance amount % must be a non-negative number.', v_key using errcode = '22023';
    end if;
  end loop;

  v_value := lower(nullif(btrim(v_preferences ->> 'invoiceLanguageCode'), ''));
  if v_value is not null and v_value !~ '^[a-z]{2}(-[a-z]{2})?$' then
    raise exception 'Invoice language must use a two-letter language code.' using errcode = '22023';
  end if;
  if v_value is not null then v_preferences := jsonb_set(v_preferences, '{invoiceLanguageCode}', to_jsonb(v_value), true); end if;

  foreach v_key in array array[
    'customerTaxRegistrationNo','supplierTaxRegistrationNo','salesPaymentTermCode','purchasePaymentTermCode',
    'salesTaxTreatmentCode','purchaseTaxTreatmentCode','receivableAccountCode','payableAccountCode',
    'invoiceEmail','statementEmail','purchaseInvoiceEmail','remittanceAdviceEmail','invoiceDeliveryMethod',
    'purchaseInvoiceDeliveryMethod'
  ] loop
    if v_preferences ? v_key then
      v_preferences := jsonb_set(v_preferences, array[v_key], to_jsonb(left(coalesce(v_preferences ->> v_key, ''), case when v_key like '%Email' then 320 else 180 end)), true);
    end if;
  end loop;

  if jsonb_typeof(coalesce(v_preferences -> 'bankAccounts', '[]'::jsonb)) <> 'array' then
    raise exception 'Bank accounts must be a list.' using errcode = '22023';
  end if;
  for v_bank in select value from jsonb_array_elements(coalesce(v_preferences -> 'bankAccounts', '[]'::jsonb)) loop
    if coalesce(nullif(v_bank ->> 'verificationStatusCode', ''), 'pending') not in ('pending','verified','rejected') then
      raise exception 'Choose a valid bank verification status.' using errcode = '22023';
    end if;
    foreach v_key in array array['useForPayments','useForRefunds','useForDirectDebit','isDefault'] loop
      if v_bank ? v_key and jsonb_typeof(v_bank -> v_key) <> 'boolean' then
        raise exception 'Bank usage switch % must be true or false.', v_key using errcode = '22023';
      end if;
    end loop;
    begin
      v_effective_from := nullif(v_bank ->> 'effectiveFrom', '')::date;
      v_effective_to := nullif(v_bank ->> 'effectiveTo', '')::date;
      perform nullif(v_bank ->> 'verifiedAt', '')::date;
    exception when invalid_datetime_format or datetime_field_overflow then
      raise exception 'Bank verification and effective dates must be valid dates.' using errcode = '22023';
    end;
    if v_effective_from is not null and v_effective_to is not null and v_effective_to < v_effective_from then
      raise exception 'A bank account effective-to date cannot be before its effective-from date.' using errcode = '22023';
    end if;
    if coalesce(v_bank ->> 'verificationStatusCode', 'pending') = 'verified'
      and (nullif(btrim(v_bank ->> 'verificationReference'), '') is null or nullif(v_bank ->> 'verifiedAt', '') is null) then
      raise exception 'A verified bank account needs a verification reference and date.' using errcode = '22023';
    end if;
  end loop;

  new."CRMAccountOps_InvoicePreferencesJSON" := v_preferences;
  return new;
end;
$_$;


ALTER FUNCTION "public"."_multideck_crm_validate_account_finance_preferences"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_multideck_crm_validate_account_finance_preferences"() IS 'Validates party-level AR, AP, tax, legal-entity, payment and verified masked-bank settings before accounting transactions use them.';



CREATE OR REPLACE FUNCTION "public"."_multideck_crm_validate_deal_pipeline_stage"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if not new."CRMOppty_IsDeleted" then
    perform public._multideck_crm_lock_pipeline_stage(
      new."CRMOppty_PipelineID",
      new."CRMOppty_PipelineStageID"
    );

    if new."CRMOppty_PipelineID" is null or new."CRMOppty_PipelineStageID" is null or not exists (
      select 1
      from public."CRM_Pipelines" pipeline
      join public."CRM_PipelineStages" stage
        on stage."CRMPipeline_ID" = pipeline."CRMPipeline_ID"
       and stage."CRMPipelineStage_ID" = new."CRMOppty_PipelineStageID"
       and not stage."Is_Deleted"
      where pipeline."CRMPipeline_ID" = new."CRMOppty_PipelineID"
        and not pipeline."Is_Deleted"
    ) then
      raise exception 'Choose an active stage in this pipeline before saving the deal.' using errcode = '22023';
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."_multideck_crm_validate_deal_pipeline_stage"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_crm_win_deal_unfiltered_20260818"("p_deal_id" "uuid", "p_pipeline_stage_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_context record; v_deal public."CRM_Opportunities"%rowtype; v_stage public."CRM_PipelineStages"%rowtype;
  v_won_stage text; v_won_status text; v_customer_status text; v_customer_type uuid; v_account_id uuid; v_activity_type text; v_now timestamptz := now();
begin
  select * into v_context from public._multideck_crm_context();
  perform pg_advisory_xact_lock(hashtextextended(p_deal_id::text, 7299));
  select * into v_deal from public."CRM_Opportunities" where "CRMOppty_ID" = p_deal_id and not "CRMOppty_IsDeleted" for update;
  if not found then raise exception 'This deal no longer exists.' using errcode = 'P0002'; end if;
  if not exists (select 1 from public."CRM_Pipelines" where "CRMPipeline_ID" = v_deal."CRMOppty_PipelineID" and "Company_ID" = v_context.company_id and not "Is_Deleted") then
    raise exception 'This deal is outside your CRM workspace.' using errcode = '42501';
  end if;
  if v_deal."CRMOppty_OwnerUserID" is distinct from v_context.user_id and not public._multideck_crm_has_permission(v_context.user_id, 'CRM.Deals.Win') then
    raise exception 'You do not have permission to mark this deal won.' using errcode = '42501';
  end if;
  select * into v_stage from public."CRM_PipelineStages" where "CRMPipelineStage_ID" = p_pipeline_stage_id
    and "CRMPipeline_ID" = v_deal."CRMOppty_PipelineID" and "Company_ID" = v_context.company_id and not "Is_Deleted";
  if not found or not v_stage."CRMPipelineStage_IsConversion" then raise exception 'Choose the configured customer-conversion stage.' using errcode = '22023'; end if;
  if v_deal."CRMOppty_WonAt" is not null then
    return public._multideck_crm_deal_json(p_deal_id, v_context.company_id) || jsonb_build_object('isWon', true, 'wonAt', v_deal."CRMOppty_WonAt", 'isCustomer', true, 'wasAlreadyConverted', true);
  end if;
  select "CRMStage_Code" into v_won_stage from public."sys_CRMOpportunityStages" where "CRMStage_IsActive" and "CRMStage_IsWon" order by "CRMStage_SortOrder" limit 1;
  select "CRMOpptyStatus_Code" into v_won_status from public."sys_CRMOpportunityStatuses" where "CRMOpptyStatus_IsActive" and not "CRMOpptyStatus_IsOpen"
  order by (lower("CRMOpptyStatus_Code") like '%won%' or lower("CRMOpptyStatus_Name") like '%won%') desc, "CRMOpptyStatus_SortOrder" limit 1;
  select "CRMRelStatus_Code" into v_customer_status from public."sys_CRMRelationshipStatuses" where "CRMRelStatus_IsActive" and "CRMRelStatus_IsCustomer" order by "CRMRelStatus_SortOrder" limit 1;
  select "OrgType_ID" into v_customer_type from public."Org_Types" where lower("OrgType_Name") = 'customer' order by "OrgType_Order" nulls last limit 1;
  if v_won_stage is null or v_won_status is null or v_customer_status is null or v_customer_type is null then
    raise exception 'Customer conversion lookups are incomplete for this workspace.' using errcode = '55000';
  end if;
  insert into public."CRM_AccountProfiles" ("CRMAccount_OrgID", "CRMAccount_RelationshipStatusCode", "CRMAccount_OwnerUserID", "CRMAccount_CreatedBy", "CRMAccount_UpdatedBy")
  values (v_deal."CRMOppty_OrgID", v_customer_status, v_deal."CRMOppty_OwnerUserID", v_context.user_id, v_context.user_id)
  on conflict ("CRMAccount_OrgID") do update set "CRMAccount_RelationshipStatusCode" = excluded."CRMAccount_RelationshipStatusCode",
    "CRMAccount_OwnerUserID" = coalesce(public."CRM_AccountProfiles"."CRMAccount_OwnerUserID", excluded."CRMAccount_OwnerUserID"),
    "CRMAccount_UpdatedAt" = v_now, "CRMAccount_UpdatedBy" = v_context.user_id, "CRMAccount_IsDeleted" = false
  returning "CRMAccount_ID" into v_account_id;
  insert into public."Org_Master_Type" ("Org_ID", "OrgType_ID")
  select v_deal."CRMOppty_OrgID", v_customer_type
  where not exists (select 1 from public."Org_Master_Type" where "Org_ID" = v_deal."CRMOppty_OrgID" and "OrgType_ID" = v_customer_type);
  update public."Org_Master" set "Org_CRMRelationshipStatusCode" = v_customer_status, "Org_CRMIsLead" = false,
    "Org_CRMIsPotentialCustomer" = false, "Org_CRMUpdatedAt" = v_now where "Org_id" = v_deal."CRMOppty_OrgID";
  update public."CRM_Opportunities" set "CRMOppty_AccountID" = v_account_id, "CRMOppty_PipelineStageID" = p_pipeline_stage_id,
    "CRMOppty_StageCode" = v_won_stage, "CRMOppty_StatusCode" = v_won_status, "CRMOppty_ProbabilityPct" = 100,
    "CRMOppty_WonAt" = v_now, "CRMOppty_LostAt" = null, "CRMOppty_UpdatedAt" = v_now, "CRMOppty_UpdatedBy" = v_context.user_id,
    "CRMOppty_MetadataJSON" = coalesce("CRMOppty_MetadataJSON", '{}'::jsonb) || jsonb_build_object('customerConvertedAt', v_now, 'customerConvertedBy', v_context.user_id)
  where "CRMOppty_ID" = p_deal_id;
  select "CRMActType_Code" into v_activity_type from public."sys_CRMActivityTypes" where "CRMActType_IsActive" order by "CRMActType_SortOrder" limit 1;
  if v_activity_type is not null then
    insert into public."CRM_Activities" ("CRMActivity_ActivityTypeCode", "CRMActivity_AccountID", "CRMActivity_LeadID", "CRMActivity_OpportunityID", "CRMActivity_Subject", "CRMActivity_Summary", "CRMActivity_OwnerUserID", "CRMActivity_MetadataJSON", "CRMActivity_CreatedBy", "CRMActivity_UpdatedBy")
    values (v_activity_type, v_account_id, v_deal."CRMOppty_SourceLeadID", p_deal_id, 'Deal won — customer created', nullif(btrim(p_reason), ''),
      v_deal."CRMOppty_OwnerUserID", jsonb_build_object('event', 'customer_converted', 'organisationId', v_deal."CRMOppty_OrgID"), v_context.user_id, v_context.user_id);
  end if;
  return public._multideck_crm_deal_json(p_deal_id, v_context.company_id) || jsonb_build_object('isWon', true, 'wonAt', v_now, 'isCustomer', true, 'customerOrgId', v_deal."CRMOppty_OrgID", 'wasAlreadyConverted', false);
end;
$$;


ALTER FUNCTION "public"."_multideck_crm_win_deal_unfiltered_20260818"("p_deal_id" "uuid", "p_pipeline_stage_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_crm_write_actor"("p_actor_user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if p_actor_user_id is null or not exists (
    select 1 from public."cmp_Users"
    where "User_ID" = p_actor_user_id
      and coalesce("User_AccessStatus", 'active') = 'active'
      and "Auth_User_ID" is not null
  ) then
    raise exception 'The CRM operator is not active.' using errcode = '42501';
  end if;
  perform public."Audit_SetContext"(
    p_actor_user_id, null, 'user', null, null, null, null, null, null,
    'multideck', 'crm', null, null, null
  );
end;
$$;


