    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_company_id uuid; v_booking_reference text; v_old jsonb:='{}'::jsonb; v_new jsonb;
