    'riskScore',new."Job_TrackingRiskScore",'mode',new."Job_TransportModeSummary",'direction',new."Job_Direction",
    'origin',coalesce(new."Job_OriginNameSnapshot",new."Job_OriginUNLocode"),'destination',coalesce(new."Job_DestinationNameSnapshot",new."Job_DestinationUNLocode"),
    'currentLocation',new."Job_CurrentLocationNameSnapshot",'requiredDeliveryDate',new."Job_RequiredDeliveryDate",
    'predictedDeliveryAt',new."Job_PredictedDeliveryAt",'customerId',new."Job_Customer",'carrierId',new."Job_Carrier",
    'customerReference',new."Job_CustomerReference",'invoiceStatus',new."Job_InvoiceStatus",'invoiceReadyAt',new."Job_InvoiceReadyAt",'completedAt',new."Job_CompletedAt");
  insert into public."AI_DexterWatchSignals" (
    "AIDexterWatchSignal_CompanyID","AIDexterWatchSignal_CapabilityCode","AIDexterWatchSignal_SourceTable",
    "AIDexterWatchSignal_SourceID","AIDexterWatchSignal_OldJSON","AIDexterWatchSignal_NewJSON"
