CREATE OR REPLACE FUNCTION "public"."_multideck_dexter_context"() RETURNS TABLE("user_id" "uuid", "company_id" "uuid")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare linked_count integer;
begin
 if auth.uid() is null then raise exception 'Sign in again to use Agent Dexter.' using errcode='42501';end if;
 select count(*) into linked_count from public."cmp_Users" p where p."Auth_User_ID"=auth.uid();
 if linked_count<>1 then raise exception 'Your signed-in account is not linked to this Multideck workspace.' using errcode='42501';end if;
 return query select p."User_ID",p."Company_ID" from public."cmp_Users" p
 where p."Auth_User_ID"=auth.uid() and p."Company_ID" is not null and coalesce(p."User_AccessStatus",'active')='active';
 if not found then raise exception 'Your signed-in account does not have active access to this Multideck workspace.' using errcode='42501';end if;
end $$;


ALTER FUNCTION "public"."_multideck_dexter_context"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_dexter_conversation_json"("p_conversation_id" "uuid", "p_user_id" "uuid", "p_company_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
  select jsonb_build_object(
    'id', conversation."AICNV_ID",
    'title', coalesce(conversation."AICNV_Title", 'Dexter conversation'),
    'summary', coalesce(conversation."AICNV_SummaryText", ''),
    'updatedAt', conversation."AICNV_UpdatedAt",
    'messages', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', message."AIMSG_ID",
          'role', message."AIMSG_Role",
          'content', message."AIMSG_ContentText",
          'createdAt', message."AIMSG_CreatedAt",
          'specialist', nullif(message."AIMSG_ContentJSON" ->> 'specialist', ''),
          'attachments', case when jsonb_typeof(message."AIMSG_ContentJSON" -> 'attachments') = 'array'
            then message."AIMSG_ContentJSON" -> 'attachments' else '[]'::jsonb end,
          'parentResponseMessageId', nullif(message."AIMSG_ContentJSON" #>> '{metadata,parentResponseMessageId}', ''),
          'pendingAction', case when jsonb_typeof(message."AIMSG_ContentJSON" #> '{metadata,pendingAction}') = 'object'
            then message."AIMSG_ContentJSON" #> '{metadata,pendingAction}' else null end,
          'reasoningSummary', nullif(message."AIMSG_ContentJSON" #>> '{metadata,reasoningSummary}', ''),
          'emailAttachments', case when jsonb_typeof(message."AIMSG_ContentJSON" #> '{metadata,emailAttachments}') = 'array'
            then message."AIMSG_ContentJSON" #> '{metadata,emailAttachments}' else '[]'::jsonb end,
          'emailDraft', case when jsonb_typeof(message."AIMSG_ContentJSON" #> '{metadata,emailDraft}') = 'object'
            then message."AIMSG_ContentJSON" #> '{metadata,emailDraft}' else null end,
          'responseToUserMessageId', nullif(message."AIMSG_ContentJSON" #>> '{metadata,responseToUserMessageId}', ''),
          'responseVersion', case when coalesce(message."AIMSG_ContentJSON" #>> '{metadata,responseVersion}', '') ~ '^[1-9][0-9]*$'
            then (message."AIMSG_ContentJSON" #>> '{metadata,responseVersion}')::integer else null end
        ) order by message."AIMSG_CreatedAt", message."AIMSG_ID"
      )
      from public."AI_Messages" message
      where message."AIMSG_ConversationID" = conversation."AICNV_ID"
        and message."AIMSG_ContentText" is not null
    ), '[]'::jsonb)
  )
  from public."AI_Conversations" conversation
  where conversation."AICNV_ID" = p_conversation_id
    and conversation."AICNV_CompanyID" = p_company_id
    and conversation."AICNV_OwnerUserID" = p_user_id
    and conversation."AICNV_Channel" = 'chat'
    and conversation."AICNV_EndedAt" is null
    and conversation."AICNV_DomainCode" in ('multideck', 'warehouse');
$_$;


ALTER FUNCTION "public"."_multideck_dexter_conversation_json"("p_conversation_id" "uuid", "p_user_id" "uuid", "p_company_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_dexter_create_watch_before_allocations_20260906"("p_capability" "text", "p_title" "text", "p_summary" "text", "p_request" "text", "p_target_id" "uuid", "p_target_label" "text", "p_rule" "jsonb", "p_action" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare context record;
begin
  select * into context from public._multideck_dexter_context();
  if lower(btrim(p_capability))='quote_cargo' then
    if not public.multideck_dexter_can_read_quote_cargo_watch(context.company_id) or p_target_id is null
      or not exists(select 1 from jsonb_array_elements(public.multideck_dexter_domain_quote_cargo(context.company_id,p_target_id::text,1)) row
        where row->>'recordId'=p_target_id::text and (row->>'editable')::boolean) then
      raise exception 'Choose one current editable Quote cargo line in this workspace.' using errcode='42501';end if;
    if p_action is not null or p_rule->>'operator' is distinct from 'changed' then
      raise exception 'Quote cargo watches notify on changes only. Edits need fresh approval.' using errcode='22023';end if;
  end if;
  return public._multideck_dexter_create_watch_before_quote_cargo_20260905(p_capability,p_title,p_summary,p_request,p_target_id,p_target_label,p_rule,p_action);
end $$;


