CREATE OR REPLACE FUNCTION "public"."_multideck_dexter_crm_essential_signal"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_company_id uuid; v_capability text := tg_argv[0]; v_source_id uuid; v_mailbox_id uuid; v_subject text; v_old jsonb := '{}'; v_new jsonb := '{}';
begin
  if tg_table_name = 'CRM_LeadTransferRequests' then
    v_company_id := new."Company_ID"; v_source_id := new."CRMLeadTransfer_LeadID";
    v_old := case when tg_op = 'INSERT' then '{}' else jsonb_build_object('pendingTransferStatus', old."CRMLeadTransfer_Status", 'fromUserId', old."CRMLeadTransfer_FromUserID", 'toUserId', old."CRMLeadTransfer_ToUserID") end;
    v_new := jsonb_build_object('pendingTransferStatus', new."CRMLeadTransfer_Status", 'fromUserId', new."CRMLeadTransfer_FromUserID", 'toUserId', new."CRMLeadTransfer_ToUserID", 'decisionReason', new."CRMLeadTransfer_DecisionReason");
  else
    v_source_id := new."CommDelivery_MessageID";
    select owner."Company_ID", mailbox."CommMailbox_ID", message."CommMessage_Subject" into v_company_id, v_mailbox_id, v_subject
    from public."Comm_Messages" message
    join public."Comm_Mailboxes" mailbox on mailbox."CommMailbox_ID" = message."CommMessage_MailboxID"
    join public."Comm_ProviderConnections" connection on connection."CommConn_ID" = mailbox."CommMailbox_ConnectionID"
    join public."cmp_Users" owner on owner."User_ID" = connection."CommConn_UserID"
    where message."CommMessage_ID" = new."CommDelivery_MessageID";
    v_new := jsonb_build_object('mailboxId', v_mailbox_id, 'subject', v_subject,
      'openedAt', case when new."CommDelivery_EventTypeCode" = 'opened' then new."CommDelivery_EventAt" end,
      'deliveredAt', case when new."CommDelivery_EventTypeCode" = 'delivered' then new."CommDelivery_EventAt" end,
      'repliedAt', case when new."CommDelivery_EventTypeCode" = 'replied' then new."CommDelivery_EventAt" end,
      'bouncedAt', case when new."CommDelivery_EventTypeCode" = 'bounced' then new."CommDelivery_EventAt" end,
      'deliveryStatus', new."CommDelivery_EventTypeCode", 'eventAt', new."CommDelivery_EventAt",
      'openConfidence', case when new."CommDelivery_EventTypeCode" = 'opened' then 'estimated' else 'confirmed' end);
  end if;
  if v_company_id is not null and v_source_id is not null and exists (
    select 1 from public."AI_DexterWatches" watch where watch."AIDexterWatch_CompanyID" = v_company_id
      and watch."AIDexterWatch_CapabilityCode" = v_capability and watch."AIDexterWatch_StatusCode" = 'active'
      and (watch."AIDexterWatch_TargetID" is null or watch."AIDexterWatch_TargetID" = v_source_id)
  ) then
    insert into public."AI_DexterWatchSignals" ("AIDexterWatchSignal_CompanyID", "AIDexterWatchSignal_CapabilityCode", "AIDexterWatchSignal_SourceTable", "AIDexterWatchSignal_SourceID", "AIDexterWatchSignal_OldJSON", "AIDexterWatchSignal_NewJSON")
    values (v_company_id, v_capability, tg_table_name, v_source_id, v_old, v_new);
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."_multideck_dexter_crm_essential_signal"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_dexter_customs_assessment_watch_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare declaration public."Customs_Declarations"; company_id uuid;
begin
  select * into declaration from public."Customs_Declarations" where "CUST_id"=new.declaration_id;
  if not found or declaration."CUST_IsDeleted" then return new; end if;
  if declaration."CUST_JobID" is not null then
    select office."Company_ID" into company_id from public."Job_Header" job join public."cmp_Offices" office
      on office."Office_ID"=coalesce(job."Job_OrgOfficeID",job."Job_OfficeID") where job."Job_ID"=declaration."CUST_JobID";
  else
    select actor."Company_ID" into company_id from public."cmp_Users" actor where actor."Auth_User_ID"=declaration."CUST_CreatedBy" order by actor."User_ID" limit 1;
  end if;
  if company_id is null then return new; end if;
  perform public._multideck_dexter_pause_unauthorised_customs_watches(company_id,new.declaration_id);
  if not exists(select 1 from public."AI_DexterWatches" w where w."AIDexterWatch_CompanyID"=company_id and w."AIDexterWatch_CapabilityCode"='customs_declarations' and w."AIDexterWatch_TargetID"=new.declaration_id and w."AIDexterWatch_StatusCode"='active') then return new; end if;
  insert into public."AI_DexterWatchSignals"("AIDexterWatchSignal_CompanyID","AIDexterWatchSignal_CapabilityCode","AIDexterWatchSignal_SourceTable","AIDexterWatchSignal_SourceID","AIDexterWatchSignal_OldJSON","AIDexterWatchSignal_NewJSON")
    values(company_id,'customs_declarations','Customs_AssessmentComparisons',new.declaration_id,'{}',jsonb_build_object('assessmentEvent',new.id,'sourceType',case when declaration."CUST_JobID" is null then 'standalone' else 'job_related' end,'direction','import','updatedAt',new.created_at));
  return new;
end;
$$;


ALTER FUNCTION "public"."_multideck_dexter_customs_assessment_watch_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_dexter_customs_calculation_watch_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare declaration public."Customs_Declarations"; company_id uuid; previous_id uuid;
begin
  select * into declaration from public."Customs_Declarations" where "CUST_id" = new.declaration_id;
  if not found or declaration."CUST_IsDeleted" then return new; end if;
  if declaration."CUST_JobID" is not null then
    select office."Company_ID" into company_id from public."Job_Header" job
      join public."cmp_Offices" office on office."Office_ID" = coalesce(job."Job_OrgOfficeID", job."Job_OfficeID")
      where job."Job_ID" = declaration."CUST_JobID";
  else
    select actor."Company_ID" into company_id from public."cmp_Users" actor
      where actor."Auth_User_ID" = declaration."CUST_CreatedBy" order by actor."User_ID" limit 1;
  end if;
  if company_id is null then return new; end if;
  perform public._multideck_dexter_pause_unauthorised_customs_watches(company_id, new.declaration_id);
  if not exists(select 1 from public."AI_DexterWatches" watch
    where watch."AIDexterWatch_CompanyID" = company_id
      and watch."AIDexterWatch_CapabilityCode" = 'customs_declarations'
      and watch."AIDexterWatch_TargetID" = new.declaration_id
      and watch."AIDexterWatch_StatusCode" = 'active') then return new; end if;
  select id into previous_id from public."Customs_CalculationAudit"
    where declaration_id = new.declaration_id and id <> new.id
    order by created_at desc, id desc limit 1;
  insert into public."AI_DexterWatchSignals" (
    "AIDexterWatchSignal_CompanyID", "AIDexterWatchSignal_CapabilityCode",
    "AIDexterWatchSignal_SourceTable", "AIDexterWatchSignal_SourceID",
    "AIDexterWatchSignal_OldJSON", "AIDexterWatchSignal_NewJSON"
  ) values (company_id, 'customs_declarations', 'Customs_CalculationAudit', new.declaration_id,
    jsonb_build_object('calculationEvent', previous_id),
    jsonb_build_object('calculationEvent', new.id, 'calculationKind', new.kind,
      'sourceType', case when declaration."CUST_JobID" is null then 'standalone' else 'job_related' end,
      'direction', 'import', 'reference', new.declaration_id, 'updatedAt', new.created_at));
  return new;
end;
$$;


ALTER FUNCTION "public"."_multideck_dexter_customs_calculation_watch_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_dexter_customs_declaration_watch_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_company_id uuid;
  v_old jsonb := '{}'::jsonb;
  v_new jsonb;
begin
  select actor."Company_ID" into v_company_id
  from public."cmp_Users" actor
  where actor."Auth_User_ID" = new."CUST_CreatedBy"
  order by actor."User_ID"
  limit 1;
  if v_company_id is null then return new; end if;

  if tg_op <> 'INSERT' then
    v_old := jsonb_build_object(
      'assignedUserId', old."CUST_AssignedUserID",
      'status', old."CUST_Status",
      'iCustomsStatus', old."CUST_iCustomsStatusSnapshot",
      'customsReference', old."CUST_CustomsReferenceNumber",
      'mrn', old."CUST_MasterReferenceNumber",
      'documentAvailable', old."CUST_DeclarationDocumentID" is not null,
      'documentReceivedAt', old."CUST_DeclarationDocumentReceivedAt",
      'destinationCountry', old."CUST_CountryOfDestinationCodeSnapshot",
      'invoiceAmount', old."CUST_InvoiceAmount",
      'currency', old."CUST_InvoiceCurrencyCodeSnapshot",
      'updatedAt', old."CUST_UpdatedAt"
    );
  end if;
  v_new := jsonb_build_object(
    'reference', coalesce(new."CUST_LocalReferenceNumber", new."CUST_id"::text),
    'sourceType', case when new."CUST_JobID" is null then 'standalone' else 'job_related' end,
    'jobId', new."CUST_JobID",
    'assignedUserId', new."CUST_AssignedUserID",
    'status', new."CUST_Status",
    'iCustomsStatus', new."CUST_iCustomsStatusSnapshot",
    'customsReference', new."CUST_CustomsReferenceNumber",
    'mrn', new."CUST_MasterReferenceNumber",
    'documentAvailable', new."CUST_DeclarationDocumentID" is not null,
    'documentReceivedAt', new."CUST_DeclarationDocumentReceivedAt",
    'destinationCountry', new."CUST_CountryOfDestinationCodeSnapshot",
    'invoiceAmount', new."CUST_InvoiceAmount",
    'currency', new."CUST_InvoiceCurrencyCodeSnapshot",
    'updatedAt', new."CUST_UpdatedAt"
  );

  if exists (
    select 1 from public."AI_DexterWatches" watch
    where watch."AIDexterWatch_CompanyID" = v_company_id
      and watch."AIDexterWatch_CapabilityCode" = 'customs_declarations'
      and watch."AIDexterWatch_StatusCode" = 'active'
      and watch."AIDexterWatch_TargetID" = new."CUST_id"
  ) then
    insert into public."AI_DexterWatchSignals" (
      "AIDexterWatchSignal_CompanyID", "AIDexterWatchSignal_CapabilityCode",
      "AIDexterWatchSignal_SourceTable", "AIDexterWatchSignal_SourceID",
      "AIDexterWatchSignal_OldJSON", "AIDexterWatchSignal_NewJSON"
    ) values (
      v_company_id, 'customs_declarations', tg_table_name, new."CUST_id", v_old, v_new
    );
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."_multideck_dexter_customs_declaration_watch_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_dexter_customs_draft_payload"("p_draft" "jsonb", "p_direction" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_direction text := lower(btrim(coalesce(p_direction, '')));
  v_draft jsonb := coalesce(p_draft, '{}'::jsonb);
begin
  if v_direction not in ('import', 'export') then
    raise exception 'Choose whether this is an import or export Customs declaration.' using errcode = '22023';
  end if;
  if jsonb_typeof(v_draft) <> 'object' then
    raise exception 'A valid Customs declaration field-value object is required.' using errcode = '22023';
  end if;
  if v_draft ? 'items' and jsonb_typeof(v_draft -> 'items') <> 'array' then
    raise exception 'Customs declaration goods items must be an array.' using errcode = '22023';
  end if;
  if jsonb_array_length(coalesce(v_draft -> 'items', '[]'::jsonb)) > 250 then
    raise exception 'A Dexter Customs declaration can contain up to 250 goods items.' using errcode = '22023';
  end if;
  v_draft := v_draft - array['direction', 'multideckReference', 'iCustomsCorrelationId'];
  return v_draft || jsonb_build_object('direction', v_direction);
end;
$$;


ALTER FUNCTION "public"."_multideck_dexter_customs_draft_payload"("p_draft" "jsonb", "p_direction" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_dexter_customs_submission_watch_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_declaration public."Customs_Declarations"; v_company_id uuid; v_old jsonb:='{}'::jsonb; v_new jsonb;
begin
  if new."ICUSS_CustomsID" is null then return new; end if;
  select declaration.* into v_declaration from public."Customs_Declarations" declaration where declaration."CUST_id"=new."ICUSS_CustomsID" and not declaration."CUST_IsDeleted";
  if not found then return new; end if;
  if v_declaration."CUST_JobID" is not null then
    select office."Company_ID" into v_company_id from public."Job_Header" job join public."cmp_Offices" office
      on office."Office_ID"=coalesce(job."Job_OrgOfficeID",job."Job_OfficeID") where job."Job_ID"=v_declaration."CUST_JobID";
  else
    select actor."Company_ID" into v_company_id from public."cmp_Users" actor where actor."Auth_User_ID"=v_declaration."CUST_CreatedBy" order by actor."User_ID" limit 1;
  end if;
  if v_company_id is null then return new; end if;
  perform public._multideck_dexter_pause_unauthorised_customs_watches(v_company_id, v_declaration."CUST_id");
  if tg_op<>'INSERT' then v_old:=jsonb_build_object(
    'status',v_declaration."CUST_Status",'iCustomsStatus',v_declaration."CUST_iCustomsStatusSnapshot",'submissionStatus',old."ICUSS_Status",
    'customsReference',v_declaration."CUST_CustomsReferenceNumber",'mrn',coalesce(old."ICUSS_MRN",v_declaration."CUST_MasterReferenceNumber"),
    'lrn',old."ICUSS_LRN",'errorCode',old."ICUSS_ErrorCode",'submittedAt',old."ICUSS_SubmittedAt",'acknowledgedAt',old."ICUSS_AcknowledgedAt",'completedAt',old."ICUSS_CompletedAt"); end if;
  v_new:=jsonb_build_object(
    'reference',coalesce(v_declaration."CUST_LocalReferenceNumber",v_declaration."CUST_id"::text),
    'sourceType',case when v_declaration."CUST_JobID" is null then 'standalone' else 'job_related' end,
    'jobId',v_declaration."CUST_JobID",'status',v_declaration."CUST_Status",'iCustomsStatus',v_declaration."CUST_iCustomsStatusSnapshot",
    'submissionStatus',new."ICUSS_Status",'customsReference',v_declaration."CUST_CustomsReferenceNumber",
    'mrn',coalesce(new."ICUSS_MRN",v_declaration."CUST_MasterReferenceNumber"),'lrn',new."ICUSS_LRN",'errorCode',new."ICUSS_ErrorCode",
    'submittedAt',new."ICUSS_SubmittedAt",'acknowledgedAt',new."ICUSS_AcknowledgedAt",'completedAt',new."ICUSS_CompletedAt");
  if exists(select 1 from public."AI_DexterWatches" watch where watch."AIDexterWatch_CompanyID"=v_company_id
    and watch."AIDexterWatch_CapabilityCode"='customs_declarations' and watch."AIDexterWatch_StatusCode"='active' and watch."AIDexterWatch_TargetID"=v_declaration."CUST_id") then
    insert into public."AI_DexterWatchSignals"("AIDexterWatchSignal_CompanyID","AIDexterWatchSignal_CapabilityCode","AIDexterWatchSignal_SourceTable","AIDexterWatchSignal_SourceID","AIDexterWatchSignal_OldJSON","AIDexterWatchSignal_NewJSON")
    values(v_company_id,'customs_declarations',tg_table_name,v_declaration."CUST_id",v_old,v_new);
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."_multideck_dexter_customs_submission_watch_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_dexter_dangerous_goods_watch_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare company uuid;reference text;job_id uuid;line_number integer;before_value jsonb;after_value jsonb;
begin
  if new."JobCargoDG_Source"<>'operator' then return new;end if;
  select o."Company_ID",j."Job_BookingReference",j."Job_ID",c."JobCargo_LineNo" into company,reference,job_id,line_number
    from public."Job_Cargo" c join public."Job_Header" j on j."Job_ID"=c."JobCargo_JobID" and not j."Job_IsDeleted"
    join public."cmp_Offices" o on o."Office_ID"=coalesce(j."Job_OrgOfficeID",j."Job_OfficeID")
    where c."JobCargo_ID"=new."JobCargoDG_JobCargoID" and not c."JobCargo_IsDeleted";
  if company is null or not exists(select 1 from public."AI_DexterWatches" w where w."AIDexterWatch_CompanyID"=company
    and w."AIDexterWatch_CapabilityCode"='booking_dangerous_goods' and w."AIDexterWatch_TargetID"=new."JobCargoDG_ID"
    and w."AIDexterWatch_StatusCode"='active') then return new;end if;
  before_value:=case when tg_op='INSERT' then '{}'::jsonb else booking_api.cargo_dangerous_goods_values(old) end;
  after_value:=booking_api.cargo_dangerous_goods_values(new);
  if before_value=after_value then return new;end if;
  insert into public."AI_DexterWatchSignals"("AIDexterWatchSignal_CompanyID","AIDexterWatchSignal_CapabilityCode","AIDexterWatchSignal_SourceTable",
    "AIDexterWatchSignal_SourceID","AIDexterWatchSignal_OldJSON","AIDexterWatchSignal_NewJSON")
    values(company,'booking_dangerous_goods','Job_CargoDangerousGoods',new."JobCargoDG_ID",before_value,
      after_value||jsonb_build_object('bookingId',job_id,'bookingReference',reference,'lineNumber',line_number,'sourceUrl','/bookings/'||lower(reference)));
  return new;
end $$;


ALTER FUNCTION "public"."_multideck_dexter_dangerous_goods_watch_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_dexter_deal_stage_signal"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare company uuid;before_value jsonb:='{}';after_value jsonb;
begin
  select "Company_ID" into company from public."CRM_Pipelines" where "CRMPipeline_ID"=new."CRMOppty_PipelineID" and not "Is_Deleted";
  if company is null or not public._multideck_crm_deal_is_operator_visible(new."CRMOppty_ID",company) then return new;end if;
  if tg_op<>'INSERT' then before_value:=public._multideck_dexter_deal_watch_snapshot(old);end if;
  after_value:=public._multideck_dexter_deal_watch_snapshot(new);
  if before_value is distinct from after_value and exists(select 1 from public."AI_DexterWatches" w
    where w."AIDexterWatch_CompanyID"=company and w."AIDexterWatch_CapabilityCode"='deals'
      and w."AIDexterWatch_StatusCode"='active' and (w."AIDexterWatch_TargetID" is null or w."AIDexterWatch_TargetID"=new."CRMOppty_ID")) then
    insert into public."AI_DexterWatchSignals" ("AIDexterWatchSignal_CompanyID","AIDexterWatchSignal_CapabilityCode","AIDexterWatchSignal_SourceTable","AIDexterWatchSignal_SourceID","AIDexterWatchSignal_OldJSON","AIDexterWatchSignal_NewJSON")
    values(company,'deals',tg_table_name,new."CRMOppty_ID",before_value,after_value);
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."_multideck_dexter_deal_stage_signal"() OWNER TO "postgres";


