CREATE OR REPLACE FUNCTION "public"."_multideck_dexter_deny_prepared_action"("p_prepared_action_id" "uuid", "p_company_id" "uuid", "p_user_id" "uuid", "p_code" "text", "p_message" "text", "p_event_kind" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_prepared public."AI_DexterPreparedActions";
begin
  select * into v_prepared from public."AI_DexterPreparedActions" p
  where p."AIDexterPrepared_ID"=p_prepared_action_id
    and p."AIDexterPrepared_CompanyID"=p_company_id and p."AIDexterPrepared_UserID"=p_user_id;
  insert into public."AI_DexterSecurityEvents"(
    "AIDexterSecurityEvent_CompanyID","AIDexterSecurityEvent_UserID","AIDexterSecurityEvent_Kind",
    "AIDexterSecurityEvent_Severity","AIDexterSecurityEvent_MetadataJSON"
  ) values(p_company_id,p_user_id,left(coalesce(p_event_kind,'prepared_action_denied'),80),
    case when p_event_kind in ('target_substitution_denied','recipient_substitution_denied','cross_scope_action_denied') then 'high' else 'warning' end,
    jsonb_build_object('preparedActionId',p_prepared_action_id,'actionCode',v_prepared."AIDexterPrepared_ActionCode",'code',left(coalesce(p_code,'denied'),100)));
  if v_prepared."AIDexterPrepared_ID" is not null then
    insert into public."AI_DexterActionAudit"(
      "AIDexterAudit_CompanyID","AIDexterAudit_UserID","AIDexterAudit_ActionCode","AIDexterAudit_AccessMode",
      "AIDexterAudit_ArgumentsJSON","AIDexterAudit_ResultJSON","AIDexterAudit_PreparedActionID","AIDexterAudit_IntentID",
      "AIDexterAudit_ConversationID","AIDexterAudit_Status","AIDexterAudit_IdempotencyKey","AIDexterAudit_ErrorCode",
      "AIDexterAudit_ErrorMessage","AIDexterAudit_AttemptedAt","AIDexterAudit_CompletedAt"
    ) values(p_company_id,p_user_id,v_prepared."AIDexterPrepared_ActionCode",v_prepared."AIDexterPrepared_AccessMode",
      '{}'::jsonb,'{}'::jsonb,p_prepared_action_id,v_prepared."AIDexterPrepared_IntentID",v_prepared."AIDexterPrepared_ConversationID",
      'denied',v_prepared."AIDexterPrepared_IdempotencyKey",left(coalesce(p_code,'denied'),100),left(coalesce(p_message,'Action denied.'),500),now(),now());
  end if;
  return jsonb_build_object('ok',false,'error',jsonb_build_object('code',left(coalesce(p_code,'denied'),100),'message',left(coalesce(p_message,'Action denied.'),500)));
end $$;


ALTER FUNCTION "public"."_multideck_dexter_deny_prepared_action"("p_prepared_action_id" "uuid", "p_company_id" "uuid", "p_user_id" "uuid", "p_code" "text", "p_message" "text", "p_event_kind" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_dexter_domain_contacts_unscoped_20260818"("p_company_id" "uuid", "p_search" "text", "p_take" integer) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
  select coalesce(jsonb_agg(row_data order by search_rank desc, contact_name), '[]'::jsonb)
  from (
    select jsonb_build_object(
      'recordId', contact."OrgContact_ID",
      'recordType', 'contact',
      'name', nullif(btrim(concat_ws(' ', contact."OrgContact_FirstName", contact."OrgContact_LastName")), ''),
      'accountId', account."Org_id",
      'accountName', account."Org_Name",
      'email', email."OrgContactEmail_Email",
      'role', profile."CRMContact_RoleCode",
      'influenceLevel', profile."CRMContact_InfluenceLevel",
      'relationshipStrength', profile."CRMContact_RelationshipStrength",
      'preferredChannel', profile."CRMContact_PreferredChannelCode",
      'preferredLanguage', profile."CRMContact_PreferredLanguageCode",
      'salesContactAllowed', coalesce(profile."CRMContact_ConsentSalesContact", false),
      'lastContactAt', profile."CRMContact_LastContactAt",
      'notes', profile."CRMContact_Notes",
      'jobTitle', profile."CRMContact_MetadataJSON"->>'jobTitle',
      'department', profile."CRMContact_MetadataJSON"->>'department',
      'searchEvidence', evidence.value - 'matched'
    ) row_data,
    coalesce((evidence.value->>'confidence')::numeric, 0) search_rank,
    nullif(btrim(concat_ws(' ', contact."OrgContact_FirstName", contact."OrgContact_LastName")), '') contact_name
    from public."Org_Contacts" contact
    join public."Org_Master" account on account."Org_id" = contact."Org_ID"
    left join public."CRM_ContactProfiles" profile on profile."CRMContact_OrgContactID" = contact."OrgContact_ID"
    left join lateral (
      select contact_email."OrgContactEmail_Email"
      from public."OrgContact_Emails" contact_email
      where contact_email."OrgContact_ID" = contact."OrgContact_ID"
      order by contact_email."OrgContactEmail_Type", contact_email."OrgContactEmail_ID"
      limit 1
    ) email on true
    cross join lateral public._multideck_dexter_search_evidence(
      p_search,
      jsonb_build_object(
        'name', nullif(btrim(concat_ws(' ', contact."OrgContact_FirstName", contact."OrgContact_LastName")), ''),
        'accountName', account."Org_Name",
        'email', email."OrgContactEmail_Email",
        'role', profile."CRMContact_RoleCode",
        'jobTitle', profile."CRMContact_MetadataJSON"->>'jobTitle',
        'department', profile."CRMContact_MetadataJSON"->>'department'
      ),
      array['email']::text[]
    ) evidence(value)
    where public._multideck_dexter_has_permission(
      (select app_user."User_ID" from public."cmp_Users" app_user where app_user."Auth_User_ID" = auth.uid() and app_user."Company_ID" = p_company_id limit 1),
      'Customers.Read'
    )
      and (evidence.value->>'matched')::boolean
    order by search_rank desc, contact_name
    limit greatest(1, least(coalesce(p_take, 10), 25))
  ) contacts;
$$;


ALTER FUNCTION "public"."_multideck_dexter_domain_contacts_unscoped_20260818"("p_company_id" "uuid", "p_search" "text", "p_take" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_dexter_domain_customers_unscoped_20260818"("p_company_id" "uuid", "p_search" "text", "p_take" integer) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
  select coalesce(jsonb_agg(row_data order by search_rank desc, customer_name), '[]'::jsonb)
  from (
    select jsonb_build_object(
      'recordId', customer."Org_id",
      'recordType', 'account',
      'name', customer."Org_Name",
      'relationshipStatus', coalesce(profile."CRMAccount_RelationshipStatusCode", customer."Org_CRMRelationshipStatusCode"),
      'tier', profile."CRMAccount_Tier",
      'segment', profile."CRMAccount_Segment",
      'vertical', profile."CRMAccount_Vertical",
      'primaryMode', profile."CRMAccount_PrimaryModeCode",
      'primaryTradeLane', profile."CRMAccount_PrimaryTradeLane",
      'healthScore', profile."CRMAccount_HealthScore",
      'churnRiskScore', profile."CRMAccount_ChurnRiskScore",
      'lastContactAt', profile."CRMAccount_LastContactAt",
      'nextActionDueAt', profile."CRMAccount_NextActionDueAt",
      'strategic', coalesce(profile."CRMAccount_IsStrategic", false),
      'owner', nullif(btrim(concat_ws(' ', owner."User_Firstname", owner."User_Lastname")), ''),
      'contactCount', (select count(*) from public."Org_Contacts" contact where contact."Org_ID" = customer."Org_id"),
      'location', address.location,
      'summary', profile."CRMAccount_CustomerCentricSummary",
      'searchEvidence', evidence.value - 'matched'
    ) row_data,
    coalesce((evidence.value->>'confidence')::numeric, 0) search_rank,
    customer."Org_Name" customer_name
    from public."Org_Master" customer
    left join public."CRM_AccountProfiles" profile
      on profile."CRMAccount_OrgID" = customer."Org_id" and not profile."CRMAccount_IsDeleted"
    left join public."cmp_Users" owner on owner."User_ID" = profile."CRMAccount_OwnerUserID"
    left join lateral (
      select nullif(concat_ws(', ', nullif(btrim(location_row."OrgAdd_TownCity"), ''), nullif(upper(btrim(location_row."OrgAdd_Country")), '')), '') location
      from public."Org_Addresses" location_row
      where location_row."Org_ID" = customer."Org_id"
      order by location_row."OrgAdd_ID"
      limit 1
    ) address on true
    cross join lateral public._multideck_dexter_search_evidence(
      p_search,
      jsonb_build_object(
        'name', customer."Org_Name",
        'status', coalesce(profile."CRMAccount_RelationshipStatusCode", customer."Org_CRMRelationshipStatusCode"),
        'tier', profile."CRMAccount_Tier",
        'segment', profile."CRMAccount_Segment",
        'vertical', profile."CRMAccount_Vertical",
        'tradeLane', profile."CRMAccount_PrimaryTradeLane",
        'owner', nullif(btrim(concat_ws(' ', owner."User_Firstname", owner."User_Lastname")), ''),
        'location', address.location
      )
    ) evidence(value)
    where public._multideck_dexter_has_permission(
      (select app_user."User_ID" from public."cmp_Users" app_user where app_user."Auth_User_ID" = auth.uid() and app_user."Company_ID" = p_company_id limit 1),
      'Customers.Read'
    )
      and (
        customer."Org_CRMIsPotentialCustomer"
        or exists (
          select 1 from public."Org_Master_Type" customer_type
          join public."Org_Types" type on type."OrgType_ID" = customer_type."OrgType_ID"
          where customer_type."Org_ID" = customer."Org_id" and lower(type."OrgType_Name") = 'customer'
        )
      )
      and (evidence.value->>'matched')::boolean
    order by search_rank desc, customer."Org_Name"
    limit greatest(1, least(coalesce(p_take, 10), 25))
  ) customers;
$$;


ALTER FUNCTION "public"."_multideck_dexter_domain_customers_unscoped_20260818"("p_company_id" "uuid", "p_search" "text", "p_take" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_dexter_domain_deals_unfiltered_20260818"("p_company_id" "uuid", "p_search" "text", "p_take" integer) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select coalesce(jsonb_agg(row_data order by search_rank desc, sort_close nulls last, sort_created desc), '[]'::jsonb)
  from (
    select jsonb_build_object(
      'recordId', deal."CRMOppty_ID", 'name', deal."CRMOppty_Name", 'pipeline', pipeline."CRMPipeline_Name",
      'stage', stage."CRMPipelineStage_Name", 'status', deal."CRMOppty_StatusCode", 'type', deal."CRMOppty_TypeCode",
      'mode', deal."CRMOppty_ModeCode", 'direction', deal."CRMOppty_DirectionCode", 'tradeLane', deal."CRMOppty_TradeLane",
      'serviceInterest', deal."CRMOppty_ServiceInterest", 'expectedCloseDate', deal."CRMOppty_ExpectedCloseDate",
      'probabilityPct', deal."CRMOppty_ProbabilityPct", 'expectedValue', deal."CRMOppty_ExpectedValueAmount",
      'expectedMargin', deal."CRMOppty_ExpectedMarginAmount", 'weightedValue', deal."CRMOppty_WeightedValueAmount",
      'currency', deal."CRMOppty_CurrencyCode", 'nextActionDueAt', deal."CRMOppty_NextActionDueAt",
      'lastActivityAt', deal."CRMOppty_LastActivityAt", 'searchEvidence', evidence.value - 'matched'
    ) row_data,
    coalesce((evidence.value->>'confidence')::numeric, 0) search_rank,
    deal."CRMOppty_ExpectedCloseDate" sort_close,
    deal."CRMOppty_CreatedAt" sort_created
    from public."CRM_Opportunities" deal
    join public."CRM_Pipelines" pipeline
      on pipeline."CRMPipeline_ID" = deal."CRMOppty_PipelineID"
     and pipeline."Company_ID" = p_company_id
     and not pipeline."Is_Deleted"
    left join public."CRM_PipelineStages" stage
      on stage."CRMPipelineStage_ID" = deal."CRMOppty_PipelineStageID"
     and not stage."Is_Deleted"
    cross join lateral public._multideck_dexter_search_evidence(
      p_search,
      jsonb_build_object(
        'name', deal."CRMOppty_Name", 'pipeline', pipeline."CRMPipeline_Name", 'stage', stage."CRMPipelineStage_Name",
        'status', deal."CRMOppty_StatusCode", 'type', deal."CRMOppty_TypeCode", 'mode', deal."CRMOppty_ModeCode",
        'direction', deal."CRMOppty_DirectionCode", 'tradeLane', deal."CRMOppty_TradeLane",
        'serviceInterest', deal."CRMOppty_ServiceInterest"
      )
    ) evidence(value)
    where not deal."CRMOppty_IsDeleted"
      and (evidence.value->>'matched')::boolean
    order by search_rank desc, deal."CRMOppty_ExpectedCloseDate" nulls last, deal."CRMOppty_CreatedAt" desc
    limit greatest(1, least(coalesce(p_take, 10), 25))
  ) rows;
$$;


