CREATE OR REPLACE FUNCTION "public"."_multideck_dexter_email_mailboxes"("p_user_id" "uuid", "p_company_id" "uuid") RETURNS TABLE("mailbox_id" "uuid", "provider" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  with readable as (
    select access."CommMailboxAccess_MailboxID" as mailbox_id
    from public."Comm_MailboxAccess" access
    where access."CommMailboxAccess_UserID" = p_user_id
      and access."CommMailboxAccess_CanRead"
      and access."CommMailboxAccess_RevokedAt" is null
      and (
        access."CommMailboxAccess_ExpiresAt" is null
        or access."CommMailboxAccess_ExpiresAt" > now()
      )

    union

    select mailbox."CommMailbox_ID"
    from public."Comm_Mailboxes" mailbox
    join public."Comm_ProviderConnections" connection
      on connection."CommConn_ID" = mailbox."CommMailbox_ConnectionID"
     and connection."CommConn_UserID" = p_user_id
     and connection."CommConn_StatusCode" = 'active'
     and connection."CommConn_InboundEnabled"
     and not connection."CommConn_IsDeleted"
    where mailbox."CommMailbox_UserID" = p_user_id
      and mailbox."CommMailbox_TypeCode" = 'personal'
      and mailbox."CommMailbox_InboundEnabled"
      and not mailbox."CommMailbox_IsDeleted"
  )
  select distinct
    mailbox."CommMailbox_ID",
    case connection."CommConn_ProviderTypeCode"
      when 'google_workspace' then 'gmail'
      when 'microsoft_365' then 'outlook'
    end
  from readable
  join public."Comm_Mailboxes" mailbox
    on mailbox."CommMailbox_ID" = readable.mailbox_id
   and mailbox."CommMailbox_InboundEnabled"
   and not mailbox."CommMailbox_IsDeleted"
  join public."Comm_ProviderConnections" connection
    on connection."CommConn_ID" = mailbox."CommMailbox_ConnectionID"
   and connection."CommConn_StatusCode" = 'active'
   and connection."CommConn_InboundEnabled"
   and not connection."CommConn_IsDeleted"
  join public."cmp_Users" connection_owner
    on connection_owner."User_ID" = connection."CommConn_UserID"
   and connection_owner."Company_ID" = p_company_id
  where connection."CommConn_ProviderTypeCode" in ('google_workspace', 'microsoft_365');
$$;


ALTER FUNCTION "public"."_multideck_dexter_email_mailboxes"("p_user_id" "uuid", "p_company_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_dexter_emit_email_watch_signal"("p_message_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_message public."Comm_Messages";
  v_company_id uuid;
  v_sender_email text;
  v_sender_name text;
  v_attachment_names text;
  v_snapshot jsonb;
begin
  select message.* into v_message
  from public."Comm_Messages" message
  where message."CommMessage_ID" = p_message_id
    and message."CommMessage_IsInbound"
    and not message."CommMessage_IsDraft"
    and not message."CommMessage_IsSpam"
    and not message."CommMessage_IsDeleted";
  if not found then return; end if;

  select
    string_agg(distinct recipient."CommRecipient_NormalizedAddress", ' ' order by recipient."CommRecipient_NormalizedAddress"),
    string_agg(distinct recipient."CommRecipient_DisplayNameSnapshot", ' ' order by recipient."CommRecipient_DisplayNameSnapshot")
  into v_sender_email, v_sender_name
  from public."Comm_MessageRecipients" recipient
  where recipient."CommRecipient_MessageID" = p_message_id
    and recipient."CommRecipient_RecipientTypeCode" = 'from';

  select string_agg(distinct attachment."CommAttachment_FileName", ' ' order by attachment."CommAttachment_FileName")
  into v_attachment_names
  from public."Comm_MessageAttachments" attachment
  where attachment."CommAttachment_MessageID" = p_message_id
    and not attachment."CommAttachment_IsInline";

  select owner."Company_ID" into v_company_id
  from public."Comm_Mailboxes" mailbox
  join public."Comm_ProviderConnections" connection
    on connection."CommConn_ID" = mailbox."CommMailbox_ConnectionID"
  join public."cmp_Users" owner
    on owner."User_ID" = connection."CommConn_UserID"
  where mailbox."CommMailbox_ID" = v_message."CommMessage_MailboxID";
  if v_company_id is null then return; end if;

  if not exists (
    select 1 from public."AI_DexterWatches" watch
    where watch."AIDexterWatch_CompanyID" = v_company_id
      and watch."AIDexterWatch_CapabilityCode" = 'email'
      and watch."AIDexterWatch_StatusCode" = 'active'
  ) then return; end if;

  v_snapshot := jsonb_build_object(
    'senderEmail', coalesce(v_sender_email, ''),
    'senderName', coalesce(v_sender_name, ''),
    'subject', coalesce(v_message."CommMessage_Subject", ''),
    'body', left(coalesce(v_message."CommMessage_BodyText", v_message."CommMessage_BodyPreview", ''), 16000),
    'receivedAt', v_message."CommMessage_ReceivedAt",
    'hasAttachments', v_message."CommMessage_HasAttachments",
    'attachmentNames', left(coalesce(v_attachment_names, ''), 4000),
    'mailboxId', v_message."CommMessage_MailboxID",
    'searchText', left(concat_ws(
      ' ',
      v_sender_email,
      v_sender_name,
      v_message."CommMessage_Subject",
      coalesce(v_message."CommMessage_BodyText", v_message."CommMessage_BodyPreview"),
      v_attachment_names
    ), 24000)
  );

  insert into public."AI_DexterWatchSignals" (
    "AIDexterWatchSignal_CompanyID",
    "AIDexterWatchSignal_CapabilityCode",
    "AIDexterWatchSignal_SourceTable",
    "AIDexterWatchSignal_SourceID",
    "AIDexterWatchSignal_OldJSON",
    "AIDexterWatchSignal_NewJSON"
  ) values (
    v_company_id,
    'email',
    'Comm_Messages',
    p_message_id,
    '{}'::jsonb,
    v_snapshot
  );
end; $$;


ALTER FUNCTION "public"."_multideck_dexter_emit_email_watch_signal"("p_message_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_dexter_estimated_usage_gbp"("p_model" "text", "p_input_tokens" integer, "p_output_tokens" integer) RETURNS numeric
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
  select case when lower(p_model)='gpt-6-astra' then public._multideck_dexter_astra_usage_gbp(
    p_input_tokens,p_output_tokens,0,greatest(coalesce(p_input_tokens,0),0))
  else round((greatest(coalesce(p_input_tokens,0),0)::numeric*case when lower(coalesce(p_model,'fast'))='worker' then 2.00 else 0.80 end
    +greatest(coalesce(p_output_tokens,0),0)::numeric*case when lower(coalesce(p_model,'fast'))='worker' then 12.00 else 4.80 end)/1000000,6) end;
$$;


ALTER FUNCTION "public"."_multideck_dexter_estimated_usage_gbp"("p_model" "text", "p_input_tokens" integer, "p_output_tokens" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_dexter_evaluate_watch_signal"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  watch record;
  v_matches boolean;
  v_previously_matched boolean;
  v_field text;
  v_old text;
  v_new text;
  v_event_id uuid;
  v_event_body text;
  v_changed jsonb;
begin
  for watch in
    select watch_row.*
    from public."AI_DexterWatches" watch_row
    where watch_row."AIDexterWatch_CompanyID" = new."AIDexterWatchSignal_CompanyID"
      and watch_row."AIDexterWatch_CapabilityCode" = new."AIDexterWatchSignal_CapabilityCode"
      and watch_row."AIDexterWatch_StatusCode" = 'active'
    and (new."AIDexterWatchSignal_SourceTable" not in ('Customs_CalculationAudit','Customs_AssessmentComparisons') or (
      watch_row."AIDexterWatch_TargetID" = new."AIDexterWatchSignal_SourceID"
      and exists (select 1 from public."cmp_Users" actor
        where actor."User_ID" = watch_row."AIDexterWatch_OwnerUserID"
          and actor."Company_ID" = watch_row."AIDexterWatch_CompanyID"
          and actor."User_AccessStatus" = 'active'
          and booking_api.customs_access(actor."Auth_User_ID", new."AIDexterWatchSignal_SourceID", false))
    ))
      and (watch_row."AIDexterWatch_CapabilityCode" <> 'email_signatures' or ((watch_row."AIDexterWatch_RuleJSON"->>'field'<>'assignments' or public._multideck_dexter_has_permission(watch_row."AIDexterWatch_OwnerUserID",'Email.Signatures.Manage')) and public.email_signature_available(watch_row."AIDexterWatch_OwnerUserID",watch_row."AIDexterWatch_CompanyID",new."AIDexterWatchSignal_SourceID")))
      and (new."AIDexterWatchSignal_SourceTable" not in ('Org_Addresses','Org_Master','CRM_AccountProfiles','CRM_AccountOfficeAssignments','Org_RelatedPartyDefaults','CRM_ContactOrganisationAssignments','OrgContact_Emails') or (
        exists(select 1 from public.multideck_crm_accessible_account_ids(watch_row."AIDexterWatch_CompanyID") a
          where a.account_id=new."AIDexterWatchSignal_SourceID")
        and exists(select 1 from public."cmp_Users" u where u."User_ID"=watch_row."AIDexterWatch_OwnerUserID"
          and u."Company_ID"=watch_row."AIDexterWatch_CompanyID" and u."User_AccessStatus"='active'
          and public._multideck_crm_has_permission(u."User_ID",'CRM.Read'))
      ))
      and (watch_row."AIDexterWatch_CapabilityCode" <> 'deals' or (
        public._multideck_crm_deal_is_operator_visible(
          new."AIDexterWatchSignal_SourceID", watch_row."AIDexterWatch_CompanyID")
        and exists (
          select 1 from public."cmp_Users" owner_user
          where owner_user."User_ID" = watch_row."AIDexterWatch_OwnerUserID"
            and owner_user."Company_ID" = watch_row."AIDexterWatch_CompanyID"
            and owner_user."User_AccessStatus" = 'active'
            and public._multideck_crm_has_permission(owner_user."User_ID", 'CRM.Read')
        )
      ))
      and (watch_row."AIDexterWatch_CapabilityCode"<>'reports' or (
        report_api.watch_allowed(watch_row."AIDexterWatch_OwnerUserID",watch_row."AIDexterWatch_CompanyID",watch_row."AIDexterWatch_TargetID")
        and new."AIDexterWatchSignal_NewJSON"->>'ownerId'=watch_row."AIDexterWatch_OwnerUserID"::text
        and new."AIDexterWatchSignal_NewJSON" ? (watch_row."AIDexterWatch_RuleJSON"->>'field')))
    and (watch_row."AIDexterWatch_CapabilityCode"<>'quote_cargo' or exists(select 1 from public."cmp_Users" owner_user
      where owner_user."User_ID"=watch_row."AIDexterWatch_OwnerUserID" and owner_user."Company_ID"=watch_row."AIDexterWatch_CompanyID"
      and owner_user."User_AccessStatus"='active' and quote_api.has_permission(owner_user."Auth_User_ID",'Quotes.Read')))
      and (watch_row."AIDexterWatch_CapabilityCode" not in ('booking_security_evidence','booking_dangerous_goods','booking_milestones','booking_allocations','booking_cargo','booking_containers','booking_routes','booking_shipment_value') or exists (
        select 1 from public."cmp_Users" owner_user
        where owner_user."User_ID" = watch_row."AIDexterWatch_OwnerUserID"
          and owner_user."Company_ID" = watch_row."AIDexterWatch_CompanyID"
          and owner_user."User_AccessStatus" = 'active'
          and booking_api.has_permission(owner_user."Auth_User_ID", 'Bookings.Read')
      ))
      and (
        watch_row."AIDexterWatch_TargetID" is null
        or watch_row."AIDexterWatch_TargetID" = new."AIDexterWatchSignal_SourceID"
      )
      and (
        watch_row."AIDexterWatch_CapabilityCode" <> 'email'
        or exists (
          select 1
          from public._multideck_dexter_email_mailboxes(
            watch_row."AIDexterWatch_OwnerUserID",
            watch_row."AIDexterWatch_CompanyID"
          ) permitted
          where permitted.mailbox_id = nullif(
            new."AIDexterWatchSignal_NewJSON"->>'mailboxId',
            ''
          )::uuid
        )
      )
  loop
    begin
      v_matches := public._multideck_dexter_watch_matches(
        watch."AIDexterWatch_RuleJSON",
        new."AIDexterWatchSignal_OldJSON",
        new."AIDexterWatchSignal_NewJSON"
      );

      select state."AIDexterWatchState_LastMatched"
      into v_previously_matched
      from public."AI_DexterWatchStates" state
      where state."AIDexterWatchState_WatchID" = watch."AIDexterWatch_ID"
        and state."AIDexterWatchState_SourceID" = new."AIDexterWatchSignal_SourceID";

      insert into public."AI_DexterWatchStates" (
        "AIDexterWatchState_WatchID",
        "AIDexterWatchState_SourceID",
        "AIDexterWatchState_LastMatched",
        "AIDexterWatchState_LastEvaluatedAt"
      )
      values (
        watch."AIDexterWatch_ID",
        new."AIDexterWatchSignal_SourceID",
        v_matches,
        now()
      )
      on conflict ("AIDexterWatchState_WatchID", "AIDexterWatchState_SourceID")
      do update set
        "AIDexterWatchState_LastMatched" = excluded."AIDexterWatchState_LastMatched",
        "AIDexterWatchState_LastEvaluatedAt" = excluded."AIDexterWatchState_LastEvaluatedAt";

      v_field := watch."AIDexterWatch_RuleJSON"->>'field';
      v_old := new."AIDexterWatchSignal_OldJSON"->>v_field;
      v_new := new."AIDexterWatchSignal_NewJSON"->>v_field;

      update public."AI_DexterWatches"
      set "AIDexterWatch_LastEvaluatedAt" = now(),
          "AIDexterWatch_IsArmed" = case
            when v_matches then "AIDexterWatch_IsArmed"
            else true
          end,
          "AIDexterWatch_UpdatedAt" = now()
      where "AIDexterWatch_ID" = watch."AIDexterWatch_ID";

      if v_matches and (
    (watch."AIDexterWatch_CapabilityCode" = 'customs_declarations'
      and watch."AIDexterWatch_RuleJSON"->>'field' in ('calculationEvent','assessmentEvent')
      and watch."AIDexterWatch_RuleJSON"->>'operator' = 'changed') or
        (watch."AIDexterWatch_CapabilityCode"='email_signatures' and watch."AIDexterWatch_RuleJSON"->>'operator'='changed') or
        (new."AIDexterWatchSignal_SourceTable" in ('Org_Addresses','Org_Master','CRM_AccountProfiles','CRM_AccountOfficeAssignments','Org_RelatedPartyDefaults','CRM_ContactOrganisationAssignments','OrgContact_Emails')
          and watch."AIDexterWatch_RuleJSON"->>'operator'='changed') or
        (watch."AIDexterWatch_CapabilityCode" = 'deals'
          and watch."AIDexterWatch_RuleJSON"->>'operator' = 'changed') or watch."AIDexterWatch_CapabilityCode"='reports' or (watch."AIDexterWatch_CapabilityCode" in ('booking_security_evidence','booking_dangerous_goods','booking_milestones','booking_allocations','quote_cargo','booking_cargo','booking_containers','booking_routes','booking_shipment_value') and watch."AIDexterWatch_RuleJSON"->>'operator' = 'changed') or not coalesce(v_previously_matched, false)) then


    if watch."AIDexterWatch_CapabilityCode"='customs_declarations' and v_field='assessmentEvent' then
      v_event_body:=coalesce(watch."AIDexterWatch_TargetLabel",'Your declaration') || ': an assessment comparison was recorded. Review the result and any differences.';
      v_changed:=jsonb_build_object('field',v_field,'sourceId',new."AIDexterWatchSignal_SourceID",'assessmentId',v_new);
    elsif watch."AIDexterWatch_CapabilityCode" = 'customs_declarations'
      and v_field = 'calculationEvent' then
      v_event_body := coalesce(watch."AIDexterWatch_TargetLabel", 'Your declaration') || ': ' ||
        case when new."AIDexterWatchSignal_NewJSON"->>'calculationKind' = 'override'
          then 'a duty or VAT estimate override was recorded.'
          else 'a new duty and VAT calculation was recorded.' end;
      v_changed := jsonb_build_object('field', v_field,
        'sourceId', new."AIDexterWatchSignal_SourceID", 'calculationId', v_new);
    elsif watch."AIDexterWatch_CapabilityCode" = 'email' then
          v_event_body := concat(
            'New matching email from ',
            coalesce(
              nullif(new."AIDexterWatchSignal_NewJSON"->>'senderName', ''),
              nullif(new."AIDexterWatchSignal_NewJSON"->>'senderEmail', ''),
              'an unknown sender'
            ),
            ': ',
            coalesce(nullif(new."AIDexterWatchSignal_NewJSON"->>'subject', ''), '(No subject)'),
            '.'
          );
          v_changed := jsonb_build_object(
            'field', v_field,
            'sourceId', new."AIDexterWatchSignal_SourceID",
            'mailboxId', new."AIDexterWatchSignal_NewJSON"->>'mailboxId',
            'senderEmail', new."AIDexterWatchSignal_NewJSON"->>'senderEmail',
            'senderName', new."AIDexterWatchSignal_NewJSON"->>'senderName',
            'subject', new."AIDexterWatchSignal_NewJSON"->>'subject',
            'receivedAt', new."AIDexterWatchSignal_NewJSON"->>'receivedAt',
            'attachmentNames', new."AIDexterWatchSignal_NewJSON"->>'attachmentNames'
          );
        else
          v_event_body := coalesce(watch."AIDexterWatch_TargetLabel", 'A watched record')
            || ': ' || case v_field when 'accountCode' then 'Company code' when 'scopeCode' then 'Scope' else v_field end || ' changed from ' || coalesce(v_old, 'not set')
            || ' to ' || coalesce(v_new, 'not set') || '.';
          v_changed := jsonb_build_object(
            'field', v_field,
            'before', v_old,
            'after', v_new,
            'sourceId', new."AIDexterWatchSignal_SourceID"
          );
        end if;


    if watch."AIDexterWatch_CapabilityCode"='booking_allocations' then
      v_event_body:=coalesce(new."AIDexterWatchSignal_NewJSON"->>'bookingReference',watch."AIDexterWatch_TargetLabel",'Booking')
        ||': cargo allocation plan changed ('||jsonb_array_length(new."AIDexterWatchSignal_OldJSON"->'allocations')
        ||' allocations before, '||jsonb_array_length(new."AIDexterWatchSignal_NewJSON"->'allocations')||' now). Review the Booking for details.';
      v_changed:=v_changed||jsonb_build_object('sourceUrl',new."AIDexterWatchSignal_NewJSON"->>'sourceUrl');
    end if;

    if watch."AIDexterWatch_CapabilityCode"='booking_milestones' then
      v_event_body:=coalesce(new."AIDexterWatchSignal_NewJSON"->>'bookingReference','Booking')||' · Leg '
        ||coalesce(new."AIDexterWatchSignal_NewJSON"->>'legNumber','?')||' · '
        ||coalesce(new."AIDexterWatchSignal_NewJSON"->>'name','Milestone')||': '
        ||case watch."AIDexterWatch_RuleJSON"->>'field' when 'plannedAt' then 'planned time' when 'estimatedAt' then 'estimated time'
          when 'actualAt' then 'actual time' when 'locationUnlocode' then 'location code' when 'externalReference' then 'external reference'
          when 'status' then 'status' when 'location' then 'location' else 'notes' end||' changed. Review the saved milestone for details.';
      v_changed:=v_changed||jsonb_build_object('sourceUrl',new."AIDexterWatchSignal_NewJSON"->>'sourceUrl');
    end if;

    if watch."AIDexterWatch_CapabilityCode"='booking_dangerous_goods' then
      v_event_body:=coalesce(new."AIDexterWatchSignal_NewJSON"->>'bookingReference','Booking')||' · Cargo '
        ||coalesce(new."AIDexterWatchSignal_NewJSON"->>'lineNumber','?')||': dangerous-goods evidence changed. Review the saved source; this is not a compliance approval.';
      v_changed:=v_changed||jsonb_build_object('sourceUrl',new."AIDexterWatchSignal_NewJSON"->>'sourceUrl');
    end if;

    if watch."AIDexterWatch_CapabilityCode"='booking_security_evidence' then
      v_event_body:=coalesce(new."AIDexterWatchSignal_NewJSON"->>'bookingReference','Booking')||' · Cargo '
        ||coalesce(new."AIDexterWatchSignal_NewJSON"->>'lineNumber','?')||': screening evidence changed. Review the saved source; this is not clearance or agent verification.';
      v_changed:=v_changed||jsonb_build_object('sourceUrl',new."AIDexterWatchSignal_NewJSON"->>'sourceUrl');
    end if;
            if new."AIDexterWatchSignal_SourceTable" = 'Org_Addresses' and v_field = 'addresses' then
          v_event_body := coalesce(watch."AIDexterWatch_TargetLabel", 'A watched company') || ': address details changed.';
        end if;

 if new."AIDexterWatchSignal_SourceTable"='CRM_AccountOfficeAssignments' and v_field='responsibleOffices' then
  v_event_body:=coalesce(watch."AIDexterWatch_TargetLabel",'A watched company')||': Responsible offices updated.';
 end if;

 if new."AIDexterWatchSignal_SourceTable"='Org_RelatedPartyDefaults' and v_field='relatedPartyDefaults' then
  v_event_body:=coalesce(watch."AIDexterWatch_TargetLabel",'A watched company')||': Related-party defaults updated.';
 end if;

 if new."AIDexterWatchSignal_SourceTable"='CRM_ContactOrganisationAssignments' and v_field='contactEmployment' then
  v_event_body:=coalesce(watch."AIDexterWatch_TargetLabel",'A watched company')||': Contact employment updated.';
 end if;

 if new."AIDexterWatchSignal_SourceTable"='OrgContact_Emails' and v_field='contactEmails' then
  v_event_body:=coalesce(watch."AIDexterWatch_TargetLabel",'A watched company')||': Contact email details updated.';
 end if;

      if watch."AIDexterWatch_CapabilityCode" = 'email'
         and new."AIDexterWatchSignal_NewJSON" ? 'deliveryStatus' then
        v_event_body := 'Email engagement: ' || case new."AIDexterWatchSignal_NewJSON"->>'deliveryStatus'
          when 'opened' then 'opened (estimated)' when 'sent' then 'accepted for sending'
          when 'delivered' then 'delivery confirmed' when 'replied' then 'reply received'
          when 'bounced' then 'delivery bounced' when 'failed' then 'sending failed'
          else 'status updated' end || ' — ' || coalesce(new."AIDexterWatchSignal_NewJSON"->>'subject','(No subject)') || '.';
        v_changed := v_changed || jsonb_build_object(
          'deliveryStatus',new."AIDexterWatchSignal_NewJSON"->>'deliveryStatus',
          'openConfidence',new."AIDexterWatchSignal_NewJSON"->>'openConfidence',
          'eventAt',new."AIDexterWatchSignal_NewJSON"->>'eventAt');
      end if;

        if watch."AIDexterWatch_CapabilityCode"='email_signatures' then v_event_body:=coalesce(watch."AIDexterWatch_TargetLabel",'An email signature')||': '||case v_field when 'assignments' then 'Published assignments changed.' else 'A new signature version was applied.' end;end if;
        insert into public."AI_DexterWatchEvents" (
          "AIDexterWatchEvent_WatchID",
          "AIDexterWatchEvent_SignalID",
          "AIDexterWatchEvent_OwnerUserID",
          "AIDexterWatchEvent_Title",
          "AIDexterWatchEvent_Body",
          "AIDexterWatchEvent_ChangedJSON",
          "AIDexterWatchEvent_ActionJSON"
        )
        values (
          watch."AIDexterWatch_ID",
          new."AIDexterWatchSignal_ID",
          watch."AIDexterWatch_OwnerUserID",
          watch."AIDexterWatch_Title",
          v_event_body,
          v_changed,
          watch."AIDexterWatch_ActionJSON"
        )
        returning "AIDexterWatchEvent_ID" into v_event_id;

        insert into public."Comm_Notifications" (
          "CommNotif_UserID",
          "CommNotif_Title",
          "CommNotif_Body",
          "CommNotif_TargetTable",
          "CommNotif_TargetID",
          "CommNotif_LinkTypeCode",
          "CommNotif_MetadataJSON",
          "CommNotif_CreatedBy"
        )
        values (
          watch."AIDexterWatch_OwnerUserID",
          watch."AIDexterWatch_Title",
          v_event_body,
          'AI_DexterWatches',
          watch."AIDexterWatch_ID",
          'dexter_watch',
          jsonb_build_object(
            'event_type', 'dexter_watch',
            'watch_id', watch."AIDexterWatch_ID",
            'watch_event_id', v_event_id,
            'url', '/agent-dexter?watch=' || watch."AIDexterWatch_ID",
            'action_url', '/agent-dexter?watch=' || watch."AIDexterWatch_ID"
          ),
          watch."AIDexterWatch_OwnerUserID"
        );

        update public."AI_DexterWatches"
        set "AIDexterWatch_IsArmed" = false,
            "AIDexterWatch_LastTriggeredAt" = now(),
            "AIDexterWatch_TriggerCount" = "AIDexterWatch_TriggerCount" + 1,
            "AIDexterWatch_UpdatedAt" = now()
        where "AIDexterWatch_ID" = watch."AIDexterWatch_ID";
      end if;
    exception
      when others then
        update public."AI_DexterWatches"
        set "AIDexterWatch_HealthStatusCode" = 'error',
            "AIDexterWatch_LastSourceCheckAt" = now(),
            "AIDexterWatch_LastHealthError" = left(sqlerrm, 1000),
            "AIDexterWatch_UpdatedAt" = now()
        where "AIDexterWatch_ID" = watch."AIDexterWatch_ID";
    end;
  end loop;

  update public."AI_DexterWatchSignals"
  set "AIDexterWatchSignal_ProcessedAt" = now()
  where "AIDexterWatchSignal_ID" = new."AIDexterWatchSignal_ID";

  delete from public."AI_DexterWatchSignals" signal
  where signal."AIDexterWatchSignal_ID" = new."AIDexterWatchSignal_ID"
    and not exists (
      select 1
      from public."AI_DexterWatchEvents" event
      where event."AIDexterWatchEvent_SignalID" = signal."AIDexterWatchSignal_ID"
    );

  return new;
end;
$$;


ALTER FUNCTION "public"."_multideck_dexter_evaluate_watch_signal"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_dexter_finance_administration_watch_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_company uuid; v_entity public."cmp_LegalEntities";
begin
  select * into v_entity from public."cmp_LegalEntities" where "LegalEntity_ID"=new."FINAdminRevision_LegalEntityID";
  v_company:=v_entity."Company_ID";
  if v_company is not null and exists(select 1 from public."AI_DexterWatches" w where w."AIDexterWatch_CompanyID"=v_company and w."AIDexterWatch_CapabilityCode"='finance' and w."AIDexterWatch_StatusCode"='active' and (w."AIDexterWatch_TargetID" is null or w."AIDexterWatch_TargetID"=new."FINAdminRevision_LegalEntityID")) then
    insert into public."AI_DexterWatchSignals"("AIDexterWatchSignal_CompanyID","AIDexterWatchSignal_CapabilityCode","AIDexterWatchSignal_SourceTable","AIDexterWatchSignal_SourceID","AIDexterWatchSignal_OldJSON","AIDexterWatchSignal_NewJSON")
    values(v_company,'finance','FIN_AdministrationRevisions',new."FINAdminRevision_LegalEntityID",'{}'::jsonb,jsonb_build_object('configurationRevision',new."FINAdminRevision_Number",'readiness',new."FINAdminRevision_ReadinessJSON",'baseCurrency',v_entity."LegalEntity_BaseCurrencyCodeSnapshot",'provider',v_entity."LegalEntity_SettingsJSON"#>>'{financeProvider,providerCode}'));
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."_multideck_dexter_finance_administration_watch_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_dexter_finance_compliance_watch_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_company uuid; v_entity uuid:=coalesce(new."FINComplianceReg_LegalEntityID",old."FINComplianceReg_LegalEntityID"); v_row uuid:=coalesce(new."FINComplianceReg_ID",old."FINComplianceReg_ID");
begin
  select "Company_ID" into v_company from public."cmp_LegalEntities" where "LegalEntity_ID"=v_entity;
  if v_company is not null and exists(
    select 1 from public."AI_DexterWatches" watch
    where watch."AIDexterWatch_CompanyID"=v_company and watch."AIDexterWatch_CapabilityCode"='finance' and watch."AIDexterWatch_StatusCode"='active'
      and (watch."AIDexterWatch_TargetID" is null or watch."AIDexterWatch_TargetID"=v_entity)
  ) then
    insert into public."AI_DexterWatchSignals"(
      "AIDexterWatchSignal_CompanyID","AIDexterWatchSignal_CapabilityCode","AIDexterWatchSignal_SourceTable","AIDexterWatchSignal_SourceID","AIDexterWatchSignal_OldJSON","AIDexterWatchSignal_NewJSON"
    ) values (
      v_company,'finance','FIN_LegalEntityComplianceRegistrations',v_row,
      case when tg_op='INSERT' then '{}'::jsonb else jsonb_build_object('complianceStatus',old."FINComplianceReg_StatusCode",'obligationId',old."FINComplianceReg_ObligationID",'legalEntityId',v_entity) end,
      jsonb_build_object('complianceStatus',new."FINComplianceReg_StatusCode",'obligationId',new."FINComplianceReg_ObligationID",'legalEntityId',v_entity)
    );
  end if;
  return new;
end; $$;


