CREATE OR REPLACE FUNCTION "public"."_multideck_dexter_finance_watch_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_company uuid;
  v_source uuid;
  v_old jsonb := '{}'::jsonb;
  v_new jsonb;
begin
  if tg_table_name = 'FIN_Documents' then
    v_source := new."FINDoc_ID";
    select "Company_ID" into v_company from public."cmp_LegalEntities" where "LegalEntity_ID" = new."FINDoc_LegalEntityID";
    if tg_op <> 'INSERT' then
      v_old := jsonb_build_object(
        'status', old."FINDoc_StatusCode", 'dueDate', old."FINDoc_DueDate", 'outstandingAmount', old."FINDoc_OutstandingAmount",
        'taxStatus', coalesce(old."FINDoc_MetadataJSON" ->> 'taxStatus', 'pending'),
        'postingStatus', old."FINDoc_PostingStatusCode", 'exportStatus', old."FINDoc_ExportStatusCode"
      );
    end if;
    v_new := jsonb_build_object(
      'number', new."FINDoc_Number", 'status', new."FINDoc_StatusCode", 'dueDate', new."FINDoc_DueDate", 'outstandingAmount', new."FINDoc_OutstandingAmount",
      'taxStatus', coalesce(new."FINDoc_MetadataJSON" ->> 'taxStatus', 'pending'),
      'postingStatus', new."FINDoc_PostingStatusCode", 'exportStatus', new."FINDoc_ExportStatusCode"
    );
  else
    v_source := new."FINCash_ID";
    select "Company_ID" into v_company from public."cmp_LegalEntities" where "LegalEntity_ID" = new."FINCash_LegalEntityID";
    if tg_op <> 'INSERT' then
      v_old := jsonb_build_object('cashStatus', old."FINCash_StatusCode", 'unallocatedAmount', old."FINCash_UnallocatedAmount", 'postingStatus', old."FINCash_PostingStatusCode");
    end if;
    v_new := jsonb_build_object('number', new."FINCash_Number", 'cashStatus', new."FINCash_StatusCode", 'unallocatedAmount', new."FINCash_UnallocatedAmount", 'postingStatus', new."FINCash_PostingStatusCode");
  end if;
  if v_old is distinct from v_new
    and v_company is not null
    and exists (
      select 1 from public."AI_DexterWatches" watch
      where watch."AIDexterWatch_CompanyID" = v_company
        and watch."AIDexterWatch_CapabilityCode" = 'finance'
        and watch."AIDexterWatch_StatusCode" = 'active'
        and (watch."AIDexterWatch_TargetID" is null or watch."AIDexterWatch_TargetID" = v_source)
    ) then
    insert into public."AI_DexterWatchSignals"(
      "AIDexterWatchSignal_CompanyID", "AIDexterWatchSignal_CapabilityCode", "AIDexterWatchSignal_SourceTable", "AIDexterWatchSignal_SourceID", "AIDexterWatchSignal_OldJSON", "AIDexterWatchSignal_NewJSON"
    ) values (v_company, 'finance', tg_table_name, v_source, v_old, v_new);
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."_multideck_dexter_finance_watch_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_dexter_flush_address_watch"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_address_id uuid;before_value jsonb;after_value jsonb;source_id uuid;
begin
 for v_address_id in select distinct value::uuid from unnest(array[
  case when tg_op<>'INSERT' then to_jsonb(old)->>tg_argv[0] end,
  case when tg_op<>'DELETE' then to_jsonb(new)->>tg_argv[0] end]) value where value is not null
 loop
  delete from public."AI_DexterAddressWatchChanges" q where q.transaction_id=txid_current() and q.address_id=v_address_id returning q.before_value into before_value;
  if not found then continue;end if;
  after_value:=public._multideck_dexter_address_watch_snapshot(v_address_id);
  if before_value is not distinct from after_value then continue;end if;
  for source_id in select distinct value::uuid from unnest(array[before_value->>'Org_ID',after_value->>'Org_ID']) value where value is not null
  loop
   insert into public."AI_DexterWatchSignals"("AIDexterWatchSignal_CompanyID","AIDexterWatchSignal_CapabilityCode","AIDexterWatchSignal_SourceTable","AIDexterWatchSignal_SourceID","AIDexterWatchSignal_OldJSON","AIDexterWatchSignal_NewJSON")
   select distinct w."AIDexterWatch_CompanyID",'customers','Org_Addresses',source_id,
    jsonb_build_object('addresses',case when before_value->>'Org_ID'=source_id::text then before_value else '{}'::jsonb end),
    jsonb_build_object('addresses',case when after_value->>'Org_ID'=source_id::text then after_value else '{}'::jsonb end)
   from public."AI_DexterWatches" w where w."AIDexterWatch_CapabilityCode"='customers' and w."AIDexterWatch_StatusCode"='active'
    and (w."AIDexterWatch_TargetID" is null or w."AIDexterWatch_TargetID"=source_id)
    and exists(select 1 from public.multideck_crm_accessible_account_ids(w."AIDexterWatch_CompanyID") a where a.account_id=source_id);
  end loop;
 end loop;
 return null;
end $$;


ALTER FUNCTION "public"."_multideck_dexter_flush_address_watch"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_dexter_flush_contact_email_watch"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_contact_id uuid;before_snapshot jsonb;after_snapshot jsonb;before_value jsonb;after_value jsonb;source record;
begin
 for v_contact_id in select distinct v from unnest(array[case when tg_op<>'INSERT' then old."OrgContact_ID" end,case when tg_op<>'DELETE' then new."OrgContact_ID" end]) v where v is not null loop
  delete from public."AI_DexterContactEmailWatchChanges" q where q.transaction_id=txid_current() and q.contact_id=v_contact_id returning q.before_value into before_snapshot;
  if not found then continue;end if;
  after_snapshot:=public._multideck_dexter_contact_email_snapshot(v_contact_id);
  for source in select distinct (v->>'companyId')::uuid company_id,(v->>'organisationId')::uuid organisation_id from jsonb_array_elements(jsonb_build_array(before_snapshot,after_snapshot)) v where v->>'companyId' is not null loop
   before_value:=case when (before_snapshot->>'companyId')::uuid=source.company_id and (before_snapshot->>'organisationId')::uuid=source.organisation_id then before_snapshot->'emails' else '[]'::jsonb end;
   after_value:=case when (after_snapshot->>'companyId')::uuid=source.company_id and (after_snapshot->>'organisationId')::uuid=source.organisation_id then after_snapshot->'emails' else '[]'::jsonb end;
   if before_value is not distinct from after_value then continue;end if;
   insert into public."AI_DexterWatchSignals"("AIDexterWatchSignal_CompanyID","AIDexterWatchSignal_CapabilityCode","AIDexterWatchSignal_SourceTable","AIDexterWatchSignal_SourceID","AIDexterWatchSignal_OldJSON","AIDexterWatchSignal_NewJSON")
   select distinct w."AIDexterWatch_CompanyID",'customers','OrgContact_Emails',source.organisation_id,jsonb_build_object('contactEmails',before_value),jsonb_build_object('contactEmails',after_value)
   from public."AI_DexterWatches" w where w."AIDexterWatch_CompanyID"=source.company_id and w."AIDexterWatch_CapabilityCode"='customers' and w."AIDexterWatch_StatusCode"='active'
    and (w."AIDexterWatch_TargetID" is null or w."AIDexterWatch_TargetID"=source.organisation_id)
    and exists(select 1 from public.multideck_crm_accessible_account_ids(source.company_id) a where a.account_id=source.organisation_id);
  end loop;
 end loop;
 return null;
end $$;


ALTER FUNCTION "public"."_multideck_dexter_flush_contact_email_watch"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_dexter_flush_office_watch"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_profile_id uuid;before_value jsonb;after_value jsonb;source_id uuid;company_id uuid;
begin
 for v_profile_id in select distinct value from unnest(array[
  case when tg_op<>'INSERT' then old."CRMAccountOffice_AccountID" end,
  case when tg_op<>'DELETE' then new."CRMAccountOffice_AccountID" end]) value where value is not null
 loop
  delete from public."AI_DexterOfficeWatchChanges" q where q.transaction_id=txid_current() and q.profile_id=v_profile_id returning q.before_value into before_value;
  if not found then continue;end if;
  after_value:=public._multideck_dexter_office_watch_snapshot(v_profile_id);
  if before_value is not distinct from after_value then continue;end if;
  select p."CRMAccount_OrgID",p."CRMAccount_CompanyID" into source_id,company_id from public."CRM_AccountProfiles" p where p."CRMAccount_ID"=v_profile_id and not p."CRMAccount_IsDeleted";
  if not found then continue;end if;
  insert into public."AI_DexterWatchSignals"("AIDexterWatchSignal_CompanyID","AIDexterWatchSignal_CapabilityCode","AIDexterWatchSignal_SourceTable","AIDexterWatchSignal_SourceID","AIDexterWatchSignal_OldJSON","AIDexterWatchSignal_NewJSON")
  select distinct w."AIDexterWatch_CompanyID",'customers','CRM_AccountOfficeAssignments',source_id,
   jsonb_build_object('responsibleOffices',before_value),jsonb_build_object('responsibleOffices',after_value)
  from public."AI_DexterWatches" w where w."AIDexterWatch_CompanyID"=company_id and w."AIDexterWatch_CapabilityCode"='customers' and w."AIDexterWatch_StatusCode"='active'
   and (w."AIDexterWatch_TargetID" is null or w."AIDexterWatch_TargetID"=source_id)
   and exists(select 1 from public.multideck_crm_accessible_account_ids(company_id) a where a.account_id=source_id);
 end loop;
 return null;
end $$;


ALTER FUNCTION "public"."_multideck_dexter_flush_office_watch"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_dexter_has_permission"("p_user_id" "uuid", "p_permission" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select exists (
    select 1
    from public."cmp_Users_Roles" user_role
    join public."sys_UserRole_Permissions" role_permission
      on role_permission."sys_UserRole_ID" = user_role."sys_UserRole_ID"
    join public."sys_Permissions" permission
      on permission."sys_Permission_ID" = role_permission."sys_Permission_ID"
    where user_role."User_ID" = p_user_id
      and permission."sys_Permission_Value" = p_permission
  );
$$;


ALTER FUNCTION "public"."_multideck_dexter_has_permission"("p_user_id" "uuid", "p_permission" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_dexter_has_permissions"("p_user_id" "uuid", "p_permissions" "jsonb") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select jsonb_typeof(coalesce(p_permissions, '[]'::jsonb)) = 'array'
    and not exists (
      select 1
      from jsonb_array_elements_text(coalesce(p_permissions, '[]'::jsonb)) required(permission)
      where not public._multideck_dexter_has_permission(p_user_id, required.permission)
    );
$$;


