CREATE OR REPLACE FUNCTION "public"."_multideck_dexter_quote_cargo_watch_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare item quote_api.version_cargo_lines; source_id uuid;company uuid;reference text;before_value jsonb;after_value jsonb;
begin
  item:=case when tg_op='DELETE' then old else new end;
  source_id:=quote_api.cargo_record_id(item.version_id,item.line_id);
  select v."Company_ID",v."CusQuoteVersion_SnapshotJSON"->>'reference' into company,reference
    from public."CusQuote_Versions" v join public."CusQuote_Header" q on q."CusQuoteHeader_ID"=v."CusQuoteHeader_ID"
    join public."cmp_Offices" office on office."Office_ID"=coalesce(q."CusQuoteHeader_OrgOfficeID",q."OrgOffice_ID")
    where v."CusQuoteVersion_ID"=item.version_id and not q."CusQuoteHeader_IsDeleted" and office."Company_ID"=v."Company_ID";
  if not found or not exists(select 1 from public."AI_DexterWatches" where "AIDexterWatch_CompanyID"=company
    and "AIDexterWatch_CapabilityCode"='quote_cargo' and "AIDexterWatch_TargetID"=source_id and "AIDexterWatch_StatusCode"='active') then return null;end if;
  before_value:=case when tg_op='INSERT' then '{}'::jsonb else quote_api.cargo_read_values(old) end;
  after_value:=case when tg_op='DELETE' then before_value||'{"archived":true}'::jsonb else quote_api.cargo_read_values(new) end;
  if before_value=after_value then return null;end if;
  insert into public."AI_DexterWatchSignals"("AIDexterWatchSignal_CompanyID","AIDexterWatchSignal_CapabilityCode",
    "AIDexterWatchSignal_SourceTable","AIDexterWatchSignal_SourceID","AIDexterWatchSignal_OldJSON","AIDexterWatchSignal_NewJSON")
    values(company,'quote_cargo','quote_api.version_cargo_lines',source_id,before_value,after_value||jsonb_build_object(
      'versionId',item.version_id,'lineId',item.line_id,'quoteReference',reference,'sourceUrl','/quotes/'||lower(reference)));
  return null;
end $$;


ALTER FUNCTION "public"."_multideck_dexter_quote_cargo_watch_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_dexter_quote_delivery_watch_source_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  quote_reference text;
  old_json jsonb;
  new_json jsonb;
begin
  if old.follow_up_status_code is distinct from new.follow_up_status_code
     and new.follow_up_status_code = 'processing'
     and old.delivery_status_code is not distinct from new.delivery_status_code
     and old.follow_up_next_attempt_at is not distinct from new.follow_up_next_attempt_at then
    return new;
  end if;
  select "CusQuoteHeader_CustomerReference" into quote_reference
  from public."CusQuote_Header" where "CusQuoteHeader_ID" = new.quote_id;
  old_json := jsonb_build_object(
    'quoteNumber', quote_reference, 'deliveryMode', old.delivery_mode_code,
    'responseControlsEnabled', old.delivery_mode_code = 'standard', 'recipientSource', old.recipient_source_code,
    'recipientEmail', old.recipient_email, 'quoteDocumentId', old.quote_document_id,
    'deliveryStatus', old.delivery_status_code, 'followUpStatus', old.follow_up_status_code,
    'followUpAt', old.follow_up_next_attempt_at
  );
  new_json := jsonb_build_object(
    'quoteNumber', quote_reference, 'deliveryMode', new.delivery_mode_code,
    'responseControlsEnabled', new.delivery_mode_code = 'standard', 'recipientSource', new.recipient_source_code,
    'recipientEmail', new.recipient_email, 'quoteDocumentId', new.quote_document_id,
    'deliveryStatus', new.delivery_status_code, 'followUpStatus', new.follow_up_status_code,
    'followUpAt', new.follow_up_next_attempt_at
  );
  if old_json is distinct from new_json and exists (
    select 1 from public."AI_DexterWatches" watch
    where watch."AIDexterWatch_CompanyID" = new.company_id
      and watch."AIDexterWatch_CapabilityCode" = 'quotes'
      and watch."AIDexterWatch_StatusCode" = 'active'
      and (watch."AIDexterWatch_TargetID" is null or watch."AIDexterWatch_TargetID" = new.quote_id)
  ) then
    insert into public."AI_DexterWatchSignals" (
      "AIDexterWatchSignal_CompanyID", "AIDexterWatchSignal_CapabilityCode",
      "AIDexterWatchSignal_SourceTable", "AIDexterWatchSignal_SourceID",
      "AIDexterWatchSignal_OldJSON", "AIDexterWatchSignal_NewJSON"
    ) values (new.company_id, 'quotes', 'quote_api.customer_response_links', new.quote_id, old_json, new_json);
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."_multideck_dexter_quote_delivery_watch_source_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_dexter_quote_watch_source_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  company_id uuid;
  source_id uuid := new."CusQuoteHeader_ID";
  latest_decision text;
  latest_decline_reason text;
  booking_reference text;
  old_json jsonb;
  new_json jsonb;
begin
  company_id := new."Org_ID";
  if company_id is null then
    select office."Company_ID" into company_id
    from public."cmp_Offices" office
    where office."Office_ID" = coalesce(new."CusQuoteHeader_OrgOfficeID", new."OrgOffice_ID");
  end if;
  select response.decision_code, response.decline_reason_code
    into latest_decision, latest_decline_reason
  from quote_api.customer_responses response
  where response.quote_id = source_id
  order by response.created_at desc limit 1;
  select job."Job_BookingReference" into booking_reference
  from public."Job_Header" job
  where job."Job_SourceQuoteID" = source_id and not job."Job_IsDeleted"
  order by job."Job_CreatedDate" asc limit 1;

  old_json := case when tg_op = 'INSERT' then '{}'::jsonb else jsonb_build_object(
    'quoteNumber', old."CusQuoteHeader_CustomerReference",
    'status', case when old."CusQuoteHeader_LifecycleCode" = 'accepted' then 'Won' when old."CusQuoteHeader_LifecycleCode" in ('declined','ghosted') then 'Lost' else 'Open' end,
    'lifecycle', old."CusQuoteHeader_LifecycleCode",
    'deadline', old."CusQuoteHeader_Deadline",
    'validFrom', old."CusQuoteHeader_ValidFrom",
    'validTo', old."CusQuoteHeader_ValidTo",
    'estimatedDeparture', old."CusQuoteHeader_ShipmentFactsJSON"->>'estimatedDeparture',
    'estimatedArrival', old."CusQuoteHeader_ShipmentFactsJSON"->>'estimatedArrival',
    'origin', coalesce(old."CusQuoteHeader_LoadingPoint", old."CusQuoteHeader_OriginExtra"),
    'destination', coalesce(old."CusQuoteHeader_DischargePoint", old."CusQuoteHeader_DestinationExtra"),
    'customerDecision', case when old."CusQuoteHeader_LifecycleCode" is distinct from new."CusQuoteHeader_LifecycleCode" then null else latest_decision end,
    'declineReasonCode', case when old."CusQuoteHeader_LifecycleCode" is distinct from new."CusQuoteHeader_LifecycleCode" then null else latest_decline_reason end,
    'bookingReference', case when old."CusQuoteHeader_LifecycleCode" = 'accepted' then booking_reference end
  ) end;
  new_json := jsonb_build_object(
    'quoteNumber', new."CusQuoteHeader_CustomerReference",
    'status', case when new."CusQuoteHeader_LifecycleCode" = 'accepted' then 'Won' when new."CusQuoteHeader_LifecycleCode" in ('declined','ghosted') then 'Lost' else 'Open' end,
    'lifecycle', new."CusQuoteHeader_LifecycleCode",
    'deadline', new."CusQuoteHeader_Deadline",
    'validFrom', new."CusQuoteHeader_ValidFrom",
    'validTo', new."CusQuoteHeader_ValidTo",
    'estimatedDeparture', new."CusQuoteHeader_ShipmentFactsJSON"->>'estimatedDeparture',
    'estimatedArrival', new."CusQuoteHeader_ShipmentFactsJSON"->>'estimatedArrival',
    'origin', coalesce(new."CusQuoteHeader_LoadingPoint", new."CusQuoteHeader_OriginExtra"),
    'destination', coalesce(new."CusQuoteHeader_DischargePoint", new."CusQuoteHeader_DestinationExtra"),
    'customerDecision', latest_decision,
    'declineReasonCode', latest_decline_reason,
    'bookingReference', booking_reference
  );

  if company_id is not null and old_json is distinct from new_json and exists (
    select 1 from public."AI_DexterWatches" watch
    where watch."AIDexterWatch_CompanyID" = company_id
      and watch."AIDexterWatch_CapabilityCode" = 'quotes'
      and watch."AIDexterWatch_StatusCode" = 'active'
      and (watch."AIDexterWatch_TargetID" is null or watch."AIDexterWatch_TargetID" = source_id)
  ) then
    insert into public."AI_DexterWatchSignals"(
      "AIDexterWatchSignal_CompanyID", "AIDexterWatchSignal_CapabilityCode",
      "AIDexterWatchSignal_SourceTable", "AIDexterWatchSignal_SourceID",
      "AIDexterWatchSignal_OldJSON", "AIDexterWatchSignal_NewJSON"
    ) values (company_id, 'quotes', 'CusQuote_Header', source_id, old_json, new_json);
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."_multideck_dexter_quote_watch_source_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_dexter_rate_watch_source_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_old jsonb := '{}'::jsonb;
  v_new jsonb;
begin
  if new."Company_ID" is null then return new; end if;
  if tg_op <> 'INSERT' then
    v_old := jsonb_build_object(
      'status', old."RATEContract_StatusCode", 'validFrom', old."RATEContract_ValidFrom", 'validTo', old."RATEContract_ValidTo",
      'mode', old."RATEContract_MetadataJSON"->>'mode', 'origin', old."RATEContract_MetadataJSON"->>'origin',
      'destination', old."RATEContract_MetadataJSON"->>'destination', 'carrier', old."RATEContract_MetadataJSON"->>'carrier',
      'supplier', old."RATEContract_MetadataJSON"->>'supplier', 'customer', old."RATEContract_MetadataJSON"->>'customer',
      'buyTotal', old."RATEContract_MetadataJSON"->'buyTotal', 'sellTotal', old."RATEContract_MetadataJSON"->'sellTotal',
      'versionId', old."RATEContract_CurrentVersionID"
    );
  end if;
  v_new := jsonb_build_object(
    'rateCode', new."RATEContract_Code", 'name', new."RATEContract_Name", 'status', new."RATEContract_StatusCode",
    'validFrom', new."RATEContract_ValidFrom", 'validTo', new."RATEContract_ValidTo", 'mode', new."RATEContract_MetadataJSON"->>'mode',
    'origin', new."RATEContract_MetadataJSON"->>'origin', 'destination', new."RATEContract_MetadataJSON"->>'destination',
    'carrier', new."RATEContract_MetadataJSON"->>'carrier', 'supplier', new."RATEContract_MetadataJSON"->>'supplier',
    'customer', new."RATEContract_MetadataJSON"->>'customer', 'buyTotal', new."RATEContract_MetadataJSON"->'buyTotal',
    'sellTotal', new."RATEContract_MetadataJSON"->'sellTotal', 'versionId', new."RATEContract_CurrentVersionID"
  );
  if tg_op = 'INSERT' or v_old is distinct from (v_new - 'rateCode' - 'name') then
    insert into public."AI_DexterWatchSignals" (
      "AIDexterWatchSignal_CompanyID", "AIDexterWatchSignal_CapabilityCode", "AIDexterWatchSignal_SourceTable",
      "AIDexterWatchSignal_SourceID", "AIDexterWatchSignal_OldJSON", "AIDexterWatchSignal_NewJSON"
