CREATE OR REPLACE FUNCTION "public"."_multideck_dexter_writing_profile_audit"("p_profile_id" "uuid", "p_company_id" "uuid", "p_user_id" "uuid", "p_event" "text", "p_status" "text" DEFAULT NULL::"text", "p_message_count" integer DEFAULT 0) RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  insert into public."AI_DexterWritingProfileAudit" (
    "AIDexterWritingAudit_ProfileID",
    "AIDexterWritingAudit_CompanyID",
    "AIDexterWritingAudit_UserID",
    "AIDexterWritingAudit_EventCode",
    "AIDexterWritingAudit_StatusCode",
    "AIDexterWritingAudit_MessageCount"
  ) values (
    p_profile_id,
    p_company_id,
    p_user_id,
    left(btrim(coalesce(p_event, '')), 40),
    nullif(left(btrim(coalesce(p_status, '')), 24), ''),
    greatest(coalesce(p_message_count, 0), 0)
  );
$$;


ALTER FUNCTION "public"."_multideck_dexter_writing_profile_audit"("p_profile_id" "uuid", "p_company_id" "uuid", "p_user_id" "uuid", "p_event" "text", "p_status" "text", "p_message_count" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_dexter_writing_profile_source_for"("p_company_id" "uuid", "p_user_id" "uuid", "p_take" integer DEFAULT 40, "p_after" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_take integer := least(greatest(coalesce(p_take, 40), 1), 40);
  v_result jsonb;
begin
  if not public._multideck_dexter_has_permission(p_user_id, 'Email.Read')
     or not public._multideck_dexter_has_permission(p_user_id, 'Email.AIRead') then
    raise exception 'You do not have permission to use email with Dexter.' using errcode = '42501';
  end if;

  if not exists (
    select 1 from public."cmp_Users" profile
    where profile."User_ID" = p_user_id
      and profile."Company_ID" = p_company_id
  ) then
    raise exception 'This operator is outside the tenant workspace.' using errcode = '42501';
  end if;

  with permitted_mailboxes as materialized (
    select permitted.mailbox_id
    from public._multideck_dexter_email_mailboxes(p_user_id, p_company_id) permitted
  ),
  eligible as materialized (
    select
      message."CommMessage_ID" as message_id,
      message."CommMessage_ThreadID" as thread_id,
      message."CommMessage_BodyText" as body_text,
      coalesce(message."CommMessage_MessageDate", message."CommMessage_SentAt", message."CommMessage_CreatedAt") as occurred_at,
      coalesce(recipients.recipient_key, message."CommMessage_ThreadID"::text) as recipient_key,
      row_number() over (
        partition by message."CommMessage_ThreadID"
        order by coalesce(message."CommMessage_MessageDate", message."CommMessage_SentAt", message."CommMessage_CreatedAt") desc,
          message."CommMessage_ID" desc
      ) as thread_rank
    from public."Comm_Messages" message
    join permitted_mailboxes permitted on permitted.mailbox_id = message."CommMessage_MailboxID"
    join public."Comm_Mailboxes" mailbox on mailbox."CommMailbox_ID" = message."CommMessage_MailboxID"
    join public."Comm_ProviderConnections" connection on connection."CommConn_ID" = mailbox."CommMailbox_ConnectionID"
    left join lateral (
      select min(recipient."CommRecipient_NormalizedAddress") as recipient_key
      from public."Comm_MessageRecipients" recipient
      where recipient."CommRecipient_MessageID" = message."CommMessage_ID"
        and recipient."CommRecipient_RecipientTypeCode" = 'to'
        and recipient."CommRecipient_IsExternal"
        and not recipient."CommRecipient_IsSuppressed"
    ) recipients on true
    where message."CommMessage_DirectionCode" = 'outbound'
      and not message."CommMessage_IsInbound"
      and message."CommMessage_StatusCode" in ('sent','delivered')
      and not message."CommMessage_IsDraft"
      and not message."CommMessage_IsSpam"
      and not message."CommMessage_IsDeleted"
      and not message."CommMessage_IsBodyRedacted"
      and nullif(btrim(message."CommMessage_BodyText"), '') is not null
      and char_length(btrim(message."CommMessage_BodyText")) between 40 and 12000
      and coalesce(message."CommMessage_MessageDate", message."CommMessage_SentAt", message."CommMessage_CreatedAt") >= now() - interval '12 months'
      and (p_after is null or coalesce(message."CommMessage_MessageDate", message."CommMessage_SentAt", message."CommMessage_CreatedAt") > p_after)
      and (
        (
          mailbox."CommMailbox_TypeCode" = 'personal'
          and mailbox."CommMailbox_UserID" = p_user_id
          and connection."CommConn_UserID" = p_user_id
        )
        or message."CommMessage_CreatedBy" = p_user_id
      )
      and lower(coalesce(message."CommMessage_Subject", '') || ' ' || left(message."CommMessage_BodyText", 800)) !~
        '(automatic reply|auto.?reply|out of office|undeliverable|delivery status|mail delivery|do.?not.?reply|no.?reply|newsletter|unsubscribe|password reset|verification code|support ticket)'
  ),
  diversified as materialized (
    select eligible.*,
      row_number() over (
        partition by eligible.recipient_key
        order by eligible.occurred_at desc, eligible.message_id desc
      ) as recipient_rank
    from eligible
    where thread_rank = 1
  ),
  selected as (
    select * from diversified
    order by recipient_rank, occurred_at desc, message_id desc
    limit v_take
  )
  select jsonb_build_object(
    'eligibleCount', (select count(*) from diversified),
    'messages', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'messageId', selected.message_id,
          'bodyText', selected.body_text,
          'occurredAt', selected.occurred_at
        ) order by selected.occurred_at desc, selected.message_id desc
      ) from selected
    ), '[]'::jsonb),
    'latestMessageAt', (select max(occurred_at) from diversified)
  ) into v_result;

  return coalesce(v_result, jsonb_build_object('eligibleCount', 0, 'messages', '[]'::jsonb, 'latestMessageAt', null));
end;
$$;


ALTER FUNCTION "public"."_multideck_dexter_writing_profile_source_for"("p_company_id" "uuid", "p_user_id" "uuid", "p_take" integer, "p_after" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_multideck_dexter_writing_profile_source_for"("p_company_id" "uuid", "p_user_id" "uuid", "p_take" integer, "p_after" timestamp with time zone) IS 'Selects bounded, provably authored sent email for one operator. Private preferences do not emit Watching for you signals.';



CREATE OR REPLACE FUNCTION "public"."_multideck_document_usage_watch"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_company_id uuid;
begin
  if new."DOCBRJ_StatusCode" = 'completed' and old."DOCBRJ_StatusCode" is distinct from 'completed' then
    select workspace_user."Company_ID" into v_company_id
    from public."cmp_Users" workspace_user
    where workspace_user."User_ID" = new."DOCBRJ_CreatedBy";
    if v_company_id is not null then
      perform public._multideck_emit_usage_watch_signal(v_company_id, tg_table_name, new."DOCBRJ_ID", 'documents');
    end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."_multideck_document_usage_watch"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_emit_usage_watch_signal"("p_company_id" "uuid", "p_source_table" "text", "p_source_id" "uuid", "p_category" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_category jsonb;
begin
  if not exists (
    select 1 from public."AI_DexterWatches" watch
    where watch."AIDexterWatch_CompanyID" = p_company_id
      and watch."AIDexterWatch_CapabilityCode" = 'usage'
      and watch."AIDexterWatch_StatusCode" = 'active'
      and (watch."AIDexterWatch_TargetID" is null or watch."AIDexterWatch_TargetID" = p_company_id)
  ) then
    return;
  end if;

  select category.value into v_category
  from jsonb_array_elements(public._multideck_usage_categories(p_company_id) -> 'categories') category(value)
  where category.value ->> 'id' = p_category
    and coalesce((category.value ->> 'enabled')::boolean, false)
  limit 1;

  if v_category is null then return; end if;

  insert into public."AI_DexterWatchSignals" (
    "AIDexterWatchSignal_CompanyID", "AIDexterWatchSignal_CapabilityCode",
    "AIDexterWatchSignal_SourceTable", "AIDexterWatchSignal_SourceID",
    "AIDexterWatchSignal_OldJSON", "AIDexterWatchSignal_NewJSON"
  ) values (
    p_company_id, 'usage', left(p_source_table, 120), p_source_id, '{}'::jsonb,
    jsonb_build_object(
      'category', v_category ->> 'id',
      'used', (v_category ->> 'used')::numeric,
      'included', (v_category ->> 'included')::numeric,
      'extra', (v_category ->> 'extra')::numeric,
      'usedPercent', (v_category ->> 'usedPercent')::numeric
    )
  );
end;
$$;


ALTER FUNCTION "public"."_multideck_emit_usage_watch_signal"("p_company_id" "uuid", "p_source_table" "text", "p_source_id" "uuid", "p_category" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_finance_adapt_legacy_job_charge"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_domain text; v_actor uuid;
begin
  select coalesce(job."Job_DomainCode",'freight'),job."Job_CreatedBy" into v_domain,v_actor
  from public."Job_Header" job where job."Job_ID"=new."Job_ID";
  if tg_table_name='Job_Costing_ChargesIn' then
    perform public._multideck_finance_upsert_job_charge(
      new."Job_ID",v_domain,'Job_Costing_ChargesIn',new."JCIn_ID",null,
      coalesce(nullif(btrim(new."JCIn_Description"),''),'Expected supplier cost'),new."JCIn_From",new."JCIn_ChargeCode",
      coalesce(new."JCIn_Expected_NetCost_Local",0),0,new."JCIn_Expected_NetCost_Curr",null,
      new."JCIn_FromCurr",null,new."JCIn_FromROE",null,v_actor,
      jsonb_build_object('sourceKind','legacy_cost','actualsIgnored',true)
    );
  else
    perform public._multideck_finance_upsert_job_charge(
      new."Job_ID",v_domain,'Job_Costing_ChargesOut',new."JCOut_ID",null,
      coalesce(nullif(btrim(new."JCOut_Description"),''),'Expected customer revenue'),null,new."JCOut_ChargeCode",
      0,coalesce(new."JCOut_Expected_NetCost_Local",0),null,new."JCOut_Expected_NetCost_Curr",
      null,new."JCOut_ToCurr",null,new."JCOut_ToROE",v_actor,
      jsonb_build_object('sourceKind','legacy_revenue','actualsIgnored',true,'customerOrgId',new."JCOut_To")
    );
  end if;
  return new;
end; $$;


ALTER FUNCTION "public"."_multideck_finance_adapt_legacy_job_charge"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_finance_adapt_warehouse_billing_event"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare v_job uuid; v_actor uuid; v_entity uuid; v_base text; v_currency text; v_roe numeric; v_local numeric;
begin
  v_job:=new."WMSBillEvent_JobID";
  if v_job is null and new."WMSBillEvent_OrderID" is not null then
    select "WMSOrder_JobID" into v_job from public."WMS_Orders" where "WMSOrder_ID"=new."WMSBillEvent_OrderID";
    new."WMSBillEvent_JobID":=v_job;
  end if;
  if v_job is null then raise exception 'A warehouse billing event must be linked to an operational job.' using errcode='22023'; end if;
  select coalesce(new."WMSBillEvent_CreatedBy",job."Job_CreatedBy") into v_actor from public."Job_Header" job where job."Job_ID"=v_job;
  v_entity:=public._multideck_finance_resolve_job_legal_entity(v_job);
  select upper(coalesce("LegalEntity_BaseCurrencyCodeSnapshot",'GBP')) into v_base from public."cmp_LegalEntities" where "LegalEntity_ID"=v_entity;
  v_currency:=upper(coalesce(new."WMSBillEvent_CurrencyCode",v_base));
  if coalesce(new."WMSBillEvent_MetadataJSON"->>'exchangeRate','') ~ '^\d+(\.\d+)?$' then v_roe:=(new."WMSBillEvent_MetadataJSON"->>'exchangeRate')::numeric; end if;
  if coalesce(new."WMSBillEvent_MetadataJSON"->>'localNetAmount','') ~ '^\d+(\.\d+)?$' then
    v_local:=(new."WMSBillEvent_MetadataJSON"->>'localNetAmount')::numeric;
  elsif v_currency=v_base then v_local:=new."WMSBillEvent_NetAmount";
  elsif v_roe is not null and v_roe>0 then v_local:=round(new."WMSBillEvent_NetAmount"*v_roe,4);
  else raise exception 'A foreign-currency warehouse billing event needs exchangeRate or localNetAmount evidence.' using errcode='22023';
  end if;
  perform public._multideck_finance_upsert_job_charge(
    v_job,'warehouse','WMS_BillingEvents',new."WMSBillEvent_ID",null,new."WMSBillEvent_Description",null,null,
    0,case when new."WMSBillEvent_StatusCode"='cancelled' then 0 else v_local end,null,new."WMSBillEvent_NetAmount",
    null,null,null,v_roe,v_actor,
    coalesce(new."WMSBillEvent_MetadataJSON",'{}'::jsonb)||jsonb_build_object('eventType',new."WMSBillEvent_EventTypeCode",'billingBasis',new."WMSBillEvent_BillingBasisCode",'currencyCode',v_currency,'localCurrencyCode',v_base,'orderId',new."WMSBillEvent_OrderID")
  );
  return new;
end; $_$;


ALTER FUNCTION "public"."_multideck_finance_adapt_warehouse_billing_event"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_finance_apply_approved_line_tax"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_legal_entity_id uuid;
  v_document_type text;
  v_document_status text;
  v_document_date date;
  v_exchange_rate numeric;
  v_direction text;
  v_match_count integer := 0;
  v_tax_id uuid;
  v_tax_code text;
  v_tax_rate numeric := 0;
  v_sign numeric;
  v_net numeric;
  v_tax numeric;
  v_has_approved_tax_advice boolean := false;
  v_demo_tax_allowed boolean := false;
begin
  select
    document."FINDoc_LegalEntityID",
    document."FINDoc_TypeCode",
    document."FINDoc_StatusCode",
    document."FINDoc_DocumentDate",
    document."FINDoc_ExchangeRate"
  into v_legal_entity_id, v_document_type, v_document_status, v_document_date, v_exchange_rate
  from public."FIN_Documents" document
  where document."FINDoc_ID" = new."FINDocLine_DocumentID";

  if v_legal_entity_id is null then
    raise exception 'The finance document for this line does not exist.' using errcode = 'P0002';
  end if;
  if new."FINDocLine_Quantity" <= 0 or new."FINDocLine_UnitAmount" < 0 then
    raise exception 'Check the finance line quantity and unit amount.' using errcode = '22023';
  end if;

  select exists (
    select 1
    from public."FIN_AdministrationRevisions" revision
    where revision."FINAdminRevision_LegalEntityID" = v_legal_entity_id
      and revision."FINAdminRevision_StatusCode" = 'approved'
      and coalesce(revision."FINAdminRevision_ConfigJSON" #>> '{taxSettings,localAdviceConfirmed}', 'false') = 'true'
  ) into v_has_approved_tax_advice;
  v_demo_tax_allowed := public._multideck_finance_demo_tax_allowed(v_legal_entity_id);

  new."FINDocLine_TaxCodeSnapshot" := nullif(left(btrim(new."FINDocLine_TaxCodeSnapshot"), 80), '');
  v_direction := case when v_document_type in ('sl_invoice', 'credit_note') then 'sales' else 'purchase' end;

  if (v_has_approved_tax_advice or v_demo_tax_allowed) and new."FINDocLine_TaxCodeSnapshot" is not null then
    select
      count(*),
      (array_agg(tax."FINTax_ID" order by tax."FINTax_EffectiveFrom" desc))[1],
      (array_agg(tax."FINTax_Code" order by tax."FINTax_EffectiveFrom" desc))[1],
      (array_agg(tax."FINTax_RatePercent" order by tax."FINTax_EffectiveFrom" desc))[1]
    into v_match_count, v_tax_id, v_tax_code, v_tax_rate
    from public."FIN_TaxCodes" tax
    where tax."FINTax_LegalEntityID" = v_legal_entity_id
      and tax."FINTax_Code" = new."FINDocLine_TaxCodeSnapshot"
      and tax."FINTax_IsActive"
      and tax."FINTax_ApprovedAt" is not null
      and tax."FINTax_TransactionTypeCode" in ('both', v_direction)
      and tax."FINTax_EffectiveFrom" <= v_document_date
      and (tax."FINTax_EffectiveTo" is null or tax."FINTax_EffectiveTo" >= v_document_date)
      and (
        (v_has_approved_tax_advice and not coalesce((tax."FINTax_SettingsJSON" ->> 'demoOnly')::boolean, false))
        or (v_demo_tax_allowed and tax."FINTax_Code" = 'DEMO-NONTAX' and tax."FINTax_RatePercent" = 0 and coalesce((tax."FINTax_SettingsJSON" ->> 'demoOnly')::boolean, false))
      );

    if v_match_count > 1 then
      raise exception 'The selected tax treatment has overlapping effective rules. Finance must correct the setup.' using errcode = '22023';
    end if;
  end if;

  if v_match_count = 1 then
    new."FINDocLine_TaxCodeID" := v_tax_id;
    new."FINDocLine_TaxCodeSnapshot" := v_tax_code;
    new."FINDocLine_TaxRatePercent" := v_tax_rate;
  else
    if v_document_status <> 'draft' then
      if not v_has_approved_tax_advice and not v_demo_tax_allowed then
        raise exception 'Finance must approve local tax advice before this document can enter review.' using errcode = '22023';
      end if;
      raise exception 'Every finance line must use one approved effective tax treatment before review.' using errcode = '22023';
    end if;
    new."FINDocLine_TaxCodeID" := null;
    new."FINDocLine_TaxRatePercent" := 0;
    v_tax_rate := 0;
  end if;

  v_sign := case when v_document_type in ('credit_note', 'debit_note') then -1 else 1 end;
  v_net := round(new."FINDocLine_Quantity" * new."FINDocLine_UnitAmount", 4) * v_sign;
  v_tax := round(abs(v_net) * v_tax_rate / 100, 4) * v_sign;
  new."FINDocLine_NetAmount" := v_net;
  new."FINDocLine_TaxAmount" := v_tax;
  new."FINDocLine_GrossAmount" := v_net + v_tax;
  new."FINDocLine_LocalNetAmount" := round(v_net * v_exchange_rate, 4);
  new."FINDocLine_LocalTaxAmount" := round(v_tax * v_exchange_rate, 4);
  new."FINDocLine_LocalGrossAmount" := round((v_net + v_tax) * v_exchange_rate, 4);
  return new;
end;
$$;


ALTER FUNCTION "public"."_multideck_finance_apply_approved_line_tax"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_multideck_finance_apply_approved_line_tax"() IS 'Derives tax from an approved effective legal-entity treatment, while allowing an unmistakable tax-pending line only on an unposted draft.';



CREATE OR REPLACE FUNCTION "public"."_multideck_finance_default_job_charge_domain"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_domain text;
begin
  if new."JobCostingLine_DomainCode" is null then
    select job."Job_DomainCode" into v_domain
    from public."Job_Header" job where job."Job_ID"=new."Job_ID";
    new."JobCostingLine_DomainCode":=coalesce(v_domain,'freight');
  end if;
  new."JobCostingLine_SourceTable":=nullif(btrim(new."JobCostingLine_SourceTable"),'');
  return new;
end; $$;


