CREATE OR REPLACE FUNCTION "public"."_multideck_mutate_lifecycle_note"("p_auth_user_id" "uuid", "p_note_id" "uuid", "p_body" "text", "p_delete" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth', 'booking_api', 'quote_api'
    AS $$
declare
  v_note public."OPS_LifecycleNotes";
  v_context record;
  v_body text := btrim(coalesce(p_body, ''));
  v_old_body text;
  v_mentions jsonb;
  v_event_kind text := case when p_delete then 'deleted' else 'edited' end;
begin
  select * into v_note
  from public."OPS_LifecycleNotes" note
  where note."LifecycleNote_ID" = p_note_id
  for update;

  if not found then
    raise exception 'That note is no longer available.' using errcode = 'P0002';
  end if;

  select * into strict v_context
  from public._multideck_lifecycle_note_context(
    p_auth_user_id,
    v_note."LifecycleNote_SubjectType",
    v_note."LifecycleNote_SubjectID",
    true
  );

  if v_note."LifecycleNote_CompanyID" <> v_context.company_id
     or v_note."LifecycleNote_AuthorUserID" is distinct from v_context.actor_user_id then
    raise exception 'You can only change a note you added.' using errcode = '42501';
  end if;
  if v_note."LifecycleNote_DeletedAt" is not null then
    raise exception 'That note has already been deleted.' using errcode = '22023';
  end if;
  if not p_delete and v_body = '' then
    raise exception 'Write a note before saving it.' using errcode = '22023';
  end if;
  if not p_delete and char_length(v_body) > 4000 then
    raise exception 'Keep the note to 4,000 characters or fewer.' using errcode = '22023';
  end if;

  v_old_body := v_note."LifecycleNote_Body";
  perform set_config('app.user_id', v_context.actor_user_id::text, true);
  perform set_config('app.auth_user_id', p_auth_user_id::text, true);
  perform set_config('app.actor_type', 'user', true);
  perform set_config('app.source_app', 'Multideck App', true);
  perform set_config('app.source_module', 'lifecycle_notes', true);

  if p_delete then
    update public."OPS_LifecycleNotes"
    set "LifecycleNote_DeletedAt" = now(),
        "LifecycleNote_DeletedByUserID" = v_context.actor_user_id
    where "LifecycleNote_ID" = p_note_id
    returning * into v_note;
  else
    update public."OPS_LifecycleNotes"
    set "LifecycleNote_Body" = v_body,
        "LifecycleNote_UpdatedAt" = now()
    where "LifecycleNote_ID" = p_note_id
    returning * into v_note;
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'type', mention."LifecycleNoteMention_TargetType",
    'id', mention."LifecycleNoteMention_TargetID",
    'label', mention."LifecycleNoteMention_LabelSnapshot"
  )), '[]'::jsonb)
  into v_mentions
  from public."OPS_LifecycleNoteMentions" mention
  where mention."LifecycleNoteMention_NoteID" = p_note_id;

  insert into public."AI_DexterWatchSignals" (
    "AIDexterWatchSignal_CompanyID", "AIDexterWatchSignal_CapabilityCode",
    "AIDexterWatchSignal_SourceTable", "AIDexterWatchSignal_SourceID",
    "AIDexterWatchSignal_OldJSON", "AIDexterWatchSignal_NewJSON"
  )
  select distinct
    v_context.company_id,
    'lifecycle_notes',
    'OPS_LifecycleNotes',
    watch."AIDexterWatch_TargetID",
    jsonb_build_object(
      'eventKind', 'existing',
      'subjectType', v_note."LifecycleNote_SubjectType",
      'body', v_old_body,
      'author', v_note."LifecycleNote_AuthorNameSnapshot",
      'updatedAt', coalesce(v_note."LifecycleNote_UpdatedAt", v_note."LifecycleNote_CreatedAt")
    ),
    jsonb_build_object(
      'eventKind', v_event_kind,
      'subjectType', v_note."LifecycleNote_SubjectType",
      'reference', coalesce(
        (select 'Q-' || quote."CusQuoteHeader_Number" from public."CusQuote_Header" quote where quote."CusQuoteHeader_ID" = watch."AIDexterWatch_TargetID"),
        (select coalesce(nullif(btrim(job."Job_BookingReference"), ''), 'MD-' || job."Job_Number") from public."Job_Header" job where job."Job_ID" = watch."AIDexterWatch_TargetID"),
        (select coalesce(nullif(btrim(declaration."CUST_LocalReferenceNumber"), ''), declaration."CUST_id"::text) from public."Customs_Declarations" declaration where declaration."CUST_id" = watch."AIDexterWatch_TargetID"),
        v_context.reference
      ),
      'body', case when p_delete then null else v_note."LifecycleNote_Body" end,
      'author', v_note."LifecycleNote_AuthorNameSnapshot",
      'mentionedUsers', coalesce((select jsonb_agg(value->>'label') from jsonb_array_elements(v_mentions) value where value->>'type' = 'user'), '[]'::jsonb),
      'mentionedDepartments', coalesce((select jsonb_agg(value->>'label') from jsonb_array_elements(v_mentions) value where value->>'type' = 'department'), '[]'::jsonb),
      'createdAt', v_note."LifecycleNote_CreatedAt",
      'updatedAt', coalesce(v_note."LifecycleNote_DeletedAt", v_note."LifecycleNote_UpdatedAt")
    )
  from public."AI_DexterWatches" watch
  where watch."AIDexterWatch_CompanyID" = v_context.company_id
    and watch."AIDexterWatch_CapabilityCode" = 'lifecycle_notes'
    and watch."AIDexterWatch_StatusCode" = 'active'
    and (
      watch."AIDexterWatch_TargetID" = v_note."LifecycleNote_SubjectID"
      or (
        v_note."LifecycleNote_SubjectType" = 'quote'
        and exists (
          select 1 from public."Job_Header" job
          where job."Job_SourceQuoteID" = v_note."LifecycleNote_QuoteID"
            and not job."Job_IsDeleted"
            and (
              watch."AIDexterWatch_TargetID" = job."Job_ID"
              or exists (
                select 1 from public."Customs_Declarations" declaration
                where declaration."CUST_JobID" = job."Job_ID"
                  and declaration."CUST_id" = watch."AIDexterWatch_TargetID"
                  and not declaration."CUST_IsDeleted"
              )
            )
        )
      )
      or (
        v_note."LifecycleNote_SubjectType" = 'booking'
        and exists (
          select 1 from public."Customs_Declarations" declaration
          where declaration."CUST_JobID" = v_note."LifecycleNote_JobID"
            and declaration."CUST_id" = watch."AIDexterWatch_TargetID"
            and not declaration."CUST_IsDeleted"
        )
      )
    );

  return public._multideck_lifecycle_note_json(p_note_id);
exception
  when no_data_found then
    raise exception 'Your signed-in account is not linked to an active Multideck user.' using errcode = '42501';
end;
$$;


ALTER FUNCTION "public"."_multideck_mutate_lifecycle_note"("p_auth_user_id" "uuid", "p_note_id" "uuid", "p_body" "text", "p_delete" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_phone_assert_actor"("p_company_id" "uuid", "p_user_id" "uuid", "p_permission" "text") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if not exists (
    select 1 from public."cmp_Users" actor
    where actor."User_ID" = p_user_id
      and actor."Company_ID" = p_company_id
      and actor."Auth_User_ID" is not null
      and coalesce(actor."User_AccessStatus", 'active') = 'active'
  ) or not public._multideck_crm_has_permission(p_user_id, p_permission) then
    raise exception 'You do not have permission to use Phone calls.' using errcode = '42501';
  end if;
end;
$$;


ALTER FUNCTION "public"."_multideck_phone_assert_actor"("p_company_id" "uuid", "p_user_id" "uuid", "p_permission" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_phone_call_action_watch_source_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_call_id uuid;
  v_company_id uuid;
  v_pending integer;
  v_old_pending integer;
  v_old jsonb;
  v_new jsonb;
begin
  select call."CommCall_ID", call."CommCall_CompanyID"
  into v_call_id, v_company_id
  from public."CRM_CallReviews" review
  join public."Comm_CallLogs" call
    on call."CommCall_ID" = review."CRMCallReview_CommCallID"
  where review."CRMCallReview_ID" = new."CRMCallAction_CallReviewID";

  if v_call_id is null then return new; end if;
  perform public._multideck_phone_call_pause_unauthorised_watches(v_company_id);
  if not exists (
    select 1
    from public."AI_DexterWatches" watch
    where watch."AIDexterWatch_CompanyID" = v_company_id
      and watch."AIDexterWatch_CapabilityCode" = 'phone_calls'
      and watch."AIDexterWatch_StatusCode" = 'active'
      and public._multideck_crm_has_permission(
        watch."AIDexterWatch_OwnerUserID",
        'CRM.PhoneCalls.Read'
      )
      and (
        watch."AIDexterWatch_TargetID" is null
        or watch."AIDexterWatch_TargetID" = v_call_id
      )
  ) then
    return new;
  end if;

  select count(*) filter (
    where action."CRMCallAction_DecisionStatus" = 'pending'
  )::integer
  into v_pending
  from public."CRM_CallActionCandidates" action
  where action."CRMCallAction_CallReviewID" = new."CRMCallAction_CallReviewID";

  v_old_pending := greatest(
    0,
    coalesce(v_pending, 0)
      - case
          when new."CRMCallAction_DecisionStatus" = 'pending' then 1
          else 0
        end
      + case
          when tg_op = 'UPDATE'
            and old."CRMCallAction_DecisionStatus" = 'pending' then 1
          else 0
        end
  );
  v_new := public._multideck_phone_call_watch_snapshot(
    v_company_id,
    v_call_id
  ) || jsonb_build_object(
    'actionStatus', new."CRMCallAction_DecisionStatus"
  );
  v_old := v_new || jsonb_build_object(
    'pendingActionCount', v_old_pending,
    'actionStatus', case
      when tg_op = 'UPDATE' then old."CRMCallAction_DecisionStatus"
      else null
    end
  );

  if v_old is not distinct from v_new then return new; end if;
  insert into public."AI_DexterWatchSignals" (
    "AIDexterWatchSignal_CompanyID",
    "AIDexterWatchSignal_CapabilityCode",
    "AIDexterWatchSignal_SourceTable",
    "AIDexterWatchSignal_SourceID",
    "AIDexterWatchSignal_OldJSON",
    "AIDexterWatchSignal_NewJSON"
  ) values (
    v_company_id,
    'phone_calls',
    'CRM_CallActionCandidates',
    v_call_id,
    v_old,
    v_new
  );
  return new;
end;
$$;


ALTER FUNCTION "public"."_multideck_phone_call_action_watch_source_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_phone_call_enforce_match_consistency"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_expected_org_id uuid;
  v_has_related_record boolean := false;
  v_has_canonical_link boolean := false;
begin
  v_has_canonical_link := new."CommCall_MatchedOrgID" is not null
    or new."CommCall_MatchedContactID" is not null
    or new."CommCall_MatchedLeadID" is not null;

  if v_has_canonical_link and (
    new."CommCall_MatchStatusCode" is distinct from 'matched'
    or coalesce(new."CommCall_MatchMethodCode" not in (
      'user_review',
      'approved_action',
      'approved_action_edited'
    ), true)
  ) then
    raise exception 'Phone-call CRM links require an operator-reviewed or approved match.'
      using errcode = '23514';
  end if;

  if new."CommCall_MatchedContactID" is not null
    and new."CommCall_MatchedLeadID" is not null then
    raise exception 'A phone call cannot be linked to both a contact and a lead.'
      using errcode = '22023';
  end if;

  if new."CommCall_MatchedContactID" is not null then
    select contact."Org_ID"
    into v_expected_org_id
    from public."Org_Contacts" contact
    where contact."OrgContact_ID" = new."CommCall_MatchedContactID";

    if not found then
      raise exception 'The selected phone-call contact no longer exists.'
        using errcode = '22023';
    end if;
    v_has_related_record := true;
  elsif new."CommCall_MatchedLeadID" is not null then
    select lead."CRMLead_OrgID"
    into v_expected_org_id
    from public."CRM_Leads" lead
    where lead."CRMLead_ID" = new."CommCall_MatchedLeadID"
      and not lead."CRMLead_IsDeleted";

    if not found then
      raise exception 'The selected phone-call lead is unavailable.'
        using errcode = '22023';
    end if;
    v_has_related_record := true;
  end if;

  if v_has_related_record then
    if new."CommCall_MatchedOrgID" is null then
      new."CommCall_MatchedOrgID" := v_expected_org_id;
    elsif v_expected_org_id is null
      or new."CommCall_MatchedOrgID" <> v_expected_org_id then
      raise exception 'The phone-call CRM links do not belong to the same company.'
        using errcode = '22023';
    end if;
  end if;

  if new."CommCall_MatchedOrgID" is not null
    and not public.multideck_crm_company_can_access_account(
      new."CommCall_CompanyID",
      new."CommCall_MatchedOrgID"
    ) then
    raise exception 'The phone-call company is outside this workspace.'
      using errcode = '42501';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."_multideck_phone_call_enforce_match_consistency"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_phone_call_merge_fact"("p_current" "text", "p_incoming" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
  select case
    when coalesce(p_incoming, 'unknown') = 'unknown' then coalesce(p_current, 'unknown')
    when coalesce(p_current, 'unknown') = 'unknown' then p_incoming
    when p_current = p_incoming then p_current
    when p_current = 'conflict' then 'conflict'
    else 'conflict'
  end
$$;


ALTER FUNCTION "public"."_multideck_phone_call_merge_fact"("p_current" "text", "p_incoming" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_phone_call_pause_unauthorised_watches"("p_company_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_count integer;
begin
  update public."AI_DexterWatches" watch
  set "AIDexterWatch_StatusCode" = 'paused',
      "AIDexterWatch_IsArmed" = true,
      "AIDexterWatch_UpdatedAt" = now()
  where watch."AIDexterWatch_CompanyID" = p_company_id
    and watch."AIDexterWatch_CapabilityCode" = 'phone_calls'
    and watch."AIDexterWatch_StatusCode" = 'active'
    and not public._multideck_crm_has_permission(
      watch."AIDexterWatch_OwnerUserID",
      'CRM.PhoneCalls.Read'
    );
  get diagnostics v_count = row_count;
  return v_count;
end;
$$;


ALTER FUNCTION "public"."_multideck_phone_call_pause_unauthorised_watches"("p_company_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_phone_call_redact_sync_error"("p_value" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_value text := left(coalesce(p_value, ''), 2000);
begin
  v_value := coalesce(nullif(btrim(v_value), ''), 'Provider sync failed.');
  v_value := replace(replace(replace(v_value, chr(10), ' '), chr(13), ' '), chr(9), ' ');
  v_value := regexp_replace(
    v_value,
    '((authorization|api[_ -]?key|secret|token|password|auth[_ -]?token)[[:space:]]*[:=][[:space:]]*)((basic|bearer)[[:space:]]+)?[^[:space:],;]+',
    '\1[redacted]',
    'gi'
  );
  v_value := regexp_replace(
    v_value,
    '(basic|bearer)[[:space:]]+[A-Za-z0-9+/_=.-]+',
    '\1 [redacted]',
    'gi'
  );
  v_value := regexp_replace(
    v_value,
    '[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+[.][A-Za-z]{2,}',
    '[redacted-email]',
    'gi'
  );
  v_value := regexp_replace(
    v_value,
    '[+]?[0-9][0-9() .-]{7,}[0-9]',
    '[redacted-phone]',
    'g'
  );
  v_value := regexp_replace(
    v_value,
    '[A-Za-z0-9+/_=-]{32,}',
    '[redacted-value]',
    'g'
  );
  v_value := regexp_replace(v_value, '[[:space:]]+', ' ', 'g');
  return left(btrim(v_value), 500);
end;
$$;


ALTER FUNCTION "public"."_multideck_phone_call_redact_sync_error"("p_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_phone_call_review_action_for_actor"("p_company_id" "uuid", "p_user_id" "uuid", "p_call_id" "uuid", "p_action_id" "uuid", "p_decision" "text", "p_edited_title" "text" DEFAULT NULL::"text", "p_scheduled_date" "date" DEFAULT NULL::"date", "p_priority" "text" DEFAULT NULL::"text", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  v_action public."CRM_CallActionCandidates"%rowtype;
  v_review public."CRM_CallReviews"%rowtype;
  v_title text;
  v_todo_title text;
  v_original_title text;
  v_todo jsonb;
  v_lead_id uuid;
begin
  perform public._multideck_phone_assert_actor(p_company_id, p_user_id, 'CRM.PhoneCalls.Review');
  select action.* into v_action
  from public."CRM_CallActionCandidates" action
  join public."CRM_CallReviews" review on review."CRMCallReview_ID" = action."CRMCallAction_CallReviewID"
  join public."Comm_CallLogs" call on call."CommCall_ID" = review."CRMCallReview_CommCallID"
  where action."CRMCallAction_ID" = p_action_id
    and call."CommCall_ID" = p_call_id
    and call."CommCall_CompanyID" = p_company_id
  for update of action;
  if not found then raise exception 'Suggested action not found.' using errcode = 'P0002'; end if;
  select review.* into strict v_review
  from public."CRM_CallReviews" review
  where review."CRMCallReview_ID" = v_action."CRMCallAction_CallReviewID";
  if v_action."CRMCallAction_DecisionStatus" <> 'pending' then
    return jsonb_build_object(
      'id', v_action."CRMCallAction_ID", 'status', v_action."CRMCallAction_DecisionStatus",
      'todoTaskId', v_action."CRMCallAction_TodoTaskID", 'replayed', true
    );
  end if;
  if p_decision not in ('approve', 'dismiss') then
    raise exception 'Choose Approve or Dismiss.' using errcode = '22023';
  end if;
  v_original_title := v_action."CRMCallAction_Title";
  v_title := left(coalesce(nullif(btrim(p_edited_title), ''), v_action."CRMCallAction_Title"), 240);
  v_todo_title := left(regexp_replace(v_title, '\s+—\s+add this to the to-do list\?$', '', 'i'), 240);
  if p_decision = 'approve' and v_action."CRMCallAction_ActionTypeCode" in ('create_todo', 'follow_up') then
    v_todo := public._multideck_todo_create_for_actor(
      p_company_id, p_user_id, v_todo_title, coalesce(p_scheduled_date, current_date), p_priority,
      jsonb_build_array(jsonb_build_object('label', 'Phone call', 'url', '/crm/phone-calls/' || p_call_id::text)),
      jsonb_build_array(jsonb_build_object('label', 'Phone call follow-up', 'href', '/crm/phone-calls/' || p_call_id::text)),
      'dexter_action', null
    );
  elsif p_decision = 'approve' and v_action."CRMCallAction_ActionTypeCode" = 'link_lead' then
    begin v_lead_id := (v_action."CRMCallAction_ActionPayloadJSON" ->> 'leadId')::uuid;
    exception when others then raise exception 'The suggested lead link is invalid.' using errcode = '22023'; end;
    if not exists (
      select 1 from public."CRM_Leads" lead
      left join public."cmp_Users" owner on owner."User_ID" = lead."CRMLead_OwnerUserID"
      where lead."CRMLead_ID" = v_lead_id and not lead."CRMLead_IsDeleted"
        and (owner."Company_ID" = p_company_id or public.multideck_crm_company_can_access_account(p_company_id, lead."CRMLead_OrgID"))
    ) then raise exception 'The suggested lead is outside this workspace.' using errcode = '42501'; end if;
    update public."Comm_CallLogs"
    set "CommCall_MatchedLeadID" = v_lead_id,
        "CommCall_MatchStatusCode" = 'matched',
        "CommCall_MatchMethodCode" = 'approved_action',
        "CommCall_EditVersion" = "CommCall_EditVersion" + 1,
        "CommCall_UpdatedAt" = now(),
        "CommCall_UpdatedBy" = p_user_id
    where "CommCall_ID" = p_call_id;
  elsif p_decision = 'approve' then
    raise exception 'That generated action is review-only and cannot yet change CRM data.' using errcode = '22023';
  end if;

  update public."CRM_CallActionCandidates"
  set "CRMCallAction_Title" = v_title,
      "CRMCallAction_DecisionStatus" = case
        when p_decision = 'dismiss' then 'rejected'
        when p_edited_title is not null then 'edited'
        else 'accepted'
      end,
      "CRMCallAction_DecisionReason" = nullif(left(btrim(coalesce(p_reason, '')), 1000), ''),
      "CRMCallAction_TodoTaskID" = case when v_todo is null then null else (v_todo ->> 'id')::uuid end,
      "CRMCallAction_DecidedAt" = now(),
      "CRMCallAction_DecidedBy" = p_user_id,
      "CRMCallAction_AppliedAt" = case when p_decision = 'approve' then now() else null end,
      "CRMCallAction_EditVersion" = "CRMCallAction_EditVersion" + 1,
      "CRMCallAction_UpdatedAt" = now()
  where "CRMCallAction_ID" = p_action_id
  returning * into v_action;

  insert into public."CRM_CallReviewDecisions" (
    "CRMCallDecision_CallReviewID", "CRMCallDecision_ActionCandidateID", "CRMCallDecision_Decision",
    "CRMCallDecision_OriginalText", "CRMCallDecision_EditedText", "CRMCallDecision_Reason", "CRMCallDecision_DecidedBy"
  ) values (
    v_review."CRMCallReview_ID", p_action_id, p_decision,
    v_original_title, nullif(btrim(p_edited_title), ''), nullif(btrim(p_reason), ''), p_user_id
  );
  insert into public."Comm_CallAccessEvents" (
    "CommCallAccess_CompanyID", "CommCallAccess_CallID", "CommCallAccess_UserID",
    "CommCallAccess_AccessTypeCode", "CommCallAccess_MetadataJSON"
  ) values (p_company_id, p_call_id, p_user_id, 'action_review', jsonb_build_object('actionId', p_action_id, 'decision', p_decision));

  return jsonb_build_object(
    'id', v_action."CRMCallAction_ID",
    'status', v_action."CRMCallAction_DecisionStatus",
    'title', v_action."CRMCallAction_Title",
    'todoTaskId', v_action."CRMCallAction_TodoTaskID",
    'appliedAt', v_action."CRMCallAction_AppliedAt"
  );
end;
$_$;


ALTER FUNCTION "public"."_multideck_phone_call_review_action_for_actor"("p_company_id" "uuid", "p_user_id" "uuid", "p_call_id" "uuid", "p_action_id" "uuid", "p_decision" "text", "p_edited_title" "text", "p_scheduled_date" "date", "p_priority" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_phone_call_review_action_v2_for_actor"("p_company_id" "uuid", "p_user_id" "uuid", "p_call_id" "uuid", "p_action_id" "uuid", "p_decision" "text", "p_edited_title" "text", "p_scheduled_date" "date", "p_priority" "text", "p_reason" "text", "p_edited_lead_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  v_action public."CRM_CallActionCandidates"%rowtype;
  v_review public."CRM_CallReviews"%rowtype;
  v_title text;
  v_todo_title text;
  v_original_title text;
  v_todo jsonb;
  v_original_lead_id uuid;
  v_lead_id uuid;
  v_lead_target_edited boolean := false;
begin
  perform public._multideck_phone_assert_actor(p_company_id, p_user_id, 'CRM.PhoneCalls.Review');
  select action.* into v_action
  from public."CRM_CallActionCandidates" action
  join public."CRM_CallReviews" review on review."CRMCallReview_ID" = action."CRMCallAction_CallReviewID"
  join public."Comm_CallLogs" call on call."CommCall_ID" = review."CRMCallReview_CommCallID"
  where action."CRMCallAction_ID" = p_action_id
    and call."CommCall_ID" = p_call_id
    and call."CommCall_CompanyID" = p_company_id
  for update of action;
  if not found then raise exception 'Suggested action not found.' using errcode = 'P0002'; end if;

  select review.* into strict v_review
  from public."CRM_CallReviews" review
  where review."CRMCallReview_ID" = v_action."CRMCallAction_CallReviewID";

  if v_action."CRMCallAction_DecisionStatus" <> 'pending' then
    return jsonb_build_object(
      'id', v_action."CRMCallAction_ID",
      'status', v_action."CRMCallAction_DecisionStatus",
      'todoTaskId', v_action."CRMCallAction_TodoTaskID",
      'leadId', nullif(v_action."CRMCallAction_ActionPayloadJSON" ->> 'leadId', ''),
      'replayed', true
    );
  end if;
  if p_decision not in ('approve', 'dismiss') then
    raise exception 'Choose Approve or Dismiss.' using errcode = '22023';
  end if;
  if p_edited_lead_id is not null and v_action."CRMCallAction_ActionTypeCode" <> 'link_lead' then
    raise exception 'A lead target can only be edited for a lead-link suggestion.' using errcode = '22023';
  end if;

  v_original_title := v_action."CRMCallAction_Title";
  v_title := left(coalesce(nullif(btrim(p_edited_title), ''), v_action."CRMCallAction_Title"), 240);
  v_todo_title := left(regexp_replace(v_title, '\s+—\s+add this to the to-do list\?$', '', 'i'), 240);

  if v_action."CRMCallAction_ActionTypeCode" = 'link_lead' then
    begin
      v_original_lead_id := nullif(v_action."CRMCallAction_ActionPayloadJSON" ->> 'leadId', '')::uuid;
    exception when invalid_text_representation then
      v_original_lead_id := null;
    end;
  end if;

  if p_decision = 'approve' and v_action."CRMCallAction_ActionTypeCode" in ('create_todo', 'follow_up') then
    v_todo := public._multideck_todo_create_for_actor(
      p_company_id, p_user_id, v_todo_title, coalesce(p_scheduled_date, current_date), p_priority,
      jsonb_build_array(jsonb_build_object('label', 'Phone call', 'url', '/crm/phone-calls/' || p_call_id::text)),
      jsonb_build_array(jsonb_build_object('label', 'Phone call follow-up', 'href', '/crm/phone-calls/' || p_call_id::text)),
      'dexter_action', null
    );
  elsif p_decision = 'approve' and v_action."CRMCallAction_ActionTypeCode" = 'link_lead' then
    v_lead_id := coalesce(p_edited_lead_id, v_original_lead_id);
    if v_lead_id is null then
      raise exception 'The suggested lead link is invalid.' using errcode = '22023';
    end if;
    if not exists (
      select 1 from public."CRM_Leads" lead
      left join public."cmp_Users" owner on owner."User_ID" = lead."CRMLead_OwnerUserID"
      where lead."CRMLead_ID" = v_lead_id and not lead."CRMLead_IsDeleted"
        and (owner."Company_ID" = p_company_id or public.multideck_crm_company_can_access_account(p_company_id, lead."CRMLead_OrgID"))
    ) then raise exception 'The selected lead is outside this workspace.' using errcode = '42501'; end if;

    v_lead_target_edited := p_edited_lead_id is not null
      and p_edited_lead_id is distinct from v_original_lead_id;
    update public."Comm_CallLogs"
    set "CommCall_MatchedLeadID" = v_lead_id,
        "CommCall_MatchStatusCode" = 'matched',
        "CommCall_MatchMethodCode" = case when v_lead_target_edited then 'approved_action_edited' else 'approved_action' end,
        "CommCall_EditVersion" = "CommCall_EditVersion" + 1,
        "CommCall_UpdatedAt" = now(),
        "CommCall_UpdatedBy" = p_user_id
    where "CommCall_ID" = p_call_id;
  elsif p_decision = 'approve' then
    raise exception 'That generated action is review-only and cannot yet change CRM data.' using errcode = '22023';
  end if;

  update public."CRM_CallActionCandidates"
  set "CRMCallAction_Title" = v_title,
      "CRMCallAction_ActionPayloadJSON" = case
        when p_decision = 'approve' and v_action."CRMCallAction_ActionTypeCode" = 'link_lead'
          then jsonb_set(coalesce("CRMCallAction_ActionPayloadJSON", '{}'::jsonb), '{leadId}', to_jsonb(v_lead_id::text), true)
        else "CRMCallAction_ActionPayloadJSON"
      end,
      "CRMCallAction_DecisionStatus" = case
        when p_decision = 'dismiss' then 'rejected'
        when p_edited_title is not null or v_lead_target_edited then 'edited'
        else 'accepted'
      end,
      "CRMCallAction_DecisionReason" = nullif(left(btrim(coalesce(p_reason, '')), 1000), ''),
      "CRMCallAction_TodoTaskID" = case when v_todo is null then null else (v_todo ->> 'id')::uuid end,
      "CRMCallAction_DecidedAt" = now(),
      "CRMCallAction_DecidedBy" = p_user_id,
      "CRMCallAction_AppliedAt" = case when p_decision = 'approve' then now() else null end,
      "CRMCallAction_EditVersion" = "CRMCallAction_EditVersion" + 1,
      "CRMCallAction_UpdatedAt" = now()
  where "CRMCallAction_ID" = p_action_id
  returning * into v_action;

  insert into public."CRM_CallReviewDecisions" (
    "CRMCallDecision_CallReviewID", "CRMCallDecision_ActionCandidateID", "CRMCallDecision_Decision",
    "CRMCallDecision_OriginalText", "CRMCallDecision_EditedText", "CRMCallDecision_Reason",
    "CRMCallDecision_DecidedBy", "CRMCallDecision_MetadataJSON"
  ) values (
    v_review."CRMCallReview_ID", p_action_id, p_decision,
    v_original_title, nullif(btrim(p_edited_title), ''), nullif(btrim(p_reason), ''), p_user_id,
    jsonb_strip_nulls(jsonb_build_object(
      'actionType', v_action."CRMCallAction_ActionTypeCode",
      'originalLeadId', v_original_lead_id,
      'reviewedLeadId', v_lead_id,
      'leadTargetEdited', v_lead_target_edited
    ))
  );
  insert into public."Comm_CallAccessEvents" (
    "CommCallAccess_CompanyID", "CommCallAccess_CallID", "CommCallAccess_UserID",
    "CommCallAccess_AccessTypeCode", "CommCallAccess_MetadataJSON"
  ) values (
    p_company_id, p_call_id, p_user_id, 'action_review',
    jsonb_strip_nulls(jsonb_build_object(
      'actionId', p_action_id,
      'decision', p_decision,
      'reviewedLeadId', v_lead_id,
      'leadTargetEdited', v_lead_target_edited
    ))
  );

  return jsonb_build_object(
    'id', v_action."CRMCallAction_ID",
    'status', v_action."CRMCallAction_DecisionStatus",
    'title', v_action."CRMCallAction_Title",
    'todoTaskId', v_action."CRMCallAction_TodoTaskID",
    'leadId', v_lead_id,
    'appliedAt', v_action."CRMCallAction_AppliedAt"
  );
end;
$_$;


ALTER FUNCTION "public"."_multideck_phone_call_review_action_v2_for_actor"("p_company_id" "uuid", "p_user_id" "uuid", "p_call_id" "uuid", "p_action_id" "uuid", "p_decision" "text", "p_edited_title" "text", "p_scheduled_date" "date", "p_priority" "text", "p_reason" "text", "p_edited_lead_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_phone_call_review_watch_source_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_call_id uuid;
  v_company_id uuid;
  v_old jsonb;
  v_new jsonb;
begin
  if tg_op = 'INSERT'
    and nullif(btrim(new."CRMCallReview_CallReason"), '') is null then
    return new;
  end if;
  if tg_op = 'UPDATE'
    and old."CRMCallReview_CallReason"
      is not distinct from new."CRMCallReview_CallReason" then
    return new;
  end if;

  select call."CommCall_ID", call."CommCall_CompanyID"
  into v_call_id, v_company_id
  from public."Comm_CallLogs" call
  where call."CommCall_ID" = new."CRMCallReview_CommCallID";

  if v_call_id is null then return new; end if;
  perform public._multideck_phone_call_pause_unauthorised_watches(v_company_id);
  if not exists (
    select 1
    from public."AI_DexterWatches" watch
    where watch."AIDexterWatch_CompanyID" = v_company_id
      and watch."AIDexterWatch_CapabilityCode" = 'phone_calls'
      and watch."AIDexterWatch_StatusCode" = 'active'
      and public._multideck_crm_has_permission(
        watch."AIDexterWatch_OwnerUserID",
        'CRM.PhoneCalls.Read'
      )
      and (
        watch."AIDexterWatch_TargetID" is null
        or watch."AIDexterWatch_TargetID" = v_call_id
      )
  ) then
    return new;
  end if;

  v_new := public._multideck_phone_call_watch_snapshot(
    v_company_id,
    v_call_id
  );
  v_old := v_new || jsonb_build_object(
    'callReason', case
      when tg_op = 'UPDATE' then old."CRMCallReview_CallReason"
      else null
    end
  );

  if v_old is not distinct from v_new then return new; end if;
  insert into public."AI_DexterWatchSignals" (
    "AIDexterWatchSignal_CompanyID",
    "AIDexterWatchSignal_CapabilityCode",
    "AIDexterWatchSignal_SourceTable",
    "AIDexterWatchSignal_SourceID",
    "AIDexterWatchSignal_OldJSON",
    "AIDexterWatchSignal_NewJSON"
  ) values (
    v_company_id,
    'phone_calls',
    'CRM_CallReviews',
    v_call_id,
    v_old,
    v_new
  );
  return new;
end;
$$;


ALTER FUNCTION "public"."_multideck_phone_call_review_watch_source_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_phone_call_sync_confirmed_entity_links"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_review_id uuid;
  v_is_approved_match boolean := false;
begin
  select review."CRMCallReview_ID"
  into v_review_id
  from public."CRM_CallReviews" review
  where review."CRMCallReview_CommCallID" = new."CommCall_ID";

  if v_review_id is null then
    return new;
  end if;

  v_is_approved_match := new."CommCall_MatchStatusCode" = 'matched'
    and new."CommCall_MatchMethodCode" in (
      'user_review',
      'approved_action',
      'approved_action_edited'
    );

  -- Confirmed relationship rows mirror the canonical approved match exactly.
  -- Unconfirmed extraction candidates remain intact for the review rail.
  delete from public."CRM_CallEntityLinks" link
  where link."CRMCallEntity_CallReviewID" = v_review_id
    and link."CRMCallEntity_IsConfirmed" = true
    and link."CRMCallEntity_TargetTable" in (
      'Org_Master',
      'Org_Contacts',
      'CRM_Leads'
    );

  if not v_is_approved_match then
    return new;
  end if;

  if new."CommCall_MatchedOrgID" is not null then
    insert into public."CRM_CallEntityLinks" (
      "CRMCallEntity_CallReviewID",
      "CRMCallEntity_EntityType",
      "CRMCallEntity_EntityValue",
      "CRMCallEntity_TargetTable",
      "CRMCallEntity_TargetID",
      "CRMCallEntity_ConfidenceScore",
      "CRMCallEntity_IsConfirmed"
    ) values (
      v_review_id,
      'company',
      new."CommCall_MatchedOrgID"::text,
      'Org_Master',
      new."CommCall_MatchedOrgID",
      1,
      true
    );
  end if;

  if new."CommCall_MatchedContactID" is not null then
    insert into public."CRM_CallEntityLinks" (
      "CRMCallEntity_CallReviewID",
      "CRMCallEntity_EntityType",
      "CRMCallEntity_EntityValue",
      "CRMCallEntity_TargetTable",
      "CRMCallEntity_TargetID",
      "CRMCallEntity_ConfidenceScore",
      "CRMCallEntity_IsConfirmed"
    ) values (
      v_review_id,
      'contact',
      new."CommCall_MatchedContactID"::text,
      'Org_Contacts',
      new."CommCall_MatchedContactID",
      1,
      true
    );
  end if;

  if new."CommCall_MatchedLeadID" is not null then
    insert into public."CRM_CallEntityLinks" (
      "CRMCallEntity_CallReviewID",
      "CRMCallEntity_EntityType",
      "CRMCallEntity_EntityValue",
      "CRMCallEntity_TargetTable",
      "CRMCallEntity_TargetID",
      "CRMCallEntity_ConfidenceScore",
      "CRMCallEntity_IsConfirmed"
    ) values (
      v_review_id,
      'lead',
      new."CommCall_MatchedLeadID"::text,
      'CRM_Leads',
      new."CommCall_MatchedLeadID",
      1,
      true
    );
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."_multideck_phone_call_sync_confirmed_entity_links"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_multideck_phone_call_sync_confirmed_entity_links"() IS 'Mirrors only operator-reviewed or approved phone-call CRM matches into confirmed relationship rows for Lead and Company record views.';



CREATE OR REPLACE FUNCTION "public"."_multideck_phone_call_watch_snapshot"("p_company_id" "uuid", "p_call_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select coalesce((
    select jsonb_build_object(
      'outcome', call."CommCall_OutcomeCode",
      'transferStatus', call."CommCall_TransferStatusCode",
      'transcriptStatus', call."CommCall_TranscriptStatusCode",
      'matchStatus', call."CommCall_MatchStatusCode",
      'companyId', call."CommCall_MatchedOrgID",
      'companyName', organisation."Org_Name",
      'contactId', call."CommCall_MatchedContactID",
      'leadId', call."CommCall_MatchedLeadID",
      'callReason', review."CRMCallReview_CallReason",
      'pendingActionCount', coalesce(action_count.pending_count, 0),
      'aiDisclosureStatus', call."CommCall_AIDisclosureStatusCode",
      'recordingConsentStatus', call."CommCall_RecordingConsentStatusCode",
      'transcriptionConsentStatus', call."CommCall_TranscriptionConsentStatusCode",
      'recordingStatus', call."CommCall_RecordingStatusCode"
    )
    from public."Comm_CallLogs" call
    left join public."Org_Master" organisation
      on organisation."Org_id" = call."CommCall_MatchedOrgID"
    left join public."CRM_CallReviews" review
      on review."CRMCallReview_CommCallID" = call."CommCall_ID"
      and review."CRMCallReview_CompanyID" = p_company_id
    left join lateral (
      select count(*) filter (
        where action."CRMCallAction_DecisionStatus" = 'pending'
      )::integer as pending_count
      from public."CRM_CallActionCandidates" action
      where action."CRMCallAction_CallReviewID" = review."CRMCallReview_ID"
    ) action_count on true
    where call."CommCall_ID" = p_call_id
      and call."CommCall_CompanyID" = p_company_id
  ), '{}'::jsonb);
$$;


ALTER FUNCTION "public"."_multideck_phone_call_watch_snapshot"("p_company_id" "uuid", "p_call_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_phone_call_watch_source_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_old jsonb := '{}'::jsonb;
  v_new jsonb;
  v_old_company_name text;
begin
  if new."CommCall_CompanyID" is null then return new; end if;
  perform public._multideck_phone_call_pause_unauthorised_watches(
    new."CommCall_CompanyID"
  );
  if not exists (
    select 1
    from public."AI_DexterWatches" watch
    where watch."AIDexterWatch_CompanyID" = new."CommCall_CompanyID"
      and watch."AIDexterWatch_CapabilityCode" = 'phone_calls'
      and watch."AIDexterWatch_StatusCode" = 'active'
      and public._multideck_crm_has_permission(
        watch."AIDexterWatch_OwnerUserID",
        'CRM.PhoneCalls.Read'
      )
      and (
        watch."AIDexterWatch_TargetID" is null
        or watch."AIDexterWatch_TargetID" = new."CommCall_ID"
      )
  ) then
    return new;
  end if;

  v_new := public._multideck_phone_call_watch_snapshot(
    new."CommCall_CompanyID",
    new."CommCall_ID"
  );

  if tg_op = 'UPDATE' then
    select organisation."Org_Name"
    into v_old_company_name
    from public."Org_Master" organisation
    where organisation."Org_id" = old."CommCall_MatchedOrgID";

    v_old := v_new || jsonb_build_object(
      'outcome', old."CommCall_OutcomeCode",
      'transferStatus', old."CommCall_TransferStatusCode",
      'transcriptStatus', old."CommCall_TranscriptStatusCode",
      'matchStatus', old."CommCall_MatchStatusCode",
      'companyId', old."CommCall_MatchedOrgID",
      'companyName', v_old_company_name,
      'contactId', old."CommCall_MatchedContactID",
      'leadId', old."CommCall_MatchedLeadID",
      'aiDisclosureStatus', old."CommCall_AIDisclosureStatusCode",
      'recordingConsentStatus', old."CommCall_RecordingConsentStatusCode",
      'transcriptionConsentStatus', old."CommCall_TranscriptionConsentStatusCode",
      'recordingStatus', old."CommCall_RecordingStatusCode"
    );
  end if;

  if v_old is not distinct from v_new then return new; end if;
  insert into public."AI_DexterWatchSignals" (
    "AIDexterWatchSignal_CompanyID",
    "AIDexterWatchSignal_CapabilityCode",
    "AIDexterWatchSignal_SourceTable",
    "AIDexterWatchSignal_SourceID",
    "AIDexterWatchSignal_OldJSON",
    "AIDexterWatchSignal_NewJSON"
  ) values (
    new."CommCall_CompanyID",
    'phone_calls',
    'Comm_CallLogs',
    new."CommCall_ID",
    v_old,
    v_new
  );
  return new;
end;
$$;


ALTER FUNCTION "public"."_multideck_phone_call_watch_source_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_phone_match_text"("p_value" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
  select nullif(btrim(regexp_replace(lower(coalesce(p_value, '')), '[^[:alnum:]]+', ' ', 'g')), '')
$$;


ALTER FUNCTION "public"."_multideck_phone_match_text"("p_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_phone_normalize"("p_value" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
  select nullif(
    case
      when btrim(coalesce(p_value, '')) like '00%' then '+' || substr(regexp_replace(coalesce(p_value, ''), '[^0-9]', '', 'g'), 3)
      else regexp_replace(
        regexp_replace(coalesce(p_value, ''), '^\s*(\+[0-9]{1,3})\s*\(0\)', '\1'),
        '[^0-9+]', '', 'g'
      )
    end,
    ''
  )
$$;


ALTER FUNCTION "public"."_multideck_phone_normalize"("p_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_refresh_dexter_email_search_document"("p_message_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  insert into public."AI_DexterEmailSearchDocuments" (
    "AIDexterEmailSearch_MessageID",
    "AIDexterEmailSearch_Document",
    "AIDexterEmailSearch_UpdatedAt"
  )
  select
    message."CommMessage_ID",
    setweight(to_tsvector('simple'::regconfig, coalesce(message."CommMessage_Subject", '')), 'A') ||
    setweight(to_tsvector(
      'simple'::regconfig,
      coalesce(participants.participant_text, '') || ' ' ||
      coalesce(attachments.attachment_text, '')
    ), 'B') ||
    setweight(to_tsvector(
      'simple'::regconfig,
      coalesce(message."CommMessage_BodyPreview", '') || ' ' ||
      coalesce(message."CommMessage_BodyText", '')
    ), 'C'),
    now()
  from public."Comm_Messages" message
  left join lateral (
    select string_agg(
      coalesce(recipient."CommRecipient_Address", '') || ' ' ||
      coalesce(recipient."CommRecipient_NormalizedAddress", '') || ' ' ||
      coalesce(recipient."CommRecipient_DisplayNameSnapshot", ''),
      ' '
    ) as participant_text
    from public."Comm_MessageRecipients" recipient
    where recipient."CommRecipient_MessageID" = message."CommMessage_ID"
  ) participants on true
  left join lateral (
    select string_agg(
      regexp_replace(coalesce(attachment."CommAttachment_FileName", ''), '[^[:alnum:]@]+', ' ', 'g'),
      ' '
    ) as attachment_text
    from public."Comm_MessageAttachments" attachment
    where attachment."CommAttachment_MessageID" = message."CommMessage_ID"
      and not attachment."CommAttachment_IsInline"
  ) attachments on true
  where message."CommMessage_ID" = p_message_id
  on conflict ("AIDexterEmailSearch_MessageID") do update
  set
    "AIDexterEmailSearch_Document" = excluded."AIDexterEmailSearch_Document",
    "AIDexterEmailSearch_UpdatedAt" = excluded."AIDexterEmailSearch_UpdatedAt";

  if not found then
    delete from public."AI_DexterEmailSearchDocuments"
    where "AIDexterEmailSearch_MessageID" = p_message_id;
  end if;
end;
$$;


ALTER FUNCTION "public"."_multideck_refresh_dexter_email_search_document"("p_message_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_refresh_dexter_email_search_from_attachment"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_old_message_id uuid := case when tg_op in ('UPDATE', 'DELETE') then old."CommAttachment_MessageID" else null end;
  v_new_message_id uuid := case when tg_op in ('INSERT', 'UPDATE') then new."CommAttachment_MessageID" else null end;
begin
  if v_old_message_id is not null then
    perform public._multideck_refresh_dexter_email_search_document(v_old_message_id);
  end if;
  if v_new_message_id is not null and v_new_message_id is distinct from v_old_message_id then
    perform public._multideck_refresh_dexter_email_search_document(v_new_message_id);
  end if;
  return null;
end;
$$;


