CREATE OR REPLACE FUNCTION "public"."_multideck_refresh_retained_email_threads"("p_thread_ids" "uuid"[]) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_thread_id uuid;
  v_latest public."Comm_Messages";
begin
  foreach v_thread_id in array coalesce(p_thread_ids, '{}'::uuid[])
  loop
    select message.*
    into v_latest
    from public."Comm_Messages" message
    where message."CommMessage_ThreadID" = v_thread_id
      and not message."CommMessage_IsDeleted"
    order by coalesce(
      message."CommMessage_MessageDate",
      message."CommMessage_ReceivedAt",
      message."CommMessage_SentAt",
      message."CommMessage_CreatedAt"
    ) desc, message."CommMessage_ID" desc
    limit 1;

    if found then
      update public."Comm_Threads"
      set "CommThread_LastMessageID" = v_latest."CommMessage_ID",
          "CommThread_LastMessageAt" = coalesce(
            v_latest."CommMessage_MessageDate",
            v_latest."CommMessage_ReceivedAt",
            v_latest."CommMessage_SentAt",
            v_latest."CommMessage_CreatedAt"
          ),
          "CommThread_Subject" = coalesce(
            v_latest."CommMessage_Subject",
            "CommThread_Subject"
          ),
          "CommThread_IsDeleted" = false,
          "CommThread_UpdatedAt" = now()
      where "CommThread_ID" = v_thread_id;
    else
      update public."Comm_Threads"
      set "CommThread_LastMessageID" = null,
          "CommThread_LastMessageAt" = null,
          "CommThread_IsDeleted" = case
            when "CommThread_SourceTypeCode" = 'provider_sync' then true
            else "CommThread_IsDeleted"
          end,
          "CommThread_UpdatedAt" = now()
      where "CommThread_ID" = v_thread_id;
    end if;
  end loop;
end;
$$;


ALTER FUNCTION "public"."_multideck_refresh_retained_email_threads"("p_thread_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_set_marketing_consent"("p_record_type" "text", "p_record_id" "uuid", "p_opted_in" boolean, "p_source" "text", "p_reason" "text", "p_actor" "uuid", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_type text := lower(btrim(coalesce(p_record_type, '')));
  v_now timestamptz := now();
  v_lead uuid;
  v_contact uuid;
  v_org uuid;
  v_email text;
begin
  if v_type = 'lead' then
    update public."CRM_Leads"
    set "CRMLead_MarketingOptIn" = p_opted_in,
        "CRMLead_MarketingConsentSource" = left(coalesce(nullif(btrim(p_source), ''), 'manual_override'), 120),
        "CRMLead_MarketingConsentUpdatedAt" = v_now,
        "CRMLead_UpdatedAt" = v_now,
        "CRMLead_UpdatedBy" = coalesce(p_actor, "CRMLead_UpdatedBy")
    where "CRMLead_ID" = p_record_id and not "CRMLead_IsDeleted"
    returning "CRMLead_ID", "CRMLead_PrimaryContactID", "CRMLead_OrgID", lower(nullif(btrim("CRMLead_Email"), ''))
      into v_lead, v_contact, v_org, v_email;
    if v_lead is null then raise exception 'Lead not found.' using errcode = 'P0002'; end if;

    if v_contact is not null then
      update public."Org_Contacts"
      set "OrgContact_MarketingOptIn" = p_opted_in,
          "OrgContact_MarketingConsentSource" = left(coalesce(nullif(btrim(p_source), ''), 'manual_override'), 120),
          "OrgContact_MarketingConsentUpdatedAt" = v_now
      where "OrgContact_ID" = v_contact;
    end if;
  elsif v_type = 'contact' then
    update public."Org_Contacts"
    set "OrgContact_MarketingOptIn" = p_opted_in,
        "OrgContact_MarketingConsentSource" = left(coalesce(nullif(btrim(p_source), ''), 'manual_override'), 120),
        "OrgContact_MarketingConsentUpdatedAt" = v_now
    where "OrgContact_ID" = p_record_id
    returning "OrgContact_ID", "Org_ID" into v_contact, v_org;
    if v_contact is null then raise exception 'Contact not found.' using errcode = 'P0002'; end if;
    select lower(nullif(btrim(email."OrgContactEmail_Email"), '')) into v_email
    from public."OrgContact_Emails" email
    where email."OrgContact_ID" = v_contact
    order by email."OrgContactEmail_Type", email."OrgContactEmail_ID" limit 1;
  elsif v_type = 'customer' then
    update public."Org_Master"
    set "Org_MarketingOptIn" = p_opted_in,
        "Org_MarketingConsentSource" = left(coalesce(nullif(btrim(p_source), ''), 'manual_override'), 120),
        "Org_MarketingConsentUpdatedAt" = v_now,
        "Org_CRMUpdatedAt" = v_now
    where "Org_id" = p_record_id
    returning "Org_id" into v_org;
    if v_org is null then raise exception 'Customer not found.' using errcode = 'P0002'; end if;
  else
    raise exception 'Choose lead, contact or customer.' using errcode = '22023';
  end if;

  insert into public."Comm_ConsentPreferences"(
    "CommConsent_ChannelCode", "CommConsent_LeadID", "CommConsent_OrgID", "CommConsent_ContactID",
    "CommConsent_Address", "CommConsent_NormalizedAddress", "CommConsent_StatusCode",
    "CommConsent_LawfulBasis", "CommConsent_Source", "CommConsent_Reason", "CommConsent_EffectiveAt",
    "CommConsent_CapturedBy", "CommConsent_MetadataJSON"
  ) values (
    'email', v_lead, v_org, v_contact, v_email, v_email,
    case when p_opted_in then 'opted_in' else 'opted_out' end,
    case when p_source = 'contact_card' then 'explicit_consent' else 'manual_override' end,
    left(coalesce(nullif(btrim(p_source), ''), 'manual_override'), 120), nullif(btrim(p_reason), ''), v_now,
    p_actor, coalesce(p_metadata, '{}'::jsonb) || jsonb_build_object('recordType', v_type, 'recordId', p_record_id)
  );

  return jsonb_build_object(
    'recordType', v_type,
    'recordId', p_record_id,
    'marketingOptIn', p_opted_in,
    'marketingConsentSource', left(coalesce(nullif(btrim(p_source), ''), 'manual_override'), 120),
    'marketingConsentUpdatedAt', v_now
  );
end;
$$;


ALTER FUNCTION "public"."_multideck_set_marketing_consent"("p_record_type" "text", "p_record_id" "uuid", "p_opted_in" boolean, "p_source" "text", "p_reason" "text", "p_actor" "uuid", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_todo_assert_actor"("p_company_id" "uuid", "p_user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if not exists (
    select 1 from public."cmp_Users" profile
    where profile."User_ID" = p_user_id
      and profile."Company_ID" = p_company_id
      and coalesce(profile."User_AccessStatus", 'active') = 'active'
  ) then
    raise exception 'Your Multideck account is no longer available.' using errcode = '42501';
  end if;
end;
$$;


ALTER FUNCTION "public"."_multideck_todo_assert_actor"("p_company_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_todo_clean_references"("p_value" "jsonb", "p_kind" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_result jsonb := '[]'::jsonb;
  v_item jsonb;
  v_label text;
  v_target text;
begin
  if p_value is null or p_value = 'null'::jsonb then
    return v_result;
  end if;
  if jsonb_typeof(p_value) <> 'array' or jsonb_array_length(p_value) > 20 then
    raise exception 'Add no more than 20 task references.' using errcode = '22023';
  end if;
  if p_kind not in ('link','tag') then
    raise exception 'That task reference type is not supported.' using errcode = '22023';
  end if;

  for v_item in select value from jsonb_array_elements(p_value)
  loop
    if jsonb_typeof(v_item) <> 'object' then
      raise exception 'Each task reference needs a label.' using errcode = '22023';
    end if;
    v_label := left(btrim(coalesce(v_item->>'label','')), 120);
    v_target := left(btrim(coalesce(v_item->>case when p_kind = 'link' then 'url' else 'href' end,'')), 2000);
    if v_label = '' then
      raise exception 'Each task reference needs a label.' using errcode = '22023';
    end if;
    if p_kind = 'link' and v_target = '' then
      raise exception 'Each task link needs a destination.' using errcode = '22023';
    end if;
    if v_target <> '' and v_target !~* '^(https?://|mailto:|/)' then
      raise exception 'Task links must use HTTPS, HTTP, mailto, or a Multideck route.' using errcode = '22023';
    end if;
    if p_kind = 'link' then
      v_result := v_result || jsonb_build_array(jsonb_build_object('label',v_label,'url',v_target));
    else
      v_result := v_result || jsonb_build_array(
        jsonb_strip_nulls(jsonb_build_object('label',v_label,'href',nullif(v_target,'')))
      );
    end if;
  end loop;
  return v_result;
end;
$$;


ALTER FUNCTION "public"."_multideck_todo_clean_references"("p_value" "jsonb", "p_kind" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_todo_create_for_actor"("p_company_id" "uuid", "p_user_id" "uuid", "p_title" "text", "p_scheduled_date" "date", "p_priority" "text", "p_links" "jsonb", "p_tags" "jsonb", "p_source_code" "text", "p_source_message_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_task public."OPS_UserTasks";
  v_title text := left(btrim(coalesce(p_title,'')), 240);
  v_priority text := nullif(lower(btrim(coalesce(p_priority,''))), '');
  v_source text := lower(btrim(coalesce(p_source_code,'manual')));
begin
  perform public._multideck_todo_assert_actor(p_company_id, p_user_id);
  if v_title = '' then raise exception 'Give the task a title.' using errcode = '22023'; end if;
  if v_priority is not null and v_priority not in ('low','medium','high','urgent') then
    raise exception 'Choose low, medium, high, urgent, or no priority.' using errcode = '22023';
  end if;
  if v_source not in ('manual','dexter_context','dexter_action') then v_source := 'manual'; end if;

  if p_source_message_id is not null then
    select * into v_task from public."OPS_UserTasks" task
    where task."TodoTask_OwnerUserID" = p_user_id
      and task."TodoTask_SourceDexterMessageID" = p_source_message_id
      and not task."TodoTask_IsDeleted"
    limit 1;
    if found then return public._multideck_todo_task_json(v_task); end if;
  end if;

  begin
    insert into public."OPS_UserTasks" (
      "TodoTask_CompanyID", "TodoTask_OwnerUserID", "TodoTask_Title",
      "TodoTask_ScheduledDate", "TodoTask_PriorityCode", "TodoTask_LinksJSON", "TodoTask_TagsJSON",
      "TodoTask_SourceCode", "TodoTask_SourceDexterMessageID", "TodoTask_CreatedBy", "TodoTask_UpdatedBy"
    ) values (
      p_company_id, p_user_id, v_title, coalesce(p_scheduled_date,current_date), v_priority,
      public._multideck_todo_clean_references(coalesce(p_links,'[]'::jsonb),'link'),
      public._multideck_todo_clean_references(coalesce(p_tags,'[]'::jsonb),'tag'),
      v_source, p_source_message_id, p_user_id, p_user_id
    ) returning * into v_task;
  exception when unique_violation then
    select * into v_task from public."OPS_UserTasks" task
    where task."TodoTask_OwnerUserID" = p_user_id
      and task."TodoTask_SourceDexterMessageID" = p_source_message_id
      and not task."TodoTask_IsDeleted"
    limit 1;
    if not found then raise; end if;
  end;
  return public._multideck_todo_task_json(v_task);
end;
$$;


ALTER FUNCTION "public"."_multideck_todo_create_for_actor"("p_company_id" "uuid", "p_user_id" "uuid", "p_title" "text", "p_scheduled_date" "date", "p_priority" "text", "p_links" "jsonb", "p_tags" "jsonb", "p_source_code" "text", "p_source_message_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_todo_delete_for_actor"("p_company_id" "uuid", "p_user_id" "uuid", "p_task_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_task public."OPS_UserTasks";
begin
  perform public._multideck_todo_assert_actor(p_company_id, p_user_id);
  update public."OPS_UserTasks" set
    "TodoTask_IsDeleted" = true,
    "TodoTask_EditVersion" = "TodoTask_EditVersion" + 1,
    "TodoTask_UpdatedBy" = p_user_id,
    "TodoTask_UpdatedAt" = now()
  where "TodoTask_ID" = p_task_id
    and "TodoTask_CompanyID" = p_company_id
    and "TodoTask_OwnerUserID" = p_user_id
    and not "TodoTask_IsDeleted"
  returning * into v_task;
  if not found then raise exception 'Task not found.' using errcode = 'P0002'; end if;
  return jsonb_build_object('id',v_task."TodoTask_ID",'deleted',true);
end;
$$;


ALTER FUNCTION "public"."_multideck_todo_delete_for_actor"("p_company_id" "uuid", "p_user_id" "uuid", "p_task_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."OPS_UserTasks" (
    "TodoTask_ID" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "TodoTask_CompanyID" "uuid" NOT NULL,
    "TodoTask_OwnerUserID" "uuid" NOT NULL,
    "TodoTask_Title" character varying(240) NOT NULL,
    "TodoTask_ScheduledDate" "date" NOT NULL,
    "TodoTask_PriorityCode" character varying(12),
    "TodoTask_StatusCode" character varying(16) DEFAULT 'open'::character varying NOT NULL,
    "TodoTask_CompletedAt" timestamp with time zone,
    "TodoTask_LinksJSON" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "TodoTask_TagsJSON" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "TodoTask_SourceCode" character varying(24) DEFAULT 'manual'::character varying NOT NULL,
    "TodoTask_SourceDexterMessageID" "uuid",
    "TodoTask_EditVersion" integer DEFAULT 1 NOT NULL,
    "TodoTask_CreatedBy" "uuid" NOT NULL,
    "TodoTask_UpdatedBy" "uuid" NOT NULL,
    "TodoTask_CreatedAt" timestamp with time zone DEFAULT "now"() NOT NULL,
    "TodoTask_UpdatedAt" timestamp with time zone DEFAULT "now"() NOT NULL,
    "TodoTask_IsDeleted" boolean DEFAULT false NOT NULL,
    CONSTRAINT "CK_OPS_UserTasks_completion" CHECK ((((("TodoTask_StatusCode")::"text" = 'completed'::"text") AND ("TodoTask_CompletedAt" IS NOT NULL)) OR ((("TodoTask_StatusCode")::"text" = 'open'::"text") AND ("TodoTask_CompletedAt" IS NULL)))),
    CONSTRAINT "CK_OPS_UserTasks_links_array" CHECK (("jsonb_typeof"("TodoTask_LinksJSON") = 'array'::"text")),
    CONSTRAINT "CK_OPS_UserTasks_priority" CHECK ((("TodoTask_PriorityCode" IS NULL) OR (("TodoTask_PriorityCode")::"text" = ANY ((ARRAY['low'::character varying, 'medium'::character varying, 'high'::character varying, 'urgent'::character varying])::"text"[])))),
    CONSTRAINT "CK_OPS_UserTasks_source" CHECK ((("TodoTask_SourceCode")::"text" = ANY ((ARRAY['manual'::character varying, 'dexter_context'::character varying, 'dexter_action'::character varying])::"text"[]))),
    CONSTRAINT "CK_OPS_UserTasks_status" CHECK ((("TodoTask_StatusCode")::"text" = ANY ((ARRAY['open'::character varying, 'completed'::character varying])::"text"[]))),
    CONSTRAINT "CK_OPS_UserTasks_tags_array" CHECK (("jsonb_typeof"("TodoTask_TagsJSON") = 'array'::"text")),
    CONSTRAINT "CK_OPS_UserTasks_title" CHECK (("btrim"(("TodoTask_Title")::"text") <> ''::"text"))
);


ALTER TABLE "public"."OPS_UserTasks" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_todo_task_json"("p_task" "public"."OPS_UserTasks") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
  select jsonb_build_object(
    'id', p_task."TodoTask_ID",
    'title', p_task."TodoTask_Title",
    'scheduledDate', p_task."TodoTask_ScheduledDate",
    'priority', p_task."TodoTask_PriorityCode",
    'status', p_task."TodoTask_StatusCode",
    'completedAt', p_task."TodoTask_CompletedAt",
    'links', p_task."TodoTask_LinksJSON",
    'tags', p_task."TodoTask_TagsJSON",
    'source', p_task."TodoTask_SourceCode",
    'sourceDexterMessageId', p_task."TodoTask_SourceDexterMessageID",
    'editVersion', p_task."TodoTask_EditVersion",
    'createdAt', p_task."TodoTask_CreatedAt",
    'updatedAt', p_task."TodoTask_UpdatedAt"
  );
$$;


ALTER FUNCTION "public"."_multideck_todo_task_json"("p_task" "public"."OPS_UserTasks") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_todo_update_for_actor"("p_company_id" "uuid", "p_user_id" "uuid", "p_task_id" "uuid", "p_patch" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_task public."OPS_UserTasks";
  v_title text;
  v_date date;
  v_priority text;
  v_status text;
  v_links jsonb;
  v_tags jsonb;
begin
  perform public._multideck_todo_assert_actor(p_company_id, p_user_id);
  if jsonb_typeof(coalesce(p_patch,'null'::jsonb)) <> 'object' then
    raise exception 'The task changes are invalid.' using errcode = '22023';
  end if;
  if exists (
    select 1 from jsonb_object_keys(p_patch) key
    where key not in ('title','scheduledDate','priority','status','links','tags')
  ) then
    raise exception 'That task field cannot be changed.' using errcode = '22023';
  end if;

  select * into v_task from public."OPS_UserTasks" task
  where task."TodoTask_ID" = p_task_id
    and task."TodoTask_CompanyID" = p_company_id
    and task."TodoTask_OwnerUserID" = p_user_id
    and not task."TodoTask_IsDeleted"
  for update;
  if not found then raise exception 'Task not found.' using errcode = 'P0002'; end if;

  v_title := v_task."TodoTask_Title";
  v_date := v_task."TodoTask_ScheduledDate";
  v_priority := v_task."TodoTask_PriorityCode";
  v_status := v_task."TodoTask_StatusCode";
  v_links := v_task."TodoTask_LinksJSON";
  v_tags := v_task."TodoTask_TagsJSON";

  if p_patch ? 'title' then
    v_title := left(btrim(coalesce(p_patch->>'title','')),240);
    if v_title = '' then raise exception 'Give the task a title.' using errcode = '22023'; end if;
  end if;
  if p_patch ? 'scheduledDate' then
    begin
      v_date := (p_patch->>'scheduledDate')::date;
    exception when invalid_datetime_format or datetime_field_overflow then
      raise exception 'Choose a valid task date.' using errcode = '22023';
    end;
    if v_date is null then raise exception 'Choose a valid task date.' using errcode = '22023'; end if;
  end if;
  if p_patch ? 'priority' then
    v_priority := nullif(lower(btrim(coalesce(p_patch->>'priority',''))),'');
    if v_priority is not null and v_priority not in ('low','medium','high','urgent') then
      raise exception 'Choose low, medium, high, urgent, or no priority.' using errcode = '22023';
    end if;
  end if;
  if p_patch ? 'status' then
    v_status := lower(btrim(coalesce(p_patch->>'status','')));
    if v_status not in ('open','completed') then
      raise exception 'Choose open or completed.' using errcode = '22023';
    end if;
  end if;
  if p_patch ? 'links' then v_links := public._multideck_todo_clean_references(p_patch->'links','link'); end if;
  if p_patch ? 'tags' then v_tags := public._multideck_todo_clean_references(p_patch->'tags','tag'); end if;

  update public."OPS_UserTasks" set
    "TodoTask_Title" = v_title,
    "TodoTask_ScheduledDate" = v_date,
    "TodoTask_PriorityCode" = v_priority,
    "TodoTask_StatusCode" = v_status,
    "TodoTask_CompletedAt" = case
      when v_status = 'completed' then coalesce("TodoTask_CompletedAt",now())
      else null
    end,
    "TodoTask_LinksJSON" = v_links,
    "TodoTask_TagsJSON" = v_tags,
    "TodoTask_EditVersion" = "TodoTask_EditVersion" + 1,
    "TodoTask_UpdatedBy" = p_user_id,
    "TodoTask_UpdatedAt" = now()
  where "TodoTask_ID" = p_task_id
  returning * into v_task;
  return public._multideck_todo_task_json(v_task);
end;
$$;


ALTER FUNCTION "public"."_multideck_todo_update_for_actor"("p_company_id" "uuid", "p_user_id" "uuid", "p_task_id" "uuid", "p_patch" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_multideck_todo_watch_signal"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_old jsonb := '{}'::jsonb;
  v_new jsonb;
begin
  if not exists (
    select 1 from public."AI_DexterWatches" watch
    where watch."AIDexterWatch_CompanyID" = new."TodoTask_CompanyID"
      and watch."AIDexterWatch_OwnerUserID" = new."TodoTask_OwnerUserID"
      and watch."AIDexterWatch_CapabilityCode" = 'todo'
      and watch."AIDexterWatch_StatusCode" = 'active'
      and watch."AIDexterWatch_TargetID" = new."TodoTask_ID"
  ) then return new; end if;

  if tg_op = 'UPDATE' then
    v_old := jsonb_build_object(
      'title',old."TodoTask_Title",
      'scheduledDate',old."TodoTask_ScheduledDate",
      'priority',old."TodoTask_PriorityCode",
      'status',case when old."TodoTask_IsDeleted" then 'deleted' else old."TodoTask_StatusCode" end,
      'tags',old."TodoTask_TagsJSON"::text,
      'ownerUserId',old."TodoTask_OwnerUserID"
    );
  end if;
  v_new := jsonb_build_object(
    'title',new."TodoTask_Title",
    'scheduledDate',new."TodoTask_ScheduledDate",
    'priority',new."TodoTask_PriorityCode",
    'status',case when new."TodoTask_IsDeleted" then 'deleted' else new."TodoTask_StatusCode" end,
    'tags',new."TodoTask_TagsJSON"::text,
    'ownerUserId',new."TodoTask_OwnerUserID"
  );
  if v_old is not distinct from v_new then return new; end if;

  insert into public."AI_DexterWatchSignals" (
    "AIDexterWatchSignal_CompanyID", "AIDexterWatchSignal_CapabilityCode",
    "AIDexterWatchSignal_SourceTable", "AIDexterWatchSignal_SourceID",
    "AIDexterWatchSignal_OldJSON", "AIDexterWatchSignal_NewJSON"
  ) values (
    new."TodoTask_CompanyID",'todo','OPS_UserTasks',new."TodoTask_ID",v_old,v_new
  );
  return new;
end;
$$;


