    AS $$
begin
  if old."TranscriptionUsage_Status" = 'reserved'
     and new."TranscriptionUsage_Status" = 'succeeded' then
    perform public._multideck_emit_usage_watch_signal(
      new."TranscriptionUsage_CompanyID",
      tg_table_name,
      new."TranscriptionUsage_ID",
      'ai'
    );
  end if;
  return new;
end;
$$;


