CREATE OR REPLACE FUNCTION "public"."_quote_intelligence_rate_changed"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_sheet_id uuid; v_rate record; v_quote_id uuid; v_user_id uuid;
begin
  if tg_op = 'DELETE' then v_sheet_id := old."RATELine_SheetID"; v_user_id := old."RATELine_UpdatedBy";
  else v_sheet_id := new."RATELine_SheetID"; v_user_id := coalesce(new."RATELine_UpdatedBy", new."RATELine_CreatedBy");
  end if;
  select office."Company_ID", sheet."RATESheet_ModeCode", sheet."RATESheet_ShipmentTypeCode",
    contract."RATEContract_CustomerOrgID", lane."RATELane_OriginNameSnapshot", lane."RATELane_DestinationNameSnapshot"
  into v_rate
  from public."RATE_RateSheets" sheet
  join public."RATE_ContractVersions" version on version."RATEContractVer_ID" = sheet."RATESheet_ContractVerID"
  join public."RATE_Contracts" contract on contract."RATEContract_ID" = version."RATEContractVer_ContractID"
  join public."cmp_Offices" office on office."Office_ID" = contract."RATEContract_OrgOfficeID"
  left join public."RATE_Lanes" lane on lane."RATELane_ID" = sheet."RATESheet_LaneID"
  where sheet."RATESheet_ID" = v_sheet_id;
  if not found then
    if tg_op = 'DELETE' then return old; end if;
    return new;
  end if;
  for v_quote_id in
    select quote."CusQuoteHeader_ID"
    from public."CusQuote_Header" quote
    join public."cmp_Offices" office on office."Office_ID" = coalesce(quote."CusQuoteHeader_OrgOfficeID", quote."OrgOffice_ID")
    where office."Company_ID" = v_rate."Company_ID"
      and not quote."CusQuoteHeader_IsDeleted"
      and coalesce(quote."CusQuoteHeader_LifecycleCode", 'draft') not in ('declined','ghosted','accepted','converted')
      and (v_rate."RATESheet_ModeCode" is null or lower(coalesce(quote."CusQuoteHeader_ModeCode", '')) = lower(v_rate."RATESheet_ModeCode"))
      and (v_rate."RATESheet_ShipmentTypeCode" is null or lower(coalesce(quote."CusQuoteHeader_ShipmentTypeCode", '')) = lower(v_rate."RATESheet_ShipmentTypeCode"))
      and (v_rate."RATEContract_CustomerOrgID" is null or quote."CusQuoteHeader_CustomerID" = v_rate."RATEContract_CustomerOrgID")
    order by coalesce(quote."CusQuoteHeader_LastEditedDate", quote."CusQuoteHeader_CreatedDate") desc
    limit 250
  loop
    perform public.quote_intelligence_enqueue(v_quote_id, v_user_id, 'published_rate_changed', 10);
  end loop;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."_quote_intelligence_rate_changed"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_quote_intelligence_watch_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_old jsonb := '{}'::jsonb; v_new jsonb := '{}'::jsonb; v_adjustment numeric := 0;
begin
  if old."CusQuoteIntelligence_AIJSON"->>'inputFingerprint' = old."CusQuoteIntelligence_InputFingerprint" then
    v_adjustment := coalesce((old."CusQuoteIntelligence_AIJSON"->>'adjustmentPoints')::numeric, 0);
  end if;
  v_old := jsonb_build_object(
    'intelligenceState', old."CusQuoteIntelligence_StateCode",
    'aiWinLikelihood', coalesce((old."CusQuoteIntelligence_DeterministicJSON"#>>'{metrics,aiWinLikelihood,value,basePct}')::numeric, 0) + v_adjustment,
    'priceConfidence', (old."CusQuoteIntelligence_DeterministicJSON"#>>'{metrics,priceConfidence,value,score}')::numeric,
    'temperature', coalesce((old."CusQuoteIntelligence_DeterministicJSON"#>>'{metrics,aiTemperature,value,baseScore}')::numeric, 0) + v_adjustment * 0.45
  );
  v_adjustment := 0;
  if new."CusQuoteIntelligence_AIJSON"->>'inputFingerprint' = new."CusQuoteIntelligence_InputFingerprint" then
    v_adjustment := coalesce((new."CusQuoteIntelligence_AIJSON"->>'adjustmentPoints')::numeric, 0);
  end if;
  v_new := jsonb_build_object(
    'intelligenceState', new."CusQuoteIntelligence_StateCode",
    'aiWinLikelihood', coalesce((new."CusQuoteIntelligence_DeterministicJSON"#>>'{metrics,aiWinLikelihood,value,basePct}')::numeric, 0) + v_adjustment,
    'priceConfidence', (new."CusQuoteIntelligence_DeterministicJSON"#>>'{metrics,priceConfidence,value,score}')::numeric,
    'temperature', coalesce((new."CusQuoteIntelligence_DeterministicJSON"#>>'{metrics,aiTemperature,value,baseScore}')::numeric, 0) + v_adjustment * 0.45
  );
  if v_old is distinct from v_new and exists (
    select 1 from public."AI_DexterWatches" watch
    where watch."AIDexterWatch_CompanyID" = new."Company_ID"
      and watch."AIDexterWatch_CapabilityCode" = 'quotes'
      and watch."AIDexterWatch_StatusCode" = 'active'
      and (watch."AIDexterWatch_TargetID" is null or watch."AIDexterWatch_TargetID" = new."CusQuoteIntelligence_QuoteID")
  ) then
    insert into public."AI_DexterWatchSignals"(
      "AIDexterWatchSignal_CompanyID", "AIDexterWatchSignal_CapabilityCode",
      "AIDexterWatchSignal_SourceTable", "AIDexterWatchSignal_SourceID",
      "AIDexterWatchSignal_OldJSON", "AIDexterWatchSignal_NewJSON"
    ) values (new."Company_ID", 'quotes', 'CusQuote_Intelligence', new."CusQuoteIntelligence_QuoteID", v_old, v_new);
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."_quote_intelligence_watch_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_quote_workflow_save_reference_settings_before_sync_20260820"("caller_auth_user_id" "uuid", "quote_pattern" "text", "quote_next_number" bigint, "booking_patterns" "jsonb", "customer_pattern" "text", "customer_next_number" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'quote_api'
    AS $$
declare
  company_id_value uuid;
  user_id_value uuid;
  normalized_quote_pattern text := quote_api.clean_reference_pattern(quote_pattern, 'Q-{NUMBER:4}');
  normalized_customer_pattern text := quote_api.clean_reference_pattern(customer_pattern, 'CUS{NUMBER:4}');
  item jsonb;
  normalized_key text;
  normalized_label text;
  normalized_pattern text;
  normalized_next_number bigint;
  before_value jsonb;
  after_value jsonb;
begin
  select "User_ID", "Company_ID" into user_id_value, company_id_value
  from public."cmp_Users"
  where "Auth_User_ID" = caller_auth_user_id and "User_AccessStatus" = 'active';
  if company_id_value is null then
    raise exception 'User identity is incomplete.' using errcode = '42501';
  end if;
  if not exists (
    select 1 from public."cmp_Users_Roles" link
    join public."sys_UserRoles" role on role."sys_UserRole_ID" = link."sys_UserRole_ID"
    where link."User_ID" = user_id_value
      and lower(role."sys_UserRole_Name") in ('administrator', 'company admin')
  ) then
    raise exception 'Only tenant administrators can change system preferences.' using errcode = '42501';
  end if;
  if jsonb_typeof(booking_patterns) <> 'array' or jsonb_array_length(booking_patterns) < 1
     or jsonb_array_length(booking_patterns) > 20 then
    raise exception 'Keep between 1 and 20 booking reference rules.' using errcode = '22023';
  end if;
  if length(quote_api.render_reference_pattern(normalized_customer_pattern, greatest(coalesce(customer_next_number, 1), 1), company_id_value)) > 8 then
    raise exception 'Customer references must stay within the eight-character account-code limit.' using errcode = '22023';
  end if;
  before_value := public.quote_workflow_get_reference_settings(caller_auth_user_id);
  insert into quote_api.reference_settings(
    company_id, quote_prefix, booking_prefix, quote_pattern, quote_next_number,
    customer_pattern, customer_next_number, updated_at, updated_by
  ) values (
    company_id_value,
    coalesce(nullif(left(split_part(normalized_quote_pattern, '{', 1), 12), ''), 'Q'),
    'B', normalized_quote_pattern,
    greatest(coalesce(quote_next_number, 1), 1), normalized_customer_pattern,
    greatest(coalesce(customer_next_number, 1), 1), now(), user_id_value
  )
  on conflict (company_id) do update set
    quote_pattern = excluded.quote_pattern,
    quote_next_number = excluded.quote_next_number,
    customer_pattern = excluded.customer_pattern,
    customer_next_number = excluded.customer_next_number,
    updated_at = now(), updated_by = excluded.updated_by;

  delete from quote_api.booking_reference_sequences where company_id = company_id_value;
  for item in select value from jsonb_array_elements(booking_patterns) loop
    normalized_key := lower(regexp_replace(coalesce(item ->> 'key', ''), '[^a-z0-9_-]', '', 'g'));
    normalized_label := left(nullif(btrim(item ->> 'label'), ''), 80);
    normalized_pattern := quote_api.clean_reference_pattern(item ->> 'pattern', 'B-{NUMBER:4}');
    normalized_next_number := greatest(coalesce((item ->> 'nextNumber')::bigint, 1), 1);
    if normalized_key = '' or normalized_label is null then
      raise exception 'Each booking reference rule needs a name.' using errcode = '22023';
    end if;
    insert into quote_api.booking_reference_sequences(
      company_id, sequence_key, label, pattern, next_number, enabled, updated_at, updated_by
    ) values (
      company_id_value, left(normalized_key, 40), normalized_label,
      normalized_pattern, normalized_next_number, true, now(), user_id_value
    );
  end loop;
  after_value := public.quote_workflow_get_reference_settings(caller_auth_user_id);
  if after_value is distinct from before_value then
    insert into public."AI_DexterWatchSignals" (
      "AIDexterWatchSignal_CompanyID", "AIDexterWatchSignal_CapabilityCode",
      "AIDexterWatchSignal_SourceTable", "AIDexterWatchSignal_SourceID",
      "AIDexterWatchSignal_OldJSON", "AIDexterWatchSignal_NewJSON"
    ) values (
      company_id_value, 'reference_settings', 'quote_api.reference_settings', company_id_value,
      before_value, after_value
    );
  end if;
  return after_value;
end;
$$;


ALTER FUNCTION "public"."_quote_workflow_save_reference_settings_before_sync_20260820"("caller_auth_user_id" "uuid", "quote_pattern" "text", "quote_next_number" bigint, "booking_patterns" "jsonb", "customer_pattern" "text", "customer_next_number" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_warehouse_create_putaway_task"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_order public."WMS_Orders"%rowtype;
  v_balance_id uuid;
  v_location_type text;
  v_zone_type text;
  v_good numeric;
  v_task_id uuid;
begin
  v_good := new."WMSReceiptLine_ReceivedQuantity" - new."WMSReceiptLine_DamagedQuantity";
  if v_good <= 0 or new."WMSReceiptLine_TargetLocationID" is null then return new; end if;
  select location."WMSLocation_TypeCode", zone."WMSZone_TypeCode"
  into v_location_type, v_zone_type
  from public."WMS_Locations" location
  left join public."WMS_Zones" zone on zone."WMSZone_ID" = location."WMSLocation_ZoneID"
  where location."WMSLocation_ID" = new."WMSReceiptLine_TargetLocationID";
  if coalesce(v_location_type,'') not in ('staging','dock') and coalesce(v_zone_type,'') <> 'receiving' then
    raise exception 'WMS400: Receive stock into an active dock or staging location before putaway.';
  end if;
  select receipt_order.* into v_order
  from public."WMS_Receipts" receipt
  join public."WMS_Orders" receipt_order on receipt_order."WMSOrder_ID" = receipt."WMSReceipt_OrderID"
  where receipt."WMSReceipt_ID" = new."WMSReceiptLine_ReceiptID";
  select transaction."WMSTransaction_BalanceID" into v_balance_id
  from public."WMS_InventoryTransactions" transaction
  where transaction."WMSTransaction_ID" = new."WMSReceiptLine_InventoryTransactionID";
  v_task_id := gen_random_uuid();
  insert into public."WMS_Tasks" (
    "WMSTask_ID","WMSTask_FacilityID","WMSTask_OrderID","WMSTask_OrderLineID","WMSTask_JobID",
    "WMSTask_TypeCode","WMSTask_StatusCode","WMSTask_PriorityCode","WMSTask_Title","WMSTask_Instructions",
    "WMSTask_SourceLocationID","WMSTask_ItemID","WMSTask_BalanceID","WMSTask_HU_ID","WMSTask_Quantity",
    "WMSTask_CompletedQuantity","WMSTask_UOMCode","WMSTask_LotID","WMSTask_MetadataJSON","WMSTask_CreatedBy"
  ) values (
    v_task_id,v_order."WMSOrder_FacilityID",v_order."WMSOrder_ID",new."WMSReceiptLine_OrderLineID",v_order."WMSOrder_JobID",
    'putaway','queued',v_order."WMSOrder_PriorityCode",'Put away received '||new."WMSReceiptLine_UOMCode",'Scan the receiving location, stock, and destination location.',
    new."WMSReceiptLine_TargetLocationID",new."WMSReceiptLine_ItemID",v_balance_id,new."WMSReceiptLine_HU_ID",v_good,
    0,new."WMSReceiptLine_UOMCode",(select "WMSLot_ID" from public."WMS_InventoryBalances" where "WMSBalance_ID"=v_balance_id),
    jsonb_build_object('receiptId',new."WMSReceiptLine_ReceiptID",'receiptLineId',new."WMSReceiptLine_ID"),v_order."WMSOrder_UpdatedBy"
  );
  insert into public."WMS_TaskEvents" ("WMSTaskEvent_TaskID","WMSTaskEvent_EventTypeCode","WMSTaskEvent_ToStatusCode","WMSTaskEvent_MetadataJSON","WMSTaskEvent_EventBy")
  values(v_task_id,'created','queued',jsonb_build_object('receiptLineId',new."WMSReceiptLine_ID"),v_order."WMSOrder_UpdatedBy");
  return new;
end;
$$;


ALTER FUNCTION "public"."_warehouse_create_putaway_task"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_warehouse_edge_quantity_in_uom"("p_item_id" "uuid", "p_quantity" numeric, "p_source_uom" "text", "p_target_uom" "text") RETURNS numeric
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  base_uom text;
  source_factor numeric;
  target_factor numeric;
begin
  if p_quantity is null or p_quantity::text in ('NaN','Infinity','-Infinity') or p_quantity<0 then
    raise exception 'WMS400: Check the stock quantity.';
  end if;
  select upper(btrim("WMSItem_BaseUOMCode")) into base_uom from public."WMS_Items" where "WMSItem_ID"=p_item_id;
  if not found then raise exception 'WMS400: Product unavailable for unit conversion.'; end if;
  if upper(btrim(p_source_uom))=base_uom then source_factor:=1;
  else
    select "WMSItemUOM_QuantityInBaseUOM" into source_factor from public."WMS_ItemUOMs"
      where "WMSItemUOM_ItemID"=p_item_id and "WMSItemUOM_UOMCode"=upper(btrim(p_source_uom));
  end if;
  if upper(btrim(p_target_uom))=base_uom then target_factor:=1;
  else
    select "WMSItemUOM_QuantityInBaseUOM" into target_factor from public."WMS_ItemUOMs"
      where "WMSItemUOM_ItemID"=p_item_id and "WMSItemUOM_UOMCode"=upper(btrim(p_target_uom));
  end if;
  if source_factor is null or target_factor is null or source_factor<=0 or target_factor<=0
    or source_factor::text in ('NaN','Infinity','-Infinity') or target_factor::text in ('NaN','Infinity','-Infinity') then
    raise exception 'WMS409: The product needs valid unit conversions before this stock can be used.';
  end if;
  return p_quantity*source_factor/target_factor;
end;
$$;


ALTER FUNCTION "public"."_warehouse_edge_quantity_in_uom"("p_item_id" "uuid", "p_quantity" numeric, "p_source_uom" "text", "p_target_uom" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_warehouse_edge_sync_hu_contents"("p_hu_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if p_hu_id is null then return; end if;
  delete from public."WMS_HandlingUnitContents" where "WMSHUContent_HU_ID"=p_hu_id;
  insert into public."WMS_HandlingUnitContents" (
    "WMSHUContent_ID","WMSHUContent_HU_ID","WMSHUContent_ItemID","WMSHUContent_LotID","WMSHUContent_SerialID",
    "WMSHUContent_Quantity","WMSHUContent_UOMCode","WMSHUContent_InventoryStatusCode","WMSHUContent_CustomsStatusCode","WMSHUContent_CreatedAt"
  )
  select gen_random_uuid(),p_hu_id,"WMSBalance_ItemID","WMSBalance_LotID","WMSBalance_SerialID",
    sum("WMSBalance_OnHandQuantity"),"WMSBalance_UOMCode","WMSBalance_InventoryStatusCode","WMSBalance_CustomsStatusCode",now()
  from public."WMS_InventoryBalances"
  where "WMSBalance_HU_ID"=p_hu_id and "WMSBalance_OnHandQuantity">0
  group by "WMSBalance_ItemID","WMSBalance_LotID","WMSBalance_SerialID","WMSBalance_UOMCode","WMSBalance_InventoryStatusCode","WMSBalance_CustomsStatusCode";
end; $$;


ALTER FUNCTION "public"."_warehouse_edge_sync_hu_contents"("p_hu_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_warehouse_edge_task_balance_quantity"("p_quantity" numeric, "p_task_uom" "text", "p_balance_uom" "text", "p_metadata" "jsonb") RETURNS numeric
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare conversion jsonb:=p_metadata->'quantityConversion'; result numeric; task_factor numeric; balance_factor numeric;
begin
  if p_quantity is null or p_quantity<0 or p_quantity::text in ('NaN','Infinity','-Infinity') then raise exception 'WMS400: Check the task quantity.'; end if;
  if conversion is null then
    if p_task_uom is distinct from p_balance_uom then raise exception 'WMS409: This older task needs its unit conversion reviewed before stock can move.'; end if;
    result:=p_quantity;
  else
    if conversion->>'taskUom' is distinct from p_task_uom or conversion->>'balanceUom' is distinct from p_balance_uom then raise exception 'WMS409: Task and stock units changed after allocation.'; end if;
    task_factor:=(conversion->>'taskFactor')::numeric; balance_factor:=(conversion->>'balanceFactor')::numeric;
    if task_factor is null or balance_factor is null or task_factor<=0 or balance_factor<=0 or task_factor::text in ('NaN','Infinity','-Infinity') or balance_factor::text in ('NaN','Infinity','-Infinity') then raise exception 'WMS409: Task conversion evidence is invalid.'; end if;
    result:=p_quantity*task_factor/balance_factor;
  end if;
  if result<>round(result,6) then raise exception 'WMS409: This quantity cannot be represented in the stock unit. Repack stock into a suitable unit first.'; end if;
  return result;
end;
$$;


ALTER FUNCTION "public"."_warehouse_edge_task_balance_quantity"("p_quantity" numeric, "p_task_uom" "text", "p_balance_uom" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_warehouse_edge_validate_quantity"("p_item_id" "uuid", "p_quantity" numeric) RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_basis text;
  v_scale integer;
  v_minimum numeric;
  v_fractional boolean;
begin
  select "WMSItem_QuantityBasisCode","WMSItem_QuantityScale","WMSItem_MinimumMovementQuantity","WMSItem_AllowsFractionalQuantity"
  into v_basis,v_scale,v_minimum,v_fractional from public."WMS_Items" where "WMSItem_ID"=p_item_id and not "WMSItem_IsDeleted";
  if not found then raise exception 'WMS404: This product does not exist.'; end if;
  if p_quantity<v_minimum or round(p_quantity,v_scale)<>p_quantity then raise exception 'WMS400: The quantity does not match this product''s minimum movement or precision.'; end if;
  if v_basis='count' and not v_fractional and trunc(p_quantity)<>p_quantity then raise exception 'WMS400: This counted product must move in whole units.'; end if;
end; $$;


ALTER FUNCTION "public"."_warehouse_edge_validate_quantity"("p_item_id" "uuid", "p_quantity" numeric) OWNER TO "postgres";


