CREATE OR REPLACE FUNCTION "public"."assign_customs_declaration"("p_declaration_id" "uuid", "p_assigned_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth', 'booking_api'
    AS $$
declare
  v_actor record;
  v_target record;
  v_old_assigned_user_id uuid;
  v_reference text;
begin
  if auth.uid() is null
     or not booking_api.customs_access(auth.uid(), p_declaration_id, true) then
    raise exception 'This Customs declaration is unavailable or cannot be reassigned.' using errcode = '42501';
  end if;
  select workspace_user."User_ID", workspace_user."Company_ID" into strict v_actor
  from public."cmp_Users" workspace_user
  where workspace_user."Auth_User_ID" = auth.uid()
    and coalesce(workspace_user."User_AccessStatus", 'active') = 'active';

  if p_assigned_user_id is not null then
    select workspace_user."User_ID", workspace_user."Auth_User_ID" into v_target
    from public."cmp_Users" workspace_user
    where workspace_user."User_ID" = p_assigned_user_id
      and workspace_user."Company_ID" = v_actor."Company_ID"
      and workspace_user."Auth_User_ID" is not null
      and coalesce(workspace_user."User_AccessStatus", 'active') = 'active';
    if v_target."User_ID" is null then
      raise exception 'Choose an active user from this workspace.' using errcode = '22023';
    end if;
    if not booking_api.has_permission(v_target."Auth_User_ID", 'Customs.Write') then
      raise exception 'That user does not have permission to work on Customs declarations.' using errcode = '22023';
    end if;
  end if;

  select declaration."CUST_AssignedUserID",
         coalesce(declaration."CUST_LocalReferenceNumber", declaration."CUST_id"::text)
  into v_old_assigned_user_id, v_reference
  from public."Customs_Declarations" declaration
  where declaration."CUST_id" = p_declaration_id and not declaration."CUST_IsDeleted"
  for update;

  if v_old_assigned_user_id is not distinct from p_assigned_user_id then
    return jsonb_build_object(
      'declarationId', p_declaration_id,
      'assignedUserId', p_assigned_user_id,
      'reference', v_reference,
      'unchanged', true
    );
  end if;

  update public."Customs_Declarations" set
    "CUST_AssignedUserID" = p_assigned_user_id,
    "CUST_UpdatedAt" = clock_timestamp(),
    "CUST_UpdatedBy" = auth.uid()
  where "CUST_id" = p_declaration_id;

  insert into public."Customs_AuditLog" (
    "CUSTAU_CustomsID", "CUSTAU_Action", "CUSTAU_TableName", "CUSTAU_RecordID",
    "CUSTAU_ChangedBy", "CUSTAU_OldValues", "CUSTAU_NewValues", "CUSTAU_Source", "CUSTAU_Notes"
  ) values (
    p_declaration_id,
    'declaration_assigned',
    'Customs_Declarations',
    p_declaration_id,
    auth.uid(),
    jsonb_build_object('assignedUserId', v_old_assigned_user_id),
    jsonb_build_object('assignedUserId', p_assigned_user_id),
    'multideck_app',
    case when p_assigned_user_id is null
      then 'The declaration was left unassigned.'
      else 'Responsibility for the declaration changed.'
    end
  );

  return jsonb_build_object(
    'declarationId', p_declaration_id,
    'assignedUserId', p_assigned_user_id,
    'reference', v_reference,
    'unchanged', false
  );
end;
$$;


ALTER FUNCTION "public"."assign_customs_declaration"("p_declaration_id" "uuid", "p_assigned_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."booking_workflow_apply_quote_sync"("caller_auth_user_id" "uuid", "requested_job_id" "uuid", "requested_review_id" "uuid", "requested_fields" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  apply_result jsonb;
  app_user_id uuid;
  review_row record;
  refreshed_snapshot jsonb;
begin
  apply_result := public.booking_workflow_apply_quote_sync_before_container_allocation_20260904(
    caller_auth_user_id,
    requested_job_id,
    requested_review_id,
    requested_fields
  );

  if requested_fields ? 'equipment' then
    select app_user."User_ID" into strict app_user_id
    from public."cmp_Users" app_user
    where app_user."Auth_User_ID" = caller_auth_user_id
      and app_user."User_AccessStatus" = 'active';

    select review.* into strict review_row
    from booking_api.quote_sync_reviews review
    where review.review_id = requested_review_id
      and review.job_id = requested_job_id;

    if review_row.proposed_snapshot->>'mode' in ('sea', 'ocean') then
      perform booking_api.replace_quote_containers(
        requested_job_id,
        app_user_id,
        review_row.proposed_snapshot,
        'accepted_quote_update',
        review_row.proposed_version_id
      );

      refreshed_snapshot := booking_api.current_quote_sync_projection(requested_job_id);
      update booking_api.events event
      set metadata = jsonb_set(event.metadata, '{after}', refreshed_snapshot, true)
      where event.event_id = (
        select candidate.event_id
        from booking_api.events candidate
        where candidate.job_id = requested_job_id
          and candidate.metadata->>'reviewId' = requested_review_id::text
        order by candidate.occurred_at desc
        limit 1
      );

      apply_result := jsonb_set(
        apply_result,
        '{workspace}',
        booking_api.workspace_with_document_groups(caller_auth_user_id, (apply_result#>>'{workspace,booking,bookingReference}')::text),
        true
      );
    end if;
  end if;

  return apply_result;
exception
  when no_data_found or too_many_rows then
    raise exception 'The quote update review is unavailable in this workspace.' using errcode = 'P0002';
end;
$$;


ALTER FUNCTION "public"."booking_workflow_apply_quote_sync"("caller_auth_user_id" "uuid", "requested_job_id" "uuid", "requested_review_id" "uuid", "requested_fields" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."booking_workflow_apply_quote_sync_before_container_allocation_2"("caller_auth_user_id" "uuid", "requested_job_id" "uuid", "requested_review_id" "uuid", "requested_fields" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  app_user record;
  review_row record;
  payer jsonb;
begin
  if requested_fields ? 'payer' then
    if caller_auth_user_id is null or not booking_api.has_permission(caller_auth_user_id, 'Bookings.Write') then
      raise exception 'Booking changes are not authorised.' using errcode = '42501';
    end if;
    select "User_ID", "Company_ID" into strict app_user
    from public."cmp_Users"
    where "Auth_User_ID" = caller_auth_user_id
      and "User_AccessStatus" = 'active';
    select review.* into strict review_row
    from booking_api.quote_sync_reviews review
    where review.review_id = requested_review_id
      and review.job_id = requested_job_id
      and review.company_id = app_user."Company_ID"
      and review.status_code in ('pending', 'partially_applied')
    for update;
    payer := review_row.proposed_snapshot->'payer';

    delete from public."Job_Parties"
    where "JobParty_JobID" = requested_job_id
      and "JobParty_Role" = 'payer';

    if quote_api.jsonb_has_content(payer) then
      insert into public."Job_Parties" (
        "JobParty_JobID", "JobParty_Role", "JobParty_OrgID", "JobParty_Sequence",
        "JobParty_NameSnapshot", "JobParty_AddressSnapshot", "JobParty_ContactNameSnapshot",
        "JobParty_EmailSnapshot", "JobParty_IdentifierType", "JobParty_IdentifierValueSnapshot",
        "JobParty_IsPrimary", "JobParty_RawSnapshot", "JobParty_CreatedBy"
      ) values (
        requested_job_id, 'payer', nullif(payer->>'orgId', '')::uuid, 1,
        left(nullif(btrim(payer->>'name'), ''), 240), nullif(btrim(payer->>'address'), ''),
        left(nullif(btrim(payer->>'contact'), ''), 180), left(nullif(btrim(payer->>'email'), ''), 254),
        'account_code', left(nullif(btrim(payer->>'code'), ''), 120), true, payer, app_user."User_ID"
      );
    end if;
  end if;

  return public.booking_workflow_apply_quote_sync_before_payer_20260904(
    caller_auth_user_id,
    requested_job_id,
    requested_review_id,
    requested_fields
  );
exception when no_data_found or too_many_rows then
  raise exception 'The quote update review is unavailable in this workspace.' using errcode = 'P0002';
end;
$$;


ALTER FUNCTION "public"."booking_workflow_apply_quote_sync_before_container_allocation_2"("caller_auth_user_id" "uuid", "requested_job_id" "uuid", "requested_review_id" "uuid", "requested_fields" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."booking_workflow_apply_quote_sync_before_container_allocation_2"("caller_auth_user_id" "uuid", "requested_job_id" "uuid", "requested_review_id" "uuid", "requested_fields" "jsonb") IS 'Applies operator-approved accepted-quote fields through Bookings.Write. Quote charges are operational job costing; protected customer finance master data remains outside this workflow. UI approval is required and every application remains audited.';



CREATE OR REPLACE FUNCTION "public"."booking_workflow_apply_quote_sync_before_payer_20260904"("caller_auth_user_id" "uuid", "requested_job_id" "uuid", "requested_review_id" "uuid", "requested_fields" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  app_user record;
  job_row record;
  review_row record;
  version_snapshot jsonb;
  proposed jsonb;
  current_parties jsonb;
  save_payload jsonb := '{}'::jsonb;
  selected_fields jsonb;
  combined_fields jsonb;
  remaining_count integer;
  before_snapshot jsonb;
  after_snapshot jsonb;
  charge jsonb;
  charge_number integer := 0;
begin
  if caller_auth_user_id is null or not booking_api.has_permission(caller_auth_user_id,'Bookings.Write') then
    raise exception 'Booking changes are not authorised.' using errcode='42501';
  end if;
  if requested_fields is null or jsonb_typeof(requested_fields)<>'array'
     or jsonb_array_length(requested_fields)=0 or jsonb_array_length(requested_fields)>30 then
    raise exception 'Choose at least one quote field to apply.' using errcode='22023';
  end if;
  select "User_ID","Company_ID" into strict app_user from public."cmp_Users"
  where "Auth_User_ID"=caller_auth_user_id and "User_AccessStatus"='active';
  select job.* into strict job_row
  from public."Job_Header" job
  join public."cmp_Offices" office on office."Office_ID"=coalesce(job."Job_OrgOfficeID",job."Job_OfficeID")
  where job."Job_ID"=requested_job_id and office."Company_ID"=app_user."Company_ID"
    and not job."Job_IsDeleted" for update;
  select review.* into strict review_row
  from booking_api.quote_sync_reviews review
  where review.review_id=requested_review_id and review.job_id=requested_job_id
    and review.company_id=app_user."Company_ID" and review.status_code in ('pending','partially_applied')
  for update;

  select coalesce(jsonb_agg(distinct item.value),'[]'::jsonb) into selected_fields
  from jsonb_array_elements(requested_fields) item
  where jsonb_typeof(item.value)='string';
  if jsonb_array_length(selected_fields)<>jsonb_array_length(requested_fields)
     or exists (
       select 1 from jsonb_array_elements_text(selected_fields) field_name
       where not exists (
         select 1 from jsonb_array_elements(review_row.differences) difference
         where difference->>'key'=field_name
       )
     ) then
    raise exception 'One or more selected quote fields are not available for this review.' using errcode='22023';
  end if;

  if exists(select 1 from jsonb_array_elements_text(selected_fields) field where field like 'cargo:%') then
    raise exception 'Refresh the Booking and use the current cargo review action.' using errcode='22023'; end if;
  if selected_fields ? 'cargo' and (review_row.baseline_snapshot ? 'cargoLines' or review_row.proposed_snapshot ? 'cargoLines') then
    raise exception 'Shipment goods value requires a separate allocation review.' using errcode='22023'; end if;
  proposed := review_row.proposed_snapshot;
  before_snapshot := booking_api.current_quote_sync_projection(requested_job_id);
  if selected_fields ? 'shipmentGoodsValue' then
    save_payload:=save_payload||jsonb_build_object('shipmentGoodsValue',proposed->'shipmentGoodsValue');
  end if;


  if selected_fields ? 'direction' then save_payload := save_payload || jsonb_build_object('direction',proposed->>'direction'); end if;
  if selected_fields ? 'mode' then save_payload := save_payload || jsonb_build_object('mode',proposed->>'mode'); end if;
  if selected_fields ? 'carrier' then save_payload := save_payload || jsonb_build_object('carrierId',proposed#>>'{carrier,id}'); end if;
  if selected_fields ? 'supplier' then save_payload := save_payload || jsonb_build_object('supplierId',proposed#>>'{supplier,id}'); end if;
  if selected_fields ? 'origin' then
    save_payload := save_payload || jsonb_build_object('origin',proposed->>'origin');
    save_payload := save_payload || jsonb_build_object('originUnlocode',
      case when proposed->>'origin' ~ '^[A-Za-z]{2}[A-Za-z0-9]{3}$' then upper(proposed->>'origin') else null end);
  end if;
  if selected_fields ? 'destination' then
    save_payload := save_payload || jsonb_build_object('destination',proposed->>'destination');
    save_payload := save_payload || jsonb_build_object('destinationUnlocode',
      case when proposed->>'destination' ~ '^[A-Za-z]{2}[A-Za-z0-9]{3}$' then upper(proposed->>'destination') else null end);
  end if;
  if selected_fields ? 'collectionAddress' then save_payload := save_payload || jsonb_build_object('collectionAddress',proposed->>'collectionAddress'); end if;
  if selected_fields ? 'deliveryAddress' then save_payload := save_payload || jsonb_build_object('deliveryAddress',proposed->>'deliveryAddress'); end if;
  if selected_fields ? 'incoterm' then save_payload := save_payload || jsonb_build_object('incoterm',proposed->>'incoterm'); end if;
  if selected_fields ? 'incotermLocation' then save_payload := save_payload || jsonb_build_object('incotermLocation',proposed->>'incotermLocation'); end if;
  if selected_fields ? 'estimatedDeparture' then save_payload := save_payload || jsonb_build_object('readyDate',proposed->>'estimatedDeparture'); end if;
  if selected_fields ? 'estimatedArrival' then save_payload := save_payload || jsonb_build_object('requiredDeliveryDate',proposed->>'estimatedArrival'); end if;

  if selected_fields ?| array['shipmentType','customerNotes','terms','subjectToTerms'] then
    save_payload := save_payload || jsonb_build_object('editableDetails',
      (case when selected_fields ? 'shipmentType' then jsonb_build_object('shipmentType',proposed->>'shipmentType') else '{}'::jsonb end)
      || (case when selected_fields ? 'customerNotes' then jsonb_build_object('customerNotes',proposed->>'customerNotes') else '{}'::jsonb end)
      || (case when selected_fields ? 'terms' then jsonb_build_object('termsAndConditions',proposed->>'terms') else '{}'::jsonb end)
      || (case when selected_fields ? 'subjectToTerms' then jsonb_build_object('subjectToTerms',proposed->>'subjectToTerms') else '{}'::jsonb end)
    );
  end if;
  if selected_fields ? 'customerNotes' then update public."Job_Header" set "Job_CustomerNotes"=proposed->>'customerNotes' where "Job_ID"=requested_job_id; end if;
  if selected_fields ? 'terms' then update public."Job_Header" set "Job_TermsConditions"=proposed->>'terms' where "Job_ID"=requested_job_id; end if;
  if selected_fields ? 'subjectToTerms' then update public."Job_Header" set "Job_SubjectToTerms"=proposed->>'subjectToTerms' where "Job_ID"=requested_job_id; end if;

  if selected_fields ?| array['origin','destination','collectionAddress','deliveryAddress','serviceLevel','estimatedDeparture','estimatedArrival','carrier','mode'] then
    save_payload := save_payload || jsonb_build_object('route',jsonb_strip_nulls(jsonb_build_object(
      'origin',case when selected_fields ? 'origin' then coalesce(proposed->>'origin','') end,
      'originUnlocode',case when selected_fields ? 'origin' then case when proposed->>'origin' ~ '^[A-Za-z]{2}[A-Za-z0-9]{3}$' then upper(proposed->>'origin') else '' end end,
      'originAddress',case when selected_fields ? 'collectionAddress' then coalesce(proposed->>'collectionAddress','') end,
      'destination',case when selected_fields ? 'destination' then coalesce(proposed->>'destination','') end,
      'destinationUnlocode',case when selected_fields ? 'destination' then case when proposed->>'destination' ~ '^[A-Za-z]{2}[A-Za-z0-9]{3}$' then upper(proposed->>'destination') else '' end end,
      'destinationAddress',case when selected_fields ? 'deliveryAddress' then coalesce(proposed->>'deliveryAddress','') end,
      'serviceLevel',case when selected_fields ? 'serviceLevel' then coalesce(proposed->>'serviceLevel','') end,
      'plannedDepartureAt',case when selected_fields ? 'estimatedDeparture' then coalesce(proposed->>'estimatedDeparture','') end,
      'plannedArrivalAt',case when selected_fields ? 'estimatedArrival' then coalesce(proposed->>'estimatedArrival','') end,
      'carrierId',case when selected_fields ? 'carrier' then coalesce(proposed#>>'{carrier,id}','') end,
      'mode',case when selected_fields ? 'mode' then proposed->>'mode' end
    )));
  end if;

  if selected_fields ?| array['shipper','consignee'] then
    -- save_booking replaces the complete party list. Preserve every operational
    -- party and replace only the primary quote-controlled shipper/consignee.
    select coalesce(jsonb_agg(party_payload order by role_code, sequence_no, party_id),'[]'::jsonb)
    into current_parties
    from (
      select
        party."JobParty_ID" as party_id,
        party."JobParty_Role" as role_code,
        party."JobParty_Sequence" as sequence_no,
        jsonb_strip_nulls(jsonb_build_object(
          'role',party."JobParty_Role",'organisationId',party."JobParty_OrgID",'addressId',party."JobParty_AddressID",
          'contactId',party."JobParty_ContactID",'sequence',party."JobParty_Sequence",'name',party."JobParty_NameSnapshot",
          'address',party."JobParty_AddressSnapshot",'contactName',party."JobParty_ContactNameSnapshot",
          'email',party."JobParty_EmailSnapshot",'phone',party."JobParty_PhoneSnapshot",
          'countryCode',party."JobParty_CountryCodeSnapshot",'identifierType',party."JobParty_IdentifierType",
          'identifierValue',party."JobParty_IdentifierValueSnapshot",'isPrimary',party."JobParty_IsPrimary"
        )) as party_payload,
        row_number() over (
          partition by party."JobParty_Role"
          order by party."JobParty_IsPrimary" desc, party."JobParty_Sequence", party."JobParty_ID"
        ) as role_rank
      from public."Job_Parties" party
      where party."JobParty_JobID"=requested_job_id
    ) existing_party
    where not (
      role_rank=1 and (
        (selected_fields ? 'shipper' and role_code='shipper')
        or (selected_fields ? 'consignee' and role_code='consignee')
      )
    );
    if selected_fields ? 'shipper' and proposed->'shipper' is not null then
      current_parties := current_parties || jsonb_build_array(jsonb_build_object(
        'role','shipper','organisationId',proposed#>>'{shipper,orgId}','name',proposed#>>'{shipper,name}',
        'address',proposed#>>'{shipper,address}','contactName',proposed#>>'{shipper,contact}','sequence',1,'isPrimary',true));
    end if;
    if selected_fields ? 'consignee' and proposed->'consignee' is not null then
      current_parties := current_parties || jsonb_build_array(jsonb_build_object(
        'role','consignee','organisationId',proposed#>>'{consignee,orgId}','name',proposed#>>'{consignee,name}',
        'address',proposed#>>'{consignee,address}','contactName',proposed#>>'{consignee,contact}','sequence',1,'isPrimary',true));
    end if;
    save_payload := save_payload || jsonb_build_object('parties',current_parties);
  end if;

  if selected_fields ? 'cargo' then
    save_payload := save_payload || jsonb_build_object('cargo',jsonb_build_array(jsonb_build_object(
      'description',proposed#>>'{cargo,description}','packageQuantity',proposed#>>'{cargo,packageQuantity}',
      'packageType',proposed#>>'{cargo,packageType}','grossWeightKg',proposed#>>'{cargo,grossWeightKg}',
      'netWeightKg',proposed#>>'{cargo,netWeightKg}','volumeCbm',proposed#>>'{cargo,volumeCbm}',
      'declaredValue',before_snapshot#>>'{cargo,goodsValue}','declaredValueCurrency',before_snapshot#>>'{cargo,goodsValueCurrency}'
    )));
  end if;
  if selected_fields ? 'equipment' and proposed->>'mode' in ('sea','ocean') then
    save_payload := save_payload || jsonb_build_object('containers',jsonb_build_array(jsonb_build_object(
      'type',proposed->>'equipment','equipmentKind','container','status','planned',
      'data',jsonb_build_object('source','accepted_quote_update','quoteVersionId',review_row.proposed_version_id)
    )));
  end if;


  if selected_fields ? 'mode' and (
    coalesce(review_row.baseline_snapshot->'routingIsExplicit'='true'::jsonb,false)
    or coalesce(proposed->'routingIsExplicit'='true'::jsonb,false)
    or selected_fields ? 'routing'
    or (select count(*)<>1 or not coalesce(bool_and(
        booking_api.normalise_mode(route."JobRoute_ModeCode") is not distinct from
          booking_api.normalise_mode(before_snapshot->>'mode')),false)
      from public."Job_Routing" route
      where route."Job_ID"=requested_job_id
        and coalesce(route."JobRoute_Status",'planned')<>'superseded')
  ) then
    save_payload:=save_payload #- '{route,mode}';
    -- Do not send an empty compatibility route: even an empty object causes
    -- the legacy saver to touch the first leg and can revive stale defaults.
    if save_payload->'route'='{}'::jsonb then save_payload:=save_payload-'route';end if;
  end if;
  perform booking_api.save_booking(caller_auth_user_id,requested_job_id,save_payload);
  perform booking_api.save_booking_detail_fields(caller_auth_user_id,requested_job_id,save_payload);
  if selected_fields ? 'cargo' then perform booking_api.save_booking_cargo_measurements(caller_auth_user_id,requested_job_id,save_payload); end if;

  if selected_fields ? 'charges' then
    delete from public."Job_Costing_Lines" where "Job_ID"=requested_job_id;
    for charge in select value from jsonb_array_elements(coalesce(proposed->'charges','[]'::jsonb)) loop
      charge_number := charge_number+1;
      insert into public."Job_Costing_Lines" (
        "Job_ID","JobCostingLine_Number","JobCostingLine_SupplierID","JobCostingLine_Description",
        "JobCostingLine_InternalNotes","JobCostingLine_CustomerNotes","JobCostingLine_CostROE",
        "JobCostingLine_CostAmountCurrency","JobCostingLine_CostAmountLocal","JobCostingLine_RevenueROE",
        "JobCostingLine_RevenueAmountCurrency","JobCostingLine_RevenueAmountLocal","JobCostingLine_ShowToCustomer",
        "JobCostingLine_CreatedBy","JobCostingLine_UpdatedBy","JobCostingLine_SourceTable","JobCostingLine_SourceID","JobCostingLine_SourceMetadataJSON"
      ) values (
        requested_job_id,charge_number,nullif(charge->>'supplierId','')::uuid,left(coalesce(nullif(btrim(charge->>'description'),''),'Charge'),240),
        nullif(charge->>'internalNotes',''),nullif(charge->>'customerNotes',''),greatest(coalesce(nullif(charge->>'costRoe','')::numeric,1),0.00001),
        coalesce(nullif(charge->>'costAmount','')::numeric,0),coalesce(nullif(charge->>'costLocal','')::numeric,0),
        greatest(coalesce(nullif(charge->>'sellRoe','')::numeric,1),0.00001),coalesce(nullif(charge->>'sellAmount','')::numeric,0),
        coalesce(nullif(charge->>'sellLocal','')::numeric,0),coalesce((charge->>'showToCustomer')::boolean,true),
        app_user."User_ID",app_user."User_ID",'CusQuote_Versions',review_row.proposed_version_id,
        jsonb_build_object('source','accepted_quote_update','reviewId',requested_review_id)
      );
    end loop;
  end if;

  select coalesce(jsonb_agg(distinct value),'[]'::jsonb) into combined_fields
  from jsonb_array_elements(review_row.applied_fields || selected_fields);
  select count(*) into remaining_count
  from jsonb_array_elements(review_row.differences) difference
  where not combined_fields ? (difference->>'key');
  after_snapshot := booking_api.current_quote_sync_projection(requested_job_id);

  update booking_api.quote_sync_reviews set
    applied_fields=combined_fields,status_code=case when remaining_count=0 then 'applied' else 'partially_applied' end,
    decided_at=case when remaining_count=0 then now() else decided_at end,
    decided_by=app_user."User_ID"
  where review_id=requested_review_id;

  if remaining_count=0 then
    select version."CusQuoteVersion_SnapshotJSON" into strict version_snapshot
    from public."CusQuote_Versions" version where version."CusQuoteVersion_ID"=review_row.proposed_version_id;
    update public."Job_Header" set
      "Job_SourceQuoteVersionID"=review_row.proposed_version_id,
      "Job_SourceQuoteResponseID"=review_row.proposed_response_id,
      "Job_PendingQuoteVersionID"=null,"Job_PendingQuoteResponseID"=null,
      "Job_QuoteSyncStatus"='in_sync',"Job_QuoteSyncDetectedAt"=null,
      "Job_SourceSnapshotJSON"="Job_SourceSnapshotJSON" || jsonb_build_object('acceptedSnapshot',version_snapshot),
      "Job_UpdatedAt"=now(),"Job_UpdatedBy"=app_user."User_ID"
    where "Job_ID"=requested_job_id;
  else
    update public."Job_Header" set "Job_QuoteSyncStatus"='partially_applied',"Job_UpdatedAt"=now(),"Job_UpdatedBy"=app_user."User_ID"
    where "Job_ID"=requested_job_id;
  end if;

  insert into booking_api.events(company_id,job_id,event_type,summary,metadata,actor_user_id)
  values(app_user."Company_ID",requested_job_id,
    case when remaining_count=0 then 'quote_update_applied' else 'quote_update_partially_applied' end,
    case when remaining_count=0 then 'The newer accepted quote was applied to the booking.' else 'Selected fields from the newer accepted quote were applied.' end,
    jsonb_build_object('reviewId',requested_review_id,'quoteVersionId',review_row.proposed_version_id,
      'appliedFields',selected_fields,'before',before_snapshot,'after',after_snapshot,'remainingFields',remaining_count),
    app_user."User_ID");

  return jsonb_build_object('reviewId',requested_review_id,'status',case when remaining_count=0 then 'applied' else 'partially_applied' end,
    'appliedFields',combined_fields,'remainingFields',remaining_count,
    'workspace',booking_api.workspace_with_document_groups(caller_auth_user_id,job_row."Job_BookingReference"));
exception when no_data_found or too_many_rows then
  raise exception 'The quote update review is unavailable in this workspace.' using errcode='P0002';
end;
$_$;


ALTER FUNCTION "public"."booking_workflow_apply_quote_sync_before_payer_20260904"("caller_auth_user_id" "uuid", "requested_job_id" "uuid", "requested_review_id" "uuid", "requested_fields" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."booking_workflow_apply_quote_sync_confirmed"("caller_auth_user_id" "uuid", "requested_job_id" "uuid", "requested_review_id" "uuid", "requested_fields" "jsonb", "confirm_mode_change" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  review_row record;
  result jsonb;
  booking_reference text;
  actor_user_id uuid;
begin
  if requested_fields ? 'mode' and not coalesce(confirm_mode_change,false) then
    raise exception 'Confirm the mode change before applying it to the booking.' using errcode='22023';
  end if;
  if requested_fields ? 'routing' then
    select app_user."User_ID" into strict actor_user_id
    from public."cmp_Users" app_user
    where app_user."Auth_User_ID"=caller_auth_user_id and app_user."User_AccessStatus"='active';
    select review.* into strict review_row
    from booking_api.quote_sync_reviews review
    where review.review_id=requested_review_id and review.job_id=requested_job_id
      and review.status_code in ('pending','partially_applied');
    if not coalesce(confirm_mode_change,false) and booking_api.routing_mode_review_required(
      booking_api.current_quote_sync_projection(requested_job_id)->'routing',review_row.proposed_snapshot->'routing') then
      raise exception 'Confirm the routing mode change before applying it to the Booking.' using errcode='22023';
    end if;
    perform booking_api.apply_quote_routing_plan(
      requested_job_id,review_row.proposed_version_id,actor_user_id
    );
  end if;

  result := public.booking_workflow_apply_quote_sync(
    caller_auth_user_id,requested_job_id,requested_review_id,requested_fields
  );

  if requested_fields ? 'routing' then
    select job."Job_BookingReference" into strict booking_reference
    from public."Job_Header" job where job."Job_ID"=requested_job_id;
    result := result || jsonb_build_object(
      'workspace',booking_api.workspace_with_document_groups(caller_auth_user_id,booking_reference)
    );
  end if;
  return result;
exception when no_data_found or too_many_rows then
  raise exception 'The quote update review is unavailable in this workspace.' using errcode='P0002';
end;
$$;


ALTER FUNCTION "public"."booking_workflow_apply_quote_sync_confirmed"("caller_auth_user_id" "uuid", "requested_job_id" "uuid", "requested_review_id" "uuid", "requested_fields" "jsonb", "confirm_mode_change" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."booking_workflow_apply_quote_sync_v2"("caller_auth_user_id" "uuid", "requested_job_id" "uuid", "requested_review_id" "uuid", "requested_fields" "jsonb", "expected_review_token" "text", "confirm_mode_change" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare app_user record; job_row record; review_row record; refreshed jsonb; selected jsonb; cargo_fields jsonb; other_fields jsonb; result jsonb;
begin
  if caller_auth_user_id is null or not booking_api.has_permission(caller_auth_user_id,'Bookings.Write') then raise exception 'Booking changes are not authorised.' using errcode='42501'; end if;
  select "User_ID","Company_ID" into strict app_user from public."cmp_Users" where "Auth_User_ID"=caller_auth_user_id and "User_AccessStatus"='active';
  select job.* into strict job_row from public."Job_Header" job join public."cmp_Offices" office on office."Office_ID"=coalesce(job."Job_OrgOfficeID",job."Job_OfficeID")
    where job."Job_ID"=requested_job_id and not job."Job_IsDeleted" and office."Company_ID"=app_user."Company_ID" for update of job;
  select * into strict review_row from booking_api.quote_sync_reviews where review_id=requested_review_id and job_id=requested_job_id
    and company_id=app_user."Company_ID" and quote_id=job_row."Job_SourceQuoteID"
    and status_code in ('pending','partially_applied','applied') for update;
  if requested_fields is null or jsonb_typeof(requested_fields)<>'array' or jsonb_array_length(requested_fields) not between 1 and 8030
    or (select count(distinct value) from jsonb_array_elements(requested_fields) where jsonb_typeof(value)='string')<>jsonb_array_length(requested_fields) then
    raise exception 'Choose unique Quote fields to apply.' using errcode='22023'; end if;
  select coalesce(jsonb_agg(value),'[]') into selected from jsonb_array_elements(requested_fields) where not review_row.applied_fields ? (value#>>'{}');
  if jsonb_array_length(selected)=0 then
    return jsonb_build_object('reviewId',requested_review_id,'reused',true,'status',review_row.status_code,'appliedFields',review_row.applied_fields,
      'remainingFields',(select count(*) from jsonb_array_elements(review_row.differences) d where not review_row.applied_fields ? (d->>'key')),
      'workspace',booking_api.workspace_with_document_groups(caller_auth_user_id,job_row."Job_BookingReference")); end if;
  if review_row.status_code='applied' or job_row."Job_PendingQuoteVersionID" is distinct from review_row.proposed_version_id
    or job_row."Job_SourceQuoteVersionID" is distinct from review_row.applied_version_id then
    raise exception 'The Quote review changed. Refresh before applying.' using errcode='40001'; end if;
  if not exists(select 1 from public."CusQuote_Versions" version where version."CusQuoteVersion_ID"=review_row.proposed_version_id
      and version."CusQuoteHeader_ID"=job_row."Job_SourceQuoteID" and version."CusQuoteVersion_IsSubmitted" and version."CusQuoteVersion_StatusCode"='accepted'
      and exists(select 1 from public."CusQuote_Header" quote where quote."CusQuoteHeader_ID"=version."CusQuoteHeader_ID" and not quote."CusQuoteHeader_IsDeleted")
      and not exists(select 1 from public."CusQuote_Versions" newer where newer."CusQuoteHeader_ID"=version."CusQuoteHeader_ID"
        and newer."CusQuoteVersion_Number">version."CusQuoteVersion_Number" and newer."CusQuoteVersion_IsSubmitted" and newer."CusQuoteVersion_StatusCode"='accepted')) then
    raise exception 'This is no longer the latest accepted Quote. Refresh the review.' using errcode='40001'; end if;
  refreshed:=booking_api.refreshed_cargo_review(requested_review_id);
  if expected_review_token is distinct from refreshed->>'reviewToken' then
    raise exception 'The Booking or review changed. Refresh and check the differences before applying.' using errcode='40001'; end if;
  if exists(select 1 from jsonb_array_elements_text(selected) field where not exists(select 1 from jsonb_array_elements(refreshed->'differences') d
    where d->>'key'=field and nullif(d->>'blockedReason','') is null)) then
    raise exception 'A selected field is unavailable or needs a separate cargo mapping/value review.' using errcode='22023'; end if;
  if (selected ? 'mode' or (selected ? 'routing' and
    booking_api.routing_mode_review_required(refreshed#>'{booking,routing}',refreshed#>'{proposed,routing}')))
    and not coalesce(confirm_mode_change,false) then raise exception 'Confirm the mode change before applying it to the Booking.' using errcode='22023'; end if;
  -- Preserve the original booking_snapshot as creation evidence. Refreshed
  -- differences become the explicit decision record only inside Apply.
  update booking_api.quote_sync_reviews set differences=refreshed->'differences',baseline_snapshot=refreshed->'baseline',proposed_snapshot=refreshed->'proposed'
    where review_id=requested_review_id;
  select coalesce(jsonb_agg(value),'[]') into cargo_fields from jsonb_array_elements(selected) where value#>>'{}' like 'cargo:%';
  select coalesce(jsonb_agg(value),'[]') into other_fields from jsonb_array_elements(selected) where value#>>'{}' not like 'cargo:%';
  if jsonb_array_length(cargo_fields)>0 then
    result:=booking_api.apply_quote_cargo_fields(caller_auth_user_id,requested_job_id,requested_review_id,cargo_fields,refreshed#>'{booking,cargoLines}'); end if;
  if jsonb_array_length(other_fields)>0 then
    result:=public.booking_workflow_apply_quote_sync_confirmed(caller_auth_user_id,requested_job_id,requested_review_id,other_fields,confirm_mode_change); end if;
  if coalesce(confirm_mode_change,false) and (selected ? 'mode' or (selected ? 'routing' and
      booking_api.routing_mode_review_required(refreshed#>'{booking,routing}',refreshed#>'{proposed,routing}'))) then
    insert into booking_api.events(company_id,job_id,event_type,summary,metadata,actor_user_id)
      values(app_user."Company_ID",requested_job_id,'quote_mode_change_confirmed',
        'The operator confirmed transport mode changes when applying the accepted Quote revision.',
        jsonb_build_object('reviewId',requested_review_id,'quoteVersionId',review_row.proposed_version_id,
          'appliedFields',selected,'modeChangeConfirmed',true,'reviewToken',expected_review_token),app_user."User_ID");
  end if;
  select * into strict review_row from booking_api.quote_sync_reviews where review_id=requested_review_id;
  return coalesce(result,'{}')||jsonb_build_object('reviewId',requested_review_id,'status',review_row.status_code,'appliedFields',review_row.applied_fields,
    'remainingFields',(select count(*) from jsonb_array_elements(review_row.differences) d where not review_row.applied_fields ? (d->>'key')),
    'workspace',booking_api.workspace_with_document_groups(caller_auth_user_id,job_row."Job_BookingReference"));
exception when no_data_found or too_many_rows then raise exception 'The Quote review is unavailable in this workspace.' using errcode='42501';
end;
$$;


ALTER FUNCTION "public"."booking_workflow_apply_quote_sync_v2"("caller_auth_user_id" "uuid", "requested_job_id" "uuid", "requested_review_id" "uuid", "requested_fields" "jsonb", "expected_review_token" "text", "confirm_mode_change" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."booking_workflow_cancel_document_upload"("caller_auth_user_id" "uuid", "requested_reservation_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'booking_api'
    AS $$
declare actor_id uuid;
begin
  select "User_ID" into actor_id from public."cmp_Users"
  where "Auth_User_ID" = caller_auth_user_id and coalesce("User_AccessStatus", 'active') = 'active';
  update booking_api.document_upload_reservations set status_code = 'cancelled'
  where reservation_id = requested_reservation_id and actor_user_id = actor_id and status_code = 'reserved';
  return found;
end;
$$;


ALTER FUNCTION "public"."booking_workflow_cancel_document_upload"("caller_auth_user_id" "uuid", "requested_reservation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."booking_workflow_complete"("caller_auth_user_id" "uuid", "requested_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$ select booking_api.complete_booking(caller_auth_user_id, requested_job_id) $$;


ALTER FUNCTION "public"."booking_workflow_complete"("caller_auth_user_id" "uuid", "requested_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."booking_workflow_complete_document_upload"("caller_auth_user_id" "uuid", "requested_reservation_id" "uuid", "requested_file_name" "text", "requested_mime_type" "text", "requested_sha256" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'booking_api'
    AS $_$
declare
  actor record;
  reservation record;
  current_document record;
  stored_id uuid;
  old_stored_id uuid;
  old_blob text;
  document_id_value uuid;
  now_value timestamptz := clock_timestamp();
begin
  select app_user."User_ID", app_user."Company_ID" into actor
  from public."cmp_Users" app_user
  where app_user."Auth_User_ID" = caller_auth_user_id
    and coalesce(app_user."User_AccessStatus", 'active') = 'active';
  if actor."User_ID" is null or not booking_api.has_permission(caller_auth_user_id, 'Bookings.Write') then
    raise exception 'You are not authorised to attach booking documents.' using errcode = '42501';
  end if;
  if nullif(btrim(requested_file_name), '') is null or char_length(requested_file_name) > 240
     or nullif(btrim(requested_mime_type), '') is null or char_length(requested_mime_type) > 120
     or requested_sha256 !~ '^[0-9a-f]{64}$' then
    raise exception 'The uploaded document metadata is invalid.' using errcode = '22023';
  end if;

  select * into reservation from booking_api.document_upload_reservations
  where reservation_id = requested_reservation_id for update;
  if not found or reservation.actor_user_id <> actor."User_ID" or reservation.company_id <> actor."Company_ID" then
    raise exception 'That upload reservation is unavailable.' using errcode = '42501';
  end if;
  if reservation.status_code = 'completed' then
    return jsonb_build_object('documentId', reservation.document_id, 'storedObjectId', reservation.stored_object_id, 'blobName', reservation.blob_name, 'completed', true);
  end if;
  if reservation.status_code <> 'reserved' or reservation.expires_at <= now() then
    raise exception 'That upload reservation has expired.' using errcode = '22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(reservation.job_id::text || ':' || reservation.document_type, 0));

  select document.* into current_document
  from public."Job_Documents" document
  where document."JobDoc_JobID" = reservation.job_id
    and lower(document."JobDoc_DocTypeCodeSnapshot") = reservation.document_type
    and document."JobDoc_IsCurrentVersion" and not document."JobDoc_IsDeleted"
  for update;
  old_stored_id := current_document."JobDoc_StoredObjectID";
  old_blob := current_document."JobDoc_FilePath";

  insert into public."DOC_StoredObjects" (
    "DOCStoredObject_ConcernCode", "DOCStoredObject_AggregateType", "DOCStoredObject_AggregateID",
    "DOCStoredObject_ProviderCode", "DOCStoredObject_Container", "DOCStoredObject_BlobName",
    "DOCStoredObject_OriginalFileName", "DOCStoredObject_MimeType", "DOCStoredObject_FileSizeBytes",
    "DOCStoredObject_SHA256", "DOCStoredObject_StatusCode", "DOCStoredObject_CreatedAt",
    "DOCStoredObject_CreatedBy", "DOCStoredObject_DeletedAt", "DOCStoredObject_DeletedBy"
  ) values (
    'booking', 'job', reservation.job_id, 'supabase_storage', 'multideck-documents', reservation.blob_name,
    btrim(requested_file_name), btrim(requested_mime_type), reservation.file_size_bytes,
    requested_sha256, 'active', now_value, actor."User_ID", null, null
  ) on conflict ("DOCStoredObject_Container", "DOCStoredObject_BlobName") do update set
    "DOCStoredObject_ConcernCode" = excluded."DOCStoredObject_ConcernCode",
    "DOCStoredObject_AggregateType" = excluded."DOCStoredObject_AggregateType",
    "DOCStoredObject_AggregateID" = excluded."DOCStoredObject_AggregateID",
    "DOCStoredObject_OriginalFileName" = excluded."DOCStoredObject_OriginalFileName",
    "DOCStoredObject_MimeType" = excluded."DOCStoredObject_MimeType",
    "DOCStoredObject_FileSizeBytes" = excluded."DOCStoredObject_FileSizeBytes",
    "DOCStoredObject_SHA256" = excluded."DOCStoredObject_SHA256",
    "DOCStoredObject_StatusCode" = 'active',
    "DOCStoredObject_CreatedAt" = now_value,
    "DOCStoredObject_CreatedBy" = actor."User_ID",
    "DOCStoredObject_DeletedAt" = null,
    "DOCStoredObject_DeletedBy" = null
  returning "DOCStoredObject_ID" into stored_id;

  if current_document."JobDoc_ID" is null then
    insert into public."Job_Documents" (
      "JobDoc_JobID", "JobDoc_DocTypeCodeSnapshot", "JobDoc_Title", "JobDoc_Status", "JobDoc_Source",
      "JobDoc_FileName", "JobDoc_FilePath", "JobDoc_FileMimeType", "JobDoc_FileSizeBytes",
      "JobDoc_IsCurrentVersion", "JobDoc_IsPrimary", "JobDoc_StoredObjectID", "JobDoc_ReceivedAt",
      "JobDoc_MetadataJSON", "JobDoc_CreatedBy", "JobDoc_UpdatedBy"
    ) values (
      reservation.job_id, reservation.document_type,
      case when reservation.document_type = 'commercial_invoice' then 'Commercial invoice' else 'Packing list' end,
      'received', 'booking_workspace', btrim(requested_file_name), reservation.blob_name,
      btrim(requested_mime_type), reservation.file_size_bytes, true, true, stored_id, now_value,
      jsonb_build_object('storageBucket', 'multideck-documents', 'sha256', requested_sha256),
      actor."User_ID", actor."User_ID"
    ) returning "JobDoc_ID" into document_id_value;
  else
    document_id_value := current_document."JobDoc_ID";
    update public."Job_Documents" set
      "JobDoc_FileName" = btrim(requested_file_name),
      "JobDoc_FilePath" = reservation.blob_name,
      "JobDoc_FileMimeType" = btrim(requested_mime_type),
      "JobDoc_FileSizeBytes" = reservation.file_size_bytes,
      "JobDoc_StoredObjectID" = stored_id,
      "JobDoc_ReceivedAt" = now_value,
      "JobDoc_MetadataJSON" = jsonb_build_object('storageBucket', 'multideck-documents', 'sha256', requested_sha256),
      "JobDoc_UpdatedAt" = now_value,
      "JobDoc_UpdatedBy" = actor."User_ID"
    where "JobDoc_ID" = document_id_value;
  end if;

  if old_stored_id is not null and old_stored_id <> stored_id then
    update public."DOC_StoredObjects" set
      "DOCStoredObject_StatusCode" = 'deleted', "DOCStoredObject_DeletedAt" = now_value,
      "DOCStoredObject_DeletedBy" = actor."User_ID"
    where "DOCStoredObject_ID" = old_stored_id;
  end if;
  update booking_api.document_upload_reservations set
    status_code = 'completed', document_id = document_id_value, stored_object_id = stored_id,
    completed_at = now_value
  where reservation_id = reservation.reservation_id;
  return jsonb_build_object(
    'documentId', document_id_value, 'storedObjectId', stored_id, 'blobName', reservation.blob_name,
    'oldBlobName', case when old_blob is distinct from reservation.blob_name then old_blob else null end,
    'fileName', btrim(requested_file_name), 'documentType', reservation.document_type, 'completed', true
  );
end;
$_$;


