CREATE OR REPLACE FUNCTION "public"."booking_workflow_completion_readiness"("caller_auth_user_id" "uuid", "requested_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$ select booking_api.completion_readiness(caller_auth_user_id, requested_job_id) $$;


