COMMENT ON FUNCTION "public"."booking_workflow_open_road"("caller_auth_user_id" "uuid", "requested_idempotency_key" "uuid", "requested_sequence_key" "text") IS 'Atomic operator Road draft opening through canonical open/save; no transport instruction or customer acceptance.';



CREATE OR REPLACE FUNCTION "public"."booking_workflow_open_road"("caller_auth_user_id" "uuid", "requested_idempotency_key" "uuid", "requested_sequence_key" "text", "requested_direction" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare opened jsonb;
begin
  opened:=booking_api.open_booking(caller_auth_user_id,requested_idempotency_key,requested_sequence_key,requested_direction);
  if (opened->>'reused')::boolean is false then
    perform public.booking_workflow_save(caller_auth_user_id,(opened->>'jobId')::uuid,'{"mode":"road"}');end if;
  return opened;
end $$;


