CREATE OR REPLACE FUNCTION "public"."cmp_claim_screening_refresh"("p_token" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_source public."sys_ScreeningListSources"; v_status jsonb;
begin
  select * into v_source from public."sys_ScreeningListSources"
  where "ScreeningListSource_Code" = public._cmp_screening_refresh_source_code() for update;
  if not found or not v_source."ScreeningListSource_IsActive" then
    raise exception 'The UK Sanctions List source is unavailable.';
  end if;
  if v_source."ScreeningListSource_RefreshExpiresAt" > now() then return 'busy'; end if;
  v_status := public.cmp_screening_list_status();
  if not (v_status->>'stale')::boolean then return 'current'; end if;
  -- A shared cooldown also covers a crashed/expired worker, not just HTTP errors.
  if v_source."ScreeningListSource_LastAttemptAt" > now() - interval '1 minute' then return 'cooldown'; end if;
  update public."sys_ScreeningListSources" set
    "ScreeningListSource_RefreshToken" = p_token,
    "ScreeningListSource_RefreshExpiresAt" = now() + interval '5 minutes',
    "ScreeningListSource_LastAttemptAt" = now()
  where "ScreeningListSource_Code" = public._cmp_screening_refresh_source_code();
  return 'acquired';
end;
$$;


ALTER FUNCTION "public"."cmp_claim_screening_refresh"("p_token" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cmp_decide_screening_check"("p_company_id" "uuid", "p_user_id" "uuid", "p_check_id" "uuid", "p_action" "text", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_check public."CMP_ScreeningChecks"%rowtype;
  v_action text := lower(btrim(p_action));
  v_due_at timestamptz;
begin
  if v_action not in ('manual_clean', 'sanctioned') then
    raise exception 'Choose clean or sanctioned.' using errcode = '22023';
  end if;
  select * into v_check
  from public."CMP_ScreeningChecks"
  where "ScreeningCheck_ID" = p_check_id and "ScreeningCheck_CompanyID" = p_company_id
  for update;
  if not found then
    raise exception 'That screening result is not available.' using errcode = '22023';
  end if;
  if v_check."ScreeningCheck_DecisionCode" not in ('review_required', 'manual_clean', 'sanctioned') then
    raise exception 'Only a review item can be resolved manually.' using errcode = '22023';
  end if;
  v_due_at := now() + case when v_action = 'manual_clean' then interval '30 days' else interval '1 day' end;
  insert into public."CMP_ScreeningDecisions" (
    "ScreeningDecision_CheckID", "ScreeningDecision_CompanyID", "ScreeningDecision_ActionCode", "ScreeningDecision_Note", "ScreeningDecision_DecidedBy"
  ) values (p_check_id, p_company_id, v_action, nullif(btrim(p_note), ''), p_user_id);
  update public."CMP_ScreeningChecks"
  set
    "ScreeningCheck_DecisionCode" = v_action,
    "ScreeningCheck_DecisionNote" = nullif(btrim(p_note), ''),
    "ScreeningCheck_DecidedBy" = p_user_id,
    "ScreeningCheck_DecidedAt" = now(),
    "ScreeningCheck_RescreenDueAt" = v_due_at
  where "ScreeningCheck_ID" = p_check_id;
  return jsonb_build_object('id', p_check_id, 'decisionCode', v_action, 'decisionAt', now(), 'rescreenDueAt', v_due_at);
end;
$$;


ALTER FUNCTION "public"."cmp_decide_screening_check"("p_company_id" "uuid", "p_user_id" "uuid", "p_check_id" "uuid", "p_action" "text", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cmp_fail_screening_refresh"("p_token" "uuid", "p_message" "text") RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  update public."sys_ScreeningListSources" set
    "ScreeningListSource_LastError" = left(coalesce(p_message, 'The sanctions list could not be checked.'), 500),
    "ScreeningListSource_RefreshToken" = null, "ScreeningListSource_RefreshExpiresAt" = null
  where "ScreeningListSource_Code" = public._cmp_screening_refresh_source_code() and "ScreeningListSource_RefreshToken" = p_token;
$$;


ALTER FUNCTION "public"."cmp_fail_screening_refresh"("p_token" "uuid", "p_message" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cmp_finish_screening_refresh"("p_token" "uuid", "p_snapshot_id" "uuid", "p_hash" "text", "p_entry_count" integer, "p_group_count" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare v_source public."sys_ScreeningListSources"; v_snapshot public."sys_ScreeningListSnapshots"; v_count integer;
begin
  select * into v_source from public."sys_ScreeningListSources"
  where "ScreeningListSource_Code" = public._cmp_screening_refresh_source_code() for update;
  if v_source."ScreeningListSource_RefreshToken" is distinct from p_token
    or v_source."ScreeningListSource_RefreshExpiresAt" is null
    or v_source."ScreeningListSource_RefreshExpiresAt" <= now() then
    raise exception 'The sanctions refresh lease expired. Retry the check.';
  end if;
  select * into v_snapshot from public."sys_ScreeningListSnapshots"
  where "ScreeningListSnapshot_ID" = p_snapshot_id and "ScreeningListSnapshot_SourceCode" = public._cmp_screening_refresh_source_code() for update;
  if not found or v_snapshot."ScreeningListSnapshot_StatusCode" not in ('importing', 'current')
    or v_snapshot."ScreeningListSnapshot_FeedUrl" is distinct from v_source."ScreeningListSource_DownloadUrl" then
    raise exception 'The downloaded sanctions snapshot is not valid.';
  end if;
  select count(*) into v_count from public."sys_ScreeningListEntries" where "ScreeningListEntry_SnapshotID" = p_snapshot_id;
  if p_hash is null or p_hash !~ '^[a-f0-9]{64}$' or p_entry_count is null or p_group_count is null
    or p_entry_count <= 0 or p_group_count <= 0 or v_count <> p_entry_count then
    raise exception 'The sanctions download is incomplete. The previous list was preserved.';
  end if;
  if v_snapshot."ScreeningListSnapshot_StatusCode" = 'current' and v_snapshot."ScreeningListSnapshot_ContentSha256" <> p_hash then
    raise exception 'The sanctions content changed and must be imported.';
  end if;
  -- Publication and success evidence commit together. Readers never see half an import.
  update public."sys_ScreeningListSnapshots" set "ScreeningListSnapshot_StatusCode" = 'superseded'
    where "ScreeningListSnapshot_SourceCode" = public._cmp_screening_refresh_source_code()
      and "ScreeningListSnapshot_StatusCode" = 'current' and "ScreeningListSnapshot_ID" <> p_snapshot_id;
  update public."sys_ScreeningListSnapshots" set
    "ScreeningListSnapshot_StatusCode" = 'current', "ScreeningListSnapshot_ContentSha256" = p_hash,
    "ScreeningListSnapshot_EntryCount" = p_entry_count, "ScreeningListSnapshot_GroupCount" = p_group_count,
    "ScreeningListSnapshot_CheckedAt" = now()
    where "ScreeningListSnapshot_ID" = p_snapshot_id;
  update public."sys_ScreeningListSources" set
    "ScreeningListSource_LastSuccessAt" = now(), "ScreeningListSource_LastError" = null,
    "ScreeningListSource_RefreshToken" = null, "ScreeningListSource_RefreshExpiresAt" = null
    where "ScreeningListSource_Code" = public._cmp_screening_refresh_source_code();
end;
$_$;


ALTER FUNCTION "public"."cmp_finish_screening_refresh"("p_token" "uuid", "p_snapshot_id" "uuid", "p_hash" "text", "p_entry_count" integer, "p_group_count" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cmp_normalize_screening_name"("p_name" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select nullif(btrim(regexp_replace(
    regexp_replace(
      regexp_replace(
        translate(
          lower(coalesce(p_name, '')),
          'àáâãäåçèéêëìíîïñòóôõöùúûüýÿ',
          'aaaaaaceeeeiiiinooooouuuuyy'
        ),
        '[^a-z0-9]+',
        ' ',
        'g'
      ),
      '\y(limited|ltd|llc|inc|gmbh|plc|corp|incorporated|company|co|sa|bv|ag|pty|sarl|llp)\y',
      ' ',
      'g'
    ),
    '\s+',
    ' ',
    'g'
  )), '');
$$;


ALTER FUNCTION "public"."cmp_normalize_screening_name"("p_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cmp_run_screening_check"("p_company_id" "uuid", "p_user_id" "uuid", "p_subject_name" "text", "p_country" "text" DEFAULT NULL::"text", "p_org_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select public.cmp_run_screening_check_v2(p_company_id, p_user_id, p_subject_name, p_country, p_org_id, p_include_similar => true);
$$;


ALTER FUNCTION "public"."cmp_run_screening_check"("p_company_id" "uuid", "p_user_id" "uuid", "p_subject_name" "text", "p_country" "text", "p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cmp_run_screening_check_v2"("p_company_id" "uuid", "p_user_id" "uuid", "p_subject_name" "text", "p_country" "text" DEFAULT NULL::"text", "p_org_id" "uuid" DEFAULT NULL::"uuid", "p_source_area" "text" DEFAULT 'manual'::"text", "p_source_record_id" "text" DEFAULT NULL::"text", "p_source_label" "text" DEFAULT NULL::"text", "p_subject_role" "text" DEFAULT 'party'::"text", "p_include_similar" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'extensions'
    AS $$
declare
  v_normalized text := public.cmp_normalize_screening_name(p_subject_name);
  v_snapshot record;
  v_check_id uuid := gen_random_uuid();
  v_outcome text := 'unavailable';
  v_decision text := 'unavailable';
  v_match_count integer := 0;
  v_age_hours numeric(10, 2) := null;
  v_stale boolean := true;
  v_matches jsonb := '[]'::jsonb;
  v_source_area text := lower(coalesce(nullif(btrim(p_source_area), ''), 'manual'));
  v_subject_role text := lower(coalesce(nullif(btrim(p_subject_role), ''), 'party'));
  v_rescreen_due_at timestamptz;
  v_list jsonb;
begin
  if v_normalized is null or char_length(v_normalized) < 3 then
    raise exception 'Enter a party name with at least three letters.' using errcode = '22023';
  end if;
  if v_source_area not in ('manual', 'customer', 'crm', 'quote', 'booking', 'customs', 'document', 'other') then
    raise exception 'That screening context is not supported.' using errcode = '22023';
  end if;
  if p_org_id is not null and not exists (
    select 1 from public."Org_Master" organisation where organisation."Org_id" = p_org_id
  ) then
    raise exception 'That organisation is not available in this workspace.' using errcode = '22023';
  end if;

  -- Lock source state through the check, so publication/failure cannot race this result.
  perform 1 from public."sys_ScreeningListSources" where "ScreeningListSource_Code" = public._cmp_screening_refresh_source_code() for share;
  v_list := public.cmp_screening_list_status();
  select snapshot."ScreeningListSnapshot_ID" as snapshot_id, snapshot."ScreeningListSnapshot_CheckedAt" as checked_at
  into v_snapshot
  from public."sys_ScreeningListSnapshots" snapshot
  where snapshot."ScreeningListSnapshot_SourceCode" = public._cmp_screening_refresh_source_code()
    and snapshot."ScreeningListSnapshot_StatusCode" = 'current';

  if v_snapshot.snapshot_id is not null and not coalesce((v_list->>'stale')::boolean, true) then
    perform set_config('pg_trgm.similarity_threshold', '0.82', true);
    perform set_config('pg_trgm.word_similarity_threshold', '0.82', true);
    v_age_hours := round(extract(epoch from (now() - v_snapshot.checked_at)) / 3600.0, 2);
    v_stale := false;

    select coalesce(jsonb_agg(match_row order by (match_row->>'score')::numeric desc), '[]'::jsonb)
    into v_matches
    from (
      select jsonb_build_object(
        'entryId', entry."ScreeningListEntry_ID",
        'groupId', entry."ScreeningListEntry_GroupId",
        'listedName', entry."ScreeningListEntry_Name",
        'matchKind', case when entry."ScreeningListEntry_NormalizedName" = v_normalized then 'exact' else 'similar' end,
        'score', case when entry."ScreeningListEntry_NormalizedName" = v_normalized then 1 else round(greatest(extensions.similarity(v_normalized, entry."ScreeningListEntry_NormalizedName"), extensions.word_similarity(v_normalized, entry."ScreeningListEntry_NormalizedName"))::numeric, 4) end,
        'regime', entry."ScreeningListEntry_Regime",
        'groupType', entry."ScreeningListEntry_GroupType",
        'listedOn', entry."ScreeningListEntry_ListedOn",
        'ukRef', entry."ScreeningListEntry_UkRef",
        'country', entry."ScreeningListEntry_Country",
        'listingNotes', entry."ScreeningListEntry_OtherInformation"
      ) as match_row
      from public."sys_ScreeningListEntries" entry
      where entry."ScreeningListEntry_SnapshotID" = v_snapshot.snapshot_id
        and (
          entry."ScreeningListEntry_NormalizedName" = v_normalized
          or (coalesce(p_include_similar, false) and (entry."ScreeningListEntry_NormalizedName" % v_normalized or v_normalized <% entry."ScreeningListEntry_NormalizedName"))
        )
      order by
        (entry."ScreeningListEntry_NormalizedName" = v_normalized) desc,
        greatest(extensions.similarity(v_normalized, entry."ScreeningListEntry_NormalizedName"), extensions.word_similarity(v_normalized, entry."ScreeningListEntry_NormalizedName")) desc
    ) ranked;
    v_match_count := jsonb_array_length(v_matches);
    v_outcome := case
      when exists (select 1 from jsonb_array_elements(v_matches) item where item->>'matchKind' = 'exact') then 'match'
      when v_match_count > 0 then 'possible_match'
      else 'clear'
    end;
    v_decision := case
      when v_stale then 'unavailable'
      when v_match_count > 0 then 'review_required'
      else 'automatic_clear'
    end;
  end if;

  v_rescreen_due_at := now() + case when v_decision = 'automatic_clear' then interval '30 days' else interval '1 day' end;
  insert into public."CMP_ScreeningChecks" (
    "ScreeningCheck_ID", "ScreeningCheck_CompanyID", "ScreeningCheck_CreatedBy", "ScreeningCheck_OrgID", "ScreeningCheck_SnapshotID",
    "ScreeningCheck_SubjectName", "ScreeningCheck_NormalizedName", "ScreeningCheck_Country", "ScreeningCheck_OutcomeCode", "ScreeningCheck_MatchCount",
    "ScreeningCheck_ListAgeHours", "ScreeningCheck_ListStale", "ScreeningCheck_IncludeSimilar", "ScreeningCheck_SourceArea", "ScreeningCheck_SourceRecordID",
    "ScreeningCheck_SourceLabel", "ScreeningCheck_SubjectRole", "ScreeningCheck_DecisionCode", "ScreeningCheck_DecidedAt", "ScreeningCheck_RescreenDueAt"
  ) values (
    v_check_id, p_company_id, p_user_id, p_org_id, v_snapshot.snapshot_id, btrim(p_subject_name), v_normalized, nullif(btrim(p_country), ''),
    v_outcome, v_match_count, v_age_hours, v_stale, coalesce(p_include_similar, false), v_source_area, nullif(btrim(p_source_record_id), ''),
    nullif(btrim(p_source_label), ''), v_subject_role, v_decision, now(), v_rescreen_due_at
  );

  insert into public."CMP_ScreeningMatches" (
    "ScreeningMatch_CheckID", "ScreeningMatch_EntryID", "ScreeningMatch_GroupId", "ScreeningMatch_ListedName", "ScreeningMatch_MatchKind",
    "ScreeningMatch_Score", "ScreeningMatch_Regime", "ScreeningMatch_GroupType", "ScreeningMatch_ListedOn", "ScreeningMatch_UkRef", "ScreeningMatch_Country", "ScreeningMatch_ListingNotes"
  )
  select v_check_id, nullif(item->>'entryId', '')::uuid, item->>'groupId', item->>'listedName', item->>'matchKind', (item->>'score')::numeric,
    item->>'regime', item->>'groupType', nullif(item->>'listedOn', '')::date, item->>'ukRef', item->>'country', nullif(item->>'listingNotes', '')
  from jsonb_array_elements(v_matches) item;

  return jsonb_build_object(
    'id', v_check_id, 'subjectName', btrim(p_subject_name), 'country', nullif(btrim(p_country), ''), 'orgId', p_org_id,
    'outcome', v_outcome, 'matchCount', v_match_count, 'totalCount', v_match_count, 'listAgeHours', v_age_hours, 'listStale', v_stale,
    'includeSimilar', coalesce(p_include_similar, false), 'sourceArea', v_source_area, 'sourceRecordId', nullif(btrim(p_source_record_id), ''),
    'sourceLabel', nullif(btrim(p_source_label), ''), 'subjectRole', v_subject_role, 'decisionCode', v_decision,
    'decisionAt', now(), 'rescreenDueAt', v_rescreen_due_at, 'createdAt', now(), 'matches', v_matches
  );
end;
$$;


ALTER FUNCTION "public"."cmp_run_screening_check_v2"("p_company_id" "uuid", "p_user_id" "uuid", "p_subject_name" "text", "p_country" "text", "p_org_id" "uuid", "p_source_area" "text", "p_source_record_id" "text", "p_source_label" "text", "p_subject_role" "text", "p_include_similar" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cmp_screening_list_status"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select coalesce((select jsonb_build_object(
    'loaded', snapshot."ScreeningListSnapshot_ID" is not null,
    'sourceCode', source."ScreeningListSource_Code",
    'sourceName', source."ScreeningListSource_Name",
    'publisher', source."ScreeningListSource_Publisher",
    'snapshotId', snapshot."ScreeningListSnapshot_ID",
    'downloadedAt', snapshot."ScreeningListSnapshot_DownloadedAt",
    'checkedAt', snapshot."ScreeningListSnapshot_CheckedAt",
    'lastAttemptAt', source."ScreeningListSource_LastAttemptAt",
    'lastSuccessAt', source."ScreeningListSource_LastSuccessAt",
    'lastError', source."ScreeningListSource_LastError",
    'entryCount', coalesce(snapshot."ScreeningListSnapshot_EntryCount", 0),
    'groupCount', coalesce(snapshot."ScreeningListSnapshot_GroupCount", 0),
    'refreshing', coalesce(source."ScreeningListSource_RefreshExpiresAt" > now(), false),
    'stale', snapshot."ScreeningListSnapshot_ID" is null
      or snapshot."ScreeningListSnapshot_FeedUrl" is distinct from source."ScreeningListSource_DownloadUrl"
      or snapshot."ScreeningListSnapshot_CheckedAt" < now() - make_interval(hours => least(12, greatest(1, source."ScreeningListSource_RefreshIntervalHours")))
      or snapshot."ScreeningListSnapshot_EntryCount" <= 0
      or source."ScreeningListSource_LastError" is not null
      or not source."ScreeningListSource_IsActive"
  ) from public."sys_ScreeningListSources" source
  left join public."sys_ScreeningListSnapshots" snapshot
    on snapshot."ScreeningListSnapshot_SourceCode" = source."ScreeningListSource_Code"
    and snapshot."ScreeningListSnapshot_StatusCode" = 'current'
  where source."ScreeningListSource_Code" = public._cmp_screening_refresh_source_code()), '{"loaded":false,"stale":true}'::jsonb);
$$;


ALTER FUNCTION "public"."cmp_screening_list_status"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."comm_begin_email_oauth_state"("p_state_hash" character varying, "p_provider_code" character varying, "p_auth_user_id" "uuid", "p_return_path" "text" DEFAULT '/inbox'::"text", "p_pkce_verifier_secret_ref" character varying DEFAULT NULL::character varying, "p_requested_scopes" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_user_id uuid;
  v_state_id uuid;
begin
  if p_auth_user_id is null then
    raise exception 'An authenticated user is required.' using errcode = '22023';
  end if;

  if p_provider_code not in ('gmail', 'outlook') then
    raise exception 'Unsupported email provider.' using errcode = '22023';
  end if;

  if p_state_hash is null or length(btrim(p_state_hash)) not between 32 and 128 then
    raise exception 'OAuth state hash is invalid.' using errcode = '22023';
  end if;

  if p_return_path is null
     or p_return_path !~ '^/[^/].*'
     or p_return_path ~ '[[:cntrl:]]' then
    raise exception 'OAuth return path must be a local application path.' using errcode = '22023';
  end if;

  if p_requested_scopes is null or jsonb_typeof(p_requested_scopes) <> 'array' then
    raise exception 'Requested scopes must be a JSON array.' using errcode = '22023';
  end if;

  select workspace_user."User_ID"
    into v_user_id
  from public."cmp_Users" as workspace_user
  where workspace_user."Auth_User_ID" = p_auth_user_id
  order by workspace_user."User_ID"
  limit 1;

  if v_user_id is null then
    -- Keep a missing workspace profile distinct from Email.Connect denial so the
    -- OAuth boundary can return a fixed public error without matching text.
    raise exception 'No Multideck workspace user matches this identity.' using errcode = 'P0002';
  end if;

  if not exists (
    select 1
    from public."cmp_Users_Roles" as user_role
    join public."sys_UserRole_Permissions" as role_permission
      on role_permission."sys_UserRole_ID" = user_role."sys_UserRole_ID"
    join public."sys_Permissions" as permission
      on permission."sys_Permission_ID" = role_permission."sys_Permission_ID"
    where user_role."User_ID" = v_user_id
      and permission."sys_Permission_Value" = 'Email.Connect'
  ) then
    raise exception 'Email.Connect permission is required.' using errcode = '42501';
  end if;

  insert into public."Comm_OAuthStates" (
    "CommOAuthState_StateHash",
    "CommOAuthState_ProviderCode",
    "CommOAuthState_UserID",
    "CommOAuthState_ReturnPath",
    "CommOAuthState_PKCEVerifierSecretRef",
    "CommOAuthState_RequestedScopes"
  )
  values (
    btrim(p_state_hash),
    p_provider_code,
    v_user_id,
    p_return_path,
    nullif(btrim(p_pkce_verifier_secret_ref), ''),
    p_requested_scopes
  )
  returning "CommOAuthState_ID" into v_state_id;

  return v_state_id;
end;
$$;


ALTER FUNCTION "public"."comm_begin_email_oauth_state"("p_state_hash" character varying, "p_provider_code" character varying, "p_auth_user_id" "uuid", "p_return_path" "text", "p_pkce_verifier_secret_ref" character varying, "p_requested_scopes" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."comm_claim_email_watch_owners"("p_mode" "text", "p_lease_token" "uuid", "p_limit" integer DEFAULT 5) RETURNS TABLE("owner_user_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_mode text := case when p_mode = 'backfill' then 'backfill' else 'live' end;
  v_limit integer := greatest(1, least(coalesce(p_limit, 5), 10));
  v_lease_seconds integer := case when p_mode = 'backfill' then 300 else 120 end;
begin
  if p_lease_token is null then
    raise exception 'A worker lease token is required.' using errcode = '22023';
  end if;

  insert into public."Comm_EmailWatchWorkerState" (
    "CommWatchWorker_OwnerUserID",
    "CommWatchWorker_ModeCode"
  )
  select distinct connection."CommConn_UserID", v_mode
  from public."Comm_ProviderConnections" connection
  join public."cmp_Users" profile
    on profile."User_ID" = connection."CommConn_UserID"
   and profile."Company_ID" is not null
  where connection."CommConn_StatusCode" = 'active'
    and connection."CommConn_InboundEnabled"
    and not connection."CommConn_IsDeleted"
    and connection."CommConn_UserID" is not null
  on conflict ("CommWatchWorker_OwnerUserID", "CommWatchWorker_ModeCode") do nothing;

  return query
  with candidates as (
    select state."CommWatchWorker_OwnerUserID", state."CommWatchWorker_ModeCode"
    from public."Comm_EmailWatchWorkerState" state
    where state."CommWatchWorker_ModeCode" = v_mode
      and (
        state."CommWatchWorker_LeaseUntil" is null
        or state."CommWatchWorker_LeaseUntil" <= clock_timestamp()
      )
      and exists (
        select 1
        from public."Comm_ProviderConnections" connection
        where connection."CommConn_UserID" = state."CommWatchWorker_OwnerUserID"
          and connection."CommConn_StatusCode" = 'active'
          and connection."CommConn_InboundEnabled"
          and not connection."CommConn_IsDeleted"
        limit 1
      )
    order by state."CommWatchWorker_LastClaimedAt" asc nulls first,
      state."CommWatchWorker_OwnerUserID"
    for update of state skip locked
    limit v_limit
  ), claimed as (
    update public."Comm_EmailWatchWorkerState" state
    set "CommWatchWorker_LeaseToken" = p_lease_token,
        "CommWatchWorker_LeaseUntil" = clock_timestamp() + make_interval(secs => v_lease_seconds),
        "CommWatchWorker_LastClaimedAt" = clock_timestamp()
    from candidates
    where state."CommWatchWorker_OwnerUserID" = candidates."CommWatchWorker_OwnerUserID"
      and state."CommWatchWorker_ModeCode" = candidates."CommWatchWorker_ModeCode"
    returning state."CommWatchWorker_OwnerUserID"
  )
  select claimed."CommWatchWorker_OwnerUserID"
  from claimed
  order by claimed."CommWatchWorker_OwnerUserID";
end;
$$;


ALTER FUNCTION "public"."comm_claim_email_watch_owners"("p_mode" "text", "p_lease_token" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."comm_complete_email_oauth_connection"("p_oauth_state_id" "uuid", "p_provider_type_code" character varying, "p_connection_name" character varying, "p_secret_ref" character varying, "p_provider_tenant_id" character varying, "p_provider_account_id" character varying, "p_mailbox_display_name" character varying, "p_mailbox_address" character varying, "p_provider_mailbox_id" character varying, "p_mailbox_type_code" character varying DEFAULT 'personal'::character varying, "p_scopes" "jsonb" DEFAULT '[]'::"jsonb") RETURNS TABLE("connection_id" "uuid", "mailbox_id" "uuid", "replaced_secret_ref" character varying)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  v_state_provider varchar(40);
  v_user_id uuid;
  v_expected_provider_type varchar(60);
  v_connection_id uuid;
  v_mailbox_id uuid;
  v_previous_secret_ref varchar(240);
  v_previous_provider_tenant_id varchar(180);
  v_previous_provider_account_id varchar(180);
  v_normalized_address varchar(320);
  v_now timestamptz := now();
begin
  if p_provider_type_code not in ('google_workspace', 'microsoft_365') then
    raise exception 'Unsupported provider type.' using errcode = '22023';
  end if;

  if p_mailbox_type_code not in ('personal', 'shared', 'group') then
    raise exception 'Unsupported mailbox type.' using errcode = '22023';
  end if;

  if p_scopes is null or jsonb_typeof(p_scopes) <> 'array' then
    raise exception 'Granted scopes must be a JSON array.' using errcode = '22023';
  end if;

  if p_provider_account_id is null
     or length(btrim(p_provider_account_id)) not between 1 and 180 then
    raise exception 'A provider account identity is required.' using errcode = '22023';
  end if;

  if p_provider_tenant_id is not null
     and length(btrim(p_provider_tenant_id)) not between 1 and 180 then
    raise exception 'Provider tenant identity is invalid.' using errcode = '22023';
  end if;

  if p_secret_ref is null
     or btrim(p_secret_ref)
       !~ '^supabase-vault:[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
    raise exception 'An opaque credential secret reference is required.' using errcode = '22023';
  end if;

  v_normalized_address := lower(btrim(p_mailbox_address));
  if v_normalized_address is null
     or length(v_normalized_address) > 320
     or v_normalized_address !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then
    raise exception 'A valid mailbox address is required.' using errcode = '22023';
  end if;

  select
    oauth_state."CommOAuthState_ProviderCode",
    oauth_state."CommOAuthState_UserID"
  into v_state_provider, v_user_id
  from public."Comm_OAuthStates" as oauth_state
  where oauth_state."CommOAuthState_ID" = p_oauth_state_id
    and oauth_state."CommOAuthState_ConsumedAt" is not null
    and oauth_state."CommOAuthState_FailedAt" is null
    and oauth_state."CommOAuthState_CreatedAt" > v_now - interval '1 day'
  for update;

  if v_user_id is null then
    raise exception 'OAuth state is not valid for completion.' using errcode = '42501';
  end if;

  -- Re-check at completion so revocation during the provider round trip takes
  -- effect before any credential reference, connection, mailbox, or ACL write.
  if not exists (
    select 1
    from public."cmp_Users_Roles" as user_role
    join public."sys_UserRole_Permissions" as role_permission
      on role_permission."sys_UserRole_ID" = user_role."sys_UserRole_ID"
    join public."sys_Permissions" as permission
      on permission."sys_Permission_ID" = role_permission."sys_Permission_ID"
    where user_role."User_ID" = v_user_id
      and permission."sys_Permission_Value" = 'Email.Connect'
  ) then
    raise exception 'Email.Connect permission is required.' using errcode = '42501';
  end if;

  v_expected_provider_type := case v_state_provider
    when 'gmail' then 'google_workspace'
    when 'outlook' then 'microsoft_365'
    else null
  end;

  if v_expected_provider_type is distinct from p_provider_type_code then
    raise exception 'OAuth provider does not match the connection provider.' using errcode = '42501';
  end if;

  select
    connection."CommConn_ID",
    connection."CommConn_SecretRef",
    connection."CommConn_ProviderTenantID",
    connection."CommConn_ProviderAccountID"
  into
    v_connection_id,
    v_previous_secret_ref,
    v_previous_provider_tenant_id,
    v_previous_provider_account_id
  from public."Comm_ProviderConnections" as connection
  where connection."CommConn_UserID" = v_user_id
    and connection."CommConn_ProviderTypeCode" = p_provider_type_code
    and not connection."CommConn_IsDeleted"
  order by connection."CommConn_UpdatedAt" desc
  limit 1
  for update;

  if v_connection_id is not null
     and (
       (
         nullif(btrim(v_previous_provider_account_id), '') is not null
         and nullif(btrim(v_previous_provider_account_id), '')
           is distinct from nullif(btrim(p_provider_account_id), '')
       )
       or (
         nullif(btrim(v_previous_provider_tenant_id), '') is not null
         and nullif(btrim(v_previous_provider_tenant_id), '')
           is distinct from nullif(btrim(p_provider_tenant_id), '')
       )
     ) then
    raise exception
      'A different provider account is already connected. Disconnect it before connecting another account.'
      using errcode = '42501';
  end if;

  if v_connection_id is null then
    insert into public."Comm_ProviderConnections" (
      "CommConn_Name",
      "CommConn_ProviderTypeCode",
      "CommConn_DefaultChannelCode",
      "CommConn_StatusCode",
      "CommConn_UserID",
      "CommConn_AuthType",
      "CommConn_SecretRef",
      "CommConn_ProviderTenantID",
      "CommConn_ProviderAccountID",
      "CommConn_InboundEnabled",
      "CommConn_OutboundEnabled",
      "CommConn_RateLimitJSON",
      "CommConn_SettingsJSON",
      "CommConn_CreatedAt",
      "CommConn_CreatedBy",
      "CommConn_UpdatedAt",
      "CommConn_UpdatedBy",
      "CommConn_IsDeleted"
    )
    values (
      left(coalesce(nullif(btrim(p_connection_name), ''), p_provider_type_code), 160),
      p_provider_type_code,
      'email',
      'active',
      v_user_id,
      'oauth2',
      btrim(p_secret_ref),
      nullif(left(btrim(p_provider_tenant_id), 180), ''),
      nullif(left(btrim(p_provider_account_id), 180), ''),
      true,
      true,
      '{}'::jsonb,
      jsonb_build_object('oauthScopes', p_scopes, 'oauthProvider', v_state_provider),
      v_now,
      v_user_id,
      v_now,
      v_user_id,
      false
    )
    returning "CommConn_ID" into v_connection_id;
  else
    update public."Comm_ProviderConnections" as connection
    set "CommConn_Name" = left(coalesce(nullif(btrim(p_connection_name), ''), connection."CommConn_Name"), 160),
        "CommConn_StatusCode" = 'active',
        "CommConn_AuthType" = 'oauth2',
        "CommConn_SecretRef" = btrim(p_secret_ref),
        "CommConn_ProviderTenantID" = nullif(left(btrim(p_provider_tenant_id), 180), ''),
        "CommConn_ProviderAccountID" = nullif(left(btrim(p_provider_account_id), 180), ''),
        "CommConn_InboundEnabled" = true,
        "CommConn_OutboundEnabled" = true,
        "CommConn_SettingsJSON" = coalesce(connection."CommConn_SettingsJSON", '{}'::jsonb)
          || jsonb_build_object('oauthScopes', p_scopes, 'oauthProvider', v_state_provider),
        "CommConn_ErrorMessage" = null,
        "CommConn_UpdatedAt" = v_now,
        "CommConn_UpdatedBy" = v_user_id,
        "CommConn_IsDeleted" = false
    where connection."CommConn_ID" = v_connection_id;
  end if;

  select mailbox."CommMailbox_ID"
    into v_mailbox_id
  from public."Comm_Mailboxes" as mailbox
  where mailbox."CommMailbox_ConnectionID" = v_connection_id
    and not mailbox."CommMailbox_IsDeleted"
    and (
      (
        nullif(btrim(p_provider_mailbox_id), '') is not null
        and mailbox."CommMailbox_ProviderMailboxID" = left(btrim(p_provider_mailbox_id), 180)
      )
      or mailbox."CommMailbox_NormalizedAddress" = v_normalized_address
    )
  order by mailbox."CommMailbox_UpdatedAt" desc
  limit 1
  for update;

  if v_mailbox_id is null then
    insert into public."Comm_Mailboxes" (
      "CommMailbox_ConnectionID",
      "CommMailbox_TypeCode",
      "CommMailbox_ChannelCode",
      "CommMailbox_UserID",
      "CommMailbox_DisplayName",
      "CommMailbox_Address",
      "CommMailbox_NormalizedAddress",
      "CommMailbox_ProviderMailboxID",
      "CommMailbox_IsDefaultOutbound",
      "CommMailbox_InboundEnabled",
      "CommMailbox_OutboundEnabled",
      "CommMailbox_DefaultSensitivityCode",
      "CommMailbox_SettingsJSON",
      "CommMailbox_CreatedAt",
      "CommMailbox_CreatedBy",
      "CommMailbox_UpdatedAt",
      "CommMailbox_UpdatedBy",
      "CommMailbox_IsDeleted"
    )
    values (
      v_connection_id,
      p_mailbox_type_code,
      'email',
      case when p_mailbox_type_code = 'personal' then v_user_id else null end,
      left(coalesce(nullif(btrim(p_mailbox_display_name), ''), v_normalized_address), 180),
      left(btrim(p_mailbox_address), 320),
      v_normalized_address,
      nullif(left(btrim(p_provider_mailbox_id), 180), ''),
      not exists (
        select 1
        from public."Comm_Mailboxes" as existing_default
        where existing_default."CommMailbox_ConnectionID" = v_connection_id
          and existing_default."CommMailbox_IsDefaultOutbound"
          and not existing_default."CommMailbox_IsDeleted"
      ),
      true,
      true,
      'internal',
      '{}'::jsonb,
      v_now,
      v_user_id,
      v_now,
      v_user_id,
      false
    )
    returning "CommMailbox_ID" into v_mailbox_id;
  else
    update public."Comm_Mailboxes" as mailbox
    set "CommMailbox_TypeCode" = p_mailbox_type_code,
        "CommMailbox_UserID" = case when p_mailbox_type_code = 'personal' then v_user_id else null end,
        "CommMailbox_DisplayName" = left(coalesce(nullif(btrim(p_mailbox_display_name), ''), mailbox."CommMailbox_DisplayName"), 180),
        "CommMailbox_Address" = left(btrim(p_mailbox_address), 320),
        "CommMailbox_NormalizedAddress" = v_normalized_address,
        "CommMailbox_ProviderMailboxID" = nullif(left(btrim(p_provider_mailbox_id), 180), ''),
        "CommMailbox_InboundEnabled" = true,
        "CommMailbox_OutboundEnabled" = true,
        "CommMailbox_UpdatedAt" = v_now,
        "CommMailbox_UpdatedBy" = v_user_id,
        "CommMailbox_IsDeleted" = false
    where mailbox."CommMailbox_ID" = v_mailbox_id;
  end if;

  insert into public."Comm_MailboxAccess" (
    "CommMailboxAccess_MailboxID",
    "CommMailboxAccess_UserID",
    "CommMailboxAccess_ScopeCode",
    "CommMailboxAccess_CanRead",
    "CommMailboxAccess_CanSend",
    "CommMailboxAccess_CanSendAs",
    "CommMailboxAccess_CanManage",
    "CommMailboxAccess_GrantedAt",
    "CommMailboxAccess_UpdatedAt"
  )
  values (
    v_mailbox_id,
    v_user_id,
    p_mailbox_type_code,
    true,
    true,
    p_mailbox_type_code = 'personal',
    p_mailbox_type_code = 'personal',
    v_now,
    v_now
  )
  on conflict (
    "CommMailboxAccess_MailboxID",
    "CommMailboxAccess_UserID"
  ) where "CommMailboxAccess_RevokedAt" is null
  do update set
    "CommMailboxAccess_ScopeCode" = excluded."CommMailboxAccess_ScopeCode",
    "CommMailboxAccess_CanRead" = excluded."CommMailboxAccess_CanRead",
    "CommMailboxAccess_CanSend" = excluded."CommMailboxAccess_CanSend",
    "CommMailboxAccess_CanSendAs" = excluded."CommMailboxAccess_CanSendAs",
    "CommMailboxAccess_CanManage" = excluded."CommMailboxAccess_CanManage",
    "CommMailboxAccess_ExpiresAt" = null,
    "CommMailboxAccess_UpdatedAt" = v_now;

  return query
  select
    v_connection_id,
    v_mailbox_id,
    case
      when v_previous_secret_ref is distinct from btrim(p_secret_ref)
        then v_previous_secret_ref
      else null
    end;
end;
$_$;


ALTER FUNCTION "public"."comm_complete_email_oauth_connection"("p_oauth_state_id" "uuid", "p_provider_type_code" character varying, "p_connection_name" character varying, "p_secret_ref" character varying, "p_provider_tenant_id" character varying, "p_provider_account_id" character varying, "p_mailbox_display_name" character varying, "p_mailbox_address" character varying, "p_provider_mailbox_id" character varying, "p_mailbox_type_code" character varying, "p_scopes" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."comm_consume_email_oauth_state"("p_state_hash" character varying) RETURNS TABLE("oauth_state_id" "uuid", "provider_code" character varying, "user_id" "uuid", "auth_user_id" "uuid", "return_path" "text", "pkce_verifier_secret_ref" character varying, "requested_scopes" "jsonb")
    LANGUAGE "sql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  with consumed as (
    update public."Comm_OAuthStates" as oauth_state
    set "CommOAuthState_ConsumedAt" = now()
    where oauth_state."CommOAuthState_StateHash" = btrim(p_state_hash)
      and oauth_state."CommOAuthState_ConsumedAt" is null
      and oauth_state."CommOAuthState_FailedAt" is null
      and oauth_state."CommOAuthState_ExpiresAt" > now()
    returning oauth_state.*
  )
  select
    consumed."CommOAuthState_ID",
    consumed."CommOAuthState_ProviderCode",
    consumed."CommOAuthState_UserID",
    workspace_user."Auth_User_ID",
    consumed."CommOAuthState_ReturnPath",
    consumed."CommOAuthState_PKCEVerifierSecretRef",
    consumed."CommOAuthState_RequestedScopes"
  from consumed
  join public."cmp_Users" as workspace_user
    on workspace_user."User_ID" = consumed."CommOAuthState_UserID";
$$;


ALTER FUNCTION "public"."comm_consume_email_oauth_state"("p_state_hash" character varying) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."comm_delete_email_secret"("p_secret_ref" "text") RETURNS boolean
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public', 'vault'
    AS $_$
declare
  v_secret_id uuid;
  v_deleted bigint;
begin
  if p_secret_ref is null or p_secret_ref !~ '^supabase-vault:[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
    raise exception 'Email secret reference is invalid.' using errcode = '22023';
  end if;

  v_secret_id := substring(p_secret_ref from 16)::uuid;
  delete from vault.secrets as secret
  where secret.id = v_secret_id;

  get diagnostics v_deleted = row_count;
  return v_deleted = 1;
end;
$_$;


ALTER FUNCTION "public"."comm_delete_email_secret"("p_secret_ref" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."comm_email_delivery_evidence"("p_message_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select jsonb_build_object(
    'status', evidence.status,
    'sentAt', message."CommMessage_SentAt",
    'deliveredAt', coalesce(message."CommMessage_DeliveredAt", events.delivered_at),
    'openedAt', coalesce(tracking.opened_at, events.opened_at),
    'repliedAt', coalesce(events.replied_at, replies.replied_at),
    'bouncedAt', events.bounced_at, 'failedAt', events.failed_at,
    'openTrackingEnabled', tracking.enabled,
    'confidence', case when evidence.status = 'opened_estimated' then 'estimated'
      when evidence.status in ('delivered','replied','failed','bounced') then 'confirmed' else 'none' end
  )
  from public."Comm_Messages" message
  cross join lateral (
    select min("CommDelivery_EventAt") filter(where "CommDelivery_EventTypeCode"='delivered') delivered_at,
      min("CommDelivery_EventAt") filter(where "CommDelivery_EventTypeCode"='opened') opened_at,
      min("CommDelivery_EventAt") filter(where "CommDelivery_EventTypeCode"='replied') replied_at,
      min("CommDelivery_EventAt") filter(where "CommDelivery_EventTypeCode"='bounced') bounced_at,
      min("CommDelivery_EventAt") filter(where "CommDelivery_EventTypeCode"='failed') failed_at
    from public."Comm_DeliveryEvents" where "CommDelivery_MessageID"=message."CommMessage_ID"
  ) events
  cross join lateral (
    select count(*) > 0 enabled, min("CommTrack_FirstOpenedAt") opened_at
    from public."Comm_MessageTrackingTokens" where "CommTrack_MessageID"=message."CommMessage_ID"
  ) tracking
  cross join lateral (
    select min("CommMessage_ReceivedAt") replied_at from public."Comm_Messages" reply
    where reply."CommMessage_ReplyToMessageID"=message."CommMessage_ID" and reply."CommMessage_IsInbound"
      and not reply."CommMessage_IsDeleted" and not reply."CommMessage_IsDraft"
  ) replies
  cross join lateral (
    select case
      when message."CommMessage_IsDraft" or message."CommMessage_StatusCode"='draft' then 'draft'
      when events.bounced_at is not null then 'bounced'
      when events.failed_at is not null or message."CommMessage_StatusCode"='failed' then 'failed'
      when coalesce(events.replied_at,replies.replied_at) is not null then 'replied'
      when coalesce(tracking.opened_at,events.opened_at) is not null then 'opened_estimated'
      when coalesce(message."CommMessage_DeliveredAt",events.delivered_at) is not null then 'delivered'
      when message."CommMessage_SentAt" is null and message."CommMessage_StatusCode"<>'sent' then 'sending'
      when tracking.enabled then 'no_open_signal' else 'sent' end status
  ) evidence
  where message."CommMessage_ID"=p_message_id and not message."CommMessage_IsInbound";
$$;


ALTER FUNCTION "public"."comm_email_delivery_evidence"("p_message_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."comm_enqueue_email_inbound_event"("p_connection_id" "uuid", "p_mailbox_id" "uuid", "p_provider_event_id" character varying, "p_provider_message_id" character varying, "p_dedupe_key" character varying, "p_payload" "jsonb", "p_received_at" timestamp with time zone DEFAULT "now"()) RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_inbound_id uuid;
begin
  if p_connection_id is null then
    raise exception 'Connection is required.' using errcode = '22023';
  end if;

  if p_dedupe_key is null or length(btrim(p_dedupe_key)) not between 1 and 240 then
    raise exception 'A provider dedupe key is required.' using errcode = '22023';
  end if;

  if p_payload is null or jsonb_typeof(p_payload) <> 'object' then
    raise exception 'Inbound payload must be a JSON object.' using errcode = '22023';
  end if;

  if p_payload::text ~* '"(access_token|refresh_token|client_secret|authorization|clientstate)"[[:space:]]*:' then
    raise exception 'Inbound payload contains credential material.' using errcode = '22023';
  end if;

  if not exists (
    select 1
    from public."Comm_ProviderConnections" as connection
    where connection."CommConn_ID" = p_connection_id
      and connection."CommConn_InboundEnabled"
      and connection."CommConn_StatusCode" = 'active'
      and not connection."CommConn_IsDeleted"
  ) then
    raise exception 'Connection is not active for inbound email.' using errcode = '42501';
  end if;

  if p_mailbox_id is not null and not exists (
    select 1
    from public."Comm_Mailboxes" as mailbox
    where mailbox."CommMailbox_ID" = p_mailbox_id
      and mailbox."CommMailbox_ConnectionID" = p_connection_id
      and mailbox."CommMailbox_InboundEnabled"
      and not mailbox."CommMailbox_IsDeleted"
  ) then
    raise exception 'Mailbox does not belong to the active connection.' using errcode = '42501';
  end if;

  insert into public."Comm_InboundEvents" (
    "CommInbound_ConnectionID",
    "CommInbound_MailboxID",
    "CommInbound_ChannelCode",
    "CommInbound_ProcessingStatusCode",
    "CommInbound_ProviderEventID",
    "CommInbound_ProviderMessageID",
    "CommInbound_DedupeKey",
    "CommInbound_ReceivedAt",
    "CommInbound_PayloadJSON"
  )
  values (
    p_connection_id,
    p_mailbox_id,
    'email',
    'new',
    nullif(left(btrim(p_provider_event_id), 240), ''),
    nullif(left(btrim(p_provider_message_id), 240), ''),
    btrim(p_dedupe_key),
    coalesce(p_received_at, now()),
    p_payload
  )
  on conflict ("CommInbound_DedupeKey")
    where "CommInbound_DedupeKey" is not null
  do nothing
  returning "CommInbound_ID" into v_inbound_id;

  if v_inbound_id is null then
    select inbound_event."CommInbound_ID"
      into v_inbound_id
    from public."Comm_InboundEvents" as inbound_event
    where inbound_event."CommInbound_DedupeKey" = btrim(p_dedupe_key);
  end if;

  return v_inbound_id;
end;
$$;


ALTER FUNCTION "public"."comm_enqueue_email_inbound_event"("p_connection_id" "uuid", "p_mailbox_id" "uuid", "p_provider_event_id" character varying, "p_provider_message_id" character varying, "p_dedupe_key" character varying, "p_payload" "jsonb", "p_received_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."comm_get_email_secret"("p_secret_ref" "text") RETURNS "text"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'pg_catalog', 'public', 'vault'
    AS $_$
declare
  v_secret_id uuid;
  v_secret text;
begin
  if p_secret_ref is null or p_secret_ref !~ '^supabase-vault:[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
    raise exception 'Email secret reference is invalid.' using errcode = '22023';
  end if;

  v_secret_id := substring(p_secret_ref from 16)::uuid;

  select secret.decrypted_secret
    into v_secret
  from vault.decrypted_secrets as secret
  where secret.id = v_secret_id;

  return v_secret;
end;
$_$;


ALTER FUNCTION "public"."comm_get_email_secret"("p_secret_ref" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."comm_inbox_mailbox_unread_counts"("p_user_id" "uuid", "p_mailbox_ids" "uuid"[]) RETURNS TABLE("mailbox_id" "uuid", "unread_count" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select
    message."CommMessage_MailboxID" as mailbox_id,
    count(*) filter (
      where coalesce(
        message."CommMessage_ReceivedAt",
        message."CommMessage_MessageDate",
        message."CommMessage_CreatedAt"
      ) > coalesce(state."CommRead_ReadAt", '-infinity'::timestamptz)
    ) as unread_count
  from public."Comm_Messages" as message
  left join public."Comm_ReadStates" as state
    on state."CommRead_ThreadID" = message."CommMessage_ThreadID"
   and state."CommRead_UserID" = p_user_id
   and state."CommRead_MessageID" is null
  where message."CommMessage_MailboxID" = any(coalesce(p_mailbox_ids, '{}'::uuid[]))
    and message."CommMessage_IsInbound"
    and not message."CommMessage_IsDraft"
    and not message."CommMessage_IsDeleted"
  group by message."CommMessage_MailboxID";
$$;


ALTER FUNCTION "public"."comm_inbox_mailbox_unread_counts"("p_user_id" "uuid", "p_mailbox_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."comm_inbox_provider_folder_thread_page"("p_user_id" "uuid", "p_mailbox_id" "uuid", "p_folder_id" "uuid", "p_query" "text", "p_limit" integer, "p_offset" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_provider text;
  v_limit integer := least(100, greatest(1, coalesce(p_limit, 25)));
  v_offset integer := greatest(0, coalesce(p_offset, 0));
  v_query text := lower(coalesce(trim(p_query), ''));
  v_result jsonb;
begin
  if not exists (
    select 1
    from public."cmp_Users_Roles" as user_role
    join public."sys_UserRole_Permissions" as role_permission
      on role_permission."sys_UserRole_ID" = user_role."sys_UserRole_ID"
    join public."sys_Permissions" as permission
      on permission."sys_Permission_ID" = role_permission."sys_Permission_ID"
    where user_role."User_ID" = p_user_id
      and permission."sys_Permission_Value" = 'Email.Read'
  ) then
    return jsonb_build_object('permissionGranted', false, 'mailboxFound', false, 'folderValid', false, 'items', '[]'::jsonb);
  end if;

  if not (
    exists (
      select 1
      from public."Comm_MailboxAccess" as access
      where access."CommMailboxAccess_MailboxID" = p_mailbox_id
        and access."CommMailboxAccess_UserID" = p_user_id
        and access."CommMailboxAccess_CanRead"
        and access."CommMailboxAccess_RevokedAt" is null
        and (access."CommMailboxAccess_ExpiresAt" is null or access."CommMailboxAccess_ExpiresAt" > now())
    )
    or exists (
      select 1
      from public."Comm_Mailboxes" as mailbox
      join public."Comm_ProviderConnections" as connection
        on connection."CommConn_ID" = mailbox."CommMailbox_ConnectionID"
      where mailbox."CommMailbox_ID" = p_mailbox_id
        and mailbox."CommMailbox_UserID" = p_user_id
        and mailbox."CommMailbox_TypeCode" = 'personal'
        and not mailbox."CommMailbox_IsDeleted"
        and connection."CommConn_UserID" = p_user_id
        and not connection."CommConn_IsDeleted"
    )
  ) then
    return jsonb_build_object('permissionGranted', true, 'mailboxFound', false, 'folderValid', false, 'items', '[]'::jsonb);
  end if;

  if not exists (
    select 1
    from public."Comm_MailFolders" as folder
    where folder."CommMailFolder_ID" = p_folder_id
      and folder."CommMailFolder_MailboxID" = p_mailbox_id
      and folder."CommMailFolder_CanHoldMessages"
      and not folder."CommMailFolder_IsHidden"
  ) then
    return jsonb_build_object('permissionGranted', true, 'mailboxFound', true, 'folderValid', false, 'items', '[]'::jsonb);
  end if;

  select case
    when lower(connection."CommConn_ProviderTypeCode") like '%gmail%'
      or lower(connection."CommConn_ProviderTypeCode") like '%google%'
      then 'gmail'
    else 'outlook'
  end
  into v_provider
  from public."Comm_Mailboxes" as mailbox
  join public."Comm_ProviderConnections" as connection
    on connection."CommConn_ID" = mailbox."CommMailbox_ConnectionID"
  where mailbox."CommMailbox_ID" = p_mailbox_id
    and not mailbox."CommMailbox_IsDeleted"
    and not connection."CommConn_IsDeleted"
  limit 1;

  if v_provider is null then
    return jsonb_build_object('permissionGranted', true, 'mailboxFound', false, 'folderValid', false, 'items', '[]'::jsonb);
  end if;

  with message_scope as materialized (
    select
      message."CommMessage_ID" as message_id,
      message."CommMessage_ThreadID" as thread_id,
      message."CommMessage_MailboxID" as mailbox_id,
      message."CommMessage_Subject" as subject,
      message."CommMessage_BodyPreview" as preview,
      coalesce(
        message."CommMessage_MessageDate",
        message."CommMessage_ReceivedAt",
        message."CommMessage_SentAt",
        message."CommMessage_CreatedAt"
      ) as occurred_at,
      message."CommMessage_IsInbound" as is_inbound,
      message."CommMessage_HasAttachments" as has_attachments,
      state."CommRead_ReadAt" as read_at,
      coalesce(state."CommRead_IsArchived", false) as is_archived,
      coalesce(state."CommRead_IsStarred", false) as is_starred
    from public."Comm_Messages" as message
    join public."Comm_MessageFolders" as membership
      on membership."CommMessageFolder_MessageID" = message."CommMessage_ID"
     and membership."CommMessageFolder_FolderID" = p_folder_id
    left join public."Comm_ReadStates" as state
      on state."CommRead_ThreadID" = message."CommMessage_ThreadID"
     and state."CommRead_UserID" = p_user_id
     and state."CommRead_MessageID" is null
    where message."CommMessage_MailboxID" = p_mailbox_id
      and not message."CommMessage_IsDeleted"
      and (
        v_query = ''
        or lower(coalesce(message."CommMessage_Subject", '') || ' ' || coalesce(message."CommMessage_BodyPreview", '')) like '%' || v_query || '%'
      )
  ),
  grouped as materialized (
    select
      thread_id,
      (array_agg(message_id order by occurred_at desc nulls last))[1] as latest_message_id,
      max(occurred_at) as last_message_at,
      count(*)::integer as message_count,
      count(*) filter (
        where is_inbound and occurred_at > coalesce(read_at, '-infinity'::timestamptz)
      )::integer as unread_count,
      bool_or(has_attachments) as has_attachments,
      bool_or(is_starred) as is_starred,
      bool_or(is_archived) as is_archived
    from message_scope
    group by thread_id
  ),
  ordered as materialized (
    select
      grouped.*,
      row_number() over (order by last_message_at desc nulls last, thread_id) as row_number,
      count(*) over () as total_count
    from grouped
  ),
  visible as materialized (
    select *
    from ordered
    where row_number > v_offset
      and row_number <= v_offset + v_limit
    order by row_number
  )
  select jsonb_build_object(
    'permissionGranted', true,
    'mailboxFound', true,
    'folderValid', true,
    'items', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'threadId', visible.thread_id,
          'mailboxId', latest."CommMessage_MailboxID",
          'provider', v_provider,
          'subject', latest."CommMessage_Subject",
          'preview', latest."CommMessage_BodyPreview",
          'lastMessageAt', visible.last_message_at,
          'unreadCount', visible.unread_count,
          'messageCount', visible.message_count,
          'hasAttachments', visible.has_attachments,
          'starred', visible.is_starred,
          'archived', visible.is_archived,
          'participants', coalesce((
            select jsonb_agg(jsonb_build_object(
              'address', participant."CommRecipient_Address",
              'displayName', participant."CommRecipient_DisplayNameSnapshot"
            ))
            from (
              select distinct on (recipient."CommRecipient_NormalizedAddress")
                recipient."CommRecipient_NormalizedAddress",
                recipient."CommRecipient_Address",
                recipient."CommRecipient_DisplayNameSnapshot"
              from public."Comm_MessageRecipients" as recipient
              join message_scope as thread_message
                on thread_message.message_id = recipient."CommRecipient_MessageID"
              where thread_message.thread_id = visible.thread_id
              order by recipient."CommRecipient_NormalizedAddress"
              limit 8
            ) as participant
          ), '[]'::jsonb),
          'summary', (
            select to_jsonb(summary)
            from public."Comm_ThreadSummaries" as summary
            where summary."CommThreadSummary_ThreadID" = visible.thread_id
              and summary."CommThreadSummary_SupersededAt" is null
            limit 1
          )
        )
        order by visible.row_number
      )
      from visible
      join public."Comm_Messages" as latest
        on latest."CommMessage_ID" = visible.latest_message_id
    ), '[]'::jsonb),
    'hasMore', coalesce((select max(total_count) > v_offset + v_limit from visible), false),
    'nextOffset', case
      when coalesce((select max(total_count) > v_offset + v_limit from visible), false)
        then v_offset + v_limit
      else null
    end
  ) into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."comm_inbox_provider_folder_thread_page"("p_user_id" "uuid", "p_mailbox_id" "uuid", "p_folder_id" "uuid", "p_query" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."comm_inbox_thread_page"("p_user_id" "uuid", "p_thread_id" "uuid", "p_limit" integer DEFAULT 25, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_message_count integer;
  v_accessible_count integer;
  v_limit integer := greatest(1, least(coalesce(p_limit, 25), 50));
  v_offset integer := greatest(coalesce(p_offset, 0), 0);
  v_result jsonb;
begin
  if not exists (
    select 1
    from public."cmp_Users_Roles" as user_role
    join public."sys_UserRole_Permissions" as role_permission
      on role_permission."sys_UserRole_ID" = user_role."sys_UserRole_ID"
    join public."sys_Permissions" as permission
      on permission."sys_Permission_ID" = role_permission."sys_Permission_ID"
    where user_role."User_ID" = p_user_id
      and permission."sys_Permission_Value" = 'Email.Read'
  ) then
    return jsonb_build_object('permissionGranted', false, 'found', false);
  end if;

  select count(*)
  into v_message_count
  from public."Comm_Messages" as message
  where message."CommMessage_ThreadID" = p_thread_id
    and not message."CommMessage_IsDeleted";

  select count(*)
  into v_accessible_count
  from public."Comm_Messages" as message
  where message."CommMessage_ThreadID" = p_thread_id
    and not message."CommMessage_IsDeleted"
    and (
      exists (
        select 1
        from public."Comm_MailboxAccess" as access
        where access."CommMailboxAccess_MailboxID" = message."CommMessage_MailboxID"
          and access."CommMailboxAccess_UserID" = p_user_id
          and access."CommMailboxAccess_CanRead"
          and access."CommMailboxAccess_RevokedAt" is null
          and (access."CommMailboxAccess_ExpiresAt" is null or access."CommMailboxAccess_ExpiresAt" > now())
      )
      or exists (
        select 1
        from public."Comm_Mailboxes" as mailbox
        join public."Comm_ProviderConnections" as connection
          on connection."CommConn_ID" = mailbox."CommMailbox_ConnectionID"
        where mailbox."CommMailbox_ID" = message."CommMessage_MailboxID"
          and mailbox."CommMailbox_UserID" = p_user_id
          and mailbox."CommMailbox_TypeCode" = 'personal'
          and not mailbox."CommMailbox_IsDeleted"
          and connection."CommConn_UserID" = p_user_id
          and not connection."CommConn_IsDeleted"
      )
    );

  if v_message_count = 0 or v_accessible_count <> v_message_count then
    return jsonb_build_object('permissionGranted', true, 'found', false);
  end if;

  with page_desc as materialized (
    select message.*
    from public."Comm_Messages" as message
    where message."CommMessage_ThreadID" = p_thread_id
      and not message."CommMessage_IsDeleted"
    order by coalesce(
      message."CommMessage_MessageDate",
      message."CommMessage_ReceivedAt",
      message."CommMessage_SentAt",
      message."CommMessage_CreatedAt"
    ) desc, message."CommMessage_ID" desc
    limit v_limit
    offset v_offset
  ),
  page_messages as materialized (
    select message.*
    from page_desc as message
    order by coalesce(
      message."CommMessage_MessageDate",
      message."CommMessage_ReceivedAt",
      message."CommMessage_SentAt",
      message."CommMessage_CreatedAt"
    ), message."CommMessage_ID"
  ),
  message_ids as materialized (
    select message."CommMessage_ID" as id
    from page_messages as message
  ),
  send_mailboxes as materialized (
    select distinct message."CommMessage_MailboxID" as id
    from public."Comm_Messages" as message
    where message."CommMessage_ThreadID" = p_thread_id
      and not message."CommMessage_IsDeleted"
      and (
        exists (
          select 1
          from public."Comm_MailboxAccess" as access
          where access."CommMailboxAccess_MailboxID" = message."CommMessage_MailboxID"
            and access."CommMailboxAccess_UserID" = p_user_id
            and access."CommMailboxAccess_CanSend"
            and (access."CommMailboxAccess_ScopeCode" = 'personal' or access."CommMailboxAccess_CanSendAs")
            and access."CommMailboxAccess_RevokedAt" is null
            and (access."CommMailboxAccess_ExpiresAt" is null or access."CommMailboxAccess_ExpiresAt" > now())
        )
        or exists (
          select 1
          from public."Comm_Mailboxes" as mailbox
          join public."Comm_ProviderConnections" as connection
            on connection."CommConn_ID" = mailbox."CommMailbox_ConnectionID"
          where mailbox."CommMailbox_ID" = message."CommMessage_MailboxID"
            and mailbox."CommMailbox_UserID" = p_user_id
            and mailbox."CommMailbox_TypeCode" = 'personal'
            and not mailbox."CommMailbox_IsDeleted"
            and connection."CommConn_UserID" = p_user_id
            and not connection."CommConn_IsDeleted"
        )
      )
  )
  select jsonb_build_object(
    'permissionGranted', true,
    'found', true,
    'messageTotal', v_message_count,
    'messageOffset', v_offset,
    'messageLimit', v_limit,
    'hasOlderMessages', v_offset + least(v_limit, greatest(v_message_count - v_offset, 0)) < v_message_count,
    'messages', coalesce((
      select jsonb_agg(to_jsonb(message) order by coalesce(
        message."CommMessage_MessageDate",
        message."CommMessage_ReceivedAt",
        message."CommMessage_SentAt",
        message."CommMessage_CreatedAt"
      ), message."CommMessage_ID")
      from page_messages as message
    ), '[]'::jsonb),
    'recipients', coalesce((
      select jsonb_agg(to_jsonb(recipient))
      from public."Comm_MessageRecipients" as recipient
      where recipient."CommRecipient_MessageID" in (select id from message_ids)
    ), '[]'::jsonb),
    'attachments', coalesce((
      select jsonb_agg(to_jsonb(attachment))
      from public."Comm_MessageAttachments" as attachment
      where attachment."CommAttachment_MessageID" in (select id from message_ids)
    ), '[]'::jsonb),
    'deliveryEvents', coalesce((
      select jsonb_agg(to_jsonb(event) order by event."CommDelivery_EventAt")
      from public."Comm_DeliveryEvents" as event
      where event."CommDelivery_MessageID" in (select id from message_ids)
    ), '[]'::jsonb),
    'trackingTokens', coalesce((
      select jsonb_agg(jsonb_build_object(
        'CommTrack_MessageID', token."CommTrack_MessageID",
        'CommTrack_FirstOpenedAt', token."CommTrack_FirstOpenedAt"
      ))
      from public."Comm_MessageTrackingTokens" as token
      where token."CommTrack_MessageID" in (select id from message_ids)
    ), '[]'::jsonb),
    'replyMessages', coalesce((
      select jsonb_agg(jsonb_build_object(
        'CommMessage_ID', reply."CommMessage_ID",
        'CommMessage_IsInbound', true,
        'CommMessage_ReplyToMessageID', reply."CommMessage_ReplyToMessageID",
        'CommMessage_ReceivedAt', reply."CommMessage_ReceivedAt"
      ))
      from public."Comm_Messages" as reply
      where reply."CommMessage_IsInbound"
        and not reply."CommMessage_IsDeleted"
        and reply."CommMessage_ThreadID" = p_thread_id
        and reply."CommMessage_ReplyToMessageID" in (
          select message."CommMessage_ID"
          from page_messages as message
          where not message."CommMessage_IsInbound"
        )
    ), '[]'::jsonb),
    'state', (
      select to_jsonb(state)
      from public."Comm_ReadStates" as state
      where state."CommRead_UserID" = p_user_id
        and state."CommRead_ThreadID" = p_thread_id
        and state."CommRead_MessageID" is null
      limit 1
    ),
    'summary', (
      select to_jsonb(summary)
      from public."Comm_ThreadSummaries" as summary
      where summary."CommThreadSummary_ThreadID" = p_thread_id
        and summary."CommThreadSummary_SupersededAt" is null
      limit 1
    ),
    'sendMailboxIds', coalesce((select jsonb_agg(id) from send_mailboxes), '[]'::jsonb),
    'readOnly', exists (
      select 1
      from public."Comm_Messages" as message
      where message."CommMessage_ThreadID" = p_thread_id
        and not message."CommMessage_IsDeleted"
        and not exists (select 1 from send_mailboxes where id = message."CommMessage_MailboxID")
    ),
    'unreadCount', (
      select count(*)
      from public."Comm_Messages" as message
      where message."CommMessage_ThreadID" = p_thread_id
        and not message."CommMessage_IsDeleted"
        and message."CommMessage_IsInbound"
        and coalesce(
          message."CommMessage_MessageDate",
          message."CommMessage_ReceivedAt",
          message."CommMessage_SentAt",
          message."CommMessage_CreatedAt"
        ) > coalesce((
          select state."CommRead_ReadAt"
          from public."Comm_ReadStates" as state
          where state."CommRead_UserID" = p_user_id
            and state."CommRead_ThreadID" = p_thread_id
            and state."CommRead_MessageID" is null
          limit 1
        ), '-infinity'::timestamptz)
    )
  )
  into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."comm_inbox_thread_page"("p_user_id" "uuid", "p_thread_id" "uuid", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."comm_inbox_thread_page"("p_user_id" "uuid", "p_thread_id" "uuid", "p_limit" integer, "p_offset" integer) IS 'Service-role-only Inbox thread detail page capped at 50 message bodies with exact thread metadata.';



CREATE OR REPLACE FUNCTION "public"."comm_inbox_thread_page"("p_user_id" "uuid", "p_mailbox_id" "uuid", "p_folder" "text", "p_query" "text", "p_limit" integer, "p_offset" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_provider text;
  v_limit integer := least(100, greatest(1, coalesce(p_limit, 25)));
  v_offset integer := greatest(0, coalesce(p_offset, 0));
  v_folder text := lower(coalesce(nullif(trim(p_folder), ''), 'inbox'));
  v_query text := lower(coalesce(trim(p_query), ''));
  v_result jsonb;
begin
  if not exists (
    select 1
    from public."cmp_Users_Roles" as user_role
    join public."sys_UserRole_Permissions" as role_permission
      on role_permission."sys_UserRole_ID" = user_role."sys_UserRole_ID"
    join public."sys_Permissions" as permission
      on permission."sys_Permission_ID" = role_permission."sys_Permission_ID"
    where user_role."User_ID" = p_user_id
      and permission."sys_Permission_Value" = 'Email.Read'
  ) then
    return jsonb_build_object('permissionGranted', false, 'mailboxFound', false, 'items', '[]'::jsonb);
  end if;

  if v_folder not in ('inbox', 'sent', 'drafts', 'archive', 'all', 'spam', 'trash', 'deleted') then
    return jsonb_build_object('permissionGranted', true, 'mailboxFound', true, 'folderValid', false, 'items', '[]'::jsonb);
  end if;

  if not (
    exists (
      select 1
      from public."Comm_MailboxAccess" as access
      where access."CommMailboxAccess_MailboxID" = p_mailbox_id
        and access."CommMailboxAccess_UserID" = p_user_id
        and access."CommMailboxAccess_CanRead"
        and access."CommMailboxAccess_RevokedAt" is null
        and (access."CommMailboxAccess_ExpiresAt" is null or access."CommMailboxAccess_ExpiresAt" > now())
    )
    or exists (
      select 1
      from public."Comm_Mailboxes" as mailbox
      join public."Comm_ProviderConnections" as connection
        on connection."CommConn_ID" = mailbox."CommMailbox_ConnectionID"
      where mailbox."CommMailbox_ID" = p_mailbox_id
        and mailbox."CommMailbox_UserID" = p_user_id
        and mailbox."CommMailbox_TypeCode" = 'personal'
        and not mailbox."CommMailbox_IsDeleted"
        and connection."CommConn_UserID" = p_user_id
        and not connection."CommConn_IsDeleted"
    )
  ) then
    return jsonb_build_object('permissionGranted', true, 'mailboxFound', false, 'items', '[]'::jsonb);
  end if;

  select case
    when lower(connection."CommConn_ProviderTypeCode") like '%gmail%'
      or lower(connection."CommConn_ProviderTypeCode") like '%google%'
      then 'gmail'
    else 'outlook'
  end
  into v_provider
  from public."Comm_Mailboxes" as mailbox
  join public."Comm_ProviderConnections" as connection
    on connection."CommConn_ID" = mailbox."CommMailbox_ConnectionID"
  where mailbox."CommMailbox_ID" = p_mailbox_id
    and not mailbox."CommMailbox_IsDeleted"
    and not connection."CommConn_IsDeleted"
  limit 1;

  if v_provider is null then
    return jsonb_build_object('permissionGranted', true, 'mailboxFound', false, 'items', '[]'::jsonb);
  end if;

  with message_scope as materialized (
    select
      message."CommMessage_ID" as message_id,
      message."CommMessage_ThreadID" as thread_id,
      message."CommMessage_MailboxID" as mailbox_id,
      message."CommMessage_Subject" as subject,
      message."CommMessage_BodyPreview" as preview,
      coalesce(
        message."CommMessage_MessageDate",
        message."CommMessage_ReceivedAt",
        message."CommMessage_SentAt",
        message."CommMessage_CreatedAt"
      ) as occurred_at,
      message."CommMessage_CreatedBy" as created_by,
      message."CommMessage_StatusCode" as status_code,
      message."CommMessage_IsInbound" as is_inbound,
      message."CommMessage_IsDraft" as is_draft,
      message."CommMessage_IsSpam" as is_spam,
      message."CommMessage_HasAttachments" as has_attachments,
      state."CommRead_ReadAt" as read_at,
      coalesce(state."CommRead_IsArchived", false) as is_archived,
      coalesce(state."CommRead_IsStarred", false) as is_starred,
      coalesce(folder_roles.roles, '{}'::text[]) as folder_roles
    from public."Comm_Messages" as message
    left join public."Comm_ReadStates" as state
      on state."CommRead_ThreadID" = message."CommMessage_ThreadID"
     and state."CommRead_UserID" = p_user_id
     and state."CommRead_MessageID" is null
    left join lateral (
      select array_agg(distinct folder."CommMailFolder_RoleCode")
        filter (where folder."CommMailFolder_RoleCode" is not null) as roles
      from public."Comm_MessageFolders" as membership
      join public."Comm_MailFolders" as folder
        on folder."CommMailFolder_ID" = membership."CommMessageFolder_FolderID"
      where membership."CommMessageFolder_MessageID" = message."CommMessage_ID"
    ) as folder_roles on true
    where message."CommMessage_MailboxID" = p_mailbox_id
      and not message."CommMessage_IsDeleted"
      and (
        v_query = ''
        or lower(coalesce(message."CommMessage_Subject", '') || ' ' || coalesce(message."CommMessage_BodyPreview", '')) like '%' || v_query || '%'
      )
  ),
  filtered_messages as materialized (
    select *
    from message_scope
    where case
      when v_folder = 'inbox' then
        ('inbox' = any(folder_roles) or (cardinality(folder_roles) = 0 and is_inbound))
        and not is_draft
        and not is_archived
      when v_folder = 'sent' then
        'sent' = any(folder_roles)
        or (cardinality(folder_roles) = 0 and not is_inbound and status_code = 'sent')
      when v_folder = 'drafts' then
        'drafts' = any(folder_roles)
        or (is_draft and created_by = p_user_id)
      when v_folder = 'archive' then is_archived
      when v_folder = 'spam' then 'spam' = any(folder_roles) or is_spam
      when v_folder in ('trash', 'deleted') then 'trash' = any(folder_roles)
      else true
    end
  ),
  grouped as materialized (
    select
      thread_id,
      (array_agg(message_id order by occurred_at desc nulls last))[1] as latest_message_id,
      max(occurred_at) as last_message_at,
      count(*)::integer as message_count,
      count(*) filter (
        where is_inbound and occurred_at > coalesce(read_at, '-infinity'::timestamptz)
      )::integer as unread_count,
      bool_or(has_attachments) as has_attachments,
      bool_or(is_starred) as is_starred,
      bool_or(is_archived) as is_archived
    from filtered_messages
    group by thread_id
  ),
  ordered as materialized (
    select
      grouped.*,
      row_number() over (order by last_message_at desc nulls last, thread_id) as row_number,
      count(*) over () as total_count
    from grouped
  ),
  visible as materialized (
    select *
    from ordered
    where row_number > v_offset
      and row_number <= v_offset + v_limit
    order by row_number
  )
  select jsonb_build_object(
    'permissionGranted', true,
    'mailboxFound', true,
    'folderValid', true,
    'items', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'threadId', visible.thread_id,
          'mailboxId', latest."CommMessage_MailboxID",
          'provider', v_provider,
          'subject', latest."CommMessage_Subject",
          'preview', latest."CommMessage_BodyPreview",
          'lastMessageAt', visible.last_message_at,
          'unreadCount', visible.unread_count,
          'messageCount', visible.message_count,
          'hasAttachments', visible.has_attachments,
          'starred', visible.is_starred,
          'archived', visible.is_archived,
          'participants', coalesce((
            select jsonb_agg(jsonb_build_object(
              'address', participant."CommRecipient_Address",
              'displayName', participant."CommRecipient_DisplayNameSnapshot"
            ))
            from (
              select distinct on (recipient."CommRecipient_NormalizedAddress")
                recipient."CommRecipient_NormalizedAddress",
                recipient."CommRecipient_Address",
                recipient."CommRecipient_DisplayNameSnapshot"
              from public."Comm_MessageRecipients" as recipient
              join filtered_messages as thread_message
                on thread_message.message_id = recipient."CommRecipient_MessageID"
              where thread_message.thread_id = visible.thread_id
              order by recipient."CommRecipient_NormalizedAddress"
              limit 8
            ) as participant
          ), '[]'::jsonb),
          'summary', (
            select to_jsonb(summary)
            from public."Comm_ThreadSummaries" as summary
            where summary."CommThreadSummary_ThreadID" = visible.thread_id
              and summary."CommThreadSummary_SupersededAt" is null
            limit 1
          )
        )
        order by visible.row_number
      )
      from visible
      join public."Comm_Messages" as latest
        on latest."CommMessage_ID" = visible.latest_message_id
    ), '[]'::jsonb),
    'hasMore', coalesce((select max(total_count) > v_offset + v_limit from visible), false),
    'nextOffset', case
      when coalesce((select max(total_count) > v_offset + v_limit from visible), false)
        then v_offset + v_limit
      else null
    end
  )
  into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."comm_inbox_thread_page"("p_user_id" "uuid", "p_mailbox_id" "uuid", "p_folder" "text", "p_query" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."comm_inbox_thread_slice_page"("p_user_id" "uuid", "p_mailbox_id" "uuid", "p_folder" "text", "p_provider_folder_id" "uuid", "p_limit" integer, "p_after_at" timestamp with time zone, "p_after_thread_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_provider text;
  v_limit integer := least(100, greatest(1, coalesce(p_limit, 25)));
  v_folder text := lower(coalesce(nullif(trim(p_folder), ''), 'inbox'));
  v_slice_key text;
  v_result jsonb;
begin
  if (p_after_at is null) <> (p_after_thread_id is null) then
    return jsonb_build_object(
      'permissionGranted', true,
      'mailboxFound', true,
      'folderValid', true,
      'cursorValid', false,
      'items', '[]'::jsonb
    );
  end if;

  if not exists (
    select 1
    from public."cmp_Users_Roles" as user_role
    join public."sys_UserRole_Permissions" as role_permission
      on role_permission."sys_UserRole_ID" = user_role."sys_UserRole_ID"
    join public."sys_Permissions" as permission
      on permission."sys_Permission_ID" = role_permission."sys_Permission_ID"
    where user_role."User_ID" = p_user_id
      and permission."sys_Permission_Value" = 'Email.Read'
  ) then
    return jsonb_build_object('permissionGranted', false, 'mailboxFound', false, 'items', '[]'::jsonb);
  end if;

  if not (
    exists (
      select 1
      from public."Comm_MailboxAccess" as access
      where access."CommMailboxAccess_MailboxID" = p_mailbox_id
        and access."CommMailboxAccess_UserID" = p_user_id
        and access."CommMailboxAccess_CanRead"
        and access."CommMailboxAccess_RevokedAt" is null
        and (access."CommMailboxAccess_ExpiresAt" is null or access."CommMailboxAccess_ExpiresAt" > now())
    )
    or exists (
      select 1
      from public."Comm_Mailboxes" as mailbox
      join public."Comm_ProviderConnections" as connection
        on connection."CommConn_ID" = mailbox."CommMailbox_ConnectionID"
      where mailbox."CommMailbox_ID" = p_mailbox_id
        and mailbox."CommMailbox_UserID" = p_user_id
        and mailbox."CommMailbox_TypeCode" = 'personal'
        and not mailbox."CommMailbox_IsDeleted"
        and connection."CommConn_UserID" = p_user_id
        and not connection."CommConn_IsDeleted"
    )
  ) then
    return jsonb_build_object('permissionGranted', true, 'mailboxFound', false, 'items', '[]'::jsonb);
  end if;

  if p_provider_folder_id is not null then
    if not exists (
      select 1
      from public."Comm_MailFolders" as folder
      where folder."CommMailFolder_ID" = p_provider_folder_id
        and folder."CommMailFolder_MailboxID" = p_mailbox_id
        and folder."CommMailFolder_CanHoldMessages"
        and not folder."CommMailFolder_IsHidden"
    ) then
      return jsonb_build_object(
        'permissionGranted', true,
        'mailboxFound', true,
        'folderValid', false,
        'items', '[]'::jsonb
      );
    end if;
    v_slice_key := 'folder:' || p_provider_folder_id::text;
  else
    if v_folder not in ('inbox', 'sent', 'archive', 'all', 'spam', 'trash', 'deleted') then
      return jsonb_build_object(
        'permissionGranted', true,
        'mailboxFound', true,
        'folderValid', false,
        'items', '[]'::jsonb
      );
    end if;
    v_slice_key := case
      when v_folder = 'archive' then 'all'
      when v_folder = 'deleted' then 'trash'
      else v_folder
    end;
  end if;

  select case
    when lower(connection."CommConn_ProviderTypeCode") like '%gmail%'
      or lower(connection."CommConn_ProviderTypeCode") like '%google%'
      then 'gmail'
    else 'outlook'
  end
  into v_provider
  from public."Comm_Mailboxes" as mailbox
  join public."Comm_ProviderConnections" as connection
    on connection."CommConn_ID" = mailbox."CommMailbox_ConnectionID"
  where mailbox."CommMailbox_ID" = p_mailbox_id
    and not mailbox."CommMailbox_IsDeleted"
    and not connection."CommConn_IsDeleted"
  limit 1;

  if v_provider is null then
    return jsonb_build_object('permissionGranted', true, 'mailboxFound', false, 'items', '[]'::jsonb);
  end if;

  with candidates as materialized (
    select
      slice."CommInboxSlice_ThreadID" as thread_id,
      slice."CommInboxSlice_LastMessageAt" as last_message_at,
      coalesce(state."CommRead_ReadAt", '-infinity'::timestamptz) as read_at,
      coalesce(state."CommRead_IsArchived", false) as is_archived,
      coalesce(state."CommRead_IsStarred", false) as is_starred
    from public."Comm_InboxThreadSlices" as slice
    left join public."Comm_ReadStates" as state
      on state."CommRead_ThreadID" = slice."CommInboxSlice_ThreadID"
     and state."CommRead_UserID" = p_user_id
     and state."CommRead_MessageID" is null
    where slice."CommInboxSlice_MailboxID" = p_mailbox_id
      and slice."CommInboxSlice_Key" = v_slice_key
      and (
        p_provider_folder_id is not null
        or v_folder <> 'inbox'
        or not coalesce(state."CommRead_IsArchived", false)
      )
      and (
        p_provider_folder_id is not null
        or v_folder <> 'archive'
        or coalesce(state."CommRead_IsArchived", false)
      )
      and (
        p_after_at is null
        or slice."CommInboxSlice_LastMessageAt" < p_after_at
        or (
          slice."CommInboxSlice_LastMessageAt" = p_after_at
          and slice."CommInboxSlice_ThreadID" > p_after_thread_id
        )
      )
    order by
      slice."CommInboxSlice_LastMessageAt" desc,
      slice."CommInboxSlice_ThreadID"
    limit v_limit + 1
  ),
  visible as materialized (
    select candidates.*
    from candidates
    order by candidates.last_message_at desc, candidates.thread_id
    limit v_limit
  ),
  message_scope as materialized (
    select
      message."CommMessage_ID" as message_id,
      message."CommMessage_ThreadID" as thread_id,
      message."CommMessage_MailboxID" as mailbox_id,
      message."CommMessage_Subject" as subject,
      message."CommMessage_BodyPreview" as preview,
      coalesce(
        message."CommMessage_MessageDate",
        message."CommMessage_ReceivedAt",
        message."CommMessage_SentAt",
        message."CommMessage_CreatedAt"
      ) as occurred_at,
      message."CommMessage_CreatedBy" as created_by,
      message."CommMessage_StatusCode" as status_code,
      message."CommMessage_IsInbound" as is_inbound,
      message."CommMessage_IsDraft" as is_draft,
      message."CommMessage_IsSpam" as is_spam,
      message."CommMessage_HasAttachments" as has_attachments,
      visible.read_at,
      visible.is_archived,
      visible.is_starred,
      coalesce(folder_roles.roles, '{}'::text[]) as folder_roles
    from visible
    join public."Comm_Messages" as message
      on message."CommMessage_ThreadID" = visible.thread_id
     and message."CommMessage_MailboxID" = p_mailbox_id
     and not message."CommMessage_IsDeleted"
    left join lateral (
      select array_agg(distinct folder."CommMailFolder_RoleCode")
        filter (where folder."CommMailFolder_RoleCode" is not null) as roles
      from public."Comm_MessageFolders" as membership
      join public."Comm_MailFolders" as folder
        on folder."CommMailFolder_ID" = membership."CommMessageFolder_FolderID"
      where membership."CommMessageFolder_MessageID" = message."CommMessage_ID"
    ) as folder_roles on true
    where case
      when p_provider_folder_id is not null then exists (
        select 1
        from public."Comm_MessageFolders" as membership
        where membership."CommMessageFolder_MessageID" = message."CommMessage_ID"
          and membership."CommMessageFolder_FolderID" = p_provider_folder_id
      )
      when v_folder = 'inbox' then
        ('inbox' = any(coalesce(folder_roles.roles, '{}'::text[]))
          or (cardinality(coalesce(folder_roles.roles, '{}'::text[])) = 0 and message."CommMessage_IsInbound"))
        and not message."CommMessage_IsDraft"
      when v_folder = 'sent' then
        'sent' = any(coalesce(folder_roles.roles, '{}'::text[]))
        or (
          cardinality(coalesce(folder_roles.roles, '{}'::text[])) = 0
          and not message."CommMessage_IsInbound"
          and message."CommMessage_StatusCode" = 'sent'
        )
      when v_folder = 'spam' then
        'spam' = any(coalesce(folder_roles.roles, '{}'::text[]))
        or message."CommMessage_IsSpam"
      when v_folder in ('trash', 'deleted') then
        'trash' = any(coalesce(folder_roles.roles, '{}'::text[]))
      else true
    end
  ),
  page_threads as materialized (
    select
      message_scope.thread_id,
      (array_agg(message_scope.message_id order by message_scope.occurred_at desc, message_scope.message_id desc))[1] as latest_message_id,
      max(message_scope.occurred_at) as last_message_at,
      count(*)::integer as message_count,
      count(*) filter (
        where message_scope.is_inbound and message_scope.occurred_at > message_scope.read_at
      )::integer as unread_count,
      bool_or(message_scope.has_attachments) as has_attachments,
      bool_or(message_scope.is_starred) as is_starred,
      bool_or(message_scope.is_archived) as is_archived
    from message_scope
    group by message_scope.thread_id
  )
  select jsonb_build_object(
    'permissionGranted', true,
    'mailboxFound', true,
    'folderValid', true,
    'cursorValid', true,
    'items', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'threadId', page_threads.thread_id,
          'mailboxId', latest."CommMessage_MailboxID",
          'provider', v_provider,
          'subject', latest."CommMessage_Subject",
          'preview', latest."CommMessage_BodyPreview",
          'lastMessageAt', page_threads.last_message_at,
          'unreadCount', page_threads.unread_count,
          'messageCount', page_threads.message_count,
          'hasAttachments', page_threads.has_attachments,
          'starred', page_threads.is_starred,
          'archived', page_threads.is_archived,
          'participants', coalesce((
            select jsonb_agg(jsonb_build_object(
              'address', participant."CommRecipient_Address",
              'displayName', participant."CommRecipient_DisplayNameSnapshot"
            ))
            from (
              select distinct on (recipient."CommRecipient_NormalizedAddress")
                recipient."CommRecipient_NormalizedAddress",
                recipient."CommRecipient_Address",
                recipient."CommRecipient_DisplayNameSnapshot"
              from public."Comm_MessageRecipients" as recipient
              join message_scope as thread_message
                on thread_message.message_id = recipient."CommRecipient_MessageID"
              where thread_message.thread_id = page_threads.thread_id
              order by recipient."CommRecipient_NormalizedAddress"
              limit 8
            ) as participant
          ), '[]'::jsonb),
          'summary', (
            select to_jsonb(summary)
            from public."Comm_ThreadSummaries" as summary
            where summary."CommThreadSummary_ThreadID" = page_threads.thread_id
              and summary."CommThreadSummary_SupersededAt" is null
            order by summary."CommThreadSummary_GeneratedAt" desc
            limit 1
          )
        )
        order by visible.last_message_at desc, visible.thread_id
      )
      from visible
      join page_threads on page_threads.thread_id = visible.thread_id
      join public."Comm_Messages" as latest
        on latest."CommMessage_ID" = page_threads.latest_message_id
    ), '[]'::jsonb),
    'hasMore', (select count(*) > v_limit from candidates),
    'nextLastMessageAt', case
      when (select count(*) > v_limit from candidates)
        then (select visible.last_message_at from visible order by visible.last_message_at, visible.thread_id desc limit 1)
      else null
    end,
    'nextThreadId', case
      when (select count(*) > v_limit from candidates)
        then (select visible.thread_id from visible order by visible.last_message_at, visible.thread_id desc limit 1)
      else null
    end
  ) into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."comm_inbox_thread_slice_page"("p_user_id" "uuid", "p_mailbox_id" "uuid", "p_folder" "text", "p_provider_folder_id" "uuid", "p_limit" integer, "p_after_at" timestamp with time zone, "p_after_thread_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."comm_inbox_thread_slice_page"("p_user_id" "uuid", "p_mailbox_id" "uuid", "p_folder" "text", "p_provider_folder_id" "uuid", "p_limit" integer, "p_after_at" timestamp with time zone, "p_after_thread_id" "uuid") IS 'Service-role-only keyset Inbox page. Preserves mailbox ACL, folder and per-user read-state semantics while hydrating only visible threads.';



CREATE OR REPLACE FUNCTION "public"."comm_inbox_thread_snapshot"("p_user_id" "uuid", "p_thread_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_message_count integer;
  v_accessible_count integer;
  v_result jsonb;
begin
  if not exists (
    select 1
    from public."cmp_Users_Roles" as user_role
    join public."sys_UserRole_Permissions" as role_permission
      on role_permission."sys_UserRole_ID" = user_role."sys_UserRole_ID"
    join public."sys_Permissions" as permission
      on permission."sys_Permission_ID" = role_permission."sys_Permission_ID"
    where user_role."User_ID" = p_user_id
      and permission."sys_Permission_Value" = 'Email.Read'
  ) then
    return jsonb_build_object('permissionGranted', false, 'found', false);
  end if;

  select count(*)
  into v_message_count
  from public."Comm_Messages" as message
  where message."CommMessage_ThreadID" = p_thread_id
    and not message."CommMessage_IsDeleted";

  select count(*)
  into v_accessible_count
  from public."Comm_Messages" as message
  where message."CommMessage_ThreadID" = p_thread_id
    and not message."CommMessage_IsDeleted"
    and (
      exists (
        select 1
        from public."Comm_MailboxAccess" as access
        where access."CommMailboxAccess_MailboxID" = message."CommMessage_MailboxID"
          and access."CommMailboxAccess_UserID" = p_user_id
          and access."CommMailboxAccess_CanRead"
          and access."CommMailboxAccess_RevokedAt" is null
          and (access."CommMailboxAccess_ExpiresAt" is null or access."CommMailboxAccess_ExpiresAt" > now())
      )
      or exists (
        select 1
        from public."Comm_Mailboxes" as mailbox
        join public."Comm_ProviderConnections" as connection
          on connection."CommConn_ID" = mailbox."CommMailbox_ConnectionID"
        where mailbox."CommMailbox_ID" = message."CommMessage_MailboxID"
          and mailbox."CommMailbox_UserID" = p_user_id
          and mailbox."CommMailbox_TypeCode" = 'personal'
          and not mailbox."CommMailbox_IsDeleted"
          and connection."CommConn_UserID" = p_user_id
          and not connection."CommConn_IsDeleted"
      )
    );

  if v_message_count = 0 or v_accessible_count <> v_message_count then
    return jsonb_build_object('permissionGranted', true, 'found', false);
  end if;

  with thread_messages as materialized (
    select message.*
    from public."Comm_Messages" as message
    where message."CommMessage_ThreadID" = p_thread_id
      and not message."CommMessage_IsDeleted"
  ),
  message_ids as materialized (
    select message."CommMessage_ID" as id
    from thread_messages as message
  )
  select jsonb_build_object(
    'permissionGranted', true,
    'found', true,
    'messages', coalesce((
      select jsonb_agg(
        to_jsonb(message)
        order by coalesce(
          message."CommMessage_MessageDate",
          message."CommMessage_ReceivedAt",
          message."CommMessage_SentAt",
          message."CommMessage_CreatedAt"
        )
      )
      from thread_messages as message
    ), '[]'::jsonb),
    'recipients', coalesce((
      select jsonb_agg(to_jsonb(recipient))
      from public."Comm_MessageRecipients" as recipient
      where recipient."CommRecipient_MessageID" in (select id from message_ids)
    ), '[]'::jsonb),
    'attachments', coalesce((
      select jsonb_agg(to_jsonb(attachment))
      from public."Comm_MessageAttachments" as attachment
      where attachment."CommAttachment_MessageID" in (select id from message_ids)
    ), '[]'::jsonb),
    'deliveryEvents', coalesce((
      select jsonb_agg(to_jsonb(event) order by event."CommDelivery_EventAt")
      from public."Comm_DeliveryEvents" as event
      where event."CommDelivery_MessageID" in (select id from message_ids)
    ), '[]'::jsonb),
    'trackingTokens', coalesce((
      select jsonb_agg(jsonb_build_object(
        'CommTrack_MessageID', token."CommTrack_MessageID",
        'CommTrack_FirstOpenedAt', token."CommTrack_FirstOpenedAt"
      ))
      from public."Comm_MessageTrackingTokens" as token
      where token."CommTrack_MessageID" in (select id from message_ids)
    ), '[]'::jsonb),
    'state', (
      select to_jsonb(state)
      from public."Comm_ReadStates" as state
      where state."CommRead_UserID" = p_user_id
        and state."CommRead_ThreadID" = p_thread_id
        and state."CommRead_MessageID" is null
      limit 1
    ),
    'summary', (
      select to_jsonb(summary)
      from public."Comm_ThreadSummaries" as summary
      where summary."CommThreadSummary_ThreadID" = p_thread_id
        and summary."CommThreadSummary_SupersededAt" is null
      limit 1
    ),
    'sendMailboxIds', coalesce((
      select jsonb_agg(distinct message."CommMessage_MailboxID")
      from thread_messages as message
      where exists (
        select 1
        from public."Comm_MailboxAccess" as access
        where access."CommMailboxAccess_MailboxID" = message."CommMessage_MailboxID"
          and access."CommMailboxAccess_UserID" = p_user_id
          and access."CommMailboxAccess_CanSend"
          and (access."CommMailboxAccess_ScopeCode" = 'personal' or access."CommMailboxAccess_CanSendAs")
          and access."CommMailboxAccess_RevokedAt" is null
          and (access."CommMailboxAccess_ExpiresAt" is null or access."CommMailboxAccess_ExpiresAt" > now())
      ) or exists (
        select 1
        from public."Comm_Mailboxes" as mailbox
        join public."Comm_ProviderConnections" as connection
          on connection."CommConn_ID" = mailbox."CommMailbox_ConnectionID"
        where mailbox."CommMailbox_ID" = message."CommMessage_MailboxID"
          and mailbox."CommMailbox_UserID" = p_user_id
          and mailbox."CommMailbox_TypeCode" = 'personal'
          and not mailbox."CommMailbox_IsDeleted"
          and connection."CommConn_UserID" = p_user_id
          and not connection."CommConn_IsDeleted"
      )
    ), '[]'::jsonb)
  )
  into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."comm_inbox_thread_snapshot"("p_user_id" "uuid", "p_thread_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."comm_purge_expired_email_oauth_states"("p_retention" interval DEFAULT '1 day'::interval) RETURNS bigint
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_deleted bigint;
  v_pkce_secret_ids uuid[];
begin
  if p_retention < interval '0 seconds' or p_retention > interval '30 days' then
    raise exception 'OAuth state retention must be between zero and 30 days.' using errcode = '22023';
  end if;

  select coalesce(
    array_agg(substring(oauth_state."CommOAuthState_PKCEVerifierSecretRef" from 16)::uuid),
    array[]::uuid[]
  )
  into v_pkce_secret_ids
  from public."Comm_OAuthStates" as oauth_state
  where (
      oauth_state."CommOAuthState_ExpiresAt" < now() - p_retention
      or oauth_state."CommOAuthState_ConsumedAt" < now() - p_retention
      or oauth_state."CommOAuthState_FailedAt" < now() - p_retention
    )
    and oauth_state."CommOAuthState_PKCEVerifierSecretRef" is not null;

  delete from vault.secrets as secret
  where secret.id = any(v_pkce_secret_ids);

  delete from public."Comm_OAuthStates" as oauth_state
  where oauth_state."CommOAuthState_ExpiresAt" < now() - p_retention
     or oauth_state."CommOAuthState_ConsumedAt" < now() - p_retention
     or oauth_state."CommOAuthState_FailedAt" < now() - p_retention;

  get diagnostics v_deleted = row_count;
  return v_deleted;
end;
$$;


ALTER FUNCTION "public"."comm_purge_expired_email_oauth_states"("p_retention" interval) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."comm_put_email_secret"("p_secret" "text", "p_name" "text" DEFAULT NULL::"text", "p_description" "text" DEFAULT NULL::"text") RETURNS "text"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public', 'vault'
    AS $$
declare
  v_secret_id uuid;
begin
  if p_secret is null or length(p_secret) not between 1 and 131072 then
    raise exception 'Email secret must be between 1 byte and 128 KiB.' using errcode = '22023';
  end if;

  if p_name is not null and length(btrim(p_name)) not between 1 and 180 then
    raise exception 'Email secret name must be between 1 and 180 characters.' using errcode = '22023';
  end if;

  select vault.create_secret(
    p_secret,
    nullif(btrim(p_name), ''),
    coalesce(nullif(btrim(p_description), ''), 'Multideck Inbox credential')
  )
  into v_secret_id;

  if v_secret_id is null then
    raise exception 'Tenant Vault did not create an email secret.' using errcode = '55000';
  end if;

  return 'supabase-vault:' || v_secret_id::text;
end;
$$;


ALTER FUNCTION "public"."comm_put_email_secret"("p_secret" "text", "p_name" "text", "p_description" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."comm_reconcile_email_watch_messages"("p_user_id" "uuid", "p_company_id" "uuid", "p_since" timestamp with time zone DEFAULT ("now"() - '00:15:00'::interval)) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_message record;
  v_count integer := 0;
begin
  if p_user_id is null or p_company_id is null then
    raise exception 'A watch owner and company are required.' using errcode = '22023';
  end if;

  for v_message in
    select message."CommMessage_ID"
    from public."Comm_Messages" message
    join public._multideck_dexter_email_mailboxes(p_user_id, p_company_id) permitted
      on permitted.mailbox_id = message."CommMessage_MailboxID"
    where message."CommMessage_IsInbound"
      and not message."CommMessage_IsDraft"
      and not message."CommMessage_IsSpam"
      and not message."CommMessage_IsDeleted"
      and message."CommMessage_ReceivedAt" >= greatest(
        coalesce(p_since, now() - interval '15 minutes'),
        coalesce((
          select min(watch."AIDexterWatch_CreatedAt")
          from public."AI_DexterWatches" watch
          where watch."AIDexterWatch_OwnerUserID" = p_user_id
            and watch."AIDexterWatch_CompanyID" = p_company_id
            and watch."AIDexterWatch_CapabilityCode" = 'email'
            and watch."AIDexterWatch_StatusCode" = 'active'
        ), now())
      )
    order by message."CommMessage_ReceivedAt"
    limit 500
  loop
    perform public._multideck_dexter_emit_email_watch_signal(v_message."CommMessage_ID");
    v_count := v_count + 1;
  end loop;

  return v_count;
end;
$$;


ALTER FUNCTION "public"."comm_reconcile_email_watch_messages"("p_user_id" "uuid", "p_company_id" "uuid", "p_since" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."comm_reconcile_sent_draft_folders"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  delete from public."Comm_MessageFolders" membership
  using public."Comm_MailFolders" folder
  where membership."CommMessageFolder_MessageID" = new."CommMessage_ID"
    and membership."CommMessageFolder_FolderID" = folder."CommMailFolder_ID"
    and folder."CommMailFolder_MailboxID" = new."CommMessage_MailboxID"
    and folder."CommMailFolder_RoleCode" = 'drafts';

  insert into public."Comm_MessageFolders" (
    "CommMessageFolder_MessageID", "CommMessageFolder_FolderID",
    "CommMessageFolder_IsPrimary", "CommMessageFolder_AddedAt"
  )
  select new."CommMessage_ID", folder."CommMailFolder_ID", false, now()
  from public."Comm_MailFolders" folder
  where folder."CommMailFolder_MailboxID" = new."CommMessage_MailboxID"
    and folder."CommMailFolder_RoleCode" = 'sent'
  order by folder."CommMailFolder_ID"
  limit 1
  on conflict ("CommMessageFolder_MessageID", "CommMessageFolder_FolderID") do nothing;
  return new;
end;
$$;


ALTER FUNCTION "public"."comm_reconcile_sent_draft_folders"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."comm_record_tracking_open"("p_token_hash" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_token public."Comm_MessageTrackingTokens"%rowtype;
  v_first boolean;
  v_now timestamptz := now();
begin
  select * into v_token
  from public."Comm_MessageTrackingTokens"
  where "CommTrack_TokenHashSHA256" = p_token_hash
    and "CommTrack_IsActive"
    and "CommTrack_ExpiresAt" > v_now
  for update;
  if not found then return false; end if;

  v_first := v_token."CommTrack_FirstOpenedAt" is null;
  update public."Comm_MessageTrackingTokens"
  set "CommTrack_FirstOpenedAt" = coalesce("CommTrack_FirstOpenedAt", v_now),
      "CommTrack_LastOpenedAt" = v_now,
      "CommTrack_OpenCount" = "CommTrack_OpenCount" + 1
  where "CommTrack_ID" = v_token."CommTrack_ID";

  if v_first then
    perform public."Comm_RecordDeliveryEvent"(
      v_token."CommTrack_MessageID",
      v_token."CommTrack_SendID",
      'opened',
      null,
      'open:' || v_token."CommTrack_ID"::text,
      jsonb_build_object('source', 'tracking_image', 'confidence', 'estimated', 'eventAt', v_now)
    );
  end if;
  return true;
end;
$$;


ALTER FUNCTION "public"."comm_record_tracking_open"("p_token_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."comm_reject_delivery_event_message_collision"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_existing_message_id uuid;
begin
  if new."CommDelivery_ConnectionID" is null
     or new."CommDelivery_ProviderEventID" is null then
    return new;
  end if;

  select event."CommDelivery_MessageID"
  into v_existing_message_id
  from public."Comm_DeliveryEvents" as event
  where event."CommDelivery_ConnectionID" = new."CommDelivery_ConnectionID"
    and event."CommDelivery_ProviderEventID" = new."CommDelivery_ProviderEventID"
  limit 1;

  if found and v_existing_message_id is distinct from new."CommDelivery_MessageID" then
    raise exception 'A provider delivery event cannot be attached to a different message.'
      using errcode = '23505';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."comm_reject_delivery_event_message_collision"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."comm_release_email_watch_owner"("p_mode" "text", "p_owner_user_id" "uuid", "p_lease_token" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_released integer := 0;
begin
  update public."Comm_EmailWatchWorkerState"
  set "CommWatchWorker_LeaseToken" = null,
      "CommWatchWorker_LeaseUntil" = null
  where "CommWatchWorker_OwnerUserID" = p_owner_user_id
    and "CommWatchWorker_ModeCode" = case when p_mode = 'backfill' then 'backfill' else 'live' end
    and "CommWatchWorker_LeaseToken" = p_lease_token;

  get diagnostics v_released = row_count;
  return v_released > 0;
end;
$$;


ALTER FUNCTION "public"."comm_release_email_watch_owner"("p_mode" "text", "p_owner_user_id" "uuid", "p_lease_token" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."comm_remove_provider_messages"("p_mailbox_id" "uuid", "p_provider_message_ids" "text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_thread_ids uuid[];
  v_deleted integer := 0;
begin
  perform set_config('multideck.retention_cleanup', 'on', true);

  with deleted as (
    delete from public."Comm_Messages" message
    where message."CommMessage_MailboxID" = p_mailbox_id
      and message."CommMessage_SourceTypeCode" = 'provider_sync'
      and message."CommMessage_ProviderMessageID" = any(
        coalesce(p_provider_message_ids, '{}'::text[])
      )
    returning message."CommMessage_ThreadID"
  )
  select
    count(*),
    coalesce(array_agg(distinct "CommMessage_ThreadID"), '{}'::uuid[])
  into v_deleted, v_thread_ids
  from deleted;

  perform public._multideck_refresh_retained_email_threads(v_thread_ids);

  return jsonb_build_object('deleted', v_deleted);
end;
$$;


ALTER FUNCTION "public"."comm_remove_provider_messages"("p_mailbox_id" "uuid", "p_provider_message_ids" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."comm_resolve_email_provider_subscription"("p_provider_subscription_id" character varying, "p_provider_resource" character varying) RETURNS TABLE("subscription_id" "uuid", "connection_id" "uuid", "mailbox_id" "uuid", "provider_subscription_id" character varying, "provider_resource" character varying, "client_state_secret_ref" character varying, "expires_at" timestamp with time zone)
    LANGUAGE "sql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select
    subscription."CommProviderSubscription_ID",
    subscription."CommProviderSubscription_ConnectionID",
    subscription."CommProviderSubscription_MailboxID",
    subscription."CommProviderSubscription_ProviderSubscriptionID",
    subscription."CommProviderSubscription_ProviderResource",
    subscription."CommProviderSubscription_ClientStateSecretRef",
    subscription."CommProviderSubscription_ExpiresAt"
  from public."Comm_ProviderSubscriptions" as subscription
  where subscription."CommProviderSubscription_StatusCode" = 'active'
    and subscription."CommProviderSubscription_ExpiresAt" > now()
    and (
      nullif(btrim(p_provider_subscription_id), '') is not null
      or nullif(btrim(p_provider_resource), '') is not null
    )
    and (
      nullif(btrim(p_provider_subscription_id), '') is null
      or subscription."CommProviderSubscription_ProviderSubscriptionID"
        = btrim(p_provider_subscription_id)
    )
    and (
      nullif(btrim(p_provider_resource), '') is null
      or subscription."CommProviderSubscription_ProviderResource"
        = btrim(p_provider_resource)
    )
  order by subscription."CommProviderSubscription_UpdatedAt" desc
  limit 1;
$$;


ALTER FUNCTION "public"."comm_resolve_email_provider_subscription"("p_provider_subscription_id" character varying, "p_provider_resource" character varying) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."comm_save_email_thread_summary"("p_thread_id" "uuid", "p_model_code" character varying, "p_summary_text" "text", "p_structured_json" "jsonb", "p_source_message_count" integer, "p_source_last_message_id" "uuid", "p_source_fingerprint" character varying, "p_generated_by_user_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  v_summary_id uuid;
  v_version integer;
  v_now timestamptz := now();
begin
  if p_thread_id is null then
    raise exception 'Thread is required.' using errcode = '22023';
  end if;

  if p_model_code is null or length(btrim(p_model_code)) not between 1 and 120 then
    raise exception 'Summary model code is invalid.' using errcode = '22023';
  end if;

  if p_summary_text is null or length(btrim(p_summary_text)) = 0 then
    raise exception 'Summary text is required.' using errcode = '22023';
  end if;

  if p_structured_json is null or jsonb_typeof(p_structured_json) <> 'object' then
    raise exception 'Structured summary must be a JSON object.' using errcode = '22023';
  end if;

  if p_source_message_count is null or p_source_message_count < 0 then
    raise exception 'Source message count is invalid.' using errcode = '22023';
  end if;

  if p_source_fingerprint is null or p_source_fingerprint !~ '^[0-9a-f]{64}$' then
    raise exception 'Source fingerprint must be a lowercase SHA-256 hash.' using errcode = '22023';
  end if;

  perform 1
  from public."Comm_Threads" as thread
  where thread."CommThread_ID" = p_thread_id
    and not thread."CommThread_IsDeleted"
  for update;

  if not found then
    raise exception 'Thread is not available for summarisation.' using errcode = '42501';
  end if;

  if p_source_last_message_id is not null and not exists (
    select 1
    from public."Comm_Messages" as message
    where message."CommMessage_ID" = p_source_last_message_id
      and message."CommMessage_ThreadID" = p_thread_id
      and not message."CommMessage_IsDeleted"
  ) then
    raise exception 'Summary source message does not belong to the thread.' using errcode = '22023';
  end if;

  update public."Comm_ThreadSummaries" as previous_summary
  set "CommThreadSummary_SupersededAt" = v_now
  where previous_summary."CommThreadSummary_ThreadID" = p_thread_id
    and previous_summary."CommThreadSummary_SupersededAt" is null;

  select coalesce(max(summary."CommThreadSummary_Version"), 0) + 1
    into v_version
  from public."Comm_ThreadSummaries" as summary
  where summary."CommThreadSummary_ThreadID" = p_thread_id;

  insert into public."Comm_ThreadSummaries" (
    "CommThreadSummary_ThreadID",
    "CommThreadSummary_Version",
    "CommThreadSummary_ModelCode",
    "CommThreadSummary_SummaryText",
    "CommThreadSummary_StructuredJSON",
    "CommThreadSummary_SourceMessageCount",
    "CommThreadSummary_SourceLastMessageID",
    "CommThreadSummary_SourceFingerprint",
    "CommThreadSummary_GeneratedByUserID",
    "CommThreadSummary_GeneratedAt"
  )
  values (
    p_thread_id,
    v_version,
    btrim(p_model_code),
    btrim(p_summary_text),
    p_structured_json,
    p_source_message_count,
    p_source_last_message_id,
    p_source_fingerprint,
    p_generated_by_user_id,
    v_now
  )
  returning "CommThreadSummary_ID" into v_summary_id;

  return v_summary_id;
end;
$_$;


ALTER FUNCTION "public"."comm_save_email_thread_summary"("p_thread_id" "uuid", "p_model_code" character varying, "p_summary_text" "text", "p_structured_json" "jsonb", "p_source_message_count" integer, "p_source_last_message_id" "uuid", "p_source_fingerprint" character varying, "p_generated_by_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."comm_update_email_secret"("p_secret_ref" "text", "p_secret" "text") RETURNS boolean
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public', 'vault'
    AS $_$
declare
  v_secret_id uuid;
begin
  if p_secret_ref is null or p_secret_ref !~ '^supabase-vault:[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
    raise exception 'Email secret reference is invalid.' using errcode = '22023';
  end if;

  if p_secret is null or length(p_secret) not between 1 and 131072 then
    raise exception 'Email secret must be between 1 byte and 128 KiB.' using errcode = '22023';
  end if;

  v_secret_id := substring(p_secret_ref from 16)::uuid;
  if not exists (
    select 1
    from vault.decrypted_secrets as secret
    where secret.id = v_secret_id
  ) then
    return false;
  end if;

  perform vault.update_secret(v_secret_id, p_secret, null, null);
  return true;
end;
$_$;


ALTER FUNCTION "public"."comm_update_email_secret"("p_secret_ref" "text", "p_secret" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."company_appearance_available"("p_company_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_brand public."cmp_Brands"%rowtype;
  v_settings jsonb;
begin
  select * into v_brand from public."cmp_Brands"
  where "Company_ID" = p_company_id and "Brand_IsActive" = true
  order by "Brand_IsDefault" desc, "Brand_CreatedAt" asc
  limit 1 for share;
  if not found then return false; end if;
  v_settings := v_brand."Brand_TemplateSettingsJSON" -> 'tenantBranding';
  return coalesce(
    v_settings -> 'version' = '1'::jsonb
    and (v_settings -> 'configured' is distinct from 'false'::jsonb)
    and coalesce(nullif(btrim(v_brand."Brand_DisplayName"), ''), nullif(btrim(v_brand."Brand_Name"), '')) is not null
    and (v_settings ->> 'primaryColor') ~* '^#[0-9a-f]{6}$'
    and (v_settings ->> 'secondaryColor') ~* '^#[0-9a-f]{6}$', false);
end;
$_$;


ALTER FUNCTION "public"."company_appearance_available"("p_company_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."crm_drive_complete_cleanup"("p_paths" "text"[]) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_company_id uuid := public.app_current_company_id();
begin
  perform public._crm_drive_require_permission('CRM.Drive.Write');
  update public."CRM_DriveObjectCleanupQueue" queue
  set "DriveCleanup_CleanedAt" = now()
  where queue."Company_ID" = v_company_id
    and queue."DriveCleanup_Path" = any(coalesce(p_paths, array[]::text[]))
    and queue."DriveCleanup_CleanedAt" is null;
end;
$$;


ALTER FUNCTION "public"."crm_drive_complete_cleanup"("p_paths" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."crm_drive_delete_file"("p_file_id" "uuid") RETURNS "text"[]
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_company_id uuid := public.app_current_company_id();
  v_user_id uuid;
  v_paths text[];
begin
  perform public._crm_drive_require_permission('CRM.Drive.Write');
  select actor."User_ID" into v_user_id
  from public."cmp_Users" actor
  where actor."Auth_User_ID" = (select auth.uid())
    and actor."Company_ID" = v_company_id
    and coalesce(actor."User_AccessStatus", 'active') = 'active'
  limit 1;

  select array_remove(array[file."DriveFile_StoragePath", file."DriveFile_ThumbnailPath"], null)
  into v_paths
  from public."CRM_DriveFiles" file
  where file."DriveFile_ID" = p_file_id
    and file."Company_ID" = v_company_id
  for update;

  if not found then
    raise exception 'This file no longer exists.' using errcode = 'P0002';
  end if;

  perform public._crm_drive_enqueue_cleanup(v_company_id, v_user_id, v_paths);
  delete from public."CRM_DriveFiles"
  where "DriveFile_ID" = p_file_id
    and "Company_ID" = v_company_id;
  return coalesce(v_paths, array[]::text[]);
end;
$$;


ALTER FUNCTION "public"."crm_drive_delete_file"("p_file_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."crm_drive_delete_folder"("p_folder_id" "uuid") RETURNS "text"[]
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_company_id uuid := public.app_current_company_id();
  v_user_id uuid;
  v_paths text[];
begin
  perform public._crm_drive_require_permission('CRM.Drive.Write');
  select actor."User_ID" into v_user_id
  from public."cmp_Users" actor
  where actor."Auth_User_ID" = (select auth.uid())
    and actor."Company_ID" = v_company_id
    and coalesce(actor."User_AccessStatus", 'active') = 'active'
  limit 1;

  if not exists (
    select 1 from public."CRM_DriveFolders" folder
    where folder."DriveFolder_ID" = p_folder_id
      and folder."Company_ID" = v_company_id
  ) then
    raise exception 'This folder no longer exists.' using errcode = 'P0002';
  end if;

  with recursive tree as (
    select "DriveFolder_ID"
    from public."CRM_DriveFolders"
    where "DriveFolder_ID" = p_folder_id
      and "Company_ID" = v_company_id
    union all
    select child."DriveFolder_ID"
    from public."CRM_DriveFolders" child
    join tree on child."DriveFolder_ParentID" = tree."DriveFolder_ID"
    where child."Company_ID" = v_company_id
  )
  select coalesce(array_agg(path) filter (where path is not null), array[]::text[])
  into v_paths
  from (
    select file."DriveFile_StoragePath" path
    from public."CRM_DriveFiles" file
    join tree on tree."DriveFolder_ID" = file."DriveFile_FolderID"
    where file."Company_ID" = v_company_id
    union all
    select file."DriveFile_ThumbnailPath"
    from public."CRM_DriveFiles" file
    join tree on tree."DriveFolder_ID" = file."DriveFile_FolderID"
    where file."Company_ID" = v_company_id
  ) stored_objects;

  perform public._crm_drive_enqueue_cleanup(v_company_id, v_user_id, v_paths);
  delete from public."CRM_DriveFolders"
  where "DriveFolder_ID" = p_folder_id
    and "Company_ID" = v_company_id;
  return v_paths;
end;
$$;


ALTER FUNCTION "public"."crm_drive_delete_folder"("p_folder_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."crm_drive_folder_path"("p_folder_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_company_id uuid := public.app_current_company_id();
  v_result jsonb;
begin
  perform public._crm_drive_require_permission('CRM.Drive.Read');
  if p_folder_id is null then return '[]'::jsonb; end if;

  with recursive ancestors as (
    select
      folder."DriveFolder_ID" as id,
      folder."DriveFolder_ParentID" as parent_id,
      folder."DriveFolder_Name" as name,
      folder."DriveFolder_ColourCode" as colour,
      folder."DriveFolder_IconCode" as icon,
      folder."DriveFolder_CreatedAt" as created_at,
      folder."DriveFolder_UpdatedAt" as updated_at,
      array[folder."DriveFolder_ID"]::uuid[] as visited,
      0 as depth
    from public."CRM_DriveFolders" as folder
    where folder."Company_ID" = v_company_id
      and folder."DriveFolder_ID" = p_folder_id
    union all
    select
      parent."DriveFolder_ID",
      parent."DriveFolder_ParentID",
      parent."DriveFolder_Name",
      parent."DriveFolder_ColourCode",
      parent."DriveFolder_IconCode",
      parent."DriveFolder_CreatedAt",
      parent."DriveFolder_UpdatedAt",
      ancestors.visited || parent."DriveFolder_ID",
      ancestors.depth + 1
    from ancestors
    join public."CRM_DriveFolders" as parent
      on parent."DriveFolder_ID" = ancestors.parent_id
     and parent."Company_ID" = v_company_id
    where ancestors.depth < 63
      and not parent."DriveFolder_ID" = any(ancestors.visited)
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', ancestors.id,
    'parentId', ancestors.parent_id,
    'name', ancestors.name,
    'colour', ancestors.colour,
    'icon', ancestors.icon,
    'createdAt', ancestors.created_at,
    'updatedAt', ancestors.updated_at
  ) order by ancestors.depth desc), '[]'::jsonb)
  into v_result
  from ancestors;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."crm_drive_folder_path"("p_folder_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."crm_drive_folder_stats"("p_parent_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("folderId" "uuid", "folderCount" bigint, "fileCount" bigint, "byteTotal" bigint, "lastActivityAt" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  perform public._crm_drive_require_permission('CRM.Drive.Read');
  return query
  with recursive subtree as (
    select folder."DriveFolder_ID" as root_id, folder."DriveFolder_ID" as node_id
    from public."CRM_DriveFolders" as folder
    where folder."Company_ID" = public.app_current_company_id()
      and folder."DriveFolder_ParentID" is not distinct from p_parent_id
    union all
    select parent.root_id, child."DriveFolder_ID"
    from subtree as parent
    join public."CRM_DriveFolders" as child
      on child."DriveFolder_ParentID" = parent.node_id
    where child."Company_ID" = public.app_current_company_id()
  )
  select
    subtree.root_id,
    count(distinct subtree.node_id) - 1,
    count(file."DriveFile_ID"),
    coalesce(sum(file."DriveFile_SizeBytes"), 0)::bigint,
    max(file."DriveFile_UpdatedAt")
  from subtree
  left join public."CRM_DriveFiles" as file
    on file."DriveFile_FolderID" = subtree.node_id
  group by subtree.root_id;
end;
$$;


ALTER FUNCTION "public"."crm_drive_folder_stats"("p_parent_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."crm_drive_list_files"("p_folder_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 48, "p_cursor" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_company_id uuid := public.app_current_company_id();
  v_limit integer := greatest(1, least(coalesce(p_limit, 48), 100));
begin
  perform public._crm_drive_require_permission('CRM.Drive.Read');

  return (
    with eligible as (
      select
        file."DriveFile_ID" as id,
        file."DriveFile_FolderID" as folder_id,
        file."DriveFile_Name" as name,
        file."DriveFile_MimeType" as mime_type,
        file."DriveFile_SizeBytes" as size_bytes,
        file."DriveFile_StoragePath" as storage_path,
        file."DriveFile_ThumbnailPath" as thumbnail_path,
        file."DriveFile_PreviewSeed" as preview_seed,
        file."DriveFile_PreviewWidth" as preview_width,
        file."DriveFile_PreviewHeight" as preview_height,
        file."DriveFile_CreatedAt" as created_at,
        file."DriveFile_UpdatedAt" as updated_at
      from public."CRM_DriveFiles" as file
      where file."Company_ID" = v_company_id
        and file."DriveFile_FolderID" is not distinct from p_folder_id
        and (
          p_cursor is null
          or lower(file."DriveFile_Name") > lower(p_cursor->>'name')
          or (
            lower(file."DriveFile_Name") = lower(p_cursor->>'name')
            and file."DriveFile_ID" > (p_cursor->>'id')::uuid
          )
        )
      order by lower(file."DriveFile_Name"), file."DriveFile_ID"
      limit v_limit + 1
    ), page as (
      select * from eligible
      limit v_limit
    ), total as (
      select count(*)::bigint as value
      from public."CRM_DriveFiles" as file
      where file."Company_ID" = v_company_id
        and file."DriveFile_FolderID" is not distinct from p_folder_id
    ), last_page as (
      select page.name, page.id
      from page
      order by lower(page.name) desc, page.id desc
      limit 1
    )
    select jsonb_build_object(
      'items', coalesce((
        select jsonb_agg(jsonb_build_object(
          'id', page.id,
          'folderId', page.folder_id,
          'name', page.name,
          'mimeType', page.mime_type,
          'sizeBytes', page.size_bytes,
          'storagePath', page.storage_path,
          'thumbnailPath', page.thumbnail_path,
          'previewSeed', page.preview_seed,
          'previewWidth', page.preview_width,
          'previewHeight', page.preview_height,
          'createdAt', page.created_at,
          'updatedAt', page.updated_at
        ) order by lower(page.name), page.id)
        from page
      ), '[]'::jsonb),
      'totalCount', (select total.value from total),
      'hasMore', (select count(*) > v_limit from eligible),
      'nextCursor', case
        when (select count(*) > v_limit from eligible) then (
          select jsonb_build_object('name', last_page.name, 'id', last_page.id)
          from last_page
        )
        else null
      end
    )
  );
end;
$$;


ALTER FUNCTION "public"."crm_drive_list_files"("p_folder_id" "uuid", "p_limit" integer, "p_cursor" "jsonb") OWNER TO "postgres";


