CREATE OR REPLACE FUNCTION "public"."customs_record_assessment_comparison"("p_actor" "uuid", "p_declaration" "uuid", "p_source" "uuid", "p_calculation" "uuid", "p_adapter_version" "text", "p_evidence" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare source public."Customs_ProviderResponseHistory"; calculation public."Customs_CalculationAudit"; result_id uuid;
begin
  perform 1 from public."Customs_Declarations" where "CUST_id"=p_declaration for update;
  if not coalesce(public.customs_declaration_authorised(p_actor,p_declaration,true,false),false)
    or not exists(select 1 from public."Customs_Declarations" where "CUST_id"=p_declaration and "CUST_Direction"='import') then
    raise exception 'Customs declaration unavailable.' using errcode='42501';
  end if;
  select * into source from public."Customs_ProviderResponseHistory" where id=p_source and declaration_id=p_declaration;
  select * into calculation from public."Customs_CalculationAudit" where id=p_calculation and declaration_id=p_declaration and kind='calculation';
  if source.id is null or calculation.id is null
    or source.declaration_snapshot#>>'{declaration,id}' is distinct from p_declaration::text
    or source.declaration_snapshot#>>'{calculationLink,calculationId}' is distinct from p_calculation::text
    or source.declaration_snapshot#>'{declaration,genericPayload}' is distinct from calculation.draft_snapshot then
    raise exception 'The source and calculation do not describe the same submitted revision.' using errcode='22023';
  end if;
  if p_adapter_version is null or p_adapter_version !~ '^[a-zA-Z0-9._-]{1,80}$'
    or jsonb_typeof(p_evidence) is distinct from 'object'
    or jsonb_typeof(p_evidence->'notices') is distinct from 'array'
    or jsonb_array_length(p_evidence->'notices')=0
    or octet_length(p_evidence::text)>2000000 then
    raise exception 'Invalid assessment comparison evidence.' using errcode='22023';
  end if;
  insert into public."Customs_AssessmentComparisons"(declaration_id,source_id,calculation_id,actor_auth_id,adapter_version,evidence)
    values(p_declaration,p_source,p_calculation,p_actor,p_adapter_version,p_evidence)
    on conflict(source_id,calculation_id,adapter_version) do nothing returning id into result_id;
  if result_id is null then
    select id into result_id from public."Customs_AssessmentComparisons"
      where source_id=p_source and calculation_id=p_calculation and adapter_version=p_adapter_version;
  end if;
  return result_id;
end;
$_$;


ALTER FUNCTION "public"."customs_record_assessment_comparison"("p_actor" "uuid", "p_declaration" "uuid", "p_source" "uuid", "p_calculation" "uuid", "p_adapter_version" "text", "p_evidence" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."customs_reference_preferences"("payload" "jsonb" DEFAULT NULL::"jsonb", "expected_version" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  actor public."cmp_Users"%rowtype;
  is_admin boolean;
  current_row booking_api.customs_reference_settings%rowtype;
  old_settings jsonb;
  offices jsonb;
  entry record;
  badge jsonb;
  eori text;
  default_office text;
begin
  select * into actor from public."cmp_Users"
    where "Auth_User_ID"=auth.uid() and "User_AccessStatus"='active' and "Company_ID" is not null;
  if actor."User_ID" is null then raise exception 'Your workspace identity is unavailable.' using errcode='42501'; end if;
  select exists(select 1 from public."cmp_Users_Roles" ur join public."sys_UserRoles" r
    on r."sys_UserRole_ID"=ur."sys_UserRole_ID"
    where ur."User_ID"=actor."User_ID" and lower(trim(r."sys_UserRole_Name")) in ('administrator','company admin')) into is_admin;
  if not is_admin and not coalesce(booking_api.has_permission(auth.uid(),'Customs.Read'),false) then
    raise exception 'Customs access is required.' using errcode='42501';
  end if;
  if payload is not null and not is_admin then
    raise exception 'Only tenant administrators can change customs preferences.' using errcode='42501';
  end if;
  -- Serialize first saves too, and detect stale admin forms.
  if payload is not null then perform pg_advisory_xact_lock(hashtextextended(actor."Company_ID"::text,731)); end if;
  select * into current_row from booking_api.customs_reference_settings where company_id=actor."Company_ID";
  if payload is not null then
    if expected_version is distinct from coalesce(current_row.version,0) then
      raise exception 'Customs preferences changed. Reload before saving.' using errcode='40001';
    end if;
    if jsonb_typeof(payload) is distinct from 'object' or octet_length(payload::text)>100000
      or jsonb_typeof(payload->'officeEoris') is distinct from 'object'
      or jsonb_typeof(payload->'badges') is distinct from 'array' then
      raise exception 'Invalid customs preferences.' using errcode='22023';
    end if;
    eori:=coalesce(payload->>'eori','');
    if eori<>'' and (eori !~ '^[A-Z]{2}[A-Z0-9]{1,15}$' or (left(eori,2) in ('GB','XI') and eori !~ '^(GB|XI)[0-9]{12}$')) then
      raise exception 'Enter the full registered company EORI. GB and XI EORIs require 12 digits.' using errcode='22023';
    end if;
    default_office:=coalesce(payload->>'defaultOfficeId','');
    if default_office<>'' and not exists(select 1 from public."cmp_Offices" o where o."Office_ID"::text=default_office and o."Company_ID"=actor."Company_ID" and o."Office_IsActive") then
      raise exception 'Select an active office in this company.' using errcode='42501';
    end if;
    for entry in select key,value from jsonb_each_text(payload->'officeEoris') loop
      if jsonb_typeof(payload->'officeEoris'->entry.key) is distinct from 'string' then
        raise exception 'Office EORI must be a registered identifier or an empty string.' using errcode='22023';
      end if;
      if not exists(select 1 from public."cmp_Offices" o where o."Office_ID"::text=entry.key and o."Company_ID"=actor."Company_ID" and o."Office_IsActive") then
        raise exception 'Office EORI must belong to an active office in this company.' using errcode='42501';
      end if;
      if entry.value<>'' and (entry.value !~ '^[A-Z]{2}[A-Z0-9]{1,15}$' or (left(entry.value,2) in ('GB','XI') and entry.value !~ '^(GB|XI)[0-9]{12}$')) then
        raise exception 'Enter the full registered office EORI.' using errcode='22023';
      end if;
    end loop;
    if jsonb_array_length(payload->'badges')>100 then raise exception 'Use no more than 100 badge configurations.' using errcode='22023'; end if;
    for badge in select value from jsonb_array_elements(payload->'badges') loop
      if jsonb_typeof(badge) is distinct from 'object'
        or exists(select 1 from unnest(array['id','code','provider','portCode','portName']) field where jsonb_typeof(badge->field) is distinct from 'string')
        or coalesce(badge->>'id','') !~ '^[a-zA-Z0-9-]{1,40}$'
        or coalesce(badge->>'code','') !~ '^[A-Z0-9]{1,40}$'
        or length(trim(coalesce(badge->>'provider',''))) not between 1 and 80
        or coalesce(badge->>'portCode','') !~ '^[A-Z]{2}[A-Z0-9]{3}$'
        or length(trim(coalesce(badge->>'portName',''))) not between 1 and 180
        or jsonb_typeof(badge->'active') is distinct from 'boolean' then
        raise exception 'Each badge needs a code, provider, port name, UN/LOCODE and active state.' using errcode='22023';
      end if;
    end loop;
    if (select count(*)<>count(distinct value->>'id') from jsonb_array_elements(payload->'badges')) then
      raise exception 'Badge identifiers must be unique.' using errcode='22023';
    end if;
    old_settings:=current_row.settings;
    insert into booking_api.customs_reference_settings(company_id,settings,updated_by)
      values(actor."Company_ID",jsonb_build_object('eori',eori,'defaultOfficeId',default_office,'officeEoris',payload->'officeEoris','badges',payload->'badges'),auth.uid())
      on conflict(company_id) do update set settings=excluded.settings,version=booking_api.customs_reference_settings.version+1,updated_by=auth.uid(),updated_at=now()
      returning * into current_row;
    insert into booking_api.customs_reference_settings_audit(company_id,actor_auth_user_id,previous_settings,settings)
      values(actor."Company_ID",auth.uid(),old_settings,current_row.settings);
  end if;
  select coalesce(jsonb_agg(jsonb_build_object('id',"Office_ID",'name',"Office_Name") order by "Office_Name"),'[]'::jsonb)
    into offices from public."cmp_Offices" where "Company_ID"=actor."Company_ID" and "Office_IsActive";
  return jsonb_build_object('settings',coalesce(current_row.settings,'{"eori":"","defaultOfficeId":"","officeEoris":{},"badges":[]}'::jsonb),'version',coalesce(current_row.version,0),'offices',offices,'canManage',is_admin);
end $_$;


ALTER FUNCTION "public"."customs_reference_preferences"("payload" "jsonb", "expected_version" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_customs_draft"("p_declaration_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_reference text;
  v_status text;
  v_is_deleted boolean;
  v_changed_at timestamptz := clock_timestamp();
begin
  if v_user_id is null then
    raise exception using errcode = '42501', message = 'Authentication is required to delete a Customs draft.';
  end if;

  select
    declaration."CUST_LocalReferenceNumber",
    declaration."CUST_Status",
    declaration."CUST_IsDeleted"
  into v_reference, v_status, v_is_deleted
  from public."Customs_Declarations" as declaration
  where declaration."CUST_id" = p_declaration_id
    and declaration."CUST_CreatedBy" = v_user_id
  for update;

  if not found or v_is_deleted or v_status <> 'draft' then
    raise exception using errcode = '42501', message = 'This Customs draft is unavailable or can no longer be deleted.';
  end if;

  update public."Customs_Declarations"
  set
    "CUST_IsDeleted" = true,
    "CUST_UpdatedAt" = v_changed_at,
    "CUST_UpdatedBy" = v_user_id
  where "CUST_id" = p_declaration_id;

  insert into public."Customs_AuditLog" (
    "CUSTAU_CustomsID",
    "CUSTAU_Action",
    "CUSTAU_TableName",
    "CUSTAU_RecordID",
    "CUSTAU_ChangedBy",
    "CUSTAU_ChangedAt",
    "CUSTAU_OldValues",
    "CUSTAU_NewValues",
    "CUSTAU_Source",
    "CUSTAU_Notes"
  ) values (
    p_declaration_id,
    'draft_deleted',
    'Customs_Declarations',
    p_declaration_id,
    v_user_id,
    v_changed_at,
    jsonb_build_object('isDeleted', false, 'status', v_status),
    jsonb_build_object('isDeleted', true, 'status', v_status),
    'multideck_app',
    coalesce(v_reference, p_declaration_id::text)
  );

  return true;
end;
$$;


ALTER FUNCTION "public"."delete_customs_draft"("p_declaration_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."delete_customs_draft"("p_declaration_id" "uuid") IS 'Soft-deletes one authenticated user-owned Customs declaration while it is still a draft and records the action in the Customs audit log.';



CREATE OR REPLACE FUNCTION "public"."email_signature_available"("p_user" "uuid", "p_company" "uuid", "p_template" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
 with actor as (
  select u."User_ID",public._multideck_dexter_has_permission(p_user,'Email.Signatures.Manage') manager,
    coalesce(profile.allow_customisation,policy.allow_customisation,true) personal
  from public."cmp_Users" u
  left join public.email_signature_profiles profile on profile.user_id=u."User_ID" and profile.company_id=p_company
  left join public.email_signature_policies policy on policy.company_id=p_company
  where u."User_ID"=p_user and u."Company_ID"=p_company and u."Auth_User_ID" is not null and coalesce(u."User_AccessStatus",'active')='active'
   and (public._multideck_dexter_has_permission(p_user,'Email.Send') or public._multideck_dexter_has_permission(p_user,'Email.Signatures.Manage'))
 ), candidates as (
  select t.id,min(case a->>'kind' when 'user' then 1 when 'department' then 2 when 'everyone' then 3 end) rank
  from public.email_signature_templates t cross join lateral jsonb_array_elements(t.published_assignments) a
  where t.company_id=p_company and not t.archived and t.owner_user_id is null and t.published_revision is not null
   and (a->>'kind'='everyone' or a->>'kind'='user' and a->>'id'=p_user::text or a->>'kind'='department' and exists(
    select 1 from public."cmp_Users_Departments" m join public."cmp_Departments" d on d."Department_ID"=m."Department_ID"
    where m."User_ID"=p_user and d."Company_ID"=p_company and d."Department_IsActive" and d."Department_ID"::text=a->>'id'))
  group by t.id
 ) select exists(select 1 from actor u cross join public.email_signature_templates t where t.id=p_template and t.company_id=p_company and not t.archived and
  (t.owner_user_id=p_user and u.personal or t.owner_user_id is null and (u.manager or t.id in(select id from candidates where rank=(select min(rank) from candidates)))));
$$;


ALTER FUNCTION "public"."email_signature_available"("p_user" "uuid", "p_company" "uuid", "p_template" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."email_signature_commit"("p_actor" "uuid", "p_id" "uuid", "p_expected" integer, "p_payload" "jsonb", "p_publish" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare u record; old public.email_signature_templates%rowtype; saved public.email_signature_templates%rowtype; manager boolean; allow_edit boolean; personal boolean;
begin
 select * into u from public."cmp_Users" where "User_ID"=p_actor and "Auth_User_ID" is not null and coalesce("User_AccessStatus",'active')='active';
 if not found or u."Company_ID" is null then raise exception 'Active company profile required' using errcode='42501'; end if;
 select exists(select 1 from public."cmp_Users_Roles" ur join public."sys_UserRole_Permissions" rp using("sys_UserRole_ID") join public."sys_Permissions" p using("sys_Permission_ID") where ur."User_ID"=p_actor and p."sys_Permission_Value"='Email.Signatures.Manage') into manager;
 select coalesce((select allow_customisation from public.email_signature_profiles where user_id=p_actor),(select allow_customisation from public.email_signature_policies where company_id=u."Company_ID"),true) into allow_edit;
 if not manager and not exists(select 1 from public."cmp_Users_Roles" ur join public."sys_UserRole_Permissions" rp using("sys_UserRole_ID") join public."sys_Permissions" p using("sys_Permission_ID") where ur."User_ID"=p_actor and p."sys_Permission_Value"='Email.Send') then raise exception 'Email permission required' using errcode='42501';end if;
 -- Serialise assignment and policy changes for this company, including separate templates.
 perform pg_advisory_xact_lock(hashtextextended(u."Company_ID"::text,1430));
 select * into old from public.email_signature_templates where id=p_id for update;
 if found then
   if old.company_id<>u."Company_ID" or old.archived or (old.owner_user_id is null and not manager) or (old.owner_user_id is not null and (old.owner_user_id<>p_actor or not allow_edit)) then raise exception 'Signature access denied' using errcode='42501';end if;
   if old.revision<>p_expected then raise exception 'Signature changed; refresh before saving' using errcode='40001';end if;
   personal:=old.owner_user_id is not null;
 else
   if p_expected<>0 then raise exception 'Signature not found' using errcode='42501';end if;
   personal:=coalesce((p_payload->>'personal')::boolean,false);
   if (personal and not allow_edit) or (not personal and not manager) then raise exception 'Signature access denied' using errcode='42501';end if;
 end if;
 if exists(select 1 from jsonb_array_elements(coalesce(p_payload->'assignments','[]')) a where not (
   a->>'kind'='everyone' and a->>'id' is null or a->>'kind'='user' and exists(select 1 from public."cmp_Users" target where target."User_ID"::text=a->>'id' and target."Company_ID"=u."Company_ID" and coalesce(target."User_AccessStatus",'active')='active') or a->>'kind'='department' and exists(select 1 from public."cmp_Departments" d where d."Department_ID"::text=a->>'id' and d."Company_ID"=u."Company_ID" and d."Department_IsActive"))) then raise exception 'Invalid assignment' using errcode='42501';end if;
 if nullif(p_payload->>'sourceTemplateId','') is not null and not exists(select 1 from public.email_signature_templates source where source.id::text=p_payload->>'sourceTemplateId' and source.company_id=u."Company_ID" and (source.owner_user_id is null or source.owner_user_id=p_actor)) then raise exception 'Invalid source signature' using errcode='42501';end if;
 if personal and jsonb_array_length(coalesce(p_payload->'assignments','[]'))>0 then raise exception 'Personal signatures cannot be assigned';end if;
 if coalesce((p_payload->>'archived')::boolean,false) and (jsonb_array_length(coalesce(old.published_assignments,'[]'))>0 or jsonb_array_length(coalesce(p_payload->'assignments','[]'))>0) then raise exception 'Remove assignments before archiving';end if;
 insert into public.email_signature_templates(id,company_id,owner_user_id,source_template_id,name,document,assignments,revision,created_by,updated_by)
 values(p_id,u."Company_ID",case when personal then p_actor end,nullif(p_payload->>'sourceTemplateId','')::uuid,p_payload->>'name',p_payload->'document',coalesce(p_payload->'assignments','[]'),1,p_actor,p_actor)
 on conflict(id) do update set name=excluded.name,document=excluded.document,assignments=excluded.assignments,revision=old.revision+1,updated_by=p_actor,updated_at=clock_timestamp()
 returning * into saved;
 if p_publish then
   if not personal and not coalesce(p_payload->'assignments','[]') @> '[{"kind":"everyone","id":null}]'::jsonb
     and not exists(select 1 from public.email_signature_templates t where t.company_id=u."Company_ID" and t.id<>p_id and not t.archived and t.owner_user_id is null and t.published_assignments @> '[{"kind":"everyone","id":null}]'::jsonb)
     and (exists(select 1 from public.email_signature_policies where company_id=u."Company_ID" and not allow_customisation) or exists(select 1 from public.email_signature_profiles where company_id=u."Company_ID" and allow_customisation=false)) then
       raise exception 'Keep a company default while customisation is restricted' using errcode='42501';
   end if;
   update public.email_signature_templates set published_document=document,published_assignments=assignments,published_revision=revision where id=p_id returning * into saved;
   insert into public.email_signature_versions(template_id,company_id,revision,document,assignments,actor_id) values(p_id,u."Company_ID",saved.revision,saved.document,saved.assignments,p_actor);
 end if;
 if coalesce((p_payload->>'archived')::boolean,false) then update public.email_signature_templates set archived=true where id=p_id returning * into saved;end if;
 insert into public.email_signature_events(company_id,actor_id,owner_user_id,template_id,kind,details) values(u."Company_ID",p_actor,saved.owner_user_id,p_id,case when saved.archived then 'archived' when p_publish then 'published' else 'draft_saved' end,jsonb_build_object('revision',saved.revision,'name',saved.name));
 return to_jsonb(saved);
end $$;


ALTER FUNCTION "public"."email_signature_commit"("p_actor" "uuid", "p_id" "uuid", "p_expected" integer, "p_payload" "jsonb", "p_publish" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."email_signature_company_details"("p_actor" "uuid", "p_details" "jsonb", "p_revision" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare company uuid; current_revision integer;
begin
 select u."Company_ID" into company from public."cmp_Users" u where u."User_ID"=p_actor and u."Auth_User_ID" is not null and coalesce(u."User_AccessStatus",'active')='active'
 and exists(select 1 from public."cmp_Users_Roles" ur join public."sys_UserRole_Permissions" rp using("sys_UserRole_ID") join public."sys_Permissions" p using("sys_Permission_ID") where ur."User_ID"=p_actor and p."sys_Permission_Value"='Email.Signatures.Manage');
 if company is null then raise exception 'Signature manager required' using errcode='42501'; end if;
 perform pg_advisory_xact_lock(hashtextextended(company::text,1430));
 select revision into current_revision from public.email_signature_policies where company_id=company;
 if p_revision is distinct from coalesce(current_revision,0) then raise exception 'Company details changed. Refresh and try again.' using errcode='40001'; end if;
 if jsonb_typeof(p_details) is distinct from 'object' or pg_column_size(p_details)>10000 then raise exception 'Invalid company details' using errcode='22023'; end if;
 insert into public.email_signature_policies(company_id,company_details) values(company,p_details)
 on conflict(company_id) do update set company_details=excluded.company_details,revision=email_signature_policies.revision+1,updated_at=clock_timestamp();
 insert into public.email_signature_events(company_id,actor_id,kind,details) values(company,p_actor,'policy_changed','{"companyDetailsChanged":true}');
end $$;


ALTER FUNCTION "public"."email_signature_company_details"("p_actor" "uuid", "p_details" "jsonb", "p_revision" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."email_signature_policy"("p_actor" "uuid", "p_user" "uuid", "p_allow" boolean, "p_website" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare company uuid;
begin
 select u."Company_ID" into company from public."cmp_Users" u where u."User_ID"=p_actor and u."Auth_User_ID" is not null and coalesce(u."User_AccessStatus",'active')='active'
  and exists(select 1 from public."cmp_Users_Roles" ur join public."sys_UserRole_Permissions" rp using("sys_UserRole_ID") join public."sys_Permissions" p using("sys_Permission_ID") where ur."User_ID"=p_actor and p."sys_Permission_Value"='Email.Signatures.Manage');
 if company is null then raise exception 'Signature manager required' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended(company::text,1430));
 if p_user is not null and not exists(select 1 from public."cmp_Users" where "User_ID"=p_user and "Company_ID"=company and coalesce("User_AccessStatus",'active')='active') then raise exception 'Signature profile unavailable' using errcode='42501';end if;
 if p_allow=false and not exists(select 1 from public.email_signature_templates where company_id=company and owner_user_id is null and not archived and published_revision is not null and published_assignments @> '[{"kind":"everyone","id":null}]'::jsonb) then raise exception 'Apply a company default before restricting customisation' using errcode='22023';end if;
 if p_user is null then
  insert into public.email_signature_policies(company_id,allow_customisation,website) values(company,coalesce(p_allow,true),left(coalesce(p_website,''),2000))
  on conflict(company_id) do update set allow_customisation=excluded.allow_customisation,website=excluded.website,revision=email_signature_policies.revision+1,updated_at=clock_timestamp();
 else
  insert into public.email_signature_profiles(user_id,company_id,allow_customisation) values(p_user,company,p_allow)
  on conflict(user_id) do update set allow_customisation=excluded.allow_customisation,updated_at=clock_timestamp();
 end if;
 insert into public.email_signature_events(company_id,actor_id,owner_user_id,kind,details) values(company,p_actor,p_user,'policy_changed',jsonb_build_object('allowCustomisation',p_allow));
end $$;


ALTER FUNCTION "public"."email_signature_policy"("p_actor" "uuid", "p_user" "uuid", "p_allow" boolean, "p_website" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."email_signature_profile_sources"("p_company" "uuid") RETURNS TABLE("user_id" "uuid", "name" "text", "phone" "text", "mobile" "text", "website" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
 select u."User_ID",coalesce(nullif(trim(concat_ws(' ',a.raw_user_meta_data->>'first_name',a.raw_user_meta_data->>'last_name')),''),nullif(a.raw_user_meta_data->>'full_name',''),nullif(a.raw_user_meta_data->>'name','')),
 coalesce(a.raw_user_meta_data->>'phone',a.raw_user_meta_data->>'phone_number',a.raw_user_meta_data->>'mobile',a.phone,''),coalesce(a.raw_user_meta_data->>'mobile',''),coalesce(a.raw_user_meta_data->>'website',a.raw_user_meta_data->>'website_url','')
 from public."cmp_Users" u join auth.users a on a.id=u."Auth_User_ID" where u."Company_ID"=p_company and coalesce(u."User_AccessStatus",'active')='active'
$$;


ALTER FUNCTION "public"."email_signature_profile_sources"("p_company" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."email_signature_team_patch"("p_actor" "uuid", "p_user" "uuid", "p_field" "text", "p_value" "text", "p_expected" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare company uuid; saved public.email_signature_profiles%rowtype;
begin
 select "Company_ID" into company from "cmp_Users" where "User_ID"=p_actor and "Auth_User_ID" is not null and coalesce("User_AccessStatus",'active')='active';
 if company is null or not exists(select 1 from "cmp_Users_Roles" ur join "sys_UserRole_Permissions" rp using("sys_UserRole_ID") join "sys_Permissions" p using("sys_Permission_ID") where ur."User_ID"=p_actor and p."sys_Permission_Value"='Email.Signatures.Manage') then raise exception 'Signature manager required' using errcode='42501';end if;
 if not exists(select 1 from "cmp_Users" where "User_ID"=p_user and "Company_ID"=company and "Auth_User_ID" is not null and coalesce("User_AccessStatus",'active')='active') then raise exception 'Person unavailable' using errcode='42501';end if;
 if p_field not in ('name','jobTitle','email','phone','mobile','address','website','company') or length(p_value)>500 then raise exception 'Invalid signature field' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_user::text,1700));
 select * into saved from email_signature_profiles where user_id=p_user for update;
 if coalesce(saved.revision,0)<>p_expected then raise exception 'Details changed; refresh before saving' using errcode='40001';end if;
 insert into email_signature_profiles(user_id,company_id,overrides,revision) values(p_user,company,case when p_value is null then '{}'::jsonb else jsonb_build_object(p_field,p_value) end,1)
 on conflict(user_id) do update set overrides=case when p_value is null then email_signature_profiles.overrides-p_field else email_signature_profiles.overrides||jsonb_build_object(p_field,p_value) end,revision=email_signature_profiles.revision+1,updated_at=now() returning * into saved;
 insert into email_signature_events(company_id,actor_id,owner_user_id,kind,details) values(company,p_actor,p_user,'profile_override_changed',jsonb_build_object('field',p_field,'reset',p_value is null,'revision',saved.revision));
 return to_jsonb(saved);
end $$;


ALTER FUNCTION "public"."email_signature_team_patch"("p_actor" "uuid", "p_user" "uuid", "p_field" "text", "p_value" "text", "p_expected" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."email_signature_watch_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
 if new."AIDexterWatch_CapabilityCode"='email_signatures' and new."AIDexterWatch_StatusCode"='active' and
  (new."AIDexterWatch_TargetID" is null or not public.email_signature_available(new."AIDexterWatch_OwnerUserID",new."AIDexterWatch_CompanyID",new."AIDexterWatch_TargetID")
   or (new."AIDexterWatch_RuleJSON"->>'field'='assignments' and not public._multideck_dexter_has_permission(new."AIDexterWatch_OwnerUserID",'Email.Signatures.Manage'))
   or new."AIDexterWatch_RuleJSON"->>'field' not in ('publishedRevision','assignments') or new."AIDexterWatch_RuleJSON"->>'operator'<>'changed' or new."AIDexterWatch_ActionJSON" is not null) then
   raise exception 'Choose one accessible signature and a published change to watch; automatic edits are unavailable.' using errcode='42501';
 end if;
 return new;
end $$;


ALTER FUNCTION "public"."email_signature_watch_guard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."email_signature_watch_signal"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
 if new.published_revision is not null and (old.published_revision is distinct from new.published_revision or old.published_assignments is distinct from new.published_assignments) then
  insert into public."AI_DexterWatchSignals"("AIDexterWatchSignal_CompanyID","AIDexterWatchSignal_CapabilityCode","AIDexterWatchSignal_SourceTable","AIDexterWatchSignal_SourceID","AIDexterWatchSignal_OldJSON","AIDexterWatchSignal_NewJSON")
  values(new.company_id,'email_signatures','email_signature_templates',new.id,jsonb_build_object('publishedRevision',old.published_revision,'assignments',old.published_assignments),jsonb_build_object('publishedRevision',new.published_revision,'assignments',new.published_assignments));
 end if;
 return new;
end $$;


