  end if;
  return NEW;
end;
$$;


ALTER FUNCTION "public"."guard_company_appearance_preference"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_training_access_changes"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if exists (select 1 from public.training_configuration)
    and coalesce(current_setting('multideck.training_identity_sync', true), '') <> 'on' then
    raise exception 'Manage accounts and permissions in Main; Training inherits access';
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end $$;


ALTER FUNCTION "public"."guard_training_access_changes"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_training_auth_credentials"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare source_url text;
begin
  select main_project_url into source_url from public.training_configuration where singleton;
  if source_url is null then return new; end if;
  -- GoTrue creates a random password when admin.createUser omits one, and
  -- writes app_metadata later in the same transaction. Remove that password.
  if tg_op = 'INSERT' then new.encrypted_password := null; end if;
  if new.email is distinct from new.id::text || '@training.multideck.invalid'
    or (new.raw_app_meta_data->>'training_main_project' is not null
      and new.raw_app_meta_data->>'training_main_project' is distinct from source_url)
    or coalesce(new.encrypted_password, '') <> '' or coalesce(new.phone, '') <> '' then
    raise exception 'Training authentication is available only through Main';
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."guard_training_auth_credentials"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_training_auth_factors"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if exists (select 1 from public.training_configuration) then
    raise exception 'Manage authentication factors and passkeys in Main';
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."guard_training_auth_factors"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_training_auth_identities"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if exists (select 1 from public.training_configuration) then
    if tg_op = 'DELETE' or new.provider <> 'email'
      or new.identity_data->>'email' is distinct from new.user_id::text || '@training.multideck.invalid' then
      raise exception 'Link sign-in methods in Main, not Training';
    end if;
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end $$;


ALTER FUNCTION "public"."guard_training_auth_identities"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."live_gateway_access_synced"("p_grant_id" "text", "p_version" integer) RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
 update private_live_gateway.customer_grants set live_sync_status='ready' where id=p_grant_id and version=p_version;
$$;


ALTER FUNCTION "public"."live_gateway_access_synced"("p_grant_id" "text", "p_version" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."live_gateway_admin_email_access"("p_actor_id" "uuid", "p_organisation_id" "uuid", "p_facility_ids" "uuid"[], "p_input" "jsonb", "p_email" "text", "p_live_customer_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare result jsonb; old_value jsonb; requested_facilities uuid[]; previous_facilities jsonb;
begin
 if p_email is null or length(p_email)>254 or p_email!~'^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$' or p_live_customer_id is null or p_live_customer_id<1 then raise exception 'Choose a Live customer' using errcode='22023'; end if;
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_input->>'id',0));
 select to_jsonb(g) into old_value from private_live_gateway.customer_grants g where g.id=p_input->>'id';
 if old_value->>'live_customer_id' is not null and (old_value->>'live_customer_id')::bigint<>p_live_customer_id then raise exception 'Customer identity cannot change' using errcode='42501'; end if;
 -- The selected warehouses are the explicit business assignment; no legacy setup step is required.
 -- All changes remain in the grant transaction and roll back if grant validation fails.
 if p_input->'enabled'='true'::jsonb then
   if p_actor_id is null or p_organisation_id is null or jsonb_typeof(p_input->'facilityIds') is distinct from 'array' then
     raise exception 'Choose warehouses for this company' using errcode='22023';
   end if;
   select array_agg(distinct value::uuid) into requested_facilities from jsonb_array_elements_text(p_input->'facilityIds');
   if coalesce(cardinality(requested_facilities),0)=0 or coalesce(cardinality(p_facility_ids),0)=0
     or not requested_facilities<@p_facility_ids or exists(select 1 from unnest(requested_facilities) id where
       not exists(select 1 from public."WMS_Facilities" f where f."WMSFacility_ID"=id and f."WMSFacility_IsActive" and not f."WMSFacility_IsDeleted")) then
     raise exception 'Warehouse assignment denied' using errcode='42501';
   end if;
   select coalesce(jsonb_agg(to_jsonb(a)),'[]') into previous_facilities from public."WMS_CustomerFacilityAccess" a
     where a."WMSCustomerFacilityAccess_CustomerOrgID"=p_organisation_id and a."WMSCustomerFacilityAccess_FacilityID"=any(requested_facilities);
   insert into public."WMS_CustomerFacilityAccess"("WMSCustomerFacilityAccess_ID","WMSCustomerFacilityAccess_CustomerOrgID","WMSCustomerFacilityAccess_FacilityID","WMSCustomerFacilityAccess_IsActive","WMSCustomerFacilityAccess_CreatedAt","WMSCustomerFacilityAccess_CreatedBy","WMSCustomerFacilityAccess_UpdatedAt")
     select gen_random_uuid(),p_organisation_id,id,true,now(),p_actor_id,now() from unnest(requested_facilities) id
     on conflict ("WMSCustomerFacilityAccess_CustomerOrgID","WMSCustomerFacilityAccess_FacilityID") do update
       set "WMSCustomerFacilityAccess_IsActive"=true,"WMSCustomerFacilityAccess_UpdatedAt"=now()
       where not "WMS_CustomerFacilityAccess"."WMSCustomerFacilityAccess_IsActive";
   insert into private_live_gateway.grant_audit(actor_id,grant_id,reason,before_value,after_value)
     values(p_actor_id,p_input->>'id','Company warehouses selected for Live access',
       jsonb_build_object('organisationId',p_organisation_id,'assignments',previous_facilities),
       jsonb_build_object('organisationId',p_organisation_id,'selectedFacilityIds',requested_facilities,'enabled',true));
 end if;
 result:=public.live_gateway_admin_grants(p_actor_id,p_organisation_id,p_facility_ids,p_input);
 update private_live_gateway.customer_grants g set email=lower(btrim(p_email)),live_customer_id=p_live_customer_id,live_sync_status='pending' where g.id=result->>'id' returning to_jsonb(g) into result;
 insert into private_live_gateway.grant_audit(actor_id,grant_id,reason,before_value,after_value) values(p_actor_id,result->>'id','Verified Live email binding',coalesce(old_value,'{}'),result);
 return result;
end;
$_$;


ALTER FUNCTION "public"."live_gateway_admin_email_access"("p_actor_id" "uuid", "p_organisation_id" "uuid", "p_facility_ids" "uuid"[], "p_input" "jsonb", "p_email" "text", "p_live_customer_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."live_gateway_admin_grants"("p_actor_id" "uuid", "p_organisation_id" "uuid", "p_facility_ids" "uuid"[], "p_input" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare g private_live_gateway.customer_grants%rowtype; result jsonb; requested_facilities uuid[]; previous jsonb:='{}';
begin
 if p_actor_id is null or p_organisation_id is null or coalesce(cardinality(p_facility_ids),0)=0 then raise exception 'Warehouse administration denied' using errcode='42501'; end if;
 if p_input is null then
   select coalesce(jsonb_agg(to_jsonb(a) order by a.id),'[]') into result from private_live_gateway.customer_grants a
   where a.organisation_id=p_organisation_id and a.facility_ids<@p_facility_ids;
   return result;
 end if;
 if jsonb_typeof(p_input) is distinct from 'object' or exists(select 1 from jsonb_object_keys(p_input) k where k not in ('id','connectionId','keyId','subjectId','facilityIds','enabled','productsEnabled','ordersEnabled','purchaseOrdersEnabled','expectedVersion','reason'))
   or coalesce(p_input->>'id','')!~'^[A-Za-z0-9_-]{1,128}$' or coalesce(p_input->>'connectionId','')!~'^[A-Za-z0-9_-]{1,128}$'
   or coalesce(p_input->>'keyId','')!~'^[A-Za-z0-9_-]{1,128}$' or coalesce(p_input->>'subjectId','')!~'^[A-Za-z0-9_-]{1,128}$'
   or nullif(btrim(p_input->>'reason'),'') is null or length(p_input->>'reason')>500
   or jsonb_typeof(p_input->'facilityIds') is distinct from 'array' then raise exception 'Invalid grant' using errcode='22023'; end if;
 if exists(select 1 from unnest(array['enabled','productsEnabled','ordersEnabled','purchaseOrdersEnabled']) k where jsonb_typeof(p_input->k) is distinct from 'boolean') then raise exception 'Choose each permission' using errcode='22023'; end if;
 select array_agg(distinct value::uuid) into requested_facilities from jsonb_array_elements_text(p_input->'facilityIds');
 if coalesce(cardinality(requested_facilities),0)=0 or not requested_facilities<@p_facility_ids or ((p_input->>'enabled')::boolean and exists(select 1 from unnest(requested_facilities) id
   where not exists(select 1 from public."WMS_CustomerFacilityAccess" a join public."WMS_Facilities" f on f."WMSFacility_ID"=a."WMSCustomerFacilityAccess_FacilityID"
     where a."WMSCustomerFacilityAccess_CustomerOrgID"=p_organisation_id and a."WMSCustomerFacilityAccess_FacilityID"=id and a."WMSCustomerFacilityAccess_IsActive" and f."WMSFacility_IsActive" and not f."WMSFacility_IsDeleted"))) then raise exception 'Warehouse assignment denied' using errcode='42501'; end if;
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_input->>'id',0));
 select * into g from private_live_gateway.customer_grants where id=p_input->>'id' for update;
 if g.id is not null and (g.organisation_id<>p_organisation_id or not g.facility_ids<@p_facility_ids or g.connection_id<>p_input->>'connectionId' or g.subject_id<>p_input->>'subjectId') then raise exception 'Grant identity cannot be reassigned' using errcode='42501'; end if;
 if (g.id is null and p_input->>'expectedVersion' is not null) or (g.id is not null and g.version is distinct from (p_input->>'expectedVersion')::integer) then raise exception 'Grant changed' using errcode='40001'; end if;
 if g.id is not null then previous:=to_jsonb(g); end if;
 if (p_input->>'enabled')::boolean then
 insert into private_live_gateway.connections(id,enabled) values(p_input->>'connectionId',true) on conflict(id) do nothing;
 insert into private_live_gateway.keys(id,connection_id,enabled) values(p_input->>'keyId',p_input->>'connectionId',true) on conflict(id) do nothing;
 if not exists(select 1 from private_live_gateway.keys k join private_live_gateway.connections c on c.id=k.connection_id where k.id=p_input->>'keyId' and k.connection_id=p_input->>'connectionId' and k.enabled and c.enabled and (k.expires_at is null or k.expires_at>now())) then raise exception 'Connection key is disabled or belongs to another company' using errcode='42501'; end if;
 end if;
 insert into private_live_gateway.customer_grants as a(id,connection_id,subject_id,organisation_id,facility_ids,enabled,products_enabled,orders_enabled,purchase_orders_enabled)
 values(p_input->>'id',p_input->>'connectionId',p_input->>'subjectId',p_organisation_id,requested_facilities,(p_input->>'enabled')::boolean,(p_input->>'productsEnabled')::boolean,(p_input->>'ordersEnabled')::boolean,(p_input->>'purchaseOrdersEnabled')::boolean)
 on conflict(id) do update set facility_ids=excluded.facility_ids,enabled=excluded.enabled,products_enabled=excluded.products_enabled,orders_enabled=excluded.orders_enabled,purchase_orders_enabled=excluded.purchase_orders_enabled,version=a.version+1
 returning to_jsonb(a) into result;
 insert into private_live_gateway.grant_audit(actor_id,grant_id,reason,before_value,after_value) values(p_actor_id,p_input->>'id',btrim(p_input->>'reason'),previous,result);
 return result;
end;
$_$;


ALTER FUNCTION "public"."live_gateway_admin_grants"("p_actor_id" "uuid", "p_organisation_id" "uuid", "p_facility_ids" "uuid"[], "p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."live_gateway_mutate"("p_key_id" "text", "p_connection_id" "text", "p_subject_id" "text", "p_grant_id" "text", "p_nonce" "uuid", "p_operation" "text", "p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
<<mutation>>
declare
  grant_row private_live_gateway.customer_grants%rowtype;
  replay private_live_gateway.changes%rowtype;
  org_id uuid; target_facility_id uuid; target_item_id uuid; request_id uuid;
  product_description text; product_sku text; product_uom text; expected_updated_at timestamptz;
  item public."WMS_Items"%rowtype; previous jsonb := '{}'; result jsonb;
  order_kind text; order_payload jsonb; line jsonb; operational_lines jsonb := '[]';
  quantity numeric; unit_price numeric; tax_rate numeric; payload jsonb; record_id uuid; reference text; status text;
begin
  if p_operation is null or p_operation not in ('warehouse.product.create','warehouse.product.rename','warehouse.order.submit')
    or jsonb_typeof(p_input) is distinct from 'object' then raise exception 'Invalid operation' using errcode='22023'; end if;
  target_facility_id := (p_input->>'facilityId')::uuid;
  request_id := (p_input->>'requestId')::uuid;
  if request_id is null or target_facility_id is null then raise exception 'Request and warehouse required' using errcode='22023'; end if;
  -- Reuse the exact read authentication boundary and consume the transport nonce atomically.
  perform public.live_gateway_read(p_key_id,p_connection_id,p_subject_id,p_grant_id,p_nonce,'warehouse.stock',jsonb_build_object('facilityId',target_facility_id,'limit',1));
  update private_live_gateway.requests set operation=p_operation where key_id=p_key_id and nonce=p_nonce;
  -- Serialise writes/retries and permission edits on the verified grant.
  select * into grant_row from private_live_gateway.customer_grants where id=p_grant_id for update;
  org_id := grant_row.organisation_id;
  order_kind := p_input->>'kind';
  if not (case when p_operation='warehouse.order.submit' then
    case when order_kind='purchase_order' then grant_row.purchase_orders_enabled else grant_row.orders_enabled end
    else grant_row.products_enabled end) then raise exception 'Action denied' using errcode='42501'; end if;
  -- Serialise the request identity across grants, too; never repeat a write on a new grant.
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_connection_id||':'||p_subject_id||':'||request_id::text,0));
  select * into replay from private_live_gateway.changes c where c.connection_id=p_connection_id and c.subject_id=p_subject_id and c.request_id=mutation.request_id;
  if found then
    if replay.grant_id<>p_grant_id or replay.organisation_id<>org_id or replay.operation<>p_operation or replay.input<>p_input then
      raise exception 'Request ID used for a different change' using errcode='40001'; end if;
    return replay.result;
  end if;
  if p_operation='warehouse.order.submit' then
    if exists(select 1 from jsonb_object_keys(p_input) k where k not in ('facilityId','requestId','kind','payload')) then raise exception 'Unsupported order field' using errcode='22023'; end if;
    order_payload := p_input->'payload';
  if order_kind is null or order_kind not in ('purchase_order','inbound','outbound') or request_id is null
    or jsonb_typeof(order_payload) is distinct from 'object' then
    raise exception 'Invalid order request' using errcode='22023'; end if;
  if exists(select 1 from jsonb_object_keys(order_payload) k where k not in ('reference','requestedDate','instructions','supplierName','currency','lines')) then
    raise exception 'Unsupported order field' using errcode='22023'; end if;
  if nullif(btrim(order_payload->>'reference'),'') is null or length(order_payload->>'reference')>120
    or length(coalesce(order_payload->>'instructions',''))>4000 or length(coalesce(order_payload->>'supplierName',''))>240
    or jsonb_typeof(order_payload->'lines') is distinct from 'array' then
    raise exception 'Provide a reference and item lines' using errcode='22023'; end if;
  if jsonb_array_length(order_payload->'lines') not between 1 and 100 then
    raise exception 'Supply between 1 and 100 item lines' using errcode='22023'; end if;
  if nullif(order_payload->>'requestedDate','') is null then
    raise exception 'Choose a requested date' using errcode='22023'; end if;
  perform (order_payload->>'requestedDate')::date;
  -- One line per product prevents per-line availability checks being bypassed by duplicates.
  if (select count(distinct value->>'itemId') from jsonb_array_elements(order_payload->'lines'))<>jsonb_array_length(order_payload->'lines') then
    raise exception 'Use one line per product' using errcode='22023'; end if;
  for line in select value from jsonb_array_elements(order_payload->'lines') loop
    if jsonb_typeof(line) is distinct from 'object' or exists(select 1 from jsonb_object_keys(line) k where k not in ('itemId','quantity','unitPrice','taxRate')) then
      raise exception 'Unsupported item line' using errcode='22023'; end if;
    select i.* into item from public."WMS_Items" i
      join public."WMS_ItemFacilityAssignments" a on a."WMSItemFacility_ItemID"=i."WMSItem_ID"
        and a."WMSItemFacility_FacilityID"=target_facility_id and a."WMSItemFacility_IsActive"
      where i."WMSItem_ID"=(line->>'itemId')::uuid and i."WMSItem_CustomerOrgID"=org_id and i."WMSItem_IsActive" and not i."WMSItem_IsDeleted";
    if not found then raise exception 'Product is not available for this customer and warehouse' using errcode='42501'; end if;
    if coalesce(line->>'quantity','')!~'^[0-9]+(\.[0-9]{1,6})?$' then raise exception 'Enter a positive quantity with at most six decimal places' using errcode='22023'; end if;
    quantity:=(line->>'quantity')::numeric;
    if quantity<=0 or quantity>=1000000000000 then raise exception 'Quantity out of range' using errcode='22023'; end if;
    perform public._warehouse_edge_validate_quantity(item."WMSItem_ID",quantity);
    unit_price:=coalesce(nullif(line->>'unitPrice','')::numeric,0);tax_rate:=coalesce(nullif(line->>'taxRate','')::numeric,0);
    if unit_price<0 or unit_price>=1000000000 or tax_rate<0 or tax_rate>100 or unit_price::text in ('NaN','Infinity','-Infinity') or tax_rate::text in ('NaN','Infinity','-Infinity') then
      raise exception 'Invalid price or tax rate' using errcode='22023'; end if;
    operational_lines:=operational_lines||jsonb_build_array(jsonb_build_object('itemId',item."WMSItem_ID",'sku',item."WMSItem_SKU",
      'description',item."WMSItem_Description",'quantity',quantity,'uomCode',item."WMSItem_BaseUOMCode",'unitPrice',unit_price,'taxRate',tax_rate));
  end loop;
  if order_kind='purchase_order' then
    if coalesce(order_payload->>'currency','')!~'^[A-Z]{3}$' then raise exception 'Choose a currency' using errcode='22023'; end if;
    payload:=jsonb_build_object('facilityId',target_facility_id,'customerOrgId',org_id,'number',btrim(order_payload->>'reference'),
      'supplierName',coalesce(order_payload->>'supplierName',''),'currencyCode',order_payload->>'currency',
      'expectedDeliveryDate',order_payload->>'requestedDate','notes',order_payload->>'instructions','lines',operational_lines);
    record_id:=public.warehouse_edge_purchase_order_mutation('create',null,payload,null,array[target_facility_id]);
    perform public.warehouse_edge_purchase_order_mutation('issue',record_id,'{}',null,array[target_facility_id]);
    -- This server-owned facility policy is never accepted from customer input.
    -- Use the real inbound conversion so links, quantities and events stay consistent.
    if exists(select 1 from public."WMS_Facilities" f where f."WMSFacility_ID"=target_facility_id
      and f."WMSFacility_AutoReceiveLivePurchaseOrders" and f."WMSFacility_IsActive" and not f."WMSFacility_IsDeleted") then
      perform public.warehouse_edge_purchase_order_mutation('create_inbound',record_id,'{}',null,array[target_facility_id]);
    end if;
    select p."WMSPO_Number",p."WMSPO_StatusCode" into reference,status from public."WMS_PurchaseOrders" p where p."WMSPO_ID"=record_id;
  else
    payload:=jsonb_build_object('facilityId',target_facility_id,'customerOrgId',org_id,'typeCode',order_kind,
      'sourceTypeCode','manual_exception','sourceNotes','Customer submitted through Multideck Live',
      'customerReference',btrim(order_payload->>'reference'),'requestedDate',order_payload->>'requestedDate',
      'instructions',order_payload->>'instructions','lines',operational_lines);
    record_id:=public.warehouse_edge_create_order_mutation(payload,null,null,array[target_facility_id],array[org_id]);
    select o."WMSOrder_OrderNumber",o."WMSOrder_StatusCode" into reference,status from public."WMS_Orders" o where o."WMSOrder_ID"=record_id;
  end if;
  result:=jsonb_build_object('id',record_id,'kind',order_kind,'number',reference,'status',status);

  else
    if exists(select 1 from jsonb_object_keys(p_input) k where k not in ('facilityId','requestId','itemId','description','sku','uom','updatedAt','details')) then raise exception 'Unsupported product field' using errcode='22023'; end if;
    target_item_id := (p_input->>'itemId')::uuid;
    if (p_operation='warehouse.product.rename' and target_item_id is null) or (p_operation='warehouse.product.create' and target_item_id is not null) then raise exception 'Invalid product operation' using errcode='22023'; end if;
    product_description := p_input->>'description'; product_sku := p_input->>'sku'; product_uom := p_input->>'uom'; expected_updated_at := (p_input->>'updatedAt')::timestamptz;
    if nullif(btrim(product_description),'') is null or length(btrim(product_description))>240 then raise exception 'Invalid product name' using errcode='22023'; end if;
  if target_item_id is not null and p_input ? 'details' then raise exception 'Renaming cannot change product details' using errcode='22023'; end if;
  if target_item_id is null then
    payload := private_live_gateway.product_details(coalesce(p_input->'details','{}'::jsonb));
    if expected_updated_at is not null or nullif(btrim(product_sku),'') is null or length(btrim(product_sku))>120
      or product_uom is null or upper(btrim(product_uom))!~'^[A-Z][A-Z0-9_/-]{0,19}$' then
      raise exception 'Enter a SKU and unit' using errcode='22023'; end if;
    insert into public."WMS_Items"("WMSItem_CustomerOrgID","WMSItem_DefaultFacilityID","WMSItem_SKU","WMSItem_Description","WMSItem_BaseUOMCode","WMSItem_CommodityDescription","WMSItem_HSCode","WMSItem_CountryOfOriginCode","WMSItem_LengthM","WMSItem_WidthM","WMSItem_HeightM","WMSItem_NetWeightKG","WMSItem_GrossWeightKG","WMSItem_TemperatureMinC","WMSItem_TemperatureMaxC","WMSItem_IsDangerousGoods","WMSItem_IsExciseGoods","WMSItem_IsHighValue","WMSItem_RequiresLot","WMSItem_RequiresSerial","WMSItem_RequiresExpiry")
      values(org_id,target_facility_id,btrim(product_sku),btrim(product_description),upper(btrim(product_uom)),payload->>'commodityDescription',payload->>'hsCode',payload->>'countryOfOriginCode',(payload->>'lengthM')::numeric,(payload->>'widthM')::numeric,(payload->>'heightM')::numeric,(payload->>'netWeightKg')::numeric,(payload->>'grossWeightKg')::numeric,(payload->>'temperatureMinC')::numeric,(payload->>'temperatureMaxC')::numeric,coalesce((payload->>'isDangerousGoods')::boolean,false),coalesce((payload->>'isExciseGoods')::boolean,false),coalesce((payload->>'isHighValue')::boolean,false),coalesce((payload->>'requiresLot')::boolean,false),coalesce((payload->>'requiresSerial')::boolean,false),coalesce((payload->>'requiresExpiry')::boolean,false)) returning * into item;
  else
    select i.* into item from public."WMS_Items" i
      join public."WMS_ItemFacilityAssignments" a on a."WMSItemFacility_ItemID"=i."WMSItem_ID"
        and a."WMSItemFacility_FacilityID"=target_facility_id and a."WMSItemFacility_IsActive"
      where i."WMSItem_ID"=target_item_id and i."WMSItem_CustomerOrgID"=org_id and not i."WMSItem_IsDeleted" for update of i;
    if not found then raise exception 'Product unavailable' using errcode='42501'; end if;
    if expected_updated_at is null or item."WMSItem_UpdatedAt"<>expected_updated_at then
      raise exception 'Product changed; reload before renaming' using errcode='40001'; end if;
    if product_sku is not null or product_uom is not null then
      raise exception 'Renaming cannot change SKU or unit' using errcode='22023'; end if;
    previous := jsonb_build_object('description',item."WMSItem_Description");
    update public."WMS_Items" set "WMSItem_Description"=btrim(product_description),"WMSItem_UpdatedAt"=clock_timestamp()
      where "WMSItem_ID"=item."WMSItem_ID" returning * into item;
  end if;
  result := jsonb_build_object('id',item."WMSItem_ID",'facilityId',target_facility_id,
    'sku',item."WMSItem_SKU",'description',item."WMSItem_Description",'uom',item."WMSItem_BaseUOMCode",'updatedAt',item."WMSItem_UpdatedAt",'details',case when target_item_id is null then payload else '{}'::jsonb end);

  end if;
  insert into private_live_gateway.changes(connection_id,subject_id,grant_id,organisation_id,request_id,operation,input,before_value,result)
    values(p_connection_id,p_subject_id,p_grant_id,org_id,request_id,p_operation,p_input,previous,result);
  return result;
end;
$_$;


ALTER FUNCTION "public"."live_gateway_mutate"("p_key_id" "text", "p_connection_id" "text", "p_subject_id" "text", "p_grant_id" "text", "p_nonce" "uuid", "p_operation" "text", "p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."live_gateway_query"("p_key_id" "text", "p_connection_id" "text", "p_subject_id" "text", "p_grant_id" "text", "p_nonce" "uuid", "p_operation" "text", "p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare result jsonb; g private_live_gateway.customer_grants%rowtype; page_offset integer; page_size integer;
begin
  if p_operation in ('warehouse.context','warehouse.stock','warehouse.products') then
    result:=public.live_gateway_read(p_key_id,p_connection_id,p_subject_id,p_grant_id,p_nonce,p_operation,p_input);
  elsif p_operation in ('warehouse.orders','warehouse.order.detail') then
    if jsonb_typeof(p_input) is distinct from 'object' or exists(select 1 from jsonb_object_keys(p_input) k where k not in ('kind','id','offset','limit'))
      or (p_operation='warehouse.orders' and p_input ? 'id') then raise exception 'Invalid order filter' using errcode='22023'; end if;
    perform public.live_gateway_read(p_key_id,p_connection_id,p_subject_id,p_grant_id,p_nonce,'warehouse.context','{}');
    update private_live_gateway.requests set operation=p_operation where key_id=p_key_id and nonce=p_nonce;
    if coalesce(p_input->>'offset','0')!~'^\d+$' or coalesce(p_input->>'limit','50')!~'^\d+$' then raise exception 'Invalid page' using errcode='22023'; end if;
    page_offset:=coalesce(p_input->>'offset','0')::integer; page_size:=coalesce(p_input->>'limit','50')::integer;
    if p_operation='warehouse.orders' then return private_live_gateway.order_records(p_grant_id,p_input->>'kind',page_offset,page_size); end if;
    return private_live_gateway.order_detail(p_grant_id,p_input->>'kind',(p_input->>'id')::uuid,page_offset,page_size);
  else raise exception 'Unsupported operation' using errcode='22023'; end if;
  select * into g from private_live_gateway.customer_grants where id=p_grant_id;
  if p_operation='warehouse.context' then
    select jsonb_build_object('assignments',coalesce(jsonb_agg(a||jsonb_build_object('canManageProducts',g.products_enabled,'canCreateOrders',g.orders_enabled,'canCreatePurchaseOrders',g.purchase_orders_enabled)),'[]')) into result from jsonb_array_elements(result->'assignments') a;
  elsif p_operation='warehouse.products' then
    result:=jsonb_set(result,'{rows}',(select coalesce(jsonb_agg(r||jsonb_build_object('canManage',g.products_enabled,'facilityId',(select s.facility_id from private_live_gateway.scope(p_grant_id) s
      join public."WMS_ItemFacilityAssignments" a on a."WMSItemFacility_FacilityID"=s.facility_id and a."WMSItemFacility_ItemID"=(r->>'id')::uuid and a."WMSItemFacility_IsActive"
      where nullif(p_input->>'facilityId','') is null or s.facility_id=(p_input->>'facilityId')::uuid order by s.facility_id limit 1))),'[]') from jsonb_array_elements(result->'rows') r));
  elsif p_operation='warehouse.stock' then
    result:=jsonb_set(result,'{rows}',(select coalesce(jsonb_agg(r||jsonb_build_object('facilityName',f."WMSFacility_Name")),'[]') from jsonb_array_elements(result->'rows') r join public."WMS_Facilities" f on f."WMSFacility_ID"=(r->>'facilityId')::uuid));
  end if;
  return result;
end;
$_$;


ALTER FUNCTION "public"."live_gateway_query"("p_key_id" "text", "p_connection_id" "text", "p_subject_id" "text", "p_grant_id" "text", "p_nonce" "uuid", "p_operation" "text", "p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."live_gateway_read"("p_key_id" "text", "p_connection_id" "text", "p_subject_id" "text", "p_grant_id" "text", "p_nonce" "uuid", "p_operation" "text", "p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare grant_row private_live_gateway.customer_grants%rowtype; facilities uuid[]; selected uuid;
  result jsonb; page_offset integer; page_size integer;
begin
  if p_nonce is null or p_operation not in ('warehouse.context','warehouse.stock','warehouse.products') or p_operation is null
    or jsonb_typeof(p_input) is distinct from 'object' then raise exception 'Invalid request' using errcode='22023'; end if;
  perform 1 from private_live_gateway.keys k join private_live_gateway.connections c on c.id=k.connection_id
    where k.id=p_key_id and c.id=p_connection_id and c.enabled and k.enabled and (k.expires_at is null or k.expires_at>now()) for share of k,c;
  if not found then raise exception 'Connection denied' using errcode='42501'; end if;
  select * into grant_row from private_live_gateway.customer_grants g
    where g.id=p_grant_id and g.connection_id=p_connection_id and g.subject_id=p_subject_id and g.enabled for share;
  if not found then raise exception 'Customer grant denied' using errcode='42501'; end if;
  if exists(select 1 from jsonb_object_keys(p_input) k where k not in ('facilityId','offset','limit'))
    or (p_operation='warehouse.context' and p_input<>'{}'::jsonb) then raise exception 'Unsupported filter' using errcode='22023'; end if;
  if coalesce(p_input->>'offset','0')!~'^\d+$' or coalesce(p_input->>'limit','50')!~'^\d+$' then raise exception 'Invalid page' using errcode='22023'; end if;
  page_offset:=(coalesce(p_input->>'offset','0'))::integer; page_size:=(coalesce(p_input->>'limit','50'))::integer;
  if page_offset<0 or page_offset>100000 or page_size<1 or page_size>100 then raise exception 'Invalid page' using errcode='22023'; end if;
  selected:=nullif(p_input->>'facilityId','')::uuid;
  select coalesce(array_agg(f."WMSFacility_ID"),'{}') into facilities
    from public."WMS_CustomerFacilityAccess" a join public."WMS_Facilities" f on f."WMSFacility_ID"=a."WMSCustomerFacilityAccess_FacilityID"
    where a."WMSCustomerFacilityAccess_CustomerOrgID"=grant_row.organisation_id and a."WMSCustomerFacilityAccess_IsActive"
      and f."WMSFacility_ID"=any(grant_row.facility_ids) and f."WMSFacility_IsActive" and not f."WMSFacility_IsDeleted";
  if selected is not null and not selected=any(facilities) then raise exception 'Warehouse denied' using errcode='42501'; end if;
  insert into private_live_gateway.requests(key_id,nonce,connection_id,subject_id,grant_id,operation)
    values(p_key_id,p_nonce,p_connection_id,p_subject_id,p_grant_id,p_operation);
  if p_operation='warehouse.context' then
    select jsonb_build_object('assignments',coalesce(jsonb_agg(jsonb_build_object('customerName',(select o."Org_Name" from public."Org_Master" o where o."Org_id"=grant_row.organisation_id),'facilityId',f."WMSFacility_ID",'facilityCode',f."WMSFacility_Code",'facilityName',f."WMSFacility_Name") order by f."WMSFacility_Name",f."WMSFacility_ID"),'[]'::jsonb)) into result
    from public."WMS_Facilities" f where f."WMSFacility_ID"=any(facilities);
  else
    with records as (
      select b."WMSBalance_ID" as id,i."WMSItem_SKU"::text as sku,jsonb_build_object('id',b."WMSBalance_ID",'itemId',i."WMSItem_ID",'sku',i."WMSItem_SKU",'description',i."WMSItem_Description",
        'facilityId',b."WMSBalance_FacilityID",'uom',b."WMSBalance_UOMCode",'onHand',b."WMSBalance_OnHandQuantity",'available',b."WMSBalance_AvailableQuantity",
        'held',b."WMSBalance_HeldQuantity",'reserved',b."WMSBalance_ReservedQuantity",'allocated',b."WMSBalance_AllocatedQuantity",'updatedAt',b."WMSBalance_UpdatedAt") as value
      from public."WMS_InventoryBalances" b join public."WMS_Items" i on i."WMSItem_ID"=b."WMSBalance_ItemID" and i."WMSItem_CustomerOrgID"=grant_row.organisation_id and not i."WMSItem_IsDeleted"
      where p_operation='warehouse.stock' and b."WMSBalance_CustomerOrgID"=grant_row.organisation_id and b."WMSBalance_FacilityID"=any(facilities) and (selected is null or b."WMSBalance_FacilityID"=selected)
      union all
      select i."WMSItem_ID",i."WMSItem_SKU",jsonb_build_object('id',i."WMSItem_ID",'sku',i."WMSItem_SKU",'description',i."WMSItem_Description",'uom',i."WMSItem_BaseUOMCode",'active',i."WMSItem_IsActive",'updatedAt',i."WMSItem_UpdatedAt")
      from public."WMS_Items" i where p_operation='warehouse.products' and i."WMSItem_CustomerOrgID"=grant_row.organisation_id and not i."WMSItem_IsDeleted"
        and exists(select 1 from public."WMS_ItemFacilityAssignments" a where a."WMSItemFacility_ItemID"=i."WMSItem_ID" and a."WMSItemFacility_IsActive" and a."WMSItemFacility_FacilityID"=any(facilities) and (selected is null or a."WMSItemFacility_FacilityID"=selected))
    ), page as(select * from records order by sku,id limit page_size+1 offset page_offset), numbered as(select *,row_number() over(order by sku,id) as n from page)
    select jsonb_build_object('rows',coalesce(jsonb_agg(value order by n) filter(where n<=page_size),'[]'::jsonb),'hasMore',count(*)>page_size,'offset',page_offset) into result from numbered;
  end if;
  return result;
end;
$_$;


