CREATE OR REPLACE FUNCTION "public"."multideck_booking_register_page"("p_search" "text" DEFAULT NULL::"text", "p_scope" "text" DEFAULT 'All Jobs'::"text", "p_operator_code" "text" DEFAULT NULL::"text", "p_direction" "text" DEFAULT NULL::"text", "p_mode" "text" DEFAULT NULL::"text", "p_shipment_type" "text" DEFAULT NULL::"text", "p_filter_query" "jsonb" DEFAULT NULL::"jsonb", "p_sort" "text" DEFAULT 'customerCargo'::"text", "p_sort_direction" "text" DEFAULT 'asc'::"text", "p_limit" integer DEFAULT 10, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  v_limit integer := greatest(1, least(coalesce(p_limit, 10), 50));
  v_offset integer := greatest(0, coalesce(p_offset, 0));
  v_search text := nullif(btrim(p_search), '');
  v_scope text := case when p_scope in ('All Jobs', 'My Jobs', 'Staged Jobs') then p_scope else 'All Jobs' end;
  v_direction text := nullif(btrim(p_direction), '');
  v_mode text := nullif(btrim(p_mode), '');
  v_shipment_type text := nullif(btrim(p_shipment_type), '');
  v_sort_direction text := case when lower(p_sort_direction) = 'desc' then 'desc' else 'asc' end;
  v_sort text := case when p_sort in (
    'status', 'trackingStatus', 'booking', 'customerCargo', 'mode', 'movement', 'schedule', 'nextAction',
    'ownerActivity', 'progress', 'value', 'customerReference', 'supplierReference', 'invoice'
  ) then p_sort else 'customerCargo' end;
  v_result jsonb;
begin
  if auth.uid() is null then raise exception 'Authentication required.' using errcode = '42501'; end if;

  with base as materialized (
    select
      booking."Job_ID", booking."Lifecycle_Status",
      booking."Booking_Reference",
      booking."Customer_Name",
      booking."Route",
      booking."Carrier",
      booking."Equipment",
      booking."Mode",
      booking."Direction",
      booking."Shipment_Type",
      booking."Value_Display",
      booking."Eta_Display",
      booking."Time_Display",
      booking."Status",
      booking."Progress",
      booking."Owner_Code",
      booking."Tone",
      booking."Invoice_Reference",
      booking."Job_Reference",
      booking."Customer_Reference",
      booking."Supplier_Reference",
      booking."Origin",
      booking."Destination",
      booking."Vessel",
      booking."Departure_Date",
      booking."Arrival_Date",
      booking."Vin",
      booking."Is_Favourite",
      booking."Custom_Fields",
      booking."Updated_At",
      booking."Departure_At",
      booking."Arrival_At",
      concat_ws(' ',
        booking."Booking_Reference", booking."Customer_Name", booking."Route", booking."Carrier", booking."Equipment",
        booking."Mode", booking."Value_Display", booking."Eta_Display", booking."Time_Display", booking."Status",
        booking."Owner_Code", booking."Invoice_Reference", booking."Job_Reference", booking."Customer_Reference",
        booking."Supplier_Reference", booking."Origin", booking."Destination", booking."Vessel", booking."Vin",
        booking."Custom_Fields"::text, case when booking."Lifecycle_Status" in ('draft','provisional') then 'Provisional' when booking."Lifecycle_Status" in ('complete','completed') then 'Complete' when booking."Lifecycle_Status" in ('cancelled','archived') then booking."Lifecycle_Status" else 'In progress' end
      ) as search_text,
      jsonb_build_object(
        'any', jsonb_build_array(
          booking."Booking_Reference", booking."Customer_Name", booking."Route", booking."Carrier", booking."Equipment",
          booking."Mode", booking."Value_Display", booking."Eta_Display", booking."Time_Display", booking."Status",
          booking."Owner_Code", booking."Invoice_Reference", booking."Job_Reference", booking."Customer_Reference",
          booking."Supplier_Reference", booking."Origin", booking."Destination", booking."Vessel", booking."Vin"
        ) || custom.field_values,
        'invoice', jsonb_build_array(booking."Invoice_Reference"),
        'jobRef', jsonb_build_array(booking."Job_Reference"),
        'customerRef', jsonb_build_array(booking."Customer_Reference"),
        'supplierRef', jsonb_build_array(booking."Supplier_Reference"),
        'date', jsonb_build_array(booking."Departure_Date", booking."Arrival_Date"),
        'destination', jsonb_build_array(booking."Destination", booking."Route"),
        'origin', jsonb_build_array(booking."Origin", booking."Route"),
        'vessel', jsonb_build_array(booking."Vessel", booking."Carrier"),
        'departure', jsonb_build_array(booking."Departure_Date"),
        'arrival', jsonb_build_array(booking."Arrival_Date"),
        'vin', jsonb_build_array(booking."Vin"),
        'customFields', custom.field_values
      ) as filter_fields,
      coalesce(exception_detail.value, case when booking."Status" = 'Exception' then 'Action required' when booking."Status" = 'Delayed' then 'Schedule changed' else 'No open exception' end) as exception_summary,
      case
        when booking."Status" = 'Exception' then coalesce(exception_detail.value, 'Action required')
        when booking."Status" = 'Delayed' then 'Review schedule and update customer'
        when booking."Progress" >= 100 then 'Complete'
        when booking."Progress" < 25 then 'Confirm booking and departure'
        when booking."Progress" < 75 then 'Monitor movement'
        else 'Prepare arrival and delivery'
      end as next_action,
      case
        when regexp_replace(booking."Value_Display", '[^0-9.-]', '', 'g') ~ '^-?[0-9]+(\.[0-9]+)?$'
          then regexp_replace(booking."Value_Display", '[^0-9.-]', '', 'g')::numeric
      end as numeric_value
    from public."App_Live_Bookings" booking
    left join lateral (
      select coalesce(jsonb_agg(value), '[]'::jsonb) as field_values
      from (
        select field ->> 'label' as value from jsonb_array_elements(coalesce(booking."Custom_Fields", '[]'::jsonb)) field
        union all
        select field ->> 'value' from jsonb_array_elements(coalesce(booking."Custom_Fields", '[]'::jsonb)) field
        union all
        select concat_ws(' ', field ->> 'label', field ->> 'value') from jsonb_array_elements(coalesce(booking."Custom_Fields", '[]'::jsonb)) field
      ) items
    ) custom on true
    left join lateral (
      select field ->> 'value' as value
      from jsonb_array_elements(coalesce(booking."Custom_Fields", '[]'::jsonb)) field
      where lower(field ->> 'label') in ('exception', 'delay reason', 'licence', 'blocker', 'tracking')
        and nullif(btrim(field ->> 'value'), '') is not null
      limit 1
    ) exception_detail on true
  ), scoped as materialized (
    select *
    from base
    where (v_scope <> 'My Jobs' or "Owner_Code" = coalesce(nullif(btrim(p_operator_code), ''), ''))
      and (v_scope <> 'Staged Jobs' or "Progress" < 25)
  ), filtered as materialized (
    select *
    from scoped
    where (v_direction is null or "Direction" = v_direction)
      and (v_mode is null or "Mode" = v_mode)
      and (v_shipment_type is null or "Shipment_Type" = v_shipment_type)
      and (v_search is null or strpos(lower(search_text), lower(v_search)) > 0)
      and (p_filter_query is null or public.multideck_register_filter_matches(filter_fields, p_filter_query))
  ), ranked as (
    select *, row_number() over (
      order by
        case when v_sort_direction = 'asc' then case v_sort
          when 'trackingStatus' then lower("Status") when 'status' then lower(case when "Lifecycle_Status" in ('draft','provisional') then 'Provisional' when "Lifecycle_Status" in ('complete','completed','closed') then 'Complete' when "Lifecycle_Status" in ('open','booked','in_transit','arrived','delivered','ready_for_invoice','in_progress') then 'In progress' else "Lifecycle_Status" end)
          when 'booking' then lower("Booking_Reference")
          when 'customerCargo' then lower("Customer_Name")
          when 'mode' then lower("Mode")
          when 'movement' then lower(concat_ws(' ', "Origin", "Destination", "Carrier"))
          when 'nextAction' then lower(next_action)
          when 'customerReference' then lower("Customer_Reference")
          when 'supplierReference' then lower("Supplier_Reference")
          when 'invoice' then lower("Invoice_Reference")
        end end asc nulls last,
        case when v_sort_direction = 'desc' then case v_sort
          when 'trackingStatus' then lower("Status") when 'status' then lower(case when "Lifecycle_Status" in ('draft','provisional') then 'Provisional' when "Lifecycle_Status" in ('complete','completed','closed') then 'Complete' when "Lifecycle_Status" in ('open','booked','in_transit','arrived','delivered','ready_for_invoice','in_progress') then 'In progress' else "Lifecycle_Status" end)
          when 'booking' then lower("Booking_Reference")
          when 'customerCargo' then lower("Customer_Name")
          when 'mode' then lower("Mode")
          when 'movement' then lower(concat_ws(' ', "Origin", "Destination", "Carrier"))
          when 'nextAction' then lower(next_action)
          when 'customerReference' then lower("Customer_Reference")
          when 'supplierReference' then lower("Supplier_Reference")
          when 'invoice' then lower("Invoice_Reference")
        end end desc nulls last,
        case when v_sort_direction = 'asc' then case v_sort
          when 'schedule' then "Arrival_Date"::timestamptz
          when 'ownerActivity' then "Updated_At"
        end end asc nulls last,
        case when v_sort_direction = 'desc' then case v_sort
          when 'schedule' then "Arrival_Date"::timestamptz
          when 'ownerActivity' then "Updated_At"
        end end desc nulls last,
        case when v_sort_direction = 'asc' then case v_sort when 'progress' then "Progress" when 'value' then numeric_value end end asc nulls last,
        case when v_sort_direction = 'desc' then case v_sort when 'progress' then "Progress" when 'value' then numeric_value end end desc nulls last,
        lower("Customer_Name"), "Booking_Reference"
    ) as ordinal
    from filtered
  ), page as (
    select * from ranked where ordinal > v_offset and ordinal <= v_offset + v_limit
  )
  select jsonb_build_object(
    'rows', coalesce((select jsonb_agg(
      to_jsonb(item) - 'search_text' - 'filter_fields' - 'exception_summary' - 'next_action' - 'numeric_value' - 'ordinal'
      order by item.ordinal
    ) from page item), '[]'::jsonb),
    'total', (select count(*) from filtered),
    'summary', coalesce((select jsonb_build_object(
      'active', count(*) filter (where "Progress" < 100),
      'inTransit', count(*) filter (where "Progress" >= 25 and "Progress" < 75),
      'atDestination', count(*) filter (where "Progress" >= 75 and "Progress" < 100),
      'exceptions', count(*) filter (where "Status" = 'Exception'),
      'complete', count(*) filter (where "Progress" >= 100),
      'total', count(*)
    ) from scoped), '{}'::jsonb)
  ) into v_result;

  return v_result;
end;
$_$;


ALTER FUNCTION "public"."multideck_booking_register_page"("p_search" "text", "p_scope" "text", "p_operator_code" "text", "p_direction" "text", "p_mode" "text", "p_shipment_type" "text", "p_filter_query" "jsonb", "p_sort" "text", "p_sort_direction" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."multideck_booking_register_page"("p_search" "text", "p_scope" "text", "p_operator_code" "text", "p_direction" "text", "p_mode" "text", "p_shipment_type" "text", "p_filter_query" "jsonb", "p_sort" "text", "p_sort_direction" "text", "p_limit" integer, "p_offset" integer) IS 'RLS-preserving, maximum-50-row Bookings register read with exact filtered total and scope summary.';



CREATE TABLE IF NOT EXISTS "public"."CAL_Deliveries" (
    "CALDelivery_ID" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "CALDelivery_CompanyID" "uuid" NOT NULL,
    "CALDelivery_MeetingID" "uuid",
    "CALDelivery_ParticipantID" "uuid",
    "CALDelivery_KindCode" character varying(40) NOT NULL,
    "CALDelivery_SendAfter" timestamp with time zone DEFAULT "now"() NOT NULL,
    "CALDelivery_StatusCode" character varying(16) DEFAULT 'pending'::character varying NOT NULL,
    "CALDelivery_IdempotencyKey" character varying(240) NOT NULL,
    "CALDelivery_Attempts" integer DEFAULT 0 NOT NULL,
    "CALDelivery_LeaseUntil" timestamp with time zone,
    "CALDelivery_ProviderID" character varying(500),
    "CALDelivery_RenderedJSON" "jsonb",
    "CALDelivery_LastError" character varying(500),
    "CALDelivery_CreatedAt" timestamp with time zone DEFAULT "now"() NOT NULL,
    "CALDelivery_CompletedAt" timestamp with time zone,
    CONSTRAINT "CK_CAL_Deliveries_kind" CHECK ((("CALDelivery_KindCode")::"text" = ANY ((ARRAY['provider_create'::character varying, 'provider_update'::character varying, 'provider_cancel'::character varying, 'crm_link'::character varying, 'booking_verification'::character varying, 'management'::character varying, 'standalone_confirmation'::character varying, 'reminder'::character varying, 'rescheduled'::character varying, 'cancelled'::character varying, 'group_reschedule_request'::character varying, 'group_reschedule_outcome'::character varying, 'external_event_update'::character varying, 'external_event_cancel'::character varying, 'external_event_rsvp'::character varying])::"text"[]))),
    CONSTRAINT "CK_CAL_Deliveries_rendered" CHECK ((("CALDelivery_RenderedJSON" IS NULL) OR ("jsonb_typeof"("CALDelivery_RenderedJSON") = 'object'::"text"))),
    CONSTRAINT "CK_CAL_Deliveries_status" CHECK ((("CALDelivery_StatusCode")::"text" = ANY ((ARRAY['pending'::character varying, 'leased'::character varying, 'delivered'::character varying, 'cancelled'::character varying, 'failed'::character varying])::"text"[])))
);


ALTER TABLE "public"."CAL_Deliveries" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_calendar_claim_deliveries"("p_limit" integer DEFAULT 10) RETURNS SETOF "public"."CAL_Deliveries"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  return query
  with due as (
    select delivery."CALDelivery_ID"
    from public."CAL_Deliveries" delivery
    where delivery."CALDelivery_StatusCode" in ('pending','leased')
      and delivery."CALDelivery_SendAfter" <= now()
      and (delivery."CALDelivery_LeaseUntil" is null or delivery."CALDelivery_LeaseUntil" < now())
    order by delivery."CALDelivery_SendAfter", delivery."CALDelivery_CreatedAt"
    for update skip locked
    limit greatest(1, least(coalesce(p_limit,10),50))
  )
  update public."CAL_Deliveries" delivery
  set "CALDelivery_StatusCode"='leased',
      "CALDelivery_LeaseUntil"=now()+interval '2 minutes',
      "CALDelivery_Attempts"="CALDelivery_Attempts"+1
  from due
  where delivery."CALDelivery_ID"=due."CALDelivery_ID"
  returning delivery.*;
end;
$$;


ALTER FUNCTION "public"."multideck_calendar_claim_deliveries"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_calendar_configure_worker_schedule"() RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_endpoint text; v_secret text; v_job_id bigint;
begin
  select secret.decrypted_secret into v_endpoint from vault.decrypted_secrets secret where secret.name='multideck_calendar_worker_endpoint' limit 1;
  select secret.decrypted_secret into v_secret from vault.decrypted_secrets secret where secret.name='multideck_calendar_worker_secret' limit 1;
  if nullif(btrim(v_endpoint),'') is null or btrim(v_endpoint) !~ '^https://[a-z0-9]+\.supabase\.co/functions/v1/calendar-worker$' then
    raise exception 'Calendar worker endpoint is missing or is not an exact tenant Supabase Function URL.' using errcode='55000';
  end if;
  if nullif(btrim(v_secret),'') is null or length(v_secret) < 32 then
    raise exception 'Calendar worker secret is missing or invalid.' using errcode='55000';
  end if;
  create extension if not exists pg_cron;
  create extension if not exists pg_net;
  for v_job_id in select jobid from cron.job where jobname='multideck-calendar-worker' loop perform cron.unschedule(v_job_id); end loop;
  perform cron.schedule('multideck-calendar-worker','* * * * *',$schedule$
    select net.http_post(
      url := (select btrim(secret.decrypted_secret) from vault.decrypted_secrets secret where secret.name='multideck_calendar_worker_endpoint' limit 1),
      headers := jsonb_build_object('Content-Type','application/json','x-multideck-calendar-worker',(select secret.decrypted_secret from vault.decrypted_secrets secret where secret.name='multideck_calendar_worker_secret' limit 1)),
      body := jsonb_build_object('source','cron','requestedAt',now()),
      timeout_milliseconds := 55000
    );
  $schedule$);
  return true;
end;
$_$;


ALTER FUNCTION "public"."multideck_calendar_configure_worker_schedule"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_calendar_consume_public_rate_limit"("p_company_id" "uuid", "p_action" "text", "p_subject_hash" "text", "p_window_started_at" timestamp with time zone) RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare v_count integer;
begin
  if p_company_id is null or p_action not in ('hold','verify','resend','manage')
     or p_subject_hash !~ '^[0-9a-f]{64}$' or p_window_started_at is null then
    raise exception 'The public Calendar rate-limit key is invalid.' using errcode='22023';
  end if;
  insert into public."CAL_PublicRateLimits" (
    "CALRateLimit_CompanyID","CALRateLimit_ActionCode","CALRateLimit_SubjectHash",
    "CALRateLimit_WindowStartedAt","CALRateLimit_AttemptCount","CALRateLimit_UpdatedAt"
  ) values (p_company_id,p_action,p_subject_hash,p_window_started_at,1,now())
  on conflict ("CALRateLimit_CompanyID","CALRateLimit_ActionCode","CALRateLimit_SubjectHash","CALRateLimit_WindowStartedAt")
  do update set
    "CALRateLimit_AttemptCount"=least(10000,public."CAL_PublicRateLimits"."CALRateLimit_AttemptCount"+1),
    "CALRateLimit_UpdatedAt"=now()
  returning "CALRateLimit_AttemptCount" into v_count;
  return v_count;
end;
$_$;


ALTER FUNCTION "public"."multideck_calendar_consume_public_rate_limit"("p_company_id" "uuid", "p_action" "text", "p_subject_hash" "text", "p_window_started_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_calendar_expire_holds"() RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_count integer;
begin
  update public."CAL_Reservations" reservation
  set "CALReservation_StatusCode"='expired'
  where reservation."CALReservation_SourceCode"='hold'
    and reservation."CALReservation_StatusCode"='active'
    and reservation."CALReservation_ExpiresAt" < now();
  get diagnostics v_count = row_count;
  delete from public."CAL_PublicRateLimits" where "CALRateLimit_WindowStartedAt" < now()-interval '24 hours';
  delete from public."CAL_OAuthStates" where "CALOAuthState_ExpiresAt" < now()-interval '24 hours';
  delete from public."CAL_WebhookReceipts" where "CALWebhookReceipt_ReceivedAt" < now()-interval '30 days';
  return v_count;
end;
$$;


ALTER FUNCTION "public"."multideck_calendar_expire_holds"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_calendar_finalise_verified_hold"("p_hold_id" "uuid", "p_booking_link_id" "uuid", "p_verification_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  v_hold public."CAL_BookingHolds"%rowtype;
  v_link public."CAL_BookingLinks"%rowtype;
  v_reservation public."CAL_Reservations"%rowtype;
  v_meeting public."CAL_Meetings"%rowtype;
  v_status text;
  v_connection_provider text;
  v_host uuid;
  v_cohost record;
begin
  if p_hold_id is null or p_booking_link_id is null or p_verification_hash !~ '^[0-9a-f]{64}$' then
    raise exception 'The verified booking request is invalid.' using errcode='22023';
  end if;

  select hold.* into v_hold
  from public."CAL_BookingHolds" hold
  where hold."CALBookingHold_ID"=p_hold_id
    and hold."CALBookingHold_BookingLinkID"=p_booking_link_id
  for update;
  if not found then
    raise exception 'That booking hold is not available.' using errcode='P0002';
  end if;
  if v_hold."CALBookingHold_VerificationHash" <> p_verification_hash then
    raise exception 'The verification code does not match.' using errcode='22023';
  end if;

  if v_hold."CALBookingHold_MeetingID" is not null then
    select meeting.* into v_meeting
    from public."CAL_Meetings" meeting
    where meeting."CALMeeting_ID"=v_hold."CALBookingHold_MeetingID";
    if not found then
      raise exception 'The verified booking meeting is missing.' using errcode='55000';
    end if;
    return to_jsonb(v_meeting);
  end if;

  if v_hold."CALBookingHold_ExpiresAt" <= now() then
    raise exception 'That booking hold has expired.' using errcode='55000';
  end if;

  select link.* into v_link
  from public."CAL_BookingLinks" link
  where link."CALBookingLink_ID"=p_booking_link_id
    and link."CALBookingLink_CompanyID"=v_hold."CALBookingHold_CompanyID"
    and link."CALBookingLink_StatusCode"='active'
  for share;
  if not found then
    raise exception 'That booking link is no longer active.' using errcode='55000';
  end if;

  v_host := coalesce(v_hold."CALBookingHold_HostUserID", v_link."CALBookingLink_OwnerUserID");
  if v_host <> v_link."CALBookingLink_OwnerUserID" and not exists (
    select 1 from public."CAL_BookingLinkHosts" host
    where host."CALBookingLinkHost_BookingLinkID"=v_link."CALBookingLink_ID" and host."CALBookingLinkHost_UserID"=v_host
  ) then
    raise exception 'The assigned host is no longer part of this booking link.' using errcode='55000';
  end if;

  select reservation.* into v_reservation
  from public."CAL_Reservations" reservation
  where reservation."CALReservation_ID"=v_hold."CALBookingHold_ReservationID"
    and reservation."CALReservation_CompanyID"=v_hold."CALBookingHold_CompanyID"
    and reservation."CALReservation_OwnerUserID"=v_host
    and reservation."CALReservation_SourceCode"='hold'
    and reservation."CALReservation_SourceID"=p_hold_id
    and reservation."CALReservation_StatusCode"='active'
    and reservation."CALReservation_ExpiresAt">now()
  for update;
  if not found then
    raise exception 'That booking time is no longer reserved.' using errcode='55000';
  end if;

  if v_link."CALBookingLink_ProviderCode" in ('google_meet','microsoft_teams','zoom') then
    v_connection_provider := case v_link."CALBookingLink_ProviderCode"
      when 'google_meet' then 'google'
      when 'microsoft_teams' then 'microsoft'
      else 'zoom'
    end;
    if not exists (
      select 1
      from public."CAL_ProviderConnections" connection
      where connection."CALConnection_CompanyID"=v_link."CALBookingLink_CompanyID"
        and connection."CALConnection_UserID"=v_host
        and connection."CALConnection_ProviderCode"=v_connection_provider
        and connection."CALConnection_StatusCode"='connected'
    ) then
      raise exception 'The selected meeting provider is not connected.' using errcode='55000';
    end if;
    v_status := 'provisioning';
  else
    v_status := 'confirmed';
  end if;

  insert into public."CAL_Meetings" (
    "CALMeeting_CompanyID","CALMeeting_OrganiserUserID","CALMeeting_ReservationID",
    "CALMeeting_Title","CALMeeting_Agenda","CALMeeting_StartAt","CALMeeting_EndAt","CALMeeting_TimeZone",
    "CALMeeting_StatusCode","CALMeeting_ProviderCode","CALMeeting_Location","CALMeeting_BookingLinkID",
    "CALMeeting_SourceCode","CALMeeting_CreatedBy","CALMeeting_UpdatedBy"
  ) values (
    v_link."CALBookingLink_CompanyID",v_host,v_reservation."CALReservation_ID",
    v_link."CALBookingLink_Title",coalesce(nullif(btrim(v_hold."CALBookingHold_AnswersJSON"->>'notes'),''),v_link."CALBookingLink_Description"),
    v_reservation."CALReservation_StartAt",v_reservation."CALReservation_EndAt",v_hold."CALBookingHold_TimeZone",
    v_status,v_link."CALBookingLink_ProviderCode",v_link."CALBookingLink_Location",v_link."CALBookingLink_ID",
    'booking_link',v_host,v_host
  ) on conflict ("CALMeeting_ReservationID") do nothing
  returning * into v_meeting;

  if v_meeting."CALMeeting_ID" is null then
    select meeting.* into v_meeting
    from public."CAL_Meetings" meeting
    where meeting."CALMeeting_ReservationID"=v_reservation."CALReservation_ID";
    if not found then
      raise exception 'The booking meeting could not be secured.' using errcode='55000';
    end if;
  end if;

  if v_link."CALBookingLink_KindCode"='collective' then
    for v_cohost in
      select profile."User_ID", profile."User_Email", concat_ws(' ', profile."User_Firstname", profile."User_Lastname") as full_name
      from public."CAL_BookingLinkHosts" host
      join public."cmp_Users" profile on profile."User_ID"=host."CALBookingLinkHost_UserID"
      where host."CALBookingLinkHost_BookingLinkID"=v_link."CALBookingLink_ID"
        and host."CALBookingLinkHost_UserID"<>v_host
        and profile."User_Email" is not null
      order by host."CALBookingLinkHost_SortOrder"
    loop
      insert into public."CAL_MeetingParticipants" (
        "CALParticipant_MeetingID","CALParticipant_UserID","CALParticipant_Name","CALParticipant_Email",
        "CALParticipant_RoleCode","CALParticipant_ResponseCode","CALParticipant_IsExternal"
      ) values (
        v_meeting."CALMeeting_ID", v_cohost."User_ID", left(coalesce(nullif(btrim(v_cohost.full_name),''), split_part(v_cohost."User_Email",'@',1)),240),
        lower(left(v_cohost."User_Email",320)), 'attendee', 'accepted', false
      ) on conflict ("CALParticipant_MeetingID","CALParticipant_Email") do nothing;
    end loop;
  end if;

  update public."CAL_Reservations"
  set "CALReservation_SourceCode"='meeting',
      "CALReservation_SourceID"=v_meeting."CALMeeting_ID",
      "CALReservation_ExpiresAt"=null
  where "CALReservation_ID"=v_reservation."CALReservation_ID";

  update public."CAL_BookingHolds"
  set "CALBookingHold_VerifiedAt"=coalesce("CALBookingHold_VerifiedAt",now()),
      "CALBookingHold_MeetingID"=v_meeting."CALMeeting_ID"
  where "CALBookingHold_ID"=p_hold_id;

  return to_jsonb(v_meeting);
end;
$_$;


ALTER FUNCTION "public"."multideck_calendar_finalise_verified_hold"("p_hold_id" "uuid", "p_booking_link_id" "uuid", "p_verification_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_calendar_job_milestones"("p_company_id" "uuid", "p_start" timestamp with time zone, "p_end" timestamp with time zone) RETURNS TABLE("job_id" "uuid", "job_number" integer, "milestone_kind" "text", "milestone_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  with permitted_jobs as (
    select
      job."Job_ID" as job_id,
      job."Job_Number" as job_number,
      job."Job_ReadyDate" as ready_date,
      job."Job_RequiredDeliveryDate" as required_delivery_date,
      job."Job_PredictedDeliveryAt" as predicted_delivery_at,
      route.departure_at,
      route.arrival_at
    from public."Job_Header" job
    join public."cmp_Offices" office
      on office."Office_ID" = coalesce(job."Job_OrgOfficeID", job."Job_OfficeID")
     and office."Company_ID" = p_company_id
    left join lateral (
      select
        coalesce(leg."JobRoute_EstimatedDepartureAt", leg."JobRoute_PlannedDepartureAt") as departure_at,
        coalesce(leg."JobRoute_EstimatedArrivalAt", leg."JobRoute_PlannedArrivalAt") as arrival_at
      from public."Job_Routing" leg
      where leg."Job_ID" = job."Job_ID"
      order by leg."JobRoute_IsMainCarriage" desc, leg."JobRoute_OrderNo" nulls last, leg."JobRoute_ID"
      limit 1
    ) route on true
    where not coalesce(job."Job_IsDeleted", false)
  ), milestones as (
    select job_id, job_number, 'collection'::text as milestone_kind,
      (ready_date + time '12:00') at time zone 'UTC' as milestone_at
    from permitted_jobs where ready_date is not null
    union all
    select job_id, job_number, 'departure', departure_at
    from permitted_jobs where departure_at is not null
    union all
    select job_id, job_number, 'arrival', coalesce(arrival_at, predicted_delivery_at)
    from permitted_jobs where coalesce(arrival_at, predicted_delivery_at) is not null
    union all
    select job_id, job_number, 'delivery',
      (required_delivery_date + time '12:00') at time zone 'UTC'
    from permitted_jobs where required_delivery_date is not null
  )
  select job_id, job_number, milestone_kind, milestone_at
  from milestones
  where milestone_at >= p_start and milestone_at < p_end
  order by milestone_at, job_number, milestone_kind;
$$;


ALTER FUNCTION "public"."multideck_calendar_job_milestones"("p_company_id" "uuid", "p_start" timestamp with time zone, "p_end" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."multideck_calendar_job_milestones"("p_company_id" "uuid", "p_start" timestamp with time zone, "p_end" timestamp with time zone) IS 'Returns company-scoped collection, departure, arrival and delivery ribbons for the bounded Calendar range. Service-role only; the caller must also enforce Bookings.Read.';



CREATE OR REPLACE FUNCTION "public"."multideck_calendar_match_or_create_booking_lead"("p_meeting_id" "uuid", "p_organiser_user_id" "uuid", "p_booking_link_id" "uuid", "p_attendee_name" "text", "p_attendee_email" "text", "p_attendee_phone" "text", "p_company_entered" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_email text := lower(nullif(btrim(p_attendee_email), ''));
  v_lead_id uuid;
  v_meeting public."CAL_Meetings"%rowtype;
begin
  if v_email is null or position('@' in v_email) <= 1 then
    raise exception 'A valid attendee email is required.' using errcode = '22023';
  end if;

  select meeting.* into v_meeting
  from public."CAL_Meetings" meeting
  where meeting."CALMeeting_ID" = p_meeting_id
    and meeting."CALMeeting_OrganiserUserID" = p_organiser_user_id
    and meeting."CALMeeting_BookingLinkID" = p_booking_link_id;
  if not found then
    raise exception 'That booking meeting is not available for CRM linking.' using errcode = '42501';
  end if;

  -- One workspace-wide lock per normalised email keeps simultaneous booking
  -- links from creating duplicate leads before the second request can re-read.
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('multideck-booking-lead:' || v_email, 0));

  select lead."CRMLead_ID" into v_lead_id
  from public."CRM_Leads" lead
  where not lead."CRMLead_IsDeleted"
    and lower(btrim(lead."CRMLead_Email")) = v_email
  order by lead."CRMLead_CreatedAt"
  limit 1;

  if v_lead_id is null then
    insert into public."CRM_Leads" (
      "CRMLead_SourceCode", "CRMLead_StatusCode", "CRMLead_OwnerUserID",
      "CRMLead_CompanyName", "CRMLead_PersonName", "CRMLead_Email", "CRMLead_Phone",
      "CRMLead_MetadataJSON", "CRMLead_CreatedBy", "CRMLead_UpdatedBy"
    ) values (
      'booking_link', 'new', p_organiser_user_id,
      nullif(btrim(p_company_entered), ''), nullif(btrim(p_attendee_name), ''), v_email, nullif(btrim(p_attendee_phone), ''),
      jsonb_build_object(
        'bookingLinkId', p_booking_link_id,
        'companyEntered', nullif(btrim(p_company_entered), ''),
        'reviewCompany', nullif(btrim(p_company_entered), '') is not null
      ),
      p_organiser_user_id, p_organiser_user_id
    ) returning "CRMLead_ID" into v_lead_id;
  end if;

  update public."CAL_Meetings"
  set "CALMeeting_LeadID" = v_lead_id,
      "CALMeeting_UpdatedAt" = now()
  where "CALMeeting_ID" = p_meeting_id
    and "CALMeeting_LeadID" is distinct from v_lead_id;

  insert into public."CRM_Activities" (
    "CRMActivity_ActivityTypeCode", "CRMActivity_LeadID", "CRMActivity_Subject",
    "CRMActivity_Summary", "CRMActivity_ActivityAt", "CRMActivity_DurationMinutes",
    "CRMActivity_OwnerUserID", "CRMActivity_MetadataJSON",
    "CRMActivity_CreatedBy", "CRMActivity_UpdatedBy"
  ) values (
    'meeting', v_lead_id, v_meeting."CALMeeting_Title",
    'Booked through a Multideck booking link.', v_meeting."CALMeeting_StartAt",
    greatest(1, round(extract(epoch from (v_meeting."CALMeeting_EndAt" - v_meeting."CALMeeting_StartAt")) / 60)::integer),
    p_organiser_user_id,
    jsonb_build_object(
      'calendarMeetingId', p_meeting_id,
      'bookingLinkId', p_booking_link_id,
      'provider', v_meeting."CALMeeting_ProviderCode",
      'status', v_meeting."CALMeeting_StatusCode"
    ),
    p_organiser_user_id, p_organiser_user_id
  ) on conflict do nothing;

  return v_lead_id;
end;
$$;


ALTER FUNCTION "public"."multideck_calendar_match_or_create_booking_lead"("p_meeting_id" "uuid", "p_organiser_user_id" "uuid", "p_booking_link_id" "uuid", "p_attendee_name" "text", "p_attendee_email" "text", "p_attendee_phone" "text", "p_company_entered" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_calendar_record_verification_failure"("p_hold_id" "uuid", "p_booking_link_id" "uuid", "p_max_attempts" integer DEFAULT 10) RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_hold public."CAL_BookingHolds"%rowtype;
  v_attempts integer;
begin
  if p_hold_id is null or p_booking_link_id is null or p_max_attempts not between 1 and 20 then
    raise exception 'The verification-attempt request is invalid.' using errcode='22023';
  end if;

  select hold.* into v_hold
  from public."CAL_BookingHolds" hold
  where hold."CALBookingHold_ID"=p_hold_id
    and hold."CALBookingHold_BookingLinkID"=p_booking_link_id
  for update;
  if not found then
    raise exception 'That booking hold is not available.' using errcode='P0002';
  end if;

  v_attempts := least(p_max_attempts, v_hold."CALBookingHold_VerificationAttempts"+1);
  update public."CAL_BookingHolds"
  set "CALBookingHold_VerificationAttempts"=v_attempts,
      "CALBookingHold_ExpiresAt"=case when v_attempts >= p_max_attempts then least("CALBookingHold_ExpiresAt",now()) else "CALBookingHold_ExpiresAt" end
  where "CALBookingHold_ID"=p_hold_id;

  if v_attempts >= p_max_attempts and v_hold."CALBookingHold_MeetingID" is null then
    update public."CAL_Reservations"
    set "CALReservation_StatusCode"='expired'
    where "CALReservation_ID"=v_hold."CALBookingHold_ReservationID"
      and "CALReservation_StatusCode"='active';
  end if;
  return v_attempts;
end;
$$;


ALTER FUNCTION "public"."multideck_calendar_record_verification_failure"("p_hold_id" "uuid", "p_booking_link_id" "uuid", "p_max_attempts" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_contact_card_create"("p_card" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare v_context record; v_id uuid;
begin
  select * into v_context from public._multideck_crm_context();
  begin v_id := nullif(p_card->>'id', '')::uuid; exception when invalid_text_representation then v_id := null; end;
  if v_id is null then raise exception 'A card ID is required.' using errcode = '22023'; end if;
  if exists (select 1 from public."CRM_ContactCards" where "ContactCard_ID" = v_id) then
    raise exception 'This card already exists.' using errcode = '23505';
  end if;
  insert into public."CRM_ContactCards"(
    "ContactCard_ID", "Company_ID", "Owner_User_ID", "ContactCard_Slug", "ContactCard_Label",
    "ContactCard_Status", "ContactCard_ShowTenantName"
  ) values (
    v_id, v_context.company_id, coalesce(nullif(p_card->>'ownerUserId', '')::uuid, v_context.user_id),
    lower(p_card->>'slug'), coalesce(nullif(p_card->>'label', ''), 'Contact card'), 'draft',
    coalesce((p_card->>'showTenantName')::boolean, true)
  );
  return public.multideck_contact_card_save(p_card);
end;
$$;


