CREATE OR REPLACE FUNCTION "public"."multideck_contact_card_record_scan"("p_slug" "text", "p_device" "text", "p_browser" "text", "p_channel" "text", "p_country" "text", "p_region" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_card uuid;
  v_scan uuid;
  v_recent_count integer;
  v_daily_count integer;
begin
  select "ContactCard_ID" into v_card
  from public."CRM_ContactCards"
  where "ContactCard_Slug" = lower(btrim(p_slug))
    and "ContactCard_Status" = 'published'
    and "ContactCard_DeletedAt" is null
  limit 1;
  if v_card is null then return null; end if;

  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_card::text, 772));
  select
    count(*) filter (where "Scan_At" > now() - interval '10 minutes'),
    count(*) filter (where "Scan_At" > now() - interval '1 day')
  into v_recent_count, v_daily_count
  from public."CRM_ContactCardScans"
  where "ContactCard_ID" = v_card
    and "Scan_At" > now() - interval '1 day';
  if v_recent_count >= 120 or v_daily_count >= 5000 then
    raise exception 'This contact card is receiving too many requests. Try again later.' using errcode = 'P0001';
  end if;

  insert into public."CRM_ContactCardScans" (
    "ContactCard_ID", "Scan_Device", "Scan_Browser", "Scan_Channel", "Scan_Country", "Scan_Region"
  ) values (
    v_card,
    case when p_device in ('mobile', 'tablet', 'desktop') then p_device else 'desktop' end,
    left(coalesce(p_browser, 'Other'), 80),
    case when p_channel in ('direct-scan', 'shared-link', 'in-app-browser', 'unknown') then p_channel else 'unknown' end,
    left(coalesce(p_country, ''), 80),
    left(coalesce(p_region, ''), 80)
  ) returning "Scan_ID" into v_scan;
  return v_scan;
end;
$$;


ALTER FUNCTION "public"."multideck_contact_card_record_scan"("p_slug" "text", "p_device" "text", "p_browser" "text", "p_channel" "text", "p_country" "text", "p_region" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_contact_card_record_scan_v2"("p_slug" "text", "p_device" "text", "p_browser" "text", "p_channel" "text", "p_request_id" "uuid", "p_session_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_card uuid; v_scan uuid;
begin
  if p_request_id is null or p_session_id is null then
    raise exception 'Reload this contact card before continuing.' using errcode = '22023';
  end if;
  select "ContactCard_ID" into v_card from public."CRM_ContactCards"
  where "ContactCard_Slug" = lower(btrim(p_slug)) and "ContactCard_Status" = 'published' and "ContactCard_DeletedAt" is null;
  if v_card is null then return null; end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_card::text || p_request_id::text, 774));
  select "Scan_ID" into v_scan from public."CRM_ContactCardScans"
  where "ContactCard_ID" = v_card and "Scan_RequestID" = p_request_id;
  if v_scan is not null then return v_scan; end if;

  -- Reuse the existing per-card limits and publication check. Never accept
  -- invented client location; approximate geolocation is not collected here.
  v_scan := public.multideck_contact_card_record_scan(p_slug, p_device, p_browser, p_channel, '', '');
  if v_scan is not null then
    update public."CRM_ContactCardScans"
    set "Scan_RequestID" = p_request_id, "Scan_SessionID" = p_session_id
    where "Scan_ID" = v_scan;
  end if;
  return v_scan;
end;
$$;


