CREATE OR REPLACE FUNCTION "public"."multideck_crm_accessible_account_ids"("p_company_id" "uuid") RETURNS TABLE("account_id" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select candidate.account_id
  from (
    select profile."CRMAccount_OrgID" account_id
    from public."CRM_AccountProfiles" profile
    where not profile."CRMAccount_IsDeleted"
      and profile."CRMAccount_CompanyID" = p_company_id
    union
    select job."Job_Customer"
    from public."Job_Header" job
    join public."cmp_Offices" office
      on office."Office_ID" = coalesce(job."Job_OrgOfficeID", job."Job_OfficeID")
    where office."Company_ID" = p_company_id and job."Job_Customer" is not null
    union
    select quote."CusQuoteHeader_CustomerID"
    from public."CusQuote_Header" quote
    join public."cmp_Offices" office
      on office."Office_ID" = coalesce(quote."CusQuoteHeader_OrgOfficeID", quote."OrgOffice_ID")
    where office."Company_ID" = p_company_id and quote."CusQuoteHeader_CustomerID" is not null
  ) candidate
  where candidate.account_id is not null
    and not exists (
      select 1
      from public."CRM_AccountProfiles" fixture
      where fixture."CRMAccount_OrgID" = candidate.account_id
        and not fixture."CRMAccount_IsDeleted"
        and lower(coalesce(fixture."CRMAccount_MetadataJSON" ->> 'developmentFixture', 'false')) = 'true'
    )
$$;


ALTER FUNCTION "public"."multideck_crm_accessible_account_ids"("p_company_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_crm_account_register_page"("p_search" "text" DEFAULT NULL::"text", "p_marketing_scope" "text" DEFAULT NULL::"text", "p_relationship" "text" DEFAULT NULL::"text", "p_owner_id" "uuid" DEFAULT NULL::"uuid", "p_unassigned" boolean DEFAULT false, "p_sort" "text" DEFAULT 'account'::"text", "p_direction" "text" DEFAULT 'asc'::"text", "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_context record;
  v_limit integer := greatest(1, least(coalesce(p_limit, 50), 100));
  v_offset integer := greatest(0, coalesce(p_offset, 0));
  v_search text := nullif(btrim(p_search), '');
  v_direction text := case when lower(p_direction) = 'desc' then 'desc' else 'asc' end;
  v_result jsonb;
begin
  select * into v_context from public._multideck_crm_context();
  if not public._multideck_crm_has_permission(v_context.user_id, 'Customers.Read') then
    raise exception 'You do not have permission to view CRM accounts.' using errcode = '42501';
  end if;

  with base as materialized (
    select
      org."Org_id" as id,
      coalesce(org."Org_Name", '') as name,
      coalesce(profile."CRMAccount_RelationshipStatusCode", org."Org_CRMRelationshipStatusCode", 'active_customer') as relationship_status,
      profile."CRMAccount_OwnerUserID" as owner_id,
      nullif(btrim(concat_ws(' ', owner."User_Firstname", owner."User_Lastname")), '') as owner_name,
      profile."CRMAccount_Vertical" as industry,
      profile."CRMAccount_HealthScore" as health_score,
      profile."CRMAccount_LastContactAt" as last_contact_at,
      profile."CRMAccount_NextActionDueAt" as next_action_due_at,
      coalesce(org."Org_MarketingOptIn", false) as marketing_opt_in,
      coalesce(contact_count.value, 0)::integer as contact_count,
      concat_ws(', ', address."OrgAdd_TownCity", address."OrgAdd_Country") as location
    from public.multideck_crm_accessible_account_ids(v_context.company_id) accessible
    join public."Org_Master" org on org."Org_id" = accessible.account_id
    left join public."CRM_AccountProfiles" profile
      on profile."CRMAccount_OrgID" = org."Org_id"
     and not profile."CRMAccount_IsDeleted"
    left join public."cmp_Users" owner on owner."User_ID" = profile."CRMAccount_OwnerUserID"
    left join lateral (
      select count(*)::integer as value
      from public."Org_Contacts" contact
      where contact."Org_ID" = org."Org_id"
    ) contact_count on true
    left join lateral (
      select item."OrgAdd_TownCity", item."OrgAdd_Country"
      from public."Org_Addresses" item
      where item."Org_ID" = org."Org_id"
      limit 1
    ) address on true
    where coalesce(org."Org_CRMIsPotentialCustomer", false)
       or exists (
         select 1
         from public."Org_Master_Type" link
         join public."Org_Types" type on type."OrgType_ID" = link."OrgType_ID"
         where link."Org_ID" = org."Org_id"
           and lower(type."OrgType_Name") = 'customer'
       )
  ), filtered as materialized (
    select *
    from base
    where (v_search is null or concat_ws(' ', name, location, industry, owner_name, relationship_status) ilike '%' || v_search || '%')
      and (p_marketing_scope is null or p_marketing_scope = 'all'
        or (p_marketing_scope = 'opted_in' and marketing_opt_in)
        or (p_marketing_scope = 'opted_out' and not marketing_opt_in))
      and (nullif(btrim(p_relationship), '') is null or relationship_status = p_relationship)
      and (not p_unassigned or owner_id is null)
      and (p_owner_id is null or owner_id = p_owner_id)
  ), ranked as (
    select id, row_number() over (
      order by
        case when p_sort = 'account' and v_direction = 'asc' then lower(name) end asc,
        case when p_sort = 'account' and v_direction = 'desc' then lower(name) end desc,
        case when p_sort = 'relationship' and v_direction = 'asc' then lower(relationship_status) end asc,
        case when p_sort = 'relationship' and v_direction = 'desc' then lower(relationship_status) end desc,
        case when p_sort = 'owner' and v_direction = 'asc' then lower(owner_name) end asc nulls last,
        case when p_sort = 'owner' and v_direction = 'desc' then lower(owner_name) end desc nulls last,
        case when p_sort = 'last-contact' and v_direction = 'asc' then last_contact_at end asc nulls last,
        case when p_sort = 'last-contact' and v_direction = 'desc' then last_contact_at end desc nulls last,
        case when p_sort = 'contacts' and v_direction = 'asc' then contact_count end asc,
        case when p_sort = 'contacts' and v_direction = 'desc' then contact_count end desc,
        case when p_sort = 'marketing' and v_direction = 'asc' then marketing_opt_in::integer end asc,
        case when p_sort = 'marketing' and v_direction = 'desc' then marketing_opt_in::integer end desc,
        lower(name), id
    ) as ordinal
    from filtered
  ), page as (
    select id, ordinal
    from ranked
    where ordinal > v_offset and ordinal <= v_offset + v_limit
  )
  select jsonb_build_object(
    'ids', coalesce((select jsonb_agg(id order by ordinal) from page), '[]'::jsonb),
    'total', (select count(*) from filtered),
    'summary', coalesce((select jsonb_build_object(
      'accounts', count(*),
      'contacts', coalesce(sum(contact_count), 0),
      'needsAttention', count(*) filter (where next_action_due_at is not null and next_action_due_at <= now()),
      'marketingOptedIn', count(*) filter (where marketing_opt_in),
      'unassigned', count(*) filter (where owner_id is null),
      'healthy', count(*) filter (where health_score >= 70)
    ) from base), '{}'::jsonb),
    'facets', jsonb_build_object(
      'relationships', coalesce((select jsonb_agg(value order by value) from (select distinct relationship_status as value from base where relationship_status is not null) valueset), '[]'::jsonb),
      'owners', coalesce((select jsonb_agg(jsonb_build_object('id', owner_id, 'name', owner_name) order by owner_name) from (select distinct owner_id, owner_name from base where owner_id is not null and owner_name is not null) ownerset), '[]'::jsonb),
      'hasUnassigned', exists(select 1 from base where owner_id is null)
    )
  ) into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."multideck_crm_account_register_page"("p_search" "text", "p_marketing_scope" "text", "p_relationship" "text", "p_owner_id" "uuid", "p_unassigned" boolean, "p_sort" "text", "p_direction" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_crm_archive_organisation_address"("p_actor_user_id" "uuid", "p_account_id" "uuid", "p_address_id" "uuid", "p_expected_version" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_profile public."CRM_AccountProfiles"%rowtype;
  v_next_version bigint;
begin
  perform public._multideck_crm_write_actor(p_actor_user_id);
  perform public._multideck_crm_require_account_access(p_actor_user_id, p_account_id);
  select * into v_profile from public."CRM_AccountProfiles"
  where "CRMAccount_OrgID" = p_account_id and not "CRMAccount_IsDeleted"
  order by "CRMAccount_ID" limit 1 for update;
  if not found then raise exception 'Organisation not found.' using errcode = 'P0002'; end if;
  if p_expected_version is null or p_expected_version <> v_profile."CRMAccount_EditVersion" then
    raise exception 'CRM_CONFLICT:This organisation changed since it was loaded.' using errcode = 'P0001';
  end if;
  if exists (
    select 1 from public."Org_AddressTypes"
    where "OrgAdd_ID" = p_address_id and "OrgAddType_IsDefault"
  ) then
    raise exception 'Choose replacement defaults before archiving this address.' using errcode = '22023';
  end if;
  update public."Org_Addresses"
  set "OrgAdd_IsActive" = false, "OrgAdd_UpdatedAt" = now(), "OrgAdd_UpdatedBy" = p_actor_user_id
  where "OrgAdd_ID" = p_address_id and "Org_ID" = p_account_id and "OrgAdd_IsActive";
  if not found then raise exception 'Active address not found.' using errcode = 'P0002'; end if;
  v_next_version := v_profile."CRMAccount_EditVersion" + 1;
  update public."CRM_AccountProfiles"
  set "CRMAccount_EditVersion" = v_next_version, "CRMAccount_UpdatedAt" = now(), "CRMAccount_UpdatedBy" = p_actor_user_id
  where "CRMAccount_ID" = v_profile."CRMAccount_ID";
  return jsonb_build_object('id', p_address_id, 'accountId', p_account_id, 'editVersion', v_next_version, 'archived', true);
end;
$$;


ALTER FUNCTION "public"."multideck_crm_archive_organisation_address"("p_actor_user_id" "uuid", "p_account_id" "uuid", "p_address_id" "uuid", "p_expected_version" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_crm_cancel_lead_transfer"("p_request_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare v_context record; v_request public."CRM_LeadTransferRequests"%rowtype;
begin
  select * into v_context from public._multideck_crm_context();
  select * into v_request from public."CRM_LeadTransferRequests" where "CRMLeadTransfer_ID" = p_request_id for update;
  if not found or v_request."Company_ID" <> v_context.company_id then raise exception 'This transfer request was not found.' using errcode = 'P0002'; end if;
  if v_request."CRMLeadTransfer_RequesterUserID" <> v_context.user_id then raise exception 'Only the requester can cancel this request.' using errcode = '42501'; end if;
  if v_request."CRMLeadTransfer_Status" <> 'pending' then raise exception 'Only a pending request can be cancelled.' using errcode = '22023'; end if;
  update public."CRM_LeadTransferRequests" set "CRMLeadTransfer_Status" = 'cancelled', "CRMLeadTransfer_CancelledAt" = now(), "CRMLeadTransfer_UpdatedAt" = now()
  where "CRMLeadTransfer_ID" = p_request_id;
  return public._multideck_crm_transfer_request_json(p_request_id);
end;
$$;


ALTER FUNCTION "public"."multideck_crm_cancel_lead_transfer"("p_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_crm_company_can_access_account"("p_company_id" "uuid", "p_account_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select p_company_id is not null and p_account_id is not null and (
    exists (
      select 1
      from public."CRM_AccountProfiles" profile
      where profile."CRMAccount_OrgID" = p_account_id
        and not profile."CRMAccount_IsDeleted"
        and profile."CRMAccount_CompanyID" = p_company_id
    )
    or exists (
      select 1
      from public."Job_Header" job
      join public."cmp_Offices" office
        on office."Office_ID" = coalesce(job."Job_OrgOfficeID", job."Job_OfficeID")
      where office."Company_ID" = p_company_id
        and job."Job_Customer" = p_account_id
    )
    or exists (
      select 1
      from public."CusQuote_Header" quote
      join public."cmp_Offices" office
        on office."Office_ID" = coalesce(quote."CusQuoteHeader_OrgOfficeID", quote."OrgOffice_ID")
      where office."Company_ID" = p_company_id
        and quote."CusQuoteHeader_CustomerID" = p_account_id
    )
  )
  and not exists (
    select 1
    from public."CRM_AccountProfiles" fixture
    where fixture."CRMAccount_OrgID" = p_account_id
      and not fixture."CRMAccount_IsDeleted"
      and lower(coalesce(fixture."CRMAccount_MetadataJSON" ->> 'developmentFixture', 'false')) = 'true'
  )
$$;


ALTER FUNCTION "public"."multideck_crm_company_can_access_account"("p_company_id" "uuid", "p_account_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_crm_contact_activity_page"("p_user_id" "uuid", "p_contact_id" "uuid", "p_limit" integer DEFAULT 20) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_limit integer := least(20, greatest(1, coalesce(p_limit, 20)));
  v_result jsonb;
begin
  if not exists (
    select 1
    from public."cmp_Users" as user_row
    where user_row."User_ID" = p_user_id
      and user_row."Auth_User_ID" is not null
  ) then
    raise exception 'The signed-in CRM user could not be verified.' using errcode = '42501';
  end if;

  if not public._multideck_crm_has_permission(p_user_id, 'Customers.Read') then
    raise exception 'You do not have permission to read CRM customers.' using errcode = '42501';
  end if;

  select coalesce(jsonb_agg(
    jsonb_build_object(
      'id', activity."CRMActivity_ID",
      'subject', activity."CRMActivity_Subject",
      'summary', activity."CRMActivity_Summary",
      'occurredAt', activity."CRMActivity_ActivityAt",
      'type', activity."CRMActivity_ActivityTypeCode"
    )
    order by activity."CRMActivity_ActivityAt" desc nulls last, activity."CRMActivity_ID" desc
  ), '[]'::jsonb)
  into v_result
  from (
    select activity.*
    from public."CRM_Activities" as activity
    where not activity."CRMActivity_IsDeleted"
      and exists (
        select 1
        from public."CRM_ActivityParticipants" as participant
        where participant."CRMActPart_ActivityID" = activity."CRMActivity_ID"
          and participant."CRMActPart_OrgContactID" = p_contact_id
      )
    order by activity."CRMActivity_ActivityAt" desc nulls last, activity."CRMActivity_ID" desc
    limit v_limit
  ) as activity;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."multideck_crm_contact_activity_page"("p_user_id" "uuid", "p_contact_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_crm_contact_counts"("p_account_ids" "uuid"[]) RETURNS TABLE("account_id" "uuid", "contact_count" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select contact."Org_ID", count(*)::bigint
  from public."Org_Contacts" contact
  where contact."Org_ID" = any(coalesce(p_account_ids, '{}'::uuid[]))
  group by contact."Org_ID"
$$;


ALTER FUNCTION "public"."multideck_crm_contact_counts"("p_account_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."multideck_crm_contact_counts"("p_account_ids" "uuid"[]) IS 'Returns contact totals for an Edge-scoped account page without transferring contact rows.';



CREATE OR REPLACE FUNCTION "public"."multideck_crm_contact_register_page"("p_search" "text" DEFAULT NULL::"text", "p_consent_scope" "text" DEFAULT NULL::"text", "p_account_id" "uuid" DEFAULT NULL::"uuid", "p_channel" "text" DEFAULT NULL::"text", "p_sort" "text" DEFAULT 'contact'::"text", "p_direction" "text" DEFAULT 'asc'::"text", "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_context record;
  v_limit integer := greatest(1, least(coalesce(p_limit, 50), 100));
  v_offset integer := greatest(0, coalesce(p_offset, 0));
  v_search text := nullif(btrim(p_search), '');
  v_direction text := case when lower(p_direction) = 'desc' then 'desc' else 'asc' end;
  v_result jsonb;
begin
  select * into v_context from public._multideck_crm_context();
  if not public._multideck_crm_has_permission(v_context.user_id, 'Customers.Read') then
    raise exception 'You do not have permission to view CRM contacts.' using errcode = '42501';
  end if;

  with base as materialized (
    select
      contact."OrgContact_ID" as id,
      contact."Org_ID" as account_id,
      coalesce(org."Org_Name", 'Unknown account') as account_name,
      nullif(btrim(concat_ws(' ', contact."OrgContact_FirstName", contact."OrgContact_LastName")), '') as name,
      email.address as email,
      phone.address as phone,
      profile."CRMContact_RoleCode" as role,
      profile."CRMContact_PreferredChannelCode" as preferred_channel,
      profile."CRMContact_LastContactAt" as last_contact_at,
      coalesce(contact."OrgContact_MarketingOptIn", profile."CRMContact_ConsentMarketing", false) as consent_marketing,
      profile."CRMContact_MetadataJSON" ->> 'jobTitle' as job_title,
      profile."CRMContact_MetadataJSON" ->> 'department' as department
    from public.multideck_crm_accessible_account_ids(v_context.company_id) accessible
    join public."Org_Contacts" contact on contact."Org_ID" = accessible.account_id
    join public."Org_Master" org on org."Org_id" = contact."Org_ID"
    left join public."CRM_ContactProfiles" profile on profile."CRMContact_OrgContactID" = contact."OrgContact_ID"
    left join lateral (
      select item."OrgContactEmail_Email" as address
      from public."OrgContact_Emails" item
      where item."OrgContact_ID" = contact."OrgContact_ID"
      order by item."OrgContactEmail_Type"
      limit 1
    ) email on true
    left join lateral (
      select identity."CommIdentity_Address" as address
      from public."Comm_Identities" identity
      where identity."CommIdentity_ContactID" = contact."OrgContact_ID"
        and identity."CommIdentity_ChannelCode" in ('phone', 'sms', 'whatsapp')
        and not identity."CommIdentity_IsDeleted"
      order by case identity."CommIdentity_ChannelCode" when 'phone' then 0 when 'sms' then 1 else 2 end
      limit 1
    ) phone on true
  ), filtered as materialized (
    select *
    from base
    where (v_search is null or concat_ws(' ', name, email, phone, account_name, role, job_title, department) ilike '%' || v_search || '%')
      and (p_consent_scope is null or p_consent_scope = 'all'
        or (p_consent_scope = 'opted_in' and consent_marketing)
        or (p_consent_scope = 'opted_out' and not consent_marketing))
      and (p_account_id is null or account_id = p_account_id)
      and (nullif(btrim(p_channel), '') is null or preferred_channel = p_channel)
  ), ranked as (
    select id, row_number() over (
      order by
        case when p_sort = 'contact' and v_direction = 'asc' then lower(name) end asc nulls last,
        case when p_sort = 'contact' and v_direction = 'desc' then lower(name) end desc nulls last,
        case when p_sort = 'account' and v_direction = 'asc' then lower(account_name) end asc,
        case when p_sort = 'account' and v_direction = 'desc' then lower(account_name) end desc,
        case when p_sort = 'role' and v_direction = 'asc' then lower(coalesce(job_title, role)) end asc nulls last,
        case when p_sort = 'role' and v_direction = 'desc' then lower(coalesce(job_title, role)) end desc nulls last,
        case when p_sort = 'preference' and v_direction = 'asc' then lower(preferred_channel) end asc nulls last,
        case when p_sort = 'preference' and v_direction = 'desc' then lower(preferred_channel) end desc nulls last,
        case when p_sort = 'last-contact' and v_direction = 'asc' then last_contact_at end asc nulls last,
        case when p_sort = 'last-contact' and v_direction = 'desc' then last_contact_at end desc nulls last,
        case when p_sort = 'marketing' and v_direction = 'asc' then consent_marketing::integer end asc,
        case when p_sort = 'marketing' and v_direction = 'desc' then consent_marketing::integer end desc,
        lower(coalesce(name, '')), id
    ) as ordinal
    from filtered
  ), page as (
    select id, ordinal
    from ranked
    where ordinal > v_offset and ordinal <= v_offset + v_limit
  )
  select jsonb_build_object(
    'ids', coalesce((select jsonb_agg(id order by ordinal) from page), '[]'::jsonb),
    'total', (select count(*) from filtered),
    'summary', coalesce((select jsonb_build_object(
      'contacts', count(*),
      'recentlyContacted', count(*) filter (where last_contact_at >= now() - interval '30 days'),
      'marketingOptedIn', count(*) filter (where consent_marketing),
      'marketingOptedOut', count(*) filter (where not consent_marketing)
    ) from base), '{}'::jsonb),
    'facets', jsonb_build_object(
      'accounts', coalesce((select jsonb_agg(jsonb_build_object('id', account_id, 'name', account_name) order by account_name) from (select distinct account_id, account_name from base) accountset), '[]'::jsonb),
      'channels', coalesce((select jsonb_agg(value order by value) from (select distinct preferred_channel as value from base where preferred_channel is not null) channelset), '[]'::jsonb)
    )
  ) into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."multideck_crm_contact_register_page"("p_search" "text", "p_consent_scope" "text", "p_account_id" "uuid", "p_channel" "text", "p_sort" "text", "p_direction" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_crm_convert_lead"("p_lead_id" "uuid", "p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_context record;
  v_lead public."CRM_Leads"%rowtype;
  v_org_id uuid;
  v_account_id uuid;
  v_contact_id uuid;
  v_contact_profile_id uuid;
  v_company_name text;
  v_contact_name text;
  v_contact_first_name text;
  v_contact_last_name text;
  v_email text;
  v_existing_contact_account_id uuid;
  v_existing_contact_company_id uuid;
  v_relationship_status text;
  v_currency_id uuid;
  v_org_type_id uuid;
  v_matching_account_count integer;
  v_matching_contact_count integer;
  v_conversion_input jsonb := p_input;
  v_promoted_org_free boolean := false;
begin
  select * into v_context from public._multideck_crm_context();

  if not public._multideck_crm_has_permission(v_context.user_id, 'CRM.Write') then
    raise exception 'You do not have permission to convert CRM leads.' using errcode = '42501';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(p_lead_id::text, 0));

  select * into v_lead
  from public."CRM_Leads"
  where "CRMLead_ID" = p_lead_id
    and not "CRMLead_IsDeleted"
  for update;

  if not found or not public._multideck_crm_lead_is_reachable(p_lead_id, v_context.company_id) then
    raise exception 'Lead not found.' using errcode = 'P0002';
  end if;

  if lower(coalesce(v_lead."CRMLead_MetadataJSON" ->> 'isDemo', 'false')) = 'true' then
    raise exception 'Development demo leads cannot be converted.' using errcode = '42501';
  end if;

  perform public."Audit_SetContext"(
    v_context.user_id, null, 'user', null, null, null, null, null, null,
    'multideck', 'crm', null, null, null
  );

  if v_lead."CRMLead_OrgID" is null then
    v_promoted_org_free := true;
    v_company_name := nullif(btrim(v_lead."CRMLead_CompanyName"), '');
    if v_company_name is null then
      raise exception 'Add a company name to this lead before converting it to a deal.' using errcode = '22023';
    end if;

    v_email := lower(nullif(btrim(v_lead."CRMLead_Email"), ''));
    v_contact_name := nullif(btrim(v_lead."CRMLead_PersonName"), '');
    v_contact_first_name := nullif(split_part(coalesce(v_contact_name, ''), ' ', 1), '');
    v_contact_last_name := nullif(btrim(substring(coalesce(v_contact_name, '') from length(coalesce(v_contact_first_name, '')) + 1)), '');

    if length(v_company_name) > 100 then
      raise exception 'Company names must be 100 characters or fewer before conversion.' using errcode = '22023';
    end if;
    if length(v_email) > 200 then
      raise exception 'Contact emails must be 200 characters or fewer before conversion.' using errcode = '22023';
    end if;
    if length(v_contact_first_name) > 50 or length(v_contact_last_name) > 50 then
      raise exception 'Contact names must fit within 50 characters per name before conversion.' using errcode = '22023';
    end if;
    if length(nullif(btrim(v_lead."CRMLead_AddressLine1"), '')) > 50
      or length(nullif(btrim(v_lead."CRMLead_AddressLine2"), '')) > 50
      or length(nullif(btrim(v_lead."CRMLead_TownCity"), '')) > 50
      or length(nullif(btrim(v_lead."CRMLead_CountyState"), '')) > 50
      or length(nullif(btrim(v_lead."CRMLead_PostZipCode"), '')) > 50 then
      raise exception 'Lead address fields must be 50 characters or fewer before conversion.' using errcode = '22023';
    end if;

    perform pg_advisory_xact_lock(hashtextextended(lower(v_company_name), 0));

    select count(*)
    into v_matching_account_count
    from public."CRM_AccountProfiles" profile
    join public."Org_Master" organisation
      on organisation."Org_id" = profile."CRMAccount_OrgID"
    where profile."CRMAccount_CompanyID" = v_context.company_id
      and not profile."CRMAccount_IsDeleted"
      and lower(coalesce(profile."CRMAccount_MetadataJSON" ->> 'developmentFixture', 'false')) <> 'true'
      and lower(btrim(organisation."Org_Name")) = lower(v_company_name);

    if v_matching_account_count > 1 then
      raise exception 'More than one account matches this company name. Choose the correct account before converting the lead.' using errcode = '22023';
    end if;

    if v_matching_account_count = 1 then
      select profile."CRMAccount_ID", profile."CRMAccount_OrgID"
      into v_account_id, v_org_id
      from public."CRM_AccountProfiles" profile
      join public."Org_Master" organisation
        on organisation."Org_id" = profile."CRMAccount_OrgID"
      where profile."CRMAccount_CompanyID" = v_context.company_id
        and not profile."CRMAccount_IsDeleted"
        and lower(coalesce(profile."CRMAccount_MetadataJSON" ->> 'developmentFixture', 'false')) <> 'true'
        and lower(btrim(organisation."Org_Name")) = lower(v_company_name)
      limit 1;
    else
      select status."CRMRelStatus_Code" into v_relationship_status
      from public."sys_CRMRelationshipStatuses" status
      where status."CRMRelStatus_IsActive"
        and not status."CRMRelStatus_IsCustomer"
      order by
        case status."CRMRelStatus_Code" when 'prospect' then 0 when 'lead' then 1 else 2 end,
        status."CRMRelStatus_SortOrder"
      limit 1;

      select currency."Currency_ID" into v_currency_id
      from public."sys_Currency" currency
      order by case when currency."Currency_Code" = 'GBP' then 0 else 1 end, currency."Currency_Code"
      limit 1;

      if v_relationship_status is null or v_currency_id is null then
        raise exception 'Prospect account lookups are incomplete for this workspace.' using errcode = '55000';
      end if;

      v_org_id := gen_random_uuid();
      v_account_id := gen_random_uuid();

      insert into public."Org_Master" (
        "Org_id", "Org_Name", "Org_BaseCurrency", "Org_AccCode",
        "Org_CRMRelationshipStatusCode", "Org_CRMIsPotentialCustomer", "Org_CRMIsLead", "Org_CRMUpdatedAt"
      ) values (
        v_org_id, v_company_name, v_currency_id,
        coalesce(nullif(left(regexp_replace(upper(v_company_name), '[^A-Z0-9]', '', 'g'), 11), ''), 'PROSPECT')
          || '-' || upper(left(replace(v_org_id::text, '-', ''), 6)),
        v_relationship_status, true, true, now()
      );

      insert into public."CRM_AccountProfiles" (
        "CRMAccount_ID", "CRMAccount_OrgID", "CRMAccount_CompanyID", "CRMAccount_RelationshipStatusCode",
        "CRMAccount_OwnerUserID", "CRMAccount_CreatedBy", "CRMAccount_UpdatedBy", "CRMAccount_EditVersion"
      ) values (
        v_account_id, v_org_id, v_context.company_id, v_relationship_status,
        coalesce(v_lead."CRMLead_OwnerUserID", v_context.user_id), v_context.user_id, v_context.user_id, 1
      );

      select "OrgType_ID" into v_org_type_id
      from public."Org_Types"
      where lower(btrim("OrgType_Name")) in ('prospect', 'lead')
      order by case lower(btrim("OrgType_Name")) when 'prospect' then 0 else 1 end, "OrgType_Order" nulls last
      limit 1;
      if v_org_type_id is not null then
        insert into public."Org_Master_Type" ("Org_ID", "OrgType_ID")
        values (v_org_id, v_org_type_id)
        on conflict ("OrgType_ID", "Org_ID") do nothing;
      end if;
    end if;

    if coalesce(
      nullif(btrim(v_lead."CRMLead_AddressLine1"), ''),
      nullif(btrim(v_lead."CRMLead_TownCity"), ''),
      nullif(btrim(v_lead."CRMLead_PostZipCode"), ''),
      nullif(btrim(v_lead."CRMLead_CountryCode"), '')
    ) is not null and not exists (
      select 1 from public."Org_Addresses" address where address."Org_ID" = v_org_id
    ) then
      insert into public."Org_Addresses" (
        "OrgAdd_ID", "Org_ID", "OrgAdd_Line1", "OrgAdd_Line2", "OrgAdd_TownCity",
        "OrgAdd_CountyState", "OrgAdd_PostZipCode", "OrgAdd_Country"
      ) values (
        gen_random_uuid(), v_org_id,
        nullif(btrim(v_lead."CRMLead_AddressLine1"), ''),
        nullif(btrim(v_lead."CRMLead_AddressLine2"), ''),
        nullif(btrim(v_lead."CRMLead_TownCity"), ''),
        nullif(btrim(v_lead."CRMLead_CountyState"), ''),
        nullif(btrim(v_lead."CRMLead_PostZipCode"), ''),
        upper(nullif(btrim(v_lead."CRMLead_CountryCode"), ''))
      );
    end if;

    if v_email is not null then
      perform pg_advisory_xact_lock(hashtextextended(v_email, 0));
      select count(distinct contact."OrgContact_ID") into v_matching_contact_count
      from public."Org_Contacts" contact
      join public."OrgContact_Emails" email
        on email."OrgContact_ID" = contact."OrgContact_ID"
      where contact."Org_ID" = v_org_id
        and lower(btrim(email."OrgContactEmail_Email")) = v_email;
      if v_matching_contact_count > 1 then
        raise exception 'More than one contact matches this lead email. Choose the correct contact before converting the lead.' using errcode = '22023';
      elsif v_matching_contact_count = 1 then
        select contact."OrgContact_ID" into v_contact_id
        from public."Org_Contacts" contact
        join public."OrgContact_Emails" email
          on email."OrgContact_ID" = contact."OrgContact_ID"
        where contact."Org_ID" = v_org_id
          and lower(btrim(email."OrgContactEmail_Email")) = v_email;
      end if;
    end if;

    if v_contact_id is not null then
      select profile."CRMContact_ID", profile."CRMContact_AccountID", profile."CRMContact_CompanyID"
      into v_contact_profile_id, v_existing_contact_account_id, v_existing_contact_company_id
      from public."CRM_ContactProfiles" profile
      where profile."CRMContact_OrgContactID" = v_contact_id
      order by profile."CRMContact_ID"
      limit 1
      for update;

      if v_contact_profile_id is null then
        insert into public."CRM_ContactProfiles" (
          "CRMContact_ID", "CRMContact_OrgContactID", "CRMContact_AccountID", "CRMContact_CompanyID",
          "CRMContact_CreatedBy", "CRMContact_UpdatedBy", "CRMContact_EditVersion"
        ) values (gen_random_uuid(), v_contact_id, v_account_id, v_context.company_id, v_context.user_id, v_context.user_id, 1);
      elsif v_existing_contact_company_id is distinct from v_context.company_id
        or (v_existing_contact_account_id is not null and v_existing_contact_account_id is distinct from v_account_id) then
        raise exception 'The matched contact belongs to a different CRM account or company.' using errcode = '42501';
      else
        update public."CRM_ContactProfiles"
        set "CRMContact_AccountID" = v_account_id,
            "CRMContact_CompanyID" = v_context.company_id,
            "CRMContact_UpdatedBy" = v_context.user_id,
            "CRMContact_UpdatedAt" = now(),
            "CRMContact_EditVersion" = "CRMContact_EditVersion" + 1
        where "CRMContact_ID" = v_contact_profile_id;
      end if;
    elsif v_contact_name is not null or v_email is not null then
      v_contact_id := gen_random_uuid();
      v_contact_profile_id := gen_random_uuid();

      insert into public."Org_Contacts" (
        "OrgContact_ID", "Org_ID", "OrgContact_FirstName", "OrgContact_LastName"
      ) values (
        v_contact_id, v_org_id, v_contact_first_name, v_contact_last_name
      );

      insert into public."CRM_ContactProfiles" (
        "CRMContact_ID", "CRMContact_OrgContactID", "CRMContact_AccountID", "CRMContact_CompanyID",
        "CRMContact_CreatedBy", "CRMContact_UpdatedBy", "CRMContact_EditVersion"
      ) values (
        v_contact_profile_id, v_contact_id, v_account_id, v_context.company_id,
        v_context.user_id, v_context.user_id, 1
      );

      if v_email is not null then
        insert into public."OrgContact_Emails" (
          "OrgContactEmail_ID", "OrgContact_ID", "OrgContactEmail_Email", "OrgContactEmail_Type"
        ) values (gen_random_uuid(), v_contact_id, v_email, 1);
      end if;
    end if;

    update public."CRM_Leads"
    set "CRMLead_OrgID" = v_org_id,
        "CRMLead_PrimaryContactID" = coalesce(v_contact_id, "CRMLead_PrimaryContactID"),
        "CRMLead_UpdatedAt" = now(),
        "CRMLead_UpdatedBy" = v_context.user_id
    where "CRMLead_ID" = p_lead_id;

    insert into public."CRM_OrgLifecycleTags" (
      "CRMOrgLifeTag_OrgID", "CRMOrgLifeTag_TagCode", "CRMOrgLifeTag_SourceTable",
      "CRMOrgLifeTag_SourceID", "CRMOrgLifeTag_CreatedBy"
    ) values
      (v_org_id, 'potential_customer', 'CRM_Leads', p_lead_id, v_context.user_id),
      (v_org_id, 'prospect', 'CRM_Leads', p_lead_id, v_context.user_id)
    on conflict ("CRMOrgLifeTag_OrgID", "CRMOrgLifeTag_TagCode") do update
      set "CRMOrgLifeTag_IsActive" = true;
  end if;

  if v_promoted_org_free then
    v_conversion_input := coalesce(p_input, '{}'::jsonb)
      || jsonb_build_object('primaryContactId', v_contact_id);
  end if;

  return public._multideck_crm_convert_lead_with_org_20260818(p_lead_id, v_conversion_input);
end;
$$;


ALTER FUNCTION "public"."multideck_crm_convert_lead"("p_lead_id" "uuid", "p_input" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."multideck_crm_convert_lead"("p_lead_id" "uuid", "p_input" "jsonb") IS 'Atomically promotes an organisation-free lead into a company-scoped prospect account, repairs the conversion contact input, and then creates the first deal.';



CREATE OR REPLACE FUNCTION "public"."multideck_crm_create_account"("p_actor_user_id" "uuid", "p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_result jsonb; v_org uuid; v_name text; v_location text; v_base text; v_candidate text; v_n integer:=0;
begin
  v_result:=public._multideck_crm_create_account_pre_sage8_20260820(p_actor_user_id,p_input);
  v_org:=(v_result->>'id')::uuid;
  -- Explicit codes are import/conversion data. The wrapped create path has
  -- already validated them with the eight-character helper, so preserve them.
  if nullif(btrim(p_input->>'accountCode'),'') is not null then
    select "Org_AccCode" into v_candidate from public."Org_Master" where "Org_id"=v_org;
    return v_result||jsonb_build_object('accountCode',v_candidate);
  end if;
  v_name:=regexp_replace(upper(coalesce(p_input->>'name','')),'[^A-Z0-9]','','g');
  v_location:=regexp_replace(upper(coalesce(nullif(p_input->>'townCity',''),p_input->>'countryCode','')),'[^A-Z0-9]','','g');
  v_base:=left(v_name,5)||left(v_location,3);
  if length(v_base)<2 then v_base:='ACCOUNT'; end if;
  perform pg_advisory_xact_lock(hashtextextended('sage50-account-code:'||left(v_base,6),0));
  loop
    v_candidate:=case when v_n=0 then left(v_base,8) else left(v_base,6)||lpad(v_n::text,2,'0') end;
    exit when not exists(select 1 from public."Org_Master" where lower("Org_AccCode")=lower(v_candidate) and "Org_id"<>v_org);
    v_n:=v_n+1; if v_n>99 then raise exception 'No Sage 50-compatible account code is available for this mnemonic.' using errcode='23505'; end if;
  end loop;
  update public."Org_Master" set "Org_AccCode"=v_candidate where "Org_id"=v_org;
  return v_result||jsonb_build_object('accountCode',v_candidate);
end; $$;


ALTER FUNCTION "public"."multideck_crm_create_account"("p_actor_user_id" "uuid", "p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_crm_create_contact"("p_actor_user_id" "uuid", "p_account_id" "uuid", "p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_result jsonb;
  v_contact_id uuid;
  v_company_id uuid;
begin
  v_result := public._multideck_crm_create_contact_prefoundation_20260820(p_actor_user_id, p_account_id, p_input);
  v_contact_id := (v_result ->> 'id')::uuid;
  select "CRMAccount_CompanyID" into v_company_id from public."CRM_AccountProfiles"
  where "CRMAccount_OrgID" = p_account_id and not "CRMAccount_IsDeleted"
  order by "CRMAccount_ID" limit 1;
  update public."OrgContact_Emails"
  set "OrgContactEmail_IsPrimary" = true
  where "OrgContactEmail_ID" = (
    select email."OrgContactEmail_ID" from public."OrgContact_Emails" email
    where email."OrgContact_ID" = v_contact_id and email."OrgContactEmail_IsActive"
    order by email."OrgContactEmail_ValidFrom" desc, email."OrgContactEmail_ID" limit 1
  );
  insert into public."CRM_ContactOrganisationAssignments"(
    "CRMContactOrg_ContactID", "CRMContactOrg_OrgID", "CRMContactOrg_CompanyID",
    "CRMContactOrg_JobTitle", "CRMContactOrg_Department", "CRMContactOrg_RoleCode",
    "CRMContactOrg_StartedAt", "CRMContactOrg_IsCurrent", "CRMContactOrg_CreatedBy"
  ) values (
    v_contact_id, p_account_id, v_company_id, nullif(btrim(p_input ->> 'jobTitle'), ''),
    nullif(btrim(p_input ->> 'department'), ''), nullif(btrim(p_input ->> 'role'), ''),
    coalesce(nullif(p_input ->> 'startedAt', '')::date, current_date), true, p_actor_user_id
  ) on conflict do nothing;
  return v_result;
end;
$$;


ALTER FUNCTION "public"."multideck_crm_create_contact"("p_actor_user_id" "uuid", "p_account_id" "uuid", "p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_crm_create_follow_up_lead"("p_email" "text", "p_person_name" "text" DEFAULT NULL::"text", "p_company_name" "text" DEFAULT NULL::"text", "p_thread_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $_$
declare
  v_context record;
  v_email text := lower(btrim(coalesce(p_email, '')));
  v_id uuid;
begin
  select * into v_context from public._multideck_crm_context();
  if v_email = '' or v_email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' then
    raise exception 'Enter a valid email address.' using errcode = '22023';
  end if;
  if exists (
    select 1 from public."CRM_Leads" lead
    where not lead."CRMLead_IsDeleted" and lower(btrim(lead."CRMLead_Email")) = v_email
  ) or exists (
    select 1 from public."OrgContact_Emails" email
    where lower(btrim(email."OrgContactEmail_Email")) = v_email
  ) then
    raise exception 'This email is already connected to a CRM record.' using errcode = '23505';
  end if;

  insert into public."CRM_Leads" (
    "CRMLead_SourceCode", "CRMLead_StatusCode", "CRMLead_RatingCode", "CRMLead_OwnerUserID",
    "CRMLead_CompanyName", "CRMLead_PersonName", "CRMLead_Email", "CRMLead_MetadataJSON",
    "CRMLead_CreatedBy", "CRMLead_UpdatedBy"
  ) values (
    'manual', 'new', 'unrated', v_context.user_id,
    nullif(btrim(p_company_name), ''), nullif(btrim(p_person_name), ''), v_email,
    jsonb_strip_nulls(jsonb_build_object('source', 'follow_up_opportunity', 'threadId', p_thread_id)),
    v_context.user_id, v_context.user_id
  ) returning "CRMLead_ID" into v_id;

  return public._multideck_crm_lead_json(v_id);
end;
$_$;


ALTER FUNCTION "public"."multideck_crm_create_follow_up_lead"("p_email" "text", "p_person_name" "text", "p_company_name" "text", "p_thread_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."multideck_crm_create_follow_up_lead"("p_email" "text", "p_person_name" "text", "p_company_name" "text", "p_thread_id" "uuid") IS 'Dashboard-only assisted creation from reviewed mailbox evidence. Not exposed as a generic Dexter write because it requires the dedicated preview and approval UI.';



CREATE OR REPLACE FUNCTION "public"."multideck_crm_create_follow_up_lead"("p_email" "text", "p_person_name" "text", "p_company_name" "text", "p_thread_id" "uuid", "p_address" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $_$
declare
  v_result jsonb;
  v_lead_id uuid;
  v_country text := upper(nullif(btrim(coalesce(p_address ->> 'countryCode', '')), ''));
begin
  if p_address is not null and jsonb_typeof(p_address) <> 'object' then
    raise exception 'Lead address must be an object.' using errcode = '22023';
  end if;
  if v_country is not null and v_country !~ '^[A-Z]{2}$' then
    raise exception 'Enter a two-letter ISO country code, such as GB.' using errcode = '22023';
  end if;
  if length(coalesce(p_address ->> 'line1', '')) > 160
    or length(coalesce(p_address ->> 'line2', '')) > 160
    or length(coalesce(p_address ->> 'townCity', '')) > 120
    or length(coalesce(p_address ->> 'countyState', '')) > 120
    or length(coalesce(p_address ->> 'postZipCode', '')) > 40 then
    raise exception 'One or more lead address fields are too long.' using errcode = '22001';
  end if;

  v_result := public.multideck_crm_create_follow_up_lead(p_email, p_person_name, p_company_name, p_thread_id);
  v_lead_id := (v_result ->> 'id')::uuid;

  update public."CRM_Leads"
  set "CRMLead_AddressLine1" = nullif(btrim(p_address ->> 'line1'), ''),
      "CRMLead_AddressLine2" = nullif(btrim(p_address ->> 'line2'), ''),
      "CRMLead_TownCity" = nullif(btrim(p_address ->> 'townCity'), ''),
      "CRMLead_CountyState" = nullif(btrim(p_address ->> 'countyState'), ''),
      "CRMLead_PostZipCode" = nullif(btrim(p_address ->> 'postZipCode'), ''),
      "CRMLead_CountryCode" = v_country,
      "CRMLead_UpdatedAt" = now()
  where "CRMLead_ID" = v_lead_id;

  return v_result || jsonb_build_object('address', public._multideck_crm_lead_native_address(v_lead_id));
end;
$_$;


ALTER FUNCTION "public"."multideck_crm_create_follow_up_lead"("p_email" "text", "p_person_name" "text", "p_company_name" "text", "p_thread_id" "uuid", "p_address" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."multideck_crm_create_follow_up_lead"("p_email" "text", "p_person_name" "text", "p_company_name" "text", "p_thread_id" "uuid", "p_address" "jsonb") IS 'Creates a reviewed CRM lead with an optional lead-native address. The lead does not require an organisation.';



CREATE OR REPLACE FUNCTION "public"."multideck_crm_customer_recent_emails"("p_user_id" "uuid", "p_account_id" "uuid", "p_contact_ids" "uuid"[] DEFAULT '{}'::"uuid"[], "p_contact_emails" "text"[] DEFAULT '{}'::"text"[], "p_include_account_threads" boolean DEFAULT true, "p_limit" integer DEFAULT 12) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_limit integer := least(12, greatest(1, coalesce(p_limit, 12)));
  v_result jsonb;
begin
  if not exists (
    select 1
    from public."cmp_Users" as user_row
    where user_row."User_ID" = p_user_id
      and user_row."Auth_User_ID" is not null
  ) then
    raise exception 'The signed-in CRM user could not be verified.' using errcode = '42501';
  end if;

  if not public._multideck_crm_has_permission(p_user_id, 'Email.Read') then
    return jsonb_build_object('available', false, 'items', '[]'::jsonb);
  end if;

  with candidate_messages as materialized (
    select
      message."CommMessage_ID" as message_id,
      message."CommMessage_ThreadID" as thread_id,
      message."CommMessage_Subject" as subject,
      message."CommMessage_BodyPreview" as body_preview,
      message."CommMessage_IsBodyRedacted" as body_redacted,
      message."CommMessage_HasAttachments" as has_attachments,
      message."CommMessage_IsInbound" as is_inbound,
      message."CommMessage_DirectionCode" as direction_code,
      coalesce(
        message."CommMessage_MessageDate",
        message."CommMessage_ReceivedAt",
        message."CommMessage_SentAt",
        message."CommMessage_CreatedAt"
      ) as occurred_at
    from public."Comm_Messages" as message
    where not message."CommMessage_IsDeleted"
      and not message."CommMessage_IsDraft"
      and not message."CommMessage_IsSpam"
      and exists (
        select 1
        from public."Comm_MailboxAccess" as mailbox_access
        where mailbox_access."CommMailboxAccess_MailboxID" = message."CommMessage_MailboxID"
          and mailbox_access."CommMailboxAccess_UserID" = p_user_id
          and mailbox_access."CommMailboxAccess_CanRead"
          and mailbox_access."CommMailboxAccess_RevokedAt" is null
          and (
            mailbox_access."CommMailboxAccess_ExpiresAt" is null
            or mailbox_access."CommMailboxAccess_ExpiresAt" > now()
          )
      )
      and (
        exists (
          select 1
          from public."Comm_MessageRecipients" as recipient
          where recipient."CommRecipient_MessageID" = message."CommMessage_ID"
            and (
              recipient."CommRecipient_ContactID" = any(coalesce(p_contact_ids, '{}'::uuid[]))
              or lower(recipient."CommRecipient_NormalizedAddress") = any(coalesce(p_contact_emails, '{}'::text[]))
            )
        )
        or (
          coalesce(p_include_account_threads, false)
          and exists (
            select 1
            from public."Comm_Threads" as thread
            where thread."CommThread_ID" = message."CommMessage_ThreadID"
              and thread."CommThread_CustomerOrgID" = p_account_id
              and not thread."CommThread_IsDeleted"
          )
        )
      )
    order by occurred_at desc nulls last, message."CommMessage_ID" desc
    limit v_limit
  )
  select jsonb_build_object(
    'available', true,
    'items', coalesce(jsonb_agg(
      jsonb_build_object(
        'id', candidate.message_id,
        'threadId', candidate.thread_id,
        'direction', case when candidate.is_inbound or candidate.direction_code = 'inbound' then 'inbound' else 'outbound' end,
        'subject', coalesce(nullif(candidate.subject, ''), '(No subject)'),
        'preview', case when candidate.body_redacted then null else candidate.body_preview end,
        'occurredAt', candidate.occurred_at,
        'contactName', selected_recipient.display_name,
        'contactEmail', selected_recipient.address,
        'hasAttachments', coalesce(candidate.has_attachments, false)
      )
      order by candidate.occurred_at desc nulls last, candidate.message_id desc
    ), '[]'::jsonb)
  )
  into v_result
  from candidate_messages as candidate
  left join lateral (
    select
      recipient."CommRecipient_DisplayNameSnapshot" as display_name,
      recipient."CommRecipient_Address" as address
    from public."Comm_MessageRecipients" as recipient
    where recipient."CommRecipient_MessageID" = candidate.message_id
    order by
      case
        when recipient."CommRecipient_ContactID" = any(coalesce(p_contact_ids, '{}'::uuid[])) then 0
        when recipient."CommRecipient_IsExternal" then 1
        else 2
      end,
      recipient."CommRecipient_CreatedAt" asc nulls last,
      recipient."CommRecipient_ID" asc
    limit 1
  ) as selected_recipient on true;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."multideck_crm_customer_recent_emails"("p_user_id" "uuid", "p_account_id" "uuid", "p_contact_ids" "uuid"[], "p_contact_emails" "text"[], "p_include_account_threads" boolean, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_crm_deal_conversion_options"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_context record;
  v_result jsonb;
begin
  select * into v_context from public._multideck_crm_context();

  select jsonb_build_object(
    'opportunityTypes',
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'code', type."CRMOpptyType_Code",
          'name', type."CRMOpptyType_Name",
          'description', type."CRMOpptyType_Description"
        )
        order by type."CRMOpptyType_SortOrder", type."CRMOpptyType_Name"
      ),
      '[]'::jsonb
    )
  )
  into v_result
  from public."sys_CRMOpportunityTypes" type
  where type."CRMOpptyType_IsActive";

  return v_result;
end;
$$;


ALTER FUNCTION "public"."multideck_crm_deal_conversion_options"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_crm_deal_is_visible"("p_deal_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
  select coalesce((
    select public._multideck_crm_deal_is_operator_visible(
      p_deal_id,
      workspace_user."Company_ID"
    )
    from public."cmp_Users" workspace_user
    where workspace_user."Auth_User_ID" = auth.uid()
      and coalesce(workspace_user."User_AccessStatus", 'active') = 'active'
      and public._multideck_crm_has_permission(workspace_user."User_ID", 'CRM.Read')
    limit 1
  ), false)
$$;


ALTER FUNCTION "public"."multideck_crm_deal_is_visible"("p_deal_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_crm_deal_register_page"("p_search" "text" DEFAULT NULL::"text", "p_status_code" "text" DEFAULT NULL::"text", "p_pipeline_id" "uuid" DEFAULT NULL::"uuid", "p_pipeline_stage_id" "uuid" DEFAULT NULL::"uuid", "p_owner_id" "uuid" DEFAULT NULL::"uuid", "p_unassigned" boolean DEFAULT false, "p_open_only" boolean DEFAULT false, "p_sort" "text" DEFAULT 'deal'::"text", "p_direction" "text" DEFAULT 'asc'::"text", "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_context record;
  v_limit integer := greatest(1, least(coalesce(p_limit, 50), 100));
  v_offset integer := greatest(0, coalesce(p_offset, 0));
  v_search text := nullif(btrim(p_search), '');
  v_direction text := case when lower(p_direction) = 'desc' then 'desc' else 'asc' end;
  v_sort text := case
    when p_sort in ('deal', 'company', 'pipeline', 'stage', 'status', 'owner', 'close-date', 'value', 'created') then p_sort
    else 'deal'
  end;
  v_result jsonb;
begin
  select * into v_context from public._multideck_crm_context();
  if not public._multideck_crm_has_permission(v_context.user_id, 'CRM.Read') then
    raise exception 'You do not have permission to view CRM deals.' using errcode = '42501';
  end if;

  with base as materialized (
    select
      deal."CRMOppty_ID" as id,
      deal."CRMOppty_EditVersion" as edit_version,
      deal."CRMOppty_Name" as deal_name,
      coalesce(nullif(btrim(source_lead."CRMLead_CompanyName"), ''), nullif(btrim(organisation."Org_Name"), ''), 'Organisation') as company_name,
      pipeline."CRMPipeline_ID" as pipeline_id,
      pipeline."CRMPipeline_Name" as pipeline_name,
      pipeline_stage."CRMPipelineStage_ID" as pipeline_stage_id,
      pipeline_stage."CRMPipelineStage_Name" as pipeline_stage_name,
      pipeline_stage."CRMPipelineStage_SortOrder" as pipeline_stage_order,
      deal."CRMOppty_StatusCode" as status_code,
      opportunity_status."CRMOpptyStatus_Name" as status_name,
      deal."CRMOppty_OwnerUserID" as owner_id,
      nullif(btrim(concat_ws(' ', owner."User_Firstname", owner."User_Lastname")), '') as owner_name,
      deal."CRMOppty_ExpectedCloseDate" as expected_close_date,
      deal."CRMOppty_ExpectedValueAmount" as expected_value_amount,
      deal."CRMOppty_ProbabilityPct" as probability_pct,
      deal."CRMOppty_CreatedAt" as created_at,
      deal."CRMOppty_WonAt" as won_at,
      deal."CRMOppty_LostAt" as lost_at
    from public."CRM_Opportunities" deal
    join public."CRM_Pipelines" pipeline on pipeline."CRMPipeline_ID" = deal."CRMOppty_PipelineID"
      and pipeline."Company_ID" = v_context.company_id and not pipeline."Is_Deleted"
    join public."CRM_PipelineStages" pipeline_stage on pipeline_stage."CRMPipelineStage_ID" = deal."CRMOppty_PipelineStageID"
      and pipeline_stage."CRMPipeline_ID" = pipeline."CRMPipeline_ID" and not pipeline_stage."Is_Deleted"
    join public."sys_CRMOpportunityStatuses" opportunity_status on opportunity_status."CRMOpptyStatus_Code" = deal."CRMOppty_StatusCode"
    left join public."CRM_Leads" source_lead on source_lead."CRMLead_ID" = deal."CRMOppty_SourceLeadID"
    left join public."Org_Master" organisation on organisation."Org_id" = deal."CRMOppty_OrgID"
    left join public."cmp_Users" owner on owner."User_ID" = deal."CRMOppty_OwnerUserID"
    where public._multideck_crm_deal_is_operator_visible(deal."CRMOppty_ID", v_context.company_id)
  ), filtered as materialized (
    select *
    from base
    where (v_search is null or concat_ws(' ', deal_name, company_name, pipeline_name, pipeline_stage_name, status_name, owner_name) ilike '%' || v_search || '%')
      and (nullif(btrim(p_status_code), '') is null or status_code = p_status_code)
      and (p_pipeline_id is null or pipeline_id = p_pipeline_id)
      and (p_pipeline_stage_id is null or pipeline_stage_id = p_pipeline_stage_id)
      and (p_owner_id is null or owner_id = p_owner_id)
      and (not p_unassigned or owner_id is null)
      and (not p_open_only or (won_at is null and lost_at is null))
  ), ranked as (
    select *, row_number() over (
      order by
        case when v_sort = 'deal' and v_direction = 'asc' then lower(deal_name) end asc nulls last,
        case when v_sort = 'deal' and v_direction = 'desc' then lower(deal_name) end desc nulls last,
        case when v_sort = 'company' and v_direction = 'asc' then lower(company_name) end asc nulls last,
        case when v_sort = 'company' and v_direction = 'desc' then lower(company_name) end desc nulls last,
        case when v_sort = 'pipeline' and v_direction = 'asc' then lower(pipeline_name) end asc nulls last,
        case when v_sort = 'pipeline' and v_direction = 'desc' then lower(pipeline_name) end desc nulls last,
        case when v_sort = 'stage' and v_direction = 'asc' then pipeline_stage_order end asc nulls last,
        case when v_sort = 'stage' and v_direction = 'desc' then pipeline_stage_order end desc nulls last,
        case when v_sort = 'status' and v_direction = 'asc' then lower(status_name) end asc nulls last,
        case when v_sort = 'status' and v_direction = 'desc' then lower(status_name) end desc nulls last,
        case when v_sort = 'owner' and v_direction = 'asc' then lower(owner_name) end asc nulls last,
        case when v_sort = 'owner' and v_direction = 'desc' then lower(owner_name) end desc nulls last,
        case when v_sort = 'close-date' and v_direction = 'asc' then expected_close_date end asc nulls last,
        case when v_sort = 'close-date' and v_direction = 'desc' then expected_close_date end desc nulls last,
        case when v_sort = 'value' and v_direction = 'asc' then expected_value_amount end asc nulls last,
        case when v_sort = 'value' and v_direction = 'desc' then expected_value_amount end desc nulls last,
        case when v_sort = 'created' and v_direction = 'asc' then created_at end asc nulls last,
        case when v_sort = 'created' and v_direction = 'desc' then created_at end desc nulls last,
        lower(deal_name), id
    ) as ordinal
    from filtered
  ), page as (
    select * from ranked
    where ordinal > v_offset and ordinal <= v_offset + v_limit
  )
  select jsonb_build_object(
    'rows', coalesce((select jsonb_agg(
      public._multideck_crm_deal_json(item.id, v_context.company_id)
        || jsonb_build_object('editVersion', item.edit_version)
        || coalesce(public._multideck_crm_deal_conversion_state(item.id), '{}'::jsonb)
      order by item.ordinal
    ) from page item), '[]'::jsonb),
    'total', (select count(*) from filtered),
    'summary', coalesce((select jsonb_build_object(
      'deals', count(*),
      'open', count(*) filter (where won_at is null and lost_at is null),
      'won', count(*) filter (where won_at is not null),
      'lost', count(*) filter (where lost_at is not null),
      'unassigned', count(*) filter (where owner_id is null),
      'pipelineValue', coalesce(sum(expected_value_amount) filter (where won_at is null and lost_at is null), 0),
      'weightedPipelineValue', coalesce(sum(expected_value_amount * coalesce(probability_pct, 0) / 100) filter (where won_at is null and lost_at is null), 0),
      'byStage', coalesce((select jsonb_agg(jsonb_build_object(
        'id', stage_group.pipeline_stage_id,
        'name', stage_group.pipeline_stage_name,
        'count', stage_group.stage_count,
        'value', stage_group.stage_value
      ) order by stage_group.pipeline_stage_order, stage_group.pipeline_stage_name)
      from (
        select pipeline_stage_id, pipeline_stage_name, min(pipeline_stage_order) as pipeline_stage_order,
          count(*) as stage_count,
          coalesce(sum(expected_value_amount), 0) as stage_value
        from filtered
        group by pipeline_stage_id, pipeline_stage_name
      ) stage_group), '[]'::jsonb)
    ) from filtered), '{}'::jsonb),
    'facets', jsonb_build_object(
      'pipelines', coalesce((select jsonb_agg(jsonb_build_object('id', pipeline_id, 'name', pipeline_name) order by pipeline_name) from (select distinct pipeline_id, pipeline_name from base) valueset), '[]'::jsonb),
      'stages', coalesce((select jsonb_agg(jsonb_build_object('id', pipeline_stage_id, 'name', pipeline_stage_name, 'pipelineId', pipeline_id) order by pipeline_stage_order, pipeline_stage_name) from (select distinct pipeline_stage_id, pipeline_stage_name, pipeline_id, pipeline_stage_order from base) valueset), '[]'::jsonb),
      'statuses', coalesce((select jsonb_agg(jsonb_build_object('code', status_code, 'name', status_name) order by status_name) from (select distinct status_code, status_name from base) valueset), '[]'::jsonb),
      'owners', coalesce((select jsonb_agg(jsonb_build_object('id', owner_id, 'name', owner_name) order by owner_name) from (select distinct owner_id, owner_name from base where owner_id is not null and owner_name is not null) valueset), '[]'::jsonb),
      'hasUnassigned', exists(select 1 from base where owner_id is null)
    )
  ) into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."multideck_crm_deal_register_page"("p_search" "text", "p_status_code" "text", "p_pipeline_id" "uuid", "p_pipeline_stage_id" "uuid", "p_owner_id" "uuid", "p_unassigned" boolean, "p_open_only" boolean, "p_sort" "text", "p_direction" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_crm_decide_lead_transfer"("p_request_id" "uuid", "p_decision" "text", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare v_context record; v_request public."CRM_LeadTransferRequests"%rowtype; v_decision text := lower(btrim(coalesce(p_decision, ''))); v_result jsonb;
begin
  select * into v_context from public._multideck_crm_context();
  select * into v_request from public."CRM_LeadTransferRequests" where "CRMLeadTransfer_ID" = p_request_id for update;
  if not found or v_request."Company_ID" <> v_context.company_id then raise exception 'This transfer request was not found.' using errcode = 'P0002'; end if;
  if v_request."CRMLeadTransfer_Status" <> 'pending' then raise exception 'This transfer request has already been decided.' using errcode = '22023'; end if;
  if v_request."CRMLeadTransfer_FromUserID" <> v_context.user_id and not public._multideck_crm_has_permission(v_context.user_id, 'CRM.Leads.Reassign') then
    raise exception 'Only the current owner can decide this request.' using errcode = '42501';
  end if;
  if v_decision = 'approved' then
    return public._multideck_crm_apply_lead_transfer(v_request."CRMLeadTransfer_LeadID", v_request."CRMLeadTransfer_FromUserID", v_request."CRMLeadTransfer_ToUserID", v_context.user_id, v_context.company_id, p_reason, p_request_id);
  elsif v_decision = 'declined' then
    update public."CRM_LeadTransferRequests" set "CRMLeadTransfer_Status" = 'declined', "CRMLeadTransfer_DecisionReason" = nullif(btrim(p_reason), ''),
      "CRMLeadTransfer_DecidedAt" = now(), "CRMLeadTransfer_DecidedBy" = v_context.user_id, "CRMLeadTransfer_UpdatedAt" = now()
    where "CRMLeadTransfer_ID" = p_request_id;
    insert into public."Comm_Notifications" ("CommNotif_UserID", "CommNotif_Title", "CommNotif_Body", "CommNotif_TargetTable", "CommNotif_TargetID", "CommNotif_LinkTypeCode", "CommNotif_MetadataJSON", "CommNotif_CreatedBy")
    values (v_request."CRMLeadTransfer_RequesterUserID", 'Lead ownership request declined', coalesce(nullif(btrim(p_reason), ''), 'The current owner declined the request.'), 'CRM_LeadTransferRequests', p_request_id, null, jsonb_build_object('event', 'lead_transfer_declined'), v_context.user_id);
    return public._multideck_crm_transfer_request_json(p_request_id);
  end if;
  raise exception 'Choose approved or declined.' using errcode = '22023';
end;
$$;


ALTER FUNCTION "public"."multideck_crm_decide_lead_transfer"("p_request_id" "uuid", "p_decision" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_crm_engagement_signals"("p_account_ids" "uuid"[] DEFAULT '{}'::"uuid"[], "p_lead_ids" "uuid"[] DEFAULT '{}'::"uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_context record;
  v_email_allowed boolean := false;
  v_result jsonb;
begin
  select * into v_context from public._multideck_crm_context();

  if cardinality(coalesce(p_account_ids, '{}'::uuid[])) > 0
     and not public._multideck_crm_has_permission(v_context.user_id, 'Customers.Read') then
    raise exception 'You do not have permission to view CRM accounts.' using errcode = '42501';
  end if;

  if cardinality(coalesce(p_lead_ids, '{}'::uuid[])) > 0
     and not public._multideck_crm_has_permission(v_context.user_id, 'CRM.Read') then
    raise exception 'You do not have permission to view CRM leads.' using errcode = '42501';
  end if;

  v_email_allowed := public._multideck_crm_has_permission(v_context.user_id, 'Email.Read');

  with accessible_mailboxes as materialized (
    select mailbox."CommMailbox_ID" as id
    from public."Comm_Mailboxes" mailbox
    where v_email_allowed
      and not mailbox."CommMailbox_IsDeleted"
      and mailbox."CommMailbox_UserID" = v_context.user_id
      and mailbox."CommMailbox_TypeCode" = 'personal'
    union
    select access."CommMailboxAccess_MailboxID"
    from public."Comm_MailboxAccess" access
    join public."Comm_Mailboxes" mailbox
      on mailbox."CommMailbox_ID" = access."CommMailboxAccess_MailboxID"
     and not mailbox."CommMailbox_IsDeleted"
    where v_email_allowed
      and access."CommMailboxAccess_UserID" = v_context.user_id
      and access."CommMailboxAccess_CanRead"
      and access."CommMailboxAccess_RevokedAt" is null
      and (access."CommMailboxAccess_ExpiresAt" is null or access."CommMailboxAccess_ExpiresAt" > now())
  ), account_records as materialized (
    select requested.id, profile."CRMAccount_ID" as profile_id, profile."CRMAccount_LastContactAt" as recorded_last_at
    from unnest(coalesce(p_account_ids, '{}'::uuid[])) requested(id)
    join public.multideck_crm_accessible_account_ids(v_context.company_id) accessible
      on accessible.account_id = requested.id
    left join public."CRM_AccountProfiles" profile
      on profile."CRMAccount_OrgID" = requested.id
     and not profile."CRMAccount_IsDeleted"
  ), lead_records as materialized (
    select
      lead."CRMLead_ID" as id,
      lead."CRMLead_OrgID" as org_id,
      lower(nullif(btrim(lead."CRMLead_Email"), '')) as email,
      lead."CRMLead_LastInteractionAt" as recorded_last_at
    from public."CRM_Leads" lead
    where lead."CRMLead_ID" = any(coalesce(p_lead_ids, '{}'::uuid[]))
      and public._multideck_crm_lead_is_reachable(lead."CRMLead_ID", v_context.company_id)
      and lower(coalesce(lead."CRMLead_MetadataJSON" ->> 'isDemo', 'false')) <> 'true'
  ), account_activity as (
    select
      account.id,
      max(activity."CRMActivity_ActivityAt") as last_at,
      count(*) filter (where activity."CRMActivity_ActivityAt" >= now() - interval '30 days')::integer as count_30d
    from account_records account
    left join public."CRM_Activities" activity
      on activity."CRMActivity_AccountID" = account.profile_id
     and not activity."CRMActivity_IsDeleted"
    group by account.id
  ), lead_activity as (
    select
      lead.id,
      max(activity."CRMActivity_ActivityAt") as last_at,
      count(*) filter (where activity."CRMActivity_ActivityAt" >= now() - interval '30 days')::integer as count_30d
    from lead_records lead
    left join public."CRM_Activities" activity
      on activity."CRMActivity_LeadID" = lead.id
     and not activity."CRMActivity_IsDeleted"
    group by lead.id
  ), account_threads as materialized (
    -- Separate associations let Postgres join once per relation instead of
    -- testing every requested account against every thread.
    select account.id as record_id, thread."CommThread_ID" as thread_id
    from account_records account
    join public."Comm_Threads" thread on thread."CommThread_CustomerOrgID" = account.id
    where v_email_allowed and not thread."CommThread_IsDeleted"
    union
    select account.id, thread."CommThread_ID"
    from account_records account
    join public."Comm_ThreadParticipants" participant on participant."CommThreadPart_OrgID" = account.id
    join public."Comm_Threads" thread on thread."CommThread_ID" = participant."CommThreadPart_ThreadID"
    where v_email_allowed and not thread."CommThread_IsDeleted"
    union
    select account.id, thread."CommThread_ID"
    from account_records account
    join public."Comm_Identities" identity on identity."CommIdentity_OrgID" = account.id and not identity."CommIdentity_IsDeleted"
    join public."Comm_ThreadParticipants" participant on participant."CommThreadPart_IdentityID" = identity."CommIdentity_ID"
    join public."Comm_Threads" thread on thread."CommThread_ID" = participant."CommThreadPart_ThreadID"
    where v_email_allowed and not thread."CommThread_IsDeleted"
  ), lead_threads as materialized (
    select lead.id as record_id, thread."CommThread_ID" as thread_id
    from lead_records lead
    join public."Comm_Threads" thread on thread."CommThread_PrimaryTargetID" = lead.id
    where v_email_allowed and not thread."CommThread_IsDeleted"
    union
    select lead.id, thread."CommThread_ID"
    from lead_records lead
    join public."Comm_Threads" thread on thread."CommThread_CustomerOrgID" = lead.org_id
    where v_email_allowed and not thread."CommThread_IsDeleted"
    union
    select lead.id, thread."CommThread_ID"
    from lead_records lead
    join public."Comm_ThreadParticipants" participant on participant."CommThreadPart_OrgID" = lead.org_id
    join public."Comm_Threads" thread on thread."CommThread_ID" = participant."CommThreadPart_ThreadID"
    where v_email_allowed and not thread."CommThread_IsDeleted"
    union
    select lead.id, thread."CommThread_ID"
    from lead_records lead
    join public."Comm_Identities" identity on identity."CommIdentity_OrgID" = lead.org_id and not identity."CommIdentity_IsDeleted"
    join public."Comm_ThreadParticipants" participant on participant."CommThreadPart_IdentityID" = identity."CommIdentity_ID"
    join public."Comm_Threads" thread on thread."CommThread_ID" = participant."CommThreadPart_ThreadID"
    where v_email_allowed and not thread."CommThread_IsDeleted"
    union
    select lead.id, thread."CommThread_ID"
    from lead_records lead
    join public."Comm_Identities" identity on lower(identity."CommIdentity_NormalizedAddress") = lead.email and not identity."CommIdentity_IsDeleted"
    join public."Comm_ThreadParticipants" participant on participant."CommThreadPart_IdentityID" = identity."CommIdentity_ID"
    join public."Comm_Threads" thread on thread."CommThread_ID" = participant."CommThreadPart_ThreadID"
    where v_email_allowed and not thread."CommThread_IsDeleted"
    union
    select lead.id, thread."CommThread_ID"
    from lead_records lead
    join public."Comm_ThreadParticipants" participant on lower(participant."CommThreadPart_AddressSnapshot") = lead.email
    left join public."Comm_Identities" identity on identity."CommIdentity_ID" = participant."CommThreadPart_IdentityID" and not identity."CommIdentity_IsDeleted"
    join public."Comm_Threads" thread on thread."CommThread_ID" = participant."CommThreadPart_ThreadID"
    where v_email_allowed and not thread."CommThread_IsDeleted"
      and identity."CommIdentity_NormalizedAddress" is null
  ), account_email as (
    select
      link.record_id as id,
      max(coalesce(message."CommMessage_MessageDate", message."CommMessage_ReceivedAt", message."CommMessage_SentAt", message."CommMessage_CreatedAt")) as last_at,
      count(*) filter (
        where coalesce(message."CommMessage_MessageDate", message."CommMessage_ReceivedAt", message."CommMessage_SentAt", message."CommMessage_CreatedAt") >= now() - interval '30 days'
      )::integer as count_30d,
      count(*) filter (
        where message."CommMessage_DirectionCode" = 'inbound'
          and coalesce(message."CommMessage_MessageDate", message."CommMessage_ReceivedAt", message."CommMessage_SentAt", message."CommMessage_CreatedAt") >= now() - interval '30 days'
      )::integer as inbound_count_30d
    from account_threads link
    join public."Comm_Messages" message
      on message."CommMessage_ThreadID" = link.thread_id
     and not message."CommMessage_IsDeleted"
     and message."CommMessage_MailboxID" in (select id from accessible_mailboxes)
    group by link.record_id
  ), lead_email as (
    select
      link.record_id as id,
      max(coalesce(message."CommMessage_MessageDate", message."CommMessage_ReceivedAt", message."CommMessage_SentAt", message."CommMessage_CreatedAt")) as last_at,
      count(*) filter (
        where coalesce(message."CommMessage_MessageDate", message."CommMessage_ReceivedAt", message."CommMessage_SentAt", message."CommMessage_CreatedAt") >= now() - interval '30 days'
      )::integer as count_30d,
      count(*) filter (
        where message."CommMessage_DirectionCode" = 'inbound'
          and coalesce(message."CommMessage_MessageDate", message."CommMessage_ReceivedAt", message."CommMessage_SentAt", message."CommMessage_CreatedAt") >= now() - interval '30 days'
      )::integer as inbound_count_30d
    from lead_threads link
    join public."Comm_Messages" message
      on message."CommMessage_ThreadID" = link.thread_id
     and not message."CommMessage_IsDeleted"
     and message."CommMessage_MailboxID" in (select id from accessible_mailboxes)
    group by link.record_id
  ), raw_signals as (
    select
      'account'::text as record_type,
      account.id as record_id,
      greatest(account.recorded_last_at, activity.last_at, email.last_at) as last_engagement_at,
      coalesce(activity.count_30d, 0) as activity_count_30d,
      coalesce(email.count_30d, 0) as email_count_30d,
      coalesce(email.inbound_count_30d, 0) as inbound_email_count_30d
    from account_records account
    left join account_activity activity on activity.id = account.id
    left join account_email email on email.id = account.id

    union all

    select
      'lead'::text,
      lead.id,
      greatest(lead.recorded_last_at, activity.last_at, email.last_at),
      coalesce(activity.count_30d, 0),
      coalesce(email.count_30d, 0),
      coalesce(email.inbound_count_30d, 0)
    from lead_records lead
    left join lead_activity activity on activity.id = lead.id
    left join lead_email email on email.id = lead.id
  ), scored as (
    select
      signal.*,
      least(100,
        case
          when signal.last_engagement_at >= now() - interval '7 days' then 45
          when signal.last_engagement_at >= now() - interval '30 days' then 25
          when signal.last_engagement_at >= now() - interval '90 days' then 10
          else 0
        end
        + least(signal.activity_count_30d * 10, 30)
        + least(signal.email_count_30d * 5, 20)
        + least(signal.inbound_email_count_30d * 5, 10)
      )::integer as score
    from raw_signals signal
  ), labelled as (
    select
      scored.*,
      case when scored.score >= 70 then 'Hot' when scored.score >= 30 then 'Warm' else 'Cold' end as temperature
    from scored
  )
  select jsonb_build_object(
    'emailAvailable', v_email_allowed,
    'accounts', coalesce((
      select jsonb_agg(jsonb_build_object(
        'recordId', item.record_id,
        'temperature', item.temperature,
        'score', item.score,
        'lastEngagementAt', item.last_engagement_at,
        'activityCount30d', item.activity_count_30d,
        'emailCount30d', item.email_count_30d,
        'inboundEmailCount30d', item.inbound_email_count_30d
      ) order by item.record_id)
      from labelled item where item.record_type = 'account'
    ), '[]'::jsonb),
    'leads', coalesce((
      select jsonb_agg(jsonb_build_object(
        'recordId', item.record_id,
        'temperature', item.temperature,
        'score', item.score,
        'lastEngagementAt', item.last_engagement_at,
        'activityCount30d', item.activity_count_30d,
        'emailCount30d', item.email_count_30d,
        'inboundEmailCount30d', item.inbound_email_count_30d
      ) order by item.record_id)
      from labelled item where item.record_type = 'lead'
    ), '[]'::jsonb)
  ) into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."multideck_crm_engagement_signals"("p_account_ids" "uuid"[], "p_lead_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."multideck_crm_engagement_signals"("p_account_ids" "uuid"[], "p_lead_ids" "uuid"[]) IS 'Permission-aware CRM register roll-up of recent CRM activity and connected email exchanges.';



CREATE OR REPLACE FUNCTION "public"."multideck_crm_get_dashboard"("p_inactivity_days" integer DEFAULT 90, "p_area" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_context record;
  v_result jsonb;
  v_summary jsonb;
  v_pipeline jsonb;
  v_activity jsonb;
  v_open_deals bigint;
  v_pipeline_value numeric;
  v_currency_code text;
begin
  select * into v_context from public._multideck_crm_context();
  v_result := public._multideck_crm_get_dashboard_unfiltered_deals_20260818(
    p_inactivity_days,
    p_area
  );

  with visible_deals as (
    select
      opportunity.*,
      stage."CRMPipelineStage_Name" as pipeline_stage_name,
      stage."CRMPipelineStage_SortOrder" as pipeline_stage_order,
      pipeline."CRMPipeline_Name" as pipeline_name
    from public."CRM_Opportunities" opportunity
    join public."CRM_Pipelines" pipeline
      on pipeline."CRMPipeline_ID" = opportunity."CRMOppty_PipelineID"
     and pipeline."Company_ID" = v_context.company_id
     and not pipeline."Is_Deleted"
    join public."CRM_PipelineStages" stage
      on stage."CRMPipelineStage_ID" = opportunity."CRMOppty_PipelineStageID"
     and stage."CRMPipeline_ID" = pipeline."CRMPipeline_ID"
     and not stage."Is_Deleted"
    where public._multideck_crm_deal_is_operator_visible(
      opportunity."CRMOppty_ID",
      v_context.company_id
    )
  ), open_deals as (
    select * from visible_deals
    where "CRMOppty_WonAt" is null and "CRMOppty_LostAt" is null
  )
  select
    count(*),
    coalesce(sum("CRMOppty_ExpectedValueAmount"), 0),
    coalesce((
      select nullif(btrim(recent."CRMOppty_CurrencyCode"), '')
      from open_deals recent
      where recent."CRMOppty_ExpectedValueAmount" is not null
      order by recent."CRMOppty_CreatedAt" desc
      limit 1
    ), 'GBP')
  into v_open_deals, v_pipeline_value, v_currency_code
  from open_deals;

  with visible_deals as (
    select
      opportunity.*,
      stage."CRMPipelineStage_Name" as pipeline_stage_name,
      stage."CRMPipelineStage_SortOrder" as pipeline_stage_order,
      pipeline."CRMPipeline_Name" as pipeline_name
    from public."CRM_Opportunities" opportunity
    join public."CRM_Pipelines" pipeline
      on pipeline."CRMPipeline_ID" = opportunity."CRMOppty_PipelineID"
     and pipeline."Company_ID" = v_context.company_id
     and not pipeline."Is_Deleted"
    join public."CRM_PipelineStages" stage
      on stage."CRMPipelineStage_ID" = opportunity."CRMOppty_PipelineStageID"
     and stage."CRMPipeline_ID" = pipeline."CRMPipeline_ID"
     and not stage."Is_Deleted"
    where opportunity."CRMOppty_WonAt" is null
      and opportunity."CRMOppty_LostAt" is null
      and public._multideck_crm_deal_is_operator_visible(
        opportunity."CRMOppty_ID",
        v_context.company_id
      )
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'stageId', grouped.pipeline_stage_id,
    'stage', grouped.pipeline_stage_name,
    'pipeline', grouped.pipeline_name,
    'count', grouped.deal_count,
    'value', grouped.deal_value,
    'currencyCode', grouped.currency_code
  ) order by grouped.stage_order), '[]'::jsonb)
  into v_pipeline
  from (
    select
      "CRMOppty_PipelineStageID" as pipeline_stage_id,
      pipeline_stage_name,
      pipeline_name,
      min("CRMOppty_CurrencyCode") as currency_code,
      count(*) as deal_count,
      coalesce(sum("CRMOppty_ExpectedValueAmount"), 0) as deal_value,
      min(pipeline_stage_order) as stage_order
    from visible_deals
    group by "CRMOppty_PipelineStageID", pipeline_stage_name, pipeline_name
  ) grouped;

  select coalesce(jsonb_agg(entry.item order by entry.ordinal), '[]'::jsonb)
  into v_activity
  from jsonb_array_elements(coalesce(v_result -> 'activity', '[]'::jsonb))
    with ordinality entry(item, ordinal)
  where (
      nullif(entry.item ->> 'dealId', '') is null
      or public._multideck_crm_deal_is_operator_visible(
        (entry.item ->> 'dealId')::uuid,
        v_context.company_id
      )
    )
    and (
      nullif(entry.item ->> 'leadId', '') is null
      or public._multideck_crm_lead_is_reachable(
        (entry.item ->> 'leadId')::uuid,
        v_context.company_id
      )
    );

  v_summary := coalesce(v_result -> 'summary', '{}'::jsonb)
    || jsonb_build_object(
      'openDeals', v_open_deals,
      'pipelineValue', v_pipeline_value,
      'currencyCode', v_currency_code
    );

  return v_result || jsonb_build_object(
    'summary', v_summary,
    'pipeline', v_pipeline,
    'activity', v_activity
  );
end;
$$;


ALTER FUNCTION "public"."multideck_crm_get_dashboard"("p_inactivity_days" integer, "p_area" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_crm_get_deal_essential"("p_deal_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_context record;
  v_result jsonb;
begin
  select * into v_context from public._multideck_crm_context();
  if not public._multideck_crm_has_permission(v_context.user_id, 'CRM.Read') then
    raise exception 'You do not have permission to view CRM deals.' using errcode = '42501';
  end if;
  if not public._multideck_crm_deal_is_operator_visible(p_deal_id, v_context.company_id) then
    raise exception 'Deal not found.' using errcode = 'P0002';
  end if;
  select public._multideck_crm_deal_json(p_deal_id, v_context.company_id)
    || jsonb_build_object('editVersion', deal."CRMOppty_EditVersion")
    || coalesce(public._multideck_crm_deal_conversion_state(p_deal_id), '{}'::jsonb)
    into v_result
  from public."CRM_Opportunities" deal
  where deal."CRMOppty_ID" = p_deal_id;
  return v_result;
end;
$$;


ALTER FUNCTION "public"."multideck_crm_get_deal_essential"("p_deal_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_crm_get_follow_up_opportunities"("p_area" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $_$
declare
  v_context record;
  v_area text := nullif(lower(btrim(coalesce(p_area, ''))), '');
  v_result jsonb;
begin
  select * into v_context from public._multideck_crm_context();

  with accessible_mailboxes as materialized (
    select mailbox."CommMailbox_ID" as mailbox_id, lower(btrim(mailbox."CommMailbox_Address")) as mailbox_address
    from public."Comm_Mailboxes" mailbox
    where not mailbox."CommMailbox_IsDeleted"
      and mailbox."CommMailbox_UserID" = v_context.user_id
      and mailbox."CommMailbox_TypeCode" = 'personal'
    union
    select access."CommMailboxAccess_MailboxID", lower(btrim(mailbox."CommMailbox_Address"))
    from public."Comm_MailboxAccess" access
    join public."Comm_Mailboxes" mailbox on mailbox."CommMailbox_ID" = access."CommMailboxAccess_MailboxID" and not mailbox."CommMailbox_IsDeleted"
    where access."CommMailboxAccess_UserID" = v_context.user_id
      and access."CommMailboxAccess_CanRead"
      and access."CommMailboxAccess_RevokedAt" is null
      and (access."CommMailboxAccess_ExpiresAt" is null or access."CommMailboxAccess_ExpiresAt" > now())
  ), meaningful_messages as materialized (
    select
      message."CommMessage_ID",
      message."CommMessage_ThreadID",
      message."CommMessage_MailboxID",
      message."CommMessage_Subject",
      message."CommMessage_BodyPreview",
      message."CommMessage_IsInbound",
      coalesce(message."CommMessage_MessageDate", message."CommMessage_ReceivedAt", message."CommMessage_SentAt", message."CommMessage_CreatedAt") as occurred_at
    from public."Comm_Messages" message
    where message."CommMessage_MailboxID" in (select mailbox_id from accessible_mailboxes)
      and message."CommMessage_ChannelCode" = 'email'
      and not message."CommMessage_IsDeleted"
      and not message."CommMessage_IsDraft"
      and not message."CommMessage_IsSpam"
      and coalesce(message."CommMessage_MessageDate", message."CommMessage_ReceivedAt", message."CommMessage_SentAt", message."CommMessage_CreatedAt") >= now() - interval '21 days'
      and lower(coalesce(message."CommMessage_Subject", '')) !~ '(newsletter|daily digest|weekly digest|monthly digest|unsubscribe|promotional|special offer|webinar|event reminder|automatic reply|out of office|undeliverable|delivery status notification|failure notice|mail delivery failed|password reset|verification code|support ticket|ticket #[0-9]|zoho desk)'
      and lower(coalesce(message."CommMessage_HeaderJSON", '{}'::jsonb)::text) not like '%list-unsubscribe%'
  ), thread_rollup as materialized (
    select
      thread_id,
      max(occurred_at) as latest_at,
      max(occurred_at) filter (where is_inbound) as last_inbound_at,
      max(occurred_at) filter (where not is_inbound) as last_outbound_at
    from (
      select
        message."CommMessage_ThreadID" as thread_id,
        message.occurred_at,
        message."CommMessage_IsInbound" as is_inbound
      from meaningful_messages message
    ) rows
    group by thread_id
  ), latest_messages as materialized (
    select distinct on (message."CommMessage_ThreadID")
      message."CommMessage_ThreadID" as thread_id,
      message."CommMessage_ID" as message_id,
      message."CommMessage_MailboxID" as mailbox_id,
      message."CommMessage_Subject" as subject,
      message."CommMessage_BodyPreview" as preview,
      message."CommMessage_IsInbound" as is_inbound,
      message.occurred_at
    from meaningful_messages message
    order by message."CommMessage_ThreadID", message.occurred_at desc, message."CommMessage_ID" desc
  ), outbound_counts as materialized (
    select
      message."CommMessage_ThreadID" as thread_id,
      count(*)::integer as outbound_since_reply
    from meaningful_messages message
    join thread_rollup rollup on rollup.thread_id = message."CommMessage_ThreadID"
    where not message."CommMessage_IsInbound"
      and (rollup.last_inbound_at is null or message.occurred_at > rollup.last_inbound_at)
    group by message."CommMessage_ThreadID"
  ), email_threads as materialized (
    select
      latest.thread_id,
      latest.message_id,
      latest.mailbox_id,
      latest.subject,
      latest.preview,
      latest.is_inbound,
      latest.occurred_at,
      party.email,
      party.display_name,
      party.contact_id,
      party.org_id,
      rollup.last_inbound_at,
      rollup.last_outbound_at,
      coalesce(outbound.outbound_since_reply, 0) as outbound_since_reply
    from latest_messages latest
    join thread_rollup rollup on rollup.thread_id = latest.thread_id
    left join outbound_counts outbound on outbound.thread_id = latest.thread_id
    join lateral (
      select
        lower(btrim(recipient."CommRecipient_NormalizedAddress")) as email,
        nullif(btrim(recipient."CommRecipient_DisplayNameSnapshot"), '') as display_name,
        recipient."CommRecipient_ContactID" as contact_id,
        recipient."CommRecipient_OrgID" as org_id
      from public."Comm_MessageRecipients" recipient
      where recipient."CommRecipient_MessageID" = latest.message_id
        and recipient."CommRecipient_IsExternal"
        and (
          (latest.is_inbound and recipient."CommRecipient_RecipientTypeCode" = 'from')
          or (not latest.is_inbound and recipient."CommRecipient_RecipientTypeCode" in ('to', 'cc'))
        )
      order by case when recipient."CommRecipient_RecipientTypeCode" in ('from', 'to') then 0 else 1 end,
        recipient."CommRecipient_CreatedAt"
      limit 1
    ) party on true
    where party.email <> ''
      and split_part(party.email, '@', 1) !~ '^(no-?reply|do-?not-?reply|mailer-daemon|postmaster|notifications?|newsletters?|marketing|support|tickets?)$'
      and not exists (
        select 1 from accessible_mailboxes own_mailbox
        where split_part(own_mailbox.mailbox_address, '@', 2) <> ''
          and split_part(own_mailbox.mailbox_address, '@', 2) not in (
            'gmail.com', 'googlemail.com', 'outlook.com', 'hotmail.com', 'live.com',
            'icloud.com', 'me.com', 'yahoo.com', 'proton.me', 'protonmail.com'
          )
          and split_part(own_mailbox.mailbox_address, '@', 2) = split_part(party.email, '@', 2)
      )
      and lower(coalesce(latest.subject, '') || ' ' || coalesce(latest.preview, '')) !~ '((^|[^a-z])ooo([^a-z]|$)|out of (the )?office|automatic reply|auto.?reply|office closed|currently away|annual leave|returning on|mailbox is unattended|has not been forwarded|reacted via gmail|delivery status|undeliverable|failure notice|mail delivery failed|your receipt|subscription|booking reminder|password|verification code|security alert|confirm your email|support ticket|ticket #[0-9]|zoho desk|not at this time|not interested|no thank(s| you)|remove me|stop emailing|this is my final note|my last email|should i close this out|should i move on)'
      and (
        (latest.is_inbound and rollup.last_outbound_at is not null and latest.occurred_at > rollup.last_outbound_at)
        or (
          not latest.is_inbound
          and (
            (rollup.last_inbound_at is null and latest.occurred_at <= now() - interval '3 days')
            or (rollup.last_inbound_at is not null and latest.occurred_at > rollup.last_inbound_at and latest.occurred_at <= now() - interval '3 days')
          )
        )
      )
  ), matched_email_threads as materialized (
    select
      email.*,
      lead."CRMLead_ID" as lead_id,
      lead."CRMLead_CompanyName" as lead_company_name,
      lead."CRMLead_PersonName" as lead_person_name,
      lead_status."CRMLeadStatus_Name" as lead_status_name,
      contact."OrgContact_ID" as matched_contact_id,
      nullif(btrim(concat_ws(' ', contact."OrgContact_FirstName", contact."OrgContact_LastName")), '') as contact_name,
      organisation."Org_id" as matched_org_id,
      organisation."Org_Name" as organisation_name,
      account."CRMAccount_ID" as account_id,
      coalesce(address.area_key, '') as area_key,
      coalesce(address.area_label, '') as area_label
    from email_threads email
    left join lateral (
      select candidate.*
      from public."CRM_Leads" candidate
      join public."sys_CRMLeadStatuses" candidate_status
        on candidate_status."CRMLeadStatus_Code" = candidate."CRMLead_StatusCode"
       and candidate_status."CRMLeadStatus_IsOpen"
      where not candidate."CRMLead_IsDeleted"
        and candidate."CRMLead_OwnerUserID" = v_context.user_id
        and lower(btrim(candidate."CRMLead_Email")) = email.email
      order by candidate."CRMLead_UpdatedAt" desc
      limit 1
    ) lead on true
    left join public."sys_CRMLeadStatuses" lead_status on lead_status."CRMLeadStatus_Code" = lead."CRMLead_StatusCode"
    left join lateral (
      select contact_row.*
      from public."OrgContact_Emails" contact_email
      join public."Org_Contacts" contact_row on contact_row."OrgContact_ID" = contact_email."OrgContact_ID"
      where lower(btrim(contact_email."OrgContactEmail_Email")) = email.email
      order by contact_email."OrgContactEmail_Type", contact_email."OrgContactEmail_ID"
      limit 1
    ) contact on true
    left join public."Org_Master" organisation
      on organisation."Org_id" = coalesce(contact."Org_ID", email.org_id, lead."CRMLead_OrgID")
    left join public."CRM_AccountProfiles" account
      on account."CRMAccount_OrgID" = organisation."Org_id"
     and not account."CRMAccount_IsDeleted"
     and (account."CRMAccount_OwnerUserID" is null or account."CRMAccount_OwnerUserID" = v_context.user_id)
    left join lateral (
      select
        lower(nullif(concat_ws('|', nullif(btrim(a."OrgAdd_TownCity"), ''), nullif(btrim(a."OrgAdd_CountyState"), ''),
          nullif(split_part(btrim(a."OrgAdd_PostZipCode"), ' ', 1), ''), nullif(upper(btrim(a."OrgAdd_Country")), '')), '')) as area_key,
        nullif(concat_ws(' · ', nullif(btrim(a."OrgAdd_TownCity"), ''), nullif(btrim(a."OrgAdd_CountyState"), ''),
          nullif(split_part(btrim(a."OrgAdd_PostZipCode"), ' ', 1), ''), nullif(upper(btrim(a."OrgAdd_Country")), '')), '') as area_label
      from public."Org_Addresses" a
      where a."Org_ID" = organisation."Org_id"
      order by a."OrgAdd_ID"
      limit 1
    ) address on true
  ), email_opportunities_raw as (
    select jsonb_build_object(
      'id', 'email:' || thread_id::text,
      'source', 'email',
      'threadId', thread_id,
      'mailboxId', mailbox_id,
      'recordType', case when lead_id is not null then 'lead' when matched_contact_id is not null then 'contact' when account_id is not null then 'account' else 'unmatched' end,
      'recordId', coalesce(lead_id, matched_contact_id, account_id),
      'companyName', coalesce(nullif(btrim(lead_company_name), ''), organisation_name),
      'personName', coalesce(nullif(btrim(lead_person_name), ''), contact_name, display_name),
      'email', email,
      'subject', coalesce(nullif(btrim(subject), ''), 'No subject'),
      'context', nullif(btrim(preview), ''),
      'lastActivityAt', occurred_at,
      'lastDirection', case when is_inbound then 'inbound' else 'outbound' end,
      'reasonCode', case
        when is_inbound then 'reply_due'
        when outbound_since_reply >= 2 and occurred_at <= now() - interval '5 days' then 'second_follow_up'
        else 'first_follow_up'
      end,
      'dueAt', case
        when is_inbound then occurred_at
        when outbound_since_reply >= 2 then occurred_at + interval '5 days'
        else occurred_at + interval '3 days'
      end,
      'daysWaiting', greatest(0, floor(extract(epoch from (now() - occurred_at)) / 86400)::integer),
      'stage', coalesce(lead_status_name, case when matched_contact_id is not null then 'Contact' when account_id is not null then 'Account' else 'Not in CRM' end),
      'location', nullif(area_label, ''),
      'canCreate', lead_id is null and matched_contact_id is null and account_id is null,
      'outboundAttempts', outbound_since_reply
    ) as item,
    case when is_inbound then 0 when outbound_since_reply >= 2 then 1 else 2 end as priority,
    occurred_at as sort_at
    from matched_email_threads
    where (v_area is null or area_key = v_area or (area_key = '' and lead_id is null and matched_contact_id is null and account_id is null))
      and (is_inbound or outbound_since_reply <= 2)
  ), email_opportunities as (
    select item, priority, sort_at
    from (
      select raw.*,
        row_number() over (
          partition by lower(raw.item->>'email'),
            regexp_replace(lower(raw.item->>'subject'), '^(re|fw|fwd):[[:space:]]*', ''),
            raw.item->>'reasonCode'
          order by raw.sort_at desc
        ) as duplicate_rank
      from email_opportunities_raw raw
    ) ranked
    where duplicate_rank = 1
  ), activity_leads as materialized (
    select
      lead.*,
      status."CRMLeadStatus_Name" as status_name,
      coalesce(nullif(btrim(lead."CRMLead_CompanyName"), ''), organisation."Org_Name", nullif(btrim(lead."CRMLead_PersonName"), ''), 'Unnamed lead') as company_name,
      coalesce(nullif(btrim(lead."CRMLead_PersonName"), ''), nullif(btrim(concat_ws(' ', contact."OrgContact_FirstName", contact."OrgContact_LastName")), '')) as person_name,
      coalesce(nullif(btrim(lead."CRMLead_Email"), ''), contact_email.email) as email,
      greatest(lead."CRMLead_LastInteractionAt", latest_activity.activity_at) as last_activity_at,
      latest_activity.subject as activity_subject,
      coalesce(address.area_key, '') as area_key,
      address.area_label
    from public."CRM_Leads" lead
    join public."sys_CRMLeadStatuses" status on status."CRMLeadStatus_Code" = lead."CRMLead_StatusCode" and status."CRMLeadStatus_IsOpen"
    left join public."Org_Master" organisation on organisation."Org_id" = lead."CRMLead_OrgID"
    left join public."Org_Contacts" contact on contact."OrgContact_ID" = lead."CRMLead_PrimaryContactID"
    left join lateral (
      select lower(btrim(row."OrgContactEmail_Email")) as email
      from public."OrgContact_Emails" row
      where row."OrgContact_ID" = contact."OrgContact_ID"
      order by row."OrgContactEmail_Type", row."OrgContactEmail_ID" limit 1
    ) contact_email on true
    left join lateral (
      select activity."CRMActivity_ActivityAt" as activity_at, activity."CRMActivity_Subject" as subject
      from public."CRM_Activities" activity
      where activity."CRMActivity_LeadID" = lead."CRMLead_ID" and not activity."CRMActivity_IsDeleted"
      order by activity."CRMActivity_ActivityAt" desc limit 1
    ) latest_activity on true
    left join lateral (
      select
        lower(nullif(concat_ws('|', nullif(btrim(a."OrgAdd_TownCity"), ''), nullif(btrim(a."OrgAdd_CountyState"), ''),
          nullif(split_part(btrim(a."OrgAdd_PostZipCode"), ' ', 1), ''), nullif(upper(btrim(a."OrgAdd_Country")), '')), '')) as area_key,
        nullif(concat_ws(' · ', nullif(btrim(a."OrgAdd_TownCity"), ''), nullif(btrim(a."OrgAdd_CountyState"), ''),
          nullif(split_part(btrim(a."OrgAdd_PostZipCode"), ' ', 1), ''), nullif(upper(btrim(a."OrgAdd_Country")), '')), '') as area_label
      from public."Org_Addresses" a where a."Org_ID" = lead."CRMLead_OrgID" order by a."OrgAdd_ID" limit 1
    ) address on true
    where lead."CRMLead_OwnerUserID" = v_context.user_id and not lead."CRMLead_IsDeleted"
      and (
        lead."CRMLead_NextActionDueAt" <= now()
        or (lead."CRMLead_NextActionDueAt" is null and coalesce(greatest(lead."CRMLead_LastInteractionAt", latest_activity.activity_at), lead."CRMLead_CreatedAt") <= now() - interval '3 days')
      )
  ), activity_opportunities as (
    select jsonb_build_object(
      'id', 'lead:' || lead."CRMLead_ID"::text,
      'source', 'activity',
      'threadId', null,
      'mailboxId', null,
      'recordType', 'lead',
      'recordId', lead."CRMLead_ID",
      'companyName', lead.company_name,
      'personName', lead.person_name,
      'email', lead.email,
      'subject', coalesce(lead.activity_subject, 'CRM follow-up due'),
      'context', coalesce(nullif(btrim(lead."CRMLead_TradeLane"), ''), nullif(btrim(lead."CRMLead_ServiceInterest"), '')),
      'lastActivityAt', coalesce(lead.last_activity_at, lead."CRMLead_CreatedAt"),
      'lastDirection', null,
      'reasonCode', case when lead.last_activity_at is null then 'never_contacted' else 'scheduled_due' end,
      'dueAt', coalesce(lead."CRMLead_NextActionDueAt", coalesce(lead.last_activity_at, lead."CRMLead_CreatedAt") + interval '3 days'),
      'daysWaiting', greatest(0, floor(extract(epoch from (now() - coalesce(lead.last_activity_at, lead."CRMLead_CreatedAt"))) / 86400)::integer),
      'stage', lead.status_name,
      'location', lead.area_label,
      'canCreate', false,
      'outboundAttempts', 0
    ) as item,
    3 as priority,
    coalesce(lead."CRMLead_NextActionDueAt", lead.last_activity_at, lead."CRMLead_CreatedAt") as sort_at
    from activity_leads lead
    where (v_area is null or lead.area_key = v_area)
      and not exists (
        select 1 from matched_email_threads email
        where email.lead_id = lead."CRMLead_ID"
      )
  ), all_opportunities as (
    select * from email_opportunities
    union all
    select * from activity_opportunities
  ), prioritised_opportunities as materialized (
    select * from all_opportunities
    order by priority, sort_at asc
    limit 50
  )
  select jsonb_build_object(
    'generatedAt', now(),
    'cadence', jsonb_build_object('firstFollowUpDays', 3, 'secondFollowUpDays', 5),
    'summary', jsonb_build_object(
      'total', count(*),
      'repliesDue', count(*) filter (where item->>'reasonCode' = 'reply_due'),
      'awaitingReply', count(*) filter (where item->>'reasonCode' in ('first_follow_up', 'second_follow_up')),
      'notInCrm', count(*) filter (where (item->>'canCreate')::boolean)
    ),
    'items', coalesce(jsonb_agg(item order by priority, sort_at asc), '[]'::jsonb)
  ) into v_result
  from prioritised_opportunities;

  return v_result;
end;
$_$;


ALTER FUNCTION "public"."multideck_crm_get_follow_up_opportunities"("p_area" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."multideck_crm_get_follow_up_opportunities"("p_area" "text") IS 'Deterministic CRM dashboard worklist over authorised mailbox and CRM activity. Dexter reads the same source domains separately; this composed dashboard view is not an additional Dexter data capability.';



CREATE OR REPLACE FUNCTION "public"."multideck_crm_get_lead"("p_lead_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_context record;
  v_lead record;
  v_summary jsonb;
  v_company jsonb;
  v_contacts jsonb;
  v_activities jsonb;
begin
  select * into v_context from public._multideck_crm_context();

  select * into v_lead
  from public."CRM_Leads"
  where "CRMLead_ID" = p_lead_id and not "CRMLead_IsDeleted";

  if not found then
    raise exception 'Lead not found.' using errcode = 'P0002';
  end if;

  v_summary := public._multideck_crm_lead_json(p_lead_id);

  select jsonb_build_object(
    'organisationId', v_lead."CRMLead_OrgID",
    'email', coalesce(
      address."OrgAdd_MainEmail",
      v_lead."CRMLead_MetadataJSON" ->> 'companyEmail',
      v_lead."CRMLead_MetadataJSON" ->> 'organisationEmail'
    ),
    'website', coalesce(
      v_lead."CRMLead_MetadataJSON" ->> 'companyWebsite',
      v_lead."CRMLead_MetadataJSON" ->> 'website',
      v_lead."CRMLead_MetadataJSON" ->> 'websiteUrl'
    ),
    'phone', coalesce(
      address."OrgAdd_MainPhone",
      v_lead."CRMLead_MetadataJSON" ->> 'companyPhone',
      v_lead."CRMLead_MetadataJSON" ->> 'organisationPhone'
    ),
    'address', coalesce(
      nullif(concat_ws(', ',
        nullif(btrim(address."Org_NameOverride"), ''),
        nullif(btrim(address."OrgAdd_Line1"), ''),
        nullif(btrim(address."OrgAdd_Line2"), ''),
        nullif(btrim(concat_ws(' ',
          address."OrgAdd_TownCity",
          address."OrgAdd_CountyState",
          address."OrgAdd_PostZipCode"
        )), ''),
        nullif(btrim(address."OrgAdd_Country"), '')
      ), ''),
      v_lead."CRMLead_MetadataJSON" ->> 'companyAddress',
      v_lead."CRMLead_MetadataJSON" ->> 'address'
    )
  )
  into v_company
  from (select 1) seed
  left join lateral (
    select a.*
    from public."Org_Addresses" a
    where a."Org_ID" = v_lead."CRMLead_OrgID"
    order by (a."OrgAdd_MainEmail" is not null) desc, a."OrgAdd_ID"
    limit 1
  ) address on true;

  with linked_contacts as (
    select
      contact."OrgContact_ID" as id,
      nullif(btrim(concat_ws(' ', contact."OrgContact_FirstName", contact."OrgContact_LastName")), '') as name,
      profile."CRMContact_RoleCode" as role_code,
      email.email,
      phone.phone,
      contact."OrgContact_ID" = v_lead."CRMLead_PrimaryContactID" as is_primary,
      coalesce(
        profile."CRMContact_LastContactAt",
        case when contact."OrgContact_ID" = v_lead."CRMLead_PrimaryContactID"
          then (v_summary ->> 'lastActivityAt')::timestamptz
        end
      ) as last_contact_at
    from public."Org_Contacts" contact
    left join public."CRM_ContactProfiles" profile
      on profile."CRMContact_OrgContactID" = contact."OrgContact_ID"
    left join lateral (
      select nullif(btrim(e."OrgContactEmail_Email"), '') as email
      from public."OrgContact_Emails" e
      where e."OrgContact_ID" = contact."OrgContact_ID"
      order by e."OrgContactEmail_Type", e."OrgContactEmail_ID"
      limit 1
    ) email on true
    left join lateral (
      select nullif(btrim(i."CommIdentity_Address"), '') as phone
      from public."Comm_Identities" i
      where i."CommIdentity_ContactID" = contact."OrgContact_ID"
        and not i."CommIdentity_IsDeleted"
        and i."CommIdentity_ChannelCode" in ('phone', 'sms', 'whatsapp')
      order by coalesce(i."CommIdentity_LastSeenAt", i."CommIdentity_UpdatedAt") desc
      limit 1
    ) phone on true
    where contact."Org_ID" = v_lead."CRMLead_OrgID"
  ),
  contact_rows as (
    select * from linked_contacts
    union all
    select
      coalesce(v_lead."CRMLead_PrimaryContactID", v_lead."CRMLead_ID") as id,
      nullif(btrim(v_lead."CRMLead_PersonName"), '') as name,
      null::varchar as role_code,
      nullif(btrim(v_lead."CRMLead_Email"), '') as email,
      nullif(btrim(v_lead."CRMLead_Phone"), '') as phone,
      true as is_primary,
      (v_summary ->> 'lastActivityAt')::timestamptz as last_contact_at
    where (
      nullif(btrim(v_lead."CRMLead_PersonName"), '') is not null
      or nullif(btrim(v_lead."CRMLead_Email"), '') is not null
      or nullif(btrim(v_lead."CRMLead_Phone"), '') is not null
    )
    and not exists (
      select 1
      from linked_contacts existing
      where existing.id = v_lead."CRMLead_PrimaryContactID"
         or (
           existing.email is not null
           and lower(existing.email) = lower(nullif(btrim(v_lead."CRMLead_Email"), ''))
         )
    )
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', id,
        'name', name,
        'initials', public._multideck_crm_initials(coalesce(name, email, '?')),
        'roleCode', role_code,
        'email', email,
        'phone', phone,
        'isPrimary', is_primary,
        'lastContactAt', last_contact_at
      )
      order by is_primary desc, name nulls last
    ),
    '[]'::jsonb
  )
  into v_contacts
  from contact_rows;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', activity."CRMActivity_ID",
        'typeCode', activity."CRMActivity_ActivityTypeCode",
        'subject', activity."CRMActivity_Subject",
        'summary', nullif(btrim(activity."CRMActivity_Summary"), ''),
        'activityAt', activity."CRMActivity_ActivityAt"
      )
      order by activity."CRMActivity_ActivityAt" desc
    ),
    '[]'::jsonb
  )
  into v_activities
  from (
    select *
    from public."CRM_Activities"
    where "CRMActivity_LeadID" = p_lead_id
      and not "CRMActivity_IsDeleted"
    order by "CRMActivity_ActivityAt" desc
    limit 8
  ) activity;

  return v_summary || jsonb_build_object(
    'company', v_company,
    'contacts', v_contacts,
    'activities', v_activities
  );
end;
$$;


ALTER FUNCTION "public"."multideck_crm_get_lead"("p_lead_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_crm_get_lead_essential"("p_lead_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
