CREATE OR REPLACE FUNCTION "public"."multideck_crm_move_deal_stage"("p_deal_id" "uuid", "p_pipeline_id" "uuid", "p_pipeline_stage_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare ctx record;
begin
  select * into ctx from public._multideck_crm_context();
  if not exists(select 1 from public."cmp_Users" where "User_ID"=ctx.user_id and "Company_ID"=ctx.company_id and "User_AccessStatus"='active')
    or public._multideck_crm_has_permission(ctx.user_id,'CRM.Write') is not true then
    raise exception 'You do not have permission to move deals.' using errcode='42501';end if;
  if not public._multideck_crm_deal_is_operator_visible(p_deal_id,ctx.company_id) then
    raise exception 'Deal not found.' using errcode='P0002';end if;
  return public._multideck_crm_move_deal_stage_unfiltered_20260818(p_deal_id,p_pipeline_id,p_pipeline_stage_id);
end $$;


ALTER FUNCTION "public"."multideck_crm_move_deal_stage"("p_deal_id" "uuid", "p_pipeline_id" "uuid", "p_pipeline_stage_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_crm_mutate_pipeline_settings"("p_action" "text", "p_id" "uuid" DEFAULT NULL::"uuid", "p_payload" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_context record;
  v_action text := lower(btrim(coalesce(p_action, '')));
  v_now timestamptz := now();
  v_name text;
  v_owner text;
  v_automation text;
  v_stages jsonb;
  v_stage jsonb;
  v_stage_id uuid;
  v_pipeline_id uuid;
  v_field_id uuid;
  v_sort_order integer;
  v_options jsonb;
  v_active_options jsonb;
  v_type text;
  v_result jsonb;
  v_ids uuid[];
begin
  select * into v_context from public._multideck_crm_context();
  perform public._multideck_crm_require_settings_manage(v_context.user_id);

  if v_action in ('create_pipeline', 'save_pipeline') then
    if jsonb_typeof(p_payload) is distinct from 'object' then
      raise exception 'Pipeline details are required.' using errcode = '22023';
    end if;

    v_name := btrim(coalesce(p_payload->>'name', ''));
    v_owner := nullif(btrim(coalesce(p_payload->>'owner', '')), '');
    v_automation := nullif(btrim(coalesce(p_payload->>'automation', '')), '');
    v_stages := coalesce(p_payload->'stages', '[]'::jsonb);

    if v_name = '' then
      raise exception 'Give the pipeline a name before saving.' using errcode = '22023';
    end if;
    if jsonb_typeof(v_stages) is distinct from 'array' or jsonb_array_length(v_stages) = 0 then
      raise exception 'A pipeline needs at least one stage.' using errcode = '22023';
    end if;
    if jsonb_array_length(v_stages) > 24 then
      raise exception 'A pipeline can hold up to 24 stages.' using errcode = '22023';
    end if;
    if exists (
      select 1 from jsonb_array_elements(v_stages) stage
      where btrim(coalesce(stage->>'name', '')) = ''
    ) then
      raise exception 'Every stage needs a name.' using errcode = '22023';
    end if;
    if exists (
      select 1
      from jsonb_array_elements(v_stages) stage
      group by lower(btrim(stage->>'name'))
      having count(*) > 1
    ) then
      raise exception 'A stage name is used more than once.' using errcode = '22023';
    end if;
    if exists (
      select 1 from jsonb_array_elements(v_stages) stage
      where lower(coalesce(stage->>'tone', '')) not in ('green', 'amber', 'red', 'blue', 'neutral', 'teal')
    ) then
      raise exception 'Choose a supported stage colour.' using errcode = '22023';
    end if;
    if exists (
      select 1 from jsonb_array_elements(v_stages) stage
      where coalesce((stage->>'probability')::numeric, 0) < 0
         or coalesce((stage->>'probability')::numeric, 0) > 100
    ) then
      raise exception 'Win probability must be between 0 and 100.' using errcode = '22023';
    end if;
    if (
      select count(*) from jsonb_array_elements(v_stages) stage
      where coalesce((stage->>'isDefaultEntry')::boolean, false)
    ) > 1 then
      raise exception 'Only one stage can be the default entry point.' using errcode = '22023';
    end if;
    if (
      select count(*) from jsonb_array_elements(v_stages) stage
      where coalesce((stage->>'isConversion')::boolean, false)
    ) > 1 then
      raise exception 'Only one stage can be the conversion trigger.' using errcode = '22023';
    end if;

    if exists (
      select 1
      from public."CRM_Pipelines" pipeline
      where pipeline."Company_ID" = v_context.company_id
        and not pipeline."Is_Deleted"
        and lower(pipeline."CRMPipeline_Name") = lower(v_name)
        and (v_action = 'create_pipeline' or pipeline."CRMPipeline_ID" <> p_id)
    ) then
      raise exception 'Another pipeline already uses that name.' using errcode = '23505';
    end if;

    if v_action = 'create_pipeline' then
      if (
        select count(*)
        from public."CRM_Pipelines" pipeline
        where pipeline."Company_ID" = v_context.company_id
          and not pipeline."Is_Deleted"
      ) >= 24 then
        raise exception 'A workspace can hold up to 24 pipelines.' using errcode = '22023';
      end if;

      select coalesce(max(pipeline."CRMPipeline_SortOrder") + 1, 0)
      into v_sort_order
      from public."CRM_Pipelines" pipeline
      where pipeline."Company_ID" = v_context.company_id
        and not pipeline."Is_Deleted";

      v_pipeline_id := gen_random_uuid();
      insert into public."CRM_Pipelines" (
        "CRMPipeline_ID", "Company_ID", "CRMPipeline_Name", "CRMPipeline_Owner",
        "CRMPipeline_Automation", "CRMPipeline_SortOrder", "Created_At", "Updated_At",
        "Created_By_User_ID", "Updated_By_User_ID", "Is_Deleted"
      ) values (
        v_pipeline_id, v_context.company_id, v_name, v_owner, v_automation, v_sort_order,
        v_now, v_now, v_context.user_id, v_context.user_id, false
      );
    else
      select pipeline."CRMPipeline_ID"
      into v_pipeline_id
      from public."CRM_Pipelines" pipeline
      where pipeline."CRMPipeline_ID" = p_id
        and pipeline."Company_ID" = v_context.company_id
        and not pipeline."Is_Deleted"
      for update;

      if v_pipeline_id is null then
        raise exception 'That pipeline no longer exists.' using errcode = 'P0002';
      end if;

      if exists (
        select 1
        from jsonb_array_elements(v_stages) stage
        where nullif(stage->>'id', '') is not null
          and not exists (
            select 1
            from public."CRM_PipelineStages" existing
            where existing."CRMPipelineStage_ID" = (stage->>'id')::uuid
              and existing."CRMPipeline_ID" = v_pipeline_id
              and existing."Company_ID" = v_context.company_id
              and not existing."Is_Deleted"
          )
      ) then
        raise exception 'A pipeline stage changed while you were editing. Reload and try again.' using errcode = '55000';
      end if;

      update public."CRM_PipelineStages" stage
      set
        "CRMPipelineStage_Name" = stage."CRMPipelineStage_ID"::text,
        "CRMPipelineStage_IsDefaultEntry" = false,
        "CRMPipelineStage_IsConversion" = false,
        "Is_Deleted" = not exists (
          select 1
          from jsonb_array_elements(v_stages) incoming
          where nullif(incoming->>'id', '')::uuid = stage."CRMPipelineStage_ID"
        ),
        "Updated_At" = v_now
      where stage."CRMPipeline_ID" = v_pipeline_id
        and stage."Company_ID" = v_context.company_id
        and not stage."Is_Deleted";

      update public."CRM_Pipelines"
      set
        "CRMPipeline_Name" = v_name,
        "CRMPipeline_Owner" = v_owner,
        "CRMPipeline_Automation" = v_automation,
        "Updated_At" = v_now,
        "Updated_By_User_ID" = v_context.user_id
      where "CRMPipeline_ID" = v_pipeline_id;
    end if;

    v_sort_order := 0;
    for v_stage in select value from jsonb_array_elements(v_stages)
    loop
      v_stage_id := nullif(v_stage->>'id', '')::uuid;

      if v_stage_id is null then
        v_stage_id := gen_random_uuid();
        insert into public."CRM_PipelineStages" (
          "CRMPipelineStage_ID", "Company_ID", "CRMPipeline_ID", "CRMPipelineStage_Name",
          "CRMPipelineStage_Tone", "CRMPipelineStage_EntryRule",
          "CRMPipelineStage_ProbabilityPct", "CRMPipelineStage_SortOrder",
          "CRMPipelineStage_IsDefaultEntry", "CRMPipelineStage_IsConversion",
          "Created_At", "Updated_At", "Is_Deleted"
        ) values (
          v_stage_id, v_context.company_id, v_pipeline_id, btrim(v_stage->>'name'),
          lower(v_stage->>'tone'), nullif(btrim(coalesce(v_stage->>'rule', '')), ''),
          round(coalesce((v_stage->>'probability')::numeric, 0), 2), v_sort_order,
          coalesce((v_stage->>'isDefaultEntry')::boolean, false),
          coalesce((v_stage->>'isConversion')::boolean, false),
          v_now, v_now, false
        );
      else
        update public."CRM_PipelineStages"
        set
          "CRMPipelineStage_Name" = btrim(v_stage->>'name'),
          "CRMPipelineStage_Tone" = lower(v_stage->>'tone'),
          "CRMPipelineStage_EntryRule" = nullif(btrim(coalesce(v_stage->>'rule', '')), ''),
          "CRMPipelineStage_ProbabilityPct" = round(coalesce((v_stage->>'probability')::numeric, 0), 2),
          "CRMPipelineStage_SortOrder" = v_sort_order,
          "CRMPipelineStage_IsDefaultEntry" = coalesce((v_stage->>'isDefaultEntry')::boolean, false),
          "CRMPipelineStage_IsConversion" = coalesce((v_stage->>'isConversion')::boolean, false),
          "Updated_At" = v_now,
          "Is_Deleted" = false
        where "CRMPipelineStage_ID" = v_stage_id
          and "CRMPipeline_ID" = v_pipeline_id
          and "Company_ID" = v_context.company_id;
      end if;

      v_sort_order := v_sort_order + 1;
    end loop;

    return public._multideck_crm_pipeline_json(v_pipeline_id, v_context.company_id);
  end if;

  if v_action = 'delete_pipeline' then
    update public."CRM_Pipelines"
    set
      "Is_Deleted" = true,
      "Updated_At" = v_now,
      "Updated_By_User_ID" = v_context.user_id
    where "CRMPipeline_ID" = p_id
      and "Company_ID" = v_context.company_id
      and not "Is_Deleted"
    returning "CRMPipeline_ID" into v_pipeline_id;

    if v_pipeline_id is null then
      raise exception 'That pipeline no longer exists.' using errcode = 'P0002';
    end if;

    update public."CRM_PipelineStages"
    set "Is_Deleted" = true, "Updated_At" = v_now
    where "CRMPipeline_ID" = v_pipeline_id
      and "Company_ID" = v_context.company_id
      and not "Is_Deleted";

    return null;
  end if;

  if v_action = 'reorder_pipelines' then
    if jsonb_typeof(p_payload) is distinct from 'array' then
      raise exception 'The complete pipeline order is required.' using errcode = '22023';
    end if;

    select coalesce(array_agg((item.value #>> '{}')::uuid order by item.ordinality), '{}'::uuid[])
    into v_ids
    from jsonb_array_elements(p_payload) with ordinality item(value, ordinality);

    if cardinality(v_ids) <> (
      select count(*) from public."CRM_Pipelines"
      where "Company_ID" = v_context.company_id and not "Is_Deleted"
    ) or cardinality(v_ids) <> (
      select count(distinct id) from unnest(v_ids) id
    ) or exists (
      select 1 from unnest(v_ids) id
      where not exists (
        select 1 from public."CRM_Pipelines"
        where "CRMPipeline_ID" = id
          and "Company_ID" = v_context.company_id
          and not "Is_Deleted"
      )
    ) then
      raise exception 'The pipeline list changed while you were reordering. Reload and try again.' using errcode = '55000';
    end if;

    update public."CRM_Pipelines" pipeline
    set
      "CRMPipeline_SortOrder" = ordered.ordinality - 1,
      "Updated_At" = v_now,
      "Updated_By_User_ID" = v_context.user_id
    from unnest(v_ids) with ordinality ordered(id, ordinality)
    where pipeline."CRMPipeline_ID" = ordered.id;

    select coalesce(
      jsonb_agg(public._multideck_crm_pipeline_json(id, v_context.company_id) order by ordinality),
      '[]'::jsonb
    )
    into v_result
    from unnest(v_ids) with ordinality ordered(id, ordinality);

    return v_result;
  end if;

  if v_action in ('create_field', 'save_field') then
    if jsonb_typeof(p_payload) is distinct from 'object' then
      raise exception 'Lead field details are required.' using errcode = '22023';
    end if;

    if v_action = 'save_field' then
      select field."CRMLeadField_ID", field."CRMLeadField_Label", field."CRMLeadField_TypeCode",
        field."CRMLeadField_OptionsJSON"
      into v_field_id, v_name, v_type, v_options
      from public."CRM_LeadFieldSettings" field
      where field."CRMLeadField_ID" = p_id
        and field."Company_ID" = v_context.company_id
        and not field."Is_Deleted"
      for update;

      if v_field_id is null then
        raise exception 'That lead field no longer exists.' using errcode = 'P0002';
      end if;
    else
      v_name := '';
      v_type := '';
      v_options := '[]'::jsonb;
    end if;

    if p_payload ? 'label' then v_name := btrim(coalesce(p_payload->>'label', '')); end if;
    if p_payload ? 'type' then v_type := btrim(coalesce(p_payload->>'type', '')); end if;
    if p_payload ? 'options' then v_options := coalesce(p_payload->'options', '[]'::jsonb); end if;
    v_active_options := coalesce(p_payload->'activeOptions', '[]'::jsonb);

    if v_name = '' then
      raise exception 'Give the field a name before saving.' using errcode = '22023';
    end if;
    if lower(v_type) = 'dropdown' then
      v_type := 'Dropdown';
    elsif lower(v_type) = 'multi-select dropdown' then
      v_type := 'Multi-select dropdown';
    else
      raise exception 'Choose a supported field type.' using errcode = '22023';
    end if;
    if jsonb_typeof(v_options) is distinct from 'array' or jsonb_array_length(v_options) = 0 then
      raise exception 'Give the field at least one option.' using errcode = '22023';
    end if;
    if jsonb_array_length(v_options) > 40 then
      raise exception 'A field can hold up to 40 options.' using errcode = '22023';
    end if;
    if jsonb_typeof(v_active_options) is distinct from 'array' then
      raise exception 'Selected options must be a list.' using errcode = '22023';
    end if;
    if exists (
      select 1
      from jsonb_array_elements_text(v_active_options) active(value)
      where not exists (
        select 1 from jsonb_array_elements_text(v_options) option(value)
        where lower(btrim(option.value)) = lower(btrim(active.value))
      )
    ) then
      raise exception 'A selected value is not an option on this field.' using errcode = '22023';
    end if;
    if exists (
      select 1
      from public."CRM_LeadFieldSettings" field
      where field."Company_ID" = v_context.company_id
        and not field."Is_Deleted"
        and lower(field."CRMLeadField_Label") = lower(v_name)
        and (v_action = 'create_field' or field."CRMLeadField_ID" <> p_id)
    ) then
      raise exception 'Another lead field already uses that name.' using errcode = '23505';
    end if;

    if v_action = 'create_field' then
      if (
        select count(*) from public."CRM_LeadFieldSettings"
        where "Company_ID" = v_context.company_id and not "Is_Deleted"
      ) >= 40 then
        raise exception 'A workspace can hold up to 40 lead fields.' using errcode = '22023';
      end if;

      select coalesce(max(field."CRMLeadField_SortOrder") + 1, 0)
      into v_sort_order
      from public."CRM_LeadFieldSettings" field
      where field."Company_ID" = v_context.company_id
        and not field."Is_Deleted";

      v_field_id := gen_random_uuid();
      insert into public."CRM_LeadFieldSettings" (
        "CRMLeadField_ID", "Company_ID", "CRMLeadField_Label", "CRMLeadField_TypeCode",
        "CRMLeadField_OptionsJSON", "CRMLeadField_ActiveOptionsJSON", "CRMLeadField_SortOrder",
        "Created_At", "Updated_At", "Updated_By_User_ID", "Is_Deleted"
      ) values (
        v_field_id, v_context.company_id, v_name, v_type, v_options, v_active_options,
        v_sort_order, v_now, v_now, v_context.user_id, false
      );
    else
      update public."CRM_LeadFieldSettings"
      set
        "CRMLeadField_Label" = v_name,
        "CRMLeadField_TypeCode" = v_type,
        "CRMLeadField_OptionsJSON" = v_options,
        "CRMLeadField_ActiveOptionsJSON" = v_active_options,
        "Updated_At" = v_now,
        "Updated_By_User_ID" = v_context.user_id
      where "CRMLeadField_ID" = v_field_id;
    end if;

    return public._multideck_crm_lead_field_json(v_field_id, v_context.company_id);
  end if;

  if v_action = 'delete_field' then
    update public."CRM_LeadFieldSettings"
    set
      "Is_Deleted" = true,
      "Updated_At" = v_now,
      "Updated_By_User_ID" = v_context.user_id
    where "CRMLeadField_ID" = p_id
      and "Company_ID" = v_context.company_id
      and not "Is_Deleted"
    returning "CRMLeadField_ID" into v_field_id;

    if v_field_id is null then
      raise exception 'That lead field no longer exists.' using errcode = 'P0002';
    end if;

    return null;
  end if;

  if v_action = 'reorder_fields' then
    if jsonb_typeof(p_payload) is distinct from 'array' then
      raise exception 'The complete field order is required.' using errcode = '22023';
    end if;

    select coalesce(array_agg((item.value #>> '{}')::uuid order by item.ordinality), '{}'::uuid[])
    into v_ids
    from jsonb_array_elements(p_payload) with ordinality item(value, ordinality);

    if cardinality(v_ids) <> (
      select count(*) from public."CRM_LeadFieldSettings"
      where "Company_ID" = v_context.company_id and not "Is_Deleted"
    ) or cardinality(v_ids) <> (
      select count(distinct id) from unnest(v_ids) id
    ) or exists (
      select 1 from unnest(v_ids) id
      where not exists (
        select 1 from public."CRM_LeadFieldSettings"
        where "CRMLeadField_ID" = id
          and "Company_ID" = v_context.company_id
          and not "Is_Deleted"
      )
    ) then
      raise exception 'The field list changed while you were reordering. Reload and try again.' using errcode = '55000';
    end if;

    update public."CRM_LeadFieldSettings" field
    set
      "CRMLeadField_SortOrder" = ordered.ordinality - 1,
      "Updated_At" = v_now,
      "Updated_By_User_ID" = v_context.user_id
    from unnest(v_ids) with ordinality ordered(id, ordinality)
    where field."CRMLeadField_ID" = ordered.id;

    select coalesce(
      jsonb_agg(public._multideck_crm_lead_field_json(id, v_context.company_id) order by ordinality),
      '[]'::jsonb
    )
    into v_result
    from unnest(v_ids) with ordinality ordered(id, ordinality);

    return v_result;
  end if;

  raise exception 'That CRM settings action is not supported.' using errcode = '22023';
end;
$$;


ALTER FUNCTION "public"."multideck_crm_mutate_pipeline_settings"("p_action" "text", "p_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_crm_organisation_address_options"("p_org_id" "uuid", "p_capability_code" "text" DEFAULT NULL::"text", "p_at" timestamp with time zone DEFAULT "now"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_context record;
  v_items jsonb;
begin
  select * into v_context from public._multideck_crm_context();
  if not public._multideck_crm_has_permission(v_context.user_id, 'Customers.Read')
    or not public.multideck_crm_company_can_access_account(v_context.company_id, p_org_id) then
    raise exception 'You do not have permission to view this organisation.' using errcode = '42501';
  end if;
  select coalesce(jsonb_agg(item.value order by item.sort_default desc, item.sort_label), '[]'::jsonb)
  into v_items
  from (
    select jsonb_build_object(
      'id', address."OrgAdd_ID",
      'name', coalesce(nullif(btrim(address."Org_NameOverride"), ''), nullif(btrim(address."OrgAdd_Line1"), ''), 'Address'),
      'line1', address."OrgAdd_Line1", 'line2', address."OrgAdd_Line2",
      'townCity', address."OrgAdd_TownCity", 'countyState', address."OrgAdd_CountyState",
      'postZipCode', address."OrgAdd_PostZipCode", 'countryCode', address."OrgAdd_Country",
      'unlocode', address."OrgAdd_UNLOCODE", 'timeZone', address."OrgAdd_TimeZone",
      'capabilities', capability.values,
      'isDefault', coalesce(capability.is_default, false),
      'isOpenAt', case
        when override_state.has_override then override_state.is_open
        else exists (
          select 1 from public."Org_AddressOpeningHours" hours
          where hours."OrgAddHours_OrgAddID" = address."OrgAdd_ID"
            and hours."OrgAddHours_DayOfWeek" = extract(dow from (p_at at time zone address."OrgAdd_TimeZone"))::integer
            and (p_at at time zone address."OrgAdd_TimeZone")::time >= hours."OrgAddHours_OpensAt"
            and (p_at at time zone address."OrgAdd_TimeZone")::time < hours."OrgAddHours_ClosesAt"
        )
      end
    ) value,
    coalesce(capability.is_default, false) sort_default,
    lower(coalesce(address."Org_NameOverride", address."OrgAdd_Line1", address."OrgAdd_TownCity", '')) sort_label
    from public."Org_Addresses" address
    join lateral (
      select
        coalesce(jsonb_agg(jsonb_build_object(
          'code', type."sys_AddressType_Code", 'name', type."sys_AddressType_Description",
          'isDefault', link."OrgAddType_IsDefault"
        ) order by type."sys_AddressType_SortOrder"), '[]'::jsonb) values,
        bool_or(link."OrgAddType_IsDefault" and (p_capability_code is null or type."sys_AddressType_Code" = lower(btrim(p_capability_code)))) is_default,
        bool_or(p_capability_code is null or type."sys_AddressType_Code" = lower(btrim(p_capability_code))) matches
      from public."Org_AddressTypes" link
      join public."sys_AddressTypes" type on type."sys_AddressType_ID" = link."OrgAddType_Type"
      where link."OrgAdd_ID" = address."OrgAdd_ID" and type."sys_AddressType_IsActive"
    ) capability on capability.matches
    left join lateral (
      select true has_override,
        bool_or(not override."OrgAddOverride_IsClosed"
          and (p_at at time zone address."OrgAdd_TimeZone")::time >= override."OrgAddOverride_OpensAt"
          and (p_at at time zone address."OrgAdd_TimeZone")::time < override."OrgAddOverride_ClosesAt") is_open
      from public."Org_AddressOpeningOverrides" override
      where override."OrgAddOverride_OrgAddID" = address."OrgAdd_ID"
        and override."OrgAddOverride_Date" = (p_at at time zone address."OrgAdd_TimeZone")::date
      having count(*) > 0
    ) override_state on true
    where address."Org_ID" = p_org_id and address."OrgAdd_IsActive"
  ) item;
  return jsonb_build_object('organisationId', p_org_id, 'capabilityCode', nullif(lower(btrim(p_capability_code)), ''), 'at', p_at, 'items', v_items);
end;
$$;


ALTER FUNCTION "public"."multideck_crm_organisation_address_options"("p_org_id" "uuid", "p_capability_code" "text", "p_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_crm_organisation_register_page"("p_organisation_type" "text" DEFAULT 'company'::"text", "p_search" "text" DEFAULT NULL::"text", "p_marketing_scope" "text" DEFAULT NULL::"text", "p_relationship" "text" DEFAULT NULL::"text", "p_owner_id" "uuid" DEFAULT NULL::"uuid", "p_unassigned" boolean DEFAULT false, "p_filter_query" "jsonb" DEFAULT NULL::"jsonb", "p_sort" "text" DEFAULT 'account'::"text", "p_direction" "text" DEFAULT 'asc'::"text", "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_context record;
  v_organisation_type text := lower(coalesce(nullif(btrim(p_organisation_type), ''), 'company'));
  v_limit integer := greatest(1, least(coalesce(p_limit, 50), 100));
  v_offset integer := greatest(0, coalesce(p_offset, 0));
  v_search text := nullif(btrim(p_search), '');
  v_direction text := case when lower(p_direction) = 'desc' then 'desc' else 'asc' end;
  v_result jsonb;
begin
  if v_organisation_type not in ('company', 'customer', 'supplier') then
    raise exception 'Choose companies, customers or suppliers.' using errcode = '22023';
  end if;

  select * into v_context from public._multideck_crm_context();
  if not public._multideck_crm_has_permission(v_context.user_id, 'Customers.Read') then
    raise exception 'You do not have permission to view CRM organisations.' using errcode = '42501';
  end if;

  with base as materialized (
    select
      org."Org_id" as id,
      coalesce(org."Org_Name", '') as name,
      coalesce(profile."CRMAccount_RelationshipStatusCode", org."Org_CRMRelationshipStatusCode", 'active_customer') as relationship_status,
      profile."CRMAccount_OwnerUserID" as owner_id,
      nullif(btrim(concat_ws(' ', owner."User_Firstname", owner."User_Lastname")), '') as owner_name,
      profile."CRMAccount_Vertical" as industry,
      profile."CRMAccount_HealthScore" as health_score,
      profile."CRMAccount_LastContactAt" as last_contact_at,
      profile."CRMAccount_NextActionDueAt" as next_action_due_at,
      coalesce(org."Org_MarketingOptIn", false) as marketing_opt_in,
      coalesce(contact_count.value, 0)::integer as contact_count,
      concat_ws(', ', address."OrgAdd_TownCity", address."OrgAdd_Country") as location,
      jsonb_build_object(
        'any', jsonb_build_array(
          org."Org_Name", org."Org_AccCode", profile."CRMAccount_Vertical", owner_name.value,
          coalesce(profile."CRMAccount_RelationshipStatusCode", org."Org_CRMRelationshipStatusCode"),
          address_search.values, contact_search.names, contact_search.emails, organisation_types.names
        ),
        'name', org."Org_Name",
        'accountCode', org."Org_AccCode",
        'organisationTypes', organisation_types.names,
        'address', address_search.values,
        'country', address_search.countries,
        'contact', contact_search.names,
        'contactEmail', contact_search.emails,
        'owner', owner_name.value,
        'relationship', coalesce(profile."CRMAccount_RelationshipStatusCode", org."Org_CRMRelationshipStatusCode"),
        'lastContactAt', profile."CRMAccount_LastContactAt"
      ) as filter_fields
    from public.multideck_crm_accessible_account_ids(v_context.company_id) accessible
    join public."Org_Master" org on org."Org_id" = accessible.account_id
    left join public."CRM_AccountProfiles" profile
      on profile."CRMAccount_OrgID" = org."Org_id"
     and not profile."CRMAccount_IsDeleted"
    left join public."cmp_Users" owner on owner."User_ID" = profile."CRMAccount_OwnerUserID"
    left join lateral (
      select nullif(btrim(concat_ws(' ', owner."User_Firstname", owner."User_Lastname")), '') as value
    ) owner_name on true
    left join lateral (
      select coalesce(jsonb_agg(type."OrgType_Name" order by type."OrgType_Name"), '[]'::jsonb) as names
      from public."Org_Master_Type" link
      join public."Org_Types" type on type."OrgType_ID" = link."OrgType_ID"
      where link."Org_ID" = org."Org_id"
    ) organisation_types on true
    left join lateral (
      select count(*)::integer as value
      from public."Org_Contacts" contact
      where contact."Org_ID" = org."Org_id"
    ) contact_count on true
    left join lateral (
      select item."OrgAdd_TownCity", item."OrgAdd_Country"
      from public."Org_Addresses" item
      where item."Org_ID" = org."Org_id"
        and item."OrgAdd_IsActive"
      limit 1
    ) address on true
    left join lateral (
      select
        coalesce(jsonb_agg(concat_ws(', ', item."OrgAdd_Line1", item."OrgAdd_Line2", item."OrgAdd_TownCity", item."OrgAdd_CountyState", item."OrgAdd_PostZipCode", item."OrgAdd_Country")), '[]'::jsonb) as values,
        coalesce(jsonb_agg(distinct item."OrgAdd_Country") filter (where item."OrgAdd_Country" is not null), '[]'::jsonb) as countries
      from public."Org_Addresses" item
      where item."Org_ID" = org."Org_id"
        and item."OrgAdd_IsActive"
    ) address_search on true
    left join lateral (
      select
        coalesce(jsonb_agg(distinct nullif(btrim(concat_ws(' ', contact."OrgContact_FirstName", contact."OrgContact_LastName")), '')) filter (where nullif(btrim(concat_ws(' ', contact."OrgContact_FirstName", contact."OrgContact_LastName")), '') is not null), '[]'::jsonb) as names,
        coalesce(jsonb_agg(distinct email."OrgContactEmail_Email") filter (where email."OrgContactEmail_Email" is not null), '[]'::jsonb) as emails
      from public."Org_Contacts" contact
      left join public."OrgContact_Emails" email on email."OrgContact_ID" = contact."OrgContact_ID"
      where contact."Org_ID" = org."Org_id"
    ) contact_search on true
    where v_organisation_type = 'company'
       or exists (
         select 1
         from public."Org_Master_Type" link
         join public."Org_Types" type on type."OrgType_ID" = link."OrgType_ID"
         where link."Org_ID" = org."Org_id"
           and lower(type."OrgType_Name") = v_organisation_type
       )
       or (
         v_organisation_type = 'customer'
         and coalesce(org."Org_CRMIsPotentialCustomer", false)
       )
  ), filtered as materialized (
    select *
    from base
    where (v_search is null or concat_ws(' ', name, location, industry, owner_name, relationship_status) ilike '%' || v_search || '%')
      and (p_marketing_scope is null or p_marketing_scope = 'all'
        or (p_marketing_scope = 'opted_in' and marketing_opt_in)
        or (p_marketing_scope = 'opted_out' and not marketing_opt_in))
      and (nullif(btrim(p_relationship), '') is null or relationship_status = p_relationship)
      and (not p_unassigned or owner_id is null)
      and (p_owner_id is null or owner_id = p_owner_id)
      and (p_filter_query is null or public.multideck_register_filter_matches(filter_fields, p_filter_query))
  ), ranked as (
    select id, row_number() over (
      order by
        case when p_sort = 'account' and v_direction = 'asc' then lower(name) end asc,
        case when p_sort = 'account' and v_direction = 'desc' then lower(name) end desc,
        case when p_sort = 'relationship' and v_direction = 'asc' then lower(relationship_status) end asc,
        case when p_sort = 'relationship' and v_direction = 'desc' then lower(relationship_status) end desc,
        case when p_sort = 'owner' and v_direction = 'asc' then lower(owner_name) end asc nulls last,
        case when p_sort = 'owner' and v_direction = 'desc' then lower(owner_name) end desc nulls last,
        case when p_sort = 'last-contact' and v_direction = 'asc' then last_contact_at end asc nulls last,
        case when p_sort = 'last-contact' and v_direction = 'desc' then last_contact_at end desc nulls last,
        case when p_sort = 'contacts' and v_direction = 'asc' then contact_count end asc,
        case when p_sort = 'contacts' and v_direction = 'desc' then contact_count end desc,
        case when p_sort = 'marketing' and v_direction = 'asc' then marketing_opt_in::integer end asc,
        case when p_sort = 'marketing' and v_direction = 'desc' then marketing_opt_in::integer end desc,
        lower(name), id
    ) as ordinal
    from filtered
  ), page as (
    select id, ordinal from ranked
    where ordinal > v_offset and ordinal <= v_offset + v_limit
  )
  select jsonb_build_object(
    'ids', coalesce((select jsonb_agg(id order by ordinal) from page), '[]'::jsonb),
    'total', (select count(*) from filtered),
    'summary', coalesce((select jsonb_build_object(
      'accounts', count(*),
      'contacts', coalesce(sum(contact_count), 0),
      'needsAttention', count(*) filter (where next_action_due_at is not null and next_action_due_at <= now()),
      'marketingOptedIn', count(*) filter (where marketing_opt_in),
      'unassigned', count(*) filter (where owner_id is null),
      'healthy', count(*) filter (where health_score >= 70)
    ) from base), '{}'::jsonb),
    'facets', jsonb_build_object(
      'relationships', coalesce((select jsonb_agg(value order by value) from (select distinct relationship_status as value from base where relationship_status is not null) valueset), '[]'::jsonb),
      'owners', coalesce((select jsonb_agg(jsonb_build_object('id', owner_id, 'name', owner_name) order by owner_name) from (select distinct owner_id, owner_name from base where owner_id is not null and owner_name is not null) ownerset), '[]'::jsonb),
      'hasUnassigned', exists(select 1 from base where owner_id is null)
    )
  ) into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."multideck_crm_organisation_register_page"("p_organisation_type" "text", "p_search" "text", "p_marketing_scope" "text", "p_relationship" "text", "p_owner_id" "uuid", "p_unassigned" boolean, "p_filter_query" "jsonb", "p_sort" "text", "p_direction" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_crm_pipeline_settings"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_context record;
  v_pipelines jsonb;
  v_fields jsonb;
begin
  select * into v_context from public._multideck_crm_context();

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', pipeline."CRMPipeline_ID",
        'name', pipeline."CRMPipeline_Name",
        'owner', coalesce(pipeline."CRMPipeline_Owner", ''),
        'automation', coalesce(pipeline."CRMPipeline_Automation", ''),
        'sortOrder', pipeline."CRMPipeline_SortOrder",
        'defaultStage', coalesce(
          (
            select stage."CRMPipelineStage_Name"
            from public."CRM_PipelineStages" stage
            where stage."CRMPipeline_ID" = pipeline."CRMPipeline_ID"
              and not stage."Is_Deleted"
            order by stage."CRMPipelineStage_IsDefaultEntry" desc, stage."CRMPipelineStage_SortOrder"
            limit 1
          ),
          ''
        ),
        'conversionStage', coalesce(
          (
            select stage."CRMPipelineStage_Name"
            from public."CRM_PipelineStages" stage
            where stage."CRMPipeline_ID" = pipeline."CRMPipeline_ID"
              and not stage."Is_Deleted"
            order by stage."CRMPipelineStage_IsConversion" desc, stage."CRMPipelineStage_SortOrder" desc
            limit 1
          ),
          ''
        ),
        'stages', coalesce(
          (
            select jsonb_agg(
              jsonb_build_object(
                'id', stage."CRMPipelineStage_ID",
                'name', stage."CRMPipelineStage_Name",
                'tone', stage."CRMPipelineStage_Tone",
                'rule', coalesce(stage."CRMPipelineStage_EntryRule", ''),
                'probability', stage."CRMPipelineStage_ProbabilityPct",
                'sortOrder', stage."CRMPipelineStage_SortOrder",
                'isDefaultEntry', stage."CRMPipelineStage_IsDefaultEntry",
                'isConversion', stage."CRMPipelineStage_IsConversion"
              )
              order by stage."CRMPipelineStage_SortOrder"
            )
            from public."CRM_PipelineStages" stage
            where stage."CRMPipeline_ID" = pipeline."CRMPipeline_ID"
              and not stage."Is_Deleted"
          ),
          '[]'::jsonb
        )
      )
      order by pipeline."CRMPipeline_SortOrder", pipeline."CRMPipeline_Name"
    ),
    '[]'::jsonb
  )
  into v_pipelines
  from public."CRM_Pipelines" pipeline
  where pipeline."Company_ID" = v_context.company_id
    and not pipeline."Is_Deleted";

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', field."CRMLeadField_ID",
        'label', field."CRMLeadField_Label",
        'type', field."CRMLeadField_TypeCode",
        'options', coalesce(field."CRMLeadField_OptionsJSON", '[]'::jsonb),
        'activeOptions', coalesce(field."CRMLeadField_ActiveOptionsJSON", '[]'::jsonb),
        'sortOrder', field."CRMLeadField_SortOrder"
      )
      order by field."CRMLeadField_SortOrder", field."CRMLeadField_Label"
    ),
    '[]'::jsonb
  )
  into v_fields
  from public."CRM_LeadFieldSettings" field
  where field."Company_ID" = v_context.company_id
    and not field."Is_Deleted";

  return jsonb_build_object('pipelines', v_pipelines, 'fields', v_fields);
end;
$$;


ALTER FUNCTION "public"."multideck_crm_pipeline_settings"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_crm_replace_account_operations"("p_actor_user_id" "uuid", "p_org_id" "uuid", "p_expected_version" bigint, "p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_profile public."CRM_AccountProfiles"%rowtype;
  v_item jsonb;
  v_address uuid;
  v_instruction_address uuid;
  v_instruction_contact uuid;
  v_source_document uuid;
  v_old_signal jsonb;
  v_new_signal jsonb;
begin
  perform public._multideck_crm_write_actor(p_actor_user_id);
  perform public._multideck_crm_require_account_access(p_actor_user_id, p_org_id);
  select * into v_profile from public."CRM_AccountProfiles"
  where "CRMAccount_OrgID" = p_org_id and not "CRMAccount_IsDeleted" order by "CRMAccount_ID" limit 1 for update;
  if not found then raise exception 'Account not found.' using errcode = 'P0002'; end if;
  if p_expected_version is null or p_expected_version <> v_profile."CRMAccount_EditVersion" then
    raise exception 'CRM_CONFLICT:This account changed since it was loaded.' using errcode = 'P0001';
  end if;
  select jsonb_build_object(
    'roleProfiles',coalesce((select md5("CRMAccountOps_RoleProfilesJSON"::text) from public."CRM_AccountOperationalProfiles" where "CRMAccountOps_AccountID"=v_profile."CRMAccount_ID"),''),
    'invoicePreferences',coalesce((select md5("CRMAccountOps_InvoicePreferencesJSON"::text) from public."CRM_AccountOperationalProfiles" where "CRMAccountOps_AccountID"=v_profile."CRMAccount_ID"),''),
    'customs',coalesce((select md5("CRMAccountOps_CustomsJSON"::text) from public."CRM_AccountOperationalProfiles" where "CRMAccountOps_AccountID"=v_profile."CRMAccount_ID"),''),
    'privacy',coalesce((select md5("CRMAccountOps_PrivacyJSON"::text) from public."CRM_AccountOperationalProfiles" where "CRMAccountOps_AccountID"=v_profile."CRMAccount_ID"),''),
    'instructions',coalesce((select md5(coalesce(jsonb_agg(jsonb_build_array("CRMAccountInstruction_ID","CRMAccountInstruction_KindCode","CRMAccountInstruction_Title",md5("CRMAccountInstruction_Body"),"CRMAccountInstruction_DestinationCountryCode","CRMAccountInstruction_DestinationUNLOCODE","CRMAccountInstruction_AddressID","CRMAccountInstruction_ContactID","CRMAccountInstruction_IsActive") order by "CRMAccountInstruction_ID"),'[]'::jsonb)::text) from public."CRM_AccountOperationalInstructions" where "CRMAccountInstruction_AccountID"=v_profile."CRMAccount_ID"),md5('[]')),
    'documents',coalesce((select md5(coalesce(jsonb_agg(jsonb_build_array("CRMAccountDocument_ID","CRMAccountDocument_TypeCode","CRMAccountDocument_Title",md5(coalesce("CRMAccountDocument_Notes",'')),"CRMAccountDocument_SourceDocumentID","CRMAccountDocument_StatusCode") order by "CRMAccountDocument_ID"),'[]'::jsonb)::text) from public."CRM_AccountDocumentRecords" where "CRMAccountDocument_AccountID"=v_profile."CRMAccount_ID"),md5('[]')),
    'addressBookingRules',coalesce((select md5(coalesce(jsonb_agg(jsonb_build_array("OrgAddOperational_OrgAddID","OrgAddOperational_AppointmentRequired","OrgAddOperational_AdvanceBookingHours",md5(coalesce("OrgAddOperational_BookingInstructions",'')),md5(coalesce("OrgAddOperational_CollectionInstructions",'')),md5(coalesce("OrgAddOperational_DeliveryInstructions",''))) order by "OrgAddOperational_OrgAddID"),'[]'::jsonb)::text) from public."Org_AddressOperationalDetails" where "OrgAddOperational_OrgID"=p_org_id),md5('[]'))
  ) into v_old_signal;
  if jsonb_typeof(coalesce(p_input->'roleProfiles','{}'::jsonb)) <> 'object'
    or jsonb_typeof(coalesce(p_input->'invoicePreferences','{}'::jsonb)) <> 'object'
    or jsonb_typeof(coalesce(p_input->'customs','{}'::jsonb)) <> 'object'
    or jsonb_typeof(coalesce(p_input->'privacy','{}'::jsonb)) <> 'object' then
    raise exception 'Account operational profiles must be objects.' using errcode = '22023';
  end if;
  if jsonb_typeof(coalesce(p_input->'instructions','[]'::jsonb)) <> 'array'
    or jsonb_typeof(coalesce(p_input->'documents','[]'::jsonb)) <> 'array'
    or jsonb_typeof(coalesce(p_input->'addressOperations','[]'::jsonb)) <> 'array' then
    raise exception 'Instructions, documents and address operations must be lists.' using errcode = '22023';
  end if;
  if jsonb_array_length(coalesce(p_input->'instructions','[]'::jsonb)) > 100
    or jsonb_array_length(coalesce(p_input->'documents','[]'::jsonb)) > 100
    or jsonb_array_length(coalesce(p_input->'addressOperations','[]'::jsonb)) > 100 then
    raise exception 'Enter no more than 100 operational records in one update.' using errcode = '22023';
  end if;

  insert into public."CRM_AccountOperationalProfiles"(
    "CRMAccountOps_AccountID","CRMAccountOps_OrgID","CRMAccountOps_CompanyID",
    "CRMAccountOps_RoleProfilesJSON","CRMAccountOps_InvoicePreferencesJSON","CRMAccountOps_CustomsJSON","CRMAccountOps_PrivacyJSON",
    "CRMAccountOps_UpdatedBy"
  ) values (
    v_profile."CRMAccount_ID",p_org_id,v_profile."CRMAccount_CompanyID",
    coalesce(p_input->'roleProfiles','{}'::jsonb),coalesce(p_input->'invoicePreferences','{}'::jsonb),
    coalesce(p_input->'customs','{}'::jsonb),coalesce(p_input->'privacy','{}'::jsonb),p_actor_user_id
  ) on conflict ("CRMAccountOps_AccountID") do update set
    "CRMAccountOps_RoleProfilesJSON"=excluded."CRMAccountOps_RoleProfilesJSON",
    "CRMAccountOps_InvoicePreferencesJSON"=excluded."CRMAccountOps_InvoicePreferencesJSON",
    "CRMAccountOps_CustomsJSON"=excluded."CRMAccountOps_CustomsJSON",
    "CRMAccountOps_PrivacyJSON"=excluded."CRMAccountOps_PrivacyJSON",
    "CRMAccountOps_EditVersion"=public."CRM_AccountOperationalProfiles"."CRMAccountOps_EditVersion"+1,
    "CRMAccountOps_UpdatedAt"=now(),"CRMAccountOps_UpdatedBy"=p_actor_user_id;

  delete from public."CRM_AccountOperationalInstructions" where "CRMAccountInstruction_AccountID"=v_profile."CRMAccount_ID";
  for v_item in select value from jsonb_array_elements(coalesce(p_input->'instructions','[]'::jsonb)) loop
    if nullif(btrim(v_item->>'title'),'') is null or nullif(btrim(v_item->>'body'),'') is null then
      raise exception 'Every instruction needs a title and instruction text.' using errcode = '22023'; end if;
    v_instruction_address := nullif(v_item->>'addressId','')::uuid;
    v_instruction_contact := nullif(v_item->>'contactId','')::uuid;
    if v_instruction_address is not null and not exists(
      select 1 from public."Org_Addresses" where "OrgAdd_ID"=v_instruction_address and "Org_ID"=p_org_id and "OrgAdd_IsActive"
    ) then raise exception 'Choose an active address belonging to this account.' using errcode = '22023'; end if;
    if v_instruction_contact is not null and not exists(
      select 1 from public."Org_Contacts" where "OrgContact_ID"=v_instruction_contact and "Org_ID"=p_org_id
    ) then raise exception 'Choose a contact belonging to this account.' using errcode = '22023'; end if;
    insert into public."CRM_AccountOperationalInstructions"(
      "CRMAccountInstruction_ID","CRMAccountInstruction_AccountID","CRMAccountInstruction_OrgID","CRMAccountInstruction_CompanyID",
      "CRMAccountInstruction_KindCode","CRMAccountInstruction_Title","CRMAccountInstruction_Body",
      "CRMAccountInstruction_DestinationCountryCode","CRMAccountInstruction_DestinationUNLOCODE","CRMAccountInstruction_AddressID","CRMAccountInstruction_ContactID",
      "CRMAccountInstruction_Priority","CRMAccountInstruction_EffectiveFrom","CRMAccountInstruction_EffectiveTo","CRMAccountInstruction_IsActive",
      "CRMAccountInstruction_CreatedBy","CRMAccountInstruction_UpdatedBy"
    ) values (
      coalesce(nullif(v_item->>'id','')::uuid,gen_random_uuid()),v_profile."CRMAccount_ID",p_org_id,v_profile."CRMAccount_CompanyID",
      lower(coalesce(nullif(v_item->>'kind',''),'booking')),left(btrim(v_item->>'title'),160),btrim(v_item->>'body'),
      upper(nullif(btrim(v_item->>'destinationCountryCode'),'')),upper(nullif(btrim(v_item->>'destinationUnlocode'),'')),
      v_instruction_address,v_instruction_contact,coalesce((v_item->>'priority')::integer,100),
      coalesce(nullif(v_item->>'effectiveFrom','')::date,current_date),nullif(v_item->>'effectiveTo','')::date,
      coalesce((v_item->>'isActive')::boolean,true),p_actor_user_id,p_actor_user_id
    );
  end loop;

  delete from public."CRM_AccountDocumentRecords" where "CRMAccountDocument_AccountID"=v_profile."CRMAccount_ID";
  for v_item in select value from jsonb_array_elements(coalesce(p_input->'documents','[]'::jsonb)) loop
    if nullif(btrim(v_item->>'title'),'') is null then raise exception 'Every document record needs a title.' using errcode = '22023'; end if;
    v_source_document := nullif(v_item->>'sourceDocumentId','')::uuid;
    if v_source_document is not null and not exists(
      select 1 from public."CRM_CustomerDocuments"
      where "CRMCustomerDocument_ID"=v_source_document and "CRMCustomerDocument_CustomerOrgID"=p_org_id
    ) then
      raise exception 'Choose a document linked to this account.' using errcode = '22023';
    end if;
    insert into public."CRM_AccountDocumentRecords"(
      "CRMAccountDocument_ID","CRMAccountDocument_AccountID","CRMAccountDocument_OrgID","CRMAccountDocument_CompanyID",
      "CRMAccountDocument_TypeCode","CRMAccountDocument_Title","CRMAccountDocument_Notes","CRMAccountDocument_RepresentationType",
      "CRMAccountDocument_SourceDocumentID","CRMAccountDocument_ExternalReference","CRMAccountDocument_ValidFrom","CRMAccountDocument_ValidTo",
      "CRMAccountDocument_StatusCode","CRMAccountDocument_CreatedBy","CRMAccountDocument_UpdatedBy"
    ) values (
      coalesce(nullif(v_item->>'id','')::uuid,gen_random_uuid()),v_profile."CRMAccount_ID",p_org_id,v_profile."CRMAccount_CompanyID",
      lower(coalesce(nullif(v_item->>'type',''),'supporting_document')),left(btrim(v_item->>'title'),200),nullif(btrim(v_item->>'notes'),''),
      lower(nullif(btrim(v_item->>'representationType'),'')),v_source_document,nullif(btrim(v_item->>'externalReference'),''),
      nullif(v_item->>'validFrom','')::date,nullif(v_item->>'validTo','')::date,lower(coalesce(nullif(v_item->>'status',''),'active')),p_actor_user_id,p_actor_user_id
    );
  end loop;

  for v_item in select value from jsonb_array_elements(coalesce(p_input->'addressOperations','[]'::jsonb)) loop
    v_address := nullif(v_item->>'addressId','')::uuid;
    if not exists(select 1 from public."Org_Addresses" where "OrgAdd_ID"=v_address and "Org_ID"=p_org_id and "OrgAdd_IsActive") then
      raise exception 'Choose an active address belonging to this account.' using errcode = '22023'; end if;
    insert into public."Org_AddressOperationalDetails"(
      "OrgAddOperational_OrgAddID","OrgAddOperational_OrgID","OrgAddOperational_AppointmentRequired","OrgAddOperational_AdvanceBookingHours",
      "OrgAddOperational_BookingInstructions","OrgAddOperational_CollectionInstructions","OrgAddOperational_DeliveryInstructions","OrgAddOperational_UpdatedBy"
    ) values (
      v_address,p_org_id,coalesce((v_item->>'appointmentRequired')::boolean,false),coalesce((v_item->>'advanceBookingHours')::integer,0),
      nullif(btrim(v_item->>'bookingInstructions'),''),nullif(btrim(v_item->>'collectionInstructions'),''),nullif(btrim(v_item->>'deliveryInstructions'),''),p_actor_user_id
    ) on conflict ("OrgAddOperational_OrgAddID") do update set
      "OrgAddOperational_AppointmentRequired"=excluded."OrgAddOperational_AppointmentRequired",
      "OrgAddOperational_AdvanceBookingHours"=excluded."OrgAddOperational_AdvanceBookingHours",
      "OrgAddOperational_BookingInstructions"=excluded."OrgAddOperational_BookingInstructions",
      "OrgAddOperational_CollectionInstructions"=excluded."OrgAddOperational_CollectionInstructions",
      "OrgAddOperational_DeliveryInstructions"=excluded."OrgAddOperational_DeliveryInstructions",
      "OrgAddOperational_UpdatedAt"=now(),"OrgAddOperational_UpdatedBy"=p_actor_user_id;
  end loop;

  update public."CRM_AccountProfiles" set "CRMAccount_EditVersion"="CRMAccount_EditVersion"+1,
    "CRMAccount_UpdatedAt"=now(),"CRMAccount_UpdatedBy"=p_actor_user_id where "CRMAccount_ID"=v_profile."CRMAccount_ID";
  select jsonb_build_object(
    'roleProfiles',coalesce((select md5("CRMAccountOps_RoleProfilesJSON"::text) from public."CRM_AccountOperationalProfiles" where "CRMAccountOps_AccountID"=v_profile."CRMAccount_ID"),''),
    'invoicePreferences',coalesce((select md5("CRMAccountOps_InvoicePreferencesJSON"::text) from public."CRM_AccountOperationalProfiles" where "CRMAccountOps_AccountID"=v_profile."CRMAccount_ID"),''),
    'customs',coalesce((select md5("CRMAccountOps_CustomsJSON"::text) from public."CRM_AccountOperationalProfiles" where "CRMAccountOps_AccountID"=v_profile."CRMAccount_ID"),''),
    'privacy',coalesce((select md5("CRMAccountOps_PrivacyJSON"::text) from public."CRM_AccountOperationalProfiles" where "CRMAccountOps_AccountID"=v_profile."CRMAccount_ID"),''),
    'instructions',coalesce((select md5(coalesce(jsonb_agg(jsonb_build_array("CRMAccountInstruction_ID","CRMAccountInstruction_KindCode","CRMAccountInstruction_Title",md5("CRMAccountInstruction_Body"),"CRMAccountInstruction_DestinationCountryCode","CRMAccountInstruction_DestinationUNLOCODE","CRMAccountInstruction_AddressID","CRMAccountInstruction_ContactID","CRMAccountInstruction_IsActive") order by "CRMAccountInstruction_ID"),'[]'::jsonb)::text) from public."CRM_AccountOperationalInstructions" where "CRMAccountInstruction_AccountID"=v_profile."CRMAccount_ID"),md5('[]')),
    'documents',coalesce((select md5(coalesce(jsonb_agg(jsonb_build_array("CRMAccountDocument_ID","CRMAccountDocument_TypeCode","CRMAccountDocument_Title",md5(coalesce("CRMAccountDocument_Notes",'')),"CRMAccountDocument_SourceDocumentID","CRMAccountDocument_StatusCode") order by "CRMAccountDocument_ID"),'[]'::jsonb)::text) from public."CRM_AccountDocumentRecords" where "CRMAccountDocument_AccountID"=v_profile."CRMAccount_ID"),md5('[]')),
    'addressBookingRules',coalesce((select md5(coalesce(jsonb_agg(jsonb_build_array("OrgAddOperational_OrgAddID","OrgAddOperational_AppointmentRequired","OrgAddOperational_AdvanceBookingHours",md5(coalesce("OrgAddOperational_BookingInstructions",'')),md5(coalesce("OrgAddOperational_CollectionInstructions",'')),md5(coalesce("OrgAddOperational_DeliveryInstructions",''))) order by "OrgAddOperational_OrgAddID"),'[]'::jsonb)::text) from public."Org_AddressOperationalDetails" where "OrgAddOperational_OrgID"=p_org_id),md5('[]'))
  ) into v_new_signal;
  if v_old_signal is distinct from v_new_signal and exists(
    select 1 from public."AI_DexterWatches" watch
    where watch."AIDexterWatch_CompanyID"=v_profile."CRMAccount_CompanyID"
      and watch."AIDexterWatch_CapabilityCode"='customers'
      and watch."AIDexterWatch_StatusCode"='active'
      and (watch."AIDexterWatch_TargetID" is null or watch."AIDexterWatch_TargetID"=p_org_id)
  ) then
    insert into public."AI_DexterWatchSignals"(
      "AIDexterWatchSignal_CompanyID","AIDexterWatchSignal_CapabilityCode","AIDexterWatchSignal_SourceTable",
      "AIDexterWatchSignal_SourceID","AIDexterWatchSignal_OldJSON","AIDexterWatchSignal_NewJSON"
    ) values(v_profile."CRMAccount_CompanyID",'customers','CRM_AccountOperations',p_org_id,v_old_signal,v_new_signal);
  end if;
  return jsonb_build_object('id',p_org_id,'editVersion',v_profile."CRMAccount_EditVersion"+1);
end;
$$;


ALTER FUNCTION "public"."multideck_crm_replace_account_operations"("p_actor_user_id" "uuid", "p_org_id" "uuid", "p_expected_version" bigint, "p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_crm_request_lead_transfer"("p_lead_id" "uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare v_context record; v_lead public."CRM_Leads"%rowtype; v_id uuid;
begin
  select * into v_context from public._multideck_crm_context();
  perform pg_advisory_xact_lock(hashtextextended(p_lead_id::text, 7231));
  select * into v_lead from public."CRM_Leads" where "CRMLead_ID" = p_lead_id and not "CRMLead_IsDeleted" for update;
  if not found then raise exception 'This lead no longer exists.' using errcode = 'P0002'; end if;
  if v_lead."CRMLead_OwnerUserID" = v_context.user_id then raise exception 'You already own this lead.' using errcode = '22023'; end if;
  if v_lead."CRMLead_OwnerUserID" is null then raise exception 'This lead has no current owner. Ask a CRM manager to assign it.' using errcode = '22023'; end if;
  if not exists (select 1 from public."cmp_Users" where "User_ID" = v_lead."CRMLead_OwnerUserID" and "Company_ID" = v_context.company_id) then
    raise exception 'The current owner is not in this workspace.' using errcode = '22023';
  end if;
  insert into public."CRM_LeadTransferRequests" ("Company_ID", "CRMLeadTransfer_LeadID", "CRMLeadTransfer_RequesterUserID", "CRMLeadTransfer_FromUserID", "CRMLeadTransfer_ToUserID", "CRMLeadTransfer_RequestNote")
  values (v_context.company_id, p_lead_id, v_context.user_id, v_lead."CRMLead_OwnerUserID", v_context.user_id, nullif(btrim(p_note), ''))
  returning "CRMLeadTransfer_ID" into v_id;
  insert into public."Comm_Notifications" ("CommNotif_UserID", "CommNotif_Title", "CommNotif_Body", "CommNotif_TargetTable", "CommNotif_TargetID", "CommNotif_LinkTypeCode", "CommNotif_MetadataJSON", "CommNotif_CreatedBy")
  values (v_lead."CRMLead_OwnerUserID", 'Lead ownership requested', coalesce(nullif(btrim(p_note), ''), 'A colleague asked to take ownership of this CRM lead.'), 'CRM_LeadTransferRequests', v_id, null, jsonb_build_object('event', 'lead_transfer_requested', 'leadId', p_lead_id), v_context.user_id);
  return public._multideck_crm_transfer_request_json(v_id);
exception when unique_violation then
  raise exception 'You already have a pending ownership request for this lead.' using errcode = '23505';
end;
$$;


ALTER FUNCTION "public"."multideck_crm_request_lead_transfer"("p_lead_id" "uuid", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_crm_resolve_account_instructions"("p_org_id" "uuid", "p_kind_code" "text" DEFAULT NULL::"text", "p_destination_country_code" "text" DEFAULT NULL::"text", "p_destination_unlocode" "text" DEFAULT NULL::"text", "p_on_date" "date" DEFAULT CURRENT_DATE, "p_address_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_instructions jsonb; v_address_instructions jsonb:='[]'::jsonb;
begin
  if coalesce(auth.role(),'') <> 'service_role' and not public.app_user_can_access_organisation(p_org_id) then raise exception 'Account not found.' using errcode = '42501'; end if;
  if coalesce(auth.role(),'') <> 'service_role' and not exists(
    select 1 from public."cmp_Users" app_user
    where app_user."Auth_User_ID"=auth.uid() and app_user."Company_ID"=public.app_current_company_id()
      and (
        public._multideck_crm_has_permission(app_user."User_ID",'Customers.Read')
        or public._multideck_crm_has_permission(app_user."User_ID",'Bookings.Read')
      )
  ) then raise exception 'You do not have permission to read these account instructions.' using errcode='42501'; end if;
  select coalesce(jsonb_agg(jsonb_build_object(
      'id', i."CRMAccountInstruction_ID", 'kind', i."CRMAccountInstruction_KindCode", 'title', i."CRMAccountInstruction_Title",
      'body', i."CRMAccountInstruction_Body", 'addressId', i."CRMAccountInstruction_AddressID", 'contactId', i."CRMAccountInstruction_ContactID",
      'priority', i."CRMAccountInstruction_Priority", 'destinationCountryCode', i."CRMAccountInstruction_DestinationCountryCode",
      'destinationUnlocode', i."CRMAccountInstruction_DestinationUNLOCODE"
    ) order by i."CRMAccountInstruction_Priority", i."CRMAccountInstruction_Title"), '[]'::jsonb)
  into v_instructions
  from public."CRM_AccountOperationalInstructions" i
  where i."CRMAccountInstruction_OrgID" = p_org_id and i."CRMAccountInstruction_IsActive"
    and (p_kind_code is null or i."CRMAccountInstruction_KindCode" = lower(p_kind_code))
    and (i."CRMAccountInstruction_AddressID" is null or i."CRMAccountInstruction_AddressID"=p_address_id)
    and i."CRMAccountInstruction_EffectiveFrom" <= p_on_date
    and (i."CRMAccountInstruction_EffectiveTo" is null or i."CRMAccountInstruction_EffectiveTo" >= p_on_date)
    and (i."CRMAccountInstruction_DestinationCountryCode" is null or i."CRMAccountInstruction_DestinationCountryCode" = upper(p_destination_country_code))
    and (i."CRMAccountInstruction_DestinationUNLOCODE" is null or i."CRMAccountInstruction_DestinationUNLOCODE" = upper(p_destination_unlocode));
  if p_address_id is not null then
    select coalesce(jsonb_agg(jsonb_build_object(
      'id','address:'||p_address_id::text||':'||rule.kind,'kind',rule.kind,'title',rule.title,'body',rule.body,
      'addressId',p_address_id,'contactId',null,'priority',50,'source','address',
      'appointmentRequired',details."OrgAddOperational_AppointmentRequired",
      'advanceBookingHours',details."OrgAddOperational_AdvanceBookingHours"
    ) order by rule.priority),'[]'::jsonb) into v_address_instructions
    from public."Org_AddressOperationalDetails" details
    cross join lateral (values
      ('booking','Address booking instructions',details."OrgAddOperational_BookingInstructions",1),
      ('collection','Address collection instructions',details."OrgAddOperational_CollectionInstructions",2),
      ('delivery','Address delivery instructions',details."OrgAddOperational_DeliveryInstructions",3)
    ) rule(kind,title,body,priority)
    where details."OrgAddOperational_OrgID"=p_org_id and details."OrgAddOperational_OrgAddID"=p_address_id
      and nullif(btrim(rule.body),'') is not null and (p_kind_code is null or rule.kind=lower(p_kind_code));
  end if;
  return v_instructions||v_address_instructions;
end;
$$;


ALTER FUNCTION "public"."multideck_crm_resolve_account_instructions"("p_org_id" "uuid", "p_kind_code" "text", "p_destination_country_code" "text", "p_destination_unlocode" "text", "p_on_date" "date", "p_address_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_crm_resolve_related_party_default"("p_source_org_id" "uuid", "p_party_role_code" "text", "p_destination_country_code" "text" DEFAULT NULL::"text", "p_destination_unlocode" "text" DEFAULT NULL::"text", "p_destination_postcode" "text" DEFAULT NULL::"text", "p_on_date" "date" DEFAULT CURRENT_DATE) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_context record;
  v_result jsonb;
begin
  select * into v_context from public._multideck_crm_context();
  if not public._multideck_crm_has_permission(v_context.user_id, 'Customers.Read')
    or not public.multideck_crm_company_can_access_account(v_context.company_id, p_source_org_id) then
    raise exception 'You do not have permission to view this organisation.' using errcode = '42501';
  end if;
  select jsonb_build_object(
    'ruleId', rule."OrgRelatedDefault_ID", 'sourceOrganisationId', p_source_org_id,
    'partyRoleCode', rule."OrgRelatedDefault_PartyRoleCode",
    'targetOrganisation', jsonb_build_object('id', target."Org_id", 'name', target."Org_Name", 'accountCode', target."Org_AccCode"),
    'targetAddressId', rule."OrgRelatedDefault_TargetAddressID", 'targetContactId', rule."OrgRelatedDefault_TargetContactID",
    'matchedBy', case
      when rule."OrgRelatedDefault_DestinationPostcode" is not null then 'postcode'
      when rule."OrgRelatedDefault_DestinationUNLOCODE" is not null then 'unlocode'
      when rule."OrgRelatedDefault_DestinationCountryCode" is not null then 'country'
      else 'fallback' end,
    'evidence', jsonb_build_object(
      'sourceTable', 'Org_RelatedPartyDefaults', 'sourceId', rule."OrgRelatedDefault_ID",
      'effectiveFrom', rule."OrgRelatedDefault_EffectiveFrom", 'effectiveTo', rule."OrgRelatedDefault_EffectiveTo"
    )
  ) into v_result
  from public."Org_RelatedPartyDefaults" rule
  join public."Org_Master" target on target."Org_id" = rule."OrgRelatedDefault_TargetOrgID"
  where rule."OrgRelatedDefault_CompanyID" = v_context.company_id
    and rule."OrgRelatedDefault_SourceOrgID" = p_source_org_id
    and rule."OrgRelatedDefault_PartyRoleCode" = lower(btrim(p_party_role_code))
    and rule."OrgRelatedDefault_IsActive"
    and rule."OrgRelatedDefault_EffectiveFrom" <= p_on_date
    and (rule."OrgRelatedDefault_EffectiveTo" is null or rule."OrgRelatedDefault_EffectiveTo" >= p_on_date)
    and (rule."OrgRelatedDefault_DestinationCountryCode" is null or rule."OrgRelatedDefault_DestinationCountryCode" = upper(btrim(p_destination_country_code)))
    and (rule."OrgRelatedDefault_DestinationUNLOCODE" is null or rule."OrgRelatedDefault_DestinationUNLOCODE" = upper(btrim(p_destination_unlocode)))
    and (rule."OrgRelatedDefault_DestinationPostcode" is null or rule."OrgRelatedDefault_DestinationPostcode" = upper(btrim(p_destination_postcode)))
  order by
    (rule."OrgRelatedDefault_DestinationPostcode" is not null)::integer desc,
    (rule."OrgRelatedDefault_DestinationUNLOCODE" is not null)::integer desc,
    (rule."OrgRelatedDefault_DestinationCountryCode" is not null)::integer desc,
    rule."OrgRelatedDefault_Priority", rule."OrgRelatedDefault_UpdatedAt" desc
  limit 1;
  return coalesce(v_result, jsonb_build_object(
    'sourceOrganisationId', p_source_org_id, 'partyRoleCode', lower(btrim(p_party_role_code)),
    'targetOrganisation', null, 'matchedBy', null, 'evidence', null
  ));
end;
$$;


ALTER FUNCTION "public"."multideck_crm_resolve_related_party_default"("p_source_org_id" "uuid", "p_party_role_code" "text", "p_destination_country_code" "text", "p_destination_unlocode" "text", "p_destination_postcode" "text", "p_on_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_crm_set_marketing_opt_in"("p_record_type" "text", "p_record_id" "uuid", "p_opted_in" boolean, "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare v_context record;
begin
  select * into v_context from public._multideck_crm_context();
  return public._multideck_set_marketing_consent(
    p_record_type, p_record_id, p_opted_in, 'manual_override', p_reason, v_context.user_id,
    jsonb_build_object('companyId', v_context.company_id)
  );
end;
$$;


ALTER FUNCTION "public"."multideck_crm_set_marketing_opt_in"("p_record_type" "text", "p_record_id" "uuid", "p_opted_in" boolean, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_crm_transfer_contact"("p_actor_user_id" "uuid", "p_contact_id" "uuid", "p_target_org_id" "uuid", "p_expected_version" bigint, "p_input" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_contact public."Org_Contacts"%rowtype;
  v_profile public."CRM_ContactProfiles"%rowtype;
  v_target public."CRM_AccountProfiles"%rowtype;
  v_started date := coalesce(nullif(p_input ->> 'startedAt', '')::date, current_date);
  v_next_version bigint;
begin
  perform public._multideck_crm_write_actor(p_actor_user_id);
  select * into v_contact from public."Org_Contacts" where "OrgContact_ID" = p_contact_id for update;
  if not found then raise exception 'Contact not found.' using errcode = 'P0002'; end if;
  perform public._multideck_crm_require_account_access(p_actor_user_id, v_contact."Org_ID");
  perform public._multideck_crm_require_account_access(p_actor_user_id, p_target_org_id);
  if v_contact."Org_ID" = p_target_org_id then
    raise exception 'Choose a different organisation for this transfer.' using errcode = '22023';
  end if;

  select * into v_profile from public."CRM_ContactProfiles"
  where "CRMContact_OrgContactID" = p_contact_id
  order by "CRMContact_ID" limit 1 for update;
  if not found then raise exception 'Contact profile not found.' using errcode = 'P0002'; end if;
  if p_expected_version is null or v_profile."CRMContact_EditVersion" <> p_expected_version then
    raise exception 'CRM_CONFLICT:This contact changed since it was loaded.' using errcode = 'P0001';
  end if;
  select * into v_target from public."CRM_AccountProfiles"
  where "CRMAccount_OrgID" = p_target_org_id and not "CRMAccount_IsDeleted"
  order by "CRMAccount_ID" limit 1;
  if not found then raise exception 'Target organisation not found.' using errcode = 'P0002'; end if;

  -- Preserve the source employer when legacy data has no current history row.
  -- A record-created date is not evidence of an employment start date.
  insert into public."CRM_ContactOrganisationAssignments"(
    "CRMContactOrg_ContactID","CRMContactOrg_OrgID","CRMContactOrg_CompanyID",
    "CRMContactOrg_JobTitle","CRMContactOrg_Department","CRMContactOrg_RoleCode",
    "CRMContactOrg_StartedAt","CRMContactOrg_EndedAt","CRMContactOrg_IsCurrent","CRMContactOrg_CreatedBy"
  ) select p_contact_id,v_contact."Org_ID",source."CRMAccount_CompanyID",
    v_profile."CRMContact_MetadataJSON"->>'jobTitle',v_profile."CRMContact_MetadataJSON"->>'department',v_profile."CRMContact_RoleCode",
    null,v_started-1,false,p_actor_user_id
  from public."CRM_AccountProfiles" source where source."CRMAccount_OrgID"=v_contact."Org_ID" and not source."CRMAccount_IsDeleted"
    and not exists(select 1 from public."CRM_ContactOrganisationAssignments" existing where existing."CRMContactOrg_ContactID"=p_contact_id and existing."CRMContactOrg_IsCurrent")
  order by source."CRMAccount_ID" limit 1;
  update public."CRM_ContactOrganisationAssignments"
  set "CRMContactOrg_IsCurrent" = false,
      "CRMContactOrg_EndedAt" = greatest(v_started - 1, "CRMContactOrg_StartedAt")
  where "CRMContactOrg_ContactID" = p_contact_id and "CRMContactOrg_IsCurrent";
  insert into public."CRM_ContactOrganisationAssignments"(
    "CRMContactOrg_ContactID", "CRMContactOrg_OrgID", "CRMContactOrg_CompanyID",
    "CRMContactOrg_JobTitle", "CRMContactOrg_Department", "CRMContactOrg_RoleCode",
    "CRMContactOrg_StartedAt", "CRMContactOrg_IsCurrent", "CRMContactOrg_CreatedBy"
  ) values (
    p_contact_id, p_target_org_id, v_target."CRMAccount_CompanyID",
    coalesce(nullif(btrim(p_input ->> 'jobTitle'), ''), v_profile."CRMContact_MetadataJSON" ->> 'jobTitle'),
    coalesce(nullif(btrim(p_input ->> 'department'), ''), v_profile."CRMContact_MetadataJSON" ->> 'department'),
    coalesce(nullif(btrim(p_input ->> 'role'), ''), v_profile."CRMContact_RoleCode"),
    v_started, true, p_actor_user_id
  );

  v_next_version := v_profile."CRMContact_EditVersion" + 1;
  update public."Org_Contacts" set "Org_ID" = p_target_org_id where "OrgContact_ID" = p_contact_id;
  update public."CRM_ContactProfiles"
  set "CRMContact_AccountID" = v_target."CRMAccount_ID",
      "CRMContact_RoleCode" = coalesce(nullif(btrim(p_input ->> 'role'), ''), "CRMContact_RoleCode"),
      "CRMContact_MetadataJSON" = "CRMContact_MetadataJSON" || jsonb_strip_nulls(jsonb_build_object(
        'jobTitle', nullif(btrim(p_input ->> 'jobTitle'), ''),
        'department', nullif(btrim(p_input ->> 'department'), '')
      )),
      "CRMContact_EditVersion" = v_next_version,
      "CRMContact_UpdatedAt" = now(),
      "CRMContact_UpdatedBy" = p_actor_user_id
  where "CRMContact_ID" = v_profile."CRMContact_ID";
  update public."Comm_Identities"
  set "CommIdentity_OrgID" = p_target_org_id, "CommIdentity_UpdatedAt" = now()
  where "CommIdentity_ContactID" = p_contact_id and not "CommIdentity_IsDeleted";

  return jsonb_build_object('id', p_contact_id, 'accountId', p_target_org_id, 'editVersion', v_next_version);
end;
$$;


ALTER FUNCTION "public"."multideck_crm_transfer_contact"("p_actor_user_id" "uuid", "p_contact_id" "uuid", "p_target_org_id" "uuid", "p_expected_version" bigint, "p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_crm_transfer_lead"("p_lead_id" "uuid", "p_target_user_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare v_context record; v_lead public."CRM_Leads"%rowtype; v_is_override boolean;
begin
  select * into v_context from public._multideck_crm_context();
  select * into v_lead from public."CRM_Leads" where "CRMLead_ID" = p_lead_id and not "CRMLead_IsDeleted";
  if not found then raise exception 'This lead no longer exists.' using errcode = 'P0002'; end if;
  if not exists (
    select 1 from public."cmp_Users" workspace_owner
    where workspace_owner."User_ID" = v_lead."CRMLead_OwnerUserID" and workspace_owner."Company_ID" = v_context.company_id
  ) then raise exception 'This lead is outside your CRM workspace.' using errcode = '42501'; end if;
  v_is_override := v_lead."CRMLead_OwnerUserID" is distinct from v_context.user_id;
  if v_is_override and not public._multideck_crm_has_permission(v_context.user_id, 'CRM.Leads.Reassign') then
    raise exception 'Only the current owner or an authorised CRM manager can transfer this lead.' using errcode = '42501';
  end if;
  if v_is_override and nullif(btrim(coalesce(p_reason, '')), '') is null then
    raise exception 'Give a reason for overriding lead ownership.' using errcode = '22023';
  end if;
  return public._multideck_crm_apply_lead_transfer(p_lead_id, v_lead."CRMLead_OwnerUserID", p_target_user_id, v_context.user_id, v_context.company_id, p_reason, null);
end;
$$;


ALTER FUNCTION "public"."multideck_crm_transfer_lead"("p_lead_id" "uuid", "p_target_user_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_crm_transfer_users_page"("p_search" "text" DEFAULT NULL::"text", "p_exclude_user_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 25, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_context record;
  v_search text := left(lower(btrim(coalesce(p_search, ''))), 200);
  v_pattern text;
  v_limit integer := least(greatest(coalesce(p_limit, 25), 1), 50);
  v_offset integer := least(greatest(coalesce(p_offset, 0), 0), 1000000);
  v_result jsonb;
begin
  select * into v_context from public._multideck_crm_context();
  if not public._multideck_crm_has_permission(v_context.user_id, 'CRM.Read') then
    raise exception 'You do not have permission to view CRM users.' using errcode = '42501';
  end if;

  v_pattern := '%' || replace(replace(replace(v_search, E'\\', E'\\\\'), '%', E'\\%'), '_', E'\\_') || '%';

  with eligible as materialized (
    select
      workspace_user."User_ID" as id,
      coalesce(
        nullif(btrim(concat_ws(' ', workspace_user."User_Firstname", workspace_user."User_Lastname")), ''),
        workspace_user."User_Email",
        'Unnamed user'
      ) as display_name,
      workspace_user."User_Email" as email
    from public."cmp_Users" workspace_user
    where workspace_user."Company_ID" = v_context.company_id
      and workspace_user."Auth_User_ID" is not null
      and coalesce(workspace_user."User_AccessStatus", 'active') = 'active'
      and (p_exclude_user_id is null or workspace_user."User_ID" <> p_exclude_user_id)
      and (
        v_search = ''
        or lower(coalesce(workspace_user."User_Firstname", '') || ' ' || coalesce(workspace_user."User_Lastname", '')) like v_pattern escape E'\\'
        or lower(coalesce(workspace_user."User_Email", '')) like v_pattern escape E'\\'
      )
  ), page as materialized (
    select eligible.*
    from eligible
    order by lower(eligible.display_name), lower(eligible.email), eligible.id
    offset v_offset
    limit v_limit
  ), current_operator as (
    select jsonb_build_object(
      'id', workspace_user."User_ID",
      'name', coalesce(
        nullif(btrim(concat_ws(' ', workspace_user."User_Firstname", workspace_user."User_Lastname")), ''),
        workspace_user."User_Email",
        'Current user'
      ),
      'email', coalesce(workspace_user."User_Email", ''),
      'isCurrentUser', true
    ) as payload
    from public."cmp_Users" workspace_user
    where workspace_user."User_ID" = v_context.user_id
      and workspace_user."Company_ID" = v_context.company_id
  )
  select jsonb_build_object(
    'rows', coalesce((select jsonb_agg(jsonb_build_object(
      'id', page.id,
      'name', page.display_name,
      'email', coalesce(page.email, ''),
      'isCurrentUser', page.id = v_context.user_id
    ) order by lower(page.display_name), lower(page.email), page.id) from page), '[]'::jsonb),
    'total', (select count(*) from eligible),
    'limit', v_limit,
    'offset', v_offset,
    'currentUser', (select payload from current_operator)
  ) into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."multideck_crm_transfer_users_page"("p_search" "text", "p_exclude_user_id" "uuid", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."multideck_crm_transfer_users_page"("p_search" "text", "p_exclude_user_id" "uuid", "p_limit" integer, "p_offset" integer) IS 'Authenticated, company-scoped and maximum-50-row CRM ownership target selector. Search and exclusion happen before pagination.';



CREATE OR REPLACE FUNCTION "public"."multideck_crm_update_account"("p_actor_user_id" "uuid", "p_account_id" "uuid", "p_expected_version" bigint, "p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_result jsonb;
  v_type_ids uuid[];
  v_old_types jsonb;
  v_new_types jsonb;
  v_company_id uuid;
  v_is_customer boolean;
begin
  perform public._multideck_crm_require_account_access(p_actor_user_id, p_account_id);
  if jsonb_typeof(p_input -> 'orgTypeIds') <> 'array' then
    raise exception 'Choose at least one company type.' using errcode = '22023';
  end if;
  select array_agg(distinct value::uuid) into v_type_ids
  from jsonb_array_elements_text(p_input -> 'orgTypeIds') item(value);
  if coalesce(cardinality(v_type_ids), 0) < 1 or cardinality(v_type_ids) > 12 then
    raise exception 'Choose between 1 and 12 company types.' using errcode = '22023';
  end if;
  if (select count(*) from public."Org_Types" where "OrgType_ID" = any(v_type_ids)) <> cardinality(v_type_ids) then
    raise exception 'Choose valid company types.' using errcode = '22023';
  end if;

  select coalesce(jsonb_agg(type."OrgType_Name" order by type."OrgType_Name"), '[]'::jsonb)
  into v_old_types
  from public."Org_Master_Type" link
  join public."Org_Types" type on type."OrgType_ID" = link."OrgType_ID"
  where link."Org_ID" = p_account_id;

  v_result := public._multideck_crm_update_account_unscoped_20260818(p_actor_user_id, p_account_id, p_expected_version, p_input - 'orgTypeIds');

  delete from public."Org_Master_Type"
  where "Org_ID" = p_account_id and not ("OrgType_ID" = any(v_type_ids));
  insert into public."Org_Master_Type"("Org_ID", "OrgType_ID")
  select p_account_id, type_id from unnest(v_type_ids) type_id
  on conflict ("OrgType_ID", "Org_ID") do nothing;

  select exists (
    select 1 from public."Org_Types" type
    where type."OrgType_ID" = any(v_type_ids)
      and lower(type."OrgType_Name") in ('customer', 'potential customer', 'key customer account')
  ) into v_is_customer;
  update public."Org_Master"
  set "Org_CRMIsPotentialCustomer" = v_is_customer,
      "Org_CRMUpdatedAt" = now()
  where "Org_id" = p_account_id;

  select coalesce(jsonb_agg(type."OrgType_Name" order by type."OrgType_Name"), '[]'::jsonb)
  into v_new_types
  from public."Org_Master_Type" link
  join public."Org_Types" type on type."OrgType_ID" = link."OrgType_ID"
  where link."Org_ID" = p_account_id;

  select profile."CRMAccount_CompanyID" into v_company_id
  from public."CRM_AccountProfiles" profile
  where profile."CRMAccount_OrgID" = p_account_id and not profile."CRMAccount_IsDeleted"
  order by profile."CRMAccount_ID" limit 1;

  if v_company_id is not null and v_new_types is distinct from v_old_types
     and not exists (
       select 1 from public."CRM_AccountProfiles" fixture
       where fixture."CRMAccount_OrgID" = p_account_id
         and not fixture."CRMAccount_IsDeleted"
         and lower(coalesce(fixture."CRMAccount_MetadataJSON" ->> 'developmentFixture', 'false')) = 'true'
     ) then
    insert into public."AI_DexterWatchSignals"(
      "AIDexterWatchSignal_CompanyID", "AIDexterWatchSignal_CapabilityCode", "AIDexterWatchSignal_SourceTable",
      "AIDexterWatchSignal_SourceID", "AIDexterWatchSignal_OldJSON", "AIDexterWatchSignal_NewJSON"
    )
    select v_company_id, 'customers', 'Org_Master_Type', p_account_id,
      jsonb_build_object('recordType', 'company', 'organisationTypes', v_old_types),
      jsonb_build_object('recordType', 'company', 'organisationTypes', v_new_types)
    from public."AI_DexterWatches" watch
    where watch."AIDexterWatch_CompanyID" = v_company_id
      and watch."AIDexterWatch_CapabilityCode" = 'customers'
      and watch."AIDexterWatch_StatusCode" = 'active'
      and watch."AIDexterWatch_IsArmed"
      and (watch."AIDexterWatch_TargetID" is null or watch."AIDexterWatch_TargetID" = p_account_id)
    limit 1;
  end if;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."multideck_crm_update_account"("p_actor_user_id" "uuid", "p_account_id" "uuid", "p_expected_version" bigint, "p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_crm_update_contact"("p_actor_user_id" "uuid", "p_contact_id" "uuid", "p_expected_version" bigint, "p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_contact public."Org_Contacts"%rowtype;
  v_result jsonb;
  v_email text;
  v_current public."OrgContact_Emails"%rowtype;
  v_new_id uuid;
  v_now timestamptz := now();
begin
  select * into v_contact from public."Org_Contacts" where "OrgContact_ID" = p_contact_id;
  if not found then raise exception 'Contact not found.' using errcode = 'P0002'; end if;
  perform public._multideck_crm_require_account_access(p_actor_user_id, v_contact."Org_ID");

  v_result := public._multideck_crm_update_contact_unscoped_20260818(
    p_actor_user_id, p_contact_id, p_expected_version, p_input - 'email'
  );
  if not (p_input ? 'email') then return v_result; end if;

  v_email := lower(nullif(btrim(p_input ->> 'email'), ''));
  select * into v_current
  from public."OrgContact_Emails"
  where "OrgContact_ID" = p_contact_id
    and "OrgContactEmail_IsActive"
  order by "OrgContactEmail_IsPrimary" desc, "OrgContactEmail_ValidFrom" desc, "OrgContactEmail_ID"
  limit 1 for update;

  if found and lower(btrim(v_current."OrgContactEmail_Email")) is not distinct from v_email then
    update public."OrgContact_Emails"
    set "OrgContactEmail_IsPrimary" = true
    where "OrgContactEmail_ID" = v_current."OrgContactEmail_ID"
      and not "OrgContactEmail_IsPrimary";
    return v_result;
  end if;
  if v_email is not null then
    perform pg_advisory_xact_lock(hashtextextended(v_email, 0));
    if exists (
      select 1 from public."OrgContact_Emails" email
      where lower(btrim(email."OrgContactEmail_Email")) = v_email
        and email."OrgContactEmail_IsActive"
        and email."OrgContact_ID" <> p_contact_id
    ) then
      raise exception 'This email is already connected to a contact.' using errcode = '23505';
    end if;
  end if;

  if v_current."OrgContactEmail_ID" is not null then
    update public."OrgContact_Emails"
    set "OrgContactEmail_IsActive" = false,
        "OrgContactEmail_IsPrimary" = false,
        "OrgContactEmail_ValidTo" = v_now
    where "OrgContactEmail_ID" = v_current."OrgContactEmail_ID";
  end if;
  if v_email is not null then
    v_new_id := gen_random_uuid();
    insert into public."OrgContact_Emails"(
      "OrgContactEmail_ID", "OrgContact_ID", "OrgContactEmail_Email", "OrgContactEmail_Type",
      "OrgContactEmail_IsActive", "OrgContactEmail_IsPrimary", "OrgContactEmail_ValidFrom"
    ) values (v_new_id, p_contact_id, v_email, 1, true, true, v_now);
    if v_current."OrgContactEmail_ID" is not null then
      update public."OrgContact_Emails"
      set "OrgContactEmail_SupersededBy" = v_new_id
      where "OrgContactEmail_ID" = v_current."OrgContactEmail_ID";
    end if;
  end if;
  return v_result || jsonb_build_object('primaryEmailId', v_new_id);
end;
$$;


ALTER FUNCTION "public"."multideck_crm_update_contact"("p_actor_user_id" "uuid", "p_contact_id" "uuid", "p_expected_version" bigint, "p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_crm_update_deal"("p_deal_id" "uuid", "p_expected_version" bigint, "p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare v_context record;
begin
  select * into v_context from public._multideck_crm_context();
  if not public._multideck_crm_deal_is_operator_visible(p_deal_id, v_context.company_id) then
    raise exception 'Deal not found.' using errcode = 'P0002';
  end if;
  return public._multideck_crm_update_deal_visible_guard_20260818(
    p_deal_id,
    p_expected_version,
    p_input
  );
end;
$$;


ALTER FUNCTION "public"."multideck_crm_update_deal"("p_deal_id" "uuid", "p_expected_version" bigint, "p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_crm_update_lead"("p_lead_id" "uuid", "p_expected_version" bigint, "p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_context record;
  v_current_version bigint;
  v_result jsonb;
begin
  select * into v_context from public._multideck_crm_context();
  if not public._multideck_crm_has_permission(v_context.user_id, 'CRM.Write') then
    raise exception 'You do not have permission to change CRM.' using errcode = '42501';
  end if;
  if p_expected_version is null or p_expected_version < 1 then
    raise exception 'A valid lead version is required.' using errcode = '22023';
  end if;
  if not public._multideck_crm_lead_is_reachable(p_lead_id, v_context.company_id) then
    raise exception 'Lead not found.' using errcode = 'P0002';
  end if;

  select lead."CRMLead_EditVersion" into v_current_version
  from public."CRM_Leads" lead
  where lead."CRMLead_ID" = p_lead_id
    and not lead."CRMLead_IsDeleted"
  for update;

  if not found then
    raise exception 'Lead not found.' using errcode = 'P0002';
  end if;
  if v_current_version <> p_expected_version then
    raise exception 'CRM_CONFLICT: This lead changed elsewhere. Latest values have been reloaded.' using errcode = 'P0001';
  end if;

  v_result := public._multideck_crm_update_lead_unversioned_20260818(p_lead_id, p_input);
  select lead."CRMLead_EditVersion" into v_current_version
  from public."CRM_Leads" lead
  where lead."CRMLead_ID" = p_lead_id;
  return v_result || jsonb_build_object('editVersion', v_current_version);
end;
$$;


ALTER FUNCTION "public"."multideck_crm_update_lead"("p_lead_id" "uuid", "p_expected_version" bigint, "p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_crm_update_organisation_foundation"("p_actor_user_id" "uuid", "p_account_id" "uuid", "p_expected_version" bigint, "p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_profile public."CRM_AccountProfiles"%rowtype;
  v_org public."Org_Master"%rowtype;
  v_scope text;
  v_code text;
  v_is_potential boolean;
  v_offices jsonb;
  v_office jsonb;
  v_office_ids uuid[] := '{}'::uuid[];
  v_primary_count integer := 0;
  v_primary_office uuid;
  v_next_version bigint;
begin
  perform public._multideck_crm_write_actor(p_actor_user_id);
  perform public._multideck_crm_require_account_access(p_actor_user_id, p_account_id);

  select * into v_profile
  from public."CRM_AccountProfiles"
  where "CRMAccount_OrgID" = p_account_id and not "CRMAccount_IsDeleted"
  order by "CRMAccount_ID" limit 1 for update;
  if not found then raise exception 'Organisation not found.' using errcode = 'P0002'; end if;
  if p_expected_version is null or p_expected_version <> v_profile."CRMAccount_EditVersion" then
    raise exception 'CRM_CONFLICT:This organisation changed since it was loaded.' using errcode = 'P0001';
  end if;
  select * into v_org from public."Org_Master" where "Org_id" = p_account_id for update;

  v_scope := lower(coalesce(nullif(btrim(p_input ->> 'scopeCode'), ''), v_profile."CRMAccount_ScopeCode", 'standard'));
  v_code := public._multideck_crm_account_code(coalesce(nullif(btrim(p_input ->> 'accountCode'), ''), v_org."Org_AccCode"), v_scope);
  v_is_potential := case when p_input ? 'isPotential' then coalesce((p_input ->> 'isPotential')::boolean, false) else v_org."Org_CRMIsPotentialCustomer" end;

  if p_input ? 'officeAssignments' then
    if jsonb_typeof(p_input -> 'officeAssignments') <> 'array' or jsonb_array_length(p_input -> 'officeAssignments') > 20 then
      raise exception 'Choose no more than 20 responsible offices.' using errcode = '22023';
    end if;
    v_offices := p_input -> 'officeAssignments';
    for v_office in select value from jsonb_array_elements(v_offices) loop
      if nullif(btrim(v_office ->> 'officeId'), '') is null then
        raise exception 'Choose valid responsible offices.' using errcode = '22023';
      end if;
      if (v_office ->> 'officeId')::uuid = any(v_office_ids) then
        raise exception 'Each responsible office can only be assigned once.' using errcode = '22023';
      end if;
      v_office_ids := array_append(v_office_ids, (v_office ->> 'officeId')::uuid);
      if coalesce((v_office ->> 'isPrimary')::boolean, false) then
        v_primary_count := v_primary_count + 1;
        v_primary_office := (v_office ->> 'officeId')::uuid;
      end if;
    end loop;
    if not v_is_potential and (cardinality(v_office_ids) < 1 or v_primary_count <> 1) then
      raise exception 'Active organisations need at least one responsible office and exactly one primary office.' using errcode = '22023';
    end if;
    if v_primary_count > 1 then
      raise exception 'Choose one primary responsible office.' using errcode = '22023';
    end if;
    if cardinality(v_office_ids) > 0 and (
      select count(*) from public."cmp_Offices" office
      where office."Office_ID" = any(v_office_ids)
        and office."Company_ID" = v_profile."CRMAccount_CompanyID"
        and office."Office_IsActive"
    ) <> cardinality(v_office_ids) then
      raise exception 'Choose active offices from this company.' using errcode = '22023';
    end if;
  end if;

  if p_input ? 'isPotential' and not v_is_potential and v_org."Org_CRMIsPotentialCustomer" then
    if not exists (
      select 1 from public."Org_AddressTypes" link
      join public."sys_AddressTypes" type on type."sys_AddressType_ID" = link."OrgAddType_Type"
      join public."Org_Addresses" address on address."OrgAdd_ID" = link."OrgAdd_ID" and address."OrgAdd_IsActive"
      where link."OrgAddType_OrgID" = p_account_id and type."sys_AddressType_Code" = 'main' and link."OrgAddType_IsDefault"
    ) then
      raise exception 'Add a main address before making this an active organisation.' using errcode = '22023';
    end if;
    if not (
      (p_input ? 'officeAssignments' and v_primary_count = 1)
      or (not (p_input ? 'officeAssignments') and exists (
        select 1 from public."CRM_AccountOfficeAssignments" assignment
        where assignment."CRMAccountOffice_AccountID" = v_profile."CRMAccount_ID"
          and assignment."CRMAccountOffice_IsPrimary"
      ))
    ) then
      raise exception 'Choose a primary responsible office before making this an active organisation.' using errcode = '22023';
    end if;
  end if;

  v_next_version := v_profile."CRMAccount_EditVersion" + 1;
  update public."Org_Master"
  set "Org_AccCode" = v_code,
      "Org_CRMIsPotentialCustomer" = v_is_potential,
      "Org_CRMUpdatedAt" = now()
  where "Org_id" = p_account_id;
  update public."CRM_AccountProfiles"
  set "CRMAccount_ScopeCode" = v_scope,
      "CRMAccount_UpdatedAt" = now(),
      "CRMAccount_UpdatedBy" = p_actor_user_id,
      "CRMAccount_EditVersion" = v_next_version
  where "CRMAccount_ID" = v_profile."CRMAccount_ID";

  if p_input ? 'officeAssignments' then
    delete from public."CRM_AccountOfficeAssignments"
    where "CRMAccountOffice_AccountID" = v_profile."CRMAccount_ID";
    for v_office in select value from jsonb_array_elements(v_offices) loop
      insert into public."CRM_AccountOfficeAssignments"(
        "CRMAccountOffice_AccountID", "CRMAccountOffice_CompanyID", "CRMAccountOffice_OrgOfficeID",
        "CRMAccountOffice_IsPrimary", "CRMAccountOffice_CreatedBy"
      ) values (
        v_profile."CRMAccount_ID", v_profile."CRMAccount_CompanyID", (v_office ->> 'officeId')::uuid,
        coalesce((v_office ->> 'isPrimary')::boolean, false), p_actor_user_id
      );
    end loop;
    update public."CRM_AccountProfiles"
    set "CRMAccount_OrgOfficeID" = v_primary_office
    where "CRMAccount_ID" = v_profile."CRMAccount_ID";
  end if;

  return jsonb_build_object(
    'id', p_account_id, 'editVersion', v_next_version, 'accountCode', v_code,
    'scopeCode', v_scope, 'isPotential', v_is_potential
  );
exception when unique_violation then
  raise exception 'That organisation code is already in use.' using errcode = '23505';
end;
$$;


ALTER FUNCTION "public"."multideck_crm_update_organisation_foundation"("p_actor_user_id" "uuid", "p_account_id" "uuid", "p_expected_version" bigint, "p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_crm_upsert_organisation_address"("p_actor_user_id" "uuid", "p_account_id" "uuid", "p_address_id" "uuid", "p_expected_version" bigint, "p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  v_profile public."CRM_AccountProfiles"%rowtype;
  v_address_id uuid := coalesce(p_address_id, gen_random_uuid());
  v_country text := upper(nullif(btrim(p_input ->> 'countryCode'), ''));
  v_timezone text := coalesce(nullif(btrim(p_input ->> 'timeZone'), ''), 'UTC');
  v_capabilities jsonb := coalesce(p_input -> 'capabilities', '[]'::jsonb);
  v_hours jsonb := coalesce(p_input -> 'weeklyHours', '[]'::jsonb);
  v_overrides jsonb := coalesce(p_input -> 'openingOverrides', '[]'::jsonb);
  v_item jsonb;
  v_type_id integer;
  v_type_ids integer[] := '{}'::integer[];
  v_day integer;
  v_opens time;
  v_closes time;
  v_override_date date;
  v_is_closed boolean;
  v_next_version bigint;
begin
  perform public._multideck_crm_write_actor(p_actor_user_id);
  perform public._multideck_crm_require_account_access(p_actor_user_id, p_account_id);
  if jsonb_typeof(coalesce(p_input, '{}'::jsonb)) <> 'object' then
    raise exception 'Enter valid address details.' using errcode = '22023';
  end if;

  select * into v_profile
  from public."CRM_AccountProfiles"
  where "CRMAccount_OrgID" = p_account_id and not "CRMAccount_IsDeleted"
  order by "CRMAccount_ID" limit 1 for update;
  if not found then raise exception 'Organisation not found.' using errcode = 'P0002'; end if;
  if p_expected_version is null or p_expected_version <> v_profile."CRMAccount_EditVersion" then
    raise exception 'CRM_CONFLICT:This organisation changed since it was loaded.' using errcode = 'P0001';
  end if;
  if v_country is not null and v_country !~ '^[A-Z]{2}$' then
    raise exception 'Choose a two-letter country code.' using errcode = '22023';
  end if;
  if not exists (select 1 from pg_catalog.pg_timezone_names where name = v_timezone) then
    raise exception 'Choose a recognised time zone.' using errcode = '22023';
  end if;
  if jsonb_typeof(v_capabilities) <> 'array' or jsonb_array_length(v_capabilities) > 12 then
    raise exception 'Choose valid address capabilities.' using errcode = '22023';
  end if;
  if jsonb_typeof(v_hours) <> 'array' or jsonb_array_length(v_hours) > 28 then
    raise exception 'Enter no more than four opening intervals per day.' using errcode = '22023';
  end if;
  if jsonb_typeof(v_overrides) <> 'array' or jsonb_array_length(v_overrides) > 120 then
    raise exception 'Enter no more than 120 opening-hour overrides.' using errcode = '22023';
  end if;
  if coalesce(nullif(btrim(p_input ->> 'line1'), ''), nullif(btrim(p_input ->> 'townCity'), ''), v_country) is null then
    raise exception 'Enter at least an address line, town or country.' using errcode = '22023';
  end if;

  if p_address_id is null then
    insert into public."Org_Addresses"(
      "OrgAdd_ID", "Org_ID", "Org_NameOverride", "OrgAdd_Line1", "OrgAdd_Line2",
      "OrgAdd_TownCity", "OrgAdd_CountyState", "OrgAdd_PostZipCode", "OrgAdd_Country",
      "OrgAdd_UNLOCODE", "OrgAdd_MainEmail", "OrgAdd_MainPhone", "OrgAdd_TimeZone",
      "OrgAdd_IsActive", "OrgAdd_UpdatedAt", "OrgAdd_UpdatedBy"
    ) values (
      v_address_id, p_account_id, nullif(btrim(p_input ->> 'name'), ''),
      nullif(btrim(p_input ->> 'line1'), ''), nullif(btrim(p_input ->> 'line2'), ''),
      nullif(btrim(p_input ->> 'townCity'), ''), nullif(btrim(p_input ->> 'countyState'), ''),
      nullif(btrim(p_input ->> 'postZipCode'), ''), v_country,
      upper(nullif(btrim(p_input ->> 'unlocode'), '')), lower(nullif(btrim(p_input ->> 'email'), '')),
      nullif(btrim(p_input ->> 'phone'), ''), v_timezone, true, now(), p_actor_user_id
    );
  else
    update public."Org_Addresses"
    set "Org_NameOverride" = nullif(btrim(p_input ->> 'name'), ''),
        "OrgAdd_Line1" = nullif(btrim(p_input ->> 'line1'), ''),
        "OrgAdd_Line2" = nullif(btrim(p_input ->> 'line2'), ''),
        "OrgAdd_TownCity" = nullif(btrim(p_input ->> 'townCity'), ''),
        "OrgAdd_CountyState" = nullif(btrim(p_input ->> 'countyState'), ''),
        "OrgAdd_PostZipCode" = nullif(btrim(p_input ->> 'postZipCode'), ''),
        "OrgAdd_Country" = v_country,
        "OrgAdd_UNLOCODE" = upper(nullif(btrim(p_input ->> 'unlocode'), '')),
        "OrgAdd_MainEmail" = lower(nullif(btrim(p_input ->> 'email'), '')),
        "OrgAdd_MainPhone" = nullif(btrim(p_input ->> 'phone'), ''),
        "OrgAdd_TimeZone" = v_timezone,
        "OrgAdd_IsActive" = true,
        "OrgAdd_UpdatedAt" = now(),
        "OrgAdd_UpdatedBy" = p_actor_user_id
    where "OrgAdd_ID" = p_address_id and "Org_ID" = p_account_id;
    if not found then raise exception 'Address not found.' using errcode = 'P0002'; end if;
  end if;

  delete from public."Org_AddressTypes" where "OrgAdd_ID" = v_address_id;
  for v_item in select value from jsonb_array_elements(v_capabilities) loop
    select type."sys_AddressType_ID" into v_type_id
    from public."sys_AddressTypes" type
    where type."sys_AddressType_Code" = lower(btrim(v_item ->> 'code'))
      and type."sys_AddressType_IsActive";
    if v_type_id is null or v_type_id = any(v_type_ids) then
      raise exception 'Choose each valid address capability once.' using errcode = '22023';
    end if;
    v_type_ids := array_append(v_type_ids, v_type_id);
    if coalesce((v_item ->> 'isDefault')::boolean, false) then
      update public."Org_AddressTypes"
      set "OrgAddType_IsDefault" = false
      where "OrgAddType_OrgID" = p_account_id and "OrgAddType_Type" = v_type_id;
    end if;
    insert into public."Org_AddressTypes"(
      "OrgAdd_ID", "OrgAddType_Type", "OrgAddType_IsDefault", "OrgAddType_OrgID"
    ) values (
      v_address_id, v_type_id, coalesce((v_item ->> 'isDefault')::boolean, false), p_account_id
    );
  end loop;

  delete from public."Org_AddressOpeningHours" where "OrgAddHours_OrgAddID" = v_address_id;
  for v_item in select value from jsonb_array_elements(v_hours) loop
    v_day := (v_item ->> 'dayOfWeek')::integer;
    v_opens := (v_item ->> 'opensAt')::time;
    v_closes := (v_item ->> 'closesAt')::time;
    if v_day not between 0 and 6 or v_opens >= v_closes then
      raise exception 'Enter valid weekly opening intervals.' using errcode = '22023';
    end if;
    if exists (
      select 1 from public."Org_AddressOpeningHours" hours
      where hours."OrgAddHours_OrgAddID" = v_address_id
        and hours."OrgAddHours_DayOfWeek" = v_day
        and hours."OrgAddHours_OpensAt" < v_closes
        and v_opens < hours."OrgAddHours_ClosesAt"
    ) then
      raise exception 'Opening intervals cannot overlap.' using errcode = '22023';
    end if;
    insert into public."Org_AddressOpeningHours"(
      "OrgAddHours_OrgAddID", "OrgAddHours_DayOfWeek", "OrgAddHours_OpensAt", "OrgAddHours_ClosesAt", "OrgAddHours_SortOrder"
    ) values (v_address_id, v_day, v_opens, v_closes, coalesce((v_item ->> 'sortOrder')::integer, 0));
  end loop;

  delete from public."Org_AddressOpeningOverrides" where "OrgAddOverride_OrgAddID" = v_address_id;
  for v_item in select value from jsonb_array_elements(v_overrides) loop
    v_override_date := (v_item ->> 'date')::date;
    v_is_closed := coalesce((v_item ->> 'isClosed')::boolean, false);
    v_opens := nullif(v_item ->> 'opensAt', '')::time;
    v_closes := nullif(v_item ->> 'closesAt', '')::time;
    if (v_is_closed and (v_opens is not null or v_closes is not null))
      or (not v_is_closed and (v_opens is null or v_closes is null or v_opens >= v_closes)) then
      raise exception 'Enter valid dated opening-hour overrides.' using errcode = '22023';
    end if;
    insert into public."Org_AddressOpeningOverrides"(
      "OrgAddOverride_OrgAddID", "OrgAddOverride_Date", "OrgAddOverride_IsClosed",
      "OrgAddOverride_OpensAt", "OrgAddOverride_ClosesAt", "OrgAddOverride_Note"
    ) values (
      v_address_id, v_override_date, v_is_closed, v_opens, v_closes,
      left(nullif(btrim(v_item ->> 'note'), ''), 240)
    );
  end loop;

  v_next_version := v_profile."CRMAccount_EditVersion" + 1;
  update public."CRM_AccountProfiles"
  set "CRMAccount_EditVersion" = v_next_version, "CRMAccount_UpdatedAt" = now(), "CRMAccount_UpdatedBy" = p_actor_user_id
  where "CRMAccount_ID" = v_profile."CRMAccount_ID";
  return jsonb_build_object('id', v_address_id, 'accountId', p_account_id, 'editVersion', v_next_version);
end;
$_$;


ALTER FUNCTION "public"."multideck_crm_upsert_organisation_address"("p_actor_user_id" "uuid", "p_account_id" "uuid", "p_address_id" "uuid", "p_expected_version" bigint, "p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_crm_upsert_related_party_default"("p_actor_user_id" "uuid", "p_source_org_id" "uuid", "p_rule_id" "uuid", "p_expected_version" bigint, "p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  v_profile public."CRM_AccountProfiles"%rowtype;
  v_company_id uuid;
  v_target_org_id uuid := nullif(p_input ->> 'targetOrganisationId', '')::uuid;
  v_target_address_id uuid := nullif(p_input ->> 'targetAddressId', '')::uuid;
  v_target_contact_id uuid := nullif(p_input ->> 'targetContactId', '')::uuid;
  v_role text := lower(nullif(btrim(p_input ->> 'partyRoleCode'), ''));
  v_country text := upper(nullif(btrim(p_input ->> 'destinationCountryCode'), ''));
  v_unlocode text := upper(nullif(btrim(p_input ->> 'destinationUnlocode'), ''));
  v_postcode text := upper(nullif(btrim(p_input ->> 'destinationPostcode'), ''));
  v_rule_id uuid := coalesce(p_rule_id, gen_random_uuid());
  v_next_version bigint;
begin
  perform public._multideck_crm_write_actor(p_actor_user_id);
  perform public._multideck_crm_require_account_access(p_actor_user_id, p_source_org_id);
  perform public._multideck_crm_require_account_access(p_actor_user_id, v_target_org_id);
  select * into v_profile from public."CRM_AccountProfiles"
  where "CRMAccount_OrgID" = p_source_org_id and not "CRMAccount_IsDeleted"
  order by "CRMAccount_ID" limit 1 for update;
  if not found then raise exception 'Organisation not found.' using errcode = 'P0002'; end if;
  if p_expected_version is null or p_expected_version <> v_profile."CRMAccount_EditVersion" then
    raise exception 'CRM_CONFLICT:This organisation changed since it was loaded.' using errcode = 'P0001';
  end if;
  v_company_id := v_profile."CRMAccount_CompanyID";
  if v_role is null or v_role !~ '^[a-z0-9_\-]{2,60}$' then
    raise exception 'Choose a valid related-party role.' using errcode = '22023';
  end if;
  if v_country is not null and v_country !~ '^[A-Z]{2}$' then
    raise exception 'Choose a two-letter destination country code.' using errcode = '22023';
  end if;
  if v_target_address_id is not null and not exists (
    select 1 from public."Org_Addresses" where "OrgAdd_ID" = v_target_address_id and "Org_ID" = v_target_org_id and "OrgAdd_IsActive"
  ) then raise exception 'Choose an active address for the related organisation.' using errcode = '22023'; end if;
  if v_target_contact_id is not null and not exists (
    select 1 from public."Org_Contacts" where "OrgContact_ID" = v_target_contact_id and "Org_ID" = v_target_org_id
  ) then raise exception 'Choose a contact from the related organisation.' using errcode = '22023'; end if;

  insert into public."Org_RelatedPartyDefaults"(
    "OrgRelatedDefault_ID", "OrgRelatedDefault_CompanyID", "OrgRelatedDefault_SourceOrgID",
    "OrgRelatedDefault_PartyRoleCode", "OrgRelatedDefault_DestinationCountryCode",
    "OrgRelatedDefault_DestinationUNLOCODE", "OrgRelatedDefault_DestinationPostcode",
    "OrgRelatedDefault_TargetOrgID", "OrgRelatedDefault_TargetAddressID", "OrgRelatedDefault_TargetContactID",
    "OrgRelatedDefault_Priority", "OrgRelatedDefault_EffectiveFrom", "OrgRelatedDefault_EffectiveTo",
    "OrgRelatedDefault_IsActive", "OrgRelatedDefault_CreatedBy", "OrgRelatedDefault_UpdatedBy"
  ) values (
    v_rule_id, v_company_id, p_source_org_id, v_role, v_country, v_unlocode, v_postcode,
    v_target_org_id, v_target_address_id, v_target_contact_id,
    greatest(1, least(coalesce((p_input ->> 'priority')::integer, 100), 10000)),
    coalesce(nullif(p_input ->> 'effectiveFrom', '')::date, current_date),
    nullif(p_input ->> 'effectiveTo', '')::date,
    coalesce((p_input ->> 'isActive')::boolean, true), p_actor_user_id, p_actor_user_id
  )
  on conflict ("OrgRelatedDefault_ID") do update set
    "OrgRelatedDefault_PartyRoleCode" = excluded."OrgRelatedDefault_PartyRoleCode",
    "OrgRelatedDefault_DestinationCountryCode" = excluded."OrgRelatedDefault_DestinationCountryCode",
    "OrgRelatedDefault_DestinationUNLOCODE" = excluded."OrgRelatedDefault_DestinationUNLOCODE",
    "OrgRelatedDefault_DestinationPostcode" = excluded."OrgRelatedDefault_DestinationPostcode",
    "OrgRelatedDefault_TargetOrgID" = excluded."OrgRelatedDefault_TargetOrgID",
    "OrgRelatedDefault_TargetAddressID" = excluded."OrgRelatedDefault_TargetAddressID",
    "OrgRelatedDefault_TargetContactID" = excluded."OrgRelatedDefault_TargetContactID",
    "OrgRelatedDefault_Priority" = excluded."OrgRelatedDefault_Priority",
    "OrgRelatedDefault_EffectiveFrom" = excluded."OrgRelatedDefault_EffectiveFrom",
    "OrgRelatedDefault_EffectiveTo" = excluded."OrgRelatedDefault_EffectiveTo",
    "OrgRelatedDefault_IsActive" = excluded."OrgRelatedDefault_IsActive",
    "OrgRelatedDefault_UpdatedAt" = now(),
    "OrgRelatedDefault_UpdatedBy" = p_actor_user_id
  where public."Org_RelatedPartyDefaults"."OrgRelatedDefault_CompanyID" = v_company_id
    and public."Org_RelatedPartyDefaults"."OrgRelatedDefault_SourceOrgID" = p_source_org_id;
  if not found then raise exception 'Related-party default not found.' using errcode = 'P0002'; end if;
  v_next_version := v_profile."CRMAccount_EditVersion" + 1;
  update public."CRM_AccountProfiles"
  set "CRMAccount_EditVersion" = v_next_version, "CRMAccount_UpdatedAt" = now(), "CRMAccount_UpdatedBy" = p_actor_user_id
  where "CRMAccount_ID" = v_profile."CRMAccount_ID";
  return jsonb_build_object('id', v_rule_id, 'accountId', p_source_org_id, 'editVersion', v_next_version);
end;
$_$;


ALTER FUNCTION "public"."multideck_crm_upsert_related_party_default"("p_actor_user_id" "uuid", "p_source_org_id" "uuid", "p_rule_id" "uuid", "p_expected_version" bigint, "p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_crm_win_deal"("p_deal_id" "uuid", "p_pipeline_stage_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare v_context record;
begin
  select * into v_context from public._multideck_crm_context();
  if not public._multideck_crm_deal_is_operator_visible(p_deal_id, v_context.company_id) then
    raise exception 'Deal not found.' using errcode = 'P0002';
  end if;
  return public._multideck_crm_win_deal_unfiltered_20260818(
    p_deal_id,
    p_pipeline_stage_id,
    p_reason
  );
end;
$$;


ALTER FUNCTION "public"."multideck_crm_win_deal"("p_deal_id" "uuid", "p_pipeline_stage_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_customer_directory_page"("p_scope" "text" DEFAULT 'all'::"text", "p_status" "text" DEFAULT 'All'::"text", "p_limit" integer DEFAULT 20, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_context record;
  v_scope text := case when lower(coalesce(p_scope, 'all')) = 'mine' then 'mine' else 'all' end;
  v_status text := case lower(coalesce(nullif(btrim(p_status), ''), 'all'))
    when 'premium' then 'Premium'
    when 'standard' then 'Standard'
    when 'trial' then 'Trial'
    when 'new' then 'New'
    else 'All'
  end;
  v_limit integer := greatest(1, least(coalesce(p_limit, 20), 50));
  v_offset integer := greatest(0, coalesce(p_offset, 0));
  v_result jsonb;
begin
  select * into v_context from public._multideck_crm_context();
  if not public._multideck_crm_has_permission(v_context.user_id, 'Customers.Read') then
    raise exception 'You do not have permission to view customers.' using errcode = '42501';
  end if;

  with base as materialized (
    select
      org."Org_id" as id,
      coalesce(org."Org_Name", '') as name,
      profile."CRMAccount_OwnerUserID" as owner_id,
      case profile."CRMAccount_Tier"
        when 'A' then 'Premium'
        when 'Premium' then 'Premium'
        when 'Trial' then 'Trial'
        when 'New' then 'New'
        else 'Standard'
      end as status
    from public.multideck_crm_accessible_account_ids(v_context.company_id) accessible
    join public."Org_Master" org on org."Org_id" = accessible.account_id
    left join public."CRM_AccountProfiles" profile
      on profile."CRMAccount_OrgID" = org."Org_id"
     and not profile."CRMAccount_IsDeleted"
    where coalesce(org."Org_CRMIsPotentialCustomer", false)
       or exists (
         select 1
         from public."Org_Master_Type" link
         join public."Org_Types" type on type."OrgType_ID" = link."OrgType_ID"
         where link."Org_ID" = org."Org_id"
           and lower(type."OrgType_Name") = 'customer'
       )
  ), scoped as materialized (
    select *
    from base
    where v_scope = 'all' or owner_id = v_context.user_id
  ), filtered as materialized (
    select *
    from scoped
    where v_status = 'All' or status = v_status
  ), ranked as (
    select id, row_number() over (order by lower(name), id) as ordinal
    from filtered
  ), page as (
    select id, ordinal
    from ranked
    where ordinal > v_offset and ordinal <= v_offset + v_limit
  )
  select jsonb_build_object(
    'ids', coalesce((select jsonb_agg(id order by ordinal) from page), '[]'::jsonb),
    'total', (select count(*) from filtered),
    'scopeTotal', (select count(*) from scoped),
    'statusCounts', jsonb_build_object(
      'All', (select count(*) from scoped),
      'Premium', (select count(*) from scoped where status = 'Premium'),
      'Standard', (select count(*) from scoped where status = 'Standard'),
      'Trial', (select count(*) from scoped where status = 'Trial'),
      'New', (select count(*) from scoped where status = 'New')
    )
  ) into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."multideck_customer_directory_page"("p_scope" "text", "p_status" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_customs_assignees_by_ids"("p_user_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth', 'booking_api'
    AS $$
declare
  v_actor record;
  v_ids uuid[] := coalesce(p_user_ids, '{}'::uuid[]);
  v_result jsonb;
begin
  if cardinality(v_ids) > 50 then
    raise exception 'Choose up to 50 Customs assignees.' using errcode = '22023';
  end if;
  select workspace_user."User_ID", workspace_user."Company_ID" into v_actor
  from public."cmp_Users" workspace_user
  where workspace_user."Auth_User_ID" = auth.uid()
    and coalesce(workspace_user."User_AccessStatus", 'active') = 'active';
  if v_actor."User_ID" is null
     or not booking_api.has_permission(auth.uid(), 'Customs.Read') then
    raise exception 'You do not have permission to view Customs assignees.' using errcode = '42501';
  end if;

  select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
    'id', workspace_user."User_ID",
    'displayName', coalesce(nullif(btrim(concat_ws(' ', workspace_user."User_Firstname", workspace_user."User_Lastname")), ''), workspace_user."User_Email", 'Unnamed user'),
    'firstName', workspace_user."User_Firstname",
    'lastName', workspace_user."User_Lastname",
    'email', workspace_user."User_Email",
    'jobTitle', workspace_user."User_JobTitle",
    'canWorkCustoms', booking_api.has_permission(workspace_user."Auth_User_ID", 'Customs.Write'),
    'profilePhoto', case when workspace_user."User_ProfilePhotoPath" is null then null else jsonb_build_object(
      'bucket', workspace_user."User_ProfilePhotoBucket",
      'path', workspace_user."User_ProfilePhotoPath",
      'mimeType', workspace_user."User_ProfilePhotoMimeType",
      'sizeBytes', workspace_user."User_ProfilePhotoSizeBytes",
      'updatedAt', workspace_user."User_ProfilePhotoUpdatedAt"
    ) end
  )) order by workspace_user."User_ID"), '[]'::jsonb) into v_result
  from public."cmp_Users" workspace_user
  where workspace_user."Company_ID" = v_actor."Company_ID"
    and workspace_user."User_ID" = any(v_ids)
    and coalesce(workspace_user."User_AccessStatus", 'active') <> 'deleted';
  return v_result;
end;
$$;


ALTER FUNCTION "public"."multideck_customs_assignees_by_ids"("p_user_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_customs_assignment_users_page"("p_search" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth', 'booking_api'
    AS $$
declare
  v_actor record;
  v_search text := left(lower(btrim(coalesce(p_search, ''))), 200);
  v_pattern text;
  v_limit integer := least(greatest(coalesce(p_limit, 50), 1), 50);
  v_offset integer := least(greatest(coalesce(p_offset, 0), 0), 1000000);
  v_result jsonb;
begin
  select workspace_user."User_ID", workspace_user."Company_ID"
  into v_actor
  from public."cmp_Users" workspace_user
  where workspace_user."Auth_User_ID" = auth.uid()
    and coalesce(workspace_user."User_AccessStatus", 'active') = 'active';

  if v_actor."User_ID" is null
     or not booking_api.has_permission(auth.uid(), 'Customs.Read') then
    raise exception 'You do not have permission to view Customs assignees.' using errcode = '42501';
  end if;

  v_pattern := '%' || replace(replace(replace(v_search, E'\\', E'\\\\'), '%', E'\\%'), '_', E'\\_') || '%';

  with eligible as materialized (
    select
      workspace_user."User_ID" as id,
      workspace_user."User_Firstname"::text as first_name,
      workspace_user."User_Lastname"::text as last_name,
      coalesce(
        nullif(btrim(concat_ws(' ', workspace_user."User_Firstname", workspace_user."User_Lastname")), ''),
        workspace_user."User_Email",
        'Unnamed user'
      ) as display_name,
      workspace_user."User_Email"::text as email,
      workspace_user."User_JobTitle"::text as job_title,
      workspace_user."User_ProfilePhotoBucket"::text as photo_bucket,
      workspace_user."User_ProfilePhotoPath"::text as photo_path,
      workspace_user."User_ProfilePhotoMimeType"::text as photo_mime_type,
      workspace_user."User_ProfilePhotoSizeBytes" as photo_size_bytes,
      workspace_user."User_ProfilePhotoUpdatedAt" as photo_updated_at,
      booking_api.has_permission(workspace_user."Auth_User_ID", 'Customs.Write') as can_work_customs
    from public."cmp_Users" workspace_user
    where workspace_user."Company_ID" = v_actor."Company_ID"
      and workspace_user."Auth_User_ID" is not null
      and coalesce(workspace_user."User_AccessStatus", 'active') = 'active'
      and (
        v_search = ''
        or lower(coalesce(workspace_user."User_Firstname", '') || ' ' || coalesce(workspace_user."User_Lastname", '')) like v_pattern escape E'\\'
        or lower(coalesce(workspace_user."User_Email", '')) like v_pattern escape E'\\'
      )
  ), page as materialized (
    select eligible.* from eligible
    order by lower(eligible.display_name), lower(eligible.email), eligible.id
    offset v_offset limit v_limit
  )
  select jsonb_build_object(
    'users', coalesce((select jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
      'id', page.id,
      'displayName', page.display_name,
      'firstName', page.first_name,
      'lastName', page.last_name,
      'email', page.email,
      'jobTitle', page.job_title,
      'canWorkCustoms', page.can_work_customs,
      'profilePhoto', case when page.photo_path is null then null else jsonb_build_object(
        'bucket', page.photo_bucket,
        'path', page.photo_path,
        'mimeType', page.photo_mime_type,
        'sizeBytes', page.photo_size_bytes,
        'updatedAt', page.photo_updated_at
      ) end
    )) order by lower(page.display_name), lower(page.email), page.id) from page), '[]'::jsonb),
    'total', (select count(*) from eligible),
    'limit', v_limit,
    'offset', v_offset
  ) into v_result;
  return v_result;
end;
$$;


ALTER FUNCTION "public"."multideck_customs_assignment_users_page"("p_search" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_customs_declaration_register_page"("p_direction" "text", "p_scope" "text", "p_search" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text", "p_destination" "text" DEFAULT NULL::"text", "p_sort" "text" DEFAULT 'lastSaved'::"text", "p_sort_direction" "text" DEFAULT 'desc'::"text", "p_limit" integer DEFAULT 10, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_direction text := lower(coalesce(nullif(btrim(p_direction), ''), ''));
  v_scope text := lower(coalesce(nullif(btrim(p_scope), ''), ''));
  v_search text := nullif(btrim(p_search), '');
  v_status text := nullif(btrim(p_status), '');
  v_destination text := upper(nullif(btrim(p_destination), ''));
  v_sort text := coalesce(nullif(btrim(p_sort), ''), 'lastSaved');
  v_sort_direction text := lower(coalesce(nullif(btrim(p_sort_direction), ''), 'desc'));
  v_limit integer := greatest(1, least(coalesce(p_limit, 10), 50));
  v_offset integer := greatest(0, coalesce(p_offset, 0));
  v_result jsonb;
begin
  if auth.uid() is null then raise exception 'Authentication required.' using errcode = '42501'; end if;
  if v_direction not in ('export', 'import') then raise exception 'Choose a valid declaration direction.' using errcode = '22023'; end if;
  if v_scope not in ('standalone', 'job-related') then raise exception 'Choose a valid declaration scope.' using errcode = '22023'; end if;
  if v_sort_direction not in ('asc', 'desc') then raise exception 'Choose a valid sort direction.' using errcode = '22023'; end if;
  if v_sort not in ('assignedTo','submittedBy','reference','jobReference','status','traderReference','items','destination','value','lastSaved') then
    raise exception 'Choose a valid declaration sort.' using errcode = '22023';
  end if;

  with scoped as materialized (
    select
      declaration."CUST_id" as id,
      declaration."CUST_CreatedBy"::text as submitted_by,
      declaration."CUST_AssignedUserID" as assigned_user_id,
      declaration."CUST_JobID" as job_id,
      booking."Job_Reference"::text as job_reference,
      booking."Booking_Reference"::text as booking_reference,
      booking."Customer_Name"::text as customer_name,
      booking."Route"::text as route,
      coalesce(declaration."CUST_LocalReferenceNumber", declaration."CUST_id"::text) as reference,
      declaration."CUST_TraderReference"::text as trader_reference,
      declaration."CUST_Status"::text as status,
      declaration."CUST_CountryOfDestinationCodeSnapshot"::text as destination_country,
      declaration."CUST_InvoiceAmount" as amount,
      declaration."CUST_InvoiceCurrencyCodeSnapshot"::text as currency,
      case when jsonb_typeof(declaration."CUST_GenericPayloadJSON" -> 'items') = 'array'
        then jsonb_array_length(declaration."CUST_GenericPayloadJSON" -> 'items') else 0 end as item_count,
      declaration."CUST_CreatedAt" as created_at,
      declaration."CUST_UpdatedAt" as updated_at
    from public."Customs_Declarations" declaration
    left join public."App_Live_Bookings" booking on booking."Job_ID" = declaration."CUST_JobID"
    where declaration."CUST_Direction" = v_direction
      and declaration."CUST_DeclarationKind" = 'cds_' || v_direction
      and not declaration."CUST_IsDeleted"
      and case when v_scope = 'standalone' then declaration."CUST_JobID" is null else declaration."CUST_JobID" is not null end
  ), searchable as materialized (
    select scoped.*,
      concat_ws(' ', reference, job_reference, booking_reference, customer_name, route, trader_reference, status, destination_country, currency, amount::text) as search_text
    from scoped
  ), filtered as materialized (
    select * from searchable
    where (v_status is null or status = v_status)
      and (v_destination is null or destination_country = v_destination)
      and (v_search is null or strpos(lower(search_text), lower(v_search)) > 0)
  ), ranked as materialized (
    select *, row_number() over (
      order by
        case when v_sort_direction = 'asc' then case v_sort
          when 'assignedTo' then assigned_user_id::text when 'submittedBy' then lower(submitted_by) when 'reference' then lower(reference)
          when 'jobReference' then lower(coalesce(job_reference, job_id::text)) when 'status' then lower(status)
          when 'traderReference' then lower(trader_reference) when 'destination' then lower(destination_country) end end asc nulls last,
        case when v_sort_direction = 'desc' then case v_sort
          when 'assignedTo' then assigned_user_id::text when 'submittedBy' then lower(submitted_by) when 'reference' then lower(reference)
          when 'jobReference' then lower(coalesce(job_reference, job_id::text)) when 'status' then lower(status)
          when 'traderReference' then lower(trader_reference) when 'destination' then lower(destination_country) end end desc nulls last,
        case when v_sort_direction = 'asc' then case v_sort when 'items' then item_count when 'value' then amount end end asc nulls last,
        case when v_sort_direction = 'desc' then case v_sort when 'items' then item_count when 'value' then amount end end desc nulls last,
        case when v_sort_direction = 'asc' and v_sort = 'lastSaved' then updated_at end asc nulls last,
        case when v_sort_direction = 'desc' and v_sort = 'lastSaved' then updated_at end desc nulls last,
        updated_at desc, id
    ) as ordinal from filtered
  ), page as materialized (
    select * from ranked where ordinal > v_offset and ordinal <= v_offset + v_limit
  )
  select jsonb_build_object(
    'rows', coalesce((select jsonb_agg(jsonb_build_object(
      'id', id, 'submittedBy', submitted_by, 'assignedUserId', assigned_user_id,
      'jobId', job_id, 'jobReference', job_reference, 'bookingReference', booking_reference,
      'customerName', customer_name, 'route', route, 'reference', reference,
      'traderReference', trader_reference, 'status', status,
      'destinationCountry', destination_country, 'amount', amount, 'currency', currency,
      'itemCount', item_count, 'createdAt', created_at, 'updatedAt', updated_at
    ) order by ordinal) from page), '[]'::jsonb),
    'total', (select count(*) from filtered),
    'availableTotal', (select count(*) from scoped),
    'facets', jsonb_build_object(
      'statuses', coalesce((select jsonb_agg(status order by status) from (select distinct status from scoped where nullif(btrim(status), '') is not null) valueset), '[]'::jsonb),
      'destinations', coalesce((select jsonb_agg(destination_country order by destination_country) from (select distinct destination_country from scoped where nullif(btrim(destination_country), '') is not null) valueset), '[]'::jsonb)
    )
  ) into v_result;
  return v_result;
end;
$$;


ALTER FUNCTION "public"."multideck_customs_declaration_register_page"("p_direction" "text", "p_scope" "text", "p_search" "text", "p_status" "text", "p_destination" "text", "p_sort" "text", "p_sort_direction" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."multideck_customs_declaration_register_page"("p_direction" "text", "p_scope" "text", "p_search" "text", "p_status" "text", "p_destination" "text", "p_sort" "text", "p_sort_direction" "text", "p_limit" integer, "p_offset" integer) IS 'RLS-preserving Customs declaration register read with exact totals/facets and a maximum 50-row page.';



CREATE OR REPLACE FUNCTION "public"."multideck_dashboard_drilldown_page"("p_kind" "text", "p_value" "text", "p_window_start" timestamp with time zone, "p_window_end" timestamp with time zone, "p_time_zone" "text" DEFAULT 'UTC'::"text", "p_limit" integer DEFAULT 50, "p_cursor_sort_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_cursor_row_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_kind text := lower(coalesce(nullif(btrim(p_kind), ''), ''));
  v_value text := upper(coalesce(nullif(btrim(p_value), ''), ''));
  v_limit integer := greatest(1, least(coalesce(p_limit, 50), 50));
  v_time_zone text := coalesce(nullif(btrim(p_time_zone), ''), 'UTC');
  v_result jsonb;
begin
  if auth.uid() is null then
    raise exception 'Authentication required.' using errcode = '42501';
  end if;
  if v_kind not in ('active_jobs', 'booking_exceptions', 'open_quotes', 'ready_quotes', 'region') then
    raise exception 'Choose a valid dashboard drilldown.' using errcode = '22023';
  end if;
  if v_kind = 'region' and v_value not in ('LAX','CHI','NYC','YYZ','GRU','LDN','AMS','FRA','IST','DXB','BOM','SIN','HKG','SHA','TYO','SYD') then
    raise exception 'Choose a valid dashboard operating region.' using errcode = '22023';
  end if;
  if p_window_start is null or p_window_end is null or p_window_end <= p_window_start then
    raise exception 'Choose a valid dashboard date range.' using errcode = '22007';
  end if;
  if (p_cursor_sort_at is null) <> (p_cursor_row_key is null) then
    raise exception 'The dashboard cursor is incomplete.' using errcode = '22023';
  end if;
  perform 1 from pg_catalog.pg_timezone_names where name = v_time_zone;
  if not found then
    raise exception 'Choose a valid dashboard time zone.' using errcode = '22023';
  end if;

  with
  region_terms(code, terms) as (
    values
      ('LAX'::text, array['Los Angeles','Long Beach','USLAX']::text[]),
      ('CHI', array['Chicago','USCHI']::text[]),
      ('NYC', array['New York','JFK','USJFK']::text[]),
      ('YYZ', array['Toronto','CATOR']::text[]),
      ('GRU', array['Sao Paulo','Santos','BRSSZ']::text[]),
      ('LDN', array['London','Heathrow','GBLHR','Felixstowe','GBFXT','Bristol','GBBRS','Southampton','GBSOU','Gateway','Manchester','Birmingham']::text[]),
      ('AMS', array['Amsterdam','Rotterdam','NLRTM']::text[]),
      ('FRA', array['Frankfurt','DEFRA','Hamburg','DEHAM']::text[]),
      ('IST', array['Istanbul','TRIST']::text[]),
      ('DXB', array['Dubai','AEDXB']::text[]),
      ('BOM', array['Mumbai','Nhava Sheva','INNSA']::text[]),
      ('SIN', array['Singapore','SGSIN']::text[]),
      ('HKG', array['Hong Kong','HKHKG']::text[]),
      ('SHA', array['Shanghai','CNSHA','Yantian','CNYTN','Ningbo','CNNGB']::text[]),
      ('TYO', array['Tokyo','Narita','JPTYO','Kobe','JPUKB']::text[]),
      ('SYD', array['Sydney','AUSYD','Melbourne','AUMEL']::text[])
  ),
  booking_base as materialized (
    select
      booking."Booking_Reference"::text as reference,
      booking."Customer_Name"::text as customer,
      booking."Route"::text as route,
      booking."Status"::text as status,
      booking."Progress"::integer as progress,
      booking."Tone"::text as tone,
      booking."Origin"::text as origin,
      booking."Destination"::text as destination,
      coalesce(booking."Departure_At", pg_catalog.timezone(v_time_zone, booking."Departure_Date"::timestamp)) as start_at,
      coalesce(booking."Arrival_At", pg_catalog.timezone(v_time_zone, (booking."Arrival_Date" + 1)::timestamp)) as end_at,
      booking."Updated_At"::timestamptz as sort_at
    from public."App_Live_Bookings" booking
  ),
  quote_base as materialized (
    select
      quote."Quote_Reference"::text as reference,
      quote."Customer_Name"::text as customer,
      quote."Origin"::text as origin,
      quote."Destination"::text as destination,
      quote."Quote_Status"::text as status,
      quote."Quote_Status_Tone"::text as tone,
      quote."Created_At"::timestamptz as created_at,
      quote."Updated_At"::timestamptz as sort_at,
      case when quote."Estimated_Departure" is null then null else pg_catalog.timezone(v_time_zone, quote."Estimated_Departure"::timestamp) end as start_at,
      case when quote."Estimated_Arrival" is null then null else pg_catalog.timezone(v_time_zone, (quote."Estimated_Arrival" + 1)::timestamp) end as end_at
    from public."App_Live_Quotes" quote
  ),
  eligible as materialized (
    select
      'booking:' || booking.reference as row_key,
      booking.sort_at,
      jsonb_build_object(
        'id', booking.reference,
        'detail', booking.customer || ' · ' || booking.route,
        'status', booking.status,
        'tone', booking.tone,
        'recordType', 'booking'
      ) as item
    from booking_base booking
    where (
      v_kind = 'active_jobs'
      and booking.progress < 100
      and case
        when booking.start_at is not null and booking.end_at is not null then booking.start_at < p_window_end and booking.end_at > p_window_start
        when booking.start_at is not null then booking.start_at >= p_window_start and booking.start_at < p_window_end
        when booking.end_at is not null then booking.end_at > p_window_start and booking.end_at <= p_window_end
        else booking.sort_at >= p_window_start and booking.sort_at < p_window_end
      end
    ) or (
      v_kind = 'booking_exceptions'
      and booking.progress < 100
      and booking.status <> 'On track'
      and case
        when booking.start_at is not null and booking.end_at is not null then booking.start_at < p_window_end and booking.end_at > p_window_start
        when booking.start_at is not null then booking.start_at >= p_window_start and booking.start_at < p_window_end
        when booking.end_at is not null then booking.end_at > p_window_start and booking.end_at <= p_window_end
        else booking.sort_at >= p_window_start and booking.sort_at < p_window_end
      end
    ) or (
      v_kind = 'region'
      and exists (
        select 1 from region_terms region, unnest(region.terms) term
        where region.code = v_value
          and strpos(lower(coalesce(booking.origin, '') || ' ' || coalesce(booking.destination, '')), lower(term)) > 0
      )
    )

    union all

    select
      'quote:' || quote.reference,
      quote.sort_at,
      jsonb_build_object(
        'id', quote.reference,
        'detail', quote.customer || ' · ' || quote.origin || ' → ' || quote.destination,
        'status', quote.status,
        'tone', quote.tone,
        'recordType', 'quote'
      )
    from quote_base quote
    where (
      v_kind = 'open_quotes'
      and quote.status not in ('Sent', 'Accepted')
      and case
        when quote.start_at is not null and quote.end_at is not null then quote.start_at < p_window_end and quote.end_at > p_window_start
        when quote.start_at is not null then quote.start_at >= p_window_start and quote.start_at < p_window_end
        when quote.end_at is not null then quote.end_at > p_window_start and quote.end_at <= p_window_end
        else quote.created_at >= p_window_start and quote.created_at < p_window_end
      end
    ) or (
      v_kind = 'ready_quotes'
      and quote.status = 'Ready to send'
      and case
        when quote.start_at is not null and quote.end_at is not null then quote.start_at < p_window_end and quote.end_at > p_window_start
        when quote.start_at is not null then quote.start_at >= p_window_start and quote.start_at < p_window_end
        when quote.end_at is not null then quote.end_at > p_window_start and quote.end_at <= p_window_end
        else quote.created_at >= p_window_start and quote.created_at < p_window_end
      end
    ) or (
      v_kind = 'region'
      and exists (
        select 1 from region_terms region, unnest(region.terms) term
        where region.code = v_value
          and strpos(lower(coalesce(quote.origin, '') || ' ' || coalesce(quote.destination, '')), lower(term)) > 0
      )
    )
  ),
  cursor_page as materialized (
    select *
    from eligible
    where p_cursor_sort_at is null or (sort_at, row_key) < (p_cursor_sort_at, p_cursor_row_key)
    order by sort_at desc nulls last, row_key desc
    limit v_limit + 1
  ),
  numbered as materialized (
    select *, row_number() over (order by sort_at desc nulls last, row_key desc) as ordinal
    from cursor_page
  )
  select jsonb_build_object(
    'items', coalesce((select jsonb_agg(item order by ordinal) from numbered where ordinal <= v_limit), '[]'::jsonb),
    'total', (select count(*) from eligible),
    'hasMore', exists(select 1 from numbered where ordinal > v_limit),
    'nextCursor', case when exists(select 1 from numbered where ordinal > v_limit) then (
      select jsonb_build_object('sortAt', sort_at, 'rowKey', row_key)
      from numbered where ordinal = v_limit
    ) else null end
  ) into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."multideck_dashboard_drilldown_page"("p_kind" "text", "p_value" "text", "p_window_start" timestamp with time zone, "p_window_end" timestamp with time zone, "p_time_zone" "text", "p_limit" integer, "p_cursor_sort_at" timestamp with time zone, "p_cursor_row_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."multideck_dashboard_drilldown_page"("p_kind" "text", "p_value" "text", "p_window_start" timestamp with time zone, "p_window_end" timestamp with time zone, "p_time_zone" "text", "p_limit" integer, "p_cursor_sort_at" timestamp with time zone, "p_cursor_row_key" "text") IS 'RLS-preserving, maximum-50-row keyset page for Overview metric and operating-region drilldowns.';



CREATE OR REPLACE FUNCTION "public"."multideck_dashboard_overview"("p_window_start" timestamp with time zone, "p_window_end" timestamp with time zone, "p_series_end" timestamp with time zone, "p_now" timestamp with time zone, "p_cutoff_at" timestamp with time zone, "p_time_zone" "text" DEFAULT 'UTC'::"text", "p_operator_name" "text" DEFAULT NULL::"text", "p_row_limit" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_limit integer := greatest(1, least(coalesce(p_row_limit, 50), 50));
  v_time_zone text := coalesce(nullif(btrim(p_time_zone), ''), 'UTC');
  v_result jsonb;
begin
  if auth.uid() is null then
    raise exception 'Authentication required.' using errcode = '42501';
  end if;
  if p_window_start is null or p_window_end is null or p_window_end <= p_window_start then
    raise exception 'Choose a valid dashboard date range.' using errcode = '22007';
  end if;
  if p_series_end is null or p_series_end <= p_window_start or p_series_end > p_window_end then
    raise exception 'Choose a valid dashboard series range.' using errcode = '22007';
  end if;
  if p_now is null or p_cutoff_at is null then
    raise exception 'Dashboard timing context is required.' using errcode = '22007';
  end if;
  perform 1 from pg_catalog.pg_timezone_names where name = v_time_zone;
  if not found then
    raise exception 'Choose a valid dashboard time zone.' using errcode = '22023';
  end if;

  with
  booking_base as materialized (
    select
      booking."Booking_Reference"::text as reference,
      booking."Customer_Name"::text as customer,
      booking."Route"::text as route,
      upper(booking."Mode"::text) as mode,
      booking."Status"::text as status,
      booking."Progress"::integer as progress,
      booking."Owner_Code"::text as owner,
      booking."Tone"::text as tone,
      booking."Eta_Display"::text as eta,
      booking."Origin"::text as origin,
      booking."Destination"::text as destination,
      coalesce(
        booking."Departure_At",
        pg_catalog.timezone(v_time_zone, booking."Departure_Date"::timestamp)
      ) as start_at,
      coalesce(
        booking."Arrival_At",
        pg_catalog.timezone(v_time_zone, (booking."Arrival_Date" + 1)::timestamp)
      ) as end_at,
      booking."Updated_At"::timestamptz as updated_at
    from public."App_Live_Bookings" booking
  ),
  quote_base as materialized (
    select
      quote."Quote_Reference"::text as reference,
      quote."Customer_Name"::text as customer,
      quote."Origin"::text as origin,
      quote."Destination"::text as destination,
      quote."Quote_Status"::text as status,
      quote."Quote_Status_Tone"::text as status_tone,
      quote."Priority_Tone"::text as priority_tone,
      quote."Workflow_Stage"::text as workflow_stage,
      quote."Sales_Owner"::text as owner,
      case when quote."Estimated_Departure" is null then null
        else pg_catalog.timezone(v_time_zone, quote."Estimated_Departure"::timestamp)
      end as start_at,
      case when quote."Estimated_Arrival" is null then null
        else pg_catalog.timezone(v_time_zone, (quote."Estimated_Arrival" + 1)::timestamp)
      end as end_at,
      quote."Created_At"::timestamptz as created_at,
      quote."Updated_At"::timestamptz as updated_at
    from public."App_Live_Quotes" quote
  ),
  active_bookings as materialized (
    select * from booking_base where progress < 100
  ),
  range_bookings as materialized (
    select *
    from active_bookings
    where case
      when start_at is not null and end_at is not null then start_at < p_window_end and end_at > p_window_start
      when start_at is not null then start_at >= p_window_start and start_at < p_window_end
      when end_at is not null then end_at > p_window_start and end_at <= p_window_end
      else updated_at >= p_window_start and updated_at < p_window_end
    end
  ),
  range_quotes as materialized (
    select *
    from quote_base
    where case
      when start_at is not null and end_at is not null then start_at < p_window_end and end_at > p_window_start
      when start_at is not null then start_at >= p_window_start and start_at < p_window_end
      when end_at is not null then end_at > p_window_start and end_at <= p_window_end
      else created_at >= p_window_start and created_at < p_window_end
    end
  ),
  points as materialized (
    select
      point_index,
      p_window_start + ((p_series_end - p_window_start) / 10) * point_index as point_at
    from generate_series(1, 10) point_index
  ),
  kpi_series as materialized (
    select
      point.point_index,
      (
        select count(*) from range_bookings booking
        where case
          when booking.start_at is not null and booking.end_at is not null then booking.start_at <= point.point_at and booking.end_at > point.point_at
          when booking.start_at is not null then booking.start_at <= point.point_at
          when booking.end_at is not null then booking.end_at > point.point_at
          else booking.updated_at <= point.point_at
        end
      ) as active_jobs,
      (
        select count(*) from range_bookings booking
        where booking.status <> 'On track'
          and case
            when booking.start_at is not null and booking.end_at is not null then booking.start_at <= point.point_at and booking.end_at > point.point_at
            when booking.start_at is not null then booking.start_at <= point.point_at
            when booking.end_at is not null then booking.end_at > point.point_at
            else booking.updated_at <= point.point_at
          end
      ) as exceptions,
      (
        select count(*) from range_quotes quote
        where case
          when quote.start_at is not null and quote.end_at is not null then quote.start_at <= point.point_at and quote.end_at > point.point_at
          when quote.start_at is not null then quote.start_at <= point.point_at
          when quote.end_at is not null then quote.end_at > point.point_at
          else quote.created_at <= point.point_at
        end
      ) as quotes,
      (
        select count(*) from range_quotes quote
        where quote.status = 'Ready to send'
          and case
            when quote.start_at is not null and quote.end_at is not null then quote.start_at <= point.point_at and quote.end_at > point.point_at
            when quote.start_at is not null then quote.start_at <= point.point_at
            when quote.end_at is not null then quote.end_at > point.point_at
            else quote.created_at <= point.point_at
          end
      ) as ready_quotes
    from points point
  ),
  dashboard_modes(mode, label, colour, mode_order) as (
    values
      ('OCEAN'::text, 'Ocean'::text, 'var(--md-accent)'::text, 1),
      ('AIR', 'Air', 'var(--md-blue)', 2),
      ('ROAD', 'Road', 'var(--md-amber)', 3),
      ('MULTIMODAL', 'Multimodal', 'var(--md-accent-glow-warm)', 4)
  ),
  mode_series as materialized (
    select
      mode.mode,
      mode.label,
      mode.colour,
      mode.mode_order,
      (
        select count(*)
        from active_bookings booking
        where (case when booking.mode = 'SEA' then 'OCEAN' else booking.mode end) = mode.mode
      ) as total,
      jsonb_agg((
        select count(*)
        from active_bookings candidate
        where (case when candidate.mode = 'SEA' then 'OCEAN' else candidate.mode end) = mode.mode
          and case
            when candidate.start_at is not null and candidate.end_at is not null then candidate.start_at <= point.point_at and candidate.end_at > point.point_at
            when candidate.start_at is not null then candidate.start_at <= point.point_at
            when candidate.end_at is not null then candidate.end_at > point.point_at
            else candidate.updated_at <= point.point_at
          end
      ) order by point.point_index) as values
    from dashboard_modes mode
    cross join points point
    group by mode.mode, mode.label, mode.colour, mode.mode_order
  ),
  priority_rows as materialized (
    select
      'booking:' || booking.reference as row_key,
      booking.updated_at,
      booking.updated_at + greatest(1, round((100 - booking.progress)::numeric / 20)::integer) * interval '1 hour' as due_at,
      1 as category_order,
      jsonb_build_object(
        'id', 'booking:' || booking.reference,
        'kind', 'exception',
        'reference', booking.reference,
        'task', case when booking.status = 'Exception' then 'Resolve tracking exception' else 'Review revised delivery plan' end,
        'customer', booking.customer,
        'context', booking.route,
        'status', booking.status,
        'owner', booking.owner,
        'dueAt', extract(epoch from (booking.updated_at + greatest(1, round((100 - booking.progress)::numeric / 20)::integer) * interval '1 hour')) * 1000,
        'dueKind', 'action',
        'tone', booking.tone,
        'bookingId', booking.reference
      ) as item
    from active_bookings booking
    where booking.status <> 'On track'

    union all

    select
      'quote-send:' || quote.reference,
      quote.updated_at,
      least(coalesce(quote.start_at, p_cutoff_at), p_cutoff_at),
      2,
      jsonb_build_object(
        'id', 'quote-send:' || quote.reference,
        'kind', 'quote-send',
        'reference', quote.reference,
        'task', 'Send priced quote',
        'customer', quote.customer,
        'context', quote.origin || ' → ' || quote.destination,
        'status', quote.status,
        'owner', quote.owner,
        'dueAt', extract(epoch from least(coalesce(quote.start_at, p_cutoff_at), p_cutoff_at)) * 1000,
        'dueKind', case when quote.start_at is not null and quote.start_at < p_cutoff_at then 'departure' else 'cutoff' end,
        'tone', quote.status_tone,
        'quoteReference', quote.reference
      )
    from quote_base quote
    where quote.status = 'Ready to send'

    union all

    select
      'quote-progress:' || quote.reference,
      quote.updated_at,
      coalesce(quote.start_at, p_cutoff_at),
      3,
      jsonb_build_object(
        'id', 'quote-progress:' || quote.reference,
        'kind', 'quote-progress',
        'reference', quote.reference,
        'task', 'Progress ' || lower(quote.workflow_stage),
        'customer', quote.customer,
        'context', quote.origin || ' → ' || quote.destination,
        'status', quote.status,
        'owner', quote.owner,
        'dueAt', extract(epoch from coalesce(quote.start_at, p_cutoff_at)) * 1000,
        'dueKind', case when quote.start_at is null then 'cutoff' else 'departure' end,
        'tone', quote.priority_tone,
        'quoteReference', quote.reference
      )
    from quote_base quote
    where quote.status not in ('Sent', 'Accepted', 'Ready to send')
  ),
  priority_page as materialized (
    select *
    from priority_rows
    order by due_at, category_order, updated_at desc nulls last, row_key
    limit v_limit
  ),
  priority_mine_page as materialized (
    select *
    from priority_rows
    where item ->> 'owner' = coalesce(p_operator_name, '')
    order by due_at, category_order, updated_at desc nulls last, row_key
    limit v_limit
  ),
  live_page as materialized (
    select
      booking.updated_at,
      booking.reference,
      jsonb_build_object(
        'id', booking.reference,
        'lane', booking.route,
        'mode', case
          when booking.mode in ('OCEAN', 'SEA') then 'Ocean'
          when booking.mode = 'AIR' then 'Air'
          when booking.mode = 'ROAD' then 'Road'
          when booking.mode = 'MULTIMODAL' then 'Multimodal'
          else booking.mode
        end,
        'customer', booking.customer,
        'milestone', booking.status,
        'progress', booking.progress,
        'eta', booking.eta,
        'updatedAt', booking.updated_at,
        'tone', booking.tone,
        'origin', booking.origin,
        'destination', booking.destination
      ) as item
    from active_bookings booking
    order by booking.updated_at desc nulls last, booking.reference
    limit v_limit
  ),
  region_terms(code, terms, region_order) as (
    values
      ('LAX'::text, array['Los Angeles','Long Beach','USLAX']::text[], 1),
      ('CHI', array['Chicago','USCHI']::text[], 2),
      ('NYC', array['New York','JFK','USJFK']::text[], 3),
      ('YYZ', array['Toronto','CATOR']::text[], 4),
      ('GRU', array['Sao Paulo','Santos','BRSSZ']::text[], 5),
      ('LDN', array['London','Heathrow','GBLHR','Felixstowe','GBFXT','Bristol','GBBRS','Southampton','GBSOU','Gateway','Manchester','Birmingham']::text[], 6),
      ('AMS', array['Amsterdam','Rotterdam','NLRTM']::text[], 7),
      ('FRA', array['Frankfurt','DEFRA','Hamburg','DEHAM']::text[], 8),
      ('IST', array['Istanbul','TRIST']::text[], 9),
      ('DXB', array['Dubai','AEDXB']::text[], 10),
      ('BOM', array['Mumbai','Nhava Sheva','INNSA']::text[], 11),
      ('SIN', array['Singapore','SGSIN']::text[], 12),
      ('HKG', array['Hong Kong','HKHKG']::text[], 13),
      ('SHA', array['Shanghai','CNSHA','Yantian','CNYTN','Ningbo','CNNGB']::text[], 14),
      ('TYO', array['Tokyo','Narita','JPTYO','Kobe','JPUKB']::text[], 15),
      ('SYD', array['Sydney','AUSYD','Melbourne','AUMEL']::text[], 16)
  ),
  region_counts as materialized (
    select
      region.code,
      region.region_order,
      (
        select count(*) from quote_base quote
        where quote.status not in ('Sent', 'Accepted')
          and exists (
            select 1 from unnest(region.terms) term
            where strpos(lower(coalesce(quote.origin, '') || ' ' || coalesce(quote.destination, '')), lower(term)) > 0
          )
      ) as open_rfqs,
      (
        select count(*) from booking_base booking
        where booking.status <> 'On track'
          and exists (
            select 1 from unnest(region.terms) term
            where strpos(lower(coalesce(booking.origin, '') || ' ' || coalesce(booking.destination, '')), lower(term)) > 0
          )
      ) as need_action,
      (
        select count(*) from quote_base quote
        where quote.status = 'Ready to send'
          and exists (
            select 1 from unnest(region.terms) term
            where strpos(lower(coalesce(quote.origin, '') || ' ' || coalesce(quote.destination, '')), lower(term)) > 0
          )
      ) as ready_to_quote
    from region_terms region
  ),
  quote_stage_counts as materialized (
    select
      workflow_stage as name,
      count(*) as value,
      max(updated_at) as latest
    from quote_base
    where status not in ('Sent', 'Accepted') and nullif(btrim(workflow_stage), '') is not null
    group by workflow_stage
    order by value desc, latest desc nulls last, workflow_stage
    limit 5
  )
  select jsonb_build_object(
    'windowStart', p_window_start,
    'windowEnd', p_window_end,
    'seriesEnd', p_series_end,
    'generatedAt', p_now,
    'counts', jsonb_build_object(
      'activeJobs', (select count(*) from range_bookings),
      'exceptions', (select count(*) from range_bookings where status <> 'On track'),
      'openQuotes', (select count(*) from range_quotes where status not in ('Sent', 'Accepted')),
      'readyQuotes', (select count(*) from range_quotes where status = 'Ready to send'),
      'totalQuotes', (select count(*) from range_quotes),
      'priority', (select count(*) from priority_rows),
      'priorityMine', (select count(*) from priority_rows where item ->> 'owner' = coalesce(p_operator_name, '')),
      'liveBookings', (select count(*) from active_bookings),
      'liveExceptions', (select count(*) from active_bookings where status <> 'On track')
    ),
    'series', jsonb_build_object(
      'activeJobs', (select jsonb_agg(active_jobs order by point_index) from kpi_series),
      'exceptions', (select jsonb_agg(exceptions order by point_index) from kpi_series),
      'quotes', (select jsonb_agg(quotes order by point_index) from kpi_series),
      'readyQuotes', (select jsonb_agg(ready_quotes order by point_index) from kpi_series),
      'modes', coalesce((select jsonb_object_agg(mode, values order by mode_order) from mode_series where total > 0), '{}'::jsonb)
    ),
    'modeDefinitions', coalesce((select jsonb_agg(jsonb_build_object('key', mode, 'label', label, 'color', colour) order by mode_order) from mode_series where total > 0), '[]'::jsonb),
    'clockQueues', coalesce((select jsonb_object_agg(code, jsonb_build_object('openRfqs', open_rfqs, 'needAction', need_action, 'readyToQuote', ready_to_quote) order by region_order) from region_counts), '{}'::jsonb),
    'statusCounts', jsonb_build_object(
      'Exception', (select count(*) from active_bookings where status = 'Exception'),
      'Delayed', (select count(*) from active_bookings where status = 'Delayed'),
      'On track', (select count(*) from active_bookings where status = 'On track')
    ),
    'quoteStages', coalesce((select jsonb_agg(jsonb_build_object('name', name, 'value', value) order by value desc, latest desc nulls last, name) from quote_stage_counts), '[]'::jsonb),
    'priorityItems', coalesce((select jsonb_agg(item order by due_at, category_order, updated_at desc nulls last, row_key) from priority_page), '[]'::jsonb),
    'priorityMineItems', coalesce((select jsonb_agg(item order by due_at, category_order, updated_at desc nulls last, row_key) from priority_mine_page), '[]'::jsonb),
    'liveBookings', coalesce((select jsonb_agg(item order by updated_at desc nulls last, reference) from live_page), '[]'::jsonb)
  ) into v_result;

  return v_result;
end;
$$;


