CREATE OR REPLACE FUNCTION "public"."multideck_dexter_action_replace_booking_allocations"("p_company_id" "uuid", "p_user_id" "uuid", "p_arguments" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid;job public."Job_Header";before_value jsonb;after_value jsonb;saved jsonb;job_id uuid;
begin
  select "Auth_User_ID" into actor from public."cmp_Users" where "User_ID"=p_user_id and "Company_ID"=p_company_id and "User_AccessStatus"='active';
  if actor is null or not booking_api.has_permission(actor,'Bookings.Read') or not booking_api.has_permission(actor,'Bookings.Write') then
    raise exception 'Booking allocation changes are not authorised.' using errcode='42501';end if;
  if jsonb_typeof(p_arguments) is distinct from 'object' or not(p_arguments ?& array['target_id','expected_updated_at','expected_review_hash','allocations','reason'])
    or exists(select 1 from jsonb_object_keys(p_arguments) key where key not in ('target_id','expected_updated_at','expected_review_hash','allocations','reason'))
    or jsonb_typeof(p_arguments->'reason') is distinct from 'string' or nullif(btrim(p_arguments->>'reason'),'') is null
    or length(p_arguments->>'reason')>2000 or jsonb_typeof(p_arguments->'allocations') is distinct from 'array'
    or jsonb_typeof(p_arguments->'expected_review_hash') is distinct from 'string' then
    raise exception 'Provide the complete reviewed allocation plan and a reason.' using errcode='22023';end if;
  job_id:=(p_arguments->>'target_id')::uuid;
  select j.* into job from public."Job_Header" j join public."cmp_Offices" o on o."Office_ID"=coalesce(j."Job_OrgOfficeID",j."Job_OfficeID")
    where j."Job_ID"=job_id and not j."Job_IsDeleted" and o."Company_ID"=p_company_id for update of j;
  if not found then raise exception 'Choose a Booking in this workspace.' using errcode='42501';end if;
  before_value:=booking_api.allocation_review_values(job_id);
  if md5(before_value::text) is distinct from p_arguments->>'expected_review_hash' then
    raise exception 'Allocation evidence changed. Read it again and request fresh approval.' using errcode='40001';end if;
  -- Canonical transaction owns all membership, precision, quantity, retirement,
  -- scope and optimistic Job checks. Omitted identities are explicitly removed.
  saved:=public.booking_workflow_save(actor,job_id,jsonb_build_object('expectedUpdatedAt',p_arguments->'expected_updated_at','cargoAllocations',p_arguments->'allocations'));
  after_value:=booking_api.allocation_review_values(job_id);
  if before_value->'allocations' is distinct from after_value->'allocations' then
    insert into booking_api.events(company_id,job_id,event_type,summary,metadata,actor_user_id)
      values(p_company_id,job_id,'dexter_allocations_updated','Approved cargo allocation plan updated',
        jsonb_build_object('before',before_value->'allocations','after',after_value->'allocations','reason',btrim(p_arguments->>'reason')),p_user_id);
  end if;
  return jsonb_build_object('recordId',job_id,'bookingId',job_id,'bookingReference',job."Job_BookingReference",
    'before',before_value->'allocations','after',after_value->'allocations','updatedAt',saved#>'{booking,updatedAt}',
    'reviewHash',md5(after_value::text),'sourceUrl','/bookings/'||lower(job."Job_BookingReference"));
end $$;


ALTER FUNCTION "public"."multideck_dexter_action_replace_booking_allocations"("p_company_id" "uuid", "p_user_id" "uuid", "p_arguments" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_action_reschedule_meeting"("p_company_id" "uuid", "p_user_id" "uuid", "p_arguments" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_id uuid := (p_arguments->>'target_id')::uuid;
  v_start timestamptz := (p_arguments->>'start_at')::timestamptz;
  v_end timestamptz := (p_arguments->>'end_at')::timestamptz;
  v_meeting public."CAL_Meetings";
begin
  select * into v_meeting from public."CAL_Meetings"
  where "CALMeeting_ID"=v_id and "CALMeeting_CompanyID"=p_company_id and "CALMeeting_StatusCode" <> 'cancelled'
  for update;
  if not found or (v_meeting."CALMeeting_OrganiserUserID" <> p_user_id and not public._multideck_calendar_has_permission(p_user_id,'Calendar.ManageAll')) then
    raise exception 'That meeting is not available to change.' using errcode = '42501';
  end if;
  if v_meeting."CALMeeting_ProviderCode" in ('google_meet','microsoft_teams','zoom') then
    update public."CAL_Meetings" set
      "CALMeeting_StatusCode"='sync_pending',
      "CALMeeting_PendingChangeJSON"=jsonb_build_object('kind','reschedule','startAt',v_start,'endAt',v_end),
      "CALMeeting_EditVersion"="CALMeeting_EditVersion"+1,"CALMeeting_UpdatedBy"=p_user_id,"CALMeeting_UpdatedAt"=now()
    where "CALMeeting_ID"=v_id returning * into v_meeting;
  else
    update public."CAL_Reservations" set
      "CALReservation_StartAt"=v_start,"CALReservation_EndAt"=v_end
    where "CALReservation_ID"=v_meeting."CALMeeting_ReservationID";
    update public."CAL_Meetings" set
      "CALMeeting_StartAt"=v_start,"CALMeeting_EndAt"=v_end,"CALMeeting_StatusCode"='confirmed',
      "CALMeeting_PendingChangeJSON"=null,
      "CALMeeting_EditVersion"="CALMeeting_EditVersion"+1,"CALMeeting_UpdatedBy"=p_user_id,"CALMeeting_UpdatedAt"=now()
    where "CALMeeting_ID"=v_id returning * into v_meeting;
  end if;
  update public."CAL_Deliveries" set "CALDelivery_StatusCode"='cancelled'
  where "CALDelivery_MeetingID"=v_id and "CALDelivery_StatusCode"='pending';
  insert into public."CAL_Deliveries" (
    "CALDelivery_CompanyID","CALDelivery_MeetingID","CALDelivery_KindCode","CALDelivery_IdempotencyKey"
  ) values (p_company_id,v_id,
    case when v_meeting."CALMeeting_ProviderCode" in ('google_meet','microsoft_teams','zoom') then 'provider_update' else 'rescheduled' end,
    'meeting:'||v_id||':reschedule:v'||v_meeting."CALMeeting_EditVersion");
  return jsonb_build_object('id',v_id,'startAt',v_meeting."CALMeeting_StartAt",'endAt',v_meeting."CALMeeting_EndAt",'status',v_meeting."CALMeeting_StatusCode");
exception when exclusion_violation then
  raise exception 'That time is no longer available.' using errcode = '23P01';
end;
$$;


ALTER FUNCTION "public"."multideck_dexter_action_reschedule_meeting"("p_company_id" "uuid", "p_user_id" "uuid", "p_arguments" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_action_respond_external_event"("p_company_id" "uuid", "p_user_id" "uuid", "p_arguments" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_event public."CAL_ProviderEvents";
  v_connection public."CAL_ProviderConnections";
  v_response text := lower(btrim(coalesce(p_arguments->>'response','')));
  v_key text;
begin
  if not public._multideck_calendar_has_permission(p_user_id,'Calendar.ManageOwn') then
    raise exception 'You do not have permission to respond to calendar invitations.' using errcode='42501';
  end if;
  if v_response not in ('accepted','tentative','declined') then
    raise exception 'Choose accepted, tentative or declined.' using errcode='22023';
  end if;
  select * into v_event from public."CAL_ProviderEvents"
  where "CALProviderEvent_ID"=(p_arguments->>'target_id')::uuid
    and "CALProviderEvent_CompanyID"=p_company_id
    and "CALProviderEvent_OwnerUserID"=p_user_id
  for update;
  if not found then raise exception 'That calendar invitation is not available to answer.' using errcode='42501'; end if;
  if v_event."CALProviderEvent_IsCancelled" then raise exception 'That invitation was already removed from the provider.' using errcode='22023'; end if;
  if v_event."CALProviderEvent_IsOrganiser" then raise exception 'You organised this event, so there is no invitation to answer.' using errcode='22023'; end if;
  if v_event."CALProviderEvent_ResponseCode" is null then raise exception 'The provider has not identified this event as an invitation you can answer.' using errcode='22023'; end if;
  select * into v_connection from public."CAL_ProviderConnections"
  where "CALConnection_ID"=v_event."CALProviderEvent_ConnectionID"
    and "CALConnection_CompanyID"=p_company_id and "CALConnection_UserID"=p_user_id;
  if not found or v_connection."CALConnection_StatusCode" not in ('connected','syncing') or v_connection."CALConnection_ProviderCode" not in ('google','microsoft') then
    raise exception 'Reconnect the calendar this invitation came from before responding.' using errcode='22023';
  end if;
  if v_event."CALProviderEvent_ResponseCode" = v_response then
    return jsonb_build_object('id',v_event."CALProviderEvent_ID",'source',v_connection."CALConnection_ProviderCode",'status','confirmed','response',v_response);
  end if;
  v_key := 'external-event:'||v_event."CALProviderEvent_ID"||':rsvp:'||v_response||':'||to_char(clock_timestamp(),'YYYYMMDDHH24MISSMS');
  insert into public."CAL_Deliveries" ("CALDelivery_CompanyID","CALDelivery_KindCode","CALDelivery_IdempotencyKey","CALDelivery_RenderedJSON")
  values (p_company_id,'external_event_rsvp',v_key,jsonb_build_object('providerEventId',v_event."CALProviderEvent_ID",'requestedBy',p_user_id,'response',v_response));
  return jsonb_build_object('id',v_event."CALProviderEvent_ID",'source',v_connection."CALConnection_ProviderCode",'status','sync_pending','currentResponse',v_event."CALProviderEvent_ResponseCode",'requestedResponse',v_response);
end;
$$;


ALTER FUNCTION "public"."multideck_dexter_action_respond_external_event"("p_company_id" "uuid", "p_user_id" "uuid", "p_arguments" "jsonb") OWNER TO "postgres";


