CREATE OR REPLACE FUNCTION "public"."multideck_dexter_action_update_booking_cargo"("p_company_id" "uuid", "p_user_id" "uuid", "p_arguments" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  actor_auth_id uuid;
  job_row public."Job_Header";
  cargo_row public."Job_Cargo";
  target_id uuid := nullif(p_arguments->>'target_id', '')::uuid;
  cargo_id uuid := nullif(p_arguments->>'cargo_id', '')::uuid;
  field_name text := p_arguments->>'field';
  field_value jsonb := coalesce(p_arguments->'value', 'null'::jsonb);
  text_value text := p_arguments->>'value';
  numeric_value numeric;
  cargo_lines jsonb;
  saved jsonb;
begin
  select "Auth_User_ID" into actor_auth_id from public."cmp_Users"
  where "User_ID" = p_user_id and "Company_ID" = p_company_id and "User_AccessStatus" = 'active';
  if actor_auth_id is null or not booking_api.has_permission(actor_auth_id, 'Bookings.Write')
     or not booking_api.has_permission(actor_auth_id, 'Bookings.Read') then
    raise exception 'You do not have permission to edit booking cargo.' using errcode = '42501';
  end if;
  if jsonb_typeof(p_arguments) is distinct from 'object'
    or not (p_arguments ?& array['target_id','cargo_id','expected_updated_at','field','value','reason']) or exists (
    select 1 from jsonb_object_keys(p_arguments) key where key not in ('target_id','cargo_id','expected_updated_at','field','value','reason')
  ) or nullif(btrim(p_arguments->>'reason'), '') is null then
    raise exception 'Provide an exact cargo field change and its reason.' using errcode = '22023';
  end if;
  select job.* into job_row from public."Job_Header" job
  join public."cmp_Offices" office on office."Office_ID" = coalesce(job."Job_OrgOfficeID", job."Job_OfficeID")
  where job."Job_ID" = target_id and office."Company_ID" = p_company_id and not job."Job_IsDeleted"
  for update of job;
  if not found then raise exception 'That booking is outside this workspace.' using errcode = '42501'; end if;
  if nullif(p_arguments->>'expected_updated_at', '') is null
     or job_row."Job_UpdatedAt" is distinct from (p_arguments->>'expected_updated_at')::timestamptz then
    raise exception 'The booking changed since this proposal. Read it again and request fresh approval.' using errcode = '40001';
  end if;
  select * into cargo_row from public."Job_Cargo"
  where "JobCargo_ID" = cargo_id and "JobCargo_JobID" = target_id and not "JobCargo_IsDeleted";
  if not found then raise exception 'Choose an active cargo line from this booking.' using errcode = '42501'; end if;
  if field_name is null or field_name not in (
    'description','commodity','pieces','packageQuantity','packageType','chargeableWeightKg','grossWeightKg','netWeightKg','volumeCbm',
    'length','width','height','lengthUnit','hsCode','countryOfOrigin','isHazardous','isTemperatureControlled'
  ) then raise exception 'That cargo field is not available for Dexter editing.' using errcode = '22023'; end if;
  if jsonb_typeof(field_value) not in ('string','null') then
    raise exception 'Use a text value or null to clear the selected field.' using errcode = '22023';
  end if;
  if field_name in ('pieces','packageQuantity','grossWeightKg','netWeightKg','volumeCbm','length','width','height') then
    numeric_value := nullif(btrim(text_value), '')::numeric;
    if numeric_value < 0 or numeric_value::text in ('NaN','Infinity','-Infinity') then
      raise exception 'Cargo quantities and measurements must be finite and non-negative.' using errcode = '22023';
    end if;
    field_value := coalesce(to_jsonb(numeric_value), 'null'::jsonb);
  elsif field_name in ('isHazardous','isTemperatureControlled') then
    if text_value is null or text_value not in ('true','false') then
      raise exception 'Cargo safety flags must explicitly be true or false.' using errcode = '22023';
    end if;
    field_value := to_jsonb(text_value::boolean);
  elsif field_name = 'description' and nullif(btrim(text_value), '') is null then
    raise exception 'A cargo line needs a goods description.' using errcode = '22023';
  elsif field_name = 'lengthUnit' and (text_value is null or text_value not in ('cm','m','in')) then
    raise exception 'Choose cm, m or in for the dimension unit.' using errcode = '22023';
  elsif field_name = 'countryOfOrigin' and text_value is not null and text_value !~ '^[A-Za-z]{2}$' then
    raise exception 'Use a two-letter country code.' using errcode = '22023';
  end if;
  -- Keep every other line and every unexposed commercial/safety field intact.
  saved := booking_api.workspace_extended(actor_auth_id, job_row."Job_BookingReference");
  select jsonb_agg(case when line->>'id' = cargo_id::text
    then line || jsonb_build_object(field_name, field_value) else line end order by ordinal)
    into cargo_lines from jsonb_array_elements(saved->'cargo') with ordinality as entries(line, ordinal);
  if not exists(select 1 from jsonb_array_elements(cargo_lines) line where line->>'id'=cargo_id::text) then
    raise exception 'The cargo workspace changed. Reload before approving.' using errcode='40001';
  end if;
  saved := public.booking_workflow_save(actor_auth_id, target_id, jsonb_build_object('cargo', cargo_lines));
  select booking_api.cargo_public_values(cargo)->field_name into field_value
    from public."Job_Cargo" cargo where cargo."JobCargo_ID"=cargo_id;
  insert into booking_api.events(company_id, job_id, event_type, summary, metadata, actor_user_id)
  values(p_company_id, target_id, 'dexter_cargo_updated', 'Approved cargo field updated',
    jsonb_build_object('cargoId',cargo_id,'field',field_name,
      'before',booking_api.cargo_public_values(cargo_row)->field_name,'after',field_value,
      'reason',btrim(p_arguments->>'reason')), p_user_id);
  return jsonb_build_object('recordId', cargo_id, 'bookingId', target_id,
    'bookingReference', job_row."Job_BookingReference", 'field', field_name,
    'before', booking_api.cargo_public_values(cargo_row)->field_name, 'after', field_value,
    'updatedAt', saved#>'{booking,updatedAt}', 'sourceUrl', '/bookings/' || lower(job_row."Job_BookingReference"));
end;
$_$;


ALTER FUNCTION "public"."multideck_dexter_action_update_booking_cargo"("p_company_id" "uuid", "p_user_id" "uuid", "p_arguments" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_action_update_booking_container"("p_company_id" "uuid", "p_user_id" "uuid", "p_arguments" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor_auth_id uuid; job_row public."Job_Header"; container_row public."Job_Containers";
  job_id uuid; container_id uuid; field_name text; field_value jsonb; lines jsonb; saved jsonb;
begin
  select "Auth_User_ID" into actor_auth_id from public."cmp_Users"
    where "User_ID"=p_user_id and "Company_ID"=p_company_id and "User_AccessStatus"='active';
  if actor_auth_id is null or not booking_api.has_permission(actor_auth_id,'Bookings.Read')
    or not booking_api.has_permission(actor_auth_id,'Bookings.Write') then
    raise exception 'You do not have permission to edit booking containers.' using errcode='42501';end if;
  if jsonb_typeof(p_arguments) is distinct from 'object'
    or not (p_arguments ?& array['target_id','container_id','expected_updated_at','expected_container_updated_at','field','value','reason'])
    or exists(select 1 from jsonb_object_keys(p_arguments) key where key not in
      ('target_id','container_id','expected_updated_at','expected_container_updated_at','field','value','reason'))
    or nullif(btrim(p_arguments->>'reason'),'') is null then
    raise exception 'Provide an exact container field change and its reason.' using errcode='22023';end if;
  job_id:=nullif(p_arguments->>'target_id','')::uuid;container_id:=nullif(p_arguments->>'container_id','')::uuid;
  field_name:=p_arguments->>'field';field_value:=p_arguments->'value';
  if field_name is null or field_name not in ('grossWeightKg','tareWeightKg','verifiedGrossMassKg','vgmMethod','reeferSetPoint','reeferUnit')
    or jsonb_typeof(field_value) not in ('string','null') then
    raise exception 'Choose an available container field and use exact text or null to clear it.' using errcode='22023';end if;
  -- Use the same decimal, range and enum validation as the Booking editor.
  field_value:=booking_api.normalise_container_operations(jsonb_build_array(jsonb_build_object(field_name,field_value)))->0->field_name;
  select job.* into job_row from public."Job_Header" job
    join public."cmp_Offices" office on office."Office_ID"=coalesce(job."Job_OrgOfficeID",job."Job_OfficeID")
    where job."Job_ID"=job_id and office."Company_ID"=p_company_id and not job."Job_IsDeleted" for update of job;
  if not found then raise exception 'That booking is outside this workspace.' using errcode='42501';end if;
  select * into container_row from public."Job_Containers"
    where "JobContainers_ID"=container_id and "Job_ID"=job_id and not "JobContainer_IsDeleted" for update;
  if not found then raise exception 'Choose an active container from this booking.' using errcode='42501';end if;
  if nullif(p_arguments->>'expected_updated_at','') is null
    or job_row."Job_UpdatedAt" is distinct from (p_arguments->>'expected_updated_at')::timestamptz
    or nullif(p_arguments->>'expected_container_updated_at','') is null
    or container_row."JobContainer_UpdatedAt" is distinct from (p_arguments->>'expected_container_updated_at')::timestamptz then
    raise exception 'The booking or container changed since this proposal. Read it again and request fresh approval.' using errcode='40001';end if;
  saved:=booking_api.workspace_extended(actor_auth_id,job_row."Job_BookingReference");
  select jsonb_agg(case when line->>'id'=container_id::text then line||jsonb_build_object(field_name,field_value) else line end order by ordinal)
    into lines from jsonb_array_elements(saved->'containers') with ordinality entries(line,ordinal);
  if not exists(select 1 from jsonb_array_elements(lines) line where line->>'id'=container_id::text) then
    raise exception 'The container workspace changed. Reload before approving.' using errcode='40001';end if;
  saved:=public.booking_workflow_save(actor_auth_id,job_id,jsonb_build_object('containers',lines));
  select booking_api.container_operational_values(container)->field_name into field_value
    from public."Job_Containers" container where "JobContainers_ID"=container_id;
  insert into booking_api.events(company_id,job_id,event_type,summary,metadata,actor_user_id)
    values(p_company_id,job_id,'dexter_container_updated','Approved container field updated',
      jsonb_build_object('containerId',container_id,'field',field_name,
        'before',booking_api.container_operational_values(container_row)->field_name,'after',field_value,
        'reason',btrim(p_arguments->>'reason')),p_user_id);
  return jsonb_build_object('recordId',container_id,'bookingId',job_id,'bookingReference',job_row."Job_BookingReference",
    'field',field_name,'before',booking_api.container_operational_values(container_row)->field_name,'after',field_value,
    'updatedAt',saved#>'{booking,updatedAt}',
    'containerUpdatedAt',(select "JobContainer_UpdatedAt" from public."Job_Containers" where "JobContainers_ID"=container_id),
    'sourceUrl','/bookings/'||lower(job_row."Job_BookingReference"));
end $$;


ALTER FUNCTION "public"."multideck_dexter_action_update_booking_container"("p_company_id" "uuid", "p_user_id" "uuid", "p_arguments" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_action_update_booking_route"("p_company_id" "uuid", "p_user_id" "uuid", "p_arguments" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare actor_auth_id uuid;job_row public."Job_Header";route_row public."Job_Routing";
  job_id uuid;route_id uuid;field_name text;field_value jsonb;text_value text;max_length integer;date_value timestamptz;
  lines jsonb;saved jsonb;result_values jsonb;
begin
  select "Auth_User_ID" into actor_auth_id from public."cmp_Users"
    where "User_ID"=p_user_id and "Company_ID"=p_company_id and "User_AccessStatus"='active';
  if actor_auth_id is null or not booking_api.has_permission(actor_auth_id,'Bookings.Read')
    or not booking_api.has_permission(actor_auth_id,'Bookings.Write') then
    raise exception 'You do not have permission to edit booking routing.' using errcode='42501';end if;
  if jsonb_typeof(p_arguments) is distinct from 'object'
    or not (p_arguments ?& array['target_id','route_id','expected_updated_at','expected_route_updated_at','field','value','reason'])
    or exists(select 1 from jsonb_object_keys(p_arguments) key where key not in
      ('target_id','route_id','expected_updated_at','expected_route_updated_at','field','value','reason'))
    or nullif(btrim(p_arguments->>'reason'),'') is null then
    raise exception 'Provide an exact routing field change and its reason.' using errcode='22023';end if;
  job_id:=nullif(p_arguments->>'target_id','')::uuid;route_id:=nullif(p_arguments->>'route_id','')::uuid;
  field_name:=p_arguments->>'field';field_value:=p_arguments->'value';text_value:=nullif(btrim(p_arguments->>'value'),'');
  if field_name is null or field_name not in ('carrierBookingReference','masterTransportReference','houseTransportReference',
    'serviceLevel','transportMeansName','vessel','voyageNumber','flightNumber','vehicleRegistration','trailerNumber','railService',
    'plannedPickupAt','plannedDepartureAt','plannedArrivalAt','plannedDeliveryAt','cargoCutoffAt','documentationCutoffAt','vgmCutoffAt') or jsonb_typeof(field_value) not in ('string','null') then
    raise exception 'That routing field is not available for this approved action.' using errcode='22023';end if;
  if field_name in ('cargoCutoffAt','documentationCutoffAt','vgmCutoffAt') then
    field_value:=coalesce(to_jsonb(booking_api.parse_route_cutoff(field_value)),'null'::jsonb);
  elsif field_name like 'planned%At' and text_value is not null then
    if text_value ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then date_value:=text_value::date::timestamp at time zone 'UTC';
    elsif text_value ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}(:[0-9]{2}([.][0-9]{1,6})?)?(Z|[+-][0-9]{2}:[0-9]{2})$' then date_value:=text_value::timestamptz;
    else raise exception 'Use an ISO date or a timestamp with an explicit timezone.' using errcode='22023';end if;
    field_value:=to_jsonb(date_value);
  else
    max_length:=case when field_name in ('vessel','voyageNumber','vgmCutoffAt') then 50 when field_name='flightNumber' then 40
      when field_name in ('serviceLevel','vehicleRegistration','trailerNumber','railService') then 80 else 160 end;
    if length(text_value)>max_length then raise exception 'That routing value exceeds its supported length.' using errcode='22023';end if;
    field_value:=coalesce(to_jsonb(text_value),'null'::jsonb);
  end if;
  select job.* into job_row from public."Job_Header" job
    join public."cmp_Offices" office on office."Office_ID"=coalesce(job."Job_OrgOfficeID",job."Job_OfficeID")
    where job."Job_ID"=job_id and office."Company_ID"=p_company_id and not job."Job_IsDeleted" for update of job;
  if not found then raise exception 'That booking is outside this workspace.' using errcode='42501';end if;
  select * into route_row from public."Job_Routing" where "JobRoute_ID"=route_id and "Job_ID"=job_id for update;
  if not found then raise exception 'Choose an exact routing leg from this booking.' using errcode='42501';end if;
  if nullif(p_arguments->>'expected_updated_at','') is null or job_row."Job_UpdatedAt" is distinct from (p_arguments->>'expected_updated_at')::timestamptz
    or nullif(p_arguments->>'expected_route_updated_at','') is null or route_row."JobRoute_UpdatedAt" is distinct from (p_arguments->>'expected_route_updated_at')::timestamptz then
    raise exception 'The booking or routing leg changed. Read it again and request fresh approval.' using errcode='40001';end if;
  if (field_name in ('vessel','voyageNumber','vgmCutoffAt') and route_row."JobRoute_ModeCode" is distinct from 'sea')
    or (field_name='flightNumber' and route_row."JobRoute_ModeCode" is distinct from 'air')
    or (field_name in ('vehicleRegistration','trailerNumber') and coalesce(route_row."JobRoute_ModeCode",'') not in ('road','courier'))
    or (field_name='railService' and route_row."JobRoute_ModeCode" is distinct from 'rail') then
    raise exception 'That field does not belong to this leg mode. Review the exact leg in Booking Details.' using errcode='22023';end if;
  saved:=booking_api.workspace_extended(actor_auth_id,job_row."Job_BookingReference");
  select jsonb_agg(case when line->>'id'=route_id::text then line||jsonb_build_object(field_name,field_value) else line end order by ordinal)
    into lines from jsonb_array_elements(saved->'routes') with ordinality entries(line,ordinal);
  if not exists(select 1 from jsonb_array_elements(lines) line where line->>'id'=route_id::text) then
    raise exception 'The routing workspace changed. Reload before approving.' using errcode='40001';end if;
  saved:=public.booking_workflow_save(actor_auth_id,job_id,jsonb_build_object('routes',lines));
  select booking_api.route_dexter_values(route) into result_values from public."Job_Routing" route where "JobRoute_ID"=route_id;
  insert into booking_api.events(company_id,job_id,event_type,summary,metadata,actor_user_id)
    values(p_company_id,job_id,'dexter_route_updated','Approved routing field updated',jsonb_build_object(
      'routeId',route_id,'field',field_name,'before',booking_api.route_dexter_values(route_row)->field_name,
      'after',result_values->field_name,'reason',btrim(p_arguments->>'reason')),p_user_id);
  return jsonb_build_object('recordId',route_id,'bookingId',job_id,'bookingReference',job_row."Job_BookingReference",
    'field',field_name,'before',booking_api.route_dexter_values(route_row)->field_name,'after',result_values->field_name,
    'updatedAt',saved#>'{booking,updatedAt}','routeUpdatedAt',(select "JobRoute_UpdatedAt" from public."Job_Routing" where "JobRoute_ID"=route_id),
    'sourceUrl','/bookings/'||lower(job_row."Job_BookingReference"));
end $_$;


ALTER FUNCTION "public"."multideck_dexter_action_update_booking_route"("p_company_id" "uuid", "p_user_id" "uuid", "p_arguments" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_action_update_booking_shipment_value"("p_company_id" "uuid", "p_user_id" "uuid", "p_arguments" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid;job public."Job_Header";money jsonb;before_value jsonb;after_value jsonb;saved jsonb;
begin
  select "Auth_User_ID" into actor from public."cmp_Users" where "User_ID"=p_user_id and "Company_ID"=p_company_id and "User_AccessStatus"='active';
  if actor is null or not booking_api.has_permission(actor,'Bookings.Read') or not booking_api.has_permission(actor,'Bookings.Write') then
    raise exception 'You do not have permission to edit shipment goods value.' using errcode='42501';end if;
  if jsonb_typeof(p_arguments) is distinct from 'object'
    or not (p_arguments ?& array['target_id','expected_updated_at','amount','currency','reason'])
    or exists(select 1 from jsonb_object_keys(p_arguments) key where key not in ('target_id','expected_updated_at','amount','currency','reason'))
    or jsonb_typeof(p_arguments->'amount') not in ('string','null') or jsonb_typeof(p_arguments->'currency') not in ('string','null')
    or nullif(btrim(p_arguments->>'reason'),'') is null then
    raise exception 'Provide an exact shipment value amount and currency, or explicit null to clear.' using errcode='22023';end if;
  money:=booking_api.normalise_shipment_value(jsonb_build_object('amount',p_arguments->'amount','currency',p_arguments->'currency'));
  select j.* into job from public."Job_Header" j join public."cmp_Offices" office on office."Office_ID"=coalesce(j."Job_OrgOfficeID",j."Job_OfficeID")
    where j."Job_ID"=nullif(p_arguments->>'target_id','')::uuid and office."Company_ID"=p_company_id and not j."Job_IsDeleted" for update of j;
  if not found then raise exception 'That shipment is outside this workspace.' using errcode='42501';end if;
  if nullif(p_arguments->>'expected_updated_at','') is null or job."Job_UpdatedAt" is distinct from (p_arguments->>'expected_updated_at')::timestamptz then
    raise exception 'The booking changed. Read its shipment value again and request fresh approval.' using errcode='40001';end if;
  before_value:=booking_api.shipment_value_dexter_values(job);
  saved:=public.booking_workflow_save(actor,job."Job_ID",jsonb_build_object('shipmentGoodsValue',money));
  select booking_api.shipment_value_dexter_values(j) into after_value from public."Job_Header" j where j."Job_ID"=job."Job_ID";
  if before_value is distinct from after_value then
    insert into booking_api.events(company_id,job_id,event_type,summary,metadata,actor_user_id)
      values(p_company_id,job."Job_ID",'dexter_shipment_value_updated','Approved shipment goods value updated; cargo allocations retained.',
        jsonb_build_object('before',before_value,'after',after_value,'reason',btrim(p_arguments->>'reason')),p_user_id);
  end if;
  return jsonb_build_object('recordId',job."Job_ID",'bookingReference',job."Job_BookingReference",'before',before_value,'after',after_value,
    'updatedAt',saved#>'{booking,updatedAt}','sourceUrl','/bookings/'||lower(job."Job_BookingReference"));
end $$;


ALTER FUNCTION "public"."multideck_dexter_action_update_booking_shipment_value"("p_company_id" "uuid", "p_user_id" "uuid", "p_arguments" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_action_update_booking_weight_override"("p_company_id" "uuid", "p_user_id" "uuid", "p_arguments" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid;job public."Job_Header";before_weight text;after_weight text;normalized jsonb;
begin
  select "Auth_User_ID" into actor from public."cmp_Users" where "User_ID"=p_user_id and "Company_ID"=p_company_id and "User_AccessStatus"='active';
  if actor is null or not booking_api.has_permission(actor,'Bookings.Read') or not booking_api.has_permission(actor,'Bookings.Write') then
    raise exception 'You do not have permission to edit the shipment weight override.' using errcode='42501';end if;
  if jsonb_typeof(p_arguments) is distinct from 'object'
    or not (p_arguments ?& array['target_id','expected_updated_at','weightKg','reason'])
    or exists(select 1 from jsonb_object_keys(p_arguments) key where key not in ('target_id','expected_updated_at','weightKg','reason'))
    or jsonb_typeof(p_arguments->'weightKg') not in ('string','null')
    or nullif(btrim(p_arguments->>'reason'),'') is null then
    raise exception 'Provide the exact shipment override in kg, or explicit null to clear, with a reason.' using errcode='22023';end if;
  select j.* into job from public."Job_Header" j join public."cmp_Offices" office on office."Office_ID"=coalesce(j."Job_OrgOfficeID",j."Job_OfficeID")
    where j."Job_ID"=nullif(p_arguments->>'target_id','')::uuid and office."Company_ID"=p_company_id and not j."Job_IsDeleted" for update of j;
  if not found then raise exception 'That shipment is outside this workspace.' using errcode='42501';end if;
  if nullif(p_arguments->>'expected_updated_at','') is null or job."Job_UpdatedAt" is distinct from (p_arguments->>'expected_updated_at')::timestamptz then
    raise exception 'The booking changed. Read it again and request fresh approval.' using errcode='40001';end if;
  normalized:=booking_api.normalise_cargo_numbers(jsonb_build_array(jsonb_build_object('chargeableWeightKg',p_arguments->'weightKg')))#>'{0,chargeableWeightKg}';
  before_weight:=job."Job_EditableDetailsJSON"->>'chargeableWeightKg';
  perform public.booking_workflow_save(actor,job."Job_ID",jsonb_build_object('editableDetails',jsonb_build_object('chargeableWeightKg',normalized)));
  select "Job_EditableDetailsJSON"->>'chargeableWeightKg' into after_weight from public."Job_Header" where "Job_ID"=job."Job_ID";
  if before_weight is distinct from after_weight then
    insert into booking_api.events(company_id,job_id,event_type,summary,metadata,actor_user_id)
      values(p_company_id,job."Job_ID",'dexter_weight_override_updated','Approved shipment weight override updated; cargo and documents unchanged.',
        jsonb_build_object('before',before_weight,'after',after_weight,'unit','kg','reason',btrim(p_arguments->>'reason')),p_user_id);
  end if;
  return jsonb_build_object('recordId',job."Job_ID",'before',before_weight,'after',after_weight,'unit','kg',
    'sourceUrl','/bookings/'||lower(job."Job_BookingReference"));
end $$;


ALTER FUNCTION "public"."multideck_dexter_action_update_booking_weight_override"("p_company_id" "uuid", "p_user_id" "uuid", "p_arguments" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_action_update_company_foundation"("p_company_id" "uuid", "p_user_id" "uuid", "p_arguments" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare profile public."CRM_AccountProfiles"; current_offices jsonb; proposed_offices jsonb; changes jsonb;
begin
  if auth.role() is distinct from 'service_role' or public._multideck_crm_actor_company(p_user_id) is distinct from p_company_id then
    raise exception 'The company scope does not match this operator.' using errcode='42501';
  end if;
  perform public._multideck_crm_write_actor(p_user_id);
  perform public._multideck_crm_require_account_access(p_user_id,(p_arguments->>'target_id')::uuid);
  select * into profile from public."CRM_AccountProfiles"
    where "CRMAccount_OrgID"=(p_arguments->>'target_id')::uuid and not "CRMAccount_IsDeleted"
    order by "CRMAccount_ID" limit 1 for update;
  if not found then raise exception 'Organisation not found.' using errcode='P0002';end if;
  if profile."CRMAccount_EditVersion" is distinct from (p_arguments->>'expected_version')::bigint then
    raise exception 'CRM_CONFLICT:This organisation changed since it was loaded.' using errcode='P0001';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object('officeId',"CRMAccountOffice_OrgOfficeID",'isPrimary',"CRMAccountOffice_IsPrimary") order by "CRMAccountOffice_OrgOfficeID"),'[]'::jsonb)
    into current_offices from public."CRM_AccountOfficeAssignments" where "CRMAccountOffice_AccountID"=profile."CRMAccount_ID";
  if jsonb_typeof(p_arguments->'office_assignments') is distinct from 'array' then
    raise exception 'Read the responsible offices before preparing this change.' using errcode='22023';end if;
  select coalesce(jsonb_agg(value order by value->>'officeId'),'[]'::jsonb) into proposed_offices from jsonb_array_elements(p_arguments->'office_assignments');
  changes:=jsonb_build_object('accountCode',p_arguments->>'account_code','scopeCode',p_arguments->>'scope_code','isPotential',p_arguments->'is_potential');
  -- The canonical writer accepts partial edits. Only replace assignments when
  -- they change; a code correction must not delete/recreate unchanged offices.
  if proposed_offices is distinct from current_offices then changes:=changes||jsonb_build_object('officeAssignments',proposed_offices);end if;
  return public.multideck_crm_update_organisation_foundation(p_user_id,(p_arguments->>'target_id')::uuid,(p_arguments->>'expected_version')::bigint,changes);
end $$;


ALTER FUNCTION "public"."multideck_dexter_action_update_company_foundation"("p_company_id" "uuid", "p_user_id" "uuid", "p_arguments" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_action_update_customs_declaration"("p_company_id" "uuid", "p_user_id" "uuid", "p_arguments" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth', 'booking_api'
    AS $$
declare
  v_auth_user_id uuid;
  v_target_id uuid := nullif(p_arguments->>'target_id', '')::uuid;
  v_direction text;
  v_current jsonb;
  v_draft jsonb;
  v_saved record;
  v_has_provider_draft boolean := false;
  v_job_related boolean := false;
begin
  select actor."Auth_User_ID" into v_auth_user_id
  from public."cmp_Users" actor
  where actor."User_ID" = p_user_id and actor."Company_ID" = p_company_id
    and actor."Auth_User_ID" is not null and actor."User_AccessStatus" = 'active';
  if v_auth_user_id is null then raise exception 'Your signed-in account is not linked to this workspace.' using errcode = '42501'; end if;

  select declaration."CUST_Direction", declaration."CUST_GenericPayloadJSON",
         nullif(btrim(declaration."CUST_iCustomsExternalID"), '') is not null,
         declaration."CUST_JobID" is not null
  into v_direction, v_current, v_has_provider_draft, v_job_related
  from public."Customs_Declarations" declaration
  where declaration."CUST_id" = v_target_id
    and declaration."CUST_Status" = 'draft'
    and declaration."CUST_DeclarationKind" in ('cds_export', 'cds_import')
    and declaration."CUST_Direction" in ('export', 'import')
    and not declaration."CUST_IsDeleted"
    and booking_api.customs_access(v_auth_user_id, declaration."CUST_id", true)
  for update;
  if not found then raise exception 'This Customs draft is unavailable or can no longer be edited.' using errcode = '42501'; end if;

  v_draft := public._multideck_dexter_customs_draft_payload(
    coalesce(v_current, '{}'::jsonb) || coalesce(p_arguments->'draft', '{}'::jsonb), v_direction
  );
  if v_job_related then
    select * into v_saved from booking_api.save_job_customs_draft(v_auth_user_id, v_target_id, v_draft);
  elsif v_direction = 'import' then
    -- The legacy standalone writers use auth.uid(). This action is server-only
    -- and the prepared-action dispatcher has already bound p_user_id to the
    -- approved company and target, so expose that exact actor only for this
    -- transaction-local call.
    perform set_config('request.jwt.claim.sub', v_auth_user_id::text, true);
    select * into v_saved from public.save_customs_import_draft(v_target_id, v_draft);
  else
    perform set_config('request.jwt.claim.sub', v_auth_user_id::text, true);
    select * into v_saved from public.save_customs_export_draft(v_target_id, v_draft);
  end if;
  return jsonb_build_object(
    'recordId', v_saved.declaration_id, 'reference', v_saved.local_reference_number,
    'direction', v_direction, 'sourceType', case when v_job_related then 'job_related' else 'standalone' end,
    'needsProviderDraftRefresh', v_has_provider_draft, 'updatedAt', v_saved.updated_at
  );
end;
$$;


ALTER FUNCTION "public"."multideck_dexter_action_update_customs_declaration"("p_company_id" "uuid", "p_user_id" "uuid", "p_arguments" "jsonb") OWNER TO "postgres";


