CREATE OR REPLACE FUNCTION "public"."multideck_dexter_active_run"("p_operation" "text", "p_run_id" "uuid", "p_company_id" "uuid", "p_user_id" "uuid", "p_auth_user_id" "uuid", "p_client_session_id" "uuid", "p_conversation_id" "uuid" DEFAULT NULL::"uuid", "p_worker_token" "uuid" DEFAULT NULL::"uuid", "p_input_id" "uuid" DEFAULT NULL::"uuid", "p_input" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text", "p_response_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare r public."AI_DexterActiveRuns";s public."AI_DexterSteeringInputs";v_inputs jsonb;
begin
 if coalesce(auth.role(),'')<>'service_role' then raise exception 'server_only' using errcode='42501';end if;
 if not exists(select 1 from public."cmp_Users" where "User_ID"=p_user_id and "Company_ID"=p_company_id
  and "Auth_User_ID"=p_auth_user_id and coalesce("User_AccessStatus",'active')='active')
 then raise exception 'actor_unavailable' using errcode='42501';end if;
 if p_run_id is null or p_client_session_id is null then raise exception 'invalid_run' using errcode='22023';end if;
 if p_operation='begin' then
  if p_worker_token is null then raise exception 'worker_required' using errcode='22023';end if;
  if p_conversation_id is not null and not exists(select 1 from public."AI_Conversations"
   where "AICNV_ID"=p_conversation_id and "AICNV_CompanyID"=p_company_id and "AICNV_OwnerUserID"=p_user_id
   and "AICNV_Channel"='chat' and "AICNV_EndedAt" is null)
  then raise exception 'conversation_unavailable' using errcode='42501';end if;
  insert into public."AI_DexterActiveRuns"(id,company_id,user_id,client_session_id,conversation_id,worker_token)
   values(p_run_id,p_company_id,p_user_id,p_client_session_id,p_conversation_id,p_worker_token)
   on conflict(id) do nothing;
 end if;
 select * into r from public."AI_DexterActiveRuns" where id=p_run_id and company_id=p_company_id
  and user_id=p_user_id and client_session_id=p_client_session_id for update;
 if not found then raise exception 'run_unavailable' using errcode='42501';end if;
 if p_operation in ('begin','claim','transition','finish') and p_worker_token is distinct from r.worker_token
 then raise exception 'worker_unavailable' using errcode='42501';end if;
 if r.status='active' and r.expires_at<=clock_timestamp() then
  update public."AI_DexterActiveRuns" set status='expired',finished_at=clock_timestamp() where id=r.id;
  update public."AI_DexterSteeringInputs" set status=case when status='pending' then 'failed' else 'unconfirmed' end,updated_at=clock_timestamp()
   where run_id=r.id and status in ('pending','claimed','submitted','queued');
  r.status:='expired';
 end if;
 if p_operation='enqueue' then
  -- Request IDs are immutable: a retry reads its original outcome, never repeats it.
  select * into s from public."AI_DexterSteeringInputs" where id=p_input_id;
  if found then
   if s.run_id<>r.id or s.input is distinct from p_input then raise exception 'steering_id_reused' using errcode='22023';end if;
  else
   if r.status<>'active' then raise exception 'run_finished' using errcode='55000';end if;
   if p_input_id is null or p_input is null or length(btrim(p_input)) not between 1 and 8000
    then raise exception 'invalid_steering' using errcode='22023';end if;
   if (select count(*) from public."AI_DexterSteeringInputs" where run_id=r.id)>=4
    then raise exception 'steering_limit' using errcode='54000';end if;
   if exists(select 1 from public."AI_DexterSteeringInputs" where run_id=r.id and status in ('pending','claimed','submitted','queued'))
    then raise exception 'steering_pending' using errcode='55000';end if;
   insert into public."AI_DexterSteeringInputs"(id,run_id,input) values(p_input_id,r.id,p_input) returning * into s;
  end if;
 elsif p_operation='claim' then
  if r.status='active' then
   select * into s from public."AI_DexterSteeringInputs" where run_id=r.id and status='pending' order by created_at limit 1 for update;
   if found then update public."AI_DexterSteeringInputs" set status='claimed',updated_at=clock_timestamp() where id=s.id returning * into s;end if;
  end if;
  return case when s.id is null then null else to_jsonb(s) end;
 elsif p_operation='transition' then
  select * into s from public."AI_DexterSteeringInputs" where id=p_input_id and run_id=r.id for update;
  if not found then raise exception 'steering_unavailable' using errcode='22023';end if;
  if s.status is distinct from p_status then
   if r.status<>'active' or not (
    (s.status='claimed' and p_status in ('submitted','failed','unconfirmed')) or
    (s.status='submitted' and p_status in ('queued','failed','unconfirmed','incorporated')) or
    (s.status='queued' and p_status in ('incorporated','failed','unconfirmed')))
   then raise exception 'invalid_steering_transition' using errcode='55000';end if;
   if p_status='incorporated' and nullif(btrim(p_response_id),'') is null
    then raise exception 'response_required' using errcode='22023';end if;
   update public."AI_DexterSteeringInputs" set status=p_status,response_id=p_response_id,updated_at=clock_timestamp() where id=s.id;
  end if;
 elsif p_operation='finish' then
  if p_status is null or p_status not in ('completed','failed') then raise exception 'invalid_run_status' using errcode='22023';end if;
  if r.status='active' then
   update public."AI_DexterActiveRuns" set status=p_status,finished_at=clock_timestamp() where id=r.id;
   update public."AI_DexterSteeringInputs" set status=case when status='pending' then 'failed' else 'unconfirmed' end,updated_at=clock_timestamp()
    where run_id=r.id and status in ('pending','claimed','submitted','queued');
   r.status:=p_status;
  end if;
 elsif p_operation not in ('begin','status') then raise exception 'invalid_operation' using errcode='22023';
 end if;
 select coalesce(jsonb_agg(to_jsonb(i) order by i.created_at),'[]'::jsonb) into v_inputs from public."AI_DexterSteeringInputs" i where i.run_id=r.id;

 return jsonb_build_object('id',r.id,'status',r.status,'expiresAt',r.expires_at,'inputs',v_inputs,
  'savedResult',(select jsonb_build_object('conversationId',c."AICNV_ID",'messageId',m."AIMSG_ID")
   from public."AI_Conversations" c join public."AI_Messages" m on m."AIMSG_ConversationID"=c."AICNV_ID"
   where c."AICNV_ID"=r.saved_conversation_id and m."AIMSG_ID"=r.saved_message_id
    and c."AICNV_CompanyID"=p_company_id and c."AICNV_OwnerUserID"=p_user_id
    and c."AICNV_Channel"='chat' and c."AICNV_EndedAt" is null));

end $$;


ALTER FUNCTION "public"."multideck_dexter_active_run"("p_operation" "text", "p_run_id" "uuid", "p_company_id" "uuid", "p_user_id" "uuid", "p_auth_user_id" "uuid", "p_client_session_id" "uuid", "p_conversation_id" "uuid", "p_worker_token" "uuid", "p_input_id" "uuid", "p_input" "text", "p_status" "text", "p_response_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_approve_prepared_action"("p_prepared_action_id" "uuid", "p_company_id" "uuid", "p_user_id" "uuid", "p_conversation_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'server_only' using errcode = '42501';
  end if;
  update public."AI_DexterPreparedActions"
  set "AIDexterPrepared_ApprovedAt" = now()
  where "AIDexterPrepared_ID" = p_prepared_action_id
    and "AIDexterPrepared_CompanyID" = p_company_id
    and "AIDexterPrepared_UserID" = p_user_id
    and "AIDexterPrepared_ConversationID" is not distinct from p_conversation_id
    and "AIDexterPrepared_Status" = 'prepared'
    and "AIDexterPrepared_ExpiresAt" > now();
  return found;
end;
$$;


ALTER FUNCTION "public"."multideck_dexter_approve_prepared_action"("p_prepared_action_id" "uuid", "p_company_id" "uuid", "p_user_id" "uuid", "p_conversation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_begin_writing_profile"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_context record;
  v_profile_id uuid;
  v_already_consented boolean := false;
begin
  select * into v_context from public._multideck_dexter_context();
  if not public._multideck_dexter_has_permission(v_context.user_id, 'Email.Read')
     or not public._multideck_dexter_has_permission(v_context.user_id, 'Email.AIRead') then
    raise exception 'You do not have permission to use email with Dexter.' using errcode = '42501';
  end if;

  select profile."AIDexterWritingProfile_ConsentAt" is not null
  into v_already_consented
  from public."AI_DexterWritingProfiles" profile
  where profile."AIDexterWritingProfile_CompanyID" = v_context.company_id
    and profile."AIDexterWritingProfile_UserID" = v_context.user_id;

  insert into public."AI_DexterWritingProfiles" (
    "AIDexterWritingProfile_CompanyID",
    "AIDexterWritingProfile_UserID",
    "AIDexterWritingProfile_IsEnabled",
    "AIDexterWritingProfile_StatusCode",
    "AIDexterWritingProfile_ConsentAt",
    "AIDexterWritingProfile_LastError",
    "AIDexterWritingProfile_UpdatedAt"
  ) values (
    v_context.company_id,
    v_context.user_id,
    true,
    'processing',
    now(),
    null,
    now()
  )
  on conflict ("AIDexterWritingProfile_CompanyID", "AIDexterWritingProfile_UserID") do update
  set "AIDexterWritingProfile_IsEnabled" = true,
      "AIDexterWritingProfile_StatusCode" = 'processing',
      "AIDexterWritingProfile_ConsentAt" = coalesce(public."AI_DexterWritingProfiles"."AIDexterWritingProfile_ConsentAt", now()),
      "AIDexterWritingProfile_LastError" = null,
      "AIDexterWritingProfile_UpdatedAt" = now()
  returning "AIDexterWritingProfile_ID" into v_profile_id;

  if not coalesce(v_already_consented, false) then
    perform public._multideck_dexter_writing_profile_audit(
      v_profile_id, v_context.company_id, v_context.user_id, 'consented', 'processing', 0
    );
  end if;
  return public.multideck_dexter_get_writing_profile();
end;
$$;


ALTER FUNCTION "public"."multideck_dexter_begin_writing_profile"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_bind_run_result"("p_run_id" "uuid", "p_company_id" "uuid", "p_user_id" "uuid", "p_auth_user_id" "uuid", "p_client_session_id" "uuid", "p_conversation_id" "uuid", "p_message_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare r public."AI_DexterActiveRuns";
begin
 if coalesce(auth.role(),'')<>'service_role' then raise exception 'server_only' using errcode='42501';end if;
 if not exists(select 1 from public."cmp_Users" where "User_ID"=p_user_id and "Company_ID"=p_company_id
  and "Auth_User_ID"=p_auth_user_id and coalesce("User_AccessStatus",'active')='active')
 then raise exception 'actor_unavailable' using errcode='42501';end if;
 select * into r from public."AI_DexterActiveRuns" where id=p_run_id and company_id=p_company_id
  and user_id=p_user_id and client_session_id=p_client_session_id for update;
 if not found then raise exception 'run_unavailable' using errcode='42501';end if;
 if r.conversation_id is not null and r.conversation_id<>p_conversation_id
 then raise exception 'conversation_mismatch' using errcode='42501';end if;
 if not exists(select 1 from public."AI_Messages" m join public."AI_Conversations" c
  on c."AICNV_ID"=m."AIMSG_ConversationID"
  where m."AIMSG_ID"=p_message_id and m."AIMSG_ConversationID"=p_conversation_id
   and m."AIMSG_Role"='assistant' and m."AIMSG_ContentJSON"->'metadata'->>'activeRunId'=p_run_id::text
   and c."AICNV_CompanyID"=p_company_id and c."AICNV_OwnerUserID"=p_user_id
   and c."AICNV_Channel"='chat' and c."AICNV_EndedAt" is null)
 then raise exception 'saved_reply_unavailable' using errcode='42501';end if;
 if r.saved_message_id is not null and (r.saved_message_id<>p_message_id or r.saved_conversation_id<>p_conversation_id)
 then raise exception 'result_already_bound' using errcode='55000';end if;
 update public."AI_DexterActiveRuns" set saved_conversation_id=p_conversation_id,saved_message_id=p_message_id where id=r.id;
end $$;


ALTER FUNCTION "public"."multideck_dexter_bind_run_result"("p_run_id" "uuid", "p_company_id" "uuid", "p_user_id" "uuid", "p_auth_user_id" "uuid", "p_client_session_id" "uuid", "p_conversation_id" "uuid", "p_message_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_bookings_before_branch_direction_20260904"("p_company_id" "uuid", "p_search" "text", "p_take" integer) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth', 'extensions'
    AS $_$
  select coalesce(jsonb_agg(
    item.value || jsonb_strip_nulls(jsonb_build_object(
      'equipment', container_plan.equipment,
      'containers', coalesce(container_plan.lines, '[]'::jsonb)
    ))
    order by item.ordinality
  ), '[]'::jsonb)
  from jsonb_array_elements(
    public.multideck_dexter_domain_bookings_before_container_allocation_20260904(p_company_id, p_search, p_take)
  ) with ordinality item(value, ordinality)
  left join lateral (
    select
      booking_api.quote_container_summary(jsonb_build_object(
        'containerRequests', coalesce(jsonb_agg(jsonb_build_object(
          'quantity', grouped.quantity,
          'type', grouped.type_code
        ) order by grouped.request_order, grouped.first_created, grouped.type_code), '[]'::jsonb)
      )) as equipment,
      coalesce(jsonb_agg(jsonb_build_object(
        'type', grouped.type_code,
        'quantity', grouped.quantity
      ) order by grouped.request_order, grouped.first_created, grouped.type_code), '[]'::jsonb) as lines
    from (
      select
        container."JobContainer_TypeCodeSnapshot" as type_code,
        count(*) as quantity,
        min(case
          when coalesce(container."JobContainer_JSON"#>>'{data,requestIndex}', '') ~ '^[0-9]+$'
            then (container."JobContainer_JSON"#>>'{data,requestIndex}')::integer
          else 2147483647
        end) as request_order,
        min(container."JobContainer_CreatedAt") as first_created
      from public."Job_Containers" container
      where container."Job_ID" = (item.value->>'recordId')::uuid
        and not container."JobContainer_IsDeleted"
        and nullif(btrim(container."JobContainer_TypeCodeSnapshot"), '') is not null
      group by container."JobContainer_TypeCodeSnapshot"
    ) grouped
  ) container_plan on true
$_$;


ALTER FUNCTION "public"."multideck_dexter_bookings_before_branch_direction_20260904"("p_company_id" "uuid", "p_search" "text", "p_take" integer) OWNER TO "postgres";


