        ||coalesce(d."JobCargoDG_UNNumber",d."JobCargoDG_ProperShippingName",'Dangerous-goods evidence')) result,
      j."Job_BookingReference" reference,c."JobCargo_LineNo" line_number,d."JobCargoDG_ID" record_id
