CREATE OR REPLACE FUNCTION "public"."multideck_dexter_domain_booking_shipment_value"("p_company_id" "uuid", "p_search" "text", "p_take" integer) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(jsonb_agg(result order by reference),'[]'::jsonb) from (
    select booking_api.shipment_value_dexter_values(job)||jsonb_build_object('recordId',job."Job_ID",'bookingId',job."Job_ID",
      'bookingReference',job."Job_BookingReference",'updatedAt',job."Job_UpdatedAt",'sourceTable','Job_Header','valueScope','shipment_operational_values',
      'targetLabel',job."Job_BookingReference"||' · Shipment values','sourceUrl','/bookings/'||lower(job."Job_BookingReference")) result,
      job."Job_BookingReference" reference
    from public."Job_Header" job join public."cmp_Offices" office on office."Office_ID"=coalesce(job."Job_OrgOfficeID",job."Job_OfficeID")
    where office."Company_ID"=p_company_id and not job."Job_IsDeleted" and (nullif(btrim(p_search),'') is null
      or job."Job_ID"::text=btrim(p_search) or job."Job_BookingReference" ilike '%'||btrim(p_search)||'%')
    order by job."Job_BookingReference" limit greatest(1,least(coalesce(p_take,10),25))
  ) selected
$$;


ALTER FUNCTION "public"."multideck_dexter_domain_booking_shipment_value"("p_company_id" "uuid", "p_search" "text", "p_take" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_domain_booking_summary"("p_company_id" "uuid", "p_search" "text", "p_take" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare result jsonb;
begin
 if nullif(btrim(p_search),'') is not null then
  return jsonb_build_object('error','This summary counts all accessible bookings. Use an empty search, then use the returned status groups.');
 end if;
 with scoped as (
  select coalesce(nullif(btrim(j."Job_Status"),''),'Unknown') as status,j."Job_ClosedDate" is not null as closed
  from public."Job_Header" j join public."cmp_Offices" o on o."Office_ID"=coalesce(j."Job_OrgOfficeID",j."Job_OfficeID")
  where o."Company_ID"=p_company_id and not coalesce(j."Job_IsDeleted",false)
 ), grouped as (select status,closed,count(*) as total from scoped group by status,closed)
 select jsonb_build_object('totalCount',coalesce(sum(total),0),'countIsExact',true,
  'scope','All non-deleted bookings in the signed-in company; no result limit.',
  'byStatus',coalesce(jsonb_agg(jsonb_build_object('status',status,'hasClosedDate',closed,'count',total) order by status,closed),'[]'::jsonb),
  'observedAt',statement_timestamp(),'sourceUrl','/bookings') into result from grouped;
 return result;
end $$;


ALTER FUNCTION "public"."multideck_dexter_domain_booking_summary"("p_company_id" "uuid", "p_search" "text", "p_take" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_domain_bookings"("p_company_id" "uuid", "p_search" "text", "p_take" integer) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(jsonb_agg(
    item.value || jsonb_strip_nulls(jsonb_build_object(
      'operatingCountryCode', booking_api.operating_country_code(coalesce(job."Job_OrgOfficeID", job."Job_OfficeID")),
      'calculatedDirection', booking_api.direction_for_route(
        coalesce(job."Job_OrgOfficeID", job."Job_OfficeID"),
        coalesce(job."Job_OriginUNLocode", item.value->>'origin'),
        coalesce(job."Job_DestinationUNLocode", item.value->>'destination')
      ),
      'directionMatchesRoute', case
        when booking_api.direction_for_route(
          coalesce(job."Job_OrgOfficeID", job."Job_OfficeID"),
          coalesce(job."Job_OriginUNLocode", item.value->>'origin'),
          coalesce(job."Job_DestinationUNLocode", item.value->>'destination')
        ) is null then null
        else booking_api.normalise_direction(item.value->>'direction') = booking_api.direction_for_route(
          coalesce(job."Job_OrgOfficeID", job."Job_OfficeID"),
          coalesce(job."Job_OriginUNLocode", item.value->>'origin'),
          coalesce(job."Job_DestinationUNLocode", item.value->>'destination')
        )
      end
    )) order by item.ordinality
  ), '[]'::jsonb)
  from jsonb_array_elements(
    public.multideck_dexter_bookings_before_branch_direction_20260904(p_company_id, p_search, p_take)
  ) with ordinality item(value, ordinality)
  left join public."Job_Header" job
    on job."Job_ID" = nullif(item.value->>'recordId', '')::uuid
   and not job."Job_IsDeleted";
$$;


