CREATE OR REPLACE FUNCTION "public"."multideck_dexter_domain_bookings_before_container_allocation_20"("p_company_id" "uuid", "p_search" "text", "p_take" integer) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth', 'booking_api', 'extensions'
    AS $$
  select coalesce(jsonb_agg(result.row_data order by result.search_rank desc, result.sort_updated desc), '[]'::jsonb)
  from (
    select jsonb_strip_nulls(jsonb_build_object(
      'recordId', job."Job_ID",
      'bookingReference', coalesce(job."Job_BookingReference", 'MD-' || job."Job_Number"),
      'jobReference', 'JOB-' || job."Job_Number",
      'sourceQuoteId', job."Job_SourceQuoteID",
      'customerName', coalesce(customer."Org_Name", 'Unassigned customer'),
      'customerReference', coalesce(job."Job_CustomerReference", customer."Org_AccCode", ''),
      'status', initcap(replace(coalesce(job."Job_Status", 'draft'), '_', ' ')),
      'jobStatus', job."Job_Status", 'trackingStatus', job."Job_TrackingStatus",
      'riskScore', job."Job_TrackingRiskScore", 'mode', upper(coalesce(job."Job_TransportModeSummary", '')),
      'direction', initcap(replace(coalesce(job."Job_Direction", 'unknown'), '_', ' ')),
      'origin', coalesce(job."Job_OriginNameSnapshot", job."Job_OriginUNLocode", ''),
      'destination', coalesce(job."Job_DestinationNameSnapshot", job."Job_DestinationUNLocode", ''),
      'route', concat_ws(' → ', coalesce(job."Job_OriginNameSnapshot", job."Job_OriginUNLocode"), coalesce(job."Job_DestinationNameSnapshot", job."Job_DestinationUNLocode")),
      'carrier', coalesce(carrier."Org_Name", 'Carrier pending'),
      'goodsDescription', cargo.description, 'packageQuantity', cargo.package_quantity,
      'grossWeightKg', cargo.gross_weight_kg, 'containerCount', containers.container_count,
      'containersComplete', containers.complete_count = containers.container_count and containers.container_count > 0,
      'currentLocation', coalesce(job."Job_CurrentLocationNameSnapshot", 'Planning'),
      'requiredDeliveryDate', job."Job_RequiredDeliveryDate", 'predictedDeliveryAt', job."Job_PredictedDeliveryAt",
      'departureDate', coalesce(route."JobRoute_ActualDepartureAt", route."JobRoute_EstimatedDepartureAt", route."JobRoute_PlannedDepartureAt")::date,
      'arrivalDate', coalesce(route."JobRoute_ActualArrivalAt", route."JobRoute_EstimatedArrivalAt", route."JobRoute_PlannedArrivalAt")::date,
      'actualDeliveryAt', route."JobRoute_ActualDeliveryAt", 'carrierBookingReference', route."JobRoute_CarrierBookingReference",
      'invoiceStatus', job."Job_InvoiceStatus", 'invoiceReference', job."Job_InvoiceReference",
      'invoiceReadyAt', job."Job_InvoiceReadyAt", 'completedAt', job."Job_CompletedAt",
      'completionReadiness', booking_api.completion_readiness_for_job(job."Job_ID"),
      'updatedAt', job."Job_UpdatedAt", 'searchEvidence', evidence.value - 'matched'
    )) as row_data,
    coalesce((evidence.value->>'confidence')::numeric, 0) as search_rank,
    job."Job_UpdatedAt" as sort_updated
    from public."Job_Header" job
    join public."cmp_Offices" office on office."Office_ID" = coalesce(job."Job_OrgOfficeID", job."Job_OfficeID") and office."Company_ID" = p_company_id
    left join public."Org_Master" customer on customer."Org_id" = job."Job_Customer"
    left join public."Org_Master" carrier on carrier."Org_id" = job."Job_Carrier"
    left join lateral (
      select routing.* from public."Job_Routing" routing where routing."Job_ID" = job."Job_ID"
      order by routing."JobRoute_IsMainCarriage" desc, routing."JobRoute_OrderNo" nulls last limit 1
    ) route on true
    left join lateral (
      select max(cargo_row."JobCargo_Description") as description,
             sum(coalesce(cargo_row."JobCargo_PackageQty", cargo_row."JobCargo_Qty")) as package_quantity,
             sum(cargo_row."JobCargo_GrossKilos") as gross_weight_kg
      from public."Job_Cargo" cargo_row
      where cargo_row."JobCargo_JobID" = job."Job_ID" and not cargo_row."JobCargo_IsDeleted"
    ) cargo on true
    left join lateral (
      select count(*)::integer as container_count,
             count(*) filter (where nullif(btrim(container."JobContainer_Number"), '') is not null and nullif(btrim(container."JobContainer_TypeCodeSnapshot"), '') is not null)::integer as complete_count
      from public."Job_Containers" container
      where container."Job_ID" = job."Job_ID" and not container."JobContainer_IsDeleted"
    ) containers on true
    cross join lateral public._multideck_dexter_search_evidence(
      p_search,
      jsonb_build_object(
        'bookingReference',coalesce(job."Job_BookingReference",'MD-'||job."Job_Number"),'jobNumber',job."Job_Number",
        'customerName',customer."Org_Name",'customerReference',coalesce(job."Job_CustomerReference",customer."Org_AccCode"),
        'jobStatus',job."Job_Status",'trackingStatus',job."Job_TrackingStatus",'mode',job."Job_TransportModeSummary",
        'direction',job."Job_Direction",'origin',coalesce(job."Job_OriginNameSnapshot",job."Job_OriginUNLocode"),
        'destination',coalesce(job."Job_DestinationNameSnapshot",job."Job_DestinationUNLocode"),'carrier',carrier."Org_Name",
        'goodsDescription',cargo.description,'carrierBookingReference',route."JobRoute_CarrierBookingReference",
        'invoiceReference',job."Job_InvoiceReference"
      ), array['bookingReference','jobNumber','customerReference','carrierBookingReference','invoiceReference']::text[]
    ) evidence(value)
    where not job."Job_IsDeleted" and (evidence.value->>'matched')::boolean
    order by search_rank desc, job."Job_UpdatedAt" desc
    limit greatest(1, least(coalesce(p_take, 10), 25))
  ) result;
$$;


ALTER FUNCTION "public"."multideck_dexter_domain_bookings_before_container_allocation_20"("p_company_id" "uuid", "p_search" "text", "p_take" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_domain_broadcasts"("p_company_id" "uuid", "p_search" "text", "p_take" integer) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
  select case when not exists (
    select 1 from public."cmp_Users" actor
    join public."cmp_Users_Roles" ur on ur."User_ID"=actor."User_ID"
    join public."sys_UserRole_Permissions" rp on rp."sys_UserRole_ID"=ur."sys_UserRole_ID"
    join public."sys_Permissions" permission on permission."sys_Permission_ID"=rp."sys_Permission_ID"
    where actor."Auth_User_ID"=auth.uid() and actor."Company_ID"=p_company_id
      and permission."sys_Permission_Value"='Broadcasts.Read'
  ) then '[]'::jsonb else coalesce((
    select jsonb_agg(jsonb_build_object(
      'recordId', broadcast."Broadcast_ID", 'subject', broadcast."Broadcast_Subject",
      'audienceMode', broadcast."Broadcast_AudienceMode", 'audience', broadcast."Broadcast_AudienceJSON",
      'status', broadcast."Broadcast_StatusCode", 'recipientCount', broadcast."Broadcast_RecipientCount",
      'excludedCount', broadcast."Broadcast_ExcludedCount", 'deliveredCount', broadcast."Broadcast_DeliveredCount",
      'failedCount', broadcast."Broadcast_FailedCount", 'deliveryMode', broadcast."Broadcast_DeliveryMode",
      'sentAt', broadcast."Broadcast_SentAt", 'createdAt', broadcast."Broadcast_CreatedAt",
      'evidence', jsonb_build_object('sourceTable','DEV_Broadcasts','sourceId',broadcast."Broadcast_ID")
    ) order by broadcast."Broadcast_CreatedAt" desc)
    from (select * from public."DEV_Broadcasts" b where b."Company_ID"=p_company_id
      and (nullif(btrim(p_search),'') is null or b."Broadcast_Subject" ilike '%'||btrim(p_search)||'%')
      order by b."Broadcast_CreatedAt" desc limit greatest(1,least(coalesce(p_take,10),25))) broadcast
  ), '[]'::jsonb) end;
$$;


ALTER FUNCTION "public"."multideck_dexter_domain_broadcasts"("p_company_id" "uuid", "p_search" "text", "p_take" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_domain_calendar"("p_company_id" "uuid", "p_search" "text", "p_take" integer) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
  with search_window as materialized (select * from public._dexter_calendar_window(p_search))
  select coalesce(jsonb_agg(row.data order by row.start_at), '[]'::jsonb)
  from (
    select meeting."CALMeeting_StartAt" as start_at,
      jsonb_strip_nulls(jsonb_build_object(
        'recordId', meeting."CALMeeting_ID", 'recordType', 'meeting',
        'title', meeting."CALMeeting_Title", 'startAt', meeting."CALMeeting_StartAt",
        'endAt', meeting."CALMeeting_EndAt", 'timeZone', meeting."CALMeeting_TimeZone",
        'status', meeting."CALMeeting_StatusCode", 'provider', meeting."CALMeeting_ProviderCode",
        'leadId', meeting."CALMeeting_LeadID", 'accountId', meeting."CALMeeting_AccountID",
        'route', '/calendar?meeting=' || meeting."CALMeeting_ID"
      )) as data
    from public."CAL_Meetings" meeting
    cross join search_window bounds
    where meeting."CALMeeting_CompanyID" = p_company_id
      and meeting."CALMeeting_OrganiserUserID" = (
        select profile."User_ID"
        from public."cmp_Users" profile
        where profile."Company_ID" = p_company_id
          and profile."Auth_User_ID" = auth.uid()
        limit 1
      )
      and meeting."CALMeeting_StatusCode" <> 'cancelled'
      and (case when bounds.starts_at is not null then meeting."CALMeeting_StartAt"<bounds.ends_at and meeting."CALMeeting_EndAt">bounds.starts_at
       else nullif(btrim(coalesce(p_search,'')),'') is null or meeting."CALMeeting_ID"::text=btrim(p_search) or (meeting."CALMeeting_Title" ilike '%'||btrim(p_search)||'%') end)
    order by meeting."CALMeeting_StartAt"
    limit greatest(1, least(coalesce(p_take,10),25))
  ) row;
$$;


ALTER FUNCTION "public"."multideck_dexter_domain_calendar"("p_company_id" "uuid", "p_search" "text", "p_take" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_domain_contact_cards"("p_company_id" "uuid", "p_search" "text", "p_take" integer) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select coalesce(jsonb_agg(row_data order by sort_updated desc),'[]'::jsonb) from (
    select jsonb_build_object('recordId',card."ContactCard_ID",'label',card."ContactCard_Label",'person',card."ContactCard_Person"->>'fullName','status',card."ContactCard_Status",'slug',card."ContactCard_Slug",'automationState',automation."Automation_State",'lastRunAt',automation."Automation_LastRunAt",'lastRunStatus',latest."AutomationRun_Status",'failedRuns',(select count(*) from public."CRM_ContactCardAutomationRuns" failed where failed."ContactCard_ID"=card."ContactCard_ID" and failed."AutomationRun_Status"='failed'),'exchanges',(select count(*) from public."CRM_ContactCardExchanges" exchange where exchange."ContactCard_ID"=card."ContactCard_ID")) row_data,card."ContactCard_UpdatedAt" sort_updated
    from public."CRM_ContactCards" card left join public."CRM_ContactCardAutomations" automation using("ContactCard_ID") left join lateral(select run."AutomationRun_Status" from public."CRM_ContactCardAutomationRuns" run where run."ContactCard_ID"=card."ContactCard_ID" order by run."AutomationRun_StartedAt" desc limit 1) latest on true
    where card."Company_ID"=p_company_id and card."ContactCard_DeletedAt" is null and (nullif(btrim(p_search),'') is null or concat_ws(' ',card."ContactCard_Label",card."ContactCard_Slug",card."ContactCard_Person"->>'fullName',card."ContactCard_Person"->>'company') ilike '%'||btrim(p_search)||'%')
    order by card."ContactCard_UpdatedAt" desc limit greatest(1,least(coalesce(p_take,10),25))
  ) rows;
$$;


