CREATE OR REPLACE FUNCTION "public"."multideck_dexter_domain_customers"("p_company_id" "uuid", "p_search" "text", "p_take" integer) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
  select coalesce(jsonb_agg(item.row_data order by item.search_rank desc, item.organisation_name), '[]'::jsonb)
  from (
    select
      jsonb_build_object(
        'recordId', organisation."Org_id", 'recordType', 'company',
        'sourceTable', 'Org_Master', 'editVersion', profile."CRMAccount_EditVersion",
        'name', organisation."Org_Name", 'accountCode', organisation."Org_AccCode",
        'scopeCode', profile."CRMAccount_ScopeCode", 'isPotential', organisation."Org_CRMIsPotentialCustomer",
        'organisationTypes', types.values,
        'relationshipStatus', coalesce(profile."CRMAccount_RelationshipStatusCode", organisation."Org_CRMRelationshipStatusCode"),
        'responsibleOffices', offices.values,
        'addresses', addresses.values,
        'contacts', contacts.values,
        'relatedPartyDefaults', related_defaults.values,
        'sourceEvidence', jsonb_build_object(
          'sourceTable', 'Org_Master', 'sourceId', organisation."Org_id",
          'profileTable', 'CRM_AccountProfiles', 'profileId', profile."CRMAccount_ID"
        ),
        'searchEvidence', evidence.value - 'matched'
      ) row_data,
      coalesce((evidence.value ->> 'confidence')::numeric, 0) search_rank,
      organisation."Org_Name" organisation_name
    from public.multideck_crm_accessible_account_ids(p_company_id) accessible
    join public."Org_Master" organisation on organisation."Org_id" = accessible.account_id
    join public."CRM_AccountProfiles" profile
      on profile."CRMAccount_OrgID" = organisation."Org_id" and not profile."CRMAccount_IsDeleted"
    left join lateral (
      select coalesce(jsonb_agg(type."OrgType_Name" order by type."OrgType_Name"), '[]'::jsonb) values
      from public."Org_Master_Type" link
      join public."Org_Types" type on type."OrgType_ID" = link."OrgType_ID"
      where link."Org_ID" = organisation."Org_id"
    ) types on true
    left join lateral (
      select coalesce(jsonb_agg(jsonb_build_object(
        'officeId', office."Office_ID", 'name', office."Office_Name", 'code', office."Office_Code",
        'isPrimary', assignment."CRMAccountOffice_IsPrimary"
      ) order by assignment."CRMAccountOffice_IsPrimary" desc, office."Office_Name"), '[]'::jsonb) values,
      string_agg(concat_ws(' ', office."Office_Name", office."Office_Code"), ' ') search_text
      from public."CRM_AccountOfficeAssignments" assignment
      join public."cmp_Offices" office on office."Office_ID" = assignment."CRMAccountOffice_OrgOfficeID"
      where assignment."CRMAccountOffice_AccountID" = profile."CRMAccount_ID"
    ) offices on true
    left join lateral (
      select coalesce(jsonb_agg(jsonb_build_object(
        'addressId', address."OrgAdd_ID", 'name', address."Org_NameOverride", 'line1', address."OrgAdd_Line1",
        'line2', address."OrgAdd_Line2", 'countyState', address."OrgAdd_CountyState",
        'email', address."OrgAdd_MainEmail", 'phone', address."OrgAdd_MainPhone",
        'townCity', address."OrgAdd_TownCity", 'postcode', address."OrgAdd_PostZipCode",
        'postZipCode', address."OrgAdd_PostZipCode", 'updatedAt', address."OrgAdd_UpdatedAt",
        'countryCode', address."OrgAdd_Country", 'unlocode', address."OrgAdd_UNLOCODE",
        'timeZone', address."OrgAdd_TimeZone", 'capabilities', capabilities.values,
        'weeklyHours', hours.values, 'upcomingOverrideCount', overrides.value,
        'openingOverrides', overrides.details
      ) order by address."Org_NameOverride", address."OrgAdd_TownCity"), '[]'::jsonb) values,
      string_agg(concat_ws(' ', address."Org_NameOverride", address."OrgAdd_Line1", address."OrgAdd_TownCity", address."OrgAdd_PostZipCode", address."OrgAdd_Country", address."OrgAdd_UNLOCODE"), ' ') search_text
      from public."Org_Addresses" address
      left join lateral (
        select coalesce(jsonb_agg(jsonb_build_object(
          'code', type."sys_AddressType_Code", 'isDefault', link."OrgAddType_IsDefault"
        ) order by type."sys_AddressType_SortOrder"), '[]'::jsonb) values
        from public."Org_AddressTypes" link
        join public."sys_AddressTypes" type on type."sys_AddressType_ID" = link."OrgAddType_Type"
        where link."OrgAdd_ID" = address."OrgAdd_ID"
      ) capabilities on true
      left join lateral (
        select coalesce(jsonb_agg(jsonb_build_object(
          'dayOfWeek', hour."OrgAddHours_DayOfWeek", 'opensAt', hour."OrgAddHours_OpensAt", 'closesAt', hour."OrgAddHours_ClosesAt",
          'sortOrder', hour."OrgAddHours_SortOrder"
        ) order by hour."OrgAddHours_DayOfWeek", hour."OrgAddHours_OpensAt"), '[]'::jsonb) values
        from public."Org_AddressOpeningHours" hour where hour."OrgAddHours_OrgAddID" = address."OrgAdd_ID"
      ) hours on true
      left join lateral (
        select count(*) filter (where override."OrgAddOverride_Date" >= current_date)::integer value,
          coalesce(jsonb_agg(jsonb_build_object('date', override."OrgAddOverride_Date",
            'isClosed', override."OrgAddOverride_IsClosed", 'opensAt', override."OrgAddOverride_OpensAt",
            'closesAt', override."OrgAddOverride_ClosesAt", 'note', override."OrgAddOverride_Note")
            order by override."OrgAddOverride_Date", override."OrgAddOverride_OpensAt"), '[]'::jsonb) details
        from public."Org_AddressOpeningOverrides" override
        where override."OrgAddOverride_OrgAddID" = address."OrgAdd_ID"
      ) overrides on true
      where address."Org_ID" = organisation."Org_id" and address."OrgAdd_IsActive"
    ) addresses on true
    left join lateral (
      select coalesce(jsonb_agg(jsonb_build_object(
        'contactId', contact."OrgContact_ID",
        'recordId',contact."OrgContact_ID",'sourceTable','Org_Contacts',
        'organisationId',organisation."Org_id",'organisationName',organisation."Org_Name",
        'editVersion',(select p."CRMContact_EditVersion" from public."CRM_ContactProfiles" p where p."CRMContact_OrgContactID"=contact."OrgContact_ID" order by p."CRMContact_ID" limit 1),
        'role',(select p."CRMContact_RoleCode" from public."CRM_ContactProfiles" p where p."CRMContact_OrgContactID"=contact."OrgContact_ID" order by p."CRMContact_ID" limit 1),
        'jobTitle',(select p."CRMContact_MetadataJSON"->>'jobTitle' from public."CRM_ContactProfiles" p where p."CRMContact_OrgContactID"=contact."OrgContact_ID" order by p."CRMContact_ID" limit 1),
        'department',(select p."CRMContact_MetadataJSON"->>'department' from public."CRM_ContactProfiles" p where p."CRMContact_OrgContactID"=contact."OrgContact_ID" order by p."CRMContact_ID" limit 1),

        'name', nullif(btrim(concat_ws(' ', contact."OrgContact_FirstName", contact."OrgContact_LastName")), ''),
        'activeEmails', emails.values,
        'employmentHistory', employment.values
      ) order by contact."OrgContact_LastName", contact."OrgContact_FirstName"), '[]'::jsonb) values,
      string_agg(concat_ws(' ', contact."OrgContact_FirstName", contact."OrgContact_LastName", emails.search_text), ' ') search_text
      from public."Org_Contacts" contact
      left join lateral (
        select coalesce(jsonb_agg(email."OrgContactEmail_Email" order by email."OrgContactEmail_IsPrimary" desc), '[]'::jsonb) values,
          string_agg(email."OrgContactEmail_Email", ' ') search_text
        from public."OrgContact_Emails" email
        where email."OrgContact_ID" = contact."OrgContact_ID" and email."OrgContactEmail_IsActive"
      ) emails on true
      left join lateral (
        select coalesce(jsonb_agg(jsonb_build_object(
          'organisationId', assignment."CRMContactOrg_OrgID", 'organisationName', employer."Org_Name",
          'jobTitle', assignment."CRMContactOrg_JobTitle", 'department', assignment."CRMContactOrg_Department",
          'role', assignment."CRMContactOrg_RoleCode", 'startedAt', assignment."CRMContactOrg_StartedAt",
          'endedAt', assignment."CRMContactOrg_EndedAt", 'isCurrent', assignment."CRMContactOrg_IsCurrent"
        ) order by assignment."CRMContactOrg_StartedAt" desc), '[]'::jsonb) values
        from public."CRM_ContactOrganisationAssignments" assignment
        join public."Org_Master" employer on employer."Org_id" = assignment."CRMContactOrg_OrgID"
        where assignment."CRMContactOrg_ContactID" = contact."OrgContact_ID"
      ) employment on true
      where contact."Org_ID" = organisation."Org_id"
    ) contacts on true
    left join lateral (
      select coalesce(jsonb_agg(jsonb_build_object(
        'ruleId', rule."OrgRelatedDefault_ID", 'partyRoleCode', rule."OrgRelatedDefault_PartyRoleCode",
        'destinationCountryCode', rule."OrgRelatedDefault_DestinationCountryCode",
        'destinationUnlocode', rule."OrgRelatedDefault_DestinationUNLOCODE",
        'destinationPostcode', rule."OrgRelatedDefault_DestinationPostcode",
        'targetOrganisationId', target."Org_id", 'targetOrganisationName', target."Org_Name",
        'targetAddressId', rule."OrgRelatedDefault_TargetAddressID", 'targetContactId', rule."OrgRelatedDefault_TargetContactID",
        'priority', rule."OrgRelatedDefault_Priority"
      ) order by rule."OrgRelatedDefault_PartyRoleCode", rule."OrgRelatedDefault_Priority"), '[]'::jsonb) values
      from public."Org_RelatedPartyDefaults" rule
      join public."Org_Master" target on target."Org_id" = rule."OrgRelatedDefault_TargetOrgID"
      where rule."OrgRelatedDefault_SourceOrgID" = organisation."Org_id" and rule."OrgRelatedDefault_IsActive"
    ) related_defaults on true
    cross join lateral public._multideck_dexter_search_evidence(
      p_search,
      jsonb_build_object(
        'name', organisation."Org_Name", 'accountCode', organisation."Org_AccCode",
        'types', types.values, 'offices', offices.search_text,
        'addresses', addresses.search_text, 'contacts', contacts.search_text
      )
    ) evidence(value)
    where public._multideck_dexter_has_permission(
      (select app_user."User_ID" from public."cmp_Users" app_user
       where app_user."Auth_User_ID" = auth.uid() and app_user."Company_ID" = p_company_id limit 1),
      'Customers.Read'
    )
      and (evidence.value ->> 'matched')::boolean
    order by search_rank desc, organisation."Org_Name"
    limit greatest(1, least(coalesce(p_take, 10), 25))
  ) item;
$$;


ALTER FUNCTION "public"."multideck_dexter_domain_customers"("p_company_id" "uuid", "p_search" "text", "p_take" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_domain_customs_assessments"("p_company_id" "uuid", "p_search" "text", "p_take" integer) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(jsonb_agg(x.payload order by x.created_at desc,x.id desc),'[]'::jsonb) from (
    select a.id,a.created_at,jsonb_build_object('recordId',a.id,'declarationId',a.declaration_id,
      'sourceId',a.source_id,'calculationId',a.calculation_id,'createdAt',a.created_at,
      'adapterVersion',a.adapter_version,'evidence',a.evidence,'direction','import',
      'sourceType',case when d."CUST_JobID" is null then 'standalone' else 'job_related' end,
      'submissionFieldsChanged',false) payload
    from public."Customs_AssessmentComparisons" a join public."Customs_Declarations" d on d."CUST_id"=a.declaration_id
    where a.declaration_id::text=btrim(coalesce(p_search,''))
      and public.customs_declaration_current_user_authorised(a.declaration_id,false)
      and exists(select 1 from public."cmp_Users" actor where actor."Auth_User_ID"=auth.uid() and actor."Company_ID"=p_company_id)
    order by a.created_at desc,a.id desc limit greatest(1,least(coalesce(p_take,10),25))
  ) x;
$$;


ALTER FUNCTION "public"."multideck_dexter_domain_customs_assessments"("p_company_id" "uuid", "p_search" "text", "p_take" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_domain_customs_calculations"("p_company_id" "uuid", "p_search" "text", "p_take" integer) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(jsonb_agg(entry.payload order by entry.created_at desc, entry.id desc), '[]'::jsonb)
  from (
    select audit.id, audit.created_at, jsonb_build_object(
      'recordId', audit.id, 'declarationId', audit.declaration_id,
      'sourceType', case when declaration."CUST_JobID" is null then 'standalone' else 'job_related' end,
      'direction', 'import', 'kind', audit.kind, 'createdAt', audit.created_at,
      'actorAuthId', audit.actor_auth_id, 'parentCalculationId', audit.parent_id,
      'outOfDate', audit.draft_snapshot is distinct from declaration."CUST_GenericPayloadJSON",
      'result', audit.evidence->'result', 'itemId', audit.evidence->'itemId',
      'original', audit.evidence->'original', 'replacement', audit.evidence->'replacement',
      'reason', audit.evidence->'reason', 'sourceKind', audit.evidence->'sourceKind',
      'submissionFieldsChanged', false
    ) as payload
    from public."Customs_CalculationAudit" audit
    join public."Customs_Declarations" declaration on declaration."CUST_id" = audit.declaration_id
    where audit.declaration_id::text = btrim(coalesce(p_search, ''))
      and public.customs_declaration_current_user_authorised(audit.declaration_id, false)
      and exists (select 1 from public."cmp_Users" actor
        where actor."Auth_User_ID" = auth.uid() and actor."Company_ID" = p_company_id)
    order by audit.created_at desc, audit.id desc
    limit greatest(1, least(coalesce(p_take, 10), 25))
  ) entry;
$$;


ALTER FUNCTION "public"."multideck_dexter_domain_customs_calculations"("p_company_id" "uuid", "p_search" "text", "p_take" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_domain_customs_declarations"("p_company_id" "uuid", "p_search" "text", "p_take" integer) RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select coalesce(jsonb_agg(row_data order by search_rank desc, sort_updated desc), '[]'::jsonb)
  from (
    select
      jsonb_strip_nulls(jsonb_build_object(
        'recordId', declaration."CUST_id",
        'sourceType', case when declaration."CUST_JobID" is null then 'standalone' else 'job_related' end,
        'jobId', declaration."CUST_JobID",
        'reference', coalesce(declaration."CUST_LocalReferenceNumber", declaration."CUST_id"::text),
        'traderReference', declaration."CUST_TraderReference",
        'ucr', declaration."CUST_UCR",
        'status', declaration."CUST_Status",
        'direction', declaration."CUST_Direction",
        'declarationKind', declaration."CUST_DeclarationKind",
        'jurisdiction', declaration."CUST_JurisdictionCode",
        'assignedUserId', declaration."CUST_AssignedUserID",
        'assignedUserName', coalesce(nullif(btrim(concat_ws(' ', assigned_user."User_Firstname", assigned_user."User_Lastname")), ''), assigned_user."User_Email"),
        'assignedUserEmail', assigned_user."User_Email",
        'destinationCountry', declaration."CUST_CountryOfDestinationCodeSnapshot",
        'invoiceAmount', declaration."CUST_InvoiceAmount",
        'currency', declaration."CUST_InvoiceCurrencyCodeSnapshot",
        'itemCount', coalesce(items.item_count, 0),
        'customsReference', declaration."CUST_CustomsReferenceNumber",
        'mrn', coalesce(latest_submission."ICUSS_MRN", declaration."CUST_MasterReferenceNumber"),
        'iCustomsStatus', declaration."CUST_iCustomsStatusSnapshot",
        'submissionStatus', latest_submission."ICUSS_Status",
        'submissionErrorCode', latest_submission."ICUSS_ErrorCode",
        'submissionErrorMessage', latest_submission."ICUSS_ErrorMessage",
        'submittedAt', latest_submission."ICUSS_SubmittedAt",
        'acknowledgedAt', latest_submission."ICUSS_AcknowledgedAt",
        'completedAt', latest_submission."ICUSS_CompletedAt",
        'documentAvailable', declaration."CUST_DeclarationDocumentID" is not null,
        'documentId', declaration."CUST_DeclarationDocumentID",
        'documentFileName', declaration."CUST_DeclarationDocumentFileName",
        'documentReceivedAt', declaration."CUST_DeclarationDocumentReceivedAt",
        'documentMimeType', declaration."CUST_DeclarationDocumentMimeType",
        'createdAt', declaration."CUST_CreatedAt",
        'updatedAt', declaration."CUST_UpdatedAt",
        'searchEvidence', evidence.value - 'matched'
      )) as row_data,
      coalesce((evidence.value->>'confidence')::numeric, 0) as search_rank,
      declaration."CUST_UpdatedAt" as sort_updated
    from public."Customs_Declarations" declaration
    left join public."cmp_Users" assigned_user
      on assigned_user."User_ID" = declaration."CUST_AssignedUserID"
    left join lateral (
      select count(*)::integer as item_count from public."Customs_Items" item
      where item."CUSTI_CustomsID" = declaration."CUST_id"
    ) items on true
    left join lateral (
      select submission.* from public."ICUS_Submissions" submission
      where submission."ICUSS_CustomsID" = declaration."CUST_id"
      order by submission."ICUSS_CreatedAt" desc, submission."ICUSS_id" desc limit 1
    ) latest_submission on true
    cross join lateral public._multideck_dexter_search_evidence(
      p_search,
      jsonb_build_object(
        'recordId', declaration."CUST_id",
        'reference', declaration."CUST_LocalReferenceNumber",
        'traderReference', declaration."CUST_TraderReference",
        'ucr', declaration."CUST_UCR",
        'status', declaration."CUST_Status",
        'direction', declaration."CUST_Direction",
        'assignedUserName', coalesce(nullif(btrim(concat_ws(' ', assigned_user."User_Firstname", assigned_user."User_Lastname")), ''), assigned_user."User_Email"),
        'assignedUserEmail', assigned_user."User_Email",
        'customsReference', declaration."CUST_CustomsReferenceNumber",
        'mrn', coalesce(latest_submission."ICUSS_MRN", declaration."CUST_MasterReferenceNumber")
      ),
      array['recordId', 'reference', 'traderReference', 'ucr', 'assignedUserEmail', 'customsReference', 'mrn']::text[]
    ) evidence(value)
    where not declaration."CUST_IsDeleted"
      and booking_api.customs_access(auth.uid(), declaration."CUST_id", false)
      and exists (
        select 1 from public."cmp_Users" actor
        where actor."Auth_User_ID" = auth.uid()
          and actor."Company_ID" = p_company_id
          and coalesce(actor."User_AccessStatus", 'active') = 'active'
      )
      and (evidence.value->>'matched')::boolean
    order by search_rank desc, declaration."CUST_UpdatedAt" desc
    limit greatest(1, least(coalesce(p_take, 10), 25))
  ) declarations;
$$;


