CREATE OR REPLACE FUNCTION "public"."multideck_dexter_domain_drive"("p_company_id" "uuid", "p_search" "text", "p_take" integer) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select coalesce(jsonb_agg(row_data order by sort_updated desc), '[]'::jsonb)
  from (
    select
      jsonb_build_object(
        'recordId', file."DriveFile_ID",
        'name', file."DriveFile_Name",
        'folder', coalesce(folder."DriveFolder_Name", 'Drive root'),
        'folderId', file."DriveFile_FolderID",
        'mimeType', file."DriveFile_MimeType",
        'sizeBytes', file."DriveFile_SizeBytes",
        'updatedAt', file."DriveFile_UpdatedAt",
        'addedBy', nullif(btrim(concat_ws(' ', owner."User_Firstname", owner."User_Lastname")), '')
      ) as row_data,
      file."DriveFile_UpdatedAt" as sort_updated
    from public."CRM_DriveFiles" as file
    left join public."CRM_DriveFolders" as folder
      on folder."DriveFolder_ID" = file."DriveFile_FolderID"
    left join public."cmp_Users" as owner
      on owner."User_ID" = file."DriveFile_CreatedBy"
    where file."Company_ID" = p_company_id
      and (
        nullif(btrim(p_search), '') is null
        or concat_ws(' ', file."DriveFile_Name", folder."DriveFolder_Name", file."DriveFile_MimeType")
             ilike '%' || btrim(p_search) || '%'
      )
    order by file."DriveFile_UpdatedAt" desc
    limit greatest(1, least(coalesce(p_take, 10), 25))
  ) rows;
$$;


ALTER FUNCTION "public"."multideck_dexter_domain_drive"("p_company_id" "uuid", "p_search" "text", "p_take" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_domain_email_signatures"("p_company_id" "uuid", "p_search" "text", "p_take" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare actor record; result jsonb; manager boolean;
begin
 select * into actor from public._multideck_dexter_context();
 if actor.company_id<>p_company_id then raise exception 'Signature workspace access denied' using errcode='42501';end if;
 manager:=public._multideck_dexter_has_permission(actor.user_id,'Email.Signatures.Manage');
 select coalesce(jsonb_agg(item),'[]') into result from (
  select jsonb_build_object('recordId',s.id,'name',s.name,'personal',s.owner_user_id is not null,'publishedRevision',s.published_revision,
   'assignments',case when manager then s.published_assignments else '[]'::jsonb end,'updatedAt',s.updated_at,
   'route',case when manager and s.owner_user_id is null then '/admin/email-signatures' else '/inbox/signatures' end,
   '_citation',jsonb_build_object('title',s.name,'url','/inbox/signatures','description','Saved Multideck signature; provider settings are separate')) item
  from public.email_signature_templates s where public.email_signature_available(actor.user_id,p_company_id,s.id)
   and (nullif(btrim(p_search),'') is null or s.name ilike '%'||btrim(p_search)||'%' or s.id::text=p_search)
  order by s.name limit greatest(1,least(coalesce(p_take,10),25))
 ) records;
 return result;
end $$;


ALTER FUNCTION "public"."multideck_dexter_domain_email_signatures"("p_company_id" "uuid", "p_search" "text", "p_take" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_domain_external_events"("p_company_id" "uuid", "p_search" "text", "p_take" integer) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
  with search_window as materialized (select * from public._dexter_calendar_window(p_search))
  select coalesce(jsonb_agg(row.data order by row.start_at), '[]'::jsonb)
  from (
    select event."CALProviderEvent_StartAt" as start_at,
      jsonb_strip_nulls(jsonb_build_object(
        'recordId', event."CALProviderEvent_ID", 'recordType', 'external_event',
        'title', case when event."CALProviderEvent_IsPrivate" then 'Busy' else coalesce(event."CALProviderEvent_Title",'Busy') end,
        'startAt', event."CALProviderEvent_StartAt", 'endAt', event."CALProviderEvent_EndAt",
        'source', connection."CALConnection_ProviderCode", 'private', event."CALProviderEvent_IsPrivate",
        'joinUrl', event."CALProviderEvent_JoinURL",
        'canEdit', connection."CALConnection_StatusCode" in ('connected','syncing')
          and connection."CALConnection_ProviderCode" in ('google','microsoft')
          and event."CALProviderEvent_IsOrganiser",
        'canRespond', connection."CALConnection_StatusCode" in ('connected','syncing')
          and connection."CALConnection_ProviderCode" in ('google','microsoft')
          and not event."CALProviderEvent_IsOrganiser"
          and event."CALProviderEvent_ResponseCode" is not null,
        'response', event."CALProviderEvent_ResponseCode",
        'route', '/calendar?date=' || to_char(event."CALProviderEvent_StartAt" at time zone 'UTC','YYYY-MM-DD')
      )) as data
    from public."CAL_ProviderEvents" event
    join public."CAL_ProviderConnections" connection on connection."CALConnection_ID"=event."CALProviderEvent_ConnectionID"
      and connection."CALConnection_CompanyID"=event."CALProviderEvent_CompanyID"
      and connection."CALConnection_UserID"=event."CALProviderEvent_OwnerUserID"
    cross join search_window bounds
    where event."CALProviderEvent_CompanyID" = p_company_id
      and event."CALProviderEvent_OwnerUserID" = (
        select profile."User_ID"
        from public."cmp_Users" profile
        where profile."Company_ID" = p_company_id
          and profile."Auth_User_ID" = auth.uid()
        limit 1
      )
      and event."CALProviderEvent_MeetingID" is null
      and event."CALProviderEvent_IsCancelled" = false
      and event."CALProviderEvent_EndAt" > now() - interval '1 day'
      and (case when bounds.starts_at is not null then event."CALProviderEvent_StartAt"<bounds.ends_at and event."CALProviderEvent_EndAt">bounds.starts_at
       else nullif(btrim(coalesce(p_search,'')),'') is null or event."CALProviderEvent_ID"::text=btrim(p_search) or (event."CALProviderEvent_IsPrivate" = false and event."CALProviderEvent_Title" ilike '%'||btrim(p_search)||'%') end)
    order by event."CALProviderEvent_StartAt"
    limit greatest(1, least(coalesce(p_take,10),25))
  ) row;
$$;


ALTER FUNCTION "public"."multideck_dexter_domain_external_events"("p_company_id" "uuid", "p_search" "text", "p_take" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_domain_finance"("p_company_id" "uuid", "p_search" "text", "p_take" integer) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  with entity_totals as (
    select entity."LegalEntity_ID" entity_id,entity."LegalEntity_Name" entity_name,entity."LegalEntity_CountryCode" country_code,
      upper(entity."LegalEntity_BaseCurrencyCodeSnapshot") currency,
      coalesce(sum(case when nominal."FINNom_ReportCategoryCode" in ('income','direct_cost','expense','finance')
        then line."FINPostLine_CreditAmount"-line."FINPostLine_DebitAmount" else 0 end),0) profit_loss,
      coalesce(sum(case when nominal."FINNom_ReportCategoryCode"='asset' then line."FINPostLine_DebitAmount"-line."FINPostLine_CreditAmount" else 0 end),0) assets,
      coalesce(sum(case when nominal."FINNom_ReportCategoryCode"='liability' then line."FINPostLine_CreditAmount"-line."FINPostLine_DebitAmount" else 0 end),0) liabilities,
      coalesce(sum(case when nominal."FINNom_ReportCategoryCode"='equity' then line."FINPostLine_CreditAmount"-line."FINPostLine_DebitAmount" else 0 end),0) equity,
      max(batch."FINPostBatch_PostedAt") updated_at
    from public."cmp_LegalEntities" entity
    left join public."FIN_PostingBatches" batch on batch."FINPostBatch_LegalEntityID"=entity."LegalEntity_ID" and batch."FINPostBatch_StatusCode"='posted'
    left join public."FIN_PostingLines" line on line."FINPostLine_BatchID"=batch."FINPostBatch_ID"
    left join public."FIN_NominalAccounts" nominal on nominal."FINNom_ID"=line."FINPostLine_NominalAccountID"
    where entity."Company_ID"=p_company_id and entity."LegalEntity_IsActive"
    group by entity."LegalEntity_ID",entity."LegalEntity_Name",entity."LegalEntity_CountryCode",entity."LegalEntity_BaseCurrencyCodeSnapshot"
  ), records as (
    select value,coalesce((value->'evidence'->>'updatedAt')::timestamptz,'2000-01-01'::timestamptz) updated_at
    from jsonb_array_elements(public._multideck_dexter_domain_finance_before_native_global(p_company_id,p_search,p_take)) value
    union all
    select jsonb_build_object(
      'recordId',totals.entity_id,'recordKind','native_financial_summary','legalEntityId',totals.entity_id,'legalEntity',totals.entity_name,
      'currency',totals.currency,'profitOrLoss',round(totals.profit_loss,4),'assets',round(totals.assets,4),'liabilities',round(totals.liabilities,4),
      'equity',round(totals.equity,4),'currentEarnings',round(totals.profit_loss,4),'balanceDifference',round(totals.assets-totals.liabilities-totals.equity-totals.profit_loss,4),
      'reportRoute','/finance/reports','evidence',jsonb_build_object('sourceTable','FIN_PostingLines','legalEntityId',totals.entity_id,'updatedAt',coalesce(totals.updated_at,now()))
    ),coalesce(totals.updated_at,'2000-01-01'::timestamptz)
    from entity_totals totals
    where nullif(btrim(p_search),'') is null or concat_ws(' ',totals.entity_name,'profit loss balance sheet trial balance native ledger financial report') ilike '%'||btrim(p_search)||'%'
    union all
    select jsonb_build_object(
      'recordId',obligation."FINCompliance_ID",'recordKind','compliance_obligation','legalEntityId',entity."LegalEntity_ID",'legalEntity',entity."LegalEntity_Name",
      'country',pack."FINLocPack_CountryCode",'code',obligation."FINCompliance_Code",'name',obligation."FINCompliance_Name",'obligationType',obligation."FINCompliance_ObligationTypeCode",
      'authority',obligation."FINCompliance_AuthorityName",'filingChannel',obligation."FINCompliance_FilingChannelCode",'frequency',obligation."FINCompliance_FrequencyCode",
      'readinessStatus',obligation."FINCompliance_ReadinessStatusCode",'sourceUrl',obligation."FINCompliance_SourceURL",'payrollIncluded',false,
      'evidence',jsonb_build_object('sourceTable','FIN_ComplianceObligations','sourceId',obligation."FINCompliance_ID",'legalEntityId',entity."LegalEntity_ID",'updatedAt',obligation."FINCompliance_UpdatedAt")
    ),obligation."FINCompliance_UpdatedAt"
    from public."FIN_ComplianceObligations" obligation
    join public."FIN_LocalisationPacks" pack on pack."FINLocPack_ID"=obligation."FINCompliance_PackID"
    join public."cmp_LegalEntities" entity on entity."Company_ID"=p_company_id and entity."LegalEntity_CountryCode"=pack."FINLocPack_CountryCode" and entity."LegalEntity_IsActive"
    where obligation."FINCompliance_IsActive" and (
      nullif(btrim(p_search),'') is null or concat_ws(' ',obligation."FINCompliance_Code",obligation."FINCompliance_Name",obligation."FINCompliance_ObligationTypeCode",obligation."FINCompliance_AuthorityName",pack."FINLocPack_CountryCode") ilike '%'||btrim(p_search)||'%'
    )
  )
  select coalesce(jsonb_agg(value order by updated_at desc),'[]'::jsonb)
  from (select * from records order by updated_at desc limit greatest(1,least(coalesce(p_take,10),25))) limited
$$;


ALTER FUNCTION "public"."multideck_dexter_domain_finance"("p_company_id" "uuid", "p_search" "text", "p_take" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_domain_inbox_suggestions"("p_company_id" "uuid", "p_search" "text", "p_take" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare v_context record; v_result jsonb; v_search text := nullif(btrim(p_search),'');
begin
  select * into v_context from public._multideck_dexter_context();
  if v_context.company_id <> p_company_id then
    raise exception 'Those Inbox suggestions are outside this workspace.' using errcode = '42501';
  end if;
  select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
    'recordId', suggestion."AIInboxSuggestion_ID", 'recordType', 'inbox_suggestion',
    'documentType', suggestion."AIInboxSuggestion_DocumentTypeCode",
    'status', suggestion."AIInboxSuggestion_StatusCode", 'targetId', suggestion."AIInboxSuggestion_TargetID",
    'targetLabel', suggestion."AIInboxSuggestion_TargetLabel", 'matchConfidence', suggestion."AIInboxSuggestion_MatchConfidence",
    'summary', suggestion."AIInboxSuggestion_Summary", 'sourceFileName', suggestion."AIInboxSuggestion_SourceFileName",
    'createdAt', suggestion."AIInboxSuggestion_CreatedAt", 'appliedAt', suggestion."AIInboxSuggestion_AppliedAt"
  )) order by suggestion."AIInboxSuggestion_CreatedAt" desc), '[]'::jsonb) into v_result
  from (
    select item.* from public."AI_InboxSuggestedUpdates" item
    where item."AIInboxSuggestion_CompanyID" = p_company_id
      and item."AIInboxSuggestion_OwnerUserID" = v_context.user_id
      and (v_search is null or concat_ws(' ', item."AIInboxSuggestion_TargetLabel", item."AIInboxSuggestion_Summary", item."AIInboxSuggestion_SourceFileName") ilike '%' || v_search || '%')
    order by item."AIInboxSuggestion_CreatedAt" desc
    limit greatest(1, least(coalesce(p_take,10),25))
  ) suggestion;
  return v_result;
end;
$$;


ALTER FUNCTION "public"."multideck_dexter_domain_inbox_suggestions"("p_company_id" "uuid", "p_search" "text", "p_take" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_domain_leads"("p_company_id" "uuid", "p_search" "text", "p_take" integer) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $_$
  select coalesce(jsonb_agg(row_data order by search_rank desc, sort_due nulls last, sort_created desc), '[]'::jsonb)
  from (
    select jsonb_build_object(
      'recordId', lead."CRMLead_ID", 'companyName', lead."CRMLead_CompanyName", 'contactName', lead."CRMLead_PersonName",
      'contactEmail', lead."CRMLead_Email", 'status', lead."CRMLead_StatusCode", 'rating', lead."CRMLead_RatingCode",
      'source', lead."CRMLead_SourceCode", 'ownerId', lead."CRMLead_OwnerUserID",
      'owner', nullif(btrim(concat_ws(' ', owner."User_Firstname", owner."User_Lastname")), ''),
      'address', public._multideck_crm_lead_native_address(lead."CRMLead_ID"),
      'area', address.area_label, 'mode', lead."CRMLead_ModeCode", 'direction', lead."CRMLead_DirectionCode",
      'tradeLane', lead."CRMLead_TradeLane", 'serviceInterest', lead."CRMLead_ServiceInterest",
      'estimatedValue', lead."CRMLead_EstimatedValueAmount", 'currency', lead."CRMLead_EstimatedValueCurrencyCode",
      'urgency', lead."CRMLead_UrgencyCode", 'score', lead."CRMLead_Score",
      'conversionProbability', lead."CRMLead_AIProbabilityToConvert", 'nextActionDueAt', lead."CRMLead_NextActionDueAt",
      'lastInteractionAt', lead."CRMLead_LastInteractionAt",
      'contactAgeDays', case when lead."CRMLead_LastInteractionAt" is null then null else floor(extract(epoch from (now() - lead."CRMLead_LastInteractionAt")) / 86400)::integer end,
      'pendingTransfer', pending_transfer.value,
      'searchEvidence', evidence.value - 'matched'
    ) row_data,
    coalesce((evidence.value ->> 'confidence')::numeric, 0) search_rank,
    lead."CRMLead_NextActionDueAt" sort_due,
    lead."CRMLead_CreatedAt" sort_created
    from public."CRM_Leads" lead
    join public."cmp_Users" owner on owner."User_ID" = lead."CRMLead_OwnerUserID"
    left join lateral (
      select coalesce(
        nullif(concat_ws(' · ', nullif(btrim(lead."CRMLead_TownCity"), ''), nullif(btrim(lead."CRMLead_CountyState"), ''),
          nullif(split_part(btrim(lead."CRMLead_PostZipCode"), ' ', 1), ''), nullif(upper(btrim(lead."CRMLead_CountryCode")), '')), ''),
        organisation.area_label
      ) area_label
      from (select 1) seed
      left join lateral (
        select nullif(concat_ws(' · ', nullif(btrim(a."OrgAdd_TownCity"), ''), nullif(btrim(a."OrgAdd_CountyState"), ''),
          nullif(split_part(btrim(a."OrgAdd_PostZipCode"), ' ', 1), ''), nullif(upper(btrim(a."OrgAdd_Country")), '')), '') area_label
        from public."Org_Addresses" a
        where a."Org_ID" = lead."CRMLead_OrgID"
        order by a."OrgAdd_ID" limit 1
      ) organisation on true
    ) address on true
    left join lateral (
      select jsonb_build_object('id', request."CRMLeadTransfer_ID", 'status', request."CRMLeadTransfer_Status",
        'fromUserId', request."CRMLeadTransfer_FromUserID", 'toUserId', request."CRMLeadTransfer_ToUserID", 'requestedAt', request."CRMLeadTransfer_RequestedAt") value
      from public."CRM_LeadTransferRequests" request
      where request."CRMLeadTransfer_LeadID" = lead."CRMLead_ID" and request."CRMLeadTransfer_Status" = 'pending'
      order by request."CRMLeadTransfer_RequestedAt" desc limit 1
    ) pending_transfer on true
    cross join lateral (select case
      when btrim(coalesce(p_search, '')) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
        jsonb_build_object('matched', lead."CRMLead_ID"::text = lower(btrim(p_search)),
          'quality', 'exact_identifier', 'matchedField', 'recordId',
          'matchedValue', lead."CRMLead_ID", 'confidence', 1)
      else public._multideck_dexter_search_evidence(
      p_search,
      jsonb_build_object(
        'companyName', lead."CRMLead_CompanyName", 'contactName', lead."CRMLead_PersonName",
        'contactEmail', lead."CRMLead_Email", 'status', lead."CRMLead_StatusCode", 'rating', lead."CRMLead_RatingCode",
        'source', lead."CRMLead_SourceCode", 'owner', nullif(btrim(concat_ws(' ', owner."User_Firstname", owner."User_Lastname")), ''),
        'area', address.area_label, 'mode', lead."CRMLead_ModeCode", 'direction', lead."CRMLead_DirectionCode",
        'tradeLane', lead."CRMLead_TradeLane", 'serviceInterest', lead."CRMLead_ServiceInterest", 'urgency', lead."CRMLead_UrgencyCode"
      ),
      array['contactEmail']::text[]
    ) end) evidence(value)
    where not lead."CRMLead_IsDeleted"
      and lower(coalesce(lead."CRMLead_MetadataJSON" ->> 'isDemo', 'false')) <> 'true'
      and owner."Company_ID" = p_company_id
      and owner."Auth_User_ID" = auth.uid()
      and (evidence.value ->> 'matched')::boolean
    order by search_rank desc, lead."CRMLead_NextActionDueAt" nulls last, lead."CRMLead_CreatedAt" desc
    limit greatest(1, least(coalesce(p_take, 10), 25))
  ) rows;
$_$;


ALTER FUNCTION "public"."multideck_dexter_domain_leads"("p_company_id" "uuid", "p_search" "text", "p_take" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_domain_lifecycle_note_targets"("p_company_id" "uuid", "p_search" "text", "p_take" integer) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
  with actor as (
    select workspace_user."User_ID"
    from public."cmp_Users" workspace_user
    where workspace_user."Auth_User_ID" = auth.uid()
      and workspace_user."Company_ID" = p_company_id
      and workspace_user."User_AccessStatus" = 'active'
    limit 1
  ), targets as (
    select
      'user'::text as target_type,
      workspace_user."User_ID" as target_id,
      coalesce(
        nullif(btrim(concat_ws(' ', workspace_user."User_Firstname", workspace_user."User_Lastname")), ''),
        workspace_user."User_Email"
      ) as label,
      nullif(btrim(workspace_user."User_JobTitle"), '') as detail,
      0 as target_order
    from public."cmp_Users" workspace_user
    where exists (select 1 from actor)
      and workspace_user."Company_ID" = p_company_id
      and workspace_user."User_AccessStatus" = 'active'
      and workspace_user."Auth_User_ID" is not null
    union all
    select
      'department'::text,
      department."Department_ID",
      department."Department_Name",
      'Department'::text,
      1
    from public."cmp_Departments" department
    where exists (select 1 from actor)
      and department."Company_ID" = p_company_id
      and department."Department_IsActive"
      and exists (
        select 1
        from public."cmp_Users_Departments" membership
        join public."cmp_Users" member on member."User_ID" = membership."User_ID"
        where membership."Department_ID" = department."Department_ID"
          and member."Company_ID" = p_company_id
          and member."User_AccessStatus" = 'active'
          and member."Auth_User_ID" is not null
      )
  ), filtered as (
    select *
    from targets
    where nullif(left(btrim(coalesce(p_search, '')), 160), '') is null
      or concat_ws(' ', label, detail) ilike '%' || left(btrim(p_search), 160) || '%'
    order by target_order, lower(label), target_id
    limit greatest(1, least(coalesce(p_take, 10), 25))
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'recordId', target_id,
    'recordKind', 'mention_target',
    'targetType', target_type,
    'label', label,
    'detail', detail
  ) order by target_order, lower(label), target_id), '[]'::jsonb)
  from filtered;
$$;


ALTER FUNCTION "public"."multideck_dexter_domain_lifecycle_note_targets"("p_company_id" "uuid", "p_search" "text", "p_take" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_domain_lifecycle_notes"("p_company_id" "uuid", "p_search" "text", "p_take" integer) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth', 'booking_api', 'quote_api'
    AS $$
  with rows as (
    select
      note."LifecycleNote_CreatedAt" as created_at,
      jsonb_strip_nulls(jsonb_build_object(
        'recordId', case when note."LifecycleNote_SubjectType" = 'company' then note."LifecycleNote_SubjectID"
          when note."LifecycleNote_SubjectType" = 'quote' and quote_api.has_permission(auth.uid(), 'Quotes.Read')
            then note."LifecycleNote_SubjectID"
          when job."Job_ID" is not null and booking_api.has_permission(auth.uid(), 'Bookings.Read')
            then job."Job_ID"
          else customs_context.primary_id
        end,
        'noteId', note."LifecycleNote_ID",
        'subjectType', case when note."LifecycleNote_SubjectType" = 'company' then 'company'
          when note."LifecycleNote_SubjectType" = 'quote' and quote_api.has_permission(auth.uid(), 'Quotes.Read') then 'quote'
          when job."Job_ID" is not null and booking_api.has_permission(auth.uid(), 'Bookings.Read') then 'booking'
          else 'customs'
        end,
        'originSubjectType', note."LifecycleNote_SubjectType",
        'reference', case when note."LifecycleNote_SubjectType" = 'company' then account."Org_Name"
          when note."LifecycleNote_SubjectType" = 'quote' and quote_api.has_permission(auth.uid(), 'Quotes.Read')
            then 'Q-' || quote."CusQuoteHeader_Number"
          when job."Job_ID" is not null and booking_api.has_permission(auth.uid(), 'Bookings.Read')
            then coalesce(job."Job_BookingReference", 'MD-' || job."Job_Number")
          else customs_context.primary_reference
        end,
        'visibleOn', jsonb_strip_nulls(jsonb_build_object(
          'quote', case when note."LifecycleNote_QuoteID" is not null and quote_api.has_permission(auth.uid(), 'Quotes.Read') then jsonb_build_object(
            'id', note."LifecycleNote_QuoteID", 'reference', 'Q-' || quote."CusQuoteHeader_Number"
          ) end,
          'booking', case when job."Job_ID" is not null and booking_api.has_permission(auth.uid(), 'Bookings.Read') then jsonb_build_object(
            'id', job."Job_ID", 'reference', coalesce(job."Job_BookingReference", 'MD-' || job."Job_Number")
          ) end,
          'customs', coalesce(customs_context.records, '[]'::jsonb)
        )),
        'body', note."LifecycleNote_Body",
        'author', note."LifecycleNote_AuthorNameSnapshot",
        'mentions', coalesce(mentions.records, '[]'::jsonb),
        'mentionedUsers', coalesce(mentions.users, '[]'::jsonb),
        'mentionedDepartments', coalesce(mentions.departments, '[]'::jsonb),
        'createdAt', note."LifecycleNote_CreatedAt",
        'evidence', jsonb_build_object('sourceTable', 'OPS_LifecycleNotes', 'sourceId', note."LifecycleNote_ID")
      )) as value
    from public."OPS_LifecycleNotes" note
    left join public."Org_Master" account on note."LifecycleNote_SubjectType" = 'company' and account."Org_id" = note."LifecycleNote_SubjectID"
    left join public."CusQuote_Header" quote on quote."CusQuoteHeader_ID" = note."LifecycleNote_QuoteID"
    left join lateral (
      select candidate.*
      from public."Job_Header" candidate
      where not candidate."Job_IsDeleted"
        and (
          candidate."Job_ID" = note."LifecycleNote_JobID"
          or (
            note."LifecycleNote_SubjectType" = 'quote'
            and candidate."Job_SourceQuoteID" = note."LifecycleNote_QuoteID"
          )
        )
      order by case when candidate."Job_ID" = note."LifecycleNote_JobID" then 0 else 1 end, candidate."Job_ID"
      limit 1
    ) job on true
    left join lateral (
      select
        jsonb_agg(jsonb_build_object(
          'id', declaration."CUST_id",
          'reference', coalesce(nullif(btrim(declaration."CUST_LocalReferenceNumber"), ''), declaration."CUST_id"::text)
        ) order by declaration."CUST_CreatedAt", declaration."CUST_id") as records,
        string_agg(coalesce(declaration."CUST_LocalReferenceNumber", ''), ' ') as search_text,
        bool_or(booking_api.customs_access(auth.uid(), declaration."CUST_id", false)) as can_read,
        (array_agg(declaration."CUST_id" order by declaration."CUST_CreatedAt", declaration."CUST_id"))[1] as primary_id,
        (array_agg(coalesce(nullif(btrim(declaration."CUST_LocalReferenceNumber"), ''), declaration."CUST_id"::text)
          order by declaration."CUST_CreatedAt", declaration."CUST_id"))[1] as primary_reference
      from public."Customs_Declarations" declaration
      where not declaration."CUST_IsDeleted"
        and booking_api.customs_access(auth.uid(), declaration."CUST_id", false)
        and (
          (note."LifecycleNote_SubjectType" = 'customs' and declaration."CUST_id" = note."LifecycleNote_CustomsID")
          or (
            note."LifecycleNote_SubjectType" in ('quote', 'booking')
            and coalesce(job."Job_ID", note."LifecycleNote_JobID") is not null
            and declaration."CUST_JobID" = coalesce(job."Job_ID", note."LifecycleNote_JobID")
          )
        )
    ) customs_context on true
    left join lateral (
      select
        jsonb_agg(jsonb_build_object(
          'type', mention."LifecycleNoteMention_TargetType",
          'id', mention."LifecycleNoteMention_TargetID",
          'label', mention."LifecycleNoteMention_LabelSnapshot"
        ) order by mention."LifecycleNoteMention_CreatedAt", mention."LifecycleNoteMention_ID") as records,
        jsonb_agg(mention."LifecycleNoteMention_LabelSnapshot" order by mention."LifecycleNoteMention_LabelSnapshot")
          filter (where mention."LifecycleNoteMention_TargetType" = 'user') as users,
        jsonb_agg(mention."LifecycleNoteMention_LabelSnapshot" order by mention."LifecycleNoteMention_LabelSnapshot")
          filter (where mention."LifecycleNoteMention_TargetType" = 'department') as departments,
        string_agg(mention."LifecycleNoteMention_LabelSnapshot", ' ') as search_text
      from public."OPS_LifecycleNoteMentions" mention
      where mention."LifecycleNoteMention_NoteID" = note."LifecycleNote_ID"
    ) mentions on true
    where note."LifecycleNote_CompanyID" = p_company_id
      and (
        (note."LifecycleNote_SubjectType" = 'company' and public.multideck_lifecycle_note_recipient_authorised(auth.uid(), 'company', note."LifecycleNote_SubjectID"))
        or (note."LifecycleNote_SubjectType" = 'quote' and (
          quote_api.has_permission(auth.uid(), 'Quotes.Read')
          or (job."Job_ID" is not null and booking_api.has_permission(auth.uid(), 'Bookings.Read'))
          or coalesce(customs_context.can_read, false)
        ))
        or (note."LifecycleNote_SubjectType" = 'booking' and (
          booking_api.has_permission(auth.uid(), 'Bookings.Read')
          or coalesce(customs_context.can_read, false)
        ))
        or (note."LifecycleNote_SubjectType" = 'customs' and booking_api.customs_access(auth.uid(), note."LifecycleNote_CustomsID", false))
      )
      and (
        nullif(btrim(p_search), '') is null
        or concat_ws(' ', account."Org_Name", note."LifecycleNote_Body", note."LifecycleNote_AuthorNameSnapshot", mentions.search_text,
          quote."CusQuoteHeader_Number", job."Job_BookingReference", customs_context.search_text)
          ilike '%' || btrim(p_search) || '%'
      )
    order by note."LifecycleNote_CreatedAt" desc, note."LifecycleNote_ID" desc
    limit greatest(1, least(coalesce(p_take, 10), 25))
  )
  select coalesce(jsonb_agg(value order by created_at desc), '[]'::jsonb) from rows;
$$;


ALTER FUNCTION "public"."multideck_dexter_domain_lifecycle_notes"("p_company_id" "uuid", "p_search" "text", "p_take" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_domain_lifecycle_notes_v2"("p_company_id" "uuid", "p_search" "text", "p_take" integer) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select coalesce(jsonb_agg(
    case when note."LifecycleNote_DeletedAt" is not null then
      (item.value - 'body') || jsonb_build_object(
        'deleted', true,
        'updatedAt', note."LifecycleNote_UpdatedAt",
        'deletedAt', note."LifecycleNote_DeletedAt"
      )
    else item.value || jsonb_build_object(
      'deleted', false,
      'updatedAt', note."LifecycleNote_UpdatedAt",
      'deletedAt', null
    ) end
    order by item.ordinality
  ), '[]'::jsonb)
  from jsonb_array_elements(public.multideck_dexter_domain_lifecycle_notes(p_company_id, p_search, p_take))
    with ordinality as item(value, ordinality)
  join public."OPS_LifecycleNotes" note
    on note."LifecycleNote_ID" = (item.value->>'noteId')::uuid;
$$;


ALTER FUNCTION "public"."multideck_dexter_domain_lifecycle_notes_v2"("p_company_id" "uuid", "p_search" "text", "p_take" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_domain_marketing_consent"("p_company_id" "uuid", "p_search" "text", "p_take" integer) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  with records as (
    select lead."CRMLead_ID" record_id, 'lead'::text record_type,
      coalesce(nullif(btrim(lead."CRMLead_PersonName"), ''), nullif(btrim(lead."CRMLead_CompanyName"), ''), 'Unnamed lead') label,
      lead."CRMLead_Email" email, lead."CRMLead_MarketingOptIn" opted_in,
      lead."CRMLead_MarketingConsentSource" source, lead."CRMLead_MarketingConsentUpdatedAt" updated_at
    from public."CRM_Leads" lead
    join public."cmp_Users" owner on owner."User_ID" = coalesce(lead."CRMLead_OwnerUserID", lead."CRMLead_CreatedBy")
    where owner."Company_ID" = p_company_id and not lead."CRMLead_IsDeleted"
    union all
    select contact."OrgContact_ID", 'contact',
      coalesce(nullif(btrim(concat_ws(' ', contact."OrgContact_FirstName", contact."OrgContact_LastName")), ''), 'Unnamed contact'),
      email."OrgContactEmail_Email", contact."OrgContact_MarketingOptIn", contact."OrgContact_MarketingConsentSource", contact."OrgContact_MarketingConsentUpdatedAt"
    from public."Org_Contacts" contact
    left join lateral (
      select row."OrgContactEmail_Email" from public."OrgContact_Emails" row
      where row."OrgContact_ID" = contact."OrgContact_ID" order by row."OrgContactEmail_Type", row."OrgContactEmail_ID" limit 1
    ) email on true
    union all
    select org."Org_id", 'customer', org."Org_Name", null, org."Org_MarketingOptIn", org."Org_MarketingConsentSource", org."Org_MarketingConsentUpdatedAt"
    from public."Org_Master" org
    where org."Org_CRMIsPotentialCustomer" or exists (
      select 1 from public."Org_Master_Type" link join public."Org_Types" type on type."OrgType_ID" = link."OrgType_ID"
      where link."Org_ID" = org."Org_id" and lower(type."OrgType_Name") = 'customer'
    )
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'recordId', record_id, 'recordType', record_type, 'label', label, 'email', email,
    'marketingOptIn', opted_in, 'source', source, 'updatedAt', updated_at
  ) order by updated_at desc nulls last, label), '[]'::jsonb)
  from (
    select * from records
    where nullif(btrim(p_search), '') is null or concat_ws(' ', label, email, record_type, source) ilike '%' || btrim(p_search) || '%'
    order by updated_at desc nulls last, label
    limit greatest(1, least(coalesce(p_take, 10), 25))
  ) limited;
$$;


ALTER FUNCTION "public"."multideck_dexter_domain_marketing_consent"("p_company_id" "uuid", "p_search" "text", "p_take" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_domain_phone_calls"("p_company_id" "uuid", "p_search" "text", "p_take" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_context record;
  v_result jsonb;
  v_term text := nullif(btrim(p_search), '');
begin
  select * into v_context from public._multideck_dexter_context();
  if v_context.company_id <> p_company_id
    or not public._multideck_crm_has_permission(
      v_context.user_id,
      'CRM.PhoneCalls.Read'
    ) then
    raise exception 'Phone calls are outside this workspace or permission.'
      using errcode = '42501';
  end if;

  select coalesce(
    jsonb_agg(call_row.row_data order by call_row.started_at desc),
    '[]'::jsonb
  )
  into v_result
  from (
    select
      jsonb_build_object(
        'recordId', call."CommCall_ID",
        'callerName', coalesce(
          call."CommCall_FromDisplayNameSnapshot",
          call."CommCall_ToDisplayNameSnapshot"
        ),
        'phoneNumber', case
          when call."CommCall_DirectionCode" = 'outbound'
            then call."CommCall_ToNumber"
          else call."CommCall_FromNumber"
        end,
        'direction', call."CommCall_DirectionCode",
        'outcome', call."CommCall_OutcomeCode",
        'startedAt', call."CommCall_StartedAt",
        'answeredAt', call."CommCall_AnsweredAt",
        'endedAt', call."CommCall_EndedAt",
        'durationSeconds', call."CommCall_DurationSeconds",
        'transferStatus', call."CommCall_TransferStatusCode",
        'transcriptStatus', call."CommCall_TranscriptStatusCode",
        'matchStatus', call."CommCall_MatchStatusCode",
        'aiDisclosureStatus', call."CommCall_AIDisclosureStatusCode",
        'recordingConsentStatus', call."CommCall_RecordingConsentStatusCode",
        'transcriptionConsentStatus', call."CommCall_TranscriptionConsentStatusCode",
        'consentDisclosureVersion', call."CommCall_ConsentDisclosureVersion",
        'consentDisclosedAt', call."CommCall_ConsentDisclosedAt",
        'recordingStatus', call."CommCall_RecordingStatusCode",
        'companyId', call."CommCall_MatchedOrgID",
        'companyName', organisation."Org_Name",
        'contactId', call."CommCall_MatchedContactID",
        'leadId', call."CommCall_MatchedLeadID",
        'summary', coalesce(
          review."CRMCallReview_UserApprovedSummary",
          review."CRMCallReview_AISummary",
          call."CommCall_AISummary"
        ),
        'meetingNotes', left(review."CRMCallReview_MeetingNotes", 4000),
        'meetingNotesTruncated', length(
          coalesce(review."CRMCallReview_MeetingNotes", '')
        ) > 4000,
        'callReason', review."CRMCallReview_CallReason",
        'participants', coalesce(participants.items, '[]'::jsonb),
        'participantsTruncated', coalesce(participants.total, 0) > 12,
        'transcriptSegments', coalesce(transcript.items, '[]'::jsonb),
        'transcriptTruncated', coalesce(transcript.total, 0) > 40
          or coalesce(transcript.has_long_text, false),
        'pendingSuggestions', coalesce(suggestions.items, '[]'::jsonb),
        'pendingSuggestionCount', coalesce(suggestions.total, 0),
        'pendingSuggestionsTruncated', coalesce(suggestions.total, 0) > 8,
        'providerEvidence', jsonb_build_object(
          'source', call."CommCall_SourceProviderCode",
          'providerCallId', call."CommCall_ProviderCallID",
          'correlationId', call."CommCall_CorrelationID",
          'consentSourceProvider', call."CommCall_ConsentSourceProviderCode",
          'consentSourceEventId', call."CommCall_ConsentSourceEventID"
        ),
        'route', '/crm/phone-calls/' || call."CommCall_ID"::text
      ) as row_data,
      call."CommCall_StartedAt" as started_at
    from public."Comm_CallLogs" call
    left join public."CRM_CallReviews" review
      on review."CRMCallReview_CommCallID" = call."CommCall_ID"
      and review."CRMCallReview_CompanyID" = p_company_id
    left join public."Org_Master" organisation
      on organisation."Org_id" = call."CommCall_MatchedOrgID"
    left join lateral (
      select
        coalesce(jsonb_agg(item.row_data order by item.joined_at), '[]'::jsonb) as items,
        (
          select count(*)
          from public."Comm_CallParticipants" participant_count
          where participant_count."CommCallParticipant_CallID" = call."CommCall_ID"
            and participant_count."CommCallParticipant_CompanyID" = p_company_id
        ) as total
      from (
        select
          jsonb_build_object(
            'id', participant."CommCallParticipant_ID",
            'name', participant."CommCallParticipant_DisplayName",
            'phone', participant."CommCallParticipant_Phone",
            'role', participant."CommCallParticipant_TypeCode",
            'joinedAt', participant."CommCallParticipant_JoinedAt",
            'leftAt', participant."CommCallParticipant_LeftAt"
          ) as row_data,
          participant."CommCallParticipant_JoinedAt" as joined_at
        from public."Comm_CallParticipants" participant
        where participant."CommCallParticipant_CallID" = call."CommCall_ID"
          and participant."CommCallParticipant_CompanyID" = p_company_id
        order by participant."CommCallParticipant_JoinedAt" nulls last,
          participant."CommCallParticipant_CreatedAt"
        limit 12
      ) item
    ) participants on true
    left join lateral (
      select
        coalesce(
          jsonb_agg(item.row_data order by item.started_at nulls last, item.sequence_no),
          '[]'::jsonb
        ) as items,
        (
          select count(*)
          from public."Comm_CallTranscriptSegments" segment_count
          where segment_count."CommCallSeg_CallID" = call."CommCall_ID"
        ) as total,
        (
          select coalesce(bool_or(length(segment_length."CommCallSeg_Text") > 1200), false)
          from public."Comm_CallTranscriptSegments" segment_length
          where segment_length."CommCallSeg_CallID" = call."CommCall_ID"
        ) as has_long_text
      from (
        select
          jsonb_build_object(
            'id', segment."CommCallSeg_ID",
            'source', segment."CommCallSeg_SourceProviderCode",
            'sourceLegId', segment."CommCallSeg_SourceLegID",
            'providerSegmentId', segment."CommCallSeg_ProviderSegmentID",
            'sequence', segment."CommCallSeg_SourceSequenceNo",
            'startedAt', segment."CommCallSeg_StartedAt",
            'endedAt', segment."CommCallSeg_EndedAt",
            'speakerLabel', segment."CommCallSeg_SpeakerLabel",
            'speakerType', segment."CommCallSeg_SpeakerType",
            'state', segment."CommCallSeg_StateCode",
            'text', left(segment."CommCallSeg_Text", 1200),
            'untrustedEvidence', true
          ) as row_data,
          segment."CommCallSeg_StartedAt" as started_at,
          segment."CommCallSeg_SequenceNo" as sequence_no
        from public."Comm_CallTranscriptSegments" segment
        where segment."CommCallSeg_CallID" = call."CommCall_ID"
        order by segment."CommCallSeg_StartedAt" nulls last,
          segment."CommCallSeg_SequenceNo"
        limit 40
      ) item
    ) transcript on true
    left join lateral (
      select
        coalesce(
          jsonb_agg(item.row_data order by item.created_at),
          '[]'::jsonb
        ) as items,
        (
          select count(*)
          from public."CRM_CallActionCandidates" action_count
          where action_count."CRMCallAction_CallReviewID" = review."CRMCallReview_ID"
            and action_count."CRMCallAction_DecisionStatus" = 'pending'
        ) as total
      from (
        select
          jsonb_build_object(
            'id', action."CRMCallAction_ID",
            'callId', call."CommCall_ID",
            'type', action."CRMCallAction_ActionTypeCode",
            'title', action."CRMCallAction_Title",
            'reason', action."CRMCallAction_Description",
            'confidence', action."CRMCallAction_ConfidenceScore",
            'status', action."CRMCallAction_DecisionStatus",
            'requiresReview', true,
            'sourceKey', action."CRMCallAction_SourceKey"
          ) as row_data,
          action."CRMCallAction_CreatedAt" as created_at
        from public."CRM_CallActionCandidates" action
        where action."CRMCallAction_CallReviewID" = review."CRMCallReview_ID"
          and action."CRMCallAction_DecisionStatus" = 'pending'
        order by action."CRMCallAction_CreatedAt"
        limit 8
      ) item
    ) suggestions on true
    where call."CommCall_CompanyID" = p_company_id
      and (
        v_term is null
        or concat_ws(
          ' ',
          call."CommCall_FromDisplayNameSnapshot",
          call."CommCall_ToDisplayNameSnapshot",
          call."CommCall_FromNumber",
          call."CommCall_ToNumber",
          organisation."Org_Name",
          review."CRMCallReview_CallReason",
          review."CRMCallReview_AISummary"
        ) ilike '%' || v_term || '%'
      )
    order by call."CommCall_StartedAt" desc nulls last,
      call."CommCall_CreatedAt" desc
    limit greatest(1, least(coalesce(p_take, 10), 25))
  ) call_row;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."multideck_dexter_domain_phone_calls"("p_company_id" "uuid", "p_search" "text", "p_take" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_domain_purchase_orders"("p_user_id" "uuid", "p_search" "text" DEFAULT NULL::"text", "p_take" integer DEFAULT 10) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
with actor as (
  select "Company_ID" company_id
  from public."cmp_Users"
  where "User_ID" = p_user_id
), facilities as (
  select facility."WMSFacility_ID"
  from public."WMS_Facilities" facility
  join public."cmp_Offices" office
    on office."Office_ID" = facility."WMSFacility_OrgOfficeID"
  join actor on actor.company_id = office."Company_ID"
  where not facility."WMSFacility_IsDeleted"
), rows as (
  select
    po.*,
    facility."WMSFacility_Code",
    customer."Org_Name" customer_name,
    (
      select jsonb_agg(
        jsonb_build_object(
          'recordId', line."WMSPOLine_ID",
          'lineNumber', line."WMSPOLine_LineNo",
          'itemId', line."WMSPOLine_ItemID",
          'sku', line."WMSPOLine_SKU",
          'description', line."WMSPOLine_Description",
          'quantity', line."WMSPOLine_OrderedQuantity",
          'receivedQuantity', line."WMSPOLine_ReceivedQuantity",
          'uom', line."WMSPOLine_UOMCode",
          'unitPrice', line."WMSPOLine_UnitPrice",
          'totalAmount', line."WMSPOLine_TotalAmount"
        ) order by line."WMSPOLine_LineNo"
      )
      from public."WMS_PurchaseOrderLines" line
      where line."WMSPOLine_PurchaseOrderID" = po."WMSPO_ID"
    ) lines
  from public."WMS_PurchaseOrders" po
  join facilities f on f."WMSFacility_ID" = po."WMSPO_FacilityID"
  join public."WMS_Facilities" facility
    on facility."WMSFacility_ID" = po."WMSPO_FacilityID"
  join public."Org_Master" customer
    on customer."Org_id" = po."WMSPO_CustomerOrgID"
  where not po."WMSPO_IsDeleted"
    and (
      coalesce(btrim(p_search), '') = ''
      or concat_ws(' ', po."WMSPO_Number", customer."Org_Name", po."WMSPO_SupplierName", po."WMSPO_BuyerReference", po."WMSPO_SupplierReference")
        ilike '%' || btrim(p_search) || '%'
    )
  order by po."WMSPO_UpdatedAt" desc
  limit greatest(1, least(coalesce(p_take, 10), 25))
)
select coalesce(
  jsonb_agg(
    jsonb_build_object(
      'recordId', "WMSPO_ID",
      'recordRole', "WMSPO_RecordRoleCode",
      'financePurchaseOrder', false,
      'facilityId', "WMSPO_FacilityID",
      'facilityCode', "WMSFacility_Code",
      'customerOrgId', "WMSPO_CustomerOrgID",
      'customerName', customer_name,
      'purchaseOrderNumber', "WMSPO_Number",
      'supplierName', "WMSPO_SupplierName",
      'status', "WMSPO_StatusCode",
      'issueDate', "WMSPO_IssueDate",
      'expectedDeliveryDate', "WMSPO_ExpectedDeliveryDate",
      'currency', "WMSPO_CurrencyCode",
      'netAmount', "WMSPO_NetAmount",
      'taxAmount', "WMSPO_TaxAmount",
      'totalAmount', "WMSPO_TotalAmount",
      'warehouseOrderId', "WMSPO_WarehouseOrderID",
      'lines', coalesce(lines, '[]'::jsonb),
      'source', jsonb_build_object(
        'table', 'WMS_PurchaseOrders',
        'id', "WMSPO_ID",
        'observedAt', "WMSPO_UpdatedAt"
      )
    )
  ),
  '[]'::jsonb
)
from rows;
$$;


ALTER FUNCTION "public"."multideck_dexter_domain_purchase_orders"("p_user_id" "uuid", "p_search" "text", "p_take" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_domain_quote_cargo"("p_company_id" "uuid", "p_search" "text", "p_take" integer) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(jsonb_agg(result order by reference,line_number),'[]'::jsonb) from (
    select quote_api.cargo_read_values(line)||jsonb_build_object(
      'recordId',quote_api.cargo_record_id(line.version_id,line.line_id),'quoteId',q."CusQuoteHeader_ID",
      'versionId',line.version_id,'lineId',line.line_id,'lineNumber',line.line_number,'cargoScope','quote_version',
      'quoteReference',v."CusQuoteVersion_SnapshotJSON"->>'reference','versionNumber',v."CusQuoteVersion_Number",
      'updatedAt',q."CusQuoteHeader_LastEditedDate",'snapshotHash',md5(v."CusQuoteVersion_SnapshotJSON"::text),
      'editable',not v."CusQuoteVersion_IsSubmitted" and v."CusQuoteVersion_StatusCode"='draft'
        and q."CusQuoteHeader_LifecycleCode" in ('draft','calculated','revised')
        and not exists(select 1 from quote_api.customer_response_links where quote_version_id=line.version_id)
        and not exists(select 1 from quote_api.customer_responses where quote_version_id=line.version_id),
      'sourceTable','quote_api.version_cargo_lines',
      'sourceUrl','/quotes/'||lower(v."CusQuoteVersion_SnapshotJSON"->>'reference'),
      'targetLabel',coalesce(v."CusQuoteVersion_SnapshotJSON"->>'reference','Quote')||' · Version '||v."CusQuoteVersion_Number"||' · Cargo '||line.line_number
    ) result, v."CusQuoteVersion_SnapshotJSON"->>'reference' reference,line.line_number
    from quote_api.version_cargo_lines line join public."CusQuote_Versions" v on v."CusQuoteVersion_ID"=line.version_id
    join public."CusQuote_Header" q on q."CusQuoteHeader_ID"=v."CusQuoteHeader_ID" and not q."CusQuoteHeader_IsDeleted"
    join public."cmp_Offices" office on office."Office_ID"=coalesce(q."CusQuoteHeader_OrgOfficeID",q."OrgOffice_ID")
    where office."Company_ID"=p_company_id and v."Company_ID"=p_company_id and v."CusQuoteVersion_IsCurrent"
      and (nullif(btrim(p_search),'') is null or q."CusQuoteHeader_ID"::text=btrim(p_search)
        or line.version_id::text=btrim(p_search) or line.line_id::text=btrim(p_search)
        or quote_api.cargo_record_id(line.version_id,line.line_id)::text=btrim(p_search)
        or v."CusQuoteVersion_SnapshotJSON"->>'reference' ilike '%'||btrim(p_search)||'%'
        or line.description ilike '%'||btrim(p_search)||'%')
    order by reference,line.line_number limit greatest(1,least(coalesce(p_take,10),25))
  ) selected
$$;


ALTER FUNCTION "public"."multideck_dexter_domain_quote_cargo"("p_company_id" "uuid", "p_search" "text", "p_take" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_domain_quote_follow_up_policy"("p_company_id" "uuid", "p_search" "text", "p_take" integer) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_array(jsonb_build_object(
    'recordId', p_company_id, 'name', 'Quote follow-up policy',
    'enabled', coalesce(settings.quote_follow_up_enabled, true),
    'defaultDelayDays', coalesce(settings.quote_follow_up_delay_days, 3),
    'sendTime', to_char(coalesce(settings.quote_follow_up_send_time, time '09:00'), 'HH24:MI'),
    'timezone', coalesce(settings.quote_follow_up_timezone, 'Europe/London'),
    'updatedAt', settings.updated_at
  ))
  from (select 1) seed
  left join quote_api.reference_settings settings on settings.company_id = p_company_id;
$$;


ALTER FUNCTION "public"."multideck_dexter_domain_quote_follow_up_policy"("p_company_id" "uuid", "p_search" "text", "p_take" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_domain_quotes"("p_company_id" "uuid", "p_search" "text", "p_take" integer) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(jsonb_agg(
    item.value || jsonb_strip_nulls(jsonb_build_object(
      'operatingCountryCode', booking_api.operating_country_code(coalesce(quote."CusQuoteHeader_OrgOfficeID", quote."OrgOffice_ID")),
      'calculatedDirection', booking_api.direction_for_route(
        coalesce(quote."CusQuoteHeader_OrgOfficeID", quote."OrgOffice_ID"),
        coalesce(quote."CusQuoteHeader_ShipmentFactsJSON"->>'originUnlocode', item.value->>'origin'),
        coalesce(quote."CusQuoteHeader_ShipmentFactsJSON"->>'destinationUnlocode', item.value->>'destination')
      ),
      'directionMatchesRoute', case
        when booking_api.direction_for_route(
          coalesce(quote."CusQuoteHeader_OrgOfficeID", quote."OrgOffice_ID"),
          coalesce(quote."CusQuoteHeader_ShipmentFactsJSON"->>'originUnlocode', item.value->>'origin'),
          coalesce(quote."CusQuoteHeader_ShipmentFactsJSON"->>'destinationUnlocode', item.value->>'destination')
        ) is null then null
        else booking_api.normalise_direction(item.value->>'direction') = booking_api.direction_for_route(
          coalesce(quote."CusQuoteHeader_OrgOfficeID", quote."OrgOffice_ID"),
          coalesce(quote."CusQuoteHeader_ShipmentFactsJSON"->>'originUnlocode', item.value->>'origin'),
          coalesce(quote."CusQuoteHeader_ShipmentFactsJSON"->>'destinationUnlocode', item.value->>'destination')
        )
      end
    )) order by item.ordinality
  ), '[]'::jsonb)
  from jsonb_array_elements(
    public.multideck_dexter_quotes_before_branch_direction_20260904(p_company_id, p_search, p_take)
  ) with ordinality item(value, ordinality)
  left join public."CusQuote_Header" quote
    on quote."CusQuoteHeader_ID" = nullif(item.value->>'recordId', '')::uuid
   and not quote."CusQuoteHeader_IsDeleted";
$$;


ALTER FUNCTION "public"."multideck_dexter_domain_quotes"("p_company_id" "uuid", "p_search" "text", "p_take" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_domain_quotes_before_payer_20260904"("p_company_id" "uuid", "p_search" "text", "p_take" integer) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(jsonb_agg(
    item.value || jsonb_strip_nulls(jsonb_build_object(
      'estimatedDeparture', quote."CusQuoteHeader_ShipmentFactsJSON"->>'estimatedDeparture',
      'estimatedArrival', quote."CusQuoteHeader_ShipmentFactsJSON"->>'estimatedArrival',
      'copiedFromQuoteId', quote."CusQuoteHeader_ShipmentFactsJSON"->>'copiedFromQuoteId',
      'copiedFromQuoteReference', quote."CusQuoteHeader_ShipmentFactsJSON"->>'copiedFromQuoteReference',
      'copyReason', quote."CusQuoteHeader_ShipmentFactsJSON"->>'copyReason',
      'customerResponse', case
        when response.response_id is null then item.value->'customerResponse'
        else coalesce(item.value->'customerResponse', '{}'::jsonb)
          || jsonb_strip_nulls(jsonb_build_object('declineReasonCode', response.decline_reason_code))
      end
    )) order by item.ordinality
  ), '[]'::jsonb)
  from jsonb_array_elements(
    public.multideck_dexter_domain_quotes_before_route_schedule_20260902(p_company_id, p_search, p_take)
  ) with ordinality item(value, ordinality)
  left join public."CusQuote_Header" quote
    on quote."CusQuoteHeader_ID" = nullif(item.value->>'recordId', '')::uuid
   and not quote."CusQuoteHeader_IsDeleted"
  left join lateral (
    select response.response_id, response.decline_reason_code
    from quote_api.customer_responses response
    where response.quote_id = quote."CusQuoteHeader_ID"
      and response.company_id = p_company_id
    order by response.created_at desc
    limit 1
  ) response on true;
$$;


ALTER FUNCTION "public"."multideck_dexter_domain_quotes_before_payer_20260904"("p_company_id" "uuid", "p_search" "text", "p_take" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."multideck_dexter_domain_quotes_before_payer_20260904"("p_company_id" "uuid", "p_search" "text", "p_take" integer) IS 'Tenant-scoped Dexter quote read model with route schedule and structured response context. Direct quote sending remains an operator-reviewed action outside Dexter.';



CREATE OR REPLACE FUNCTION "public"."multideck_dexter_domain_quotes_before_route_schedule_20260902"("p_company_id" "uuid", "p_search" "text", "p_take" integer) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select coalesce(jsonb_agg(result.value order by result.updated_at desc), '[]'::jsonb)
  from (
    select jsonb_strip_nulls(jsonb_build_object(
      'recordId', quote."CusQuoteHeader_ID",
      'quoteNumber', 'Q-' || quote."CusQuoteHeader_Number",
      'customerReference', quote."CusQuoteHeader_CustomerReference",
      'customer', coalesce(customer."Org_Name", quote."CusQuoteHeader_CustomerNameSnapshot"),
      'status', case
        when quote."CusQuoteHeader_LifecycleCode" = 'accepted' then 'Won'
        when quote."CusQuoteHeader_LifecycleCode" in ('declined', 'ghosted') then 'Lost'
        else 'Open'
      end,
      'lifecycle', quote."CusQuoteHeader_LifecycleCode",
      'lossReason', case when quote."CusQuoteHeader_LifecycleCode" in ('declined', 'ghosted') then quote."CusQuoteHeader_OutcomeNotes" end,
      'customerResponse', case when customer_response.decision_code is null then null else jsonb_strip_nulls(jsonb_build_object(
        'decision', customer_response.decision_code,
        'message', customer_response.customer_message,
        'attachmentDocumentId', customer_response.competitor_document_id,
        'receivedAt', customer_response.created_at,
        'evidence', jsonb_build_object('sourceTable', 'quote_api.customer_responses', 'sourceId', customer_response.response_id)
      )) end,
      'latestDelivery', case when latest_issue.response_link_id is null then null else jsonb_strip_nulls(jsonb_build_object(
        'mode', latest_issue.delivery_mode_code,
        'responseControlsEnabled', latest_issue.delivery_mode_code = 'standard',
        'recipientSource', latest_issue.recipient_source_code,
        'recipientEmail', latest_issue.recipient_email,
        'quoteDocumentId', latest_issue.quote_document_id,
        'deliveryStatus', latest_issue.delivery_status_code,
        'sentAt', latest_issue.created_at,
        'evidence', jsonb_build_object('sourceTable', 'quote_api.customer_response_links', 'sourceId', latest_issue.response_link_id)
      )) end,
      'linkedBooking', case when linked_booking."Job_ID" is null then null else jsonb_build_object(
        'jobId', linked_booking."Job_ID",
        'bookingReference', linked_booking."Job_BookingReference",
        'status', linked_booking."Job_Status",
        'requiresCustomerLink', linked_booking."Job_Customer" is null,
        'source', 'accepted_quote'
      ) end,
      'mode', quote."CusQuoteHeader_ModeCode",
      'shipmentType', quote."CusQuoteHeader_ShipmentTypeCode",
      'serviceLevel', quote."CusQuoteHeader_ServiceLevel",
      'currency', quote."CusQuoteHeader_CurrencyCode",
      'origin', coalesce(quote."CusQuoteHeader_LoadingPoint", quote."CusQuoteHeader_OriginExtra"),
      'destination', coalesce(quote."CusQuoteHeader_DischargePoint", quote."CusQuoteHeader_DestinationExtra"),
      'direction', quote."CusQuoteHeader_Direction",
      'incoterm', quote."CusQuoteHeader_Incoterm",
      'validFrom', quote."CusQuoteHeader_ValidFrom",
      'validTo', quote."CusQuoteHeader_ValidTo",
      'supplier', coalesce(quote."CusQuoteHeader_SupplierNameSnapshot", supplier."Org_Name"),
      'carrier', coalesce(quote."CusQuoteHeader_CarrierNameSnapshot", carrier."Org_Name"),
      'followUpAt', quote."CusQuoteHeader_FollowUpAt",
      'costTotal', totals.cost,
      'sellTotal', totals.sell,
      'profit', totals.sell - totals.cost,
      'marginPct', case when totals.sell = 0 then null else round(((totals.sell - totals.cost) / totals.sell) * 100, 2) end,
      'updatedAt', quote."CusQuoteHeader_LastEditedDate",
      'evidence', jsonb_build_object(
        'sourceTable', 'CusQuote_Header',
        'sourceId', quote."CusQuoteHeader_ID",
        'currentVersionId', version."CusQuoteVersion_ID"
      )
    )) value,
    quote."CusQuoteHeader_LastEditedDate" updated_at
    from public."CusQuote_Header" quote
    join public."cmp_Offices" office
      on office."Office_ID" = coalesce(quote."CusQuoteHeader_OrgOfficeID", quote."OrgOffice_ID")
      and office."Company_ID" = p_company_id
    left join public."Org_Master" customer on customer."Org_id" = quote."CusQuoteHeader_CustomerID"
    left join public."Org_Master" supplier on supplier."Org_id" = quote."CusQuoteHeader_SupplierID"
    left join public."Org_Master" carrier on carrier."Org_id" = quote."CusQuoteHeader_CarrierID"
    left join public."CusQuote_Versions" version
      on version."CusQuoteHeader_ID" = quote."CusQuoteHeader_ID" and version."CusQuoteVersion_IsCurrent"
    left join lateral (
      select response.response_id, response.decision_code, response.customer_message,
        response.competitor_document_id, response.created_at
      from quote_api.customer_responses response
      where response.quote_id = quote."CusQuoteHeader_ID" and response.company_id = p_company_id
      order by response.created_at desc limit 1
    ) customer_response on true
    left join lateral (
      select link.response_link_id, link.quote_document_id, link.delivery_mode_code, link.recipient_source_code,
        link.recipient_email, link.delivery_status_code, link.created_at
      from quote_api.customer_response_links link
      where link.quote_id = quote."CusQuoteHeader_ID"
        and link.company_id = p_company_id
        and link.delivery_status_code = 'sent'
      order by link.created_at desc limit 1
    ) latest_issue on true
    left join lateral (
      select job."Job_ID", job."Job_BookingReference", job."Job_Status", job."Job_Customer"
      from public."Job_Header" job
      where job."Job_SourceQuoteID" = quote."CusQuoteHeader_ID" and not job."Job_IsDeleted"
      order by job."Job_CreatedDate" asc limit 1
    ) linked_booking on true
    left join lateral (
      select coalesce(sum("CusQuoteLine_CostAmountLocal"), 0) cost,
        coalesce(sum("CusQuoteLine_RevenueAmountLocal"), 0) sell
      from public."CusQuote_Lines" where "CusQuoteHeader_ID" = quote."CusQuoteHeader_ID"
    ) totals on true
    where not quote."CusQuoteHeader_IsDeleted"
      and (
        nullif(btrim(p_search), '') is null
        or concat_ws(' ', quote."CusQuoteHeader_Number", quote."CusQuoteHeader_CustomerReference",
          customer."Org_Name", quote."CusQuoteHeader_CustomerNameSnapshot", quote."CusQuoteHeader_LifecycleCode",
          quote."CusQuoteHeader_OutcomeNotes", customer_response.decision_code, customer_response.customer_message,
          latest_issue.delivery_mode_code, latest_issue.recipient_email, linked_booking."Job_BookingReference",
          quote."CusQuoteHeader_ModeCode", quote."CusQuoteHeader_ShipmentTypeCode",
          quote."CusQuoteHeader_OriginExtra", quote."CusQuoteHeader_DestinationExtra",
          quote."CusQuoteHeader_SupplierNameSnapshot", quote."CusQuoteHeader_CarrierNameSnapshot"
        ) ilike '%' || btrim(p_search) || '%'
      )
    order by quote."CusQuoteHeader_LastEditedDate" desc
    limit greatest(1, least(coalesce(p_take, 10), 25))
  ) result;
$$;


ALTER FUNCTION "public"."multideck_dexter_domain_quotes_before_route_schedule_20260902"("p_company_id" "uuid", "p_search" "text", "p_take" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."multideck_dexter_domain_quotes_before_route_schedule_20260902"("p_company_id" "uuid", "p_search" "text", "p_take" integer) IS 'Tenant-scoped Dexter quote base read model. Failed staged email attempts never replace the latest confirmed delivery evidence.';



CREATE OR REPLACE FUNCTION "public"."multideck_dexter_domain_quotes_intelligence"("p_company_id" "uuid", "p_search" "text", "p_take" integer) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  with base as (
    select value
    from jsonb_array_elements(public.multideck_dexter_domain_quotes(p_company_id, p_search, p_take)) value
  ), enriched as (
    select base.value || case when intelligence."CusQuoteIntelligence_QuoteID" is null then '{}'::jsonb else
      jsonb_build_object('quoteIntelligence', jsonb_strip_nulls(jsonb_build_object(
        'state', intelligence."CusQuoteIntelligence_StateCode",
        'historicalWinRate', intelligence."CusQuoteIntelligence_DeterministicJSON"#>'{metrics,historicalWinRate,value}',
        'wonPriceBand', intelligence."CusQuoteIntelligence_DeterministicJSON"#>'{metrics,wonPriceBand,value}',
        'suggestedPitch', intelligence."CusQuoteIntelligence_DeterministicJSON"#>'{metrics,suggestedPitch,value}',
        'marginHeadroom', intelligence."CusQuoteIntelligence_DeterministicJSON"#>'{metrics,marginHeadroom,value}',
        'priceConfidence', intelligence."CusQuoteIntelligence_DeterministicJSON"#>'{metrics,priceConfidence,value,score}',
        'aiWinLikelihoodBase', intelligence."CusQuoteIntelligence_DeterministicJSON"#>'{metrics,aiWinLikelihood,value,basePct}',
        'aiAdjustmentPoints', case
          when intelligence."CusQuoteIntelligence_AIJSON"->>'inputFingerprint' = intelligence."CusQuoteIntelligence_InputFingerprint"
          then intelligence."CusQuoteIntelligence_AIJSON"->'adjustmentPoints' end,
        'aiTemperatureBase', intelligence."CusQuoteIntelligence_DeterministicJSON"#>'{metrics,aiTemperature,value,baseScore}',
        'algorithmVersion', intelligence."CusQuoteIntelligence_AlgorithmVersion",
        'calculatedAt', intelligence."CusQuoteIntelligence_CalculatedAt",
        'aiGeneratedAt', intelligence."CusQuoteIntelligence_AIGeneratedAt",
        'evidence', jsonb_build_object(
          'historicalCount', intelligence."CusQuoteIntelligence_DeterministicJSON"#>'{metrics,historicalWinRate,evidenceCount}',
          'pricingCount', intelligence."CusQuoteIntelligence_DeterministicJSON"#>'{metrics,priceConfidence,evidenceCount}',
          'cohort', intelligence."CusQuoteIntelligence_DeterministicJSON"#>'{metrics,historicalWinRate,cohort}'
        )
      ))) end as value
    from base
    left join public."CusQuote_Intelligence" intelligence
      on intelligence."CusQuoteIntelligence_QuoteID" = nullif(base.value->>'recordId', '')::uuid
     and intelligence."Company_ID" = p_company_id
  )
  select coalesce(jsonb_agg(enriched.value), '[]'::jsonb) from enriched;
$$;


ALTER FUNCTION "public"."multideck_dexter_domain_quotes_intelligence"("p_company_id" "uuid", "p_search" "text", "p_take" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_domain_quotes_pre_followup_20260904"("p_company_id" "uuid", "p_search" "text", "p_take" integer) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(jsonb_agg(
    item.value || jsonb_strip_nulls(jsonb_build_object(
      'payer', case when payer."CusQuoteParty_ID" is null then null else jsonb_strip_nulls(jsonb_build_object(
        'organisationId', payer."CusQuoteParty_OrgID",
        'name', payer."CusQuoteParty_NameSnapshot",
        'address', payer."CusQuoteParty_AddressSnapshot",
        'contact', payer."CusQuoteParty_ContactSnapshot",
        'code', quote."CusQuoteHeader_ShipmentFactsJSON"->>'payerCode',
        'email', quote."CusQuoteHeader_ShipmentFactsJSON"->>'payerEmail'
      )) end
    )) order by item.ordinality
  ), '[]'::jsonb)
  from jsonb_array_elements(
    public.multideck_dexter_domain_quotes_before_payer_20260904(p_company_id, p_search, p_take)
  ) with ordinality item(value, ordinality)
  left join public."CusQuote_Header" quote
    on quote."CusQuoteHeader_ID" = nullif(item.value->>'recordId', '')::uuid
   and not quote."CusQuoteHeader_IsDeleted"
  left join public."CusQuote_Parties" payer
    on payer."CusQuoteHeader_ID" = quote."CusQuoteHeader_ID"
   and payer."CusQuoteParty_RoleCode" = 'payer';
$$;


ALTER FUNCTION "public"."multideck_dexter_domain_quotes_pre_followup_20260904"("p_company_id" "uuid", "p_search" "text", "p_take" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."multideck_dexter_domain_quotes_pre_followup_20260904"("p_company_id" "uuid", "p_search" "text", "p_take" integer) IS 'Tenant-safe quote reads include payer evidence. Payer writes are deliberately not allowlisted until the Dexter proposed-action approval stage.';



CREATE OR REPLACE FUNCTION "public"."multideck_dexter_domain_rates"("p_company_id" "uuid", "p_search" "text", "p_take" integer) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select coalesce(jsonb_agg(result.value order by result.updated_at desc), '[]'::jsonb)
  from (
    select jsonb_strip_nulls(jsonb_build_object(
      'recordId', contract."RATEContract_ID",
      'rateCode', contract."RATEContract_Code",
      'name', contract."RATEContract_Name",
      'type', contract."RATEContract_TypeCode",
      'status', contract."RATEContract_StatusCode",
      'mode', contract."RATEContract_MetadataJSON"->>'mode',
      'carrier', contract."RATEContract_MetadataJSON"->>'carrier',
      'supplier', contract."RATEContract_MetadataJSON"->>'supplier',
      'customer', contract."RATEContract_MetadataJSON"->>'customer',
      'origin', contract."RATEContract_MetadataJSON"->>'origin',
      'destination', contract."RATEContract_MetadataJSON"->>'destination',
      'cargo', contract."RATEContract_MetadataJSON"->>'cargo',
      'service', contract."RATEContract_MetadataJSON"->>'service',
      'currency', contract."RATEContract_CurrencyCodeSnapshot",
      'validFrom', contract."RATEContract_ValidFrom",
      'validTo', contract."RATEContract_ValidTo",
      'buyTotal', contract."RATEContract_MetadataJSON"->'buyTotal',
      'sellTotal', contract."RATEContract_MetadataJSON"->'sellTotal',
      'currentVersion', version."RATEContractVer_VersionNo",
      'sourceReference', version."RATEContractVer_SourceReference",
      'updatedAt', contract."RATEContract_UpdatedAt",
      'evidence', jsonb_build_object(
        'sourceTable', 'RATE_Contracts',
        'sourceId', contract."RATEContract_ID",
        'versionId', contract."RATEContract_CurrentVersionID",
        'immutableVersion', version."RATEContractVer_VersionNo"
      )
    )) as value, contract."RATEContract_UpdatedAt" as updated_at
    from public."RATE_Contracts" contract
    left join public."RATE_ContractVersions" version
      on version."RATEContractVer_ID" = contract."RATEContract_CurrentVersionID"
    where contract."Company_ID" = p_company_id
      and not contract."RATEContract_IsDeleted"
      and (
        nullif(btrim(p_search), '') is null
        or concat_ws(' ', contract."RATEContract_Code", contract."RATEContract_Name", contract."RATEContract_TypeCode",
          contract."RATEContract_MetadataJSON"->>'mode', contract."RATEContract_MetadataJSON"->>'carrier',
          contract."RATEContract_MetadataJSON"->>'supplier', contract."RATEContract_MetadataJSON"->>'customer',
          contract."RATEContract_MetadataJSON"->>'origin', contract."RATEContract_MetadataJSON"->>'destination',
          contract."RATEContract_MetadataJSON"->>'cargo') ilike '%' || btrim(p_search) || '%'
      )
    order by contract."RATEContract_UpdatedAt" desc
    limit greatest(1, least(coalesce(p_take, 10), 25))
  ) result;
$$;


