CREATE OR REPLACE FUNCTION "public"."multideck_dexter_domain_report_sources"("p_company_id" "uuid", "p_search" "text", "p_take" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare u public."cmp_Users"; result jsonb;
begin
  u:=report_api.context(auth.uid());
  if u."Company_ID"<>p_company_id then raise exception 'The reporting workspace is unavailable.' using errcode='42501';end if;
  select coalesce(jsonb_agg(c||jsonb_build_object('recordId',c->>'id','sourceUrl','/reports/new',
    'queryExample',jsonb_build_object('source',c->>'id','dateField',c->>'defaultDate','period',jsonb_build_object('preset','last12months'),
      'columns',(select jsonb_agg(f->>'id') from jsonb_array_elements(c->'fields') f),'mode','rows','filters','[]'::jsonb,'filterMatch','all',
      'groupBy','month','measure','count','aggregation','sum','currency','','compare','none','chart','bar',
      'sort',jsonb_build_object('field',c->>'defaultDate','direction','desc')))),'[]') into result
    from jsonb_array_elements(report_api.catalogue()) c where booking_api.has_permission(auth.uid(),c->>'permission');
  return result;
end $$;


ALTER FUNCTION "public"."multideck_dexter_domain_report_sources"("p_company_id" "uuid", "p_search" "text", "p_take" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_domain_reports"("p_company_id" "uuid", "p_search" "text", "p_take" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare u public."cmp_Users"; result jsonb;
begin
  u:=report_api.context(auth.uid());
  if u."Company_ID"<>p_company_id then raise exception 'The reporting workspace is unavailable.' using errcode='42501';end if;
  select coalesce(jsonb_agg(row order by edited desc),'[]') into result from (
    select jsonb_build_object('recordId',r.id,'name',r.name,'definition',r.definition,'version',r.version,'visibility',r.visibility,
      'canEdit',r.owner_id=u."User_ID",'updatedAt',r.updated_at,'sourceTable','report_api.reports','sourceUrl','/reports/edit/'||r.id,
      'latestRun',(select jsonb_build_object('id',h.id,'status',h.status,'generatedAt',h.created_at,'sourceUrl','/reports/history')
        from report_api.runs h where h.report_id=r.id and h.owner_id=u."User_ID" order by h.created_at desc limit 1)) row,r.updated_at edited
    from report_api.reports r where report_api.can_read(auth.uid(),r) and (nullif(btrim(p_search),'') is null or r.id::text=p_search or r.name ilike '%'||p_search||'%')
    order by r.updated_at desc limit greatest(1,least(coalesce(p_take,10),25))) selected;
  return result;
end $$;


ALTER FUNCTION "public"."multideck_dexter_domain_reports"("p_company_id" "uuid", "p_search" "text", "p_take" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_domain_screening"("p_company_id" "uuid", "p_search" "text", "p_take" integer) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
  select jsonb_build_object(
    'list', public.cmp_screening_list_status(),
    'checks', coalesce((
      select jsonb_agg(row_data order by search_rank desc, created_at desc)
      from (
        select jsonb_build_object(
          'recordId', check_row."ScreeningCheck_ID",
          'subjectName', check_row."ScreeningCheck_SubjectName",
          'outcome', check_row."ScreeningCheck_OutcomeCode",
          'decisionCode', check_row."ScreeningCheck_DecisionCode",
          'matchCount', check_row."ScreeningCheck_MatchCount",
          'sourceArea', check_row."ScreeningCheck_SourceArea",
          'sourceRecordId', check_row."ScreeningCheck_SourceRecordID",
          'sourceLabel', check_row."ScreeningCheck_SourceLabel",
          'subjectRole', check_row."ScreeningCheck_SubjectRole",
          'rescreenDueAt', check_row."ScreeningCheck_RescreenDueAt",
          'orgId', check_row."ScreeningCheck_OrgID",
          'country', check_row."ScreeningCheck_Country",
          'listStale', check_row."ScreeningCheck_ListStale",
          'createdAt', check_row."ScreeningCheck_CreatedAt",
          'searchEvidence', evidence.value - 'matched'
        ) as row_data,
        coalesce((evidence.value->>'confidence')::numeric, 0) as search_rank,
        check_row."ScreeningCheck_CreatedAt" as created_at
        from public."CMP_ScreeningChecks" check_row
        cross join lateral public._multideck_dexter_search_evidence(
          p_search,
          jsonb_build_object('recordId', check_row."ScreeningCheck_ID", 'subjectName', check_row."ScreeningCheck_SubjectName", 'sourceLabel', check_row."ScreeningCheck_SourceLabel", 'sourceArea', check_row."ScreeningCheck_SourceArea", 'outcome', check_row."ScreeningCheck_OutcomeCode"),
          array['recordId']::text[]
        ) evidence(value)
        where check_row."ScreeningCheck_CompanyID" = p_company_id
          and (evidence.value->>'matched')::boolean
        order by search_rank desc, check_row."ScreeningCheck_CreatedAt" desc
        limit greatest(1, least(coalesce(p_take, 10), 25))
      ) ranked
    ), '[]'::jsonb)
  );
$$;


ALTER FUNCTION "public"."multideck_dexter_domain_screening"("p_company_id" "uuid", "p_search" "text", "p_take" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_domain_support_tickets"("p_company_id" "uuid", "p_search" "text", "p_take" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth', 'private'
    AS $$
declare
  v_context record;
  v_is_admin boolean;
  v_result jsonb;
begin
  select * into v_context from public._multideck_dexter_context();
  if v_context.company_id <> p_company_id then
    raise exception 'That ticket workspace is not available.' using errcode = '42501';
  end if;
  v_is_admin := private.is_tenant_administrator(v_context.user_id);

  select coalesce(jsonb_agg(row_payload order by changed_at desc), '[]'::jsonb)
  into v_result
  from (
    select
      signal."CloudTicketSignal_ChangedAt" as changed_at,
      jsonb_build_object(
        'id', signal."CloudTicketSignal_TicketID",
        'reference', signal."CloudTicketSignal_Reference",
        'status', signal."CloudTicketSignal_StatusCode",
        'needsReply', signal."CloudTicketSignal_NeedsReply",
        'latestMessageId', signal."CloudTicketSignal_LatestMessageID",
        'updatedAt', signal."CloudTicketSignal_ChangedAt",
        'sourceReferences', jsonb_build_array(jsonb_build_object(
          'source', 'multideck_cloud_support_ticket',
          'id', signal."CloudTicketSignal_TicketID",
          'reference', signal."CloudTicketSignal_Reference"
        )),
        'securityOperationsSupported', false
      ) as row_payload
    from public."Support_CloudTicketSignals" signal
    where signal."CloudTicketSignal_CompanyID" = p_company_id
      and (
        signal."CloudTicketSignal_ReporterUserID" = v_context.user_id
        or v_is_admin
      )
      and (
        nullif(btrim(p_search), '') is null
        or signal."CloudTicketSignal_Reference" ilike '%' || btrim(p_search) || '%'
        or replace(signal."CloudTicketSignal_StatusCode", '_', ' ') ilike '%' || btrim(p_search) || '%'
      )
    order by signal."CloudTicketSignal_ChangedAt" desc
    limit greatest(1, least(coalesce(p_take, 10), 25))
  ) visible_rows;
  return v_result;
end;
$$;


ALTER FUNCTION "public"."multideck_dexter_domain_support_tickets"("p_company_id" "uuid", "p_search" "text", "p_take" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_domain_todo"("p_company_id" "uuid", "p_search" "text", "p_take" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare v_context record; v_result jsonb; v_search text := nullif(btrim(p_search),'');
begin
  select * into v_context from public._multideck_dexter_context();
  if v_context.company_id <> p_company_id then
    raise exception 'Those tasks is outside this workspace.' using errcode = '42501';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
    'recordId', task."TodoTask_ID",
    'title', task."TodoTask_Title",
    'scheduledDate', task."TodoTask_ScheduledDate",
    'priority', task."TodoTask_PriorityCode",
    'status', task."TodoTask_StatusCode",
    'completedAt', task."TodoTask_CompletedAt",
    'links', task."TodoTask_LinksJSON",
    'tags', task."TodoTask_TagsJSON",
    'agent', (select jsonb_build_object('id',a.id,'name',a.name,'status',a.status,'summary',a.summary,'conversationId',a.conversation_id,'route','/agent-dexter?conversation='||a.conversation_id) from public."AI_DexterTaskAssignments" a where a.task_id=task."TodoTask_ID" and a.owner_id=v_context.user_id and a.company_id=p_company_id),
    'route', '/to-do?date=' || task."TodoTask_ScheduledDate"::text
  ) order by task."TodoTask_ScheduledDate", task."TodoTask_CreatedAt"), '[]'::jsonb)
  into v_result
  from (
    select * from public."OPS_UserTasks" task
    where task."TodoTask_CompanyID" = p_company_id
      and task."TodoTask_OwnerUserID" = v_context.user_id
      and not task."TodoTask_IsDeleted"
      and (
        v_search is null
        or task."TodoTask_Title" ilike '%' || v_search || '%'
        or task."TodoTask_ScheduledDate"::text = v_search
        or coalesce(task."TodoTask_PriorityCode",'') ilike '%' || v_search || '%'
        or task."TodoTask_TagsJSON"::text ilike '%' || v_search || '%'
      )
    order by task."TodoTask_ScheduledDate", task."TodoTask_CreatedAt"
    limit greatest(1,least(coalesce(p_take,10),25))
  ) task;
  return v_result;
end;
$$;


ALTER FUNCTION "public"."multideck_dexter_domain_todo"("p_company_id" "uuid", "p_search" "text", "p_take" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_domain_usage"("p_company_id" "uuid", "p_search" "text", "p_take" integer) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
  with usage_state as (
    select public._multideck_usage_categories(p_company_id) as value
  ), sanitized as (
    select jsonb_set(
      usage_state.value,
      '{categories}',
      coalesce((
        select jsonb_agg(category.value - 'teamUsage')
        from jsonb_array_elements(usage_state.value -> 'categories') category(value)
      ), '[]'::jsonb),
      false
    ) as value
    from usage_state
  )
  select case
    when exists (
      select 1 from public."cmp_Users" workspace_user
      where workspace_user."Auth_User_ID" = auth.uid()
        and workspace_user."Company_ID" = p_company_id
        and coalesce(workspace_user."User_AccessStatus", 'active') = 'active'
    ) then jsonb_build_array(
      sanitized.value || jsonb_build_object('recordId', p_company_id, 'scope', 'workspace')
    )
    else '[]'::jsonb
  end
  from sanitized;
$$;


ALTER FUNCTION "public"."multideck_dexter_domain_usage"("p_company_id" "uuid", "p_search" "text", "p_take" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_domain_warehouse"("p_company_id" "uuid", "p_search" "text", "p_take" integer) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
with parameters as (
  select greatest(1, least(coalesce(p_take, 10), 15)) as take
), company_facilities as (
  select facility.* from public."WMS_Facilities" facility
  join public."cmp_Offices" office on office."Office_ID" = facility."WMSFacility_OrgOfficeID" and office."Company_ID" = p_company_id
  where not facility."WMSFacility_IsDeleted"
), order_rows as (
  select jsonb_build_object(
    'recordId', orders."WMSOrder_ID", 'orderNumber', orders."WMSOrder_OrderNumber", 'type', orders."WMSOrder_TypeCode",
    'status', orders."WMSOrder_StatusCode", 'priority', orders."WMSOrder_PriorityCode", 'facility', facility."WMSFacility_Code",
    'customerReference', orders."WMSOrder_CustomerReference", 'requestedDate', orders."WMSOrder_RequestedDate",
    'containerNumber', orders."WMSOrder_ContainerNumber", 'releaseGateStatus', orders."WMSOrder_ReleaseGateStatusCode",
    'searchEvidence', evidence.value - 'matched'
  ) value, coalesce((evidence.value->>'confidence')::numeric, 0) rank, orders."WMSOrder_UpdatedAt" updated_at
  from public."WMS_Orders" orders join company_facilities facility on facility."WMSFacility_ID" = orders."WMSOrder_FacilityID"
  cross join lateral public._multideck_dexter_search_evidence(p_search, jsonb_build_object(
    'orderNumber', orders."WMSOrder_OrderNumber", 'customerReference', orders."WMSOrder_CustomerReference",
    'containerNumber', orders."WMSOrder_ContainerNumber", 'facility', facility."WMSFacility_Code", 'status', orders."WMSOrder_StatusCode"
  ), array['orderNumber','customerReference','containerNumber']::text[]) evidence(value)
  where not orders."WMSOrder_IsDeleted" and (evidence.value->>'matched')::boolean
  order by rank desc, updated_at desc limit (select take from parameters)
), inventory_rows as (
  select jsonb_build_object(
    'recordId', balance."WMSBalance_ID", 'facilityId', balance."WMSBalance_FacilityID",
    'sku', item."WMSItem_SKU", 'description', item."WMSItem_Description", 'quantityBasis', item."WMSItem_QuantityBasisCode",
    'facility', facility."WMSFacility_Code", 'locationCode', location."WMSLocation_Code",
    'handlingUnitCode', hu."WMSHU_Code", 'handlingUnitType', hu."WMSHU_TypeCode",
    'inventoryStatus', balance."WMSBalance_InventoryStatusCode", 'customsStatus', balance."WMSBalance_CustomsStatusCode",
    'onHand', balance."WMSBalance_OnHandQuantity", 'available', balance."WMSBalance_AvailableQuantity",
    'reserved', balance."WMSBalance_ReservedQuantity", 'held', balance."WMSBalance_HeldQuantity",
    'uom', balance."WMSBalance_UOMCode", 'isBonded', balance."WMSBalance_IsBonded",
    'lastMovementAt', balance."WMSBalance_LastMovementAt", 'searchEvidence', evidence.value - 'matched'
  ) value, coalesce((evidence.value->>'confidence')::numeric, 0) rank, balance."WMSBalance_UpdatedAt" updated_at
  from public."WMS_InventoryBalances" balance
  join company_facilities facility on facility."WMSFacility_ID" = balance."WMSBalance_FacilityID"
  join public."WMS_Items" item on item."WMSItem_ID" = balance."WMSBalance_ItemID"
  left join public."WMS_Locations" location on location."WMSLocation_ID" = balance."WMSBalance_LocationID"
  left join public."WMS_HandlingUnits" hu on hu."WMSHU_ID" = balance."WMSBalance_HU_ID"
  cross join lateral public._multideck_dexter_search_evidence(p_search, jsonb_build_object(
    'sku', item."WMSItem_SKU", 'description', item."WMSItem_Description", 'facility', facility."WMSFacility_Code",
    'locationCode', location."WMSLocation_Code", 'handlingUnitCode', hu."WMSHU_Code",
    'inventoryStatus', balance."WMSBalance_InventoryStatusCode"
  ), array['sku','handlingUnitCode','locationCode']::text[]) evidence(value)
  where not item."WMSItem_IsDeleted" and balance."WMSBalance_OnHandQuantity" > 0 and (evidence.value->>'matched')::boolean
  order by rank desc, updated_at desc limit (select take from parameters)
), handling_unit_rows as (
  select jsonb_build_object(
    'recordId', hu."WMSHU_ID", 'code', hu."WMSHU_Code", 'type', hu."WMSHU_TypeCode",
    'lifecycleStatus', hu."WMSHU_LifecycleStatusCode", 'inventoryStatus', hu."WMSHU_InventoryStatusCode",
    'facility', facility."WMSFacility_Code", 'locationCode', location."WMSLocation_Code",
    'lineCount', count(balance."WMSBalance_ID"), 'totalQuantity', coalesce(sum(balance."WMSBalance_OnHandQuantity"), 0),
    'searchEvidence', evidence.value - 'matched'
  ) value, coalesce((evidence.value->>'confidence')::numeric, 0) rank, hu."WMSHU_UpdatedAt" updated_at
  from public."WMS_HandlingUnits" hu join company_facilities facility on facility."WMSFacility_ID" = hu."WMSHU_FacilityID"
  left join public."WMS_Locations" location on location."WMSLocation_ID" = hu."WMSHU_LocationID"
  left join public."WMS_InventoryBalances" balance on balance."WMSBalance_HU_ID" = hu."WMSHU_ID" and balance."WMSBalance_OnHandQuantity" > 0
  cross join lateral public._multideck_dexter_search_evidence(p_search, jsonb_build_object(
    'handlingUnitCode', hu."WMSHU_Code", 'type', hu."WMSHU_TypeCode", 'facility', facility."WMSFacility_Code", 'locationCode', location."WMSLocation_Code"
  ), array['handlingUnitCode','locationCode']::text[]) evidence(value)
  where not hu."WMSHU_IsDeleted" and (evidence.value->>'matched')::boolean
  group by hu."WMSHU_ID", facility."WMSFacility_Code", location."WMSLocation_Code", evidence.value
  order by rank desc, updated_at desc limit (select take from parameters)
), exception_rows as (
  select jsonb_build_object(
    'recordId', exception."WMSException_ID", 'balanceId', exception."WMSException_BalanceID",
    'title', exception."WMSException_Title", 'description', exception."WMSException_Description",
    'type', exception."WMSException_TypeCode", 'status', exception."WMSException_StatusCode",
    'severity', exception."WMSException_SeverityCode", 'facility', facility."WMSFacility_Code",
    'expectedLocationCode', expected."WMSLocation_Code", 'actualLocationCode', actual."WMSLocation_Code",
    'raisedAt', exception."WMSException_RaisedAt", 'searchEvidence', evidence.value - 'matched'
  ) value, coalesce((evidence.value->>'confidence')::numeric, 0) rank, exception."WMSException_RaisedAt" raised_at
  from public."WMS_Exceptions" exception join company_facilities facility on facility."WMSFacility_ID" = exception."WMSException_FacilityID"
  left join public."WMS_Locations" expected on expected."WMSLocation_ID" = exception."WMSException_ExpectedLocationID"
  left join public."WMS_Locations" actual on actual."WMSLocation_ID" = exception."WMSException_ActualLocationID"
  cross join lateral public._multideck_dexter_search_evidence(p_search, jsonb_build_object(
    'title', exception."WMSException_Title", 'type', exception."WMSException_TypeCode", 'status', exception."WMSException_StatusCode",
    'facility', facility."WMSFacility_Code", 'expectedLocationCode', expected."WMSLocation_Code", 'actualLocationCode', actual."WMSLocation_Code"
  ), array['expectedLocationCode','actualLocationCode']::text[]) evidence(value)
  where exception."WMSException_ResolvedAt" is null and (evidence.value->>'matched')::boolean
  order by rank desc, raised_at desc limit (select take from parameters)
)
select jsonb_build_object(
  'overview', jsonb_build_object(
    'activeFacilities', (select count(*) from company_facilities where "WMSFacility_IsActive"),
    'openOrders', (select count(*) from public."WMS_Orders" orders join company_facilities f on f."WMSFacility_ID"=orders."WMSOrder_FacilityID" where not orders."WMSOrder_IsDeleted" and orders."WMSOrder_StatusCode" not in ('complete','cancelled')),
    'openExceptions', (select count(*) from public."WMS_Exceptions" exception join company_facilities f on f."WMSFacility_ID"=exception."WMSException_FacilityID" where exception."WMSException_ResolvedAt" is null),
    'openHandlingUnits', (select count(*) from public."WMS_HandlingUnits" hu join company_facilities f on f."WMSFacility_ID"=hu."WMSHU_FacilityID" where not hu."WMSHU_IsDeleted" and hu."WMSHU_LifecycleStatusCode" in ('open','sealed')),
    'heldStockQuantity', (select coalesce(sum(balance."WMSBalance_HeldQuantity"),0) from public."WMS_InventoryBalances" balance join company_facilities f on f."WMSFacility_ID"=balance."WMSBalance_FacilityID")
  ),
  'orders', coalesce((select jsonb_agg(value order by rank desc, updated_at desc) from order_rows),'[]'::jsonb),
  'inventory', coalesce((select jsonb_agg(value order by rank desc, updated_at desc) from inventory_rows),'[]'::jsonb),
  'handlingUnits', coalesce((select jsonb_agg(value order by rank desc, updated_at desc) from handling_unit_rows),'[]'::jsonb),
  'exceptions', coalesce((select jsonb_agg(value order by rank desc, raised_at desc) from exception_rows),'[]'::jsonb)
);
$$;


ALTER FUNCTION "public"."multideck_dexter_domain_warehouse"("p_company_id" "uuid", "p_search" "text", "p_take" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_domain_warehouse_execution"("p_company_id" "uuid", "p_search" "text" DEFAULT NULL::"text", "p_take" integer DEFAULT 10) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
with permitted as (
  select public._multideck_dexter_can_manage(user_row."User_ID") allowed
  from public."cmp_Users" user_row where user_row."Auth_User_ID"=auth.uid() and user_row."Company_ID"=p_company_id limit 1
), company_facilities as (
  select facility."WMSFacility_ID",facility."WMSFacility_Code",facility."WMSFacility_Name"
  from public."WMS_Facilities" facility join public."cmp_Offices" office on office."Office_ID"=facility."WMSFacility_OrgOfficeID" and office."Company_ID"=p_company_id
  where not facility."WMSFacility_IsDeleted"
), rows as (
  select jsonb_build_object(
    'recordId',task."WMSTask_ID",'taskType',task."WMSTask_TypeCode",'taskStatus',task."WMSTask_StatusCode",
    'quantity',task."WMSTask_Quantity",'completedQuantity',task."WMSTask_CompletedQuantity",'uomCode',task."WMSTask_UOMCode",
    'facilityId',facility."WMSFacility_ID",'facility',facility."WMSFacility_Code",'facilityName',facility."WMSFacility_Name",
    'orderId',warehouse_order."WMSOrder_ID",'orderNumber',warehouse_order."WMSOrder_OrderNumber",'orderType',warehouse_order."WMSOrder_TypeCode",
    'sourceTypeCode',warehouse_order."WMSOrder_SourceTypeCode",'sourceReference',warehouse_order."WMSOrder_SourceReference",'sourceRecordId',warehouse_order."WMSOrder_SourceRecordID",
    'customerOrgId',warehouse_order."WMSOrder_CustomerOrgID",'orderLineId',task."WMSTask_OrderLineID",
    'itemId',item."WMSItem_ID",'sku',item."WMSItem_SKU",'description',item."WMSItem_Description",
    'sourceLocationId',task."WMSTask_SourceLocationID",'sourceLocation',source_location."WMSLocation_Code",
    'targetLocationId',task."WMSTask_TargetLocationID",'targetLocation',target_location."WMSLocation_Code",
    'createdAt',task."WMSTask_CreatedAt",'completedAt',task."WMSTask_CompletedAt"
  ) value,task."WMSTask_CreatedAt" created_at
  from public."WMS_Tasks" task join company_facilities facility on facility."WMSFacility_ID"=task."WMSTask_FacilityID"
  left join public."WMS_Orders" warehouse_order on warehouse_order."WMSOrder_ID"=task."WMSTask_OrderID"
  left join public."WMS_Items" item on item."WMSItem_ID"=task."WMSTask_ItemID"
  left join public."WMS_Locations" source_location on source_location."WMSLocation_ID"=task."WMSTask_SourceLocationID"
  left join public."WMS_Locations" target_location on target_location."WMSLocation_ID"=task."WMSTask_TargetLocationID"
  where task."WMSTask_TypeCode" in ('putaway','pick') and (nullif(btrim(p_search),'') is null or concat_ws(' ',task."WMSTask_TypeCode",task."WMSTask_StatusCode",warehouse_order."WMSOrder_OrderNumber",warehouse_order."WMSOrder_SourceReference",item."WMSItem_SKU",item."WMSItem_Description",source_location."WMSLocation_Code",target_location."WMSLocation_Code") ilike '%'||btrim(p_search)||'%')
  order by task."WMSTask_CreatedAt" desc limit greatest(1,least(coalesce(p_take,10),25))
)
select case when coalesce((select allowed from permitted),false) then coalesce((select jsonb_agg(value order by created_at desc) from rows),'[]'::jsonb) else '[]'::jsonb end;
$$;


ALTER FUNCTION "public"."multideck_dexter_domain_warehouse_execution"("p_company_id" "uuid", "p_search" "text", "p_take" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_duplicate_sent_email_draft"("p_message_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_context record;
  v_message public."AI_Messages";
  v_new_message_id uuid := gen_random_uuid();
  v_new_draft jsonb;
  v_content jsonb;
  v_response_version integer;
begin
  select * into v_context from public._multideck_dexter_context();

  select message.* into v_message
  from public."AI_Messages" message
  join public."AI_Conversations" conversation
    on conversation."AICNV_ID" = message."AIMSG_ConversationID"
  where message."AIMSG_ID" = p_message_id
    and message."AIMSG_Role" = 'assistant'
    and conversation."AICNV_CompanyID" = v_context.company_id
    and conversation."AICNV_OwnerUserID" = v_context.user_id
    and jsonb_typeof(message."AIMSG_ContentJSON" #> '{metadata,emailDraft}') = 'object'
  for update;
  if not found then
    raise exception 'This Dexter email draft is unavailable.' using errcode = 'P0002';
  end if;

  if coalesce(
    v_message."AIMSG_ContentJSON" #>> '{metadata,emailDraft,delivery,status}',
    'draft'
  ) <> 'sent' then
    raise exception 'Only a sent email can be copied into a new draft.' using errcode = '22023';
  end if;

  v_new_draft := jsonb_set(
    jsonb_set(
      v_message."AIMSG_ContentJSON" #> '{metadata,emailDraft}',
      '{id}',
      to_jsonb(gen_random_uuid()::text),
      true
    ),
    '{delivery}',
    jsonb_build_object('status', 'draft'),
    true
  );

  v_response_version := greatest(
    coalesce((v_message."AIMSG_ContentJSON" #>> '{metadata,responseVersion}')::integer, 1) + 1,
    2
  );
  v_content := jsonb_set(
    jsonb_set(
      v_message."AIMSG_ContentJSON",
      '{metadata,emailDraft}',
      v_new_draft,
      true
    ),
    '{metadata,responseVersion}',
    to_jsonb(v_response_version),
    true
  );

  insert into public."AI_Messages" (
    "AIMSG_ID",
    "AIMSG_ConversationID",
    "AIMSG_ParentMessageID",
    "AIMSG_Role",
    "AIMSG_ModelID",
    "AIMSG_ContentText",
    "AIMSG_ContentJSON",
    "AIMSG_SecurityClass",
    "AIMSG_IsTrainingCandidate",
    "AIMSG_IsTrainingAllowed",
    "AIMSG_CreatedAt",
    "AIMSG_CreatedBy"
  )
  values (
    v_new_message_id,
    v_message."AIMSG_ConversationID",
    v_message."AIMSG_ParentMessageID",
    'assistant',
    v_message."AIMSG_ModelID",
    v_message."AIMSG_ContentText",
    v_content,
    v_message."AIMSG_SecurityClass",
    false,
    false,
    now(),
    v_context.user_id
  );

  return jsonb_build_object(
    'messageId', v_new_message_id,
    'draft', v_new_draft
  );
end;
$$;


ALTER FUNCTION "public"."multideck_dexter_duplicate_sent_email_draft"("p_message_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_email_thread_folders"("p_thread_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_context record;
  v_result jsonb;
begin
  select * into v_context from public._multideck_dexter_context();
  if not public._multideck_dexter_has_permission(v_context.user_id, 'Email.Read')
     or not public._multideck_dexter_has_permission(v_context.user_id, 'Email.AIRead') then
    raise exception 'You do not have permission to use email with Dexter.' using errcode = '42501';
  end if;

  with permitted_mailboxes as materialized (
    select mailbox_id
    from public._multideck_dexter_email_mailboxes(v_context.user_id, v_context.company_id)
  ),
  visible_folders as (
    select distinct
      folder."CommMailFolder_ID" as folder_id,
      folder."CommMailFolder_DisplayName" as display_name,
      folder."CommMailFolder_RoleCode" as role_code,
      folder."CommMailFolder_CatalogTypeCode" as catalog_type
    from public."Comm_Messages" as message
    join permitted_mailboxes as permitted
      on permitted.mailbox_id = message."CommMessage_MailboxID"
    join public."Comm_MessageFolders" as membership
      on membership."CommMessageFolder_MessageID" = message."CommMessage_ID"
    join public."Comm_MailFolders" as folder
      on folder."CommMailFolder_ID" = membership."CommMessageFolder_FolderID"
    where message."CommMessage_ThreadID" = p_thread_id
      and not message."CommMessage_IsDeleted"
      and not folder."CommMailFolder_IsHidden"
      and folder."CommMailFolder_CanHoldMessages"
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', visible_folders.folder_id,
    'displayName', visible_folders.display_name,
    'role', visible_folders.role_code,
    'kind', visible_folders.catalog_type
  ) order by visible_folders.display_name), '[]'::jsonb)
  into v_result
  from visible_folders;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."multideck_dexter_email_thread_folders"("p_thread_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_execute_action"("p_action" "text", "p_arguments" "jsonb", "p_access_mode" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $_$
declare
  v_context record;
  v_code text := lower(btrim(coalesce(p_action, '')));
  v_mode text := lower(btrim(coalesce(p_access_mode, '')));
  v_action_function text;
  v_result jsonb;
begin
  select * into v_context from public._multideck_dexter_context();
  if not public._multideck_dexter_can_manage(v_context.user_id) then
    raise exception 'You do not have permission to let Dexter change workspace data.'
      using errcode = '42501';
  end if;
  if v_mode not in ('approve', 'full') then
    raise exception 'Choose Approve or Full access before changing data.' using errcode = '22023';
  end if;

  select action."AIDexterAction_Function"
  into v_action_function
  from public."sys_AIDexterActions" action
  join public."sys_AIDexterDataDomains" domain
    on domain."AIDexterDomain_Code" = action."AIDexterAction_DomainCode"
   and domain."AIDexterDomain_IsActive"
  where action."AIDexterAction_Code" = v_code
    and action."AIDexterAction_IsActive";

  if v_action_function is null then
    raise exception 'That Dexter action is not available in this workspace.' using errcode = '22023';
  end if;

  execute format('select public.%I($1, $2, $3)', v_action_function)
  into v_result
  using v_context.company_id, v_context.user_id, coalesce(p_arguments, '{}'::jsonb);

  insert into public."AI_DexterActionAudit" (
    "AIDexterAudit_CompanyID",
    "AIDexterAudit_UserID",
    "AIDexterAudit_ActionCode",
    "AIDexterAudit_AccessMode",
    "AIDexterAudit_ArgumentsJSON",
    "AIDexterAudit_ResultJSON"
  ) values (
    v_context.company_id,
    v_context.user_id,
    v_code,
    v_mode,
    coalesce(p_arguments, '{}'::jsonb),
    coalesce(v_result, '{}'::jsonb)
  );

  return jsonb_build_object('action', v_code, 'updated', true, 'result', v_result);
end;
$_$;


ALTER FUNCTION "public"."multideck_dexter_execute_action"("p_action" "text", "p_arguments" "jsonb", "p_access_mode" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_execute_prepared_action"("p_prepared_action_id" "uuid", "p_company_id" "uuid", "p_user_id" "uuid", "p_conversation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $_$
declare v_context record; v_prepared public."AI_DexterPreparedActions"; v_intent public."AI_DexterIntentPlans";
  v_action_function text; v_required jsonb; v_domain_required jsonb; v_result jsonb; v_error_code text; v_error_message text;
begin
  if auth.role()<>'service_role' then raise exception 'server_only' using errcode='42501'; end if;
  select p_company_id as company_id,p_user_id as user_id into v_context;
  select * into v_prepared from public."AI_DexterPreparedActions" prepared
  where prepared."AIDexterPrepared_ID"=p_prepared_action_id
    and prepared."AIDexterPrepared_CompanyID"=v_context.company_id
    and prepared."AIDexterPrepared_UserID"=v_context.user_id
    and prepared."AIDexterPrepared_ConversationID" is not distinct from p_conversation_id
  for update;
  if not found then
    return public._multideck_dexter_deny_prepared_action(p_prepared_action_id,v_context.company_id,v_context.user_id,'prepared_action_unavailable','That prepared action is unavailable.','prepared_action_missing');
  end if;
  if v_prepared."AIDexterPrepared_Status"='succeeded' then
    insert into public."AI_DexterSecurityEvents"("AIDexterSecurityEvent_CompanyID","AIDexterSecurityEvent_UserID","AIDexterSecurityEvent_Kind","AIDexterSecurityEvent_Severity","AIDexterSecurityEvent_MetadataJSON")
    values(v_context.company_id,v_context.user_id,'prepared_action_safe_retry','info',jsonb_build_object('preparedActionId',p_prepared_action_id));
    return jsonb_build_object('action',v_prepared."AIDexterPrepared_ActionCode",'updated',true,'result',coalesce(v_prepared."AIDexterPrepared_ResultJSON",'{}'::jsonb),'replayed',true);
  end if;
  if v_prepared."AIDexterPrepared_Status"<>'prepared' then
    return public._multideck_dexter_deny_prepared_action(p_prepared_action_id,v_context.company_id,v_context.user_id,'prepared_action_replayed','That prepared action has already been used.','prepared_action_replay_denied');
  end if;
  if v_prepared."AIDexterPrepared_ExpiresAt"<=now() then
    update public."AI_DexterPreparedActions" set "AIDexterPrepared_Status"='expired',"AIDexterPrepared_CompletedAt"=now() where "AIDexterPrepared_ID"=p_prepared_action_id;
    return public._multideck_dexter_deny_prepared_action(p_prepared_action_id,v_context.company_id,v_context.user_id,'prepared_action_expired','That prepared action has expired.','prepared_action_replay_denied');
  end if;
  if v_prepared."AIDexterPrepared_ConversationID" is not null and not exists(
    select 1 from public."AI_Conversations" c where c."AICNV_ID"=v_prepared."AIDexterPrepared_ConversationID"
      and c."AICNV_CompanyID"=v_context.company_id and c."AICNV_OwnerUserID"=v_context.user_id and c."AICNV_Channel"='chat' and c."AICNV_EndedAt" is null
  ) then
    return public._multideck_dexter_deny_prepared_action(p_prepared_action_id,v_context.company_id,v_context.user_id,'conversation_unavailable','That conversation is no longer active.','cross_scope_action_denied');
  end if;
  select * into v_intent from public."AI_DexterIntentPlans" i where i."AIDexterIntent_ID"=v_prepared."AIDexterPrepared_IntentID"
    and i."AIDexterIntent_CompanyID"=v_context.company_id and i."AIDexterIntent_UserID"=v_context.user_id
    and i."AIDexterIntent_ClientSessionID"=v_prepared."AIDexterPrepared_ClientSessionID"
    and i."AIDexterIntent_ConversationID" is not distinct from v_prepared."AIDexterPrepared_ConversationID"
    and i."AIDexterIntent_AccessMode"=v_prepared."AIDexterPrepared_AccessMode" and i."AIDexterIntent_ExpiresAt">now();
  if not found or not coalesce(v_intent."AIDexterIntent_AllowedActionsJSON",'[]'::jsonb)?v_prepared."AIDexterPrepared_ActionCode" then
    return public._multideck_dexter_deny_prepared_action(p_prepared_action_id,v_context.company_id,v_context.user_id,'intent_mismatch','That action no longer matches the operator request.','intent_mismatch');
  end if;
  if v_prepared."AIDexterPrepared_AccessMode"='full' and v_prepared."AIDexterPrepared_TargetID" is not null
    and not (v_prepared."AIDexterPrepared_ActionCode" in ('record_booking_dangerous_goods','record_booking_security_evidence','record_booking_milestone','replace_booking_allocations','update_quote_cargo','update_booking_cargo','update_booking_container','update_booking_route','change_booking_route_mode','update_booking_shipment_value','update_booking_weight_override')
      and v_prepared."AIDexterPrepared_ApprovedAt" is not null)
    and not coalesce(v_intent."AIDexterIntent_TargetConstraintsJSON",'[]'::jsonb)?v_prepared."AIDexterPrepared_TargetID"::text then
    return public._multideck_dexter_deny_prepared_action(p_prepared_action_id,v_context.company_id,v_context.user_id,'target_outside_operator_intent','That target was not authorised by the operator.','target_substitution_denied');
  end if;
  if v_prepared."AIDexterPrepared_AccessMode"='full' and not exists(
    select 1 from public."AI_DexterConversationGrants" g where g."AIDexterGrant_ID"=v_prepared."AIDexterPrepared_GrantID"
      and g."AIDexterGrant_CompanyID"=v_context.company_id and g."AIDexterGrant_UserID"=v_context.user_id
      and g."AIDexterGrant_ClientSessionID"=v_prepared."AIDexterPrepared_ClientSessionID" and g."AIDexterGrant_Status"='active'
      and g."AIDexterGrant_ExpiresAt">now() and g."AIDexterGrant_ConversationID" is not distinct from v_prepared."AIDexterPrepared_ConversationID"
  ) then
    return public._multideck_dexter_deny_prepared_action(p_prepared_action_id,v_context.company_id,v_context.user_id,'full_access_expired','Full access is no longer active for this conversation.','full_access_replay_denied');
  end if;
  if not public._multideck_dexter_can_manage(v_context.user_id) then
    return public._multideck_dexter_deny_prepared_action(p_prepared_action_id,v_context.company_id,v_context.user_id,'permission_denied','You no longer have permission to let Dexter change workspace data.','permission_denied');
  end if;
  select action."AIDexterAction_Function",action."AIDexterAction_RequiredPermissionsJSON",domain."AIDexterDomain_RequiredPermissionsJSON"
  into v_action_function,v_required,v_domain_required from public."sys_AIDexterActions" action
  join public."sys_AIDexterDataDomains" domain on domain."AIDexterDomain_Code"=action."AIDexterAction_DomainCode" and domain."AIDexterDomain_IsActive"
  where action."AIDexterAction_Code"=v_prepared."AIDexterPrepared_ActionCode" and action."AIDexterAction_IsActive";
  if v_action_function is null or not public._multideck_dexter_has_permissions(v_context.user_id,v_required)
    or not public._multideck_dexter_has_permissions(v_context.user_id,v_domain_required) then
    return public._multideck_dexter_deny_prepared_action(p_prepared_action_id,v_context.company_id,v_context.user_id,'permission_denied','You no longer have permission to run that Dexter action.','permission_denied');
  end if;
  update public."AI_DexterPreparedActions" set "AIDexterPrepared_Status"='executing',"AIDexterPrepared_AttemptedAt"=now() where "AIDexterPrepared_ID"=p_prepared_action_id;
  insert into public."AI_DexterActionAudit"(
    "AIDexterAudit_CompanyID","AIDexterAudit_UserID","AIDexterAudit_ActionCode","AIDexterAudit_AccessMode",
    "AIDexterAudit_ArgumentsJSON","AIDexterAudit_ResultJSON","AIDexterAudit_PreparedActionID","AIDexterAudit_IntentID",
    "AIDexterAudit_ConversationID","AIDexterAudit_Status","AIDexterAudit_IdempotencyKey","AIDexterAudit_AttemptedAt"
  ) values(v_context.company_id,v_context.user_id,v_prepared."AIDexterPrepared_ActionCode",v_prepared."AIDexterPrepared_AccessMode",
    v_prepared."AIDexterPrepared_ArgumentsJSON",'{}'::jsonb,p_prepared_action_id,v_prepared."AIDexterPrepared_IntentID",
    v_prepared."AIDexterPrepared_ConversationID",'attempted',v_prepared."AIDexterPrepared_IdempotencyKey",now());
  begin

    if v_prepared."AIDexterPrepared_ArgumentsJSON" ? '_document_evidence'
      and jsonb_typeof(v_prepared."AIDexterPrepared_ArgumentsJSON"->'_document_evidence') is distinct from 'object' then
      raise exception 'Document provenance must be an audit object.' using errcode='22023';
    end if;
    execute format('select public.%I($1,$2,$3)',v_action_function) into v_result
      using v_context.company_id,v_context.user_id,v_prepared."AIDexterPrepared_ArgumentsJSON"-'_document_evidence';
    update public."AI_DexterPreparedActions" set "AIDexterPrepared_Status"='succeeded',"AIDexterPrepared_ResultJSON"=coalesce(v_result,'{}'::jsonb),"AIDexterPrepared_CompletedAt"=now() where "AIDexterPrepared_ID"=p_prepared_action_id;
    insert into public."AI_DexterActionAudit" (
      "AIDexterAudit_CompanyID","AIDexterAudit_UserID","AIDexterAudit_ActionCode","AIDexterAudit_AccessMode",
      "AIDexterAudit_ArgumentsJSON","AIDexterAudit_ResultJSON","AIDexterAudit_PreparedActionID","AIDexterAudit_IntentID",
      "AIDexterAudit_ConversationID","AIDexterAudit_Status","AIDexterAudit_IdempotencyKey","AIDexterAudit_AttemptedAt","AIDexterAudit_CompletedAt"
    ) values (v_context.company_id,v_context.user_id,v_prepared."AIDexterPrepared_ActionCode",v_prepared."AIDexterPrepared_AccessMode",
      v_prepared."AIDexterPrepared_ArgumentsJSON",coalesce(v_result,'{}'::jsonb),p_prepared_action_id,v_prepared."AIDexterPrepared_IntentID",
      v_prepared."AIDexterPrepared_ConversationID",'succeeded',v_prepared."AIDexterPrepared_IdempotencyKey",now(),now());
    return jsonb_build_object('action',v_prepared."AIDexterPrepared_ActionCode",'updated',true,'result',v_result);
  exception when others then
    get stacked diagnostics v_error_code=returned_sqlstate,v_error_message=message_text;
    update public."AI_DexterPreparedActions" set "AIDexterPrepared_Status"='failed',"AIDexterPrepared_ErrorCode"=v_error_code,"AIDexterPrepared_ErrorMessage"=left(v_error_message,500),"AIDexterPrepared_CompletedAt"=now() where "AIDexterPrepared_ID"=p_prepared_action_id;
    insert into public."AI_DexterActionAudit" (
      "AIDexterAudit_CompanyID","AIDexterAudit_UserID","AIDexterAudit_ActionCode","AIDexterAudit_AccessMode",
      "AIDexterAudit_ArgumentsJSON","AIDexterAudit_ResultJSON","AIDexterAudit_PreparedActionID","AIDexterAudit_IntentID",
      "AIDexterAudit_ConversationID","AIDexterAudit_Status","AIDexterAudit_IdempotencyKey","AIDexterAudit_ErrorCode","AIDexterAudit_ErrorMessage","AIDexterAudit_AttemptedAt","AIDexterAudit_CompletedAt"
    ) values (v_context.company_id,v_context.user_id,v_prepared."AIDexterPrepared_ActionCode",v_prepared."AIDexterPrepared_AccessMode",
      v_prepared."AIDexterPrepared_ArgumentsJSON",'{}'::jsonb,p_prepared_action_id,v_prepared."AIDexterPrepared_IntentID",
      v_prepared."AIDexterPrepared_ConversationID",'failed',v_prepared."AIDexterPrepared_IdempotencyKey",v_error_code,left(v_error_message,500),now(),now());
    return jsonb_build_object('action',v_prepared."AIDexterPrepared_ActionCode",'updated',false,'error',jsonb_build_object('code',v_error_code,'message',left(v_error_message,500)));
  end;
end; $_$;


ALTER FUNCTION "public"."multideck_dexter_execute_prepared_action"("p_prepared_action_id" "uuid", "p_company_id" "uuid", "p_user_id" "uuid", "p_conversation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_get_conversation"("p_conversation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_user_id uuid;
  v_company_id uuid;
  v_result jsonb;
begin
  select context.user_id, context.company_id
  into v_user_id, v_company_id
  from public._multideck_dexter_context() context;

  select public._multideck_dexter_conversation_json(
    p_conversation_id,
    v_user_id,
    v_company_id
  ) into v_result;

  if v_result is null then
    raise exception 'This conversation does not exist or is outside your workspace.'
      using errcode = 'P0002';
  end if;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."multideck_dexter_get_conversation"("p_conversation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_get_conversation_page"("p_conversation_id" "uuid", "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $_$
declare
  v_context record;
  v_conversation record;
  v_limit integer := least(greatest(coalesce(p_limit, 50), 1), 100);
  v_offset integer := least(greatest(coalesce(p_offset, 0), 0), 1000000);
  v_total bigint := 0;
  v_messages jsonb := '[]'::jsonb;
begin
  select * into v_context from public._multideck_dexter_context();

  select
    conversation."AICNV_ID" as id,
    coalesce(conversation."AICNV_Title", 'Dexter conversation') as title,
    coalesce(conversation."AICNV_SummaryText", '') as summary,
    conversation."AICNV_UpdatedAt" as updated_at
  into v_conversation
  from public."AI_Conversations" conversation
  where conversation."AICNV_ID" = p_conversation_id
    and conversation."AICNV_CompanyID" = v_context.company_id
    and conversation."AICNV_OwnerUserID" = v_context.user_id
    and conversation."AICNV_Channel" = 'chat'
    and conversation."AICNV_EndedAt" is null
    and conversation."AICNV_DomainCode" in ('multideck', 'warehouse');

  if not found then
    raise exception 'This conversation does not exist or is outside your workspace.' using errcode = 'P0002';
  end if;

  select count(*)
  into v_total
  from public."AI_Messages" message
  where message."AIMSG_ConversationID" = p_conversation_id
    and message."AIMSG_ContentText" is not null;

  select coalesce(jsonb_agg(page.value order by page.created_at, page.id), '[]'::jsonb)
  into v_messages
  from (
    select
      message."AIMSG_ID" as id,
      message."AIMSG_CreatedAt" as created_at,
      jsonb_build_object(
        'id', message."AIMSG_ID",
        'role', message."AIMSG_Role",
        'content', message."AIMSG_ContentText",
        'createdAt', message."AIMSG_CreatedAt",
        'specialist', nullif(message."AIMSG_ContentJSON" ->> 'specialist', ''),
        'attachments', case when jsonb_typeof(message."AIMSG_ContentJSON" -> 'attachments') = 'array'
          then message."AIMSG_ContentJSON" -> 'attachments' else '[]'::jsonb end,
        'parentResponseMessageId', nullif(message."AIMSG_ContentJSON" #>> '{metadata,parentResponseMessageId}', ''),
        'pendingAction', case when jsonb_typeof(message."AIMSG_ContentJSON" #> '{metadata,pendingAction}') = 'object'
          then message."AIMSG_ContentJSON" #> '{metadata,pendingAction}' else null end,
        'reasoningSummary', nullif(message."AIMSG_ContentJSON" #>> '{metadata,reasoningSummary}', ''),
        'emailAttachments', case when jsonb_typeof(message."AIMSG_ContentJSON" #> '{metadata,emailAttachments}') = 'array'
          then message."AIMSG_ContentJSON" #> '{metadata,emailAttachments}' else '[]'::jsonb end,
        'emailDraft', case when jsonb_typeof(message."AIMSG_ContentJSON" #> '{metadata,emailDraft}') = 'object'
          then message."AIMSG_ContentJSON" #> '{metadata,emailDraft}' else null end,
        'responseToUserMessageId', nullif(message."AIMSG_ContentJSON" #>> '{metadata,responseToUserMessageId}', ''),
        'responseVersion', case when coalesce(message."AIMSG_ContentJSON" #>> '{metadata,responseVersion}', '') ~ '^[1-9][0-9]*$'
          then (message."AIMSG_ContentJSON" #>> '{metadata,responseVersion}')::integer else null end
      ) as value
    from public."AI_Messages" message
    where message."AIMSG_ConversationID" = p_conversation_id
      and message."AIMSG_ContentText" is not null
    order by message."AIMSG_CreatedAt" desc, message."AIMSG_ID" desc
    offset v_offset
    limit v_limit
  ) page;

  return jsonb_build_object(
    'id', v_conversation.id,
    'title', v_conversation.title,
    'summary', v_conversation.summary,
    'updatedAt', v_conversation.updated_at,
    'messages', v_messages,
    'messageTotal', v_total,
    'messageOffset', v_offset,
    'messageLimit', v_limit,
    'hasOlderMessages', v_offset + jsonb_array_length(v_messages) < v_total
  );
end;
$_$;


ALTER FUNCTION "public"."multideck_dexter_get_conversation_page"("p_conversation_id" "uuid", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."multideck_dexter_get_conversation_page"("p_conversation_id" "uuid", "p_limit" integer, "p_offset" integer) IS 'Returns one owner-private newest-offset page of a Dexter conversation, in chronological display order. This changes existing read transport only and adds no new write or Watching capability.';



CREATE OR REPLACE FUNCTION "public"."multideck_dexter_get_usage"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_company_id uuid;
  v_period_start timestamptz := date_trunc('month', now());
  v_period_end timestamptz := date_trunc('month', now()) + interval '1 month';
  v_trend_start date := (date_trunc('week', now()) - interval '5 weeks')::date;
  v_result jsonb;
begin
  select context.company_id
  into v_company_id
  from public._multideck_dexter_context() context;

  with scoped_rows as (
    select
      message."AIMSG_ID" as id,
      coalesce(conversation."AICNV_Title", 'Dexter conversation') as title,
      case lower(coalesce(message."AIMSG_ContentJSON" ->> 'model', 'fast'))
        when 'smart' then 'smart'
        when 'worker' then 'worker'
        else 'fast'
      end as model,
      coalesce(
        nullif(message."AIMSG_ContentJSON" #>> '{metadata,providerModel}', ''),
        case lower(coalesce(message."AIMSG_ContentJSON" ->> 'model', 'fast'))
          when 'worker' then 'gpt-5.6-terra'
          else 'gpt-5.6-luna'
        end
      ) as provider_model,
      case lower(coalesce(
        nullif(message."AIMSG_ContentJSON" #>> '{metadata,reasoningEffort}', ''),
        case lower(coalesce(message."AIMSG_ContentJSON" ->> 'model', 'fast'))
          when 'smart' then 'high'
          else 'medium'
        end
      ))
        when 'low' then 'low'
        when 'high' then 'high'
        when 'xhigh' then 'xhigh'
        else 'medium'
      end as reasoning_effort,
      greatest(coalesce(message."AIMSG_PromptTokens", 0), 0) as input_tokens,
      greatest(coalesce(message."AIMSG_CompletionTokens", 0), 0) as output_tokens,
      message."AIMSG_ConversationID" as conversation_id,
      message."AIMSG_CreatedAt" as created_at
    from public."AI_Messages" message
    join public."AI_Conversations" conversation
      on conversation."AICNV_ID" = message."AIMSG_ConversationID"
    where message."AIMSG_Role" = 'assistant'
      and message."AIMSG_CreatedAt" >= least(v_period_start, v_trend_start::timestamptz)
      and message."AIMSG_CreatedAt" < v_period_end
      and conversation."AICNV_CompanyID" = v_company_id
      and conversation."AICNV_Channel" = 'chat'
      and conversation."AICNV_DomainCode" in ('multideck', 'warehouse')
  ),
  month_rows as (
    select * from scoped_rows where created_at >= v_period_start
  ),
  trend as (
    select jsonb_agg(
      jsonb_build_object(
        'weekStart', week.week_start,
        'actions', (select count(*) from scoped_rows row_data where row_data.created_at >= week.week_start::timestamptz and row_data.created_at < (week.week_start + 7)::timestamptz),
        'tokens', (select coalesce(sum(row_data.input_tokens + row_data.output_tokens), 0) from scoped_rows row_data where row_data.created_at >= week.week_start::timestamptz and row_data.created_at < (week.week_start + 7)::timestamptz)
      )
      order by week.week_start
    ) as value
    from (select v_trend_start + (series.index * 7) as week_start from generate_series(0, 5) series(index)) week
  ),
  model_totals as (
    select
      lane.model,
      lane.position,
      coalesce(max(month.provider_model), lane.default_provider_model) as provider_model,
      coalesce(max(month.reasoning_effort), lane.default_reasoning_effort) as reasoning_effort,
      coalesce(sum(month.input_tokens), 0) as input_tokens,
      coalesce(sum(month.output_tokens), 0) as output_tokens
    from (
      values
        ('fast'::text, 1, 'gpt-5.6-luna'::text, 'medium'::text),
        ('smart', 2, 'gpt-5.6-luna', 'high'),
        ('worker', 3, 'gpt-5.6-terra', 'medium')
    ) as lane(model, position, default_provider_model, default_reasoning_effort)
    left join month_rows month on month.model = lane.model
    group by lane.model, lane.position, lane.default_provider_model, lane.default_reasoning_effort
  ),
  model_breakdown as (
    select jsonb_agg(
      jsonb_build_object(
        'model', model,
        'providerModel', provider_model,
        'reasoningEffort', reasoning_effort,
        'inputTokens', input_tokens,
        'outputTokens', output_tokens,
        'totalTokens', input_tokens + output_tokens
      )
      order by position
    ) as value
    from model_totals
  ),
  recent as (
    select coalesce(jsonb_agg(item.value order by item.created_at desc), '[]'::jsonb) as value
    from (
      select jsonb_build_object('id', month.id, 'title', month.title, 'inputTokens', month.input_tokens, 'outputTokens', month.output_tokens, 'totalTokens', month.input_tokens + month.output_tokens, 'createdAt', month.created_at) as value, month.created_at
      from month_rows month order by month.created_at desc limit 50
    ) item
  )
  select jsonb_build_object(
    'periodStart', v_period_start,
    'periodEnd', v_period_end,
    'includedActionsLimit', 10000,
    'actionsUsed', (select count(*) from month_rows),
    'trackedActions', (select count(*) from month_rows where input_tokens + output_tokens > 0),
    'conversationCount', (select count(distinct conversation_id) from month_rows),
    'inputTokens', coalesce((select sum(input_tokens) from month_rows), 0),
    'outputTokens', coalesce((select sum(output_tokens) from month_rows), 0),
    'totalTokens', coalesce((select sum(input_tokens + output_tokens) from month_rows), 0),
    'modelBreakdown', coalesce((select value from model_breakdown), '[]'::jsonb),
    'trend', coalesce((select value from trend), '[]'::jsonb),
    'recentEntries', coalesce((select value from recent), '[]'::jsonb)
  ) into v_result;

  return v_result || public._multideck_dexter_allowance_state(v_company_id);
end;
$$;


ALTER FUNCTION "public"."multideck_dexter_get_usage"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_get_usage_history"("p_sort" "text" DEFAULT 'newest'::"text", "p_limit" integer DEFAULT 10, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_company_id uuid;
  v_period_start timestamptz := date_trunc('month', now());
  v_period_end timestamptz := date_trunc('month', now()) + interval '1 month';
  v_sort text := case when lower(coalesce(p_sort, 'newest')) = 'heaviest' then 'heaviest' else 'newest' end;
  v_limit integer := least(greatest(coalesce(p_limit, 10), 1), 50);
  v_offset integer := least(greatest(coalesce(p_offset, 0), 0), 1000000);
  v_total bigint := 0;
  v_rows jsonb := '[]'::jsonb;
begin
  select context.company_id
  into v_company_id
  from public._multideck_dexter_context() context;

  select count(*)
  into v_total
  from public."AI_Messages" message
  join public."AI_Conversations" conversation
    on conversation."AICNV_ID" = message."AIMSG_ConversationID"
  where message."AIMSG_Role" = 'assistant'
    and message."AIMSG_CreatedAt" >= v_period_start
    and message."AIMSG_CreatedAt" < v_period_end
    and conversation."AICNV_CompanyID" = v_company_id
    and conversation."AICNV_Channel" = 'chat'
    and conversation."AICNV_DomainCode" in ('multideck', 'warehouse');

  select coalesce(jsonb_agg(page.value order by page.position), '[]'::jsonb)
  into v_rows
  from (
    select
      row_number() over (order by
        case when v_sort = 'heaviest' then greatest(coalesce(message."AIMSG_PromptTokens", 0), 0) + greatest(coalesce(message."AIMSG_CompletionTokens", 0), 0) end desc,
        message."AIMSG_CreatedAt" desc,
        message."AIMSG_ID" desc
      ) as position,
      jsonb_build_object(
        'id', message."AIMSG_ID",
        'title', coalesce(conversation."AICNV_Title", 'Dexter conversation'),
        'inputTokens', greatest(coalesce(message."AIMSG_PromptTokens", 0), 0),
        'outputTokens', greatest(coalesce(message."AIMSG_CompletionTokens", 0), 0),
        'totalTokens', greatest(coalesce(message."AIMSG_PromptTokens", 0), 0) + greatest(coalesce(message."AIMSG_CompletionTokens", 0), 0),
        'createdAt', message."AIMSG_CreatedAt"
      ) as value
    from public."AI_Messages" message
    join public."AI_Conversations" conversation
      on conversation."AICNV_ID" = message."AIMSG_ConversationID"
    where message."AIMSG_Role" = 'assistant'
      and message."AIMSG_CreatedAt" >= v_period_start
      and message."AIMSG_CreatedAt" < v_period_end
      and conversation."AICNV_CompanyID" = v_company_id
      and conversation."AICNV_Channel" = 'chat'
      and conversation."AICNV_DomainCode" in ('multideck', 'warehouse')
    order by
      case when v_sort = 'heaviest' then greatest(coalesce(message."AIMSG_PromptTokens", 0), 0) + greatest(coalesce(message."AIMSG_CompletionTokens", 0), 0) end desc,
      message."AIMSG_CreatedAt" desc,
      message."AIMSG_ID" desc
    offset v_offset
    limit v_limit
  ) page;

  return jsonb_build_object(
    'rows', v_rows,
    'total', v_total,
    'offset', v_offset,
    'limit', v_limit,
    'sort', v_sort
  );
end;
$$;


ALTER FUNCTION "public"."multideck_dexter_get_usage_history"("p_sort" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."multideck_dexter_get_usage_history"("p_sort" "text", "p_limit" integer, "p_offset" integer) IS 'Returns one exact, bounded page of the authenticated tenant workspace Dexter usage history. This changes Admin transport only and does not add a Dexter write or Watching capability.';



CREATE OR REPLACE FUNCTION "public"."multideck_dexter_get_writing_profile"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_context record;
  v_profile public."AI_DexterWritingProfiles";
  v_source jsonb;
  v_exists boolean := false;
begin
  select * into v_context from public._multideck_dexter_context();
  select * into v_profile
  from public."AI_DexterWritingProfiles" profile
  where profile."AIDexterWritingProfile_CompanyID" = v_context.company_id
    and profile."AIDexterWritingProfile_UserID" = v_context.user_id;
  v_exists := found;

  begin
    v_source := public._multideck_dexter_writing_profile_source_for(v_context.company_id, v_context.user_id, 1, null);
  exception when insufficient_privilege then
    v_source := jsonb_build_object('eligibleCount', 0, 'messages', '[]'::jsonb, 'latestMessageAt', null);
  end;

  return jsonb_build_object(
    'exists', v_exists,
    'enabled', coalesce(v_profile."AIDexterWritingProfile_IsEnabled", false),
    'status', coalesce(v_profile."AIDexterWritingProfile_StatusCode", 'not_started'),
    'profileText', coalesce(v_profile."AIDexterWritingProfile_ProfileText", ''),
    'eligibleMessageCount', greatest(coalesce((v_source ->> 'eligibleCount')::integer, v_profile."AIDexterWritingProfile_EligibleMessageCount", 0), 0),
    'analysedMessageCount', coalesce(v_profile."AIDexterWritingProfile_AnalysedMessageCount", 0),
    'consentedAt', v_profile."AIDexterWritingProfile_ConsentAt",
    'lastGeneratedAt', v_profile."AIDexterWritingProfile_LastGeneratedAt",
    'nextRefreshAt', v_profile."AIDexterWritingProfile_NextRefreshAt",
    'lastError', v_profile."AIDexterWritingProfile_LastError"
  );
end;
$$;


