CREATE OR REPLACE FUNCTION "public"."multideck_dexter_prepare_conversation"("p_conversation_id" "uuid" DEFAULT NULL::"uuid", "p_retry_message_id" "uuid" DEFAULT NULL::"uuid", "p_history_message_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $_$
declare
  v_user_id uuid;
  v_company_id uuid;
  v_history jsonb := '[]'::jsonb;
  v_retry_created_at timestamptz;
begin
  select context.user_id, context.company_id
  into v_user_id, v_company_id
  from public._multideck_dexter_context() context;

  if p_conversation_id is not null and not exists (
    select 1
    from public."AI_Conversations" conversation
    where conversation."AICNV_ID" = p_conversation_id
      and conversation."AICNV_CompanyID" = v_company_id
      and conversation."AICNV_OwnerUserID" = v_user_id
      and conversation."AICNV_Channel" = 'chat'
      and conversation."AICNV_EndedAt" is null
      and conversation."AICNV_DomainCode" in ('multideck', 'warehouse')
  ) then
    raise exception 'This conversation does not exist or is outside your workspace.'
      using errcode = 'P0002';
  end if;

  if p_retry_message_id is not null then
    if p_conversation_id is null then
      raise exception 'Choose a saved message to retry.'
        using errcode = '22023';
    end if;

    select message."AIMSG_CreatedAt"
    into v_retry_created_at
    from public."AI_Messages" message
    where message."AIMSG_ID" = p_retry_message_id
      and message."AIMSG_ConversationID" = p_conversation_id
      and message."AIMSG_Role" = 'user'
      and message."AIMSG_UserID" = v_user_id;

    if not found then
      raise exception 'That message cannot be retried in this conversation.'
        using errcode = 'P0002';
    end if;
  end if;

  if p_conversation_id is not null then
    if coalesce(cardinality(p_history_message_ids), 0) > 30 then
      raise exception 'Dexter can keep up to 30 selected messages in context.'
        using errcode = '22023';
    end if;

    select coalesce(
      jsonb_agg(
        jsonb_build_object(
          'id', item.message_id,
          'role', item.role,
          'content', item.content
        )
        order by item.created_at, item.message_id
      ),
      '[]'::jsonb
    )
    into v_history
    from (
      select
        message."AIMSG_ID" as message_id,
        message."AIMSG_Role" as role,
        message."AIMSG_ContentText" as content,
        message."AIMSG_CreatedAt" as created_at
      from public."AI_Messages" message
      where message."AIMSG_ConversationID" = p_conversation_id
        and message."AIMSG_Role" in ('user', 'assistant')
        and message."AIMSG_ContentText" is not null
        and (
          (
            p_history_message_ids is not null
            and message."AIMSG_ID" = any(p_history_message_ids)
          )
          or (
            p_history_message_ids is null
            and (
              p_retry_message_id is null
              or message."AIMSG_CreatedAt" < v_retry_created_at
              or (
                message."AIMSG_CreatedAt" = v_retry_created_at
                and message."AIMSG_ID" < p_retry_message_id
              )
            )
          )
        )
        and (
          p_history_message_ids is not null
          or message."AIMSG_Role" = 'user'
          or (
            message."AIMSG_Role" = 'assistant'
            and (
              (
                nullif(
                  message."AIMSG_ContentJSON" #>> '{metadata,responseToUserMessageId}',
                  ''
                ) is not null
                and coalesce(
                  case
                    when coalesce(
                      message."AIMSG_ContentJSON" #>> '{metadata,responseVersion}',
                      ''
                    ) ~ '^[1-9][0-9]*$'
                      then (message."AIMSG_ContentJSON" #>> '{metadata,responseVersion}')::integer
                    else 1
                  end,
                  1
                ) = (
                  select max(
                    case
                      when coalesce(
                        versioned."AIMSG_ContentJSON" #>> '{metadata,responseVersion}',
                        ''
                      ) ~ '^[1-9][0-9]*$'
                        then (versioned."AIMSG_ContentJSON" #>> '{metadata,responseVersion}')::integer
                      else 1
                    end
                  )
                  from public."AI_Messages" versioned
                  where versioned."AIMSG_ConversationID" = p_conversation_id
                    and versioned."AIMSG_Role" = 'assistant'
                    and versioned."AIMSG_ContentJSON" #>> '{metadata,responseToUserMessageId}' =
                      message."AIMSG_ContentJSON" #>> '{metadata,responseToUserMessageId}'
                )
              )
              or (
                nullif(
                  message."AIMSG_ContentJSON" #>> '{metadata,responseToUserMessageId}',
                  ''
                ) is null
                and not exists (
                  select 1
                  from public."AI_Messages" versioned
                  where versioned."AIMSG_ConversationID" = p_conversation_id
                    and versioned."AIMSG_Role" = 'assistant'
                    and versioned."AIMSG_ContentJSON" #>> '{metadata,responseToUserMessageId}' = (
                      select previous_user."AIMSG_ID"::text
                      from public."AI_Messages" previous_user
                      where previous_user."AIMSG_ConversationID" = p_conversation_id
                        and previous_user."AIMSG_Role" = 'user'
                        and (
                          previous_user."AIMSG_CreatedAt" < message."AIMSG_CreatedAt"
                          or (
                            previous_user."AIMSG_CreatedAt" = message."AIMSG_CreatedAt"
                            and previous_user."AIMSG_ID" < message."AIMSG_ID"
                          )
                        )
                      order by previous_user."AIMSG_CreatedAt" desc, previous_user."AIMSG_ID" desc
                      limit 1
                    )
                )
              )
            )
          )
        )
      order by message."AIMSG_CreatedAt" desc, message."AIMSG_ID" desc
      limit 30
    ) item;
  end if;

  return jsonb_build_object(
    'conversationId', p_conversation_id,
    'retryMessageId', p_retry_message_id,
    'history', v_history
  );
end;
$_$;


ALTER FUNCTION "public"."multideck_dexter_prepare_conversation"("p_conversation_id" "uuid", "p_retry_message_id" "uuid", "p_history_message_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_provider_history"("p_company_id" "uuid", "p_user_id" "uuid", "p_auth_user_id" "uuid", "p_conversation_id" "uuid", "p_message_id" "uuid", "p_history" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_history jsonb;
begin
 if coalesce(auth.role(),'')<>'service_role' then raise exception 'server_only' using errcode='42501';end if;
 if not exists(select 1 from public."cmp_Users" where "User_ID"=p_user_id and "Company_ID"=p_company_id
  and "Auth_User_ID"=p_auth_user_id and coalesce("User_AccessStatus",'active')='active')
 or not exists(select 1 from public."AI_Conversations" c join public."AI_Messages" m on m."AIMSG_ConversationID"=c."AICNV_ID"
  where c."AICNV_ID"=p_conversation_id and c."AICNV_CompanyID"=p_company_id and c."AICNV_OwnerUserID"=p_user_id
  and c."AICNV_Channel"='chat' and c."AICNV_EndedAt" is null and m."AIMSG_ID"=p_message_id and m."AIMSG_Role"='assistant')
 then raise exception 'provider_history_unavailable' using errcode='42501';end if;
 if p_history is not null then
  if p_history->>'model' is distinct from 'gpt-6-astra'
   or coalesce(p_history->>'baseEffort','') not in ('low','medium','high','xhigh','max')
   or coalesce(p_history->>'lastEffort','') not in ('low','medium','high','xhigh','max')
   or jsonb_typeof(p_history->'items') is distinct from 'array'
   or jsonb_typeof(p_history->'contract') is distinct from 'string'
  then raise exception 'invalid_provider_history' using errcode='22023';end if;
  insert into public."AI_DexterProviderHistory"(message_id,conversation_id,company_id,user_id,history)
   values(p_message_id,p_conversation_id,p_company_id,p_user_id,p_history) on conflict(message_id) do nothing;
 end if;
 select history into v_history from public."AI_DexterProviderHistory" where message_id=p_message_id
  and conversation_id=p_conversation_id and company_id=p_company_id and user_id=p_user_id;
 if p_history is not null and v_history is distinct from p_history then raise exception 'provider_history_immutable' using errcode='22023';end if;
 return v_history;
end $$;


ALTER FUNCTION "public"."multideck_dexter_provider_history"("p_company_id" "uuid", "p_user_id" "uuid", "p_auth_user_id" "uuid", "p_conversation_id" "uuid", "p_message_id" "uuid", "p_history" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_query_domain"("p_domain" "text", "p_search" "text" DEFAULT NULL::"text", "p_take" integer DEFAULT 10) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $_$
declare v_context record; v_code text:=lower(btrim(coalesce(p_domain,''))); v_query_function text; v_required jsonb; v_result jsonb;
begin
  select * into v_context from public._multideck_dexter_context();
  select domain."AIDexterDomain_QueryFunction", domain."AIDexterDomain_RequiredPermissionsJSON"
  into v_query_function, v_required from public."sys_AIDexterDataDomains" domain
  where domain."AIDexterDomain_Code"=v_code and domain."AIDexterDomain_IsActive";
  if v_query_function is null then raise exception 'That Dexter data domain is not available in this workspace.' using errcode='22023'; end if;
  if not public._multideck_dexter_has_permissions(v_context.user_id, v_required) then
    raise exception 'You do not have permission to read that workspace data.' using errcode='42501';
  end if;
  execute format('select public.%I($1,$2,$3)', v_query_function) into v_result
    using v_context.company_id, nullif(btrim(p_search),''), greatest(1,least(coalesce(p_take,10),25));
  return jsonb_build_object('domain',v_code,'data',coalesce(v_result,'[]'::jsonb));
end; $_$;


ALTER FUNCTION "public"."multideck_dexter_query_domain"("p_domain" "text", "p_search" "text", "p_take" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_quotes_before_branch_direction_20260904"("p_company_id" "uuid", "p_search" "text", "p_take" integer) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(jsonb_agg(
    item.value || jsonb_strip_nulls(jsonb_build_object(
      'followUpDelivery', case when latest.response_link_id is null then null else jsonb_strip_nulls(jsonb_build_object(
        'status', latest.follow_up_status_code,
        'scheduledAt', latest.follow_up_next_attempt_at,
        'sentAt', latest.follow_up_sent_at,
        'attempts', latest.follow_up_attempt_count,
        'needsAttention', latest.follow_up_status_code = 'failed',
        'evidence', jsonb_build_object('sourceTable', 'quote_api.customer_response_links', 'sourceId', latest.response_link_id)
      )) end
    )) order by item.ordinality
  ), '[]'::jsonb)
  from jsonb_array_elements(
    public.multideck_dexter_domain_quotes_pre_followup_20260904(p_company_id, p_search, p_take)
  ) with ordinality item(value, ordinality)
  left join lateral (
    select link.response_link_id, link.follow_up_status_code, link.follow_up_next_attempt_at,
      link.follow_up_sent_at, link.follow_up_attempt_count
    from quote_api.customer_response_links link
    where link.quote_id = nullif(item.value->>'recordId', '')::uuid
    order by link.created_at desc limit 1
  ) latest on true;
$$;


ALTER FUNCTION "public"."multideck_dexter_quotes_before_branch_direction_20260904"("p_company_id" "uuid", "p_search" "text", "p_take" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_read_email_thread"("p_providers" "text"[], "p_thread_id" "uuid", "p_before" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_context record;
  v_providers text[];
  v_mailbox_id uuid;
  v_provider text;
  v_subject text;
  v_synced_at timestamptz;
  v_index_status text;
  v_result jsonb;
begin
  select * into v_context from public._multideck_dexter_context();
  if not public._multideck_dexter_has_permission(v_context.user_id, 'Email.Read')
     or not public._multideck_dexter_has_permission(v_context.user_id, 'Email.AIRead') then
    raise exception 'You do not have permission to use email with Dexter.' using errcode = '42501';
  end if;

  select coalesce(array_agg(distinct lower(btrim(provider))), array[]::text[])
  into v_providers
  from unnest(coalesce(p_providers, array[]::text[])) provider
  where lower(btrim(provider)) in ('gmail', 'outlook');
  if cardinality(v_providers) = 0
     or cardinality(v_providers) <> cardinality(coalesce(p_providers, array[]::text[])) then
    raise exception 'Choose Gmail, Outlook, or both as the email source.' using errcode = '22023';
  end if;

  select
    message."CommMessage_MailboxID",
    permitted.provider,
    coalesce(nullif(message."CommMessage_Subject", ''), '(No subject)'),
    mailbox."CommMailbox_LastSyncedAt",
    coalesce(mailbox."CommMailbox_IndexStatus", 'pending')
  into v_mailbox_id, v_provider, v_subject, v_synced_at, v_index_status
  from public."Comm_Messages" message
  join public._multideck_dexter_email_mailboxes(v_context.user_id, v_context.company_id) permitted
    on permitted.mailbox_id = message."CommMessage_MailboxID"
   and permitted.provider = any(v_providers)
  join public."Comm_Mailboxes" mailbox
    on mailbox."CommMailbox_ID" = message."CommMessage_MailboxID"
  where message."CommMessage_ThreadID" = p_thread_id
    and not message."CommMessage_IsDeleted"
    and not message."CommMessage_IsDraft"
    and not message."CommMessage_IsSpam"
  order by coalesce(
    message."CommMessage_MessageDate",
    message."CommMessage_ReceivedAt",
    message."CommMessage_SentAt",
    message."CommMessage_CreatedAt"
  ) desc
  limit 1;

  if v_mailbox_id is null or exists (
    select 1
    from public."Comm_Messages" message
    where message."CommMessage_ThreadID" = p_thread_id
      and not message."CommMessage_IsDeleted"
      and not exists (
        select 1
        from public._multideck_dexter_email_mailboxes(v_context.user_id, v_context.company_id) permitted
        where permitted.mailbox_id = message."CommMessage_MailboxID"
          and permitted.provider = any(v_providers)
      )
  ) then
    raise exception 'This email thread was not found.' using errcode = 'P0002';
  end if;

  with eligible as (
    select
      message.*,
      coalesce(
        message."CommMessage_MessageDate",
        message."CommMessage_ReceivedAt",
        message."CommMessage_SentAt",
        message."CommMessage_CreatedAt"
      ) as occurred_at
    from public."Comm_Messages" message
    where message."CommMessage_ThreadID" = p_thread_id
      and message."CommMessage_MailboxID" = v_mailbox_id
      and not message."CommMessage_IsDeleted"
      and not message."CommMessage_IsDraft"
      and not message."CommMessage_IsSpam"
      and (
        p_before is null
        or coalesce(
          message."CommMessage_MessageDate",
          message."CommMessage_ReceivedAt",
          message."CommMessage_SentAt",
          message."CommMessage_CreatedAt"
        ) < p_before
      )
      and not exists (
        select 1
        from public."Comm_MessageFolders" membership
        join public."Comm_MailFolders" folder
          on folder."CommMailFolder_ID" = membership."CommMessageFolder_FolderID"
        where membership."CommMessageFolder_MessageID" = message."CommMessage_ID"
          and folder."CommMailFolder_RoleCode" in ('drafts', 'spam', 'trash')
      )
  ),
  newest as (
    select *
    from eligible
    order by occurred_at desc, "CommMessage_ID" desc
    limit 31
  ),
  page as (
    select *
    from newest
    order by occurred_at desc, "CommMessage_ID" desc
    limit 30
  ),
  message_rows as (
    select jsonb_build_object(
      'messageId', page."CommMessage_ID",
      'threadId', page."CommMessage_ThreadID",
      'mailboxId', page."CommMessage_MailboxID",
      'direction', case when page."CommMessage_IsInbound" then 'inbound' else 'outbound' end,
      'subject', coalesce(nullif(page."CommMessage_Subject", ''), '(No subject)'),
      'occurredAt', page.occurred_at,
      'bodyText', left(coalesce(page."CommMessage_BodyText", page."CommMessage_BodyPreview", ''), 12000),
      'bodyWasRedacted', page."CommMessage_IsBodyRedacted",
      'delivery', public.comm_email_delivery_evidence(page."CommMessage_ID"),
      'recipients', coalesce((
        select jsonb_agg(recipient_row.value order by recipient_row.sort_order, recipient_row.sort_address)
        from (
          select
            jsonb_build_object(
              'address', recipient."CommRecipient_Address",
              'displayName', recipient."CommRecipient_DisplayNameSnapshot",
              'role', recipient."CommRecipient_RecipientTypeCode"
            ) as value,
            case recipient."CommRecipient_RecipientTypeCode"
              when 'from' then 0 when 'to' then 1 when 'cc' then 2 else 3
            end as sort_order,
            recipient."CommRecipient_NormalizedAddress" as sort_address
          from public."Comm_MessageRecipients" recipient
          where recipient."CommRecipient_MessageID" = page."CommMessage_ID"
        ) recipient_row
      ), '[]'::jsonb),
      'attachments', coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'attachmentId', attachment."CommAttachment_ID",
            'fileName', attachment."CommAttachment_FileName",
            'mimeType', attachment."CommAttachment_MimeType",
            'sizeBytes', attachment."CommAttachment_FileSizeBytes",
            '_citation', jsonb_build_object(
              'title', attachment."CommAttachment_FileName",
              'url', '/inbox?provider=' || v_provider || '&mailbox=' || v_mailbox_id || '&thread=' || p_thread_id,
              'description', 'Email attachment in ' || v_subject
            )
          )
          order by attachment."CommAttachment_CreatedAt", attachment."CommAttachment_ID"
        )
        from public."Comm_MessageAttachments" attachment
        where attachment."CommAttachment_MessageID" = page."CommMessage_ID"
          and not attachment."CommAttachment_IsInline"
      ), '[]'::jsonb),
      '_citation', jsonb_build_object(
        'title', v_subject,
        'url', '/inbox?provider=' || v_provider || '&mailbox=' || v_mailbox_id || '&thread=' || p_thread_id,
        'description', case v_provider when 'gmail' then 'Gmail email thread' else 'Outlook email thread' end
      )
    ) as value,
    page.occurred_at,
    page."CommMessage_ID" as message_id
    from page
  )
  select jsonb_build_object(
    'threadId', p_thread_id,
    'mailboxId', v_mailbox_id,
    'provider', v_provider,
    'subject', v_subject,
    'syncedAt', v_synced_at,
    'indexStatus', v_index_status,
    'stale', v_synced_at is null
      or v_synced_at < now() - interval '30 minutes'
      or v_index_status = 'error',
    'messages', coalesce(jsonb_agg(message_rows.value order by message_rows.occurred_at, message_rows.message_id), '[]'::jsonb),
    'hasMore', (select count(*) from newest) > 30,
    'nextCursor', case when (select count(*) from newest) > 30 then (select min(occurred_at) from page) else null end,
    '_citation', jsonb_build_object(
      'title', v_subject,
      'url', '/inbox?provider=' || v_provider || '&mailbox=' || v_mailbox_id || '&thread=' || p_thread_id,
      'description', case v_provider when 'gmail' then 'Gmail email thread' else 'Outlook email thread' end
    )
  )
  into v_result
  from message_rows;

  return coalesce(v_result, jsonb_build_object(
    'threadId', p_thread_id,
    'mailboxId', v_mailbox_id,
    'provider', v_provider,
    'subject', v_subject,
    'syncedAt', v_synced_at,
    'indexStatus', v_index_status,
    'stale', v_synced_at is null
      or v_synced_at < now() - interval '30 minutes'
      or v_index_status = 'error',
    'messages', '[]'::jsonb,
    'hasMore', false,
    'nextCursor', null,
    '_citation', jsonb_build_object(
      'title', v_subject,
      'url', '/inbox?provider=' || v_provider || '&mailbox=' || v_mailbox_id || '&thread=' || p_thread_id,
      'description', case v_provider when 'gmail' then 'Gmail email thread' else 'Outlook email thread' end
    )
  ));
end;
$$;


ALTER FUNCTION "public"."multideck_dexter_read_email_thread"("p_providers" "text"[], "p_thread_id" "uuid", "p_before" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_recent_email"("p_providers" "text"[], "p_direction" "text", "p_after" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_before" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_take" integer DEFAULT 10) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare actor record;providers text[];take_count integer:=greatest(1,least(coalesce(p_take,10),20));result jsonb;coverage_start timestamptz:=now()-interval '12 months';
begin
 select * into actor from public._multideck_dexter_context();
 if not public._multideck_dexter_has_permission(actor.user_id,'Email.Read') or not public._multideck_dexter_has_permission(actor.user_id,'Email.AIRead') then
  raise exception 'You do not have permission to use email with Dexter.' using errcode='42501';end if;
 select coalesce(array_agg(distinct lower(btrim(p))),array[]::text[]) into providers from unnest(p_providers) p where lower(btrim(p)) in ('gmail','outlook');
 if cardinality(providers)=0 or cardinality(providers)<>cardinality(p_providers) then raise exception 'Choose Gmail, Outlook, or both as the email source.' using errcode='22023';end if;
 if p_direction is null or p_direction not in ('received','sent','all') then raise exception 'Choose received, sent or all email.' using errcode='22023';end if;
 if p_after is not null and p_before is not null and p_after>=p_before then raise exception 'The email date range is invalid.' using errcode='22023';end if;
 with permitted as materialized (
  select a.*,m."CommMailbox_LastSyncedAt" synced_at,coalesce(m."CommMailbox_IndexStatus",'pending') index_status
  from public._multideck_dexter_email_mailboxes(actor.user_id,actor.company_id) a
  join public."Comm_Mailboxes" m on m."CommMailbox_ID"=a.mailbox_id where a.provider=any(providers)
 ), candidates as (
  select m.*,p.provider,p.synced_at,p.index_status,coalesce(m."CommMessage_MessageDate",m."CommMessage_ReceivedAt",m."CommMessage_SentAt",m."CommMessage_CreatedAt") occurred_at
  from public."Comm_Messages" m join permitted p on p.mailbox_id=m."CommMessage_MailboxID"
  where m."CommMessage_ChannelCode"='email' and not m."CommMessage_IsDeleted" and not m."CommMessage_IsDraft" and not m."CommMessage_IsSpam"
   and m."CommMessage_ThreadID" is not null
   and (p_direction='all' or (p_direction='received' and m."CommMessage_IsInbound") or (p_direction='sent' and not m."CommMessage_IsInbound"))
   and not exists(select 1 from public."Comm_MessageFolders" f join public."Comm_MailFolders" folder on folder."CommMailFolder_ID"=f."CommMessageFolder_FolderID"
    where f."CommMessageFolder_MessageID"=m."CommMessage_ID" and folder."CommMailFolder_RoleCode" in ('drafts','spam','trash'))
 ), ordered as materialized (
  select * from candidates where occurred_at>=greatest(coalesce(p_after,coverage_start),coverage_start) and (p_before is null or occurred_at<p_before)
  order by occurred_at desc,"CommMessage_ID" desc limit take_count+1
 ), output_rows as (
  select jsonb_build_object('threadId',o."CommMessage_ThreadID",'matchMessageId',o."CommMessage_ID",'mailboxId',o."CommMessage_MailboxID",'provider',o.provider,
   'subject',o."CommMessage_Subject",'occurredAt',o.occurred_at,'direction',case when o."CommMessage_IsInbound" then 'received' else 'sent' end,
   'hasAttachments',o."CommMessage_HasAttachments",'syncedAt',o.synced_at,'indexStatus',o.index_status,
   'participants',coalesce((select jsonb_agg(jsonb_build_object('address',r."CommRecipient_Address",'displayName',r."CommRecipient_DisplayNameSnapshot",'role',r."CommRecipient_RecipientTypeCode")) from public."Comm_MessageRecipients" r where r."CommRecipient_MessageID"=o."CommMessage_ID"),'[]'::jsonb),
   '_citation',jsonb_build_object('title',coalesce(o."CommMessage_Subject",'Email'),'url','/inbox?provider='||o.provider||'&mailbox='||o."CommMessage_MailboxID"||'&thread='||o."CommMessage_ThreadID",'description','Email thread')
  ) value,o.occurred_at,o."CommMessage_ID" id from ordered o order by o.occurred_at desc,o."CommMessage_ID" desc limit take_count
 ) select jsonb_build_object('items',coalesce((select jsonb_agg(value order by occurred_at desc,id desc) from output_rows),'[]'::jsonb),
  'hasMore',(select count(*) from ordered)>take_count,'direction',p_direction,'coreCoverageStart',coverage_start,
  'outsideRetentionWindow',(p_before is not null and p_before<=coverage_start) or (p_after is not null and p_after<coverage_start),
  'coverage',coalesce((select jsonb_agg(jsonb_build_object('mailboxId',mailbox_id,'provider',provider,'syncedAt',synced_at,'indexStatus',index_status,'stale',synced_at is null or synced_at<now()-interval '30 minutes' or index_status='error')) from permitted),'[]'::jsonb),
  'scope','Authorised synced email retained in Multideck; excludes drafts, spam and trash. Ordered by message date, not keyword relevance.') into result;
 return result;
end $$;


ALTER FUNCTION "public"."multideck_dexter_recent_email"("p_providers" "text"[], "p_direction" "text", "p_after" timestamp with time zone, "p_before" timestamp with time zone, "p_take" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_record_email_draft_delivery"("p_message_id" "uuid", "p_send_request_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_context record;
  v_message public."AI_Messages";
  v_send public."Comm_SendRequests";
  v_status text;
begin
  select * into v_context from public._multideck_dexter_context();
  select message.* into v_message
  from public."AI_Messages" message
  join public."AI_Conversations" conversation on conversation."AICNV_ID" = message."AIMSG_ConversationID"
  where message."AIMSG_ID" = p_message_id
    and message."AIMSG_Role" = 'assistant'
    and conversation."AICNV_CompanyID" = v_context.company_id
    and conversation."AICNV_OwnerUserID" = v_context.user_id
    and jsonb_typeof(message."AIMSG_ContentJSON" #> '{metadata,emailDraft}') = 'object'
  for update;
  if not found then
    raise exception 'This Dexter email draft is unavailable.' using errcode = 'P0002';
  end if;

  select send.* into v_send
  from public."Comm_SendRequests" send
  where send."CommSend_ID" = p_send_request_id
    and send."CommSend_RequestedBy" = v_context.user_id;
  if not found then
    raise exception 'This email send receipt is unavailable.' using errcode = 'P0002';
  end if;

  v_status := case lower(v_send."CommSend_StatusCode")
    when 'sent' then 'sent'
    when 'delivered' then 'sent'
    when 'failed' then 'failed'
    else 'queued'
  end;

  update public."AI_Messages"
  set "AIMSG_ContentJSON" = jsonb_set(
    "AIMSG_ContentJSON",
    '{metadata,emailDraft,delivery}',
    jsonb_strip_nulls(jsonb_build_object(
      'status', v_status,
      'sendRequestId', v_send."CommSend_ID",
      'messageId', v_send."CommSend_MessageID",
      'threadId', v_send."CommSend_ThreadID",
      'updatedAt', v_send."CommSend_UpdatedAt"
    )),
    true
  )
  where "AIMSG_ID" = p_message_id;

  perform public._multideck_dexter_writing_profile_audit(
    null, v_context.company_id, v_context.user_id,
    case v_status when 'sent' then 'email_sent' when 'failed' then 'email_failed' else 'email_queued' end,
    v_status, 0
  );

  return jsonb_build_object(
    'status', v_status,
    'sendRequestId', v_send."CommSend_ID",
    'messageId', v_send."CommSend_MessageID",
    'threadId', v_send."CommSend_ThreadID",
    'updatedAt', v_send."CommSend_UpdatedAt"
  );
end;
$$;


ALTER FUNCTION "public"."multideck_dexter_record_email_draft_delivery"("p_message_id" "uuid", "p_send_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_record_provider_draft_delivery"("p_message_id" "uuid", "p_draft_message_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_context record;
  v_message public."AI_Messages";
  v_provider_draft public."Comm_Messages";
  v_delivery jsonb;
begin
  select * into v_context from public._multideck_dexter_context();

  select message.* into v_message
  from public."AI_Messages" message
  join public."AI_Conversations" conversation
    on conversation."AICNV_ID" = message."AIMSG_ConversationID"
  where message."AIMSG_ID" = p_message_id
    and message."AIMSG_Role" = 'assistant'
    and conversation."AICNV_CompanyID" = v_context.company_id
    and conversation."AICNV_OwnerUserID" = v_context.user_id
    and jsonb_typeof(message."AIMSG_ContentJSON" #> '{metadata,emailDraft}') = 'object'
  for update;
  if not found then
    raise exception 'This Dexter email draft is unavailable.' using errcode = 'P0002';
  end if;

  select draft.* into v_provider_draft
  from public."Comm_Messages" draft
  where draft."CommMessage_ID" = p_draft_message_id
    and draft."CommMessage_CreatedBy" = v_context.user_id
    and draft."CommMessage_IsDraft" = true
    and draft."CommMessage_IsDeleted" = false
    and draft."CommMessage_StatusCode" = 'draft'
    and nullif(draft."CommMessage_ProviderMessageID", '') is not null;
  if not found then
    raise exception 'This provider email draft is unavailable.' using errcode = 'P0002';
  end if;

  v_delivery := jsonb_build_object(
    'status', 'draft_created',
    'messageId', v_provider_draft."CommMessage_ID",
    'threadId', v_provider_draft."CommMessage_ThreadID",
    'updatedAt', v_provider_draft."CommMessage_UpdatedAt"
  );

  update public."AI_Messages"
  set "AIMSG_ContentJSON" = jsonb_set(
    "AIMSG_ContentJSON",
    '{metadata,emailDraft,delivery}',
    v_delivery,
    true
  )
  where "AIMSG_ID" = p_message_id;

  perform public._multideck_dexter_writing_profile_audit(
    null,
    v_context.company_id,
    v_context.user_id,
    'provider_draft_created',
    'draft_created',
    0
  );

  return v_delivery;
end;
$$;


ALTER FUNCTION "public"."multideck_dexter_record_provider_draft_delivery"("p_message_id" "uuid", "p_draft_message_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_record_writing_profile_event"("p_event" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_context record;
  v_profile_id uuid;
begin
  if p_event <> 'draft_prepared' then
    raise exception 'This writing-profile event is not supported.' using errcode = '22023';
  end if;
  select * into v_context from public._multideck_dexter_context();
  select profile."AIDexterWritingProfile_ID" into v_profile_id
  from public."AI_DexterWritingProfiles" profile
  where profile."AIDexterWritingProfile_CompanyID" = v_context.company_id
    and profile."AIDexterWritingProfile_UserID" = v_context.user_id;
  perform public._multideck_dexter_writing_profile_audit(
    v_profile_id, v_context.company_id, v_context.user_id, p_event, null, 0
  );
end;
$$;


ALTER FUNCTION "public"."multideck_dexter_record_writing_profile_event"("p_event" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_rename_conversation"("p_conversation_id" "uuid", "p_title" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_user_id uuid;
  v_company_id uuid;
  v_title text := btrim(coalesce(p_title, ''));
  v_result jsonb;
begin
  if v_title = '' then
    raise exception 'Give this conversation a name first.' using errcode = '22023';
  end if;
  if char_length(v_title) > 120 then
    raise exception 'Keep conversation names under 120 characters.' using errcode = '22023';
  end if;

  select context.user_id, context.company_id
  into v_user_id, v_company_id
  from public._multideck_dexter_context() context;

  update public."AI_Conversations" conversation
  set
    "AICNV_Title" = v_title,
    "AICNV_UpdatedAt" = clock_timestamp(),
    "AICNV_UpdatedBy" = v_user_id
  where conversation."AICNV_ID" = p_conversation_id
    and conversation."AICNV_CompanyID" = v_company_id
    and conversation."AICNV_OwnerUserID" = v_user_id
    and conversation."AICNV_Channel" = 'chat'
    and conversation."AICNV_EndedAt" is null
    and conversation."AICNV_DomainCode" in ('multideck', 'warehouse');

  if not found then
    raise exception 'This conversation does not exist or is outside your workspace.'
      using errcode = 'P0002';
  end if;

  select jsonb_build_object(
    'id', conversation."AICNV_ID",
    'title', coalesce(conversation."AICNV_Title", 'Dexter conversation'),
    'summary', coalesce(conversation."AICNV_SummaryText", ''),
    'updatedAt', conversation."AICNV_UpdatedAt"
  )
  into v_result
  from public."AI_Conversations" conversation
  where conversation."AICNV_ID" = p_conversation_id;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."multideck_dexter_rename_conversation"("p_conversation_id" "uuid", "p_title" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_reserve_model_egress"("p_company_id" "uuid", "p_user_id" "uuid", "p_conversation_id" "uuid", "p_provider" "text", "p_model" "text", "p_purpose" "text", "p_data_categories" "jsonb", "p_record_count" integer, "p_byte_count" bigint, "p_estimated_input_units" integer, "p_estimated_output_units" integer) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_id uuid := gen_random_uuid();
  v_state jsonb;
  v_estimated numeric;
  v_remaining numeric;
  v_ocr_pages integer := 0;
  v_plan text := '25';
  v_seat_count integer := 25;
  v_ocr_included integer := 25000;
  v_requested_pages integer := greatest(coalesce(p_estimated_input_units, 0), 1);
  v_is_ocr boolean := lower(coalesce(p_provider, '')) = 'mistral'
    and p_purpose in ('document_ocr', 'invoice_ocr');
begin
  if auth.role() <> 'service_role' then raise exception 'server_only' using errcode = '42501'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_company_id::text, 719));

  if not exists (
    select 1 from public."cmp_Users" workspace_user
    where workspace_user."User_ID" = p_user_id
      and workspace_user."Company_ID" = p_company_id
      and coalesce(workspace_user."User_AccessStatus", 'active') = 'active'
  ) then
    raise exception 'operator_unavailable' using errcode = '42501';
  end if;

  if v_is_ocr and (
    select count(*) from public."AI_DexterModelEgressAudit" egress
    where egress."AIDexterEgress_UserID" = p_user_id
      and egress."AIDexterEgress_Purpose" in ('document_ocr', 'invoice_ocr')
      and egress."AIDexterEgress_Outcome" = 'attempted'
      and egress."AIDexterEgress_CreatedAt" > now() - interval '3 minutes'
  ) >= 2 then
    raise exception 'ocr_concurrency_limit' using errcode = 'P0001';
  end if;

  v_state := public._multideck_dexter_allowance_state(p_company_id);
  v_plan := coalesce(v_state ->> 'planCode', '25');
  if v_plan = 'enterprise' then
    select greatest(count(*)::integer, 1)
    into v_seat_count
    from public."cmp_Users" workspace_user
    where workspace_user."Company_ID" = p_company_id
      and coalesce(workspace_user."User_AccessStatus", 'active') = 'active';
  else
    v_seat_count := case v_plan when '10' then 10 when '50' then 50 else 25 end;
  end if;
  v_ocr_included := v_seat_count * 1000;

  if v_is_ocr then
    select coalesce(sum(egress."AIDexterEgress_InputUnits"), 0)::integer
    into v_ocr_pages
    from public."AI_DexterModelEgressAudit" egress
    where egress."AIDexterEgress_CompanyID" = p_company_id
      and egress."AIDexterEgress_Provider" = 'mistral'
      and egress."AIDexterEgress_Purpose" in ('document_ocr', 'invoice_ocr')
      and egress."AIDexterEgress_Outcome" in ('attempted', 'succeeded')
      and egress."AIDexterEgress_CreatedAt" >= date_trunc('month', now())
      and egress."AIDexterEgress_CreatedAt" < date_trunc('month', now()) + interval '1 month';

    if v_ocr_pages + v_requested_pages > v_ocr_included
       and not coalesce((v_state ->> 'extraUsageEnabled')::boolean, false) then
      raise exception 'usage_allowance_reached' using errcode = 'P0001';
    end if;
    v_estimated := round(v_requested_pages * 0.003076923::numeric, 6);
  else
    v_estimated := public._multideck_dexter_estimated_usage_gbp(
      case when lower(p_model)='gpt-6-astra' then 'gpt-6-astra' when lower(p_model) like '%terra%' then 'worker' else 'fast' end,
      p_estimated_input_units,
      p_estimated_output_units
    );
    if not coalesce((v_state ->> 'usageAllowed')::boolean, false) then
      raise exception 'usage_allowance_reached' using errcode = 'P0001';
    end if;
    v_remaining := greatest(coalesce((v_state ->> 'includedUsageRemainingGbp')::numeric, 0), 0)
      + case when coalesce((v_state ->> 'extraUsageEnabled')::boolean, false)
        then coalesce((v_state ->> 'extraUsageRemainingGbp')::numeric, 1000000000)
        else 0
      end;
    if v_estimated > v_remaining then
      raise exception 'usage_allowance_reached' using errcode = 'P0001';
    end if;
  end if;

  insert into public."AI_DexterModelEgressAudit" (
    "AIDexterEgress_ID", "AIDexterEgress_CompanyID", "AIDexterEgress_UserID", "AIDexterEgress_ConversationID",
    "AIDexterEgress_Provider", "AIDexterEgress_Model", "AIDexterEgress_Purpose", "AIDexterEgress_DataCategoriesJSON",
    "AIDexterEgress_RecordCount", "AIDexterEgress_ByteCount", "AIDexterEgress_InputUnits", "AIDexterEgress_OutputUnits",
    "AIDexterEgress_EstimatedCostGBP", "AIDexterEgress_Outcome"
  ) values (
    v_id, p_company_id, p_user_id, p_conversation_id, lower(p_provider), left(p_model, 120), left(p_purpose, 80), coalesce(p_data_categories, '[]'),
    greatest(coalesce(p_record_count, 0), 0), greatest(coalesce(p_byte_count, 0), 0),
    case when v_is_ocr then v_requested_pages else greatest(coalesce(p_estimated_input_units, 0), 0) end,
    greatest(coalesce(p_estimated_output_units, 0), 0), v_estimated, 'attempted'
  );
  return v_id;
end;
$$;


ALTER FUNCTION "public"."multideck_dexter_reserve_model_egress"("p_company_id" "uuid", "p_user_id" "uuid", "p_conversation_id" "uuid", "p_provider" "text", "p_model" "text", "p_purpose" "text", "p_data_categories" "jsonb", "p_record_count" integer, "p_byte_count" bigint, "p_estimated_input_units" integer, "p_estimated_output_units" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_reserve_upload"("p_company_id" "uuid", "p_user_id" "uuid", "p_byte_count" bigint) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare v_id uuid:=gen_random_uuid(); v_recent integer; v_daily bigint; v_workspace bigint;
begin
  if auth.role()<>'service_role' then raise exception 'server_only' using errcode='42501'; end if;
  if p_byte_count<=0 or p_byte_count>25*1024*1024 then raise exception 'upload_too_large' using errcode='22023'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_company_id::text||':'||p_user_id::text,731));
  if not exists(select 1 from public."cmp_Users" u where u."User_ID"=p_user_id and u."Company_ID"=p_company_id
    and coalesce(u."User_AccessStatus",'active')='active') then raise exception 'operator_unavailable' using errcode='42501'; end if;
  select
    (select count(*) from public."AI_DexterUploads" u where u."AIDexterUpload_CompanyID"=p_company_id
      and u."AIDexterUpload_UserID"=p_user_id and u."AIDexterUpload_CreatedAt">=now()-interval '10 minutes')
    +(select count(*) from public."AI_DexterUploadReservations" r where r."AIDexterUploadReservation_CompanyID"=p_company_id
      and r."AIDexterUploadReservation_UserID"=p_user_id and r."AIDexterUploadReservation_Status"='reserved'
      and r."AIDexterUploadReservation_ExpiresAt">now() and r."AIDexterUploadReservation_CreatedAt">=now()-interval '10 minutes')
  into v_recent;
  if v_recent>=10 then raise exception 'upload_rate_limited' using errcode='P0001'; end if;
  select
    coalesce((select sum(u."AIDexterUpload_FileSizeBytes") from public."AI_DexterUploads" u
      where u."AIDexterUpload_CompanyID"=p_company_id and u."AIDexterUpload_UserID"=p_user_id
        and u."AIDexterUpload_CreatedAt">=now()-interval '24 hours'),0)
    +coalesce((select sum(r."AIDexterUploadReservation_ByteCount") from public."AI_DexterUploadReservations" r
      where r."AIDexterUploadReservation_CompanyID"=p_company_id and r."AIDexterUploadReservation_UserID"=p_user_id
        and r."AIDexterUploadReservation_Status"='reserved' and r."AIDexterUploadReservation_ExpiresAt">now()),0)
  into v_daily;
  if v_daily+p_byte_count>250*1024*1024 then raise exception 'upload_daily_limit' using errcode='P0001'; end if;
  select
    coalesce((select sum(u."AIDexterUpload_FileSizeBytes") from public."AI_DexterUploads" u
      where u."AIDexterUpload_CompanyID"=p_company_id and u."AIDexterUpload_StatusCode"='active'),0)
    +coalesce((select sum(r."AIDexterUploadReservation_ByteCount") from public."AI_DexterUploadReservations" r
      where r."AIDexterUploadReservation_CompanyID"=p_company_id and r."AIDexterUploadReservation_Status"='reserved'
        and r."AIDexterUploadReservation_ExpiresAt">now()),0)
  into v_workspace;
  if v_workspace+p_byte_count>2::bigint*1024*1024*1024 then raise exception 'upload_workspace_limit' using errcode='P0001'; end if;
  insert into public."AI_DexterUploadReservations"(
    "AIDexterUploadReservation_ID","AIDexterUploadReservation_CompanyID","AIDexterUploadReservation_UserID",
    "AIDexterUploadReservation_ByteCount"
  ) values(v_id,p_company_id,p_user_id,p_byte_count);
  return v_id;
end $$;


ALTER FUNCTION "public"."multideck_dexter_reserve_upload"("p_company_id" "uuid", "p_user_id" "uuid", "p_byte_count" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_reset_writing_profile"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_context record;
  v_profile_id uuid;
begin
  select * into v_context from public._multideck_dexter_context();
  delete from public."AI_DexterWritingProfiles" profile
  where profile."AIDexterWritingProfile_CompanyID" = v_context.company_id
    and profile."AIDexterWritingProfile_UserID" = v_context.user_id
  returning profile."AIDexterWritingProfile_ID" into v_profile_id;
  if v_profile_id is not null then
    perform public._multideck_dexter_writing_profile_audit(
      null, v_context.company_id, v_context.user_id, 'reset', 'not_started', 0
    );
  end if;
  return public.multideck_dexter_get_writing_profile();
end;
$$;


ALTER FUNCTION "public"."multideck_dexter_reset_writing_profile"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_resolve_email_attachment"("p_providers" "text"[], "p_attachment_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_context record;
  v_providers text[];
  v_result jsonb;
begin
  select * into v_context from public._multideck_dexter_context();
  if not public._multideck_dexter_has_permission(v_context.user_id, 'Email.Read')
     or not public._multideck_dexter_has_permission(v_context.user_id, 'Email.AIRead') then
    raise exception 'You do not have permission to use email with Dexter.' using errcode = '42501';
  end if;

  select coalesce(array_agg(distinct lower(btrim(provider))), array[]::text[])
  into v_providers
  from unnest(coalesce(p_providers, array[]::text[])) provider
  where lower(btrim(provider)) in ('gmail', 'outlook');
  if cardinality(v_providers) = 0
     or cardinality(v_providers) <> cardinality(coalesce(p_providers, array[]::text[])) then
    raise exception 'Choose Gmail, Outlook, or both as the email source.' using errcode = '22023';
  end if;

  select jsonb_build_object(
    'attachmentId', attachment."CommAttachment_ID",
    'messageId', message."CommMessage_ID",
    'threadId', message."CommMessage_ThreadID",
    'mailboxId', message."CommMessage_MailboxID",
    'provider', permitted.provider,
    'subject', coalesce(nullif(message."CommMessage_Subject", ''), '(No subject)'),
    'fileName', attachment."CommAttachment_FileName",
    'mimeType', attachment."CommAttachment_MimeType",
    'sizeBytes', attachment."CommAttachment_FileSizeBytes",
    '_citation', jsonb_build_object(
      'title', attachment."CommAttachment_FileName",
      'url', '/inbox?provider=' || permitted.provider || '&mailbox=' || message."CommMessage_MailboxID" || '&thread=' || message."CommMessage_ThreadID",
      'description', 'Email attachment in ' || coalesce(nullif(message."CommMessage_Subject", ''), '(No subject)')
    )
  )
  into v_result
  from public."Comm_MessageAttachments" attachment
  join public."Comm_Messages" message
    on message."CommMessage_ID" = attachment."CommAttachment_MessageID"
  join public._multideck_dexter_email_mailboxes(v_context.user_id, v_context.company_id) permitted
    on permitted.mailbox_id = message."CommMessage_MailboxID"
   and permitted.provider = any(v_providers)
  where attachment."CommAttachment_ID" = p_attachment_id
    and not attachment."CommAttachment_IsInline"
    and not message."CommMessage_IsDeleted"
    and not message."CommMessage_IsDraft"
    and not message."CommMessage_IsSpam"
    and not exists (
      select 1
      from public."Comm_MessageFolders" membership
      join public."Comm_MailFolders" folder
        on folder."CommMailFolder_ID" = membership."CommMessageFolder_FolderID"
      where membership."CommMessageFolder_MessageID" = message."CommMessage_ID"
        and folder."CommMailFolder_RoleCode" in ('drafts', 'spam', 'trash')
    );

  if v_result is null then
    raise exception 'This email attachment was not found.' using errcode = 'P0002';
  end if;
  return v_result;
end;
$$;


ALTER FUNCTION "public"."multideck_dexter_resolve_email_attachment"("p_providers" "text"[], "p_attachment_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_resolve_email_compose_context"("p_message_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_context record;
  v_source jsonb;
  v_thread_id uuid;
  v_messages jsonb;
begin
  select * into v_context from public._multideck_dexter_context();
  if not public._multideck_dexter_has_permission(v_context.user_id, 'Email.Read')
     or not public._multideck_dexter_has_permission(v_context.user_id, 'Email.AIRead') then
    raise exception 'You do not have permission to use email with Dexter.' using errcode = '42501';
  end if;

  v_source := public.multideck_dexter_resolve_email_draft_source(p_message_id);
  v_thread_id := nullif(v_source ->> 'threadId', '')::uuid;

  select coalesce(jsonb_agg(item.payload order by item.occurred_at, item.message_id), '[]'::jsonb)
    into v_messages
  from (
    select
      message."CommMessage_ID" message_id,
      coalesce(message."CommMessage_ReceivedAt", message."CommMessage_SentAt", message."CommMessage_MessageDate", message."CommMessage_CreatedAt") occurred_at,
      jsonb_build_object(
        'messageId', message."CommMessage_ID",
        'direction', message."CommMessage_DirectionCode",
        'occurredAt', coalesce(message."CommMessage_ReceivedAt", message."CommMessage_SentAt", message."CommMessage_MessageDate", message."CommMessage_CreatedAt"),
        'from', coalesce((
          select jsonb_agg(jsonb_build_object(
            'address', recipient."CommRecipient_Address",
            'displayName', recipient."CommRecipient_DisplayNameSnapshot"
          ) order by recipient."CommRecipient_CreatedAt", recipient."CommRecipient_ID")
          from public."Comm_MessageRecipients" recipient
          where recipient."CommRecipient_MessageID" = message."CommMessage_ID"
            and recipient."CommRecipient_RecipientTypeCode" = 'from'
            and not recipient."CommRecipient_IsSuppressed"
        ), '[]'::jsonb),
        'bodyText', left(coalesce(message."CommMessage_BodyText", message."CommMessage_BodyPreview", ''), 20000)
      ) payload
    from public."Comm_Messages" message
    join public._multideck_dexter_email_mailboxes(v_context.user_id, v_context.company_id) permitted
      on permitted.mailbox_id = message."CommMessage_MailboxID"
    where message."CommMessage_ThreadID" = v_thread_id
      and not message."CommMessage_IsDeleted"
      and not message."CommMessage_IsDraft"
      and not message."CommMessage_IsSpam"
      and not exists (
        select 1
        from public."Comm_MessageFolders" membership
        join public."Comm_MailFolders" folder
          on folder."CommMailFolder_ID" = membership."CommMessageFolder_FolderID"
        where membership."CommMessageFolder_MessageID" = message."CommMessage_ID"
          and folder."CommMailFolder_RoleCode" in ('drafts', 'spam', 'trash')
      )
    order by coalesce(message."CommMessage_ReceivedAt", message."CommMessage_SentAt", message."CommMessage_MessageDate", message."CommMessage_CreatedAt") desc
    limit 30
  ) item;

  return v_source || jsonb_build_object('messages', v_messages);
end;
$$;


ALTER FUNCTION "public"."multideck_dexter_resolve_email_compose_context"("p_message_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."multideck_dexter_resolve_email_compose_context"("p_message_id" "uuid") IS 'Returns the selected source plus a bounded tenant-safe thread transcript for the Inbox Dexter composer. This read capability already exists in Dexter chat; it creates no watchable record change.';



CREATE OR REPLACE FUNCTION "public"."multideck_dexter_resolve_email_draft_source"("p_message_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_context record;
  v_result jsonb;
begin
  select * into v_context from public._multideck_dexter_context();
  if not public._multideck_dexter_has_permission(v_context.user_id, 'Email.Read')
     or not public._multideck_dexter_has_permission(v_context.user_id, 'Email.AIRead') then
    raise exception 'You do not have permission to use email with Dexter.' using errcode = '42501';
  end if;

  select jsonb_build_object(
    'messageId', message."CommMessage_ID",
    'threadId', message."CommMessage_ThreadID",
    'mailboxId', message."CommMessage_MailboxID",
    'mailboxAddress', coalesce(mailbox."CommMailbox_NormalizedAddress", mailbox."CommMailbox_Address", ''),
    'direction', message."CommMessage_DirectionCode",
    'subject', coalesce(message."CommMessage_Subject", ''),
    'from', coalesce((
      select jsonb_agg(jsonb_build_object(
        'address', recipient."CommRecipient_Address",
        'displayName', recipient."CommRecipient_DisplayNameSnapshot"
      ) order by recipient."CommRecipient_CreatedAt", recipient."CommRecipient_ID")
      from public."Comm_MessageRecipients" recipient
      where recipient."CommRecipient_MessageID" = message."CommMessage_ID"
        and recipient."CommRecipient_RecipientTypeCode" = 'from'
        and not recipient."CommRecipient_IsSuppressed"
    ), '[]'::jsonb),
    'to', coalesce((
      select jsonb_agg(jsonb_build_object(
        'address', recipient."CommRecipient_Address",
        'displayName', recipient."CommRecipient_DisplayNameSnapshot"
      ) order by recipient."CommRecipient_CreatedAt", recipient."CommRecipient_ID")
      from public."Comm_MessageRecipients" recipient
      where recipient."CommRecipient_MessageID" = message."CommMessage_ID"
        and recipient."CommRecipient_RecipientTypeCode" = 'to'
        and not recipient."CommRecipient_IsSuppressed"
    ), '[]'::jsonb),
    'cc', coalesce((
      select jsonb_agg(jsonb_build_object(
        'address', recipient."CommRecipient_Address",
        'displayName', recipient."CommRecipient_DisplayNameSnapshot"
      ) order by recipient."CommRecipient_CreatedAt", recipient."CommRecipient_ID")
      from public."Comm_MessageRecipients" recipient
      where recipient."CommRecipient_MessageID" = message."CommMessage_ID"
        and recipient."CommRecipient_RecipientTypeCode" = 'cc'
        and not recipient."CommRecipient_IsSuppressed"
    ), '[]'::jsonb)
  ) into v_result
  from public."Comm_Messages" message
  join public._multideck_dexter_email_mailboxes(v_context.user_id, v_context.company_id) permitted
    on permitted.mailbox_id = message."CommMessage_MailboxID"
  join public."Comm_Mailboxes" mailbox
    on mailbox."CommMailbox_ID" = message."CommMessage_MailboxID"
  where message."CommMessage_ID" = p_message_id
    and not message."CommMessage_IsDeleted"
    and not message."CommMessage_IsDraft"
    and not message."CommMessage_IsSpam"
    and not exists (
      select 1
      from public."Comm_MessageFolders" membership
      join public."Comm_MailFolders" folder
        on folder."CommMailFolder_ID" = membership."CommMessageFolder_FolderID"
      where membership."CommMessageFolder_MessageID" = message."CommMessage_ID"
        and folder."CommMailFolder_RoleCode" in ('drafts','spam','trash')
    );

  if v_result is null then
    raise exception 'This email update was not found.' using errcode = 'P0002';
  end if;
  return v_result;
end;
$$;


ALTER FUNCTION "public"."multideck_dexter_resolve_email_draft_source"("p_message_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_resolve_email_message"("p_message_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare v_context record; v_result jsonb;
begin
  select * into v_context from public._multideck_dexter_context();
  if not public._multideck_dexter_has_permission(v_context.user_id, 'Email.Read')
     or not public._multideck_dexter_has_permission(v_context.user_id, 'Email.AIRead') then
    raise exception 'You do not have permission to use email with Dexter.' using errcode = '42501';
  end if;

  select jsonb_build_object(
    'messageId', message."CommMessage_ID", 'threadId', message."CommMessage_ThreadID",
    'mailboxId', message."CommMessage_MailboxID", 'provider', permitted.provider,
    'subject', coalesce(nullif(message."CommMessage_Subject", ''), '(No subject)'),
    'senderName', coalesce(sender.display_name, ''), 'senderEmail', coalesce(sender.address, ''),
    'receivedAt', coalesce(message."CommMessage_ReceivedAt", message."CommMessage_MessageDate", message."CommMessage_CreatedAt"),
    'preview', left(coalesce(message."CommMessage_BodyPreview", ''), 1200),
    'bodyText', left(coalesce(message."CommMessage_BodyText", message."CommMessage_BodyPreview", ''), 20000),
    '_citation', jsonb_build_object(
      'title', coalesce(nullif(message."CommMessage_Subject", ''), '(No subject)'),
      'url', '/inbox?provider=' || permitted.provider || '&mailbox=' || message."CommMessage_MailboxID" || '&thread=' || message."CommMessage_ThreadID",
      'description', case permitted.provider when 'gmail' then 'Gmail email update' else 'Outlook email update' end
    )
  ) into v_result
  from public."Comm_Messages" message
  join public._multideck_dexter_email_mailboxes(v_context.user_id, v_context.company_id) permitted
    on permitted.mailbox_id = message."CommMessage_MailboxID"
  left join lateral (
    select recipient."CommRecipient_DisplayNameSnapshot" display_name, recipient."CommRecipient_Address" address
    from public."Comm_MessageRecipients" recipient
    where recipient."CommRecipient_MessageID" = message."CommMessage_ID"
      and recipient."CommRecipient_RecipientTypeCode" = 'from'
    order by recipient."CommRecipient_CreatedAt", recipient."CommRecipient_ID" limit 1
  ) sender on true
  where message."CommMessage_ID" = p_message_id
    and not message."CommMessage_IsDeleted" and not message."CommMessage_IsDraft" and not message."CommMessage_IsSpam"
    and not exists (
      select 1 from public."Comm_MessageFolders" membership
      join public."Comm_MailFolders" folder on folder."CommMailFolder_ID" = membership."CommMessageFolder_FolderID"
      where membership."CommMessageFolder_MessageID" = message."CommMessage_ID"
        and folder."CommMailFolder_RoleCode" in ('drafts','spam','trash')
    );
  if v_result is null then raise exception 'This email update was not found.' using errcode = 'P0002'; end if;
  return v_result;
end;
$$;


ALTER FUNCTION "public"."multideck_dexter_resolve_email_message"("p_message_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_save_exchange"("p_conversation_id" "uuid", "p_prompt" "text", "p_answer" "text", "p_specialist" "text", "p_model" "text", "p_attachments" "jsonb", "p_metadata" "jsonb", "p_input_tokens" integer, "p_output_tokens" integer, "p_retry_message_id" "uuid" DEFAULT NULL::"uuid", "p_parent_response_message_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $_$
declare
  v_user_id uuid;
  v_company_id uuid;
  v_conversation_id uuid := p_conversation_id;
  v_user_message_id uuid := coalesce(p_retry_message_id, gen_random_uuid());
  v_assistant_message_id uuid := gen_random_uuid();
  v_prompt text := btrim(coalesce(p_prompt, ''));
  v_answer text := btrim(coalesce(p_answer, ''));
  v_specialist text := lower(btrim(coalesce(p_specialist, 'auto')));
  v_model text := lower(btrim(coalesce(p_model, 'fast')));
  v_attachments jsonb := case
    when jsonb_typeof(coalesce(p_attachments, '[]'::jsonb)) = 'array'
      then coalesce(p_attachments, '[]'::jsonb)
    else '[]'::jsonb
  end;
  v_metadata jsonb := case
    when jsonb_typeof(coalesce(p_metadata, '{}'::jsonb)) = 'object'
      then coalesce(p_metadata, '{}'::jsonb)
    else '{}'::jsonb
  end;
  v_response_version integer := 1;
  v_now timestamptz := clock_timestamp();
  v_attachment jsonb;
  v_target_id uuid;
  v_target_table text;
  v_summary text;
  v_result jsonb;
begin
  if v_prompt = '' or char_length(v_prompt) > 4000 then
    raise exception 'Write a Dexter request between 1 and 4,000 characters.'
      using errcode = '22023';
  end if;
  if v_answer = '' or char_length(v_answer) > 24000 then
    raise exception 'Dexter did not return a valid answer.'
      using errcode = '22023';
  end if;
  if v_specialist not in ('auto', 'customs', 'customer', 'sales', 'ops', 'analytics') then
    raise exception 'The selected Dexter specialist is not recognised.'
      using errcode = '22023';
  end if;
  if v_model not in ('fast', 'smart', 'worker') then
    raise exception 'The selected Dexter model is not recognised.'
      using errcode = '22023';
  end if;

  select context.user_id, context.company_id
  into v_user_id, v_company_id
  from public._multideck_dexter_context() context;

  if v_conversation_id is null then
    if p_retry_message_id is not null then
      raise exception 'Choose a saved message to retry.'
        using errcode = '22023';
    end if;

    v_conversation_id := gen_random_uuid();

    insert into public."AI_Conversations" (
      "AICNV_ID",
      "AICNV_Title",
      "AICNV_Channel",
      "AICNV_DomainCode",
      "AICNV_CompanyID",
      "AICNV_OwnerUserID",
      "AICNV_Status",
      "AICNV_SecurityClass",
      "AICNV_IsTrainingAllowed",
      "AICNV_MetadataJSON",
      "AICNV_StartedAt",
      "AICNV_CreatedAt",
      "AICNV_CreatedBy",
      "AICNV_UpdatedAt",
      "AICNV_UpdatedBy"
    )
    values (
      v_conversation_id,
      case
        when char_length(regexp_replace(v_prompt, '\s+', ' ', 'g')) <= 100
          then regexp_replace(v_prompt, '\s+', ' ', 'g')
        else left(regexp_replace(v_prompt, '\s+', ' ', 'g'), 99) || '…'
      end,
      'chat',
      'multideck',
      v_company_id,
      v_user_id,
      'open',
      'internal',
      false,
      jsonb_build_object('agent', 'dexter', 'domain', 'multideck'),
      v_now,
      v_now,
      v_user_id,
      v_now,
      v_user_id
    );

    insert into public."AI_ConversationParticipants" (
      "AICNP_ConversationID",
      "AICNP_ParticipantType",
      "AICNP_UserID",
      "AICNP_IsPrimary",
      "AICNP_CreatedAt"
    )
    values (
      v_conversation_id,
      'user',
      v_user_id,
      true,
      v_now
    );

    insert into public."AI_ConversationParticipants" (
      "AICNP_ConversationID",
      "AICNP_ParticipantType",
      "AICNP_DisplayNameSnapshot",
      "AICNP_IsPrimary",
      "AICNP_CreatedAt"
    )
    values (
      v_conversation_id,
      'ai',
      'Dexter',
      false,
      v_now
    );
  else
    perform 1
    from public."AI_Conversations" conversation
    where conversation."AICNV_ID" = v_conversation_id
      and conversation."AICNV_CompanyID" = v_company_id
      and conversation."AICNV_OwnerUserID" = v_user_id
      and conversation."AICNV_Channel" = 'chat'
      and conversation."AICNV_EndedAt" is null
      and conversation."AICNV_DomainCode" in ('multideck', 'warehouse')
    for update;

    if not found then
      raise exception 'This conversation does not exist or is outside your workspace.'
        using errcode = 'P0002';
    end if;
  end if;

  if p_retry_message_id is not null then
    select message."AIMSG_ContentText"
    into v_prompt
    from public."AI_Messages" message
    where message."AIMSG_ID" = p_retry_message_id
      and message."AIMSG_ConversationID" = v_conversation_id
      and message."AIMSG_Role" = 'user'
      and message."AIMSG_UserID" = v_user_id
    for update;

    if not found then
      raise exception 'That message cannot be retried in this conversation.'
        using errcode = 'P0002';
    end if;

    select coalesce(
      max(
        case
          when coalesce(
            message."AIMSG_ContentJSON" #>> '{metadata,responseVersion}',
            ''
          ) ~ '^[1-9][0-9]*$'
            then (message."AIMSG_ContentJSON" #>> '{metadata,responseVersion}')::integer
          else 1
        end
      ),
      1
    ) + 1
    into v_response_version
    from public."AI_Messages" message
    where message."AIMSG_ConversationID" = v_conversation_id
      and message."AIMSG_Role" = 'assistant'
      and message."AIMSG_ContentJSON" #>> '{metadata,responseToUserMessageId}' =
        p_retry_message_id::text;
  else
    if p_parent_response_message_id is not null and not exists (
      select 1
      from public."AI_Messages" parent_message
      where parent_message."AIMSG_ID" = p_parent_response_message_id
        and parent_message."AIMSG_ConversationID" = v_conversation_id
        and parent_message."AIMSG_Role" = 'assistant'
    ) then
      raise exception 'That Dexter response is not part of this conversation.'
        using errcode = 'P0002';
    end if;

    insert into public."AI_Messages" (
      "AIMSG_ID",
      "AIMSG_ConversationID",
      "AIMSG_Role",
      "AIMSG_UserID",
      "AIMSG_ContentText",
      "AIMSG_ContentJSON",
      "AIMSG_SecurityClass",
      "AIMSG_IsTrainingCandidate",
      "AIMSG_IsTrainingAllowed",
      "AIMSG_CreatedAt",
      "AIMSG_CreatedBy"
    )
    values (
      v_user_message_id,
      v_conversation_id,
      'user',
      v_user_id,
      v_prompt,
      jsonb_build_object(
        'specialist', v_specialist,
        'model', v_model,
        'attachments', v_attachments,
        'metadata', case
          when p_parent_response_message_id is null then null
          else jsonb_build_object(
            'parentResponseMessageId',
            p_parent_response_message_id::text
          )
        end
      ),
      'internal',
      false,
      false,
      v_now,
      v_user_id
    );
  end if;

  v_metadata := v_metadata || jsonb_build_object(
    'responseToUserMessageId', v_user_message_id::text,
    'responseVersion', v_response_version
  );

  insert into public."AI_Messages" (
    "AIMSG_ID",
    "AIMSG_ConversationID",
    "AIMSG_Role",
    "AIMSG_ContentText",
    "AIMSG_ContentJSON",
    "AIMSG_PromptTokens",
    "AIMSG_CompletionTokens",
    "AIMSG_SecurityClass",
    "AIMSG_IsTrainingCandidate",
    "AIMSG_IsTrainingAllowed",
    "AIMSG_CreatedAt"
  )
  values (
    v_assistant_message_id,
    v_conversation_id,
    'assistant',
    v_answer,
    jsonb_build_object(
      'specialist', v_specialist,
      'model', v_model,
      'attachments', '[]'::jsonb,
      'metadata', v_metadata
    ),
    greatest(coalesce(p_input_tokens, 0), 0),
    greatest(coalesce(p_output_tokens, 0), 0),
    'internal',
    false,
    false,
    v_now + interval '1 microsecond'
  );

  if p_retry_message_id is null then
    for v_attachment in
      select attachment.value
      from jsonb_array_elements(v_attachments) attachment(value)
      limit 10
    loop
      begin
        v_target_id := nullif(v_attachment ->> 'id', '')::uuid;
      exception when invalid_text_representation then
        continue;
      end;

      v_target_table := case lower(coalesce(v_attachment ->> 'type', ''))
        when 'booking' then 'WMS_Orders'
        when 'order' then 'WMS_Orders'
        when 'item' then 'WMS_Items'
        when 'facility' then 'WMS_Facilities'
        when 'document' then 'WMS_Documents'
        else null
      end;

      if v_target_id is not null and v_target_table is not null then
        insert into public."AI_MessageLinks" (
          "AIML_MessageID",
          "AIML_TargetTable",
          "AIML_TargetID",
          "AIML_LinkRole",
          "AIML_CreatedAt"
        )
        values (
          v_user_message_id,
          v_target_table,
          v_target_id,
          'context',
          v_now
        );
      end if;
    end loop;
  end if;

  v_summary := case
    when char_length(v_answer) <= 180 then v_answer
    else left(v_answer, 179) || '…'
  end;

  update public."AI_Conversations"
  set
    "AICNV_SummaryText" = v_summary,
    "AICNV_UpdatedAt" = v_now + interval '1 microsecond',
    "AICNV_UpdatedBy" = v_user_id
  where "AICNV_ID" = v_conversation_id;

  select public._multideck_dexter_conversation_json(
    v_conversation_id,
    v_user_id,
    v_company_id
  ) into v_result;

  return v_result;
end;
$_$;


ALTER FUNCTION "public"."multideck_dexter_save_exchange"("p_conversation_id" "uuid", "p_prompt" "text", "p_answer" "text", "p_specialist" "text", "p_model" "text", "p_attachments" "jsonb", "p_metadata" "jsonb", "p_input_tokens" integer, "p_output_tokens" integer, "p_retry_message_id" "uuid", "p_parent_response_message_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_search_conversations"("p_query" "text", "p_limit" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_user_id uuid;
  v_company_id uuid;
  v_query text := lower(btrim(coalesce(p_query, '')));
  v_limit integer := least(greatest(coalesce(p_limit, 50), 1), 50);
  v_result jsonb;
begin
  select context.user_id, context.company_id
  into v_user_id, v_company_id
  from public._multideck_dexter_context() context;

  if v_query = '' then
    return public.multideck_dexter_list_conversations();
  end if;

  select coalesce(jsonb_agg(item.value order by item.updated_at desc), '[]'::jsonb)
  into v_result
  from (
    select
      jsonb_build_object(
        'id', conversation."AICNV_ID",
        'title', coalesce(conversation."AICNV_Title", 'Dexter conversation'),
        'summary', coalesce(conversation."AICNV_SummaryText", ''),
        'updatedAt', conversation."AICNV_UpdatedAt",
        'matchSnippet', coalesce(
          (
            select left(regexp_replace(message."AIMSG_ContentText", '[[:space:]]+', ' ', 'g'), 240)
            from public."AI_Messages" message
            where message."AIMSG_ConversationID" = conversation."AICNV_ID"
              and position(v_query in lower(coalesce(message."AIMSG_ContentText", ''))) > 0
            order by message."AIMSG_CreatedAt" desc
            limit 1
          ),
          coalesce(conversation."AICNV_SummaryText", '')
        )
      ) as value,
      conversation."AICNV_UpdatedAt" as updated_at
    from public."AI_Conversations" conversation
    where conversation."AICNV_CompanyID" = v_company_id
      and conversation."AICNV_OwnerUserID" = v_user_id
      and conversation."AICNV_Channel" = 'chat'
      and conversation."AICNV_EndedAt" is null
      and conversation."AICNV_DomainCode" in ('multideck', 'warehouse')
      and (
        position(v_query in lower(coalesce(conversation."AICNV_Title", ''))) > 0
        or exists (
          select 1
          from public."AI_Messages" message
          where message."AIMSG_ConversationID" = conversation."AICNV_ID"
            and position(v_query in lower(coalesce(message."AIMSG_ContentText", ''))) > 0
        )
      )
    order by conversation."AICNV_UpdatedAt" desc
    limit v_limit
  ) item;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."multideck_dexter_search_conversations"("p_query" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_search_email"("p_providers" "text"[], "p_query" "text", "p_after" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_before" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_take" integer DEFAULT 10) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_context record;
  v_query text := left(btrim(coalesce(p_query, '')), 300);
  v_take integer := greatest(1, least(coalesce(p_take, 10), 20));
  v_providers text[];
  v_result jsonb;
begin
  select * into v_context from public._multideck_dexter_context();
  if not public._multideck_dexter_has_permission(v_context.user_id, 'Email.Read')
     or not public._multideck_dexter_has_permission(v_context.user_id, 'Email.AIRead') then
    raise exception 'You do not have permission to use email with Dexter.' using errcode = '42501';
  end if;

  select coalesce(array_agg(distinct lower(btrim(provider))), array[]::text[])
  into v_providers
  from unnest(coalesce(p_providers, array[]::text[])) provider
  where lower(btrim(provider)) in ('gmail', 'outlook');

  if cardinality(v_providers) = 0
     or cardinality(v_providers) <> cardinality(coalesce(p_providers, array[]::text[])) then
    raise exception 'Choose Gmail, Outlook, or both as the email source.' using errcode = '22023';
  end if;
  if v_query = '' then
    raise exception 'Enter an email search term.' using errcode = '22023';
  end if;
  if p_after is not null and p_before is not null and p_after >= p_before then
    raise exception 'The email search date range is invalid.' using errcode = '22023';
  end if;

  with permitted_mailboxes as materialized (
    select *
    from public._multideck_dexter_email_mailboxes(v_context.user_id, v_context.company_id)
    where provider = any(v_providers)
  ),
  parameters as (
    select
      websearch_to_tsquery('simple'::regconfig, v_query) as search_query,
      to_tsquery(
        'simple'::regconfig,
        replace(plainto_tsquery('simple'::regconfig, v_query)::text, ' & ', ' | ')
      ) as fallback_query
  ),
  candidates as (
    select
      message.*,
      permitted.provider,
      mailbox."CommMailbox_LastSyncedAt" as synced_at,
      coalesce(mailbox."CommMailbox_IndexStatus", 'pending') as index_status,
      search_document."AIDexterEmailSearch_Document" as search_vector
    from public."Comm_Messages" message
    join permitted_mailboxes permitted
      on permitted.mailbox_id = message."CommMessage_MailboxID"
    join public."Comm_Mailboxes" mailbox
      on mailbox."CommMailbox_ID" = message."CommMessage_MailboxID"
    join public."AI_DexterEmailSearchDocuments" search_document
      on search_document."AIDexterEmailSearch_MessageID" = message."CommMessage_ID"
  ),
  matches as (
    select
      candidate."CommMessage_ID" as message_id,
      candidate."CommMessage_ThreadID" as thread_id,
      candidate."CommMessage_MailboxID" as mailbox_id,
      candidate.provider,
      coalesce(nullif(candidate."CommMessage_Subject", ''), '(No subject)') as subject,
      left(coalesce(candidate."CommMessage_BodyPreview", candidate."CommMessage_BodyText", ''), 1000) as preview,
      coalesce(
        candidate."CommMessage_MessageDate",
        candidate."CommMessage_ReceivedAt",
        candidate."CommMessage_SentAt",
        candidate."CommMessage_CreatedAt"
      ) as occurred_at,
      candidate."CommMessage_HasAttachments" as has_attachments,
      candidate.synced_at,
      candidate.index_status,
      case
        when candidate.search_vector @@ parameters.search_query
          then 100 + least(ts_rank_cd(candidate.search_vector, parameters.search_query), 10)
        else
          10 * ts_rank_cd(
            to_tsvector('simple'::regconfig, coalesce(candidate."CommMessage_Subject", '')),
            parameters.fallback_query
          )
          + least(ts_rank_cd(candidate.search_vector, parameters.fallback_query), 0.99)
      end as search_rank
    from candidates candidate
    cross join parameters
    where not candidate."CommMessage_IsDeleted"
      and not candidate."CommMessage_IsDraft"
      and not candidate."CommMessage_IsSpam"
      and (
        p_after is null
        or coalesce(
          candidate."CommMessage_MessageDate",
          candidate."CommMessage_ReceivedAt",
          candidate."CommMessage_SentAt",
          candidate."CommMessage_CreatedAt"
        ) >= p_after
      )
      and (
        p_before is null
        or coalesce(
          candidate."CommMessage_MessageDate",
          candidate."CommMessage_ReceivedAt",
          candidate."CommMessage_SentAt",
          candidate."CommMessage_CreatedAt"
        ) < p_before
      )
      and not exists (
        select 1
        from public."Comm_MessageFolders" membership
        join public."Comm_MailFolders" folder
          on folder."CommMailFolder_ID" = membership."CommMessageFolder_FolderID"
        where membership."CommMessageFolder_MessageID" = candidate."CommMessage_ID"
          and folder."CommMailFolder_RoleCode" in ('drafts', 'spam', 'trash')
      )
      and (
        candidate.search_vector @@ parameters.search_query
        or candidate.search_vector @@ parameters.fallback_query
      )
  ),
  thread_matches as (
    select distinct on (matches.thread_id)
      matches.*
    from matches
    order by matches.thread_id, matches.search_rank desc, matches.occurred_at desc, matches.message_id desc
  ),
  ordered as (
    select *
    from thread_matches
    order by search_rank desc, occurred_at desc, thread_id
    limit v_take + 1
  ),
  output_rows as (
    select jsonb_build_object(
      'threadId', ordered.thread_id,
      'matchMessageId', ordered.message_id,
      'mailboxId', ordered.mailbox_id,
      'provider', ordered.provider,
      'subject', ordered.subject,
      'preview', ordered.preview,
      'occurredAt', ordered.occurred_at,
      'hasAttachments', ordered.has_attachments,
      'syncedAt', ordered.synced_at,
      'indexStatus', ordered.index_status,
      'stale', ordered.synced_at is null
        or ordered.synced_at < now() - interval '30 minutes'
        or ordered.index_status = 'error',
      'participants', coalesce((
        select jsonb_agg(participant_row.value order by participant_row.sort_address)
        from (
          select distinct on (recipient."CommRecipient_NormalizedAddress")
            jsonb_build_object(
              'address', recipient."CommRecipient_Address",
              'displayName', recipient."CommRecipient_DisplayNameSnapshot",
              'role', recipient."CommRecipient_RecipientTypeCode"
            ) as value,
            recipient."CommRecipient_NormalizedAddress" as sort_address
          from public."Comm_MessageRecipients" recipient
          where recipient."CommRecipient_MessageID" = ordered.message_id
          order by recipient."CommRecipient_NormalizedAddress", recipient."CommRecipient_RecipientTypeCode"
        ) participant_row
      ), '[]'::jsonb),
      '_citation', jsonb_build_object(
        'title', ordered.subject,
        'url', '/inbox?provider=' || ordered.provider || '&mailbox=' || ordered.mailbox_id || '&thread=' || ordered.thread_id,
        'description', case ordered.provider when 'gmail' then 'Gmail email thread' else 'Outlook email thread' end
      )
    ) as value,
    ordered.search_rank,
    ordered.occurred_at,
    ordered.thread_id
    from ordered
    order by ordered.search_rank desc, ordered.occurred_at desc, ordered.thread_id
    limit v_take
  )
  select jsonb_build_object(
    'items', coalesce(jsonb_agg(output_rows.value order by output_rows.search_rank desc, output_rows.occurred_at desc, output_rows.thread_id), '[]'::jsonb),
    'hasMore', (select count(*) from ordered) > v_take,
    'query', v_query
  )
  into v_result
  from output_rows;

  return coalesce(v_result, jsonb_build_object('items', '[]'::jsonb, 'hasMore', false, 'query', v_query));
end;
$$;


ALTER FUNCTION "public"."multideck_dexter_search_email"("p_providers" "text"[], "p_query" "text", "p_after" timestamp with time zone, "p_before" timestamp with time zone, "p_take" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_search_email"("p_providers" "text"[], "p_query" "text", "p_after" timestamp with time zone, "p_before" timestamp with time zone, "p_take" integer, "p_sender" "text", "p_has_attachment" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_context record;
  v_query text := left(btrim(coalesce(p_query, '')), 300);
  v_sender text := left(lower(btrim(coalesce(p_sender, ''))), 320);
  v_take integer := greatest(1, least(coalesce(p_take, 10), 20));
  v_providers text[];
  v_result jsonb;
begin
  select * into v_context from public._multideck_dexter_context();
  if not public._multideck_dexter_has_permission(v_context.user_id, 'Email.Read')
     or not public._multideck_dexter_has_permission(v_context.user_id, 'Email.AIRead') then
    raise exception 'You do not have permission to use email with Dexter.' using errcode = '42501';
  end if;

  select coalesce(array_agg(distinct lower(btrim(provider))), array[]::text[])
  into v_providers
  from unnest(coalesce(p_providers, array[]::text[])) provider
  where lower(btrim(provider)) in ('gmail', 'outlook');

  if cardinality(v_providers) = 0
     or cardinality(v_providers) <> cardinality(coalesce(p_providers, array[]::text[])) then
    raise exception 'Choose Gmail, Outlook, or both as the email source.' using errcode = '22023';
  end if;
  if v_query = '' then
    raise exception 'Enter an email search term.' using errcode = '22023';
  end if;
  if p_after is not null and p_before is not null and p_after >= p_before then
    raise exception 'The email search date range is invalid.' using errcode = '22023';
  end if;

  with permitted_mailboxes as materialized (
    select *
    from public._multideck_dexter_email_mailboxes(v_context.user_id, v_context.company_id)
    where provider = any(v_providers)
  ),
  parameters as (
    select
      websearch_to_tsquery('simple'::regconfig, v_query) as search_query,
      to_tsquery(
        'simple'::regconfig,
        replace(plainto_tsquery('simple'::regconfig, v_query)::text, ' & ', ' | ')
      ) as fallback_query,
      nullif(v_sender, '') as sender_query,
      position('@' in v_sender) > 1 as sender_is_address,
      split_part(v_sender, '@', 1) as sender_local,
      split_part(v_sender, '@', 2) as sender_domain,
      plainto_tsquery('simple'::regconfig, v_sender) as sender_name_query,
      lower(v_query) = v_sender as query_repeats_sender
  ),
  base_candidates as (
    select
      message.*,
      permitted.provider,
      mailbox."CommMailbox_LastSyncedAt" as synced_at,
      coalesce(mailbox."CommMailbox_IndexStatus", 'pending') as index_status,
      search_document."AIDexterEmailSearch_Document" as search_vector,
      parameters.*
    from public."Comm_Messages" message
    join permitted_mailboxes permitted
      on permitted.mailbox_id = message."CommMessage_MailboxID"
    join public."Comm_Mailboxes" mailbox
      on mailbox."CommMailbox_ID" = message."CommMessage_MailboxID"
    join public."AI_DexterEmailSearchDocuments" search_document
      on search_document."AIDexterEmailSearch_MessageID" = message."CommMessage_ID"
    cross join parameters
    where not message."CommMessage_IsDeleted"
      and not message."CommMessage_IsDraft"
      and not message."CommMessage_IsSpam"
      and (p_has_attachment is distinct from true or message."CommMessage_HasAttachments")
      and (
        p_after is null
        or coalesce(
          message."CommMessage_MessageDate",
          message."CommMessage_ReceivedAt",
          message."CommMessage_SentAt",
          message."CommMessage_CreatedAt"
        ) >= p_after
      )
      and (
        p_before is null
        or coalesce(
          message."CommMessage_MessageDate",
          message."CommMessage_ReceivedAt",
          message."CommMessage_SentAt",
          message."CommMessage_CreatedAt"
        ) < p_before
      )
      and not exists (
        select 1
        from public."Comm_MessageFolders" membership
        join public."Comm_MailFolders" folder
          on folder."CommMailFolder_ID" = membership."CommMessageFolder_FolderID"
        where membership."CommMessageFolder_MessageID" = message."CommMessage_ID"
          and folder."CommMailFolder_RoleCode" in ('drafts', 'spam', 'trash')
      )
      and (
        search_document."AIDexterEmailSearch_Document" @@ parameters.search_query
        or search_document."AIDexterEmailSearch_Document" @@ parameters.fallback_query
        or (parameters.sender_query is not null and parameters.query_repeats_sender)
      )
  ),
  candidates as (
    select
      base_candidate.*,
      sender_match.address as matched_sender_address,
      sender_match.display_name as matched_sender_name,
      sender_match.exact_address as sender_exact,
      sender_match.exact_name as sender_name_exact,
      sender_match.local_similarity as sender_local_similarity,
      sender_match.fuzzy_address as sender_fuzzy
    from base_candidates base_candidate
    left join lateral (
      select
        scored.address,
        scored.display_name,
        scored.exact_address,
        scored.exact_name,
        scored.local_similarity,
        scored.sender_is_address
          and scored.sender_domain = scored.address_domain
          and greatest(length(scored.sender_local), length(scored.address_local)) >= 5
          and (
            scored.local_similarity >= 0.65
            or (
              scored.local_similarity >= 0.45
              and scored.candidate_has_attachment
              and scored.query_exact
            )
          ) as fuzzy_address
      from (
        select
          recipient."CommRecipient_Address" as address,
          recipient."CommRecipient_DisplayNameSnapshot" as display_name,
          base_candidate.sender_is_address,
          base_candidate.sender_local,
          base_candidate.sender_domain,
          base_candidate."CommMessage_HasAttachments" as candidate_has_attachment,
          base_candidate.search_vector @@ base_candidate.search_query as query_exact,
          split_part(lower(recipient."CommRecipient_NormalizedAddress"), '@', 1) as address_local,
          split_part(lower(recipient."CommRecipient_NormalizedAddress"), '@', 2) as address_domain,
          lower(recipient."CommRecipient_NormalizedAddress") = base_candidate.sender_query as exact_address,
          not base_candidate.sender_is_address
            and to_tsvector(
              'simple'::regconfig,
              coalesce(recipient."CommRecipient_DisplayNameSnapshot", '') || ' ' ||
              coalesce(recipient."CommRecipient_NormalizedAddress", '')
            ) @@ base_candidate.sender_name_query as exact_name,
          case
            when base_candidate.sender_is_address
              then extensions.similarity(
                base_candidate.sender_local,
                split_part(lower(recipient."CommRecipient_NormalizedAddress"), '@', 1)
              )
            else 0
          end as local_similarity
        from public."Comm_MessageRecipients" recipient
        where recipient."CommRecipient_MessageID" = base_candidate."CommMessage_ID"
          and recipient."CommRecipient_RecipientTypeCode" = 'from'
      ) scored
      order by scored.exact_address desc, scored.exact_name desc, scored.local_similarity desc, scored.address
      limit 1
    ) sender_match on base_candidate.sender_query is not null
  ),
  matches as (
    select
      candidate."CommMessage_ID" as message_id,
      candidate."CommMessage_ThreadID" as thread_id,
      candidate."CommMessage_MailboxID" as mailbox_id,
      candidate.provider,
      coalesce(nullif(candidate."CommMessage_Subject", ''), '(No subject)') as subject,
      left(coalesce(candidate."CommMessage_BodyPreview", candidate."CommMessage_BodyText", ''), 1000) as preview,
      coalesce(
        candidate."CommMessage_MessageDate",
        candidate."CommMessage_ReceivedAt",
        candidate."CommMessage_SentAt",
        candidate."CommMessage_CreatedAt"
      ) as occurred_at,
      candidate."CommMessage_HasAttachments" as has_attachments,
      candidate.synced_at,
      candidate.index_status,
      candidate.matched_sender_address,
      candidate.matched_sender_name,
      candidate.sender_local_similarity,
      case
        when candidate.sender_query is null and candidate.search_vector @@ candidate.search_query then 'exact'
        when (candidate.sender_exact or candidate.sender_name_exact)
          and candidate.search_vector @@ candidate.search_query then 'exact'
        when candidate.sender_fuzzy
          and candidate.search_vector @@ candidate.search_query then 'corrected_sender'
        when candidate.sender_exact or candidate.sender_name_exact then 'strong_candidate'
        when candidate.sender_fuzzy then 'possible_sender'
        else 'broad_candidate'
      end as match_quality,
      case
        when candidate.sender_query is null and candidate.search_vector @@ candidate.search_query
          then 100 + least(ts_rank_cd(candidate.search_vector, candidate.search_query), 10)
        when (candidate.sender_exact or candidate.sender_name_exact)
          and candidate.search_vector @@ candidate.search_query
          then 200 + least(ts_rank_cd(candidate.search_vector, candidate.search_query), 10)
        when candidate.sender_fuzzy
          and candidate.search_vector @@ candidate.search_query
          then 160 + candidate.sender_local_similarity * 10 + least(ts_rank_cd(candidate.search_vector, candidate.search_query), 10)
        when candidate.sender_exact or candidate.sender_name_exact
          then 130 + least(ts_rank_cd(candidate.search_vector, candidate.fallback_query), 0.99)
        when candidate.sender_fuzzy
          then 110 + candidate.sender_local_similarity * 10 + least(ts_rank_cd(candidate.search_vector, candidate.fallback_query), 0.99)
        else 10 * ts_rank_cd(
          to_tsvector('simple'::regconfig, coalesce(candidate."CommMessage_Subject", '')),
          candidate.fallback_query
        ) + least(ts_rank_cd(candidate.search_vector, candidate.fallback_query), 0.99)
      end as search_rank
    from candidates candidate
    where candidate.sender_query is null
      or candidate.sender_exact
      or candidate.sender_name_exact
      or candidate.sender_fuzzy
  ),
  thread_matches as (
    select distinct on (matches.thread_id)
      matches.*
    from matches
    order by matches.thread_id, matches.search_rank desc, matches.occurred_at desc, matches.message_id desc
  ),
  ordered as (
    select *
    from thread_matches
    order by search_rank desc, occurred_at desc, thread_id
    limit v_take + 1
  ),
  output_rows as (
    select
      jsonb_build_object(
        'threadId', ordered.thread_id,
        'matchMessageId', ordered.message_id,
        'mailboxId', ordered.mailbox_id,
        'provider', ordered.provider,
        'subject', ordered.subject,
        'preview', ordered.preview,
        'occurredAt', ordered.occurred_at,
        'hasAttachments', ordered.has_attachments,
        'matchQuality', ordered.match_quality,
        'matchedSender', case when ordered.matched_sender_address is null then null else jsonb_build_object(
          'address', ordered.matched_sender_address,
          'displayName', ordered.matched_sender_name,
          'role', 'from',
          'similarity', round(ordered.sender_local_similarity::numeric, 2)
        ) end,
        'syncedAt', ordered.synced_at,
        'indexStatus', ordered.index_status,
        'stale', ordered.synced_at is null
          or ordered.synced_at < now() - interval '30 minutes'
          or ordered.index_status = 'error',
        'participants', coalesce((
          select jsonb_agg(participant_row.value order by participant_row.sort_address)
          from (
            select distinct on (recipient."CommRecipient_NormalizedAddress")
              jsonb_build_object(
                'address', recipient."CommRecipient_Address",
                'displayName', recipient."CommRecipient_DisplayNameSnapshot",
                'role', recipient."CommRecipient_RecipientTypeCode"
              ) as value,
              recipient."CommRecipient_NormalizedAddress" as sort_address
            from public."Comm_MessageRecipients" recipient
            where recipient."CommRecipient_MessageID" = ordered.message_id
            order by recipient."CommRecipient_NormalizedAddress", recipient."CommRecipient_RecipientTypeCode"
          ) participant_row
        ), '[]'::jsonb),
        '_citation', jsonb_build_object(
          'title', ordered.subject,
          'url', '/inbox?provider=' || ordered.provider || '&mailbox=' || ordered.mailbox_id || '&thread=' || ordered.thread_id,
          'description', case ordered.provider when 'gmail' then 'Gmail email thread' else 'Outlook email thread' end
        )
      ) as value,
      ordered.search_rank,
      ordered.occurred_at,
      ordered.thread_id
    from ordered
    order by ordered.search_rank desc, ordered.occurred_at desc, ordered.thread_id
    limit v_take
  )
  select jsonb_build_object(
    'items', coalesce(jsonb_agg(output_rows.value order by output_rows.search_rank desc, output_rows.occurred_at desc, output_rows.thread_id), '[]'::jsonb),
    'hasMore', (select count(*) from ordered) > v_take,
    'query', v_query,
    'sender', nullif(v_sender, ''),
    'hasAttachment', p_has_attachment is true
  )
  into v_result
  from output_rows;

  return coalesce(v_result, jsonb_build_object(
    'items', '[]'::jsonb,
    'hasMore', false,
    'query', v_query,
    'sender', nullif(v_sender, ''),
    'hasAttachment', p_has_attachment is true
  ));
end;
$$;


ALTER FUNCTION "public"."multideck_dexter_search_email"("p_providers" "text"[], "p_query" "text", "p_after" timestamp with time zone, "p_before" timestamp with time zone, "p_take" integer, "p_sender" "text", "p_has_attachment" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_set_watch_status"("p_watch_id" "uuid", "p_status" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare v_context record;
begin
  select * into v_context from public._multideck_dexter_context();
  if p_status not in ('active','paused') then raise exception 'Choose active or paused.' using errcode = '22023'; end if;
  update public."AI_DexterWatches" set "AIDexterWatch_StatusCode"=p_status,"AIDexterWatch_IsArmed"=true,"AIDexterWatch_UpdatedAt"=now()
  where "AIDexterWatch_ID"=p_watch_id and "AIDexterWatch_OwnerUserID"=v_context.user_id and "AIDexterWatch_CompanyID"=v_context.company_id;
  if not found then raise exception 'Watch not found.' using errcode = 'P0002'; end if;
end; $$;


ALTER FUNCTION "public"."multideck_dexter_set_watch_status"("p_watch_id" "uuid", "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_settle_model_egress"("p_reservation_id" "uuid", "p_company_id" "uuid", "p_user_id" "uuid", "p_outcome" "text", "p_provider_request_id" "text", "p_input_units" integer, "p_output_units" integer, "p_error_code" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_row public."AI_DexterModelEgressAudit";
  v_cost numeric;
  v_input_units integer;
begin
  if auth.role() <> 'service_role' then raise exception 'server_only' using errcode = '42501'; end if;
  select * into v_row
  from public."AI_DexterModelEgressAudit"
  where "AIDexterEgress_ID" = p_reservation_id
    and "AIDexterEgress_CompanyID" = p_company_id
    and "AIDexterEgress_UserID" = p_user_id
  for update;
  if not found or v_row."AIDexterEgress_Outcome" <> 'attempted' then return; end if;

  v_input_units := greatest(coalesce(
    nullif(p_input_units, 0),
    case when v_row."AIDexterEgress_Provider" = 'mistral' then v_row."AIDexterEgress_InputUnits" else 0 end
  ), 0);
  if v_row."AIDexterEgress_Provider" = 'mistral' then
    v_cost := round(v_input_units * 0.003076923::numeric, 6);
  else
    v_cost := public._multideck_dexter_estimated_usage_gbp(
      case when lower(v_row."AIDexterEgress_Model")='gpt-6-astra' then 'gpt-6-astra' when lower(v_row."AIDexterEgress_Model") like '%terra%' then 'worker' else 'fast' end,
      v_input_units,
      p_output_units
    );
  end if;

  update public."AI_DexterModelEgressAudit"
  set
    "AIDexterEgress_InputUnits" = v_input_units,
    "AIDexterEgress_OutputUnits" = greatest(coalesce(p_output_units, 0), 0),
    "AIDexterEgress_ActualCostGBP" = v_cost,
    "AIDexterEgress_ProviderRequestID" = nullif(left(p_provider_request_id, 240), ''),
    "AIDexterEgress_Outcome" = case when p_outcome in ('succeeded', 'failed', 'denied') then p_outcome else 'failed' end,
    "AIDexterEgress_ErrorCode" = nullif(left(p_error_code, 120), ''),
    "AIDexterEgress_CompletedAt" = now()
  where "AIDexterEgress_ID" = p_reservation_id;
end;
$$;


ALTER FUNCTION "public"."multideck_dexter_settle_model_egress"("p_reservation_id" "uuid", "p_company_id" "uuid", "p_user_id" "uuid", "p_outcome" "text", "p_provider_request_id" "text", "p_input_units" integer, "p_output_units" integer, "p_error_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_settle_responses_egress"("p_reservation_id" "uuid", "p_company_id" "uuid", "p_user_id" "uuid", "p_outcome" "text", "p_response_id" "text", "p_usage" "jsonb", "p_error_code" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare entry public."AI_DexterModelEgressAudit";i integer;o integer;cached integer;written integer;cost numeric;
begin
  if auth.role() is distinct from 'service_role' then raise exception 'server_only' using errcode='42501';end if;
  select * into entry from public."AI_DexterModelEgressAudit" where "AIDexterEgress_ID"=p_reservation_id
    and "AIDexterEgress_CompanyID"=p_company_id and "AIDexterEgress_UserID"=p_user_id for update;
  if not found or entry."AIDexterEgress_Outcome"<>'attempted' then return;end if;
  if entry."AIDexterEgress_Provider"<>'openai' then raise exception 'Wrong provider reservation.' using errcode='22023';end if;
  i:=greatest(coalesce((p_usage->>'input_tokens')::integer,0),0);
  o:=greatest(coalesce((p_usage->>'output_tokens')::integer,0),0);
  cached:=greatest(coalesce((p_usage#>>'{input_tokens_details,cached_tokens}')::integer,0),0);
  written:=greatest(coalesce((p_usage#>>'{input_tokens_details,cache_write_tokens}')::integer,0),0);
  if lower(entry."AIDexterEgress_Model")='gpt-6-astra' then cost:=public._multideck_dexter_astra_usage_gbp(i,o,cached,written);end if;
  perform public.multideck_dexter_settle_model_egress(p_reservation_id,p_company_id,p_user_id,p_outcome,p_response_id,i,o,p_error_code);
  update public."AI_DexterModelEgressAudit" set "AIDexterEgress_CachedInputUnits"=cached,"AIDexterEgress_CacheWriteInputUnits"=written,
    "AIDexterEgress_ActualCostGBP"=coalesce(cost,"AIDexterEgress_ActualCostGBP") where "AIDexterEgress_ID"=p_reservation_id;
end $$;


ALTER FUNCTION "public"."multideck_dexter_settle_responses_egress"("p_reservation_id" "uuid", "p_company_id" "uuid", "p_user_id" "uuid", "p_outcome" "text", "p_response_id" "text", "p_usage" "jsonb", "p_error_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_settle_upload_reservation"("p_reservation_id" "uuid", "p_company_id" "uuid", "p_user_id" "uuid", "p_succeeded" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
begin
  if auth.role()<>'service_role' then raise exception 'server_only' using errcode='42501'; end if;
  update public."AI_DexterUploadReservations" set
    "AIDexterUploadReservation_Status"=case when p_succeeded then 'settled' else 'released' end,
    "AIDexterUploadReservation_CompletedAt"=now()
  where "AIDexterUploadReservation_ID"=p_reservation_id
    and "AIDexterUploadReservation_CompanyID"=p_company_id
    and "AIDexterUploadReservation_UserID"=p_user_id
    and "AIDexterUploadReservation_Status"='reserved';
end $$;


ALTER FUNCTION "public"."multideck_dexter_settle_upload_reservation"("p_reservation_id" "uuid", "p_company_id" "uuid", "p_user_id" "uuid", "p_succeeded" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_update_email_draft"("p_message_id" "uuid", "p_draft" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_context record;
  v_message public."AI_Messages";
  v_current_delivery jsonb;
  v_draft jsonb;
begin
  select * into v_context from public._multideck_dexter_context();
  if jsonb_typeof(p_draft) <> 'object'
     or coalesce(p_draft ->> 'mode', '') not in ('new','reply','reply_all','forward')
     or coalesce(p_draft ->> 'requestedAction', '') not in ('create_draft','send')
     or jsonb_typeof(coalesce(p_draft -> 'to', '[]'::jsonb)) <> 'array'
     or jsonb_typeof(coalesce(p_draft -> 'cc', '[]'::jsonb)) <> 'array'
     or jsonb_typeof(coalesce(p_draft -> 'bcc', '[]'::jsonb)) <> 'array'
     or jsonb_array_length(coalesce(p_draft -> 'to', '[]'::jsonb)) > 50
     or jsonb_array_length(coalesce(p_draft -> 'cc', '[]'::jsonb)) > 50
     or jsonb_array_length(coalesce(p_draft -> 'bcc', '[]'::jsonb)) > 50
     or char_length(coalesce(p_draft ->> 'subject', '')) > 500
     or char_length(coalesce(p_draft ->> 'bodyText', '')) > 50000
     or pg_column_size(p_draft) > 100000 then
    raise exception 'This email draft is not valid.' using errcode = '22023';
  end if;

  select message.* into v_message
  from public."AI_Messages" message
  join public."AI_Conversations" conversation on conversation."AICNV_ID" = message."AIMSG_ConversationID"
  where message."AIMSG_ID" = p_message_id
    and message."AIMSG_Role" = 'assistant'
    and conversation."AICNV_CompanyID" = v_context.company_id
    and conversation."AICNV_OwnerUserID" = v_context.user_id
    and jsonb_typeof(message."AIMSG_ContentJSON" #> '{metadata,emailDraft}') = 'object'
  for update;
  if not found then
    raise exception 'This Dexter email draft is unavailable.' using errcode = 'P0002';
  end if;

  v_current_delivery := coalesce(
    v_message."AIMSG_ContentJSON" #> '{metadata,emailDraft,delivery}',
    jsonb_build_object('status', 'draft')
  );
  if coalesce(v_current_delivery ->> 'status', 'draft') in ('sent', 'draft_created') then
    raise exception 'A completed email action cannot be edited.' using errcode = '22023';
  end if;

  v_draft := jsonb_strip_nulls(jsonb_build_object(
    'id', left(coalesce(p_draft ->> 'id', gen_random_uuid()::text), 80),
    'requestedAction', p_draft ->> 'requestedAction',
    'mode', p_draft ->> 'mode',
    'mailboxId', nullif(left(coalesce(p_draft ->> 'mailboxId', ''), 80), ''),
    'sourceMessageId', nullif(left(coalesce(p_draft ->> 'sourceMessageId', ''), 80), ''),
    'threadId', nullif(left(coalesce(p_draft ->> 'threadId', ''), 80), ''),
    'to', coalesce(p_draft -> 'to', '[]'::jsonb),
    'cc', coalesce(p_draft -> 'cc', '[]'::jsonb),
    'bcc', coalesce(p_draft -> 'bcc', '[]'::jsonb),
    'subject', left(coalesce(p_draft ->> 'subject', ''), 500),
    'bodyText', left(coalesce(p_draft ->> 'bodyText', ''), 50000),
    'trackOpens', coalesce((p_draft ->> 'trackOpens')::boolean, false),
    'signature', case when jsonb_typeof(p_draft -> 'signature') = 'object' then jsonb_build_object(
      'enabled', coalesce((p_draft #>> '{signature,enabled}')::boolean, true),
      'templateId', nullif(p_draft #>> '{signature,templateId}', '')::uuid,
      'revision', nullif(p_draft #>> '{signature,revision}', '')::integer,
      'fingerprint', left(p_draft #>> '{signature,fingerprint}', 64)
    ) end,
    'delivery', v_current_delivery
  ));

  update public."AI_Messages"
  set "AIMSG_ContentJSON" = jsonb_set(
    "AIMSG_ContentJSON", '{metadata,emailDraft}', v_draft, true
  )
  where "AIMSG_ID" = p_message_id;
  return v_draft;
end;
$$;


ALTER FUNCTION "public"."multideck_dexter_update_email_draft"("p_message_id" "uuid", "p_draft" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_dexter_update_writing_profile"("p_enabled" boolean, "p_profile_text" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_context record;
  v_profile_id uuid;
  v_profile_text text := btrim(coalesce(p_profile_text, ''));
  v_event text;
begin
  select * into v_context from public._multideck_dexter_context();
  if char_length(v_profile_text) > 2400 then
    raise exception 'Keep the writing profile within 2,400 characters.' using errcode = '22023';
  end if;

  update public."AI_DexterWritingProfiles" profile
  set "AIDexterWritingProfile_IsEnabled" = coalesce(p_enabled, false),
      "AIDexterWritingProfile_ProfileText" = v_profile_text,
      "AIDexterWritingProfile_StatusCode" = case
        when v_profile_text = '' then 'not_started'
        else 'ready'
      end,
      "AIDexterWritingProfile_LastError" = null,
      "AIDexterWritingProfile_UpdatedAt" = now()
  where profile."AIDexterWritingProfile_CompanyID" = v_context.company_id
    and profile."AIDexterWritingProfile_UserID" = v_context.user_id
  returning profile."AIDexterWritingProfile_ID" into v_profile_id;

  if not found then
    raise exception 'Create your writing profile before editing it.' using errcode = 'P0002';
  end if;

  v_event := case when not coalesce(p_enabled, false) then 'disabled' else 'edited' end;
  perform public._multideck_dexter_writing_profile_audit(
    v_profile_id, v_context.company_id, v_context.user_id, v_event,
    case when v_profile_text = '' then 'not_started' else 'ready' end, 0
  );
  return public.multideck_dexter_get_writing_profile();
end;
$$;


ALTER FUNCTION "public"."multideck_dexter_update_writing_profile"("p_enabled" boolean, "p_profile_text" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_finance_approve_configuration"("p_company_id" "uuid", "p_user_id" "uuid", "p_run_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare v_run public."FIN_ConfigurationRuns"; v_entity public."cmp_LegalEntities"; v_connection uuid; v_provider_currency text; v_currency_initialised boolean:=false;
begin
  if not exists(select 1 from public."cmp_Users" where "User_ID"=p_user_id and "Company_ID"=p_company_id and coalesce("User_AccessStatus",'active')='active') then raise exception 'The finance operator is outside this workspace.' using errcode='42501'; end if;
  select * into v_run from public."FIN_ConfigurationRuns" where "FINConfigRun_ID"=p_run_id for update; if not found or v_run."FINConfigRun_StatusCode"<>'awaiting_approval' then raise exception 'That finance configuration is not awaiting approval.' using errcode='22023'; end if;
  select * into v_entity from public."cmp_LegalEntities" where "LegalEntity_ID"=v_run."FINConfigRun_LegalEntityID" and "Company_ID"=p_company_id and "LegalEntity_IsActive" for update; if not found then raise exception 'Finance configuration is outside this workspace.' using errcode='42501'; end if;
  if v_run."FINConfigRun_ProviderCode"<>'erpnext' then raise exception 'This provider adapter is recognised but not enabled yet.' using errcode='22023'; end if;
  if nullif(btrim(v_run."FINConfigRun_ExternalCompany"),'') is null then raise exception 'Choose the accounting Company.' using errcode='22023'; end if;
  if not exists(select 1 from public."RefCountry" where upper("RN_Code")=upper(v_run."FINConfigRun_CountryCode") and coalesce("RN_IsActive",true)) then raise exception 'Enter a valid two-letter ISO country code.' using errcode='22023'; end if;
  v_provider_currency:=upper(coalesce(v_run."FINConfigRun_PreviewJSON"#>>'{providerPreflight,baseCurrencyCode}',''));
  if v_provider_currency!~'^[A-Z]{3}$' then raise exception 'Repeat the accounting Company currency preflight before approval.' using errcode='22023'; end if;
  if upper(coalesce(v_entity."LegalEntity_BaseCurrencyCodeSnapshot",''))!~'^[A-Z]{3}$' then
    update public."cmp_LegalEntities" set "LegalEntity_BaseCurrencyCodeSnapshot"=v_provider_currency,"LegalEntity_UpdatedAt"=now(),"LegalEntity_UpdatedBy"=p_user_id where "LegalEntity_ID"=v_entity."LegalEntity_ID";
    v_entity."LegalEntity_BaseCurrencyCodeSnapshot":=v_provider_currency; v_currency_initialised:=true;
  elsif upper(v_entity."LegalEntity_BaseCurrencyCodeSnapshot")<>v_provider_currency then raise exception 'The provider and legal-entity base currencies no longer match.' using errcode='22023'; end if;
  select "ACCIC_ID" into v_connection from public."ACCI_Connections" where "ACCIC_LegalEntityID"=v_entity."LegalEntity_ID" and "ACCIC_ProviderCode"=v_run."FINConfigRun_ProviderCode" and "ACCIC_StatusCode"<>'disabled' order by "ACCIC_UpdatedAt" desc limit 1 for update;
  if v_connection is null then
    insert into public."ACCI_Connections"("ACCIC_ProviderCode","ACCIC_Name","ACCIC_StatusCode","ACCIC_LegalEntityID","ACCIC_Environment","ACCIC_AuthType","ACCIC_SecretRef","ACCIC_ExternalTenantName","ACCIC_ExternalBaseCurrencyCode","ACCIC_ExternalCountryCode","ACCIC_SettingsJSON","ACCIC_CreatedBy","ACCIC_UpdatedBy")
    values(v_run."FINConfigRun_ProviderCode",v_entity."LegalEntity_Name"||' · '||v_run."FINConfigRun_ExternalCompany",'active',v_entity."LegalEntity_ID",'production','api_token','tenant-edge-secret:erpnext',v_run."FINConfigRun_ExternalCompany",upper(v_entity."LegalEntity_BaseCurrencyCodeSnapshot"),v_run."FINConfigRun_CountryCode",jsonb_build_object('configurationRunId',p_run_id,'externalCompany',v_run."FINConfigRun_ExternalCompany"),p_user_id,p_user_id)
    returning "ACCIC_ID" into v_connection;
  else
    update public."ACCI_Connections" set "ACCIC_Name"=v_entity."LegalEntity_Name"||' · '||v_run."FINConfigRun_ExternalCompany","ACCIC_StatusCode"='active',"ACCIC_ExternalTenantName"=v_run."FINConfigRun_ExternalCompany","ACCIC_ExternalBaseCurrencyCode"=upper(v_entity."LegalEntity_BaseCurrencyCodeSnapshot"),"ACCIC_ExternalCountryCode"=v_run."FINConfigRun_CountryCode","ACCIC_SettingsJSON"="ACCIC_SettingsJSON"||jsonb_build_object('configurationRunId',p_run_id,'externalCompany',v_run."FINConfigRun_ExternalCompany"),"ACCIC_UpdatedAt"=now(),"ACCIC_UpdatedBy"=p_user_id where "ACCIC_ID"=v_connection;
  end if;
  update public."ACCI_Connections" set "ACCIC_StatusCode"='disabled',"ACCIC_UpdatedAt"=now(),"ACCIC_UpdatedBy"=p_user_id where "ACCIC_LegalEntityID"=v_entity."LegalEntity_ID" and "ACCIC_ID"<>v_connection and "ACCIC_StatusCode"='active';
  update public."cmp_LegalEntities" set "LegalEntity_SettingsJSON"="LegalEntity_SettingsJSON"||jsonb_build_object('financeProvider',jsonb_build_object('providerCode',v_run."FINConfigRun_ProviderCode",'externalCompany',v_run."FINConfigRun_ExternalCompany",'connectionId',v_connection)),"LegalEntity_UpdatedAt"=now(),"LegalEntity_UpdatedBy"=p_user_id where "LegalEntity_ID"=v_entity."LegalEntity_ID";
  update public."FIN_ConfigurationRuns" set "FINConfigRun_StatusCode"='completed',"FINConfigRun_ApprovedAt"=now(),"FINConfigRun_ApprovedBy"=p_user_id,"FINConfigRun_CompletedAt"=now(),"FINConfigRun_ProvisioningJSON"=jsonb_build_object('connectionId',v_connection,'providerRecordsChanged',false,'mappingReviewRequired',true,'baseCurrencyCode',v_provider_currency,'baseCurrencyInitialised',v_currency_initialised) where "FINConfigRun_ID"=p_run_id;
  insert into public."FIN_ConfigurationRunEvents"("FINConfigRunEvent_RunID","FINConfigRunEvent_TypeCode","FINConfigRunEvent_By","FINConfigRunEvent_DetailJSON") values(p_run_id,'approved',p_user_id,jsonb_build_object('connectionId',v_connection,'providerRecordsChanged',false,'baseCurrencyCode',v_provider_currency,'baseCurrencyInitialised',v_currency_initialised));
  if v_currency_initialised then
    insert into public."Audit_Events"("AuditEvent_EventTypeCode","AuditEvent_UserID","AuditEvent_LegalEntityID","AuditEvent_SourceApp","AuditEvent_SourceModule","AuditEvent_SourceTableSchema","AuditEvent_SourceTableName","AuditEvent_RecordTypeCode","AuditEvent_RecordID","AuditEvent_Action","AuditEvent_Title","AuditEvent_MetadataJSON")
    values('finance_lifecycle',p_user_id,v_entity."LegalEntity_ID",'multideck-app','finance','public','cmp_LegalEntities','finance_configuration',v_entity."LegalEntity_ID",'initialise_base_currency','Legal entity base currency initialised from reviewed provider setup',jsonb_build_object('configurationRunId',p_run_id,'providerCode',v_run."FINConfigRun_ProviderCode",'externalCompany',v_run."FINConfigRun_ExternalCompany",'baseCurrencyCode',v_provider_currency));
  end if;
  return jsonb_build_object('runId',p_run_id,'status','completed','connectionId',v_connection);
end;
$_$;


ALTER FUNCTION "public"."multideck_finance_approve_configuration"("p_company_id" "uuid", "p_user_id" "uuid", "p_run_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_finance_assign_job_period"("p_company_id" "uuid", "p_user_id" "uuid", "p_legal_entity_id" "uuid", "p_job_id" "uuid", "p_period_code" "text", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_job public."Job_Header"%rowtype; v_from text; v_period_id uuid;
begin
  if nullif(btrim(p_reason),'') is null then raise exception 'Explain why the job period is changing.' using errcode='22023'; end if;
  if not exists(select 1 from public."cmp_Users" where "User_ID"=p_user_id and "Company_ID"=p_company_id and coalesce("User_AccessStatus",'active')='active') then raise exception 'The finance operator is outside this workspace.' using errcode='42501'; end if;
  if not exists(select 1 from public."cmp_LegalEntities" where "LegalEntity_ID"=p_legal_entity_id and "Company_ID"=p_company_id) then raise exception 'That legal entity is outside this workspace.' using errcode='42501'; end if;
  select job.* into v_job from public."Job_Header" job join public."cmp_Offices" office on office."Office_ID"=coalesce(job."Job_OrgOfficeID",job."Job_OfficeID") where job."Job_ID"=p_job_id and office."Company_ID"=p_company_id and not job."Job_IsDeleted" for update;
  if not found then raise exception 'Job not found.' using errcode='P0002'; end if;
  if v_job."Job_LegalEntityID" is not null and v_job."Job_LegalEntityID"<>p_legal_entity_id then raise exception 'That job belongs to another legal entity.' using errcode='42501'; end if;
  v_period_id:=public._multideck_finance_ensure_period(p_legal_entity_id,p_period_code,p_user_id);
  v_from:=v_job."Job_Period";
  if v_from=p_period_code and v_job."Job_LegalEntityID"=p_legal_entity_id then return jsonb_build_object('jobId',p_job_id,'periodCode',p_period_code,'changed',false); end if;
  insert into public."FIN_JobPeriodHistory"("FINJobPeriodHistory_JobID","FINJobPeriodHistory_LegalEntityID","FINJobPeriodHistory_FromPeriodCode","FINJobPeriodHistory_ToPeriodCode","FINJobPeriodHistory_Reason","FINJobPeriodHistory_AssignedBy") values(p_job_id,p_legal_entity_id,v_from,p_period_code,btrim(p_reason),p_user_id);
  update public."Job_Header" set "Job_Period"=p_period_code,"Job_LegalEntityID"=p_legal_entity_id,"Job_UpdatedAt"=now(),"Job_UpdatedBy"=p_user_id where "Job_ID"=p_job_id;
  insert into public."Audit_Events"("AuditEvent_EventTypeCode","AuditEvent_UserID","AuditEvent_LegalEntityID","AuditEvent_SourceApp","AuditEvent_SourceModule","AuditEvent_SourceTableSchema","AuditEvent_SourceTableName","AuditEvent_RecordTypeCode","AuditEvent_RecordID","AuditEvent_Action","AuditEvent_Title","AuditEvent_Reason","AuditEvent_HasFieldChanges","AuditEvent_ChangedFieldCount","AuditEvent_MetadataJSON") values('finance_lifecycle',p_user_id,p_legal_entity_id,'multideck-app','finance','public','Job_Header','job_management_period',p_job_id,'assign_job_management_period','Job management period assigned',btrim(p_reason),true,1,jsonb_build_object('fromPeriod',v_from,'toPeriod',p_period_code,'periodId',v_period_id));
  return jsonb_build_object('jobId',p_job_id,'periodCode',p_period_code,'changed',true);
end; $$;


ALTER FUNCTION "public"."multideck_finance_assign_job_period"("p_company_id" "uuid", "p_user_id" "uuid", "p_legal_entity_id" "uuid", "p_job_id" "uuid", "p_period_code" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_finance_create_cash_draft"("p_company_id" "uuid", "p_user_id" "uuid", "p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  v_type text:=p_input->>'type'; v_entity uuid; v_entity_currency text; v_party uuid; v_bank uuid; v_date date; v_currency text; v_exchange numeric; v_amount numeric; v_number text; v_cash uuid; v_idempotency uuid;
  v_allocation jsonb; v_document public."FIN_Documents"; v_allocated numeric; v_total_allocated numeric:=0; v_idempotent_company uuid;
begin
  if jsonb_typeof(p_input)<>'object' then raise exception 'Finance input must be an object.' using errcode='22023'; end if;
  if not exists(select 1 from public."cmp_Users" where "User_ID"=p_user_id and "Company_ID"=p_company_id and coalesce("User_AccessStatus",'active')='active') then raise exception 'The finance operator is outside this workspace.' using errcode='42501'; end if;
  if v_type not in ('customer_receipt','supplier_payment') then raise exception 'Choose a customer receipt or supplier payment.' using errcode='22023'; end if;
  begin v_entity:=(p_input->>'legalEntityId')::uuid; v_party:=(p_input->>'partyOrgId')::uuid; v_bank:=nullif(p_input->>'bankAccountId','')::uuid; exception when invalid_text_representation then raise exception 'Choose a valid legal entity, party and bank account.' using errcode='22023'; end;
  if v_bank is null then raise exception 'Choose an active bank account before recording a receipt or payment.' using errcode='22023'; end if;
  select upper("LegalEntity_BaseCurrencyCodeSnapshot") into v_entity_currency from public."cmp_LegalEntities" where "LegalEntity_ID"=v_entity and "Company_ID"=p_company_id and "LegalEntity_IsActive";
  if not found then raise exception 'That legal entity is not active in this workspace.' using errcode='42501'; end if;
  if v_entity_currency is null or v_entity_currency!~'^[A-Z]{3}$' then raise exception 'Configure a valid base currency for this legal entity.' using errcode='22023'; end if;
  if not exists(select 1 from public."Org_Master" where "Org_id"=v_party) then raise exception 'Choose a valid customer or supplier.' using errcode='22023'; end if;
  if not exists(select 1 from public."FIN_BankAccounts" where "FINBank_ID"=v_bank and "FINBank_LegalEntityID"=v_entity and "FINBank_IsActive") then raise exception 'Choose an active bank account for this legal entity.' using errcode='22023'; end if;
  begin v_date:=coalesce(nullif(p_input->>'transactionDate','')::date,current_date); v_amount:=(p_input->>'amount')::numeric; exception when invalid_datetime_format or invalid_text_representation then raise exception 'Check the cash date and amount.' using errcode='22023'; end;
  if v_amount::text in ('NaN','Infinity','-Infinity') or v_amount<=0 then raise exception 'The receipt or payment amount must be greater than zero.' using errcode='22023'; end if;
  v_currency:=upper(coalesce(nullif(btrim(p_input->>'currencyCode'),''),v_entity_currency)); if v_currency!~'^[A-Z]{3}$' then raise exception 'Enter a three-letter currency code.' using errcode='22023'; end if;
  begin v_exchange:=coalesce(nullif(p_input->>'exchangeRate','')::numeric,1); exception when invalid_text_representation then raise exception 'Enter a valid exchange rate.' using errcode='22023'; end;
  if v_exchange::text in ('NaN','Infinity','-Infinity') or v_exchange<=0 or (v_currency<>v_entity_currency and nullif(p_input->>'exchangeRate','') is null) then raise exception 'Enter the reviewed exchange rate from transaction currency to base currency.' using errcode='22023'; end if;
  if v_currency=v_entity_currency then v_exchange:=1; end if;
  if not exists(select 1 from public."FIN_BankAccounts" where "FINBank_ID"=v_bank and "FINBank_LegalEntityID"=v_entity and upper("FINBank_CurrencyCode")=v_currency and "FINBank_IsActive") then raise exception 'The bank account currency must match the receipt or payment currency.' using errcode='22023'; end if;
  if jsonb_typeof(coalesce(p_input->'allocations','[]'::jsonb)) is distinct from 'array' then raise exception 'Cash allocations must be an array.' using errcode='22023'; end if;
  if coalesce(jsonb_array_length(coalesce(p_input->'allocations','[]'::jsonb)),0)>100 then raise exception 'Add no more than 100 allocations.' using errcode='22023'; end if;
  begin v_idempotency:=coalesce(nullif(p_input->>'idempotencyKey','')::uuid,gen_random_uuid()); exception when invalid_text_representation then raise exception 'The finance request key is invalid.' using errcode='22023'; end;
  select cash."FINCash_ID",entity."Company_ID" into v_cash,v_idempotent_company from public."FIN_CashTransactions" cash join public."cmp_LegalEntities" entity on entity."LegalEntity_ID"=cash."FINCash_LegalEntityID" where cash."FINCash_IdempotencyKey"=v_idempotency;
  if v_cash is not null and v_idempotent_company is distinct from p_company_id then raise exception 'The finance request key belongs to another workspace.' using errcode='42501'; end if;
  if v_cash is not null then return (select to_jsonb(c) from public."FIN_CashTransactions" c where c."FINCash_ID"=v_cash); end if;
  v_number:=public._multideck_finance_next_number(v_entity,v_type);
  insert into public."FIN_CashTransactions"("FINCash_TypeCode","FINCash_StatusCode","FINCash_Number","FINCash_LegalEntityID","FINCash_BankAccountID","FINCash_PartyOrgID","FINCash_TransactionDate","FINCash_AccountingDate","FINCash_CurrencyCodeSnapshot","FINCash_ExchangeRate","FINCash_Amount","FINCash_LocalAmount","FINCash_UnallocatedAmount","FINCash_LocalUnallocatedAmount","FINCash_Reference","FINCash_IdempotencyKey","FINCash_MetadataJSON","FINCash_CreatedBy","FINCash_UpdatedBy")
  values(v_type,'draft',v_number,v_entity,v_bank,v_party,v_date,v_date,v_currency,v_exchange,v_amount,round(v_amount*v_exchange,4),v_amount,round(v_amount*v_exchange,4),nullif(left(btrim(p_input->>'reference'),180),''),v_idempotency,jsonb_build_object('source','multideck_finance','baseCurrency',v_entity_currency),p_user_id,p_user_id)
  returning "FINCash_ID" into v_cash;
  for v_allocation in select value from jsonb_array_elements(coalesce(p_input->'allocations','[]'::jsonb)) loop
    begin v_allocated:=(v_allocation->>'amount')::numeric; select document.* into v_document from public."FIN_Documents" document join public."cmp_LegalEntities" entity on entity."LegalEntity_ID"=document."FINDoc_LegalEntityID" where document."FINDoc_ID"=(v_allocation->>'documentId')::uuid and entity."Company_ID"=p_company_id;
    exception when invalid_text_representation then raise exception 'Choose a valid document for every allocation.' using errcode='22023'; end;
    if not found or v_allocated::text in ('NaN','Infinity','-Infinity') or v_document."FINDoc_LegalEntityID" is distinct from v_entity or v_document."FINDoc_PartyOrgID" is distinct from v_party or v_document."FINDoc_CurrencyCodeSnapshot"<>v_currency or v_document."FINDoc_StatusCode" not in ('approved','submitted') or v_document."FINDoc_TypeCode"<>(case when v_type='customer_receipt' then 'sl_invoice' else 'pl_invoice' end) or v_allocated<=0 or v_allocated>v_document."FINDoc_OutstandingAmount" then
      raise exception 'An allocation does not match this party, currency, ledger or open balance.' using errcode='22023';
    end if;
    if exists(select 1 from public."FIN_CashAllocations" where "FINCashAlloc_CashID"=v_cash and "FINCashAlloc_DocumentID"=v_document."FINDoc_ID") then raise exception 'Allocate to each document once.' using errcode='22023'; end if;
    insert into public."FIN_CashAllocations"("FINCashAlloc_CashID","FINCashAlloc_DocumentID","FINCashAlloc_AllocationStatusCode","FINCashAlloc_AllocatedAmount","FINCashAlloc_LocalAllocatedAmount","FINCashAlloc_AllocatedBy") values(v_cash,v_document."FINDoc_ID",'pending',v_allocated,round(v_allocated*v_document."FINDoc_ExchangeRate",4),p_user_id);
    v_total_allocated:=v_total_allocated+v_allocated;
  end loop;
  if v_total_allocated>v_amount then raise exception 'Allocations cannot exceed the receipt or payment amount.' using errcode='22023'; end if;
  update public."FIN_CashTransactions" set "FINCash_UnallocatedAmount"=v_amount-v_total_allocated,"FINCash_LocalUnallocatedAmount"=round((v_amount-v_total_allocated)*v_exchange,4),"FINCash_UpdatedAt"=now() where "FINCash_ID"=v_cash;
  insert into public."Audit_Events"("AuditEvent_EventTypeCode","AuditEvent_UserID","AuditEvent_LegalEntityID","AuditEvent_SourceApp","AuditEvent_SourceModule","AuditEvent_SourceTableSchema","AuditEvent_SourceTableName","AuditEvent_RecordTypeCode","AuditEvent_RecordID","AuditEvent_Action","AuditEvent_Title","AuditEvent_MetadataJSON")
  values('finance_lifecycle',p_user_id,v_entity,'multideck-app','finance','public','FIN_CashTransactions',v_type,v_cash,'create_draft','Finance cash draft created',jsonb_build_object('number',v_number,'amount',v_amount,'allocatedAmount',v_total_allocated,'currency',v_currency,'exchangeRate',v_exchange));
  return (select to_jsonb(c) from public."FIN_CashTransactions" c where c."FINCash_ID"=v_cash);
end;
$_$;


ALTER FUNCTION "public"."multideck_finance_create_cash_draft"("p_company_id" "uuid", "p_user_id" "uuid", "p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_finance_create_document_draft"("p_company_id" "uuid", "p_user_id" "uuid", "p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  v_type text := p_input ->> 'type';
  v_entity uuid;
  v_entity_currency text;
  v_entity_currency_status text;
  v_party uuid;
  v_job uuid;
  v_job_company uuid;
  v_job_entity uuid;
  v_job_party uuid;
  v_date date;
  v_due date;
  v_currency text;
  v_exchange numeric;
  v_source_kind text;
  v_number text;
  v_document uuid;
  v_line jsonb;
  v_index integer := 0;
  v_quantity numeric;
  v_unit numeric;
  v_net numeric;
  v_tax numeric;
  v_gross numeric;
  v_total_net numeric := 0;
  v_total_tax numeric := 0;
  v_total_gross numeric := 0;
  v_line_id uuid;
  v_idempotency uuid;
  v_idempotent_company uuid;
  v_tax_status text;
begin
  if jsonb_typeof(p_input) <> 'object' then
    raise exception 'Finance input must be an object.' using errcode = '22023';
  end if;
  if not exists (
    select 1 from public."cmp_Users"
    where "User_ID" = p_user_id
      and "Company_ID" = p_company_id
      and coalesce("User_AccessStatus", 'active') = 'active'
  ) then
    raise exception 'The finance operator is outside this workspace.' using errcode = '42501';
  end if;
  if v_type not in ('sl_invoice', 'credit_note', 'pl_invoice', 'debit_note') then
    raise exception 'Choose a supported finance document type.' using errcode = '22023';
  end if;

  begin
    v_entity := (p_input ->> 'legalEntityId')::uuid;
    v_party := (p_input ->> 'partyOrgId')::uuid;
  exception when invalid_text_representation then
    raise exception 'Choose a valid legal entity and party.' using errcode = '22023';
  end;

  select upper(entity."LegalEntity_BaseCurrencyCodeSnapshot")
  into v_entity_currency
  from public."cmp_LegalEntities" entity
  where entity."LegalEntity_ID" = v_entity
    and entity."Company_ID" = p_company_id
    and entity."LegalEntity_IsActive";
  if not found then
    raise exception 'That legal entity is not active in this workspace.' using errcode = '42501';
  end if;

  if v_entity_currency ~ '^[A-Z]{3}$' then
    v_entity_currency_status := 'approved';
  else
    select upper(run."FINConfigRun_PreviewJSON" #>> '{providerPreflight,baseCurrencyCode}')
    into v_entity_currency
    from public."FIN_ConfigurationRuns" run
    where run."FINConfigRun_LegalEntityID" = v_entity
      and run."FINConfigRun_StatusCode" = 'awaiting_approval'
      and run."FINConfigRun_ProviderCode" = run."FINConfigRun_PreviewJSON" #>> '{providerPreflight,providerCode}'
      and run."FINConfigRun_ExternalCompany" = run."FINConfigRun_PreviewJSON" #>> '{providerPreflight,externalCompany}'
      and coalesce((run."FINConfigRun_PreviewJSON" #>> '{providerPreflight,providerRecordsChanged}')::boolean, false) = false
      and upper(coalesce(run."FINConfigRun_PreviewJSON" #>> '{providerPreflight,baseCurrencyCode}', '')) ~ '^[A-Z]{3}$'
      and run."FINConfigRun_RequestedAt" >= now() - interval '24 hours'
    order by run."FINConfigRun_RequestedAt" desc
    limit 1;
    if v_entity_currency is null then
      raise exception 'Approve or prepare a current accounting Company currency review before creating this draft.' using errcode = '22023';
    end if;
    v_entity_currency_status := 'pending_configuration';
  end if;

  if not exists (select 1 from public."Org_Master" where "Org_id" = v_party) then
    raise exception 'Choose a valid customer or supplier.' using errcode = '22023';
  end if;
  begin
    v_date := coalesce(nullif(p_input ->> 'documentDate', '')::date, current_date);
    v_due := nullif(p_input ->> 'dueDate', '')::date;
  exception when invalid_datetime_format then
    raise exception 'Check the document and due dates.' using errcode = '22023';
  end;
  if v_due is not null and v_due < v_date then
    raise exception 'The due date cannot be before the document date.' using errcode = '22023';
  end if;

  v_currency := upper(coalesce(nullif(btrim(p_input ->> 'currencyCode'), ''), v_entity_currency));
  if v_currency !~ '^[A-Z]{3}$' then
    raise exception 'Enter a three-letter currency code.' using errcode = '22023';
  end if;
  begin
    v_exchange := coalesce(nullif(p_input ->> 'exchangeRate', '')::numeric, 1);
  exception when invalid_text_representation then
    raise exception 'Enter a valid exchange rate.' using errcode = '22023';
  end;
  if v_exchange::text in ('NaN', 'Infinity', '-Infinity')
    or v_exchange <= 0
    or (v_currency <> v_entity_currency and nullif(p_input ->> 'exchangeRate', '') is null) then
    raise exception 'Enter the reviewed exchange rate from document currency to base currency.' using errcode = '22023';
  end if;
  if v_currency = v_entity_currency then v_exchange := 1; end if;

  if nullif(p_input ->> 'sourceJobId', '') is not null then
    begin
      v_job := (p_input ->> 'sourceJobId')::uuid;
    exception when invalid_text_representation then
      raise exception 'Choose a valid job.' using errcode = '22023';
    end;
    select
      office."Company_ID",
      job."Job_LegalEntityID",
      case when v_type in ('sl_invoice', 'credit_note') then job."Job_Customer" else job."Job_Supplier" end
    into v_job_company, v_job_entity, v_job_party
    from public."Job_Header" job
    join public."cmp_Offices" office on office."Office_ID" = coalesce(job."Job_OrgOfficeID", job."Job_OfficeID")
    where job."Job_ID" = v_job and not job."Job_IsDeleted";
    if v_job_company is distinct from p_company_id
      or (v_job_entity is not null and v_job_entity is distinct from v_entity) then
      raise exception 'That job is outside the selected company or legal entity.' using errcode = '42501';
    end if;
    if v_job_party is null or v_job_party is distinct from v_party then
      raise exception 'The selected party must match the customer or supplier on the job.' using errcode = '22023';
    end if;
  end if;

  if jsonb_typeof(p_input -> 'lines') <> 'array'
    or jsonb_array_length(p_input -> 'lines') not between 1 and 100 then
    raise exception 'Add between one and 100 document lines.' using errcode = '22023';
  end if;
  begin
    v_idempotency := coalesce(nullif(p_input ->> 'idempotencyKey', '')::uuid, gen_random_uuid());
  exception when invalid_text_representation then
    raise exception 'The finance request key is invalid.' using errcode = '22023';
  end;

  select document."FINDoc_ID", entity."Company_ID"
  into v_document, v_idempotent_company
  from public."FIN_Documents" document
  join public."cmp_LegalEntities" entity on entity."LegalEntity_ID" = document."FINDoc_LegalEntityID"
  where document."FINDoc_IdempotencyKey" = v_idempotency;
  if v_document is not null and v_idempotent_company is distinct from p_company_id then
    raise exception 'The finance request key belongs to another workspace.' using errcode = '42501';
  end if;
  if v_document is not null then
    return (select to_jsonb(document) from public."FIN_Documents" document where document."FINDoc_ID" = v_document);
  end if;

  v_source_kind := case when v_job is null then 'manual' else 'job' end;
  v_number := public._multideck_finance_next_number(v_entity, v_type);
  insert into public."FIN_Documents"(
    "FINDoc_TypeCode", "FINDoc_StatusCode", "FINDoc_Number", "FINDoc_LegalEntityID", "FINDoc_PartyOrgID", "FINDoc_PartyRole",
    "FINDoc_DocumentDate", "FINDoc_AccountingDate", "FINDoc_DueDate", "FINDoc_CurrencyCodeSnapshot", "FINDoc_SourceJobID", "FINDoc_SourceTable", "FINDoc_SourceID",
    "FINDoc_SourceKindCode", "FINDoc_IdempotencyKey", "FINDoc_ExchangeRate", "FINDoc_MetadataJSON", "FINDoc_CreatedBy", "FINDoc_UpdatedBy"
  ) values (
    v_type, 'draft', v_number, v_entity, v_party, case when v_type in ('sl_invoice', 'credit_note') then 'customer' else 'supplier' end,
    v_date, v_date, v_due, v_currency, v_job, case when v_job is null then null else 'Job_Header' end, v_job,
    v_source_kind, v_idempotency, v_exchange,
    jsonb_build_object('source', 'multideck_finance', 'sourceKind', v_source_kind, 'baseCurrency', v_entity_currency, 'baseCurrencyStatus', v_entity_currency_status, 'taxStatus', 'pending'),
    p_user_id, p_user_id
  ) returning "FINDoc_ID" into v_document;

  for v_line in select value from jsonb_array_elements(p_input -> 'lines') loop
    v_index := v_index + 1;
    begin
      v_quantity := coalesce(nullif(v_line ->> 'quantity', '')::numeric, 1);
      v_unit := coalesce(nullif(v_line ->> 'unitAmount', '')::numeric, 0);
    exception when invalid_text_representation then
      raise exception 'Check finance line %.', v_index using errcode = '22023';
    end;
    if v_quantity::text in ('NaN', 'Infinity', '-Infinity')
      or v_unit::text in ('NaN', 'Infinity', '-Infinity')
      or nullif(btrim(v_line ->> 'description'), '') is null
      or length(v_line ->> 'description') > 1000
      or nullif(btrim(v_line ->> 'chargeCode'), '') is null
      or length(v_line ->> 'chargeCode') > 80
      or length(coalesce(v_line ->> 'taxCode', '')) > 80
      or v_quantity <= 0
      or v_unit < 0 then
      raise exception 'Check finance line %.', v_index using errcode = '22023';
    end if;

    -- The rate is always zero at the RPC boundary. The line trigger resolves
    -- the approved statutory rate when one exists and otherwise keeps it pending.
    v_net := round(v_quantity * v_unit, 4) * case when v_type in ('credit_note', 'debit_note') then -1 else 1 end;
    insert into public."FIN_DocumentLines"(
      "FINDocLine_DocumentID", "FINDocLine_LineNo", "FINDocLine_LineTypeCode", "FINDocLine_ChargeCodeSnapshot", "FINDocLine_Description", "FINDocLine_Quantity", "FINDocLine_UnitAmount",
      "FINDocLine_NetAmount", "FINDocLine_TaxCodeSnapshot", "FINDocLine_TaxRatePercent", "FINDocLine_TaxAmount", "FINDocLine_GrossAmount",
      "FINDocLine_LocalNetAmount", "FINDocLine_LocalTaxAmount", "FINDocLine_LocalGrossAmount"
    ) values (
      v_document, v_index,
      case when v_job is not null then 'freight' when coalesce(v_line ->> 'lineType', '') = 'ancillary' then 'ancillary' else 'service' end,
      left(btrim(v_line ->> 'chargeCode'), 80), btrim(v_line ->> 'description'), v_quantity, v_unit,
      v_net, nullif(left(btrim(v_line ->> 'taxCode'), 80), ''), 0, 0, v_net,
      round(v_net * v_exchange, 4), 0, round(v_net * v_exchange, 4)
    ) returning
      "FINDocLine_ID", "FINDocLine_NetAmount", "FINDocLine_TaxAmount", "FINDocLine_GrossAmount"
    into v_line_id, v_net, v_tax, v_gross;

    if v_job is not null then
      insert into public."FIN_DocumentLineJobLinks"(
        "FINDocLineJob_DocumentID", "FINDocLineJob_DocumentLineID", "FINDocLineJob_JobID", "FINDocLineJob_LinkTypeCode", "FINDocLineJob_NetAmount", "FINDocLineJob_LocalNetAmount", "FINDocLineJob_PercentOfLine"
      ) values (v_document, v_line_id, v_job, 'source_job', v_net, round(v_net * v_exchange, 4), 100);
    end if;
    v_total_net := v_total_net + v_net;
    v_total_tax := v_total_tax + v_tax;
    v_total_gross := v_total_gross + v_gross;
  end loop;

  if abs(v_total_gross) <= 0 then
    raise exception 'The finance document gross amount must be greater than zero.' using errcode = '22023';
  end if;
  select case when bool_and(line."FINDocLine_TaxCodeID" is not null) then 'approved' else 'pending' end
  into v_tax_status
  from public."FIN_DocumentLines" line
  where line."FINDocLine_DocumentID" = v_document;

  update public."FIN_Documents"
  set "FINDoc_NetAmount" = v_total_net,
      "FINDoc_TaxAmount" = v_total_tax,
      "FINDoc_GrossAmount" = v_total_gross,
      "FINDoc_LocalNetAmount" = round(v_total_net * v_exchange, 4),
      "FINDoc_LocalTaxAmount" = round(v_total_tax * v_exchange, 4),
      "FINDoc_LocalGrossAmount" = round(v_total_gross * v_exchange, 4),
      "FINDoc_OutstandingAmount" = v_total_gross,
      "FINDoc_LocalOutstandingAmount" = round(v_total_gross * v_exchange, 4),
      "FINDoc_MetadataJSON" = jsonb_set("FINDoc_MetadataJSON", '{taxStatus}', to_jsonb(v_tax_status), true),
      "FINDoc_UpdatedAt" = now()
  where "FINDoc_ID" = v_document;

  insert into public."FIN_DocumentStatusHistory"(
    "FINDocStatus_DocumentID", "FINDocStatus_ToStatusCode", "FINDocStatus_ChangedBy", "FINDocStatus_Reason", "FINDocStatus_MetadataJSON"
  ) values (
    v_document, 'draft', p_user_id, 'Created in Multideck finance',
    jsonb_build_object('sourceKind', v_source_kind, 'jobId', v_job, 'taxStatus', v_tax_status, 'baseCurrencyStatus', v_entity_currency_status)
  );
  insert into public."Audit_Events"(
    "AuditEvent_EventTypeCode", "AuditEvent_UserID", "AuditEvent_LegalEntityID", "AuditEvent_SourceApp", "AuditEvent_SourceModule", "AuditEvent_SourceTableSchema", "AuditEvent_SourceTableName", "AuditEvent_RecordTypeCode", "AuditEvent_RecordID", "AuditEvent_Action", "AuditEvent_Title", "AuditEvent_MetadataJSON"
  ) values (
    'finance_lifecycle', p_user_id, v_entity, 'multideck-app', 'finance', 'public', 'FIN_Documents', v_type, v_document,
    'create_draft', 'Finance document draft created',
    jsonb_build_object('number', v_number, 'sourceKind', v_source_kind, 'grossAmount', v_total_gross, 'currency', v_currency, 'exchangeRate', v_exchange, 'taxStatus', v_tax_status, 'baseCurrencyStatus', v_entity_currency_status)
  );
  return (select to_jsonb(document) from public."FIN_Documents" document where document."FINDoc_ID" = v_document);
end;
$_$;


ALTER FUNCTION "public"."multideck_finance_create_document_draft"("p_company_id" "uuid", "p_user_id" "uuid", "p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_finance_customer_account_snapshot"("p_company_id" "uuid", "p_account_ids" "uuid"[], "p_include_accounting_sync" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  v_account_ids uuid[] := coalesce(p_account_ids, '{}'::uuid[]);
  v_result jsonb;
begin
  if p_company_id is null then
    raise exception 'Choose a tenant company before loading customer accounts.' using errcode = '22023';
  end if;

  if cardinality(v_account_ids) > 100 then
    raise exception 'Customer account finance snapshots are limited to 100 requested accounts.' using errcode = '22023';
  end if;

  with tenant_entities as materialized (
    -- Inactive legal entities remain in scope because historic debt does not
    -- stop being due when the issuer is retired. Only active entities are used
    -- below to discover the current accounting-system connections.
    select
      entity."LegalEntity_ID" as legal_entity_id,
      entity."LegalEntity_IsActive" as is_active,
      case
        when upper(nullif(btrim(entity."LegalEntity_BaseCurrencyCodeSnapshot"), '')) ~ '^[A-Z]{3}$'
          then upper(btrim(entity."LegalEntity_BaseCurrencyCodeSnapshot"))
        else null
      end as base_currency_code
    from public."cmp_LegalEntities" entity
    where entity."Company_ID" = p_company_id
  ), currency_context as (
    select
      count(*)::integer as entity_count,
      count(*) filter (where is_active)::integer as active_entity_count,
      count(*) filter (where base_currency_code is null)::integer as invalid_currency_count,
      count(distinct base_currency_code)::integer as distinct_currency_count,
      min(base_currency_code) as candidate_currency_code
    from tenant_entities
  ), finance_context as materialized (
    select
      (
        entity_count > 0
        and active_entity_count = 1
        and invalid_currency_count = 0
        and distinct_currency_count = 1
      ) as finance_ready,
      case
        when entity_count > 0
          and active_entity_count = 1
          and invalid_currency_count = 0
          and distinct_currency_count = 1
          then candidate_currency_code
        else null
      end as base_currency_code
    from currency_context
  ), customer_accounts as materialized (
    -- Match the current customer register eligibility while retaining the
    -- shared accessible-account boundary for the supplied company.
    select distinct accessible.account_id
    from public.multideck_crm_accessible_account_ids(p_company_id) accessible
    join public."Org_Master" organisation
      on organisation."Org_id" = accessible.account_id
    where coalesce(organisation."Org_CRMIsPotentialCustomer", false)
       or exists (
         select 1
         from public."Org_Master_Type" link
         join public."Org_Types" organisation_type
           on organisation_type."OrgType_ID" = link."OrgType_ID"
         where link."Org_ID" = organisation."Org_id"
           and lower(organisation_type."OrgType_Name") = 'customer'
       )
  ), requested_accounts as materialized (
    select distinct requested.account_id
    from unnest(v_account_ids) requested(account_id)
    join customer_accounts accessible
      on accessible.account_id = requested.account_id
    where requested.account_id is not null
  ), account_preferences as materialized (
    select
      account.account_id,
      case
        when nullif(btrim(profile."CRMAccountOps_InvoicePreferencesJSON" ->> 'creditLimit'), '')
          ~ '^[0-9]+([.][0-9]{1,4})?$'
          then (profile."CRMAccountOps_InvoicePreferencesJSON" ->> 'creditLimit')::numeric
        else null
      end as credit_limit,
      case
        when upper(nullif(btrim(profile."CRMAccountOps_InvoicePreferencesJSON" ->> 'primaryCurrency'), ''))
          ~ '^[A-Z]{3}$'
          then upper(btrim(profile."CRMAccountOps_InvoicePreferencesJSON" ->> 'primaryCurrency'))
        else null
      end as credit_currency_code,
      nullif(btrim(profile."CRMAccountOps_InvoicePreferencesJSON" ->> 'salesPaymentTermCode'), '') as payment_terms_code,
      case
        when nullif(btrim(profile."CRMAccountOps_InvoicePreferencesJSON" ->> 'receivableTermDays'), '')
          ~ '^[0-9]+([.][0-9]{1,4})?$'
          then (profile."CRMAccountOps_InvoicePreferencesJSON" ->> 'receivableTermDays')::numeric
        else null
      end as payment_term_days,
      case
        when nullif(btrim(profile."CRMAccountOps_InvoicePreferencesJSON" ->> 'receivableDueDay'), '')
          ~ '^[0-9]+([.][0-9]{1,4})?$'
          then (profile."CRMAccountOps_InvoicePreferencesJSON" ->> 'receivableDueDay')::numeric
        else null
      end as payment_term_due_day,
      lower(coalesce(profile."CRMAccountOps_InvoicePreferencesJSON" ->> 'receivableEndOfMonth', 'false')) = 'true'
        as payment_term_end_of_month,
      lower(coalesce(profile."CRMAccountOps_InvoicePreferencesJSON" ->> 'creditHold', 'false')) = 'true'
        as credit_hold,
      case
        when nullif(btrim(profile."CRMAccountOps_InvoicePreferencesJSON" ->> 'customerAccountingStatusCode'), '') = 'blocked'
          then 'blocked'
        when nullif(btrim(profile."CRMAccountOps_InvoicePreferencesJSON" ->> 'customerAccountingStatusCode'), '') = 'on_hold'
          or lower(coalesce(profile."CRMAccountOps_InvoicePreferencesJSON" ->> 'creditHold', 'false')) = 'true'
          then 'on_hold'
        else 'active'
      end as account_status
    from customer_accounts account
    left join public."CRM_AccountOperationalProfiles" profile
      on profile."CRMAccountOps_OrgID" = account.account_id
     and profile."CRMAccountOps_CompanyID" = p_company_id
  ), document_balances as materialized (
    select
      document."FINDoc_PartyOrgID" as account_id,
      sum(document."FINDoc_LocalOutstandingAmount") as balance_due,
      coalesce(sum(document."FINDoc_LocalOutstandingAmount") filter (
        where document."FINDoc_TypeCode" = 'sl_invoice'
          and document."FINDoc_OutstandingAmount" > 0
          and document."FINDoc_DueDate" < current_date
      ), 0) as overdue_amount,
      count(*) filter (
        where document."FINDoc_TypeCode" = 'sl_invoice'
          and document."FINDoc_OutstandingAmount" > 0
      )::integer as open_invoice_count,
      count(*) filter (
        where document."FINDoc_TypeCode" = 'sl_invoice'
          and document."FINDoc_OutstandingAmount" > 0
          and document."FINDoc_DueDate" < current_date
      )::integer as overdue_invoice_count,
      min(document."FINDoc_DueDate") filter (
        where document."FINDoc_TypeCode" = 'sl_invoice'
          and document."FINDoc_OutstandingAmount" > 0
          and document."FINDoc_DueDate" < current_date
      ) as oldest_overdue_date
    from public."FIN_Documents" document
    join tenant_entities entity
      on entity.legal_entity_id = document."FINDoc_LegalEntityID"
    join customer_accounts account
      on account.account_id = document."FINDoc_PartyOrgID"
    where document."FINDoc_TypeCode" in ('sl_invoice', 'credit_note')
      and document."FINDoc_PartyRole" = 'customer'
      and document."FINDoc_StatusCode" in ('approved', 'submitted')
    group by document."FINDoc_PartyOrgID"
  ), active_connections as materialized (
    select connection."ACCIC_ID" as connection_id
    from public."ACCI_Connections" connection
    join tenant_entities entity
      on entity.legal_entity_id = connection."ACCIC_LegalEntityID"
     and entity.is_active
    where p_include_accounting_sync
      and connection."ACCIC_StatusCode" = 'active'
  ), connection_count as materialized (
    select count(*)::integer as value from active_connections
  ), active_party_mappings as materialized (
    select
      mapping."ACCIPM_ConnectionID" as connection_id,
      mapping."ACCIPM_OrgID" as account_id,
      max(coalesce(mapping."ACCIPM_LastSyncedAt", mapping."ACCIPM_CreatedAt")) as mapping_effective_at,
      max(mapping."ACCIPM_LastSyncedAt") as last_synced_at
    from public."ACCI_PartyMappings" mapping
    join active_connections connection
      on connection.connection_id = mapping."ACCIPM_ConnectionID"
    join customer_accounts account
      on account.account_id = mapping."ACCIPM_OrgID"
    where p_include_accounting_sync
      and mapping."ACCIPM_PartyType" in ('customer', 'both')
      and mapping."ACCIPM_IsActive"
    group by mapping."ACCIPM_ConnectionID", mapping."ACCIPM_OrgID"
  ), latest_party_events as materialized (
    select distinct on (event."ACCISE_ConnectionID", event."ACCISE_LocalID")
      event."ACCISE_ConnectionID" as connection_id,
      event."ACCISE_LocalID" as account_id,
      event."ACCISE_EventCode" as event_code,
      event."ACCISE_Severity" as severity,
      event."ACCISE_CreatedAt" as created_at
    from public."ACCI_SyncEvents" event
    join active_connections connection
      on connection.connection_id = event."ACCISE_ConnectionID"
    join customer_accounts account
      on account.account_id = event."ACCISE_LocalID"
    where p_include_accounting_sync
      and event."ACCISE_LocalTable" = 'Org_Master'
      and event."ACCISE_EventCode" in ('party_account_synced', 'party_account_sync_failed')
    order by event."ACCISE_ConnectionID", event."ACCISE_LocalID", event."ACCISE_CreatedAt" desc, event."ACCISE_ID" desc
  ), connection_account_state as materialized (
    select
      account.account_id,
      connection.connection_id,
      mapping.connection_id is not null as is_mapped,
      mapping.last_synced_at,
      (event.event_code = 'party_account_sync_failed' or event.severity in ('error', 'critical'))
        and event.created_at >= coalesce(mapping.mapping_effective_at, '-infinity'::timestamptz)
        as has_later_failure
    from customer_accounts account
    cross join active_connections connection
    left join active_party_mappings mapping
      on mapping.connection_id = connection.connection_id
     and mapping.account_id = account.account_id
    left join latest_party_events event
      on event.connection_id = connection.connection_id
     and event.account_id = account.account_id
  ), account_connection_totals as materialized (
    select
      state.account_id,
      count(*) filter (where state.is_mapped)::integer as mapped_connection_count,
      coalesce(bool_or(state.has_later_failure), false) as has_later_failure,
      max(state.last_synced_at) as last_synced_at
    from connection_account_state state
    group by state.account_id
  ), account_sync_state as materialized (
    select
      account.account_id,
      case
        when connections.value = 0 then 'not_connected'
        when coalesce(totals.has_later_failure, false) then 'failed'
        when coalesce(totals.mapped_connection_count, 0) = connections.value then 'synced'
        when coalesce(totals.mapped_connection_count, 0) > 0 then 'partial'
        else 'not_synced'
      end as sync_status,
      totals.last_synced_at
    from customer_accounts account
    cross join connection_count connections
    left join account_connection_totals totals
      on totals.account_id = account.account_id
  ), row_payloads as materialized (
    select
      requested.account_id,
      jsonb_build_object(
        'organisationId', requested.account_id,
        'financeReady', context.finance_ready,
        'baseCurrencyCode', context.base_currency_code,
        'balanceDue', case when context.finance_ready then coalesce(balance.balance_due, 0) else null end,
        'overdueAmount', case when context.finance_ready then coalesce(balance.overdue_amount, 0) else null end,
        'openInvoiceCount', coalesce(balance.open_invoice_count, 0),
        'overdueInvoiceCount', coalesce(balance.overdue_invoice_count, 0),
        'oldestOverdueDate', balance.oldest_overdue_date,
        'creditLimit', preferences.credit_limit,
        'creditCurrencyCode', preferences.credit_currency_code,
        'availableCredit', case
          when context.finance_ready
            and preferences.credit_limit is not null
            and preferences.credit_currency_code = context.base_currency_code
            then preferences.credit_limit - greatest(coalesce(balance.balance_due, 0), 0)
          else null
        end,
        'paymentTermsCode', preferences.payment_terms_code,
        'paymentTermDays', preferences.payment_term_days,
        'paymentTermDueDay', preferences.payment_term_due_day,
        'paymentTermEndOfMonth', preferences.payment_term_end_of_month,
        'accountStatus', preferences.account_status,
        'creditHold', preferences.credit_hold
      ) || case
        when p_include_accounting_sync then jsonb_build_object(
          'accountingSyncStatus', sync.sync_status,
          'accountingLastSyncedAt', sync.last_synced_at
        )
        else '{}'::jsonb
      end as value
    from requested_accounts requested
    cross join finance_context context
    join account_preferences preferences
      on preferences.account_id = requested.account_id
    left join document_balances balance
      on balance.account_id = requested.account_id
    left join account_sync_state sync
      on sync.account_id = requested.account_id
  ), summary_payload as materialized (
    select jsonb_build_object(
      'balanceDue', case when context.finance_ready then coalesce(sum(balance.balance_due), 0) else null end,
      'overdueAmount', case when context.finance_ready then coalesce(sum(balance.overdue_amount), 0) else null end,
      'openInvoiceCount', coalesce(sum(balance.open_invoice_count), 0)::integer,
      'overdueInvoiceCount', coalesce(sum(balance.overdue_invoice_count), 0)::integer,
      'overdueCustomerCount', count(*) filter (where coalesce(balance.overdue_invoice_count, 0) > 0)::integer,
      'creditAttentionCount', count(*) filter (
        where context.finance_ready
          and preferences.credit_limit is not null
          and preferences.credit_currency_code = context.base_currency_code
          and greatest(coalesce(balance.balance_due, 0), 0) > preferences.credit_limit
      )::integer,
      'onHoldCount', count(*) filter (where preferences.account_status in ('on_hold', 'blocked'))::integer,
      'accountingAttentionCount', case
        when p_include_accounting_sync
          then count(*) filter (where sync.sync_status <> 'synced')::integer
        else null
      end
    ) as value
    from customer_accounts account
    cross join finance_context context
    join account_preferences preferences
      on preferences.account_id = account.account_id
    left join document_balances balance
      on balance.account_id = account.account_id
    left join account_sync_state sync
      on sync.account_id = account.account_id
    group by context.finance_ready, context.base_currency_code
  )
  select jsonb_build_object(
    'financeReady', context.finance_ready,
    'baseCurrencyCode', context.base_currency_code,
    'rows', coalesce((select jsonb_agg(row_payloads.value order by row_payloads.account_id) from row_payloads), '[]'::jsonb),
    'summary', coalesce((select summary_payload.value from summary_payload), jsonb_build_object(
      'balanceDue', case when context.finance_ready then 0 else null end,
      'overdueAmount', case when context.finance_ready then 0 else null end,
      'openInvoiceCount', 0,
      'overdueInvoiceCount', 0,
      'overdueCustomerCount', 0,
      'creditAttentionCount', 0,
      'onHoldCount', 0,
      'accountingAttentionCount', case when p_include_accounting_sync then 0 else null end
    ))
  ) into v_result
  from finance_context context;

  return v_result;
end;
$_$;


ALTER FUNCTION "public"."multideck_finance_customer_account_snapshot"("p_company_id" "uuid", "p_account_ids" "uuid"[], "p_include_accounting_sync" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."multideck_finance_customer_account_snapshot"("p_company_id" "uuid", "p_account_ids" "uuid"[], "p_include_accounting_sync" boolean) IS 'Service-role-only, read-only customer account projection. It emits no state or watch event; existing FIN_Documents, customer invoice-preference and provider party-sync event adapters remain the lifecycle signals.';



CREATE OR REPLACE FUNCTION "public"."multideck_finance_latest_exchange_rates"("p_currency_codes" "text"[]) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
  with requested as (
    select distinct upper(btrim(code)) as code
    from unnest(coalesce(p_currency_codes, '{}'::text[])) code
    where upper(btrim(code)) ~ '^[A-Z]{3}$'
    limit 64
  ), latest as (
    select distinct on (rate."FINRate_FromCurrencyCode", rate."FINRate_ToCurrencyCode")
      rate."FINRate_ID",
      rate."FINRate_FromCurrencyCode",
      rate."FINRate_ToCurrencyCode",
      rate."FINRate_RateDate",
      rate."FINRate_MidRate",
      rate."FINRate_ImportID",
      rate."FINRate_SourceReference",
      rate."FINRate_IsOfficial",
      rate."FINRate_ImportedAt",
      provider."FINRateProvider_Name"
    from public."FIN_ExchangeRates" rate
    join public."FIN_ExchangeRateProviders" provider
      on provider."FINRateProvider_ID" = rate."FINRate_ProviderID"
     and provider."FINRateProvider_IsActive"
    where rate."FINRate_IsApproved"
      and rate."FINRate_MidRate" > 0
      and rate."FINRate_FromCurrencyCode" in (select code from requested)
      and rate."FINRate_ToCurrencyCode" in (select code from requested)
    order by
      rate."FINRate_FromCurrencyCode",
      rate."FINRate_ToCurrencyCode",
      rate."FINRate_RateDate" desc,
      rate."FINRate_IsOfficial" desc,
      rate."FINRate_ImportedAt" desc,
      rate."FINRate_ID" desc
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'FINRate_ID', latest."FINRate_ID",
    'FINRate_FromCurrencyCode', latest."FINRate_FromCurrencyCode",
    'FINRate_ToCurrencyCode', latest."FINRate_ToCurrencyCode",
    'FINRate_RateDate', latest."FINRate_RateDate",
    'FINRate_MidRate', latest."FINRate_MidRate",
    'FINRate_ImportID', latest."FINRate_ImportID",
    'FINRate_SourceReference', latest."FINRate_SourceReference",
    'FINRate_IsOfficial', latest."FINRate_IsOfficial",
    'FINRate_ImportedAt', latest."FINRate_ImportedAt",
    'providerName', latest."FINRateProvider_Name"
  ) order by latest."FINRate_FromCurrencyCode", latest."FINRate_ToCurrencyCode"), '[]'::jsonb)
  from latest
$_$;


ALTER FUNCTION "public"."multideck_finance_latest_exchange_rates"("p_currency_codes" "text"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."multideck_finance_latest_exchange_rates"("p_currency_codes" "text"[]) IS 'Returns at most one current approved rate per requested currency pair for the Finance Edge Function.';



CREATE OR REPLACE FUNCTION "public"."multideck_finance_link_document_charge_lines"("p_company_id" "uuid", "p_user_id" "uuid", "p_document_id" "uuid", "p_lines" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_document public."FIN_Documents"%rowtype; v_entry jsonb; v_line_id uuid; v_costing_line uuid; v_nominal uuid; v_count integer:=0;
begin
  select document.* into v_document
  from public."FIN_Documents" document
  join public."cmp_LegalEntities" entity on entity."LegalEntity_ID"=document."FINDoc_LegalEntityID"
  where document."FINDoc_ID"=p_document_id and entity."Company_ID"=p_company_id for update;
  if not found then raise exception 'Finance document not found.' using errcode='P0002'; end if;
  if v_document."FINDoc_StatusCode"<>'draft' or v_document."FINDoc_SourceJobID" is null then
    if v_document."FINDoc_SourceJobID" is null then return jsonb_build_object('documentId',p_document_id,'linkedCount',0); end if;
    raise exception 'Only a job-linked draft can change charge allocations.' using errcode='22023';
  end if;
  if not exists(select 1 from public."cmp_Users" where "User_ID"=p_user_id and "Company_ID"=p_company_id and coalesce("User_AccessStatus",'active')='active') then raise exception 'The finance operator is outside this workspace.' using errcode='42501'; end if;
  if jsonb_typeof(p_lines)<>'array' then raise exception 'Charge allocations must be an array.' using errcode='22023'; end if;
  for v_entry in select value from jsonb_array_elements(p_lines) loop
    select line."FINDocLine_ID" into v_line_id from public."FIN_DocumentLines" line
    where line."FINDocLine_DocumentID"=p_document_id and line."FINDocLine_LineNo"=(v_entry->>'lineNo')::integer;
    if v_line_id is null then raise exception 'Finance line % was not found.',v_entry->>'lineNo' using errcode='P0002'; end if;
    v_costing_line:=nullif(v_entry->>'jobCostingLineId','')::uuid;
    if v_costing_line is not null then
      select case when v_document."FINDoc_TypeCode" in ('sl_invoice','credit_note') then line."JobCostingLine_RevenueNominalAccountID" else line."JobCostingLine_CostNominalAccountID" end
      into v_nominal from public."Job_Costing_Lines" line
      where line."JobCostingLine_ID"=v_costing_line and line."Job_ID"=v_document."FINDoc_SourceJobID";
      if not found then raise exception 'A selected charge line does not belong to this job.' using errcode='42501'; end if;
      v_nominal:=public._multideck_finance_resolve_nominal(
        v_document."FINDoc_LegalEntityID",v_nominal,
        case when v_document."FINDoc_TypeCode" in ('sl_invoice','credit_note') then '4000' else '5000' end
      );
      if v_nominal is null then raise exception 'Assign a nominal code to the selected job charge before review.' using errcode='22023'; end if;
      if v_document."FINDoc_TypeCode" in ('sl_invoice','credit_note') then
        update public."Job_Costing_Lines" set "JobCostingLine_RevenueNominalAccountID"=v_nominal where "JobCostingLine_ID"=v_costing_line;
      else
        update public."Job_Costing_Lines" set "JobCostingLine_CostNominalAccountID"=v_nominal where "JobCostingLine_ID"=v_costing_line;
      end if;
    else v_nominal:=null;
    end if;
    update public."FIN_DocumentLineJobLinks" set "FINDocLineJob_JobCostingLineID"=v_costing_line,"FINDocLineJob_LinkTypeCode"=case when v_costing_line is null then 'source_job' else 'source_charge_line' end
    where "FINDocLineJob_DocumentID"=p_document_id and "FINDocLineJob_DocumentLineID"=v_line_id and "FINDocLineJob_JobID"=v_document."FINDoc_SourceJobID";
    update public."FIN_DocumentLines" set "FINDocLine_NominalAccountID"=v_nominal where "FINDocLine_ID"=v_line_id;
    if v_costing_line is not null then v_count:=v_count+1; end if;
  end loop;
  insert into public."Audit_Events"("AuditEvent_EventTypeCode","AuditEvent_UserID","AuditEvent_LegalEntityID","AuditEvent_SourceApp","AuditEvent_SourceModule","AuditEvent_SourceTableSchema","AuditEvent_SourceTableName","AuditEvent_RecordTypeCode","AuditEvent_RecordID","AuditEvent_Action","AuditEvent_Title","AuditEvent_HasFieldChanges","AuditEvent_ChangedFieldCount","AuditEvent_MetadataJSON")
  values('finance_lifecycle',p_user_id,v_document."FINDoc_LegalEntityID",'multideck-app','finance','public','FIN_Documents',v_document."FINDoc_TypeCode",p_document_id,'link_job_charge_lines','Document lines linked to job charges',true,v_count,jsonb_build_object('linkedCount',v_count));
  return jsonb_build_object('documentId',p_document_id,'linkedCount',v_count);
end; $$;


ALTER FUNCTION "public"."multideck_finance_link_document_charge_lines"("p_company_id" "uuid", "p_user_id" "uuid", "p_document_id" "uuid", "p_lines" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_finance_post_accrual_wip"("p_company_id" "uuid", "p_user_id" "uuid", "p_run_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_run public."FIN_PeriodCloseRuns"%rowtype; v_period public."FIN_Periods"%rowtype; v_item public."FIN_PeriodCloseRunItems"%rowtype;
  v_charge public."FIN_JobChargePeriodAllocations"%rowtype; v_batch uuid; v_accrual uuid; v_wip uuid; v_line integer:=0; v_total numeric:=0;
  v_currency text; v_cost uuid; v_income uuid; v_accrual_control uuid; v_wip_control uuid; v_has_charge_rows boolean;
begin
  select run.* into v_run from public."FIN_PeriodCloseRuns" run join public."cmp_LegalEntities" entity on entity."LegalEntity_ID"=run."FINCloseRun_LegalEntityID" where run."FINCloseRun_ID"=p_run_id and entity."Company_ID"=p_company_id for update;
  if not found then raise exception 'Accrual and WIP review not found.' using errcode='P0002'; end if;
  if v_run."FINCloseRun_StatusCode"<>'approved' then raise exception 'Approve this review before posting it.' using errcode='22023'; end if;
  if not exists(select 1 from public."cmp_Users" where "User_ID"=p_user_id and "Company_ID"=p_company_id and coalesce("User_AccessStatus",'active')='active') then raise exception 'The finance operator is outside this workspace.' using errcode='42501'; end if;
  select * into v_period from public."FIN_Periods" where "FINPeriod_ID"=v_run."FINCloseRun_PeriodID" for update;
  if v_period."FINPeriod_StatusCode" not in ('open','soft_closed') then raise exception 'This management period is locked.' using errcode='22023'; end if;
  v_currency:=v_period."FINPeriod_BaseCurrencyCode";
  select "FINNom_ID" into v_cost from public."FIN_NominalAccounts" where "FINNom_LegalEntityID"=v_run."FINCloseRun_LegalEntityID" and "FINNom_Code"='5000' and "FINNom_IsActive" limit 1;
  select "FINNom_ID" into v_income from public."FIN_NominalAccounts" where "FINNom_LegalEntityID"=v_run."FINCloseRun_LegalEntityID" and "FINNom_Code"='4000' and "FINNom_IsActive" limit 1;
  select "FINNom_ID" into v_accrual_control from public."FIN_NominalAccounts" where "FINNom_LegalEntityID"=v_run."FINCloseRun_LegalEntityID" and "FINNom_Code"='2300' and "FINNom_IsActive" limit 1;
  select "FINNom_ID" into v_wip_control from public."FIN_NominalAccounts" where "FINNom_LegalEntityID"=v_run."FINCloseRun_LegalEntityID" and "FINNom_Code"='1400' and "FINNom_IsActive" limit 1;
  if v_cost is null or v_income is null or v_accrual_control is null or v_wip_control is null then raise exception 'Configure active 5000 cost, 4000 income, 2300 accrual and 1400 WIP accounts before posting.' using errcode='22023'; end if;
  insert into public."FIN_PostingBatches"("FINPostBatch_Number","FINPostBatch_StatusCode","FINPostBatch_SourceTable","FINPostBatch_SourceID","FINPostBatch_PeriodID","FINPostBatch_LegalEntityID","FINPostBatch_DebitTotal","FINPostBatch_CreditTotal","FINPostBatch_CurrencyCodeSnapshot","FINPostBatch_PostedAt","FINPostBatch_PostedBy","FINPostBatch_CreatedBy") values('MA-'||v_period."FINPeriod_Code"||'-'||left(p_run_id::text,8),'posted','FIN_PeriodCloseRuns',p_run_id,v_period."FINPeriod_ID",v_run."FINCloseRun_LegalEntityID",0,0,v_currency,now(),p_user_id,p_user_id) returning "FINPostBatch_ID" into v_batch;
  select exists(select 1 from public."FIN_JobChargePeriodAllocations" allocation join public."FIN_PeriodCloseRunItems" item on item."FINCloseItem_ID"=allocation."FINChargePeriod_CloseRunItemID" where item."FINCloseItem_CloseRunID"=p_run_id) into v_has_charge_rows;
  if v_has_charge_rows then
    for v_charge in
      select allocation.* from public."FIN_JobChargePeriodAllocations" allocation join public."FIN_PeriodCloseRunItems" item on item."FINCloseItem_ID"=allocation."FINChargePeriod_CloseRunItemID"
      where item."FINCloseItem_CloseRunID"=p_run_id and (allocation."FINChargePeriod_ApprovedAccrual">0 or allocation."FINChargePeriod_ApprovedWIP">0)
      order by allocation."FINChargePeriod_JobID",allocation."FINChargePeriod_LineNoSnapshot"
    loop
      if v_charge."FINChargePeriod_ApprovedAccrual">0 then
        insert into public."FIN_Accruals"("FINAccrual_JobID","FINAccrual_JobCostingLineID","FINAccrual_PeriodID","FINAccrual_StatusCode","FINAccrual_AccountingDate","FINAccrual_ExpectedAmount","FINAccrual_AccruedAmount","FINAccrual_LocalAccruedAmount","FINAccrual_CurrencyCodeSnapshot","FINAccrual_CreatedBy","FINAccrual_CloseRunItemID","FINAccrual_Description","FINAccrual_ApprovedAt","FINAccrual_ApprovedBy","FINAccrual_PostedAt","FINAccrual_PostedBy") values(v_charge."FINChargePeriod_JobID",v_charge."FINChargePeriod_JobCostingLineID",v_period."FINPeriod_ID",'posted',v_period."FINPeriod_EndDate",v_charge."FINChargePeriod_ExpectedCost",v_charge."FINChargePeriod_ApprovedAccrual",v_charge."FINChargePeriod_ApprovedAccrual",v_currency,p_user_id,v_charge."FINChargePeriod_CloseRunItemID",'Cost accrual · '||v_charge."FINChargePeriod_DescriptionSnapshot",v_run."FINCloseRun_ApprovedAt",v_run."FINCloseRun_ApprovedBy",now(),p_user_id) returning "FINAccrual_ID" into v_accrual;
        v_line:=v_line+1; insert into public."FIN_PostingLines"("FINPostLine_BatchID","FINPostLine_LineNo","FINPostLine_NominalAccountID","FINPostLine_AccrualID","FINPostLine_Description","FINPostLine_DebitAmount","FINPostLine_CreditAmount","FINPostLine_CurrencyCodeSnapshot","FINPostLine_Dimension1ID","FINPostLine_JobID") values(v_batch,v_line,coalesce(v_charge."FINChargePeriod_CostNominalAccountID",v_cost),v_accrual,'Accrued job cost · '||v_charge."FINChargePeriod_DescriptionSnapshot",v_charge."FINChargePeriod_ApprovedAccrual",0,v_currency,v_charge."FINChargePeriod_JobID",v_charge."FINChargePeriod_JobID");
        v_line:=v_line+1; insert into public."FIN_PostingLines"("FINPostLine_BatchID","FINPostLine_LineNo","FINPostLine_NominalAccountID","FINPostLine_AccrualID","FINPostLine_Description","FINPostLine_DebitAmount","FINPostLine_CreditAmount","FINPostLine_CurrencyCodeSnapshot","FINPostLine_Dimension1ID","FINPostLine_JobID") values(v_batch,v_line,v_accrual_control,v_accrual,'Accrued cost liability · '||v_charge."FINChargePeriod_DescriptionSnapshot",0,v_charge."FINChargePeriod_ApprovedAccrual",v_currency,v_charge."FINChargePeriod_JobID",v_charge."FINChargePeriod_JobID");
        v_total:=v_total+v_charge."FINChargePeriod_ApprovedAccrual";
      end if;
      if v_charge."FINChargePeriod_ApprovedWIP">0 then
        insert into public."FIN_WIPItems"("FINWIP_JobID","FINWIP_JobCostingLineID","FINWIP_PeriodID","FINWIP_StatusCode","FINWIP_AccountingDate","FINWIP_ExpectedAmount","FINWIP_WIPAmount","FINWIP_LocalWIPAmount","FINWIP_CurrencyCodeSnapshot","FINWIP_CreatedBy","FINWIP_CloseRunItemID","FINWIP_Description","FINWIP_ApprovedAt","FINWIP_ApprovedBy","FINWIP_PostedAt","FINWIP_PostedBy") values(v_charge."FINChargePeriod_JobID",v_charge."FINChargePeriod_JobCostingLineID",v_period."FINPeriod_ID",'posted',v_period."FINPeriod_EndDate",v_charge."FINChargePeriod_ExpectedRevenue",v_charge."FINChargePeriod_ApprovedWIP",v_charge."FINChargePeriod_ApprovedWIP",v_currency,p_user_id,v_charge."FINChargePeriod_CloseRunItemID",'Revenue WIP · '||v_charge."FINChargePeriod_DescriptionSnapshot",v_run."FINCloseRun_ApprovedAt",v_run."FINCloseRun_ApprovedBy",now(),p_user_id) returning "FINWIP_ID" into v_wip;
        v_line:=v_line+1; insert into public."FIN_PostingLines"("FINPostLine_BatchID","FINPostLine_LineNo","FINPostLine_NominalAccountID","FINPostLine_WIPID","FINPostLine_Description","FINPostLine_DebitAmount","FINPostLine_CreditAmount","FINPostLine_CurrencyCodeSnapshot","FINPostLine_Dimension1ID","FINPostLine_JobID") values(v_batch,v_line,v_wip_control,v_wip,'Accrued income and WIP · '||v_charge."FINChargePeriod_DescriptionSnapshot",v_charge."FINChargePeriod_ApprovedWIP",0,v_currency,v_charge."FINChargePeriod_JobID",v_charge."FINChargePeriod_JobID");
        v_line:=v_line+1; insert into public."FIN_PostingLines"("FINPostLine_BatchID","FINPostLine_LineNo","FINPostLine_NominalAccountID","FINPostLine_WIPID","FINPostLine_Description","FINPostLine_DebitAmount","FINPostLine_CreditAmount","FINPostLine_CurrencyCodeSnapshot","FINPostLine_Dimension1ID","FINPostLine_JobID") values(v_batch,v_line,coalesce(v_charge."FINChargePeriod_RevenueNominalAccountID",v_income),v_wip,'Recognised unbilled revenue · '||v_charge."FINChargePeriod_DescriptionSnapshot",0,v_charge."FINChargePeriod_ApprovedWIP",v_currency,v_charge."FINChargePeriod_JobID",v_charge."FINChargePeriod_JobID");
        v_total:=v_total+v_charge."FINChargePeriod_ApprovedWIP";
      end if;
    end loop;
  else
    -- Compatibility for reviews created before charge-level allocation existed.
    for v_item in select * from public."FIN_PeriodCloseRunItems" where "FINCloseItem_CloseRunID"=p_run_id and ("FINCloseItem_ApprovedAccrual">0 or "FINCloseItem_ApprovedWIP">0) order by "FINCloseItem_JobID" loop
      if v_item."FINCloseItem_ApprovedAccrual">0 then
        insert into public."FIN_Accruals"("FINAccrual_JobID","FINAccrual_PeriodID","FINAccrual_StatusCode","FINAccrual_AccountingDate","FINAccrual_ExpectedAmount","FINAccrual_AccruedAmount","FINAccrual_LocalAccruedAmount","FINAccrual_CurrencyCodeSnapshot","FINAccrual_CreatedBy","FINAccrual_CloseRunItemID") values(v_item."FINCloseItem_JobID",v_period."FINPeriod_ID",'posted',v_period."FINPeriod_EndDate",v_item."FINCloseItem_ExpectedCost",v_item."FINCloseItem_ApprovedAccrual",v_item."FINCloseItem_ApprovedAccrual",v_currency,p_user_id,v_item."FINCloseItem_ID") returning "FINAccrual_ID" into v_accrual;
        v_line:=v_line+1; insert into public."FIN_PostingLines"("FINPostLine_BatchID","FINPostLine_LineNo","FINPostLine_NominalAccountID","FINPostLine_AccrualID","FINPostLine_Description","FINPostLine_DebitAmount","FINPostLine_CreditAmount","FINPostLine_CurrencyCodeSnapshot","FINPostLine_JobID") values(v_batch,v_line,v_cost,v_accrual,'Legacy accrued job cost',v_item."FINCloseItem_ApprovedAccrual",0,v_currency,v_item."FINCloseItem_JobID");
        v_line:=v_line+1; insert into public."FIN_PostingLines"("FINPostLine_BatchID","FINPostLine_LineNo","FINPostLine_NominalAccountID","FINPostLine_AccrualID","FINPostLine_Description","FINPostLine_DebitAmount","FINPostLine_CreditAmount","FINPostLine_CurrencyCodeSnapshot","FINPostLine_JobID") values(v_batch,v_line,v_accrual_control,v_accrual,'Legacy accrued cost liability',0,v_item."FINCloseItem_ApprovedAccrual",v_currency,v_item."FINCloseItem_JobID"); v_total:=v_total+v_item."FINCloseItem_ApprovedAccrual";
      end if;
      if v_item."FINCloseItem_ApprovedWIP">0 then
        insert into public."FIN_WIPItems"("FINWIP_JobID","FINWIP_PeriodID","FINWIP_StatusCode","FINWIP_AccountingDate","FINWIP_ExpectedAmount","FINWIP_WIPAmount","FINWIP_LocalWIPAmount","FINWIP_CurrencyCodeSnapshot","FINWIP_CreatedBy","FINWIP_CloseRunItemID") values(v_item."FINCloseItem_JobID",v_period."FINPeriod_ID",'posted',v_period."FINPeriod_EndDate",v_item."FINCloseItem_ExpectedRevenue",v_item."FINCloseItem_ApprovedWIP",v_item."FINCloseItem_ApprovedWIP",v_currency,p_user_id,v_item."FINCloseItem_ID") returning "FINWIP_ID" into v_wip;
        v_line:=v_line+1; insert into public."FIN_PostingLines"("FINPostLine_BatchID","FINPostLine_LineNo","FINPostLine_NominalAccountID","FINPostLine_WIPID","FINPostLine_Description","FINPostLine_DebitAmount","FINPostLine_CreditAmount","FINPostLine_CurrencyCodeSnapshot","FINPostLine_JobID") values(v_batch,v_line,v_wip_control,v_wip,'Legacy accrued income and WIP',v_item."FINCloseItem_ApprovedWIP",0,v_currency,v_item."FINCloseItem_JobID");
        v_line:=v_line+1; insert into public."FIN_PostingLines"("FINPostLine_BatchID","FINPostLine_LineNo","FINPostLine_NominalAccountID","FINPostLine_WIPID","FINPostLine_Description","FINPostLine_DebitAmount","FINPostLine_CreditAmount","FINPostLine_CurrencyCodeSnapshot","FINPostLine_JobID") values(v_batch,v_line,v_income,v_wip,'Legacy recognised unbilled revenue',0,v_item."FINCloseItem_ApprovedWIP",v_currency,v_item."FINCloseItem_JobID"); v_total:=v_total+v_item."FINCloseItem_ApprovedWIP";
      end if;
    end loop;
  end if;
  if v_total<=0 then raise exception 'This review has no approved accrual or WIP amounts to post.' using errcode='22023'; end if;
  update public."FIN_PostingBatches" set "FINPostBatch_DebitTotal"=v_total,"FINPostBatch_CreditTotal"=v_total where "FINPostBatch_ID"=v_batch;
  update public."FIN_PeriodCloseRunItems" set "FINCloseItem_StatusCode"='posted',"FINCloseItem_UpdatedAt"=now(),"FINCloseItem_UpdatedBy"=p_user_id where "FINCloseItem_CloseRunID"=p_run_id;
  update public."FIN_PeriodCloseRuns" set "FINCloseRun_StatusCode"='posted',"FINCloseRun_PostedAt"=now(),"FINCloseRun_PostedBy"=p_user_id,"FINCloseRun_PostingBatchID"=v_batch,"FINCloseRun_UpdatedAt"=now(),"FINCloseRun_UpdatedBy"=p_user_id,"FINCloseRun_ControlTotalsJSON"="FINCloseRun_ControlTotalsJSON"||jsonb_build_object('postedTotal',v_total,'postingBatchId',v_batch,'basis','job_charge_lines') where "FINCloseRun_ID"=p_run_id;
  insert into public."Audit_Events"("AuditEvent_EventTypeCode","AuditEvent_UserID","AuditEvent_LegalEntityID","AuditEvent_SourceApp","AuditEvent_SourceModule","AuditEvent_SourceTableSchema","AuditEvent_SourceTableName","AuditEvent_RecordTypeCode","AuditEvent_RecordID","AuditEvent_Action","AuditEvent_Title","AuditEvent_HasFieldChanges","AuditEvent_ChangedFieldCount","AuditEvent_MetadataJSON") values('finance_lifecycle',p_user_id,v_run."FINCloseRun_LegalEntityID",'multideck-app','finance','public','FIN_PeriodCloseRuns','accrual_wip_review',p_run_id,'post_accrual_wip','Charge-level accrual and WIP journal posted',true,1,jsonb_build_object('postingBatchId',v_batch,'total',v_total,'currency',v_currency,'basis','job_charge_lines'));
  return jsonb_build_object('runId',p_run_id,'status','posted','postingBatchId',v_batch,'total',v_total,'currency',v_currency,'basis','job_charge_lines');
end; $$;


ALTER FUNCTION "public"."multideck_finance_post_accrual_wip"("p_company_id" "uuid", "p_user_id" "uuid", "p_run_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_finance_reopen_document_draft"("p_company_id" "uuid", "p_user_id" "uuid", "p_document_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_document public."FIN_Documents";
  v_reason text;
  v_cancelled integer := 0;
begin
  if not exists (
    select 1 from public."cmp_Users"
    where "User_ID" = p_user_id
      and "Company_ID" = p_company_id
      and coalesce("User_AccessStatus", 'active') = 'active'
  ) then
    raise exception 'The finance operator is outside this workspace.' using errcode = '42501';
  end if;
  select document.*
  into v_document
  from public."FIN_Documents" document
  join public."cmp_LegalEntities" entity on entity."LegalEntity_ID" = document."FINDoc_LegalEntityID"
  where document."FINDoc_ID" = p_document_id
    and entity."Company_ID" = p_company_id
  for update of document;
  if not found then
    raise exception 'Finance document not found in this workspace.' using errcode = 'P0002';
  end if;
  if v_document."FINDoc_PostedAt" is not null
    or v_document."FINDoc_PostingStatusCode" = 'posted'
    or v_document."FINDoc_StatusCode" = 'submitted' then
    raise exception 'A posted document is immutable and cannot be returned to draft.' using errcode = '22023';
  end if;
  if not (
    v_document."FINDoc_StatusCode" = 'rejected'
    or (
      v_document."FINDoc_StatusCode" = 'approved'
      and v_document."FINDoc_PostingStatusCode" in ('blocked', 'failed')
    )
  ) then
    raise exception 'Only a rejected or provider-blocked approved document can be returned to draft.' using errcode = '22023';
  end if;

  v_reason := coalesce(nullif(btrim(p_reason), ''), 'Returned to draft for correction');
  update public."FIN_IntegrationQueue"
  set "FINIntQ_StatusCode" = 'cancelled',
      "FINIntQ_LastError" = 'Approval revoked: ' || left(v_reason, 460)
  where "FINIntQ_LocalTable" = 'FIN_Documents'
    and "FINIntQ_LocalID" = p_document_id
    and "FINIntQ_StatusCode" in ('queued', 'processing', 'blocked', 'failed');
  get diagnostics v_cancelled = row_count;

  update public."ACCI_ReconciliationIssues"
  set "ACCIRI_StatusCode" = 'synced',
      "ACCIRI_ResolutionText" = 'Document returned to draft: ' || left(v_reason, 460),
      "ACCIRI_ResolvedAt" = now(),
      "ACCIRI_ResolvedBy" = p_user_id
  where "ACCIRI_LocalTable" = 'FIN_Documents'
    and "ACCIRI_LocalID" = p_document_id
    and "ACCIRI_StatusCode" <> 'synced';

  update public."FIN_Documents"
  set "FINDoc_StatusCode" = 'draft',
      "FINDoc_PostingStatusCode" = 'draft',
      "FINDoc_ExportStatusCode" = 'not_queued',
      "FINDoc_ExportBatchID" = null,
      "FINDoc_IsLocked" = false,
      "FINDoc_PostedAt" = null,
      "FINDoc_PostedBy" = null,
      "FINDoc_UpdatedAt" = now(),
      "FINDoc_UpdatedBy" = p_user_id
  where "FINDoc_ID" = p_document_id;

  insert into public."FIN_DocumentStatusHistory"(
    "FINDocStatus_DocumentID", "FINDocStatus_FromStatusCode", "FINDocStatus_ToStatusCode", "FINDocStatus_ChangedBy", "FINDocStatus_Reason", "FINDocStatus_MetadataJSON"
  ) values (
    p_document_id, v_document."FINDoc_StatusCode", 'draft', p_user_id, v_reason,
    jsonb_build_object('priorPostingStatus', v_document."FINDoc_PostingStatusCode", 'cancelledQueueItems', v_cancelled, 'approvalRevoked', true)
  );
  insert into public."Audit_Events"(
    "AuditEvent_EventTypeCode", "AuditEvent_UserID", "AuditEvent_LegalEntityID", "AuditEvent_SourceApp", "AuditEvent_SourceModule", "AuditEvent_SourceTableSchema", "AuditEvent_SourceTableName", "AuditEvent_RecordTypeCode", "AuditEvent_RecordID", "AuditEvent_Action", "AuditEvent_Title", "AuditEvent_MetadataJSON"
  ) values (
    'finance_lifecycle', p_user_id, v_document."FINDoc_LegalEntityID", 'multideck-app', 'finance', 'public', 'FIN_Documents', v_document."FINDoc_TypeCode", p_document_id,
    'reopen_draft', 'Finance document approval revoked and returned to draft',
    jsonb_build_object('from', v_document."FINDoc_StatusCode", 'priorPostingStatus', v_document."FINDoc_PostingStatusCode", 'cancelledQueueItems', v_cancelled, 'reason', v_reason)
  );
  return (select to_jsonb(document) from public."FIN_Documents" document where document."FINDoc_ID" = p_document_id);
end;
$$;


ALTER FUNCTION "public"."multideck_finance_reopen_document_draft"("p_company_id" "uuid", "p_user_id" "uuid", "p_document_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_finance_reporting_snapshot"("p_company_id" "uuid", "p_user_id" "uuid", "p_legal_entity_id" "uuid", "p_from_date" "date", "p_to_date" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_from date; v_to date; v_currency text; v_entity_name text; v_native boolean; v_mode text; v_connection boolean;
begin
  if not exists(select 1 from public."cmp_Users" where "User_ID"=p_user_id and "Company_ID"=p_company_id and coalesce("User_AccessStatus",'active')='active') then
    raise exception 'The finance operator is outside this workspace.' using errcode='42501';
  end if;
  select "LegalEntity_Name",upper("LegalEntity_BaseCurrencyCodeSnapshot") into v_entity_name,v_currency
  from public."cmp_LegalEntities" where "LegalEntity_ID"=p_legal_entity_id and "Company_ID"=p_company_id and "LegalEntity_IsActive";
  if not found then raise exception 'That legal entity is outside this workspace.' using errcode='42501'; end if;
  if p_from_date is null or p_to_date is null or p_to_date<p_from_date or p_to_date>p_from_date+interval '10 years' then
    raise exception 'Choose a valid reporting range of no more than ten years.' using errcode='22023';
  end if;
  v_from:=date_trunc('month',p_from_date)::date;
  v_to:=(date_trunc('month',p_to_date)+interval '1 month'-interval '1 day')::date;
  select mirror_mode,active_connection,native_ledger_enabled into v_mode,v_connection,v_native from public._multideck_finance_mirror_state(p_legal_entity_id);

  return (
    with posted as (
      select nominal."FINNom_ID" account_id,nominal."FINNom_Code" account_code,nominal."FINNom_Name" account_name,
        nominal."FINNom_AccountTypeCode" account_type,coalesce(nominal."FINNom_ReportCategoryCode",'asset') category,
        period."FINPeriod_StartDate" period_start,period."FINPeriod_EndDate" period_end,
        line."FINPostLine_DebitAmount" debit,line."FINPostLine_CreditAmount" credit
      from public."FIN_PostingLines" line
      join public."FIN_PostingBatches" batch on batch."FINPostBatch_ID"=line."FINPostLine_BatchID" and batch."FINPostBatch_StatusCode"='posted'
      join public."FIN_Periods" period on period."FINPeriod_ID"=batch."FINPostBatch_PeriodID"
      join public."FIN_NominalAccounts" nominal on nominal."FINNom_ID"=line."FINPostLine_NominalAccountID"
      where batch."FINPostBatch_LegalEntityID"=p_legal_entity_id and period."FINPeriod_EndDate"<=v_to
    ), accounts as (
      select nominal."FINNom_ID" account_id,nominal."FINNom_Code" account_code,nominal."FINNom_Name" account_name,
        nominal."FINNom_AccountTypeCode" account_type,coalesce(nominal."FINNom_ReportCategoryCode",'asset') category
      from public."FIN_NominalAccounts" nominal
      where nominal."FINNom_LegalEntityID"=p_legal_entity_id and nominal."FINNom_IsActive"
    ), balances as (
      select account.account_id,account.account_code,account.account_name,account.account_type,account.category,
        round(coalesce(sum(posted.debit-posted.credit) filter(where posted.period_end<v_from),0),4) opening_balance,
        round(coalesce(sum(posted.debit) filter(where posted.period_start<=v_to and posted.period_end>=v_from),0),4) period_debit,
        round(coalesce(sum(posted.credit) filter(where posted.period_start<=v_to and posted.period_end>=v_from),0),4) period_credit,
        round(coalesce(sum(posted.debit-posted.credit),0),4) closing_debit_balance
      from accounts account left join posted on posted.account_id=account.account_id
      group by account.account_id,account.account_code,account.account_name,account.account_type,account.category
    ), pnl as (
      -- A positive amount is profit contribution; costs and expenses therefore
      -- appear negative and cannot be accidentally added to income.
      select *,round(period_credit-period_debit,4) display_amount
      from balances where category in ('income','direct_cost','expense','finance')
    ), statement as (
      select *,round(case when category='asset' then closing_debit_balance else -closing_debit_balance end,4) display_amount
      from balances where category in ('asset','liability','equity')
    ), totals as (
      select
        coalesce((select round(sum(display_amount),4) from pnl),0) pnl_total,
        coalesce((select round(sum(-closing_debit_balance),4) from balances where category in ('income','direct_cost','expense','finance')),0) current_earnings,
        coalesce((select round(sum(display_amount),4) from statement where category='asset'),0) assets,
        coalesce((select round(sum(display_amount),4) from statement where category='liability'),0) liabilities,
        coalesce((select round(sum(display_amount),4) from statement where category='equity'),0) equity
    )
    select jsonb_build_object(
      'legalEntityId',p_legal_entity_id,'legalEntity',v_entity_name,'currency',v_currency,'fromDate',v_from,'toDate',v_to,
      'nativeLedgerEnabled',v_native,'externalMirrorModeCode',v_mode,'externalMirrorConnected',v_connection,
      'trialBalance',coalesce((select jsonb_agg(jsonb_build_object(
        'accountId',account_id,'accountCode',account_code,'accountName',account_name,'accountType',account_type,'category',category,
        'openingBalance',opening_balance,'debit',period_debit,'credit',period_credit,'closingBalance',closing_debit_balance
      ) order by account_code) from balances where opening_balance<>0 or period_debit<>0 or period_credit<>0 or closing_debit_balance<>0),'[]'::jsonb),
      'profitAndLoss',coalesce((select jsonb_agg(jsonb_build_object(
        'accountId',account_id,'accountCode',account_code,'accountName',account_name,'category',category,'amount',display_amount
      ) order by account_code) from pnl where display_amount<>0),'[]'::jsonb),
      'balanceSheet',coalesce((select jsonb_agg(jsonb_build_object(
        'accountId',account_id,'accountCode',account_code,'accountName',account_name,'category',category,'amount',display_amount
      ) order by account_code) from statement where display_amount<>0),'[]'::jsonb),
      'totals',(select jsonb_build_object(
        'profitOrLoss',pnl_total,'assets',assets,'liabilities',liabilities,'equity',equity,
        'currentEarnings',current_earnings,'balanceDifference',round(assets-liabilities-equity-current_earnings,4)
      ) from totals),
      'coverage',jsonb_build_object(
        'pendingDocumentMigrations',(select count(*) from public."FIN_Documents" where "FINDoc_LegalEntityID"=p_legal_entity_id and "FINDoc_NativePostingStatusCode"='pending_migration'),
        'pendingCashMigrations',(select count(*) from public."FIN_CashTransactions" where "FINCash_LegalEntityID"=p_legal_entity_id and "FINCash_NativePostingStatusCode"='pending_migration'),
        'postedBatches',(select count(*) from public."FIN_PostingBatches" where "FINPostBatch_LegalEntityID"=p_legal_entity_id and "FINPostBatch_StatusCode"='posted')
      ),
      'evidence',jsonb_build_object('sourceTable','FIN_PostingLines','legalEntityId',p_legal_entity_id,'generatedAt',now())
    )
  );
end; $$;


ALTER FUNCTION "public"."multideck_finance_reporting_snapshot"("p_company_id" "uuid", "p_user_id" "uuid", "p_legal_entity_id" "uuid", "p_from_date" "date", "p_to_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_finance_reverse_accrual_wip"("p_company_id" "uuid", "p_user_id" "uuid", "p_run_id" "uuid", "p_reversal_period_code" "text", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_run public."FIN_PeriodCloseRuns"%rowtype; v_period_id uuid; v_period public."FIN_Periods"%rowtype; v_batch uuid; v_line integer:=0; v_total numeric:=0; v_record record; v_source_line record; v_remaining numeric;
begin
  if nullif(btrim(p_reason),'') is null then raise exception 'Explain why this accrual and WIP journal is being reversed.' using errcode='22023'; end if;
  select run.* into v_run from public."FIN_PeriodCloseRuns" run join public."cmp_LegalEntities" entity on entity."LegalEntity_ID"=run."FINCloseRun_LegalEntityID" where run."FINCloseRun_ID"=p_run_id and entity."Company_ID"=p_company_id for update;
  if not found then raise exception 'Accrual and WIP review not found.' using errcode='P0002'; end if;
  if v_run."FINCloseRun_StatusCode"<>'posted' or v_run."FINCloseRun_PostingBatchID" is null then raise exception 'Only a posted review can be reversed.' using errcode='22023'; end if;
  v_period_id:=public._multideck_finance_ensure_period(v_run."FINCloseRun_LegalEntityID",p_reversal_period_code,p_user_id);
  select * into v_period from public."FIN_Periods" where "FINPeriod_ID"=v_period_id for update;
  if v_period."FINPeriod_StatusCode"<>'open' then raise exception 'Choose an open reversal period.' using errcode='22023'; end if;
  insert into public."FIN_PostingBatches"("FINPostBatch_Number","FINPostBatch_StatusCode","FINPostBatch_SourceTable","FINPostBatch_SourceID","FINPostBatch_PeriodID","FINPostBatch_LegalEntityID","FINPostBatch_DebitTotal","FINPostBatch_CreditTotal","FINPostBatch_CurrencyCodeSnapshot","FINPostBatch_PostedAt","FINPostBatch_PostedBy","FINPostBatch_CreatedBy") values('REV-'||v_period."FINPeriod_Code"||'-'||left(p_run_id::text,8),'posted','FIN_PeriodCloseRuns',p_run_id,v_period_id,v_run."FINCloseRun_LegalEntityID",0,0,v_period."FINPeriod_BaseCurrencyCode",now(),p_user_id,p_user_id) returning "FINPostBatch_ID" into v_batch;
  for v_record in
    select 'accrual' kind,a."FINAccrual_ID" adjustment_id,a."FINAccrual_JobID" job_id,a."FINAccrual_AccruedAmount" original_amount,a."FINAccrual_RelievedAmount" relieved_amount
    from public."FIN_Accruals" a join public."FIN_PeriodCloseRunItems" item on item."FINCloseItem_ID"=a."FINAccrual_CloseRunItemID" where item."FINCloseItem_CloseRunID"=p_run_id and a."FINAccrual_AccruedAmount">a."FINAccrual_RelievedAmount"
    union all
    select 'wip',w."FINWIP_ID",w."FINWIP_JobID",w."FINWIP_WIPAmount",w."FINWIP_RelievedAmount"
    from public."FIN_WIPItems" w join public."FIN_PeriodCloseRunItems" item on item."FINCloseItem_ID"=w."FINWIP_CloseRunItemID" where item."FINCloseItem_CloseRunID"=p_run_id and w."FINWIP_WIPAmount">w."FINWIP_RelievedAmount"
    order by kind,adjustment_id
  loop
    v_remaining:=v_record.original_amount-v_record.relieved_amount;
    for v_source_line in select line.* from public."FIN_PostingLines" line where line."FINPostLine_BatchID"=v_run."FINCloseRun_PostingBatchID" and ((v_record.kind='accrual' and line."FINPostLine_AccrualID"=v_record.adjustment_id) or (v_record.kind='wip' and line."FINPostLine_WIPID"=v_record.adjustment_id)) order by line."FINPostLine_LineNo" loop
      v_line:=v_line+1;
      insert into public."FIN_PostingLines"("FINPostLine_BatchID","FINPostLine_LineNo","FINPostLine_NominalAccountID","FINPostLine_AccrualID","FINPostLine_WIPID","FINPostLine_Description","FINPostLine_DebitAmount","FINPostLine_CreditAmount","FINPostLine_CurrencyCodeSnapshot","FINPostLine_Dimension1ID") values(v_batch,v_line,v_source_line."FINPostLine_NominalAccountID",case when v_record.kind='accrual' then v_record.adjustment_id end,case when v_record.kind='wip' then v_record.adjustment_id end,'Reversal of remaining balance: '||coalesce(v_source_line."FINPostLine_Description",''),round(v_source_line."FINPostLine_CreditAmount"*v_remaining/v_record.original_amount,4),round(v_source_line."FINPostLine_DebitAmount"*v_remaining/v_record.original_amount,4),v_source_line."FINPostLine_CurrencyCodeSnapshot",v_record.job_id);
    end loop;
    if v_record.kind='accrual' then update public."FIN_Accruals" set "FINAccrual_StatusCode"='reversed',"FINAccrual_RelievedAmount"="FINAccrual_AccruedAmount","FINAccrual_ReversalPeriodID"=v_period_id,"FINAccrual_ReversedAt"=now(),"FINAccrual_ReversedBy"=p_user_id where "FINAccrual_ID"=v_record.adjustment_id;
    else update public."FIN_WIPItems" set "FINWIP_StatusCode"='reversed',"FINWIP_RelievedAmount"="FINWIP_WIPAmount","FINWIP_ReversalPeriodID"=v_period_id,"FINWIP_ReversedAt"=now(),"FINWIP_ReversedBy"=p_user_id where "FINWIP_ID"=v_record.adjustment_id; end if;
    v_total:=v_total+v_remaining;
  end loop;
  if v_total<=0 then raise exception 'This review has no remaining accrual or WIP balance to reverse.' using errcode='22023'; end if;
  update public."FIN_PostingBatches" set "FINPostBatch_DebitTotal"=v_total,"FINPostBatch_CreditTotal"=v_total where "FINPostBatch_ID"=v_batch;
  update public."FIN_PeriodCloseRunItems" set "FINCloseItem_StatusCode"='reversed',"FINCloseItem_UpdatedAt"=now(),"FINCloseItem_UpdatedBy"=p_user_id where "FINCloseItem_CloseRunID"=p_run_id;
  update public."FIN_PeriodCloseRuns" set "FINCloseRun_StatusCode"='reversed',"FINCloseRun_ReversedAt"=now(),"FINCloseRun_ReversedBy"=p_user_id,"FINCloseRun_ReversalBatchID"=v_batch,"FINCloseRun_UpdatedAt"=now(),"FINCloseRun_UpdatedBy"=p_user_id where "FINCloseRun_ID"=p_run_id;
  insert into public."Audit_Events"("AuditEvent_EventTypeCode","AuditEvent_UserID","AuditEvent_LegalEntityID","AuditEvent_SourceApp","AuditEvent_SourceModule","AuditEvent_SourceTableSchema","AuditEvent_SourceTableName","AuditEvent_RecordTypeCode","AuditEvent_RecordID","AuditEvent_Action","AuditEvent_Title","AuditEvent_Reason","AuditEvent_HasFieldChanges","AuditEvent_ChangedFieldCount","AuditEvent_MetadataJSON") values('finance_lifecycle',p_user_id,v_run."FINCloseRun_LegalEntityID",'multideck-app','finance','public','FIN_PeriodCloseRuns','accrual_wip_review',p_run_id,'reverse_accrual_wip','Remaining accrual and WIP journal reversed',btrim(p_reason),true,1,jsonb_build_object('reversalBatchId',v_batch,'periodCode',p_reversal_period_code,'remainingTotal',v_total));
  return jsonb_build_object('runId',p_run_id,'status','reversed','reversalBatchId',v_batch,'total',v_total);
end; $$;


ALTER FUNCTION "public"."multideck_finance_reverse_accrual_wip"("p_company_id" "uuid", "p_user_id" "uuid", "p_run_id" "uuid", "p_reversal_period_code" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_finance_save_administration"("p_company_id" "uuid", "p_user_id" "uuid", "p_legal_entity_id" "uuid", "p_settings" "jsonb", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  v_entity public."cmp_LegalEntities";
  v_item jsonb;
  v_id uuid;
  v_pack_id uuid;
  v_settings_id uuid;
  v_localisation_id uuid;
  v_connection_id uuid;
  v_base_currency text;
  v_country text;
  v_code text;
  v_revision integer;
  v_missing text[] := array[]::text[];
  v_row_count integer;
  v_control_count integer;
  v_active_banks integer;
  v_active_currencies integer;
  v_active_taxes integer;
  v_active_sequences integer;
begin
  if jsonb_typeof(coalesce(p_settings,'{}'::jsonb)) <> 'object' then
    raise exception 'Finance settings must be an object.' using errcode='22023';
  end if;
  if not exists(select 1 from public."cmp_Users" where "User_ID"=p_user_id and "Company_ID"=p_company_id and coalesce("User_AccessStatus",'active')='active') then
    raise exception 'The finance operator is outside this workspace.' using errcode='42501';
  end if;
  select * into v_entity from public."cmp_LegalEntities" where "LegalEntity_ID"=p_legal_entity_id and "Company_ID"=p_company_id and "LegalEntity_IsActive" for update;
  if not found then raise exception 'That legal entity is outside this workspace.' using errcode='42501'; end if;

  v_base_currency := upper(nullif(btrim(p_settings#>>'{organisation,baseCurrencyCode}'),''));
  v_country := upper(nullif(btrim(p_settings#>>'{organisation,countryCode}'),''));
  if v_base_currency is null or v_base_currency !~ '^[A-Z]{3}$' then raise exception 'Enter a valid three-letter base currency.' using errcode='22023'; end if;
  if v_country is null or v_country !~ '^[A-Z]{2}$' or not exists(select 1 from public."RefCountry" where upper("RN_Code")=v_country and coalesce("RN_IsActive",true)) then raise exception 'Choose a valid legal-entity country.' using errcode='22023'; end if;

  foreach v_code in array array['currencies','banks','nominalAccounts','taxJurisdictions','taxCodes','numberSequences','paymentTerms','accountMappings','chargeMappings','taxMappings'] loop
    if p_settings ? v_code and jsonb_typeof(p_settings->v_code) <> 'array' then raise exception 'Finance setting % must be a list.',v_code using errcode='22023'; end if;
    if jsonb_array_length(coalesce(p_settings->v_code,'[]'::jsonb)) > 500 then raise exception 'Finance setting % has too many rows.',v_code using errcode='22023'; end if;
  end loop;

  update public."cmp_LegalEntities" set
    "LegalEntity_CountryCode"=v_country,
    "LegalEntity_BaseCurrencyCodeSnapshot"=v_base_currency,
    "LegalEntity_VATNumber"=nullif(btrim(p_settings#>>'{organisation,taxRegistrationNo}'),''),
    "LegalEntity_SettingsJSON"="LegalEntity_SettingsJSON" || jsonb_build_object('financeAdministration',jsonb_build_object(
      'accountingStandardCode',coalesce(nullif(btrim(p_settings#>>'{organisation,accountingStandardCode}'),''),'IFRS'),
      'fiscalYearStartMonth',greatest(1,least(12,coalesce((p_settings#>>'{organisation,fiscalYearStartMonth}')::integer,1))),
      'timeZone',coalesce(nullif(btrim(p_settings#>>'{organisation,timeZone}'),''),'Europe/London'),
      'updatedAt',now()
    )),
    "LegalEntity_UpdatedAt"=now(),"LegalEntity_UpdatedBy"=p_user_id
  where "LegalEntity_ID"=p_legal_entity_id;

  select "FINSET_ID" into v_settings_id from public."FIN_Settings" where "FINSET_LegalEntityID"=p_legal_entity_id and "FINSET_OrgOfficeID" is null and "FINSET_BrandID" is null for update;
  if v_settings_id is null then
    insert into public."FIN_Settings"(
      "FINSET_LegalEntityID","FINSET_BaseCurrencyCode","FINSET_DefaultOperatingModelCode","FINSET_AutoCreateSalesInvoices","FINSET_AutoCreatePurchaseAccruals","FINSET_AutoPostLowRiskItems","FINSET_UseAccountingDateRules","FINSET_BlockLockedPeriodDirectPosting","FINSET_DefaultROEProviderCode","FINSET_IncludeFXInOperationalProfit","FINSET_SettingsJSON","FINSET_CreatedBy","FINSET_UpdatedBy"
    ) values (
      p_legal_entity_id,v_base_currency,coalesce(nullif(p_settings#>>'{controls,defaultOperatingModelCode}',''),'hybrid'),
      coalesce((p_settings#>>'{controls,autoCreateSalesInvoices}')::boolean,false),coalesce((p_settings#>>'{controls,autoCreatePurchaseAccruals}')::boolean,true),coalesce((p_settings#>>'{controls,autoPostLowRiskItems}')::boolean,false),coalesce((p_settings#>>'{controls,useAccountingDateRules}')::boolean,true),coalesce((p_settings#>>'{controls,blockLockedPeriodDirectPosting}')::boolean,true),nullif(btrim(p_settings#>>'{controls,defaultRoeProviderCode}'),''),coalesce((p_settings#>>'{controls,includeFxInOperationalProfit}')::boolean,false),
      jsonb_build_object('administration',coalesce(p_settings->'controls','{}'::jsonb),'defaults',coalesce(p_settings->'defaults','{}'::jsonb),'updatedAt',now()),p_user_id,p_user_id
    ) returning "FINSET_ID" into v_settings_id;
  else
    update public."FIN_Settings" set
      "FINSET_BaseCurrencyCode"=v_base_currency,
      "FINSET_DefaultOperatingModelCode"=coalesce(nullif(p_settings#>>'{controls,defaultOperatingModelCode}',''),'hybrid'),
      "FINSET_AutoCreateSalesInvoices"=coalesce((p_settings#>>'{controls,autoCreateSalesInvoices}')::boolean,false),
      "FINSET_AutoCreatePurchaseAccruals"=coalesce((p_settings#>>'{controls,autoCreatePurchaseAccruals}')::boolean,true),
      "FINSET_AutoPostLowRiskItems"=coalesce((p_settings#>>'{controls,autoPostLowRiskItems}')::boolean,false),
      "FINSET_UseAccountingDateRules"=coalesce((p_settings#>>'{controls,useAccountingDateRules}')::boolean,true),
      "FINSET_BlockLockedPeriodDirectPosting"=coalesce((p_settings#>>'{controls,blockLockedPeriodDirectPosting}')::boolean,true),
      "FINSET_DefaultROEProviderCode"=nullif(btrim(p_settings#>>'{controls,defaultRoeProviderCode}'),''),
      "FINSET_IncludeFXInOperationalProfit"=coalesce((p_settings#>>'{controls,includeFxInOperationalProfit}')::boolean,false),
      "FINSET_SettingsJSON"="FINSET_SettingsJSON" || jsonb_build_object('administration',coalesce(p_settings->'controls','{}'::jsonb),'defaults',coalesce(p_settings->'defaults','{}'::jsonb),'updatedAt',now()),
      "FINSET_UpdatedAt"=now(),"FINSET_UpdatedBy"=p_user_id
    where "FINSET_ID"=v_settings_id;
  end if;

  select "FINLocPack_ID" into v_pack_id from public."FIN_LocalisationPacks" where "FINLocPack_Code"=coalesce(nullif(p_settings#>>'{organisation,localisationPackCode}',''),'global-v1') and "FINLocPack_IsActive" limit 1;
  if v_pack_id is null then raise exception 'Choose an active finance localisation pack.' using errcode='22023'; end if;
  select "FINLocSet_ID" into v_localisation_id from public."FIN_LocalisationSettings" where "FINLocSet_LegalEntityID"=p_legal_entity_id and "FINLocSet_IsActive" for update;
  if v_localisation_id is null then
    insert into public."FIN_LocalisationSettings"("FINLocSet_LegalEntityID","FINLocSet_PackID","FINLocSet_TaxRegistrationNo","FINLocSet_ReportingBasisCode","FINLocSet_SettingsJSON","FINLocSet_EffectiveFrom","FINLocSet_UpdatedBy")
    values(p_legal_entity_id,v_pack_id,nullif(btrim(p_settings#>>'{organisation,taxRegistrationNo}'),''),coalesce(nullif(btrim(p_settings#>>'{organisation,reportingBasisCode}'),''),'accrual'),coalesce(p_settings->'taxSettings','{}'::jsonb),coalesce((p_settings#>>'{organisation,effectiveFrom}')::date,current_date),p_user_id)
    returning "FINLocSet_ID" into v_localisation_id;
  else
