      get diagnostics v_row_count=row_count; if v_row_count=0 then raise exception 'A document sequence is outside this legal entity.' using errcode='42501'; end if;
    end if;
  end loop;

  for v_item in select value from jsonb_array_elements(coalesce(p_settings->'paymentTerms','[]'::jsonb)) loop
    v_code:=nullif(btrim(v_item->>'code'),''); if v_code is null then raise exception 'Every payment term needs a code.' using errcode='22023'; end if;
    v_id:=nullif(v_item->>'id','')::uuid;
    if v_id is null then
      insert into public."FIN_PaymentTerms"("FINTerm_Code","FINTerm_Name","FINTerm_Days","FINTerm_DueDayOfMonth","FINTerm_EndOfMonth","FINTerm_IsCashAccount","FINTerm_IsActive","FINTerm_LegalEntityID","FINTerm_CreatedBy","FINTerm_UpdatedBy")
      values(v_code,coalesce(nullif(btrim(v_item->>'name'),''),v_code),greatest(0,coalesce((v_item->>'days')::integer,30)),nullif(v_item->>'dueDayOfMonth','')::integer,coalesce((v_item->>'endOfMonth')::boolean,false),coalesce((v_item->>'isCashAccount')::boolean,false),coalesce((v_item->>'isActive')::boolean,true),p_legal_entity_id,p_user_id,p_user_id)
      on conflict ("FINTerm_LegalEntityID","FINTerm_Code") where "FINTerm_LegalEntityID" is not null do update set "FINTerm_Name"=excluded."FINTerm_Name","FINTerm_Days"=excluded."FINTerm_Days","FINTerm_DueDayOfMonth"=excluded."FINTerm_DueDayOfMonth","FINTerm_EndOfMonth"=excluded."FINTerm_EndOfMonth","FINTerm_IsCashAccount"=excluded."FINTerm_IsCashAccount","FINTerm_IsActive"=excluded."FINTerm_IsActive","FINTerm_UpdatedAt"=now(),"FINTerm_UpdatedBy"=p_user_id;
    else
      update public."FIN_PaymentTerms" set "FINTerm_Code"=v_code,"FINTerm_Name"=coalesce(nullif(btrim(v_item->>'name'),''),v_code),"FINTerm_Days"=greatest(0,coalesce((v_item->>'days')::integer,30)),"FINTerm_DueDayOfMonth"=nullif(v_item->>'dueDayOfMonth','')::integer,"FINTerm_EndOfMonth"=coalesce((v_item->>'endOfMonth')::boolean,false),"FINTerm_IsCashAccount"=coalesce((v_item->>'isCashAccount')::boolean,false),"FINTerm_IsActive"=coalesce((v_item->>'isActive')::boolean,true),"FINTerm_UpdatedAt"=now(),"FINTerm_UpdatedBy"=p_user_id where "FINTerm_ID"=v_id and "FINTerm_LegalEntityID"=p_legal_entity_id;
      get diagnostics v_row_count=row_count; if v_row_count=0 then raise exception 'A payment term is outside this legal entity.' using errcode='42501'; end if;
    end if;
  end loop;

  -- Provider mappings are connection-scoped. A connection must belong to the
  -- same legal entity before any mapping can be inserted or changed.
  for v_item in select value from jsonb_array_elements(coalesce(p_settings->'accountMappings','[]'::jsonb)) loop
    v_connection_id:=nullif(v_item->>'connectionId','')::uuid;
    if not exists(select 1 from public."ACCI_Connections" where "ACCIC_ID"=v_connection_id and "ACCIC_LegalEntityID"=p_legal_entity_id) then raise exception 'An account mapping connection is outside this legal entity.' using errcode='42501'; end if;
    v_id:=nullif(v_item->>'id','')::uuid;
    if v_id is null then
      insert into public."ACCI_AccountMappings"("ACCIAM_ConnectionID","ACCIAM_DirectionCode","ACCIAM_LocalContextCode","ACCIAM_ProviderAccountID","ACCIAM_ProviderAccountCode","ACCIAM_ProviderAccountName","ACCIAM_IsDefault","ACCIAM_IsActive") values(v_connection_id,coalesce(nullif(v_item->>'directionCode',''),'sales'),nullif(btrim(v_item->>'localContextCode'),''),coalesce(nullif(btrim(v_item->>'providerAccountId'),''),nullif(btrim(v_item->>'providerAccountCode'),'')),nullif(btrim(v_item->>'providerAccountCode'),''),nullif(btrim(v_item->>'providerAccountName'),''),coalesce((v_item->>'isDefault')::boolean,false),coalesce((v_item->>'isActive')::boolean,true));
    else
      update public."ACCI_AccountMappings" set "ACCIAM_DirectionCode"=coalesce(nullif(v_item->>'directionCode',''),'sales'),"ACCIAM_LocalContextCode"=nullif(btrim(v_item->>'localContextCode'),''),"ACCIAM_ProviderAccountID"=coalesce(nullif(btrim(v_item->>'providerAccountId'),''),nullif(btrim(v_item->>'providerAccountCode'),'')),"ACCIAM_ProviderAccountCode"=nullif(btrim(v_item->>'providerAccountCode'),''),"ACCIAM_ProviderAccountName"=nullif(btrim(v_item->>'providerAccountName'),''),"ACCIAM_IsDefault"=coalesce((v_item->>'isDefault')::boolean,false),"ACCIAM_IsActive"=coalesce((v_item->>'isActive')::boolean,true) where "ACCIAM_ID"=v_id and "ACCIAM_ConnectionID"=v_connection_id;
      get diagnostics v_row_count=row_count; if v_row_count=0 then raise exception 'An account mapping is outside this connection.' using errcode='42501'; end if;
    end if;
  end loop;

  for v_item in select value from jsonb_array_elements(coalesce(p_settings->'chargeMappings','[]'::jsonb)) loop
    v_connection_id:=nullif(v_item->>'connectionId','')::uuid;
    if not exists(select 1 from public."ACCI_Connections" where "ACCIC_ID"=v_connection_id and "ACCIC_LegalEntityID"=p_legal_entity_id) then raise exception 'A charge mapping connection is outside this legal entity.' using errcode='42501'; end if;
    v_id:=nullif(v_item->>'id','')::uuid;
    if v_id is null then
      insert into public."ACCI_ChargeCodeMappings"("ACCICM_ConnectionID","ACCICM_LocalChargeCodeSnapshot","ACCICM_DirectionCode","ACCICM_ProviderItemID","ACCICM_ProviderItemCode","ACCICM_ProviderItemName","ACCICM_ProviderAccountID","ACCICM_IsActive") values(v_connection_id,coalesce(nullif(btrim(v_item->>'localChargeCode'),''),'ADHOC'),coalesce(nullif(v_item->>'directionCode',''),'sales'),nullif(btrim(v_item->>'providerItemId'),''),nullif(btrim(v_item->>'providerItemCode'),''),nullif(btrim(v_item->>'providerItemName'),''),nullif(btrim(v_item->>'providerAccountId'),''),coalesce((v_item->>'isActive')::boolean,true));
    else
      update public."ACCI_ChargeCodeMappings" set "ACCICM_LocalChargeCodeSnapshot"=coalesce(nullif(btrim(v_item->>'localChargeCode'),''),'ADHOC'),"ACCICM_DirectionCode"=coalesce(nullif(v_item->>'directionCode',''),'sales'),"ACCICM_ProviderItemID"=nullif(btrim(v_item->>'providerItemId'),''),"ACCICM_ProviderItemCode"=nullif(btrim(v_item->>'providerItemCode'),''),"ACCICM_ProviderItemName"=nullif(btrim(v_item->>'providerItemName'),''),"ACCICM_ProviderAccountID"=nullif(btrim(v_item->>'providerAccountId'),''),"ACCICM_IsActive"=coalesce((v_item->>'isActive')::boolean,true) where "ACCICM_ID"=v_id and "ACCICM_ConnectionID"=v_connection_id;
      get diagnostics v_row_count=row_count; if v_row_count=0 then raise exception 'A charge mapping is outside this connection.' using errcode='42501'; end if;
    end if;
  end loop;

  for v_item in select value from jsonb_array_elements(coalesce(p_settings->'taxMappings','[]'::jsonb)) loop
    v_connection_id:=nullif(v_item->>'connectionId','')::uuid;
    if not exists(select 1 from public."ACCI_Connections" where "ACCIC_ID"=v_connection_id and "ACCIC_LegalEntityID"=p_legal_entity_id) then raise exception 'A tax mapping connection is outside this legal entity.' using errcode='42501'; end if;
    v_id:=nullif(v_item->>'id','')::uuid;
    if v_id is null then
      insert into public."ACCI_TaxCodeMappings"("ACCITM_ConnectionID","ACCITM_LocalTaxCode","ACCITM_LocalTaxDescription","ACCITM_LocalCountryCode","ACCITM_DirectionCode","ACCITM_ProviderTaxID","ACCITM_ProviderTaxCode","ACCITM_ProviderTaxName","ACCITM_TaxRatePercent","ACCITM_IsActive") values(v_connection_id,coalesce(nullif(btrim(v_item->>'localTaxCode'),''),'out-of-scope'),nullif(btrim(v_item->>'localTaxDescription'),''),upper(coalesce(nullif(btrim(v_item->>'countryCode'),''),v_country)),coalesce(nullif(v_item->>'directionCode',''),'sales'),nullif(btrim(v_item->>'providerTaxId'),''),coalesce(nullif(btrim(v_item->>'providerTaxCode'),''),nullif(btrim(v_item->>'localTaxCode'),'')),nullif(btrim(v_item->>'providerTaxName'),''),nullif(v_item->>'taxRatePercent','')::numeric,coalesce((v_item->>'isActive')::boolean,true));
    else
      update public."ACCI_TaxCodeMappings" set "ACCITM_LocalTaxCode"=coalesce(nullif(btrim(v_item->>'localTaxCode'),''),'out-of-scope'),"ACCITM_LocalTaxDescription"=nullif(btrim(v_item->>'localTaxDescription'),''),"ACCITM_LocalCountryCode"=upper(coalesce(nullif(btrim(v_item->>'countryCode'),''),v_country)),"ACCITM_DirectionCode"=coalesce(nullif(v_item->>'directionCode',''),'sales'),"ACCITM_ProviderTaxID"=nullif(btrim(v_item->>'providerTaxId'),''),"ACCITM_ProviderTaxCode"=coalesce(nullif(btrim(v_item->>'providerTaxCode'),''),nullif(btrim(v_item->>'localTaxCode'),'')),"ACCITM_ProviderTaxName"=nullif(btrim(v_item->>'providerTaxName'),''),"ACCITM_TaxRatePercent"=nullif(v_item->>'taxRatePercent','')::numeric,"ACCITM_IsActive"=coalesce((v_item->>'isActive')::boolean,true) where "ACCITM_ID"=v_id and "ACCITM_ConnectionID"=v_connection_id;
      get diagnostics v_row_count=row_count; if v_row_count=0 then raise exception 'A tax mapping is outside this connection.' using errcode='42501'; end if;
    end if;
  end loop;

  select count(*) into v_control_count from public."FIN_NominalAccounts" where "FINNom_LegalEntityID"=p_legal_entity_id and "FINNom_IsControlAccount" and "FINNom_IsActive";
  select count(*) into v_active_banks from public."FIN_BankAccounts" where "FINBank_LegalEntityID"=p_legal_entity_id and "FINBank_IsActive";
  select count(*) into v_active_currencies from public."FIN_CurrencySettings" where "FINCurSet_LegalEntityID"=p_legal_entity_id and "FINCurSet_IsActive";
  select count(*) into v_active_taxes from public."FIN_TaxCodes" where "FINTax_LegalEntityID"=p_legal_entity_id and "FINTax_IsActive";
  select count(*) into v_active_sequences from public."FIN_NumberSequences" where "FINSeq_LegalEntityID"=p_legal_entity_id and "FINSeq_IsActive";
  if v_control_count < 6 then v_missing:=array_append(v_missing,'control_accounts'); end if;
  if v_active_banks = 0 then v_missing:=array_append(v_missing,'bank_account'); end if;
  if v_active_currencies = 0 then v_missing:=array_append(v_missing,'operating_currency'); end if;
  if v_active_taxes = 0 then v_missing:=array_append(v_missing,'tax_treatment'); end if;
  if v_active_sequences < 4 then v_missing:=array_append(v_missing,'document_sequences'); end if;
  if not exists(select 1 from public."ACCI_Connections" where "ACCIC_LegalEntityID"=p_legal_entity_id and "ACCIC_StatusCode"='active') then v_missing:=array_append(v_missing,'accounting_connection'); end if;

  update public."FIN_AdministrationRevisions" set "FINAdminRevision_StatusCode"='superseded' where "FINAdminRevision_LegalEntityID"=p_legal_entity_id and "FINAdminRevision_StatusCode"='approved';
  select coalesce(max("FINAdminRevision_Number"),0)+1 into v_revision from public."FIN_AdministrationRevisions" where "FINAdminRevision_LegalEntityID"=p_legal_entity_id;
  insert into public."FIN_AdministrationRevisions"("FINAdminRevision_LegalEntityID","FINAdminRevision_Number","FINAdminRevision_ConfigJSON","FINAdminRevision_ReadinessJSON","FINAdminRevision_Reason","FINAdminRevision_ApprovedBy")
  values(p_legal_entity_id,v_revision,p_settings,jsonb_build_object('ready',coalesce(array_length(v_missing,1),0)=0,'missing',to_jsonb(v_missing),'controlAccounts',v_control_count,'banks',v_active_banks,'currencies',v_active_currencies,'taxCodes',v_active_taxes,'sequences',v_active_sequences),nullif(btrim(p_reason),''),p_user_id);

  insert into public."Audit_Events"("AuditEvent_EventTypeCode","AuditEvent_UserID","AuditEvent_LegalEntityID","AuditEvent_SourceApp","AuditEvent_SourceModule","AuditEvent_SourceTableSchema","AuditEvent_SourceTableName","AuditEvent_RecordTypeCode","AuditEvent_RecordID","AuditEvent_Action","AuditEvent_Title","AuditEvent_Reason","AuditEvent_HasFieldChanges","AuditEvent_ChangedFieldCount","AuditEvent_MetadataJSON")
  values('finance_lifecycle',p_user_id,p_legal_entity_id,'multideck-app','finance','public','FIN_AdministrationRevisions','finance_configuration',p_legal_entity_id,'approve_finance_administration','Finance administration settings approved',nullif(btrim(p_reason),''),true,1,jsonb_build_object('revision',v_revision,'ready',coalesce(array_length(v_missing,1),0)=0,'missing',to_jsonb(v_missing)));

  return jsonb_build_object('legalEntityId',p_legal_entity_id,'revision',v_revision,'ready',coalesce(array_length(v_missing,1),0)=0,'missing',to_jsonb(v_missing));
exception when unique_violation then
  raise exception 'A finance code or default is duplicated for this legal entity.' using errcode='22023';
end;
$_$;


ALTER FUNCTION "public"."multideck_finance_save_administration"("p_company_id" "uuid", "p_user_id" "uuid", "p_legal_entity_id" "uuid", "p_settings" "jsonb", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_finance_transition_accrual_wip"("p_company_id" "uuid", "p_user_id" "uuid", "p_run_id" "uuid", "p_action" "text", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_run public."FIN_PeriodCloseRuns"%rowtype; v_next text;
begin
  select run.* into v_run from public."FIN_PeriodCloseRuns" run join public."cmp_LegalEntities" entity on entity."LegalEntity_ID"=run."FINCloseRun_LegalEntityID" where run."FINCloseRun_ID"=p_run_id and entity."Company_ID"=p_company_id for update;
  if not found then raise exception 'Accrual and WIP review not found.' using errcode='P0002'; end if;
  if not exists(select 1 from public."cmp_Users" where "User_ID"=p_user_id and "Company_ID"=p_company_id and coalesce("User_AccessStatus",'active')='active') then raise exception 'The finance operator is outside this workspace.' using errcode='42501'; end if;
  if p_action='request_review' and v_run."FINCloseRun_StatusCode"='draft' then v_next:='awaiting_approval';
  elsif p_action='approve' and v_run."FINCloseRun_StatusCode"='awaiting_approval' then v_next:='approved';
  elsif p_action='reject' and v_run."FINCloseRun_StatusCode" in ('awaiting_approval','approved') then v_next:='rejected';
  else raise exception 'That review cannot make this transition from %.',v_run."FINCloseRun_StatusCode" using errcode='22023'; end if;
  update public."FIN_PeriodCloseRuns" set "FINCloseRun_StatusCode"=v_next,"FINCloseRun_ApprovedAt"=case when v_next='approved' then now() else "FINCloseRun_ApprovedAt" end,"FINCloseRun_ApprovedBy"=case when v_next='approved' then p_user_id else "FINCloseRun_ApprovedBy" end,"FINCloseRun_UpdatedAt"=now(),"FINCloseRun_UpdatedBy"=p_user_id where "FINCloseRun_ID"=p_run_id;
  update public."FIN_PeriodCloseRunItems" set "FINCloseItem_StatusCode"=v_next,"FINCloseItem_ApprovedWIP"=case when v_next='approved' then "FINCloseItem_ProposedWIP" else "FINCloseItem_ApprovedWIP" end,"FINCloseItem_ApprovedAccrual"=case when v_next='approved' then "FINCloseItem_ProposedAccrual" else "FINCloseItem_ApprovedAccrual" end,"FINCloseItem_UpdatedAt"=now(),"FINCloseItem_UpdatedBy"=p_user_id where "FINCloseItem_CloseRunID"=p_run_id;
  if v_next='approved' then
    update public."FIN_JobChargePeriodAllocations" allocation set
      "FINChargePeriod_ApprovedWIP"=allocation."FINChargePeriod_ProposedWIP",
      "FINChargePeriod_ApprovedAccrual"=allocation."FINChargePeriod_ProposedAccrual",
      "FINChargePeriod_UpdatedAt"=now(),"FINChargePeriod_UpdatedBy"=p_user_id
    from public."FIN_PeriodCloseRunItems" item
    where item."FINCloseItem_ID"=allocation."FINChargePeriod_CloseRunItemID" and item."FINCloseItem_CloseRunID"=p_run_id;
  end if;
  insert into public."Audit_Events"("AuditEvent_EventTypeCode","AuditEvent_UserID","AuditEvent_LegalEntityID","AuditEvent_SourceApp","AuditEvent_SourceModule","AuditEvent_SourceTableSchema","AuditEvent_SourceTableName","AuditEvent_RecordTypeCode","AuditEvent_RecordID","AuditEvent_Action","AuditEvent_Title","AuditEvent_Reason","AuditEvent_HasFieldChanges","AuditEvent_ChangedFieldCount","AuditEvent_MetadataJSON") values('finance_lifecycle',p_user_id,v_run."FINCloseRun_LegalEntityID",'multideck-app','finance','public','FIN_PeriodCloseRuns','accrual_wip_review',p_run_id,p_action,'Accrual and WIP review '||replace(v_next,'_',' '),nullif(btrim(p_reason),''),true,1,jsonb_build_object('fromStatus',v_run."FINCloseRun_StatusCode",'toStatus',v_next,'basis','job_charge_lines'));
  return jsonb_build_object('runId',p_run_id,'status',v_next);
end; $$;


ALTER FUNCTION "public"."multideck_finance_transition_accrual_wip"("p_company_id" "uuid", "p_user_id" "uuid", "p_run_id" "uuid", "p_action" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_finance_transition_cash"("p_company_id" "uuid", "p_user_id" "uuid", "p_cash_id" "uuid", "p_transition" "text", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare v_cash public."FIN_CashTransactions"; v_entity_currency text; v_bank_currency text; v_next text; v_allocation public."FIN_CashAllocations"; v_document public."FIN_Documents"; v_queue uuid; v_allocation_count integer; v_total_allocated numeric;
begin
  if not exists(select 1 from public."cmp_Users" where "User_ID"=p_user_id and "Company_ID"=p_company_id and coalesce("User_AccessStatus",'active')='active') then raise exception 'The finance operator is outside this workspace.' using errcode='42501'; end if;
  select cash.* into v_cash from public."FIN_CashTransactions" cash join public."cmp_LegalEntities" entity on entity."LegalEntity_ID"=cash."FINCash_LegalEntityID" where cash."FINCash_ID"=p_cash_id and entity."Company_ID"=p_company_id for update of cash;
  if not found then raise exception 'Cash transaction not found in this workspace.' using errcode='P0002'; end if;
  if p_transition='request_review' and v_cash."FINCash_StatusCode"='draft' then v_next:='awaiting_approval';
  elsif p_transition='approve' and v_cash."FINCash_StatusCode"='awaiting_approval' then v_next:='approved';
  elsif p_transition='reject' and v_cash."FINCash_StatusCode"='awaiting_approval' then v_next:='rejected';
  else raise exception 'That cash transition is not available from its current status.' using errcode='22023'; end if;
  if v_next in ('awaiting_approval','approved') then
    select upper("LegalEntity_BaseCurrencyCodeSnapshot") into v_entity_currency from public."cmp_LegalEntities" where "LegalEntity_ID"=v_cash."FINCash_LegalEntityID" and "Company_ID"=p_company_id and "LegalEntity_IsActive";
    if not found or v_entity_currency is null or v_entity_currency!~'^[A-Z]{3}$' then raise exception 'Configure a valid base currency for this legal entity.' using errcode='22023'; end if;
    if upper(coalesce(v_cash."FINCash_CurrencyCodeSnapshot",''))!~'^[A-Z]{3}$' then raise exception 'The receipt or payment has no valid transaction currency.' using errcode='22023'; end if;
    if v_cash."FINCash_ExchangeRate"::text in ('NaN','Infinity','-Infinity') or v_cash."FINCash_ExchangeRate"<=0 or (upper(v_cash."FINCash_CurrencyCodeSnapshot")=v_entity_currency and v_cash."FINCash_ExchangeRate"<>1) then raise exception 'The receipt or payment has no valid reviewed exchange rate.' using errcode='22023'; end if;
    if v_cash."FINCash_Amount"::text in ('NaN','Infinity','-Infinity') or v_cash."FINCash_Amount"<=0 or v_cash."FINCash_LocalAmount" is distinct from round(v_cash."FINCash_Amount"*v_cash."FINCash_ExchangeRate",4) then raise exception 'The receipt or payment amount no longer agrees with its exchange rate.' using errcode='22023'; end if;
    if v_cash."FINCash_BankAccountID" is null then raise exception 'Choose an active bank account before approving this receipt or payment.' using errcode='22023'; end if;
    select upper("FINBank_CurrencyCode") into v_bank_currency from public."FIN_BankAccounts" where "FINBank_ID"=v_cash."FINCash_BankAccountID" and "FINBank_LegalEntityID"=v_cash."FINCash_LegalEntityID" and "FINBank_IsActive";
    if not found then raise exception 'The selected bank account is no longer active for this legal entity.' using errcode='22023'; end if;
    if v_bank_currency is null or v_bank_currency!~'^[A-Z]{3}$' then raise exception 'Configure a valid currency for the selected bank account.' using errcode='22023'; end if;
    if v_bank_currency<>upper(v_cash."FINCash_CurrencyCodeSnapshot") then raise exception 'The bank account currency must match the receipt or payment currency.' using errcode='22023'; end if;
    if not exists(select 1 from public."Org_Master" where "Org_id"=v_cash."FINCash_PartyOrgID") then raise exception 'The receipt or payment customer or supplier is no longer available.' using errcode='22023'; end if;
    select count(*),coalesce(sum("FINCashAlloc_AllocatedAmount"),0) into v_allocation_count,v_total_allocated from public."FIN_CashAllocations" where "FINCashAlloc_CashID"=p_cash_id and "FINCashAlloc_AllocationStatusCode"='pending';
    if v_allocation_count>100 or v_total_allocated>v_cash."FINCash_Amount" or v_cash."FINCash_UnallocatedAmount" is distinct from v_cash."FINCash_Amount"-v_total_allocated then raise exception 'The receipt or payment allocations no longer agree with its amount.' using errcode='22023'; end if;
  end if;
  if v_next='approved' then
    for v_allocation in select * from public."FIN_CashAllocations" where "FINCashAlloc_CashID"=p_cash_id and "FINCashAlloc_AllocationStatusCode"='pending' order by "FINCashAlloc_DocumentID" for update loop
      select * into v_document from public."FIN_Documents" where "FINDoc_ID"=v_allocation."FINCashAlloc_DocumentID" for update;
      if not found or v_document."FINDoc_LegalEntityID" is distinct from v_cash."FINCash_LegalEntityID" or v_document."FINDoc_PartyOrgID" is distinct from v_cash."FINCash_PartyOrgID" or v_document."FINDoc_CurrencyCodeSnapshot"<>v_cash."FINCash_CurrencyCodeSnapshot" or v_document."FINDoc_StatusCode" not in ('approved','submitted') or v_document."FINDoc_TypeCode"<>(case when v_cash."FINCash_TypeCode"='customer_receipt' then 'sl_invoice' else 'pl_invoice' end) or v_document."FINDoc_OutstandingAmount"<v_allocation."FINCashAlloc_AllocatedAmount" then raise exception 'An allocation is no longer valid against the open balance.' using errcode='22023'; end if;
      update public."FIN_Documents" set "FINDoc_OutstandingAmount"="FINDoc_OutstandingAmount"-v_allocation."FINCashAlloc_AllocatedAmount","FINDoc_LocalOutstandingAmount"="FINDoc_LocalOutstandingAmount"-v_allocation."FINCashAlloc_LocalAllocatedAmount","FINDoc_UpdatedAt"=now(),"FINDoc_UpdatedBy"=p_user_id where "FINDoc_ID"=v_document."FINDoc_ID";
      update public."FIN_CashAllocations" set "FINCashAlloc_AllocationStatusCode"='allocated',"FINCashAlloc_AllocatedAt"=now(),"FINCashAlloc_AllocatedBy"=p_user_id where "FINCashAlloc_ID"=v_allocation."FINCashAlloc_ID";
    end loop;
    insert into public."FIN_IntegrationQueue"("FINIntQ_LocalTable","FINIntQ_LocalID","FINIntQ_StatusCode","FINIntQ_CreatedBy") values('FIN_CashTransactions',p_cash_id,'queued',p_user_id)
    on conflict ("FINIntQ_LocalTable","FINIntQ_LocalID") where "FINIntQ_StatusCode" in ('queued','processing','blocked') do update set "FINIntQ_StatusCode"='queued',"FINIntQ_LastError"=null returning "FINIntQ_ID" into v_queue;
  elsif v_next='awaiting_approval' then
    insert into public."FIN_AuthorisationRequests"("FINAUTHREQ_ActionTypeCode","FINAUTHREQ_SourceTable","FINAUTHREQ_SourceID","FINAUTHREQ_RequestedBy","FINAUTHREQ_Amount","FINAUTHREQ_CurrencyCodeSnapshot","FINAUTHREQ_Reason")
    values('finance_cash_post','FIN_CashTransactions',p_cash_id,p_user_id,v_cash."FINCash_Amount",v_cash."FINCash_CurrencyCodeSnapshot",coalesce(nullif(btrim(p_reason),''),'Finance cash review requested'));
  end if;
  if v_next in ('approved','rejected') then
    with resolved as (
      update public."FIN_AuthorisationRequests" set "FINAUTHREQ_StatusCode"=v_next where "FINAUTHREQ_SourceTable"='FIN_CashTransactions' and "FINAUTHREQ_SourceID"=p_cash_id and "FINAUTHREQ_StatusCode"='awaiting_approval' returning "FINAUTHREQ_ID"
    ) insert into public."FIN_AuthorisationDecisions"("FINAUTHDEC_RequestID","FINAUTHDEC_DecisionCode","FINAUTHDEC_DecidedBy","FINAUTHDEC_Comments","FINAUTHDEC_MetadataJSON")
      select "FINAUTHREQ_ID",v_next,p_user_id,nullif(btrim(p_reason),''),jsonb_build_object('transition',p_transition) from resolved;
  end if;
  update public."FIN_CashTransactions" set "FINCash_StatusCode"=v_next,"FINCash_PostingStatusCode"=case when v_next='approved' then 'queued' else "FINCash_PostingStatusCode" end,"FINCash_UpdatedAt"=now(),"FINCash_UpdatedBy"=p_user_id where "FINCash_ID"=p_cash_id;
  insert into public."Audit_Events"("AuditEvent_EventTypeCode","AuditEvent_UserID","AuditEvent_LegalEntityID","AuditEvent_SourceApp","AuditEvent_SourceModule","AuditEvent_SourceTableSchema","AuditEvent_SourceTableName","AuditEvent_RecordTypeCode","AuditEvent_RecordID","AuditEvent_Action","AuditEvent_Title","AuditEvent_MetadataJSON")
  values('finance_lifecycle',p_user_id,v_cash."FINCash_LegalEntityID",'multideck-app','finance','public','FIN_CashTransactions',v_cash."FINCash_TypeCode",p_cash_id,p_transition,'Finance cash status changed',jsonb_build_object('from',v_cash."FINCash_StatusCode",'to',v_next,'integrationQueueId',v_queue));
  return (select to_jsonb(c) from public."FIN_CashTransactions" c where c."FINCash_ID"=p_cash_id);
end;
$_$;


ALTER FUNCTION "public"."multideck_finance_transition_cash"("p_company_id" "uuid", "p_user_id" "uuid", "p_cash_id" "uuid", "p_transition" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_finance_transition_document"("p_company_id" "uuid", "p_user_id" "uuid", "p_document_id" "uuid", "p_transition" "text", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  v_document public."FIN_Documents";
  v_entity_currency text;
  v_next text;
  v_queue uuid;
  v_line_count integer;
  v_line_net numeric;
  v_line_tax numeric;
  v_line_gross numeric;
  v_local_line_net numeric;
  v_local_line_tax numeric;
  v_local_line_gross numeric;
  v_tax_status text;
begin
  if not exists (
    select 1 from public."cmp_Users"
    where "User_ID" = p_user_id
      and "Company_ID" = p_company_id
      and coalesce("User_AccessStatus", 'active') = 'active'
  ) then
    raise exception 'The finance operator is outside this workspace.' using errcode = '42501';
  end if;
  select document.*
  into v_document
  from public."FIN_Documents" document
  join public."cmp_LegalEntities" entity on entity."LegalEntity_ID" = document."FINDoc_LegalEntityID"
  where document."FINDoc_ID" = p_document_id and entity."Company_ID" = p_company_id
  for update of document;
  if not found then
    raise exception 'Finance document not found in this workspace.' using errcode = 'P0002';
  end if;

  if p_transition = 'request_review' and v_document."FINDoc_StatusCode" = 'draft' then v_next := 'awaiting_approval';
  elsif p_transition = 'approve' and v_document."FINDoc_StatusCode" = 'awaiting_approval' then v_next := 'approved';
  elsif p_transition = 'reject' and v_document."FINDoc_StatusCode" = 'awaiting_approval' then v_next := 'rejected';
  else
    raise exception 'That finance document transition is not available from its current status.' using errcode = '22023';
  end if;

  if v_next = 'awaiting_approval' then
    -- Re-resolve provisional classifications against the now-approved setup.
    -- The line trigger owns the rate and all derived amounts.
    update public."FIN_DocumentLines"
    set "FINDocLine_TaxCodeSnapshot" = "FINDocLine_TaxCodeSnapshot"
    where "FINDocLine_DocumentID" = p_document_id
      and "FINDocLine_TaxCodeID" is null
      and nullif(btrim("FINDocLine_TaxCodeSnapshot"), '') is not null;

    select
      count(*),
      coalesce(sum("FINDocLine_NetAmount"), 0),
      coalesce(sum("FINDocLine_TaxAmount"), 0),
      coalesce(sum("FINDocLine_GrossAmount"), 0),
      coalesce(sum("FINDocLine_LocalNetAmount"), 0),
      coalesce(sum("FINDocLine_LocalTaxAmount"), 0),
      coalesce(sum("FINDocLine_LocalGrossAmount"), 0),
      case when bool_and("FINDocLine_TaxCodeID" is not null) then 'approved' else 'pending' end
    into
      v_line_count, v_line_net, v_line_tax, v_line_gross,
      v_local_line_net, v_local_line_tax, v_local_line_gross, v_tax_status
    from public."FIN_DocumentLines"
    where "FINDocLine_DocumentID" = p_document_id;

    update public."FIN_Documents"
    set "FINDoc_NetAmount" = v_line_net,
        "FINDoc_TaxAmount" = v_line_tax,
        "FINDoc_GrossAmount" = v_line_gross,
        "FINDoc_LocalNetAmount" = v_local_line_net,
        "FINDoc_LocalTaxAmount" = v_local_line_tax,
        "FINDoc_LocalGrossAmount" = v_local_line_gross,
        "FINDoc_OutstandingAmount" = v_line_gross,
        "FINDoc_LocalOutstandingAmount" = v_local_line_gross,
        "FINDoc_MetadataJSON" = jsonb_set("FINDoc_MetadataJSON", '{taxStatus}', to_jsonb(v_tax_status), true),
        "FINDoc_UpdatedAt" = now(),
        "FINDoc_UpdatedBy" = p_user_id
    where "FINDoc_ID" = p_document_id;

    select document.* into v_document
    from public."FIN_Documents" document
    where document."FINDoc_ID" = p_document_id;

    if v_tax_status <> 'approved' then
      raise exception 'Finance must approve local tax advice and every line must use an approved effective treatment before review.' using errcode = '22023';
    end if;
  end if;

  if v_next in ('awaiting_approval', 'approved') then
    select upper("LegalEntity_BaseCurrencyCodeSnapshot")
    into v_entity_currency
    from public."cmp_LegalEntities"
    where "LegalEntity_ID" = v_document."FINDoc_LegalEntityID"
      and "Company_ID" = p_company_id
      and "LegalEntity_IsActive";
    if not found or v_entity_currency is null or v_entity_currency !~ '^[A-Z]{3}$' then
      raise exception 'Configure a valid base currency for this legal entity.' using errcode = '22023';
    end if;
    if upper(coalesce(v_document."FINDoc_CurrencyCodeSnapshot", '')) !~ '^[A-Z]{3}$' then
      raise exception 'The finance document has no valid transaction currency.' using errcode = '22023';
    end if;
    if v_document."FINDoc_ExchangeRate"::text in ('NaN', 'Infinity', '-Infinity')
      or v_document."FINDoc_ExchangeRate" <= 0
      or (upper(v_document."FINDoc_CurrencyCodeSnapshot") = v_entity_currency and v_document."FINDoc_ExchangeRate" <> 1) then
      raise exception 'The finance document has no valid reviewed exchange rate.' using errcode = '22023';
    end if;
    if v_document."FINDoc_DueDate" is not null and v_document."FINDoc_DueDate" < v_document."FINDoc_DocumentDate" then
      raise exception 'The due date cannot be before the document date.' using errcode = '22023';
    end if;
    if v_document."FINDoc_GrossAmount" = 0
      or (v_document."FINDoc_TypeCode" in ('credit_note', 'debit_note') and v_document."FINDoc_GrossAmount" >= 0)
      or (v_document."FINDoc_TypeCode" in ('sl_invoice', 'pl_invoice') and v_document."FINDoc_GrossAmount" <= 0) then
      raise exception 'The finance document amount has the wrong invoice or credit polarity.' using errcode = '22023';
    end if;
    if not exists (select 1 from public."Org_Master" where "Org_id" = v_document."FINDoc_PartyOrgID") then
      raise exception 'The finance document customer or supplier is no longer available.' using errcode = '22023';
    end if;
    if v_document."FINDoc_SourceKindCode" = 'job' and not exists (
      select 1
      from public."Job_Header" job
      join public."cmp_Offices" office on office."Office_ID" = coalesce(job."Job_OrgOfficeID", job."Job_OfficeID")
      where job."Job_ID" = v_document."FINDoc_SourceJobID"
        and not job."Job_IsDeleted"
        and office."Company_ID" = p_company_id
        and (job."Job_LegalEntityID" is null or job."Job_LegalEntityID" = v_document."FINDoc_LegalEntityID")
        and case when v_document."FINDoc_TypeCode" in ('sl_invoice', 'credit_note') then job."Job_Customer" else job."Job_Supplier" end = v_document."FINDoc_PartyOrgID"
    ) then
      raise exception 'The job, legal entity and customer or supplier no longer match.' using errcode = '22023';
    end if;

    select
      count(*),
      coalesce(sum("FINDocLine_NetAmount"), 0),
      coalesce(sum("FINDocLine_TaxAmount"), 0),
      coalesce(sum("FINDocLine_GrossAmount"), 0)
    into v_line_count, v_line_net, v_line_tax, v_line_gross
    from public."FIN_DocumentLines"
    where "FINDocLine_DocumentID" = p_document_id;
    if v_line_count not between 1 and 100
      or v_line_net is distinct from v_document."FINDoc_NetAmount"
      or v_line_tax is distinct from v_document."FINDoc_TaxAmount"
      or v_line_gross is distinct from v_document."FINDoc_GrossAmount" then
      raise exception 'The finance document header no longer agrees with its lines.' using errcode = '22023';
    end if;
    if exists (
      select 1 from public."FIN_DocumentLines"
      where "FINDocLine_DocumentID" = p_document_id
        and (
          nullif(btrim("FINDocLine_Description"), '') is null
          or nullif(btrim("FINDocLine_ChargeCodeSnapshot"), '') is null
          or "FINDocLine_Quantity" <= 0
          or "FINDocLine_UnitAmount" < 0
          or "FINDocLine_TaxCodeID" is null
          or "FINDocLine_TaxRatePercent" not between 0 and 100
        )
    ) then
      raise exception 'One or more finance document lines are incomplete.' using errcode = '22023';
    end if;
  end if;

  update public."FIN_Documents"
  set "FINDoc_StatusCode" = v_next,
      "FINDoc_PostingStatusCode" = case when v_next = 'approved' then 'queued' else "FINDoc_PostingStatusCode" end,
      "FINDoc_ExportStatusCode" = case when v_next = 'approved' then 'queued' else "FINDoc_ExportStatusCode" end,
      "FINDoc_UpdatedAt" = now(),
      "FINDoc_UpdatedBy" = p_user_id
  where "FINDoc_ID" = p_document_id;

  if v_next = 'awaiting_approval' then
    insert into public."FIN_AuthorisationRequests"(
      "FINAUTHREQ_ActionTypeCode", "FINAUTHREQ_SourceTable", "FINAUTHREQ_SourceID", "FINAUTHREQ_DocumentID", "FINAUTHREQ_RequestedBy", "FINAUTHREQ_Amount", "FINAUTHREQ_CurrencyCodeSnapshot", "FINAUTHREQ_Reason"
    ) values (
      'finance_post', 'FIN_Documents', p_document_id, p_document_id, p_user_id,
      v_document."FINDoc_GrossAmount", v_document."FINDoc_CurrencyCodeSnapshot", coalesce(nullif(btrim(p_reason), ''), 'Finance review requested')
    );
  elsif v_next = 'approved' then
    insert into public."FIN_IntegrationQueue"(
      "FINIntQ_LocalTable", "FINIntQ_LocalID", "FINIntQ_DocumentID", "FINIntQ_StatusCode", "FINIntQ_CreatedBy"
    ) values ('FIN_Documents', p_document_id, p_document_id, 'queued', p_user_id)
    on conflict ("FINIntQ_LocalTable", "FINIntQ_LocalID")
      where "FINIntQ_StatusCode" in ('queued', 'processing', 'blocked')
    do update set "FINIntQ_StatusCode" = 'queued', "FINIntQ_LastError" = null
    returning "FINIntQ_ID" into v_queue;
  end if;

  if v_next in ('approved', 'rejected') then
    with resolved as (
      update public."FIN_AuthorisationRequests"
      set "FINAUTHREQ_StatusCode" = v_next
      where "FINAUTHREQ_SourceTable" = 'FIN_Documents'
        and "FINAUTHREQ_SourceID" = p_document_id
        and "FINAUTHREQ_StatusCode" = 'awaiting_approval'
      returning "FINAUTHREQ_ID"
    )
    insert into public."FIN_AuthorisationDecisions"(
      "FINAUTHDEC_RequestID", "FINAUTHDEC_DecisionCode", "FINAUTHDEC_DecidedBy", "FINAUTHDEC_Comments", "FINAUTHDEC_MetadataJSON"
    )
    select "FINAUTHREQ_ID", v_next, p_user_id, nullif(btrim(p_reason), ''), jsonb_build_object('transition', p_transition)
    from resolved;
  end if;

  insert into public."FIN_DocumentStatusHistory"(
    "FINDocStatus_DocumentID", "FINDocStatus_FromStatusCode", "FINDocStatus_ToStatusCode", "FINDocStatus_ChangedBy", "FINDocStatus_Reason", "FINDocStatus_MetadataJSON"
  ) values (
    p_document_id, v_document."FINDoc_StatusCode", v_next, p_user_id, nullif(btrim(p_reason), ''), jsonb_build_object('integrationQueueId', v_queue)
  );
  insert into public."Audit_Events"(
    "AuditEvent_EventTypeCode", "AuditEvent_UserID", "AuditEvent_LegalEntityID", "AuditEvent_SourceApp", "AuditEvent_SourceModule", "AuditEvent_SourceTableSchema", "AuditEvent_SourceTableName", "AuditEvent_RecordTypeCode", "AuditEvent_RecordID", "AuditEvent_Action", "AuditEvent_Title", "AuditEvent_MetadataJSON"
  ) values (
    'finance_lifecycle', p_user_id, v_document."FINDoc_LegalEntityID", 'multideck-app', 'finance', 'public', 'FIN_Documents', v_document."FINDoc_TypeCode", p_document_id,
    p_transition, 'Finance document status changed', jsonb_build_object('from', v_document."FINDoc_StatusCode", 'to', v_next, 'integrationQueueId', v_queue)
  );
  return (select to_jsonb(document) from public."FIN_Documents" document where document."FINDoc_ID" = p_document_id);
end;
$_$;


ALTER FUNCTION "public"."multideck_finance_transition_document"("p_company_id" "uuid", "p_user_id" "uuid", "p_document_id" "uuid", "p_transition" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_finance_update_document_draft"("p_company_id" "uuid", "p_user_id" "uuid", "p_document_id" "uuid", "p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  v_document public."FIN_Documents";
  v_type text;
  v_entity uuid;
  v_entity_currency text;
  v_party uuid;
  v_job uuid;
  v_job_company uuid;
  v_job_entity uuid;
  v_job_party uuid;
  v_date date;
  v_due date;
  v_currency text;
  v_exchange numeric;
  v_source_kind text;
  v_line jsonb;
  v_index integer := 0;
  v_quantity numeric;
  v_unit numeric;
  v_net numeric;
  v_tax numeric;
  v_gross numeric;
  v_total_net numeric := 0;
  v_total_tax numeric := 0;
  v_total_gross numeric := 0;
  v_line_id uuid;
  v_tax_status text;
begin
  if jsonb_typeof(p_input) <> 'object' then
    raise exception 'Finance input must be an object.' using errcode = '22023';
  end if;
  if not exists (
    select 1 from public."cmp_Users"
    where "User_ID" = p_user_id
      and "Company_ID" = p_company_id
      and coalesce("User_AccessStatus", 'active') = 'active'
  ) then
    raise exception 'The finance operator is outside this workspace.' using errcode = '42501';
  end if;

  select document.*
  into v_document
  from public."FIN_Documents" document
  join public."cmp_LegalEntities" entity on entity."LegalEntity_ID" = document."FINDoc_LegalEntityID"
  where document."FINDoc_ID" = p_document_id
    and entity."Company_ID" = p_company_id
  for update of document;
  if not found then
    raise exception 'Finance document not found in this workspace.' using errcode = 'P0002';
  end if;
  if v_document."FINDoc_StatusCode" <> 'draft'
    or v_document."FINDoc_IsLocked"
    or v_document."FINDoc_PostedAt" is not null then
    raise exception 'Only an unlocked draft can be edited.' using errcode = '22023';
  end if;

  v_type := v_document."FINDoc_TypeCode";
  v_entity := v_document."FINDoc_LegalEntityID";
  begin
    v_party := (p_input ->> 'partyOrgId')::uuid;
  exception when invalid_text_representation then
    raise exception 'Choose a valid customer or supplier.' using errcode = '22023';
  end;
  if not exists (select 1 from public."Org_Master" where "Org_id" = v_party) then
    raise exception 'Choose a valid customer or supplier.' using errcode = '22023';
  end if;

  select upper(entity."LegalEntity_BaseCurrencyCodeSnapshot")
  into v_entity_currency
  from public."cmp_LegalEntities" entity
  where entity."LegalEntity_ID" = v_entity
    and entity."Company_ID" = p_company_id
    and entity."LegalEntity_IsActive";
  if not found or v_entity_currency !~ '^[A-Z]{3}$' then
    raise exception 'Configure a valid base currency for this legal entity.' using errcode = '22023';
  end if;

  begin
    v_date := coalesce(nullif(p_input ->> 'documentDate', '')::date, current_date);
    v_due := nullif(p_input ->> 'dueDate', '')::date;
  exception when invalid_datetime_format then
    raise exception 'Check the document and due dates.' using errcode = '22023';
  end;
  if v_due is not null and v_due < v_date then
    raise exception 'The due date cannot be before the document date.' using errcode = '22023';
  end if;

  v_currency := upper(coalesce(nullif(btrim(p_input ->> 'currencyCode'), ''), v_entity_currency));
  if v_currency !~ '^[A-Z]{3}$' then
    raise exception 'Enter a three-letter currency code.' using errcode = '22023';
  end if;
  begin
    v_exchange := coalesce(nullif(p_input ->> 'exchangeRate', '')::numeric, 1);
  exception when invalid_text_representation then
    raise exception 'Enter a valid exchange rate.' using errcode = '22023';
  end;
  if v_exchange::text in ('NaN', 'Infinity', '-Infinity')
    or v_exchange <= 0
    or (v_currency <> v_entity_currency and nullif(p_input ->> 'exchangeRate', '') is null) then
    raise exception 'Enter the reviewed exchange rate from document currency to base currency.' using errcode = '22023';
  end if;
  if v_currency = v_entity_currency then v_exchange := 1; end if;

  if nullif(p_input ->> 'sourceJobId', '') is not null then
    begin
      v_job := (p_input ->> 'sourceJobId')::uuid;
    exception when invalid_text_representation then
      raise exception 'Choose a valid job.' using errcode = '22023';
    end;
    select office."Company_ID", job."Job_LegalEntityID",
      case when v_type in ('sl_invoice', 'credit_note') then job."Job_Customer" else job."Job_Supplier" end
    into v_job_company, v_job_entity, v_job_party
    from public."Job_Header" job
    join public."cmp_Offices" office on office."Office_ID" = coalesce(job."Job_OrgOfficeID", job."Job_OfficeID")
    where job."Job_ID" = v_job and not job."Job_IsDeleted";
    if v_job_company is distinct from p_company_id
      or (v_job_entity is not null and v_job_entity is distinct from v_entity) then
      raise exception 'That job is outside the selected company or legal entity.' using errcode = '42501';
    end if;
    if v_job_party is null or v_job_party is distinct from v_party then
      raise exception 'The selected party must match the customer or supplier on the job.' using errcode = '22023';
    end if;
  end if;

  if jsonb_typeof(p_input -> 'lines') <> 'array'
    or jsonb_array_length(p_input -> 'lines') not between 1 and 100 then
    raise exception 'Add between one and 100 document lines.' using errcode = '22023';
  end if;

  delete from public."FIN_DocumentLines"
  where "FINDocLine_DocumentID" = p_document_id;

  v_source_kind := case when v_job is null then 'manual' else 'job' end;
  for v_line in select value from jsonb_array_elements(p_input -> 'lines') loop
    v_index := v_index + 1;
    begin
      v_quantity := coalesce(nullif(v_line ->> 'quantity', '')::numeric, 1);
      v_unit := coalesce(nullif(v_line ->> 'unitAmount', '')::numeric, 0);
    exception when invalid_text_representation then
      raise exception 'Check finance line %.', v_index using errcode = '22023';
    end;
    if v_quantity::text in ('NaN', 'Infinity', '-Infinity')
      or v_unit::text in ('NaN', 'Infinity', '-Infinity')
      or nullif(btrim(v_line ->> 'description'), '') is null
      or length(v_line ->> 'description') > 1000
      or nullif(btrim(v_line ->> 'chargeCode'), '') is null
      or length(v_line ->> 'chargeCode') > 80
      or length(coalesce(v_line ->> 'taxCode', '')) > 80
      or v_quantity <= 0
      or v_unit < 0 then
      raise exception 'Check finance line %.', v_index using errcode = '22023';
    end if;

    v_net := round(v_quantity * v_unit, 4) * case when v_type in ('credit_note', 'debit_note') then -1 else 1 end;
    insert into public."FIN_DocumentLines"(
      "FINDocLine_DocumentID", "FINDocLine_LineNo", "FINDocLine_LineTypeCode", "FINDocLine_ChargeCodeSnapshot", "FINDocLine_Description", "FINDocLine_Quantity", "FINDocLine_UnitAmount",
      "FINDocLine_NetAmount", "FINDocLine_TaxCodeSnapshot", "FINDocLine_TaxRatePercent", "FINDocLine_TaxAmount", "FINDocLine_GrossAmount",
      "FINDocLine_LocalNetAmount", "FINDocLine_LocalTaxAmount", "FINDocLine_LocalGrossAmount"
    ) values (
      p_document_id, v_index,
      case when v_job is not null then 'freight' when coalesce(v_line ->> 'lineType', '') = 'ancillary' then 'ancillary' else 'service' end,
      left(btrim(v_line ->> 'chargeCode'), 80), btrim(v_line ->> 'description'), v_quantity, v_unit,
      v_net, nullif(left(btrim(v_line ->> 'taxCode'), 80), ''), 0, 0, v_net,
      round(v_net * v_exchange, 4), 0, round(v_net * v_exchange, 4)
    ) returning "FINDocLine_ID", "FINDocLine_NetAmount", "FINDocLine_TaxAmount", "FINDocLine_GrossAmount"
    into v_line_id, v_net, v_tax, v_gross;

    if v_job is not null then
      insert into public."FIN_DocumentLineJobLinks"(
        "FINDocLineJob_DocumentID", "FINDocLineJob_DocumentLineID", "FINDocLineJob_JobID", "FINDocLineJob_LinkTypeCode", "FINDocLineJob_NetAmount", "FINDocLineJob_LocalNetAmount", "FINDocLineJob_PercentOfLine"
      ) values (p_document_id, v_line_id, v_job, 'source_job', v_net, round(v_net * v_exchange, 4), 100);
    end if;
    v_total_net := v_total_net + v_net;
    v_total_tax := v_total_tax + v_tax;
    v_total_gross := v_total_gross + v_gross;
  end loop;

  if abs(v_total_gross) <= 0 then
    raise exception 'The finance document gross amount must be greater than zero.' using errcode = '22023';
  end if;
  select case when bool_and(line."FINDocLine_TaxCodeID" is not null) then 'approved' else 'pending' end
  into v_tax_status
  from public."FIN_DocumentLines" line
  where line."FINDocLine_DocumentID" = p_document_id;

  update public."FIN_Documents"
  set "FINDoc_PartyOrgID" = v_party,
      "FINDoc_PartyRole" = case when v_type in ('sl_invoice', 'credit_note') then 'customer' else 'supplier' end,
      "FINDoc_DocumentDate" = v_date,
      "FINDoc_AccountingDate" = v_date,
      "FINDoc_DueDate" = v_due,
      "FINDoc_CurrencyCodeSnapshot" = v_currency,
      "FINDoc_ExchangeRate" = v_exchange,
      "FINDoc_SourceJobID" = v_job,
      "FINDoc_SourceTable" = case when v_job is null then null else 'Job_Header' end,
      "FINDoc_SourceID" = v_job,
      "FINDoc_SourceKindCode" = v_source_kind,
      "FINDoc_NetAmount" = v_total_net,
      "FINDoc_TaxAmount" = v_total_tax,
      "FINDoc_GrossAmount" = v_total_gross,
      "FINDoc_LocalNetAmount" = round(v_total_net * v_exchange, 4),
      "FINDoc_LocalTaxAmount" = round(v_total_tax * v_exchange, 4),
      "FINDoc_LocalGrossAmount" = round(v_total_gross * v_exchange, 4),
      "FINDoc_OutstandingAmount" = v_total_gross,
      "FINDoc_LocalOutstandingAmount" = round(v_total_gross * v_exchange, 4),
      "FINDoc_MetadataJSON" = jsonb_set(
        jsonb_set("FINDoc_MetadataJSON", '{sourceKind}', to_jsonb(v_source_kind), true),
        '{taxStatus}', to_jsonb(v_tax_status), true
      ),
      "FINDoc_UpdatedAt" = now(),
      "FINDoc_UpdatedBy" = p_user_id
  where "FINDoc_ID" = p_document_id;

  insert into public."FIN_DocumentStatusHistory"(
    "FINDocStatus_DocumentID", "FINDocStatus_FromStatusCode", "FINDocStatus_ToStatusCode", "FINDocStatus_ChangedBy", "FINDocStatus_Reason", "FINDocStatus_MetadataJSON"
  ) values (
    p_document_id, 'draft', 'draft', p_user_id, 'Draft edited in Multideck finance',
    jsonb_build_object('sourceKind', v_source_kind, 'jobId', v_job, 'taxStatus', v_tax_status)
  );
  insert into public."Audit_Events"(
    "AuditEvent_EventTypeCode", "AuditEvent_UserID", "AuditEvent_LegalEntityID", "AuditEvent_SourceApp", "AuditEvent_SourceModule", "AuditEvent_SourceTableSchema", "AuditEvent_SourceTableName", "AuditEvent_RecordTypeCode", "AuditEvent_RecordID", "AuditEvent_Action", "AuditEvent_Title", "AuditEvent_MetadataJSON"
  ) values (
    'finance_lifecycle', p_user_id, v_entity, 'multideck-app', 'finance', 'public', 'FIN_Documents', v_type, p_document_id,
    'update_draft', 'Finance document draft updated',
    jsonb_build_object('grossAmount', v_total_gross, 'currency', v_currency, 'exchangeRate', v_exchange, 'taxStatus', v_tax_status)
  );
  return (select to_jsonb(document) from public."FIN_Documents" document where document."FINDoc_ID" = p_document_id);
end;
$_$;


ALTER FUNCTION "public"."multideck_finance_update_document_draft"("p_company_id" "uuid", "p_user_id" "uuid", "p_document_id" "uuid", "p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_finance_upsert_job_charge"("p_company_id" "uuid", "p_user_id" "uuid", "p_job_id" "uuid", "p_domain_code" "text", "p_source_table" "text", "p_source_id" "uuid", "p_source_line_id" "uuid", "p_description" "text", "p_supplier_id" "uuid", "p_charge_code_id" "uuid", "p_expected_cost_local" numeric, "p_expected_revenue_local" numeric, "p_expected_cost_currency" numeric, "p_expected_revenue_currency" numeric, "p_cost_currency_id" integer, "p_revenue_currency_id" integer, "p_cost_roe" numeric, "p_revenue_roe" numeric, "p_source_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_entity uuid; v_line uuid;
begin
  if not exists(select 1 from public."cmp_Users" where "User_ID"=p_user_id and "Company_ID"=p_company_id and coalesce("User_AccessStatus",'active')='active') then
    raise exception 'The operator is outside this workspace.' using errcode='42501';
  end if;
  v_entity:=public._multideck_finance_resolve_job_legal_entity(p_job_id);
  if v_entity is null or not exists(select 1 from public."cmp_LegalEntities" where "LegalEntity_ID"=v_entity and "Company_ID"=p_company_id and "LegalEntity_IsActive") then
    raise exception 'The job is outside this workspace or has no active legal entity.' using errcode='42501';
  end if;
  v_line:=public._multideck_finance_upsert_job_charge(p_job_id,p_domain_code,p_source_table,p_source_id,p_source_line_id,p_description,p_supplier_id,p_charge_code_id,p_expected_cost_local,p_expected_revenue_local,p_expected_cost_currency,p_expected_revenue_currency,p_cost_currency_id,p_revenue_currency_id,p_cost_roe,p_revenue_roe,p_user_id,p_source_metadata);
  return v_line;
end; $$;


ALTER FUNCTION "public"."multideck_finance_upsert_job_charge"("p_company_id" "uuid", "p_user_id" "uuid", "p_job_id" "uuid", "p_domain_code" "text", "p_source_table" "text", "p_source_id" "uuid", "p_source_line_id" "uuid", "p_description" "text", "p_supplier_id" "uuid", "p_charge_code_id" "uuid", "p_expected_cost_local" numeric, "p_expected_revenue_local" numeric, "p_expected_cost_currency" numeric, "p_expected_revenue_currency" numeric, "p_cost_currency_id" integer, "p_revenue_currency_id" integer, "p_cost_roe" numeric, "p_revenue_roe" numeric, "p_source_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_get_usage_categories"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_context record;
begin
  select * into v_context from public._multideck_dexter_context();
  if not private.is_tenant_administrator(v_context.user_id) then
    raise exception 'Only tenant administrators can view workspace usage.' using errcode = '42501';
  end if;
  return public._multideck_usage_categories(v_context.company_id);
end;
$$;


ALTER FUNCTION "public"."multideck_get_usage_categories"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_inbox_apply_suggested_update"("p_company_id" "uuid", "p_user_id" "uuid", "p_suggestion_id" "uuid", "p_selected_field_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_suggestion public."AI_InboxSuggestedUpdates";
  v_job public."Job_Header";
  v_field public."AI_InboxSuggestedUpdateFields";
  v_current jsonb;
  v_applied_ids uuid[] := '{}'::uuid[];
  v_document_id uuid;
  v_version integer;
  v_now timestamptz := now();
begin
  if p_company_id is null or p_user_id is null or p_suggestion_id is null then
    raise exception 'That suggested update is invalid.' using errcode = '22023';
  end if;
  if not public._multideck_dexter_has_permission(p_user_id, 'Email.Read')
     or not public._multideck_dexter_has_permission(p_user_id, 'Email.AIRead')
     or not public._multideck_dexter_has_permission(p_user_id, 'Bookings.Read')
     or not public._multideck_dexter_has_permission(p_user_id, 'Bookings.Write') then
    raise exception 'You do not have permission to apply this suggested update.' using errcode = '42501';
  end if;

  select suggestion.* into v_suggestion
  from public."AI_InboxSuggestedUpdates" suggestion
  where suggestion."AIInboxSuggestion_ID" = p_suggestion_id
    and suggestion."AIInboxSuggestion_CompanyID" = p_company_id
    and suggestion."AIInboxSuggestion_OwnerUserID" = p_user_id
  for update;
  if not found then raise exception 'That suggested update was not found.' using errcode = 'P0002'; end if;
  if v_suggestion."AIInboxSuggestion_StatusCode" = 'applied' then
    return jsonb_build_object('status','already_applied','suggestionId',p_suggestion_id,'bookingId',v_suggestion."AIInboxSuggestion_TargetID",'documentId',v_suggestion."AIInboxSuggestion_AppliedJobDocumentID");
  end if;
  if v_suggestion."AIInboxSuggestion_StatusCode" <> 'ready' or v_suggestion."AIInboxSuggestion_TargetTypeCode" <> 'booking' then
    raise exception 'This suggestion is not ready to apply.' using errcode = '55000';
  end if;
  if coalesce(cardinality(p_selected_field_ids), 0) = 0 then
    raise exception 'Choose at least one change to apply.' using errcode = '22023';
  end if;

  select job.* into v_job
  from public."Job_Header" job
  join public."cmp_Offices" office on office."Office_ID" = coalesce(job."Job_OrgOfficeID", job."Job_OfficeID")
  where job."Job_ID" = v_suggestion."AIInboxSuggestion_TargetID"
    and office."Company_ID" = p_company_id and not job."Job_IsDeleted"
  for update;
  if not found then raise exception 'The matched booking is no longer available.' using errcode = 'P0002'; end if;

  update public."AI_InboxSuggestedUpdates" set
    "AIInboxSuggestion_StatusCode" = 'applying', "AIInboxSuggestion_UpdatedAt" = v_now
  where "AIInboxSuggestion_ID" = p_suggestion_id;

  for v_field in
    select field.* from public."AI_InboxSuggestedUpdateFields" field
    where field."AIInboxField_SuggestionID" = p_suggestion_id
      and field."AIInboxField_ID" = any(p_selected_field_ids)
    order by field."AIInboxField_SortOrder", field."AIInboxField_ID"
  loop
    if v_field."AIInboxField_TargetRecordTypeCode" = 'route' then
      select case v_field."AIInboxField_FieldCode"
        when 'planned_arrival_at' then coalesce(to_jsonb(route."JobRoute_PlannedArrivalAt"), 'null'::jsonb)
        when 'vessel' then coalesce(to_jsonb(route."JobRoute_Vessel"), 'null'::jsonb)
        when 'voyage_number' then coalesce(to_jsonb(route."JobRoute_VoyageNumber"), 'null'::jsonb)
        when 'destination_terminal' then coalesce(to_jsonb(route."JobRoute_DestinationTerminal"), 'null'::jsonb)
        else 'null'::jsonb end
      into v_current
      from public."Job_Routing" route
      where route."JobRoute_ID" = v_field."AIInboxField_TargetRecordID" and route."Job_ID" = v_job."Job_ID"
      for update;
      if not found or v_current is distinct from v_field."AIInboxField_CurrentValueJSON" then
        raise exception 'The booking changed after this suggestion was prepared. Review it again before applying.' using errcode = '40001';
      end if;
      update public."Job_Routing" route set
        "JobRoute_PlannedArrivalAt" = case when v_field."AIInboxField_FieldCode" = 'planned_arrival_at' then nullif(v_field."AIInboxField_ProposedValueJSON" #>> '{}','')::timestamptz else route."JobRoute_PlannedArrivalAt" end,
        "JobRoute_Vessel" = case when v_field."AIInboxField_FieldCode" = 'vessel' then nullif(v_field."AIInboxField_ProposedValueJSON" #>> '{}','') else route."JobRoute_Vessel" end,
        "JobRoute_VoyageNumber" = case when v_field."AIInboxField_FieldCode" = 'voyage_number' then nullif(v_field."AIInboxField_ProposedValueJSON" #>> '{}','') else route."JobRoute_VoyageNumber" end,
        "JobRoute_DestinationTerminal" = case when v_field."AIInboxField_FieldCode" = 'destination_terminal' then nullif(v_field."AIInboxField_ProposedValueJSON" #>> '{}','') else route."JobRoute_DestinationTerminal" end,
        "JobRoute_UpdatedAt" = v_now, "JobRoute_UpdatedBy" = p_user_id
      where route."JobRoute_ID" = v_field."AIInboxField_TargetRecordID";
    elsif v_field."AIInboxField_TargetRecordTypeCode" = 'cargo' and v_field."AIInboxField_FieldCode" = 'gross_weight_kg' then
      select coalesce(to_jsonb(cargo."JobCargo_GrossKilos"), 'null'::jsonb) into v_current
      from public."Job_Cargo" cargo
      where cargo."JobCargo_ID" = v_field."AIInboxField_TargetRecordID" and cargo."JobCargo_JobID" = v_job."Job_ID"
      for update;
      if not found or v_current is distinct from v_field."AIInboxField_CurrentValueJSON" then
        raise exception 'The booking changed after this suggestion was prepared. Review it again before applying.' using errcode = '40001';
      end if;
      update public."Job_Cargo" cargo set
        "JobCargo_GrossKilos" = nullif(v_field."AIInboxField_ProposedValueJSON" #>> '{}','')::numeric,
        "JobCargo_UpdatedAt" = v_now, "JobCargo_UpdatedBy" = p_user_id
      where cargo."JobCargo_ID" = v_field."AIInboxField_TargetRecordID";
    else
      raise exception 'That suggested field is not allowlisted.' using errcode = '22023';
    end if;
    update public."AI_InboxSuggestedUpdateFields" set "AIInboxField_AppliedAt" = v_now
    where "AIInboxField_ID" = v_field."AIInboxField_ID";
    v_applied_ids := array_append(v_applied_ids, v_field."AIInboxField_ID");
  end loop;

  if cardinality(v_applied_ids) <> cardinality(p_selected_field_ids) then
    raise exception 'One or more selected changes are no longer available.' using errcode = '22023';
  end if;

  if v_suggestion."AIInboxSuggestion_StoredObjectID" is not null then
    select coalesce(max(document."JobDoc_VersionNo"), 0) + 1 into v_version
    from public."Job_Documents" document
    where document."JobDoc_JobID" = v_job."Job_ID"
      and lower(document."JobDoc_DocTypeCodeSnapshot") = lower(v_suggestion."AIInboxSuggestion_DocumentTypeCode")
      and not document."JobDoc_IsDeleted";
    update public."Job_Documents" set "JobDoc_IsCurrentVersion" = false, "JobDoc_UpdatedAt" = v_now, "JobDoc_UpdatedBy" = p_user_id
    where "JobDoc_JobID" = v_job."Job_ID"
      and lower("JobDoc_DocTypeCodeSnapshot") = lower(v_suggestion."AIInboxSuggestion_DocumentTypeCode")
      and "JobDoc_IsCurrentVersion" and not "JobDoc_IsDeleted";
    insert into public."Job_Documents" (
      "JobDoc_JobID", "JobDoc_DocTypeCodeSnapshot", "JobDoc_Title", "JobDoc_Description",
      "JobDoc_Status", "JobDoc_Source", "JobDoc_FileName", "JobDoc_FileMimeType",
      "JobDoc_FileSizeBytes", "JobDoc_VersionNo", "JobDoc_IsCurrentVersion",
      "JobDoc_ReceivedAt", "JobDoc_MetadataJSON", "JobDoc_CreatedBy", "JobDoc_UpdatedBy",
      "JobDoc_StoredObjectID"
    ) select
      v_job."Job_ID", v_suggestion."AIInboxSuggestion_DocumentTypeCode",
      case when v_suggestion."AIInboxSuggestion_DocumentTypeCode" = 'booking_confirmation' then 'Booking confirmation' else 'Commercial invoice' end,
      'Received through Inbox and applied from Suggested updates.', 'received', 'inbox_suggestion',
      v_suggestion."AIInboxSuggestion_SourceFileName", stored."DOCStoredObject_MimeType",
      stored."DOCStoredObject_FileSizeBytes", v_version, true, v_now,
      jsonb_build_object('suggestionId', p_suggestion_id, 'messageId', v_suggestion."AIInboxSuggestion_MessageID", 'attachmentId', v_suggestion."AIInboxSuggestion_AttachmentID"),
      p_user_id, p_user_id, stored."DOCStoredObject_ID"
    from public."DOC_StoredObjects" stored
    where stored."DOCStoredObject_ID" = v_suggestion."AIInboxSuggestion_StoredObjectID"
      and stored."DOCStoredObject_StatusCode" = 'active'
    returning "JobDoc_ID" into v_document_id;
    if v_document_id is null then raise exception 'The source document is no longer available.' using errcode = 'P0002'; end if;
    update public."Comm_MessageAttachments" set "CommAttachment_JobDocumentID" = v_document_id
    where "CommAttachment_ID" = v_suggestion."AIInboxSuggestion_AttachmentID";
  end if;

  update public."AI_InboxSuggestedUpdates" set
    "AIInboxSuggestion_StatusCode" = 'applied', "AIInboxSuggestion_AppliedAt" = v_now,
    "AIInboxSuggestion_AppliedByUserID" = p_user_id,
    "AIInboxSuggestion_AppliedJobDocumentID" = v_document_id,
    "AIInboxSuggestion_UpdatedAt" = v_now
  where "AIInboxSuggestion_ID" = p_suggestion_id;

  insert into public."AI_InboxSuggestionAudit" (
    "AIInboxAudit_SuggestionID", "AIInboxAudit_CompanyID", "AIInboxAudit_UserID",
    "AIInboxAudit_EventCode", "AIInboxAudit_DetailsJSON"
  ) values (p_suggestion_id, p_company_id, p_user_id, 'applied', jsonb_build_object('fieldIds', to_jsonb(v_applied_ids), 'bookingId', v_job."Job_ID", 'documentId', v_document_id));
  insert into public."AI_DexterActionAudit" (
    "AIDexterAudit_CompanyID", "AIDexterAudit_UserID", "AIDexterAudit_ActionCode",
    "AIDexterAudit_AccessMode", "AIDexterAudit_ArgumentsJSON", "AIDexterAudit_ResultJSON"
  ) values (
    p_company_id, p_user_id, 'apply_inbox_suggested_update', 'approve',
    jsonb_build_object('suggestion_id', p_suggestion_id, 'selected_field_ids', to_jsonb(v_applied_ids)),
    jsonb_build_object('status','applied','booking_id',v_job."Job_ID",'document_id',v_document_id)
  );
  insert into public."Comm_Notifications" (
    "CommNotif_UserID", "CommNotif_Title", "CommNotif_Body", "CommNotif_TargetTable",
    "CommNotif_TargetID", "CommNotif_LinkTypeCode", "CommNotif_MetadataJSON", "CommNotif_CreatedBy"
  ) values (
    p_user_id, 'Booking updated from Inbox',
    format('%s selected changes were applied to %s.', cardinality(v_applied_ids), coalesce(v_suggestion."AIInboxSuggestion_TargetLabel", 'the booking')),
    'AI_InboxSuggestedUpdates', p_suggestion_id, 'inbox_suggestion',
    jsonb_build_object('suggestion_id',p_suggestion_id,'booking_id',v_job."Job_ID",'document_id',v_document_id), p_user_id
  );
  return jsonb_build_object('status','applied','suggestionId',p_suggestion_id,'bookingId',v_job."Job_ID",'documentId',v_document_id,'appliedFieldIds',to_jsonb(v_applied_ids));
end;
$$;


ALTER FUNCTION "public"."multideck_inbox_apply_suggested_update"("p_company_id" "uuid", "p_user_id" "uuid", "p_suggestion_id" "uuid", "p_selected_field_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_inbox_attach_suggested_document"("p_company_id" "uuid", "p_user_id" "uuid", "p_suggestion_id" "uuid", "p_booking_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_suggestion public."AI_InboxSuggestedUpdates";
  v_job public."Job_Header";
  v_booking_label text;
  v_document_id uuid;
  v_existing_document_id uuid;
  v_version integer;
  v_now timestamptz := now();
begin
  if p_company_id is null or p_user_id is null or p_suggestion_id is null or p_booking_id is null then
    raise exception 'Choose a valid suggestion and booking.' using errcode = '22023';
  end if;
  if not public._multideck_dexter_has_permission(p_user_id, 'Email.Read')
     or not public._multideck_dexter_has_permission(p_user_id, 'Email.AIRead')
     or not public._multideck_dexter_has_permission(p_user_id, 'Bookings.Read')
     or not public._multideck_dexter_has_permission(p_user_id, 'Bookings.Write') then
    raise exception 'You do not have permission to add this document to a booking.' using errcode = '42501';
  end if;

  select suggestion.* into v_suggestion
  from public."AI_InboxSuggestedUpdates" suggestion
  where suggestion."AIInboxSuggestion_ID" = p_suggestion_id
    and suggestion."AIInboxSuggestion_CompanyID" = p_company_id
    and suggestion."AIInboxSuggestion_OwnerUserID" = p_user_id
  for update;
  if not found then raise exception 'That suggestion was not found.' using errcode = 'P0002'; end if;
  if v_suggestion."AIInboxSuggestion_StatusCode" = 'applied' then
    return jsonb_build_object(
      'status', 'already_applied', 'suggestionId', p_suggestion_id,
      'bookingId', v_suggestion."AIInboxSuggestion_TargetID",
      'documentId', v_suggestion."AIInboxSuggestion_AppliedJobDocumentID"
    );
  end if;
  if v_suggestion."AIInboxSuggestion_StatusCode" <> 'needs_match' then
    raise exception 'This document no longer needs a booking.' using errcode = '40001';
  end if;
  if v_suggestion."AIInboxSuggestion_StoredObjectID" is null then
    raise exception 'The source document is no longer available.' using errcode = 'P0002';
  end if;

  select job.* into v_job
  from public."Job_Header" job
  join public."cmp_Offices" office on office."Office_ID" = coalesce(job."Job_OrgOfficeID", job."Job_OfficeID")
  where job."Job_ID" = p_booking_id
    and office."Company_ID" = p_company_id
    and not coalesce(job."Job_IsDeleted", false)
  for update of job;
  if not found then raise exception 'That booking is no longer available.' using errcode = 'P0002'; end if;

  v_booking_label := coalesce(nullif(btrim(v_job."Job_BookingReference"), ''), 'JOB-' || v_job."Job_Number");

  select attachment."CommAttachment_JobDocumentID" into v_existing_document_id
  from public."Comm_MessageAttachments" attachment
  where attachment."CommAttachment_ID" = v_suggestion."AIInboxSuggestion_AttachmentID"
  for update;
  if v_existing_document_id is not null then
    raise exception 'This email attachment is already linked to a booking document.' using errcode = '40001';
  end if;

  select coalesce(max(document."JobDoc_VersionNo"), 0) + 1 into v_version
  from public."Job_Documents" document
  where document."JobDoc_JobID" = p_booking_id
    and lower(document."JobDoc_DocTypeCodeSnapshot") = lower(v_suggestion."AIInboxSuggestion_DocumentTypeCode")
    and not document."JobDoc_IsDeleted";

  update public."Job_Documents" set
    "JobDoc_IsCurrentVersion" = false,
    "JobDoc_UpdatedAt" = v_now,
    "JobDoc_UpdatedBy" = p_user_id
  where "JobDoc_JobID" = p_booking_id
    and lower("JobDoc_DocTypeCodeSnapshot") = lower(v_suggestion."AIInboxSuggestion_DocumentTypeCode")
    and "JobDoc_IsCurrentVersion"
    and not "JobDoc_IsDeleted";

  insert into public."Job_Documents" (
    "JobDoc_JobID", "JobDoc_DocTypeCodeSnapshot", "JobDoc_Title", "JobDoc_Description",
    "JobDoc_Status", "JobDoc_Source", "JobDoc_FileName", "JobDoc_FileMimeType",
    "JobDoc_FileSizeBytes", "JobDoc_VersionNo", "JobDoc_IsCurrentVersion",
    "JobDoc_ReceivedAt", "JobDoc_MetadataJSON", "JobDoc_CreatedBy", "JobDoc_UpdatedBy",
    "JobDoc_StoredObjectID"
  ) select
    p_booking_id, v_suggestion."AIInboxSuggestion_DocumentTypeCode",
    case when v_suggestion."AIInboxSuggestion_DocumentTypeCode" = 'booking_confirmation'
      then 'Booking confirmation' else 'Commercial invoice' end,
    'Received through Inbox and added to a booking after manual review.',
    'received', 'inbox_suggestion', v_suggestion."AIInboxSuggestion_SourceFileName",
    stored."DOCStoredObject_MimeType", stored."DOCStoredObject_FileSizeBytes",
    v_version, true, v_now,
    jsonb_build_object(
      'suggestionId', p_suggestion_id,
      'messageId', v_suggestion."AIInboxSuggestion_MessageID",
      'attachmentId', v_suggestion."AIInboxSuggestion_AttachmentID",
      'matchMethod', 'manual_selection'
    ),
    p_user_id, p_user_id, stored."DOCStoredObject_ID"
  from public."DOC_StoredObjects" stored
  where stored."DOCStoredObject_ID" = v_suggestion."AIInboxSuggestion_StoredObjectID"
    and stored."DOCStoredObject_StatusCode" = 'active'
  returning "JobDoc_ID" into v_document_id;
  if v_document_id is null then raise exception 'The source document is no longer available.' using errcode = 'P0002'; end if;

  update public."Comm_MessageAttachments" set "CommAttachment_JobDocumentID" = v_document_id
  where "CommAttachment_ID" = v_suggestion."AIInboxSuggestion_AttachmentID";

  update public."AI_InboxSuggestedUpdates" set
    "AIInboxSuggestion_TargetTypeCode" = 'booking',
    "AIInboxSuggestion_TargetID" = p_booking_id,
    "AIInboxSuggestion_TargetLabel" = v_booking_label,
    "AIInboxSuggestion_MatchMethodCode" = 'manual_selection',
    "AIInboxSuggestion_MatchConfidence" = null,
    "AIInboxSuggestion_StatusCode" = 'applied',
    "AIInboxSuggestion_AppliedAt" = v_now,
    "AIInboxSuggestion_AppliedByUserID" = p_user_id,
    "AIInboxSuggestion_AppliedJobDocumentID" = v_document_id,
    "AIInboxSuggestion_UpdatedAt" = v_now
  where "AIInboxSuggestion_ID" = p_suggestion_id;

  insert into public."AI_InboxSuggestionAudit" (
    "AIInboxAudit_SuggestionID", "AIInboxAudit_CompanyID", "AIInboxAudit_UserID",
    "AIInboxAudit_EventCode", "AIInboxAudit_DetailsJSON"
  ) values (
    p_suggestion_id, p_company_id, p_user_id, 'manually_attached',
    jsonb_build_object('bookingId', p_booking_id, 'documentId', v_document_id)
  );

  insert into public."AI_DexterActionAudit" (
    "AIDexterAudit_CompanyID", "AIDexterAudit_UserID", "AIDexterAudit_ActionCode",
    "AIDexterAudit_AccessMode", "AIDexterAudit_ArgumentsJSON", "AIDexterAudit_ResultJSON"
  ) values (
    p_company_id, p_user_id, 'attach_inbox_suggested_document', 'approve',
    jsonb_build_object('suggestion_id', p_suggestion_id, 'booking_id', p_booking_id),
    jsonb_build_object('status', 'applied', 'booking_id', p_booking_id, 'document_id', v_document_id)
  );

  insert into public."Comm_Notifications" (
    "CommNotif_UserID", "CommNotif_Title", "CommNotif_Body", "CommNotif_TargetTable",
    "CommNotif_TargetID", "CommNotif_LinkTypeCode", "CommNotif_MetadataJSON", "CommNotif_CreatedBy"
  ) values (
    p_user_id, 'Inbox document added to booking',
    format('%s was added to %s.', v_suggestion."AIInboxSuggestion_SourceFileName", v_booking_label),
    'AI_InboxSuggestedUpdates', p_suggestion_id, 'inbox_suggestion',
    jsonb_build_object('suggestion_id', p_suggestion_id, 'booking_id', p_booking_id, 'document_id', v_document_id),
    p_user_id
  );

  return jsonb_build_object(
    'status', 'applied', 'suggestionId', p_suggestion_id,
    'bookingId', p_booking_id, 'bookingLabel', v_booking_label,
    'documentId', v_document_id
  );
end;
$$;


ALTER FUNCTION "public"."multideck_inbox_attach_suggested_document"("p_company_id" "uuid", "p_user_id" "uuid", "p_suggestion_id" "uuid", "p_booking_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_inbox_claim_suggestion_jobs"("p_lease_token" "uuid", "p_limit" integer DEFAULT 2) RETURNS TABLE("job_id" "uuid", "company_id" "uuid", "owner_user_id" "uuid", "mailbox_id" "uuid", "message_id" "uuid", "attachment_id" "uuid", "classifier_version" "text", "extractor_version" "text")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  with candidates as (
    select job."AIInboxJob_ID"
    from public."AI_InboxProcessingJobs" job
    where (
      job."AIInboxJob_StatusCode" = 'queued'
      or (job."AIInboxJob_StatusCode" = 'processing' and job."AIInboxJob_LeaseExpiresAt" < now())
    )
      and job."AIInboxJob_AvailableAt" <= now()
      and job."AIInboxJob_AttemptCount" < 5
    order by job."AIInboxJob_CreatedAt"
    for update skip locked
    limit greatest(1, least(coalesce(p_limit, 2), 5))
  ), claimed as (
    update public."AI_InboxProcessingJobs" job set
      "AIInboxJob_StatusCode" = 'processing',
      "AIInboxJob_LeaseToken" = p_lease_token,
      "AIInboxJob_LeaseExpiresAt" = now() + interval '4 minutes',
      "AIInboxJob_AttemptCount" = job."AIInboxJob_AttemptCount" + 1,
      "AIInboxJob_StartedAt" = coalesce(job."AIInboxJob_StartedAt", now()),
      "AIInboxJob_UpdatedAt" = now()
    from candidates
    where job."AIInboxJob_ID" = candidates."AIInboxJob_ID"
    returning job.*
  )
  select
    claimed."AIInboxJob_ID", claimed."AIInboxJob_CompanyID", claimed."AIInboxJob_OwnerUserID",
    claimed."AIInboxJob_MailboxID", claimed."AIInboxJob_MessageID", claimed."AIInboxJob_AttachmentID",
    claimed."AIInboxJob_ClassifierVersion"::text, claimed."AIInboxJob_ExtractorVersion"::text
  from claimed;
$$;


ALTER FUNCTION "public"."multideck_inbox_claim_suggestion_jobs"("p_lease_token" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_inbox_complete_suggestion_job"("p_job_id" "uuid", "p_lease_token" "uuid", "p_suggestion" "jsonb", "p_fields" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_job public."AI_InboxProcessingJobs";
  v_suggestion_id uuid := nullif(p_suggestion->>'id', '')::uuid;
  v_status text := nullif(p_suggestion->>'status', '');
  v_target_id uuid := nullif(p_suggestion->>'targetId', '')::uuid;
  v_target_label text := nullif(p_suggestion->>'targetLabel', '');
  v_match_confidence numeric := nullif(p_suggestion->>'matchConfidence', '')::numeric;
  v_field_count integer := 0;
  v_now timestamptz := now();
begin
  if p_job_id is null or p_lease_token is null or v_suggestion_id is null
     or jsonb_typeof(coalesce(p_fields, '[]'::jsonb)) <> 'array' then
    raise exception 'The extracted Inbox suggestion is invalid.' using errcode = '22023';
  end if;

  select job.* into v_job
  from public."AI_InboxProcessingJobs" job
  where job."AIInboxJob_ID" = p_job_id
    and job."AIInboxJob_StatusCode" = 'processing'
    and job."AIInboxJob_LeaseToken" = p_lease_token
  for update;
  if not found then
    raise exception 'The Inbox suggestion job lease is no longer active.' using errcode = '40001';
  end if;

  if v_suggestion_id <> p_job_id
     or nullif(p_suggestion->>'companyId', '')::uuid <> v_job."AIInboxJob_CompanyID"
     or nullif(p_suggestion->>'ownerUserId', '')::uuid <> v_job."AIInboxJob_OwnerUserID"
     or nullif(p_suggestion->>'mailboxId', '')::uuid <> v_job."AIInboxJob_MailboxID"
     or nullif(p_suggestion->>'messageId', '')::uuid <> v_job."AIInboxJob_MessageID"
     or nullif(p_suggestion->>'attachmentId', '')::uuid <> v_job."AIInboxJob_AttachmentID" then
    raise exception 'The extracted Inbox suggestion does not match its source job.' using errcode = '22023';
  end if;

  insert into public."AI_InboxSuggestedUpdates" (
    "AIInboxSuggestion_ID", "AIInboxSuggestion_CompanyID", "AIInboxSuggestion_OwnerUserID",
    "AIInboxSuggestion_MailboxID", "AIInboxSuggestion_MessageID", "AIInboxSuggestion_AttachmentID",
    "AIInboxSuggestion_JobID", "AIInboxSuggestion_DocumentTypeCode", "AIInboxSuggestion_TargetTypeCode",
    "AIInboxSuggestion_TargetID", "AIInboxSuggestion_TargetLabel", "AIInboxSuggestion_MatchMethodCode",
    "AIInboxSuggestion_MatchConfidence", "AIInboxSuggestion_StatusCode", "AIInboxSuggestion_SourceFileName",
    "AIInboxSuggestion_Summary", "AIInboxSuggestion_ExtractedJSON", "AIInboxSuggestion_EvidenceJSON",
    "AIInboxSuggestion_ModelJSON", "AIInboxSuggestion_StoredObjectID",
    "AIInboxSuggestion_CreatedAt", "AIInboxSuggestion_UpdatedAt"
  ) values (
    v_suggestion_id, v_job."AIInboxJob_CompanyID", v_job."AIInboxJob_OwnerUserID",
    v_job."AIInboxJob_MailboxID", v_job."AIInboxJob_MessageID", v_job."AIInboxJob_AttachmentID",
    p_job_id, p_suggestion->>'documentType', nullif(p_suggestion->>'targetType', ''),
    v_target_id, v_target_label, nullif(p_suggestion->>'matchMethod', ''),
    v_match_confidence, v_status, left(p_suggestion->>'sourceFileName', 260),
    p_suggestion->>'summary', coalesce(p_suggestion->'extracted', '{}'::jsonb),
    coalesce(p_suggestion->'evidence', '{}'::jsonb), coalesce(p_suggestion->'model', '{}'::jsonb),
    nullif(p_suggestion->>'storedObjectId', '')::uuid, v_now, v_now
  );

  insert into public."AI_InboxSuggestedUpdateFields" (
    "AIInboxField_ID", "AIInboxField_SuggestionID", "AIInboxField_TargetRecordTypeCode",
    "AIInboxField_TargetRecordID", "AIInboxField_FieldCode", "AIInboxField_Label",
    "AIInboxField_CurrentValueJSON", "AIInboxField_ProposedValueJSON", "AIInboxField_EvidenceJSON",
    "AIInboxField_Confidence", "AIInboxField_IsSelectedByDefault", "AIInboxField_SortOrder"
  )
  select
    nullif(field->>'id', '')::uuid, v_suggestion_id, field->>'targetType',
    nullif(field->>'targetId', '')::uuid, field->>'code', field->>'label',
    coalesce(field->'current', 'null'::jsonb), coalesce(field->'proposed', 'null'::jsonb),
    jsonb_build_object('source', 'document_ocr', 'extractedValue', field->'proposed'),
    (field->>'confidence')::numeric, coalesce((field->>'selectedByDefault')::boolean, true),
    coalesce((field->>'sortOrder')::integer, 100)
  from jsonb_array_elements(coalesce(p_fields, '[]'::jsonb)) field;
  get diagnostics v_field_count = row_count;

  if v_status = 'ready' and v_field_count = 0 then
    raise exception 'A ready Inbox suggestion must include at least one reviewable field.' using errcode = '22023';
  end if;

  insert into public."AI_InboxSuggestionAudit" (
    "AIInboxAudit_SuggestionID", "AIInboxAudit_CompanyID", "AIInboxAudit_UserID",
    "AIInboxAudit_EventCode", "AIInboxAudit_DetailsJSON"
  ) values (
    v_suggestion_id, v_job."AIInboxJob_CompanyID", v_job."AIInboxJob_OwnerUserID", v_status,
    jsonb_build_object('documentType', p_suggestion->>'documentType', 'targetId', v_target_id, 'fieldCount', v_field_count)
  );

  if v_status in ('ready', 'needs_match') then
    insert into public."Comm_Notifications" (
      "CommNotif_UserID", "CommNotif_Title", "CommNotif_Body", "CommNotif_TargetTable",
      "CommNotif_TargetID", "CommNotif_LinkTypeCode", "CommNotif_MessageID",
      "CommNotif_MetadataJSON", "CommNotif_CreatedBy"
    ) values (
      v_job."AIInboxJob_OwnerUserID",
      case when v_status = 'ready' then 'Booking update ready to review' else 'Inbox document needs a match' end,
      case when v_status = 'ready'
        then format('%s changes were found for %s.', v_field_count, coalesce(v_target_label, 'the booking'))
        else format('Review %s in Suggested updates.', left(p_suggestion->>'sourceFileName', 260)) end,
      'AI_InboxSuggestedUpdates', v_suggestion_id, 'inbox_suggestion', v_job."AIInboxJob_MessageID",
      jsonb_build_object('suggestion_id', v_suggestion_id, 'booking_id', v_target_id, 'route', '/inbox?view=suggested'),
      v_job."AIInboxJob_OwnerUserID"
    );
  end if;

  update public."AI_InboxProcessingJobs" set
    "AIInboxJob_StatusCode" = 'completed',
    "AIInboxJob_DocumentTypeCode" = p_suggestion->>'documentType',
    "AIInboxJob_ClassificationMethod" = p_suggestion->>'classificationMethod',
    "AIInboxJob_ClassificationConfidence" = nullif(p_suggestion->>'classificationConfidence', '')::numeric,
    "AIInboxJob_FailureCode" = null, "AIInboxJob_FailureMessage" = null,
    "AIInboxJob_LeaseToken" = null, "AIInboxJob_LeaseExpiresAt" = null,
    "AIInboxJob_CompletedAt" = v_now, "AIInboxJob_UpdatedAt" = v_now
  where "AIInboxJob_ID" = p_job_id;

  return v_suggestion_id;
end;
$$;


ALTER FUNCTION "public"."multideck_inbox_complete_suggestion_job"("p_job_id" "uuid", "p_lease_token" "uuid", "p_suggestion" "jsonb", "p_fields" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_inbox_dismiss_suggested_update"("p_company_id" "uuid", "p_user_id" "uuid", "p_suggestion_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if not public._multideck_dexter_has_permission(p_user_id, 'Email.Read') then
    raise exception 'You do not have permission to dismiss this suggestion.' using errcode = '42501';
  end if;
  update public."AI_InboxSuggestedUpdates" set
    "AIInboxSuggestion_StatusCode" = 'dismissed', "AIInboxSuggestion_DismissedAt" = now(),
    "AIInboxSuggestion_DismissedByUserID" = p_user_id, "AIInboxSuggestion_UpdatedAt" = now()
  where "AIInboxSuggestion_ID" = p_suggestion_id
    and "AIInboxSuggestion_CompanyID" = p_company_id
    and "AIInboxSuggestion_OwnerUserID" = p_user_id
    and "AIInboxSuggestion_StatusCode" in ('needs_match','ready','no_changes');
  if not found then return false; end if;
  insert into public."AI_InboxSuggestionAudit" (
    "AIInboxAudit_SuggestionID", "AIInboxAudit_CompanyID", "AIInboxAudit_UserID", "AIInboxAudit_EventCode"
  ) values (p_suggestion_id, p_company_id, p_user_id, 'dismissed');
  return true;
end;
$$;


ALTER FUNCTION "public"."multideck_inbox_dismiss_suggested_update"("p_company_id" "uuid", "p_user_id" "uuid", "p_suggestion_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_inbox_enqueue_suggestions"("p_message_id" "uuid", "p_actor_user_id" "uuid", "p_classifier_version" "text" DEFAULT 'inbox-triage-v1'::"text", "p_extractor_version" "text" DEFAULT 'inbox-extract-v1'::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare v_inserted integer := 0;
begin
  insert into public."AI_InboxProcessingJobs" (
    "AIInboxJob_CompanyID", "AIInboxJob_OwnerUserID", "AIInboxJob_MailboxID",
    "AIInboxJob_MessageID", "AIInboxJob_AttachmentID",
    "AIInboxJob_ClassifierVersion", "AIInboxJob_ExtractorVersion"
  )
  select
    setting."AIInboxSetting_CompanyID", setting."AIInboxSetting_EnabledByUserID",
    mailbox."CommMailbox_ID", message."CommMessage_ID", attachment."CommAttachment_ID",
    left(btrim(p_classifier_version), 40), left(btrim(p_extractor_version), 40)
  from public."Comm_Messages" message
  join public."Comm_Mailboxes" mailbox
    on mailbox."CommMailbox_ID" = message."CommMessage_MailboxID"
  join public."AI_InboxSuggestionSettings" setting
    on setting."AIInboxSetting_MailboxID" = mailbox."CommMailbox_ID"
  join public."Comm_MessageAttachments" attachment
    on attachment."CommAttachment_MessageID" = message."CommMessage_ID"
  where message."CommMessage_ID" = p_message_id
    and setting."AIInboxSetting_IsEnabled"
    and setting."AIInboxSetting_EnabledAt" is not null
    and coalesce(
      message."CommMessage_ReceivedAt",
      message."CommMessage_MessageDate",
      message."CommMessage_CreatedAt"
    ) >= setting."AIInboxSetting_EnabledAt"
    and exists (
      select 1
      from public."cmp_Users" actor
      where actor."User_ID" = p_actor_user_id
        and actor."Company_ID" = setting."AIInboxSetting_CompanyID"
        and coalesce(actor."User_AccessStatus", 'active') = 'active'
    )
    and mailbox."CommMailbox_InboundEnabled"
    and not mailbox."CommMailbox_IsDeleted"
    and not message."CommMessage_IsDeleted"
    and not message."CommMessage_IsDraft"
    and not message."CommMessage_IsSpam"
    and not attachment."CommAttachment_IsInline"
    and lower(attachment."CommAttachment_FileName")
      ~ '\.(pdf|xlsx|xls|csv|docx|doc|odt|ods|png|jpe?g|webp)$'
    and not exists (
      select 1
      from public."Comm_MessageFolders" membership
      join public."Comm_MailFolders" folder
        on folder."CommMailFolder_ID" = membership."CommMessageFolder_FolderID"
      where membership."CommMessageFolder_MessageID" = message."CommMessage_ID"
        and folder."CommMailFolder_RoleCode" in ('drafts','spam','trash')
    )
    and exists (
      select 1
      from public."Comm_MessageFolders" membership
      join public."Comm_MailFolders" folder
        on folder."CommMailFolder_ID" = membership."CommMessageFolder_FolderID"
      where membership."CommMessageFolder_MessageID" = message."CommMessage_ID"
        and folder."CommMailFolder_RoleCode" = 'inbox'
    )
    and exists (
      select 1
      from public."Comm_MessageRecipients" recipient
      where recipient."CommRecipient_MessageID" = message."CommMessage_ID"
        and recipient."CommRecipient_RecipientTypeCode" in ('to','cc','bcc')
        and lower(recipient."CommRecipient_NormalizedAddress")
          = lower(mailbox."CommMailbox_NormalizedAddress")
    )
  on conflict (
    "AIInboxJob_AttachmentID",
    "AIInboxJob_ClassifierVersion",
    "AIInboxJob_ExtractorVersion"
  ) do nothing;

  get diagnostics v_inserted = row_count;
  return v_inserted;
end;
$_$;


ALTER FUNCTION "public"."multideck_inbox_enqueue_suggestions"("p_message_id" "uuid", "p_actor_user_id" "uuid", "p_classifier_version" "text", "p_extractor_version" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_inbox_search_bookings"("p_company_id" "uuid", "p_user_id" "uuid", "p_search" "text" DEFAULT NULL::"text", "p_take" integer DEFAULT 12) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_search text := nullif(btrim(p_search), '');
  v_take integer := greatest(1, least(coalesce(p_take, 12), 20));
  v_result jsonb;
begin
  if p_company_id is null or p_user_id is null
     or not public._multideck_dexter_has_permission(p_user_id, 'Bookings.Read') then
    raise exception 'You do not have permission to search bookings.' using errcode = '42501';
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'id', item."Job_ID",
    'reference', item."Booking_Reference",
    'customer', item."Customer_Name",
    'route', item."Route",
    'status', item."Status",
    'updatedAt', item."Updated_At"
  ) order by item.rank_order, item."Updated_At" desc nulls last, item."Booking_Reference"), '[]'::jsonb)
  into v_result
  from (
    select booking.*,
      case
        when v_search is not null and lower(booking."Booking_Reference") = lower(v_search) then 0
        when v_search is not null and lower(booking."Booking_Reference") like lower(v_search) || '%' then 1
        else 2
      end as rank_order
    from public."App_Live_Bookings" booking
    join public."Job_Header" job on job."Job_ID" = booking."Job_ID"
    join public."cmp_Offices" office on office."Office_ID" = coalesce(job."Job_OrgOfficeID", job."Job_OfficeID")
    where office."Company_ID" = p_company_id
      and not coalesce(job."Job_IsDeleted", false)
      and (
        v_search is null
        or strpos(lower(concat_ws(' ',
          booking."Booking_Reference", booking."Job_Reference", booking."Customer_Name",
          booking."Route", booking."Customer_Reference", booking."Carrier"
        )), lower(v_search)) > 0
      )
    order by rank_order, booking."Updated_At" desc nulls last, booking."Booking_Reference"
    limit v_take
  ) item;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."multideck_inbox_search_bookings"("p_company_id" "uuid", "p_user_id" "uuid", "p_search" "text", "p_take" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_index_dexter_email_body"("p_message_id" "uuid", "p_body_text" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  insert into public."AI_DexterEmailSearchDocuments" (
    "AIDexterEmailSearch_MessageID",
    "AIDexterEmailSearch_Document",
    "AIDexterEmailSearch_UpdatedAt"
  )
  select
    message."CommMessage_ID",
    setweight(
      to_tsvector(
        'simple'::regconfig,
        coalesce(message."CommMessage_Subject", '')
      ),
      'A'
    ) ||
    setweight(
      to_tsvector('simple'::regconfig, coalesce(participants.value, '')),
      'B'
    ) ||
    setweight(
      to_tsvector(
        'simple'::regconfig,
        left(
          coalesce(message."CommMessage_BodyPreview", '') || ' ' ||
          coalesce(p_body_text, message."CommMessage_BodyText", ''),
          512000
        )
      ),
      'C'
    ) ||
    setweight(
      to_tsvector('simple'::regconfig, coalesce(attachments.value, '')),
      'B'
    ),
    now()
  from public."Comm_Messages" message
  left join lateral (
    select string_agg(
      coalesce(recipient."CommRecipient_Address", '') || ' ' ||
      coalesce(recipient."CommRecipient_NormalizedAddress", '') || ' ' ||
      coalesce(recipient."CommRecipient_DisplayNameSnapshot", ''),
      ' '
    ) as value
    from public."Comm_MessageRecipients" recipient
    where recipient."CommRecipient_MessageID" = message."CommMessage_ID"
  ) participants on true
  left join lateral (
    select string_agg(
      regexp_replace(
        coalesce(attachment."CommAttachment_FileName", ''),
        '[^[:alnum:]@]+',
        ' ',
        'g'
      ),
      ' '
    ) as value
    from public."Comm_MessageAttachments" attachment
    where attachment."CommAttachment_MessageID" = message."CommMessage_ID"
      and not attachment."CommAttachment_IsInline"
  ) attachments on true
  where message."CommMessage_ID" = p_message_id
    and message."CommMessage_SourceTypeCode" = 'provider_sync'
  on conflict ("AIDexterEmailSearch_MessageID") do update
  set "AIDexterEmailSearch_Document" = excluded."AIDexterEmailSearch_Document",
      "AIDexterEmailSearch_UpdatedAt" = excluded."AIDexterEmailSearch_UpdatedAt";

  if not found then
    raise exception 'The provider email does not exist.' using errcode = '22023';
  end if;
end;
$$;


ALTER FUNCTION "public"."multideck_index_dexter_email_body"("p_message_id" "uuid", "p_body_text" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_lifecycle_note_recipient_authorised"("p_auth_user_id" "uuid", "p_subject_type" "text", "p_subject_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'booking_api', 'quote_api'
    AS $$
  select p_auth_user_id is not null and p_subject_id is not null and case lower(btrim(coalesce(p_subject_type, '')))
    when 'company' then
      quote_api.has_permission(p_auth_user_id, 'Customers.Read') and exists (
        select 1 from public."cmp_Users" actor
        where actor."Auth_User_ID" = p_auth_user_id and actor."User_AccessStatus" = 'active'
          and public.multideck_crm_company_can_access_account(actor."Company_ID", p_subject_id)
      )
    when 'quote' then
      quote_api.has_permission(p_auth_user_id, 'Quotes.Read')
      and exists (
        select 1
        from public."CusQuote_Header" quote
        join public."cmp_Offices" office
          on office."Office_ID" = coalesce(quote."CusQuoteHeader_OrgOfficeID", quote."OrgOffice_ID")
        join public."cmp_Users" recipient
          on recipient."Auth_User_ID" = p_auth_user_id
         and recipient."Company_ID" = office."Company_ID"
         and recipient."User_AccessStatus" = 'active'
        where quote."CusQuoteHeader_ID" = p_subject_id
          and not quote."CusQuoteHeader_IsDeleted"
      )
    when 'booking' then
      booking_api.has_permission(p_auth_user_id, 'Bookings.Read')
      and exists (
        select 1
        from public."Job_Header" job
        join public."cmp_Offices" office
          on office."Office_ID" = coalesce(job."Job_OrgOfficeID", job."Job_OfficeID")
        join public."cmp_Users" recipient
          on recipient."Auth_User_ID" = p_auth_user_id
         and recipient."Company_ID" = office."Company_ID"
         and recipient."User_AccessStatus" = 'active'
        where job."Job_ID" = p_subject_id
          and not job."Job_IsDeleted"
      )
    when 'customs' then booking_api.customs_access(p_auth_user_id, p_subject_id, false)
    else false
  end;
$$;


ALTER FUNCTION "public"."multideck_lifecycle_note_recipient_authorised"("p_auth_user_id" "uuid", "p_subject_type" "text", "p_subject_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_lifecycle_note_target_authorised"("p_auth_user_id" "uuid", "p_target_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'booking_api', 'quote_api'
    AS $$
  select p_auth_user_id is not null and p_target_id is not null and (
    (
      quote_api.has_permission(p_auth_user_id, 'Quotes.Read')
      and exists (
        select 1
        from public."CusQuote_Header" quote
        join public."cmp_Offices" office
          on office."Office_ID" = coalesce(quote."CusQuoteHeader_OrgOfficeID", quote."OrgOffice_ID")
        join public."cmp_Users" actor
          on actor."Auth_User_ID" = p_auth_user_id
         and actor."Company_ID" = office."Company_ID"
         and actor."User_AccessStatus" = 'active'
        where quote."CusQuoteHeader_ID" = p_target_id and not quote."CusQuoteHeader_IsDeleted"
      )
    ) or (
      booking_api.has_permission(p_auth_user_id, 'Bookings.Read')
      and exists (
        select 1
        from public."Job_Header" job
        join public."cmp_Offices" office
          on office."Office_ID" = coalesce(job."Job_OrgOfficeID", job."Job_OfficeID")
        join public."cmp_Users" actor
          on actor."Auth_User_ID" = p_auth_user_id
         and actor."Company_ID" = office."Company_ID"
         and actor."User_AccessStatus" = 'active'
        where job."Job_ID" = p_target_id and not job."Job_IsDeleted"
      )
    ) or public.multideck_lifecycle_note_recipient_authorised(p_auth_user_id, 'company', p_target_id) or booking_api.customs_access(p_auth_user_id, p_target_id, false)
  );
$$;


ALTER FUNCTION "public"."multideck_lifecycle_note_target_authorised"("p_auth_user_id" "uuid", "p_target_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_lifecycle_note_targets"("p_subject_type" "text", "p_subject_id" "uuid", "p_search" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 20) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth', 'booking_api', 'quote_api'
    AS $$
declare
  v_context record;
  v_search text := nullif(left(btrim(coalesce(p_search, '')), 160), '');
  v_limit integer := greatest(1, least(coalesce(p_limit, 20), 50));
  v_result jsonb;
begin
  select * into strict v_context
  from public._multideck_lifecycle_note_context(auth.uid(), p_subject_type, p_subject_id, false);

  with targets as (
    select
      'user'::text as target_type,
      workspace_user."User_ID" as target_id,
      coalesce(
        nullif(btrim(concat_ws(' ', workspace_user."User_Firstname", workspace_user."User_Lastname")), ''),
        workspace_user."User_Email"
      ) as label,
      nullif(btrim(workspace_user."User_JobTitle"), '') as detail,
      0 as target_order
    from public."cmp_Users" workspace_user
    where workspace_user."Company_ID" = v_context.company_id
      and workspace_user."User_AccessStatus" = 'active'
      and workspace_user."Auth_User_ID" is not null
      and public.multideck_lifecycle_note_recipient_authorised(
        workspace_user."Auth_User_ID", p_subject_type, p_subject_id
      )
    union all
    select
      'department'::text,
      department."Department_ID",
      department."Department_Name",
      'Department'::text,
      1
    from public."cmp_Departments" department
    where department."Company_ID" = v_context.company_id
      and department."Department_IsActive"
      and exists (
        select 1
        from public."cmp_Users_Departments" membership
        join public."cmp_Users" member on member."User_ID" = membership."User_ID"
        where membership."Department_ID" = department."Department_ID"
          and member."Company_ID" = v_context.company_id
          and member."User_AccessStatus" = 'active'
          and member."Auth_User_ID" is not null
          and public.multideck_lifecycle_note_recipient_authorised(
            member."Auth_User_ID", p_subject_type, p_subject_id
          )
      )
  ), filtered as (
    select *
    from targets
    where v_search is null
      or concat_ws(' ', label, detail) ilike '%' || v_search || '%'
    order by target_order, lower(label), target_id
    limit v_limit
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'type', target_type,
    'id', target_id,
    'label', label,
    'detail', detail
  ) order by target_order, lower(label), target_id), '[]'::jsonb)
  into v_result
  from filtered;

  return v_result;
exception
  when no_data_found then
    raise exception 'Your signed-in account is not linked to an active Multideck user.' using errcode = '42501';
end;
$$;


ALTER FUNCTION "public"."multideck_lifecycle_note_targets"("p_subject_type" "text", "p_subject_id" "uuid", "p_search" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_lifecycle_notes"("p_subject_type" "text", "p_subject_id" "uuid", "p_limit" integer DEFAULT 30, "p_before" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  with base as (
    select public._multideck_lifecycle_notes_base(p_subject_type, p_subject_id, p_limit, p_before) as value
  ), enriched as (
    select coalesce(jsonb_agg(
      case when note."LifecycleNote_DeletedAt" is not null then
        (item.value - 'body') || jsonb_build_object(
          'body', '',
          'updatedAt', note."LifecycleNote_UpdatedAt",
          'deletedAt', note."LifecycleNote_DeletedAt"
        )
      else item.value || jsonb_build_object(
        'updatedAt', note."LifecycleNote_UpdatedAt",
        'deletedAt', null
      ) end
      order by item.ordinality
    ), '[]'::jsonb) as notes
    from base
    cross join lateral jsonb_array_elements(coalesce(base.value->'notes', '[]'::jsonb))
      with ordinality as item(value, ordinality)
    join public."OPS_LifecycleNotes" note
      on note."LifecycleNote_ID" = (item.value->>'id')::uuid
  )
  select jsonb_set(base.value, '{notes}', enriched.notes, true)
  from base cross join enriched;
$$;


ALTER FUNCTION "public"."multideck_lifecycle_notes"("p_subject_type" "text", "p_subject_id" "uuid", "p_limit" integer, "p_before" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_other_active_admin_exists"("p_company_id" "uuid", "p_excluded_user_id" "uuid", "p_role_ids" "uuid"[]) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select exists (
    select 1
    from public."cmp_Users" workspace_user
    join public."cmp_Users_Roles" user_role
      on user_role."User_ID" = workspace_user."User_ID"
    where workspace_user."Company_ID" = p_company_id
      and workspace_user."User_AccessStatus" = 'active'
      and workspace_user."User_ID" <> p_excluded_user_id
      and user_role."sys_UserRole_ID" = any(coalesce(p_role_ids, array[]::uuid[]))
    limit 1
  );
$$;


ALTER FUNCTION "public"."multideck_other_active_admin_exists"("p_company_id" "uuid", "p_excluded_user_id" "uuid", "p_role_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."multideck_other_active_admin_exists"("p_company_id" "uuid", "p_excluded_user_id" "uuid", "p_role_ids" "uuid"[]) IS 'Returns whether another active user has one of the workspace administrator roles.';



CREATE OR REPLACE FUNCTION "public"."multideck_phone_call_claim_retries"("p_company_id" "uuid", "p_limit" integer DEFAULT 20, "p_lease_seconds" integer DEFAULT 120) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_result jsonb;
begin
  if p_company_id is null or p_limit < 1 or p_limit > 50
    or p_lease_seconds < 30 or p_lease_seconds > 600
  then
    raise exception 'Invalid phone-call retry claim.' using errcode = '22023';
  end if;
  with candidates as (
    select event."CommCallEvent_ID"
    from public."Comm_CallIngestionEvents" event
    where event."CommCallEvent_CompanyID" = p_company_id
      and event."CommCallEvent_SignatureVerified" = true
      and event."CommCallEvent_AttemptCount" < 8
      and (
        (event."CommCallEvent_ProviderCode" = '3cx' and event."CommCallEvent_EventType" = 'cdr')
        or (event."CommCallEvent_ProviderCode" = 'twilio' and event."CommCallEvent_EventType" like 'jenkar\_%' escape '\')
        or (event."CommCallEvent_ProviderCode" = 'twilio' and event."CommCallEvent_EventType" = 'call_status')
        or (event."CommCallEvent_ProviderCode" = 'elevenlabs' and event."CommCallEvent_EventType" <> 'conversation_initiation')
      )
      and (
        (event."CommCallEvent_StatusCode" = 'retryable'
          and coalesce(event."CommCallEvent_NextAttemptAt", now()) <= now())
        or (event."CommCallEvent_StatusCode" = 'received'
          and event."CommCallEvent_ReceivedAt" <= now() - interval '5 minutes')
        or (event."CommCallEvent_StatusCode" = 'processing'
          and event."CommCallEvent_LeaseExpiresAt" < now())
      )
    order by coalesce(event."CommCallEvent_NextAttemptAt", event."CommCallEvent_ReceivedAt")
    for update skip locked
    limit p_limit
  ), claimed as (
    update public."Comm_CallIngestionEvents" event
    set "CommCallEvent_StatusCode" = 'processing',
        "CommCallEvent_LeaseToken" = gen_random_uuid(),
        "CommCallEvent_LeaseExpiresAt" = now() + make_interval(secs => p_lease_seconds),
        "CommCallEvent_LastAttemptAt" = now()
    from candidates
    where event."CommCallEvent_ID" = candidates."CommCallEvent_ID"
    returning event.*
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'eventId', claimed."CommCallEvent_ID",
    'provider', claimed."CommCallEvent_ProviderCode",
    'eventType', claimed."CommCallEvent_EventType",
    'payload', claimed."CommCallEvent_RawPayloadJSON",
    'metadata', claimed."CommCallEvent_MetadataJSON",
    'leaseToken', claimed."CommCallEvent_LeaseToken",
    'attemptCount', claimed."CommCallEvent_AttemptCount"
  )), '[]'::jsonb) into v_result from claimed;
  return v_result;
end;
$$;


ALTER FUNCTION "public"."multideck_phone_call_claim_retries"("p_company_id" "uuid", "p_limit" integer, "p_lease_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_phone_call_configure_worker_schedules"() RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_endpoint text;
  v_worker_secret text;
  v_twilio_enabled boolean := false;
  v_elevenlabs_enabled boolean := false;
  v_3cx_xapi_enabled boolean := false;
  v_job_id bigint;
begin
  select secret.decrypted_secret
  into v_endpoint
  from vault.decrypted_secrets secret
  where secret.name = 'multideck_phone_calls_worker_endpoint'
  limit 1;

  select secret.decrypted_secret
  into v_worker_secret
  from vault.decrypted_secrets secret
  where secret.name = 'multideck_phone_calls_worker_secret'
  limit 1;

  if nullif(btrim(v_endpoint), '') is null
    or btrim(v_endpoint) !~ '^https://[a-z0-9]+\.supabase\.co/functions/v1/phone-calls$' then
    raise exception 'Phone calls worker endpoint is missing or is not a tenant Supabase Phone calls Function URL.'
      using errcode = '55000';
  end if;

  if nullif(btrim(v_worker_secret), '') is null or length(v_worker_secret) < 32 then
    raise exception 'Phone calls worker secret is missing or invalid.'
      using errcode = '55000';
  end if;

  select coalesce(lower(btrim(secret.decrypted_secret)) = 'true', false)
  into v_twilio_enabled
  from vault.decrypted_secrets secret
  where secret.name = 'multideck_phone_calls_twilio_sync_enabled'
  limit 1;

  select coalesce(lower(btrim(secret.decrypted_secret)) = 'true', false)
  into v_elevenlabs_enabled
  from vault.decrypted_secrets secret
  where secret.name = 'multideck_phone_calls_elevenlabs_sync_enabled'
  limit 1;

  select coalesce(lower(btrim(secret.decrypted_secret)) = 'true', false)
  into v_3cx_xapi_enabled
  from vault.decrypted_secrets secret
  where secret.name = 'multideck_phone_calls_3cx_xapi_sync_enabled'
  limit 1;

  for v_job_id in
    select job.jobid
    from cron.job job
    where job.jobname in (
      'multideck-phone-calls-twilio-sync',
      'multideck-phone-calls-elevenlabs-sync',
      'multideck-phone-calls-3cx-xapi-sync',
      'multideck-phone-calls-retry',
      'multideck-phone-calls-retention'
    )
  loop
    perform cron.unschedule(v_job_id);
  end loop;

  if coalesce(v_twilio_enabled, false) then
    perform cron.schedule(
      'multideck-phone-calls-twilio-sync',
      '* * * * *',
      $schedule$
      select net.http_post(
        url := (
          select btrim(secret.decrypted_secret)
          from vault.decrypted_secrets secret
          where secret.name = 'multideck_phone_calls_worker_endpoint'
          limit 1
        ) || '/sync/twilio',
        headers := jsonb_build_object(
          'Content-Type', 'application/json',
          'x-multideck-worker-secret', (
            select secret.decrypted_secret
            from vault.decrypted_secrets secret
            where secret.name = 'multideck_phone_calls_worker_secret'
            limit 1
          )
        ),
        body := jsonb_build_object('source', 'cron', 'requestedAt', now()),
        timeout_milliseconds := 55000
      );
      $schedule$
    );
  end if;

  if coalesce(v_elevenlabs_enabled, false) then
    perform cron.schedule(
      'multideck-phone-calls-elevenlabs-sync',
      '*/2 * * * *',
      $schedule$
      select net.http_post(
        url := (
          select btrim(secret.decrypted_secret)
          from vault.decrypted_secrets secret
          where secret.name = 'multideck_phone_calls_worker_endpoint'
          limit 1
        ) || '/sync/elevenlabs',
        headers := jsonb_build_object(
          'Content-Type', 'application/json',
          'x-multideck-worker-secret', (
            select secret.decrypted_secret
            from vault.decrypted_secrets secret
            where secret.name = 'multideck_phone_calls_worker_secret'
            limit 1
          )
        ),
        body := jsonb_build_object('source', 'cron', 'requestedAt', now()),
        timeout_milliseconds := 55000
      );
      $schedule$
    );
  end if;

  -- This readiness marker must remain absent/false until the XAPI credentials
  -- and the tenant-specific call-log filter semantics have been approved.
  if coalesce(v_3cx_xapi_enabled, false) then
    perform cron.schedule(
      'multideck-phone-calls-3cx-xapi-sync',
      '*/2 * * * *',
      $schedule$
      select net.http_post(
        url := (
          select btrim(secret.decrypted_secret)
          from vault.decrypted_secrets secret
          where secret.name = 'multideck_phone_calls_worker_endpoint'
          limit 1
        ) || '/sync/3cx-xapi',
        headers := jsonb_build_object(
          'Content-Type', 'application/json',
          'x-multideck-worker-secret', (
            select secret.decrypted_secret
            from vault.decrypted_secrets secret
            where secret.name = 'multideck_phone_calls_worker_secret'
            limit 1
          )
        ),
        body := jsonb_build_object('source', 'cron', 'requestedAt', now()),
        timeout_milliseconds := 55000
      );
      $schedule$
    );
  end if;

  perform cron.schedule(
    'multideck-phone-calls-retry',
    '* * * * *',
    $schedule$
      select net.http_post(
        url := (
          select btrim(secret.decrypted_secret)
          from vault.decrypted_secrets secret
          where secret.name = 'multideck_phone_calls_worker_endpoint'
          limit 1
        ) || '/maintenance/retry',
        headers := jsonb_build_object(
          'Content-Type', 'application/json',
          'x-multideck-worker-secret', (
            select secret.decrypted_secret
            from vault.decrypted_secrets secret
            where secret.name = 'multideck_phone_calls_worker_secret'
            limit 1
          )
        ),
        body := jsonb_build_object('source', 'cron', 'requestedAt', now()),
        timeout_milliseconds := 55000
      );
    $schedule$
  );

  perform cron.schedule(
    'multideck-phone-calls-retention',
    '17 2 * * *',
    $schedule$
      select net.http_post(
        url := (
          select btrim(secret.decrypted_secret)
          from vault.decrypted_secrets secret
          where secret.name = 'multideck_phone_calls_worker_endpoint'
          limit 1
        ) || '/maintenance/retention',
        headers := jsonb_build_object(
          'Content-Type', 'application/json',
          'x-multideck-worker-secret', (
            select secret.decrypted_secret
            from vault.decrypted_secrets secret
            where secret.name = 'multideck_phone_calls_worker_secret'
            limit 1
          )
        ),
        body := jsonb_build_object('source', 'cron', 'requestedAt', now()),
        timeout_milliseconds := 55000
      );
    $schedule$
  );

  return true;
end;
$_$;


ALTER FUNCTION "public"."multideck_phone_call_configure_worker_schedules"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."multideck_phone_call_configure_worker_schedules"() IS 'Idempotently configures tenant-local Phone calls workers after validating Vault configuration. 3CX XAPI polling is opt-in only after credentials and call-log scope are approved.';



CREATE OR REPLACE FUNCTION "public"."multideck_phone_call_dead_letter_unsupported_retries"("p_company_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_result jsonb;
begin
  with unsupported as (
    update public."Comm_CallIngestionEvents" event
    set "CommCallEvent_StatusCode" = 'dead_letter',
        "CommCallEvent_ProcessedAt" = now(),
        "CommCallEvent_NextAttemptAt" = null,
        "CommCallEvent_ErrorCode" = 'unsupported_replay_type',
        "CommCallEvent_ErrorMessage" = 'Stored event needs a provider-specific replay adapter; it was not marked complete.',
        "CommCallEvent_LeaseToken" = null,
        "CommCallEvent_LeaseExpiresAt" = null
    where event."CommCallEvent_CompanyID" = p_company_id
      and event."CommCallEvent_SignatureVerified" = true
      and event."CommCallEvent_StatusCode" in ('received', 'retryable')
      and (
        (event."CommCallEvent_StatusCode" = 'retryable'
          and coalesce(event."CommCallEvent_NextAttemptAt", now()) <= now())
        or (event."CommCallEvent_StatusCode" = 'received'
          and event."CommCallEvent_ReceivedAt" <= now() - interval '5 minutes')
      )
      and not (
        (event."CommCallEvent_ProviderCode" = '3cx' and event."CommCallEvent_EventType" = 'cdr')
        or (event."CommCallEvent_ProviderCode" = 'twilio' and event."CommCallEvent_EventType" like 'jenkar\_%' escape '\')
        or (event."CommCallEvent_ProviderCode" = 'twilio' and event."CommCallEvent_EventType" = 'call_status')
        or (event."CommCallEvent_ProviderCode" = 'elevenlabs' and event."CommCallEvent_EventType" <> 'conversation_initiation')
      )
    returning event."CommCallEvent_ProviderCode", event."CommCallEvent_EventType"
  )
  select jsonb_build_object(
    'count', count(*),
    'eventTypes', coalesce(jsonb_agg(distinct unsupported."CommCallEvent_ProviderCode" || ':' || unsupported."CommCallEvent_EventType"), '[]'::jsonb)
  ) into v_result from unsupported;
  return v_result;
end;
$$;


ALTER FUNCTION "public"."multideck_phone_call_dead_letter_unsupported_retries"("p_company_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_phone_call_finish_retry"("p_company_id" "uuid", "p_event_id" "uuid", "p_lease_token" "uuid", "p_status" "text", "p_error_code" "text" DEFAULT NULL::"text", "p_error_message" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_event public."Comm_CallIngestionEvents"%rowtype; v_attempts integer; v_status text;
begin
  if coalesce(p_status, '') not in ('complete', 'partial', 'retryable', 'terminal') then
    raise exception 'Invalid phone-call retry result.' using errcode = '22023';
  end if;
  select event.* into v_event
  from public."Comm_CallIngestionEvents" event
  where event."CommCallEvent_ID" = p_event_id
    and event."CommCallEvent_CompanyID" = p_company_id
  for update;
  if not found or v_event."CommCallEvent_StatusCode" <> 'processing'
    or v_event."CommCallEvent_LeaseToken" is distinct from p_lease_token
    or v_event."CommCallEvent_LeaseExpiresAt" is null
    or v_event."CommCallEvent_LeaseExpiresAt" <= now()
  then
    raise exception 'Phone-call retry lease is missing or expired.' using errcode = '42501';
  end if;
  v_attempts := coalesce(v_event."CommCallEvent_AttemptCount", 0) + 1;
  v_status := case when p_status = 'retryable' and v_attempts >= 8 then 'dead_letter' else p_status end;
  update public."Comm_CallIngestionEvents" event
  set "CommCallEvent_StatusCode" = v_status,
      "CommCallEvent_ProcessedAt" = case when v_status = 'retryable' then null else now() end,
      "CommCallEvent_AttemptCount" = v_attempts,
      "CommCallEvent_NextAttemptAt" = case when v_status = 'retryable'
        then now() + make_interval(secs => least(3600, 300 * (2 ^ least(v_attempts - 1, 4)))::integer)
        else null end,
      "CommCallEvent_ErrorCode" = nullif(left(coalesce(p_error_code, ''), 120), ''),
      "CommCallEvent_ErrorMessage" = nullif(left(coalesce(p_error_message, ''), 500), ''),
      "CommCallEvent_LeaseToken" = null,
      "CommCallEvent_LeaseExpiresAt" = null
  where event."CommCallEvent_ID" = p_event_id;
  return jsonb_build_object('eventId', p_event_id, 'status', v_status, 'attemptCount', v_attempts);
end;
$$;


ALTER FUNCTION "public"."multideck_phone_call_finish_retry"("p_company_id" "uuid", "p_event_id" "uuid", "p_lease_token" "uuid", "p_status" "text", "p_error_code" "text", "p_error_message" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_phone_call_mark_recording_purged"("p_company_id" "uuid", "p_call_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  update public."Comm_CallLogs" call
  set "CommCall_RecordingStorageBucket" = null,
      "CommCall_RecordingStoragePath" = null,
      "CommCall_RecordingStatusCode" = 'expired',
      "CommCall_MetadataJSON" = coalesce(call."CommCall_MetadataJSON", '{}'::jsonb)
        || jsonb_build_object('recordingPurgedAt', now()),
      "CommCall_UpdatedAt" = now()
  where call."CommCall_ID" = p_call_id
    and call."CommCall_CompanyID" = p_company_id
    and call."CommCall_RetentionUntil" is not null
    and call."CommCall_RetentionUntil" <= now()
    and call."CommCall_RecordingStatusCode" = 'purge_pending';

  return found;
end;
$$;


ALTER FUNCTION "public"."multideck_phone_call_mark_recording_purged"("p_company_id" "uuid", "p_call_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_phone_call_match_candidates"("p_company_id" "uuid", "p_user_id" "uuid", "p_call_id" "uuid", "p_take" integer DEFAULT 8) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'extensions'
    AS $$
declare
  v_call public."Comm_CallLogs"%rowtype;
  v_review_id uuid;
  v_name text;
  v_company text;
  v_phone text;
  v_result jsonb;
begin
  perform public._multideck_phone_assert_actor(p_company_id, p_user_id, 'CRM.PhoneCalls.Read');
  select * into v_call from public."Comm_CallLogs" call
  where call."CommCall_ID" = p_call_id and call."CommCall_CompanyID" = p_company_id;
  if not found then raise exception 'Phone call not found.' using errcode = 'P0002'; end if;

  insert into public."CRM_CallReviews" (
    "CRMCallReview_CommCallID", "CRMCallReview_CompanyID", "CRMCallReview_OwnerUserID",
    "CRMCallReview_CapturedCallerName", "CRMCallReview_CapturedCompanyName",
    "CRMCallReview_CreatedBy", "CRMCallReview_UpdatedBy"
  ) values (
    p_call_id, p_company_id, p_user_id,
    coalesce(nullif(btrim(v_call."CommCall_FromDisplayNameSnapshot"), ''), nullif(btrim(v_call."CommCall_ToDisplayNameSnapshot"), '')),
    null, p_user_id, p_user_id
  )
  on conflict ("CRMCallReview_CommCallID") do update
  set "CRMCallReview_CompanyID" = coalesce(public."CRM_CallReviews"."CRMCallReview_CompanyID", excluded."CRMCallReview_CompanyID")
  returning "CRMCallReview_ID", "CRMCallReview_CapturedCallerName", "CRMCallReview_CapturedCompanyName"
  into v_review_id, v_name, v_company;

  v_phone := public._multideck_phone_normalize(
    case when v_call."CommCall_DirectionCode" = 'outbound' then v_call."CommCall_ToNumber" else v_call."CommCall_FromNumber" end
  );

  delete from public."CRM_CallMatchCandidates"
  where "CRMCallMatch_CallReviewID" = v_review_id
    and "CRMCallMatch_StatusCode" = 'candidate';

  with accessible_company as (
    select account_id from public.multideck_crm_accessible_account_ids(p_company_id)
  ), candidates as (
    select
      'company'::text entity_type,
      organisation."Org_id" target_id,
      organisation."Org_Name"::text target_label,
      least(0.99, greatest(
        case when v_company is not null and public._multideck_phone_match_text(organisation."Org_Name") = public._multideck_phone_match_text(v_company) then 0.92 else 0 end,
        case when v_company is not null then extensions.similarity(
          public._multideck_phone_match_text(organisation."Org_Name"),
          public._multideck_phone_match_text(v_company)
        ) * 0.82 else 0 end,
        case when v_phone is not null and exists (
          select 1 from public."Comm_Identities" identity
          where identity."CommIdentity_OrgID" = organisation."Org_id"
            and identity."CommIdentity_ChannelCode" in ('phone', 'sms', 'whatsapp')
            and not identity."CommIdentity_IsDeleted"
            and public._multideck_phone_normalize(identity."CommIdentity_NormalizedAddress") = v_phone
        ) then 0.98 else 0 end
      ))::numeric(5,4) confidence,
      jsonb_build_object(
        'companyNameExact', v_company is not null and public._multideck_phone_match_text(organisation."Org_Name") = public._multideck_phone_match_text(v_company),
        'companyNameSimilarity', case when v_company is null then null else round(extensions.similarity(public._multideck_phone_match_text(organisation."Org_Name"), public._multideck_phone_match_text(v_company))::numeric, 4) end,
        'phoneExact', v_phone is not null and exists (
          select 1 from public."Comm_Identities" identity
          where identity."CommIdentity_OrgID" = organisation."Org_id"
            and not identity."CommIdentity_IsDeleted"
            and public._multideck_phone_normalize(identity."CommIdentity_NormalizedAddress") = v_phone
        )
      ) evidence
    from public."Org_Master" organisation
    join accessible_company accessible on accessible.account_id = organisation."Org_id"
    where v_company is not null or v_phone is not null

    union all

    select
      'contact'::text,
      contact."OrgContact_ID",
      coalesce(nullif(btrim(concat_ws(' ', contact."OrgContact_FirstName", contact."OrgContact_LastName")), ''), organisation."Org_Name")::text,
      least(0.99, greatest(
        case when v_phone is not null and exists (
          select 1 from public."Comm_Identities" identity
          where identity."CommIdentity_ContactID" = contact."OrgContact_ID"
            and not identity."CommIdentity_IsDeleted"
            and public._multideck_phone_normalize(identity."CommIdentity_NormalizedAddress") = v_phone
        ) then 0.99 else 0 end,
        case when v_name is not null then extensions.similarity(
          public._multideck_phone_match_text(concat_ws(' ', contact."OrgContact_FirstName", contact."OrgContact_LastName")),
          public._multideck_phone_match_text(v_name)
        ) * 0.86 else 0 end
      ))::numeric(5,4),
      jsonb_build_object(
        'nameSimilarity', case when v_name is null then null else round(extensions.similarity(public._multideck_phone_match_text(concat_ws(' ', contact."OrgContact_FirstName", contact."OrgContact_LastName")), public._multideck_phone_match_text(v_name))::numeric, 4) end,
        'phoneExact', v_phone is not null and exists (
          select 1 from public."Comm_Identities" identity
          where identity."CommIdentity_ContactID" = contact."OrgContact_ID"
            and not identity."CommIdentity_IsDeleted"
            and public._multideck_phone_normalize(identity."CommIdentity_NormalizedAddress") = v_phone
        ),
        'companyId', organisation."Org_id",
        'companyName', organisation."Org_Name"
      )
    from public."Org_Contacts" contact
    join accessible_company accessible on accessible.account_id = contact."Org_ID"
    join public."Org_Master" organisation on organisation."Org_id" = contact."Org_ID"
    where v_name is not null or v_phone is not null

    union all

    select
      'lead'::text,
      lead."CRMLead_ID",
      coalesce(nullif(btrim(lead."CRMLead_CompanyName"), ''), nullif(btrim(lead."CRMLead_PersonName"), ''), 'Unnamed lead')::text,
      least(0.99, greatest(
        case when v_phone is not null and public._multideck_phone_normalize(lead."CRMLead_Phone") = v_phone then 0.98 else 0 end,
        case when v_name is not null then extensions.similarity(public._multideck_phone_match_text(lead."CRMLead_PersonName"), public._multideck_phone_match_text(v_name)) * 0.82 else 0 end,
        case when v_company is not null then extensions.similarity(public._multideck_phone_match_text(lead."CRMLead_CompanyName"), public._multideck_phone_match_text(v_company)) * 0.78 else 0 end
      ))::numeric(5,4),
      jsonb_build_object(
        'phoneExact', v_phone is not null and public._multideck_phone_normalize(lead."CRMLead_Phone") = v_phone,
        'nameSimilarity', case when v_name is null then null else round(extensions.similarity(public._multideck_phone_match_text(lead."CRMLead_PersonName"), public._multideck_phone_match_text(v_name))::numeric, 4) end,
        'companySimilarity', case when v_company is null then null else round(extensions.similarity(public._multideck_phone_match_text(lead."CRMLead_CompanyName"), public._multideck_phone_match_text(v_company))::numeric, 4) end
      )
    from public."CRM_Leads" lead
    left join public."cmp_Users" owner on owner."User_ID" = lead."CRMLead_OwnerUserID"
    where not lead."CRMLead_IsDeleted"
      and lower(coalesce(lead."CRMLead_MetadataJSON" ->> 'isDemo', 'false')) <> 'true'
      and (owner."Company_ID" = p_company_id or lead."CRMLead_OrgID" in (select account_id from accessible_company))
      and (v_name is not null or v_company is not null or v_phone is not null)
  ), ranked as (
    select *, row_number() over (order by confidence desc, entity_type, target_label, target_id) rank
    from candidates where confidence >= 0.34
  ), inserted as (
    insert into public."CRM_CallMatchCandidates" (
      "CRMCallMatch_CompanyID", "CRMCallMatch_CallReviewID", "CRMCallMatch_EntityTypeCode",
      "CRMCallMatch_TargetID", "CRMCallMatch_TargetLabel", "CRMCallMatch_Confidence",
      "CRMCallMatch_Rank", "CRMCallMatch_AlgorithmVersion", "CRMCallMatch_EvidenceJSON"
    )
    select p_company_id, v_review_id, entity_type, target_id, left(target_label, 240), confidence,
      rank, 'phone-match-v1', evidence
    from ranked where rank <= greatest(1, least(coalesce(p_take, 8), 20))
    on conflict ("CRMCallMatch_CallReviewID", "CRMCallMatch_EntityTypeCode", "CRMCallMatch_TargetID")
    do update set
      "CRMCallMatch_TargetLabel" = excluded."CRMCallMatch_TargetLabel",
      "CRMCallMatch_Confidence" = excluded."CRMCallMatch_Confidence",
      "CRMCallMatch_Rank" = excluded."CRMCallMatch_Rank",
      "CRMCallMatch_AlgorithmVersion" = excluded."CRMCallMatch_AlgorithmVersion",
      "CRMCallMatch_EvidenceJSON" = excluded."CRMCallMatch_EvidenceJSON",
      "CRMCallMatch_StatusCode" = case when public."CRM_CallMatchCandidates"."CRMCallMatch_StatusCode" = 'selected' then 'selected' else 'candidate' end
    returning *
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', inserted."CRMCallMatch_ID",
    'entityType', inserted."CRMCallMatch_EntityTypeCode",
    'targetId', inserted."CRMCallMatch_TargetID",
    'label', inserted."CRMCallMatch_TargetLabel",
    'confidence', inserted."CRMCallMatch_Confidence",
    'rank', inserted."CRMCallMatch_Rank",
    'status', inserted."CRMCallMatch_StatusCode",
    'algorithmVersion', inserted."CRMCallMatch_AlgorithmVersion",
    'evidence', inserted."CRMCallMatch_EvidenceJSON"
  ) order by inserted."CRMCallMatch_Rank"), '[]'::jsonb)
  into v_result from inserted;

  update public."Comm_CallLogs"
  set "CommCall_MatchStatusCode" = case
        when jsonb_array_length(v_result) = 0 then 'unmatched'
        else 'review'
      end,
      "CommCall_UpdatedAt" = now()
  where "CommCall_ID" = p_call_id;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."multideck_phone_call_match_candidates"("p_company_id" "uuid", "p_user_id" "uuid", "p_call_id" "uuid", "p_take" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_phone_call_provider_sync_claim"("p_company_id" "uuid", "p_provider_code" "text", "p_source_key" "text", "p_lease_seconds" integer DEFAULT 90) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_provider text := lower(btrim(coalesce(p_provider_code, '')));
  v_source_key text := btrim(coalesce(p_source_key, ''));
  v_lease_token uuid := gen_random_uuid();
  v_now timestamptz := clock_timestamp();
  v_cursor public."Comm_CallProviderSyncCursors"%rowtype;
  v_active_until timestamptz;
begin
  if p_company_id is null then
    raise exception 'A company is required.' using errcode = '22023';
  end if;
  if v_provider not in ('elevenlabs', 'twilio', '3cx') then
    raise exception 'The provider is not supported.' using errcode = '22023';
  end if;
  if char_length(v_source_key) not between 1 and 300 then
    raise exception 'The provider source key is invalid.' using errcode = '22023';
  end if;
  if p_lease_seconds is null or p_lease_seconds not between 15 and 600 then
    raise exception 'The provider lease must be between 15 and 600 seconds.' using errcode = '22023';
  end if;
  if not exists (
    select 1
    from public."cmp_Company" company
    where company."Company_ID" = p_company_id
  ) then
    raise exception 'The company does not exist.' using errcode = '22023';
  end if;

  insert into public."Comm_CallProviderSyncCursors" as cursor (
    "CommCallSyncCursor_CompanyID",
    "CommCallSyncCursor_ProviderCode",
    "CommCallSyncCursor_SourceKey",
    "CommCallSyncCursor_LeaseToken",
    "CommCallSyncCursor_LeaseAcquiredAt",
    "CommCallSyncCursor_LeaseExpiresAt",
    "CommCallSyncCursor_LastAttemptAt",
    "CommCallSyncCursor_CreatedAt",
    "CommCallSyncCursor_UpdatedAt"
  ) values (
    p_company_id,
    v_provider,
    v_source_key,
    v_lease_token,
    v_now,
    v_now + make_interval(secs => p_lease_seconds),
    v_now,
    v_now,
    v_now
  )
  on conflict (
    "CommCallSyncCursor_CompanyID",
    "CommCallSyncCursor_ProviderCode",
    "CommCallSyncCursor_SourceKey"
  ) do update set
    "CommCallSyncCursor_LeaseToken" = excluded."CommCallSyncCursor_LeaseToken",
    "CommCallSyncCursor_LeaseAcquiredAt" = excluded."CommCallSyncCursor_LeaseAcquiredAt",
    "CommCallSyncCursor_LeaseExpiresAt" = excluded."CommCallSyncCursor_LeaseExpiresAt",
    "CommCallSyncCursor_LastAttemptAt" = excluded."CommCallSyncCursor_LastAttemptAt",
    "CommCallSyncCursor_UpdatedAt" = excluded."CommCallSyncCursor_UpdatedAt"
  where cursor."CommCallSyncCursor_CompanyID" = p_company_id
    and cursor."CommCallSyncCursor_ProviderCode" = v_provider
    and cursor."CommCallSyncCursor_SourceKey" = v_source_key
    and (
      cursor."CommCallSyncCursor_LeaseToken" is null
      or cursor."CommCallSyncCursor_LeaseExpiresAt" <= v_now
    )
  returning cursor.* into v_cursor;

  if v_cursor."CommCallSyncCursor_ID" is null then
    select cursor."CommCallSyncCursor_LeaseExpiresAt"
    into v_active_until
    from public."Comm_CallProviderSyncCursors" cursor
    where cursor."CommCallSyncCursor_CompanyID" = p_company_id
      and cursor."CommCallSyncCursor_ProviderCode" = v_provider
      and cursor."CommCallSyncCursor_SourceKey" = v_source_key;

    return jsonb_build_object(
      'claimed', false,
      'retryAt', v_active_until
    );
  end if;

  return jsonb_build_object(
    'claimed', true,
    'companyId', v_cursor."CommCallSyncCursor_CompanyID",
    'provider', v_cursor."CommCallSyncCursor_ProviderCode",
    'sourceKey', v_cursor."CommCallSyncCursor_SourceKey",
    'leaseToken', v_cursor."CommCallSyncCursor_LeaseToken",
    'leaseExpiresAt', v_cursor."CommCallSyncCursor_LeaseExpiresAt",
    'checkpoint', v_cursor."CommCallSyncCursor_CheckpointJSON"
  );
end;
$$;


ALTER FUNCTION "public"."multideck_phone_call_provider_sync_claim"("p_company_id" "uuid", "p_provider_code" "text", "p_source_key" "text", "p_lease_seconds" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."multideck_phone_call_provider_sync_claim"("p_company_id" "uuid", "p_provider_code" "text", "p_source_key" "text", "p_lease_seconds" integer) IS 'Atomically claims one company/provider/source cursor and returns its last committed checkpoint.';



CREATE OR REPLACE FUNCTION "public"."multideck_phone_call_provider_sync_commit"("p_company_id" "uuid", "p_provider_code" "text", "p_source_key" "text", "p_lease_token" "uuid", "p_checkpoint" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_provider text := lower(btrim(coalesce(p_provider_code, '')));
  v_source_key text := btrim(coalesce(p_source_key, ''));
  v_now timestamptz := clock_timestamp();
  v_checkpoint jsonb;
begin
  if p_company_id is null or p_lease_token is null then
    raise exception 'A company and lease token are required.' using errcode = '22023';
  end if;
  if v_provider not in ('elevenlabs', 'twilio', '3cx') then
    raise exception 'The provider is not supported.' using errcode = '22023';
  end if;
  if char_length(v_source_key) not between 1 and 300 then
    raise exception 'The provider source key is invalid.' using errcode = '22023';
  end if;
  if p_checkpoint is null
    or jsonb_typeof(p_checkpoint) <> 'object'
    or octet_length(p_checkpoint::text) > 8192
  then
    raise exception 'The provider checkpoint must be a bounded JSON object.' using errcode = '22023';
  end if;

  update public."Comm_CallProviderSyncCursors" cursor
  set
    "CommCallSyncCursor_CheckpointJSON" = p_checkpoint,
    "CommCallSyncCursor_CheckpointCommittedAt" = v_now,
    "CommCallSyncCursor_LeaseToken" = null,
    "CommCallSyncCursor_LeaseAcquiredAt" = null,
    "CommCallSyncCursor_LeaseExpiresAt" = null,
    "CommCallSyncCursor_LastSucceededAt" = v_now,
    "CommCallSyncCursor_ConsecutiveFailures" = 0,
    "CommCallSyncCursor_LastErrorCode" = null,
    "CommCallSyncCursor_LastErrorMessage" = null,
    "CommCallSyncCursor_UpdatedAt" = v_now
  where cursor."CommCallSyncCursor_CompanyID" = p_company_id
    and cursor."CommCallSyncCursor_ProviderCode" = v_provider
    and cursor."CommCallSyncCursor_SourceKey" = v_source_key
    and cursor."CommCallSyncCursor_LeaseToken" = p_lease_token
    and cursor."CommCallSyncCursor_LeaseExpiresAt" > v_now
  returning cursor."CommCallSyncCursor_CheckpointJSON" into v_checkpoint;

  if v_checkpoint is null then
    raise exception 'The provider lease is missing, expired, or no longer owned.' using errcode = '55000';
  end if;

  return jsonb_build_object(
    'committed', true,
    'companyId', p_company_id,
    'provider', v_provider,
    'sourceKey', v_source_key,
    'checkpoint', v_checkpoint,
    'committedAt', v_now
  );
end;
$$;


ALTER FUNCTION "public"."multideck_phone_call_provider_sync_commit"("p_company_id" "uuid", "p_provider_code" "text", "p_source_key" "text", "p_lease_token" "uuid", "p_checkpoint" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."multideck_phone_call_provider_sync_commit"("p_company_id" "uuid", "p_provider_code" "text", "p_source_key" "text", "p_lease_token" "uuid", "p_checkpoint" "jsonb") IS 'Commits a provider checkpoint only for the current unexpired lease holder.';



CREATE OR REPLACE FUNCTION "public"."multideck_phone_call_provider_sync_fail"("p_company_id" "uuid", "p_provider_code" "text", "p_source_key" "text", "p_lease_token" "uuid", "p_error_code" "text", "p_error_message" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_provider text := lower(btrim(coalesce(p_provider_code, '')));
  v_source_key text := btrim(coalesce(p_source_key, ''));
  v_error_code text := left(
    nullif(
      btrim(
        regexp_replace(
          lower(public._multideck_phone_call_redact_sync_error(
            coalesce(nullif(btrim(p_error_code), ''), 'provider_sync_failed')
          )),
          '[^a-z0-9._:-]+',
          '_',
          'g'
        ),
        '_'
      ),
      ''
    ),
    80
  );
  v_error_message text := public._multideck_phone_call_redact_sync_error(p_error_message);
  v_now timestamptz := clock_timestamp();
  v_checkpoint jsonb;
begin
  if p_company_id is null or p_lease_token is null then
    raise exception 'A company and lease token are required.' using errcode = '22023';
  end if;
  if v_provider not in ('elevenlabs', 'twilio', '3cx') then
    raise exception 'The provider is not supported.' using errcode = '22023';
  end if;
  if char_length(v_source_key) not between 1 and 300 then
    raise exception 'The provider source key is invalid.' using errcode = '22023';
  end if;
  v_error_code := coalesce(v_error_code, 'provider_sync_failed');

  update public."Comm_CallProviderSyncCursors" cursor
  set
    "CommCallSyncCursor_LeaseToken" = null,
    "CommCallSyncCursor_LeaseAcquiredAt" = null,
    "CommCallSyncCursor_LeaseExpiresAt" = null,
    "CommCallSyncCursor_LastFailedAt" = v_now,
    "CommCallSyncCursor_ConsecutiveFailures" = least(
      cursor."CommCallSyncCursor_ConsecutiveFailures" + 1,
      2147483647
    ),
    "CommCallSyncCursor_LastErrorCode" = v_error_code,
    "CommCallSyncCursor_LastErrorMessage" = v_error_message,
    "CommCallSyncCursor_UpdatedAt" = v_now
  where cursor."CommCallSyncCursor_CompanyID" = p_company_id
    and cursor."CommCallSyncCursor_ProviderCode" = v_provider
    and cursor."CommCallSyncCursor_SourceKey" = v_source_key
    and cursor."CommCallSyncCursor_LeaseToken" = p_lease_token
    and cursor."CommCallSyncCursor_LeaseExpiresAt" > v_now
  returning cursor."CommCallSyncCursor_CheckpointJSON" into v_checkpoint;

  if v_checkpoint is null then
    raise exception 'The provider lease is missing, expired, or no longer owned.' using errcode = '55000';
  end if;

  return jsonb_build_object(
    'failed', true,
    'companyId', p_company_id,
    'provider', v_provider,
    'sourceKey', v_source_key,
    'checkpoint', v_checkpoint,
    'errorCode', v_error_code,
    'errorMessage', v_error_message,
    'failedAt', v_now
  );
end;
$$;


ALTER FUNCTION "public"."multideck_phone_call_provider_sync_fail"("p_company_id" "uuid", "p_provider_code" "text", "p_source_key" "text", "p_lease_token" "uuid", "p_error_code" "text", "p_error_message" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."multideck_phone_call_provider_sync_fail"("p_company_id" "uuid", "p_provider_code" "text", "p_source_key" "text", "p_lease_token" "uuid", "p_error_code" "text", "p_error_message" "text") IS 'Releases the current lease after a failure, retaining the checkpoint and storing bounded redacted diagnostics.';



CREATE OR REPLACE FUNCTION "public"."multideck_phone_call_purge_expired"("p_company_id" "uuid", "p_limit" integer DEFAULT 100) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_call_ids uuid[];
  v_count integer;
begin
  select coalesce(array_agg(expired.call_id), '{}'::uuid[])
  into v_call_ids
  from (
    select call."CommCall_ID" as call_id
    from public."Comm_CallLogs" call
    where call."CommCall_CompanyID" = p_company_id
      and call."CommCall_RetentionUntil" is not null
      and call."CommCall_RetentionUntil" <= now()
      and (
        call."CommCall_TranscriptStatusCode" <> 'expired'
        or (
          call."CommCall_RecordingStoragePath" is not null
          and coalesce(call."CommCall_RecordingStatusCode", '') <> 'purge_pending'
        )
      )
    order by call."CommCall_RetentionUntil"
    limit greatest(1, least(coalesce(p_limit, 100), 500))
    for update skip locked
  ) expired;

  v_count := coalesce(cardinality(v_call_ids), 0);
  if v_count = 0 then return 0; end if;

  -- Provider events can otherwise retain the same phone, participant and
  -- transcript PII after the readable call content has expired. Segment event
  -- IDs are authoritative. Stable provider leg identifiers also cover Twilio
  -- status/screening and ElevenLabs personalisation events which have no
  -- transcript segment of their own. Preserve delivery IDs and hashes for
  -- idempotency, but remove the linked provider body and error text.
  update public."Comm_CallIngestionEvents" event
  set "CommCallEvent_RawPayloadJSON" = '{}'::jsonb,
      "CommCallEvent_ErrorMessage" = null,
      "CommCallEvent_MetadataJSON" = jsonb_build_object(
        'retentionExpired', true,
        'redactedAt', now()
      )
  where event."CommCallEvent_CompanyID" = p_company_id
    and (
      event."CommCallEvent_ID" in (
        select distinct segment."CommCallSeg_RawEventID"
        from public."Comm_CallTranscriptSegments" segment
        where segment."CommCallSeg_CallID" = any(v_call_ids)
          and segment."CommCallSeg_RawEventID" is not null
      )
      or exists (
      select 1
      from public."Comm_CallProviderLegs" leg
      where leg."CommCallLeg_CompanyID" = p_company_id
        and leg."CommCallLeg_CallID" = any(v_call_ids)
        and (
          (
            event."CommCallEvent_ProviderCode" = leg."CommCallLeg_ProviderCode"
            and event."CommCallEvent_SourceObjectID" = any(array_remove(array[
              leg."CommCallLeg_ProviderCallID",
              leg."CommCallLeg_ParentProviderCallID",
              leg."CommCallLeg_ProviderConversationID",
              leg."CommCallLeg_ProviderConferenceID",
              leg."CommCallLeg_ProviderHistoryID",
              leg."CommCallLeg_ProviderSegmentID"
            ], null))
          )
          or (
            event."CommCallEvent_ProviderCode" = 'elevenlabs'
            and event."CommCallEvent_EventType" = 'conversation_initiation'
            and leg."CommCallLeg_ProviderCode" = 'twilio'
            and event."CommCallEvent_SourceObjectID" = any(array_remove(array[
              leg."CommCallLeg_ProviderCallID",
              leg."CommCallLeg_ParentProviderCallID",
              leg."CommCallLeg_ProviderConferenceID"
            ], null))
          )
        )
      )
    );

  delete from public."Comm_CallActionItems" action_item
  where action_item."CommCallAction_CallID" = any(v_call_ids);

  delete from public."Comm_CallAIOutputs" ai_output
  where ai_output."CommCallAI_CallID" = any(v_call_ids);

  update public."CRM_CallActionCandidates" action
  set "CRMCallAction_Title" = 'Expired call suggestion',
      "CRMCallAction_Description" = null,
      "CRMCallAction_ConfidenceScore" = null,
      "CRMCallAction_DecisionReason" = null,
      "CRMCallAction_DecisionStatus" = 'expired',
      "CRMCallAction_ActionPayloadJSON" = '{}'::jsonb,
      "CRMCallAction_MetadataJSON" = jsonb_build_object('retentionExpired', true),
      "CRMCallAction_EditVersion" = "CRMCallAction_EditVersion" + 1,
      "CRMCallAction_UpdatedAt" = now()
  from public."CRM_CallReviews" review
  where action."CRMCallAction_CallReviewID" = review."CRMCallReview_ID"
    and review."CRMCallReview_CommCallID" = any(v_call_ids)
    and action."CRMCallAction_DecisionStatus" = 'pending'
    and action."CRMCallAction_MetadataJSON" @> '{"generated":true}'::jsonb;

  update public."CRM_CallReviews" review
  set "CRMCallReview_AISummary" = null,
      "CRMCallReview_AISentimentCode" = null,
      "CRMCallReview_AIUrgencyScore" = null,
      "CRMCallReview_MetadataJSON" = coalesce(review."CRMCallReview_MetadataJSON", '{}'::jsonb)
        || jsonb_build_object('retentionExpired', true, 'redactedAt', now()),
      "CRMCallReview_EditVersion" = "CRMCallReview_EditVersion" + 1,
      "CRMCallReview_UpdatedAt" = now()
  where review."CRMCallReview_CommCallID" = any(v_call_ids);

  delete from public."Comm_CallTranscriptSegments" segment
  where segment."CommCallSeg_CallID" = any(v_call_ids);

  update public."Comm_CallLogs" call
  set "CommCall_TranscriptText" = null,
      "CommCall_AISummary" = null,
      "CommCall_AIActionItemsJSON" = '[]'::jsonb,
      "CommCall_TranscriptStatusCode" = 'expired',
      -- Storage objects must be deleted with the Storage API. Do not orphan a
      -- recording by clearing its pointer before that separate job succeeds.
      "CommCall_RecordingStatusCode" = case
        when call."CommCall_RecordingStoragePath" is null then 'expired'
        else 'purge_pending'
      end,
      "CommCall_MetadataJSON" = coalesce(call."CommCall_MetadataJSON", '{}'::jsonb)
        || jsonb_build_object(
          'retentionExpiredAt', now(),
          'retentionPurgeVersion', 'phone-call-retention-v2'
        ),
      "CommCall_UpdatedAt" = now()
  where call."CommCall_ID" = any(v_call_ids);

  return v_count;
end;
$$;


ALTER FUNCTION "public"."multideck_phone_call_purge_expired"("p_company_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_phone_call_purge_expired_events"("p_company_id" "uuid", "p_limit" integer DEFAULT 100) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_event_ids uuid[];
  v_count integer;
begin
  if auth.role() <> 'service_role' then
    raise exception 'server_only' using errcode = '42501';
  end if;

  select coalesce(array_agg(expired.event_id), '{}'::uuid[])
  into v_event_ids
  from (
    select event."CommCallEvent_ID" as event_id
    from public."Comm_CallIngestionEvents" event
    where event."CommCallEvent_CompanyID" = p_company_id
      and event."CommCallEvent_RetentionUntil" is not null
      and event."CommCallEvent_RetentionUntil" <= now()
      and event."CommCallEvent_RawPayloadJSON" <> '{}'::jsonb
    order by event."CommCallEvent_RetentionUntil",
      event."CommCallEvent_ReceivedAt"
    limit greatest(1, least(coalesce(p_limit, 100), 500))
    for update skip locked
  ) expired;

  v_count := coalesce(cardinality(v_event_ids), 0);
  if v_count = 0 then return 0; end if;

  update public."Comm_CallIngestionEvents" event
  set "CommCallEvent_RawPayloadJSON" = '{}'::jsonb,
      "CommCallEvent_ErrorCode" = null,
      "CommCallEvent_ErrorMessage" = null,
      "CommCallEvent_NextAttemptAt" = null,
      "CommCallEvent_LeaseToken" = null,
      "CommCallEvent_LeaseExpiresAt" = null,
      "CommCallEvent_StatusCode" = case
        when event."CommCallEvent_StatusCode" in (
          'received', 'processing', 'partial', 'retryable'
        ) then 'terminal'
        else event."CommCallEvent_StatusCode"
      end,
      "CommCallEvent_ProcessedAt" = coalesce(
        event."CommCallEvent_ProcessedAt",
        now()
      ),
      "CommCallEvent_MetadataJSON" = jsonb_build_object(
        'retentionExpired', true,
        'retentionScope', 'raw_event',
        'redactedAt', now()
      )
  where event."CommCallEvent_CompanyID" = p_company_id
    and event."CommCallEvent_ID" = any(v_event_ids);

  return v_count;
end;
$$;


ALTER FUNCTION "public"."multideck_phone_call_purge_expired_events"("p_company_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_phone_call_record_consent_evidence"("p_company_id" "uuid", "p_call_id" "uuid", "p_raw_event_id" "uuid", "p_provider_code" "text", "p_ai_disclosure_status" "text" DEFAULT 'unknown'::"text", "p_recording_consent_status" "text" DEFAULT 'unknown'::"text", "p_transcription_consent_status" "text" DEFAULT 'unknown'::"text", "p_disclosure_version" "text" DEFAULT NULL::"text", "p_disclosed_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_source_fields" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_call public."Comm_CallLogs"%rowtype;
  v_disclosure text;
  v_recording text;
  v_transcription text;
  v_legacy text;
begin
  if coalesce(p_provider_code, '') not in ('elevenlabs', 'twilio', '3cx')
    or coalesce(p_ai_disclosure_status, '') not in ('unknown', 'disclosed', 'not_required')
    or coalesce(p_recording_consent_status, '') not in ('unknown', 'not_required', 'received', 'declined')
    or coalesce(p_transcription_consent_status, '') not in ('unknown', 'not_required', 'received', 'declined')
    or jsonb_typeof(coalesce(p_source_fields, '[]'::jsonb)) <> 'array'
  then
    raise exception 'Invalid phone-call consent evidence.' using errcode = '22023';
  end if;
  if p_ai_disclosure_status = 'unknown'
    and p_recording_consent_status = 'unknown'
    and p_transcription_consent_status = 'unknown'
    and nullif(btrim(p_disclosure_version), '') is null
    and p_disclosed_at is null
  then
    return jsonb_build_object('recorded', false, 'reason', 'no_explicit_evidence');
  end if;

  select call.* into v_call
  from public."Comm_CallLogs" call
  where call."CommCall_ID" = p_call_id
    and call."CommCall_CompanyID" = p_company_id
  for update;
  if not found then
    raise exception 'Phone call is outside this workspace.' using errcode = '42501';
  end if;
  if not exists (
    select 1
    from public."Comm_CallIngestionEvents" event
    where event."CommCallEvent_ID" = p_raw_event_id
      and event."CommCallEvent_CompanyID" = p_company_id
      and event."CommCallEvent_ProviderCode" = p_provider_code
      and event."CommCallEvent_SignatureVerified" = true
  ) then
    raise exception 'Consent evidence requires a verified provider event in this workspace.' using errcode = '42501';
  end if;

  insert into public."Comm_CallConsentEvidence" (
    "CommCallConsent_CompanyID", "CommCallConsent_CallID", "CommCallConsent_RawEventID",
    "CommCallConsent_ProviderCode", "CommCallConsent_AIDisclosureStatusCode",
    "CommCallConsent_RecordingStatusCode", "CommCallConsent_TranscriptionStatusCode",
    "CommCallConsent_DisclosureVersion", "CommCallConsent_DisclosedAt",
    "CommCallConsent_SourceFieldsJSON"
  ) values (
    p_company_id, p_call_id, p_raw_event_id, p_provider_code, p_ai_disclosure_status,
    p_recording_consent_status, p_transcription_consent_status,
    nullif(btrim(p_disclosure_version), ''), p_disclosed_at, coalesce(p_source_fields, '[]'::jsonb)
  ) on conflict ("CommCallConsent_RawEventID") do nothing;

  v_disclosure := public._multideck_phone_call_merge_fact(
    v_call."CommCall_AIDisclosureStatusCode", p_ai_disclosure_status
  );
  v_recording := public._multideck_phone_call_merge_fact(
    v_call."CommCall_RecordingConsentStatusCode", p_recording_consent_status
  );
  v_transcription := public._multideck_phone_call_merge_fact(
    v_call."CommCall_TranscriptionConsentStatusCode", p_transcription_consent_status
  );
  v_legacy := case
    when 'conflict' in (v_disclosure, v_recording, v_transcription) then 'conflict'
    when 'declined' in (v_recording, v_transcription) then 'declined'
    when v_recording in ('received', 'not_required')
      and v_transcription in ('received', 'not_required')
      and 'received' in (v_recording, v_transcription) then 'received'
    when v_recording = 'not_required' and v_transcription = 'not_required' then 'not_required'
    when v_recording <> 'unknown' or v_transcription <> 'unknown' then 'partial'
    when v_disclosure = 'disclosed' then 'disclosed'
    when v_disclosure = 'not_required' then 'not_required'
    else 'unknown'
  end;

  update public."Comm_CallLogs" call
  set "CommCall_AIDisclosureStatusCode" = v_disclosure,
      "CommCall_RecordingConsentStatusCode" = v_recording,
      "CommCall_TranscriptionConsentStatusCode" = v_transcription,
      "CommCall_ConsentStatusCode" = v_legacy,
      "CommCall_ConsentDisclosureVersion" = coalesce(
        nullif(btrim(p_disclosure_version), ''), call."CommCall_ConsentDisclosureVersion"
      ),
      "CommCall_ConsentDisclosedAt" = coalesce(
        p_disclosed_at, call."CommCall_ConsentDisclosedAt"
      ),
      "CommCall_ConsentSourceProviderCode" = p_provider_code,
      "CommCall_ConsentSourceEventID" = p_raw_event_id,
      "CommCall_ConsentEvidenceUpdatedAt" = now(),
      "CommCall_ConsentEvidenceJSON" = jsonb_build_object(
        'provider', p_provider_code,
        'sourceEventId', p_raw_event_id,
        'sourceFields', coalesce(p_source_fields, '[]'::jsonb)
      ),
      "CommCall_UpdatedAt" = now()
  where call."CommCall_ID" = p_call_id
    and call."CommCall_CompanyID" = p_company_id;

  return jsonb_build_object(
    'recorded', true,
    'aiDisclosureStatus', v_disclosure,
    'recordingConsentStatus', v_recording,
    'transcriptionConsentStatus', v_transcription,
    'legacyConsentStatus', v_legacy
  );
end;
$$;


ALTER FUNCTION "public"."multideck_phone_call_record_consent_evidence"("p_company_id" "uuid", "p_call_id" "uuid", "p_raw_event_id" "uuid", "p_provider_code" "text", "p_ai_disclosure_status" "text", "p_recording_consent_status" "text", "p_transcription_consent_status" "text", "p_disclosure_version" "text", "p_disclosed_at" timestamp with time zone, "p_source_fields" "jsonb") OWNER TO "postgres";


