CREATE OR REPLACE FUNCTION "public"."multideck_phone_call_review_match"("p_company_id" "uuid", "p_user_id" "uuid", "p_call_id" "uuid", "p_resolution" "text", "p_company_target_id" "uuid" DEFAULT NULL::"uuid", "p_contact_target_id" "uuid" DEFAULT NULL::"uuid", "p_lead_target_id" "uuid" DEFAULT NULL::"uuid", "p_expected_version" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_call public."Comm_CallLogs"%rowtype;
  v_review_id uuid;
  v_contact_org_id uuid;
  v_lead_org_id uuid;
  v_resolved_org_id uuid;
begin
  perform public._multideck_phone_assert_actor(
    p_company_id,
    p_user_id,
    'CRM.PhoneCalls.Review'
  );

  select *
  into v_call
  from public."Comm_CallLogs" call
  where call."CommCall_ID" = p_call_id
    and call."CommCall_CompanyID" = p_company_id
  for update;

  if not found then
    raise exception 'Phone call not found.' using errcode = 'P0002';
  end if;
  if p_expected_version is not null
    and v_call."CommCall_EditVersion" <> p_expected_version then
    raise exception 'PHONE_CALL_CONFLICT: Reload this call before saving.'
      using errcode = 'P0001';
  end if;
  if p_resolution not in ('link', 'unmatched') then
    raise exception 'Choose whether to link the caller or leave the call unmatched.'
      using errcode = '22023';
  end if;
  if p_resolution = 'link'
    and num_nonnulls(
      p_company_target_id,
      p_contact_target_id,
      p_lead_target_id
    ) = 0 then
    raise exception 'Choose a company, contact or lead to link.'
      using errcode = '22023';
  end if;
  if p_resolution = 'unmatched'
    and num_nonnulls(
      p_company_target_id,
      p_contact_target_id,
      p_lead_target_id
    ) > 0 then
    raise exception 'An unmatched call cannot keep a CRM link.'
      using errcode = '22023';
  end if;
  if p_contact_target_id is not null and p_lead_target_id is not null then
    raise exception 'Link the call to a contact or a lead, not both.'
      using errcode = '22023';
  end if;

  if p_company_target_id is not null
    and not public.multideck_crm_company_can_access_account(
      p_company_id,
      p_company_target_id
    ) then
    raise exception 'That company is outside this workspace.'
      using errcode = '42501';
  end if;

  if p_contact_target_id is not null then
    select contact."Org_ID"
    into v_contact_org_id
    from public."Org_Contacts" contact
    where contact."OrgContact_ID" = p_contact_target_id
      and public.multideck_crm_company_can_access_account(
        p_company_id,
        contact."Org_ID"
      );
    if not found then
      raise exception 'That contact is outside this workspace.'
        using errcode = '42501';
    end if;
  end if;

  if p_lead_target_id is not null then
    select lead."CRMLead_OrgID"
    into v_lead_org_id
    from public."CRM_Leads" lead
    left join public."cmp_Users" owner
      on owner."User_ID" = lead."CRMLead_OwnerUserID"
    where lead."CRMLead_ID" = p_lead_target_id
      and not lead."CRMLead_IsDeleted"
      and (
        owner."Company_ID" = p_company_id
        or public.multideck_crm_company_can_access_account(
          p_company_id,
          lead."CRMLead_OrgID"
        )
      );
    if not found then
      raise exception 'That lead is outside this workspace.'
        using errcode = '42501';
    end if;
    if v_lead_org_id is not null
      and not public.multideck_crm_company_can_access_account(
        p_company_id,
        v_lead_org_id
      ) then
      raise exception 'The company linked to that lead is outside this workspace.'
        using errcode = '42501';
    end if;
  end if;

  if p_company_target_id is not null
    and v_contact_org_id is not null
    and p_company_target_id <> v_contact_org_id then
    raise exception 'That contact does not belong to the selected company.'
      using errcode = '22023';
  end if;
  if p_company_target_id is not null
    and p_lead_target_id is not null
    and (
      v_lead_org_id is null
      or p_company_target_id <> v_lead_org_id
    ) then
    raise exception 'That lead is not linked to the selected company.'
      using errcode = '22023';
  end if;

  v_resolved_org_id := case
    when p_resolution = 'unmatched' then null
    else coalesce(v_contact_org_id, v_lead_org_id, p_company_target_id)
  end;

  update public."Comm_CallLogs"
  set "CommCall_MatchedOrgID" = v_resolved_org_id,
      "CommCall_MatchedContactID" = case
        when p_resolution = 'link' then p_contact_target_id
        else null
      end,
      "CommCall_MatchedLeadID" = case
        when p_resolution = 'link' then p_lead_target_id
        else null
      end,
      "CommCall_MatchStatusCode" = case
        when p_resolution = 'link' then 'matched'
        else 'unmatched'
      end,
      "CommCall_MatchMethodCode" = 'user_review',
      "CommCall_MatchConfidence" = case
        when p_resolution = 'link' then 1
        else null
      end,
      "CommCall_EditVersion" = "CommCall_EditVersion" + 1,
      "CommCall_UpdatedAt" = now(),
      "CommCall_UpdatedBy" = p_user_id
  where "CommCall_ID" = p_call_id
  returning * into v_call;

  select "CRMCallReview_ID"
  into v_review_id
  from public."CRM_CallReviews"
  where "CRMCallReview_CommCallID" = p_call_id;

  if v_review_id is not null then
    update public."CRM_CallReviews"
    set "CRMCallReview_EditVersion" = "CRMCallReview_EditVersion" + 1,
        "CRMCallReview_UpdatedAt" = now(),
        "CRMCallReview_UpdatedBy" = p_user_id
    where "CRMCallReview_ID" = v_review_id;

    update public."CRM_CallMatchCandidates"
    set "CRMCallMatch_StatusCode" = case
          when p_resolution = 'link'
            and "CRMCallMatch_TargetID" in (
              p_company_target_id,
              p_contact_target_id,
              p_lead_target_id
            ) then 'selected'
          else 'rejected'
        end,
        "CRMCallMatch_ReviewedAt" = now(),
        "CRMCallMatch_ReviewedBy" = p_user_id
    where "CRMCallMatch_CallReviewID" = v_review_id;
  end if;

  insert into public."Comm_CallAccessEvents" (
    "CommCallAccess_CompanyID",
    "CommCallAccess_CallID",
    "CommCallAccess_UserID",
    "CommCallAccess_AccessTypeCode",
    "CommCallAccess_MetadataJSON"
  ) values (
    p_company_id,
    p_call_id,
    p_user_id,
    'match_review',
    jsonb_build_object(
      'resolution', p_resolution,
      'companyId', v_resolved_org_id,
      'contactId', p_contact_target_id,
      'leadId', p_lead_target_id
    )
  );

  return jsonb_build_object(
    'id', v_call."CommCall_ID",
    'editVersion', v_call."CommCall_EditVersion",
    'matchStatus', v_call."CommCall_MatchStatusCode",
    'companyId', v_call."CommCall_MatchedOrgID",
    'contactId', v_call."CommCall_MatchedContactID",
    'leadId', v_call."CommCall_MatchedLeadID"
  );
end;
$$;


ALTER FUNCTION "public"."multideck_phone_call_review_match"("p_company_id" "uuid", "p_user_id" "uuid", "p_call_id" "uuid", "p_resolution" "text", "p_company_target_id" "uuid", "p_contact_target_id" "uuid", "p_lead_target_id" "uuid", "p_expected_version" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_phone_call_save_notes"("p_company_id" "uuid", "p_user_id" "uuid", "p_call_id" "uuid", "p_summary" "text", "p_meeting_notes" "text", "p_expected_version" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_review public."CRM_CallReviews"%rowtype;
begin
  perform public._multideck_phone_assert_actor(p_company_id, p_user_id, 'CRM.PhoneCalls.Review');
  select review.* into v_review
  from public."CRM_CallReviews" review
  join public."Comm_CallLogs" call on call."CommCall_ID" = review."CRMCallReview_CommCallID"
  where call."CommCall_ID" = p_call_id and call."CommCall_CompanyID" = p_company_id
  for update of review;
  if not found then raise exception 'Phone call review not found.' using errcode = 'P0002'; end if;
  if p_expected_version is not null and v_review."CRMCallReview_EditVersion" <> p_expected_version then
    raise exception 'PHONE_CALL_CONFLICT: Reload these notes before saving.' using errcode = 'P0001';
  end if;
  if length(coalesce(p_summary, '')) > 4000 or length(coalesce(p_meeting_notes, '')) > 12000 then
    raise exception 'The call notes are too long.' using errcode = '22023';
  end if;
  update public."CRM_CallReviews"
  set "CRMCallReview_UserApprovedSummary" = nullif(btrim(p_summary), ''),
      "CRMCallReview_MeetingNotes" = nullif(btrim(p_meeting_notes), ''),
      "CRMCallReview_EditVersion" = "CRMCallReview_EditVersion" + 1,
      "CRMCallReview_UpdatedAt" = now(),
      "CRMCallReview_UpdatedBy" = p_user_id
  where "CRMCallReview_ID" = v_review."CRMCallReview_ID"
  returning * into v_review;
  update public."Comm_CallLogs"
  set "CommCall_EditVersion" = "CommCall_EditVersion" + 1,
      "CommCall_UpdatedAt" = now(),
      "CommCall_UpdatedBy" = p_user_id
  where "CommCall_ID" = p_call_id;
  insert into public."Comm_CallAccessEvents" (
    "CommCallAccess_CompanyID", "CommCallAccess_CallID", "CommCallAccess_UserID", "CommCallAccess_AccessTypeCode"
  ) values (p_company_id, p_call_id, p_user_id, 'notes_update');
  return jsonb_build_object(
    'id', v_review."CRMCallReview_ID",
    'summary', v_review."CRMCallReview_UserApprovedSummary",
    'meetingNotes', v_review."CRMCallReview_MeetingNotes",
    'editVersion', v_review."CRMCallReview_EditVersion",
    'updatedAt', v_review."CRMCallReview_UpdatedAt"
  );
end;
$$;


ALTER FUNCTION "public"."multideck_phone_call_save_notes"("p_company_id" "uuid", "p_user_id" "uuid", "p_call_id" "uuid", "p_summary" "text", "p_meeting_notes" "text", "p_expected_version" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_public_contact_card"("p_slug" "text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select jsonb_build_object(
    'ContactCard_ID', card."ContactCard_ID",
    'ContactCard_Slug', card."ContactCard_Slug",
    'ContactCard_Label', card."ContactCard_Label",
    'ContactCard_Status', card."ContactCard_Status",
    'ContactCard_Person',
      (coalesce(card."ContactCard_Person", '{}'::jsonb) - 'phone' - 'website' - 'socialLinks')
      || jsonb_build_object(
        'phone', case when coalesce(card."ContactCard_ShowPhone", false) then coalesce(card."ContactCard_Person" ->> 'phone', '') else '' end,
        'website', case when coalesce(card."ContactCard_ShowWebsite", false) then coalesce(card."ContactCard_Person" ->> 'website', '') else '' end,
        'socialLinks', coalesce((
          select jsonb_agg(social_link.item order by social_link.position)
          from jsonb_array_elements(coalesce(card."ContactCard_Person" -> 'socialLinks', '[]'::jsonb))
            with ordinality as social_link(item, position)
          where social_link.item ->> 'enabled' = 'true'
            and (coalesce(card."ContactCard_ShowPhone", false) or lower(coalesce(social_link.item ->> 'kind', '')) not in ('phone', 'whatsapp'))
            and (coalesce(card."ContactCard_ShowWebsite", false) or lower(coalesce(social_link.item ->> 'kind', '')) <> 'website')
        ), '[]'::jsonb)
      ),
    'ContactCard_Branding', card."ContactCard_Branding",
    'ContactCard_TenantName', company."Company_Name",
    'ContactCard_ShowTenantName', card."ContactCard_ShowTenantName",
    'ContactCard_PublicHeading', card."ContactCard_PublicHeading",
    'ContactCard_PublicSubheading', card."ContactCard_PublicSubheading",
    'ContactCard_SubmitLabel', card."ContactCard_SubmitLabel",
    'ContactCard_ThanksHeading', card."ContactCard_ThanksHeading",
    'ContactCard_ThanksBody', card."ContactCard_ThanksBody",
    'ContactCard_PhoneField', card."ContactCard_PhoneField",
    'ContactCard_ShowPhone', card."ContactCard_ShowPhone",
    'ContactCard_ShowWebsite', card."ContactCard_ShowWebsite",
    'ContactCard_ConsentEnabled', card."ContactCard_ConsentEnabled",
    'ContactCard_ConsentCopy', card."ContactCard_ConsentCopy",
    'ContactCard_PrivacyUrl', card."ContactCard_PrivacyUrl",
    'ContactCard_CreatedAt', card."ContactCard_CreatedAt"
  )
  from public."CRM_ContactCards" card
  join public."cmp_Company" company on company."Company_ID" = card."Company_ID"
  where card."ContactCard_Slug" = lower(btrim(p_slug))
    and card."ContactCard_Status" = 'published'
    and card."ContactCard_DeletedAt" is null
  limit 1;
$$;


ALTER FUNCTION "public"."multideck_public_contact_card"("p_slug" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_quote_register_page"("p_search" "text" DEFAULT NULL::"text", "p_filter_query" "jsonb" DEFAULT NULL::"jsonb", "p_sort" "text" DEFAULT 'updatedAt'::"text", "p_sort_direction" "text" DEFAULT 'desc'::"text", "p_limit" integer DEFAULT 10, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_limit integer := greatest(1, least(coalesce(p_limit, 10), 50));
  v_offset integer := greatest(0, coalesce(p_offset, 0));
  v_search text := nullif(btrim(p_search), '');
  v_sort_direction text := case when lower(p_sort_direction) = 'asc' then 'asc' else 'desc' end;
  v_sort text := case when p_sort in (
    'reference', 'status', 'customer', 'origin', 'destination', 'estimatedDeparture', 'estimatedArrival',
    'transportTime', 'transportMode', 'equipmentLoad', 'pickup', 'delivery', 'routingVia', 'incoterms',
    'incotermsPlace', 'serviceLevel', 'shipmentType', 'carrier', 'supplier', 'salesOwner', 'operationsOwner',
    'quoteType', 'direction', 'customerPurchaseOrder', 'shipperReference', 'validity', 'estimatedQuote',
    'sellValue', 'estimatedProfit', 'estimatedCost', 'estimatedMargin', 'documentStatus', 'workflowStage',
    'priority', 'quoteSource', 'createdAt', 'updatedAt'
  ) then p_sort else 'updatedAt' end;
  v_result jsonb;
begin
  if auth.uid() is null then raise exception 'Authentication required.' using errcode = '42501'; end if;

  with base as materialized (
    select
      quote."CusQuoteHeader_ID",
      quote."Quote_Reference",
      quote."Quote_Status",
      quote."Quote_Status_Tone",
      quote."Customer_Name",
      quote."Origin",
      quote."Destination",
      quote."Estimated_Departure",
      quote."Estimated_Arrival",
      quote."Transport_Time",
      quote."Transport_Mode",
      quote."Equipment_Load",
      quote."Pickup",
      quote."Delivery",
      quote."Routing_Via",
      quote."Incoterms",
      quote."Incoterms_Place",
      quote."Service_Level",
      quote."Shipment_Type",
      quote."Carrier",
      quote."Supplier",
      quote."Sales_Owner",
      quote."Operations_Owner",
      quote."Quote_Type",
      quote."Direction",
      quote."Customer_Purchase_Order",
      quote."Shipper_Reference",
      quote."Validity",
      quote."Estimated_Quote",
      quote."Sell_Value",
      quote."Estimated_Profit",
      quote."Estimated_Cost",
      quote."Estimated_Margin",
      quote."Currency",
      quote."Document_Status",
      quote."Workflow_Stage",
      quote."Priority",
      quote."Priority_Tone",
      quote."Quote_Source",
      quote."Created_At",
      quote."Updated_At",
      concat_ws(' ',
        quote."Quote_Reference", quote."Quote_Status", quote."Customer_Name", quote."Origin", quote."Destination",
        quote."Estimated_Departure", quote."Estimated_Arrival", quote."Transport_Time", quote."Transport_Mode",
        quote."Equipment_Load", quote."Pickup", quote."Delivery", quote."Routing_Via", quote."Incoterms",
        quote."Incoterms_Place", quote."Service_Level", quote."Shipment_Type", quote."Carrier", quote."Supplier",
        quote."Sales_Owner", quote."Operations_Owner", quote."Quote_Type", quote."Direction",
        quote."Customer_Purchase_Order", quote."Shipper_Reference", quote."Validity", quote."Estimated_Quote",
        quote."Sell_Value", quote."Estimated_Profit", quote."Estimated_Cost", quote."Estimated_Margin", quote."Currency",
        quote."Document_Status", quote."Workflow_Stage", quote."Priority", quote."Quote_Source", quote."Created_At"
      ) as search_text,
      jsonb_build_object(
        'any', jsonb_build_array(
          quote."Quote_Reference", quote."Quote_Status", quote."Customer_Name", quote."Origin", quote."Destination",
          quote."Estimated_Departure", quote."Estimated_Arrival", quote."Transport_Time", quote."Transport_Mode",
          quote."Equipment_Load", quote."Pickup", quote."Delivery", quote."Routing_Via", quote."Incoterms",
          quote."Incoterms_Place", quote."Service_Level", quote."Shipment_Type", quote."Carrier", quote."Supplier",
          quote."Sales_Owner", quote."Operations_Owner", quote."Quote_Type", quote."Direction",
          quote."Customer_Purchase_Order", quote."Shipper_Reference", quote."Validity", quote."Estimated_Quote",
          quote."Sell_Value", quote."Estimated_Profit", quote."Estimated_Cost", quote."Estimated_Margin", quote."Currency",
          quote."Document_Status", quote."Workflow_Stage", quote."Priority", quote."Quote_Source", quote."Created_At"
        ),
        'reference', to_jsonb(quote."Quote_Reference"),
        'status', to_jsonb(quote."Quote_Status"),
        'customer', to_jsonb(quote."Customer_Name"),
        'origin', to_jsonb(quote."Origin"),
        'destination', to_jsonb(quote."Destination"),
        'estimatedDeparture', to_jsonb(quote."Estimated_Departure"),
        'estimatedArrival', to_jsonb(quote."Estimated_Arrival"),
        'transportTime', to_jsonb(quote."Transport_Time"),
        'transportMode', to_jsonb(quote."Transport_Mode"),
        'equipmentLoad', to_jsonb(quote."Equipment_Load"),
        'pickup', to_jsonb(quote."Pickup"),
        'delivery', to_jsonb(quote."Delivery"),
        'routingVia', to_jsonb(quote."Routing_Via"),
        'incoterms', to_jsonb(quote."Incoterms"),
        'incotermsPlace', to_jsonb(quote."Incoterms_Place"),
        'serviceLevel', to_jsonb(quote."Service_Level"),
        'shipmentType', to_jsonb(quote."Shipment_Type"),
        'carrier', to_jsonb(quote."Carrier"),
        'supplier', to_jsonb(quote."Supplier"),
        'salesOwner', to_jsonb(quote."Sales_Owner"),
        'operationsOwner', to_jsonb(quote."Operations_Owner"),
        'quoteType', to_jsonb(quote."Quote_Type"),
        'direction', to_jsonb(quote."Direction"),
        'customerPurchaseOrder', to_jsonb(quote."Customer_Purchase_Order"),
        'shipperReference', to_jsonb(quote."Shipper_Reference"),
        'validity', to_jsonb(quote."Validity"),
        'estimatedQuote', to_jsonb(quote."Estimated_Quote"),
        'sellValue', to_jsonb(quote."Sell_Value"),
        'estimatedProfit', to_jsonb(quote."Estimated_Profit"),
        'estimatedCost', to_jsonb(quote."Estimated_Cost"),
        'estimatedMargin', to_jsonb(quote."Estimated_Margin"),
        'documentStatus', to_jsonb(quote."Document_Status"),
        'workflowStage', to_jsonb(quote."Workflow_Stage"),
        'priority', to_jsonb(quote."Priority"),
        'quoteSource', to_jsonb(quote."Quote_Source")
      ) as filter_fields
    from public."App_Live_Quotes" quote
  ), filtered as materialized (
    select *
    from base
    where (v_search is null or strpos(lower(search_text), lower(v_search)) > 0)
      and (p_filter_query is null or public.multideck_register_filter_matches(filter_fields, p_filter_query))
  ), ranked as (
    select *, row_number() over (
      order by
        case when v_sort_direction = 'asc' then case v_sort
          when 'reference' then lower("Quote_Reference") when 'status' then lower("Quote_Status")
          when 'customer' then lower("Customer_Name") when 'origin' then lower("Origin") when 'destination' then lower("Destination")
          when 'transportTime' then lower("Transport_Time") when 'transportMode' then lower("Transport_Mode")
          when 'equipmentLoad' then lower("Equipment_Load") when 'pickup' then lower("Pickup") when 'delivery' then lower("Delivery")
          when 'routingVia' then lower("Routing_Via") when 'incoterms' then lower("Incoterms") when 'incotermsPlace' then lower("Incoterms_Place")
          when 'serviceLevel' then lower("Service_Level") when 'shipmentType' then lower("Shipment_Type") when 'carrier' then lower("Carrier")
          when 'supplier' then lower("Supplier") when 'salesOwner' then lower("Sales_Owner") when 'operationsOwner' then lower("Operations_Owner")
          when 'quoteType' then lower("Quote_Type") when 'direction' then lower("Direction")
          when 'customerPurchaseOrder' then lower("Customer_Purchase_Order") when 'shipperReference' then lower("Shipper_Reference")
          when 'validity' then lower("Validity") when 'estimatedQuote' then lower("Estimated_Quote")
          when 'documentStatus' then lower("Document_Status") when 'workflowStage' then lower("Workflow_Stage")
          when 'priority' then lower("Priority") when 'quoteSource' then lower("Quote_Source")
        end end asc nulls last,
        case when v_sort_direction = 'desc' then case v_sort
          when 'reference' then lower("Quote_Reference") when 'status' then lower("Quote_Status")
          when 'customer' then lower("Customer_Name") when 'origin' then lower("Origin") when 'destination' then lower("Destination")
          when 'transportTime' then lower("Transport_Time") when 'transportMode' then lower("Transport_Mode")
          when 'equipmentLoad' then lower("Equipment_Load") when 'pickup' then lower("Pickup") when 'delivery' then lower("Delivery")
          when 'routingVia' then lower("Routing_Via") when 'incoterms' then lower("Incoterms") when 'incotermsPlace' then lower("Incoterms_Place")
          when 'serviceLevel' then lower("Service_Level") when 'shipmentType' then lower("Shipment_Type") when 'carrier' then lower("Carrier")
          when 'supplier' then lower("Supplier") when 'salesOwner' then lower("Sales_Owner") when 'operationsOwner' then lower("Operations_Owner")
          when 'quoteType' then lower("Quote_Type") when 'direction' then lower("Direction")
          when 'customerPurchaseOrder' then lower("Customer_Purchase_Order") when 'shipperReference' then lower("Shipper_Reference")
          when 'validity' then lower("Validity") when 'estimatedQuote' then lower("Estimated_Quote")
          when 'documentStatus' then lower("Document_Status") when 'workflowStage' then lower("Workflow_Stage")
          when 'priority' then lower("Priority") when 'quoteSource' then lower("Quote_Source")
        end end desc nulls last,
        case when v_sort_direction = 'asc' then case v_sort
          when 'estimatedDeparture' then "Estimated_Departure"::timestamptz when 'estimatedArrival' then "Estimated_Arrival"::timestamptz
          when 'createdAt' then "Created_At" when 'updatedAt' then "Updated_At"
        end end asc nulls last,
        case when v_sort_direction = 'desc' then case v_sort
          when 'estimatedDeparture' then "Estimated_Departure"::timestamptz when 'estimatedArrival' then "Estimated_Arrival"::timestamptz
          when 'createdAt' then "Created_At" when 'updatedAt' then "Updated_At"
        end end desc nulls last,
        case when v_sort_direction = 'asc' then case v_sort
          when 'sellValue' then "Sell_Value" when 'estimatedProfit' then "Estimated_Profit"
          when 'estimatedCost' then "Estimated_Cost" when 'estimatedMargin' then "Estimated_Margin"
        end end asc nulls last,
        case when v_sort_direction = 'desc' then case v_sort
          when 'sellValue' then "Sell_Value" when 'estimatedProfit' then "Estimated_Profit"
          when 'estimatedCost' then "Estimated_Cost" when 'estimatedMargin' then "Estimated_Margin"
        end end desc nulls last,
        "Updated_At" desc, "Quote_Reference"
    ) as ordinal
    from filtered
  ), page as (
    select * from ranked where ordinal > v_offset and ordinal <= v_offset + v_limit
  )
  select jsonb_build_object(
    'rows', coalesce((select jsonb_agg(to_jsonb(item) - 'search_text' - 'filter_fields' - 'ordinal' order by item.ordinal) from page item), '[]'::jsonb),
    'total', (select count(*) from filtered),
    'availableTotal', (select count(*) from base)
  ) into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."multideck_quote_register_page"("p_search" "text", "p_filter_query" "jsonb", "p_sort" "text", "p_sort_direction" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."multideck_quote_register_page"("p_search" "text", "p_filter_query" "jsonb", "p_sort" "text", "p_sort_direction" "text", "p_limit" integer, "p_offset" integer) IS 'RLS-preserving, maximum-50-row Quotes register read with exact filtered total.';



CREATE OR REPLACE FUNCTION "public"."multideck_rates_quote_candidates"("p_company_id" "uuid", "p_mode" "text", "p_origin" "text", "p_destination" "text", "p_customer" "text", "p_today" "date" DEFAULT CURRENT_DATE, "p_limit" integer DEFAULT 100) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  with scoped as materialized (
    select contract."RATEContract_ID" as id, contract."RATEContract_CurrentVersionID" as current_version_id,
      contract."RATEContract_UpdatedAt" as updated_at,
      coalesce(version."RATEContractVer_SnapshotJSON"->>'mode', contract."RATEContract_MetadataJSON"->>'mode', 'fcl') as mode_code,
      coalesce(version."RATEContractVer_SnapshotJSON"->>'origin', contract."RATEContract_MetadataJSON"->>'origin', '') as origin,
      coalesce(version."RATEContractVer_SnapshotJSON"->>'destination', contract."RATEContract_MetadataJSON"->>'destination', '') as destination,
      coalesce(version."RATEContractVer_SnapshotJSON"->>'customer', contract."RATEContract_MetadataJSON"->>'customer', '') as customer
    from public."RATE_Contracts" contract
    left join public."RATE_ContractVersions" version on version."RATEContractVer_ID" = contract."RATEContract_CurrentVersionID"
    where contract."Company_ID" = p_company_id and not contract."RATEContract_IsDeleted"
      and contract."RATEContract_StatusCode" = 'active'
      and (contract."RATEContract_ValidTo" is null or contract."RATEContract_ValidTo" >= p_today)
  ), scored as materialized (
    select *,
      25
      + case when strpos(lower(coalesce(p_mode, '')), lower(mode_code)) > 0 or (lower(coalesce(p_mode, '')) = 'sea' and mode_code in ('lcl', 'fcl')) then 25 else 0 end
      + case when strpos(lower(coalesce(p_origin, '')), lower(origin)) > 0 or strpos(lower(origin), split_part(lower(coalesce(p_origin, '')), ' · ', 1)) > 0 then 20 else 0 end
      + case when strpos(lower(coalesce(p_destination, '')), lower(destination)) > 0 or strpos(lower(destination), split_part(lower(coalesce(p_destination, '')), ' · ', 1)) > 0 then 20 else 0 end
      + case when nullif(btrim(customer), '') is null or strpos(lower(coalesce(p_customer, '')), lower(customer)) > 0 then 10 else 0 end as match_score,
      array_remove(array[
        case when strpos(lower(coalesce(p_mode, '')), lower(mode_code)) > 0 or (lower(coalesce(p_mode, '')) = 'sea' and mode_code in ('lcl', 'fcl')) then 'mode' end,
        case when strpos(lower(coalesce(p_origin, '')), lower(origin)) > 0 or strpos(lower(origin), split_part(lower(coalesce(p_origin, '')), ' · ', 1)) > 0 then 'origin' end,
        case when strpos(lower(coalesce(p_destination, '')), lower(destination)) > 0 or strpos(lower(destination), split_part(lower(coalesce(p_destination, '')), ' · ', 1)) > 0 then 'destination' end,
        case when nullif(btrim(customer), '') is null or strpos(lower(coalesce(p_customer, '')), lower(customer)) > 0 then case when nullif(btrim(customer), '') is null then 'eligible customers' else 'customer' end end
      ], null) as match_reasons
    from scoped
  ), candidates as materialized (
    select * from scored where match_score >= 60
    order by match_score desc, updated_at desc, id
    limit greatest(1, least(coalesce(p_limit, 100), 100))
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'contract', to_jsonb(contract),
    'version', case when version."RATEContractVer_ID" is null then null else to_jsonb(version) end,
    'matchScore', candidates.match_score,
    'matchReasons', to_jsonb(candidates.match_reasons)
  ) order by candidates.match_score desc, candidates.updated_at desc, candidates.id), '[]'::jsonb)
  from candidates
  join public."RATE_Contracts" contract on contract."RATEContract_ID" = candidates.id
  left join public."RATE_ContractVersions" version on version."RATEContractVer_ID" = candidates.current_version_id
$$;


ALTER FUNCTION "public"."multideck_rates_quote_candidates"("p_company_id" "uuid", "p_mode" "text", "p_origin" "text", "p_destination" "text", "p_customer" "text", "p_today" "date", "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."multideck_rates_quote_candidates"("p_company_id" "uuid", "p_mode" "text", "p_origin" "text", "p_destination" "text", "p_customer" "text", "p_today" "date", "p_limit" integer) IS 'Service-role-only company-scoped quote matching with deterministic scoring and at most 100 eligible rate candidates.';



CREATE OR REPLACE FUNCTION "public"."multideck_rates_quote_picker"("p_company_id" "uuid", "p_limit" integer DEFAULT 100) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'CusQuoteHeader_ID', quote."CusQuoteHeader_ID", 'Quote_Reference', 'Q-' || quote."CusQuoteHeader_Number",
    'Customer_Name', customer."Org_Name", 'Origin', coalesce(quote."CusQuoteHeader_OriginExtra", ''),
    'Destination', coalesce(quote."CusQuoteHeader_DestinationExtra", ''),
    'Transport_Mode', initcap(coalesce(quote."CusQuoteHeader_ModeCode", '')),
    'Equipment_Load', coalesce(quote."CusQuoteHeader_ShipmentTypeCode", ''),
    'Currency', coalesce(quote."CusQuoteHeader_CurrencyCode", 'GBP')
  ) order by coalesce(quote."CusQuoteHeader_LastEditedDate", quote."CusQuoteHeader_CreatedDate") desc, quote."CusQuoteHeader_ID"), '[]'::jsonb)
  from (
    select source.* from public."CusQuote_Header" source
    join public."cmp_Offices" office on office."Office_ID" = coalesce(source."CusQuoteHeader_OrgOfficeID", source."OrgOffice_ID")
    where office."Company_ID" = p_company_id and not source."CusQuoteHeader_IsDeleted"
    order by coalesce(source."CusQuoteHeader_LastEditedDate", source."CusQuoteHeader_CreatedDate") desc, source."CusQuoteHeader_ID"
    limit greatest(1, least(coalesce(p_limit, 100), 100))
  ) quote
  join public."Org_Master" customer on customer."Org_id" = quote."CusQuoteHeader_CustomerID"
$$;


ALTER FUNCTION "public"."multideck_rates_quote_picker"("p_company_id" "uuid", "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."multideck_rates_quote_picker"("p_company_id" "uuid", "p_limit" integer) IS 'Service-role-only company-scoped quote picker capped at 100 recent quotes.';



CREATE OR REPLACE FUNCTION "public"."multideck_rates_register_page"("p_company_id" "uuid", "p_scope" "text", "p_search" "text" DEFAULT NULL::"text", "p_mode" "text" DEFAULT NULL::"text", "p_tariff_type" "text" DEFAULT NULL::"text", "p_expiry" "text" DEFAULT NULL::"text", "p_sort" "text" DEFAULT 'name'::"text", "p_sort_direction" "text" DEFAULT 'asc'::"text", "p_today" "date" DEFAULT CURRENT_DATE, "p_limit" integer DEFAULT 20, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  v_scope text := lower(coalesce(nullif(btrim(p_scope), ''), ''));
  v_search text := nullif(btrim(p_search), '');
  v_mode text := lower(nullif(btrim(p_mode), ''));
  v_tariff_type text := lower(nullif(btrim(p_tariff_type), ''));
  v_expiry text := lower(nullif(btrim(p_expiry), ''));
  v_sort text := coalesce(nullif(btrim(p_sort), ''), 'name');
  v_sort_direction text := lower(coalesce(nullif(btrim(p_sort_direction), ''), 'asc'));
  v_limit integer := greatest(1, least(coalesce(p_limit, 20), 50));
  v_offset integer := greatest(0, coalesce(p_offset, 0));
  v_result jsonb;
begin
  if p_company_id is null then raise exception 'Company is required.' using errcode = '22023'; end if;
  if v_scope not in ('contracts', 'tariffs') then raise exception 'Choose a valid rate scope.' using errcode = '22023'; end if;
  if v_mode is not null and v_mode not in ('lcl', 'fcl', 'air', 'road') then raise exception 'Choose a valid rate mode.' using errcode = '22023'; end if;
  if v_tariff_type is not null and v_tariff_type not in ('cost_tariff', 'sales_tariff') then raise exception 'Choose a valid tariff type.' using errcode = '22023'; end if;
  if v_expiry is not null and v_expiry not in ('expired', '7', '30', 'active') then raise exception 'Choose a valid expiry filter.' using errcode = '22023'; end if;
  if v_sort_direction not in ('asc', 'desc') then raise exception 'Choose a valid sort direction.' using errcode = '22023'; end if;
  if v_sort not in ('name', 'type', 'mode', 'route', 'carrier', 'validity', 'buy', 'version', 'status', 'schedule', 'eligibility', 'sell') then
    raise exception 'Choose a valid rate sort.' using errcode = '22023';
  end if;

  with scoped as materialized (
    select
      contract."RATEContract_ID" as id,
      contract."RATEContract_CurrentVersionID" as current_version_id,
      contract."RATEContract_Code"::text as code,
      contract."RATEContract_Name"::text as name,
      contract."RATEContract_TypeCode"::text as type_code,
      contract."RATEContract_StatusCode"::text as status_code,
      contract."RATEContract_ValidTo" as valid_to,
      contract."RATEContract_UpdatedAt" as updated_at,
      coalesce(version."RATEContractVer_SnapshotJSON"->>'mode', contract."RATEContract_MetadataJSON"->>'mode', 'fcl') as mode_code,
      coalesce(version."RATEContractVer_SnapshotJSON"->>'carrier', contract."RATEContract_MetadataJSON"->>'carrier', '') as carrier,
      coalesce(version."RATEContractVer_SnapshotJSON"->>'supplier', contract."RATEContract_MetadataJSON"->>'supplier', '') as supplier,
      coalesce(version."RATEContractVer_SnapshotJSON"->>'customer', contract."RATEContract_MetadataJSON"->>'customer', '') as customer,
      coalesce(version."RATEContractVer_SnapshotJSON"->>'origin', contract."RATEContract_MetadataJSON"->>'origin', '') as origin,
      coalesce(version."RATEContractVer_SnapshotJSON"->>'destination', contract."RATEContract_MetadataJSON"->>'destination', '') as destination,
      coalesce(version."RATEContractVer_SnapshotJSON"->>'cargo', contract."RATEContract_MetadataJSON"->>'cargo', '') as cargo,
      coalesce(version."RATEContractVer_SnapshotJSON"->>'schedule', contract."RATEContract_MetadataJSON"->>'schedule', 'ad_hoc') as schedule_code,
      coalesce(version."RATEContractVer_VersionNo", 1) as version_no,
      case when coalesce(version."RATEContractVer_SnapshotJSON"->>'buyTotal', contract."RATEContract_MetadataJSON"->>'buyTotal', '') ~ '^[0-9]+(\.[0-9]+)?$'
        then coalesce(version."RATEContractVer_SnapshotJSON"->>'buyTotal', contract."RATEContract_MetadataJSON"->>'buyTotal')::numeric else 0 end as buy_total,
      case when coalesce(version."RATEContractVer_SnapshotJSON"->>'sellTotal', contract."RATEContract_MetadataJSON"->>'sellTotal', '') ~ '^[0-9]+(\.[0-9]+)?$'
        then coalesce(version."RATEContractVer_SnapshotJSON"->>'sellTotal', contract."RATEContract_MetadataJSON"->>'sellTotal')::numeric else 0 end as sell_total
    from public."RATE_Contracts" contract
    left join public."RATE_ContractVersions" version on version."RATEContractVer_ID" = contract."RATEContract_CurrentVersionID"
    where contract."Company_ID" = p_company_id
      and not contract."RATEContract_IsDeleted"
      and case when v_scope = 'contracts' then contract."RATEContract_TypeCode" = 'contract' else contract."RATEContract_TypeCode" <> 'contract' end
  ), filtered as materialized (
    select *
    from scoped
    where (v_mode is null or mode_code = v_mode)
      and (v_tariff_type is null or type_code = v_tariff_type)
      and (
        v_expiry is null
        or (v_expiry = 'expired' and (status_code = 'expired' or valid_to < p_today))
        or (v_expiry = '7' and valid_to between p_today and p_today + 7)
        or (v_expiry = '30' and valid_to > p_today + 7 and valid_to <= p_today + 30)
        or (v_expiry = 'active' and status_code = 'active' and valid_to > p_today + 30)
      )
      and (
        v_search is null
        or strpos(lower(concat_ws(' ', code, name, carrier, supplier, customer, origin, destination, cargo)), lower(v_search)) > 0
      )
  ), page as materialized (
    select *
    from filtered
    order by
      case when v_sort_direction = 'asc' then case v_sort
        when 'name' then lower(name) when 'type' then lower(type_code) when 'mode' then lower(mode_code)
        when 'route' then lower(origin || destination) when 'carrier' then lower(coalesce(nullif(carrier, ''), supplier))
        when 'status' then lower(status_code) when 'schedule' then lower(schedule_code)
        when 'eligibility' then lower(coalesce(nullif(customer, ''), cargo))
      end end asc nulls last,
      case when v_sort_direction = 'desc' then case v_sort
        when 'name' then lower(name) when 'type' then lower(type_code) when 'mode' then lower(mode_code)
        when 'route' then lower(origin || destination) when 'carrier' then lower(coalesce(nullif(carrier, ''), supplier))
        when 'status' then lower(status_code) when 'schedule' then lower(schedule_code)
        when 'eligibility' then lower(coalesce(nullif(customer, ''), cargo))
      end end desc nulls last,
      case when v_sort_direction = 'asc' and v_sort = 'validity' then valid_to end asc nulls last,
      case when v_sort_direction = 'desc' and v_sort = 'validity' then valid_to end desc nulls last,
      case when v_sort_direction = 'asc' then case v_sort when 'buy' then buy_total when 'sell' then sell_total when 'version' then version_no end end asc nulls last,
      case when v_sort_direction = 'desc' then case v_sort when 'buy' then buy_total when 'sell' then sell_total when 'version' then version_no end end desc nulls last,
      updated_at desc,
      id
    limit v_limit offset v_offset
  ), page_rows as materialized (
    select page.*, to_jsonb(contract) as contract_json,
      case when version."RATEContractVer_ID" is null then null else to_jsonb(version) end as version_json
    from page
    join public."RATE_Contracts" contract on contract."RATEContract_ID" = page.id
    left join public."RATE_ContractVersions" version on version."RATEContractVer_ID" = page.current_version_id
  )
  select jsonb_build_object(
    'rows', coalesce((select jsonb_agg(jsonb_build_object('contract', contract_json, 'version', version_json) order by
      case when v_sort_direction = 'asc' then case v_sort when 'name' then lower(name) when 'type' then lower(type_code) when 'mode' then lower(mode_code) when 'route' then lower(origin || destination) when 'carrier' then lower(coalesce(nullif(carrier, ''), supplier)) when 'status' then lower(status_code) when 'schedule' then lower(schedule_code) when 'eligibility' then lower(coalesce(nullif(customer, ''), cargo)) end end asc nulls last,
      case when v_sort_direction = 'desc' then case v_sort when 'name' then lower(name) when 'type' then lower(type_code) when 'mode' then lower(mode_code) when 'route' then lower(origin || destination) when 'carrier' then lower(coalesce(nullif(carrier, ''), supplier)) when 'status' then lower(status_code) when 'schedule' then lower(schedule_code) when 'eligibility' then lower(coalesce(nullif(customer, ''), cargo)) end end desc nulls last,
      case when v_sort_direction = 'asc' and v_sort = 'validity' then valid_to end asc nulls last,
      case when v_sort_direction = 'desc' and v_sort = 'validity' then valid_to end desc nulls last,
      case when v_sort_direction = 'asc' then case v_sort when 'buy' then buy_total when 'sell' then sell_total when 'version' then version_no end end asc nulls last,
      case when v_sort_direction = 'desc' then case v_sort when 'buy' then buy_total when 'sell' then sell_total when 'version' then version_no end end desc nulls last,
      updated_at desc, id) from page_rows), '[]'::jsonb),
    'total', (select count(*) from filtered),
    'expiryCounts', jsonb_build_object(
      'expired', (select count(*) from scoped where status_code = 'expired' or valid_to < p_today),
      'sevenDays', (select count(*) from scoped where valid_to between p_today and p_today + 7),
      'thirtyDays', (select count(*) from scoped where valid_to > p_today + 7 and valid_to <= p_today + 30),
      'activeCurrent', (select count(*) from scoped where status_code = 'active' and valid_to > p_today + 30)
    )
  ) into v_result;

  return v_result;
end;
$_$;


ALTER FUNCTION "public"."multideck_rates_register_page"("p_company_id" "uuid", "p_scope" "text", "p_search" "text", "p_mode" "text", "p_tariff_type" "text", "p_expiry" "text", "p_sort" "text", "p_sort_direction" "text", "p_today" "date", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."multideck_rates_register_page"("p_company_id" "uuid", "p_scope" "text", "p_search" "text", "p_mode" "text", "p_tariff_type" "text", "p_expiry" "text", "p_sort" "text", "p_sort_direction" "text", "p_today" "date", "p_limit" integer, "p_offset" integer) IS 'Service-role-only, company-scoped Rates table read with exact totals, expiry counts and a maximum 50-row page.';



CREATE OR REPLACE FUNCTION "public"."multideck_rates_workspace_snapshot"("p_company_id" "uuid", "p_today" "date" DEFAULT CURRENT_DATE) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  with scoped as materialized (
    select
      contract."RATEContract_ID" as id,
      contract."RATEContract_CurrentVersionID" as current_version_id,
      contract."RATEContract_TypeCode"::text as type_code,
      contract."RATEContract_StatusCode"::text as status_code,
      contract."RATEContract_ValidTo" as valid_to,
      contract."RATEContract_UpdatedAt" as updated_at,
      coalesce(version."RATEContractVer_SnapshotJSON"->>'customer', contract."RATEContract_MetadataJSON"->>'customer', '') as customer
    from public."RATE_Contracts" contract
    left join public."RATE_ContractVersions" version on version."RATEContractVer_ID" = contract."RATEContract_CurrentVersionID"
    where contract."Company_ID" = p_company_id and not contract."RATEContract_IsDeleted"
  ), attention_ids as materialized (
    select id, current_version_id, updated_at from scoped
    where status_code in ('draft', 'expired') or valid_to <= p_today + 30
    order by updated_at desc, id limit 6
  ), recent_ids as materialized (
    select id, current_version_id, updated_at from scoped order by updated_at desc, id limit 5
  ), attention as materialized (
    select ids.id, ids.updated_at, to_jsonb(contract) as contract_json,
      case when version."RATEContractVer_ID" is null then null else to_jsonb(version) end as version_json
    from attention_ids ids
    join public."RATE_Contracts" contract on contract."RATEContract_ID" = ids.id
    left join public."RATE_ContractVersions" version on version."RATEContractVer_ID" = ids.current_version_id
  ), recent as materialized (
    select ids.id, ids.updated_at, to_jsonb(contract) as contract_json,
      case when version."RATEContractVer_ID" is null then null else to_jsonb(version) end as version_json
    from recent_ids ids
    join public."RATE_Contracts" contract on contract."RATEContract_ID" = ids.id
    left join public."RATE_ContractVersions" version on version."RATEContractVer_ID" = ids.current_version_id
  )
  select jsonb_build_object(
    'summary', jsonb_build_object(
      'total', (select count(*) from scoped),
      'attention', (select count(*) from scoped where status_code in ('draft', 'expired') or valid_to <= p_today + 30),
      'active', (select count(*) from scoped where status_code = 'active' and valid_to >= p_today),
      'drafts', (select count(*) from scoped where status_code = 'draft'),
      'costTariffs', (select count(*) from scoped where type_code = 'cost_tariff'),
      'salesTariffs', (select count(*) from scoped where type_code = 'sales_tariff'),
      'customerSpecific', (select count(*) from scoped where type_code <> 'contract' and nullif(btrim(customer), '') is not null),
      'expiringTariffs', (select count(*) from scoped where type_code <> 'contract' and valid_to between p_today and p_today + 30),
      'sourcesInReview', (select count(*) from public."RATE_ImportBatches" import_batch where import_batch."Company_ID" = p_company_id and import_batch."RATEImport_StatusCode" = 'review')
    ),
    'attention', coalesce((select jsonb_agg(jsonb_build_object('contract', contract_json, 'version', version_json) order by updated_at desc, id) from attention), '[]'::jsonb),
    'recent', coalesce((select jsonb_agg(jsonb_build_object('contract', contract_json, 'version', version_json) order by updated_at desc, id) from recent), '[]'::jsonb)
  )
$$;


ALTER FUNCTION "public"."multideck_rates_workspace_snapshot"("p_company_id" "uuid", "p_today" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."multideck_rates_workspace_snapshot"("p_company_id" "uuid", "p_today" "date") IS 'Service-role-only Rates dashboard read with exact summary and attention/recent queues capped at six and five rows.';



CREATE OR REPLACE FUNCTION "public"."multideck_receive_cloud_ticket_signal"("p_event_id" "uuid", "p_nonce" "uuid", "p_sent_at" bigint, "p_ticket_id" "uuid", "p_reference" "text", "p_reporter_user_id" "uuid", "p_ticket_type" "text", "p_restricted" boolean, "p_status" "text", "p_needs_reply" boolean, "p_message_id" "uuid", "p_changed_at" timestamp with time zone, "p_tenant_host" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $_$
declare
  v_reporter public."cmp_Users";
  v_before public."Support_CloudTicketSignals";
  v_after public."Support_CloudTicketSignals";
  v_old_json jsonb := '{}'::jsonb;
  v_new_json jsonb;
begin
  if auth.role() <> 'service_role' then
    raise exception 'server_only' using errcode = '42501';
  end if;
  if p_event_id is null or p_nonce is null or p_ticket_id is null or p_reporter_user_id is null then
    raise exception 'The callback identifiers are incomplete.' using errcode = '22023';
  end if;
  if abs(extract(epoch from now())::bigint - p_sent_at) > 300 then
    raise exception 'The callback timestamp is outside the allowed window.' using errcode = '22023';
  end if;
  if btrim(coalesce(p_tenant_host, '')) = ''
     or lower(btrim(p_tenant_host)) <> btrim(p_tenant_host)
     or p_tenant_host like '%/%' then
    raise exception 'The callback tenant hostname is invalid.' using errcode = '22023';
  end if;
  if coalesce(p_status, '') not in ('new','in_progress','waiting_for_customer','resolved','closed') then
    raise exception 'The callback ticket status is invalid.' using errcode = '22023';
  end if;
  if coalesce(p_restricted, true)
     or coalesce(p_ticket_type, '') not in ('bug','feature_request','question','account_billing') then
    raise exception 'Restricted ticket callbacks are not accepted by tenant deployments.' using errcode = '42501';
  end if;
  if coalesce(p_reference, '') !~ '^MD-[0-9]{5,}$' then
    raise exception 'The callback ticket reference is invalid.' using errcode = '22023';
  end if;
  if p_changed_at is null or p_changed_at > now() + interval '5 minutes' then
    raise exception 'The callback change timestamp is invalid.' using errcode = '22023';
  end if;

  delete from public."Support_CloudTicketCallbackNonces"
  where "CloudTicketCallbackNonce_SeenAt" < now() - interval '24 hours';

  insert into public."Support_CloudTicketCallbackNonces" (
    "CloudTicketCallbackNonce_Value", "CloudTicketCallbackNonce_EventID"
  ) values (p_nonce, p_event_id)
  on conflict do nothing;
  if not found then
    return jsonb_build_object('accepted', true, 'duplicate', true);
  end if;

  select * into v_reporter
  from public."cmp_Users" workspace_user
  where workspace_user."User_ID" = p_reporter_user_id
    and workspace_user."Company_ID" is not null
    and coalesce(workspace_user."User_AccessStatus", 'active') = 'active';
  if not found then
    raise exception 'The callback reporter is not an active tenant user.' using errcode = '42501';
  end if;

  select * into v_before
  from public."Support_CloudTicketSignals"
  where "CloudTicketSignal_TicketID" = p_ticket_id
  for update;

  if found and v_before."CloudTicketSignal_CompanyID" <> v_reporter."Company_ID" then
    raise exception 'The callback ticket belongs to another workspace.' using errcode = '42501';
  end if;
  if found and v_before."CloudTicketSignal_ReporterUserID" <> p_reporter_user_id then
    raise exception 'The callback reporter cannot be changed.' using errcode = '42501';
  end if;
  if found and v_before."CloudTicketSignal_TicketType" <> p_ticket_type then
    raise exception 'The callback ticket type cannot be changed.' using errcode = '42501';
  end if;
  if found and v_before."CloudTicketSignal_ChangedAt" > p_changed_at then
    return jsonb_build_object('accepted', true, 'stale', true);
  end if;

  if found then
    v_old_json := jsonb_build_object(
      'status', v_before."CloudTicketSignal_StatusCode",
      'needsReply', v_before."CloudTicketSignal_NeedsReply",
      'messageId', v_before."CloudTicketSignal_LatestMessageID",
      'updatedAt', v_before."CloudTicketSignal_ChangedAt"
    );
  end if;

  insert into public."Support_CloudTicketSignals" (
    "CloudTicketSignal_TicketID", "CloudTicketSignal_CompanyID",
    "CloudTicketSignal_ReporterUserID", "CloudTicketSignal_Reference",
    "CloudTicketSignal_TicketType",
    "CloudTicketSignal_StatusCode", "CloudTicketSignal_NeedsReply",
    "CloudTicketSignal_LatestMessageID", "CloudTicketSignal_ChangedAt"
  ) values (
    p_ticket_id, v_reporter."Company_ID", p_reporter_user_id,
    p_reference, p_ticket_type, p_status, p_needs_reply, p_message_id, p_changed_at
  )
  on conflict ("CloudTicketSignal_TicketID") do update set
    "CloudTicketSignal_StatusCode" = excluded."CloudTicketSignal_StatusCode",
    "CloudTicketSignal_NeedsReply" = excluded."CloudTicketSignal_NeedsReply",
    "CloudTicketSignal_LatestMessageID" = coalesce(
      excluded."CloudTicketSignal_LatestMessageID",
      public."Support_CloudTicketSignals"."CloudTicketSignal_LatestMessageID"
    ),
    "CloudTicketSignal_ChangedAt" = excluded."CloudTicketSignal_ChangedAt",
    "CloudTicketSignal_UpdatedAt" = now()
  returning * into v_after;

  v_new_json := jsonb_build_object(
    'status', v_after."CloudTicketSignal_StatusCode",
    'needsReply', v_after."CloudTicketSignal_NeedsReply",
    'messageId', v_after."CloudTicketSignal_LatestMessageID",
    'updatedAt', v_after."CloudTicketSignal_ChangedAt"
  );

  if v_new_json is distinct from v_old_json and exists (
    select 1
    from public."AI_DexterWatches" watch
    where watch."AIDexterWatch_CompanyID" = v_after."CloudTicketSignal_CompanyID"
      and watch."AIDexterWatch_CapabilityCode" = 'support_tickets'
      and watch."AIDexterWatch_StatusCode" = 'active'
      and watch."AIDexterWatch_TargetID" = p_ticket_id
  ) then
    insert into public."AI_DexterWatchSignals" (
      "AIDexterWatchSignal_CompanyID", "AIDexterWatchSignal_CapabilityCode",
      "AIDexterWatchSignal_SourceTable", "AIDexterWatchSignal_SourceID",
      "AIDexterWatchSignal_OldJSON", "AIDexterWatchSignal_NewJSON"
    ) values (
      v_after."CloudTicketSignal_CompanyID", 'support_tickets',
      'Support_CloudTicketSignals', p_ticket_id, v_old_json, v_new_json
    );
  end if;

  return jsonb_build_object(
    'accepted', true,
    'ticketId', p_ticket_id,
    'reference', p_reference
  );
end;
$_$;


ALTER FUNCTION "public"."multideck_receive_cloud_ticket_signal"("p_event_id" "uuid", "p_nonce" "uuid", "p_sent_at" bigint, "p_ticket_id" "uuid", "p_reference" "text", "p_reporter_user_id" "uuid", "p_ticket_type" "text", "p_restricted" boolean, "p_status" "text", "p_needs_reply" boolean, "p_message_id" "uuid", "p_changed_at" timestamp with time zone, "p_tenant_host" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_register_condition_matches"("p_values" "jsonb", "p_condition" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  v_operator text := coalesce(p_condition ->> 'operator', 'contains');
  v_query text := lower(btrim(coalesce(p_condition ->> 'value', '')));
  v_query_to text := lower(btrim(coalesce(p_condition ->> 'valueTo', '')));
  v_values text[];
  v_filled text[];
  v_days text[];
  v_start text;
  v_end text;
begin
  if jsonb_typeof(p_values) = 'array' then
    select coalesce(array_agg(coalesce(value #>> '{}', '')), array[]::text[])
      into v_values
    from jsonb_array_elements(p_values) value;
  else
    v_values := array[coalesce(p_values #>> '{}', '')];
  end if;

  select coalesce(array_agg(value), array[]::text[])
    into v_filled
  from unnest(v_values) value
  where btrim(value) <> '' and btrim(value) <> '—';

  if v_operator = 'is-empty' then return cardinality(v_filled) = 0; end if;
  if v_operator = 'is-not-empty' then return cardinality(v_filled) > 0; end if;

  if v_operator in ('on', 'before', 'after', 'between') then
    select coalesce(array_agg(substring(value from 1 for 10)), array[]::text[])
      into v_days
    from unnest(v_filled) value
    where substring(value from 1 for 10) ~ '^\d{4}-\d{2}-\d{2}$';

    if cardinality(v_days) = 0 then return false; end if;
    v_start := case when substring(v_query from 1 for 10) ~ '^\d{4}-\d{2}-\d{2}$' then substring(v_query from 1 for 10) end;
    v_end := case when substring(v_query_to from 1 for 10) ~ '^\d{4}-\d{2}-\d{2}$' then substring(v_query_to from 1 for 10) end;

    if v_operator = 'before' then return v_start is null or exists(select 1 from unnest(v_days) day where day < v_start); end if;
    if v_operator = 'after' then return v_start is null or exists(select 1 from unnest(v_days) day where day > v_start); end if;
    if v_operator = 'between' then
      if v_start is null and v_end is null then return true; end if;
      v_start := coalesce(v_start, v_end);
      v_end := coalesce(v_end, v_start);
      return exists(select 1 from unnest(v_days) day where day between least(v_start, v_end) and greatest(v_start, v_end));
    end if;
    return v_start is null or exists(select 1 from unnest(v_days) day where day = v_start);
  end if;

  if v_query = '' then return true; end if;
  if v_operator = 'is-not' then
    return not exists(select 1 from unnest(v_values) value where lower(btrim(value)) = v_query);
  end if;
  if v_operator = 'not-contains' then
    return not exists(select 1 from unnest(v_values) value where strpos(lower(btrim(value)), v_query) > 0);
  end if;
  if v_operator = 'is' then
    return exists(select 1 from unnest(v_values) value where lower(btrim(value)) = v_query);
  end if;
  if v_operator = 'starts-with' then
    return exists(select 1 from unnest(v_values) value where left(lower(btrim(value)), length(v_query)) = v_query);
  end if;
  return exists(select 1 from unnest(v_values) value where strpos(lower(btrim(value)), v_query) > 0);
end;
$_$;


ALTER FUNCTION "public"."multideck_register_condition_matches"("p_values" "jsonb", "p_condition" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_register_filter_matches"("p_fields" "jsonb", "p_query" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_query_match text := case when p_query ->> 'match' = 'any' then 'any' else 'all' end;
  v_group jsonb;
  v_condition jsonb;
  v_group_match text;
  v_group_result boolean;
  v_condition_result boolean;
  v_active_groups integer := 0;
  v_active_conditions integer;
  v_value text;
  v_value_to text;
  v_operator text;
begin
  if p_query is null or jsonb_typeof(p_query -> 'groups') <> 'array' then return true; end if;

  for v_group in select value from jsonb_array_elements(p_query -> 'groups') loop
    v_group_match := case when v_group ->> 'match' = 'any' then 'any' else 'all' end;
    v_group_result := v_group_match = 'all';
    v_active_conditions := 0;

    if jsonb_typeof(v_group -> 'conditions') = 'array' then
      for v_condition in select value from jsonb_array_elements(v_group -> 'conditions') loop
        v_operator := coalesce(v_condition ->> 'operator', 'contains');
        v_value := btrim(coalesce(v_condition ->> 'value', ''));
        v_value_to := btrim(coalesce(v_condition ->> 'valueTo', ''));
        if v_operator not in ('is-empty', 'is-not-empty')
          and not (v_operator = 'between' and (v_value <> '' or v_value_to <> ''))
          and v_value = '' then
          continue;
        end if;

        v_active_conditions := v_active_conditions + 1;
        v_condition_result := public.multideck_register_condition_matches(
          coalesce(p_fields -> (v_condition ->> 'field'), 'null'::jsonb),
          v_condition
        );
        if v_group_match = 'all' then
          v_group_result := v_group_result and v_condition_result;
        else
          v_group_result := v_group_result or v_condition_result;
        end if;
      end loop;
    end if;

    if v_active_conditions = 0 then continue; end if;
    v_active_groups := v_active_groups + 1;
    if v_query_match = 'all' and not v_group_result then return false; end if;
    if v_query_match = 'any' and v_group_result then return true; end if;
  end loop;

  if v_active_groups = 0 then return true; end if;
  return v_query_match = 'all';
end;
$$;


ALTER FUNCTION "public"."multideck_register_filter_matches"("p_fields" "jsonb", "p_query" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_road_control_page"("p_scope" "text" DEFAULT 'All Jobs'::"text", "p_operator_code" "text" DEFAULT NULL::"text", "p_stage" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 20, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_scope text := case when p_scope in ('All Jobs', 'My Jobs', 'Starred Jobs') then p_scope else 'All Jobs' end;
  v_stage text := case when p_stage in ('intake', 'ready', 'carrier', 'live', 'close') then p_stage end;
  v_limit integer := greatest(1, least(coalesce(p_limit, 20), 50));
  v_offset integer := greatest(0, coalesce(p_offset, 0));
  v_result jsonb;
begin
  if auth.uid() is null then raise exception 'Authentication required.' using errcode = '42501'; end if;

  with base as materialized (
    select
      booking."Job_ID",
      booking."Booking_Reference",
      booking."Customer_Name",
      booking."Carrier",
      booking."Mode",
      booking."Shipment_Type",
      booking."Eta_Display",
      booking."Status",
      booking."Progress",
      booking."Owner_Code",
      booking."Tone",
      booking."Customer_Reference",
      booking."Origin",
      booking."Destination",
      booking."Is_Favourite",
      booking."Updated_At",
      case
        when coalesce(booking."Progress", 0) < 30 then 'intake'
        when coalesce(booking."Progress", 0) < 50 then 'ready'
        when coalesce(booking."Progress", 0) < 60 then 'carrier'
        when coalesce(booking."Progress", 0) < 90 then 'live'
        else 'close'
      end as road_stage
    from public."App_Live_Bookings" booking
    where upper(coalesce(booking."Mode", '')) = 'ROAD'
      and (v_scope <> 'My Jobs' or booking."Owner_Code" = coalesce(nullif(btrim(p_operator_code), ''), ''))
      and (v_scope <> 'Starred Jobs' or coalesce(booking."Is_Favourite", false))
  ), ranked as (
    select *, row_number() over (
      partition by road_stage
      order by "Updated_At" desc nulls last, "Booking_Reference"
    ) as ordinal
    from base
    where v_stage is null or road_stage = v_stage
  ), page as (
    select *
    from ranked
    where case
      when v_stage is null then ordinal <= v_limit
      else ordinal > v_offset and ordinal <= v_offset + v_limit
    end
  )
  select jsonb_build_object(
    'rows', coalesce((
      select jsonb_agg(to_jsonb(item) - 'ordinal' order by item.road_stage, item.ordinal)
      from page item
    ), '[]'::jsonb),
    'counts', jsonb_build_object(
      'intake', (select count(*) from base where road_stage = 'intake'),
      'ready', (select count(*) from base where road_stage = 'ready'),
      'carrier', (select count(*) from base where road_stage = 'carrier'),
      'live', (select count(*) from base where road_stage = 'live'),
      'close', (select count(*) from base where road_stage = 'close')
    ),
    'total', (select count(*) from base),
    'filteredTotal', case
      when v_stage is null then (select count(*) from base)
      else (select count(*) from base where road_stage = v_stage)
    end,
    'limit', v_limit,
    'offset', case when v_stage is null then 0 else v_offset end
  ) into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."multideck_road_control_page"("p_scope" "text", "p_operator_code" "text", "p_stage" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."multideck_road_control_page"("p_scope" "text", "p_operator_code" "text", "p_stage" "text", "p_limit" integer, "p_offset" integer) IS 'RLS-preserving Road Control read with exact stage counts, maximum-50-row list pages and maximum-50-card Kanban lanes.';



CREATE OR REPLACE FUNCTION "public"."multideck_set_job_starred"("p_booking_reference" "text", "p_starred" boolean) RETURNS boolean
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_job_id uuid;
begin
  if auth.uid() is null then
    raise exception 'Authentication required.' using errcode = '42501';
  end if;

  select job."Job_ID" into v_job_id
  from public."Job_Header" job
  where not coalesce(job."Job_IsDeleted", false)
    and coalesce(job."Job_BookingReference", 'MD-' || job."Job_Number") = btrim(p_booking_reference)
  limit 1;

  if v_job_id is null then
    raise exception 'Job not found.' using errcode = 'P0002';
  end if;

  if coalesce(p_starred, false) then
    insert into public."App_UserJobStars" ("User_ID", "Job_ID")
    values (auth.uid(), v_job_id)
    on conflict ("User_ID", "Job_ID") do nothing;
  else
    delete from public."App_UserJobStars"
    where "User_ID" = auth.uid() and "Job_ID" = v_job_id;
  end if;

  return coalesce(p_starred, false);
end;
$$;


ALTER FUNCTION "public"."multideck_set_job_starred"("p_booking_reference" "text", "p_starred" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."multideck_set_job_starred"("p_booking_reference" "text", "p_starred" boolean) IS 'Persists the signed-in operator personal star for one exact canonical job.';



CREATE OR REPLACE FUNCTION "public"."multideck_task_assignments"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare actor record; result jsonb;
begin
 select * into actor from public._multideck_dexter_context();
 perform public._dexter_task_icons(actor.user_id);
 select coalesce(jsonb_agg(to_jsonb(a)||jsonb_build_object('title',t."TodoTask_Title",'taskStatus',t."TodoTask_StatusCode",'scheduledDate',t."TodoTask_ScheduledDate",'due_at',r.due_at) order by a.updated_at desc),'[]') into result
 from (select * from public."AI_DexterTaskAssignments" where owner_id=actor.user_id and company_id=actor.company_id order by case when status in ('queued','working','waiting','scheduled') or result_revision>viewed_revision then 0 else 1 end,updated_at desc limit 200) a
 join public."OPS_UserTasks" t on t."TodoTask_ID"=a.task_id and not t."TodoTask_IsDeleted"
 left join public."AI_DexterTaskRuns" r on r.assignment_id=a.id and r.state in ('queued','running');
 return result;
end $$;


ALTER FUNCTION "public"."multideck_task_assignments"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_task_claim"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare item record; a public."AI_DexterTaskAssignments"; r public."AI_DexterTaskRuns"; result jsonb:='[]';
begin
 if auth.role() is distinct from 'service_role' then raise exception 'Worker only.' using errcode='42501';end if;
 if not exists(select 1 from public."AI_DexterTaskSettings" where enabled) then return '[]';end if;
 -- Serialise claims, never the model work. Three workers per owner across invocations.
 perform pg_advisory_xact_lock(hashtextextended('dexter-task-claims',0));
 for item in select runs.id from public."AI_DexterTaskRuns" runs join public."AI_DexterTaskAssignments" assignment on assignment.id=runs.assignment_id
 join public."cmp_Users" u on u."User_ID"=assignment.owner_id and u."Company_ID"=assignment.company_id and coalesce(u."User_AccessStatus",'active')='active'
 join public."OPS_UserTasks" t on t."TodoTask_ID"=assignment.task_id and t."TodoTask_StatusCode"='open' and not t."TodoTask_IsDeleted"
 where ((runs.state='queued' and runs.due_at<=now()) or (runs.state='running' and runs.lease_until<now()))
 and (select count(*) from public."AI_DexterTaskRuns" x join public."AI_DexterTaskAssignments" y on y.id=x.assignment_id where y.owner_id=assignment.owner_id and x.state='running' and x.lease_until>now())<3 order by runs.due_at,runs.created_at limit 30 loop
  -- Match task-control lock order. The cursor's candidate may have been
  -- cancelled or rescheduled while we waited for the assignment lock.
  select assignment.* into a from public."AI_DexterTaskAssignments" assignment
   join public."AI_DexterTaskRuns" candidate on candidate.assignment_id=assignment.id
   where candidate.id=item.id for update of assignment;
  select * into r from public."AI_DexterTaskRuns" where id=item.id for update;
  if not ((r.state='queued' and r.due_at<=now()) or
          (r.state='running' and r.lease_until<now())) then continue;end if;
  if not exists(select 1 from public."OPS_UserTasks" t where t."TodoTask_ID"=a.task_id
    and t."TodoTask_StatusCode"='open' and not t."TodoTask_IsDeleted") then continue;end if;
  if r.attempts>=3 then
   update public."AI_DexterTaskRuns" set state='failed',lease_token=null,lease_until=null,error_code='worker_interrupted',finished_at=now() where id=r.id;
   update public."AI_DexterTaskAssignments" set status='failed',summary='The background run was interrupted. Your task is kept; retry when ready.',message_id=null,result_revision=result_revision+1,version=version+1,updated_at=now() where id=a.id;
   insert into public."Comm_Notifications"("CommNotif_UserID","CommNotif_Title","CommNotif_Body","CommNotif_TargetTable","CommNotif_TargetID","CommNotif_LinkTypeCode","CommNotif_MetadataJSON","CommNotif_CreatedBy") values(a.owner_id,'Your task needs attention','The background run was interrupted. Open the task to retry.','AI_DexterTaskAssignments',a.id,'dexter_watch',jsonb_build_object('action_url','/agent-dexter?conversation='||a.conversation_id),a.owner_id);
   continue;
  end if;
  if (select count(*) from public."AI_DexterTaskRuns" x join public."AI_DexterTaskAssignments" y on y.id=x.assignment_id where y.owner_id=a.owner_id and x.state='running' and x.lease_until>now())>=3 then continue;end if;
  update public."AI_DexterTaskRuns" set state='running',lease_token=gen_random_uuid(),lease_until=now()+interval '3 minutes',attempts=attempts+1 where id=r.id returning * into r;
  update public."AI_DexterTaskAssignments" set status='working',summary='Finding the context and preparing your result',version=version+1,updated_at=now() where id=a.id;
  perform public._dexter_task_icons(a.owner_id);
  result:=result||jsonb_build_array(jsonb_build_object('id',r.id,'lease_token',r.lease_token));
  exit when jsonb_array_length(result)>=3;
 end loop;
 return result;
end $$;


ALTER FUNCTION "public"."multideck_task_claim"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_task_configure"("p_endpoint" "text", "p_enabled" boolean DEFAULT true) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
begin
 if auth.role() is distinct from 'service_role' then raise exception 'Worker only.' using errcode='42501';end if;
 if p_endpoint !~ '^https://[a-z0-9]+\.supabase\.co/functions/v1/dexter-task-worker$' then raise exception 'Use the tenant Supabase worker URL.' using errcode='22023';end if;
 if not exists(select 1 from vault.decrypted_secrets where name='multideck_task_worker_secret') then
  perform vault.create_secret(gen_random_uuid()::text||gen_random_uuid()::text,'multideck_task_worker_secret');
 end if;
 update public."AI_DexterTaskSettings" set endpoint=p_endpoint,enabled=p_enabled;
 if p_enabled then perform cron.schedule('multideck-dexter-tasks','* * * * *','select public._dexter_task_kick()');
 elsif exists(select 1 from cron.job where jobname='multideck-dexter-tasks') then perform cron.unschedule('multideck-dexter-tasks');end if;
 return p_enabled;
end $_$;


ALTER FUNCTION "public"."multideck_task_configure"("p_endpoint" "text", "p_enabled" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_task_control"("p_id" "uuid", "p_operation" "text", "p_version" integer, "p_input" "text" DEFAULT NULL::"text", "p_revision" integer DEFAULT NULL::integer, "p_run_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare actor record; a public."AI_DexterTaskAssignments"; previous_phase text;
begin
 select * into actor from public._multideck_dexter_context();
 select * into a from public."AI_DexterTaskAssignments" where id=p_id and owner_id=actor.user_id and company_id=actor.company_id
  and exists(select 1 from public."OPS_UserTasks" t where t."TodoTask_ID"=task_id and not t."TodoTask_IsDeleted") for update;
 if not found then raise exception 'This task is unavailable.' using errcode='42501';end if;
 if p_operation='view' then
  update public."AI_DexterTaskAssignments" set viewed_revision=greatest(viewed_revision,least(coalesce(p_revision,0),result_revision)),
   status=case when status='ready' and outcome='deliver_result' and p_revision=result_revision then 'completed' else status end where id=a.id returning * into a;
  if a.status='completed' then perform public._multideck_todo_update_for_actor(actor.company_id,actor.user_id,a.task_id,'{"status":"completed"}');end if;
  return to_jsonb(a);
 end if;
 if a.version is distinct from p_version then raise exception 'This task changed. Refresh it and try again.' using errcode='40001';end if;
 if p_operation='cancel' then
  update public."AI_DexterTaskRuns" set state='cancelled',lease_token=null,lease_until=null where assignment_id=a.id and state in ('queued','running');
  if a.watch_id is not null then perform public.multideck_dexter_set_watch_status(a.watch_id,'paused');end if;
  update public."AI_DexterTaskAssignments" set status='cancelled',summary='Background work stopped',version=version+1,updated_at=now() where id=a.id returning * into a;
 elsif p_operation in ('retry','followup','reschedule','resume') then
  if exists(select 1 from public."AI_DexterTaskRuns" where assignment_id=a.id and state='running') then raise exception 'This agent is still working. Wait for its result before following up.' using errcode='55000';end if;
  if p_operation='reschedule' and (p_run_at is null or p_run_at<=now()) then raise exception 'Choose a future date and time.' using errcode='22023';end if;
  if p_operation='followup' and nullif(btrim(p_input),'') is null then raise exception 'Write a follow-up first.' using errcode='22023';end if;
  select phase into previous_phase from public."AI_DexterTaskRuns" where assignment_id=a.id order by created_at desc,id desc limit 1;
  update public."AI_DexterTaskRuns" set state='cancelled' where assignment_id=a.id and state='queued';
  if a.watch_id is not null then perform public.multideck_dexter_set_watch_status(a.watch_id,'paused');end if;
  if exists(select 1 from public."OPS_UserTasks" where "TodoTask_ID"=a.task_id and "TodoTask_StatusCode"='completed') then
   perform public._multideck_todo_update_for_actor(actor.company_id,actor.user_id,a.task_id,'{"status":"open"}');
  end if;
  insert into public."AI_DexterTaskRuns"(assignment_id,input,phase,due_at) values(a.id,coalesce(nullif(btrim(p_input),''),a.instruction),case when p_operation='reschedule' then 'execute' when p_operation in ('retry','resume') then coalesce(previous_phase,'discover') else 'discover' end,coalesce(p_run_at,now()));
  update public."AI_DexterTaskAssignments" set status=case when p_run_at>now() then 'scheduled' else 'queued' end,summary=case when p_run_at>now() then 'Scheduled for Dexter' else 'Queued for Dexter' end,watch_id=null,instruction=coalesce(nullif(btrim(p_input),''),instruction),version=version+1,updated_at=now() where id=a.id returning * into a;
 else raise exception 'Unsupported task operation.' using errcode='22023';end if;
 perform public._dexter_task_kick();
 return to_jsonb(a);
end $$;


ALTER FUNCTION "public"."multideck_task_control"("p_id" "uuid", "p_operation" "text", "p_version" integer, "p_input" "text", "p_revision" integer, "p_run_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_task_finish"("p_run" "uuid", "p_token" "uuid", "p_result" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare a public."AI_DexterTaskAssignments"; r public."AI_DexterTaskRuns"; v_status text; run_at timestamptz; watch uuid; msg uuid;
begin
 a:=public._dexter_task_lease(p_run,p_token);
 select * into r from public."AI_DexterTaskRuns" where id=p_run for update;
 v_status:=p_result->>'status';
 if v_status is null or v_status not in ('ready','needs_input','scheduled','waiting','failed') then raise exception 'Invalid task outcome.' using errcode='22023';end if;
 if v_status<>'failed' then
  select "AIMSG_ID" into msg from public."AI_Messages" where "AIMSG_ConversationID"=a.conversation_id and "AIMSG_Role"='assistant' and "AIMSG_ContentJSON"->'metadata'->>'taskRunId'=p_run::text;
  if msg is null then raise exception 'The task result has not been saved.' using errcode='55000';end if;
 end if;
 if v_status='scheduled' then run_at:=(p_result->>'run_at')::timestamptz;if run_at<=now() or run_at is null then raise exception 'Choose a future time.' using errcode='22023';end if;end if;
 if v_status='waiting' then
  watch:=(p_result->>'watch_id')::uuid;
  if not exists(select 1 from public."AI_DexterWatches" where "AIDexterWatch_ID"=watch and "AIDexterWatch_OwnerUserID"=a.owner_id and "AIDexterWatch_CompanyID"=a.company_id and "AIDexterWatch_ActionJSON" is null) then raise exception 'The task watch is unavailable.' using errcode='42501';end if;
 end if;
 update public."AI_DexterTaskRuns" set state=case when v_status='failed' then 'failed' else 'succeeded' end,result=p_result,finished_at=now(),lease_until=null,lease_token=null where id=p_run;
 update public."AI_DexterTaskAssignments" set status=v_status,summary=left(coalesce(p_result->>'summary','Your task has an update'),500),outcome=p_result->>'outcome',
 name=case when p_result->>'name' ~ '^[A-Za-z]{2,24}$' then p_result->>'name' else name end,
 watch_id=watch,message_id=msg,result_revision=result_revision+case when v_status in ('ready','needs_input','failed') then 1 else 0 end,version=version+1,updated_at=now() where id=a.id;
 -- A saved, successful deliverable completes the list item immediately.
 -- Keep its response ready and unread until the owner opens it.
 if v_status='ready' and p_result->>'outcome'='deliver_result' then
  perform public._multideck_todo_update_for_actor(a.company_id,a.owner_id,a.task_id,'{"status":"completed"}');
  update public."AI_DexterTaskAssignments" set status='ready' where id=a.id;
 end if;
 if v_status='scheduled' then insert into public."AI_DexterTaskRuns"(assignment_id,input,phase,due_at) values(a.id,r.input,'execute',run_at);end if;
 if v_status='waiting' and exists(select 1 from public."AI_DexterWatchEvents" where "AIDexterWatchEvent_WatchID"=watch) then
  insert into public."AI_DexterTaskRuns"(assignment_id,input,phase) values(a.id,r.input,'execute') on conflict do nothing;
  update public."AI_DexterTaskAssignments" set status='queued',summary='The event arrived. Queued for Dexter' where id=a.id;
  update public."AI_DexterWatches" set "AIDexterWatch_StatusCode"='paused' where "AIDexterWatch_ID"=watch;
 end if;
 if v_status in ('ready','needs_input','failed') then
  insert into public."Comm_Notifications"("CommNotif_UserID","CommNotif_Title","CommNotif_Body","CommNotif_TargetTable","CommNotif_TargetID","CommNotif_LinkTypeCode","CommNotif_MetadataJSON","CommNotif_CreatedBy")
  values(a.owner_id,case when v_status='ready' then 'Your task is ready to review' else 'Your task needs attention' end,left(coalesce(p_result->>'summary','Open the task to continue.'),500),'AI_DexterTaskAssignments',a.id,'dexter_watch',jsonb_build_object('action_url','/agent-dexter?conversation='||a.conversation_id,'task_run_id',p_run),a.owner_id);
 end if;
 perform public._dexter_task_kick();
 return true;
end $_$;


ALTER FUNCTION "public"."multideck_task_finish"("p_run" "uuid", "p_token" "uuid", "p_result" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_task_handoff"("p_task_id" "uuid", "p_instruction" "text" DEFAULT NULL::"text", "p_time_zone" "text" DEFAULT 'Europe/London'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare actor record; task public."OPS_UserTasks"; a public."AI_DexterTaskAssignments"; conv uuid:=gen_random_uuid();
begin
 select * into actor from public._multideck_dexter_context();
 if not exists(select 1 from public."AI_DexterTaskSettings" where enabled) then raise exception 'Background tasks are not enabled in this workspace yet.' using errcode='55000';end if;
 select * into task from public."OPS_UserTasks" where "TodoTask_ID"=p_task_id and "TodoTask_OwnerUserID"=actor.user_id and "TodoTask_CompanyID"=actor.company_id and not "TodoTask_IsDeleted" for update;
 if not found or task."TodoTask_StatusCode"<>'open' then raise exception 'Choose one of your open tasks.' using errcode='42501';end if;
 if not exists(select 1 from pg_timezone_names where name=p_time_zone) then raise exception 'Choose a valid timezone.' using errcode='22023';end if;
 select * into a from public."AI_DexterTaskAssignments" where task_id=p_task_id;
 if found then return to_jsonb(a);end if;
 insert into public."AI_Conversations"("AICNV_ID","AICNV_Title","AICNV_Channel","AICNV_DomainCode","AICNV_CompanyID","AICNV_OwnerUserID","AICNV_Status","AICNV_SecurityClass","AICNV_IsTrainingAllowed","AICNV_MetadataJSON","AICNV_StartedAt","AICNV_CreatedAt","AICNV_CreatedBy","AICNV_UpdatedAt","AICNV_UpdatedBy")
 values(conv,task."TodoTask_Title",'chat','multideck',actor.company_id,actor.user_id,'open','internal',false,'{"agent":"dexter","backgroundTask":true}',now(),now(),actor.user_id,now(),actor.user_id);
 insert into public."AI_DexterTaskAssignments"(task_id,owner_id,company_id,conversation_id,instruction,time_zone)
 values(p_task_id,actor.user_id,actor.company_id,conv,coalesce(nullif(btrim(p_instruction),''),task."TodoTask_Title"),p_time_zone) returning * into a;
 insert into public."AI_DexterTaskRuns"(assignment_id,input) values(a.id,a.instruction);
 perform public._dexter_task_kick();
 return to_jsonb(a);
end $$;


ALTER FUNCTION "public"."multideck_task_handoff"("p_task_id" "uuid", "p_instruction" "text", "p_time_zone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_task_worker_context"("p_run" "uuid", "p_token" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare a public."AI_DexterTaskAssignments"; result jsonb;
begin
 a:=public._dexter_task_lease(p_run,p_token);
 select to_jsonb(a)||jsonb_build_object('run',to_jsonb(r)-'lease_token','authUserId',u."Auth_User_ID",'email',u."User_Email",'displayName',concat_ws(' ',u."User_Firstname",u."User_Lastname"),'task',public._multideck_todo_task_json(t)) into result
 from public."AI_DexterTaskRuns" r join public."cmp_Users" u on u."User_ID"=a.owner_id join public."OPS_UserTasks" t on t."TodoTask_ID"=a.task_id where r.id=p_run;
 return result;
end $$;


ALTER FUNCTION "public"."multideck_task_worker_context"("p_run" "uuid", "p_token" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_task_worker_interrupted"("p_run" "uuid", "p_token" "uuid", "p_code" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare a public."AI_DexterTaskAssignments"; attempts integer;
begin
 a:=public._dexter_task_lease(p_run,p_token);
 select r.attempts into attempts from public."AI_DexterTaskRuns" r where r.id=p_run for update;
 update public."AI_DexterTaskRuns" set error_code=left(regexp_replace(coalesce(p_code,'worker_interrupted'),'[^a-zA-Z0-9_]','','g'),100) where id=p_run;
 if attempts>=3 then
  return public.multideck_task_finish(p_run,p_token,jsonb_build_object('status','failed','summary','The connection was interrupted repeatedly. Your task and any saved work are kept. Open the task to retry.'));
 end if;
 update public."AI_DexterTaskRuns" set state='queued',due_at=now()+interval '30 seconds',lease_until=null,lease_token=null where id=p_run;
 update public."AI_DexterTaskAssignments" set status='queued',summary='The connection was interrupted. Retrying shortly.',version=version+1,updated_at=now() where id=a.id;
 return true;
end $$;


ALTER FUNCTION "public"."multideck_task_worker_interrupted"("p_run" "uuid", "p_token" "uuid", "p_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_task_worker_name"("p_run" "uuid", "p_token" "uuid", "p_name" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare a public."AI_DexterTaskAssignments";
begin
 a:=public._dexter_task_lease(p_run,p_token);
 if p_name !~ '^[A-Za-z]{2,24}$' then raise exception 'Invalid agent name.' using errcode='22023';end if;
 update public."AI_DexterTaskAssignments" set name=p_name where id=a.id and name='Dexter';
end $_$;


ALTER FUNCTION "public"."multideck_task_worker_name"("p_run" "uuid", "p_token" "uuid", "p_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_task_worker_rpc"("p_run" "uuid", "p_token" "uuid", "p_name" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $_$
declare a public."AI_DexterTaskAssignments"; actor uuid; proc record; arguments text; result jsonb; claims text:=current_setting('request.jwt.claims',true); sub text:=current_setting('request.jwt.claim.sub',true); jwtrole text:=current_setting('request.jwt.claim.role',true);
begin
 a:=public._dexter_task_lease(p_run,p_token);
 if p_name<>all(array['multideck_dexter_list_domains','multideck_dexter_list_actions','multideck_dexter_query_domain','multideck_dexter_prepare_conversation','multideck_dexter_save_exchange','multideck_dexter_search_email','multideck_dexter_recent_email','multideck_dexter_read_email_thread','multideck_dexter_email_thread_folders','multideck_dexter_resolve_email_attachment','multideck_dexter_get_writing_profile','multideck_dexter_resolve_email_draft_source','multideck_dexter_record_writing_profile_event','multideck_dexter_check_usage_allowance','multideck_dexter_list_watch_capabilities','multideck_dexter_create_watch']) then raise exception 'Unsupported task capability.' using errcode='42501';end if;
 if jsonb_typeof(p_args) is distinct from 'object' then raise exception 'Invalid task arguments.' using errcode='22023';end if;
 if p_name in ('multideck_dexter_save_exchange','multideck_dexter_prepare_conversation') then p_args:=p_args||jsonb_build_object('p_conversation_id',a.conversation_id);end if;
 if p_name='multideck_dexter_save_exchange' then
  if p_args->'p_metadata'->>'taskRunId' is distinct from p_run::text then raise exception 'Task result identity required.' using errcode='42501';end if;
  -- Actual save deduplication happens below after installing the owner context.
 end if;
 if p_name='multideck_dexter_create_watch' then p_args:=p_args||'{"p_action":null}';end if;
 select u."Auth_User_ID" into actor from public."cmp_Users" u where u."User_ID"=a.owner_id;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',actor,'role','authenticated')::text,true);
 perform set_config('request.jwt.claim.sub',actor::text,true);perform set_config('request.jwt.claim.role','authenticated',true);
 if p_name='multideck_dexter_save_exchange' and exists(select 1 from public."AI_Messages" where "AIMSG_ConversationID"=a.conversation_id and "AIMSG_ContentJSON"->'metadata'->>'taskRunId'=p_run::text) then
  result:=public.multideck_dexter_get_conversation(a.conversation_id);
 else
  select p.* into proc from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname=p_name
   and not p.proretset and (select bool_and(k=any(p.proargnames)) from jsonb_object_keys(p_args) k) is not false
   order by p.pronargs desc limit 1;
  if proc.oid is null then raise exception 'Task capability is unavailable.' using errcode='42883';end if;
  select string_agg(format('%I => %s',proc.proargnames[i+1],case when format_type(proc.proargtypes[i],null) in ('jsonb','json') then format('($1->%L)::%s',proc.proargnames[i+1],format_type(proc.proargtypes[i],null))
   when format_type(proc.proargtypes[i],null) in ('uuid[]','text[]') then format('(case when $1->%L = ''null''::jsonb then null else array(select jsonb_array_elements_text($1->%L)) end)::%s',proc.proargnames[i+1],proc.proargnames[i+1],format_type(proc.proargtypes[i],null))
   else format('($1->>%L)::%s',proc.proargnames[i+1],format_type(proc.proargtypes[i],null)) end),',' order by i) into arguments
   from generate_series(0,proc.pronargs-1) i where p_args ? proc.proargnames[i+1];
  execute format('select to_jsonb(public.%I(%s))',p_name,coalesce(arguments,'')) into result using p_args;
 end if;
 perform set_config('request.jwt.claims',coalesce(claims,''),true);perform set_config('request.jwt.claim.sub',coalesce(sub,''),true);perform set_config('request.jwt.claim.role',coalesce(jwtrole,''),true);
 return result;
end $_$;


ALTER FUNCTION "public"."multideck_task_worker_rpc"("p_run" "uuid", "p_token" "uuid", "p_name" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."multideck_task_worker_secret"() RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
 if auth.role() is distinct from 'service_role' then raise exception 'Worker only.' using errcode='42501';end if;
 return (select decrypted_secret from vault.decrypted_secrets where name='multideck_task_worker_secret' limit 1);
end $$;


