CREATE OR REPLACE FUNCTION "public"."quote_workflow_bind_customer_response_document"("requested_response_link_id" "uuid", "requested_quote_document_id" "uuid") RETURNS boolean
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select quote_api.bind_customer_response_document(requested_response_link_id, requested_quote_document_id)
$$;


ALTER FUNCTION "public"."quote_workflow_bind_customer_response_document"("requested_response_link_id" "uuid", "requested_quote_document_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."quote_workflow_bind_customer_response_mailbox"("requested_response_link_id" "uuid", "requested_company_id" "uuid", "requested_user_id" "uuid", "requested_mailbox_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  updated_link_id uuid;
begin
  if not exists (
    select 1
    from public."cmp_Users" app_user
    where app_user."User_ID" = requested_user_id
      and app_user."Company_ID" = requested_company_id
      and app_user."User_AccessStatus" = 'active'
  ) then
    return false;
  end if;

  if not exists (
    select 1
    from public."Comm_Mailboxes" mailbox
    where mailbox."CommMailbox_ID" = requested_mailbox_id
      and not mailbox."CommMailbox_IsDeleted"
      and mailbox."CommMailbox_OutboundEnabled"
      and (
        mailbox."CommMailbox_UserID" = requested_user_id
        or exists (
          select 1
          from public."Comm_MailboxAccess" access
          where access."CommMailboxAccess_MailboxID" = mailbox."CommMailbox_ID"
            and access."CommMailboxAccess_UserID" = requested_user_id
            and access."CommMailboxAccess_CanSend"
            and access."CommMailboxAccess_RevokedAt" is null
            and (access."CommMailboxAccess_ExpiresAt" is null or access."CommMailboxAccess_ExpiresAt" > now())
        )
      )
  ) then
    return false;
  end if;

  update quote_api.customer_response_links link
  set delivery_mailbox_id = requested_mailbox_id
  where link.response_link_id = requested_response_link_id
    and link.company_id = requested_company_id
    and link.created_by = requested_user_id
    and link.delivery_status_code = 'pending'
  returning link.response_link_id into updated_link_id;

  return updated_link_id is not null;
end;
$$;


ALTER FUNCTION "public"."quote_workflow_bind_customer_response_mailbox"("requested_response_link_id" "uuid", "requested_company_id" "uuid", "requested_user_id" "uuid", "requested_mailbox_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."quote_workflow_bind_pending_customer_response_document_v4"("requested_response_link_id" "uuid", "requested_quote_document_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  link_row record;
begin
  select link.* into link_row
  from quote_api.customer_response_links link
  where link.response_link_id = requested_response_link_id
  for update;
  if not found then
    raise exception 'That quote response link could not be found.' using errcode = 'P0002';
  end if;
  if link_row.delivery_status_code <> 'pending' or link_row.status_code <> 'revoked' then
    raise exception 'That quote response is no longer awaiting delivery.' using errcode = '22023';
  end if;
  if not exists (
    select 1
    from public."DOC_StoredObjects" stored
    join public."cmp_Users" creator
      on creator."User_ID" = stored."DOCStoredObject_CreatedBy"
    where stored."DOCStoredObject_ID" = requested_quote_document_id
      and stored."DOCStoredObject_ConcernCode" = 'quote'
      and stored."DOCStoredObject_AggregateType" = 'CusQuote_Header'
      and stored."DOCStoredObject_AggregateID" = link_row.quote_id
      and stored."DOCStoredObject_MimeType" = 'application/pdf'
      and stored."DOCStoredObject_StatusCode" = 'active'
      and stored."DOCStoredObject_DeletedAt" is null
      and creator."Company_ID" = link_row.company_id
  ) then
    raise exception 'The quote PDF is outside this response link.' using errcode = '42501';
  end if;

  update quote_api.customer_response_links
  set quote_document_id = requested_quote_document_id
  where response_link_id = requested_response_link_id;
  return true;
end;
$$;


ALTER FUNCTION "public"."quote_workflow_bind_pending_customer_response_document_v4"("requested_response_link_id" "uuid", "requested_quote_document_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."quote_workflow_claim_due_follow_ups"("requested_lease_token" "uuid", "requested_limit" integer DEFAULT 2) RETURNS TABLE("response_link_id" "uuid", "company_id" "uuid", "quote_id" "uuid", "quote_reference" "text", "recipient_name" "text", "mailbox_id" "uuid", "source_message_id" "uuid", "actor_user_id" "uuid", "actor_auth_user_id" "uuid", "actor_email" "text", "actor_first_name" "text", "actor_last_name" "text", "attempt_number" integer)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
  with candidates as (
    select link.response_link_id
    from quote_api.customer_response_links link
    join public."CusQuote_Header" quote on quote."CusQuoteHeader_ID" = link.quote_id
    join public."cmp_Users" actor on actor."User_ID" = link.created_by
    where link.follow_up_status_code in ('pending','retryable','processing')
      and link.follow_up_next_attempt_at <= now()
      and (link.follow_up_lease_expires_at is null or link.follow_up_lease_expires_at <= now())
      and link.delivery_status_code = 'sent'
      and quote."CusQuoteHeader_LifecycleCode" = 'sent'
      and not quote."CusQuoteHeader_IsDeleted"
      and actor."User_AccessStatus" = 'active'
      and actor."Company_ID" = link.company_id
      and link.delivery_mailbox_id is not null
      and link.delivery_provider_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      and not exists (select 1 from quote_api.customer_responses response where response.response_link_id = link.response_link_id)
      and not exists (
        select 1 from quote_api.customer_response_links newer
        where newer.quote_id = link.quote_id and newer.delivery_status_code = 'sent' and newer.created_at > link.created_at
      )
    order by link.follow_up_next_attempt_at, link.created_at
    for update of link skip locked
    limit least(greatest(coalesce(requested_limit, 2), 1), 10)
  ), claimed as (
    update quote_api.customer_response_links link set
      follow_up_status_code = 'processing',
      follow_up_attempt_count = least(3, link.follow_up_attempt_count + case when link.follow_up_status_code = 'processing' then 0 else 1 end),
      follow_up_lease_token = requested_lease_token,
      follow_up_lease_expires_at = now() + interval '5 minutes'
    from candidates
    where link.response_link_id = candidates.response_link_id
    returning link.*
  )
  select claimed.response_link_id, claimed.company_id, claimed.quote_id,
    coalesce(quote."CusQuoteHeader_CustomerReference", 'Quote')::text,
    claimed.recipient_name::text, claimed.delivery_mailbox_id, claimed.delivery_provider_id::uuid,
    actor."User_ID", actor."Auth_User_ID", actor."User_Email"::text,
    actor."User_Firstname"::text, actor."User_Lastname"::text,
    claimed.follow_up_attempt_count::integer
  from claimed
  join public."CusQuote_Header" quote on quote."CusQuoteHeader_ID" = claimed.quote_id
  join public."cmp_Users" actor on actor."User_ID" = claimed.created_by;
$_$;


ALTER FUNCTION "public"."quote_workflow_claim_due_follow_ups"("requested_lease_token" "uuid", "requested_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."quote_workflow_disable_customer_response"("requested_response_link_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  update quote_api.customer_response_links set
    status_code = 'revoked',
    revoked_at = coalesce(revoked_at, now())
  where response_link_id = requested_response_link_id
    and delivery_mode_code = 'simple'
    and status_code = 'active';

  if found then return true; end if;
  if exists (
    select 1 from quote_api.customer_response_links
    where response_link_id = requested_response_link_id
      and delivery_mode_code = 'simple'
      and status_code = 'revoked'
  ) then
    return true;
  end if;
  raise exception 'That Simple quote delivery could not disable customer responses.' using errcode = '22023';
end;
$$;


