CREATE OR REPLACE FUNCTION "public"."quote_workflow_discard_draft"("caller_auth_user_id" "uuid", "requested_quote_id" "uuid", "requested_version_id" "uuid", "expected_snapshot" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor record; draft public."CusQuote_Versions"; target public."CusQuote_Versions"; saved jsonb; q public."CusQuote_Header"; prior_restore text;
begin
  if not coalesce(quote_api.has_permission(caller_auth_user_id,'Quotes.Write'),false) then
    raise exception 'Quote management is not authorised.' using errcode='42501';
  end if;
  select "User_ID","Company_ID" into strict actor from public."cmp_Users"
  where "Auth_User_ID"=caller_auth_user_id and "User_AccessStatus"='active';
  select header.* into q from public."CusQuote_Header" header
  join public."cmp_Offices" office on office."Office_ID"=coalesce(header."CusQuoteHeader_OrgOfficeID",header."OrgOffice_ID")
  where header."CusQuoteHeader_ID"=requested_quote_id and not header."CusQuoteHeader_IsDeleted"
    and office."Company_ID"=actor."Company_ID" for update of header;
  if not found then raise exception 'Quote is outside this workspace.' using errcode='42501'; end if;
  select * into draft from public."CusQuote_Versions" where "CusQuoteVersion_ID"=requested_version_id
    and "CusQuoteHeader_ID"=requested_quote_id and "Company_ID"=actor."Company_ID" for update;
  if not found then raise exception 'That draft is unavailable.' using errcode='22023'; end if;
  if draft."CusQuoteVersion_DiscardedAt" is not null then
    return jsonb_build_object('restoredVersionId',draft."CusQuoteVersion_DiscardedToID",'alreadyDiscarded',true);
  end if;
  if draft."CusQuoteVersion_IsSubmitted" or not draft."CusQuoteVersion_IsCurrent" then
    raise exception 'Only the current unsent working draft can be discarded.' using errcode='22023';
  end if;
  if draft."CusQuoteVersion_SnapshotJSON" is distinct from expected_snapshot then
    raise exception 'The draft changed after you opened it. Reload before discarding.' using errcode='40001';
  end if;
  if exists(select 1 from quote_api.customer_response_links where quote_version_id=requested_version_id)
    or exists(select 1 from quote_api.customer_responses where quote_version_id=requested_version_id) then
    raise exception 'This draft has delivery or response activity. Resolve that activity before discarding.' using errcode='22023';
  end if;
  select * into target from public."CusQuote_Versions"
  where "CusQuoteHeader_ID"=requested_quote_id and "CusQuoteVersion_IsSubmitted"
    and "CusQuoteVersion_DiscardedAt" is null
  order by ("CusQuoteVersion_StatusCode"='accepted') desc,"CusQuoteVersion_Number" desc limit 1 for update;
  if not found or jsonb_typeof(target."CusQuoteVersion_SnapshotJSON"->'quote') is distinct from 'object' then
    raise exception 'No readable submitted version is available to return to.' using errcode='22023';
  end if;
  -- Reuse the established Quote projection, but never issue, accept or convert.
  saved := public.quote_workflow_save_before_discard_20260909(caller_auth_user_id,requested_quote_id,target."CusQuoteVersion_SnapshotJSON"->'quote');
  if (saved->>'versionId')::uuid <> draft."CusQuoteVersion_ID" then
    raise exception 'The draft lifecycle changed. Reload before discarding.' using errcode='40001';
  end if;
  update public."CusQuote_Versions" set "CusQuoteVersion_IsCurrent"=false,
    "CusQuoteVersion_SnapshotJSON"=draft."CusQuoteVersion_SnapshotJSON",
    "CusQuoteVersion_DiscardedAt"=now(),"CusQuoteVersion_DiscardedToID"=target."CusQuoteVersion_ID"
    where "CusQuoteVersion_ID"=draft."CusQuoteVersion_ID";
  update public."CusQuote_Versions" set "CusQuoteVersion_IsCurrent"=true where "CusQuoteVersion_ID"=target."CusQuoteVersion_ID";
  prior_restore := current_setting('quote_api.discard_restore_quote',true);
  perform set_config('quote_api.discard_restore_quote',requested_quote_id::text,true);
  update public."CusQuote_Header" set "CusQuoteHeader_LifecycleCode"=target."CusQuoteVersion_StatusCode",
    "CusQuoteHeader_Status"=case target."CusQuoteVersion_StatusCode" when 'accepted' then 5 when 'declined' then 6 when 'sent' then 4 when 'submitted' then 4 else 1 end,
    "CusQuoteHeader_LastEditedDate"=now(),"CusQuoteHeader_LastEditedBy"=actor."User_ID"
    where "CusQuoteHeader_ID"=requested_quote_id;
  perform set_config('quote_api.discard_restore_quote',coalesce(prior_restore,''),true);
  insert into public."CusQuote_Events"("Company_ID","CusQuoteHeader_ID","CusQuoteVersion_ID","CusQuoteEvent_TypeCode","CusQuoteEvent_Summary","CusQuoteEvent_MetadataJSON","CusQuoteEvent_ActorUserID")
  values(actor."Company_ID",requested_quote_id,draft."CusQuoteVersion_ID",'draft_discarded',
    format('Working draft V%s discarded; returned to V%s.',draft."CusQuoteVersion_Number",target."CusQuoteVersion_Number"),
    jsonb_build_object('discardedVersionId',draft."CusQuoteVersion_ID",'restoredVersionId',target."CusQuoteVersion_ID"),actor."User_ID");
  return jsonb_build_object('restoredVersionId',target."CusQuoteVersion_ID",'restoredVersionNumber',target."CusQuoteVersion_Number");
end;
$$;


ALTER FUNCTION "public"."quote_workflow_discard_draft"("caller_auth_user_id" "uuid", "requested_quote_id" "uuid", "requested_version_id" "uuid", "expected_snapshot" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."quote_workflow_fail_customer_response_v4"("requested_response_link_id" "uuid", "requested_error" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  link_row record;
begin
  select link.* into link_row
  from quote_api.customer_response_links link
  where link.response_link_id = requested_response_link_id
  for update;
  if not found then
    raise exception 'The quote response link was not found.' using errcode = 'P0002';
  end if;
  if link_row.delivery_status_code = 'sent' then
    return false;
  end if;

  update quote_api.customer_response_links set
    status_code = 'revoked',
    revoked_at = coalesce(revoked_at, now()),
    delivery_status_code = 'failed',
    delivery_provider_id = null,
    delivery_error = left(coalesce(nullif(btrim(requested_error), ''), 'Quote email delivery failed.'), 2000)
  where response_link_id = requested_response_link_id;

  insert into public."CusQuote_Events" (
    "Company_ID", "CusQuoteHeader_ID", "CusQuoteVersion_ID", "CusQuoteEvent_TypeCode",
    "CusQuoteEvent_Summary", "CusQuoteEvent_MetadataJSON", "CusQuoteEvent_ActorUserID"
  ) values (
    link_row.company_id, link_row.quote_id, link_row.quote_version_id, 'customer_delivery_failed',
    'Quote email delivery failed before submission.',
    jsonb_build_object(
      'responseLinkId', link_row.response_link_id,
      'recipientEmail', link_row.recipient_email,
      'deliveryMode', link_row.delivery_mode_code,
      'message', left(coalesce(nullif(btrim(requested_error), ''), 'Quote email delivery failed.'), 2000)
    ),
    link_row.created_by
  );
  return true;
end;
$$;


ALTER FUNCTION "public"."quote_workflow_fail_customer_response_v4"("requested_response_link_id" "uuid", "requested_error" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."quote_workflow_finalize_customer_response_pre_fu_20260904"("requested_response_link_id" "uuid", "requested_provider_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  link_row record;
  quote_row record;
  version_number integer;
  reissue boolean;
  final_status text;
begin
  select link.* into link_row
  from quote_api.customer_response_links link
  where link.response_link_id = requested_response_link_id
  for update;
  if not found then
    raise exception 'The quote response link was not found.' using errcode = 'P0002';
  end if;

  select quote.* into strict quote_row
  from public."CusQuote_Header" quote
  where quote."CusQuoteHeader_ID" = link_row.quote_id
  for update;
  select version."CusQuoteVersion_Number" into strict version_number
  from public."CusQuote_Versions" version
  where version."CusQuoteVersion_ID" = link_row.quote_version_id
    and version."CusQuoteHeader_ID" = link_row.quote_id;

  if link_row.delivery_status_code = 'sent' then
    return jsonb_build_object(
      'responseLinkId', link_row.response_link_id,
      'quoteId', link_row.quote_id,
      'quoteVersionId', link_row.quote_version_id,
      'versionNumber', version_number,
      'reference', coalesce(quote_row."CusQuoteHeader_CustomerReference", 'Q-' || quote_row."CusQuoteHeader_Number"),
      'expiresAt', link_row.expires_at,
      'recipientEmail', link_row.recipient_email,
      'deliveryMode', link_row.delivery_mode_code,
      'recipientSource', link_row.recipient_source_code
    );
  end if;
  if link_row.delivery_status_code <> 'pending' or link_row.status_code <> 'revoked' then
    raise exception 'That quote response is no longer awaiting delivery.' using errcode = '22023';
  end if;
  if link_row.quote_document_id is null then
    raise exception 'Attach the generated quote PDF before finalising delivery.' using errcode = '22023';
  end if;

  select exists (
    select 1 from quote_api.customer_response_links previous
    where previous.quote_id = link_row.quote_id
      and previous.response_link_id <> link_row.response_link_id
      and previous.delivery_status_code = 'sent'
  ) into reissue;

  update quote_api.customer_response_links
  set status_code = 'revoked', revoked_at = now()
  where quote_id = link_row.quote_id
    and response_link_id <> link_row.response_link_id
    and status_code = 'active';

  final_status := case when link_row.delivery_mode_code = 'standard' then 'active' else 'revoked' end;
  update quote_api.customer_response_links set
    status_code = final_status,
    revoked_at = case when final_status = 'revoked' then now() else null end,
    delivery_status_code = 'sent',
    delivery_provider_id = left(nullif(btrim(requested_provider_id), ''), 180),
    delivery_error = null
  where response_link_id = link_row.response_link_id;

  update public."CusQuote_Header" set
    "CusQuoteHeader_LifecycleCode" = 'sent',
    "CusQuoteHeader_Status" = 4,
    "CusQuoteHeader_ContactEmailSnapshot" = case
      when link_row.recipient_source_code = 'saved' then link_row.recipient_email
      else "CusQuoteHeader_ContactEmailSnapshot"
    end,
    "CusQuoteHeader_ContactNameSnapshot" = case
      when link_row.recipient_source_code = 'saved' then coalesce(link_row.recipient_name, "CusQuoteHeader_ContactNameSnapshot")
      else "CusQuoteHeader_ContactNameSnapshot"
    end,
    "CusQuoteHeader_LastEditedBy" = link_row.created_by,
    "CusQuoteHeader_LastEditedDate" = now()
  where "CusQuoteHeader_ID" = link_row.quote_id;

  insert into public."CusQuote_Events" (
    "Company_ID", "CusQuoteHeader_ID", "CusQuoteVersion_ID", "CusQuoteEvent_TypeCode",
    "CusQuoteEvent_Summary", "CusQuoteEvent_MetadataJSON", "CusQuoteEvent_ActorUserID"
  ) values (
    link_row.company_id, link_row.quote_id, link_row.quote_version_id, 'customer_link_issued',
    case
      when link_row.delivery_mode_code = 'simple' then 'Simple quote email sent without customer response controls.'
      else 'Secure customer response link sent.'
    end,
    jsonb_build_object(
      'responseLinkId', link_row.response_link_id,
      'recipientEmail', link_row.recipient_email,
      'responseOrigin', link_row.response_origin,
      'expiresAt', link_row.expires_at,
      'deliveryMode', link_row.delivery_mode_code,
      'recipientSource', link_row.recipient_source_code,
      'responseControlsEnabled', link_row.delivery_mode_code = 'standard',
      'quoteDocumentId', link_row.quote_document_id,
      'versionNumber', version_number,
      'providerId', left(nullif(btrim(requested_provider_id), ''), 180),
      'reissue', reissue
    ),
    link_row.created_by
  );

  return jsonb_build_object(
    'responseLinkId', link_row.response_link_id,
    'quoteId', link_row.quote_id,
    'quoteVersionId', link_row.quote_version_id,
    'versionNumber', version_number,
    'reference', coalesce(quote_row."CusQuoteHeader_CustomerReference", 'Q-' || quote_row."CusQuoteHeader_Number"),
    'expiresAt', link_row.expires_at,
    'responseOrigin', link_row.response_origin,
    'recipientEmail', link_row.recipient_email,
    'deliveryMode', link_row.delivery_mode_code,
    'recipientSource', link_row.recipient_source_code
  );
end;
$$;


ALTER FUNCTION "public"."quote_workflow_finalize_customer_response_pre_fu_20260904"("requested_response_link_id" "uuid", "requested_provider_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."quote_workflow_finalize_customer_response_pre_fu_20260904"("requested_response_link_id" "uuid", "requested_provider_id" "text") IS 'After confirmed mail delivery, atomically freezes the version, records submission, and switches the active response link.';



CREATE OR REPLACE FUNCTION "public"."quote_workflow_finalize_customer_response_v4"("requested_response_link_id" "uuid", "requested_provider_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  result jsonb;
  follow_up_at timestamptz;
begin
  result := public.quote_workflow_finalize_customer_response_pre_fu_20260904(
    requested_response_link_id, requested_provider_id
  );
  follow_up_at := quote_api.schedule_customer_follow_up(requested_response_link_id);
  return result || jsonb_strip_nulls(jsonb_build_object('followUpAt', follow_up_at));
end;
$$;


ALTER FUNCTION "public"."quote_workflow_finalize_customer_response_v4"("requested_response_link_id" "uuid", "requested_provider_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."quote_workflow_finish_follow_up"("requested_response_link_id" "uuid", "requested_lease_token" "uuid", "requested_sent" boolean, "requested_provider_id" "text" DEFAULT NULL::"text", "requested_error" "text" DEFAULT NULL::"text", "requested_retryable" boolean DEFAULT false) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  link_row quote_api.customer_response_links%rowtype;
  terminal_failure boolean;
begin
  select * into link_row from quote_api.customer_response_links
  where response_link_id = requested_response_link_id
    and follow_up_status_code = 'processing'
    and follow_up_lease_token = requested_lease_token
  for update;
  if not found then return false; end if;

  if requested_sent then
    update quote_api.customer_response_links set
      follow_up_status_code = 'sent', follow_up_sent_at = now(), follow_up_next_attempt_at = null,
      follow_up_delivery_provider_id = left(nullif(btrim(requested_provider_id), ''), 180),
      follow_up_error = null, follow_up_lease_token = null, follow_up_lease_expires_at = null
    where response_link_id = requested_response_link_id;
    update public."CusQuote_Header" set "CusQuoteHeader_FollowUpAt" = null,
      "CusQuoteHeader_LastEditedDate" = now()
    where "CusQuoteHeader_ID" = link_row.quote_id;
    insert into public."CusQuote_Events" (
      "Company_ID", "CusQuoteHeader_ID", "CusQuoteVersion_ID", "CusQuoteEvent_TypeCode",
      "CusQuoteEvent_Summary", "CusQuoteEvent_MetadataJSON", "CusQuoteEvent_ActorUserID"
    ) values (
      link_row.company_id, link_row.quote_id, link_row.quote_version_id, 'customer_follow_up_sent',
      'Automatic quote follow-up sent.',
      jsonb_build_object('responseLinkId', link_row.response_link_id, 'recipientEmail', link_row.recipient_email, 'attempt', link_row.follow_up_attempt_count),
      link_row.created_by
    );
    return true;
  end if;

  terminal_failure := not coalesce(requested_retryable, false) or link_row.follow_up_attempt_count >= 3;
  update quote_api.customer_response_links set
    follow_up_status_code = case when terminal_failure then 'failed' else 'retryable' end,
    follow_up_next_attempt_at = case when terminal_failure then null else now() + case link_row.follow_up_attempt_count when 1 then interval '15 minutes' else interval '1 hour' end end,
    follow_up_error = left(coalesce(nullif(btrim(requested_error), ''), 'Quote follow-up delivery failed.'), 2000),
    follow_up_lease_token = null, follow_up_lease_expires_at = null
  where response_link_id = requested_response_link_id;
  if terminal_failure then
    insert into public."CusQuote_Events" (
      "Company_ID", "CusQuoteHeader_ID", "CusQuoteVersion_ID", "CusQuoteEvent_TypeCode",
      "CusQuoteEvent_Summary", "CusQuoteEvent_MetadataJSON", "CusQuoteEvent_ActorUserID"
    ) values (
      link_row.company_id, link_row.quote_id, link_row.quote_version_id, 'customer_follow_up_failed',
      'Automatic quote follow-up needs manual attention.',
      jsonb_build_object('responseLinkId', link_row.response_link_id, 'recipientEmail', link_row.recipient_email, 'attempts', link_row.follow_up_attempt_count, 'message', left(coalesce(requested_error, ''), 1000)),
      link_row.created_by
    );
  end if;
  return true;
end;
$$;


ALTER FUNCTION "public"."quote_workflow_finish_follow_up"("requested_response_link_id" "uuid", "requested_lease_token" "uuid", "requested_sent" boolean, "requested_provider_id" "text", "requested_error" "text", "requested_retryable" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."quote_workflow_get_follow_up_settings"("caller_auth_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  company_id_value uuid;
  settings_row quote_api.reference_settings%rowtype;
begin
  select app_user."Company_ID" into company_id_value
  from public."cmp_Users" app_user
  where app_user."Auth_User_ID" = caller_auth_user_id
    and app_user."User_AccessStatus" = 'active';
  if company_id_value is null then
    raise exception 'User identity is incomplete.' using errcode = '42501';
  end if;
  select * into settings_row from quote_api.reference_settings where company_id = company_id_value;
  return jsonb_build_object(
    'enabled', coalesce(settings_row.quote_follow_up_enabled, true),
    'defaultDelayDays', coalesce(settings_row.quote_follow_up_delay_days, 3),
    'sendTime', to_char(coalesce(settings_row.quote_follow_up_send_time, time '09:00'), 'HH24:MI'),
    'timezone', coalesce(settings_row.quote_follow_up_timezone, 'Europe/London')
  );
end;
$$;


ALTER FUNCTION "public"."quote_workflow_get_follow_up_settings"("caller_auth_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."quote_workflow_get_reference_settings"("caller_auth_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'quote_api'
    AS $$
declare
  workspace_company_id uuid;
  settings_row quote_api.reference_settings%rowtype;
  booking_patterns_value jsonb;
  company_name_value text;
begin
  select app_user."Company_ID", company."Company_Name"
    into workspace_company_id, company_name_value
  from public."cmp_Users" app_user
  join public."cmp_Company" company on company."Company_ID" = app_user."Company_ID"
  where app_user."Auth_User_ID" = caller_auth_user_id and app_user."User_AccessStatus" = 'active';
  if workspace_company_id is null then
    raise exception 'User identity is incomplete.' using errcode = '42501';
  end if;
  select * into settings_row from quote_api.reference_settings where company_id = workspace_company_id;
  select coalesce(jsonb_agg(jsonb_build_object(
    'key', sequence_key, 'label', label, 'pattern', pattern,
    'nextNumber', next_number, 'enabled', enabled
  ) order by case when sequence_key = 'default' then 0 else 1 end, label), '[]'::jsonb)
  into booking_patterns_value
  from quote_api.booking_reference_sequences
  where company_id = workspace_company_id and enabled;
  if jsonb_array_length(booking_patterns_value) = 0 then
    booking_patterns_value := jsonb_build_array(jsonb_build_object(
      'key', 'default', 'label', 'Default booking', 'pattern', 'B-{NUMBER:4}', 'nextNumber', 1, 'enabled', true
    ));
  end if;
  return jsonb_build_object(
    'companyName', company_name_value,
    'quotePattern', coalesce(settings_row.quote_pattern, 'Q-{NUMBER:4}'),
    'quoteNextNumber', coalesce(settings_row.quote_next_number, 1),
    'bookingPatterns', booking_patterns_value,
    'customerPattern', coalesce(settings_row.customer_pattern, 'CUS{NUMBER:4}'),
    'customerNextNumber', coalesce(settings_row.customer_next_number, 1)
  );
end;
$$;


