CREATE OR REPLACE FUNCTION "public"."quote_workflow_issue_customer_response_v2"("caller_auth_user_id" "uuid", "requested_quote_id" "uuid", "requested_recipient_name" "text", "requested_recipient_email" "text", "requested_recipient_source" "text", "requested_delivery_mode" "text", "requested_response_origin" "text", "requested_token_hash" "text", "requested_expires_at" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  previous_contact_name text;
  previous_contact_email text;
  issued jsonb;
  link_id uuid;
begin
  if requested_recipient_source not in ('saved', 'manual') then
    raise exception 'Choose a saved contact or a manual email address.' using errcode = '22023';
  end if;
  if requested_delivery_mode not in ('standard', 'simple') then
    raise exception 'Choose Standard or Simple quote delivery.' using errcode = '22023';
  end if;

  select "CusQuoteHeader_ContactNameSnapshot", "CusQuoteHeader_ContactEmailSnapshot"
  into previous_contact_name, previous_contact_email
  from public."CusQuote_Header"
  where "CusQuoteHeader_ID" = requested_quote_id
  for update;

  issued := quote_api.issue_customer_response(
    caller_auth_user_id,
    requested_quote_id,
    requested_recipient_name,
    requested_recipient_email,
    requested_response_origin,
    requested_token_hash,
    requested_expires_at
  );
  link_id := (issued ->> 'responseLinkId')::uuid;

  update quote_api.customer_response_links set
    delivery_mode_code = requested_delivery_mode,
    recipient_source_code = requested_recipient_source
  where response_link_id = link_id;

  if requested_recipient_source = 'manual' then
    update public."CusQuote_Header" set
      "CusQuoteHeader_ContactNameSnapshot" = previous_contact_name,
      "CusQuoteHeader_ContactEmailSnapshot" = previous_contact_email
    where "CusQuoteHeader_ID" = requested_quote_id;
  end if;

  update public."CusQuote_Events" set
    "CusQuoteEvent_Summary" = case
      when requested_delivery_mode = 'simple' then 'Simple quote email prepared without customer response controls.'
      else 'Secure customer response link issued.'
    end,
    "CusQuoteEvent_MetadataJSON" = coalesce("CusQuoteEvent_MetadataJSON", '{}'::jsonb)
      || jsonb_build_object(
        'deliveryMode', requested_delivery_mode,
        'recipientSource', requested_recipient_source,
        'recipientEmail', lower(btrim(requested_recipient_email)),
        'responseControlsEnabled', requested_delivery_mode = 'standard'
      )
  where "CusQuoteHeader_ID" = requested_quote_id
    and "CusQuoteEvent_TypeCode" = 'customer_link_issued'
    and "CusQuoteEvent_MetadataJSON" ->> 'responseLinkId' = link_id::text;

  return issued || jsonb_build_object(
    'deliveryMode', requested_delivery_mode,
    'recipientSource', requested_recipient_source
  );
end;
$$;


ALTER FUNCTION "public"."quote_workflow_issue_customer_response_v2"("caller_auth_user_id" "uuid", "requested_quote_id" "uuid", "requested_recipient_name" "text", "requested_recipient_email" "text", "requested_recipient_source" "text", "requested_delivery_mode" "text", "requested_response_origin" "text", "requested_token_hash" "text", "requested_expires_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."quote_workflow_issue_customer_response_v3"("caller_auth_user_id" "uuid", "requested_quote_id" "uuid", "requested_recipient_name" "text", "requested_recipient_email" "text", "requested_recipient_source" "text", "requested_delivery_mode" "text", "requested_response_origin" "text", "requested_token_hash" "text", "requested_expires_at" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  previous_contact_name text;
  previous_contact_email text;
  issued jsonb;
  link_id uuid;
begin
  if requested_recipient_source not in ('saved', 'manual') then
    raise exception 'Choose a saved contact or a manual email address.' using errcode = '22023';
  end if;
  if requested_delivery_mode not in ('standard', 'simple') then
    raise exception 'Choose Standard or Simple quote delivery.' using errcode = '22023';
  end if;

  if quote_api.has_permission(caller_auth_user_id, 'Quotes.Write')
     and exists (
       select 1
       from public."CusQuote_Header" quote
       join public."cmp_Offices" office
         on office."Office_ID" = coalesce(quote."CusQuoteHeader_OrgOfficeID", quote."OrgOffice_ID")
       join public."cmp_Users" app_user
         on app_user."Auth_User_ID" = caller_auth_user_id
        and app_user."Company_ID" = office."Company_ID"
        and app_user."User_AccessStatus" = 'active'
       where quote."CusQuoteHeader_ID" = requested_quote_id
         and quote."CusQuoteHeader_LifecycleCode" = 'accepted'
         and not quote."CusQuoteHeader_IsDeleted"
     ) then
    update public."CusQuote_Header" set
      "CusQuoteHeader_LifecycleCode" = 'revised',
      "CusQuoteHeader_Status" = 1
    where "CusQuoteHeader_ID" = requested_quote_id;
  end if;

  select "CusQuoteHeader_ContactNameSnapshot", "CusQuoteHeader_ContactEmailSnapshot"
  into previous_contact_name, previous_contact_email
  from public."CusQuote_Header"
  where "CusQuoteHeader_ID" = requested_quote_id
  for update;

  issued := quote_api.issue_customer_response(
    caller_auth_user_id,
    requested_quote_id,
    requested_recipient_name,
    requested_recipient_email,
    requested_response_origin,
    requested_token_hash,
    requested_expires_at
  );
  link_id := (issued ->> 'responseLinkId')::uuid;

  update quote_api.customer_response_links set
    delivery_mode_code = requested_delivery_mode,
    recipient_source_code = requested_recipient_source
  where response_link_id = link_id;

  if requested_recipient_source = 'manual' then
    update public."CusQuote_Header" set
      "CusQuoteHeader_ContactNameSnapshot" = previous_contact_name,
      "CusQuoteHeader_ContactEmailSnapshot" = previous_contact_email
    where "CusQuoteHeader_ID" = requested_quote_id;
  end if;

  update public."CusQuote_Events" set
    "CusQuoteEvent_Summary" = case
      when requested_delivery_mode = 'simple' then 'Simple quote email prepared without customer response controls.'
      else 'Secure customer response link issued.'
    end,
    "CusQuoteEvent_MetadataJSON" = coalesce("CusQuoteEvent_MetadataJSON", '{}'::jsonb)
      || jsonb_build_object(
        'deliveryMode', requested_delivery_mode,
        'recipientSource', requested_recipient_source,
        'recipientEmail', lower(btrim(requested_recipient_email)),
        'responseControlsEnabled', requested_delivery_mode = 'standard',
        'reissue', true
      )
  where "CusQuoteHeader_ID" = requested_quote_id
    and "CusQuoteEvent_TypeCode" = 'customer_link_issued'
    and "CusQuoteEvent_MetadataJSON" ->> 'responseLinkId' = link_id::text;

  return issued || jsonb_build_object(
    'deliveryMode', requested_delivery_mode,
    'recipientSource', requested_recipient_source
  );
end;
$$;


ALTER FUNCTION "public"."quote_workflow_issue_customer_response_v3"("caller_auth_user_id" "uuid", "requested_quote_id" "uuid", "requested_recipient_name" "text", "requested_recipient_email" "text", "requested_recipient_source" "text", "requested_delivery_mode" "text", "requested_response_origin" "text", "requested_token_hash" "text", "requested_expires_at" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."quote_workflow_issue_customer_response_v3"("caller_auth_user_id" "uuid", "requested_quote_id" "uuid", "requested_recipient_name" "text", "requested_recipient_email" "text", "requested_recipient_source" "text", "requested_delivery_mode" "text", "requested_response_origin" "text", "requested_token_hash" "text", "requested_expires_at" timestamp with time zone) IS 'Issues or reissues the latest saved quote version. Reissuing starts a new customer response cycle while preserving prior accepted-version and booking evidence. Direct sending remains outside Dexter and requires the operator quote-send review flow.';



CREATE OR REPLACE FUNCTION "public"."quote_workflow_latest_customer_response_issue"("caller_auth_user_id" "uuid", "requested_quote_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  app_company_id uuid;
  issue jsonb;
begin
  if caller_auth_user_id is null
     or not quote_api.has_permission(caller_auth_user_id, 'Quotes.Read') then
    raise exception 'Quote access is not authorised.' using errcode = '42501';
  end if;
  select "Company_ID" into strict app_company_id
  from public."cmp_Users"
  where "Auth_User_ID" = caller_auth_user_id
    and "User_AccessStatus" = 'active';
  if not exists (
    select 1
    from public."CusQuote_Header" quote
    join public."cmp_Offices" office
      on office."Office_ID" = coalesce(quote."CusQuoteHeader_OrgOfficeID", quote."OrgOffice_ID")
    where quote."CusQuoteHeader_ID" = requested_quote_id
      and office."Company_ID" = app_company_id
      and not quote."CusQuoteHeader_IsDeleted"
  ) then
    raise exception 'That quote is outside this workspace.' using errcode = '42501';
  end if;

  select jsonb_strip_nulls(jsonb_build_object(
    'responseLinkId', link.response_link_id,
    'quoteDocumentId', link.quote_document_id,
    'deliveryMode', link.delivery_mode_code,
    'responseControlsEnabled', link.delivery_mode_code = 'standard',
    'recipientSource', link.recipient_source_code,
    'recipientName', link.recipient_name,
    'recipientEmail', link.recipient_email,
    'deliveryStatus', link.delivery_status_code,
    'responseStatus', link.status_code,
    'createdAt', link.created_at
  )) into issue
  from quote_api.customer_response_links link
  where link.quote_id = requested_quote_id
    and link.company_id = app_company_id
    and link.delivery_status_code = 'sent'
  order by link.created_at desc
  limit 1;

  return issue;
exception
  when no_data_found or too_many_rows then
    raise exception 'User identity is incomplete or ambiguous.' using errcode = '42501';
end;
$$;


ALTER FUNCTION "public"."quote_workflow_latest_customer_response_issue"("caller_auth_user_id" "uuid", "requested_quote_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."quote_workflow_mark_customer_response_delivery"("requested_response_link_id" "uuid", "requested_status" "text", "requested_provider_id" "text" DEFAULT NULL::"text", "requested_error" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if requested_status not in ('sent','failed') then
    raise exception 'Choose a valid quote delivery status.' using errcode = '22023';
  end if;
  update quote_api.customer_response_links set
    delivery_status_code = requested_status,
    delivery_provider_id = left(nullif(btrim(requested_provider_id), ''), 180),
    delivery_error = case when requested_status = 'failed' then left(nullif(btrim(requested_error), ''), 2000) else null end
  where response_link_id = requested_response_link_id;
  if not found then raise exception 'The quote response link was not found.' using errcode = 'P0002'; end if;
end;
$$;


