CREATE OR REPLACE FUNCTION "public"."quote_workflow_recent_company_email_samples"("requested_user_id" "uuid", "requested_quote_id" "uuid", "requested_limit" integer DEFAULT 5) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  app_user record;
  quote_row record;
  take_count integer := least(5, greatest(1, coalesce(requested_limit, 5)));
  result_value jsonb;
begin
  select "User_ID", "Company_ID" into strict app_user
  from public."cmp_Users"
  where "User_ID" = requested_user_id
    and "User_AccessStatus" = 'active';

  if not public._multideck_dexter_has_permission(app_user."User_ID", 'Email.Read')
     or not public._multideck_dexter_has_permission(app_user."User_ID", 'Email.AIRead') then
    return jsonb_build_object('messages', '[]'::jsonb, 'sampleCount', 0);
  end if;

  select quote.* into quote_row
  from public."CusQuote_Header" quote
  join public."cmp_Offices" office
    on office."Office_ID" = coalesce(quote."CusQuoteHeader_OrgOfficeID", quote."OrgOffice_ID")
  where quote."CusQuoteHeader_ID" = requested_quote_id
    and office."Company_ID" = app_user."Company_ID"
    and not quote."CusQuoteHeader_IsDeleted";
  if not found or quote_row."CusQuoteHeader_CustomerID" is null then
    raise exception 'That quote is outside this workspace.' using errcode = '42501';
  end if;

  with company_emails as materialized (
    select lower(btrim(email."OrgContactEmail_Email")) as address
    from public."Org_Contacts" contact
    join public."OrgContact_Emails" email
      on email."OrgContact_ID" = contact."OrgContact_ID"
     and email."OrgContactEmail_IsActive"
    where contact."Org_ID" = quote_row."CusQuoteHeader_CustomerID"
    union
    select lower(btrim(address."OrgAdd_MainEmail"))
    from public."Org_Addresses" address
    where address."Org_ID" = quote_row."CusQuoteHeader_CustomerID"
      and address."OrgAdd_IsActive"
      and nullif(btrim(address."OrgAdd_MainEmail"), '') is not null
    union
    select lower(btrim(quote_row."CusQuoteHeader_ContactEmailSnapshot"))
    where nullif(btrim(quote_row."CusQuoteHeader_ContactEmailSnapshot"), '') is not null
  ),
  permitted_mailboxes as materialized (
    select permitted.mailbox_id
    from public._multideck_dexter_email_mailboxes(app_user."User_ID", app_user."Company_ID") permitted
  ),
  selected as (
    select
      message."CommMessage_ID" as message_id,
      message."CommMessage_BodyText" as body_text,
      coalesce(message."CommMessage_MessageDate", message."CommMessage_SentAt", message."CommMessage_CreatedAt") as occurred_at
    from public."Comm_Messages" message
    join permitted_mailboxes permitted on permitted.mailbox_id = message."CommMessage_MailboxID"
    join public."Comm_Mailboxes" mailbox on mailbox."CommMailbox_ID" = message."CommMessage_MailboxID"
    join public."Comm_ProviderConnections" connection on connection."CommConn_ID" = mailbox."CommMailbox_ConnectionID"
    where message."CommMessage_DirectionCode" = 'outbound'
      and not message."CommMessage_IsInbound"
      and message."CommMessage_StatusCode" in ('sent', 'delivered')
      and not message."CommMessage_IsDraft"
      and not message."CommMessage_IsSpam"
      and not message."CommMessage_IsDeleted"
      and not message."CommMessage_IsBodyRedacted"
      and nullif(btrim(message."CommMessage_BodyText"), '') is not null
      and char_length(btrim(message."CommMessage_BodyText")) between 40 and 12000
      and coalesce(message."CommMessage_MessageDate", message."CommMessage_SentAt", message."CommMessage_CreatedAt") >= now() - interval '12 months'
      and (
        (
          mailbox."CommMailbox_TypeCode" = 'personal'
          and mailbox."CommMailbox_UserID" = app_user."User_ID"
          and connection."CommConn_UserID" = app_user."User_ID"
        )
        or message."CommMessage_CreatedBy" = app_user."User_ID"
      )
      and (
        exists (
          select 1
          from public."Comm_MessageRecipients" recipient
          join company_emails company_email
            on company_email.address = lower(btrim(recipient."CommRecipient_NormalizedAddress"))
          where recipient."CommRecipient_MessageID" = message."CommMessage_ID"
            and recipient."CommRecipient_RecipientTypeCode" in ('to', 'cc')
            and recipient."CommRecipient_IsExternal"
            and not recipient."CommRecipient_IsSuppressed"
        )
        or exists (
          select 1 from public."Comm_Threads" thread
          where thread."CommThread_ID" = message."CommMessage_ThreadID"
            and thread."CommThread_CustomerOrgID" = quote_row."CusQuoteHeader_CustomerID"
            and not thread."CommThread_IsDeleted"
        )
      )
      and lower(coalesce(message."CommMessage_Subject", '') || ' ' || left(message."CommMessage_BodyText", 800)) !~
        '(automatic reply|auto.?reply|out of office|undeliverable|delivery status|mail delivery|do.?not.?reply|no.?reply|newsletter|unsubscribe|password reset|verification code|support ticket)'
    order by occurred_at desc nulls last, message."CommMessage_ID" desc
    limit take_count
  )
  select jsonb_build_object(
    'messages', coalesce(jsonb_agg(jsonb_build_object(
      'messageId', selected.message_id,
      'bodyText', selected.body_text,
      'occurredAt', selected.occurred_at
    ) order by selected.occurred_at desc, selected.message_id desc), '[]'::jsonb),
    'sampleCount', count(*)
  ) into result_value
  from selected;

  return coalesce(result_value, jsonb_build_object('messages', '[]'::jsonb, 'sampleCount', 0));
exception
  when no_data_found then
    raise exception 'The signed-in quote user could not be verified.' using errcode = '42501';
end;
$$;


ALTER FUNCTION "public"."quote_workflow_recent_company_email_samples"("requested_user_id" "uuid", "requested_quote_id" "uuid", "requested_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."quote_workflow_save_before_discard_20260909"("caller_auth_user_id" "uuid", "requested_quote_id" "uuid", "payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  copy_reason text := nullif(payload #>> '{shipmentFacts,copyReason}', '');
  source_quote_id uuid;
  source_quote_reference text;
  source_customer_id uuid;
  target_customer_id uuid := nullif(payload ->> 'customerId', '')::uuid;
  actor_company_id uuid;
  saved jsonb;
  saved_quote_id uuid;
  saved_version_id uuid;
  target_quote_reference text;
  committed_events jsonb;
begin
  if requested_quote_id is null and copy_reason = 'repeat_quote' then
    if coalesce(payload #>> '{shipmentFacts,copiedFromQuoteId}', '')
       !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
      raise exception 'Choose a valid source quote before creating a repeat quote.'
        using errcode = '22023';
    end if;

    source_quote_id := (payload #>> '{shipmentFacts,copiedFromQuoteId}')::uuid;

    select app_user."Company_ID"
      into strict actor_company_id
    from public."cmp_Users" app_user
    where app_user."Auth_User_ID" = caller_auth_user_id
      and app_user."User_AccessStatus" = 'active';

    select source_quote."CusQuoteHeader_CustomerID",
      coalesce(
        nullif(payload #>> '{shipmentFacts,copiedFromQuoteReference}', ''),
        current_version."CusQuoteVersion_SnapshotJSON" ->> 'reference',
        'Q-' || source_quote."CusQuoteHeader_Number"
      )
      into source_customer_id, source_quote_reference
    from public."CusQuote_Header" source_quote
    join public."cmp_Offices" source_office
      on source_office."Office_ID" = coalesce(source_quote."CusQuoteHeader_OrgOfficeID", source_quote."OrgOffice_ID")
     and source_office."Company_ID" = actor_company_id
    left join lateral (
      select version."CusQuoteVersion_SnapshotJSON"
      from public."CusQuote_Versions" version
      where version."CusQuoteHeader_ID" = source_quote."CusQuoteHeader_ID"
      order by version."CusQuoteVersion_IsCurrent" desc, version."CusQuoteVersion_Number" desc
      limit 1
    ) current_version on true
    where source_quote."CusQuoteHeader_ID" = source_quote_id
      and not source_quote."CusQuoteHeader_IsDeleted";

    if not found then
      raise exception 'The source quote is not available in this workspace.'
        using errcode = '42501';
    end if;

    if target_customer_id is null or target_customer_id is distinct from source_customer_id then
      raise exception 'A repeat quote must keep the source quote customer.'
        using errcode = '22023';
    end if;
  elsif copy_reason is not null and copy_reason <> 'customer_changed' then
    raise exception 'Unsupported quote copy reason.' using errcode = '22023';
  end if;

  saved := public.quote_workflow_save_quote_before_repeat_20260904(
    caller_auth_user_id,
    requested_quote_id,
    payload
  );

  if requested_quote_id is null and copy_reason = 'repeat_quote' then
    saved_quote_id := (saved ->> 'quoteId')::uuid;
    saved_version_id := (saved ->> 'versionId')::uuid;
    target_quote_reference := saved ->> 'reference';

    update public."CusQuote_Events"
    set
      "CusQuoteEvent_Summary" = 'Repeat quote created from ' || source_quote_reference || '.',
      "CusQuoteEvent_MetadataJSON" = (coalesce("CusQuoteEvent_MetadataJSON", '{}'::jsonb) - 'copyReason')
        || jsonb_build_object(
          'copyReason', 'repeat_quote',
          'scheduleReset', true,
          'commercialValuesReset', true
        )
    where "CusQuoteHeader_ID" = saved_quote_id
      and "CusQuoteVersion_ID" = saved_version_id
      and "CusQuoteEvent_TypeCode" = 'created';

    update public."CusQuote_Events"
    set
      "CusQuoteEvent_Summary" = 'Quote copied to ' || target_quote_reference || ' as a repeat enquiry.',
      "CusQuoteEvent_MetadataJSON" = (coalesce("CusQuoteEvent_MetadataJSON", '{}'::jsonb) - 'copyReason')
        || jsonb_build_object(
          'copyReason', 'repeat_quote',
          'scheduleReset', true,
          'commercialValuesReset', true
        )
    where "CusQuoteHeader_ID" = source_quote_id
      and "CusQuoteEvent_TypeCode" = 'copied_to_new_quote'
      and "CusQuoteEvent_MetadataJSON" ->> 'newQuoteId' = saved_quote_id::text;

    select coalesce(jsonb_agg(jsonb_build_object(
      'CusQuoteEvent_ID', event."CusQuoteEvent_ID",
      'CusQuoteEvent_TypeCode', event."CusQuoteEvent_TypeCode",
      'CusQuoteEvent_Summary', event."CusQuoteEvent_Summary",
      'CusQuoteEvent_OccurredAt', event."CusQuoteEvent_OccurredAt",
      'CusQuoteEvent_MetadataJSON', event."CusQuoteEvent_MetadataJSON",
      'cmp_Users', jsonb_build_object(
        'User_Firstname', actor."User_Firstname",
        'User_Lastname', actor."User_Lastname"
      )
    ) order by event."CusQuoteEvent_OccurredAt" desc), '[]'::jsonb)
    into committed_events
    from public."CusQuote_Events" event
    left join public."cmp_Users" actor
      on actor."User_ID" = event."CusQuoteEvent_ActorUserID"
    where event."CusQuoteHeader_ID" = saved_quote_id
      and event."CusQuoteVersion_ID" = saved_version_id;

    saved := saved || jsonb_build_object('events', committed_events);
  end if;

  return saved;
end;
$_$;


ALTER FUNCTION "public"."quote_workflow_save_before_discard_20260909"("caller_auth_user_id" "uuid", "requested_quote_id" "uuid", "payload" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."quote_workflow_save_before_discard_20260909"("caller_auth_user_id" "uuid", "requested_quote_id" "uuid", "payload" "jsonb") IS 'Saves quote drafts and creates tenant-safe, same-customer repeat quotes with reset schedule and commercial evidence.';



CREATE OR REPLACE FUNCTION "public"."quote_workflow_save_follow_up_settings"("caller_auth_user_id" "uuid", "requested_enabled" boolean, "requested_default_delay_days" integer, "requested_send_time" time without time zone, "requested_timezone" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  company_id_value uuid;
  user_id_value uuid;
  timezone_value text := nullif(btrim(requested_timezone), '');
  before_value jsonb;
  after_value jsonb;
begin
  select app_user."User_ID", app_user."Company_ID" into user_id_value, company_id_value
  from public."cmp_Users" app_user
  where app_user."Auth_User_ID" = caller_auth_user_id
    and app_user."User_AccessStatus" = 'active';
  if company_id_value is null then
    raise exception 'User identity is incomplete.' using errcode = '42501';
  end if;
  if not exists (
    select 1 from public."cmp_Users_Roles" link
    join public."sys_UserRoles" role on role."sys_UserRole_ID" = link."sys_UserRole_ID"
    where link."User_ID" = user_id_value
      and lower(role."sys_UserRole_Name") in ('administrator', 'company admin')
  ) then
    raise exception 'Only tenant administrators can change quote follow-up policy.' using errcode = '42501';
  end if;
  if requested_default_delay_days not between 1 and 30 then
    raise exception 'Quote follow-up timing must be between 1 and 30 days.' using errcode = '22023';
  end if;
  if timezone_value is null or not exists (select 1 from pg_catalog.pg_timezone_names where name = timezone_value) then
    raise exception 'Choose a recognised quote follow-up timezone.' using errcode = '22023';
  end if;

  before_value := public.quote_workflow_get_follow_up_settings(caller_auth_user_id);
  insert into quote_api.reference_settings (
    company_id, quote_follow_up_enabled, quote_follow_up_delay_days,
    quote_follow_up_send_time, quote_follow_up_timezone, updated_at, updated_by
  ) values (
    company_id_value, coalesce(requested_enabled, true), requested_default_delay_days,
    coalesce(requested_send_time, time '09:00'), timezone_value, now(), user_id_value
  )
  on conflict (company_id) do update set
    quote_follow_up_enabled = excluded.quote_follow_up_enabled,
    quote_follow_up_delay_days = excluded.quote_follow_up_delay_days,
    quote_follow_up_send_time = excluded.quote_follow_up_send_time,
    quote_follow_up_timezone = excluded.quote_follow_up_timezone,
    updated_at = now(),
    updated_by = excluded.updated_by;
  after_value := public.quote_workflow_get_follow_up_settings(caller_auth_user_id);

  if after_value is distinct from before_value then
    insert into public."AI_DexterWatchSignals" (
      "AIDexterWatchSignal_CompanyID", "AIDexterWatchSignal_CapabilityCode",
      "AIDexterWatchSignal_SourceTable", "AIDexterWatchSignal_SourceID",
      "AIDexterWatchSignal_OldJSON", "AIDexterWatchSignal_NewJSON"
    ) values (
      company_id_value, 'quote_follow_up_policy', 'quote_api.reference_settings', company_id_value,
      before_value, after_value
    );
  end if;
  return after_value;
end;
$$;


ALTER FUNCTION "public"."quote_workflow_save_follow_up_settings"("caller_auth_user_id" "uuid", "requested_enabled" boolean, "requested_default_delay_days" integer, "requested_send_time" time without time zone, "requested_timezone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."quote_workflow_save_quote"("caller_auth_user_id" "uuid", "requested_quote_id" "uuid", "payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare current_version public."CusQuote_Versions"; guarded boolean;
begin
  if requested_quote_id is not null then
    if not coalesce(quote_api.has_permission(caller_auth_user_id,'Quotes.Write'),false) then
      raise exception 'Quote management is not authorised.' using errcode='42501';
    end if;
    perform 1 from public."CusQuote_Header" q
    join public."cmp_Offices" o on o."Office_ID"=coalesce(q."CusQuoteHeader_OrgOfficeID",q."OrgOffice_ID")
    join public."cmp_Users" u on u."Company_ID"=o."Company_ID" and u."Auth_User_ID"=caller_auth_user_id and u."User_AccessStatus"='active'
    where q."CusQuoteHeader_ID"=requested_quote_id and not q."CusQuoteHeader_IsDeleted" for update of q;
    if not found then raise exception 'Quote is outside this workspace.' using errcode='42501'; end if;
    select * into strict current_version from public."CusQuote_Versions"
    where "CusQuoteHeader_ID"=requested_quote_id and "CusQuoteVersion_IsCurrent" for update;
    guarded := payload ? '_expectedVersionId' or exists(select 1 from public."CusQuote_Versions"
      where "CusQuoteHeader_ID"=requested_quote_id and "CusQuoteVersion_DiscardedAt" is not null);
    if guarded and (payload->>'_expectedVersionId') is distinct from current_version."CusQuoteVersion_ID"::text then
      raise exception 'This Quote version has changed. Reload before editing.' using errcode='40001';
    end if;
    if guarded and current_version."CusQuoteVersion_IsSubmitted" and coalesce(payload->>'_createVersion','false') <> 'true' then
      raise exception 'Create a new working version before editing this submitted Quote.' using errcode='40001';
    end if;
  end if;
  return public.quote_workflow_save_before_discard_20260909(caller_auth_user_id,requested_quote_id,payload-array['_expectedVersionId','_createVersion']);
end;
$$;


ALTER FUNCTION "public"."quote_workflow_save_quote"("caller_auth_user_id" "uuid", "requested_quote_id" "uuid", "payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."quote_workflow_save_quote_before_repeat_20260904"("caller_auth_user_id" "uuid", "requested_quote_id" "uuid", "payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  saved jsonb;
  saved_quote_id uuid;
  saved_version_id uuid;
  version_summary jsonb;
  committed_events jsonb;
  actor_user_id uuid;
  actor_company_id uuid;
  source_quote_id uuid;
  source_quote_reference text;
  source_version_id uuid;
  target_quote_reference text;
begin
  if requested_quote_id is not null
     and quote_api.has_permission(caller_auth_user_id, 'Quotes.Write')
     and exists (
       select 1
       from public."CusQuote_Header" quote
       join public."cmp_Offices" office
         on office."Office_ID" = coalesce(quote."CusQuoteHeader_OrgOfficeID", quote."OrgOffice_ID")
       join public."cmp_Users" app_user
         on app_user."Auth_User_ID" = caller_auth_user_id
        and app_user."Company_ID" = office."Company_ID"
        and app_user."User_AccessStatus" = 'active'
       where quote."CusQuoteHeader_ID" = requested_quote_id
         and quote."CusQuoteHeader_LifecycleCode" in ('accepted', 'changes_requested')
         and not quote."CusQuoteHeader_IsDeleted"
     ) then
    update public."CusQuote_Header"
    set
      "CusQuoteHeader_LifecycleCode" = 'revised',
      "CusQuoteHeader_Status" = 1
    where "CusQuoteHeader_ID" = requested_quote_id;
  end if;

  saved := quote_api.save_quote(caller_auth_user_id, requested_quote_id, payload);
  saved_quote_id := (saved ->> 'quoteId')::uuid;
  saved_version_id := (saved ->> 'versionId')::uuid;
  target_quote_reference := saved ->> 'reference';

  -- The client can request copy provenance only while creating a new master
  -- quote. Validate the source against the actor's physical tenant before
  -- recording either side of the audit link.
  if requested_quote_id is null
     and coalesce(payload #>> '{shipmentFacts,copiedFromQuoteId}', '')
       ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
    source_quote_id := (payload #>> '{shipmentFacts,copiedFromQuoteId}')::uuid;

    select app_user."User_ID", app_user."Company_ID"
      into strict actor_user_id, actor_company_id
    from public."cmp_Users" app_user
    where app_user."Auth_User_ID" = caller_auth_user_id
      and app_user."User_AccessStatus" = 'active';

    select
      coalesce(
        nullif(payload #>> '{shipmentFacts,copiedFromQuoteReference}', ''),
        current_version."CusQuoteVersion_SnapshotJSON" ->> 'reference',
        'Q-' || source_quote."CusQuoteHeader_Number"
      ),
      current_version."CusQuoteVersion_ID"
      into source_quote_reference, source_version_id
    from public."CusQuote_Header" source_quote
    join public."cmp_Offices" source_office
      on source_office."Office_ID" = coalesce(source_quote."CusQuoteHeader_OrgOfficeID", source_quote."OrgOffice_ID")
     and source_office."Company_ID" = actor_company_id
    left join lateral (
      select version."CusQuoteVersion_ID", version."CusQuoteVersion_SnapshotJSON"
      from public."CusQuote_Versions" version
      where version."CusQuoteHeader_ID" = source_quote."CusQuoteHeader_ID"
      order by version."CusQuoteVersion_IsCurrent" desc, version."CusQuoteVersion_Number" desc
      limit 1
    ) current_version on true
    where source_quote."CusQuoteHeader_ID" = source_quote_id
      and not source_quote."CusQuoteHeader_IsDeleted";

    if found and source_quote_id <> saved_quote_id then
      update public."CusQuote_Events"
      set
        "CusQuoteEvent_Summary" = 'Quote created from ' || source_quote_reference || ' for a different customer.',
        "CusQuoteEvent_MetadataJSON" = coalesce("CusQuoteEvent_MetadataJSON", '{}'::jsonb)
          || jsonb_strip_nulls(jsonb_build_object(
            'copyReason', 'customer_changed',
            'copiedFromQuoteId', source_quote_id,
            'copiedFromQuoteReference', source_quote_reference,
            'customerId', nullif(payload ->> 'customerId', ''),
            'customerName', nullif(payload ->> 'customerName', ''),
            'commercialValuesReset', true
          ))
      where "CusQuoteHeader_ID" = saved_quote_id
        and "CusQuoteVersion_ID" = saved_version_id
        and "CusQuoteEvent_TypeCode" = 'created';

      insert into public."CusQuote_Events" (
        "Company_ID", "CusQuoteHeader_ID", "CusQuoteVersion_ID",
        "CusQuoteEvent_TypeCode", "CusQuoteEvent_Summary",
        "CusQuoteEvent_MetadataJSON", "CusQuoteEvent_ActorUserID"
      ) values (
        actor_company_id, source_quote_id, source_version_id,
        'copied_to_new_quote',
        'Quote copied to ' || target_quote_reference || ' for ' || coalesce(nullif(payload ->> 'customerName', ''), 'a different customer') || '.',
        jsonb_strip_nulls(jsonb_build_object(
          'copyReason', 'customer_changed',
          'newQuoteId', saved_quote_id,
          'newQuoteReference', target_quote_reference,
          'customerId', nullif(payload ->> 'customerId', ''),
          'customerName', nullif(payload ->> 'customerName', ''),
          'commercialValuesReset', true
        )),
        actor_user_id
      );
    end if;
  end if;

  select jsonb_build_object(
    'CusQuoteVersion_ID', version."CusQuoteVersion_ID",
    'CusQuoteVersion_Number', version."CusQuoteVersion_Number",
    'CusQuoteVersion_StatusCode', version."CusQuoteVersion_StatusCode",
    'CusQuoteVersion_IsCurrent', version."CusQuoteVersion_IsCurrent",
    'CusQuoteVersion_IsSubmitted', version."CusQuoteVersion_IsSubmitted",
    'CusQuoteVersion_CreatedAt', version."CusQuoteVersion_CreatedAt",
    'CusQuoteVersion_SubmittedAt', version."CusQuoteVersion_SubmittedAt",
    'CusQuoteVersion_SubmittedBy', version."CusQuoteVersion_SubmittedBy",
    'CusQuoteVersion_SnapshotJSON', version."CusQuoteVersion_SnapshotJSON"
  ) into strict version_summary
  from public."CusQuote_Versions" version
  where version."CusQuoteHeader_ID" = saved_quote_id
    and version."CusQuoteVersion_ID" = saved_version_id;

  select coalesce(jsonb_agg(jsonb_build_object(
    'CusQuoteEvent_ID', event."CusQuoteEvent_ID",
    'CusQuoteEvent_TypeCode', event."CusQuoteEvent_TypeCode",
    'CusQuoteEvent_Summary', event."CusQuoteEvent_Summary",
    'CusQuoteEvent_OccurredAt', event."CusQuoteEvent_OccurredAt",
    'CusQuoteEvent_MetadataJSON', event."CusQuoteEvent_MetadataJSON",
    'cmp_Users', jsonb_build_object(
      'User_Firstname', actor."User_Firstname",
      'User_Lastname', actor."User_Lastname"
    )
  ) order by event."CusQuoteEvent_OccurredAt" desc), '[]'::jsonb)
  into committed_events
  from public."CusQuote_Events" event
  left join public."cmp_Users" actor
    on actor."User_ID" = event."CusQuoteEvent_ActorUserID"
  where event."CusQuoteHeader_ID" = saved_quote_id
    and event."CusQuoteVersion_ID" = saved_version_id;

  return saved || jsonb_build_object(
    'readiness', booking_api.quote_readiness(saved_quote_id),
    'version', version_summary,
    'events', committed_events
  );
end;
$_$;


