COMMENT ON FUNCTION "public"."reopen_rejected_customs_declaration"("p_declaration_id" "uuid") IS 'Idempotently reopens an operator-owned rejected CDS declaration for correction. Submitted and accepted declarations remain immutable.';



CREATE OR REPLACE FUNCTION "public"."reporting_workspace"("action" "text", "payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
declare u public."cmp_Users"; r report_api.reports; s report_api.schedules; result jsonb; identifier uuid; next_at timestamptz;
begin
  u:=report_api.context(auth.uid());
  if action='list' then return jsonb_build_object('userId',u."User_ID",'catalogue',(select coalesce(jsonb_agg(x),'[]') from jsonb_array_elements(report_api.catalogue()) x where booking_api.has_permission(auth.uid(),x->>'permission')),
    'reports',(select coalesce(jsonb_agg(to_jsonb(r) order by r.updated_at desc),'[]') from report_api.reports r where report_api.can_read(auth.uid(),r)),
    'archivedReports',(select coalesce(jsonb_agg(to_jsonb(r) order by r.updated_at desc),'[]') from report_api.reports r where r.owner_id=u."User_ID" and r.company_id=u."Company_ID" and r.archived_at is not null),
    'schedules',(select coalesce(jsonb_agg(to_jsonb(s)||jsonb_build_object('name',r.name) order by s.next_run_at),'[]') from report_api.schedules s join report_api.reports r on r.id=s.report_id where s.owner_id=u."User_ID" and s.company_id=u."Company_ID"),
    'runs',(select coalesce(jsonb_agg(x order by x->>'created_at' desc),'[]') from (select to_jsonb(h)-'snapshot'-'definition' x from report_api.runs h join report_api.reports r on r.id=h.report_id where h.owner_id=u."User_ID" and report_api.can_read_run(auth.uid(),h) order by h.created_at desc limit 100) selected));
  elsif action='preview' then return report_api.render(auth.uid(),payload->'definition',200);
  elsif action='save' then return report_api.save(auth.uid(),payload);
  elsif action='run' then return report_api.run(auth.uid(),(payload->>'id')::uuid,(payload->>'runId')::uuid);
  elsif action='get_run' then
    select h.definition into result from report_api.runs h join report_api.reports r on r.id=h.report_id
      where h.id=(payload->>'id')::uuid and h.owner_id=u."User_ID" and report_api.can_read_run(auth.uid(),h);
    if not found then raise exception 'This saved snapshot is unavailable.' using errcode='42501';end if;
    -- Recheck historical sources too: an edited report must not grant access to an older finance snapshot.
    r.company_id:=u."Company_ID";r.owner_id:=u."User_ID";r.visibility:='private';r.definition:=result;r.archived_at:=null;
    if not report_api.can_read(auth.uid(),r) then raise exception 'Your access to this snapshot data has changed.' using errcode='42501';end if;
    select to_jsonb(h) into result from report_api.runs h where id=(payload->>'id')::uuid;return result;
  elsif action='schedule' then
    select * into r from report_api.reports where id=(payload->>'reportId')::uuid;
    if not found or not report_api.can_read(auth.uid(),r) then raise exception 'Choose an available saved report.' using errcode='42501';end if;
    next_at:=report_api.next_time(payload->>'frequency',payload->>'timezone',(payload->>'localTime')::time,coalesce((payload->>'weekday')::integer,1),coalesce((payload->>'monthday')::integer,1),now());
    if nullif(payload->>'id','') is not null then
      select * into s from report_api.schedules where id=(payload->>'id')::uuid for update;
      if not found or s.owner_id<>u."User_ID" or s.company_id<>u."Company_ID" then raise exception 'This schedule is unavailable.' using errcode='42501';end if;
      if s.updated_at is distinct from (payload->>'updatedAt')::timestamptz then raise exception 'This schedule changed. Reopen it before saving.' using errcode='40001';end if;
      update report_api.schedules set report_id=r.id,frequency=payload->>'frequency',timezone=payload->>'timezone',local_time=(payload->>'localTime')::time,
        weekday=coalesce((payload->>'weekday')::integer,1),monthday=coalesce((payload->>'monthday')::integer,1),paused=coalesce((payload->>'paused')::boolean,false),next_run_at=next_at,updated_at=now() where id=s.id returning * into s;
    else
      insert into report_api.schedules(report_id,owner_id,company_id,frequency,timezone,local_time,weekday,monthday,next_run_at)
        values(r.id,u."User_ID",u."Company_ID",payload->>'frequency',payload->>'timezone',(payload->>'localTime')::time,
          coalesce((payload->>'weekday')::integer,1),coalesce((payload->>'monthday')::integer,1),next_at) returning * into s;
    end if;
    insert into report_api.audit(company_id,actor_id,report_id,action,detail) values(u."Company_ID",u."User_ID",r.id,'schedule',to_jsonb(s));
    return to_jsonb(s);
  elsif action='restore' then
    select * into r from report_api.reports where id=(payload->>'id')::uuid for update;
    if not found or r.owner_id<>u."User_ID" or r.company_id<>u."Company_ID" then raise exception 'Only the report owner can restore it.' using errcode='42501';end if;
    r.archived_at:=null;
    if not report_api.can_read(auth.uid(),r) then raise exception 'Your data access has changed. Restore the required access before restoring this report.' using errcode='42501';end if;
    update report_api.reports set archived_at=null,updated_at=now() where id=r.id returning * into r;
    insert into report_api.audit(company_id,actor_id,report_id,action) values(u."Company_ID",u."User_ID",r.id,'restore');
    return to_jsonb(r);
  elsif action='archive' then
    select * into r from report_api.reports where id=(payload->>'id')::uuid for update;
    if not found or r.owner_id<>u."User_ID" or r.company_id<>u."Company_ID" then raise exception 'Only the report owner can archive it.' using errcode='42501';end if;
    update report_api.reports set archived_at=now(),updated_at=now() where id=r.id;
    update report_api.schedules set paused=true,updated_at=now() where report_id=r.id;
    insert into report_api.audit(company_id,actor_id,report_id,action) values(u."Company_ID",u."User_ID",r.id,'archive');
    return jsonb_build_object('archived',true);
  end if;
  raise exception 'This reporting action is unavailable.' using errcode='22023';
end $$;


ALTER FUNCTION "public"."reporting_workspace"("action" "text", "payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reset_removed_company_appearance"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_company_id uuid;
begin
  -- Changes and deletes both reconcile the affected company. Other companies
  -- and colleagues with any standard Multideck preset are never changed.
  for v_company_id in
    select distinct company_id from unnest(array[
      case when TG_OP <> 'INSERT' then OLD."Company_ID" end,
      case when TG_OP <> 'DELETE' then NEW."Company_ID" end
    ]) as affected(company_id) where company_id is not null
  loop
    if not public.company_appearance_available(v_company_id) then
      update public."cmp_Users" set "User_AccentPreset" = 'teal'
      where "Company_ID" = v_company_id and "User_AccentPreset" = 'company';
    end if;
  end loop;
  return null;
end;
$$;


ALTER FUNCTION "public"."reset_removed_company_appearance"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_workspace_reference_alias"("caller_auth_user_id" "uuid", "requested_reference_kind" "text", "requested_alias" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'quote_api'
    AS $$
declare
  company_id_value uuid;
  alias_row quote_api.reference_aliases%rowtype;
begin
  if requested_reference_kind not in ('quote', 'booking') or nullif(btrim(requested_alias), '') is null then
    raise exception 'Choose a supported reference alias.' using errcode = '22023';
  end if;
  select app_user."Company_ID" into strict company_id_value
  from public."cmp_Users" app_user
  where app_user."Auth_User_ID" = caller_auth_user_id and app_user."User_AccessStatus" = 'active';
  select alias.* into alias_row from quote_api.reference_aliases alias
  where alias.company_id = company_id_value
    and alias.reference_kind = requested_reference_kind
    and alias.normalized_alias = upper(btrim(requested_alias));
  if not found then return null; end if;
  return jsonb_build_object('sourceId', alias_row.source_id, 'canonicalReference', alias_row.canonical_reference);
exception
  when no_data_found or too_many_rows then
    raise exception 'Your workspace identity is incomplete.' using errcode = '42501';
end;
$$;


ALTER FUNCTION "public"."resolve_workspace_reference_alias"("caller_auth_user_id" "uuid", "requested_reference_kind" "text", "requested_alias" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rls_auto_enable"() RETURNS "event_trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."rls_auto_enable"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_customs_export_draft"("p_declaration_id" "uuid", "p_draft" "jsonb") RETURNS TABLE("declaration_id" "uuid", "local_reference_number" "text", "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $_$
declare
  v_user_id uuid := auth.uid();
  v_declaration_id uuid := p_declaration_id;
  v_reference text;
  v_updated_at timestamptz := clock_timestamp();
  v_affected integer;
begin
  if v_user_id is null then
    raise exception using errcode = '42501', message = 'Authentication is required to save a Customs draft.';
  end if;

  if p_draft is null or jsonb_typeof(p_draft) <> 'object' then
    raise exception using errcode = '22023', message = 'A valid Customs draft is required.';
  end if;

  if jsonb_typeof(coalesce(p_draft -> 'items', '[]'::jsonb)) <> 'array' then
    raise exception using errcode = '22023', message = 'Customs draft items must be an array.';
  end if;

  if v_declaration_id is null then
    v_reference := 'MD-CDS-EX-'
      || to_char(v_updated_at at time zone 'UTC', 'YYYYMMDD')
      || '-'
      || lpad(nextval('public."Customs_DeclarationReferenceSeq"')::text, 4, '0');

    insert into public."Customs_Declarations" (
      "CUST_JurisdictionCode",
      "CUST_Direction",
      "CUST_DeclarationKind",
      "CUST_Status",
      "CUST_LocalReferenceNumber",
      "CUST_UCR",
      "CUST_TraderReference",
      "CUST_DeclarantIdentifierSnapshot",
      "CUST_ExporterIdentifierSnapshot",
      "CUST_RepresentativeIdentifierSnapshot",
      "CUST_CustomsOfficeOfExit",
      "CUST_GoodsLocationCode",
      "CUST_CountryOfDispatchCodeSnapshot",
      "CUST_CountryOfDestinationCodeSnapshot",
      "CUST_TotalPackages",
      "CUST_GrossMass",
      "CUST_InvoiceAmount",
      "CUST_InvoiceCurrencyCodeSnapshot",
      "CUST_GenericPayloadJSON",
      "CUST_SourceSnapshot",
      "CUST_CreatedAt",
      "CUST_CreatedBy",
      "CUST_UpdatedAt",
      "CUST_UpdatedBy"
    ) values (
      'GB',
      'export',
      'cds_export',
      'draft',
      v_reference,
      nullif(btrim(p_draft ->> 'ucn'), ''),
      nullif(btrim(p_draft ->> 'traderReference'), ''),
      nullif(btrim(p_draft ->> 'declarant'), ''),
      nullif(btrim(p_draft ->> 'exporter'), ''),
      nullif(btrim(p_draft ->> 'representative'), ''),
      nullif(btrim(p_draft ->> 'exitOffice'), ''),
      nullif(btrim(p_draft ->> 'goodsLocationIdentifier'), ''),
      nullif(btrim(p_draft ->> 'exportCountry'), ''),
      nullif(btrim(p_draft ->> 'destinationCountry'), ''),
      case when coalesce(p_draft ->> 'totalPackages', '') ~ '^\d+$' then (p_draft ->> 'totalPackages')::integer end,
      case when coalesce(p_draft ->> 'totalGrossMass', '') ~ '^\d+(\.\d+)?$' then (p_draft ->> 'totalGrossMass')::numeric end,
      case when coalesce(p_draft ->> 'totalAmount', '') ~ '^\d+(\.\d+)?$' then (p_draft ->> 'totalAmount')::numeric end,
      nullif(btrim(p_draft ->> 'currency'), ''),
      p_draft,
      jsonb_build_object('source', 'multideck_app', 'item_count', jsonb_array_length(coalesce(p_draft -> 'items', '[]'::jsonb))),
      v_updated_at,
      v_user_id,
      v_updated_at,
      v_user_id
    )
    returning "CUST_id" into v_declaration_id;
  else
    update public."Customs_Declarations"
    set
      "CUST_UCR" = nullif(btrim(p_draft ->> 'ucn'), ''),
      "CUST_TraderReference" = nullif(btrim(p_draft ->> 'traderReference'), ''),
      "CUST_DeclarantIdentifierSnapshot" = nullif(btrim(p_draft ->> 'declarant'), ''),
      "CUST_ExporterIdentifierSnapshot" = nullif(btrim(p_draft ->> 'exporter'), ''),
      "CUST_RepresentativeIdentifierSnapshot" = nullif(btrim(p_draft ->> 'representative'), ''),
      "CUST_CustomsOfficeOfExit" = nullif(btrim(p_draft ->> 'exitOffice'), ''),
      "CUST_GoodsLocationCode" = nullif(btrim(p_draft ->> 'goodsLocationIdentifier'), ''),
      "CUST_CountryOfDispatchCodeSnapshot" = nullif(btrim(p_draft ->> 'exportCountry'), ''),
      "CUST_CountryOfDestinationCodeSnapshot" = nullif(btrim(p_draft ->> 'destinationCountry'), ''),
      "CUST_TotalPackages" = case when coalesce(p_draft ->> 'totalPackages', '') ~ '^\d+$' then (p_draft ->> 'totalPackages')::integer end,
      "CUST_GrossMass" = case when coalesce(p_draft ->> 'totalGrossMass', '') ~ '^\d+(\.\d+)?$' then (p_draft ->> 'totalGrossMass')::numeric end,
      "CUST_InvoiceAmount" = case when coalesce(p_draft ->> 'totalAmount', '') ~ '^\d+(\.\d+)?$' then (p_draft ->> 'totalAmount')::numeric end,
      "CUST_InvoiceCurrencyCodeSnapshot" = nullif(btrim(p_draft ->> 'currency'), ''),
      "CUST_GenericPayloadJSON" = p_draft,
      "CUST_SourceSnapshot" = jsonb_build_object('source', 'multideck_app', 'item_count', jsonb_array_length(coalesce(p_draft -> 'items', '[]'::jsonb))),
      "CUST_Status" = 'draft',
      "CUST_UpdatedAt" = v_updated_at,
      "CUST_UpdatedBy" = v_user_id
    where "CUST_id" = v_declaration_id
      and "CUST_CreatedBy" = v_user_id
      and "CUST_Status" = 'draft'
      and not "CUST_IsDeleted";

    get diagnostics v_affected = row_count;
    if v_affected <> 1 then
      raise exception using errcode = '42501', message = 'This Customs draft is unavailable or can no longer be edited.';
    end if;

    select "CUST_LocalReferenceNumber"
      into v_reference
    from public."Customs_Declarations"
    where "CUST_id" = v_declaration_id;

    delete from public."Customs_Items"
    where "CUSTI_CustomsID" = v_declaration_id;
  end if;

  insert into public."Customs_Items" (
    "CUSTI_CustomsID",
    "CUSTI_ItemNumber",
    "CUSTI_CommodityCode",
    "CUSTI_DescriptionOfGoods",
    "CUSTI_CountryOfOriginCodeSnapshot",
    "CUSTI_CountryOfDestinationCodeSnapshot",
    "CUSTI_NetMass",
    "CUSTI_GrossMass",
    "CUSTI_SupplementaryUnits",
    "CUSTI_ItemValueAmount",
    "CUSTI_ItemValueCurrencyCodeSnapshot",
    "CUSTI_ProcedureCode",
    "CUSTI_AdditionalProcedureCodesJSON",
    "CUSTI_ItemPayloadJSON"
  )
  select
    v_declaration_id,
    item.ordinality::integer,
    nullif(btrim(item.value ->> 'commodityCode'), ''),
    coalesce(item.value ->> 'description', ''),
    nullif(btrim(item.value ->> 'nonPreferentialOrigin'), ''),
    nullif(btrim(item.value ->> 'destinationCountry'), ''),
    case when coalesce(item.value ->> 'netMass', '') ~ '^\d+(\.\d+)?$' then (item.value ->> 'netMass')::numeric end,
    case when coalesce(item.value ->> 'grossMass', '') ~ '^\d+(\.\d+)?$' then (item.value ->> 'grossMass')::numeric end,
    case when coalesce(item.value ->> 'tariffQuantity', '') ~ '^\d+(\.\d+)?$' then (item.value ->> 'tariffQuantity')::numeric end,
    case when coalesce(item.value ->> 'itemPrice', '') ~ '^\d+(\.\d+)?$' then (item.value ->> 'itemPrice')::numeric end,
    nullif(btrim(item.value ->> 'currency'), ''),
    nullif(btrim(item.value ->> 'procedureCode'), ''),
    case
      when nullif(btrim(item.value ->> 'additionalProcedureCode'), '') is null then '[]'::jsonb
      else jsonb_build_array(item.value ->> 'additionalProcedureCode')
    end,
    item.value
  from jsonb_array_elements(coalesce(p_draft -> 'items', '[]'::jsonb)) with ordinality as item(value, ordinality);

  return query
  select v_declaration_id, v_reference, v_updated_at;
end;
$_$;


ALTER FUNCTION "public"."save_customs_export_draft"("p_declaration_id" "uuid", "p_draft" "jsonb") OWNER TO "postgres";


