CREATE OR REPLACE FUNCTION "public"."warehouse_edge_calendar_page"("p_allowed_facility_ids" "uuid"[], "p_allowed_org_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_start_date" "date" DEFAULT CURRENT_DATE, "p_end_date" "date" DEFAULT (CURRENT_DATE + 7), "p_limit" integer DEFAULT 500, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_limit integer := greatest(1, least(coalesce(p_limit, 500), 500));
  v_offset integer := greatest(0, coalesce(p_offset, 0));
  v_start date := coalesce(p_start_date, current_date);
  v_end date := least(coalesce(p_end_date, current_date + 7), coalesce(p_start_date, current_date) + 45);
  v_result jsonb;
begin
  if coalesce(cardinality(p_allowed_facility_ids), 0) = 0 or v_end <= v_start then
    return jsonb_build_object('rows', '[]'::jsonb, 'total', 0, 'limit', v_limit, 'offset', v_offset);
  end if;

  with filtered as materialized (
    select
      warehouse_order.*,
      facility."WMSFacility_Code" as facility_code,
      facility."WMSFacility_Name" as facility_name,
      organisation."Org_Name" as customer_name,
      order_type."WMSOrderType_Name" as type_name,
      order_status."WMSOrderStatus_Name" as status_name,
      coalesce(warehouse_order."WMSOrder_AppointmentStartAt"::date, warehouse_order."WMSOrder_RequestedDate") as expected_date
    from public."WMS_Orders" warehouse_order
    join public."WMS_Facilities" facility on facility."WMSFacility_ID" = warehouse_order."WMSOrder_FacilityID"
    join public."Org_Master" organisation on organisation."Org_id" = warehouse_order."WMSOrder_CustomerOrgID"
    left join public."sys_WMSOrderTypes" order_type on order_type."WMSOrderType_Code" = warehouse_order."WMSOrder_TypeCode"
    left join public."sys_WMSOrderStatuses" order_status on order_status."WMSOrderStatus_Code" = warehouse_order."WMSOrder_StatusCode"
    where warehouse_order."WMSOrder_FacilityID" = any(p_allowed_facility_ids)
      and (p_allowed_org_ids is null or warehouse_order."WMSOrder_CustomerOrgID" = any(p_allowed_org_ids))
      and not warehouse_order."WMSOrder_IsDeleted"
      and warehouse_order."WMSOrder_StatusCode" <> 'cancelled'
      and coalesce(warehouse_order."WMSOrder_AppointmentStartAt"::date, warehouse_order."WMSOrder_RequestedDate") >= v_start
      and coalesce(warehouse_order."WMSOrder_AppointmentStartAt"::date, warehouse_order."WMSOrder_RequestedDate") < v_end
  ), ranked as (
    select *, row_number() over (
      order by expected_date, "WMSOrder_AppointmentStartAt" nulls last, "WMSOrder_OrderNumber", "WMSOrder_ID"
    ) as ordinal
    from filtered
  ), page as (
    select * from ranked where ordinal > v_offset and ordinal <= v_offset + v_limit
  )
  select jsonb_build_object(
    'rows', coalesce((select jsonb_agg(jsonb_build_object(
      'id', row."WMSOrder_ID", 'facilityId', row."WMSOrder_FacilityID",
      'facilityCode', row.facility_code, 'facilityName', row.facility_name,
      'officeId', row."WMSOrder_OrgOfficeID", 'officeName', null,
      'customerOrgId', row."WMSOrder_CustomerOrgID", 'customerName', row.customer_name,
      'orderNumber', row."WMSOrder_OrderNumber", 'typeCode', row."WMSOrder_TypeCode", 'typeName', row.type_name,
      'statusCode', row."WMSOrder_StatusCode", 'statusName', row.status_name,
      'priorityCode', row."WMSOrder_PriorityCode", 'customerReference', row."WMSOrder_CustomerReference",
      'requestedDate', row."WMSOrder_RequestedDate", 'appointmentStartAt', row."WMSOrder_AppointmentStartAt",
      'appointmentEndAt', row."WMSOrder_AppointmentEndAt", 'vehicleReg', row."WMSOrder_VehicleReg",
      'containerNumber', row."WMSOrder_ContainerNumber", 'sealNumber', row."WMSOrder_SealNumber",
      'instructions', row."WMSOrder_Instructions", 'createdAt', row."WMSOrder_CreatedAt",
      'updatedAt', row."WMSOrder_UpdatedAt", 'lines', '[]'::jsonb,
      'receipts', '[]'::jsonb, 'dispatches', '[]'::jsonb
    ) order by row.ordinal) from page row), '[]'::jsonb),
    'total', (select count(*) from filtered), 'limit', v_limit, 'offset', v_offset
  ) into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."warehouse_edge_calendar_page"("p_allowed_facility_ids" "uuid"[], "p_allowed_org_ids" "uuid"[], "p_start_date" "date", "p_end_date" "date", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."warehouse_edge_calendar_page"("p_allowed_facility_ids" "uuid"[], "p_allowed_org_ids" "uuid"[], "p_start_date" "date", "p_end_date" "date", "p_limit" integer, "p_offset" integer) IS 'Service-role-only, allowlist-scoped Warehouse calendar range capped at 500 orders and 45 days.';



CREATE OR REPLACE FUNCTION "public"."warehouse_edge_cancel_order_mutation"("p_order_id" "uuid", "p_actor_user_id" "uuid", "p_allowed_facility_ids" "uuid"[], "p_allowed_organisation_ids" "uuid"[]) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_order public."WMS_Orders"%rowtype; v_task public."WMS_Tasks"%rowtype; v_now timestamptz:=now(); v_balance public."WMS_InventoryBalances"%rowtype; v_return numeric;
begin
  select * into v_order from public."WMS_Orders" where "WMSOrder_ID"=p_order_id and "WMSOrder_FacilityID"=any(coalesce(p_allowed_facility_ids,'{}'::uuid[])) and "WMSOrder_CustomerOrgID"=any(coalesce(p_allowed_organisation_ids,'{}'::uuid[])) and not "WMSOrder_IsDeleted" for update;
  if not found then raise exception 'WMS404: This warehouse order does not exist in your workspace.'; end if;
  if v_order."WMSOrder_StatusCode" in ('complete','cancelled') then raise exception 'WMS409: This order is already final.'; end if;
  if exists(select 1 from public."WMS_OrderLines" where "WMSOrderLine_OrderID"=p_order_id and ("WMSOrderLine_ReceivedQuantity">0 or "WMSOrderLine_PickedQuantity">0 or "WMSOrderLine_DispatchedQuantity">0)) then raise exception 'WMS409: An order with received, picked, or dispatched stock cannot be cancelled.'; end if;
  if v_order."WMSOrder_TypeCode"='outbound' then
    for v_task in select * from public."WMS_Tasks" where "WMSTask_OrderID"=p_order_id and "WMSTask_TypeCode"='pick' and "WMSTask_StatusCode" not in ('complete','cancelled') for update loop
      select * into v_balance from public."WMS_InventoryBalances" where "WMSBalance_ID"=v_task."WMSTask_BalanceID" for update;
      if not found then raise exception 'WMS409: Allocated balance is missing.'; end if;
      v_return:=public._warehouse_edge_task_balance_quantity(v_task."WMSTask_Quantity",v_task."WMSTask_UOMCode",v_balance."WMSBalance_UOMCode",v_task."WMSTask_MetadataJSON");
      if v_balance."WMSBalance_AllocatedQuantity"<v_return then raise exception 'WMS409: Task no longer matches its allocated balance.'; end if;
      update public."WMS_InventoryBalances" set "WMSBalance_AllocatedQuantity"=greatest(0,"WMSBalance_AllocatedQuantity"-v_return),"WMSBalance_AvailableQuantity"="WMSBalance_AvailableQuantity"+v_return,"WMSBalance_UpdatedAt"=v_now where "WMSBalance_ID"=v_task."WMSTask_BalanceID";
      update public."WMS_Tasks" set "WMSTask_StatusCode"='cancelled',"WMSTask_CompletedAt"=v_now,"WMSTask_CompletedBy"=p_actor_user_id where "WMSTask_ID"=v_task."WMSTask_ID";
      update public."WMS_PickTasks" set "WMSPick_StatusCode"='cancelled' where "WMSPick_TaskID"=v_task."WMSTask_ID";
      insert into public."WMS_TaskEvents" ("WMSTaskEvent_TaskID","WMSTaskEvent_EventTypeCode","WMSTaskEvent_FromStatusCode","WMSTaskEvent_ToStatusCode","WMSTaskEvent_EventBy") values(v_task."WMSTask_ID",'cancelled',v_task."WMSTask_StatusCode",'cancelled',p_actor_user_id);
    end loop;
  end if;
  update public."WMS_OrderLines" set "WMSOrderLine_AllocatedQuantity"=0,"WMSOrderLine_StatusCode"='cancelled' where "WMSOrderLine_OrderID"=p_order_id;
  update public."WMS_Orders" set "WMSOrder_StatusCode"='cancelled',"WMSOrder_UpdatedAt"=v_now,"WMSOrder_UpdatedBy"=p_actor_user_id where "WMSOrder_ID"=p_order_id;
  return p_order_id;
end;
$$;


ALTER FUNCTION "public"."warehouse_edge_cancel_order_mutation"("p_order_id" "uuid", "p_actor_user_id" "uuid", "p_allowed_facility_ids" "uuid"[], "p_allowed_organisation_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."warehouse_edge_confirm_task_mutation"("p_task_id" "uuid", "p_payload" "jsonb", "p_actor_user_id" "uuid", "p_allowed_facility_ids" "uuid"[]) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_task public."WMS_Tasks"%rowtype; v_item public."WMS_Items"%rowtype; v_location public."WMS_Locations"%rowtype;
  v_request_id uuid:=nullif(p_payload->>'requestId','')::uuid; v_quantity numeric:=nullif(p_payload->>'quantity','')::numeric;
  v_target uuid:=nullif(p_payload->>'targetLocationId','')::uuid; v_previous text; v_completed numeric; v_result jsonb;
begin
  if p_actor_user_id is null then raise exception 'WMS403: Physical warehouse tasks are reserved for the warehouse team.'; end if;
  if v_request_id is null then raise exception 'WMS400: A request identifier is required.'; end if;
  select * into v_task from public."WMS_Tasks" where "WMSTask_ID"=p_task_id and "WMSTask_FacilityID"=any(coalesce(p_allowed_facility_ids,'{}'::uuid[])) for update;
  if not found then raise exception 'WMS404: This warehouse task does not exist in your workspace.'; end if;
  if coalesce(v_task."WMSTask_MetadataJSON"->'confirmationRequestIds','[]'::jsonb) ? v_request_id::text then return p_task_id; end if;
  if v_task."WMSTask_StatusCode" in ('complete','cancelled') then raise exception 'WMS409: This warehouse task is already final.'; end if;
  if coalesce(v_quantity,0)<=0 or v_quantity>coalesce(v_task."WMSTask_Quantity",0)-v_task."WMSTask_CompletedQuantity" then raise exception 'WMS400: Check the confirmed task quantity.'; end if;
  select * into v_item from public."WMS_Items" where "WMSItem_ID"=v_task."WMSTask_ItemID";
  if nullif(btrim(p_payload->>'scannedItemCode'),'') is not null and lower(btrim(p_payload->>'scannedItemCode'))<>lower(v_item."WMSItem_SKU") and not exists(select 1 from public."WMS_ItemBarcodes" barcode where barcode."WMSItemBarcode_ItemID"=v_item."WMSItem_ID" and barcode."WMSItemBarcode_IsActive" and lower(barcode."WMSItemBarcode_Barcode")=lower(btrim(p_payload->>'scannedItemCode'))) then raise exception 'WMS409: The scanned item does not match this task.'; end if;
  if nullif(btrim(p_payload->>'scannedSourceLocationCode'),'') is not null and not exists(select 1 from public."WMS_Locations" location where location."WMSLocation_ID"=v_task."WMSTask_SourceLocationID" and (lower(location."WMSLocation_Code")=lower(btrim(p_payload->>'scannedSourceLocationCode')) or lower(coalesce(location."WMSLocation_Barcode",''))=lower(btrim(p_payload->>'scannedSourceLocationCode')))) then raise exception 'WMS409: The scanned source location does not match this task.'; end if;
  v_previous:=v_task."WMSTask_StatusCode";
  if v_task."WMSTask_TypeCode"='putaway' then
    if v_target is null then raise exception 'WMS400: Choose the putaway destination.'; end if;
    select * into v_location from public."WMS_Locations" where "WMSLocation_ID"=v_target and "WMSLocation_FacilityID"=v_task."WMSTask_FacilityID" and "WMSLocation_IsActive" and not "WMSLocation_IsDeleted" and "WMSLocation_StatusCode"='available';
    if not found or v_location."WMSLocation_TypeCode" in ('staging','dock','quarantine') then raise exception 'WMS400: Choose an available storage or pick location.'; end if;
    if nullif(btrim(p_payload->>'scannedTargetLocationCode'),'') is not null and lower(btrim(p_payload->>'scannedTargetLocationCode')) not in (lower(v_location."WMSLocation_Code"),lower(coalesce(v_location."WMSLocation_Barcode",''))) then raise exception 'WMS409: The scanned destination does not match the chosen location.'; end if;
    v_result:=public.warehouse_edge_inventory_mutation('move_balance',jsonb_build_object('requestId',v_request_id,'facilityId',v_task."WMSTask_FacilityID",'balanceId',v_task."WMSTask_BalanceID",'targetLocationId',v_target,'quantity',v_quantity,'reasonCode','putaway_task','notes',nullif(btrim(p_payload->>'notes'),'')),p_actor_user_id,array[v_task."WMSTask_FacilityID"]);
    update public."WMS_Tasks" set "WMSTask_TargetLocationID"=v_target where "WMSTask_ID"=p_task_id;
  elsif v_task."WMSTask_TypeCode"='pick' then
    update public."WMS_PickTasks" set "WMSPick_QuantityPicked"="WMSPick_QuantityPicked"+v_quantity,"WMSPick_StatusCode"=case when "WMSPick_QuantityPicked"+v_quantity >= "WMSPick_QuantityToPick" then 'complete' else 'in_progress' end,"WMSPick_PickedAt"=case when "WMSPick_QuantityPicked"+v_quantity >= "WMSPick_QuantityToPick" then now() else "WMSPick_PickedAt" end,"WMSPick_PickedBy"=p_actor_user_id where "WMSPick_TaskID"=p_task_id;
  else raise exception 'WMS400: This task type cannot be confirmed here.'; end if;
  v_completed:=v_task."WMSTask_CompletedQuantity"+v_quantity;
  update public."WMS_Tasks" set "WMSTask_CompletedQuantity"=v_completed,"WMSTask_StatusCode"=case when v_completed>=coalesce("WMSTask_Quantity",0) then 'complete' else 'in_progress' end,"WMSTask_StartedAt"=coalesce("WMSTask_StartedAt",now()),"WMSTask_CompletedAt"=case when v_completed>=coalesce("WMSTask_Quantity",0) then now() else null end,"WMSTask_CompletedBy"=case when v_completed>=coalesce("WMSTask_Quantity",0) then p_actor_user_id else null end,"WMSTask_MetadataJSON"="WMSTask_MetadataJSON"||jsonb_build_object('confirmationRequestIds',coalesce("WMSTask_MetadataJSON"->'confirmationRequestIds','[]'::jsonb)||to_jsonb(v_request_id::text),'lastScan',jsonb_strip_nulls(jsonb_build_object('sourceLocationCode',nullif(btrim(p_payload->>'scannedSourceLocationCode'),''),'targetLocationCode',nullif(btrim(p_payload->>'scannedTargetLocationCode'),''),'itemCode',nullif(btrim(p_payload->>'scannedItemCode'),'')))) where "WMSTask_ID"=p_task_id;
  insert into public."WMS_TaskEvents" ("WMSTaskEvent_TaskID","WMSTaskEvent_EventTypeCode","WMSTaskEvent_FromStatusCode","WMSTaskEvent_ToStatusCode","WMSTaskEvent_Notes","WMSTaskEvent_MetadataJSON","WMSTaskEvent_EventBy") values(p_task_id,'confirmed',v_previous,case when v_completed>=coalesce(v_task."WMSTask_Quantity",0) then 'complete' else 'in_progress' end,nullif(btrim(p_payload->>'notes'),''),jsonb_strip_nulls(jsonb_build_object('requestId',v_request_id,'quantity',v_quantity,'sourceLocationCode',nullif(btrim(p_payload->>'scannedSourceLocationCode'),''),'targetLocationCode',nullif(btrim(p_payload->>'scannedTargetLocationCode'),''),'itemCode',nullif(btrim(p_payload->>'scannedItemCode'),''),'movement',v_result)),p_actor_user_id);
  if v_task."WMSTask_TypeCode"='pick' then
    update public."WMS_OrderLines" line set "WMSOrderLine_PickedQuantity"=(select coalesce(sum(pick."WMSPick_QuantityPicked"),0) from public."WMS_PickTasks" pick where pick."WMSPick_OrderLineID"=line."WMSOrderLine_ID"),"WMSOrderLine_StatusCode"=case when (select coalesce(sum(pick."WMSPick_QuantityPicked"),0) from public."WMS_PickTasks" pick where pick."WMSPick_OrderLineID"=line."WMSOrderLine_ID")>=line."WMSOrderLine_OrderedQuantity" then 'picked' else 'allocated' end where line."WMSOrderLine_ID"=v_task."WMSTask_OrderLineID";
  end if;
  return p_task_id;
end;
$$;


ALTER FUNCTION "public"."warehouse_edge_confirm_task_mutation"("p_task_id" "uuid", "p_payload" "jsonb", "p_actor_user_id" "uuid", "p_allowed_facility_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."warehouse_edge_create_order_mutation"("p_payload" "jsonb", "p_actor_user_id" "uuid", "p_actor_portal_user_id" "uuid", "p_allowed_facility_ids" "uuid"[], "p_allowed_organisation_ids" "uuid"[]) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_order_id uuid := gen_random_uuid(); v_line_id uuid; v_advice_id uuid;
  v_facility public."WMS_Facilities"%rowtype; v_item public."WMS_Items"%rowtype; v_input jsonb;
  v_type text := lower(btrim(p_payload->>'typeCode'));
  v_source_type text := coalesce(nullif(lower(btrim(p_payload->>'sourceTypeCode')),''),'manual_exception');
  v_source_reference text := coalesce(nullif(btrim(p_payload->>'sourceReference'),''),nullif(btrim(p_payload->>'customerReference'),''));
  v_number text; v_quantity numeric; v_customs text; v_index integer := 0; v_now timestamptz := now();
begin
  if v_type not in ('inbound','outbound') then raise exception 'WMS400: Warehouse orders must be inbound or outbound.'; end if;
  if (v_type='inbound' and v_source_type not in ('customer_purchase_order','asn','transfer','return','manual_exception'))
    or (v_type='outbound' and v_source_type not in ('sales_order','transfer','return_to_supplier','disposal','manual_exception')) then
    raise exception 'WMS400: Choose a valid operational source type.';
  end if;
  if not ((p_payload->>'facilityId')::uuid = any(coalesce(p_allowed_facility_ids,'{}'::uuid[]))) then raise exception 'WMS403: Choose a warehouse in your workspace.'; end if;
  if not ((p_payload->>'customerOrgId')::uuid = any(coalesce(p_allowed_organisation_ids,'{}'::uuid[]))) then raise exception 'WMS403: Choose a valid customer.'; end if;
  if jsonb_typeof(p_payload->'lines') <> 'array' or jsonb_array_length(p_payload->'lines') = 0 then raise exception 'WMS400: Add at least one item line.'; end if;
  select * into v_facility from public."WMS_Facilities" where "WMSFacility_ID"=(p_payload->>'facilityId')::uuid and "WMSFacility_IsActive" and not "WMSFacility_IsDeleted" for share;
  if not found then raise exception 'WMS400: Choose a warehouse in your workspace.'; end if;
  v_number:=upper(left(v_type,2))||'-'||to_char(v_now,'YYYYMMDD-HH24MISS')||'-'||lpad((floor(random()*9000)+1000)::int::text,4,'0');
  insert into public."WMS_Orders" (
    "WMSOrder_ID","WMSOrder_FacilityID","WMSOrder_OrgOfficeID","WMSOrder_CustomerOrgID","WMSOrder_OrderNumber","WMSOrder_TypeCode","WMSOrder_StatusCode","WMSOrder_PriorityCode",
    "WMSOrder_CustomerReference","WMSOrder_SourceTypeCode","WMSOrder_SourceReference","WMSOrder_SourceRecordID","WMSOrder_RequestedDate","WMSOrder_AppointmentStartAt","WMSOrder_AppointmentEndAt",
    "WMSOrder_VehicleReg","WMSOrder_ContainerNumber","WMSOrder_SealNumber","WMSOrder_Instructions","WMSOrder_MetadataJSON","WMSOrder_CreatedBy","WMSOrder_UpdatedBy"
  ) values (
    v_order_id,v_facility."WMSFacility_ID",v_facility."WMSFacility_OrgOfficeID",(p_payload->>'customerOrgId')::uuid,v_number,v_type,'booked',coalesce(nullif(btrim(p_payload->>'priorityCode'),''),'normal'),
    coalesce(nullif(btrim(p_payload->>'customerReference'),''),v_source_reference),v_source_type,coalesce(v_source_reference,'Manual request '||left(v_order_id::text,8)),nullif(p_payload->>'sourceRecordId','')::uuid,nullif(p_payload->>'requestedDate','')::date,
    nullif(p_payload->>'appointmentStartAt','')::timestamptz,nullif(p_payload->>'appointmentEndAt','')::timestamptz,nullif(btrim(p_payload->>'vehicleReg'),''),upper(nullif(btrim(p_payload->>'containerNumber'),'')),
    nullif(btrim(p_payload->>'sealNumber'),''),nullif(btrim(p_payload->>'instructions'),''),jsonb_build_object('sourceNotes',nullif(btrim(p_payload->>'sourceNotes'),'')),p_actor_user_id,p_actor_user_id
  );
  if p_actor_portal_user_id is not null and v_type='inbound' then
    v_advice_id:=gen_random_uuid();
    insert into public."WMS_InboundAdvices" ("WMSAdvice_ID","WMSAdvice_FacilityID","WMSAdvice_OrderID","WMSAdvice_AdviceNumber","WMSAdvice_StatusCode","WMSAdvice_CustomerOrgID","WMSAdvice_ExpectedArrivalAt","WMSAdvice_ContainerNumber","WMSAdvice_SealNumber","WMSAdvice_MetadataJSON","WMSAdvice_CreatedAt")
    values(v_advice_id,v_facility."WMSFacility_ID",v_order_id,'ASN-'||v_number,'booked',(p_payload->>'customerOrgId')::uuid,nullif(p_payload->>'appointmentStartAt','')::timestamptz,upper(nullif(btrim(p_payload->>'containerNumber'),'')),nullif(btrim(p_payload->>'sealNumber'),''),'{"source":"customer_portal"}',v_now);
  end if;
  for v_input in select value from jsonb_array_elements(p_payload->'lines') loop
    v_index:=v_index+1; v_quantity:=nullif(v_input->>'quantity','')::numeric;
    if coalesce(v_quantity,0)<=0 then raise exception 'WMS400: Quantity must be greater than zero.'; end if;
    select item.* into v_item from public."WMS_Items" item
    join public."WMS_ItemFacilityAssignments" assignment on assignment."WMSItemFacility_ItemID"=item."WMSItem_ID" and assignment."WMSItemFacility_FacilityID"=v_facility."WMSFacility_ID" and assignment."WMSItemFacility_IsActive"
    where item."WMSItem_ID"=(v_input->>'itemId')::uuid and item."WMSItem_CustomerOrgID"=(p_payload->>'customerOrgId')::uuid and item."WMSItem_IsActive" and not item."WMSItem_IsDeleted";
    if not found then raise exception 'WMS400: One or more selected items are not enabled in this warehouse.'; end if;
    perform public._warehouse_edge_validate_quantity(v_item."WMSItem_ID",v_quantity);
    v_customs:=coalesce(nullif(btrim(v_input->>'customsStatusCode'),''),v_facility."WMSFacility_DefaultCustomsStatusCode");
    if v_type='outbound' and (select coalesce(sum(public._warehouse_edge_quantity_in_uom(v_item."WMSItem_ID",balance."WMSBalance_AvailableQuantity",balance."WMSBalance_UOMCode",upper(coalesce(nullif(btrim(v_input->>'uomCode'),''),v_item."WMSItem_BaseUOMCode")))),0) from public."WMS_InventoryBalances" balance where balance."WMSBalance_FacilityID"=v_facility."WMSFacility_ID" and balance."WMSBalance_CustomerOrgID"=v_item."WMSItem_CustomerOrgID" and balance."WMSBalance_ItemID"=v_item."WMSItem_ID" and balance."WMSBalance_InventoryStatusCode"='available' and balance."WMSBalance_CustomsStatusCode"=v_customs and balance."WMSBalance_AvailableQuantity">0 and ((v_input->>'sourceLocationId') is null or balance."WMSBalance_LocationID"=(v_input->>'sourceLocationId')::uuid)) < v_quantity then raise exception 'WMS409: There is not enough available stock for this outbound line.'; end if;
    v_line_id:=gen_random_uuid();
    insert into public."WMS_OrderLines" ("WMSOrderLine_ID","WMSOrderLine_OrderID","WMSOrderLine_LineNo","WMSOrderLine_ItemID","WMSOrderLine_StatusCode","WMSOrderLine_OrderedQuantity","WMSOrderLine_UOMCode","WMSOrderLine_LotNumber","WMSOrderLine_ExpiryDate","WMSOrderLine_SourceLocationID","WMSOrderLine_TargetLocationID","WMSOrderLine_InventoryStatusCode","WMSOrderLine_CustomsStatusCode","WMSOrderLine_GoodsValue","WMSOrderLine_CurrencyCode","WMSOrderLine_Instructions","WMSOrderLine_MetadataJSON")
    values(v_line_id,v_order_id,v_index,v_item."WMSItem_ID",'open',v_quantity,upper(coalesce(nullif(btrim(v_input->>'uomCode'),''),v_item."WMSItem_BaseUOMCode")),nullif(btrim(v_input->>'lotNumber'),''),nullif(v_input->>'expiryDate','')::date,nullif(v_input->>'sourceLocationId','')::uuid,nullif(v_input->>'targetLocationId','')::uuid,'available',v_customs,nullif(v_input->>'goodsValue','')::numeric,upper(nullif(btrim(v_input->>'currencyCode'),'')),nullif(btrim(v_input->>'instructions'),''),'{}');
    if v_advice_id is not null then insert into public."WMS_InboundAdviceLines" ("WMSAdviceLine_ID","WMSAdviceLine_AdviceID","WMSAdviceLine_OrderLineID","WMSAdviceLine_LineNo","WMSAdviceLine_ItemID","WMSAdviceLine_ExpectedQuantity","WMSAdviceLine_UOMCode","WMSAdviceLine_LotNumber","WMSAdviceLine_ExpiryDate","WMSAdviceLine_CustomsStatusCode") values(gen_random_uuid(),v_advice_id,v_line_id,v_index,v_item."WMSItem_ID",v_quantity,upper(coalesce(nullif(btrim(v_input->>'uomCode'),''),v_item."WMSItem_BaseUOMCode")),nullif(btrim(v_input->>'lotNumber'),''),nullif(v_input->>'expiryDate','')::date,v_customs); end if;
  end loop;
  return v_order_id;
end;
$$;


ALTER FUNCTION "public"."warehouse_edge_create_order_mutation"("p_payload" "jsonb", "p_actor_user_id" "uuid", "p_actor_portal_user_id" "uuid", "p_allowed_facility_ids" "uuid"[], "p_allowed_organisation_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."warehouse_edge_dashboard"("p_company_id" "uuid", "p_allowed_organisation_ids" "uuid"[] DEFAULT '{}'::"uuid"[], "p_allowed_facility_ids" "uuid"[] DEFAULT '{}'::"uuid"[], "p_movement_take" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_facility_ids uuid[] := coalesce(p_allowed_facility_ids, '{}'::uuid[]);
  v_organisation_ids uuid[] := coalesce(p_allowed_organisation_ids, '{}'::uuid[]);
  v_orders jsonb := '[]'::jsonb;
  v_metrics jsonb := jsonb_build_object('onHandSkus', 0, 'availableSkus', 0, 'heldBalances', 0);
  v_movements jsonb := '[]'::jsonb;
begin
  if p_company_id is not null then
    select coalesce(array_agg(facility."WMSFacility_ID"), '{}'::uuid[])
    into v_facility_ids
    from public."WMS_Facilities" facility
    join public."cmp_Offices" office
      on office."Office_ID" = facility."WMSFacility_OrgOfficeID"
    where office."Company_ID" = p_company_id
      and not facility."WMSFacility_IsDeleted";
  end if;

  if coalesce(array_length(v_facility_ids, 1), 0) = 0 then
    return jsonb_build_object('orders', v_orders, 'metrics', v_metrics, 'movements', v_movements);
  end if;

  with scoped_orders as materialized (
    select warehouse_order.*,
           facility."WMSFacility_Code" as facility_code,
           facility."WMSFacility_Name" as facility_name,
           organisation."Org_Name" as customer_name,
           order_type."WMSOrderType_Name" as type_name,
           order_status."WMSOrderStatus_Name" as status_name
    from public."WMS_Orders" warehouse_order
    join public."WMS_Facilities" facility
      on facility."WMSFacility_ID" = warehouse_order."WMSOrder_FacilityID"
    left join public."Org_Master" organisation
      on organisation."Org_id" = warehouse_order."WMSOrder_CustomerOrgID"
    left join public."sys_WMSOrderTypes" order_type
      on order_type."WMSOrderType_Code" = warehouse_order."WMSOrder_TypeCode"
    left join public."sys_WMSOrderStatuses" order_status
      on order_status."WMSOrderStatus_Code" = warehouse_order."WMSOrder_StatusCode"
    where warehouse_order."WMSOrder_FacilityID" = any(v_facility_ids)
      and not warehouse_order."WMSOrder_IsDeleted"
      and (
        p_company_id is not null
        or warehouse_order."WMSOrder_CustomerOrgID" = any(v_organisation_ids)
      )
    order by warehouse_order."WMSOrder_CreatedAt" desc
    limit 500
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', warehouse_order."WMSOrder_ID",
    'facilityId', warehouse_order."WMSOrder_FacilityID",
    'facilityCode', warehouse_order.facility_code,
    'facilityName', warehouse_order.facility_name,
    'officeId', warehouse_order."WMSOrder_OrgOfficeID",
    'officeName', null,
    'customerOrgId', warehouse_order."WMSOrder_CustomerOrgID",
    'customerName', coalesce(warehouse_order.customer_name, ''),
    'orderNumber', warehouse_order."WMSOrder_OrderNumber",
    'typeCode', warehouse_order."WMSOrder_TypeCode",
    'typeName', warehouse_order.type_name,
    'statusCode', warehouse_order."WMSOrder_StatusCode",
    'statusName', warehouse_order.status_name,
    'priorityCode', warehouse_order."WMSOrder_PriorityCode",
    'customerReference', warehouse_order."WMSOrder_CustomerReference",
    'requestedDate', warehouse_order."WMSOrder_RequestedDate",
    'appointmentStartAt', warehouse_order."WMSOrder_AppointmentStartAt",
    'appointmentEndAt', warehouse_order."WMSOrder_AppointmentEndAt",
    'vehicleReg', warehouse_order."WMSOrder_VehicleReg",
    'containerNumber', warehouse_order."WMSOrder_ContainerNumber",
    'sealNumber', warehouse_order."WMSOrder_SealNumber",
    'instructions', warehouse_order."WMSOrder_Instructions",
    'createdAt', warehouse_order."WMSOrder_CreatedAt",
    'updatedAt', warehouse_order."WMSOrder_UpdatedAt",
    'lines', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', order_line."WMSOrderLine_ID",
        'lineNumber', order_line."WMSOrderLine_LineNo",
        'itemId', order_line."WMSOrderLine_ItemID",
        'sku', coalesce(item."WMSItem_SKU", ''),
        'description', coalesce(item."WMSItem_Description", ''),
        'statusCode', order_line."WMSOrderLine_StatusCode",
        'orderedQuantity', order_line."WMSOrderLine_OrderedQuantity",
        'receivedQuantity', order_line."WMSOrderLine_ReceivedQuantity",
        'pickedQuantity', order_line."WMSOrderLine_PickedQuantity",
        'packedQuantity', order_line."WMSOrderLine_PackedQuantity",
        'dispatchedQuantity', order_line."WMSOrderLine_DispatchedQuantity",
        'remainingQuantity', greatest(0, order_line."WMSOrderLine_OrderedQuantity" - case when warehouse_order."WMSOrder_TypeCode" = 'inbound' then order_line."WMSOrderLine_ReceivedQuantity" else order_line."WMSOrderLine_DispatchedQuantity" end),
        'uomCode', order_line."WMSOrderLine_UOMCode",
        'lotNumber', order_line."WMSOrderLine_LotNumber",
        'expiryDate', order_line."WMSOrderLine_ExpiryDate",
        'sourceLocationId', order_line."WMSOrderLine_SourceLocationID",
        'sourceLocationCode', source_location."WMSLocation_Code",
        'targetLocationId', order_line."WMSOrderLine_TargetLocationID",
        'targetLocationCode', target_location."WMSLocation_Code",
        'inventoryStatusCode', order_line."WMSOrderLine_InventoryStatusCode",
        'customsStatusCode', order_line."WMSOrderLine_CustomsStatusCode",
        'goodsValue', order_line."WMSOrderLine_GoodsValue",
        'currencyCode', order_line."WMSOrderLine_CurrencyCode",
        'instructions', order_line."WMSOrderLine_Instructions"
      ) order by order_line."WMSOrderLine_LineNo")
      from public."WMS_OrderLines" order_line
      left join public."WMS_Items" item
        on item."WMSItem_ID" = order_line."WMSOrderLine_ItemID"
      left join public."WMS_Locations" source_location
        on source_location."WMSLocation_ID" = order_line."WMSOrderLine_SourceLocationID"
      left join public."WMS_Locations" target_location
        on target_location."WMSLocation_ID" = order_line."WMSOrderLine_TargetLocationID"
      where order_line."WMSOrderLine_OrderID" = warehouse_order."WMSOrder_ID"
    ), '[]'::jsonb),
    'receipts', '[]'::jsonb,
    'dispatches', '[]'::jsonb
  ) order by warehouse_order."WMSOrder_CreatedAt" desc), '[]'::jsonb)
  into v_orders
  from scoped_orders warehouse_order;

  select jsonb_build_object(
    'onHandSkus', count(distinct balance."WMSBalance_ItemID") filter (where balance."WMSBalance_OnHandQuantity" > 0),
    'availableSkus', count(distinct balance."WMSBalance_ItemID") filter (where balance."WMSBalance_AvailableQuantity" > 0),
    'heldBalances', count(*) filter (where balance."WMSBalance_HeldQuantity" > 0 or balance."WMSBalance_InventoryStatusCode" <> 'available')
  )
  into v_metrics
  from public."WMS_InventoryBalances" balance
  where balance."WMSBalance_FacilityID" = any(v_facility_ids)
    and balance."WMSBalance_OnHandQuantity" <> 0
    and (
      p_company_id is not null
      or balance."WMSBalance_CustomerOrgID" = any(v_organisation_ids)
    );

  with recent_movements as materialized (
    select movement.*,
           facility."WMSFacility_Name" as facility_name,
           item."WMSItem_SKU" as item_sku,
           item."WMSItem_Description" as item_description,
           from_location."WMSLocation_Code" as from_location_code,
           to_location."WMSLocation_Code" as to_location_code,
           lot."WMSLot_LotNumber" as lot_number,
           lot."WMSLot_BatchNumber" as batch_number
    from public."WMS_InventoryTransactions" movement
    join public."WMS_Facilities" facility
      on facility."WMSFacility_ID" = movement."WMSTransaction_FacilityID"
    left join public."WMS_Items" item
      on item."WMSItem_ID" = movement."WMSTransaction_ItemID"
    left join public."WMS_Locations" from_location
      on from_location."WMSLocation_ID" = movement."WMSTransaction_FromLocationID"
    left join public."WMS_Locations" to_location
      on to_location."WMSLocation_ID" = movement."WMSTransaction_ToLocationID"
    left join public."WMS_InventoryLots" lot
      on lot."WMSLot_ID" = movement."WMSTransaction_LotID"
    where movement."WMSTransaction_FacilityID" = any(v_facility_ids)
      and (
        p_company_id is not null
        or movement."WMSTransaction_CustomerOrgID" = any(v_organisation_ids)
      )
    order by movement."WMSTransaction_CreatedAt" desc
    limit greatest(1, least(coalesce(p_movement_take, 50), 100))
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', movement."WMSTransaction_ID",
    'facilityId', movement."WMSTransaction_FacilityID",
    'facilityName', movement.facility_name,
    'itemId', movement."WMSTransaction_ItemID",
    'sku', coalesce(movement.item_sku, ''),
    'itemDescription', coalesce(movement.item_description, ''),
    'typeCode', movement."WMSTransaction_TypeCode",
    'typeName', movement."WMSTransaction_TypeCode",
    'quantity', movement."WMSTransaction_Quantity",
    'uomCode', movement."WMSTransaction_UOMCode",
    'fromLocationCode', movement.from_location_code,
    'toLocationCode', movement.to_location_code,
    'lotNumber', movement.lot_number,
    'batchNumber', movement.batch_number,
    'reference', movement."WMSTransaction_Reference",
    'notes', movement."WMSTransaction_Notes",
    'createdAt', movement."WMSTransaction_CreatedAt"
  ) order by movement."WMSTransaction_CreatedAt" desc), '[]'::jsonb)
  into v_movements
  from recent_movements movement;

  return jsonb_build_object('orders', v_orders, 'metrics', v_metrics, 'movements', v_movements);
end;
$$;


ALTER FUNCTION "public"."warehouse_edge_dashboard"("p_company_id" "uuid", "p_allowed_organisation_ids" "uuid"[], "p_allowed_facility_ids" "uuid"[], "p_movement_take" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."warehouse_edge_dashboard_summary"("p_company_id" "uuid", "p_allowed_organisation_ids" "uuid"[] DEFAULT '{}'::"uuid"[], "p_allowed_facility_ids" "uuid"[] DEFAULT '{}'::"uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_facility_ids uuid[] := coalesce(p_allowed_facility_ids, '{}'::uuid[]);
  v_organisation_ids uuid[] := coalesce(p_allowed_organisation_ids, '{}'::uuid[]);
  v_ready_to_receive bigint := 0;
  v_ready_to_dispatch bigint := 0;
  v_stock_holds bigint := 0;
  v_past_due bigint := 0;
  v_booked_today bigint := 0;
  v_on_hand_skus bigint := 0;
  v_available_skus bigint := 0;
begin
  if p_company_id is not null then
    select coalesce(array_agg(facility."WMSFacility_ID"), '{}'::uuid[])
    into v_facility_ids
    from public."WMS_Facilities" facility
    join public."cmp_Offices" office on office."Office_ID" = facility."WMSFacility_OrgOfficeID"
    where office."Company_ID" = p_company_id and not facility."WMSFacility_IsDeleted";
  end if;

  if coalesce(cardinality(v_facility_ids), 0) = 0 then
    return jsonb_build_object(
      'readyToReceive', 0, 'readyToDispatch', 0, 'stockHolds', 0,
      'pastDue', 0, 'bookedToday', 0, 'onHandSkus', 0, 'availableSkus', 0
    );
  end if;

  select
    count(*) filter (where warehouse_order."WMSOrder_TypeCode" = 'inbound'),
    count(*) filter (where warehouse_order."WMSOrder_TypeCode" = 'outbound'),
    count(*) filter (where coalesce(warehouse_order."WMSOrder_AppointmentStartAt"::date, warehouse_order."WMSOrder_RequestedDate") < current_date),
    count(*) filter (where coalesce(warehouse_order."WMSOrder_AppointmentStartAt"::date, warehouse_order."WMSOrder_RequestedDate") = current_date)
  into v_ready_to_receive, v_ready_to_dispatch, v_past_due, v_booked_today
  from public."WMS_Orders" warehouse_order
  join public."sys_WMSOrderStatuses" order_status
    on order_status."WMSOrderStatus_Code" = warehouse_order."WMSOrder_StatusCode"
  where warehouse_order."WMSOrder_FacilityID" = any(v_facility_ids)
    and not warehouse_order."WMSOrder_IsDeleted"
    and order_status."WMSOrderStatus_IsOpen"
    and (p_company_id is not null or warehouse_order."WMSOrder_CustomerOrgID" = any(v_organisation_ids));

  select
    count(*) filter (where balance."WMSBalance_HeldQuantity" > 0 or balance."WMSBalance_InventoryStatusCode" <> 'available'),
    count(distinct balance."WMSBalance_ItemID") filter (where balance."WMSBalance_OnHandQuantity" > 0),
    count(distinct balance."WMSBalance_ItemID") filter (where balance."WMSBalance_AvailableQuantity" > 0)
  into v_stock_holds, v_on_hand_skus, v_available_skus
  from public."WMS_InventoryBalances" balance
  where balance."WMSBalance_FacilityID" = any(v_facility_ids)
    and balance."WMSBalance_OnHandQuantity" <> 0
    and (balance."WMSBalance_HeldQuantity" > 0 or balance."WMSBalance_InventoryStatusCode" <> 'available')
    and (p_company_id is not null or balance."WMSBalance_CustomerOrgID" = any(v_organisation_ids));

  return jsonb_build_object(
    'readyToReceive', v_ready_to_receive,
    'readyToDispatch', v_ready_to_dispatch,
    'stockHolds', v_stock_holds,
    'pastDue', v_past_due,
    'bookedToday', v_booked_today,
    'onHandSkus', v_on_hand_skus,
    'availableSkus', v_available_skus
  );
end;
$$;


ALTER FUNCTION "public"."warehouse_edge_dashboard_summary"("p_company_id" "uuid", "p_allowed_organisation_ids" "uuid"[], "p_allowed_facility_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."warehouse_edge_dashboard_summary"("p_company_id" "uuid", "p_allowed_organisation_ids" "uuid"[], "p_allowed_facility_ids" "uuid"[]) IS 'Service-role-only, allowlist-scoped exact Warehouse dashboard metric summary.';



CREATE OR REPLACE FUNCTION "public"."warehouse_edge_dispatch_mutation"("p_order_id" "uuid", "p_payload" "jsonb", "p_actor_user_id" "uuid", "p_allowed_facility_ids" "uuid"[], "p_allowed_organisation_ids" "uuid"[]) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_order public."WMS_Orders"%rowtype; v_line public."WMS_OrderLines"%rowtype; v_task public."WMS_Tasks"%rowtype; v_balance public."WMS_InventoryBalances"%rowtype;
  v_input jsonb; v_request_id uuid:=nullif(p_payload->>'requestId','')::uuid; v_dispatch_id uuid; v_number text; v_quantity numeric; v_remaining numeric; v_take numeric; v_before numeric; v_balance_take numeric; v_complete boolean; v_now timestamptz:=now();
begin
  if p_actor_user_id is null then raise exception 'WMS403: Dispatch is reserved for the warehouse team.'; end if;
  if v_request_id is null then raise exception 'WMS400: A request identifier is required.'; end if;
  select * into v_order from public."WMS_Orders" where "WMSOrder_ID"=p_order_id and "WMSOrder_FacilityID"=any(coalesce(p_allowed_facility_ids,'{}'::uuid[])) and "WMSOrder_CustomerOrgID"=any(coalesce(p_allowed_organisation_ids,'{}'::uuid[])) and not "WMSOrder_IsDeleted" for update;
  if not found then raise exception 'WMS404: This warehouse order does not exist in your workspace.'; end if;
  if v_order."WMSOrder_TypeCode"<>'outbound' or v_order."WMSOrder_StatusCode" in ('complete','cancelled') then raise exception 'WMS409: This outbound order cannot be dispatched.'; end if;
  if exists(select 1 from public."WMS_Dispatches" where "WMSDispatch_OrderID"=p_order_id and "WMSDispatch_MetadataJSON"->>'requestId'=v_request_id::text) then return p_order_id; end if;
  if jsonb_typeof(p_payload->'lines')<>'array' or jsonb_array_length(p_payload->'lines')=0 then raise exception 'WMS400: Add at least one dispatch line.'; end if;
  v_dispatch_id:=gen_random_uuid(); v_number:='DSP-'||to_char(v_now,'YYYYMMDD-HH24MISS')||'-'||lpad((floor(random()*9000)+1000)::int::text,4,'0');
  insert into public."WMS_Dispatches" ("WMSDispatch_ID","WMSDispatch_FacilityID","WMSDispatch_OrderID","WMSDispatch_JobID","WMSDispatch_DispatchNumber","WMSDispatch_StatusCode","WMSDispatch_VehicleReg","WMSDispatch_ContainerNumber","WMSDispatch_SealNumber","WMSDispatch_DispatchedAt","WMSDispatch_DispatchedBy","WMSDispatch_MetadataJSON") values(v_dispatch_id,v_order."WMSOrder_FacilityID",p_order_id,v_order."WMSOrder_JobID",v_number,'complete',coalesce(nullif(btrim(p_payload->>'vehicleReg'),''),v_order."WMSOrder_VehicleReg"),coalesce(upper(nullif(btrim(p_payload->>'containerNumber'),'')),v_order."WMSOrder_ContainerNumber"),coalesce(nullif(btrim(p_payload->>'sealNumber'),''),v_order."WMSOrder_SealNumber"),v_now,p_actor_user_id,jsonb_build_object('requestId',v_request_id,'notes',nullif(btrim(p_payload->>'notes'),'')));
  for v_input in select value from jsonb_array_elements(p_payload->'lines') loop
    select * into v_line from public."WMS_OrderLines" where "WMSOrderLine_ID"=(v_input->>'orderLineId')::uuid and "WMSOrderLine_OrderID"=p_order_id for update;
    if not found then raise exception 'WMS400: A dispatch line does not belong to this order.'; end if;
    v_quantity:=nullif(v_input->>'quantity','')::numeric;
    if coalesce(v_quantity,0)<=0 or v_quantity>v_line."WMSOrderLine_PickedQuantity"-v_line."WMSOrderLine_DispatchedQuantity" then raise exception 'WMS409: Dispatch only quantities that warehouse staff have picked.'; end if;
    v_remaining:=v_quantity;
    for v_task in select task.* from public."WMS_Tasks" task where task."WMSTask_TypeCode"='pick' and task."WMSTask_OrderLineID"=v_line."WMSOrderLine_ID" and task."WMSTask_CompletedQuantity">coalesce((task."WMSTask_MetadataJSON"->>'dispatchedQuantity')::numeric,0) order by task."WMSTask_CreatedAt",task."WMSTask_ID" for update loop
      exit when v_remaining<=0; v_take:=least(v_remaining,v_task."WMSTask_CompletedQuantity"-coalesce((v_task."WMSTask_MetadataJSON"->>'dispatchedQuantity')::numeric,0));
      select * into v_balance from public."WMS_InventoryBalances" where "WMSBalance_ID"=v_task."WMSTask_BalanceID" for update;
      if not found then raise exception 'WMS409: Picked stock balance is missing.'; end if;
      v_balance_take:=public._warehouse_edge_task_balance_quantity(v_take,v_task."WMSTask_UOMCode",v_balance."WMSBalance_UOMCode",v_task."WMSTask_MetadataJSON");
      if v_balance."WMSBalance_OnHandQuantity"<v_balance_take or v_balance."WMSBalance_AllocatedQuantity"<v_balance_take then raise exception 'WMS409: Picked stock no longer matches its allocated balance.'; end if;
      v_before:=v_balance."WMSBalance_OnHandQuantity";
      update public."WMS_InventoryBalances" set "WMSBalance_OnHandQuantity"="WMSBalance_OnHandQuantity"-v_balance_take,"WMSBalance_AllocatedQuantity"="WMSBalance_AllocatedQuantity"-v_balance_take,"WMSBalance_UpdatedAt"=v_now,"WMSBalance_LastMovementAt"=v_now where "WMSBalance_ID"=v_balance."WMSBalance_ID";
      update public."WMS_Tasks" set "WMSTask_MetadataJSON"=jsonb_set("WMSTask_MetadataJSON",'{dispatchedQuantity}',to_jsonb(coalesce(("WMSTask_MetadataJSON"->>'dispatchedQuantity')::numeric,0)+v_take),true) where "WMSTask_ID"=v_task."WMSTask_ID";
      insert into public."WMS_InventoryTransactions" ("WMSTransaction_FacilityID","WMSTransaction_BalanceID","WMSTransaction_TypeCode","WMSTransaction_ItemID","WMSTransaction_CustomerOrgID","WMSTransaction_FromLocationID","WMSTransaction_LotID","WMSTransaction_HU_ID","WMSTransaction_Quantity","WMSTransaction_UOMCode","WMSTransaction_BeforeOnHandQuantity","WMSTransaction_AfterOnHandQuantity","WMSTransaction_InventoryStatusCode","WMSTransaction_CustomsStatusCode","WMSTransaction_OrderID","WMSTransaction_OrderLineID","WMSTransaction_TaskID","WMSTransaction_SourceTable","WMSTransaction_SourceID","WMSTransaction_Reference","WMSTransaction_Notes","WMSTransaction_MetadataJSON","WMSTransaction_ReasonCode","WMSTransaction_IdempotencyKey","WMSTransaction_CreatedBy") values(v_order."WMSOrder_FacilityID",v_balance."WMSBalance_ID",'dispatch',v_line."WMSOrderLine_ItemID",v_order."WMSOrder_CustomerOrgID",v_balance."WMSBalance_LocationID",v_balance."WMSBalance_LotID",v_balance."WMSBalance_HU_ID",v_balance_take,v_balance."WMSBalance_UOMCode",v_before,v_before-v_balance_take,'available',v_line."WMSOrderLine_CustomsStatusCode",p_order_id,v_line."WMSOrderLine_ID",v_task."WMSTask_ID",'WMS_Dispatches',v_dispatch_id,v_number,nullif(btrim(p_payload->>'notes'),''),jsonb_build_object('requestId',v_request_id),'dispatch_picked_stock',v_request_id,p_actor_user_id);
      v_remaining:=v_remaining-v_take;
    end loop;
    if v_remaining>0 then raise exception 'WMS409: Picked stock evidence is incomplete for this dispatch.'; end if;
    update public."WMS_OrderLines" set "WMSOrderLine_DispatchedQuantity"="WMSOrderLine_DispatchedQuantity"+v_quantity,"WMSOrderLine_StatusCode"=case when "WMSOrderLine_DispatchedQuantity"+v_quantity>="WMSOrderLine_OrderedQuantity" then 'dispatched' else 'picked' end where "WMSOrderLine_ID"=v_line."WMSOrderLine_ID";
  end loop;
  select bool_and("WMSOrderLine_DispatchedQuantity">="WMSOrderLine_OrderedQuantity") into v_complete from public."WMS_OrderLines" where "WMSOrderLine_OrderID"=p_order_id and "WMSOrderLine_StatusCode"<>'cancelled';
  update public."WMS_Orders" set "WMSOrder_StatusCode"=case when v_complete then 'complete' else 'part_complete' end,"WMSOrder_UpdatedAt"=v_now,"WMSOrder_UpdatedBy"=p_actor_user_id where "WMSOrder_ID"=p_order_id;
  return p_order_id;
end;
$$;


ALTER FUNCTION "public"."warehouse_edge_dispatch_mutation"("p_order_id" "uuid", "p_payload" "jsonb", "p_actor_user_id" "uuid", "p_allowed_facility_ids" "uuid"[], "p_allowed_organisation_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."warehouse_edge_draft_order_availability"("p_allowed_facility_ids" "uuid"[], "p_allowed_org_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_facility_id" "uuid" DEFAULT NULL::"uuid", "p_customer_org_id" "uuid" DEFAULT NULL::"uuid", "p_queries" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_result jsonb;
begin
  if p_facility_id is null
    or p_customer_org_id is null
    or not (p_facility_id = any(coalesce(p_allowed_facility_ids, '{}'::uuid[])))
    or (p_allowed_org_ids is not null and not (p_customer_org_id = any(p_allowed_org_ids)))
    or jsonb_typeof(p_queries) <> 'array'
    or jsonb_array_length(p_queries) > 100 then
    return '[]'::jsonb;
  end if;

  with requirements as materialized (
    select
      entry.value->>'key' as query_key,
      (entry.value->>'itemId')::uuid as item_id,
      nullif(entry.value->>'locationId', '')::uuid as location_id,
      nullif(btrim(entry.value->>'lotNumber'), '') as lot_number,
      coalesce(nullif(btrim(entry.value->>'customsStatusCode'), ''), 'free_circulation') as customs_status_code,
      coalesce(nullif(btrim(entry.value->>'uomCode'), ''), 'EA') as uom_code,
      entry.ordinality as position
    from jsonb_array_elements(p_queries) with ordinality as entry(value, ordinality)
  ), eligible as materialized (
    select requirement.*
    from requirements requirement
    join public."WMS_Items" item
      on item."WMSItem_ID" = requirement.item_id
      and item."WMSItem_DefaultFacilityID" = p_facility_id
      and item."WMSItem_CustomerOrgID" = p_customer_org_id
      and item."WMSItem_IsActive"
      and not item."WMSItem_IsDeleted"
  ), totals as (
    select
      requirement.query_key,
      requirement.uom_code,
      requirement.position,
      coalesce(sum(balance."WMSBalance_AvailableQuantity") filter (
        where requirement.lot_number is null
          or lot."WMSLot_LotNumber" = requirement.lot_number
      ), 0) as available
    from eligible requirement
    left join public."WMS_InventoryBalances" balance
      on balance."WMSBalance_FacilityID" = p_facility_id
      and balance."WMSBalance_CustomerOrgID" = p_customer_org_id
      and balance."WMSBalance_ItemID" = requirement.item_id
      and balance."WMSBalance_InventoryStatusCode" = 'available'
      and balance."WMSBalance_CustomsStatusCode" = requirement.customs_status_code
      and balance."WMSBalance_UOMCode" = requirement.uom_code
      and balance."WMSBalance_AvailableQuantity" > 0
      and (requirement.location_id is null or balance."WMSBalance_LocationID" = requirement.location_id)
    left join public."WMS_InventoryLots" lot
      on lot."WMSLot_ID" = balance."WMSBalance_LotID"
    group by requirement.query_key, requirement.uom_code, requirement.position
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'key', total.query_key,
    'available', total.available,
    'uomCode', total.uom_code
  ) order by total.position), '[]'::jsonb)
  into v_result
  from totals total;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."warehouse_edge_draft_order_availability"("p_allowed_facility_ids" "uuid"[], "p_allowed_org_ids" "uuid"[], "p_facility_id" "uuid", "p_customer_org_id" "uuid", "p_queries" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."warehouse_edge_draft_order_availability"("p_allowed_facility_ids" "uuid"[], "p_allowed_org_ids" "uuid"[], "p_facility_id" "uuid", "p_customer_org_id" "uuid", "p_queries" "jsonb") IS 'Returns up to 100 exact stock totals for visible outbound-order choices without exposing inventory rows.';



CREATE OR REPLACE FUNCTION "public"."warehouse_edge_existing_item_skus"("p_customer_org_id" "uuid", "p_skus" "text"[]) RETURNS "text"[]
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select coalesce(array_agg(lower(item."WMSItem_SKU") order by lower(item."WMSItem_SKU")), array[]::text[])
  from public."WMS_Items" item
  where item."WMSItem_CustomerOrgID" = p_customer_org_id
    and not item."WMSItem_IsDeleted"
    and lower(item."WMSItem_SKU") = any(coalesce(p_skus, array[]::text[]));
$$;


ALTER FUNCTION "public"."warehouse_edge_existing_item_skus"("p_customer_org_id" "uuid", "p_skus" "text"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."warehouse_edge_existing_item_skus"("p_customer_org_id" "uuid", "p_skus" "text"[]) IS 'Returns only existing case-insensitive SKUs for one customer and a bounded uploaded SKU set.';



CREATE OR REPLACE FUNCTION "public"."warehouse_edge_handling_units_page"("p_allowed_facility_ids" "uuid"[], "p_allowed_org_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_customer_org_id" "uuid" DEFAULT NULL::"uuid", "p_search" "text" DEFAULT NULL::"text", "p_facet" "text" DEFAULT NULL::"text", "p_include_consumed" boolean DEFAULT false, "p_sort" "text" DEFAULT NULL::"text", "p_direction" "text" DEFAULT 'desc'::"text", "p_limit" integer DEFAULT 20, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_limit integer := greatest(1, least(coalesce(p_limit, 20), 50));
  v_offset integer := greatest(0, coalesce(p_offset, 0));
  v_search text := lower(nullif(btrim(p_search), ''));
  v_facet text := nullif(btrim(p_facet), '');
  v_direction text := case when lower(p_direction) = 'asc' then 'asc' else 'desc' end;
  v_result jsonb;
begin
  if coalesce(cardinality(p_allowed_facility_ids), 0) = 0 then
    return jsonb_build_object('rows', '[]'::jsonb, 'total', 0, 'limit', v_limit, 'offset', v_offset, 'facets', '[]'::jsonb);
  end if;

  with base as materialized (
    select
      handling_unit.*,
      coalesce(unit_type."WMSHUType_Name", handling_unit."WMSHU_TypeCode") as type_name,
      organisation."Org_Name" as customer_name,
      location."WMSLocation_Code" as location_code,
      coalesce(inventory_status."WMSInventoryStatus_Name", handling_unit."WMSHU_InventoryStatusCode") as inventory_status_name,
      (select count(*) from public."WMS_InventoryBalances" balance where balance."WMSBalance_HU_ID" = handling_unit."WMSHU_ID" and balance."WMSBalance_OnHandQuantity" > 0) as contents_count
    from public."WMS_HandlingUnits" handling_unit
    left join public."sys_WMSHandlingUnitTypes" unit_type on unit_type."WMSHUType_Code" = handling_unit."WMSHU_TypeCode"
    left join public."Org_Master" organisation on organisation."Org_id" = handling_unit."WMSHU_CustomerOrgID"
    left join public."WMS_Locations" location on location."WMSLocation_ID" = handling_unit."WMSHU_LocationID"
    left join public."sys_WMSInventoryStatuses" inventory_status on inventory_status."WMSInventoryStatus_Code" = handling_unit."WMSHU_InventoryStatusCode"
    where handling_unit."WMSHU_FacilityID" = any(p_allowed_facility_ids)
      and (p_allowed_org_ids is null or handling_unit."WMSHU_CustomerOrgID" = any(p_allowed_org_ids))
      and (p_customer_org_id is null or handling_unit."WMSHU_CustomerOrgID" = p_customer_org_id)
      and not handling_unit."WMSHU_IsDeleted"
      and (p_include_consumed or handling_unit."WMSHU_LifecycleStatusCode" <> 'consumed')
      and (v_search is null or strpos(lower(concat_ws(' ', handling_unit."WMSHU_Code", handling_unit."WMSHU_SSCC",
        handling_unit."WMSHU_ExternalReference", organisation."Org_Name", location."WMSLocation_Code"
      )), v_search) > 0)
  ), filtered as materialized (
    select * from base where v_facet is null or type_name = v_facet
  ), ranked as (
    select *, row_number() over (
      order by
        case when v_direction = 'asc' then case p_sort
          when 'object-object' then lower("WMSHU_Code") when 'object-customer' then lower(customer_name)
          when 'object-location' then lower(location_code) when 'object-status' then lower(inventory_status_name)
        end end asc nulls last,
        case when v_direction = 'desc' then case p_sort
          when 'object-object' then lower("WMSHU_Code") when 'object-customer' then lower(customer_name)
          when 'object-location' then lower(location_code) when 'object-status' then lower(inventory_status_name)
        end end desc nulls last,
        case when v_direction = 'asc' and p_sort = 'object-contents' then contents_count end asc nulls last,
        case when v_direction = 'desc' and p_sort = 'object-contents' then contents_count end desc nulls last,
        case when v_direction = 'asc' and p_sort = 'object-weight' then "WMSHU_GrossWeightKG" end asc nulls last,
        case when v_direction = 'desc' and p_sort = 'object-weight' then "WMSHU_GrossWeightKG" end desc nulls last,
        case when p_sort is null and v_direction = 'asc' then "WMSHU_UpdatedAt" end asc,
        case when p_sort is null and v_direction = 'desc' then "WMSHU_UpdatedAt" end desc,
        "WMSHU_ID"
    ) as ordinal
    from filtered
  ), page as (
    select * from ranked where ordinal > v_offset and ordinal <= v_offset + v_limit
  )
  select jsonb_build_object(
    'rows', coalesce((select jsonb_agg(jsonb_build_object(
      'id', row."WMSHU_ID", 'facilityId', row."WMSHU_FacilityID", 'parentHandlingUnitId', row."WMSHU_ParentHU_ID",
      'typeCode', row."WMSHU_TypeCode", 'typeName', row.type_name, 'code', row."WMSHU_Code", 'sscc', row."WMSHU_SSCC",
      'externalReference', row."WMSHU_ExternalReference", 'customerOrgId', row."WMSHU_CustomerOrgID",
      'customerName', row.customer_name, 'locationId', row."WMSHU_LocationID", 'locationCode', row.location_code,
      'inventoryStatusCode', row."WMSHU_InventoryStatusCode", 'inventoryStatusName', row.inventory_status_name,
      'customsStatusCode', row."WMSHU_CustomsStatusCode", 'lifecycleStatusCode', row."WMSHU_LifecycleStatusCode",
      'consumedIntoHandlingUnitId', row."WMSHU_ConsumedIntoHU_ID", 'grossWeightKg', row."WMSHU_GrossWeightKG",
      'netWeightKg', row."WMSHU_NetWeightKG", 'volumeCbm', row."WMSHU_VolumeCBM", 'sealed', row."WMSHU_IsSealed",
      'updatedAt', row."WMSHU_UpdatedAt",
      'contents', coalesce((select jsonb_agg(jsonb_build_object(
        'balanceId', balance."WMSBalance_ID", 'itemId', balance."WMSBalance_ItemID", 'sku', item."WMSItem_SKU",
        'description', item."WMSItem_Description", 'quantity', balance."WMSBalance_OnHandQuantity",
        'uomCode', balance."WMSBalance_UOMCode", 'statusCode', balance."WMSBalance_InventoryStatusCode",
        'customsStatusCode', balance."WMSBalance_CustomsStatusCode", 'lotNumber', lot."WMSLot_LotNumber",
        'batchNumber', lot."WMSLot_BatchNumber"
      ) order by item."WMSItem_SKU", balance."WMSBalance_ID")
        from public."WMS_InventoryBalances" balance
        join public."WMS_Items" item on item."WMSItem_ID" = balance."WMSBalance_ItemID"
        left join public."WMS_InventoryLots" lot on lot."WMSLot_ID" = balance."WMSBalance_LotID"
        where balance."WMSBalance_HU_ID" = row."WMSHU_ID" and balance."WMSBalance_OnHandQuantity" > 0), '[]'::jsonb),
      'events', coalesce((select jsonb_agg(event_payload order by event_at desc) from (
        select jsonb_build_object('id', event."WMSHUEvent_ID", 'typeCode', event."WMSHUEvent_EventTypeCode",
          'at', event."WMSHUEvent_EventAt", 'locationId', event."WMSHUEvent_LocationID", 'notes', event."WMSHUEvent_Notes",
          'metadata', coalesce(event."WMSHUEvent_MetadataJSON", '{}'::jsonb)) as event_payload,
          event."WMSHUEvent_EventAt" as event_at
        from public."WMS_HandlingUnitEvents" event where event."WMSHUEvent_HU_ID" = row."WMSHU_ID"
        order by event."WMSHUEvent_EventAt" desc limit 25
      ) recent_events), '[]'::jsonb)
    ) order by row.ordinal) from page row), '[]'::jsonb),
    'total', (select count(*) from filtered), 'limit', v_limit, 'offset', v_offset,
    'facets', coalesce((select jsonb_agg(value order by value) from (select distinct type_name as value from base where type_name is not null) facet_values), '[]'::jsonb)
  ) into v_result;
  return v_result;
end;
$$;


ALTER FUNCTION "public"."warehouse_edge_handling_units_page"("p_allowed_facility_ids" "uuid"[], "p_allowed_org_ids" "uuid"[], "p_customer_org_id" "uuid", "p_search" "text", "p_facet" "text", "p_include_consumed" boolean, "p_sort" "text", "p_direction" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."warehouse_edge_handling_units_page"("p_allowed_facility_ids" "uuid"[], "p_allowed_org_ids" "uuid"[], "p_customer_org_id" "uuid", "p_search" "text", "p_facet" "text", "p_include_consumed" boolean, "p_sort" "text", "p_direction" "text", "p_limit" integer, "p_offset" integer) IS 'Service-role-only, allowlist-scoped Warehouse object register page capped at 50 rows with page-local contents and events.';



CREATE OR REPLACE FUNCTION "public"."warehouse_edge_internal_actor_context"("p_auth_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'userId', workspace_user."User_ID",
    'companyId', workspace_user."Company_ID",
    'accessStatus', coalesce(workspace_user."User_AccessStatus", 'active'),
    'permissions', coalesce((
      select jsonb_agg(permission_value order by permission_value)
      from (
        select distinct permission."sys_Permission_Value"::text as permission_value
        from public."cmp_Users_Roles" role_link
        join public."sys_UserRole_Permissions" permission_link
          on permission_link."sys_UserRole_ID" = role_link."sys_UserRole_ID"
        join public."sys_Permissions" permission
          on permission."sys_Permission_ID" = permission_link."sys_Permission_ID"
        where role_link."User_ID" = workspace_user."User_ID"
      ) resolved_permissions
    ), '[]'::jsonb),
    'facilityIds', coalesce((
      select jsonb_agg(facility_id order by facility_id)
      from (
        select distinct facility."WMSFacility_ID" as facility_id
        from public."cmp_Users_Offices" office_link
        join public."cmp_Offices" office
          on office."Office_ID" = office_link."Office_ID"
         and office."Company_ID" = workspace_user."Company_ID"
        join public."WMS_Facilities" facility
          on facility."WMSFacility_OrgOfficeID" = office."Office_ID"
         and facility."WMSFacility_IsDeleted" = false
        where office_link."User_ID" = workspace_user."User_ID"
      ) resolved_facilities
    ), '[]'::jsonb)
  )
  from public."cmp_Users" workspace_user
  where workspace_user."Auth_User_ID" = p_auth_user_id
  limit 1;
$$;


ALTER FUNCTION "public"."warehouse_edge_internal_actor_context"("p_auth_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."warehouse_edge_internal_actor_context"("p_auth_user_id" "uuid") IS 'Service-role-only warehouse actor read model. Dexter exception: this changes request authentication performance only and does not add an operational data capability or watchable event.';



CREATE OR REPLACE FUNCTION "public"."warehouse_edge_inventory_mutation"("p_action" "text", "p_payload" "jsonb", "p_actor_user_id" "uuid", "p_allowed_facility_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_action text:=lower(btrim(p_action));
  v_request_id uuid:=nullif(p_payload->>'requestId','')::uuid;
  v_facility_id uuid:=nullif(p_payload->>'facilityId','')::uuid;
  v_group_id uuid:=gen_random_uuid();
  v_now timestamptz:=now();
  v_result jsonb;
  v_existing jsonb;
  v_balance public."WMS_InventoryBalances"%rowtype;
  v_hu public."WMS_HandlingUnits"%rowtype;
  v_target_hu public."WMS_HandlingUnits"%rowtype;
  v_location public."WMS_Locations"%rowtype;
  v_target_location public."WMS_Locations"%rowtype;
  v_quantity numeric;
  v_before numeric;
  v_after numeric;
  v_destination_balance_id uuid;
  v_hu_id uuid;
  v_target_hu_id uuid;
  v_location_id uuid;
  v_target_location_id uuid;
  v_exception_id uuid;
  v_count_plan_id uuid;
  v_adjustment_id uuid;
  v_transaction_id uuid;
  v_code text;
  v_reason text;
  v_status text;
  v_resolution text;
  v_entry jsonb;
  v_affected jsonb:='[]'::jsonb;
  v_source_hu_ids uuid[];
begin
  if p_actor_user_id is null then raise exception 'WMS403: Inventory operations are reserved for the warehouse team.'; end if;
  if v_request_id is null then raise exception 'WMS400: A request identifier is required.'; end if;
  if v_facility_id is null or not (v_facility_id=any(p_allowed_facility_ids)) then raise exception 'WMS403: Choose a warehouse in your workspace.'; end if;

  select "WMSOperation_ResultJSON" into v_existing from public."WMS_InventoryOperations"
  where "WMSOperation_RequestID"=v_request_id;
  if found then return v_existing; end if;

  insert into public."WMS_InventoryOperations" (
    "WMSOperation_RequestID","WMSOperation_FacilityID","WMSOperation_ActionCode","WMSOperation_MovementGroupID",
    "WMSOperation_PayloadJSON","WMSOperation_CreatedAt","WMSOperation_CreatedBy"
  ) values (v_request_id,v_facility_id,v_action,v_group_id,p_payload,v_now,p_actor_user_id);

  if v_action='create_hu' then
    v_target_location_id:=nullif(p_payload->>'locationId','')::uuid;
    if v_target_location_id is not null then
      select * into v_target_location from public."WMS_Locations" where "WMSLocation_ID"=v_target_location_id and "WMSLocation_FacilityID"=v_facility_id and "WMSLocation_IsActive" and not "WMSLocation_IsDeleted";
      if not found then raise exception 'WMS400: Choose an active location in this warehouse.'; end if;
    end if;
    if not exists(select 1 from public."sys_WMSHandlingUnitTypes" where "WMSHUType_Code"=lower(btrim(p_payload->>'typeCode')) and "WMSHUType_IsActive") then raise exception 'WMS400: Choose a valid warehouse object type.'; end if;
    v_hu_id:=gen_random_uuid();
    v_code:=upper(coalesce(nullif(btrim(p_payload->>'code'),''),'HU-'||to_char(v_now,'YYYYMMDD-HH24MISS')||'-'||lpad((floor(random()*9000)+1000)::int::text,4,'0')));
    insert into public."WMS_HandlingUnits" (
      "WMSHU_ID","WMSHU_FacilityID","WMSHU_ParentHU_ID","WMSHU_TypeCode","WMSHU_Code","WMSHU_SSCC","WMSHU_ExternalReference",
      "WMSHU_CustomerOrgID","WMSHU_LocationID","WMSHU_InventoryStatusCode","WMSHU_CustomsStatusCode","WMSHU_LifecycleStatusCode",
      "WMSHU_GrossWeightKG","WMSHU_NetWeightKG","WMSHU_VolumeCBM","WMSHU_CreatedAt","WMSHU_CreatedBy","WMSHU_UpdatedAt","WMSHU_IsDeleted"
    ) values (
      v_hu_id,v_facility_id,nullif(p_payload->>'parentHandlingUnitId','')::uuid,lower(btrim(p_payload->>'typeCode')),v_code,
      nullif(btrim(p_payload->>'sscc'),''),nullif(btrim(p_payload->>'externalReference'),''),nullif(p_payload->>'customerOrgId','')::uuid,
      v_target_location_id,'available',coalesce(nullif(btrim(p_payload->>'customsStatusCode'),''),'free_circulation'),'open',
      nullif(p_payload->>'grossWeightKg','')::numeric,nullif(p_payload->>'netWeightKg','')::numeric,nullif(p_payload->>'volumeCbm','')::numeric,
      v_now,p_actor_user_id,v_now,false
    );
    insert into public."WMS_HandlingUnitEvents" ("WMSHUEvent_ID","WMSHUEvent_HU_ID","WMSHUEvent_EventTypeCode","WMSHUEvent_EventAt","WMSHUEvent_LocationID","WMSHUEvent_Notes","WMSHUEvent_MetadataJSON","WMSHUEvent_CreatedBy")
      values(gen_random_uuid(),v_hu_id,'created',v_now,v_target_location_id,nullif(btrim(p_payload->>'notes'),''),jsonb_build_object('movementGroupId',v_group_id),p_actor_user_id);
    v_result:=jsonb_build_object('requestId',v_request_id,'movementGroupId',v_group_id,'handlingUnitId',v_hu_id,'code',v_code);

  elsif v_action='move_balance' then
    select * into v_balance from public."WMS_InventoryBalances" where "WMSBalance_ID"=(p_payload->>'balanceId')::uuid and "WMSBalance_FacilityID"=v_facility_id for update;
    if not found then raise exception 'WMS404: This stock balance does not exist in the warehouse.'; end if;
    v_target_location_id:=(p_payload->>'targetLocationId')::uuid;
    select * into v_target_location from public."WMS_Locations" where "WMSLocation_ID"=v_target_location_id and "WMSLocation_FacilityID"=v_facility_id and "WMSLocation_IsActive" and not "WMSLocation_IsDeleted";
    if not found or v_target_location."WMSLocation_StatusCode"<>'available' then raise exception 'WMS400: Choose an available destination location.'; end if;
    if v_balance."WMSBalance_IsBonded" and not v_target_location."WMSLocation_AllowsBondedStock" then raise exception 'WMS409: Bonded stock cannot be moved into that location.'; end if;
    v_quantity:=(p_payload->>'quantity')::numeric;
    if v_quantity<=0 or v_quantity>v_balance."WMSBalance_OnHandQuantity" then raise exception 'WMS400: Check the movement quantity.'; end if;
    perform public._warehouse_edge_validate_quantity(v_balance."WMSBalance_ItemID",v_quantity);
    if (v_balance."WMSBalance_ReservedQuantity">0 or v_balance."WMSBalance_AllocatedQuantity">0) and v_quantity<v_balance."WMSBalance_OnHandQuantity" then raise exception 'WMS409: Allocated or reserved stock must be moved as a complete balance.'; end if;
    v_reason:=nullif(btrim(p_payload->>'reasonCode'),'');
    v_location_id:=coalesce(nullif(p_payload->>'actualSourceLocationId','')::uuid,v_balance."WMSBalance_LocationID");
    if v_location_id is distinct from v_balance."WMSBalance_LocationID" and nullif(btrim(p_payload->>'overrideReason'),'') is null then raise exception 'WMS400: Enter a reason for overriding the system source location.'; end if;
    if not exists(select 1 from public."WMS_Locations" where "WMSLocation_ID"=v_location_id and "WMSLocation_FacilityID"=v_facility_id and not "WMSLocation_IsDeleted") then raise exception 'WMS400: Scan a source location in this warehouse.'; end if;
    v_target_hu_id:=nullif(p_payload->>'targetHandlingUnitId','')::uuid;
    if v_target_hu_id is not null then
      select * into v_target_hu from public."WMS_HandlingUnits" where "WMSHU_ID"=v_target_hu_id and "WMSHU_FacilityID"=v_facility_id and not "WMSHU_IsDeleted" and "WMSHU_LifecycleStatusCode" in ('open','sealed') for update;
      if not found or (v_target_hu."WMSHU_CustomerOrgID" is not null and v_target_hu."WMSHU_CustomerOrgID" is distinct from v_balance."WMSBalance_CustomerOrgID") then raise exception 'WMS409: The target warehouse object is not compatible with this stock.'; end if;
    end if;
    v_before:=v_balance."WMSBalance_OnHandQuantity"; v_after:=v_before-v_quantity;
    update public."WMS_InventoryBalances" set
      "WMSBalance_OnHandQuantity"=v_after,
      "WMSBalance_HeldQuantity"=greatest(0,"WMSBalance_HeldQuantity"-case when "WMSBalance_InventoryStatusCode"='available' then 0 else v_quantity end),
      "WMSBalance_AvailableQuantity"=greatest(0,"WMSBalance_AvailableQuantity"-case when "WMSBalance_InventoryStatusCode"='available' then v_quantity else 0 end),
      "WMSBalance_LastMovementAt"=v_now,"WMSBalance_UpdatedAt"=v_now where "WMSBalance_ID"=v_balance."WMSBalance_ID";
    v_destination_balance_id:=gen_random_uuid();
    insert into public."WMS_InventoryBalances" (
      "WMSBalance_ID","WMSBalance_FacilityID","WMSBalance_CustomerOrgID","WMSBalance_ItemID","WMSBalance_LocationID","WMSBalance_LotID","WMSBalance_SerialID","WMSBalance_HU_ID",
      "WMSBalance_InventoryStatusCode","WMSBalance_CustomsStatusCode","WMSBalance_UOMCode","WMSBalance_OnHandQuantity","WMSBalance_ReservedQuantity","WMSBalance_AllocatedQuantity",
      "WMSBalance_HeldQuantity","WMSBalance_AvailableQuantity","WMSBalance_FirstReceiptAt","WMSBalance_LastMovementAt","WMSBalance_IsBonded","WMSBalance_CustomsEntryReference",
      "WMSBalance_StockValue","WMSBalance_CurrencyCode","WMSBalance_MetadataJSON","WMSBalance_CreatedAt","WMSBalance_UpdatedAt"
    ) values (
      v_destination_balance_id,v_facility_id,v_balance."WMSBalance_CustomerOrgID",v_balance."WMSBalance_ItemID",v_target_location_id,v_balance."WMSBalance_LotID",v_balance."WMSBalance_SerialID",v_target_hu_id,
      v_balance."WMSBalance_InventoryStatusCode",v_balance."WMSBalance_CustomsStatusCode",v_balance."WMSBalance_UOMCode",v_quantity,0,0,
      case when v_balance."WMSBalance_InventoryStatusCode"='available' then 0 else v_quantity end,case when v_balance."WMSBalance_InventoryStatusCode"='available' then v_quantity else 0 end,
      v_balance."WMSBalance_FirstReceiptAt",v_now,v_balance."WMSBalance_IsBonded",v_balance."WMSBalance_CustomsEntryReference",v_balance."WMSBalance_StockValue",v_balance."WMSBalance_CurrencyCode",
      jsonb_build_object('sourceBalanceId',v_balance."WMSBalance_ID",'movementGroupId',v_group_id),v_now,v_now
    );
    v_transaction_id:=gen_random_uuid();
    insert into public."WMS_InventoryTransactions" (
      "WMSTransaction_ID","WMSTransaction_FacilityID","WMSTransaction_BalanceID","WMSTransaction_TypeCode","WMSTransaction_ItemID","WMSTransaction_CustomerOrgID",
      "WMSTransaction_FromLocationID","WMSTransaction_ToLocationID","WMSTransaction_LotID","WMSTransaction_SerialID","WMSTransaction_HU_ID","WMSTransaction_Quantity","WMSTransaction_UOMCode",
      "WMSTransaction_BeforeOnHandQuantity","WMSTransaction_AfterOnHandQuantity","WMSTransaction_InventoryStatusCode","WMSTransaction_CustomsStatusCode","WMSTransaction_SourceTable","WMSTransaction_SourceID",
      "WMSTransaction_Reference","WMSTransaction_Notes","WMSTransaction_MetadataJSON","WMSTransaction_MovementGroupID","WMSTransaction_ReasonCode","WMSTransaction_IdempotencyKey","WMSTransaction_CreatedAt","WMSTransaction_CreatedBy"
    ) values (
      v_transaction_id,v_facility_id,v_balance."WMSBalance_ID",case when v_quantity<v_before then 'split' else 'move' end,v_balance."WMSBalance_ItemID",v_balance."WMSBalance_CustomerOrgID",
      v_location_id,v_target_location_id,v_balance."WMSBalance_LotID",v_balance."WMSBalance_SerialID",coalesce(v_target_hu_id,v_balance."WMSBalance_HU_ID"),v_quantity,v_balance."WMSBalance_UOMCode",
      v_before,v_after,v_balance."WMSBalance_InventoryStatusCode",v_balance."WMSBalance_CustomsStatusCode",'WMS_InventoryOperations',v_request_id,
      'MOV-'||left(v_group_id::text,8),nullif(btrim(p_payload->>'notes'),''),jsonb_build_object('destinationBalanceId',v_destination_balance_id,'sourceHandlingUnitId',v_balance."WMSBalance_HU_ID",'targetHandlingUnitId',v_target_hu_id,'overrideReason',nullif(btrim(p_payload->>'overrideReason'),'')),
      v_group_id,coalesce(v_reason,'move'),v_request_id,v_now,p_actor_user_id
    );
    if v_location_id is distinct from v_balance."WMSBalance_LocationID" then
      insert into public."WMS_Exceptions" ("WMSException_ID","WMSException_FacilityID","WMSException_TypeCode","WMSException_StatusCode","WMSException_SeverityCode","WMSException_BalanceID","WMSException_Title","WMSException_Description","WMSException_RaisedAt","WMSException_RaisedBy","WMSException_MetadataJSON","WMSException_ExpectedLocationID","WMSException_ActualLocationID","WMSException_MovementGroupID")
      values(gen_random_uuid(),v_facility_id,'location_override','open','medium',v_destination_balance_id,'Location override recorded',nullif(btrim(p_payload->>'overrideReason'),''),v_now,p_actor_user_id,jsonb_build_object('requestId',v_request_id),v_balance."WMSBalance_LocationID",v_location_id,v_group_id);
    end if;
    perform public._warehouse_edge_sync_hu_contents(v_balance."WMSBalance_HU_ID"); perform public._warehouse_edge_sync_hu_contents(v_target_hu_id);
    v_result:=jsonb_build_object('requestId',v_request_id,'movementGroupId',v_group_id,'transactionId',v_transaction_id,'balanceId',v_destination_balance_id);

  elsif v_action='move_hu' then
    select * into v_hu from public."WMS_HandlingUnits" where "WMSHU_ID"=(p_payload->>'handlingUnitId')::uuid and "WMSHU_FacilityID"=v_facility_id and not "WMSHU_IsDeleted" and "WMSHU_LifecycleStatusCode" in ('open','sealed') for update;
    if not found then raise exception 'WMS404: This warehouse object is not available.'; end if;
    v_target_location_id:=(p_payload->>'targetLocationId')::uuid;
    select * into v_target_location from public."WMS_Locations" where "WMSLocation_ID"=v_target_location_id and "WMSLocation_FacilityID"=v_facility_id and "WMSLocation_IsActive" and not "WMSLocation_IsDeleted";
    if not found or v_target_location."WMSLocation_StatusCode"<>'available' then raise exception 'WMS400: Choose an available destination location.'; end if;
    v_location_id:=coalesce(nullif(p_payload->>'actualSourceLocationId','')::uuid,v_hu."WMSHU_LocationID");
    if v_location_id is distinct from v_hu."WMSHU_LocationID" and nullif(btrim(p_payload->>'overrideReason'),'') is null then raise exception 'WMS400: Enter a reason for overriding the system source location.'; end if;
    for v_balance in select * from public."WMS_InventoryBalances" where "WMSBalance_HU_ID"=v_hu."WMSHU_ID" and "WMSBalance_OnHandQuantity">0 for update loop
      if v_balance."WMSBalance_IsBonded" and not v_target_location."WMSLocation_AllowsBondedStock" then raise exception 'WMS409: Bonded stock cannot be moved into that location.'; end if;
      update public."WMS_InventoryBalances" set "WMSBalance_LocationID"=v_target_location_id,"WMSBalance_LastMovementAt"=v_now,"WMSBalance_UpdatedAt"=v_now where "WMSBalance_ID"=v_balance."WMSBalance_ID";
      insert into public."WMS_InventoryTransactions" ("WMSTransaction_ID","WMSTransaction_FacilityID","WMSTransaction_BalanceID","WMSTransaction_TypeCode","WMSTransaction_ItemID","WMSTransaction_CustomerOrgID","WMSTransaction_FromLocationID","WMSTransaction_ToLocationID","WMSTransaction_LotID","WMSTransaction_SerialID","WMSTransaction_HU_ID","WMSTransaction_Quantity","WMSTransaction_UOMCode","WMSTransaction_BeforeOnHandQuantity","WMSTransaction_AfterOnHandQuantity","WMSTransaction_InventoryStatusCode","WMSTransaction_CustomsStatusCode","WMSTransaction_SourceTable","WMSTransaction_SourceID","WMSTransaction_Reference","WMSTransaction_Notes","WMSTransaction_MetadataJSON","WMSTransaction_MovementGroupID","WMSTransaction_ReasonCode","WMSTransaction_IdempotencyKey","WMSTransaction_CreatedAt","WMSTransaction_CreatedBy")
      values(gen_random_uuid(),v_facility_id,v_balance."WMSBalance_ID",'move',v_balance."WMSBalance_ItemID",v_balance."WMSBalance_CustomerOrgID",v_location_id,v_target_location_id,v_balance."WMSBalance_LotID",v_balance."WMSBalance_SerialID",v_hu."WMSHU_ID",v_balance."WMSBalance_OnHandQuantity",v_balance."WMSBalance_UOMCode",v_balance."WMSBalance_OnHandQuantity",v_balance."WMSBalance_OnHandQuantity",v_balance."WMSBalance_InventoryStatusCode",v_balance."WMSBalance_CustomsStatusCode",'WMS_InventoryOperations',v_request_id,'MOV-'||left(v_group_id::text,8),nullif(btrim(p_payload->>'notes'),''),jsonb_build_object('systemSourceLocationId',v_hu."WMSHU_LocationID",'overrideReason',nullif(btrim(p_payload->>'overrideReason'),'')),v_group_id,coalesce(nullif(btrim(p_payload->>'reasonCode'),''),'move_hu'),v_request_id,v_now,p_actor_user_id);
    end loop;
    update public."WMS_HandlingUnits" set "WMSHU_LocationID"=v_target_location_id,"WMSHU_UpdatedAt"=v_now,"WMSHU_Version"="WMSHU_Version"+1 where "WMSHU_ID"=v_hu."WMSHU_ID";
    insert into public."WMS_HandlingUnitEvents" ("WMSHUEvent_ID","WMSHUEvent_HU_ID","WMSHUEvent_EventTypeCode","WMSHUEvent_EventAt","WMSHUEvent_LocationID","WMSHUEvent_Notes","WMSHUEvent_MetadataJSON","WMSHUEvent_CreatedBy") values(gen_random_uuid(),v_hu."WMSHU_ID",'moved',v_now,v_target_location_id,nullif(btrim(p_payload->>'notes'),''),jsonb_build_object('fromLocationId',v_hu."WMSHU_LocationID",'movementGroupId',v_group_id,'overrideReason',nullif(btrim(p_payload->>'overrideReason'),'')),p_actor_user_id);
    if v_location_id is distinct from v_hu."WMSHU_LocationID" then
      insert into public."WMS_Exceptions" ("WMSException_ID","WMSException_FacilityID","WMSException_TypeCode","WMSException_StatusCode","WMSException_SeverityCode","WMSException_Title","WMSException_Description","WMSException_RaisedAt","WMSException_RaisedBy","WMSException_MetadataJSON","WMSException_ExpectedLocationID","WMSException_ActualLocationID","WMSException_MovementGroupID")
      values(gen_random_uuid(),v_facility_id,'location_override','open','medium','Warehouse object location override recorded',nullif(btrim(p_payload->>'overrideReason'),''),v_now,p_actor_user_id,jsonb_build_object('requestId',v_request_id,'handlingUnitId',v_hu."WMSHU_ID"),v_hu."WMSHU_LocationID",v_location_id,v_group_id);
    end if;
    v_result:=jsonb_build_object('requestId',v_request_id,'movementGroupId',v_group_id,'handlingUnitId',v_hu."WMSHU_ID");

  elsif v_action='consolidate' then
    select array_agg(value::uuid) into v_source_hu_ids from jsonb_array_elements_text(p_payload->'sourceHandlingUnitIds');
    v_target_hu_id:=(p_payload->>'targetHandlingUnitId')::uuid;
    select * into v_target_hu from public."WMS_HandlingUnits" where "WMSHU_ID"=v_target_hu_id and "WMSHU_FacilityID"=v_facility_id and not "WMSHU_IsDeleted" and "WMSHU_LifecycleStatusCode"='open' for update;
    if not found or coalesce(array_length(v_source_hu_ids,1),0)=0 then raise exception 'WMS400: Choose a target and at least one source warehouse object.'; end if;
    if v_target_hu_id=any(v_source_hu_ids) then raise exception 'WMS400: The target pallet cannot also be a source pallet.'; end if;
    for v_hu in select * from public."WMS_HandlingUnits" where "WMSHU_ID"=any(v_source_hu_ids) order by "WMSHU_ID" for update loop
      if v_hu."WMSHU_FacilityID"<>v_facility_id or v_hu."WMSHU_LifecycleStatusCode"<>'open' or v_hu."WMSHU_CustomerOrgID" is distinct from v_target_hu."WMSHU_CustomerOrgID" then raise exception 'WMS409: Source pallets must be open and belong to the same warehouse and customer as the target.'; end if;
      for v_balance in select * from public."WMS_InventoryBalances" where "WMSBalance_HU_ID"=v_hu."WMSHU_ID" and "WMSBalance_OnHandQuantity">0 for update loop
        update public."WMS_InventoryBalances" set "WMSBalance_HU_ID"=v_target_hu_id,"WMSBalance_LocationID"=v_target_hu."WMSHU_LocationID","WMSBalance_LastMovementAt"=v_now,"WMSBalance_UpdatedAt"=v_now where "WMSBalance_ID"=v_balance."WMSBalance_ID";
