          update public."WMS_InventoryBalances" set "WMSBalance_LocationID"=v_target_location_id,"WMSBalance_InventoryStatusCode"=v_entry->>'previousStatusCode',"WMSBalance_HeldQuantity"=case when v_entry->>'previousStatusCode'='available' then 0 else "WMSBalance_OnHandQuantity" end,"WMSBalance_AvailableQuantity"=case when v_entry->>'previousStatusCode'='available' then greatest(0,"WMSBalance_OnHandQuantity"-"WMSBalance_ReservedQuantity"-"WMSBalance_AllocatedQuantity") else 0 end,"WMSBalance_LastMovementAt"=v_now,"WMSBalance_UpdatedAt"=v_now where "WMSBalance_ID"=v_balance."WMSBalance_ID";
          insert into public."WMS_InventoryTransactions" ("WMSTransaction_ID","WMSTransaction_FacilityID","WMSTransaction_BalanceID","WMSTransaction_TypeCode","WMSTransaction_ItemID","WMSTransaction_CustomerOrgID","WMSTransaction_FromLocationID","WMSTransaction_ToLocationID","WMSTransaction_LotID","WMSTransaction_SerialID","WMSTransaction_HU_ID","WMSTransaction_Quantity","WMSTransaction_UOMCode","WMSTransaction_BeforeOnHandQuantity","WMSTransaction_AfterOnHandQuantity","WMSTransaction_InventoryStatusCode","WMSTransaction_CustomsStatusCode","WMSTransaction_SourceTable","WMSTransaction_SourceID","WMSTransaction_Reference","WMSTransaction_Notes","WMSTransaction_MetadataJSON","WMSTransaction_MovementGroupID","WMSTransaction_ReasonCode","WMSTransaction_IdempotencyKey","WMSTransaction_CreatedAt","WMSTransaction_CreatedBy") values(gen_random_uuid(),v_facility_id,v_balance."WMSBalance_ID",'move',v_balance."WMSBalance_ItemID",v_balance."WMSBalance_CustomerOrgID",v_balance."WMSBalance_LocationID",v_target_location_id,v_balance."WMSBalance_LotID",v_balance."WMSBalance_SerialID",v_balance."WMSBalance_HU_ID",v_balance."WMSBalance_OnHandQuantity",v_balance."WMSBalance_UOMCode",v_balance."WMSBalance_OnHandQuantity",v_balance."WMSBalance_OnHandQuantity",v_entry->>'previousStatusCode',v_balance."WMSBalance_CustomsStatusCode",'WMS_Exceptions',v_exception_id,'RES-'||left(v_group_id::text,8),nullif(btrim(p_payload->>'notes'),''),jsonb_build_object('resolution',v_resolution),v_group_id,'location_exception_resolved',v_request_id,v_now,p_actor_user_id);
          update public."WMS_InventoryHolds" set "WMSHold_StatusCode"='released',"WMSHold_ReleasedAt"=v_now,"WMSHold_ReleasedBy"=p_actor_user_id,"WMSHold_ReleaseReason"=nullif(btrim(p_payload->>'notes'),'') where "WMSHold_BalanceID"=v_balance."WMSBalance_ID" and "WMSHold_StatusCode"='open';
          if v_balance."WMSBalance_HU_ID" is not null then update public."WMS_HandlingUnits" set "WMSHU_LocationID"=v_target_location_id,"WMSHU_InventoryStatusCode"=v_entry->>'previousStatusCode',"WMSHU_LifecycleStatusCode"='open',"WMSHU_UpdatedAt"=v_now,"WMSHU_Version"="WMSHU_Version"+1 where "WMSHU_ID"=v_balance."WMSBalance_HU_ID"; end if;
        end if;
      end loop;
      update public."WMS_Exceptions" set "WMSException_StatusCode"='resolved',"WMSException_ActualLocationID"=v_target_location_id,"WMSException_ResolvedAt"=v_now,"WMSException_ResolvedBy"=p_actor_user_id,"WMSException_MetadataJSON"="WMSException_MetadataJSON"||jsonb_build_object('resolution',v_resolution,'resolutionNotes',nullif(btrim(p_payload->>'notes'),''),'resolutionMovementGroupId',v_group_id) where "WMSException_ID"=v_exception_id;
      v_result:=jsonb_build_object('requestId',v_request_id,'movementGroupId',v_group_id,'exceptionId',v_exception_id,'status','resolved');
    elsif v_resolution='request_loss' then
      v_adjustment_id:=gen_random_uuid();
      insert into public."WMS_Adjustments" ("WMSAdjust_ID","WMSAdjust_FacilityID","WMSAdjust_AdjustmentNumber","WMSAdjust_StatusCode","WMSAdjust_ReasonCode","WMSAdjust_RequiresApproval","WMSAdjust_Notes","WMSAdjust_CreatedAt","WMSAdjust_CreatedBy") values(v_adjustment_id,v_facility_id,'ADJ-'||to_char(v_now,'YYYYMMDD-HH24MISS')||'-'||lpad((floor(random()*9000)+1000)::int::text,4,'0'),'draft','confirmed_loss',true,nullif(btrim(p_payload->>'notes'),''),v_now,p_actor_user_id);
      for v_entry in select value from jsonb_array_elements(v_existing->'affected') loop
        select * into v_balance from public."WMS_InventoryBalances" where "WMSBalance_ID"=(v_entry->>'balanceId')::uuid for update;
        if found and v_balance."WMSBalance_OnHandQuantity">0 then insert into public."WMS_AdjustmentLines" ("WMSAdjustLine_ID","WMSAdjustLine_AdjustmentID","WMSAdjustLine_BalanceID","WMSAdjustLine_ItemID","WMSAdjustLine_LineNo","WMSAdjustLine_PreviousQuantity","WMSAdjustLine_NewQuantity","WMSAdjustLine_AdjustmentQuantity","WMSAdjustLine_UOMCode","WMSAdjustLine_Notes") values(gen_random_uuid(),v_adjustment_id,v_balance."WMSBalance_ID",v_balance."WMSBalance_ItemID",(select count(*)+1 from public."WMS_AdjustmentLines" where "WMSAdjustLine_AdjustmentID"=v_adjustment_id),v_balance."WMSBalance_OnHandQuantity",0,-v_balance."WMSBalance_OnHandQuantity",v_balance."WMSBalance_UOMCode",nullif(btrim(p_payload->>'notes'),'')); end if;
      end loop;
      update public."WMS_Exceptions" set "WMSException_StatusCode"='pending_approval',"WMSException_MetadataJSON"="WMSException_MetadataJSON"||jsonb_build_object('resolution','request_loss','adjustmentId',v_adjustment_id,'lossRequestedBy',p_actor_user_id,'lossRequestedAt',v_now,'resolutionNotes',nullif(btrim(p_payload->>'notes'),'')) where "WMSException_ID"=v_exception_id;
      v_result:=jsonb_build_object('requestId',v_request_id,'movementGroupId',v_group_id,'exceptionId',v_exception_id,'adjustmentId',v_adjustment_id,'status','pending_approval');
    elsif v_resolution='approve_loss' then
      v_adjustment_id:=(v_existing->>'adjustmentId')::uuid;
      if v_adjustment_id is null or (v_existing->>'lossRequestedBy')::uuid=p_actor_user_id then raise exception 'WMS409: A different warehouse user must approve the stock loss.'; end if;
      for v_entry in select to_jsonb(line) from public."WMS_AdjustmentLines" line where line."WMSAdjustLine_AdjustmentID"=v_adjustment_id order by line."WMSAdjustLine_LineNo" for update loop
        select * into v_balance from public."WMS_InventoryBalances" where "WMSBalance_ID"=(v_entry->>'WMSAdjustLine_BalanceID')::uuid for update;
        if found and v_balance."WMSBalance_OnHandQuantity">0 then
          v_before:=v_balance."WMSBalance_OnHandQuantity"; v_transaction_id:=gen_random_uuid();
          update public."WMS_InventoryBalances" set "WMSBalance_OnHandQuantity"=0,"WMSBalance_ReservedQuantity"=0,"WMSBalance_AllocatedQuantity"=0,"WMSBalance_HeldQuantity"=0,"WMSBalance_AvailableQuantity"=0,"WMSBalance_LastMovementAt"=v_now,"WMSBalance_UpdatedAt"=v_now where "WMSBalance_ID"=v_balance."WMSBalance_ID";
          insert into public."WMS_InventoryTransactions" ("WMSTransaction_ID","WMSTransaction_FacilityID","WMSTransaction_BalanceID","WMSTransaction_TypeCode","WMSTransaction_ItemID","WMSTransaction_CustomerOrgID","WMSTransaction_FromLocationID","WMSTransaction_LotID","WMSTransaction_SerialID","WMSTransaction_HU_ID","WMSTransaction_Quantity","WMSTransaction_UOMCode","WMSTransaction_BeforeOnHandQuantity","WMSTransaction_AfterOnHandQuantity","WMSTransaction_InventoryStatusCode","WMSTransaction_CustomsStatusCode","WMSTransaction_SourceTable","WMSTransaction_SourceID","WMSTransaction_Reference","WMSTransaction_Notes","WMSTransaction_MetadataJSON","WMSTransaction_MovementGroupID","WMSTransaction_ReasonCode","WMSTransaction_IdempotencyKey","WMSTransaction_CreatedAt","WMSTransaction_CreatedBy") values(v_transaction_id,v_facility_id,v_balance."WMSBalance_ID",'adjustment_out',v_balance."WMSBalance_ItemID",v_balance."WMSBalance_CustomerOrgID",v_balance."WMSBalance_LocationID",v_balance."WMSBalance_LotID",v_balance."WMSBalance_SerialID",v_balance."WMSBalance_HU_ID",v_before,v_balance."WMSBalance_UOMCode",v_before,0,'unlocated',v_balance."WMSBalance_CustomsStatusCode",'WMS_Adjustments',v_adjustment_id,'LOSS-'||left(v_group_id::text,8),nullif(btrim(p_payload->>'notes'),''),jsonb_build_object('exceptionId',v_exception_id,'approvedBy',p_actor_user_id),v_group_id,'confirmed_loss',v_request_id,v_now,p_actor_user_id);
          update public."WMS_AdjustmentLines" set "WMSAdjustLine_InventoryTransactionID"=v_transaction_id where "WMSAdjustLine_ID"=(v_entry->>'WMSAdjustLine_ID')::uuid;
        end if;
      end loop;
      update public."WMS_Adjustments" set "WMSAdjust_StatusCode"='posted',"WMSAdjust_PostedAt"=v_now,"WMSAdjust_PostedBy"=p_actor_user_id where "WMSAdjust_ID"=v_adjustment_id and "WMSAdjust_StatusCode"='draft';
      update public."WMS_Exceptions" set "WMSException_StatusCode"='resolved',"WMSException_ResolvedAt"=v_now,"WMSException_ResolvedBy"=p_actor_user_id,"WMSException_MetadataJSON"="WMSException_MetadataJSON"||jsonb_build_object('resolution','confirmed_loss','approvedBy',p_actor_user_id,'approvedAt',v_now,'resolutionMovementGroupId',v_group_id) where "WMSException_ID"=v_exception_id;
      v_result:=jsonb_build_object('requestId',v_request_id,'movementGroupId',v_group_id,'exceptionId',v_exception_id,'adjustmentId',v_adjustment_id,'status','resolved');
    else raise exception 'WMS400: Choose found, data error, request loss, or approve loss.'; end if;
  else
    raise exception 'WMS400: Unsupported inventory action.';
  end if;

  update public."WMS_InventoryOperations" set "WMSOperation_ResultJSON"=v_result where "WMSOperation_RequestID"=v_request_id;
  return v_result;
exception
  when others then
    if sqlerrm like 'WMS%' then raise; end if;
    raise exception 'WMS500: %',sqlerrm;
end; $$;


ALTER FUNCTION "public"."warehouse_edge_inventory_mutation"("p_action" "text", "p_payload" "jsonb", "p_actor_user_id" "uuid", "p_allowed_facility_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."warehouse_edge_inventory_page"("p_allowed_facility_ids" "uuid"[], "p_allowed_org_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_mode" "text" DEFAULT 'stock'::"text", "p_item_id" "uuid" DEFAULT NULL::"uuid", "p_search" "text" DEFAULT NULL::"text", "p_facet" "text" DEFAULT NULL::"text", "p_include_zero" boolean DEFAULT false, "p_open_only" boolean DEFAULT true, "p_status_code" "text" DEFAULT NULL::"text", "p_sort" "text" DEFAULT NULL::"text", "p_direction" "text" DEFAULT 'desc'::"text", "p_limit" integer DEFAULT 20, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_limit integer := greatest(1, least(coalesce(p_limit, 20), 50));
  v_offset integer := greatest(0, coalesce(p_offset, 0));
  v_mode text := case when p_mode in ('stock', 'movements', 'exceptions') then p_mode else 'stock' end;
  v_search text := lower(nullif(btrim(p_search), ''));
  v_facet text := nullif(btrim(p_facet), '');
  v_direction text := case when lower(p_direction) = 'asc' then 'asc' else 'desc' end;
  v_result jsonb;
begin
  if coalesce(cardinality(p_allowed_facility_ids), 0) = 0 then
    return jsonb_build_object('rows', '[]'::jsonb, 'total', 0, 'limit', v_limit, 'offset', v_offset, 'facets', '[]'::jsonb);
  end if;

  if v_mode = 'stock' then
    with base as materialized (
      select
        balance.*,
        facility."WMSFacility_Code" as facility_code,
        facility."WMSFacility_Name" as facility_name,
        organisation."Org_Name" as customer_name,
        item."WMSItem_SKU" as sku,
        item."WMSItem_Description" as item_description,
        location."WMSLocation_Code" as location_code,
        handling_unit."WMSHU_Code" as handling_unit_code,
        handling_unit."WMSHU_TypeCode" as handling_unit_type_code,
        lot."WMSLot_LotNumber" as lot_number,
        lot."WMSLot_BatchNumber" as batch_number,
        lot."WMSLot_ManufactureDate" as manufacture_date,
        lot."WMSLot_ExpiryDate" as expiry_date,
        coalesce(inventory_status."WMSInventoryStatus_Name", balance."WMSBalance_InventoryStatusCode") as inventory_status_name
      from public."WMS_InventoryBalances" balance
      join public."WMS_Facilities" facility on facility."WMSFacility_ID" = balance."WMSBalance_FacilityID"
      join public."WMS_Items" item on item."WMSItem_ID" = balance."WMSBalance_ItemID"
      left join public."Org_Master" organisation on organisation."Org_id" = balance."WMSBalance_CustomerOrgID"
      left join public."WMS_Locations" location on location."WMSLocation_ID" = balance."WMSBalance_LocationID"
      left join public."WMS_HandlingUnits" handling_unit on handling_unit."WMSHU_ID" = balance."WMSBalance_HU_ID"
      left join public."WMS_InventoryLots" lot on lot."WMSLot_ID" = balance."WMSBalance_LotID"
      left join public."sys_WMSInventoryStatuses" inventory_status on inventory_status."WMSInventoryStatus_Code" = balance."WMSBalance_InventoryStatusCode"
      where balance."WMSBalance_FacilityID" = any(p_allowed_facility_ids)
        and (p_allowed_org_ids is null or balance."WMSBalance_CustomerOrgID" = any(p_allowed_org_ids))
        and (p_item_id is null or balance."WMSBalance_ItemID" = p_item_id)
        and (p_include_zero or balance."WMSBalance_OnHandQuantity" <> 0)
        and (v_search is null or strpos(lower(concat_ws(' ',
          item."WMSItem_SKU", item."WMSItem_Description", organisation."Org_Name", facility."WMSFacility_Name",
          balance."WMSBalance_InventoryStatusCode", balance."WMSBalance_CustomsStatusCode", location."WMSLocation_Code",
          handling_unit."WMSHU_Code", lot."WMSLot_LotNumber", lot."WMSLot_BatchNumber"
        )), v_search) > 0)
    ), filtered as materialized (
      select * from base where v_facet is null or inventory_status_name = v_facet
    ), ranked as (
      select *, row_number() over (
        order by
          case when v_direction = 'asc' then case p_sort
            when 'stock-item' then lower(sku) when 'stock-object' then lower(handling_unit_code)
            when 'stock-location' then lower(location_code) when 'stock-lot' then lower(coalesce(batch_number, lot_number))
            when 'stock-customer' then lower(customer_name) when 'stock-status' then lower(inventory_status_name)
          end end asc nulls last,
          case when v_direction = 'desc' then case p_sort
            when 'stock-item' then lower(sku) when 'stock-object' then lower(handling_unit_code)
            when 'stock-location' then lower(location_code) when 'stock-lot' then lower(coalesce(batch_number, lot_number))
            when 'stock-customer' then lower(customer_name) when 'stock-status' then lower(inventory_status_name)
          end end desc nulls last,
          case when v_direction = 'asc' and p_sort = 'stock-onHand' then "WMSBalance_OnHandQuantity" end asc nulls last,
          case when v_direction = 'desc' and p_sort = 'stock-onHand' then "WMSBalance_OnHandQuantity" end desc nulls last,
          case when v_direction = 'asc' and p_sort = 'stock-available' then "WMSBalance_AvailableQuantity" end asc nulls last,
          case when v_direction = 'desc' and p_sort = 'stock-available' then "WMSBalance_AvailableQuantity" end desc nulls last,
          case when p_sort is null and v_direction = 'asc' then "WMSBalance_UpdatedAt" end asc,
          case when p_sort is null and v_direction = 'desc' then "WMSBalance_UpdatedAt" end desc,
          "WMSBalance_ID"
      ) as ordinal
      from filtered
    ), page as (
      select * from ranked where ordinal > v_offset and ordinal <= v_offset + v_limit
    )
    select jsonb_build_object(
      'rows', coalesce((select jsonb_agg(jsonb_build_object(
        'id', row."WMSBalance_ID", 'facilityId', row."WMSBalance_FacilityID", 'facilityCode', row.facility_code,
        'facilityName', row.facility_name, 'customerOrgId', row."WMSBalance_CustomerOrgID", 'customerName', row.customer_name,
        'itemId', row."WMSBalance_ItemID", 'sku', row.sku, 'itemDescription', row.item_description,
        'locationId', row."WMSBalance_LocationID", 'locationCode', row.location_code,
        'handlingUnitId', row."WMSBalance_HU_ID", 'handlingUnitCode', row.handling_unit_code,
        'handlingUnitTypeCode', row.handling_unit_type_code, 'lotId', row."WMSBalance_LotID",
        'lotNumber', row.lot_number, 'batchNumber', row.batch_number, 'manufactureDate', row.manufacture_date,
        'expiryDate', row.expiry_date, 'inventoryStatusCode', row."WMSBalance_InventoryStatusCode",
        'inventoryStatusName', row.inventory_status_name, 'customsStatusCode', row."WMSBalance_CustomsStatusCode",
        'uomCode', row."WMSBalance_UOMCode", 'onHandQuantity', row."WMSBalance_OnHandQuantity",
        'reservedQuantity', row."WMSBalance_ReservedQuantity", 'allocatedQuantity', row."WMSBalance_AllocatedQuantity",
        'heldQuantity', row."WMSBalance_HeldQuantity", 'availableQuantity', row."WMSBalance_AvailableQuantity",
        'isBonded', row."WMSBalance_IsBonded", 'firstReceiptAt', row."WMSBalance_FirstReceiptAt",
        'lastMovementAt', row."WMSBalance_LastMovementAt", 'updatedAt', row."WMSBalance_UpdatedAt"
      ) order by row.ordinal) from page row), '[]'::jsonb),
      'total', (select count(*) from filtered), 'limit', v_limit, 'offset', v_offset,
      'facets', coalesce((select jsonb_agg(value order by value) from (select distinct inventory_status_name as value from base where inventory_status_name is not null) facet_values), '[]'::jsonb)
    ) into v_result;

  elsif v_mode = 'movements' then
    with base as materialized (
      select
        transaction.*,
        facility."WMSFacility_Name" as facility_name,
        item."WMSItem_SKU" as sku,
        item."WMSItem_Description" as item_description,
        from_location."WMSLocation_Code" as from_location_code,
        to_location."WMSLocation_Code" as to_location_code,
        lot."WMSLot_LotNumber" as lot_number,
        lot."WMSLot_BatchNumber" as batch_number,
        handling_unit."WMSHU_Code" as handling_unit_code
      from public."WMS_InventoryTransactions" transaction
      join public."WMS_Facilities" facility on facility."WMSFacility_ID" = transaction."WMSTransaction_FacilityID"
      join public."WMS_Items" item on item."WMSItem_ID" = transaction."WMSTransaction_ItemID"
      left join public."WMS_Locations" from_location on from_location."WMSLocation_ID" = transaction."WMSTransaction_FromLocationID"
      left join public."WMS_Locations" to_location on to_location."WMSLocation_ID" = transaction."WMSTransaction_ToLocationID"
      left join public."WMS_InventoryLots" lot on lot."WMSLot_ID" = transaction."WMSTransaction_LotID"
      left join public."WMS_HandlingUnits" handling_unit on handling_unit."WMSHU_ID" = transaction."WMSTransaction_HU_ID"
      where transaction."WMSTransaction_FacilityID" = any(p_allowed_facility_ids)
        and (p_allowed_org_ids is null or transaction."WMSTransaction_CustomerOrgID" = any(p_allowed_org_ids))
        and (p_item_id is null or transaction."WMSTransaction_ItemID" = p_item_id)
        and (v_search is null or strpos(lower(concat_ws(' ', item."WMSItem_SKU", item."WMSItem_Description",
          facility."WMSFacility_Name", transaction."WMSTransaction_Reference", transaction."WMSTransaction_Notes",
          from_location."WMSLocation_Code", to_location."WMSLocation_Code", lot."WMSLot_LotNumber",
          lot."WMSLot_BatchNumber", handling_unit."WMSHU_Code", transaction."WMSTransaction_ReasonCode"
        )), v_search) > 0)
    ), filtered as materialized (
      select * from base where v_facet is null or "WMSTransaction_TypeCode" = v_facet
    ), ranked as (
      select *, row_number() over (
        order by
          case when v_direction = 'asc' then case p_sort
            when 'movement-reference' then lower("WMSTransaction_Reference") when 'movement-item' then lower(sku)
            when 'movement-movement' then lower("WMSTransaction_TypeCode") when 'movement-reason' then lower("WMSTransaction_ReasonCode")
          end end asc nulls last,
          case when v_direction = 'desc' then case p_sort
            when 'movement-reference' then lower("WMSTransaction_Reference") when 'movement-item' then lower(sku)
            when 'movement-movement' then lower("WMSTransaction_TypeCode") when 'movement-reason' then lower("WMSTransaction_ReasonCode")
          end end desc nulls last,
          case when v_direction = 'asc' and p_sort = 'movement-quantity' then "WMSTransaction_Quantity" end asc nulls last,
          case when v_direction = 'desc' and p_sort = 'movement-quantity' then "WMSTransaction_Quantity" end desc nulls last,
          case when (p_sort is null or p_sort = 'movement-posted') and v_direction = 'asc' then "WMSTransaction_CreatedAt" end asc,
          case when (p_sort is null or p_sort = 'movement-posted') and v_direction = 'desc' then "WMSTransaction_CreatedAt" end desc,
          "WMSTransaction_ID"
      ) as ordinal
      from filtered
    ), page as (
      select * from ranked where ordinal > v_offset and ordinal <= v_offset + v_limit
    )
    select jsonb_build_object(
      'rows', coalesce((select jsonb_agg(jsonb_build_object(
        'id', row."WMSTransaction_ID", 'facilityId', row."WMSTransaction_FacilityID", 'facilityName', row.facility_name,
        'itemId', row."WMSTransaction_ItemID", 'sku', row.sku, 'itemDescription', row.item_description,
        'typeCode', row."WMSTransaction_TypeCode", 'typeName', row."WMSTransaction_TypeCode",
        'quantity', row."WMSTransaction_Quantity", 'uomCode', row."WMSTransaction_UOMCode",
        'fromLocationCode', row.from_location_code, 'toLocationCode', row.to_location_code,
        'lotNumber', row.lot_number, 'batchNumber', row.batch_number, 'reference', row."WMSTransaction_Reference",
        'notes', row."WMSTransaction_Notes", 'handlingUnitId', row."WMSTransaction_HU_ID",
        'handlingUnitCode', row.handling_unit_code, 'movementGroupId', row."WMSTransaction_MovementGroupID",
        'reasonCode', row."WMSTransaction_ReasonCode", 'metadata', coalesce(row."WMSTransaction_MetadataJSON", '{}'::jsonb),
        'createdAt', row."WMSTransaction_CreatedAt"
      ) order by row.ordinal) from page row), '[]'::jsonb),
      'total', (select count(*) from filtered), 'limit', v_limit, 'offset', v_offset,
      'facets', coalesce((select jsonb_agg(value order by value) from (select distinct "WMSTransaction_TypeCode" as value from base where "WMSTransaction_TypeCode" is not null) facet_values), '[]'::jsonb)
    ) into v_result;

  else
    with base as materialized (
      select
        exception.*,
        expected_location."WMSLocation_Code" as expected_location_code,
        actual_location."WMSLocation_Code" as actual_location_code
      from public."WMS_Exceptions" exception
      left join public."WMS_Locations" expected_location on expected_location."WMSLocation_ID" = exception."WMSException_ExpectedLocationID"
      left join public."WMS_Locations" actual_location on actual_location."WMSLocation_ID" = exception."WMSException_ActualLocationID"
      where exception."WMSException_FacilityID" = any(p_allowed_facility_ids)
        and (not p_open_only or exception."WMSException_StatusCode" <> 'resolved')
        and (p_status_code is null or exception."WMSException_StatusCode" = p_status_code)
        and (v_search is null or strpos(lower(concat_ws(' ', exception."WMSException_Title",
          exception."WMSException_Description", exception."WMSException_TypeCode", exception."WMSException_SeverityCode",
          expected_location."WMSLocation_Code", actual_location."WMSLocation_Code"
        )), v_search) > 0)
    ), filtered as materialized (
      select * from base where v_facet is null or "WMSException_SeverityCode" = v_facet
    ), ranked as (
      select *, row_number() over (
        order by
          case when v_direction = 'asc' then case p_sort
            when 'exception-exception' then lower("WMSException_Title") when 'exception-severity' then lower("WMSException_SeverityCode")
            when 'exception-expected' then lower(expected_location_code) when 'exception-status' then lower("WMSException_StatusCode")
          end end asc nulls last,
          case when v_direction = 'desc' then case p_sort
            when 'exception-exception' then lower("WMSException_Title") when 'exception-severity' then lower("WMSException_SeverityCode")
            when 'exception-expected' then lower(expected_location_code) when 'exception-status' then lower("WMSException_StatusCode")
          end end desc nulls last,
          case when (p_sort is null or p_sort = 'exception-raised') and v_direction = 'asc' then "WMSException_RaisedAt" end asc,
          case when (p_sort is null or p_sort = 'exception-raised') and v_direction = 'desc' then "WMSException_RaisedAt" end desc,
          "WMSException_ID"
      ) as ordinal
      from filtered
    ), page as (
      select * from ranked where ordinal > v_offset and ordinal <= v_offset + v_limit
    )
    select jsonb_build_object(
      'rows', coalesce((select jsonb_agg(jsonb_build_object(
        'id', row."WMSException_ID", 'facilityId', row."WMSException_FacilityID", 'typeCode', row."WMSException_TypeCode",
        'statusCode', row."WMSException_StatusCode", 'severityCode', row."WMSException_SeverityCode",
        'balanceId', row."WMSException_BalanceID", 'title', row."WMSException_Title",
        'description', row."WMSException_Description", 'expectedLocationId', row."WMSException_ExpectedLocationID",
        'expectedLocationCode', row.expected_location_code, 'actualLocationId', row."WMSException_ActualLocationID",
        'actualLocationCode', row.actual_location_code, 'movementGroupId', row."WMSException_MovementGroupID",
        'raisedAt', row."WMSException_RaisedAt", 'resolvedAt', row."WMSException_ResolvedAt",
        'metadata', coalesce(row."WMSException_MetadataJSON", '{}'::jsonb)
      ) order by row.ordinal) from page row), '[]'::jsonb),
      'total', (select count(*) from filtered), 'limit', v_limit, 'offset', v_offset,
      'facets', coalesce((select jsonb_agg(value order by value) from (select distinct "WMSException_SeverityCode" as value from base where "WMSException_SeverityCode" is not null) facet_values), '[]'::jsonb)
    ) into v_result;
  end if;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."warehouse_edge_inventory_page"("p_allowed_facility_ids" "uuid"[], "p_allowed_org_ids" "uuid"[], "p_mode" "text", "p_item_id" "uuid", "p_search" "text", "p_facet" "text", "p_include_zero" boolean, "p_open_only" boolean, "p_status_code" "text", "p_sort" "text", "p_direction" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."warehouse_edge_inventory_page"("p_allowed_facility_ids" "uuid"[], "p_allowed_org_ids" "uuid"[], "p_mode" "text", "p_item_id" "uuid", "p_search" "text", "p_facet" "text", "p_include_zero" boolean, "p_open_only" boolean, "p_status_code" "text", "p_sort" "text", "p_direction" "text", "p_limit" integer, "p_offset" integer) IS 'Service-role-only, allowlist-scoped Warehouse stock, movement and exception register page capped at 50 rows.';



CREATE OR REPLACE FUNCTION "public"."warehouse_edge_inventory_sku_detail"("p_allowed_facility_ids" "uuid"[], "p_allowed_org_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_facility_id" "uuid" DEFAULT NULL::"uuid", "p_item_id" "uuid" DEFAULT NULL::"uuid", "p_line_limit" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_line_limit integer := greatest(1, least(coalesce(p_line_limit, 50), 50));
  v_result jsonb;
begin
  if p_facility_id is null or p_item_id is null or not (p_facility_id = any(p_allowed_facility_ids)) then
    return null;
  end if;

  with base as materialized (
    select
      balance.*,
      facility."WMSFacility_Code" as facility_code,
      facility."WMSFacility_Name" as facility_name,
      organisation."Org_Name" as customer_name,
      item."WMSItem_SKU" as sku,
      item."WMSItem_Description" as item_description,
      item."WMSItem_BaseUOMCode" as base_uom_code,
      location."WMSLocation_Code" as location_code,
      location."WMSLocation_TypeCode" as location_type_code,
      zone."WMSZone_Name" as zone_name,
      zone."WMSZone_TypeCode" as zone_type_code,
      handling_unit."WMSHU_Code" as handling_unit_code,
      handling_unit."WMSHU_TypeCode" as handling_unit_type_code,
      lot."WMSLot_LotNumber" as lot_number,
      lot."WMSLot_BatchNumber" as batch_number,
      lot."WMSLot_ManufactureDate" as manufacture_date,
      lot."WMSLot_ExpiryDate" as expiry_date,
      coalesce(inventory_status."WMSInventoryStatus_Name", balance."WMSBalance_InventoryStatusCode") as inventory_status_name,
      coalesce(nullif(item_uom."WMSItemUOM_QuantityInBaseUOM", 0), 1) as quantity_factor
    from public."WMS_InventoryBalances" balance
    join public."WMS_Facilities" facility on facility."WMSFacility_ID" = balance."WMSBalance_FacilityID"
    join public."WMS_Items" item on item."WMSItem_ID" = balance."WMSBalance_ItemID"
    left join public."Org_Master" organisation on organisation."Org_id" = balance."WMSBalance_CustomerOrgID"
    left join public."WMS_Locations" location on location."WMSLocation_ID" = balance."WMSBalance_LocationID"
    left join public."WMS_Zones" zone on zone."WMSZone_ID" = location."WMSLocation_ZoneID"
    left join public."WMS_HandlingUnits" handling_unit on handling_unit."WMSHU_ID" = balance."WMSBalance_HU_ID"
    left join public."WMS_InventoryLots" lot on lot."WMSLot_ID" = balance."WMSBalance_LotID"
    left join public."sys_WMSInventoryStatuses" inventory_status on inventory_status."WMSInventoryStatus_Code" = balance."WMSBalance_InventoryStatusCode"
    left join public."WMS_ItemUOMs" item_uom
      on item_uom."WMSItemUOM_ItemID" = balance."WMSBalance_ItemID"
      and item_uom."WMSItemUOM_UOMCode" = balance."WMSBalance_UOMCode"
    where balance."WMSBalance_FacilityID" = p_facility_id
      and balance."WMSBalance_FacilityID" = any(p_allowed_facility_ids)
      and balance."WMSBalance_ItemID" = p_item_id
      and (p_allowed_org_ids is null or balance."WMSBalance_CustomerOrgID" = any(p_allowed_org_ids))
      and balance."WMSBalance_OnHandQuantity" <> 0
  ), classified as materialized (
    select *,
      case
        when "WMSBalance_LocationID" is null then 'unlocated'
        when location_type_code = 'quarantine' then 'quarantine'
        when zone_type_code = 'picking' then 'pick_face'
        when location_type_code in ('staging', 'dock') or zone_type_code in ('receiving', 'packing', 'dispatch') then 'staging'
        else 'bulk_reserve'
      end as location_group_code
    from base
  ), location_totals as (
    select location_group_code,
      case location_group_code
        when 'pick_face' then 'Pick face'
        when 'bulk_reserve' then 'Bulk / reserve'
        when 'staging' then 'Staging'
        when 'quarantine' then 'Quarantine'
        else 'Unlocated'
      end as label,
      sum("WMSBalance_OnHandQuantity" * quantity_factor) as quantity
    from classified
    group by location_group_code
  ), storage_totals as (
    select storage_code, case when storage_code = 'loose' then 'Loose stock' else 'On pallets' end as label, quantity
    from (
      select case when "WMSBalance_HU_ID" is null then 'loose' else 'palletised' end as storage_code,
        sum("WMSBalance_OnHandQuantity" * quantity_factor) as quantity
      from classified
      group by 1
    ) grouped_storage
  ), pallet_totals as (
    select "WMSBalance_HU_ID" as id, handling_unit_code as code, handling_unit_type_code as type_code,
      location_code, sum("WMSBalance_OnHandQuantity" * quantity_factor) as quantity
    from classified
    where "WMSBalance_HU_ID" is not null
    group by "WMSBalance_HU_ID", handling_unit_code, handling_unit_type_code, location_code
  ), ordered_lines as (
    select *, row_number() over (order by "WMSBalance_AvailableQuantity" desc, location_code nulls last, "WMSBalance_ID") as ordinal
    from classified
  )
  select jsonb_build_object(
    'summary', (select jsonb_build_object(
      'facilityId', first_row."WMSBalance_FacilityID", 'facilityCode', first_row.facility_code, 'facilityName', first_row.facility_name,
      'customerOrgId', first_row."WMSBalance_CustomerOrgID", 'customerName', first_row.customer_name,
      'itemId', first_row."WMSBalance_ItemID", 'sku', first_row.sku, 'itemDescription', first_row.item_description,
      'uomCode', first_row.base_uom_code,
      'onHandQuantity', totals.on_hand,
      'reservedQuantity', totals.reserved,
      'allocatedQuantity', totals.allocated,
      'heldQuantity', totals.held,
      'availableQuantity', totals.available,
      'palletCount', totals.pallet_count,
      'locationCount', totals.location_count,
      'updatedAt', totals.updated_at
    ) from (select * from classified order by "WMSBalance_ID" limit 1) first_row
      cross join (select
        sum("WMSBalance_OnHandQuantity" * quantity_factor) as on_hand,
        sum("WMSBalance_ReservedQuantity" * quantity_factor) as reserved,
        sum("WMSBalance_AllocatedQuantity" * quantity_factor) as allocated,
        sum("WMSBalance_HeldQuantity" * quantity_factor) as held,
        sum("WMSBalance_AvailableQuantity" * quantity_factor) as available,
        count(distinct "WMSBalance_HU_ID") filter (where "WMSBalance_HU_ID" is not null) as pallet_count,
        count(distinct "WMSBalance_LocationID") filter (where "WMSBalance_LocationID" is not null) as location_count,
        max("WMSBalance_UpdatedAt") as updated_at
      from classified) totals),
    'locationBreakdown', coalesce((select jsonb_agg(jsonb_build_object('code', location_group_code, 'label', label, 'quantity', quantity) order by case location_group_code when 'pick_face' then 1 when 'bulk_reserve' then 2 when 'staging' then 3 when 'quarantine' then 4 else 5 end) from location_totals), '[]'::jsonb),
    'storageBreakdown', coalesce((select jsonb_agg(jsonb_build_object('code', storage_code, 'label', label, 'quantity', quantity) order by storage_code desc) from storage_totals), '[]'::jsonb),
    'pallets', coalesce((select jsonb_agg(jsonb_build_object('id', id, 'code', code, 'typeCode', type_code, 'locationCode', location_code, 'quantity', quantity) order by code) from pallet_totals), '[]'::jsonb),
    'lines', coalesce((select jsonb_agg(jsonb_build_object(
      'id', line."WMSBalance_ID", 'facilityId', line."WMSBalance_FacilityID", 'facilityCode', line.facility_code,
      'facilityName', line.facility_name, 'customerOrgId', line."WMSBalance_CustomerOrgID", 'customerName', line.customer_name,
      'itemId', line."WMSBalance_ItemID", 'sku', line.sku, 'itemDescription', line.item_description,
      'locationId', line."WMSBalance_LocationID", 'locationCode', line.location_code,
      'locationTypeCode', line.location_type_code, 'zoneTypeCode', line.zone_type_code, 'zoneName', line.zone_name,
      'handlingUnitId', line."WMSBalance_HU_ID", 'handlingUnitCode', line.handling_unit_code,
      'handlingUnitTypeCode', line.handling_unit_type_code, 'lotId', line."WMSBalance_LotID",
      'lotNumber', line.lot_number, 'batchNumber', line.batch_number, 'manufactureDate', line.manufacture_date,
      'expiryDate', line.expiry_date, 'inventoryStatusCode', line."WMSBalance_InventoryStatusCode",
      'inventoryStatusName', line.inventory_status_name, 'customsStatusCode', line."WMSBalance_CustomsStatusCode",
      'uomCode', line."WMSBalance_UOMCode", 'onHandQuantity', line."WMSBalance_OnHandQuantity",
      'reservedQuantity', line."WMSBalance_ReservedQuantity", 'allocatedQuantity', line."WMSBalance_AllocatedQuantity",
      'heldQuantity', line."WMSBalance_HeldQuantity", 'availableQuantity', line."WMSBalance_AvailableQuantity",
      'baseQuantity', line."WMSBalance_OnHandQuantity" * line.quantity_factor,
      'isBonded', line."WMSBalance_IsBonded", 'firstReceiptAt', line."WMSBalance_FirstReceiptAt",
      'lastMovementAt', line."WMSBalance_LastMovementAt", 'updatedAt', line."WMSBalance_UpdatedAt"
    ) order by line.ordinal) from ordered_lines line where line.ordinal <= v_line_limit), '[]'::jsonb),
    'lineTotal', (select count(*) from classified),
    'lineLimit', v_line_limit
  ) into v_result;

  if v_result->'summary' = 'null'::jsonb then
    return null;
  end if;
  return v_result;
end;
$$;


ALTER FUNCTION "public"."warehouse_edge_inventory_sku_detail"("p_allowed_facility_ids" "uuid"[], "p_allowed_org_ids" "uuid"[], "p_facility_id" "uuid", "p_item_id" "uuid", "p_line_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."warehouse_edge_inventory_sku_detail"("p_allowed_facility_ids" "uuid"[], "p_allowed_org_ids" "uuid"[], "p_facility_id" "uuid", "p_item_id" "uuid", "p_line_limit" integer) IS 'Service-role-only exact Warehouse SKU stock breakdown with deterministic aggregates and at most 50 exact balance lines.';



CREATE OR REPLACE FUNCTION "public"."warehouse_edge_inventory_skus_page"("p_allowed_facility_ids" "uuid"[], "p_allowed_org_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_search" "text" DEFAULT NULL::"text", "p_facet" "text" DEFAULT NULL::"text", "p_sort" "text" DEFAULT NULL::"text", "p_direction" "text" DEFAULT 'desc'::"text", "p_limit" integer DEFAULT 20, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_limit integer := greatest(1, least(coalesce(p_limit, 20), 50));
  v_offset integer := greatest(0, coalesce(p_offset, 0));
  v_search text := lower(nullif(btrim(p_search), ''));
  v_facet text := nullif(btrim(p_facet), '');
  v_direction text := case when lower(p_direction) = 'asc' then 'asc' else 'desc' end;
  v_result jsonb;
begin
  if coalesce(cardinality(p_allowed_facility_ids), 0) = 0 then
    return jsonb_build_object('rows', '[]'::jsonb, 'total', 0, 'limit', v_limit, 'offset', v_offset, 'facets', '[]'::jsonb);
  end if;

  with base as materialized (
    select
      balance."WMSBalance_FacilityID" as facility_id,
      facility."WMSFacility_Code" as facility_code,
      facility."WMSFacility_Name" as facility_name,
      balance."WMSBalance_CustomerOrgID" as customer_org_id,
      organisation."Org_Name" as customer_name,
      balance."WMSBalance_ItemID" as item_id,
      item."WMSItem_SKU" as sku,
      item."WMSItem_Description" as item_description,
      item."WMSItem_BaseUOMCode" as base_uom_code,
      balance."WMSBalance_HU_ID" as handling_unit_id,
      balance."WMSBalance_LocationID" as location_id,
      balance."WMSBalance_OnHandQuantity" * coalesce(nullif(item_uom."WMSItemUOM_QuantityInBaseUOM", 0), 1) as on_hand,
      balance."WMSBalance_ReservedQuantity" * coalesce(nullif(item_uom."WMSItemUOM_QuantityInBaseUOM", 0), 1) as reserved,
      balance."WMSBalance_AllocatedQuantity" * coalesce(nullif(item_uom."WMSItemUOM_QuantityInBaseUOM", 0), 1) as allocated,
      balance."WMSBalance_HeldQuantity" * coalesce(nullif(item_uom."WMSItemUOM_QuantityInBaseUOM", 0), 1) as held,
      balance."WMSBalance_AvailableQuantity" * coalesce(nullif(item_uom."WMSItemUOM_QuantityInBaseUOM", 0), 1) as available,
      balance."WMSBalance_UpdatedAt" as updated_at
    from public."WMS_InventoryBalances" balance
    join public."WMS_Facilities" facility on facility."WMSFacility_ID" = balance."WMSBalance_FacilityID"
    join public."WMS_Items" item on item."WMSItem_ID" = balance."WMSBalance_ItemID"
    left join public."Org_Master" organisation on organisation."Org_id" = balance."WMSBalance_CustomerOrgID"
    left join public."WMS_ItemUOMs" item_uom
      on item_uom."WMSItemUOM_ItemID" = balance."WMSBalance_ItemID"
      and item_uom."WMSItemUOM_UOMCode" = balance."WMSBalance_UOMCode"
    where balance."WMSBalance_FacilityID" = any(p_allowed_facility_ids)
      and (p_allowed_org_ids is null or balance."WMSBalance_CustomerOrgID" = any(p_allowed_org_ids))
      and balance."WMSBalance_OnHandQuantity" <> 0
      and (v_search is null or strpos(lower(concat_ws(' ', item."WMSItem_SKU", item."WMSItem_Description", organisation."Org_Name", facility."WMSFacility_Name")), v_search) > 0)
  ), grouped as materialized (
    select
      facility_id, facility_code, facility_name, customer_org_id, customer_name,
      item_id, sku, item_description, base_uom_code,
      sum(on_hand) as on_hand,
      sum(reserved) as reserved,
      sum(allocated) as allocated,
      sum(held) as held,
      sum(available) as available,
      count(distinct handling_unit_id) filter (where handling_unit_id is not null) as pallet_count,
      count(distinct location_id) filter (where location_id is not null) as location_count,
      max(updated_at) as updated_at
    from base
    group by facility_id, facility_code, facility_name, customer_org_id, customer_name, item_id, sku, item_description, base_uom_code
  ), filtered as materialized (
    select * from grouped where v_facet is null or customer_name = v_facet
  ), ranked as (
    select *, row_number() over (
      order by
        case when v_direction = 'asc' then case p_sort
          when 'stock-item' then lower(sku)
          when 'stock-customer' then lower(customer_name)
          when 'stock-warehouse' then lower(facility_name)
        end end asc nulls last,
        case when v_direction = 'desc' then case p_sort
          when 'stock-item' then lower(sku)
          when 'stock-customer' then lower(customer_name)
          when 'stock-warehouse' then lower(facility_name)
        end end desc nulls last,
        case when v_direction = 'asc' and p_sort = 'stock-onHand' then on_hand end asc nulls last,
        case when v_direction = 'desc' and p_sort = 'stock-onHand' then on_hand end desc nulls last,
        case when v_direction = 'asc' and p_sort = 'stock-available' then available end asc nulls last,
        case when v_direction = 'desc' and p_sort = 'stock-available' then available end desc nulls last,
        case when v_direction = 'asc' and p_sort = 'stock-reserved' then reserved end asc nulls last,
        case when v_direction = 'desc' and p_sort = 'stock-reserved' then reserved end desc nulls last,
        case when v_direction = 'asc' and p_sort = 'stock-held' then held end asc nulls last,
        case when v_direction = 'desc' and p_sort = 'stock-held' then held end desc nulls last,
        case when v_direction = 'asc' and p_sort = 'stock-pallets' then pallet_count end asc nulls last,
        case when v_direction = 'desc' and p_sort = 'stock-pallets' then pallet_count end desc nulls last,
        case when v_direction = 'asc' and p_sort = 'stock-locations' then location_count end asc nulls last,
        case when v_direction = 'desc' and p_sort = 'stock-locations' then location_count end desc nulls last,
        case when p_sort is null and v_direction = 'asc' then updated_at end asc,
        case when p_sort is null and v_direction = 'desc' then updated_at end desc,
        facility_id, item_id
    ) as ordinal
    from filtered
  ), page as (
    select * from ranked where ordinal > v_offset and ordinal <= v_offset + v_limit
  )
  select jsonb_build_object(
    'rows', coalesce((select jsonb_agg(jsonb_build_object(
      'id', row.item_id::text || ':' || row.facility_id::text,
      'facilityId', row.facility_id, 'facilityCode', row.facility_code, 'facilityName', row.facility_name,
      'customerOrgId', row.customer_org_id, 'customerName', row.customer_name,
      'itemId', row.item_id, 'sku', row.sku, 'itemDescription', row.item_description,
      'uomCode', row.base_uom_code, 'onHandQuantity', row.on_hand,
      'reservedQuantity', row.reserved, 'allocatedQuantity', row.allocated,
      'heldQuantity', row.held, 'availableQuantity', row.available,
      'palletCount', row.pallet_count, 'locationCount', row.location_count,
      'updatedAt', row.updated_at
    ) order by row.ordinal) from page row), '[]'::jsonb),
    'total', (select count(*) from filtered),
    'limit', v_limit,
    'offset', v_offset,
    'facets', coalesce((select jsonb_agg(value order by value) from (select distinct customer_name as value from grouped where customer_name is not null) values_for_facet), '[]'::jsonb)
  ) into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."warehouse_edge_inventory_skus_page"("p_allowed_facility_ids" "uuid"[], "p_allowed_org_ids" "uuid"[], "p_search" "text", "p_facet" "text", "p_sort" "text", "p_direction" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."warehouse_edge_inventory_skus_page"("p_allowed_facility_ids" "uuid"[], "p_allowed_org_ids" "uuid"[], "p_search" "text", "p_facet" "text", "p_sort" "text", "p_direction" "text", "p_limit" integer, "p_offset" integer) IS 'Service-role-only, allowlist-scoped Warehouse SKU totals page capped at 50 rows and normalised to each item base UOM.';



CREATE OR REPLACE FUNCTION "public"."warehouse_edge_item_id_by_sku"("p_allowed_facility_ids" "uuid"[], "p_allowed_org_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_sku" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select item."WMSItem_ID" from public."WMS_Items" item
  where btrim(coalesce(p_sku,''))<>'' and lower(item."WMSItem_SKU")=lower(btrim(p_sku))
    and (p_allowed_org_ids is null or item."WMSItem_CustomerOrgID"=any(p_allowed_org_ids)) and not item."WMSItem_IsDeleted"
    and exists(select 1 from public."WMS_ItemFacilityAssignments" assignment where assignment."WMSItemFacility_ItemID"=item."WMSItem_ID" and assignment."WMSItemFacility_FacilityID"=any(coalesce(p_allowed_facility_ids,'{}'::uuid[])) and assignment."WMSItemFacility_IsActive")
  order by item."WMSItem_ID" limit 1;
$$;


ALTER FUNCTION "public"."warehouse_edge_item_id_by_sku"("p_allowed_facility_ids" "uuid"[], "p_allowed_org_ids" "uuid"[], "p_sku" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."warehouse_edge_item_id_by_sku"("p_allowed_facility_ids" "uuid"[], "p_allowed_org_ids" "uuid"[], "p_sku" "text") IS 'Resolves one exact case-insensitive Warehouse item SKU inside an Edge-authenticated facility and organisation scope.';



CREATE OR REPLACE FUNCTION "public"."warehouse_edge_item_selector_page"("p_allowed_facility_ids" "uuid"[], "p_allowed_org_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_facility_id" "uuid" DEFAULT NULL::"uuid", "p_customer_org_id" "uuid" DEFAULT NULL::"uuid", "p_search" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 25, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_limit integer:=greatest(1,least(coalesce(p_limit,25),50)); v_offset integer:=greatest(0,coalesce(p_offset,0)); v_search text:=lower(nullif(btrim(p_search),'')); v_result jsonb;
begin
  if p_facility_id is null or p_customer_org_id is null or not p_facility_id=any(coalesce(p_allowed_facility_ids,'{}'::uuid[])) or (p_allowed_org_ids is not null and not p_customer_org_id=any(p_allowed_org_ids)) then return jsonb_build_object('rows','[]'::jsonb,'limit',v_limit,'offset',v_offset,'hasMore',false); end if;
  with candidates as materialized (
    select item.* from public."WMS_Items" item join public."WMS_ItemFacilityAssignments" assignment on assignment."WMSItemFacility_ItemID"=item."WMSItem_ID" and assignment."WMSItemFacility_FacilityID"=p_facility_id and assignment."WMSItemFacility_IsActive"
    where item."WMSItem_CustomerOrgID"=p_customer_org_id and item."WMSItem_IsActive" and not item."WMSItem_IsDeleted" and (v_search is null or strpos(lower(concat_ws(' ',item."WMSItem_SKU",item."WMSItem_Description")),v_search)>0)
    order by lower(item."WMSItem_SKU"),item."WMSItem_ID" limit v_limit+1 offset v_offset
  ), page as (select * from candidates order by lower("WMSItem_SKU"),"WMSItem_ID" limit v_limit)
  select jsonb_build_object('rows',coalesce((select jsonb_agg(jsonb_build_object('id',item."WMSItem_ID",'customerOrgId',item."WMSItem_CustomerOrgID",'facilityId',p_facility_id,'sku',item."WMSItem_SKU",'description',item."WMSItem_Description",'uomCode',item."WMSItem_BaseUOMCode",'quantityBasisCode',coalesce(item."WMSItem_QuantityBasisCode",'count'),'allowsFractionalQuantity',coalesce(item."WMSItem_AllowsFractionalQuantity",false),'requiresLot',item."WMSItem_RequiresLot",'requiresExpiry',item."WMSItem_RequiresExpiry") order by lower(item."WMSItem_SKU"),item."WMSItem_ID") from page item),'[]'::jsonb),'limit',v_limit,'offset',v_offset,'hasMore',(select count(*)>v_limit from candidates)) into v_result;
  return v_result;
end;
$$;


