COMMENT ON FUNCTION "public"."warehouse_edge_location_has_open_order"("p_facility_id" "uuid", "p_location_id" "uuid") IS 'Returns whether one facility-scoped open warehouse order references a location without transferring order-line history.';



CREATE OR REPLACE FUNCTION "public"."warehouse_edge_location_selector_page"("p_allowed_facility_ids" "uuid"[], "p_facility_id" "uuid" DEFAULT NULL::"uuid", "p_search" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 25, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_limit integer := greatest(1, least(coalesce(p_limit, 25), 50));
  v_offset integer := greatest(0, coalesce(p_offset, 0));
  v_search text := lower(nullif(btrim(p_search), ''));
  v_pattern text;
  v_result jsonb;
begin
  if p_facility_id is null
    or not (p_facility_id = any(coalesce(p_allowed_facility_ids, '{}'::uuid[]))) then
    return jsonb_build_object('rows', '[]'::jsonb, 'limit', v_limit, 'offset', v_offset, 'hasMore', false);
  end if;

  if v_search is not null then
    v_pattern := '%' || replace(replace(replace(v_search, E'\\', E'\\\\'), '%', E'\\%'), '_', E'\\_') || '%';
  end if;

  with candidates as materialized (
    select
      location."WMSLocation_ID" as id,
      location."WMSLocation_FacilityID" as facility_id,
      location."WMSLocation_Code" as code,
      location."WMSLocation_StatusCode" as status_code,
      location."WMSLocation_TypeCode" as type_code
    from public."WMS_Locations" location
    where location."WMSLocation_FacilityID" = p_facility_id
      and location."WMSLocation_IsActive"
      and not location."WMSLocation_IsDeleted"
      and (v_search is null or lower(coalesce(location."WMSLocation_Code", '')) like v_pattern escape E'\\')
    order by lower(location."WMSLocation_Code"), location."WMSLocation_ID"
    limit v_limit + 1
    offset v_offset
  ), page as (
    select * from candidates order by lower(code), id limit v_limit
  )
  select jsonb_build_object(
    'rows', coalesce((select jsonb_agg(jsonb_build_object(
      'id', row.id,
      'facilityId', row.facility_id,
      'code', row.code,
      'zoneName', null,
      'statusCode', row.status_code,
      'typeCode', row.type_code
    ) order by lower(row.code), row.id) from page row), '[]'::jsonb),
    'limit', v_limit,
    'offset', v_offset,
    'hasMore', (select count(*) > v_limit from candidates)
  ) into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."warehouse_edge_location_selector_page"("p_allowed_facility_ids" "uuid"[], "p_facility_id" "uuid", "p_search" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."warehouse_edge_location_selector_page"("p_allowed_facility_ids" "uuid"[], "p_facility_id" "uuid", "p_search" "text", "p_limit" integer, "p_offset" integer) IS 'Returns one capped tenant-scoped location selector page, including status and type for inventory actions.';



CREATE OR REPLACE FUNCTION "public"."warehouse_edge_locations_page"("p_allowed_facility_ids" "uuid"[], "p_facility_id" "uuid", "p_search" "text" DEFAULT NULL::"text", "p_include_inactive" boolean DEFAULT false, "p_sort" "text" DEFAULT 'code'::"text", "p_direction" "text" DEFAULT 'asc'::"text", "p_limit" integer DEFAULT 20, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_limit integer := greatest(1, least(coalesce(p_limit, 20), 50));
  v_offset integer := greatest(0, coalesce(p_offset, 0));
  v_search text := lower(nullif(btrim(p_search), ''));
  v_sort text := case when p_sort in ('code', 'zone', 'type', 'position', 'status') then p_sort else 'code' end;
  v_direction text := case when lower(p_direction) = 'desc' then 'desc' else 'asc' end;
  v_result jsonb;
begin
  if p_facility_id is null or not (p_facility_id = any(coalesce(p_allowed_facility_ids, array[]::uuid[]))) then
    raise exception 'WMS403: You do not have access to this warehouse.';
  end if;

  with filtered as materialized (
    select
      location.*,
      zone."WMSZone_TypeCode" as zone_type_code,
      zone."WMSZone_Name" as zone_name,
      location_type."WMSLocationType_Name" as type_name,
      location_status."WMSLocationStatus_Name" as status_name,
      concat_ws(' ', location."WMSLocation_Aisle", location."WMSLocation_Bay", location."WMSLocation_Level", location."WMSLocation_Position") as position_text
    from public."WMS_Locations" location
    left join public."WMS_Zones" zone on zone."WMSZone_ID" = location."WMSLocation_ZoneID"
    left join public."sys_WMSLocationTypes" location_type on location_type."WMSLocationType_Code" = location."WMSLocation_TypeCode"
    left join public."sys_WMSLocationStatuses" location_status on location_status."WMSLocationStatus_Code" = location."WMSLocation_StatusCode"
    where location."WMSLocation_FacilityID" = p_facility_id
      and not location."WMSLocation_IsDeleted"
      and (p_include_inactive or location."WMSLocation_IsActive")
      and (v_search is null or strpos(lower(concat_ws(' ',
        location."WMSLocation_Code", location."WMSLocation_Barcode", location."WMSLocation_Aisle",
        location."WMSLocation_Bay", location."WMSLocation_Level", location."WMSLocation_Position", zone."WMSZone_Name"
      )), v_search) > 0)
  ), ranked as (
    select *, row_number() over (
      order by
        case when v_direction = 'asc' then case v_sort
          when 'code' then lower("WMSLocation_Code") when 'zone' then lower(zone_name)
          when 'type' then lower(type_name) when 'position' then lower(position_text)
        end end asc nulls last,
        case when v_direction = 'desc' then case v_sort
          when 'code' then lower("WMSLocation_Code") when 'zone' then lower(zone_name)
          when 'type' then lower(type_name) when 'position' then lower(position_text)
        end end desc nulls last,
        case when v_direction = 'asc' and v_sort = 'status' then "WMSLocation_IsActive" end asc,
        case when v_direction = 'desc' and v_sort = 'status' then "WMSLocation_IsActive" end desc,
        lower("WMSLocation_Code"), "WMSLocation_ID"
    ) as ordinal
    from filtered
  ), page as (
    select * from ranked where ordinal > v_offset and ordinal <= v_offset + v_limit
  )
  select jsonb_build_object(
    'rows', coalesce((select jsonb_agg(jsonb_build_object(
      'id', location."WMSLocation_ID", 'facilityId', location."WMSLocation_FacilityID",
      'code', location."WMSLocation_Code", 'barcode', location."WMSLocation_Barcode",
      'typeCode', location."WMSLocation_TypeCode", 'typeName', location.type_name,
      'statusCode', location."WMSLocation_StatusCode", 'statusName', location.status_name,
      'zoneId', location."WMSLocation_ZoneID", 'zoneTypeCode', location.zone_type_code, 'zoneName', location.zone_name,
      'aisle', location."WMSLocation_Aisle", 'bay', location."WMSLocation_Bay", 'level', location."WMSLocation_Level",
      'position', location."WMSLocation_Position", 'lengthM', location."WMSLocation_LengthM",
      'widthM', location."WMSLocation_WidthM", 'heightM', location."WMSLocation_HeightM",
      'maxWeightKg', location."WMSLocation_MaxWeightKG", 'maxVolumeCbm', location."WMSLocation_MaxVolumeCBM",
      'temperatureMinC', location."WMSLocation_TemperatureMinC", 'temperatureMaxC', location."WMSLocation_TemperatureMaxC",
      'allowsMultiSku', location."WMSLocation_AllowsMultiSKU", 'allowsBondedStock', location."WMSLocation_AllowsBondedStock",
      'isActive', location."WMSLocation_IsActive", 'createdAt', location."WMSLocation_CreatedAt",
      'updatedAt', location."WMSLocation_UpdatedAt"
    ) order by location.ordinal) from page location), '[]'::jsonb),
    'total', (select count(*) from filtered),
    'limit', v_limit,
    'offset', v_offset
  ) into v_result;
  return v_result;
end;
$$;


ALTER FUNCTION "public"."warehouse_edge_locations_page"("p_allowed_facility_ids" "uuid"[], "p_facility_id" "uuid", "p_search" "text", "p_include_inactive" boolean, "p_sort" "text", "p_direction" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."warehouse_edge_locations_page"("p_allowed_facility_ids" "uuid"[], "p_facility_id" "uuid", "p_search" "text", "p_include_inactive" boolean, "p_sort" "text", "p_direction" "text", "p_limit" integer, "p_offset" integer) IS 'Service-role-only, facility-allowlist-scoped Warehouse locations register page capped at 50 rows.';



CREATE OR REPLACE FUNCTION "public"."warehouse_edge_next_purchase_order_number"("p_allowed_facility_ids" "uuid"[], "p_facility_id" "uuid", "p_prefix" "text") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  v_prefix text := left(btrim(coalesce(p_prefix, '')), 100);
  v_sequence bigint;
  v_sequence_text text;
begin
  if p_facility_id is null
    or not (p_facility_id = any(coalesce(p_allowed_facility_ids, '{}'::uuid[]))) then
    return null;
  end if;
  if v_prefix = '' then
    return null;
  end if;

  select (substring(purchase_order."WMSPO_Number" from '([0-9]+)$'))::bigint
    into v_sequence
  from public."WMS_PurchaseOrders" purchase_order
  where purchase_order."WMSPO_FacilityID" = p_facility_id
    and not purchase_order."WMSPO_IsDeleted"
    and purchase_order."WMSPO_Number" ~ '-[0-9]+$'
    and lower(regexp_replace(purchase_order."WMSPO_Number", '-[0-9]+$', '')) = lower(v_prefix)
  order by (substring(purchase_order."WMSPO_Number" from '([0-9]+)$'))::bigint desc
  limit 1;

  v_sequence_text := (coalesce(v_sequence, 0) + 1)::text;
  return v_prefix || '-' || lpad(v_sequence_text, greatest(4, length(v_sequence_text)), '0');
end;
$_$;


ALTER FUNCTION "public"."warehouse_edge_next_purchase_order_number"("p_allowed_facility_ids" "uuid"[], "p_facility_id" "uuid", "p_prefix" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."warehouse_edge_next_purchase_order_number"("p_allowed_facility_ids" "uuid"[], "p_facility_id" "uuid", "p_prefix" "text") IS 'Returns one indexed next-number suggestion inside an Edge-authenticated warehouse scope.';



CREATE OR REPLACE FUNCTION "public"."warehouse_edge_order_availability"("p_allowed_facility_ids" "uuid"[], "p_order_id" "uuid", "p_limit_per_item" integer DEFAULT 25, "p_total_limit" integer DEFAULT 500) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_per_item integer := greatest(1, least(coalesce(p_limit_per_item, 25), 50));
  v_total integer := greatest(1, least(coalesce(p_total_limit, 500), 1000));
  v_result jsonb;
begin
  with selected_order as materialized (
    select
      warehouse_order."WMSOrder_ID" as order_id,
      warehouse_order."WMSOrder_FacilityID" as facility_id,
      warehouse_order."WMSOrder_CustomerOrgID" as customer_org_id
    from public."WMS_Orders" warehouse_order
    where warehouse_order."WMSOrder_ID" = p_order_id
      and warehouse_order."WMSOrder_FacilityID" = any(coalesce(p_allowed_facility_ids, '{}'::uuid[]))
      and warehouse_order."WMSOrder_TypeCode" = 'outbound'
      and not warehouse_order."WMSOrder_IsDeleted"
    limit 1
  ), order_items as materialized (
    select distinct
      order_line."WMSOrderLine_ItemID" as item_id,
      order_line."WMSOrderLine_CustomsStatusCode" as customs_status_code
    from selected_order
    join public."WMS_OrderLines" order_line
      on order_line."WMSOrderLine_OrderID" = selected_order.order_id
  ), ranked as (
    select
      balance."WMSBalance_ID" as id,
      balance."WMSBalance_ItemID" as item_id,
      balance."WMSBalance_LocationID" as location_id,
      location."WMSLocation_Code" as location_code,
      balance."WMSBalance_LotID" as lot_id,
      lot."WMSLot_LotNumber" as lot_number,
      lot."WMSLot_BatchNumber" as batch_number,
      balance."WMSBalance_CustomsStatusCode" as customs_status_code,
      balance."WMSBalance_UOMCode" as uom_code,
      balance."WMSBalance_AvailableQuantity" as available_quantity,
      balance."WMSBalance_FirstReceiptAt" as first_receipt_at,
      row_number() over (
        partition by balance."WMSBalance_ItemID", balance."WMSBalance_CustomsStatusCode"
        order by balance."WMSBalance_FirstReceiptAt" nulls last, balance."WMSBalance_ID"
      ) as item_rank
    from selected_order
    join order_items on true
    join public."WMS_InventoryBalances" balance
      on balance."WMSBalance_FacilityID" = selected_order.facility_id
      and balance."WMSBalance_CustomerOrgID" = selected_order.customer_org_id
      and balance."WMSBalance_ItemID" = order_items.item_id
      and balance."WMSBalance_CustomsStatusCode" = order_items.customs_status_code
      and balance."WMSBalance_InventoryStatusCode" = 'available'
      and balance."WMSBalance_AvailableQuantity" > 0
    left join public."WMS_InventoryLots" lot
      on lot."WMSLot_ID" = balance."WMSBalance_LotID"
    left join public."WMS_Locations" location
      on location."WMSLocation_ID" = balance."WMSBalance_LocationID"
  ), capped as (
    select *
    from ranked
    where item_rank <= v_per_item
    order by item_id, customs_status_code, item_rank
    limit v_total
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', entry.id,
    'itemId', entry.item_id,
    'locationId', entry.location_id,
    'locationCode', entry.location_code,
    'lotId', entry.lot_id,
    'lotNumber', entry.lot_number,
    'batchNumber', entry.batch_number,
    'customsStatusCode', entry.customs_status_code,
    'uomCode', entry.uom_code,
    'availableQuantity', entry.available_quantity
  ) order by entry.item_id, entry.customs_status_code, entry.item_rank), '[]'::jsonb)
  into v_result
  from capped entry;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."warehouse_edge_order_availability"("p_allowed_facility_ids" "uuid"[], "p_order_id" "uuid", "p_limit_per_item" integer, "p_total_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."warehouse_edge_order_availability"("p_allowed_facility_ids" "uuid"[], "p_order_id" "uuid", "p_limit_per_item" integer, "p_total_limit" integer) IS 'Returns capped FIFO stock choices for the outbound items on one authorised warehouse order.';



CREATE OR REPLACE FUNCTION "public"."warehouse_edge_order_mutation"("p_action" "text", "p_order_id" "uuid", "p_payload" "jsonb", "p_actor_user_id" "uuid", "p_actor_portal_user_id" "uuid", "p_allowed_facility_ids" "uuid"[], "p_allowed_organisation_ids" "uuid"[]) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_order public."WMS_Orders"%rowtype;
  v_line public."WMS_OrderLines"%rowtype;
  v_item public."WMS_Items"%rowtype;
  v_facility public."WMS_Facilities"%rowtype;
  v_input jsonb;
  v_order_id uuid := coalesce(p_order_id, gen_random_uuid());
  v_line_id uuid;
  v_transaction_id uuid;
  v_primary_transaction_id uuid;
  v_receipt_id uuid;
  v_dispatch_id uuid;
  v_advice_id uuid;
  v_balance public."WMS_InventoryBalances"%rowtype;
  v_balance_id uuid;
  v_lot_id uuid;
  v_location_id uuid;
  v_quantity numeric;
  v_damaged numeric;
  v_good numeric;
  v_remaining numeric;
  v_take numeric;
  v_before numeric;
  v_now timestamptz := now();
  v_complete boolean;
  v_index integer := 0;
  v_type text;
  v_customs text;
  v_status text;
  v_number text;
begin
  if p_action = 'create' then
    v_type := lower(trim(p_payload->>'typeCode'));
    if v_type not in ('inbound', 'outbound') then raise exception 'WMS400: Warehouse orders must be inbound or outbound.'; end if;
    if not ((p_payload->>'facilityId')::uuid = any(p_allowed_facility_ids)) then raise exception 'WMS400: Choose a warehouse in your workspace.'; end if;
    if not ((p_payload->>'customerOrgId')::uuid = any(p_allowed_organisation_ids)) then raise exception 'WMS400: Choose a valid customer.'; end if;
    if jsonb_typeof(p_payload->'lines') <> 'array' or jsonb_array_length(p_payload->'lines') = 0 then raise exception 'WMS400: Add at least one item line.'; end if;
    select * into v_facility from public."WMS_Facilities" where "WMSFacility_ID" = (p_payload->>'facilityId')::uuid and not "WMSFacility_IsDeleted" and "WMSFacility_IsActive" for share;
    if not found then raise exception 'WMS400: Choose a warehouse in your workspace.'; end if;
    v_number := upper(left(v_type, 2)) || '-' || to_char(v_now, 'YYYYMMDD-HH24MISS') || '-' || lpad((floor(random() * 9000) + 1000)::int::text, 4, '0');
    insert into public."WMS_Orders" (
      "WMSOrder_ID","WMSOrder_FacilityID","WMSOrder_OrgOfficeID","WMSOrder_CustomerOrgID","WMSOrder_OrderNumber","WMSOrder_TypeCode","WMSOrder_StatusCode","WMSOrder_PriorityCode","WMSOrder_CustomerReference","WMSOrder_RequestedDate","WMSOrder_AppointmentStartAt","WMSOrder_AppointmentEndAt","WMSOrder_VehicleReg","WMSOrder_ContainerNumber","WMSOrder_SealNumber","WMSOrder_RequiresCustomsRelease","WMSOrder_RequiresComplianceRelease","WMSOrder_RequiresFinanceRelease","WMSOrder_ReleaseGateStatusCode","WMSOrder_Instructions","WMSOrder_MetadataJSON","WMSOrder_CreatedAt","WMSOrder_CreatedBy","WMSOrder_UpdatedAt","WMSOrder_UpdatedBy","WMSOrder_IsDeleted"
    ) values (
      v_order_id,(p_payload->>'facilityId')::uuid,v_facility."WMSFacility_OrgOfficeID",(p_payload->>'customerOrgId')::uuid,v_number,v_type,'booked',coalesce(nullif(trim(p_payload->>'priorityCode'),''),'normal'),nullif(trim(p_payload->>'customerReference'),''),nullif(p_payload->>'requestedDate','')::date,nullif(p_payload->>'appointmentStartAt','')::timestamptz,nullif(p_payload->>'appointmentEndAt','')::timestamptz,nullif(trim(p_payload->>'vehicleReg'),''),upper(nullif(trim(p_payload->>'containerNumber'),'')),nullif(trim(p_payload->>'sealNumber'),''),false,false,false,'not_checked',nullif(trim(p_payload->>'instructions'),''),'{}',v_now,p_actor_user_id,v_now,p_actor_user_id,false
    );
    if p_actor_portal_user_id is not null and v_type='inbound' then
      v_advice_id:=gen_random_uuid();
      insert into public."WMS_InboundAdvices" ("WMSAdvice_ID","WMSAdvice_FacilityID","WMSAdvice_OrderID","WMSAdvice_AdviceNumber","WMSAdvice_StatusCode","WMSAdvice_CustomerOrgID","WMSAdvice_ExpectedArrivalAt","WMSAdvice_ContainerNumber","WMSAdvice_SealNumber","WMSAdvice_MetadataJSON","WMSAdvice_CreatedAt") values(v_advice_id,(p_payload->>'facilityId')::uuid,v_order_id,'ASN-'||v_number,'booked',(p_payload->>'customerOrgId')::uuid,nullif(p_payload->>'appointmentStartAt','')::timestamptz,upper(nullif(trim(p_payload->>'containerNumber'),'')),nullif(trim(p_payload->>'sealNumber'),''),'{"source":"customer_portal"}',v_now);
    end if;
    for v_input in select value from jsonb_array_elements(p_payload->'lines') loop
      v_index := v_index + 1; v_quantity := (v_input->>'quantity')::numeric;
      if v_quantity <= 0 then raise exception 'WMS400: Quantity must be greater than zero.'; end if;
      select * into v_item from public."WMS_Items" where "WMSItem_ID" = (v_input->>'itemId')::uuid and "WMSItem_CustomerOrgID" = (p_payload->>'customerOrgId')::uuid and "WMSItem_DefaultFacilityID" = (p_payload->>'facilityId')::uuid and "WMSItem_IsActive" and not "WMSItem_IsDeleted";
      if not found then raise exception 'WMS400: One or more selected items are not available.'; end if;
      v_customs := coalesce(nullif(trim(v_input->>'customsStatusCode'),''),v_facility."WMSFacility_DefaultCustomsStatusCode");
      if v_type = 'outbound' and (select coalesce(sum("WMSBalance_AvailableQuantity"),0) from public."WMS_InventoryBalances" where "WMSBalance_FacilityID" = v_facility."WMSFacility_ID" and "WMSBalance_CustomerOrgID" = v_item."WMSItem_CustomerOrgID" and "WMSBalance_ItemID" = v_item."WMSItem_ID" and "WMSBalance_InventoryStatusCode" = 'available' and "WMSBalance_CustomsStatusCode" = v_customs and "WMSBalance_AvailableQuantity" > 0 and ((v_input->>'sourceLocationId') is null or "WMSBalance_LocationID" = (v_input->>'sourceLocationId')::uuid)) < v_quantity then raise exception 'WMS400: There is not enough available stock for this outbound line.'; end if;
      v_line_id:=gen_random_uuid();
      insert into public."WMS_OrderLines" ("WMSOrderLine_ID","WMSOrderLine_OrderID","WMSOrderLine_LineNo","WMSOrderLine_ItemID","WMSOrderLine_StatusCode","WMSOrderLine_OrderedQuantity","WMSOrderLine_ReceivedQuantity","WMSOrderLine_AllocatedQuantity","WMSOrderLine_PickedQuantity","WMSOrderLine_PackedQuantity","WMSOrderLine_DispatchedQuantity","WMSOrderLine_UOMCode","WMSOrderLine_LotNumber","WMSOrderLine_ExpiryDate","WMSOrderLine_SourceLocationID","WMSOrderLine_TargetLocationID","WMSOrderLine_InventoryStatusCode","WMSOrderLine_CustomsStatusCode","WMSOrderLine_GoodsValue","WMSOrderLine_CurrencyCode","WMSOrderLine_Instructions","WMSOrderLine_MetadataJSON","WMSOrderLine_CreatedAt")
      values (v_line_id,v_order_id,v_index,v_item."WMSItem_ID",'open',v_quantity,0,0,0,0,0,upper(coalesce(nullif(trim(v_input->>'uomCode'),''),v_item."WMSItem_BaseUOMCode")),nullif(trim(v_input->>'lotNumber'),''),nullif(v_input->>'expiryDate','')::date,nullif(v_input->>'sourceLocationId','')::uuid,nullif(v_input->>'targetLocationId','')::uuid,'available',v_customs,nullif(v_input->>'goodsValue','')::numeric,upper(nullif(trim(v_input->>'currencyCode'),'')),nullif(trim(v_input->>'instructions'),''),'{}',v_now);
      if v_advice_id is not null then insert into public."WMS_InboundAdviceLines" ("WMSAdviceLine_ID","WMSAdviceLine_AdviceID","WMSAdviceLine_OrderLineID","WMSAdviceLine_LineNo","WMSAdviceLine_ItemID","WMSAdviceLine_ExpectedQuantity","WMSAdviceLine_UOMCode","WMSAdviceLine_LotNumber","WMSAdviceLine_ExpiryDate","WMSAdviceLine_CustomsStatusCode") values(gen_random_uuid(),v_advice_id,v_line_id,v_index,v_item."WMSItem_ID",v_quantity,upper(coalesce(nullif(trim(v_input->>'uomCode'),''),v_item."WMSItem_BaseUOMCode")),nullif(trim(v_input->>'lotNumber'),''),nullif(v_input->>'expiryDate','')::date,v_customs); end if;
    end loop;
    return v_order_id;
  end if;

  select * into v_order from public."WMS_Orders" where "WMSOrder_ID" = p_order_id and not "WMSOrder_IsDeleted" and "WMSOrder_FacilityID" = any(p_allowed_facility_ids) and "WMSOrder_CustomerOrgID" = any(p_allowed_organisation_ids) for update;
  if not found then raise exception 'WMS400: This warehouse order does not exist in your workspace.'; end if;
  if v_order."WMSOrder_StatusCode" in ('complete','cancelled') then raise exception 'WMS409: This order is already final.'; end if;

  if p_action = 'cancel' then
    if exists(select 1 from public."WMS_OrderLines" where "WMSOrderLine_OrderID"=p_order_id and ("WMSOrderLine_ReceivedQuantity">0 or "WMSOrderLine_DispatchedQuantity">0)) then raise exception 'WMS409: An order with posted stock movements cannot be cancelled.'; end if;
    update public."WMS_OrderLines" set "WMSOrderLine_StatusCode"='cancelled' where "WMSOrderLine_OrderID"=p_order_id;
    update public."WMS_Orders" set "WMSOrder_StatusCode"='cancelled',"WMSOrder_UpdatedAt"=v_now,"WMSOrder_UpdatedBy"=p_actor_user_id where "WMSOrder_ID"=p_order_id;
    return p_order_id;
  end if;

  if p_action = 'reschedule' then
    if nullif(p_payload->>'appointmentStartAt','') is null or nullif(p_payload->>'appointmentEndAt','') is null then raise exception 'WMS400: A slot needs both a start and an end.'; end if;
    if (p_payload->>'appointmentEndAt')::timestamptz <= (p_payload->>'appointmentStartAt')::timestamptz then raise exception 'WMS400: A slot has to end after it starts.'; end if;
    update public."WMS_Orders" set "WMSOrder_AppointmentStartAt"=(p_payload->>'appointmentStartAt')::timestamptz,"WMSOrder_AppointmentEndAt"=(p_payload->>'appointmentEndAt')::timestamptz,"WMSOrder_UpdatedAt"=v_now,"WMSOrder_UpdatedBy"=p_actor_user_id where "WMSOrder_ID"=p_order_id;
    -- The inbound advice quotes the same slot back to the customer, so it moves with it.
    update public."WMS_InboundAdvices" set "WMSAdvice_ExpectedArrivalAt"=(p_payload->>'appointmentStartAt')::timestamptz where "WMSAdvice_OrderID"=p_order_id;
    return p_order_id;
  end if;

  if jsonb_typeof(p_payload->'lines') <> 'array' or jsonb_array_length(p_payload->'lines') = 0 then raise exception 'WMS400: Add at least one posting line.'; end if;
  if p_action = 'receive' then
    if v_order."WMSOrder_TypeCode" <> 'inbound' then raise exception 'WMS400: Only inbound orders can be received.'; end if;
    v_receipt_id := gen_random_uuid(); v_number := 'GRN-'||to_char(v_now,'YYYYMMDD-HH24MISS')||'-'||lpad((floor(random()*9000)+1000)::int::text,4,'0');
    insert into public."WMS_Receipts" ("WMSReceipt_ID","WMSReceipt_FacilityID","WMSReceipt_OrderID","WMSReceipt_JobID","WMSReceipt_ReceiptNumber","WMSReceipt_StatusCode","WMSReceipt_ReceivingLocationID","WMSReceipt_ReceivedAt","WMSReceipt_ReceivedBy","WMSReceipt_HasDiscrepancy","WMSReceipt_Notes","WMSReceipt_MetadataJSON","WMSReceipt_CreatedAt","WMSReceipt_CreatedBy") values (v_receipt_id,v_order."WMSOrder_FacilityID",p_order_id,v_order."WMSOrder_JobID",v_number,'complete',nullif(p_payload->>'receivingLocationId','')::uuid,v_now,p_actor_user_id,false,nullif(trim(p_payload->>'notes'),''),'{}',v_now,p_actor_user_id);
    for v_input in select value from jsonb_array_elements(p_payload->'lines') loop
      v_index:=v_index+1; v_primary_transaction_id:=null;
      select * into v_line from public."WMS_OrderLines" where "WMSOrderLine_ID"=(v_input->>'orderLineId')::uuid and "WMSOrderLine_OrderID"=p_order_id for update; if not found then raise exception 'WMS400: A received line does not belong to this order.'; end if;
      v_quantity := (v_input->>'quantity')::numeric; v_damaged := coalesce((v_input->>'damagedQuantity')::numeric,0); if v_quantity<=0 or v_damaged<0 or v_damaged>v_quantity then raise exception 'WMS400: Check the received and damaged quantities.'; end if;
      v_location_id := coalesce(nullif(v_input->>'targetLocationId','')::uuid,v_line."WMSOrderLine_TargetLocationID",nullif(p_payload->>'receivingLocationId','')::uuid); if v_location_id is null then raise exception 'WMS400: Choose a receiving location.'; end if;
      if not exists(select 1 from public."WMS_Locations" where "WMSLocation_ID"=v_location_id and "WMSLocation_FacilityID"=v_order."WMSOrder_FacilityID" and "WMSLocation_IsActive" and not "WMSLocation_IsDeleted") then raise exception 'WMS400: Choose an active receiving location.'; end if;
      v_lot_id := null; if coalesce(nullif(trim(v_input->>'lotNumber'),''),nullif(trim(v_input->>'batchNumber'),''),v_line."WMSOrderLine_LotNumber") is not null then select "WMSLot_ID" into v_lot_id from public."WMS_InventoryLots" where "WMSLot_FacilityID"=v_order."WMSOrder_FacilityID" and "WMSLot_ItemID"=v_line."WMSOrderLine_ItemID" and "WMSLot_LotNumber"=coalesce(nullif(trim(v_input->>'lotNumber'),''),v_line."WMSOrderLine_LotNumber",nullif(trim(v_input->>'batchNumber'),'')) limit 1; if v_lot_id is null then v_lot_id:=gen_random_uuid(); insert into public."WMS_InventoryLots" ("WMSLot_ID","WMSLot_FacilityID","WMSLot_CustomerOrgID","WMSLot_ItemID","WMSLot_LotNumber","WMSLot_BatchNumber","WMSLot_ManufactureDate","WMSLot_ExpiryDate","WMSLot_CustomsStatusCode","WMSLot_AttributesJSON","WMSLot_CreatedAt") values(v_lot_id,v_order."WMSOrder_FacilityID",v_order."WMSOrder_CustomerOrgID",v_line."WMSOrderLine_ItemID",coalesce(nullif(trim(v_input->>'lotNumber'),''),v_line."WMSOrderLine_LotNumber",trim(v_input->>'batchNumber')),coalesce(nullif(trim(v_input->>'batchNumber'),''),nullif(trim(v_input->>'lotNumber'),'')),nullif(v_input->>'manufactureDate','')::date,coalesce(nullif(v_input->>'expiryDate','')::date,v_line."WMSOrderLine_ExpiryDate"),v_line."WMSOrderLine_CustomsStatusCode",'{}',v_now); end if; end if;
      foreach v_status in array array['available','damaged'] loop v_good := case when v_status='available' then v_quantity-v_damaged else v_damaged end; if v_good<=0 then continue; end if; select * into v_balance from public."WMS_InventoryBalances" where "WMSBalance_FacilityID"=v_order."WMSOrder_FacilityID" and "WMSBalance_CustomerOrgID"=v_order."WMSOrder_CustomerOrgID" and "WMSBalance_ItemID"=v_line."WMSOrderLine_ItemID" and "WMSBalance_LocationID"=v_location_id and "WMSBalance_LotID" is not distinct from v_lot_id and "WMSBalance_InventoryStatusCode"=v_status and "WMSBalance_CustomsStatusCode"=v_line."WMSOrderLine_CustomsStatusCode" and "WMSBalance_UOMCode"=v_line."WMSOrderLine_UOMCode" for update; if not found then v_balance_id:=gen_random_uuid(); v_before:=0; insert into public."WMS_InventoryBalances" ("WMSBalance_ID","WMSBalance_FacilityID","WMSBalance_CustomerOrgID","WMSBalance_ItemID","WMSBalance_LocationID","WMSBalance_LotID","WMSBalance_InventoryStatusCode","WMSBalance_CustomsStatusCode","WMSBalance_UOMCode","WMSBalance_OnHandQuantity","WMSBalance_ReservedQuantity","WMSBalance_AllocatedQuantity","WMSBalance_HeldQuantity","WMSBalance_AvailableQuantity","WMSBalance_FirstReceiptAt","WMSBalance_LastMovementAt","WMSBalance_IsBonded","WMSBalance_MetadataJSON","WMSBalance_CreatedAt","WMSBalance_UpdatedAt") values(v_balance_id,v_order."WMSOrder_FacilityID",v_order."WMSOrder_CustomerOrgID",v_line."WMSOrderLine_ItemID",v_location_id,v_lot_id,v_status,v_line."WMSOrderLine_CustomsStatusCode",v_line."WMSOrderLine_UOMCode",v_good,0,0,case when v_status='damaged' then v_good else 0 end,case when v_status='available' then v_good else 0 end,v_now,v_now,v_line."WMSOrderLine_CustomsStatusCode"<>'free_circulation','{}',v_now,v_now); else v_balance_id:=v_balance."WMSBalance_ID"; v_before:=v_balance."WMSBalance_OnHandQuantity"; update public."WMS_InventoryBalances" set "WMSBalance_OnHandQuantity"="WMSBalance_OnHandQuantity"+v_good,"WMSBalance_HeldQuantity"="WMSBalance_HeldQuantity"+case when v_status='damaged' then v_good else 0 end,"WMSBalance_AvailableQuantity"=greatest(0,"WMSBalance_OnHandQuantity"+v_good-"WMSBalance_ReservedQuantity"-"WMSBalance_AllocatedQuantity"-("WMSBalance_HeldQuantity"+case when v_status='damaged' then v_good else 0 end)),"WMSBalance_LastMovementAt"=v_now,"WMSBalance_UpdatedAt"=v_now where "WMSBalance_ID"=v_balance_id; end if; v_transaction_id:=gen_random_uuid(); v_primary_transaction_id:=coalesce(v_primary_transaction_id,v_transaction_id); insert into public."WMS_InventoryTransactions" ("WMSTransaction_ID","WMSTransaction_FacilityID","WMSTransaction_BalanceID","WMSTransaction_TypeCode","WMSTransaction_ItemID","WMSTransaction_CustomerOrgID","WMSTransaction_ToLocationID","WMSTransaction_LotID","WMSTransaction_Quantity","WMSTransaction_UOMCode","WMSTransaction_BeforeOnHandQuantity","WMSTransaction_AfterOnHandQuantity","WMSTransaction_InventoryStatusCode","WMSTransaction_CustomsStatusCode","WMSTransaction_OrderID","WMSTransaction_OrderLineID","WMSTransaction_ReceiptID","WMSTransaction_SourceTable","WMSTransaction_SourceID","WMSTransaction_Reference","WMSTransaction_Notes","WMSTransaction_MetadataJSON","WMSTransaction_CreatedAt","WMSTransaction_CreatedBy") values(v_transaction_id,v_order."WMSOrder_FacilityID",v_balance_id,'receipt',v_line."WMSOrderLine_ItemID",v_order."WMSOrder_CustomerOrgID",v_location_id,v_lot_id,v_good,v_line."WMSOrderLine_UOMCode",v_before,v_before+v_good,v_status,v_line."WMSOrderLine_CustomsStatusCode",p_order_id,v_line."WMSOrderLine_ID",v_receipt_id,'WMS_Receipts',v_receipt_id,v_number,nullif(trim(p_payload->>'notes'),''),'{}',v_now,p_actor_user_id); end loop;
      insert into public."WMS_ReceiptLines" ("WMSReceiptLine_ID","WMSReceiptLine_ReceiptID","WMSReceiptLine_OrderLineID","WMSReceiptLine_ItemID","WMSReceiptLine_LineNo","WMSReceiptLine_ExpectedQuantity","WMSReceiptLine_ReceivedQuantity","WMSReceiptLine_DamagedQuantity","WMSReceiptLine_OverQuantity","WMSReceiptLine_ShortQuantity","WMSReceiptLine_UOMCode","WMSReceiptLine_LotNumber","WMSReceiptLine_ExpiryDate","WMSReceiptLine_TargetLocationID","WMSReceiptLine_InventoryTransactionID","WMSReceiptLine_CustomsStatusCode","WMSReceiptLine_CreatedAt") values(gen_random_uuid(),v_receipt_id,v_line."WMSOrderLine_ID",v_line."WMSOrderLine_ItemID",v_index,greatest(0,v_line."WMSOrderLine_OrderedQuantity"-v_line."WMSOrderLine_ReceivedQuantity"),v_quantity,v_damaged,greatest(0,v_quantity-(v_line."WMSOrderLine_OrderedQuantity"-v_line."WMSOrderLine_ReceivedQuantity")),greatest(0,(v_line."WMSOrderLine_OrderedQuantity"-v_line."WMSOrderLine_ReceivedQuantity")-v_quantity),v_line."WMSOrderLine_UOMCode",(select "WMSLot_LotNumber" from public."WMS_InventoryLots" where "WMSLot_ID"=v_lot_id),coalesce(nullif(v_input->>'expiryDate','')::date,v_line."WMSOrderLine_ExpiryDate"),v_location_id,v_primary_transaction_id,v_line."WMSOrderLine_CustomsStatusCode",v_now);
      if v_damaged>0 or v_quantity>v_line."WMSOrderLine_OrderedQuantity"-v_line."WMSOrderLine_ReceivedQuantity" then update public."WMS_Receipts" set "WMSReceipt_HasDiscrepancy"=true where "WMSReceipt_ID"=v_receipt_id; end if;
      update public."WMS_OrderLines" set "WMSOrderLine_ReceivedQuantity"="WMSOrderLine_ReceivedQuantity"+v_quantity,"WMSOrderLine_StatusCode"=case when "WMSOrderLine_ReceivedQuantity"+v_quantity >= "WMSOrderLine_OrderedQuantity" then 'received' else 'open' end where "WMSOrderLine_ID"=v_line."WMSOrderLine_ID";
    end loop;
  elsif p_action = 'dispatch' then
    if v_order."WMSOrder_TypeCode" <> 'outbound' then raise exception 'WMS400: Only outbound orders can be dispatched.'; end if;
    v_dispatch_id:=gen_random_uuid(); v_number:='DSP-'||to_char(v_now,'YYYYMMDD-HH24MISS')||'-'||lpad((floor(random()*9000)+1000)::int::text,4,'0'); insert into public."WMS_Dispatches" ("WMSDispatch_ID","WMSDispatch_FacilityID","WMSDispatch_OrderID","WMSDispatch_JobID","WMSDispatch_DispatchNumber","WMSDispatch_StatusCode","WMSDispatch_VehicleReg","WMSDispatch_ContainerNumber","WMSDispatch_SealNumber","WMSDispatch_DispatchedAt","WMSDispatch_DispatchedBy","WMSDispatch_MetadataJSON","WMSDispatch_CreatedAt") values(v_dispatch_id,v_order."WMSOrder_FacilityID",p_order_id,v_order."WMSOrder_JobID",v_number,'complete',coalesce(nullif(trim(p_payload->>'vehicleReg'),''),v_order."WMSOrder_VehicleReg"),coalesce(upper(nullif(trim(p_payload->>'containerNumber'),'')),v_order."WMSOrder_ContainerNumber"),coalesce(nullif(trim(p_payload->>'sealNumber'),''),v_order."WMSOrder_SealNumber"),v_now,p_actor_user_id,jsonb_build_object('notes',nullif(trim(p_payload->>'notes'),'')),v_now);
    for v_input in select value from jsonb_array_elements(p_payload->'lines') loop select * into v_line from public."WMS_OrderLines" where "WMSOrderLine_ID"=(v_input->>'orderLineId')::uuid and "WMSOrderLine_OrderID"=p_order_id for update; if not found then raise exception 'WMS400: A dispatch line does not belong to this order.'; end if; v_quantity:=(v_input->>'quantity')::numeric; if v_quantity<=0 or v_quantity>v_line."WMSOrderLine_OrderedQuantity"-v_line."WMSOrderLine_DispatchedQuantity" then raise exception 'WMS400: Check the dispatch quantity.'; end if; v_remaining:=v_quantity; for v_balance in select * from public."WMS_InventoryBalances" where "WMSBalance_FacilityID"=v_order."WMSOrder_FacilityID" and "WMSBalance_CustomerOrgID"=v_order."WMSOrder_CustomerOrgID" and "WMSBalance_ItemID"=v_line."WMSOrderLine_ItemID" and "WMSBalance_InventoryStatusCode"='available' and "WMSBalance_CustomsStatusCode"=v_line."WMSOrderLine_CustomsStatusCode" and "WMSBalance_AvailableQuantity">0 and ((v_input->>'sourceLocationId') is null or "WMSBalance_LocationID"=(v_input->>'sourceLocationId')::uuid) and ((v_input->>'lotId') is null or "WMSBalance_LotID"=(v_input->>'lotId')::uuid) order by "WMSBalance_FirstReceiptAt" for update loop exit when v_remaining<=0; v_take:=least(v_remaining,v_balance."WMSBalance_AvailableQuantity"); v_before:=v_balance."WMSBalance_OnHandQuantity"; update public."WMS_InventoryBalances" set "WMSBalance_OnHandQuantity"="WMSBalance_OnHandQuantity"-v_take,"WMSBalance_AvailableQuantity"=greatest(0,"WMSBalance_AvailableQuantity"-v_take),"WMSBalance_LastMovementAt"=v_now,"WMSBalance_UpdatedAt"=v_now where "WMSBalance_ID"=v_balance."WMSBalance_ID"; insert into public."WMS_InventoryTransactions" ("WMSTransaction_ID","WMSTransaction_FacilityID","WMSTransaction_BalanceID","WMSTransaction_TypeCode","WMSTransaction_ItemID","WMSTransaction_CustomerOrgID","WMSTransaction_FromLocationID","WMSTransaction_LotID","WMSTransaction_Quantity","WMSTransaction_UOMCode","WMSTransaction_BeforeOnHandQuantity","WMSTransaction_AfterOnHandQuantity","WMSTransaction_InventoryStatusCode","WMSTransaction_CustomsStatusCode","WMSTransaction_OrderID","WMSTransaction_OrderLineID","WMSTransaction_SourceTable","WMSTransaction_SourceID","WMSTransaction_Reference","WMSTransaction_Notes","WMSTransaction_MetadataJSON","WMSTransaction_CreatedAt","WMSTransaction_CreatedBy") values(gen_random_uuid(),v_order."WMSOrder_FacilityID",v_balance."WMSBalance_ID",'dispatch',v_line."WMSOrderLine_ItemID",v_order."WMSOrder_CustomerOrgID",v_balance."WMSBalance_LocationID",v_balance."WMSBalance_LotID",v_take,v_line."WMSOrderLine_UOMCode",v_before,v_before-v_take,'available',v_line."WMSOrderLine_CustomsStatusCode",p_order_id,v_line."WMSOrderLine_ID",'WMS_Dispatches',v_dispatch_id,v_number,nullif(trim(p_payload->>'notes'),''),'{}',v_now,p_actor_user_id); v_remaining:=v_remaining-v_take; end loop; if v_remaining>0 then raise exception 'WMS409: There is not enough available stock to complete this dispatch.'; end if; update public."WMS_OrderLines" set "WMSOrderLine_AllocatedQuantity"=greatest("WMSOrderLine_AllocatedQuantity","WMSOrderLine_DispatchedQuantity"+v_quantity),"WMSOrderLine_PickedQuantity"=greatest("WMSOrderLine_PickedQuantity","WMSOrderLine_DispatchedQuantity"+v_quantity),"WMSOrderLine_PackedQuantity"=greatest("WMSOrderLine_PackedQuantity","WMSOrderLine_DispatchedQuantity"+v_quantity),"WMSOrderLine_DispatchedQuantity"="WMSOrderLine_DispatchedQuantity"+v_quantity,"WMSOrderLine_StatusCode"=case when "WMSOrderLine_DispatchedQuantity"+v_quantity >= "WMSOrderLine_OrderedQuantity" then 'dispatched' else 'open' end where "WMSOrderLine_ID"=v_line."WMSOrderLine_ID"; end loop;
  else raise exception 'WMS400: Unsupported warehouse order action.'; end if;
  select case when v_order."WMSOrder_TypeCode"='inbound' then bool_and("WMSOrderLine_ReceivedQuantity">="WMSOrderLine_OrderedQuantity") else bool_and("WMSOrderLine_DispatchedQuantity">="WMSOrderLine_OrderedQuantity") end into v_complete from public."WMS_OrderLines" where "WMSOrderLine_OrderID"=p_order_id;
  update public."WMS_Orders" set "WMSOrder_StatusCode"=case when v_complete then 'complete' else 'part_complete' end,"WMSOrder_UpdatedAt"=v_now,"WMSOrder_UpdatedBy"=p_actor_user_id where "WMSOrder_ID"=p_order_id;
  return p_order_id;
end;
$$;


ALTER FUNCTION "public"."warehouse_edge_order_mutation"("p_action" "text", "p_order_id" "uuid", "p_payload" "jsonb", "p_actor_user_id" "uuid", "p_actor_portal_user_id" "uuid", "p_allowed_facility_ids" "uuid"[], "p_allowed_organisation_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."warehouse_edge_orders_page"("p_allowed_facility_ids" "uuid"[], "p_allowed_org_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_facility_id" "uuid" DEFAULT NULL::"uuid", "p_type_code" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text", "p_open_only" boolean DEFAULT false, "p_search" "text" DEFAULT NULL::"text", "p_sort" "text" DEFAULT NULL::"text", "p_direction" "text" DEFAULT 'desc'::"text", "p_limit" integer DEFAULT 20, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_limit integer := greatest(1, least(coalesce(p_limit, 20), 50));
  v_offset integer := greatest(0, coalesce(p_offset, 0));
  v_search text := lower(nullif(btrim(p_search), ''));
  v_status text := nullif(btrim(p_status), '');
  v_direction text := case when lower(p_direction) = 'asc' then 'asc' else 'desc' end;
  v_result jsonb;
begin
  if coalesce(cardinality(p_allowed_facility_ids), 0) = 0 then
    return jsonb_build_object('rows', '[]'::jsonb, 'total', 0, 'limit', v_limit, 'offset', v_offset, 'facets', '[]'::jsonb);
  end if;

  with base as materialized (
    select
      warehouse_order.*,
      facility."WMSFacility_Code" as facility_code,
      facility."WMSFacility_Name" as facility_name,
      organisation."Org_Name" as customer_name,
      order_type."WMSOrderType_Name" as type_name,
      order_status."WMSOrderStatus_Name" as status_name,
      order_status."WMSOrderStatus_IsOpen" as status_is_open,
      coalesce(line_totals.line_count, 0)::integer as line_count,
      coalesce(line_totals.ordered_quantity, 0) as ordered_quantity,
      coalesce(
        case when warehouse_order."WMSOrder_TypeCode" = 'inbound'
          then line_totals.received_quantity
          else line_totals.dispatched_quantity
        end,
        0
      ) as progressed_quantity
    from public."WMS_Orders" warehouse_order
    join public."WMS_Facilities" facility
      on facility."WMSFacility_ID" = warehouse_order."WMSOrder_FacilityID"
    join public."Org_Master" organisation
      on organisation."Org_id" = warehouse_order."WMSOrder_CustomerOrgID"
    left join public."sys_WMSOrderTypes" order_type
      on order_type."WMSOrderType_Code" = warehouse_order."WMSOrder_TypeCode"
    left join public."sys_WMSOrderStatuses" order_status
      on order_status."WMSOrderStatus_Code" = warehouse_order."WMSOrder_StatusCode"
    left join lateral (
      select
        count(*) as line_count,
        coalesce(sum(line."WMSOrderLine_OrderedQuantity"), 0) as ordered_quantity,
        coalesce(sum(line."WMSOrderLine_ReceivedQuantity"), 0) as received_quantity,
        coalesce(sum(line."WMSOrderLine_DispatchedQuantity"), 0) as dispatched_quantity
      from public."WMS_OrderLines" line
      where line."WMSOrderLine_OrderID" = warehouse_order."WMSOrder_ID"
    ) line_totals on true
    where warehouse_order."WMSOrder_FacilityID" = any(p_allowed_facility_ids)
      and (p_allowed_org_ids is null or warehouse_order."WMSOrder_CustomerOrgID" = any(p_allowed_org_ids))
      and (p_facility_id is null or warehouse_order."WMSOrder_FacilityID" = p_facility_id)
      and (p_type_code is null or warehouse_order."WMSOrder_TypeCode" = p_type_code)
      and not warehouse_order."WMSOrder_IsDeleted"
      and (not p_open_only or coalesce(order_status."WMSOrderStatus_IsOpen", false))
      and (
        v_search is null
        or strpos(lower(concat_ws(' ',
          warehouse_order."WMSOrder_OrderNumber",
          warehouse_order."WMSOrder_CustomerReference",
          warehouse_order."WMSOrder_VehicleReg",
          warehouse_order."WMSOrder_ContainerNumber",
          organisation."Org_Name",
          facility."WMSFacility_Code",
          facility."WMSFacility_Name"
        )), v_search) > 0
        or exists (
          select 1
          from public."WMS_OrderLines" search_line
          join public."WMS_Items" search_item on search_item."WMSItem_ID" = search_line."WMSOrderLine_ItemID"
          where search_line."WMSOrderLine_OrderID" = warehouse_order."WMSOrder_ID"
            and strpos(lower(concat_ws(' ', search_item."WMSItem_SKU", search_item."WMSItem_Description")), v_search) > 0
        )
      )
  ), filtered as materialized (
    select *
    from base
    where v_status is null or status_name = v_status or "WMSOrder_StatusCode" = v_status
  ), ranked as (
    select *, row_number() over (
      order by
        case when v_direction = 'asc' then case p_sort
          when 'order' then lower("WMSOrder_OrderNumber")
          when 'customer' then lower(customer_name)
          when 'warehouse' then lower(facility_name)
          when 'direction' then lower(coalesce(type_name, "WMSOrder_TypeCode"))
          when 'status' then lower(coalesce(status_name, "WMSOrder_StatusCode"))
        end end asc nulls last,
        case when v_direction = 'desc' then case p_sort
          when 'order' then lower("WMSOrder_OrderNumber")
          when 'customer' then lower(customer_name)
          when 'warehouse' then lower(facility_name)
          when 'direction' then lower(coalesce(type_name, "WMSOrder_TypeCode"))
          when 'status' then lower(coalesce(status_name, "WMSOrder_StatusCode"))
        end end desc nulls last,
        case when v_direction = 'asc' and p_sort = 'lines' then line_count end asc nulls last,
        case when v_direction = 'desc' and p_sort = 'lines' then line_count end desc nulls last,
        case when v_direction = 'asc' and p_sort = 'progress' then progressed_quantity / nullif(ordered_quantity, 0) end asc nulls last,
        case when v_direction = 'desc' and p_sort = 'progress' then progressed_quantity / nullif(ordered_quantity, 0) end desc nulls last,
        case when v_direction = 'asc' and p_sort = 'requested' then "WMSOrder_RequestedDate" end asc nulls last,
        case when v_direction = 'desc' and p_sort = 'requested' then "WMSOrder_RequestedDate" end desc nulls last,
        case when v_direction = 'asc' and p_sort = 'appointment' then "WMSOrder_AppointmentStartAt" end asc nulls last,
        case when v_direction = 'desc' and p_sort = 'appointment' then "WMSOrder_AppointmentStartAt" end desc nulls last,
        case when v_direction = 'asc' and p_sort = 'expected' then coalesce("WMSOrder_AppointmentStartAt", "WMSOrder_RequestedDate"::timestamp at time zone 'UTC') end asc nulls last,
        case when v_direction = 'desc' and p_sort = 'expected' then coalesce("WMSOrder_AppointmentStartAt", "WMSOrder_RequestedDate"::timestamp at time zone 'UTC') end desc nulls last,
        case when p_sort is null and v_direction = 'asc' then "WMSOrder_UpdatedAt" end asc,
        case when p_sort is null and v_direction = 'desc' then "WMSOrder_UpdatedAt" end desc,
        "WMSOrder_ID"
    ) as ordinal
    from filtered
  ), page as (
    select * from ranked where ordinal > v_offset and ordinal <= v_offset + v_limit
  )
  select jsonb_build_object(
    'rows', coalesce((select jsonb_agg(jsonb_build_object(
      'id', row."WMSOrder_ID", 'facilityId', row."WMSOrder_FacilityID",
      'facilityCode', row.facility_code, 'facilityName', row.facility_name,
      'officeId', row."WMSOrder_OrgOfficeID", 'officeName', null,
      'customerOrgId', row."WMSOrder_CustomerOrgID", 'customerName', row.customer_name,
      'orderNumber', row."WMSOrder_OrderNumber", 'typeCode', row."WMSOrder_TypeCode",
      'typeName', row.type_name, 'statusCode', row."WMSOrder_StatusCode", 'statusName', row.status_name,
      'priorityCode', row."WMSOrder_PriorityCode", 'customerReference', row."WMSOrder_CustomerReference",
      'requestedDate', row."WMSOrder_RequestedDate", 'appointmentStartAt', row."WMSOrder_AppointmentStartAt",
      'appointmentEndAt', row."WMSOrder_AppointmentEndAt", 'vehicleReg', row."WMSOrder_VehicleReg",
      'containerNumber', row."WMSOrder_ContainerNumber", 'sealNumber', row."WMSOrder_SealNumber",
      'instructions', row."WMSOrder_Instructions", 'createdAt', row."WMSOrder_CreatedAt",
      'updatedAt', row."WMSOrder_UpdatedAt",
      'lines', coalesce((select jsonb_agg(jsonb_build_object(
        'id', line."WMSOrderLine_ID", 'lineNumber', line."WMSOrderLine_LineNo",
        'itemId', line."WMSOrderLine_ItemID", 'sku', item."WMSItem_SKU",
        'description', item."WMSItem_Description", 'statusCode', line."WMSOrderLine_StatusCode",
        'orderedQuantity', line."WMSOrderLine_OrderedQuantity", 'receivedQuantity', line."WMSOrderLine_ReceivedQuantity",
        'pickedQuantity', line."WMSOrderLine_PickedQuantity", 'packedQuantity', line."WMSOrderLine_PackedQuantity",
        'dispatchedQuantity', line."WMSOrderLine_DispatchedQuantity",
        'remainingQuantity', case when line."WMSOrderLine_StatusCode" = 'short' then 0 else greatest(0,
          line."WMSOrderLine_OrderedQuantity" - case when row."WMSOrder_TypeCode" = 'inbound'
            then line."WMSOrderLine_ReceivedQuantity" else line."WMSOrderLine_DispatchedQuantity" end) end,
        'uomCode', line."WMSOrderLine_UOMCode", 'lotNumber', line."WMSOrderLine_LotNumber",
        'expiryDate', line."WMSOrderLine_ExpiryDate", 'sourceLocationId', line."WMSOrderLine_SourceLocationID",
        'sourceLocationCode', source_location."WMSLocation_Code", 'targetLocationId', line."WMSOrderLine_TargetLocationID",
        'targetLocationCode', target_location."WMSLocation_Code", 'inventoryStatusCode', line."WMSOrderLine_InventoryStatusCode",
        'customsStatusCode', line."WMSOrderLine_CustomsStatusCode", 'goodsValue', line."WMSOrderLine_GoodsValue",
        'currencyCode', line."WMSOrderLine_CurrencyCode", 'instructions', line."WMSOrderLine_Instructions"
      ) order by line."WMSOrderLine_LineNo")
        from public."WMS_OrderLines" line
        join public."WMS_Items" item on item."WMSItem_ID" = line."WMSOrderLine_ItemID"
        left join public."WMS_Locations" source_location on source_location."WMSLocation_ID" = line."WMSOrderLine_SourceLocationID"
        left join public."WMS_Locations" target_location on target_location."WMSLocation_ID" = line."WMSOrderLine_TargetLocationID"
        where line."WMSOrderLine_OrderID" = row."WMSOrder_ID"), '[]'::jsonb),
      'receipts', coalesce((select jsonb_agg(jsonb_build_object(
        'id', receipt."WMSReceipt_ID", 'receiptNumber', receipt."WMSReceipt_ReceiptNumber",
        'statusCode', receipt."WMSReceipt_StatusCode", 'receivedAt', receipt."WMSReceipt_ReceivedAt",
        'hasDiscrepancy', receipt."WMSReceipt_HasDiscrepancy", 'notes', receipt."WMSReceipt_Notes"
      ) order by receipt."WMSReceipt_CreatedAt" desc)
        from public."WMS_Receipts" receipt where receipt."WMSReceipt_OrderID" = row."WMSOrder_ID"), '[]'::jsonb),
      'dispatches', coalesce((select jsonb_agg(jsonb_build_object(
        'id', dispatch."WMSDispatch_ID", 'dispatchNumber', dispatch."WMSDispatch_DispatchNumber",
        'statusCode', dispatch."WMSDispatch_StatusCode", 'dispatchedAt', dispatch."WMSDispatch_DispatchedAt",
        'vehicleReg', dispatch."WMSDispatch_VehicleReg", 'containerNumber', dispatch."WMSDispatch_ContainerNumber",
        'sealNumber', dispatch."WMSDispatch_SealNumber"
      ) order by dispatch."WMSDispatch_CreatedAt" desc)
        from public."WMS_Dispatches" dispatch where dispatch."WMSDispatch_OrderID" = row."WMSOrder_ID"), '[]'::jsonb)
    ) order by row.ordinal) from page row), '[]'::jsonb),
    'total', (select count(*) from filtered), 'limit', v_limit, 'offset', v_offset,
    'facets', coalesce((select jsonb_agg(value order by value) from (
      select distinct coalesce(status_name, "WMSOrder_StatusCode") as value from base
    ) facet_values where value is not null), '[]'::jsonb)
  ) into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."warehouse_edge_orders_page"("p_allowed_facility_ids" "uuid"[], "p_allowed_org_ids" "uuid"[], "p_facility_id" "uuid", "p_type_code" "text", "p_status" "text", "p_open_only" boolean, "p_search" "text", "p_sort" "text", "p_direction" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."warehouse_edge_orders_page"("p_allowed_facility_ids" "uuid"[], "p_allowed_org_ids" "uuid"[], "p_facility_id" "uuid", "p_type_code" "text", "p_status" "text", "p_open_only" boolean, "p_search" "text", "p_sort" "text", "p_direction" "text", "p_limit" integer, "p_offset" integer) IS 'Service-role-only, allowlist-scoped Warehouse operational order register page capped at 50 rows.';



CREATE OR REPLACE FUNCTION "public"."warehouse_edge_portal_mutation"("p_action" "text", "p_customer_org_id" "uuid", "p_portal_user_id" "uuid", "p_payload" "jsonb", "p_actor_user_id" "uuid", "p_actor_portal_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_user_id uuid:=p_portal_user_id; v_role_id uuid; v_site_id uuid; v_role_code text:=lower(trim(p_payload->>'roleCode')); v_email text:=lower(trim(p_payload->>'email')); v_facilities uuid[]; v_result jsonb; v_now timestamptz:=now(); v_invited boolean:=false;
begin
  if p_action in ('invite','update') and v_role_code not in ('warehouse_viewer','warehouse_operator','warehouse_customer_admin') then raise exception 'WMS400: Choose a valid warehouse customer role.'; end if;
  select "PortalSite_ID" into v_site_id from public."Portal_Sites" where "PortalSite_SiteTypeCode"='warehouse_customer' and "PortalSite_IsActive" and not "PortalSite_IsDeleted" order by "PortalSite_CreatedAt" limit 1;
  if v_site_id is null then
    v_site_id:=gen_random_uuid(); insert into public."Portal_Sites" ("PortalSite_ID","PortalSite_Code","PortalSite_Name","PortalSite_Description","PortalSite_SiteTypeCode","PortalSite_DefaultAudienceTypeCode","PortalSite_DefaultLanguageCode","PortalSite_DefaultTimeZone","PortalSite_AllowedAuthMethodsJSON","PortalSite_FieldPolicyJSON","PortalSite_FeatureFlagsJSON","PortalSite_IsActive","PortalSite_CreatedAt","PortalSite_CreatedBy","PortalSite_UpdatedAt","PortalSite_UpdatedBy","PortalSite_IsDeleted") values(v_site_id,'warehouse-'||replace(gen_random_uuid()::text,'-',''),'Warehouse customer portal','Customer self-service inventory and warehouse requests.','warehouse_customer','customer','en-GB','UTC','["password","magic_link"]','{}','{"warehouse":true}',true,v_now,p_actor_user_id,v_now,p_actor_user_id,false);
  end if;
  select "PortalRole_ID" into v_role_id from public."Portal_Roles" where "PortalRole_SiteID"=v_site_id and "PortalRole_Code"=v_role_code limit 1;
  if v_role_id is null and p_action in ('invite','update') then v_role_id:=gen_random_uuid(); insert into public."Portal_Roles" ("PortalRole_ID","PortalRole_SiteID","PortalRole_Code","PortalRole_Name","PortalRole_Description","PortalRole_AudienceTypeCode","PortalRole_IsSystemRole","PortalRole_IsEnabled","PortalRole_CreatedAt","PortalRole_CreatedBy") values(v_role_id,v_site_id,v_role_code,replace(initcap(replace(v_role_code,'_',' ')),'Warehouse Warehouse','Warehouse'),'Warehouse customer access.','customer',true,true,v_now,p_actor_user_id); end if;
  if p_action in ('invite','update') then
    insert into public."Portal_RolePermissions" ("PortalRolePerm_ID","PortalRolePerm_RoleID","PortalRolePerm_ResourceTypeCode","PortalRolePerm_ActionCode","PortalRolePerm_IsAllowed","PortalRolePerm_RequiresExplicitShare","PortalRolePerm_RequiresInternalReview","PortalRolePerm_FieldAllowListJSON","PortalRolePerm_FieldDenyListJSON","PortalRolePerm_CreatedAt")
    select gen_random_uuid(),v_role_id,grant_row.resource_code,grant_row.action_code,true,false,false,'[]','[]',v_now
    from (values
      ('warehouse_inventory','read','warehouse_viewer'),('warehouse_items','read','warehouse_viewer'),('warehouse_orders','read','warehouse_viewer'),
      ('warehouse_inventory','read','warehouse_operator'),('warehouse_items','read','warehouse_operator'),('warehouse_items','manage','warehouse_operator'),('warehouse_orders','read','warehouse_operator'),('warehouse_orders','create_inbound','warehouse_operator'),('warehouse_orders','create_outbound','warehouse_operator'),('warehouse_orders','cancel','warehouse_operator'),('warehouse_documents','upload','warehouse_operator'),
      ('warehouse_inventory','read','warehouse_customer_admin'),('warehouse_items','read','warehouse_customer_admin'),('warehouse_items','manage','warehouse_customer_admin'),('warehouse_orders','read','warehouse_customer_admin'),('warehouse_orders','create_inbound','warehouse_customer_admin'),('warehouse_orders','create_outbound','warehouse_customer_admin'),('warehouse_orders','cancel','warehouse_customer_admin'),('warehouse_documents','upload','warehouse_customer_admin'),('warehouse_users','manage','warehouse_customer_admin')
    ) grant_row(resource_code,action_code,role_code)
    where grant_row.role_code=v_role_code and not exists(select 1 from public."Portal_RolePermissions" existing where existing."PortalRolePerm_RoleID"=v_role_id and existing."PortalRolePerm_ResourceTypeCode"=grant_row.resource_code and existing."PortalRolePerm_ActionCode"=grant_row.action_code);
  end if;
  if p_action='invite' then
    if v_email is null or position('@' in v_email)=0 then raise exception 'WMS400: Enter a valid customer email address.'; end if;
    select "PortalUser_ID" into v_user_id from public."Portal_Users" where lower("PortalUser_Email")=v_email limit 1;
    if v_user_id is null then
      if nullif(p_payload->>'authUserId','') is null then raise exception 'WMS409: The Supabase invitation did not return a user identity.'; end if;
      v_user_id:=gen_random_uuid(); v_invited:=true;
      insert into public."Portal_Users" ("PortalUser_ID","PortalUser_DefaultSiteID","PortalUser_AudienceTypeCode","PortalUser_StatusCode","PortalUser_PrimaryOrgID","PortalUser_DisplayName","PortalUser_Email","PortalUser_PreferredLanguageCode","PortalUser_MFARequired","PortalUser_FailedLoginCount","PortalUser_ValidFrom","PortalUser_PreferencesJSON","PortalUser_CreatedAt","PortalUser_CreatedBy","PortalUser_UpdatedAt","PortalUser_UpdatedBy","PortalUser_IsDeleted") values(v_user_id,v_site_id,'customer','active',p_customer_org_id,coalesce(nullif(trim(p_payload->>'displayName'),''),v_email),v_email,'en-GB',false,0,v_now,'{}',v_now,p_actor_user_id,v_now,p_actor_user_id,false);
      insert into public."Portal_ExternalIdentities" ("PortalIdentity_ID","PortalIdentity_PortalUserID","PortalIdentity_AuthProviderCode","PortalIdentity_ExternalSubject","PortalIdentity_ExternalUsername","PortalIdentity_EmailSnapshot","PortalIdentity_StatusCode","PortalIdentity_MetadataJSON","PortalIdentity_CreatedAt","PortalIdentity_UpdatedAt") values(gen_random_uuid(),v_user_id,'supabase',p_payload->>'authUserId',v_email,v_email,'active','{}',v_now,v_now);
    end if;
  elsif p_action='revoke' then
    if v_user_id=p_actor_portal_user_id then raise exception 'WMS400: You cannot revoke your own portal access.'; end if;
    update public."Portal_UserOrganisations" set "PortalUserOrg_StatusCode"='revoked' where "PortalUserOrg_PortalUserID"=v_user_id and "PortalUserOrg_OrgID"=p_customer_org_id;
    update public."Portal_UserRoles" set "PortalUserRole_StatusCode"='revoked' where "PortalUserRole_PortalUserID"=v_user_id and "PortalUserRole_OrgID"=p_customer_org_id;
    return null;
  end if;
  if v_user_id is null then raise exception 'WMS400: This customer portal user does not exist.'; end if;
  insert into public."Portal_UserOrganisations" ("PortalUserOrg_ID","PortalUserOrg_PortalUserID","PortalUserOrg_OrgID","PortalUserOrg_AudienceTypeCode","PortalUserOrg_StatusCode","PortalUserOrg_IsPrimary","PortalUserOrg_CanManageOrgUsers","PortalUserOrg_FieldPolicyJSON","PortalUserOrg_CreatedAt","PortalUserOrg_CreatedBy") values(gen_random_uuid(),v_user_id,p_customer_org_id,'customer','active',true,v_role_code='warehouse_customer_admin','{}',v_now,p_actor_user_id) on conflict ("PortalUserOrg_PortalUserID","PortalUserOrg_OrgID","PortalUserOrg_AudienceTypeCode") do update set "PortalUserOrg_StatusCode"='active',"PortalUserOrg_CanManageOrgUsers"=excluded."PortalUserOrg_CanManageOrgUsers";
  update public."Portal_UserRoles" set "PortalUserRole_StatusCode"='revoked' where "PortalUserRole_PortalUserID"=v_user_id and "PortalUserRole_OrgID"=p_customer_org_id;
  insert into public."Portal_UserRoles" ("PortalUserRole_ID","PortalUserRole_PortalUserID","PortalUserRole_RoleID","PortalUserRole_SiteID","PortalUserRole_OrgID","PortalUserRole_StatusCode","PortalUserRole_ValidFrom","PortalUserRole_AssignedAt","PortalUserRole_AssignedBy") values(gen_random_uuid(),v_user_id,v_role_id,v_site_id,p_customer_org_id,'active',v_now,v_now,p_actor_user_id)
  on conflict on constraint "Portal_UserRoles_unique_role" do update set
    "PortalUserRole_StatusCode"='active',
    "PortalUserRole_ValidFrom"=excluded."PortalUserRole_ValidFrom",
    "PortalUserRole_ValidUntil"=null,
    "PortalUserRole_AssignedAt"=excluded."PortalUserRole_AssignedAt",
    "PortalUserRole_AssignedBy"=excluded."PortalUserRole_AssignedBy";
  if p_actor_user_id is not null and jsonb_typeof(p_payload->'facilityIds')='array' then
    select array_agg(value::uuid) into v_facilities from jsonb_array_elements_text(p_payload->'facilityIds'); if coalesce(array_length(v_facilities,1),0)=0 then raise exception 'WMS400: Choose at least one warehouse for this customer.'; end if;
    update public."WMS_CustomerFacilityAccess" set "WMSCustomerFacilityAccess_IsActive"=("WMSCustomerFacilityAccess_FacilityID"=any(v_facilities)),"WMSCustomerFacilityAccess_UpdatedAt"=v_now where "WMSCustomerFacilityAccess_CustomerOrgID"=p_customer_org_id;
    insert into public."WMS_CustomerFacilityAccess" ("WMSCustomerFacilityAccess_ID","WMSCustomerFacilityAccess_CustomerOrgID","WMSCustomerFacilityAccess_FacilityID","WMSCustomerFacilityAccess_IsActive","WMSCustomerFacilityAccess_CreatedAt","WMSCustomerFacilityAccess_CreatedBy","WMSCustomerFacilityAccess_UpdatedAt") select gen_random_uuid(),p_customer_org_id,f,true,v_now,p_actor_user_id,v_now from unnest(v_facilities) f on conflict ("WMSCustomerFacilityAccess_CustomerOrgID","WMSCustomerFacilityAccess_FacilityID") do update set "WMSCustomerFacilityAccess_IsActive"=true,"WMSCustomerFacilityAccess_UpdatedAt"=v_now;
  end if;
  select public.warehouse_edge_portal_users(p_customer_org_id) into v_result;
  select value into v_result from jsonb_array_elements(v_result) where value->>'id'=v_user_id::text limit 1;
  return case when p_action='invite' then jsonb_build_object('user',v_result,'invited',v_invited) else v_result end;
end; $$;


ALTER FUNCTION "public"."warehouse_edge_portal_mutation"("p_action" "text", "p_customer_org_id" "uuid", "p_portal_user_id" "uuid", "p_payload" "jsonb", "p_actor_user_id" "uuid", "p_actor_portal_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."warehouse_edge_portal_users"("p_customer_org_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  with facilities as (
    select coalesce(jsonb_agg("WMSCustomerFacilityAccess_FacilityID" order by "WMSCustomerFacilityAccess_FacilityID"), '[]'::jsonb) ids
    from public."WMS_CustomerFacilityAccess" where "WMSCustomerFacilityAccess_CustomerOrgID"=p_customer_org_id and "WMSCustomerFacilityAccess_IsActive"
  ), users as (
    select u."PortalUser_ID",u."PortalUser_DisplayName",u."PortalUser_Email",u."PortalUser_StatusCode",u."PortalUser_LastLoginAt",
      coalesce((select r."PortalRole_Code" from public."Portal_UserRoles" ur join public."Portal_Roles" r on r."PortalRole_ID"=ur."PortalUserRole_RoleID" where ur."PortalUserRole_PortalUserID"=u."PortalUser_ID" and ur."PortalUserRole_OrgID"=p_customer_org_id and ur."PortalUserRole_StatusCode"='active' limit 1),'warehouse_viewer') role_code
    from public."Portal_UserOrganisations" uo join public."Portal_Users" u on u."PortalUser_ID"=uo."PortalUserOrg_PortalUserID"
    where uo."PortalUserOrg_OrgID"=p_customer_org_id and uo."PortalUserOrg_StatusCode"<>'revoked' and not u."PortalUser_IsDeleted"
  ) select coalesce(jsonb_agg(jsonb_build_object('id',"PortalUser_ID",'displayName',"PortalUser_DisplayName",'email',"PortalUser_Email",'status',"PortalUser_StatusCode",'roleCode',role_code,'facilityIds',facilities.ids,'lastLoginAt',"PortalUser_LastLoginAt") order by "PortalUser_DisplayName"),'[]'::jsonb) from users cross join facilities;
$$;


ALTER FUNCTION "public"."warehouse_edge_portal_users"("p_customer_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."warehouse_edge_portal_users_page"("p_customer_org_id" "uuid", "p_limit" integer DEFAULT 20, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_limit integer := greatest(1, least(coalesce(p_limit, 20), 50));
  v_offset integer := greatest(0, coalesce(p_offset, 0));
  v_result jsonb;
begin
  with facilities as materialized (
    select coalesce(
      jsonb_agg(access."WMSCustomerFacilityAccess_FacilityID" order by access."WMSCustomerFacilityAccess_FacilityID"),
      '[]'::jsonb
    ) as ids
    from public."WMS_CustomerFacilityAccess" access
    where access."WMSCustomerFacilityAccess_CustomerOrgID" = p_customer_org_id
      and access."WMSCustomerFacilityAccess_IsActive"
  ), matching_users as materialized (
    select
      portal_user."PortalUser_ID" as id,
      portal_user."PortalUser_DisplayName" as display_name,
      portal_user."PortalUser_Email" as email,
      portal_user."PortalUser_StatusCode" as status_code,
      portal_user."PortalUser_LastLoginAt" as last_login_at
    from public."Portal_UserOrganisations" user_org
    join public."Portal_Users" portal_user
      on portal_user."PortalUser_ID" = user_org."PortalUserOrg_PortalUserID"
    where user_org."PortalUserOrg_OrgID" = p_customer_org_id
      and user_org."PortalUserOrg_StatusCode" <> 'revoked'
      and not portal_user."PortalUser_IsDeleted"
  ), selected_users as materialized (
    select
      matching.id,
      matching.display_name,
      matching.email,
      matching.status_code,
      matching.last_login_at,
      coalesce((
        select role."PortalRole_Code"
        from public."Portal_UserRoles" user_role
        join public."Portal_Roles" role
          on role."PortalRole_ID" = user_role."PortalUserRole_RoleID"
        where user_role."PortalUserRole_PortalUserID" = matching.id
          and user_role."PortalUserRole_OrgID" = p_customer_org_id
          and user_role."PortalUserRole_StatusCode" = 'active'
        limit 1
      ), 'warehouse_viewer') as role_code
    from matching_users matching
    order by lower(matching.display_name), matching.id
    limit v_limit
    offset v_offset
  ), counts as (
    select count(*)::integer as total from matching_users
  )
  select jsonb_build_object(
    'rows', coalesce(jsonb_agg(jsonb_build_object(
      'id', selected.id,
      'displayName', selected.display_name,
      'email', selected.email,
      'status', selected.status_code,
      'roleCode', selected.role_code,
      'facilityIds', facilities.ids,
      'lastLoginAt', selected.last_login_at
    ) order by lower(selected.display_name), selected.id) filter (where selected.id is not null), '[]'::jsonb),
    'total', coalesce(max(counts.total), 0),
    'limit', v_limit,
    'offset', v_offset
  )
  into v_result
  from facilities
  cross join counts
  left join selected_users selected on true;

  return coalesce(v_result, jsonb_build_object('rows', '[]'::jsonb, 'total', 0, 'limit', v_limit, 'offset', v_offset));
end;
$$;


ALTER FUNCTION "public"."warehouse_edge_portal_users_page"("p_customer_org_id" "uuid", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."warehouse_edge_portal_users_page"("p_customer_org_id" "uuid", "p_limit" integer, "p_offset" integer) IS 'Returns one capped customer portal user page for an Edge-authorised organisation.';



CREATE OR REPLACE FUNCTION "public"."warehouse_edge_purchase_order_mutation"("p_action" "text", "p_purchase_order_id" "uuid", "p_payload" "jsonb", "p_actor_user_id" "uuid", "p_allowed_facility_ids" "uuid"[]) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  v_po public."WMS_PurchaseOrders"%rowtype;
  v_id uuid := coalesce(p_purchase_order_id, gen_random_uuid());
  v_facility_id uuid;
  v_customer_org_id uuid;
  v_supplier_org_id uuid;
  v_lines jsonb;
  v_line jsonb;
  v_item_id uuid;
  v_quantity numeric;
  v_unit_price numeric;
  v_tax_rate numeric;
  v_net numeric;
  v_tax numeric;
  v_total numeric;
  v_net_total numeric := 0;
  v_tax_total numeric := 0;
  v_grand_total numeric := 0;
  v_line_no integer := 0;
  v_office_id uuid;
  v_order_id uuid;
  v_order_number text;
begin
  if p_action not in ('create','update','issue','cancel','create_inbound') then raise exception 'WMS400: Unsupported purchase order action.'; end if;
  if p_action in ('update','issue','cancel','create_inbound') then
    select * into v_po from public."WMS_PurchaseOrders" where "WMSPO_ID"=p_purchase_order_id and not "WMSPO_IsDeleted" for update;
    if not found or not coalesce(v_po."WMSPO_FacilityID"=any(p_allowed_facility_ids),false) then raise exception 'WMS404: Purchase order not found.'; end if;
  end if;

  if p_action in ('create','update') then
    if p_action='update' and (v_po."WMSPO_StatusCode" not in ('draft','issued') or v_po."WMSPO_WarehouseOrderID" is not null) then raise exception 'WMS409: This purchase order can no longer be edited.'; end if;
    v_facility_id := nullif(p_payload->>'facilityId','')::uuid;
    v_customer_org_id := nullif(p_payload->>'customerOrgId','')::uuid;
    v_supplier_org_id := nullif(p_payload->>'supplierOrgId','')::uuid;
    if v_facility_id is null or not coalesce(v_facility_id=any(p_allowed_facility_ids),false) then raise exception 'WMS403: Choose a warehouse in your company.'; end if;
    if v_customer_org_id is null or not exists(select 1 from public."Org_Master" where "Org_id"=v_customer_org_id) then raise exception 'WMS400: Choose the stock owner.'; end if;
    if coalesce(nullif(btrim(p_payload->>'number'),''),'')='' then raise exception 'WMS400: Enter a purchase order number.'; end if;

    if upper(coalesce(nullif(btrim(p_payload->>'currencyCode'),''),'GBP')) !~ '^[A-Z]{3}$' then raise exception 'WMS400: Enter a three-letter currency code.'; end if;
    v_lines := p_payload->'lines';
    if v_lines is null or jsonb_typeof(v_lines) is distinct from 'array' or jsonb_array_length(v_lines)=0 then raise exception 'WMS400: Add at least one purchase order line.'; end if;

    if p_action='create' then
      insert into public."WMS_PurchaseOrders" (
        "WMSPO_ID","WMSPO_FacilityID","WMSPO_CustomerOrgID","WMSPO_SupplierOrgID","WMSPO_Number","WMSPO_StatusCode","WMSPO_SupplierName",
        "WMSPO_BuyerReference","WMSPO_SupplierReference","WMSPO_IssueDate","WMSPO_ExpectedDeliveryDate","WMSPO_CurrencyCode","WMSPO_DeliveryTerms",
        "WMSPO_PaymentTerms","WMSPO_DeliveryAddress","WMSPO_Notes","WMSPO_SourceFileName","WMSPO_ExtractionModeCode","WMSPO_ExtractionModel",
        "WMSPO_ExtractionMetadataJSON","WMSPO_CreatedBy","WMSPO_UpdatedBy"
      ) values (
        v_id,v_facility_id,v_customer_org_id,v_supplier_org_id,left(btrim(p_payload->>'number'),120),'draft',left(coalesce(btrim(p_payload->>'supplierName'),''),240),
        nullif(left(btrim(p_payload->>'buyerReference'),160),''),nullif(left(btrim(p_payload->>'supplierReference'),160),''),nullif(p_payload->>'issueDate','')::date,
        nullif(p_payload->>'expectedDeliveryDate','')::date,upper(coalesce(nullif(btrim(p_payload->>'currencyCode'),''),'GBP')),nullif(left(btrim(p_payload->>'deliveryTerms'),180),''),
        nullif(left(btrim(p_payload->>'paymentTerms'),180),''),nullif(btrim(p_payload->>'deliveryAddress'),''),nullif(btrim(p_payload->>'notes'),''),
        nullif(left(btrim(p_payload->>'sourceFileName'),240),''),nullif(left(btrim(p_payload->>'extractionMode'),40),''),nullif(left(btrim(p_payload->>'extractionModel'),120),''),
        coalesce(p_payload->'extractionMetadata','{}'::jsonb),p_actor_user_id,p_actor_user_id
      );
    else
      v_id := p_purchase_order_id;
      update public."WMS_PurchaseOrders" set
        "WMSPO_FacilityID"=v_facility_id,"WMSPO_CustomerOrgID"=v_customer_org_id,"WMSPO_SupplierOrgID"=v_supplier_org_id,
        "WMSPO_Number"=left(btrim(p_payload->>'number'),120),"WMSPO_SupplierName"=left(coalesce(btrim(p_payload->>'supplierName'),''),240),
        "WMSPO_BuyerReference"=nullif(left(btrim(p_payload->>'buyerReference'),160),''),"WMSPO_SupplierReference"=nullif(left(btrim(p_payload->>'supplierReference'),160),''),
        "WMSPO_IssueDate"=nullif(p_payload->>'issueDate','')::date,"WMSPO_ExpectedDeliveryDate"=nullif(p_payload->>'expectedDeliveryDate','')::date,
        "WMSPO_CurrencyCode"=upper(coalesce(nullif(btrim(p_payload->>'currencyCode'),''),'GBP')),"WMSPO_DeliveryTerms"=nullif(left(btrim(p_payload->>'deliveryTerms'),180),''),
        "WMSPO_PaymentTerms"=nullif(left(btrim(p_payload->>'paymentTerms'),180),''),"WMSPO_DeliveryAddress"=nullif(btrim(p_payload->>'deliveryAddress'),''),
        "WMSPO_Notes"=nullif(btrim(p_payload->>'notes'),''),"WMSPO_SourceFileName"=coalesce(nullif(left(btrim(p_payload->>'sourceFileName'),240),''),"WMSPO_SourceFileName"),
        "WMSPO_ExtractionModeCode"=coalesce(nullif(left(btrim(p_payload->>'extractionMode'),40),''),"WMSPO_ExtractionModeCode"),
        "WMSPO_ExtractionModel"=coalesce(nullif(left(btrim(p_payload->>'extractionModel'),120),''),"WMSPO_ExtractionModel"),
        "WMSPO_ExtractionMetadataJSON"=coalesce(p_payload->'extractionMetadata',"WMSPO_ExtractionMetadataJSON"),
        "WMSPO_Version"="WMSPO_Version"+1,"WMSPO_UpdatedAt"=now(),"WMSPO_UpdatedBy"=p_actor_user_id
      where "WMSPO_ID"=v_id;
      delete from public."WMS_PurchaseOrderLines" where "WMSPOLine_PurchaseOrderID"=v_id;
    end if;

    for v_line in select value from jsonb_array_elements(v_lines) loop
      v_line_no := v_line_no+1;
      v_item_id := nullif(v_line->>'itemId','')::uuid;
      if v_item_id is not null and not exists(select 1 from public."WMS_Items" item
        join public."WMS_ItemFacilityAssignments" assignment
          on assignment."WMSItemFacility_ItemID"=item."WMSItem_ID"
          and assignment."WMSItemFacility_FacilityID"=v_facility_id
          and assignment."WMSItemFacility_IsActive"
        where item."WMSItem_ID"=v_item_id and item."WMSItem_CustomerOrgID"=v_customer_org_id
          and item."WMSItem_IsActive" and not item."WMSItem_IsDeleted") then raise exception 'WMS400: A purchase order line uses an item outside this warehouse or stock owner.'; end if;
      v_quantity := coalesce(nullif(v_line->>'quantity','')::numeric,0);
      v_unit_price := greatest(coalesce(nullif(v_line->>'unitPrice','')::numeric,0),0);
      v_tax_rate := greatest(coalesce(nullif(v_line->>'taxRate','')::numeric,0),0);
      if v_quantity<=0 or coalesce(nullif(btrim(v_line->>'description'),''),'')='' or coalesce(nullif(btrim(v_line->>'uomCode'),''),'')='' then raise exception 'WMS400: Every line needs a description, quantity above zero and unit of measure.'; end if;
      v_net := round(v_quantity*v_unit_price,4); v_tax := round(v_net*v_tax_rate/100,4); v_total := v_net+v_tax;
      v_net_total := v_net_total+v_net; v_tax_total := v_tax_total+v_tax; v_grand_total := v_grand_total+v_total;
      insert into public."WMS_PurchaseOrderLines" (
        "WMSPOLine_PurchaseOrderID","WMSPOLine_LineNo","WMSPOLine_ItemID","WMSPOLine_SKU","WMSPOLine_SupplierItemCode","WMSPOLine_Description",
        "WMSPOLine_OrderedQuantity","WMSPOLine_UOMCode","WMSPOLine_UnitPrice","WMSPOLine_TaxRate","WMSPOLine_NetAmount","WMSPOLine_TaxAmount",
        "WMSPOLine_TotalAmount","WMSPOLine_RequestedDeliveryDate","WMSPOLine_MetadataJSON"
      ) values (
        v_id,v_line_no,v_item_id,nullif(left(btrim(v_line->>'sku'),120),''),nullif(left(btrim(v_line->>'supplierItemCode'),120),''),left(btrim(v_line->>'description'),800),
        v_quantity,upper(coalesce(nullif(btrim(v_line->>'uomCode'),''),'EA')),v_unit_price,v_tax_rate,v_net,v_tax,v_total,
        nullif(v_line->>'requestedDeliveryDate','')::date,coalesce(v_line->'metadata','{}'::jsonb)
      );
    end loop;
    update public."WMS_PurchaseOrders" set "WMSPO_NetAmount"=v_net_total,"WMSPO_TaxAmount"=v_tax_total,"WMSPO_TotalAmount"=v_grand_total where "WMSPO_ID"=v_id;
    insert into public."WMS_PurchaseOrderEvents" ("WMSPOEvent_PurchaseOrderID","WMSPOEvent_EventTypeCode","WMSPOEvent_ToStatusCode","WMSPOEvent_MetadataJSON","WMSPOEvent_CreatedBy")
      values(v_id,case when p_action='create' then 'created' else 'updated' end,coalesce(v_po."WMSPO_StatusCode",'draft'),jsonb_build_object('lineCount',v_line_no,'sourceFileName',p_payload->>'sourceFileName'),p_actor_user_id);
    return v_id;
  end if;

  if p_action='issue' then
    if v_po."WMSPO_StatusCode"<>'draft' then raise exception 'WMS409: Only a draft purchase order can be issued.'; end if;
    if exists(select 1 from public."WMS_PurchaseOrderLines" where "WMSPOLine_PurchaseOrderID"=v_po."WMSPO_ID" and "WMSPOLine_ItemID" is null) then raise exception 'WMS409: Match every line to a warehouse item before issuing.'; end if;
    update public."WMS_PurchaseOrders" set "WMSPO_StatusCode"='issued',"WMSPO_Version"="WMSPO_Version"+1,"WMSPO_UpdatedAt"=now(),"WMSPO_UpdatedBy"=p_actor_user_id where "WMSPO_ID"=v_po."WMSPO_ID";
    insert into public."WMS_PurchaseOrderEvents" ("WMSPOEvent_PurchaseOrderID","WMSPOEvent_EventTypeCode","WMSPOEvent_FromStatusCode","WMSPOEvent_ToStatusCode","WMSPOEvent_Notes","WMSPOEvent_CreatedBy") values(v_po."WMSPO_ID",'issued',v_po."WMSPO_StatusCode",'issued',nullif(btrim(p_payload->>'notes'),''),p_actor_user_id);
    return v_po."WMSPO_ID";
  end if;

  if p_action='cancel' then
    if v_po."WMSPO_StatusCode" in ('received','cancelled') or v_po."WMSPO_WarehouseOrderID" is not null then raise exception 'WMS409: This purchase order cannot be cancelled.'; end if;
    update public."WMS_PurchaseOrders" set "WMSPO_StatusCode"='cancelled',"WMSPO_Version"="WMSPO_Version"+1,"WMSPO_UpdatedAt"=now(),"WMSPO_UpdatedBy"=p_actor_user_id where "WMSPO_ID"=v_po."WMSPO_ID";
    insert into public."WMS_PurchaseOrderEvents" ("WMSPOEvent_PurchaseOrderID","WMSPOEvent_EventTypeCode","WMSPOEvent_FromStatusCode","WMSPOEvent_ToStatusCode","WMSPOEvent_Notes","WMSPOEvent_CreatedBy") values(v_po."WMSPO_ID",'cancelled',v_po."WMSPO_StatusCode",'cancelled',nullif(btrim(p_payload->>'notes'),''),p_actor_user_id);
    return v_po."WMSPO_ID";
  end if;

  if v_po."WMSPO_StatusCode"<>'issued' or v_po."WMSPO_WarehouseOrderID" is not null then raise exception 'WMS409: This purchase order is not ready for a new goods-in order.'; end if;
  if exists(select 1 from public."WMS_PurchaseOrderLines" where "WMSPOLine_PurchaseOrderID"=v_po."WMSPO_ID" and "WMSPOLine_ItemID" is null) then raise exception 'WMS409: Match every line to a warehouse item before creating goods-in work.'; end if;
  select "WMSFacility_OrgOfficeID" into v_office_id from public."WMS_Facilities" where "WMSFacility_ID"=v_po."WMSPO_FacilityID";
  v_order_id := gen_random_uuid(); v_order_number := left('PO-'||v_po."WMSPO_Number",80);
  if exists(select 1 from public."WMS_Orders" where "WMSOrder_FacilityID"=v_po."WMSPO_FacilityID" and lower("WMSOrder_OrderNumber")=lower(v_order_number) and not "WMSOrder_IsDeleted") then v_order_number:=left(v_order_number||'-'||substr(v_order_id::text,1,6),80); end if;
  insert into public."WMS_Orders" ("WMSOrder_ID","WMSOrder_FacilityID","WMSOrder_OrgOfficeID","WMSOrder_CustomerOrgID","WMSOrder_OrderNumber","WMSOrder_TypeCode","WMSOrder_StatusCode","WMSOrder_CustomerReference","WMSOrder_SupplierReference","WMSOrder_InboundFromOrgID","WMSOrder_RequestedDate","WMSOrder_Instructions","WMSOrder_MetadataJSON","WMSOrder_CreatedBy","WMSOrder_UpdatedBy")
    values(v_order_id,v_po."WMSPO_FacilityID",v_office_id,v_po."WMSPO_CustomerOrgID",v_order_number,'inbound','draft',v_po."WMSPO_BuyerReference",v_po."WMSPO_SupplierReference",v_po."WMSPO_SupplierOrgID",v_po."WMSPO_ExpectedDeliveryDate",v_po."WMSPO_Notes",jsonb_build_object('purchaseOrderId',v_po."WMSPO_ID",'purchaseOrderNumber',v_po."WMSPO_Number"),p_actor_user_id,p_actor_user_id);
  insert into public."WMS_OrderLines" ("WMSOrderLine_OrderID","WMSOrderLine_LineNo","WMSOrderLine_ItemID","WMSOrderLine_OrderedQuantity","WMSOrderLine_UOMCode","WMSOrderLine_GoodsValue","WMSOrderLine_CurrencyCode","WMSOrderLine_Instructions","WMSOrderLine_MetadataJSON")
    select v_order_id,"WMSPOLine_LineNo","WMSPOLine_ItemID","WMSPOLine_OrderedQuantity","WMSPOLine_UOMCode","WMSPOLine_NetAmount",v_po."WMSPO_CurrencyCode","WMSPOLine_Description",jsonb_build_object('purchaseOrderLineId',"WMSPOLine_ID") from public."WMS_PurchaseOrderLines" where "WMSPOLine_PurchaseOrderID"=v_po."WMSPO_ID" order by "WMSPOLine_LineNo";
  update public."WMS_PurchaseOrders" set "WMSPO_WarehouseOrderID"=v_order_id,"WMSPO_Version"="WMSPO_Version"+1,"WMSPO_UpdatedAt"=now(),"WMSPO_UpdatedBy"=p_actor_user_id where "WMSPO_ID"=v_po."WMSPO_ID";
  insert into public."WMS_PurchaseOrderEvents" ("WMSPOEvent_PurchaseOrderID","WMSPOEvent_EventTypeCode","WMSPOEvent_ToStatusCode","WMSPOEvent_MetadataJSON","WMSPOEvent_CreatedBy") values(v_po."WMSPO_ID",'goods_in_created','issued',jsonb_build_object('warehouseOrderId',v_order_id,'warehouseOrderNumber',v_order_number),p_actor_user_id);
  return v_po."WMSPO_ID";
exception when others then
  if sqlerrm like 'WMS%' then raise; end if;
  if sqlstate='23505' then raise exception 'WMS409: A purchase order with this number already exists in the warehouse.'; end if;
  raise exception 'WMS500: %',sqlerrm;
end; $_$;


ALTER FUNCTION "public"."warehouse_edge_purchase_order_mutation"("p_action" "text", "p_purchase_order_id" "uuid", "p_payload" "jsonb", "p_actor_user_id" "uuid", "p_allowed_facility_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."warehouse_edge_purchase_orders_page"("p_allowed_facility_ids" "uuid"[], "p_facility_id" "uuid" DEFAULT NULL::"uuid", "p_status" "text" DEFAULT NULL::"text", "p_open_only" boolean DEFAULT false, "p_search" "text" DEFAULT NULL::"text", "p_sort" "text" DEFAULT NULL::"text", "p_direction" "text" DEFAULT 'desc'::"text", "p_limit" integer DEFAULT 20, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_limit integer := greatest(1, least(coalesce(p_limit, 20), 50));
  v_offset integer := greatest(0, coalesce(p_offset, 0));
  v_search text := lower(nullif(btrim(p_search), ''));
  v_status text := nullif(btrim(p_status), '');
  v_direction text := case when lower(p_direction) = 'asc' then 'asc' else 'desc' end;
  v_result jsonb;
begin
  if coalesce(cardinality(p_allowed_facility_ids), 0) = 0 then
    return jsonb_build_object('rows', '[]'::jsonb, 'total', 0, 'limit', v_limit, 'offset', v_offset, 'facets', '[]'::jsonb);
  end if;

  with base as materialized (
    select
      purchase_order.*,
      facility."WMSFacility_Code" as facility_code,
      facility."WMSFacility_Name" as facility_name,
      organisation."Org_Name" as customer_name,
      coalesce(line_totals.line_count, 0)::integer as line_count
    from public."WMS_PurchaseOrders" purchase_order
    join public."WMS_Facilities" facility on facility."WMSFacility_ID" = purchase_order."WMSPO_FacilityID"
    join public."Org_Master" organisation on organisation."Org_id" = purchase_order."WMSPO_CustomerOrgID"
    left join lateral (
      select count(*) as line_count
      from public."WMS_PurchaseOrderLines" line
      where line."WMSPOLine_PurchaseOrderID" = purchase_order."WMSPO_ID"
    ) line_totals on true
    where purchase_order."WMSPO_FacilityID" = any(p_allowed_facility_ids)
      and (p_facility_id is null or purchase_order."WMSPO_FacilityID" = p_facility_id)
      and not purchase_order."WMSPO_IsDeleted"
      and (not p_open_only or purchase_order."WMSPO_StatusCode" not in ('received', 'cancelled'))
      and (v_search is null or strpos(lower(concat_ws(' ',
        purchase_order."WMSPO_Number", purchase_order."WMSPO_SupplierName",
        purchase_order."WMSPO_BuyerReference", purchase_order."WMSPO_SupplierReference"
      )), v_search) > 0)
  ), filtered as materialized (
    select * from base where v_status is null or "WMSPO_StatusCode" = v_status
  ), ranked as (
    select *, row_number() over (
      order by
        case when v_direction = 'asc' then case p_sort
          when 'number' then lower("WMSPO_Number")
          when 'supplier' then lower("WMSPO_SupplierName")
          when 'warehouse' then lower(facility_name)
          when 'status' then lower("WMSPO_StatusCode")
        end end asc nulls last,
        case when v_direction = 'desc' then case p_sort
          when 'number' then lower("WMSPO_Number")
          when 'supplier' then lower("WMSPO_SupplierName")
          when 'warehouse' then lower(facility_name)
          when 'status' then lower("WMSPO_StatusCode")
        end end desc nulls last,
        case when v_direction = 'asc' and p_sort = 'delivery' then "WMSPO_ExpectedDeliveryDate" end asc nulls last,
        case when v_direction = 'desc' and p_sort = 'delivery' then "WMSPO_ExpectedDeliveryDate" end desc nulls last,
        case when v_direction = 'asc' and p_sort = 'lines' then line_count end asc nulls last,
        case when v_direction = 'desc' and p_sort = 'lines' then line_count end desc nulls last,
        case when v_direction = 'asc' and p_sort = 'total' then "WMSPO_TotalAmount" end asc nulls last,
        case when v_direction = 'desc' and p_sort = 'total' then "WMSPO_TotalAmount" end desc nulls last,
        case when p_sort is null and v_direction = 'asc' then "WMSPO_UpdatedAt" end asc,
        case when p_sort is null and v_direction = 'desc' then "WMSPO_UpdatedAt" end desc,
        "WMSPO_ID"
    ) as ordinal
    from filtered
  ), page as (
    select * from ranked where ordinal > v_offset and ordinal <= v_offset + v_limit
  )
  select jsonb_build_object(
    'rows', coalesce((select jsonb_agg(jsonb_build_object(
      'id', row."WMSPO_ID", 'facilityId', row."WMSPO_FacilityID", 'facilityCode', row.facility_code,
      'facilityName', row.facility_name, 'customerOrgId', row."WMSPO_CustomerOrgID", 'customerName', row.customer_name,
      'supplierOrgId', row."WMSPO_SupplierOrgID", 'supplierName', row."WMSPO_SupplierName",
      'warehouseOrderId', row."WMSPO_WarehouseOrderID", 'number', row."WMSPO_Number",
      'statusCode', row."WMSPO_StatusCode", 'buyerReference', row."WMSPO_BuyerReference",
      'supplierReference', row."WMSPO_SupplierReference", 'issueDate', row."WMSPO_IssueDate",
      'expectedDeliveryDate', row."WMSPO_ExpectedDeliveryDate", 'currencyCode', row."WMSPO_CurrencyCode",
      'deliveryTerms', row."WMSPO_DeliveryTerms", 'paymentTerms', row."WMSPO_PaymentTerms",
      'deliveryAddress', row."WMSPO_DeliveryAddress", 'notes', row."WMSPO_Notes",
      'netAmount', row."WMSPO_NetAmount", 'taxAmount', row."WMSPO_TaxAmount", 'totalAmount', row."WMSPO_TotalAmount",
      'sourceFileName', row."WMSPO_SourceFileName", 'extractionMode', row."WMSPO_ExtractionModeCode",
      'extractionModel', row."WMSPO_ExtractionModel", 'extractionMetadata', row."WMSPO_ExtractionMetadataJSON",
      'version', row."WMSPO_Version", 'lineCount', row.line_count,
      'createdAt', row."WMSPO_CreatedAt", 'updatedAt', row."WMSPO_UpdatedAt",
      'lines', '[]'::jsonb, 'events', '[]'::jsonb
    ) order by row.ordinal) from page row), '[]'::jsonb),
    'total', (select count(*) from filtered), 'limit', v_limit, 'offset', v_offset,
    'facets', coalesce((select jsonb_agg(value order by value) from (
      select distinct "WMSPO_StatusCode" as value from base
    ) facet_values where value is not null), '[]'::jsonb)
  ) into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."warehouse_edge_purchase_orders_page"("p_allowed_facility_ids" "uuid"[], "p_facility_id" "uuid", "p_status" "text", "p_open_only" boolean, "p_search" "text", "p_sort" "text", "p_direction" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."warehouse_edge_purchase_orders_page"("p_allowed_facility_ids" "uuid"[], "p_facility_id" "uuid", "p_status" "text", "p_open_only" boolean, "p_search" "text", "p_sort" "text", "p_direction" "text", "p_limit" integer, "p_offset" integer) IS 'Service-role-only, allowlist-scoped Warehouse purchase-order register page capped at 50 rows.';



CREATE OR REPLACE FUNCTION "public"."warehouse_edge_receive_mutation"("p_order_id" "uuid", "p_payload" "jsonb", "p_actor_user_id" "uuid", "p_allowed_facility_ids" "uuid"[], "p_allowed_organisation_ids" "uuid"[]) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_order public."WMS_Orders"%rowtype;
  v_line public."WMS_OrderLines"%rowtype;
  v_balance public."WMS_InventoryBalances"%rowtype;
  v_hu public."WMS_HandlingUnits"%rowtype;
  v_input jsonb;
  v_request_id uuid:=nullif(p_payload->>'requestId','')::uuid;
  v_receipt_id uuid;
  v_hu_id uuid:=nullif(p_payload->>'handlingUnitId','')::uuid;
  v_balance_id uuid;
  v_lot_id uuid;
  v_location_id uuid;
  v_transaction_id uuid;
  v_primary_transaction_id uuid;
  v_now timestamptz:=now();
  v_number text;
  v_hu_code text;
  v_status text;
  v_quantity numeric;
  v_damaged numeric;
  v_missing numeric;
  v_part numeric;
  v_before numeric;
  v_index integer:=0;
  v_complete boolean;
begin
  if p_actor_user_id is null then raise exception 'WMS403: Goods receipt is reserved for the warehouse team.'; end if;
  if v_request_id is null then raise exception 'WMS400: A request identifier is required.'; end if;
  if exists(select 1 from public."WMS_Receipts" where "WMSReceipt_OrderID"=p_order_id and "WMSReceipt_MetadataJSON"->>'requestId'=v_request_id::text) then return p_order_id; end if;
  select * into v_order from public."WMS_Orders" where "WMSOrder_ID"=p_order_id and not "WMSOrder_IsDeleted" and "WMSOrder_FacilityID"=any(p_allowed_facility_ids) and "WMSOrder_CustomerOrgID"=any(p_allowed_organisation_ids) for update;
  if not found then raise exception 'WMS404: This warehouse order does not exist in your workspace.'; end if;
  if v_order."WMSOrder_TypeCode"<>'inbound' or v_order."WMSOrder_StatusCode" in ('complete','cancelled') then raise exception 'WMS409: This inbound order cannot be received.'; end if;
  if jsonb_typeof(p_payload->'lines')<>'array' or jsonb_array_length(p_payload->'lines')=0 then raise exception 'WMS400: Add at least one receipt line.'; end if;

  if v_hu_id is null and jsonb_typeof(p_payload->'newHandlingUnit')='object' then
    if not exists(select 1 from jsonb_array_elements(p_payload->'lines') line where coalesce(nullif(line->>'quantity','')::numeric,0)>0) then raise exception 'WMS400: A new pallet or warehouse object must contain received stock.'; end if;
    if not exists(select 1 from public."sys_WMSHandlingUnitTypes" where "WMSHUType_Code"=lower(btrim(p_payload->'newHandlingUnit'->>'typeCode')) and "WMSHUType_IsActive") then raise exception 'WMS400: Choose a valid pallet or warehouse object type.'; end if;
    v_hu_id:=gen_random_uuid();
    v_hu_code:=upper(coalesce(nullif(btrim(p_payload->'newHandlingUnit'->>'code'),''),'HU-'||to_char(v_now,'YYYYMMDD-HH24MISS')||'-'||lpad((floor(random()*9000)+1000)::int::text,4,'0')));
    insert into public."WMS_HandlingUnits" ("WMSHU_ID","WMSHU_FacilityID","WMSHU_TypeCode","WMSHU_Code","WMSHU_SSCC","WMSHU_ExternalReference","WMSHU_CustomerOrgID","WMSHU_InventoryStatusCode","WMSHU_CustomsStatusCode","WMSHU_LifecycleStatusCode","WMSHU_CreatedAt","WMSHU_CreatedBy","WMSHU_UpdatedAt","WMSHU_IsDeleted")
    values(v_hu_id,v_order."WMSOrder_FacilityID",lower(btrim(p_payload->'newHandlingUnit'->>'typeCode')),v_hu_code,nullif(btrim(p_payload->'newHandlingUnit'->>'sscc'),''),nullif(btrim(p_payload->'newHandlingUnit'->>'externalReference'),''),v_order."WMSOrder_CustomerOrgID",'available','free_circulation','open',v_now,p_actor_user_id,v_now,false);
    insert into public."WMS_HandlingUnitEvents" ("WMSHUEvent_ID","WMSHUEvent_HU_ID","WMSHUEvent_EventTypeCode","WMSHUEvent_EventAt","WMSHUEvent_Notes","WMSHUEvent_MetadataJSON","WMSHUEvent_CreatedBy") values(gen_random_uuid(),v_hu_id,'created',v_now,'Created during goods receipt.',jsonb_build_object('orderId',p_order_id,'requestId',v_request_id),p_actor_user_id);
  elsif v_hu_id is not null then
    select * into v_hu from public."WMS_HandlingUnits" where "WMSHU_ID"=v_hu_id and "WMSHU_FacilityID"=v_order."WMSOrder_FacilityID" and not "WMSHU_IsDeleted" and "WMSHU_LifecycleStatusCode"='open' for update;
    if not found or (v_hu."WMSHU_CustomerOrgID" is not null and v_hu."WMSHU_CustomerOrgID" is distinct from v_order."WMSOrder_CustomerOrgID") then raise exception 'WMS409: The selected pallet is not compatible with this receipt.'; end if;
  end if;

  v_receipt_id:=gen_random_uuid();
  v_number:='GRN-'||to_char(v_now,'YYYYMMDD-HH24MISS')||'-'||lpad((floor(random()*9000)+1000)::int::text,4,'0');
  insert into public."WMS_Receipts" ("WMSReceipt_ID","WMSReceipt_FacilityID","WMSReceipt_OrderID","WMSReceipt_JobID","WMSReceipt_ReceiptNumber","WMSReceipt_StatusCode","WMSReceipt_ReceivingLocationID","WMSReceipt_ReceivedAt","WMSReceipt_ReceivedBy","WMSReceipt_HasDiscrepancy","WMSReceipt_Notes","WMSReceipt_MetadataJSON","WMSReceipt_CreatedAt","WMSReceipt_CreatedBy")
  values(v_receipt_id,v_order."WMSOrder_FacilityID",p_order_id,v_order."WMSOrder_JobID",v_number,'complete',nullif(p_payload->>'receivingLocationId','')::uuid,v_now,p_actor_user_id,false,nullif(btrim(p_payload->>'notes'),''),jsonb_build_object('requestId',v_request_id,'handlingUnitId',v_hu_id),v_now,p_actor_user_id);

  for v_input in select value from jsonb_array_elements(p_payload->'lines') loop
    v_index:=v_index+1; v_primary_transaction_id:=null;
    select * into v_line from public."WMS_OrderLines" where "WMSOrderLine_ID"=(v_input->>'orderLineId')::uuid and "WMSOrderLine_OrderID"=p_order_id for update;
    if not found then raise exception 'WMS400: A received line does not belong to this order.'; end if;
    v_quantity:=coalesce(nullif(v_input->>'quantity','')::numeric,0);
    v_damaged:=coalesce(nullif(v_input->>'damagedQuantity','')::numeric,0);
    v_missing:=coalesce(nullif(v_input->>'missingQuantity','')::numeric,0);
    if v_quantity<0 or v_damaged<0 or v_missing<0 or v_damaged>v_quantity or v_quantity+v_missing<=0 or v_quantity+v_missing>v_line."WMSOrderLine_OrderedQuantity"-v_line."WMSOrderLine_ReceivedQuantity" then raise exception 'WMS400: Check the received, damaged, and missing quantities.'; end if;
    if v_quantity>0 then perform public._warehouse_edge_validate_quantity(v_line."WMSOrderLine_ItemID",v_quantity); end if;
    if v_damaged>0 then perform public._warehouse_edge_validate_quantity(v_line."WMSOrderLine_ItemID",v_damaged); end if;
    if v_missing>0 then perform public._warehouse_edge_validate_quantity(v_line."WMSOrderLine_ItemID",v_missing); end if;
    v_location_id:=coalesce(nullif(v_input->>'targetLocationId','')::uuid,v_line."WMSOrderLine_TargetLocationID",nullif(p_payload->>'receivingLocationId','')::uuid);
    if v_quantity>0 and (v_location_id is null or not exists(select 1 from public."WMS_Locations" where "WMSLocation_ID"=v_location_id and "WMSLocation_FacilityID"=v_order."WMSOrder_FacilityID" and "WMSLocation_IsActive" and not "WMSLocation_IsDeleted")) then raise exception 'WMS400: Choose an active receiving location.'; end if;
    if v_hu_id is not null and v_location_id is not null then update public."WMS_HandlingUnits" set "WMSHU_LocationID"=v_location_id,"WMSHU_CustomerOrgID"=coalesce("WMSHU_CustomerOrgID",v_order."WMSOrder_CustomerOrgID"),"WMSHU_UpdatedAt"=v_now,"WMSHU_Version"="WMSHU_Version"+1 where "WMSHU_ID"=v_hu_id; end if;
    v_lot_id:=null;
    if coalesce(nullif(btrim(v_input->>'lotNumber'),''),nullif(btrim(v_input->>'batchNumber'),''),v_line."WMSOrderLine_LotNumber") is not null then
      select "WMSLot_ID" into v_lot_id from public."WMS_InventoryLots" where "WMSLot_FacilityID"=v_order."WMSOrder_FacilityID" and "WMSLot_ItemID"=v_line."WMSOrderLine_ItemID" and "WMSLot_LotNumber"=coalesce(nullif(btrim(v_input->>'lotNumber'),''),v_line."WMSOrderLine_LotNumber",nullif(btrim(v_input->>'batchNumber'),'')) limit 1;
      if v_lot_id is null then
        v_lot_id:=gen_random_uuid();
        insert into public."WMS_InventoryLots" ("WMSLot_ID","WMSLot_FacilityID","WMSLot_CustomerOrgID","WMSLot_ItemID","WMSLot_LotNumber","WMSLot_BatchNumber","WMSLot_ManufactureDate","WMSLot_ExpiryDate","WMSLot_CustomsStatusCode","WMSLot_AttributesJSON","WMSLot_CreatedAt") values(v_lot_id,v_order."WMSOrder_FacilityID",v_order."WMSOrder_CustomerOrgID",v_line."WMSOrderLine_ItemID",coalesce(nullif(btrim(v_input->>'lotNumber'),''),v_line."WMSOrderLine_LotNumber",btrim(v_input->>'batchNumber')),coalesce(nullif(btrim(v_input->>'batchNumber'),''),nullif(btrim(v_input->>'lotNumber'),'')),nullif(v_input->>'manufactureDate','')::date,coalesce(nullif(v_input->>'expiryDate','')::date,v_line."WMSOrderLine_ExpiryDate"),v_line."WMSOrderLine_CustomsStatusCode",'{}',v_now);
      end if;
    end if;
    foreach v_status in array array['available','damaged'] loop
      v_part:=case when v_status='available' then v_quantity-v_damaged else v_damaged end;
      if v_part<=0 then continue; end if;
      select * into v_balance from public."WMS_InventoryBalances" where "WMSBalance_FacilityID"=v_order."WMSOrder_FacilityID" and "WMSBalance_CustomerOrgID"=v_order."WMSOrder_CustomerOrgID" and "WMSBalance_ItemID"=v_line."WMSOrderLine_ItemID" and "WMSBalance_LocationID"=v_location_id and "WMSBalance_LotID" is not distinct from v_lot_id and "WMSBalance_HU_ID" is not distinct from v_hu_id and "WMSBalance_InventoryStatusCode"=v_status and "WMSBalance_CustomsStatusCode"=v_line."WMSOrderLine_CustomsStatusCode" and "WMSBalance_UOMCode"=v_line."WMSOrderLine_UOMCode" for update;
      if not found then
        v_balance_id:=gen_random_uuid(); v_before:=0;
        insert into public."WMS_InventoryBalances" ("WMSBalance_ID","WMSBalance_FacilityID","WMSBalance_CustomerOrgID","WMSBalance_ItemID","WMSBalance_LocationID","WMSBalance_LotID","WMSBalance_HU_ID","WMSBalance_InventoryStatusCode","WMSBalance_CustomsStatusCode","WMSBalance_UOMCode","WMSBalance_OnHandQuantity","WMSBalance_ReservedQuantity","WMSBalance_AllocatedQuantity","WMSBalance_HeldQuantity","WMSBalance_AvailableQuantity","WMSBalance_FirstReceiptAt","WMSBalance_LastMovementAt","WMSBalance_IsBonded","WMSBalance_MetadataJSON","WMSBalance_CreatedAt","WMSBalance_UpdatedAt") values(v_balance_id,v_order."WMSOrder_FacilityID",v_order."WMSOrder_CustomerOrgID",v_line."WMSOrderLine_ItemID",v_location_id,v_lot_id,v_hu_id,v_status,v_line."WMSOrderLine_CustomsStatusCode",v_line."WMSOrderLine_UOMCode",v_part,0,0,case when v_status='damaged' then v_part else 0 end,case when v_status='available' then v_part else 0 end,v_now,v_now,v_line."WMSOrderLine_CustomsStatusCode"<>'free_circulation','{}',v_now,v_now);
      else
        v_balance_id:=v_balance."WMSBalance_ID"; v_before:=v_balance."WMSBalance_OnHandQuantity";
        update public."WMS_InventoryBalances" set "WMSBalance_OnHandQuantity"="WMSBalance_OnHandQuantity"+v_part,"WMSBalance_HeldQuantity"="WMSBalance_HeldQuantity"+case when v_status='damaged' then v_part else 0 end,"WMSBalance_AvailableQuantity"="WMSBalance_AvailableQuantity"+case when v_status='available' then v_part else 0 end,"WMSBalance_LastMovementAt"=v_now,"WMSBalance_UpdatedAt"=v_now where "WMSBalance_ID"=v_balance_id;
      end if;
      v_transaction_id:=gen_random_uuid(); v_primary_transaction_id:=coalesce(v_primary_transaction_id,v_transaction_id);
      insert into public."WMS_InventoryTransactions" ("WMSTransaction_ID","WMSTransaction_FacilityID","WMSTransaction_BalanceID","WMSTransaction_TypeCode","WMSTransaction_ItemID","WMSTransaction_CustomerOrgID","WMSTransaction_ToLocationID","WMSTransaction_LotID","WMSTransaction_HU_ID","WMSTransaction_Quantity","WMSTransaction_UOMCode","WMSTransaction_BeforeOnHandQuantity","WMSTransaction_AfterOnHandQuantity","WMSTransaction_InventoryStatusCode","WMSTransaction_CustomsStatusCode","WMSTransaction_OrderID","WMSTransaction_OrderLineID","WMSTransaction_ReceiptID","WMSTransaction_SourceTable","WMSTransaction_SourceID","WMSTransaction_Reference","WMSTransaction_Notes","WMSTransaction_MetadataJSON","WMSTransaction_MovementGroupID","WMSTransaction_ReasonCode","WMSTransaction_IdempotencyKey","WMSTransaction_CreatedAt","WMSTransaction_CreatedBy") values(v_transaction_id,v_order."WMSOrder_FacilityID",v_balance_id,'receipt',v_line."WMSOrderLine_ItemID",v_order."WMSOrder_CustomerOrgID",v_location_id,v_lot_id,v_hu_id,v_part,v_line."WMSOrderLine_UOMCode",v_before,v_before+v_part,v_status,v_line."WMSOrderLine_CustomsStatusCode",p_order_id,v_line."WMSOrderLine_ID",v_receipt_id,'WMS_Receipts',v_receipt_id,v_number,nullif(btrim(p_payload->>'notes'),''),jsonb_build_object('handlingUnitId',v_hu_id),v_request_id,case when v_status='damaged' then 'damaged_on_receipt' else 'goods_receipt' end,v_request_id,v_now,p_actor_user_id);
    end loop;
    insert into public."WMS_ReceiptLines" ("WMSReceiptLine_ID","WMSReceiptLine_ReceiptID","WMSReceiptLine_OrderLineID","WMSReceiptLine_ItemID","WMSReceiptLine_HU_ID","WMSReceiptLine_LineNo","WMSReceiptLine_ExpectedQuantity","WMSReceiptLine_ReceivedQuantity","WMSReceiptLine_DamagedQuantity","WMSReceiptLine_OverQuantity","WMSReceiptLine_ShortQuantity","WMSReceiptLine_UOMCode","WMSReceiptLine_LotNumber","WMSReceiptLine_ExpiryDate","WMSReceiptLine_TargetLocationID","WMSReceiptLine_InventoryTransactionID","WMSReceiptLine_CustomsStatusCode","WMSReceiptLine_CreatedAt") values(gen_random_uuid(),v_receipt_id,v_line."WMSOrderLine_ID",v_line."WMSOrderLine_ItemID",v_hu_id,v_index,v_line."WMSOrderLine_OrderedQuantity"-v_line."WMSOrderLine_ReceivedQuantity",v_quantity,v_damaged,0,v_missing,v_line."WMSOrderLine_UOMCode",(select "WMSLot_LotNumber" from public."WMS_InventoryLots" where "WMSLot_ID"=v_lot_id),coalesce(nullif(v_input->>'expiryDate','')::date,v_line."WMSOrderLine_ExpiryDate"),v_location_id,v_primary_transaction_id,v_line."WMSOrderLine_CustomsStatusCode",v_now);
    if v_damaged>0 or v_missing>0 then update public."WMS_Receipts" set "WMSReceipt_HasDiscrepancy"=true where "WMSReceipt_ID"=v_receipt_id; end if;
    if v_missing>0 then insert into public."WMS_Exceptions" ("WMSException_ID","WMSException_FacilityID","WMSException_TypeCode","WMSException_StatusCode","WMSException_SeverityCode","WMSException_OrderID","WMSException_OrderLineID","WMSException_ReceiptID","WMSException_Title","WMSException_Description","WMSException_RaisedAt","WMSException_RaisedBy","WMSException_MetadataJSON","WMSException_ActualLocationID","WMSException_MovementGroupID") values(gen_random_uuid(),v_order."WMSOrder_FacilityID",'stock_shortage','open','high',p_order_id,v_line."WMSOrderLine_ID",v_receipt_id,'Inbound stock received short','Expected quantity was not physically received.',v_now,p_actor_user_id,jsonb_build_object('missingQuantity',v_missing,'uomCode',v_line."WMSOrderLine_UOMCode",'requestId',v_request_id),v_location_id,v_request_id); end if;
    update public."WMS_OrderLines" set "WMSOrderLine_ReceivedQuantity"="WMSOrderLine_ReceivedQuantity"+v_quantity,"WMSOrderLine_StatusCode"=case when v_missing>0 and "WMSOrderLine_ReceivedQuantity"+v_quantity+v_missing >= "WMSOrderLine_OrderedQuantity" then 'short' when "WMSOrderLine_ReceivedQuantity"+v_quantity >= "WMSOrderLine_OrderedQuantity" then 'received' else 'open' end,"WMSOrderLine_MetadataJSON"="WMSOrderLine_MetadataJSON"||case when v_missing>0 then jsonb_build_object('confirmedMissingQuantity',coalesce(("WMSOrderLine_MetadataJSON"->>'confirmedMissingQuantity')::numeric,0)+v_missing) else '{}'::jsonb end where "WMSOrderLine_ID"=v_line."WMSOrderLine_ID";
  end loop;
  if v_hu_id is not null then perform public._warehouse_edge_sync_hu_contents(v_hu_id); insert into public."WMS_HandlingUnitEvents" ("WMSHUEvent_ID","WMSHUEvent_HU_ID","WMSHUEvent_EventTypeCode","WMSHUEvent_EventAt","WMSHUEvent_LocationID","WMSHUEvent_OrderID","WMSHUEvent_Notes","WMSHUEvent_MetadataJSON","WMSHUEvent_CreatedBy") values(gen_random_uuid(),v_hu_id,'received',v_now,(select "WMSHU_LocationID" from public."WMS_HandlingUnits" where "WMSHU_ID"=v_hu_id),p_order_id,nullif(btrim(p_payload->>'notes'),''),jsonb_build_object('receiptId',v_receipt_id,'requestId',v_request_id),p_actor_user_id); end if;
  select bool_and("WMSOrderLine_StatusCode" in ('received','short','cancelled')) into v_complete from public."WMS_OrderLines" where "WMSOrderLine_OrderID"=p_order_id;
  update public."WMS_Orders" set "WMSOrder_StatusCode"=case when v_complete then 'complete' else 'part_complete' end,"WMSOrder_UpdatedAt"=v_now,"WMSOrder_UpdatedBy"=p_actor_user_id where "WMSOrder_ID"=p_order_id;
  return p_order_id;
exception when others then if sqlerrm like 'WMS%' then raise; end if; raise exception 'WMS500: %',sqlerrm;
end; $$;


ALTER FUNCTION "public"."warehouse_edge_receive_mutation"("p_order_id" "uuid", "p_payload" "jsonb", "p_actor_user_id" "uuid", "p_allowed_facility_ids" "uuid"[], "p_allowed_organisation_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."warehouse_edge_release_order_mutation"("p_order_id" "uuid", "p_payload" "jsonb", "p_actor_user_id" "uuid", "p_allowed_facility_ids" "uuid"[], "p_allowed_organisation_ids" "uuid"[]) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_order public."WMS_Orders"%rowtype; v_line public."WMS_OrderLines"%rowtype; v_balance public."WMS_InventoryBalances"%rowtype;
  v_request_id uuid:=nullif(p_payload->>'requestId','')::uuid; v_needed numeric; v_balance_take numeric; v_conversion jsonb; v_base_uom text; v_take numeric; v_task_id uuid; v_now timestamptz:=now();
begin
  if p_actor_user_id is null then raise exception 'WMS403: Outbound release is reserved for the warehouse team.'; end if;
  if v_request_id is null then raise exception 'WMS400: A request identifier is required.'; end if;
  select * into v_order from public."WMS_Orders" where "WMSOrder_ID"=p_order_id and "WMSOrder_FacilityID"=any(coalesce(p_allowed_facility_ids,'{}'::uuid[])) and "WMSOrder_CustomerOrgID"=any(coalesce(p_allowed_organisation_ids,'{}'::uuid[])) and not "WMSOrder_IsDeleted" for update;
  if not found then raise exception 'WMS404: This warehouse order does not exist in your workspace.'; end if;
  if v_order."WMSOrder_TypeCode"<>'outbound' or v_order."WMSOrder_StatusCode" in ('complete','cancelled') then raise exception 'WMS409: This outbound order cannot be released.'; end if;
  if coalesce(v_order."WMSOrder_MetadataJSON"->'releaseRequestIds','[]'::jsonb) ? v_request_id::text then return p_order_id; end if;
  for v_line in select * from public."WMS_OrderLines" where "WMSOrderLine_OrderID"=p_order_id and "WMSOrderLine_StatusCode"<>'cancelled' order by "WMSOrderLine_LineNo" for update loop
    v_needed:=v_line."WMSOrderLine_OrderedQuantity"-v_line."WMSOrderLine_AllocatedQuantity";
    if v_needed<=0 then continue; end if;
    for v_balance in select * from public."WMS_InventoryBalances" where "WMSBalance_FacilityID"=v_order."WMSOrder_FacilityID" and "WMSBalance_CustomerOrgID"=v_order."WMSOrder_CustomerOrgID" and "WMSBalance_ItemID"=v_line."WMSOrderLine_ItemID" and "WMSBalance_InventoryStatusCode"='available' and "WMSBalance_CustomsStatusCode"=v_line."WMSOrderLine_CustomsStatusCode" and "WMSBalance_AvailableQuantity">0 and (v_line."WMSOrderLine_SourceLocationID" is null or "WMSBalance_LocationID"=v_line."WMSOrderLine_SourceLocationID") order by "WMSBalance_FirstReceiptAt", "WMSBalance_ID" for update loop
      exit when v_needed<=0;
      select "WMSItem_BaseUOMCode" into v_base_uom from public."WMS_Items" where "WMSItem_ID"=v_line."WMSOrderLine_ItemID" for share;
      v_conversion:=jsonb_build_object('taskUom',v_line."WMSOrderLine_UOMCode",'balanceUom',v_balance."WMSBalance_UOMCode",
        'taskFactor',public._warehouse_edge_quantity_in_uom(v_line."WMSOrderLine_ItemID",1,v_line."WMSOrderLine_UOMCode",v_base_uom),
        'balanceFactor',public._warehouse_edge_quantity_in_uom(v_line."WMSOrderLine_ItemID",1,v_balance."WMSBalance_UOMCode",v_base_uom));
      v_take:=least(v_needed,v_balance."WMSBalance_AvailableQuantity"*(v_conversion->>'balanceFactor')::numeric/(v_conversion->>'taskFactor')::numeric);
      if v_take<>round(v_take,6) then raise exception 'WMS409: Allocated quantity exceeds task unit precision. Repack stock first.'; end if;
      v_balance_take:=public._warehouse_edge_task_balance_quantity(v_take,v_line."WMSOrderLine_UOMCode",v_balance."WMSBalance_UOMCode",jsonb_build_object('quantityConversion',v_conversion));
      v_task_id:=gen_random_uuid();
      update public."WMS_InventoryBalances" set "WMSBalance_AllocatedQuantity"="WMSBalance_AllocatedQuantity"+v_balance_take,"WMSBalance_AvailableQuantity"="WMSBalance_AvailableQuantity"-v_balance_take,"WMSBalance_UpdatedAt"=v_now where "WMSBalance_ID"=v_balance."WMSBalance_ID";
      insert into public."WMS_Tasks" ("WMSTask_ID","WMSTask_FacilityID","WMSTask_OrderID","WMSTask_OrderLineID","WMSTask_JobID","WMSTask_TypeCode","WMSTask_StatusCode","WMSTask_PriorityCode","WMSTask_Title","WMSTask_Instructions","WMSTask_SourceLocationID","WMSTask_TargetLocationID","WMSTask_ItemID","WMSTask_BalanceID","WMSTask_HU_ID","WMSTask_Quantity","WMSTask_CompletedQuantity","WMSTask_UOMCode","WMSTask_LotID","WMSTask_MetadataJSON","WMSTask_CreatedBy")
      values(v_task_id,v_order."WMSOrder_FacilityID",p_order_id,v_line."WMSOrderLine_ID",v_order."WMSOrder_JobID",'pick','queued',v_order."WMSOrder_PriorityCode",'Pick stock for '||v_order."WMSOrder_OrderNumber",'Scan the source location and item before confirming the pick.',v_balance."WMSBalance_LocationID",v_line."WMSOrderLine_TargetLocationID",v_line."WMSOrderLine_ItemID",v_balance."WMSBalance_ID",v_balance."WMSBalance_HU_ID",v_take,0,v_line."WMSOrderLine_UOMCode",v_balance."WMSBalance_LotID",jsonb_build_object('releaseRequestId',v_request_id,'dispatchedQuantity',0,'quantityConversion',v_conversion),p_actor_user_id);
      insert into public."WMS_PickTasks" ("WMSPick_ID","WMSPick_TaskID","WMSPick_OrderLineID","WMSPick_BalanceID","WMSPick_SourceLocationID","WMSPick_TargetLocationID","WMSPick_QuantityToPick","WMSPick_QuantityPicked","WMSPick_UOMCode","WMSPick_StatusCode") values(gen_random_uuid(),v_task_id,v_line."WMSOrderLine_ID",v_balance."WMSBalance_ID",v_balance."WMSBalance_LocationID",v_line."WMSOrderLine_TargetLocationID",v_take,0,v_line."WMSOrderLine_UOMCode",'queued');
      insert into public."WMS_TaskEvents" ("WMSTaskEvent_TaskID","WMSTaskEvent_EventTypeCode","WMSTaskEvent_ToStatusCode","WMSTaskEvent_MetadataJSON","WMSTaskEvent_EventBy") values(v_task_id,'created','queued',jsonb_build_object('releaseRequestId',v_request_id),p_actor_user_id);
      v_needed:=v_needed-v_take;
    end loop;
    if v_needed>0 then raise exception 'WMS409: There is not enough available stock to release this order.'; end if;
    update public."WMS_OrderLines" set "WMSOrderLine_AllocatedQuantity"="WMSOrderLine_OrderedQuantity","WMSOrderLine_StatusCode"='allocated' where "WMSOrderLine_ID"=v_line."WMSOrderLine_ID";
  end loop;
  update public."WMS_Orders" set "WMSOrder_StatusCode"='in_progress',"WMSOrder_MetadataJSON"=jsonb_set("WMSOrder_MetadataJSON",'{releaseRequestIds}',coalesce("WMSOrder_MetadataJSON"->'releaseRequestIds','[]'::jsonb)||to_jsonb(v_request_id::text),true),"WMSOrder_UpdatedAt"=v_now,"WMSOrder_UpdatedBy"=p_actor_user_id where "WMSOrder_ID"=p_order_id;
  return p_order_id;
end;
$$;


ALTER FUNCTION "public"."warehouse_edge_release_order_mutation"("p_order_id" "uuid", "p_payload" "jsonb", "p_actor_user_id" "uuid", "p_allowed_facility_ids" "uuid"[], "p_allowed_organisation_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."warehouse_edge_set_item_facilities"("p_item_id" "uuid", "p_default_facility_id" "uuid", "p_facility_ids" "uuid"[], "p_actor_user_id" "uuid", "p_allowed_facility_ids" "uuid"[], "p_allowed_organisation_ids" "uuid"[]) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_item public."WMS_Items"%rowtype;
  v_facility_id uuid;
  v_requested uuid[] := array(select distinct unnest(coalesce(p_facility_ids, '{}'::uuid[])));
begin
  if p_actor_user_id is null then raise exception 'WMS403: Item facility changes are reserved for the warehouse team.'; end if;
  select * into v_item from public."WMS_Items"
  where "WMSItem_ID" = p_item_id and not "WMSItem_IsDeleted"
    and "WMSItem_CustomerOrgID" = any(coalesce(p_allowed_organisation_ids, '{}'::uuid[]))
  for update;
  if not found then raise exception 'WMS404: This item does not exist in your workspace.'; end if;
  if cardinality(v_requested) = 0 or not (p_default_facility_id = any(v_requested)) then
    raise exception 'WMS400: Choose at least one warehouse and include the default warehouse.';
  end if;
  if exists(select 1 from unnest(v_requested) requested where not requested = any(coalesce(p_allowed_facility_ids, '{}'::uuid[]))) then
    raise exception 'WMS403: Choose only warehouses available in your workspace.';
  end if;
  if exists(
    select 1 from public."WMS_ItemFacilityAssignments" assignment
    where assignment."WMSItemFacility_ItemID" = p_item_id
      and assignment."WMSItemFacility_IsActive"
      and not assignment."WMSItemFacility_FacilityID" = any(v_requested)
      and (
        exists(select 1 from public."WMS_InventoryBalances" balance where balance."WMSBalance_ItemID" = p_item_id and balance."WMSBalance_FacilityID" = assignment."WMSItemFacility_FacilityID" and balance."WMSBalance_OnHandQuantity" <> 0)
        or exists(select 1 from public."WMS_OrderLines" line join public."WMS_Orders" warehouse_order on warehouse_order."WMSOrder_ID" = line."WMSOrderLine_OrderID" where line."WMSOrderLine_ItemID" = p_item_id and warehouse_order."WMSOrder_FacilityID" = assignment."WMSItemFacility_FacilityID" and warehouse_order."WMSOrder_StatusCode" not in ('complete','cancelled') and not warehouse_order."WMSOrder_IsDeleted")
      )
  ) then raise exception 'WMS409: A warehouse with stock or open orders cannot be removed from this item.'; end if;

  update public."WMS_ItemFacilityAssignments"
  set "WMSItemFacility_IsActive" = false, "WMSItemFacility_IsDefault" = false, "WMSItemFacility_UpdatedAt" = now()
  where "WMSItemFacility_ItemID" = p_item_id and not "WMSItemFacility_FacilityID" = any(v_requested);
  update public."WMS_ItemFacilityAssignments"
  set "WMSItemFacility_IsDefault" = false, "WMSItemFacility_UpdatedAt" = now()
  where "WMSItemFacility_ItemID" = p_item_id;

  foreach v_facility_id in array v_requested loop
    insert into public."WMS_ItemFacilityAssignments" (
      "WMSItemFacility_ItemID", "WMSItemFacility_FacilityID", "WMSItemFacility_IsDefault",
      "WMSItemFacility_IsActive", "WMSItemFacility_CreatedBy"
    ) values (p_item_id, v_facility_id, v_facility_id = p_default_facility_id, true, p_actor_user_id)
    on conflict ("WMSItemFacility_ItemID", "WMSItemFacility_FacilityID") do update
    set "WMSItemFacility_IsActive" = true,
        "WMSItemFacility_IsDefault" = excluded."WMSItemFacility_IsDefault",
        "WMSItemFacility_UpdatedAt" = now();
  end loop;

  update public."WMS_Items"
  set "WMSItem_DefaultFacilityID" = p_default_facility_id,
      "WMSItem_UpdatedAt" = now()
  where "WMSItem_ID" = p_item_id;
  return p_item_id;
end;
$$;


ALTER FUNCTION "public"."warehouse_edge_set_item_facilities"("p_item_id" "uuid", "p_default_facility_id" "uuid", "p_facility_ids" "uuid"[], "p_actor_user_id" "uuid", "p_allowed_facility_ids" "uuid"[], "p_allowed_organisation_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "quote_api"."allocate_customer_reference"("workspace_company_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'quote_api'
    AS $$
declare
  settings_row quote_api.reference_settings%rowtype;
  allocated record;
begin
  insert into quote_api.reference_settings(company_id, quote_prefix, booking_prefix, quote_pattern, quote_next_number, customer_pattern, customer_next_number)
  values (workspace_company_id, 'Q', 'B', 'Q-{NUMBER:4}', 1, 'CUS{NUMBER:4}', 1)
  on conflict (company_id) do nothing;
  select * into settings_row from quote_api.reference_settings
  where company_id = workspace_company_id for update;
  select * into allocated from quote_api.reserve_reference(
    workspace_company_id, 'customer', 'default', settings_row.customer_pattern, settings_row.customer_next_number
  );
  update quote_api.reference_settings
  set customer_next_number = allocated.next_number, updated_at = now()
  where company_id = workspace_company_id;
  return allocated.reference_value;
end;
$$;


ALTER FUNCTION "quote_api"."allocate_customer_reference"("workspace_company_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "quote_api"."bind_customer_response_document"("requested_response_link_id" "uuid", "requested_quote_document_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  link_row record;
begin
  select link.* into link_row
  from quote_api.customer_response_links link
  where link.response_link_id = requested_response_link_id
  for update;
  if not found then
    raise exception 'That quote response link could not be found.' using errcode = 'P0002';
  end if;
  if link_row.status_code <> 'active' then
    raise exception 'That quote response link is no longer active.' using errcode = '22023';
  end if;
  if not exists (
    select 1
    from public."DOC_StoredObjects" stored
    join public."cmp_Users" creator
      on creator."User_ID" = stored."DOCStoredObject_CreatedBy"
    where stored."DOCStoredObject_ID" = requested_quote_document_id
      and stored."DOCStoredObject_ConcernCode" = 'quote'
      and stored."DOCStoredObject_AggregateType" = 'CusQuote_Header'
      and stored."DOCStoredObject_AggregateID" = link_row.quote_id
      and stored."DOCStoredObject_MimeType" = 'application/pdf'
      and stored."DOCStoredObject_StatusCode" = 'active'
      and stored."DOCStoredObject_DeletedAt" is null
      and creator."Company_ID" = link_row.company_id
  ) then
    raise exception 'The quote PDF is outside this response link.' using errcode = '42501';
  end if;

  update quote_api.customer_response_links
  set quote_document_id = requested_quote_document_id
  where response_link_id = requested_response_link_id;
  return true;
end;
$$;


ALTER FUNCTION "quote_api"."bind_customer_response_document"("requested_response_link_id" "uuid", "requested_quote_document_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "quote_api"."capture_booking_reference_sequence"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'quote_api'
    AS $$
declare
  workspace_company_id uuid;
  sequence_row record;
  extracted_value bigint;
begin
  select office."Company_ID" into workspace_company_id
  from public."cmp_Offices" office
  where office."Office_ID" = coalesce(new."Job_OrgOfficeID", new."Job_OfficeID");
  if new."Job_BookingReferenceSequenceValue" is null then
    for sequence_row in
      select sequence.sequence_key, sequence.pattern
      from quote_api.booking_reference_sequences sequence
      where sequence.company_id = workspace_company_id and sequence.enabled
      order by case when sequence.sequence_key = 'default' then 0 else 1 end, sequence.sequence_key
    loop
      extracted_value := quote_api.extract_reference_sequence(sequence_row.pattern, new."Job_BookingReference", workspace_company_id);
      if extracted_value is not null and extracted_value > 0 then
        new."Job_BookingReferenceSequenceKey" := sequence_row.sequence_key;
        new."Job_BookingReferenceSequenceValue" := extracted_value;
        exit;
      end if;
    end loop;
  end if;
  new."Job_BookingReferenceSequenceKey" := coalesce(nullif(new."Job_BookingReferenceSequenceKey", ''), 'default');
  new."Job_BookingReferenceSequenceValue" := coalesce(new."Job_BookingReferenceSequenceValue", new."Job_Number");
  return new;
end;
$$;


ALTER FUNCTION "quote_api"."capture_booking_reference_sequence"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "quote_api"."capture_customer_reference_sequence"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'quote_api'
    AS $$
declare
  profile_row record;
  pattern_value text;
  sequence_value bigint;
begin
  for profile_row in
    select profile."CRMAccount_ID", profile."CRMAccount_CompanyID"
    from public."CRM_AccountProfiles" profile
    where profile."CRMAccount_OrgID" = new."Org_id" and not profile."CRMAccount_IsDeleted"
  loop
    select settings.customer_pattern into pattern_value
    from quote_api.reference_settings settings where settings.company_id = profile_row."CRMAccount_CompanyID";
    sequence_value := quote_api.extract_reference_sequence(
      coalesce(pattern_value, 'CUS{NUMBER:4}'), new."Org_AccCode", profile_row."CRMAccount_CompanyID"
    );
    if sequence_value is not null and sequence_value > 0 then
      update public."CRM_AccountProfiles"
      set "CRMAccount_ReferenceSequenceValue" = sequence_value,
          "CRMAccount_UpdatedAt" = now()
      where "CRMAccount_ID" = profile_row."CRMAccount_ID";
    end if;
  end loop;
  return new;
end;
$$;


ALTER FUNCTION "quote_api"."capture_customer_reference_sequence"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "quote_api"."capture_quote_reference_sequence"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'quote_api'
    AS $$
declare
  workspace_company_id uuid := new."Org_ID";
  pattern_value text;
begin
  if workspace_company_id is null then
    select office."Company_ID" into workspace_company_id
    from public."cmp_Offices" office
    where office."Office_ID" = coalesce(new."CusQuoteHeader_OrgOfficeID", new."OrgOffice_ID");
  end if;
  select settings.quote_pattern into pattern_value
  from quote_api.reference_settings settings where settings.company_id = workspace_company_id;
  new."CusQuoteHeader_ReferenceSequenceValue" := coalesce(
    new."CusQuoteHeader_ReferenceSequenceValue",
    quote_api.extract_reference_sequence(coalesce(pattern_value, 'Q-{NUMBER:4}'), new."CusQuoteHeader_CustomerReference", workspace_company_id),
    new."CusQuoteHeader_Number"
  );
  return new;
end;
$$;


ALTER FUNCTION "quote_api"."capture_quote_reference_sequence"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "quote_api"."cargo_booking_missing"("lines" "jsonb") RETURNS "text"[]
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare item jsonb; key text; number_value numeric; line_number integer:=0; missing text[]:='{}';
begin
  -- Match actual typed Booking columns; do not silently truncate or round.
  for item in select value from jsonb_array_elements(quote_api.normalise_cargo_lines(lines,false)) loop
    line_number:=line_number+1;
    foreach key in array array['grossWeightKg','netWeightKg','length','width','height'] loop
      number_value:=(item->>key)::numeric;
      if number_value<>round(number_value,2) then
        missing:=array_append(missing,format('Cargo line %s: %s supports up to 2 decimal places in Booking',line_number,
          case key when 'grossWeightKg' then 'gross weight (kg)' when 'netWeightKg' then 'net weight (kg)' else key end));
      end if;
    end loop;
    number_value:=(item->>'volumeCbm')::numeric;
    if number_value<>round(number_value,6) then missing:=array_append(missing,format('Cargo line %s: volume supports up to 6 decimal places in Booking',line_number)); end if;
    if length(item->>'commodity')>50 then missing:=array_append(missing,format('Cargo line %s: commodity supports up to 50 characters; use goods description for additional detail',line_number)); end if;
    if length(item->>'packageType')>40 then missing:=array_append(missing,format('Cargo line %s: package type supports up to 40 characters',line_number)); end if;
    if length(item->>'hsCode')>30 then missing:=array_append(missing,format('Cargo line %s: HS code supports up to 30 characters',line_number)); end if;
  end loop;
  return missing;
exception when invalid_parameter_value then
  return array['Correct cargo line data before Booking handover: '||sqlerrm];
end;
$$;


ALTER FUNCTION "quote_api"."cargo_booking_missing"("lines" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "quote_api"."cargo_handling"("raw" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare data jsonb; kind text; item jsonb; field text; fields text[];
begin
  if nullif(btrim(raw),'') is null then return '{}'::jsonb; end if;
  if length(raw)>20000 then raise exception 'Cargo handling details are too long.' using errcode='22023'; end if;
  begin data:=raw::jsonb; exception when invalid_text_representation then
    raise exception 'Cargo handling details are invalid.' using errcode='22023'; end;
  if jsonb_typeof(data)<>'object' then raise exception 'Cargo handling must be an object.' using errcode='22023'; end if;
  for kind,item in select * from jsonb_each(data) loop
    fields:=case kind
      when 'hazardous' then array['unNumber','properShippingName','class','packingGroup','notes']
      when 'temperatureControlled' then array['setPoint','unit','notes']
      when 'oversized' then '{}'::text[] when 'fragile' then '{}'::text[] when 'foodGrade' then '{}'::text[] end;
    if fields is null or jsonb_typeof(item)<>'object' or jsonb_typeof(item->'tbc') is distinct from 'boolean'
       or jsonb_typeof(item->'details') is distinct from 'object' then
      raise exception 'Invalid cargo handling selection: %.',kind using errcode='22023'; end if;
    if exists(select 1 from jsonb_object_keys(item) k where k not in ('tbc','details')) then
      raise exception 'Unsupported cargo handling data.' using errcode='22023'; end if;
    for field in select jsonb_object_keys(item->'details') loop
      if not field=any(fields) or jsonb_typeof(item->'details'->field)<>'string' or length(item->'details'->>field)>4000 then
        raise exception 'Invalid cargo handling field: %.',field using errcode='22023'; end if;
    end loop;
  end loop;
  return data;
end $$;


ALTER FUNCTION "quote_api"."cargo_handling"("raw" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "quote_api"."cargo_handling_missing"("line" "jsonb", "allow_tbc" boolean DEFAULT false) RETURNS "text"[]
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
declare data jsonb:=quote_api.cargo_handling(line->>'handlingDetailsJson'); kind text; item jsonb; d jsonb; absent boolean; result text[]:='{}';
begin
  for kind,item in select * from jsonb_each(data) loop
    if allow_tbc and (item->>'tbc')::boolean then continue; end if;
    d:=item->'details'; absent:=(item->>'tbc')::boolean;
    if kind='hazardous' then
      absent:=absent or coalesce(d->>'unNumber','') !~ '^[0-9]{4}$'
        or coalesce(nullif(btrim(d->>'properShippingName'),''),'TBC') ~* '\mTBC\M'
        or coalesce(nullif(btrim(d->>'class'),''),'TBC') ~* '\mTBC\M'
        or coalesce(nullif(btrim(d->>'packingGroup'),''),'TBC') ~* '\mTBC\M';
    elsif kind='temperatureControlled' then
      absent:=absent or coalesce(d->>'setPoint','') !~ '^-?[0-9]+([.][0-9]+)?$' or upper(coalesce(d->>'unit','')) not in ('C','F');
    elsif kind='oversized' then
      absent:=absent or coalesce(line->>'length','') !~ '^[0-9]+([.][0-9]+)?$'
        or coalesce(line->>'width','') !~ '^[0-9]+([.][0-9]+)?$' or coalesce(line->>'height','') !~ '^[0-9]+([.][0-9]+)?$';
      if not absent then absent:=(line->>'length')::numeric<=0 or (line->>'width')::numeric<=0 or (line->>'height')::numeric<=0; end if;
    else
      absent:=absent or coalesce(nullif(btrim(line->>'description'),''),'TBC') ~* '\mTBC\M';
    end if;

    absent:=absent or exists(select 1 from jsonb_each_text(d) field where field.value ~* '\mTBC\M');
    if absent then result:=array_append(result,kind); end if;
  end loop;
  return result;
end $_$;


ALTER FUNCTION "quote_api"."cargo_handling_missing"("line" "jsonb", "allow_tbc" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "quote_api"."cargo_handling_summary"("facts" "jsonb") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare
  lines jsonb := quote_api.normalise_cargo_lines(facts->'cargoLines', false);
  manual text := coalesce(nullif(btrim(facts->>'cargoCharacteristics'), ''), nullif(btrim(facts->>'knownCargo'), ''), 'General cargo');
  labels text[] := '{}'; seen text[] := '{}'; token text; key text;
begin
  if exists(select 1 from jsonb_array_elements(lines) line where (line->>'isHazardous')::boolean) then
    labels := array_append(labels, 'Hazardous'); seen := array_append(seen, 'hazardous');
  end if;
  if exists(select 1 from jsonb_array_elements(lines) line where (line->>'isTemperatureControlled')::boolean) then
    labels := array_append(labels, 'Temperature controlled'); seen := array_append(seen, 'temperature controlled');
  end if;
  foreach token in array regexp_split_to_array(manual, '[;,|]') loop
    token := btrim(token); key := lower(token);
    if key <> '' and key not in ('general cargo', 'general merchandise') and not key = any(seen) then
      labels := array_append(labels, token); seen := array_append(seen, key);
    end if;
  end loop;
  return coalesce(nullif(array_to_string(labels, '; '), ''), 'General merchandise');
end $$;


ALTER FUNCTION "quote_api"."cargo_handling_summary"("facts" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "quote_api"."cargo_issue_missing"("lines" "jsonb", "mode_code" "text", "shipment_type" "text") RETURNS "text"[]
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare
  normalised jsonb; item jsonb; line_number integer := 0; label text;
  missing text[] := '{}'; mode_value text := lower(coalesce(mode_code,''));
  containerised boolean := lower(coalesce(shipment_type,'')) like '%fcl%'
    or lower(coalesce(shipment_type,'')) like '%container%';
begin
  -- Incomplete values are allowed in a draft; issue returns actionable labels.
  begin
    normalised := quote_api.normalise_cargo_lines(lines, false);
  exception when invalid_parameter_value then
    return array['Correct cargo line data: ' || sqlerrm];
  end;
  if jsonb_array_length(normalised)=0 then return array['At least one cargo line']; end if;
  for item in select value from jsonb_array_elements(normalised) loop
    line_number := line_number + 1;


    label := format('Cargo line %s: ',line_number);
    if item->>'description' is null then missing := array_append(missing,label || 'goods description'); end if;
    if not containerised then
      if coalesce((item->>'packageQuantity')::numeric,0)<=0 then
        missing := array_append(missing,label || 'positive package / piece quantity');
      end if;
      if item->>'packageType' is null then missing := array_append(missing,label || 'package type'); end if;
    end if;
    if mode_value in ('air','courier')
       and coalesce((item->>'chargeableWeightKg')::numeric,0)<=0
       and coalesce((item->>'grossWeightKg')::numeric,0)<=0 then
      missing := array_append(missing,label || 'positive chargeable or gross weight');
    end if;
    if mode_value in ('sea','ocean','road','rail') and not containerised
       and coalesce((item->>'volumeCbm')::numeric,0)<=0
       and coalesce((item->>'grossWeightKg')::numeric,0)<=0 then
      missing := array_append(missing,label || 'positive volume or gross weight');
    end if;
  end loop;
  return missing;
end;
$$;


ALTER FUNCTION "quote_api"."cargo_issue_missing"("lines" "jsonb", "mode_code" "text", "shipment_type" "text") OWNER TO "postgres";


