CREATE TABLE IF NOT EXISTS "quote_api"."version_cargo_lines" (
    "version_id" "uuid" NOT NULL,
    "line_id" "uuid" NOT NULL,
    "line_number" integer NOT NULL,
    "description" "text",
    "commodity" "text",
    "package_quantity" numeric,
    "package_type" "text",
    "gross_weight_kg" numeric,
    "net_weight_kg" numeric,
    "volume_cbm" numeric,
    "chargeable_weight_kg" numeric,
    "length" numeric,
    "width" numeric,
    "height" numeric,
    "length_unit" "text" NOT NULL,
    "hs_code" "text",
    "country_of_origin" "text",
    "is_hazardous" boolean NOT NULL,
    "is_temperature_controlled" boolean NOT NULL,
    CONSTRAINT "version_cargo_lines_chargeable_weight_kg_check" CHECK ((("chargeable_weight_kg" >= (0)::numeric) AND ("chargeable_weight_kg" <= ('999999999999'::bigint)::numeric))),
    CONSTRAINT "version_cargo_lines_country_of_origin_check" CHECK (("country_of_origin" ~ '^[A-Z]{2}$'::"text")),
    CONSTRAINT "version_cargo_lines_gross_weight_kg_check" CHECK ((("gross_weight_kg" >= (0)::numeric) AND ("gross_weight_kg" <= ('999999999999'::bigint)::numeric))),
    CONSTRAINT "version_cargo_lines_height_check" CHECK ((("height" >= (0)::numeric) AND ("height" <= ('999999999999'::bigint)::numeric))),
    CONSTRAINT "version_cargo_lines_length_check" CHECK ((("length" >= (0)::numeric) AND ("length" <= ('999999999999'::bigint)::numeric))),
    CONSTRAINT "version_cargo_lines_length_unit_check" CHECK (("length_unit" = ANY (ARRAY['cm'::"text", 'm'::"text", 'in'::"text"]))),
    CONSTRAINT "version_cargo_lines_line_number_check" CHECK ((("line_number" >= 1) AND ("line_number" <= 500))),
    CONSTRAINT "version_cargo_lines_net_weight_kg_check" CHECK ((("net_weight_kg" >= (0)::numeric) AND ("net_weight_kg" <= ('999999999999'::bigint)::numeric))),
    CONSTRAINT "version_cargo_lines_package_quantity_check" CHECK ((("package_quantity" >= (0)::numeric) AND ("package_quantity" <= ('999999999999'::bigint)::numeric) AND ("package_quantity" = "trunc"("package_quantity")))),
    CONSTRAINT "version_cargo_lines_volume_cbm_check" CHECK ((("volume_cbm" >= (0)::numeric) AND ("volume_cbm" <= ('999999999999'::bigint)::numeric))),
    CONSTRAINT "version_cargo_lines_width_check" CHECK ((("width" >= (0)::numeric) AND ("width" <= ('999999999999'::bigint)::numeric)))
);


