CREATE OR REPLACE FUNCTION "quote_api"."clean_reference_pattern"("value" "text", "fallback" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  cleaned text := upper(btrim(coalesce(value, '')));
  literal_text text;
  counter_tokens integer;
  invalid_width text;
begin
  if cleaned = '' then cleaned := upper(btrim(fallback)); end if;
  if length(cleaned) > 64 then
    raise exception 'Reference rules must be 64 characters or fewer.' using errcode = '22023';
  end if;

  select count(*) into counter_tokens
  from regexp_matches(cleaned, '\{(?:NUMBER|LETTERS)(?::[0-9]{1,2})?\}', 'g');
  if counter_tokens <> 1 then
    raise exception 'Every reference rule needs one continuous number or letter sequence.' using errcode = '22023';
  end if;

  select width_match[1] into invalid_width
  from regexp_matches(cleaned, '\{(?:NUMBER|LETTERS|COMPANY|MULTIDECK|DIRECTION):([0-9]{1,2})\}', 'g') width_match
  where width_match[1]::integer not between 1 and 18
  limit 1;
  if invalid_width is not null then
    raise exception 'Reference rule lengths must be between 1 and 18 characters.' using errcode = '22023';
  end if;

  literal_text := regexp_replace(
    cleaned,
    '\{(?:NUMBER|LETTERS|COMPANY|MULTIDECK|DIRECTION)(?::[0-9]{1,2})?\}',
    '',
    'g'
  );
  if literal_text ~ '[^A-Z0-9 _./-]' or literal_text ~ '[{}]' then
    raise exception 'Use letters, numbers, spaces, hyphens, underscores, slashes, full stops and the supported rule parts.' using errcode = '22023';
  end if;
  return cleaned;
end;
$$;


ALTER FUNCTION "quote_api"."clean_reference_pattern"("value" "text", "fallback" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "quote_api"."clean_reference_prefix"("value" "text", "fallback" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare
  cleaned text := upper(regexp_replace(coalesce(value, ''), '[^A-Z0-9]', '', 'g'));
begin
  if cleaned = '' then return fallback; end if;
  if length(cleaned) > 12 then raise exception 'Reference prefix must be 12 characters or fewer.' using errcode = '22023'; end if;
  return cleaned;
end;
$$;


ALTER FUNCTION "quote_api"."clean_reference_prefix"("value" "text", "fallback" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "quote_api"."customer_response_view"("requested_token_hash" "text", "requested_response_origin" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  link_row record;
  version_row record;
  quote_row record;
  response_row record;
begin
  if requested_token_hash !~ '^[0-9a-f]{64}$' then
    raise exception 'This quote link is invalid.' using errcode = 'P0002';
  end if;
  select link.* into link_row
  from quote_api.customer_response_links link
  where link.token_hash = requested_token_hash;
  if not found then raise exception 'This quote link is invalid.' using errcode = 'P0002'; end if;
  if link_row.response_origin is distinct from requested_response_origin then
    raise exception 'This quote link is not available on this workspace.' using errcode = 'P0002';
  end if;

  if link_row.status_code = 'active' and link_row.expires_at is not null and link_row.expires_at <= now() then
    return jsonb_build_object('state', 'expired');
  end if;
  if link_row.status_code = 'revoked' then return jsonb_build_object('state', 'revoked'); end if;
  select response.* into response_row
  from quote_api.customer_responses response
  where response.response_link_id = link_row.response_link_id;
  if found then
    return jsonb_build_object(
      'state', 'responded',
      'decision', response_row.decision_code,
      'respondedAt', response_row.created_at
    );
  end if;

  select version.* into strict version_row
  from public."CusQuote_Versions" version
  where version."CusQuoteVersion_ID" = link_row.quote_version_id;
  select quote.* into strict quote_row
  from public."CusQuote_Header" quote
  where quote."CusQuoteHeader_ID" = link_row.quote_id;

  return jsonb_build_object(
    'state', 'active',
    'expiresAt', link_row.expires_at,
    'recipientName', link_row.recipient_name,
    'recipientEmail', link_row.recipient_email,
    'documentId', link_row.quote_document_id,
    'quote', jsonb_build_object(
      'id', quote_row."CusQuoteHeader_ID",
      'reference', coalesce(quote_row."CusQuoteHeader_CustomerReference", 'Q-' || quote_row."CusQuoteHeader_Number"),
      'versionNumber', version_row."CusQuoteVersion_Number",
      'snapshot', version_row."CusQuoteVersion_SnapshotJSON",
      'customerName', coalesce(
        version_row."CusQuoteVersion_SnapshotJSON"#>>'{quote,customerName}',
        quote_row."CusQuoteHeader_CustomerNameSnapshot"
      ),
      'contactName', coalesce(
        version_row."CusQuoteVersion_SnapshotJSON"#>>'{quote,contactName}',
        quote_row."CusQuoteHeader_ContactNameSnapshot"
      )
    )
  );
exception
  when no_data_found then
    raise exception 'This quote link is no longer available.' using errcode = 'P0002';
end;
$_$;


ALTER FUNCTION "quote_api"."customer_response_view"("requested_token_hash" "text", "requested_response_origin" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "quote_api"."edit_draft_cargo"("caller_auth_user_id" "uuid", "arguments" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  actor record; quote public."CusQuote_Header"; version public."CusQuote_Versions";
  payload jsonb; lines jsonb; item jsonb; before_line jsonb; after_line jsonb; saved jsonb;
  field text := arguments->>'field'; line_id uuid; ordinal integer;
begin
  if not coalesce(quote_api.has_permission(caller_auth_user_id,'Quotes.Read'),false)
    or not coalesce(quote_api.has_permission(caller_auth_user_id,'Quotes.Write'),false) then
    raise exception 'You do not have permission to edit Quote cargo.' using errcode = '42501';
  end if;
  select "User_ID","Company_ID" into actor from public."cmp_Users"
    where "Auth_User_ID"=caller_auth_user_id and "User_AccessStatus"='active';
  if not found then raise exception 'An active operator is required.' using errcode='42501';end if;
  if jsonb_typeof(arguments) is distinct from 'object'
    or not (arguments ?& array['target_id','version_id','line_id','expected_updated_at','expected_snapshot_hash','field','value','reason'])
    or exists(select 1 from jsonb_object_keys(arguments) key where key not in
      ('target_id','version_id','line_id','expected_updated_at','expected_snapshot_hash','field','value','reason'))
    or jsonb_typeof(arguments->'reason') is distinct from 'string'
    or nullif(btrim(arguments->>'reason'),'') is null or length(arguments->>'reason')>2000
    or coalesce(arguments->>'expected_snapshot_hash','') !~ '^[0-9a-f]{32}$'
    or nullif(arguments->>'expected_updated_at','') is null then
    raise exception 'Read the exact Quote draft and cargo line before proposing an edit.' using errcode='22023';
  end if;
  if field is null or field not in ('description','commodity','packageType','hsCode','countryOfOrigin',
    'packageQuantity','grossWeightKg','netWeightKg','volumeCbm','chargeableWeightKg','length','width','height',
    'lengthUnit','isHazardous','isTemperatureControlled') then
    raise exception 'That field is not an editable Quote cargo field.' using errcode='22023';
  end if;
  if field in ('packageQuantity','grossWeightKg','netWeightKg','volumeCbm','chargeableWeightKg','length','width','height')
    and jsonb_typeof(arguments->'value') not in ('string','null') then
    raise exception 'Use exact decimal text, or null to clear a cargo measurement.' using errcode='22023';
  end if;
  line_id := (arguments->>'line_id')::uuid;
  -- Match submission's lock order. The hash is an optimistic version token,
  -- not authorization; current operator, office and record checks are separate.
  select q.* into quote from public."CusQuote_Header" q join public."cmp_Offices" office
    on office."Office_ID"=coalesce(q."CusQuoteHeader_OrgOfficeID",q."OrgOffice_ID")
    where q."CusQuoteHeader_ID"=(arguments->>'target_id')::uuid
      and office."Company_ID"=actor."Company_ID" and not q."CusQuoteHeader_IsDeleted" for update of q;
  if not found then raise exception 'That Quote is outside this workspace.' using errcode='42501';end if;
  select v.* into version from public."CusQuote_Versions" v
    where v."CusQuoteHeader_ID"=quote."CusQuoteHeader_ID" and v."Company_ID"=actor."Company_ID"
      and v."CusQuoteVersion_ID"=(arguments->>'version_id')::uuid and v."CusQuoteVersion_IsCurrent" for update;
  if not found or quote."CusQuoteHeader_LastEditedDate" is distinct from (arguments->>'expected_updated_at')::timestamp
    or md5(version."CusQuoteVersion_SnapshotJSON"::text) is distinct from arguments->>'expected_snapshot_hash' then
    raise exception 'The Quote draft changed. Read it again and request fresh approval.' using errcode='40001';
  end if;
  if version."CusQuoteVersion_IsSubmitted" or version."CusQuoteVersion_StatusCode" is distinct from 'draft'
    or coalesce(quote."CusQuoteHeader_LifecycleCode",'') not in ('draft','calculated','revised')
    or exists(select 1 from quote_api.customer_response_links where quote_version_id=version."CusQuoteVersion_ID")
    or exists(select 1 from quote_api.customer_responses where quote_version_id=version."CusQuoteVersion_ID") then
    raise exception 'Only a working draft can be edited. Open a revised draft before changing an issued Quote.' using errcode='22023';
  end if;
  payload := version."CusQuoteVersion_SnapshotJSON"->'quote';
  if jsonb_typeof(payload) is distinct from 'object'
    or jsonb_typeof(payload#>'{shipmentFacts,cargoLines}') is distinct from 'array' then
    raise exception 'This Quote needs its legacy cargo reviewed in the Quote screen first.' using errcode='22023';
  end if;
  lines := quote_api.normalise_cargo_lines(payload#>'{shipmentFacts,cargoLines}',false);
  select value, (position-1)::integer into before_line,ordinal
    from jsonb_array_elements(lines) with ordinality rows(value,position) where (value->>'id')::uuid=line_id;
  if not found then raise exception 'That cargo line is not in this Quote draft.' using errcode='42501';end if;
  item := jsonb_set(before_line,array[field],arguments->'value');
  after_line := quote_api.normalise_cargo_lines(jsonb_build_array(item),false)->0;
  if before_line is distinct from after_line then
    lines := jsonb_set(lines,array[ordinal::text],after_line);
    payload := jsonb_set(payload,'{shipmentFacts,cargoLines}',lines);
    -- Reuse the complete current saved payload: no party, payer, charge,
    -- route or commercial value is reconstructed from a partial model input.
    saved := public.quote_workflow_save_quote(caller_auth_user_id,quote."CusQuoteHeader_ID",payload);
    if saved->>'versionId' is distinct from version."CusQuoteVersion_ID"::text then
      raise exception 'The working draft changed during the save. No cargo edit was applied.' using errcode='40001';
    end if;
    insert into public."CusQuote_Events"("Company_ID","CusQuoteHeader_ID","CusQuoteVersion_ID",
      "CusQuoteEvent_TypeCode","CusQuoteEvent_Summary","CusQuoteEvent_MetadataJSON","CusQuoteEvent_ActorUserID")
    values(actor."Company_ID",quote."CusQuoteHeader_ID",version."CusQuoteVersion_ID",'cargo_updated',
      'Approved Quote draft cargo updated; issued versions and Booking unchanged.',
      jsonb_build_object('lineId',line_id,'field',field,'before',before_line->field,'after',after_line->field,
        'reason',btrim(arguments->>'reason')),actor."User_ID");
  end if;
  return jsonb_build_object('quoteId',quote."CusQuoteHeader_ID",'versionId',version."CusQuoteVersion_ID",
    'lineId',line_id,'field',field,'before',before_line->field,'after',after_line->field,'changed',before_line is distinct from after_line);
end $_$;


ALTER FUNCTION "quote_api"."edit_draft_cargo"("caller_auth_user_id" "uuid", "arguments" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "quote_api"."enforce_branch_relative_direction"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  expected_direction text;
  origin_location text;
  destination_location text;
begin
  origin_location := coalesce(
    nullif(new."CusQuoteHeader_ShipmentFactsJSON"->>'originUnlocode', ''),
    nullif(new."CusQuoteHeader_ShipmentFactsJSON"->>'originCountry', ''),
    nullif(new."CusQuoteHeader_LoadingPoint", ''),
    nullif(new."CusQuoteHeader_OriginExtra", '')
  );
  destination_location := coalesce(
    nullif(new."CusQuoteHeader_ShipmentFactsJSON"->>'destinationUnlocode', ''),
    nullif(new."CusQuoteHeader_ShipmentFactsJSON"->>'destinationCountry', ''),
    nullif(new."CusQuoteHeader_DischargePoint", ''),
    nullif(new."CusQuoteHeader_DestinationExtra", '')
  );
  expected_direction := booking_api.direction_for_route(
    coalesce(new."CusQuoteHeader_OrgOfficeID", new."OrgOffice_ID"),
    origin_location,
    destination_location
  );

  if expected_direction is not null then
    new."CusQuoteHeader_Direction" := expected_direction;
    new."CusQuoteHeader_ShipmentFactsJSON" := jsonb_set(
      coalesce(new."CusQuoteHeader_ShipmentFactsJSON", '{}'::jsonb),
      '{quoteType}',
      to_jsonb(booking_api.direction_label(expected_direction)),
      true
    );
  end if;
  return new;
end;
$$;


ALTER FUNCTION "quote_api"."enforce_branch_relative_direction"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "quote_api"."enforce_version_branch_relative_direction"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  office_id uuid;
  quote_payload jsonb;
  expected_direction text;
begin
  quote_payload := new."CusQuoteVersion_SnapshotJSON"->'quote';
  if jsonb_typeof(quote_payload) <> 'object' then return new; end if;

  select coalesce(quote."CusQuoteHeader_OrgOfficeID", quote."OrgOffice_ID")
    into office_id
  from public."CusQuote_Header" quote
  where quote."CusQuoteHeader_ID" = new."CusQuoteHeader_ID";

  expected_direction := booking_api.direction_for_route(
    office_id,
    coalesce(
      nullif(quote_payload#>>'{shipmentFacts,originUnlocode}', ''),
      nullif(quote_payload#>>'{shipmentFacts,originCountry}', ''),
      nullif(quote_payload->>'loadingPoint', '')
    ),
    coalesce(
      nullif(quote_payload#>>'{shipmentFacts,destinationUnlocode}', ''),
      nullif(quote_payload#>>'{shipmentFacts,destinationCountry}', ''),
      nullif(quote_payload->>'dischargePoint', '')
    )
  );
  if expected_direction is null then return new; end if;

  new."CusQuoteVersion_SnapshotJSON" := jsonb_set(
    jsonb_set(
      new."CusQuoteVersion_SnapshotJSON",
      '{quote,direction}',
      to_jsonb(expected_direction),
      true
    ),
    '{quote,shipmentFacts,quoteType}',
    to_jsonb(booking_api.direction_label(expected_direction)),
    true
  );
  return new;
end;
$$;


ALTER FUNCTION "quote_api"."enforce_version_branch_relative_direction"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "quote_api"."ensure_quote_reference"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'quote_api'
    AS $$
declare
  workspace_company_id uuid := new."Org_ID";
  settings_row quote_api.reference_settings%rowtype;
  allocated record;
begin
  if workspace_company_id is null and coalesce(new."CusQuoteHeader_OrgOfficeID", new."OrgOffice_ID") is not null then
    select "Company_ID" into workspace_company_id from public."cmp_Offices"
    where "Office_ID" = coalesce(new."CusQuoteHeader_OrgOfficeID", new."OrgOffice_ID");
  end if;
  if tg_op = 'INSERT' and nullif(btrim(new."CusQuoteHeader_CustomerReference"), '') is null then
    if new."CusQuoteHeader_Number" is null then new."CusQuoteHeader_Number" := nextval('quote_api.quote_number_seq'); end if;
    insert into quote_api.reference_settings(company_id, quote_prefix, booking_prefix, quote_pattern, quote_next_number)
    values (workspace_company_id, 'Q', 'B', 'Q-{NUMBER:4}', 1) on conflict (company_id) do nothing;
    select * into settings_row from quote_api.reference_settings where company_id = workspace_company_id for update;
    select * into allocated from quote_api.reserve_reference(workspace_company_id, 'quote', 'default', settings_row.quote_pattern, settings_row.quote_next_number);
    update quote_api.reference_settings set quote_next_number = allocated.next_number, updated_at = now() where company_id = workspace_company_id;
    new."CusQuoteHeader_CustomerReference" := allocated.reference_value;
    new."CusQuoteHeader_ReferenceSequenceValue" := allocated.next_number - 1;
  elsif tg_op = 'UPDATE' and old."CusQuoteHeader_CustomerReference" is null
    and nullif(btrim(new."CusQuoteHeader_CustomerReference"), '') is null then
    insert into quote_api.reference_settings(company_id, quote_prefix, booking_prefix, quote_pattern, quote_next_number)
    values (workspace_company_id, 'Q', 'B', 'Q-{NUMBER:4}', 1) on conflict (company_id) do nothing;
    select * into settings_row from quote_api.reference_settings where company_id = workspace_company_id for update;
    select * into allocated from quote_api.reserve_reference(workspace_company_id, 'quote', 'default', settings_row.quote_pattern, settings_row.quote_next_number);
    update quote_api.reference_settings set quote_next_number = allocated.next_number, updated_at = now() where company_id = workspace_company_id;
    new."CusQuoteHeader_CustomerReference" := allocated.reference_value;
    new."CusQuoteHeader_ReferenceSequenceValue" := allocated.next_number - 1;
  elsif tg_op = 'UPDATE' and old."CusQuoteHeader_CustomerReference" is not null
    and new."CusQuoteHeader_CustomerReference" is distinct from old."CusQuoteHeader_CustomerReference"
    and coalesce(current_setting('multideck.reference_sync', true), '') <> 'on' then
    new."CusQuoteHeader_CustomerReference" := old."CusQuoteHeader_CustomerReference";
  end if;
  return new;
end;
$$;


ALTER FUNCTION "quote_api"."ensure_quote_reference"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "quote_api"."extract_reference_sequence"("pattern" "text", "reference_value" "text", "workspace_company_id" "uuid") RETURNS bigint
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'quote_api'
    AS $_$
declare
  cleaned_pattern text := quote_api.clean_reference_pattern(pattern, 'Q-{NUMBER:4}');
  token text;
  token_position integer;
  counter_kind text;
  prefix_value text;
  suffix_value text;
  normalized_reference text := upper(btrim(coalesce(reference_value, '')));
  counter_value text;
  result_value bigint := 0;
  character_value text;
begin
  token := substring(cleaned_pattern from '\{(?:NUMBER|LETTERS)(?::[0-9]{1,2})?\}');
  token_position := position(token in cleaned_pattern);
  counter_kind := case when token like '{LETTERS%' then 'LETTERS' else 'NUMBER' end;
  prefix_value := quote_api.reference_literal(left(cleaned_pattern, token_position - 1), workspace_company_id);
  suffix_value := quote_api.reference_literal(substr(cleaned_pattern, token_position + length(token)), workspace_company_id);
  if normalized_reference = ''
     or normalized_reference not like prefix_value || '%'
     or (suffix_value <> '' and right(normalized_reference, length(suffix_value)) <> suffix_value)
     or length(normalized_reference) < length(prefix_value) + length(suffix_value) + 1 then
    return null;
  end if;
  counter_value := substr(
    normalized_reference,
    length(prefix_value) + 1,
    length(normalized_reference) - length(prefix_value) - length(suffix_value)
  );
  if counter_kind = 'NUMBER' then
    if counter_value !~ '^[0-9]+$' then return null; end if;
    return counter_value::bigint;
  end if;
  if counter_value !~ '^[A-Z]+$' then return null; end if;
  foreach character_value in array regexp_split_to_array(counter_value, '') loop
    result_value := result_value * 26 + ascii(character_value) - 64;
  end loop;
  -- The renderer treats the left padding A characters as zero-value padding.
  return result_value - ((power(26::numeric, length(counter_value)) - 1) / 25)::bigint + 1;
end;
$_$;


ALTER FUNCTION "quote_api"."extract_reference_sequence"("pattern" "text", "reference_value" "text", "workspace_company_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "quote_api"."follow_up_due_at"("sent_at" timestamp with time zone, "delay_days" integer, "send_time" time without time zone, "timezone_name" "text") RETURNS timestamp with time zone
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select ((((sent_at at time zone timezone_name)::date + greatest(delay_days, 1)) + send_time) at time zone timezone_name)
$$;


ALTER FUNCTION "quote_api"."follow_up_due_at"("sent_at" timestamp with time zone, "delay_days" integer, "send_time" time without time zone, "timezone_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "quote_api"."has_permission"("caller_auth_user_id" "uuid", "permission_value" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (
    select 1
    from public."cmp_Users" app_user
    join public."cmp_Users_Roles" user_role
      on user_role."User_ID" = app_user."User_ID"
    join public."sys_UserRole_Permissions" role_permission
      on role_permission."sys_UserRole_ID" = user_role."sys_UserRole_ID"
    join public."sys_Permissions" permission
      on permission."sys_Permission_ID" = role_permission."sys_Permission_ID"
    where app_user."Auth_User_ID" = caller_auth_user_id
      and app_user."User_AccessStatus" = 'active'
      and permission."sys_Permission_Value" = permission_value
  );
$$;


ALTER FUNCTION "quote_api"."has_permission"("caller_auth_user_id" "uuid", "permission_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "quote_api"."issue_customer_response"("caller_auth_user_id" "uuid", "requested_quote_id" "uuid", "requested_recipient_name" "text", "requested_recipient_email" "text", "requested_response_origin" "text", "requested_token_hash" "text", "requested_expires_at" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  app_user record;
  quote_row record;
  version_id uuid;
  readiness jsonb;
  link_id uuid;
begin
  if caller_auth_user_id is null
     or not quote_api.has_permission(caller_auth_user_id, 'Quotes.Write') then
    raise exception 'Quote issue is not authorised.' using errcode = '42501';
  end if;
  if requested_token_hash !~ '^[0-9a-f]{64}$' then
    raise exception 'The quote response token is invalid.' using errcode = '22023';
  end if;
  if requested_recipient_email is null
     or requested_recipient_email !~* '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' then
    raise exception 'Enter a valid customer email address.' using errcode = '22023';
  end if;
  if requested_response_origin is null or not (
    requested_response_origin ~ '^https://([a-z0-9]|[a-z0-9][a-z0-9-]{0,61}[a-z0-9])\.multideck\.app$'
    or requested_response_origin ~ '^https?://(localhost|127\.0\.0\.1):3000$'
  ) then
    raise exception 'The quote response workspace is invalid.' using errcode = '22023';
  end if;
  if requested_expires_at is not null
     and (requested_expires_at <= now() or requested_expires_at > now() + interval '90 days') then
    raise exception 'Choose a quote response expiry within 90 days, or never.' using errcode = '22023';
  end if;

  select "User_ID", "Company_ID" into strict app_user
  from public."cmp_Users"
  where "Auth_User_ID" = caller_auth_user_id
    and "User_AccessStatus" = 'active';
  select quote.* into quote_row
  from public."CusQuote_Header" quote
  join public."cmp_Offices" office
    on office."Office_ID" = coalesce(quote."CusQuoteHeader_OrgOfficeID", quote."OrgOffice_ID")
  where quote."CusQuoteHeader_ID" = requested_quote_id
    and office."Company_ID" = app_user."Company_ID"
    and not quote."CusQuoteHeader_IsDeleted"
  for update;
  if not found then raise exception 'That quote is outside this workspace.' using errcode = '42501'; end if;
  if quote_row."CusQuoteHeader_LifecycleCode" in ('accepted','declined','ghosted') then
    raise exception 'This quote already has a final outcome.' using errcode = '22023';
  end if;

  readiness := booking_api.quote_readiness(requested_quote_id);
  if not coalesce((readiness->>'ready')::boolean, false) then
    raise exception 'Complete the required quote fields before sending it.' using errcode = '22023', detail = readiness::text;
  end if;
  select version."CusQuoteVersion_ID" into version_id
  from public."CusQuote_Versions" version
  where version."CusQuoteHeader_ID" = requested_quote_id
    and version."CusQuoteVersion_IsCurrent"
  limit 1;
  if version_id is null then raise exception 'Save the quote before sending it.' using errcode = '22023'; end if;

  update quote_api.customer_response_links
  set status_code = 'revoked', revoked_at = now()
  where quote_id = requested_quote_id and status_code = 'active';

  insert into quote_api.customer_response_links (
    company_id, quote_id, quote_version_id, recipient_name, recipient_email,
    response_origin, token_hash, expires_at, created_by
  ) values (
    app_user."Company_ID", requested_quote_id, version_id,
    left(nullif(btrim(requested_recipient_name), ''), 180), lower(btrim(requested_recipient_email)),
    requested_response_origin, requested_token_hash, requested_expires_at, app_user."User_ID"
  ) returning response_link_id into link_id;

  update public."CusQuote_Header" set
    "CusQuoteHeader_LifecycleCode" = 'sent',
    "CusQuoteHeader_Status" = 4,
    "CusQuoteHeader_ContactEmailSnapshot" = lower(btrim(requested_recipient_email)),
    "CusQuoteHeader_ContactNameSnapshot" = coalesce(left(nullif(btrim(requested_recipient_name), ''), 180), "CusQuoteHeader_ContactNameSnapshot"),
    "CusQuoteHeader_LastEditedBy" = app_user."User_ID",
    "CusQuoteHeader_LastEditedDate" = now()
  where "CusQuoteHeader_ID" = requested_quote_id;

  insert into public."CusQuote_Events" (
    "Company_ID", "CusQuoteHeader_ID", "CusQuoteVersion_ID", "CusQuoteEvent_TypeCode",
    "CusQuoteEvent_Summary", "CusQuoteEvent_MetadataJSON", "CusQuoteEvent_ActorUserID"
  ) values (
    app_user."Company_ID", requested_quote_id, version_id, 'customer_link_issued',
    'Secure customer response link issued.',
    jsonb_build_object('responseLinkId', link_id, 'recipientEmail', lower(btrim(requested_recipient_email)), 'responseOrigin', requested_response_origin, 'expiresAt', requested_expires_at),
    app_user."User_ID"
  );

  return jsonb_build_object(
    'responseLinkId', link_id,
    'quoteId', requested_quote_id,
    'quoteVersionId', version_id,
    'reference', coalesce(quote_row."CusQuoteHeader_CustomerReference", 'Q-' || quote_row."CusQuoteHeader_Number"),
    'expiresAt', requested_expires_at,
    'responseOrigin', requested_response_origin,
    'recipientEmail', lower(btrim(requested_recipient_email))
  );
end;
$_$;


ALTER FUNCTION "quote_api"."issue_customer_response"("caller_auth_user_id" "uuid", "requested_quote_id" "uuid", "requested_recipient_name" "text", "requested_recipient_email" "text", "requested_response_origin" "text", "requested_token_hash" "text", "requested_expires_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "quote_api"."jsonb_has_content"("value" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare
  item jsonb;
begin
  if value is null or value = 'null'::jsonb then return false; end if;
  case jsonb_typeof(value)
    when 'string' then return nullif(btrim(value #>> '{}'), '') is not null;
    when 'number' then return true;
    when 'boolean' then return true;
    when 'array' then
      for item in select child from jsonb_array_elements(value) child loop
        if quote_api.jsonb_has_content(item) then return true; end if;
      end loop;
      return false;
    when 'object' then
      for item in select child from jsonb_each(value) pair(key, child) loop
        if quote_api.jsonb_has_content(item) then return true; end if;
      end loop;
      return false;
    else return false;
  end case;
end;
$$;


ALTER FUNCTION "quote_api"."jsonb_has_content"("value" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "quote_api"."mark_quote_version_submitted"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.delivery_status_code <> 'sent'
     or new.status_code not in ('active', 'revoked') then
    return new;
  end if;

  update public."CusQuote_Versions"
  set "CusQuoteVersion_IsSubmitted" = true,
      "CusQuoteVersion_SubmittedAt" = coalesce("CusQuoteVersion_SubmittedAt", now()),
      "CusQuoteVersion_SubmittedBy" = coalesce("CusQuoteVersion_SubmittedBy", new.created_by),
      "CusQuoteVersion_StatusCode" = case
        when "CusQuoteVersion_StatusCode" in ('accepted', 'declined', 'changes_requested') then "CusQuoteVersion_StatusCode"
        else 'submitted'
      end
  where "CusQuoteVersion_ID" = new.quote_version_id
    and "CusQuoteHeader_ID" = new.quote_id;

  if not found then
    raise exception 'The quote version for this response link is unavailable.' using errcode = 'P0002';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "quote_api"."mark_quote_version_submitted"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "quote_api"."normalise_cargo_facts"("facts" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare
  lines jsonb; key text; total numeric; present integer; distinct_values integer; label text;
begin
  if jsonb_typeof(facts) is distinct from 'object' then
    raise exception 'Shipment facts must be an object.' using errcode = '22023';
  end if;
  if not facts ? 'cargoLines' then return facts; end if;
  lines := quote_api.normalise_cargo_lines(facts->'cargoLines', false);
  facts := jsonb_set(facts, '{cargoLines}', lines);
  foreach key in array array['packageQuantity','grossWeightKg','volumeCbm','chargeableWeightKg'] loop
    select count(line->>key), sum((line->>key)::numeric) into present,total
      from jsonb_array_elements(lines) line;
    -- An incomplete total is unknown, not a partial sum or an invented zero.
    facts := jsonb_set(facts, array[key], to_jsonb(case
      when present > 0 and present = jsonb_array_length(lines) then trim_scale(total)::text else '' end));
  end loop;
  foreach key in array array['commodity','packageType'] loop
    select count(line->>key), count(distinct line->>key), min(line->>key)
      into present,distinct_values,label from jsonb_array_elements(lines) line;
    facts := jsonb_set(facts, array[key], to_jsonb(case
      when present = jsonb_array_length(lines) and distinct_values = 1 then label else '' end));
  end loop;
  return facts;
end $$;


ALTER FUNCTION "quote_api"."normalise_cargo_facts"("facts" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "quote_api"."normalise_cargo_lines"("lines" "jsonb", "require_complete" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
declare
  item jsonb; result jsonb := '[]'; normalised jsonb; key text; raw text;
  line_id uuid; seen uuid[] := '{}'; number_value numeric;
  text_fields constant text[] := array['description','commodity','packageType','hsCode','countryOfOrigin','handlingDetailsJson'];
  number_fields constant text[] := array['packageQuantity','grossWeightKg','netWeightKg','volumeCbm','chargeableWeightKg','length','width','height'];
  boolean_fields constant text[] := array['isHazardous','isTemperatureControlled'];
begin
  if jsonb_typeof(lines) is distinct from 'array' then
    raise exception 'Cargo lines must be a list.' using errcode = '22023';
  end if;
  if jsonb_array_length(lines) > 500 then
    raise exception 'A quote supports up to 500 cargo lines.' using errcode = '22023';
  end if;
  if require_complete and jsonb_array_length(lines) = 0 then
    raise exception 'Add at least one cargo line before submitting the quote.' using errcode = '22023';
  end if;
  for item in select value from jsonb_array_elements(lines) loop
    if jsonb_typeof(item) <> 'object' then
      raise exception 'Each cargo line must be an object.' using errcode = '22023';
    end if;
    for key in select jsonb_object_keys(item) loop
      if not key = any(text_fields || number_fields || boolean_fields || array['id','lengthUnit']) then
        raise exception 'Unsupported quote cargo field: %.', key using errcode = '22023';
      end if;
    end loop;
    if jsonb_typeof(item->'id') is distinct from 'string'
       or (item->>'id') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
      raise exception 'Each cargo line needs a stable identifier.' using errcode = '22023';
    end if;
    line_id := (item->>'id')::uuid;
    if line_id = any(seen) then
      raise exception 'Cargo line identifiers cannot be duplicated.' using errcode = '22023';
    end if;
    seen := array_append(seen, line_id);
    normalised := jsonb_build_object('id', line_id);
    foreach key in array text_fields loop
      if item ? key and jsonb_typeof(item->key) not in ('string','null') then
        raise exception 'Cargo % must be text.', key using errcode = '22023';
      end if;
      raw := nullif(btrim(item->>key), '');
      if length(raw) > 4000 then
        raise exception 'Cargo % is too long.', key using errcode = '22023';
      end if;
      if key = 'countryOfOrigin' then
        raw := upper(raw);
        if raw is not null and raw !~ '^[A-Z]{2}$' then
          raise exception 'Cargo origin must use a two-letter country code.' using errcode = '22023';
        end if;
      end if;
      normalised := normalised || jsonb_build_object(key, raw);
    end loop;
    if require_complete and normalised->>'description' is null then
      raise exception 'Describe every cargo line before submitting the quote.' using errcode = '22023';
    end if;
    foreach key in array number_fields loop
      if item ? key and jsonb_typeof(item->key) not in ('string','number','null') then
        raise exception 'Cargo % must be a non-negative number.', key using errcode = '22023';
      end if;
      raw := nullif(btrim(item->>key), '');
      if raw is not null and (length(raw) > 32 or raw !~ '^[0-9]+([.][0-9]+)?$') then
        raise exception 'Cargo % must be a finite non-negative number.', key using errcode = '22023';
      end if;
      number_value := raw::numeric;
      if number_value > 999999999999 then
        raise exception 'Cargo % exceeds the supported amount.', key using errcode = '22023';
      end if;
      if key = 'packageQuantity' and number_value <> trunc(number_value) then
        raise exception 'Cargo package quantity must be a whole number.' using errcode = '22023';
      end if;
      normalised := normalised || jsonb_build_object(key, number_value::text);
    end loop;
    raw := coalesce(nullif(btrim(item->>'lengthUnit'), ''), 'cm');
    if raw not in ('cm','m','in') then
      raise exception 'Cargo dimensions must use cm, m or in.' using errcode = '22023';
    end if;
    normalised := normalised || jsonb_build_object('lengthUnit', raw);
    foreach key in array boolean_fields loop
      if item ? key and jsonb_typeof(item->key) is distinct from 'boolean' then
        raise exception 'Cargo % must be true or false.', key using errcode = '22023';
      end if;
      normalised := normalised || jsonb_build_object(key, coalesce((item->>key)::boolean, false));
    end loop;

    if nullif(btrim(item->>'handlingDetailsJson'),'') is not null then
      perform quote_api.cargo_handling(item->>'handlingDetailsJson');
      if coalesce((normalised->>'isHazardous')::boolean,false) <> (quote_api.cargo_handling(item->>'handlingDetailsJson') ? 'hazardous')
        or coalesce((normalised->>'isTemperatureControlled')::boolean,false) <> (quote_api.cargo_handling(item->>'handlingDetailsJson') ? 'temperatureControlled') then
        raise exception 'Cargo handling flags do not match the line details.' using errcode='22023';
      end if;

    end if;
    result := result || jsonb_build_array(normalised);
  end loop;
  return result;
end;
$_$;


ALTER FUNCTION "quote_api"."normalise_cargo_lines"("lines" "jsonb", "require_complete" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "quote_api"."payload_has_content"("payload" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select
    quote_api.jsonb_has_content(
      coalesce(payload, '{}'::jsonb)
        - array[
            'sourceType', 'defaultMarkupPct', 'workflowVersion',
            'officeId', 'departmentId', 'salesOwnerId', 'charges'
          ]
    )
    or exists (
      select 1
      from jsonb_array_elements(coalesce(payload->'charges', '[]'::jsonb)) line
      where quote_api.jsonb_has_content(
        line - array[
          'showToCustomer', 'quantity', 'costRoe', 'sellRoe',
          'costAmount', 'sellAmount', 'costLocal', 'sellLocal',
          'defaultMarkupPct'
        ]
      )
      or abs(coalesce(nullif(line->>'costAmount', '')::numeric, 0)) > 0
      or abs(coalesce(nullif(line->>'sellAmount', '')::numeric, 0)) > 0
    );
$$;


ALTER FUNCTION "quote_api"."payload_has_content"("payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "quote_api"."prevent_submitted_quote_version_mutation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if tg_op = 'DELETE' then
    if old."CusQuoteVersion_IsSubmitted" then
      raise exception 'Submitted quote versions are immutable.' using errcode = '22023';
    end if;
    return old;
  end if;

  if old."CusQuoteVersion_IsSubmitted" and (
    new."Company_ID" is distinct from old."Company_ID"
    or new."CusQuoteHeader_ID" is distinct from old."CusQuoteHeader_ID"
    or new."CusQuoteVersion_Number" is distinct from old."CusQuoteVersion_Number"
    or new."CusQuoteVersion_SnapshotJSON" is distinct from old."CusQuoteVersion_SnapshotJSON"
    or new."CusQuoteVersion_CreatedAt" is distinct from old."CusQuoteVersion_CreatedAt"
    or new."CusQuoteVersion_CreatedBy" is distinct from old."CusQuoteVersion_CreatedBy"
    or not new."CusQuoteVersion_IsSubmitted"
    or new."CusQuoteVersion_SubmittedAt" is distinct from old."CusQuoteVersion_SubmittedAt"
    or new."CusQuoteVersion_SubmittedBy" is distinct from old."CusQuoteVersion_SubmittedBy"
  ) then
    raise exception 'Submitted quote versions are immutable.' using errcode = '22023';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "quote_api"."prevent_submitted_quote_version_mutation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "quote_api"."project_version_cargo"("requested_version_id" "uuid", "snapshot" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare lines jsonb;
begin
  -- This helper is not callable by any application role. A version trigger
  -- invokes it within the same save transaction, including draft collapsing.
  lines := quote_api.normalise_cargo_lines(coalesce(snapshot #> '{quote,shipmentFacts,cargoLines}', '[]'::jsonb));
  delete from quote_api.version_cargo_lines existing
    where version_id = requested_version_id
      and not exists(select 1 from jsonb_array_elements(lines) item where (item->>'id')::uuid = existing.line_id);
  insert into quote_api.version_cargo_lines as existing (
    version_id,line_id,line_number,description,commodity,package_quantity,package_type,
    gross_weight_kg,net_weight_kg,volume_cbm,chargeable_weight_kg,length,width,height,length_unit,
    hs_code,country_of_origin,is_hazardous,is_temperature_controlled
  )
  select requested_version_id,(item->>'id')::uuid,ordinality::integer,item->>'description',item->>'commodity',
    (item->>'packageQuantity')::numeric,item->>'packageType',(item->>'grossWeightKg')::numeric,
    (item->>'netWeightKg')::numeric,(item->>'volumeCbm')::numeric,(item->>'chargeableWeightKg')::numeric,
    (item->>'length')::numeric,(item->>'width')::numeric,(item->>'height')::numeric,item->>'lengthUnit',
    item->>'hsCode',item->>'countryOfOrigin',(item->>'isHazardous')::boolean,(item->>'isTemperatureControlled')::boolean
  from jsonb_array_elements(lines) with ordinality as cargo(item,ordinality)
  on conflict (version_id,line_id) do update set
    line_number=excluded.line_number,description=excluded.description,commodity=excluded.commodity,
    package_quantity=excluded.package_quantity,package_type=excluded.package_type,
    gross_weight_kg=excluded.gross_weight_kg,net_weight_kg=excluded.net_weight_kg,
    volume_cbm=excluded.volume_cbm,chargeable_weight_kg=excluded.chargeable_weight_kg,
    length=excluded.length,width=excluded.width,height=excluded.height,length_unit=excluded.length_unit,
    hs_code=excluded.hs_code,country_of_origin=excluded.country_of_origin,
    is_hazardous=excluded.is_hazardous,is_temperature_controlled=excluded.is_temperature_controlled
  where to_jsonb(existing) is distinct from to_jsonb(excluded);
end;
$$;


ALTER FUNCTION "quote_api"."project_version_cargo"("requested_version_id" "uuid", "snapshot" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "quote_api"."protect_discarded_draft"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if old."CusQuoteVersion_DiscardedAt" is not null then
    raise exception 'Discarded drafts are retained for audit and cannot be changed.' using errcode='22023';
  end if;
  if tg_op='UPDATE' and new."CusQuoteVersion_DiscardedAt" is not null
    and (new."CusQuoteVersion_IsSubmitted" or new."CusQuoteVersion_IsCurrent") then
    raise exception 'Only an unsent, inactive draft can be discarded.' using errcode='22023';
  end if;
  return case when tg_op='DELETE' then old else new end;
end;
$$;


