CREATE OR REPLACE FUNCTION "quote_api"."save_quote_before_cargo_safety_20260905"("caller_auth_user_id" "uuid", "requested_quote_id" "uuid", "payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  saved jsonb;
  saved_quote_id uuid;
  saved_version_id uuid;
  company_id uuid;
  effective_payer jsonb;
  previous_payer jsonb;
begin
  if requested_quote_id is not null then
    select jsonb_strip_nulls(jsonb_build_object(
      'orgId', party."CusQuoteParty_OrgID",
      'name', party."CusQuoteParty_NameSnapshot",
      'address', party."CusQuoteParty_AddressSnapshot",
      'contact', party."CusQuoteParty_ContactSnapshot",
      'email', quote."CusQuoteHeader_ShipmentFactsJSON"->>'payerEmail',
      'code', quote."CusQuoteHeader_ShipmentFactsJSON"->>'payerCode'
    )) into previous_payer
    from public."CusQuote_Parties" party
    join public."CusQuote_Header" quote
      on quote."CusQuoteHeader_ID" = party."CusQuoteHeader_ID"
    where party."CusQuoteHeader_ID" = requested_quote_id
      and party."CusQuoteParty_RoleCode" = 'payer';
  end if;

  effective_payer := case
    when payload ? 'payer' and jsonb_typeof(payload->'payer') = 'object'
      then payload->'payer'
    when previous_payer is not null then previous_payer
    else jsonb_strip_nulls(jsonb_build_object(
      'orgId', nullif(payload->>'customerId', ''),
      'name', nullif(btrim(payload->>'customerName'), ''),
      'address', nullif(btrim(payload#>>'{shipmentFacts,customerAddress}'), ''),
      'contact', nullif(btrim(payload->>'contactName'), ''),
      'email', nullif(btrim(payload->>'contactEmail'), ''),
      'code', nullif(btrim(payload#>>'{shipmentFacts,clientCode}'), '')
    ))
  end;

  saved := quote_api.save_quote_before_payer_20260904(
    caller_auth_user_id,
    requested_quote_id,
    payload
  );
  saved_quote_id := nullif(saved->>'quoteId', '')::uuid;
  saved_version_id := nullif(saved->>'versionId', '')::uuid;

  select app_user."Company_ID" into strict company_id
  from public."cmp_Users" app_user
  where app_user."Auth_User_ID" = caller_auth_user_id
    and app_user."User_AccessStatus" = 'active';

  delete from public."CusQuote_Parties"
  where "CusQuoteHeader_ID" = saved_quote_id
    and "CusQuoteParty_RoleCode" = 'payer';

  if quote_api.jsonb_has_content(effective_payer) then
    insert into public."CusQuote_Parties" (
      "Company_ID", "CusQuoteHeader_ID", "CusQuoteParty_RoleCode",
      "CusQuoteParty_OrgID", "CusQuoteParty_NameSnapshot",
      "CusQuoteParty_AddressSnapshot", "CusQuoteParty_ContactSnapshot"
    ) values (
      company_id, saved_quote_id, 'payer',
      nullif(effective_payer->>'orgId', '')::uuid,
      left(nullif(btrim(effective_payer->>'name'), ''), 240),
      nullif(btrim(effective_payer->>'address'), ''),
      left(nullif(btrim(effective_payer->>'contact'), ''), 180)
    );
  end if;

  update public."CusQuote_Header"
  set "CusQuoteHeader_ShipmentFactsJSON" = coalesce("CusQuoteHeader_ShipmentFactsJSON", '{}'::jsonb)
      || jsonb_strip_nulls(jsonb_build_object(
        'payerCode', nullif(btrim(effective_payer->>'code'), ''),
        'payerEmail', nullif(btrim(effective_payer->>'email'), '')
      ))
  where "CusQuoteHeader_ID" = saved_quote_id;

  if saved_version_id is not null then
    update public."CusQuote_Versions"
    set "CusQuoteVersion_SnapshotJSON" = jsonb_set(
      "CusQuoteVersion_SnapshotJSON",
      '{quote,payer}',
      coalesce(effective_payer, '{}'::jsonb),
      true
    )
    where "CusQuoteVersion_ID" = saved_version_id;
  end if;

  return saved;
end;
$$;


ALTER FUNCTION "quote_api"."save_quote_before_cargo_safety_20260905"("caller_auth_user_id" "uuid", "requested_quote_id" "uuid", "payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "quote_api"."save_quote_before_cargo_totals_20260905"("caller_auth_user_id" "uuid", "requested_quote_id" "uuid", "payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare facts jsonb := payload->'shipmentFacts';
begin
  if facts ? 'cargoLines' then
    facts := jsonb_set(facts, '{cargoCharacteristics}', to_jsonb(coalesce(
      nullif(btrim(facts->>'cargoCharacteristics'), ''), nullif(btrim(facts->>'knownCargo'), ''), 'General cargo'
    )));
    facts := jsonb_set(facts, '{knownCargo}', to_jsonb(quote_api.cargo_handling_summary(facts)));
    payload := jsonb_set(payload, '{shipmentFacts}', facts);
  end if;
  return quote_api.save_quote_before_cargo_safety_20260905(caller_auth_user_id, requested_quote_id, payload);
end $$;


ALTER FUNCTION "quote_api"."save_quote_before_cargo_totals_20260905"("caller_auth_user_id" "uuid", "requested_quote_id" "uuid", "payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "quote_api"."save_quote_before_payer_20260904"("caller_auth_user_id" "uuid", "requested_quote_id" "uuid", "payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  prior_version_id uuid;
  prior_version_number integer;
  prior_version_is_submitted boolean := false;
  prior_lifecycle text;
  prior_customer_id uuid;
  requested_customer_id uuid := nullif(payload ->> 'customerId', '')::uuid;
  transient_version_id uuid;
  transient_version record;
  saved jsonb;
begin
  if requested_quote_id is not null then
    select
      quote."CusQuoteHeader_LifecycleCode",
      quote."CusQuoteHeader_CustomerID"
      into prior_lifecycle, prior_customer_id
    from public."CusQuote_Header" quote
    where quote."CusQuoteHeader_ID" = requested_quote_id
      and not quote."CusQuoteHeader_IsDeleted";

    if prior_customer_id is not null
       and requested_customer_id is distinct from prior_customer_id then
      raise exception 'Changing the customer requires a separate quote number.'
        using errcode = '22023';
    end if;

    select version."CusQuoteVersion_ID",
      version."CusQuoteVersion_Number",
      version."CusQuoteVersion_IsSubmitted"
      into prior_version_id, prior_version_number, prior_version_is_submitted
    from public."CusQuote_Versions" version
    where version."CusQuoteHeader_ID" = requested_quote_id
      and version."CusQuoteVersion_IsCurrent"
    order by version."CusQuoteVersion_Number" desc
    limit 1;

    prior_version_is_submitted := coalesce(prior_version_is_submitted, false)
      or coalesce(prior_lifecycle in ('sent', 'accepted', 'declined', 'ghosted', 'changes_requested'), false)
      or exists (
        select 1
        from quote_api.customer_response_links link
        where link.quote_id = requested_quote_id
          and link.quote_version_id = prior_version_id
      )
      or exists (
        select 1
        from quote_api.customer_responses response
        where response.quote_id = requested_quote_id
          and response.quote_version_id = prior_version_id
      );
  end if;

  saved := quote_api.save_quote_legacy_20260903(caller_auth_user_id, requested_quote_id, payload);
  transient_version_id := nullif(saved ->> 'versionId', '')::uuid;

  if requested_quote_id is not null
     and prior_version_id is not null
     and not prior_version_is_submitted
     and transient_version_id is not null
     and transient_version_id <> prior_version_id then
    select version.* into strict transient_version
    from public."CusQuote_Versions" version
    where version."CusQuoteVersion_ID" = transient_version_id;

    update public."CusQuote_Versions"
    set "CusQuoteVersion_IsCurrent" = false
    where "CusQuoteVersion_ID" = transient_version_id;

    update public."CusQuote_Versions"
    set "CusQuoteVersion_SnapshotJSON" = transient_version."CusQuoteVersion_SnapshotJSON",
        "CusQuoteVersion_StatusCode" = 'draft',
        "CusQuoteVersion_IsCurrent" = true
    where "CusQuoteVersion_ID" = prior_version_id;

    delete from public."CusQuote_Events"
    where "CusQuoteVersion_ID" = transient_version_id
      and "CusQuoteEvent_TypeCode" in ('created', 'saved');

    delete from public."CusQuote_Versions"
    where "CusQuoteVersion_ID" = transient_version_id;

    return saved || jsonb_build_object(
      'versionId', prior_version_id,
      'versionNumber', prior_version_number,
      'versionState', 'draft'
    );
  end if;

  if transient_version_id is not null and not prior_version_is_submitted then
    update public."CusQuote_Versions"
    set "CusQuoteVersion_StatusCode" = 'draft',
        "CusQuoteVersion_IsSubmitted" = false,
        "CusQuoteVersion_SubmittedAt" = null,
        "CusQuoteVersion_SubmittedBy" = null
    where "CusQuoteVersion_ID" = transient_version_id;
    return saved || jsonb_build_object('versionState', 'draft');
  end if;

  if transient_version_id is not null then
    update public."CusQuote_Versions"
    set "CusQuoteVersion_StatusCode" = 'draft',
        "CusQuoteVersion_IsSubmitted" = false,
        "CusQuoteVersion_SubmittedAt" = null,
        "CusQuoteVersion_SubmittedBy" = null
    where "CusQuoteVersion_ID" = transient_version_id;
    return saved || jsonb_build_object('versionState', 'draft');
  end if;

  return saved;
end;
$$;


ALTER FUNCTION "quote_api"."save_quote_before_payer_20260904"("caller_auth_user_id" "uuid", "requested_quote_id" "uuid", "payload" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "quote_api"."save_quote_before_payer_20260904"("caller_auth_user_id" "uuid", "requested_quote_id" "uuid", "payload" "jsonb") IS 'Persists one mutable quote draft while preventing an established quote from being reassigned to another customer; create a separate master quote instead.';



CREATE OR REPLACE FUNCTION "quote_api"."save_quote_legacy_20260903"("caller_auth_user_id" "uuid", "requested_quote_id" "uuid", "payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  app_user record;
  existing_quote record;
  office_id uuid := nullif(payload->>'officeId', '')::uuid;
  department_id uuid := nullif(payload->>'departmentId', '')::uuid;
  sales_owner_id uuid := nullif(payload->>'salesOwnerId', '')::uuid;
  source_type text := nullif(lower(btrim(payload->>'sourceType')), '');
  source_id uuid := nullif(payload->>'sourceId', '')::uuid;
  customer_id uuid := nullif(payload->>'customerId', '')::uuid;
  customer_name text := nullif(btrim(payload->>'customerName'), '');
  contact_id uuid := nullif(payload->>'contactId', '')::uuid;
  contact_name text := nullif(btrim(payload->>'contactName'), '');
  contact_email text := nullif(btrim(payload->>'contactEmail'), '');
  supplier_id uuid := nullif(payload->>'supplierId', '')::uuid;
  supplier_name text := nullif(btrim(payload->>'supplierName'), '');
  carrier_id uuid := nullif(payload->>'carrierId', '')::uuid;
  carrier_name text := nullif(btrim(payload->>'carrierName'), '');
  quote_id uuid := requested_quote_id;
  quote_number integer;
  lifecycle text := 'draft';
  line jsonb;
  line_number integer := 0;
  version_number integer;
  version_id uuid;
  created_now boolean := requested_quote_id is null;
begin
  if caller_auth_user_id is null
     or not quote_api.has_permission(caller_auth_user_id, 'Quotes.Write') then
    raise exception 'Quote management is not authorised.' using errcode = '42501';
  end if;
  if not quote_api.payload_has_content(payload) then
    raise exception 'Add at least one quote detail before saving.' using errcode = '22023';
  end if;
  if source_type is not null and source_type not in ('account', 'lead') then
    raise exception 'Choose a supported quote source.' using errcode = '22023';
  end if;

  select "User_ID", "Company_ID"
  into strict app_user
  from public."cmp_Users"
  where "Auth_User_ID" = caller_auth_user_id
    and "User_AccessStatus" = 'active';

  if office_id is not null and not exists (
    select 1 from public."cmp_Offices"
    where "Office_ID" = office_id
      and "Company_ID" = app_user."Company_ID"
      and "Office_IsActive"
  ) then
    raise exception 'Choose an active office in this workspace.' using errcode = '22023';
  end if;
  if office_id is null then
    select "Office_ID" into office_id
    from public."cmp_Offices"
    where "Company_ID" = app_user."Company_ID" and "Office_IsActive"
    order by "Office_Name", "Office_ID"
    limit 1;
  end if;
  if office_id is null then
    raise exception 'This workspace has no active office.' using errcode = '22023';
  end if;

  if department_id is not null and not exists (
    select 1 from public."cmp_Departments"
    where "Department_ID" = department_id
      and "Company_ID" = app_user."Company_ID"
      and "Department_IsActive"
  ) then
    raise exception 'Choose an active department in this workspace.' using errcode = '22023';
  end if;
  if sales_owner_id is not null and not exists (
    select 1 from public."cmp_Users"
    where "User_ID" = sales_owner_id
      and "Company_ID" = app_user."Company_ID"
      and "User_AccessStatus" = 'active'
  ) then
    raise exception 'Choose an active sales representative in this workspace.' using errcode = '22023';
  end if;

  if source_type = 'lead' and source_id is not null then
    select lead."CRMLead_OrgID",
      coalesce(customer_name, nullif(btrim(lead."CRMLead_CompanyName"), ''), nullif(btrim(lead."CRMLead_PersonName"), '')),
      coalesce(nullif(btrim(payload->>'contactName'), ''), nullif(btrim(lead."CRMLead_PersonName"), '')),
      coalesce(nullif(btrim(payload->>'contactEmail'), ''), nullif(btrim(lead."CRMLead_Email"), ''))
    into customer_id, customer_name, contact_name, contact_email
    from public."CRM_Leads" lead
    left join public."cmp_Users" owner on owner."User_ID" = coalesce(lead."CRMLead_OwnerUserID", lead."CRMLead_CreatedBy")
    left join public."cmp_Offices" lead_office on lead_office."Office_ID" = lead."CRMLead_OrgOfficeID"
    where lead."CRMLead_ID" = source_id
      and not lead."CRMLead_IsDeleted"
      and coalesce(owner."Company_ID", lead_office."Company_ID") = app_user."Company_ID";
    if not found then
      raise exception 'That lead is outside this workspace.' using errcode = '42501';
    end if;
  elsif source_type = 'account' and source_id is not null then
    customer_id := source_id;
  end if;

  if customer_id is not null then
    select "Org_Name" into customer_name
    from public."Org_Master" where "Org_id" = customer_id;
    if not found then
      raise exception 'Choose a valid customer.' using errcode = '22023';
    end if;
  end if;
  if contact_id is not null and not exists (
    select 1 from public."Org_Contacts"
    where "OrgContact_ID" = contact_id
      and (customer_id is null or "Org_ID" = customer_id)
  ) then
    raise exception 'Choose a valid customer contact.' using errcode = '22023';
  end if;
  if supplier_id is not null then
    select "Org_Name" into supplier_name
    from public."Org_Master" where "Org_id" = supplier_id;
    if not found then raise exception 'Choose a valid supplier.' using errcode = '22023'; end if;
  end if;
  if carrier_id is not null then
    select "Org_Name" into carrier_name
    from public."Org_Master" where "Org_id" = carrier_id;
    if not found then raise exception 'Choose a valid carrier.' using errcode = '22023'; end if;
  end if;

  if quote_id is not null then
    select quote.* into existing_quote
    from public."CusQuote_Header" quote
    join public."cmp_Offices" quote_office
      on quote_office."Office_ID" = coalesce(quote."CusQuoteHeader_OrgOfficeID", quote."OrgOffice_ID")
    where quote."CusQuoteHeader_ID" = quote_id
      and quote_office."Company_ID" = app_user."Company_ID"
      and not quote."CusQuoteHeader_IsDeleted"
    for update;
    if not found then
      raise exception 'That quote is outside this workspace.' using errcode = '42501';
    end if;
    if coalesce(existing_quote."CusQuoteHeader_LifecycleCode", 'draft') = 'accepted' then
      raise exception 'An accepted quote cannot be edited.' using errcode = '22023';
    end if;
    quote_number := existing_quote."CusQuoteHeader_Number";
    lifecycle := case
      when existing_quote."CusQuoteHeader_LifecycleCode" in ('sent', 'declined', 'ghosted')
        then 'revised'
      else coalesce(existing_quote."CusQuoteHeader_LifecycleCode", 'draft')
    end;
  else
    quote_id := gen_random_uuid();
    quote_number := nextval('quote_api.quote_number_seq');
    insert into public."CusQuote_Header" (
      "CusQuoteHeader_ID", "CusQuoteHeader_Number", "CusQuoteHeader_CustomerID",
      "CusQuoteHeader_CreatedDate", "CusQuoteHeader_CreatedBy",
      "CusQuoteHeader_LastEditedDate", "CusQuoteHeader_LastEditedBy",
      "CusQuoteHeader_OrgOfficeID", "OrgOffice_ID", "Org_ID",
      "CusQuoteHeader_Status", "CusQuoteHeader_LifecycleCode",
      "CusQuoteHeader_WorkflowVersionCode"
    ) values (
      quote_id, quote_number, customer_id,
      now(), app_user."User_ID", now(), app_user."User_ID",
      office_id, office_id, app_user."Company_ID",
      1, 'draft', 'quotes-v1'
    );
  end if;

  update public."CusQuote_Header" set
    "CusQuoteHeader_CustomerID" = customer_id,
    "CusQuoteHeader_CustomerContact" = contact_id,
    "CusQuoteHeader_SourceTypeCode" = source_type,
    "CusQuoteHeader_SourceLeadID" = case when source_type = 'lead' then source_id end,
    "CusQuoteHeader_CustomerNameSnapshot" = left(customer_name, 240),
    "CusQuoteHeader_ContactNameSnapshot" = left(contact_name, 180),
    "CusQuoteHeader_ContactEmailSnapshot" = left(contact_email, 320),
    "CusQuoteHeader_CustomerReference" = left(nullif(btrim(payload->>'customerReference'), ''), 120),
    "CusQuoteHeader_DepartmentID" = department_id,
    "CusQuoteHeader_SalesOwnerID" = sales_owner_id,
    "CusQuoteHeader_ModeCode" = nullif(lower(btrim(payload->>'mode')), ''),
    "CusQuoteHeader_ShipmentTypeCode" = nullif(btrim(payload->>'shipmentType'), ''),
    "CusQuoteHeader_Direction" = nullif(lower(btrim(payload->>'direction')), ''),
    "CusQuoteHeader_ServiceLevel" = nullif(btrim(payload->>'serviceLevel'), ''),
    "CusQuoteHeader_CurrencyCode" = nullif(upper(btrim(payload->>'currency')), ''),
    "CusQuoteHeader_OriginExtra" = nullif(btrim(payload->>'loadingPoint'), ''),
    "CusQuoteHeader_DestinationExtra" = nullif(btrim(payload->>'dischargePoint'), ''),
    "CusQuoteHeader_CollectionAddress" = nullif(btrim(payload->>'collectionAddress'), ''),
    "CusQuoteHeader_LoadingPoint" = nullif(btrim(payload->>'loadingPoint'), ''),
    "CusQuoteHeader_DischargePoint" = nullif(btrim(payload->>'dischargePoint'), ''),
    "CusQuoteHeader_DeliveryAddress" = nullif(btrim(payload->>'deliveryAddress'), ''),
    "CusQuoteHeader_Incoterm" = nullif(upper(btrim(payload->>'incoterm')), ''),
    "CusQuoteHeader_ValidFrom" = nullif(payload->>'validFrom', '')::date,
    "CusQuoteHeader_ValidTo" = nullif(payload->>'validTo', '')::date,
    "CusQuoteHeader_Deadline" = nullif(payload->>'deadline', '')::timestamp,
    "CusQuoteHeader_SupplierID" = supplier_id,
    "CusQuoteHeader_SupplierNameSnapshot" = left(supplier_name, 240),
    "CusQuoteHeader_CarrierID" = carrier_id,
    "CusQuoteHeader_CarrierNameSnapshot" = left(carrier_name, 240),
    "CusQuoteHeader_ShipmentFactsJSON" = coalesce(payload->'shipmentFacts', '{}'::jsonb),
    "CusQuoteHeader_CustomerNotes" = nullif(btrim(payload->>'customerNotes'), ''),
    "CusQuoteHeader_InternalNotes" = nullif(btrim(payload->>'internalNotes'), ''),
    "CusQuoteHeader_TermsText" = nullif(btrim(payload->>'terms'), ''),
    "CusQuoteHeader_RateSourceTypeCode" = nullif(lower(btrim(payload->>'rateSourceType')), ''),
    "CusQuoteHeader_RateSourceLabel" = left(nullif(btrim(payload->>'rateSourceLabel'), ''), 240),
    "CusQuoteHeader_DefaultMarkupPct" = nullif(payload->>'defaultMarkupPct', '')::numeric,
    "CusQuoteHeader_MarkupOverrideReason" = nullif(btrim(payload->>'markupOverrideReason'), ''),
    "CusQuoteHeader_FollowUpAt" = nullif(payload->>'followUpAt', '')::timestamptz,
    "CusQuoteHeader_LifecycleCode" = lifecycle,
    "CusQuoteHeader_Status" = case lifecycle
      when 'calculated' then 2 when 'sent' then 4 when 'accepted' then 5
      when 'declined' then 6 when 'ghosted' then 7 else 1 end,
    "CusQuoteHeader_LastEditedBy" = app_user."User_ID",
    "CusQuoteHeader_LastEditedDate" = now(),
    "CusQuoteHeader_WorkflowVersionCode" = 'quotes-v1'
  where "CusQuoteHeader_ID" = quote_id;

  delete from public."CusQuote_Lines" where "CusQuoteHeader_ID" = quote_id;
  for line in select value from jsonb_array_elements(coalesce(payload->'charges', '[]'::jsonb)) loop
    if quote_api.jsonb_has_content(
      line - array['showToCustomer', 'quantity', 'costRoe', 'sellRoe']
    ) then
      line_number := line_number + 1;
      insert into public."CusQuote_Lines" (
        "CusQuoteHeader_ID", "CusQuoteLine_Number", "CusQuoteLine_SupplierID",
        "CusQuoteLine_Description", "CusQuoteLine_InternalNotes", "CusQuoteLine_CustomerNotes",
        "CusQuoteLine_CostROE", "CusQuoteLine_CostAmountCurrency", "CusQuoteLine_CostAmountLocal",
        "CusQuoteLine_RevenueROE", "CusQuoteLine_RevenueAmountCurrency", "CusQuoteLine_RevenueAmountLocal",
        "CusQuoteLine_ShowToCustomer", "CusQuoteLine_CostCurrencyCode",
        "CusQuoteLine_RevenueCurrencyCode", "CusQuoteLine_CalculationBasisCode",
        "CusQuoteLine_Quantity", "CusQuoteLine_UnitRate", "CusQuoteLine_MinimumAmount",
        "CusQuoteLine_DefaultMarkupPct", "CusQuoteLine_AppliedMarkupPct",
        "CusQuoteLine_MarkupOverrideReason", "CusQuoteLine_SourceLabel",
        "CusQuoteLine_CreatedBy", "CusQuoteLine_UpdatedBy"
      ) values (
        quote_id, line_number, nullif(line->>'supplierId', '')::uuid,
        left(coalesce(nullif(btrim(line->>'description'), ''), 'Charge'), 240),
        nullif(btrim(line->>'internalNotes'), ''), nullif(btrim(line->>'customerNotes'), ''),
        greatest(coalesce(nullif(line->>'costRoe', '')::numeric, 1), 0.00001),
        coalesce(nullif(line->>'costAmount', '')::numeric, 0),
        round(coalesce(nullif(line->>'costAmount', '')::numeric, 0)
          / greatest(coalesce(nullif(line->>'costRoe', '')::numeric, 1), 0.00001), 4),
        greatest(coalesce(nullif(line->>'sellRoe', '')::numeric, 1), 0.00001),
        coalesce(nullif(line->>'sellAmount', '')::numeric, 0),
        round(coalesce(nullif(line->>'sellAmount', '')::numeric, 0)
          / greatest(coalesce(nullif(line->>'sellRoe', '')::numeric, 1), 0.00001), 4),
        coalesce((line->>'showToCustomer')::boolean, true),
        nullif(upper(btrim(line->>'costCurrency')), ''),
        nullif(upper(btrim(line->>'sellCurrency')), ''),
        nullif(lower(btrim(line->>'calculationBasis')), ''),
        coalesce(nullif(line->>'quantity', '')::numeric, 1),
        nullif(line->>'unitRate', '')::numeric,
        nullif(line->>'minimumAmount', '')::numeric,
        nullif(line->>'defaultMarkupPct', '')::numeric,
        nullif(line->>'appliedMarkupPct', '')::numeric,
        nullif(btrim(line->>'markupOverrideReason'), ''),
        left(nullif(btrim(line->>'sourceLabel'), ''), 240),
        app_user."User_ID", app_user."User_ID"
      );
    end if;
  end loop;

  delete from public."CusQuote_Parties" where "CusQuoteHeader_ID" = quote_id;
  if quote_api.jsonb_has_content(payload->'shipper') then
    insert into public."CusQuote_Parties" (
      "Company_ID", "CusQuoteHeader_ID", "CusQuoteParty_RoleCode",
      "CusQuoteParty_OrgID", "CusQuoteParty_NameSnapshot",
      "CusQuoteParty_AddressSnapshot", "CusQuoteParty_ContactSnapshot"
    ) values (
      app_user."Company_ID", quote_id, 'shipper',
      nullif(payload#>>'{shipper,orgId}', '')::uuid,
      left(nullif(btrim(payload#>>'{shipper,name}'), ''), 240),
      nullif(btrim(payload#>>'{shipper,address}'), ''),
      left(nullif(btrim(payload#>>'{shipper,contact}'), ''), 180)
    );
  end if;
  if quote_api.jsonb_has_content(payload->'consignee') then
    insert into public."CusQuote_Parties" (
      "Company_ID", "CusQuoteHeader_ID", "CusQuoteParty_RoleCode",
      "CusQuoteParty_OrgID", "CusQuoteParty_NameSnapshot",
      "CusQuoteParty_AddressSnapshot", "CusQuoteParty_ContactSnapshot"
    ) values (
      app_user."Company_ID", quote_id, 'consignee',
      nullif(payload#>>'{consignee,orgId}', '')::uuid,
      left(nullif(btrim(payload#>>'{consignee,name}'), ''), 240),
      nullif(btrim(payload#>>'{consignee,address}'), ''),
      left(nullif(btrim(payload#>>'{consignee,contact}'), ''), 180)
    );
  end if;

  select coalesce(max("CusQuoteVersion_Number"), 0) + 1
  into version_number
  from public."CusQuote_Versions"
  where "CusQuoteHeader_ID" = quote_id;

  update public."CusQuote_Versions"
  set "CusQuoteVersion_IsCurrent" = false
  where "CusQuoteHeader_ID" = quote_id and "CusQuoteVersion_IsCurrent";

  insert into public."CusQuote_Versions" (
    "Company_ID", "CusQuoteHeader_ID", "CusQuoteVersion_Number",
    "CusQuoteVersion_StatusCode", "CusQuoteVersion_SnapshotJSON",
    "CusQuoteVersion_IsCurrent", "CusQuoteVersion_CreatedBy"
  ) values (
    app_user."Company_ID", quote_id, version_number, lifecycle,
    jsonb_build_object(
      'reference', 'Q-' || quote_number,
      'lifecycle', lifecycle,
      'quote', payload,
      'savedAt', now()
    ),
    true, app_user."User_ID"
  )
  returning "CusQuoteVersion_ID" into version_id;

  insert into public."CusQuote_Events" (
    "Company_ID", "CusQuoteHeader_ID", "CusQuoteVersion_ID",
    "CusQuoteEvent_TypeCode", "CusQuoteEvent_Summary",
    "CusQuoteEvent_MetadataJSON", "CusQuoteEvent_ActorUserID"
  ) values (
    app_user."Company_ID", quote_id, version_id,
    case when created_now then 'created' else 'saved' end,
    case when created_now then 'Quote created.' else 'Quote changes saved.' end,
    jsonb_build_object('versionNumber', version_number),
    app_user."User_ID"
  );

  return jsonb_build_object(
    'quoteId', quote_id,
    'reference', 'Q-' || quote_number,
    'lifecycle', lifecycle,
    'versionId', version_id
  );
exception
  when no_data_found or too_many_rows then
    raise exception 'User identity is incomplete or ambiguous.' using errcode = '42501';
end;
$$;


ALTER FUNCTION "quote_api"."save_quote_legacy_20260903"("caller_auth_user_id" "uuid", "requested_quote_id" "uuid", "payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "quote_api"."schedule_customer_follow_up"("requested_response_link_id" "uuid") RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  link_row quote_api.customer_response_links%rowtype;
  quote_row public."CusQuote_Header"%rowtype;
  settings_row quote_api.reference_settings%rowtype;
  payer_org_id uuid;
  payer_metadata jsonb := '{}'::jsonb;
  allow_follow_up boolean := true;
  minimum_hours integer := 24;
  delay_days integer;
  due_at timestamptz;
begin
  select * into link_row from quote_api.customer_response_links
  where response_link_id = requested_response_link_id for update;
  if not found then raise exception 'That quote response link could not be found.' using errcode = 'P0002'; end if;
  select * into quote_row from public."CusQuote_Header"
  where "CusQuoteHeader_ID" = link_row.quote_id and not "CusQuoteHeader_IsDeleted";
  if not found then return null; end if;
  select * into settings_row from quote_api.reference_settings where company_id = link_row.company_id;
  select coalesce(party."CusQuoteParty_OrgID", quote_row."CusQuoteHeader_CustomerID") into payer_org_id
  from (select 1) seed
  left join public."CusQuote_Parties" party
    on party."CusQuoteHeader_ID" = link_row.quote_id
   and party."CusQuoteParty_RoleCode" = 'payer'
  limit 1;
  select coalesce(profile."CRMAccount_MetadataJSON", '{}'::jsonb) into payer_metadata
  from public."CRM_AccountProfiles" profile
  where profile."CRMAccount_OrgID" = payer_org_id;
  select coalesce(preference."CRMCustEngPref_AllowFollowupMessages", true),
         greatest(0, coalesce(preference."CRMCustEngPref_MinHoursBetweenNonUrgentMessages", 24))
    into allow_follow_up, minimum_hours
  from (select 1) seed
  left join public."CRM_CustomerEngagementPreferences" preference
    on preference."CRMCustEngPref_CustomerOrgID" = payer_org_id
  limit 1;

  if not coalesce(settings_row.quote_follow_up_enabled, true)
     or not coalesce(allow_follow_up, true)
     or link_row.delivery_mailbox_id is null
     or link_row.delivery_provider_id is null then
    update quote_api.customer_response_links set
      follow_up_status_code = 'not_scheduled', follow_up_next_attempt_at = null,
      follow_up_error = case
        when not coalesce(allow_follow_up, true) then 'Customer follow-up messages are disabled.'
        when link_row.delivery_mailbox_id is null or link_row.delivery_provider_id is null then 'The sending mailbox could not be resolved.'
        else null
      end
    where response_link_id = requested_response_link_id;
    update public."CusQuote_Header" set "CusQuoteHeader_FollowUpAt" = null
    where "CusQuoteHeader_ID" = link_row.quote_id;
    return null;
  end if;

  delay_days := case
    when payer_metadata #>> '{quoteTerms,followUpDays}' ~ '^[0-9]+$'
      then least(30, greatest(1, (payer_metadata #>> '{quoteTerms,followUpDays}')::integer))
    else coalesce(settings_row.quote_follow_up_delay_days, 3)
  end;
  due_at := greatest(
    quote_api.follow_up_due_at(
      link_row.created_at, delay_days,
      coalesce(settings_row.quote_follow_up_send_time, time '09:00'),
      coalesce(settings_row.quote_follow_up_timezone, 'Europe/London')
    ),
    link_row.created_at + make_interval(hours => minimum_hours)
  );
  update quote_api.customer_response_links set
    follow_up_status_code = 'pending', follow_up_attempt_count = 0,
    follow_up_next_attempt_at = due_at, follow_up_sent_at = null,
    follow_up_delivery_provider_id = null, follow_up_error = null,
    follow_up_lease_token = null, follow_up_lease_expires_at = null
  where response_link_id = requested_response_link_id;
  update public."CusQuote_Header" set "CusQuoteHeader_FollowUpAt" = due_at
  where "CusQuoteHeader_ID" = link_row.quote_id;
  return due_at;
end;
$_$;


ALTER FUNCTION "quote_api"."schedule_customer_follow_up"("requested_response_link_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "quote_api"."submit_customer_response"("requested_token_hash" "text", "requested_response_origin" "text", "requested_decision" "text", "requested_message" "text" DEFAULT NULL::"text", "requested_competitor_document_id" "uuid" DEFAULT NULL::"uuid", "requested_source_ip_hash" "text" DEFAULT NULL::"text", "requested_user_agent" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select quote_api.submit_customer_response(
    requested_token_hash,
    requested_response_origin,
    requested_decision,
    requested_message,
    requested_competitor_document_id,
    requested_source_ip_hash,
    requested_user_agent,
    case when lower(btrim(coalesce(requested_decision, ''))) = 'declined' then 'other' end
  )
$$;


ALTER FUNCTION "quote_api"."submit_customer_response"("requested_token_hash" "text", "requested_response_origin" "text", "requested_decision" "text", "requested_message" "text", "requested_competitor_document_id" "uuid", "requested_source_ip_hash" "text", "requested_user_agent" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "quote_api"."submit_customer_response"("requested_token_hash" "text", "requested_response_origin" "text", "requested_decision" "text", "requested_message" "text" DEFAULT NULL::"text", "requested_competitor_document_id" "uuid" DEFAULT NULL::"uuid", "requested_source_ip_hash" "text" DEFAULT NULL::"text", "requested_user_agent" "text" DEFAULT NULL::"text", "requested_decline_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  link_row record;
  quote_row record;
  response_id_value uuid;
  decision_value text := lower(btrim(coalesce(requested_decision, '')));
  decline_reason_value text := lower(btrim(coalesce(requested_decline_reason, '')));
  lifecycle_value text;
  booking_result jsonb;
  owner_user_id uuid;
begin
  if decision_value not in ('accepted', 'declined', 'challenged') then
    raise exception 'Choose accept, decline or request changes.' using errcode = '22023';
  end if;
  if decision_value = 'challenged' and nullif(btrim(requested_message), '') is null then
    raise exception 'Tell us what you would like us to review.' using errcode = '22023';
  end if;
  if decision_value = 'declined' and decline_reason_value not in (
    'cost_too_high',
    'estimated_times_too_late',
    'found_cheaper_quote',
    'research_only',
    'job_no_longer_needed',
    'other'
  ) then
    raise exception 'Choose the main reason for declining this quote.' using errcode = '22023';
  end if;
  if decision_value <> 'declined' and decline_reason_value <> '' then
    raise exception 'A decline reason can only be supplied when declining a quote.' using errcode = '22023';
  end if;
  if requested_source_ip_hash is not null and requested_source_ip_hash !~ '^[0-9a-f]{64}$' then
    raise exception 'The response audit fingerprint is invalid.' using errcode = '22023';
  end if;

  select link.* into link_row
  from quote_api.customer_response_links link
  where link.token_hash = requested_token_hash
  for update;
  if not found then raise exception 'This quote link is invalid.' using errcode = 'P0002'; end if;
  if link_row.response_origin is distinct from requested_response_origin then
    raise exception 'This quote link is not available on this workspace.' using errcode = 'P0002';
  end if;
  if link_row.status_code <> 'active' then raise exception 'This quote link has already been used or revoked.' using errcode = '22023'; end if;
  if link_row.expires_at is not null and link_row.expires_at <= now() then
    update quote_api.customer_response_links set status_code = 'expired' where response_link_id = link_row.response_link_id;
    raise exception 'This quote link has expired.' using errcode = '22023';
  end if;
  if requested_competitor_document_id is not null and not exists (
    select 1 from public."DOC_StoredObjects" stored
    where stored."DOCStoredObject_ID" = requested_competitor_document_id
      and stored."DOCStoredObject_ConcernCode" = 'quote_response'
      and stored."DOCStoredObject_AggregateType" = 'quote_customer_response_link'
      and stored."DOCStoredObject_AggregateID" = link_row.response_link_id
      and stored."DOCStoredObject_StatusCode" = 'active'
  ) then
    raise exception 'The competitor quote attachment is unavailable.' using errcode = '22023';
  end if;

  select quote.* into quote_row
  from public."CusQuote_Header" quote
  where quote."CusQuoteHeader_ID" = link_row.quote_id
    and not quote."CusQuoteHeader_IsDeleted"
  for update;
  if not found then raise exception 'This quote is no longer available.' using errcode = 'P0002'; end if;
  if quote_row."CusQuoteHeader_LifecycleCode" not in ('sent', 'calculated', 'revised') then
    raise exception 'This quote already has a final outcome.' using errcode = '22023';
  end if;

  insert into quote_api.customer_responses (
    company_id, response_link_id, quote_id, quote_version_id, decision_code,
    customer_message, decline_reason_code, competitor_document_id, source_ip_hash, user_agent_summary
  ) values (
    link_row.company_id, link_row.response_link_id, link_row.quote_id, link_row.quote_version_id,
    decision_value, nullif(btrim(requested_message), ''),
    case when decision_value = 'declined' then decline_reason_value end,
    requested_competitor_document_id, requested_source_ip_hash, left(nullif(btrim(requested_user_agent), ''), 500)
  ) returning response_id into response_id_value;

  update quote_api.customer_response_links
  set status_code = 'responded', responded_at = now()
  where response_link_id = link_row.response_link_id;

  lifecycle_value := case decision_value
    when 'accepted' then 'accepted'
    when 'declined' then 'declined'
    else 'revised'
  end;
  update public."CusQuote_Header" set
    "CusQuoteHeader_LifecycleCode" = lifecycle_value,
    "CusQuoteHeader_Status" = case lifecycle_value when 'accepted' then 5 when 'declined' then 6 else 1 end,
    "CusQuoteHeader_AcceptedVersionID" = case when decision_value = 'accepted' then link_row.quote_version_id else null end,
    "CusQuoteHeader_OutcomeNotes" = case
      when decision_value = 'declined' then coalesce(nullif(btrim(requested_message), ''), decline_reason_value)
      else nullif(btrim(requested_message), '')
    end,
    "CusQuoteHeader_LastEditedDate" = now()
  where "CusQuoteHeader_ID" = link_row.quote_id;

  insert into public."CusQuote_Events" (
    "Company_ID", "CusQuoteHeader_ID", "CusQuoteVersion_ID", "CusQuoteEvent_TypeCode",
    "CusQuoteEvent_Summary", "CusQuoteEvent_MetadataJSON", "CusQuoteEvent_ActorUserID"
  ) values (
    link_row.company_id, link_row.quote_id, link_row.quote_version_id,
    'customer_' || decision_value,
    case decision_value
      when 'accepted' then 'Customer accepted the quote.'
      when 'declined' then 'Customer declined the quote.'
      else 'Customer requested changes to the quote.'
    end,
    jsonb_strip_nulls(jsonb_build_object(
      'responseId', response_id_value,
      'message', nullif(btrim(requested_message), ''),
      'declineReasonCode', case when decision_value = 'declined' then decline_reason_value end,
      'competitorDocumentId', requested_competitor_document_id
    )),
    null
  );

  if decision_value = 'accepted' then
    booking_result := booking_api.convert_accepted_quote(link_row.quote_id, quote_row."CusQuoteHeader_SalesOwnerID", response_id_value);
  end if;

  owner_user_id := coalesce(quote_row."CusQuoteHeader_SalesOwnerID", quote_row."CusQuoteHeader_CreatedBy");
  if owner_user_id is not null then
    insert into public."Comm_Notifications" (
      "CommNotif_UserID", "CommNotif_Title", "CommNotif_Body", "CommNotif_TargetTable",
      "CommNotif_TargetID", "CommNotif_LinkTypeCode", "CommNotif_MetadataJSON", "CommNotif_CreatedBy"
    ) values (
      owner_user_id,
      coalesce(quote_row."CusQuoteHeader_CustomerReference", 'Q-' || quote_row."CusQuoteHeader_Number") || ' customer response',
      case decision_value
        when 'accepted' then 'The customer accepted this quote. Its booking is ready.'
        when 'declined' then 'The customer declined this quote and supplied a reason.'
        else 'The customer asked for changes to this quote.'
      end,
      'CusQuote_Header', link_row.quote_id, 'quote_response',
      jsonb_build_object(
        'event_type', 'quote_response',
        'action_url', '/quotes/' || coalesce(quote_row."CusQuoteHeader_CustomerReference", 'Q-' || quote_row."CusQuoteHeader_Number"),
        'action_label', 'Open quote',
        'eyebrow', 'Customer quote response',
        'decision', decision_value,
        'decline_reason_code', case when decision_value = 'declined' then decline_reason_value end,
        'response_id', response_id_value
      ),
      null
    );
  end if;

  return jsonb_strip_nulls(jsonb_build_object(
    'state', 'responded',
    'decision', decision_value,
    'declineReasonCode', case when decision_value = 'declined' then decline_reason_value end,
    'responseId', response_id_value,
    'booking', booking_result
  ));
end;
$_$;


ALTER FUNCTION "quote_api"."submit_customer_response"("requested_token_hash" "text", "requested_response_origin" "text", "requested_decision" "text", "requested_message" "text", "requested_competitor_document_id" "uuid", "requested_source_ip_hash" "text", "requested_user_agent" "text", "requested_decline_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "quote_api"."sync_quote_after_customer_response"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  lifecycle_value text := case new.decision_code
    when 'accepted' then 'accepted'
    when 'declined' then 'declined'
    else 'changes_requested'
  end;
  version_status text := case new.decision_code
    when 'accepted' then 'accepted'
    when 'declined' then 'declined'
    else 'changes_requested'
  end;
begin
  update public."CusQuote_Versions"
  set "CusQuoteVersion_IsSubmitted" = true,
      "CusQuoteVersion_SubmittedAt" = coalesce("CusQuoteVersion_SubmittedAt", new.created_at),
      "CusQuoteVersion_StatusCode" = version_status
  where "CusQuoteVersion_ID" = new.quote_version_id
    and "CusQuoteHeader_ID" = new.quote_id;

  update public."CusQuote_Header" quote
  set "CusQuoteHeader_LifecycleCode" = lifecycle_value,
      "CusQuoteHeader_Status" = case lifecycle_value when 'accepted' then 5 when 'declined' then 6 else 1 end,
      "CusQuoteHeader_AcceptedVersionID" = coalesce(
        (
          select response.quote_version_id
          from quote_api.customer_responses response
          where response.quote_id = new.quote_id
            and response.decision_code = 'accepted'
          order by response.created_at desc
          limit 1
        ),
        quote."CusQuoteHeader_AcceptedVersionID"
      ),
      "CusQuoteHeader_LastEditedDate" = now()
  where quote."CusQuoteHeader_ID" = new.quote_id;

  return new;
end;
$$;


ALTER FUNCTION "quote_api"."sync_quote_after_customer_response"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "quote_api"."sync_version_cargo"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if tg_op = 'UPDATE' and new."CusQuoteVersion_SnapshotJSON" = old."CusQuoteVersion_SnapshotJSON" then return new; end if;
  perform quote_api.project_version_cargo(new."CusQuoteVersion_ID",new."CusQuoteVersion_SnapshotJSON");
  return new;
end;
$$;


ALTER FUNCTION "quote_api"."sync_version_cargo"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "quote_api"."synchronise_company_references"("workspace_company_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'quote_api'
    AS $$
declare
  duplicate_reference text;
  too_long_reference text;
  settings_row quote_api.reference_settings%rowtype;
begin
  if workspace_company_id is null then raise exception 'A workspace company is required.' using errcode = '42501'; end if;
  perform pg_advisory_xact_lock(hashtextextended(workspace_company_id::text || ':reference-sync', 0));
  select * into strict settings_row from quote_api.reference_settings where company_id = workspace_company_id for update;

  update public."Job_Header" job
  set "Job_BookingReferenceSequenceKey" = 'default'
  from public."cmp_Offices" office
  where office."Office_ID" = coalesce(job."Job_OrgOfficeID", job."Job_OfficeID")
    and office."Company_ID" = workspace_company_id
    and not job."Job_IsDeleted"
    and not exists (
      select 1 from quote_api.booking_reference_sequences sequence
      where sequence.company_id = workspace_company_id
        and sequence.sequence_key = job."Job_BookingReferenceSequenceKey"
        and sequence.enabled
    );

  create temp table if not exists pg_temp.multideck_reference_sync_plan (
    reference_kind text not null,
    source_id uuid not null,
    old_reference text,
    new_reference text not null,
    primary key (reference_kind, source_id)
  ) on commit drop;
  truncate pg_temp.multideck_reference_sync_plan;

  insert into pg_temp.multideck_reference_sync_plan
  select 'quote', quote."CusQuoteHeader_ID", quote."CusQuoteHeader_CustomerReference",
    quote_api.render_reference_pattern(settings_row.quote_pattern, quote."CusQuoteHeader_ReferenceSequenceValue", workspace_company_id)
  from public."CusQuote_Header" quote
  left join public."cmp_Offices" office on office."Office_ID" = coalesce(quote."CusQuoteHeader_OrgOfficeID", quote."OrgOffice_ID")
  where coalesce(office."Company_ID", quote."Org_ID") = workspace_company_id and not quote."CusQuoteHeader_IsDeleted";

  insert into pg_temp.multideck_reference_sync_plan
  select 'booking', job."Job_ID", job."Job_BookingReference",
    case
      -- Legacy bookings may not have enough shipment details to establish direction.
      -- Keep their existing identity until direction is known; never invent I/E/D/C.
      when sequence.pattern ~ '\{DIRECTION(?::[0-9]{1,2})?\}'
        and lower(replace(replace(btrim(coalesce(job."Job_Direction", '')), '-', '_'), ' ', '_'))
          not in ('import', 'export', 'domestic', 'cross_trade')
        and nullif(btrim(job."Job_BookingReference"), '') is not null
      then job."Job_BookingReference"
      else quote_api.render_reference_pattern(sequence.pattern, job."Job_BookingReferenceSequenceValue", workspace_company_id, job."Job_Direction")
    end
  from public."Job_Header" job
  join public."cmp_Offices" office on office."Office_ID" = coalesce(job."Job_OrgOfficeID", job."Job_OfficeID")
  join quote_api.booking_reference_sequences sequence
    on sequence.company_id = workspace_company_id
   and sequence.sequence_key = job."Job_BookingReferenceSequenceKey" and sequence.enabled
  where office."Company_ID" = workspace_company_id and not job."Job_IsDeleted";

  insert into pg_temp.multideck_reference_sync_plan
  select 'customer', organisation."Org_id", organisation."Org_AccCode",
    case
      when coalesce(profile."CRMAccount_ReferenceSequenceValue", 0) < 1
        and nullif(btrim(organisation."Org_AccCode"), '') is not null
      then organisation."Org_AccCode"
      else quote_api.render_reference_pattern(settings_row.customer_pattern, profile."CRMAccount_ReferenceSequenceValue", workspace_company_id)
    end
  from public."CRM_AccountProfiles" profile
  join public."Org_Master" organisation on organisation."Org_id" = profile."CRMAccount_OrgID"
  where profile."CRMAccount_CompanyID" = workspace_company_id and not profile."CRMAccount_IsDeleted";

  select upper(btrim(new_reference)) into duplicate_reference
  from pg_temp.multideck_reference_sync_plan
  group by upper(btrim(new_reference)) having count(*) > 1 limit 1;
  if duplicate_reference is not null then
    raise exception 'The reference rules would create the duplicate reference %.', duplicate_reference using errcode = '23505';
  end if;
  select new_reference into too_long_reference from pg_temp.multideck_reference_sync_plan
  where new_reference is distinct from old_reference
    and (length(new_reference) > 120 or (reference_kind = 'booking' and length(new_reference) > 80)
      or (reference_kind = 'customer' and length(new_reference) > 8)) limit 1;
  if too_long_reference is not null then
    raise exception 'The generated reference % is too long for that record type.', too_long_reference using errcode = '22023';
  end if;
  select new_plan.new_reference into duplicate_reference
  from pg_temp.multideck_reference_sync_plan old_plan
  join pg_temp.multideck_reference_sync_plan new_plan
    on upper(btrim(old_plan.old_reference)) = upper(btrim(new_plan.new_reference))
   and (old_plan.source_id <> new_plan.source_id or old_plan.reference_kind <> new_plan.reference_kind)
  where nullif(btrim(old_plan.old_reference), '') is not null
    and upper(btrim(old_plan.old_reference)) <> upper(btrim(old_plan.new_reference))
  limit 1;
  if duplicate_reference is not null then
    raise exception 'The reference % must remain available as an old link for another record.', duplicate_reference using errcode = '23505';
  end if;
  select plan.new_reference into duplicate_reference
  from pg_temp.multideck_reference_sync_plan plan
  join quote_api.reference_aliases alias
    on alias.company_id = workspace_company_id and alias.normalized_alias = upper(btrim(plan.new_reference))
   and (alias.source_id <> plan.source_id or alias.reference_kind <> plan.reference_kind)
  limit 1;
  if duplicate_reference is not null then
    raise exception 'The reference % is already kept as an old link for another record.', duplicate_reference using errcode = '23505';
  end if;
  select plan.old_reference into duplicate_reference
  from pg_temp.multideck_reference_sync_plan plan
  join quote_api.reference_aliases alias
    on alias.company_id = workspace_company_id and alias.normalized_alias = upper(btrim(plan.old_reference))
   and (alias.source_id <> plan.source_id or alias.reference_kind <> plan.reference_kind)
  where nullif(btrim(plan.old_reference), '') is not null
    and upper(btrim(plan.old_reference)) <> upper(btrim(plan.new_reference))
  limit 1;
  if duplicate_reference is not null then
    raise exception 'The old reference % already belongs to another saved link.', duplicate_reference using errcode = '23505';
  end if;

  insert into quote_api.reference_aliases (
    company_id, normalized_alias, alias_value, reference_kind, source_id, canonical_reference
  )
  select workspace_company_id, upper(btrim(old_reference)), btrim(old_reference), reference_kind, source_id, new_reference
  from pg_temp.multideck_reference_sync_plan
  where nullif(btrim(old_reference), '') is not null and upper(btrim(old_reference)) <> upper(btrim(new_reference))
  on conflict (company_id, normalized_alias) do update set canonical_reference = excluded.canonical_reference
  where quote_api.reference_aliases.reference_kind = excluded.reference_kind
    and quote_api.reference_aliases.source_id = excluded.source_id;

  update quote_api.reference_aliases alias set canonical_reference = plan.new_reference
  from pg_temp.multideck_reference_sync_plan plan
  where alias.company_id = workspace_company_id and alias.reference_kind = plan.reference_kind and alias.source_id = plan.source_id;

  perform set_config('multideck.reference_sync', 'on', true);
  update public."CusQuote_Header" quote
  set "CusQuoteHeader_CustomerReference" = plan.new_reference
  from pg_temp.multideck_reference_sync_plan plan
  where plan.reference_kind = 'quote' and plan.source_id = quote."CusQuoteHeader_ID"
    and quote."CusQuoteHeader_CustomerReference" is distinct from plan.new_reference;
  update public."Job_Header" job
  set "Job_BookingReference" = plan.new_reference, "Job_UpdatedAt" = now()
  from pg_temp.multideck_reference_sync_plan plan
  where plan.reference_kind = 'booking' and plan.source_id = job."Job_ID"
    and job."Job_BookingReference" is distinct from plan.new_reference;
  update public."Org_Master" organisation
  set "Org_AccCode" = plan.new_reference
  from pg_temp.multideck_reference_sync_plan plan
  where plan.reference_kind = 'customer' and plan.source_id = organisation."Org_id"
    and organisation."Org_AccCode" is distinct from plan.new_reference;

  delete from quote_api.reference_reservations where company_id = workspace_company_id;
  insert into quote_api.reference_reservations (company_id, normalized_reference, reference_value, reference_kind, source_id)
  select workspace_company_id, upper(btrim(new_reference)), new_reference, reference_kind, source_id
  from pg_temp.multideck_reference_sync_plan;
  insert into quote_api.reference_reservations (company_id, normalized_reference, reference_value, reference_kind, source_id)
  select alias.company_id, alias.normalized_alias, alias.alias_value, alias.reference_kind, alias.source_id
  from quote_api.reference_aliases alias where alias.company_id = workspace_company_id
  on conflict (company_id, normalized_reference) do nothing;

  update quote_api.reference_settings settings set
    quote_next_number = greatest(settings.quote_next_number, coalesce((select max(quote."CusQuoteHeader_ReferenceSequenceValue") + 1
      from public."CusQuote_Header" quote left join public."cmp_Offices" office on office."Office_ID" = coalesce(quote."CusQuoteHeader_OrgOfficeID", quote."OrgOffice_ID")
      where coalesce(office."Company_ID", quote."Org_ID") = workspace_company_id and not quote."CusQuoteHeader_IsDeleted"), 1)),
    customer_next_number = greatest(settings.customer_next_number, coalesce((select max(profile."CRMAccount_ReferenceSequenceValue") + 1
      from public."CRM_AccountProfiles" profile where profile."CRMAccount_CompanyID" = workspace_company_id and not profile."CRMAccount_IsDeleted"), 1)),
    updated_at = now()
  where settings.company_id = workspace_company_id;
  update quote_api.booking_reference_sequences sequence set
    next_number = greatest(sequence.next_number, coalesce((select max(job."Job_BookingReferenceSequenceValue") + 1
      from public."Job_Header" job join public."cmp_Offices" office on office."Office_ID" = coalesce(job."Job_OrgOfficeID", job."Job_OfficeID")
      where office."Company_ID" = workspace_company_id and not job."Job_IsDeleted"
        and job."Job_BookingReferenceSequenceKey" = sequence.sequence_key), 1)),
    updated_at = now()
  where sequence.company_id = workspace_company_id;
end;
$$;


ALTER FUNCTION "quote_api"."synchronise_company_references"("workspace_company_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "quote_api"."transition_quote"("caller_auth_user_id" "uuid", "requested_quote_id" "uuid", "requested_transition" "text", "requested_note" "text" DEFAULT NULL::"text", "requested_follow_up_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  app_user record;
  quote_row record;
  current_version record;
  outcome_version record;
  selected_version_id uuid;
  selected_version_number integer;
  next_lifecycle text := lower(btrim(requested_transition));
begin
  if caller_auth_user_id is null
     or not quote_api.has_permission(caller_auth_user_id, 'Quotes.Write') then
    raise exception 'Quote management is not authorised.' using errcode = '42501';
  end if;
  if next_lifecycle not in ('calculated', 'sent', 'revised', 'accepted', 'declined', 'ghosted') then
    raise exception 'Choose a supported quote action.' using errcode = '22023';
  end if;
  if next_lifecycle = 'declined' and nullif(btrim(requested_note), '') is null then
    raise exception 'Choose why this quote was lost.' using errcode = '22023';
  end if;

  select "User_ID", "Company_ID" into strict app_user
  from public."cmp_Users"
  where "Auth_User_ID" = caller_auth_user_id and "User_AccessStatus" = 'active';

  select quote.* into quote_row
  from public."CusQuote_Header" quote
  join public."cmp_Offices" office
    on office."Office_ID" = coalesce(quote."CusQuoteHeader_OrgOfficeID", quote."OrgOffice_ID")
  where quote."CusQuoteHeader_ID" = requested_quote_id
    and office."Company_ID" = app_user."Company_ID"
    and not quote."CusQuoteHeader_IsDeleted"
  for update;
  if not found then
    raise exception 'That quote is outside this workspace.' using errcode = '42501';
  end if;
  if coalesce(quote_row."CusQuoteHeader_LifecycleCode", 'draft') = 'accepted'
     and next_lifecycle <> 'declined' then
    raise exception 'An accepted quote can only be marked lost.' using errcode = '22023';
  end if;

  select version.* into current_version
  from public."CusQuote_Versions" version
  where version."CusQuoteHeader_ID" = requested_quote_id
    and version."CusQuoteVersion_IsCurrent"
  limit 1;

  if next_lifecycle in ('accepted', 'declined') then
    select version.* into outcome_version
    from public."CusQuote_Versions" version
    where version."CusQuoteHeader_ID" = requested_quote_id
      and version."CusQuoteVersion_IsSubmitted"
    order by version."CusQuoteVersion_SubmittedAt" desc nulls last,
      version."CusQuoteVersion_Number" desc
    limit 1
    for update;
  end if;

  if next_lifecycle = 'accepted' and outcome_version."CusQuoteVersion_ID" is null then
    raise exception 'Submit the quote before recording customer acceptance.' using errcode = '22023';
  end if;
  if next_lifecycle = 'accepted'
     and outcome_version."CusQuoteVersion_StatusCode" in ('declined', 'changes_requested') then
    raise exception 'Create and submit a new quote version before recording fresh customer acceptance.' using errcode = '22023';
  end if;

  selected_version_id := coalesce(outcome_version."CusQuoteVersion_ID", current_version."CusQuoteVersion_ID");
  selected_version_number := coalesce(outcome_version."CusQuoteVersion_Number", current_version."CusQuoteVersion_Number");
  if selected_version_id is null then
    raise exception 'The quote version is unavailable.' using errcode = 'P0002';
  end if;

  if outcome_version."CusQuoteVersion_ID" is not null then
    update public."CusQuote_Versions"
    set "CusQuoteVersion_StatusCode" = case next_lifecycle
      when 'accepted' then 'accepted'
      when 'declined' then 'declined'
      else "CusQuoteVersion_StatusCode"
    end
    where "CusQuoteVersion_ID" = outcome_version."CusQuoteVersion_ID";
  end if;

  update public."CusQuote_Header" set
    "CusQuoteHeader_LifecycleCode" = next_lifecycle,
    "CusQuoteHeader_Status" = case next_lifecycle
      when 'calculated' then 2 when 'sent' then 4 when 'accepted' then 5
      when 'declined' then 6 when 'ghosted' then 7 else 1 end,
    "CusQuoteHeader_OutcomeNotes" = case
      when next_lifecycle in ('accepted', 'declined', 'ghosted')
        then nullif(btrim(requested_note), '')
      else "CusQuoteHeader_OutcomeNotes" end,
    "CusQuoteHeader_FollowUpAt" = coalesce(
      requested_follow_up_at, "CusQuoteHeader_FollowUpAt"
    ),
    "CusQuoteHeader_AcceptedVersionID" = case
      when next_lifecycle = 'accepted' then selected_version_id
      when next_lifecycle = 'declined' then null
      else "CusQuoteHeader_AcceptedVersionID" end,
    "CusQuoteHeader_LastEditedBy" = app_user."User_ID",
    "CusQuoteHeader_LastEditedDate" = now()
  where "CusQuoteHeader_ID" = requested_quote_id;

  insert into public."CusQuote_Events" (
    "Company_ID", "CusQuoteHeader_ID", "CusQuoteVersion_ID", "CusQuoteEvent_TypeCode",
    "CusQuoteEvent_Summary", "CusQuoteEvent_MetadataJSON",
    "CusQuoteEvent_ActorUserID"
  ) values (
    app_user."Company_ID", requested_quote_id, selected_version_id, next_lifecycle,
    case
      when next_lifecycle = 'accepted' then 'Accepted manually using ' || case when selected_version_number = 1 then 'the original quote' else 'V' || selected_version_number end || '.'
      when next_lifecycle = 'declined' then 'Lost' || case when nullif(btrim(requested_note), '') is null then '.' else ': ' || left(btrim(requested_note), 500) end
      else initcap(next_lifecycle) || case when nullif(btrim(requested_note), '') is null then '.' else ': ' || left(btrim(requested_note), 500) end
    end,
    jsonb_strip_nulls(jsonb_build_object(
      'followUpAt', requested_follow_up_at,
      'lossReason', case when next_lifecycle = 'declined' then btrim(requested_note) end,
      'outcomeSource', case when next_lifecycle in ('accepted', 'declined') then 'manual' end,
      'selectedVersionId', selected_version_id,
      'selectedVersionNumber', selected_version_number,
      'workingDraftPreserved', current_version."CusQuoteVersion_ID" is distinct from selected_version_id
    )),
    app_user."User_ID"
  );

  return jsonb_build_object(
    'quoteId', requested_quote_id,
    'lifecycle', next_lifecycle,
    'versionId', selected_version_id,
    'versionNumber', selected_version_number,
    'workingDraftPreserved', current_version."CusQuoteVersion_ID" is distinct from selected_version_id,
    'lossReason', case when next_lifecycle = 'declined' then btrim(requested_note) end
  );
exception
  when no_data_found or too_many_rows then
    raise exception 'User identity is incomplete or ambiguous.' using errcode = '42501';
end;
$$;


ALTER FUNCTION "quote_api"."transition_quote"("caller_auth_user_id" "uuid", "requested_quote_id" "uuid", "requested_transition" "text", "requested_note" "text", "requested_follow_up_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "quote_api"."validate_version_cargo"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare lines jsonb;
begin
  -- The existing submitted-version mutation guard remains authoritative.
  -- Never normalise or rewrite already-submitted evidence on a status update.
  if tg_op = 'UPDATE' and old."CusQuoteVersion_IsSubmitted" then return new; end if;
  lines := new."CusQuoteVersion_SnapshotJSON" #> '{quote,shipmentFacts,cargoLines}';
  if lines is not null then
    new."CusQuoteVersion_SnapshotJSON" := jsonb_set(new."CusQuoteVersion_SnapshotJSON",
      '{quote,shipmentFacts,cargoLines}',
      quote_api.normalise_cargo_lines(lines, new."CusQuoteVersion_IsSubmitted"));
  end if;
  return new;
end;
$$;


ALTER FUNCTION "quote_api"."validate_version_cargo"() OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "report_api"."reports" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "company_id" "uuid" NOT NULL,
    "owner_id" "uuid" NOT NULL,
    "name" "text" NOT NULL,
    "visibility" "text" DEFAULT 'private'::"text" NOT NULL,
    "definition" "jsonb" NOT NULL,
    "version" integer DEFAULT 1 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "archived_at" timestamp with time zone,
    CONSTRAINT "reports_name_check" CHECK ((("length"("btrim"("name")) >= 1) AND ("length"("btrim"("name")) <= 160))),
    CONSTRAINT "reports_visibility_check" CHECK (("visibility" = ANY (ARRAY['private'::"text", 'workspace'::"text"])))
);


ALTER TABLE "report_api"."reports" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "report_api"."can_read"("actor" "uuid", "target" "report_api"."reports") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare u public."cmp_Users"; src text; required text;
begin
  u:=report_api.context(actor);
  if target.company_id is distinct from u."Company_ID" or target.archived_at is not null or (target.owner_id<>u."User_ID" and target.visibility<>'workspace') then return false;end if;
  for src in select target.definition#>>'{query,source}' where target.definition->>'kind'<>'document'
    union select b#>>'{query,source}' from jsonb_array_elements(coalesce(target.definition->'blocks','[]')) b where b->>'kind'<>'text' loop
    select x->>'permission' into required from jsonb_array_elements(report_api.catalogue()) x where x->>'id'=src;
    if required is null or not booking_api.has_permission(actor,required) then return false;end if;
  end loop;
  return true;
end $$;


ALTER FUNCTION "report_api"."can_read"("actor" "uuid", "target" "report_api"."reports") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "report_api"."runs" (
    "id" "uuid" NOT NULL,
    "report_id" "uuid" NOT NULL,
    "company_id" "uuid" NOT NULL,
    "owner_id" "uuid" NOT NULL,
    "name" "text" NOT NULL,
    "report_version" integer NOT NULL,
    "definition" "jsonb" NOT NULL,
    "status" "text" NOT NULL,
    "snapshot" "jsonb",
    "error" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "schedule_id" "uuid",
    CONSTRAINT "runs_check" CHECK (((("status" = 'ready'::"text") AND ("snapshot" IS NOT NULL) AND ("error" IS NULL)) OR (("status" = 'failed'::"text") AND ("snapshot" IS NULL) AND ("error" IS NOT NULL)))),
    CONSTRAINT "runs_status_check" CHECK (("status" = ANY (ARRAY['ready'::"text", 'failed'::"text"])))
);


ALTER TABLE "report_api"."runs" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "report_api"."can_read_run"("actor" "uuid", "target" "report_api"."runs") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare u public."cmp_Users"; r report_api.reports;
begin
  u:=report_api.context(actor);
  if target.company_id is distinct from u."Company_ID" or target.owner_id is distinct from u."User_ID" then return false;end if;
  r.company_id:=target.company_id;r.owner_id:=target.owner_id;r.visibility:='private';r.archived_at:=null;r.definition:=target.definition;
  return report_api.can_read(actor,r);
end $$;


ALTER FUNCTION "report_api"."can_read_run"("actor" "uuid", "target" "report_api"."runs") OWNER TO "postgres";


