CREATE OR REPLACE VIEW "public"."AWB_PrintSummary" WITH ("security_invoker"='true') AS
 SELECT "h"."AWB_id",
    "h"."AWB_JobID",
    "h"."AWB_Number",
    "h"."AWB_AWBType",
    "h"."AWB_Status",
    "h"."AWB_DocumentDate",
    "h"."AWB_IssueDateTime",
    "h"."AWB_eAWBIndicator",
    "h"."AWB_EAWBCode",
    "h"."AWB_OriginAirportCodeSnapshot",
    "h"."AWB_DestinationAirportCodeSnapshot",
    "h"."AWB_CarrierNameSnapshot",
    "shipper"."AWBP_NameSnapshot" AS "AWB_ShipperNameSnapshot",
    "consignee"."AWBP_NameSnapshot" AS "AWB_ConsigneeNameSnapshot",
    COALESCE("goods"."AWB_TotalPieces", (0)::bigint) AS "AWB_TotalPieces",
    COALESCE("goods"."AWB_TotalGrossWeight", (0)::numeric) AS "AWB_TotalGrossWeight",
    COALESCE("goods"."AWB_TotalChargeableWeight", (0)::numeric) AS "AWB_TotalChargeableWeight",
    "goods"."AWB_GrossWeightUOM",
    "goods"."AWB_ChargeableWeightUOM",
    "cs"."AWBCS_CurrencyCodeSnapshot" AS "AWB_ChargeCurrencyCodeSnapshot",
    "cs"."AWBCS_TotalAmount" AS "AWB_TotalChargeAmount"
   FROM (((("public"."AWB_Header" "h"
     LEFT JOIN LATERAL ( SELECT "p"."AWBP_NameSnapshot"
           FROM "public"."AWB_Parties" "p"
          WHERE (("p"."AWBP_AWBID" = "h"."AWB_id") AND (("p"."AWBP_Role")::"text" = 'shipper'::"text"))
          ORDER BY "p"."AWBP_SortOrder", "p"."AWBP_CreatedAt"
         LIMIT 1) "shipper" ON (true))
     LEFT JOIN LATERAL ( SELECT "p"."AWBP_NameSnapshot"
           FROM "public"."AWB_Parties" "p"
          WHERE (("p"."AWBP_AWBID" = "h"."AWB_id") AND (("p"."AWBP_Role")::"text" = 'consignee'::"text"))
          ORDER BY "p"."AWBP_SortOrder", "p"."AWBP_CreatedAt"
         LIMIT 1) "consignee" ON (true))
     LEFT JOIN LATERAL ( SELECT "sum"("g"."AWBG_PieceCount") AS "AWB_TotalPieces",
            "sum"(COALESCE("g"."AWBG_GrossWeight", (0)::numeric)) AS "AWB_TotalGrossWeight",
            "sum"(COALESCE("g"."AWBG_ChargeableWeight", (0)::numeric)) AS "AWB_TotalChargeableWeight",
            "min"(("g"."AWBG_GrossWeightUOM")::"text") AS "AWB_GrossWeightUOM",
            "min"(("g"."AWBG_ChargeableWeightUOM")::"text") AS "AWB_ChargeableWeightUOM"
           FROM "public"."AWB_GoodsItems" "g"
          WHERE ("g"."AWBG_AWBID" = "h"."AWB_id")) "goods" ON (true))
     LEFT JOIN "public"."AWB_ChargeSummary" "cs" ON (("cs"."AWBCS_AWBID" = "h"."AWB_id")));


