CREATE OR REPLACE VIEW "public"."App_Live_Bookings" WITH ("security_invoker"='true') AS
 SELECT "prior"."Job_ID",
    "prior"."Booking_Reference",
    "prior"."Customer_Name",
    "prior"."Route",
    "prior"."Carrier",
    "prior"."Equipment",
    "prior"."Mode",
    "prior"."Direction",
    "prior"."Shipment_Type",
    "prior"."Value_Display",
    "prior"."Eta_Display",
    "prior"."Time_Display",
    "prior"."Status",
    "prior"."Progress",
    "prior"."Owner_Code",
    "prior"."Tone",
    "prior"."Invoice_Reference",
    "prior"."Job_Reference",
    "prior"."Customer_Reference",
    "prior"."Supplier_Reference",
    "prior"."Origin",
    "prior"."Destination",
    "prior"."Vessel",
    "prior"."Departure_Date",
    "prior"."Arrival_Date",
    "prior"."Vin",
    "prior"."Is_Favourite",
    "prior"."Custom_Fields",
    "prior"."Updated_At",
    "prior"."Departure_At",
    "prior"."Arrival_At",
    ("j"."Job_Status")::"text" AS "Lifecycle_Status"
   FROM (( SELECT "j_1"."Job_ID",
            (COALESCE("j_1"."Job_BookingReference", (('MD-'::"text" || "j_1"."Job_Number"))::character varying))::"text" AS "Booking_Reference",
            COALESCE("c"."Org_Name", 'Unassigned customer'::character varying) AS "Customer_Name",
            "concat_ws"(' → '::"text", COALESCE("j_1"."Job_OriginNameSnapshot", "j_1"."Job_OriginUNLocode"), COALESCE("j_1"."Job_DestinationNameSnapshot", "j_1"."Job_DestinationUNLocode")) AS "Route",
            COALESCE("carrier"."Org_Name", 'Carrier pending'::character varying) AS "Carrier",
            COALESCE("cargo"."description", 'Shipment details needed'::"text") AS "Equipment",
            "upper"((COALESCE("j_1"."Job_TransportModeSummary", 'Mode needed'::character varying))::"text") AS "Mode",
                CASE
                    WHEN ((COALESCE("j_1"."Job_Direction", 'unknown'::character varying))::"text" = 'unknown'::"text") THEN 'Direction needed'::"text"
                    ELSE "initcap"("replace"(("j_1"."Job_Direction")::"text", '_'::"text", ' '::"text"))
                END AS "Direction",
            COALESCE("cargo"."description", 'Shipment details needed'::"text") AS "Shipment_Type",
            ''::"text" AS "Value_Display",
            COALESCE("to_char"("j_1"."Job_PredictedDeliveryAt", 'DD Mon · HH24:MI'::"text"), "to_char"(("j_1"."Job_RequiredDeliveryDate")::timestamp with time zone, 'DD Mon'::"text")) AS "Eta_Display",
            COALESCE("j_1"."Job_CurrentLocationNameSnapshot", 'Planning'::character varying) AS "Time_Display",
                CASE
                    WHEN (("j_1"."Job_Status")::"text" = 'draft'::"text") THEN 'Draft'::"text"
                    WHEN (COALESCE("j_1"."Job_TrackingRiskScore", (0)::numeric) >= 0.80) THEN 'Exception'::"text"
                    WHEN (COALESCE("j_1"."Job_TrackingRiskScore", (0)::numeric) >= 0.50) THEN 'Delayed'::"text"
                    ELSE 'On track'::"text"
                END AS "Status",
                CASE
                    WHEN ("j_1"."Job_ClosedDate" IS NOT NULL) THEN 100
                    WHEN (("j_1"."Job_TrackingStatus")::"text" = 'in_transit'::"text") THEN 62
                    WHEN (("j_1"."Job_TrackingStatus")::"text" = 'delayed'::"text") THEN 48
                    WHEN (("j_1"."Job_Status")::"text" = 'draft'::"text") THEN 8
                    ELSE 24
                END AS "Progress",
            'OP'::"text" AS "Owner_Code",
                CASE
                    WHEN (COALESCE("j_1"."Job_TrackingRiskScore", (0)::numeric) >= 0.80) THEN 'red'::"text"
                    WHEN (COALESCE("j_1"."Job_TrackingRiskScore", (0)::numeric) >= 0.50) THEN 'amber'::"text"
                    WHEN (("j_1"."Job_Status")::"text" = 'draft'::"text") THEN 'blue'::"text"
                    ELSE 'green'::"text"
                END AS "Tone",
            ''::"text" AS "Invoice_Reference",
            ('JOB-'::"text" || "j_1"."Job_Number") AS "Job_Reference",
            COALESCE("c"."Org_AccCode", ''::character varying) AS "Customer_Reference",
            ''::"text" AS "Supplier_Reference",
            COALESCE("j_1"."Job_OriginNameSnapshot", "j_1"."Job_OriginUNLocode", ''::character varying) AS "Origin",
            COALESCE("j_1"."Job_DestinationNameSnapshot", "j_1"."Job_DestinationUNLocode", ''::character varying) AS "Destination",
            COALESCE("r"."JobRoute_TransportMeansName", "r"."JobRoute_Vessel", ''::character varying) AS "Vessel",
            (COALESCE("r"."JobRoute_EstimatedDepartureAt", "r"."JobRoute_PlannedDepartureAt"))::"date" AS "Departure_Date",
            (COALESCE("r"."JobRoute_EstimatedArrivalAt", "r"."JobRoute_PlannedArrivalAt", "j_1"."Job_PredictedDeliveryAt"))::"date" AS "Arrival_Date",
            COALESCE("r"."JobRoute_VehicleRegistration", ''::character varying) AS "Vin",
            ("star"."Job_ID" IS NOT NULL) AS "Is_Favourite",
            "jsonb_build_array"("jsonb_build_object"('label', 'Tracking', 'value', COALESCE("j_1"."Job_TrackingStatus", 'Planning'::character varying)), "jsonb_build_object"('label', 'Source', 'value',
                CASE
                    WHEN ("j_1"."Job_SourceQuoteID" IS NULL) THEN 'Direct booking'::"text"
                    ELSE 'Accepted quote'::"text"
                END)) AS "Custom_Fields",
            COALESCE("j_1"."Job_UpdatedAt", ("j_1"."Job_CreatedDate")::timestamp with time zone) AS "Updated_At",
            COALESCE("r"."JobRoute_EstimatedDepartureAt", "r"."JobRoute_PlannedDepartureAt") AS "Departure_At",
            COALESCE("r"."JobRoute_EstimatedArrivalAt", "r"."JobRoute_PlannedArrivalAt", "j_1"."Job_PredictedDeliveryAt") AS "Arrival_At"
           FROM ((((("public"."Job_Header" "j_1"
             LEFT JOIN "public"."Org_Master" "c" ON (("c"."Org_id" = "j_1"."Job_Customer")))
             LEFT JOIN "public"."Org_Master" "carrier" ON (("carrier"."Org_id" = "j_1"."Job_Carrier")))
             LEFT JOIN "public"."App_UserJobStars" "star" ON ((("star"."Job_ID" = "j_1"."Job_ID") AND ("star"."User_ID" = "auth"."uid"()))))
             LEFT JOIN LATERAL ( SELECT "rr"."JobRoute_ID",
                    "rr"."Job_ID",
                    "rr"."JobRoute_LegType",
                    "rr"."JobRoute_LegETD",
                    "rr"."JobRoute_LegETA",
                    "rr"."JobRoute_OrderNo",
                    "rr"."JobRoute_OriginUNLocode",
                    "rr"."JobRoute_DestinationUNLocode",
                    "rr"."JobRoute_Carrier",
                    "rr"."JobRoute_Mode",
                    "rr"."JobRoute_Vessel",
                    "rr"."JobRoute_VoyageNumber",
                    "rr"."JobRoute_Tracked",
                    "rr"."JobRoute_LegTypeCode",
                    "rr"."JobRoute_Status",
                    "rr"."JobRoute_ModeCode",
                    "rr"."JobRoute_OriginNameSnapshot",
                    "rr"."JobRoute_OriginAddressID",
                    "rr"."JobRoute_OriginAddressSnapshot",
                    "rr"."JobRoute_OriginTerminal",
                    "rr"."JobRoute_DestinationNameSnapshot",
                    "rr"."JobRoute_DestinationAddressID",
                    "rr"."JobRoute_DestinationAddressSnapshot",
                    "rr"."JobRoute_DestinationTerminal",
                    "rr"."JobRoute_PlannedPickupAt",
                    "rr"."JobRoute_EstimatedPickupAt",
                    "rr"."JobRoute_ActualPickupAt",
                    "rr"."JobRoute_PlannedDepartureAt",
                    "rr"."JobRoute_EstimatedDepartureAt",
                    "rr"."JobRoute_ActualDepartureAt",
                    "rr"."JobRoute_PlannedArrivalAt",
                    "rr"."JobRoute_EstimatedArrivalAt",
                    "rr"."JobRoute_ActualArrivalAt",
                    "rr"."JobRoute_PlannedDeliveryAt",
                    "rr"."JobRoute_EstimatedDeliveryAt",
                    "rr"."JobRoute_ActualDeliveryAt",
                    "rr"."JobRoute_CarrierBookingReference",
                    "rr"."JobRoute_MasterTransportReference",
                    "rr"."JobRoute_HouseTransportReference",
                    "rr"."JobRoute_ServiceLevel",
                    "rr"."JobRoute_TransportMeansName",
                    "rr"."JobRoute_FlightNumber",
                    "rr"."JobRoute_VehicleRegistration",
                    "rr"."JobRoute_TrailerNumber",
                    "rr"."JobRoute_RailService",
                    "rr"."JobRoute_DistanceKm",
                    "rr"."JobRoute_IsMainCarriage",
                    "rr"."JobRoute_RouteJSON",
                    "rr"."JobRoute_InternalNotes",
                    "rr"."JobRoute_UpdatedAt",
                    "rr"."JobRoute_UpdatedBy"
                   FROM "public"."Job_Routing" "rr"
                  WHERE ("rr"."Job_ID" = "j_1"."Job_ID")
                  ORDER BY "rr"."JobRoute_OrderNo"
                 LIMIT 1) "r" ON (true))
             LEFT JOIN LATERAL ( SELECT "max"("cg"."JobCargo_Description") AS "description"
                   FROM "public"."Job_Cargo" "cg"
                  WHERE (("cg"."JobCargo_JobID" = "j_1"."Job_ID") AND (NOT COALESCE("cg"."JobCargo_IsDeleted", false)))) "cargo" ON (true))
          WHERE (NOT COALESCE("j_1"."Job_IsDeleted", false))) "prior"
     JOIN "public"."Job_Header" "j" ON (("j"."Job_ID" = "prior"."Job_ID")));


