CREATE OR REPLACE VIEW "public"."App_Live_Quotes" WITH ("security_invoker"='true') AS
 SELECT "quote"."CusQuoteHeader_ID",
    COALESCE(NULLIF("btrim"(("quote"."CusQuoteHeader_CustomerReference")::"text"), ''::"text"), ('Q-'::"text" || "quote"."CusQuoteHeader_Number")) AS "Quote_Reference",
    "initcap"("replace"((COALESCE("quote"."CusQuoteHeader_LifecycleCode", 'draft'::character varying))::"text", '_'::"text", ' '::"text")) AS "Quote_Status",
        CASE COALESCE("quote"."CusQuoteHeader_LifecycleCode", 'draft'::character varying)
            WHEN 'accepted'::"text" THEN 'green'::"text"
            WHEN 'sent'::"text" THEN 'teal'::"text"
            WHEN 'calculated'::"text" THEN 'blue'::"text"
            WHEN 'declined'::"text" THEN 'red'::"text"
            WHEN 'ghosted'::"text" THEN 'neutral'::"text"
            ELSE 'amber'::"text"
        END AS "Quote_Status_Tone",
    (COALESCE("customer"."Org_Name", "quote"."CusQuoteHeader_CustomerNameSnapshot", ''::character varying))::character varying(100) AS "Customer_Name",
    COALESCE("quote"."CusQuoteHeader_LoadingPoint", "quote"."CusQuoteHeader_OriginExtra", ''::"text") AS "Origin",
    COALESCE("quote"."CusQuoteHeader_DischargePoint", "quote"."CusQuoteHeader_DestinationExtra", ''::"text") AS "Destination",
    "schedule"."estimated_departure" AS "Estimated_Departure",
    "schedule"."estimated_arrival" AS "Estimated_Arrival",
    COALESCE(
        CASE
            WHEN (("schedule"."estimated_departure" IS NOT NULL) AND ("schedule"."estimated_arrival" IS NOT NULL)) THEN ((("schedule"."estimated_arrival" - "schedule"."estimated_departure"))::"text" || ' days'::"text")
            ELSE NULL::"text"
        END, NULLIF("btrim"("concat_ws"(' '::"text", ("quote"."CusQuoteHeader_ShipmentFactsJSON" ->> 'transitDays'::"text"), ("quote"."CusQuoteHeader_ShipmentFactsJSON" ->> 'transitUnit'::"text"))), ''::"text"), ''::"text") AS "Transport_Time",
    "initcap"((COALESCE("quote"."CusQuoteHeader_ModeCode", ''::character varying))::"text") AS "Transport_Mode",
    (COALESCE(("quote"."CusQuoteHeader_ShipmentFactsJSON" ->> 'equipment'::"text"), ("quote"."CusQuoteHeader_ShipmentTypeCode")::"text", ''::"text"))::character varying AS "Equipment_Load",
    COALESCE("quote"."CusQuoteHeader_CollectionAddress", ''::"text") AS "Pickup",
    COALESCE("quote"."CusQuoteHeader_DeliveryAddress", ''::"text") AS "Delivery",
    COALESCE(("quote"."CusQuoteHeader_ShipmentFactsJSON" ->> 'routingVia'::"text"), ''::"text") AS "Routing_Via",
    COALESCE("quote"."CusQuoteHeader_Incoterm", ''::character varying) AS "Incoterms",
    COALESCE(("quote"."CusQuoteHeader_ShipmentFactsJSON" ->> 'namedPlace'::"text"), ''::"text") AS "Incoterms_Place",
    COALESCE("quote"."CusQuoteHeader_ServiceLevel", ''::character varying) AS "Service_Level",
    COALESCE("quote"."CusQuoteHeader_ShipmentTypeCode", ''::character varying) AS "Shipment_Type",
    (COALESCE("quote"."CusQuoteHeader_CarrierNameSnapshot", "carrier"."Org_Name", ''::character varying))::"text" AS "Carrier",
    (COALESCE("quote"."CusQuoteHeader_SupplierNameSnapshot", "supplier"."Org_Name", ''::character varying))::"text" AS "Supplier",
    COALESCE(((("sales_owner"."User_Firstname")::"text" || ' '::"text") || ("sales_owner"."User_Lastname")::"text"), ''::"text") AS "Sales_Owner",
    COALESCE(((("created_by"."User_Firstname")::"text" || ' '::"text") || ("created_by"."User_Lastname")::"text"), ''::"text") AS "Operations_Owner",
    COALESCE(("quote"."CusQuoteHeader_ShipmentFactsJSON" ->> 'quoteType'::"text"), 'Spot'::"text") AS "Quote_Type",
    "initcap"((COALESCE("quote"."CusQuoteHeader_Direction", ''::character varying))::"text") AS "Direction",
    (COALESCE("quote"."CusQuoteHeader_CustomerReference", ''::character varying))::"text" AS "Customer_Purchase_Order",
    COALESCE(("quote"."CusQuoteHeader_ShipmentFactsJSON" ->> 'shipperReference'::"text"), ''::"text") AS "Shipper_Reference",
    "to_char"(("quote"."CusQuoteHeader_ValidTo")::timestamp with time zone, 'DD Mon YYYY'::"text") AS "Validity",
    "to_char"("quote"."CusQuoteHeader_Deadline", 'DD Mon · HH24:MI'::"text") AS "Estimated_Quote",
    COALESCE("totals"."sell", (0)::numeric) AS "Sell_Value",
    COALESCE(("totals"."sell" - "totals"."cost"), (0)::numeric) AS "Estimated_Profit",
    COALESCE("totals"."cost", (0)::numeric) AS "Estimated_Cost",
        CASE
            WHEN (COALESCE("totals"."sell", (0)::numeric) = (0)::numeric) THEN NULL::numeric
            ELSE "round"(((("totals"."sell" - "totals"."cost") / "totals"."sell") * (100)::numeric), 2)
        END AS "Estimated_Margin",
    COALESCE("quote"."CusQuoteHeader_CurrencyCode", ''::character varying) AS "Currency",
    'Draft'::"text" AS "Document_Status",
    "initcap"("replace"((COALESCE("quote"."CusQuoteHeader_LifecycleCode", 'draft'::character varying))::"text", '_'::"text", ' '::"text")) AS "Workflow_Stage",
    COALESCE(("quote"."CusQuoteHeader_ShipmentFactsJSON" ->> 'priority'::"text"), ''::"text") AS "Priority",
        CASE
            WHEN (("quote"."CusQuoteHeader_ShipmentFactsJSON" ->> 'priority'::"text") = 'Urgent'::"text") THEN 'red'::"text"
            ELSE 'neutral'::"text"
        END AS "Priority_Tone",
    (COALESCE("quote"."CusQuoteHeader_RateSourceLabel", ("initcap"(("quote"."CusQuoteHeader_RateSourceTypeCode")::"text"))::character varying, ''::character varying))::"text" AS "Quote_Source",
    ("quote"."CusQuoteHeader_CreatedDate")::timestamp with time zone AS "Created_At",
    (COALESCE("quote"."CusQuoteHeader_LastEditedDate", "quote"."CusQuoteHeader_CreatedDate"))::timestamp with time zone AS "Updated_At"
   FROM ((((((("public"."CusQuote_Header" "quote"
     LEFT JOIN "public"."Org_Master" "customer" ON (("customer"."Org_id" = "quote"."CusQuoteHeader_CustomerID")))
     LEFT JOIN "public"."Org_Master" "supplier" ON (("supplier"."Org_id" = "quote"."CusQuoteHeader_SupplierID")))
     LEFT JOIN "public"."Org_Master" "carrier" ON (("carrier"."Org_id" = "quote"."CusQuoteHeader_CarrierID")))
     LEFT JOIN "public"."cmp_Users" "sales_owner" ON (("sales_owner"."User_ID" = "quote"."CusQuoteHeader_SalesOwnerID")))
     LEFT JOIN "public"."cmp_Users" "created_by" ON (("created_by"."User_ID" = "quote"."CusQuoteHeader_CreatedBy")))
     LEFT JOIN LATERAL ( SELECT
                CASE
                    WHEN (("quote"."CusQuoteHeader_ShipmentFactsJSON" ->> 'estimatedDeparture'::"text") ~ '^\d{4}-\d{2}-\d{2}$'::"text") THEN (("quote"."CusQuoteHeader_ShipmentFactsJSON" ->> 'estimatedDeparture'::"text"))::"date"
                    ELSE NULL::"date"
                END AS "estimated_departure",
                CASE
                    WHEN (("quote"."CusQuoteHeader_ShipmentFactsJSON" ->> 'estimatedArrival'::"text") ~ '^\d{4}-\d{2}-\d{2}$'::"text") THEN (("quote"."CusQuoteHeader_ShipmentFactsJSON" ->> 'estimatedArrival'::"text"))::"date"
                    ELSE NULL::"date"
                END AS "estimated_arrival") "schedule" ON (true))
     LEFT JOIN LATERAL ( SELECT COALESCE("sum"("line"."CusQuoteLine_CostAmountLocal"), (0)::numeric) AS "cost",
            COALESCE("sum"("line"."CusQuoteLine_RevenueAmountLocal"), (0)::numeric) AS "sell"
           FROM "public"."CusQuote_Lines" "line"
          WHERE ("line"."CusQuoteHeader_ID" = "quote"."CusQuoteHeader_ID")) "totals" ON (true))
  WHERE (NOT "quote"."CusQuoteHeader_IsDeleted");


ALTER VIEW "public"."App_Live_Quotes" OWNER TO "postgres";


