CREATE OR REPLACE VIEW "public"."Audit_PolicySummary" WITH ("security_invoker"='true') AS
 SELECT "p"."AuditPolicy_ID",
    "p"."AuditPolicy_TableSchema",
    "p"."AuditPolicy_TableName",
    "p"."AuditPolicy_RecordTypeCode",
    "p"."AuditPolicy_ModeCode",
    "p"."AuditPolicy_RetentionClassCode",
    "p"."AuditPolicy_SensitivityCode",
    "p"."AuditPolicy_TrackInserts",
    "p"."AuditPolicy_TrackUpdates",
    "p"."AuditPolicy_TrackDeletes",
    "p"."AuditPolicy_TrackFieldChanges",
    "p"."AuditPolicy_TrackRowSnapshots",
    "p"."AuditPolicy_IsEnabled",
        CASE
            WHEN ("t"."tgname" IS NULL) THEN false
            ELSE true
        END AS "AuditPolicy_TriggerInstalled",
    "p"."AuditPolicy_UpdatedAt"
   FROM ((("public"."Audit_TablePolicies" "p"
     LEFT JOIN "pg_class" "c" ON (("c"."relname" = ("p"."AuditPolicy_TableName")::"text")))
     LEFT JOIN "pg_namespace" "n" ON ((("n"."oid" = "c"."relnamespace") AND ("n"."nspname" = ("p"."AuditPolicy_TableSchema")::"text"))))
     LEFT JOIN "pg_trigger" "t" ON ((("t"."tgrelid" = "c"."oid") AND ("t"."tgname" = 'zz_audit_row_change'::"name") AND (NOT "t"."tgisinternal"))));


ALTER VIEW "public"."Audit_PolicySummary" OWNER TO "postgres";


