CREATE OR REPLACE VIEW "public"."BL_SecuritySummary" WITH ("security_invoker"='true') AS
 SELECT "bl"."BL_id",
    "bl"."BL_Number",
    "bl"."BL_DocumentType",
    "bl"."BL_Status",
    "bl"."BL_IssueDateTime",
    "bl"."BL_DocumentDate",
    "bl"."BL_NumberOfOriginals",
    "bl"."BL_NumberOfCopies",
    "bl"."BL_Negotiable",
    "bl"."BL_ToOrder",
    "bl"."BL_OrgOfficeID",
    "bl"."BL_LegalEntityID",
    "bl"."BL_BrandID",
    "security"."BLSC_ID",
    "security"."BLSC_SecurityStatusCode",
    "bl_status"."BLSST_Name" AS "BLSecurityStatusName",
    "bl_status"."BLSST_IsValidForRelease" AS "BLSecurityIsValidForRelease",
    "security"."BLSC_CurrentFingerprintID",
    "fingerprint"."DOCSECF_FileSHA256" AS "CurrentFileSHA256",
    "security"."BLSC_CurrentVerificationTokenID",
    "token"."DOCSECVT_PublicCode" AS "CurrentVerificationPublicCode",
    "token"."DOCSECVT_VerificationURL" AS "CurrentVerificationURL",
    "token"."DOCSECVT_StatusCode" AS "CurrentVerificationTokenStatusCode",
    "security"."BLSC_OriginalSetID",
    "security"."BLSC_NumberOfOriginalsSecured",
    "security"."BLSC_NegotiableSnapshot",
    "security"."BLSC_ToOrderSnapshot",
    "security"."BLSC_QRRequired",
    "security"."BLSC_QRPublicURL",
    "security"."BLSC_LastVerificationAt",
    "security"."BLSC_VerificationCount",
    "security"."BLSC_FraudHold",
    "security"."BLSC_FraudHoldReason",
    "security"."BLSC_RevokedAt",
    "security"."BLSC_RevocationReason",
    ( SELECT ("count"(*))::integer AS "count"
           FROM "public"."DOCSEC_VerificationIssues" "issue"
          WHERE ((("issue"."DOCSECI_TargetTable")::"text" = 'BL_Header'::"text") AND ("issue"."DOCSECI_TargetID" = "bl"."BL_id") AND (("issue"."DOCSECI_Status")::"text" = 'open'::"text"))) AS "OpenSecurityIssueCount"
   FROM (((("public"."BL_Header" "bl"
     LEFT JOIN "public"."BL_SecurityControls" "security" ON (("security"."BLSC_BLID" = "bl"."BL_id")))
     LEFT JOIN "public"."sys_BLSecurityStatuses" "bl_status" ON ((("bl_status"."BLSST_Code")::"text" = ("security"."BLSC_SecurityStatusCode")::"text")))
     LEFT JOIN "public"."DOCSEC_DocumentFingerprints" "fingerprint" ON (("fingerprint"."DOCSECF_ID" = "security"."BLSC_CurrentFingerprintID")))
     LEFT JOIN "public"."DOCSEC_VerificationTokens" "token" ON (("token"."DOCSECVT_ID" = "security"."BLSC_CurrentVerificationTokenID")));


ALTER VIEW "public"."BL_SecuritySummary" OWNER TO "postgres";


