CREATE OR REPLACE VIEW "public"."CLM_EvidenceQueue" WITH ("security_invoker"='true') AS
 SELECT "evidence"."CLMEvidence_ID",
    "evidence"."CLMEvidence_IncidentID",
    "incident"."CLMIncident_Number",
    "evidence"."CLMEvidence_ClaimID",
    "claim"."CLMClaim_Number",
    "evidence"."CLMEvidence_DocumentTypeCode",
    "dtype"."CLMDocumentType_Name",
    "evidence"."CLMEvidence_Title",
    "evidence"."CLMEvidence_SourceCode",
    "evidence"."CLMEvidence_FileName",
    "evidence"."CLMEvidence_IsRequired",
