    "evidence"."CLMEvidence_AIExtractionStatusCode",
    "evidence"."CLMEvidence_CapturedAt",
    "evidence"."CLMEvidence_VerifiedAt",
    "evidence"."CLMEvidence_CreatedAt"
   FROM ((("public"."CLM_EvidenceItems" "evidence"
     LEFT JOIN "public"."CLM_Incidents" "incident" ON (("incident"."CLMIncident_ID" = "evidence"."CLMEvidence_IncidentID")))
     LEFT JOIN "public"."CLM_Claims" "claim" ON (("claim"."CLMClaim_ID" = "evidence"."CLMEvidence_ClaimID")))
     LEFT JOIN "public"."sys_CLMDocumentTypes" "dtype" ON ((("dtype"."CLMDocumentType_Code")::"text" = ("evidence"."CLMEvidence_DocumentTypeCode")::"text")));


