CREATE OR REPLACE VIEW "public"."CRM_CallActionAcceptanceSummary" WITH ("security_invoker"='true') AS
 SELECT ("date_trunc"('month'::"text", "ca"."CRMCallAction_CreatedAt"))::"date" AS "CRMCallAction_PeriodMonth",
    "cr"."CRMCallReview_OwnerUserID",
    "owner"."User_Email" AS "CRMCallReview_OwnerEmail",
    "ca"."CRMCallAction_ActionTypeCode",
    "count"(*) AS "CRMCallAction_TotalCount",
    "count"(*) FILTER (WHERE (("ca"."CRMCallAction_DecisionStatus")::"text" = 'accepted'::"text")) AS "CRMCallAction_AcceptedCount",
    "count"(*) FILTER (WHERE (("ca"."CRMCallAction_DecisionStatus")::"text" = 'rejected'::"text")) AS "CRMCallAction_RejectedCount",
    "count"(*) FILTER (WHERE (("ca"."CRMCallAction_DecisionStatus")::"text" = 'edited'::"text")) AS "CRMCallAction_EditedCount",
    "avg"("ca"."CRMCallAction_ConfidenceScore") AS "CRMCallAction_AvgConfidence"
   FROM (("public"."CRM_CallActionCandidates" "ca"
     JOIN "public"."CRM_CallReviews" "cr" ON (("cr"."CRMCallReview_ID" = "ca"."CRMCallAction_CallReviewID")))
     LEFT JOIN "public"."cmp_Users" "owner" ON (("owner"."User_ID" = "cr"."CRMCallReview_OwnerUserID")))
  GROUP BY (("date_trunc"('month'::"text", "ca"."CRMCallAction_CreatedAt"))::"date"), "cr"."CRMCallReview_OwnerUserID", "owner"."User_Email", "ca"."CRMCallAction_ActionTypeCode";


ALTER VIEW "public"."CRM_CallActionAcceptanceSummary" OWNER TO "postgres";


