CREATE TABLE IF NOT EXISTS "public"."CRM_DriveFiles" (
    "DriveFile_ID" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "Company_ID" "uuid" DEFAULT "public"."app_current_company_id"() NOT NULL,
    "DriveFile_FolderID" "uuid",
    "DriveFile_Name" "text" NOT NULL,
    "DriveFile_MimeType" "text" NOT NULL,
    "DriveFile_SizeBytes" bigint NOT NULL,
    "DriveFile_StoragePath" "text" NOT NULL,
    "DriveFile_ThumbnailPath" "text",
    "DriveFile_PreviewSeed" "text",
    "DriveFile_PreviewWidth" integer,
    "DriveFile_PreviewHeight" integer,
    "DriveFile_CreatedBy" "uuid" DEFAULT "public"."app_current_workspace_user_id"(),
    "DriveFile_CreatedAt" timestamp with time zone DEFAULT "now"() NOT NULL,
    "DriveFile_UpdatedAt" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "CK_CRM_DriveFiles_MimeType" CHECK (("DriveFile_MimeType" ~ '^[a-z]+/[a-zA-Z0-9.+_-]+$'::"text")),
    CONSTRAINT "CK_CRM_DriveFiles_Name" CHECK ((("length"("btrim"("DriveFile_Name")) >= 1) AND ("length"("btrim"("DriveFile_Name")) <= 255))),
    CONSTRAINT "CK_CRM_DriveFiles_PreviewSeed" CHECK ((("DriveFile_PreviewSeed" IS NULL) OR (("DriveFile_PreviewSeed" ~~ 'data:image/%'::"text") AND ("length"("DriveFile_PreviewSeed") <= 4000)))),
    CONSTRAINT "CK_CRM_DriveFiles_PreviewSize" CHECK (((("DriveFile_PreviewWidth" IS NULL) AND ("DriveFile_PreviewHeight" IS NULL)) OR ((("DriveFile_PreviewWidth" >= 1) AND ("DriveFile_PreviewWidth" <= 30000)) AND (("DriveFile_PreviewHeight" >= 1) AND ("DriveFile_PreviewHeight" <= 30000))))),
    CONSTRAINT "CK_CRM_DriveFiles_SizeBytes" CHECK ((("DriveFile_SizeBytes" >= 1) AND ("DriveFile_SizeBytes" <= 52428800)))
);


