    "DriveFolder_UpdatedAt" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "CK_CRM_DriveFolders_ColourCode" CHECK (("DriveFolder_ColourCode" = ANY (ARRAY['teal'::"text", 'meadow'::"text", 'sky'::"text", 'ocean'::"text", 'indigo'::"text", 'violet'::"text", 'plum'::"text", 'rose'::"text", 'ember'::"text", 'graphite'::"text"]))),
    CONSTRAINT "CK_CRM_DriveFolders_IconCode" CHECK (("DriveFolder_IconCode" = ANY (ARRAY['folder'::"text", 'image'::"text", 'file-text'::"text", 'palette'::"text", 'presentation'::"text", 'video'::"text", 'archive'::"text", 'sparkles'::"text", 'shield'::"text", 'tag'::"text", 'globe'::"text", 'package'::"text"]))),
    CONSTRAINT "CK_CRM_DriveFolders_Name" CHECK ((("length"("btrim"("DriveFolder_Name")) >= 1) AND ("length"("btrim"("DriveFolder_Name")) <= 120))),
    CONSTRAINT "CK_CRM_DriveFolders_NotItsOwnParent" CHECK ((("DriveFolder_ParentID" IS NULL) OR ("DriveFolder_ParentID" <> "DriveFolder_ID")))
);


