CREATE OR REPLACE VIEW "public"."CRM_LeadWorklist" WITH ("security_invoker"='true') AS
 SELECT "lead"."CRMLead_ID",
    "lead"."CRMLead_CompanyName",
    "lead"."CRMLead_PersonName",
    "lead"."CRMLead_Email",
    "lead"."CRMLead_Phone",
    "lead"."CRMLead_OrgID",
    "org"."Org_Name" AS "CRMLead_OrgName",
    "lead"."CRMLead_StatusCode",
    "status"."CRMLeadStatus_Name",
    "lead"."CRMLead_RatingCode",
    "lead"."CRMLead_SourceCode",
    "lead"."CRMLead_OwnerUserID",
    "owner"."User_Email" AS "CRMLead_OwnerEmail",
    "lead"."CRMLead_ModeCode",
    "lead"."CRMLead_TradeLane",
    "lead"."CRMLead_ServiceInterest",
    "lead"."CRMLead_Score",
    "lead"."CRMLead_AIProbabilityToConvert",
    "lead"."CRMLead_FirstResponseDueAt",
    "lead"."CRMLead_FirstRespondedAt",
    "lead"."CRMLead_NextActionDueAt",
    "lead"."CRMLead_LastInteractionAt",
    "lead"."CRMLead_CreatedAt"
   FROM ((("public"."CRM_Leads" "lead"
     LEFT JOIN "public"."Org_Master" "org" ON (("org"."Org_id" = "lead"."CRMLead_OrgID")))
     LEFT JOIN "public"."sys_CRMLeadStatuses" "status" ON ((("status"."CRMLeadStatus_Code")::"text" = ("lead"."CRMLead_StatusCode")::"text")))
     LEFT JOIN "public"."cmp_Users" "owner" ON (("owner"."User_ID" = "lead"."CRMLead_OwnerUserID")))
  WHERE (("lead"."CRMLead_IsDeleted" = false) AND ("status"."CRMLeadStatus_IsOpen" = true));


ALTER VIEW "public"."CRM_LeadWorklist" OWNER TO "postgres";


