CREATE OR REPLACE VIEW "public"."CRM_MarketFeedbackSummary" WITH ("security_invoker"='true') AS
 SELECT "fb"."CRMFeedback_CategoryCode",
    "cat"."CRMFeedbackCategory_Name",
    "fb"."CRMFeedback_ModeCode",
    "fb"."CRMFeedback_TradeLane",
    ("date_trunc"('month'::"text", "fb"."CRMFeedback_CreatedAt"))::"date" AS "CRMFeedback_PeriodMonth",
    "count"(*) AS "CRMFeedback_Count",
    "count"(*) FILTER (WHERE ("fb"."CRMFeedback_IsActionable" = true)) AS "CRMFeedback_ActionableCount",
    "avg"("sent"."CRMFeedbackSentiment_Score") AS "CRMFeedback_AvgSentimentScore",
    "avg"("fb"."CRMFeedback_ImpactScore") AS "CRMFeedback_AvgImpactScore",
    "avg"("fb"."CRMFeedback_ConfidenceScore") AS "CRMFeedback_AvgConfidenceScore"
   FROM (("public"."CRM_MarketFeedbackItems" "fb"
     LEFT JOIN "public"."sys_CRMFeedbackCategories" "cat" ON ((("cat"."CRMFeedbackCategory_Code")::"text" = ("fb"."CRMFeedback_CategoryCode")::"text")))
     LEFT JOIN "public"."sys_CRMFeedbackSentiments" "sent" ON ((("sent"."CRMFeedbackSentiment_Code")::"text" = ("fb"."CRMFeedback_SentimentCode")::"text")))
  GROUP BY "fb"."CRMFeedback_CategoryCode", "cat"."CRMFeedbackCategory_Name", "fb"."CRMFeedback_ModeCode", "fb"."CRMFeedback_TradeLane", (("date_trunc"('month'::"text", "fb"."CRMFeedback_CreatedAt"))::"date");


ALTER VIEW "public"."CRM_MarketFeedbackSummary" OWNER TO "postgres";


