CREATE OR REPLACE VIEW "public"."CRM_MessageRepetitionRisk" WITH ("security_invoker"='true') AS
 SELECT "hist"."CRMPVar_CustomerOrgID",
    "org"."Org_Name" AS "CustomerName",
    "hist"."CRMPVar_UserID",
    "hist"."CRMPVar_MessageIntentCode",
    "hist"."CRMPVar_ChannelCode",
    "hist"."CRMPVar_BodyHashSHA256",
    "count"(*) AS "RepeatedDraftCount",
    "count"(*) FILTER (WHERE ("hist"."CRMPVar_WasSent" = true)) AS "RepeatedSentCount",
    "max"("hist"."CRMPVar_CreatedAt") AS "LastUsedAt",
    "max"(("hist"."CRMPVar_BodyPreview")::"text") AS "BodyPreview"
   FROM ("public"."CRM_MessageVariationHistory" "hist"
     LEFT JOIN "public"."Org_Master" "org" ON (("org"."Org_id" = "hist"."CRMPVar_CustomerOrgID")))
  GROUP BY "hist"."CRMPVar_CustomerOrgID", "org"."Org_Name", "hist"."CRMPVar_UserID", "hist"."CRMPVar_MessageIntentCode", "hist"."CRMPVar_ChannelCode", "hist"."CRMPVar_BodyHashSHA256"
 HAVING ("count"(*) > 1);


