CREATE OR REPLACE VIEW "public"."CRM_QuickTaskOptionQueue" WITH ("security_invoker"='true') AS
 SELECT "opt"."CRMQuickOpt_ID",
    "opt"."CRMQuickOpt_QuickTaskID",
    "qt"."CRMQuickTask_AssignedUserID",
    "qt"."CRMQuickTask_Title",
    "opt"."CRMQuickOpt_OptionTypeCode",
    "opttype"."CRMQuickOptType_Name",
    "opt"."CRMQuickOpt_Label",
    "opt"."CRMQuickOpt_ChannelCode",
    "opt"."CRMQuickOpt_MessageDraftID",
    "msg"."CRMPMsg_Subject",
    "msg"."CRMPMsg_BodyText",
    "opt"."CRMQuickOpt_TargetTable",
    "opt"."CRMQuickOpt_TargetID",
    "opt"."CRMQuickOpt_DecisionStatusCode",
    "opt"."CRMQuickOpt_IsRecommended",
    "opt"."CRMQuickOpt_SortOrder"
   FROM ((("public"."CRM_QuickTaskOptions" "opt"
     JOIN "public"."CRM_QuickTasks" "qt" ON (("qt"."CRMQuickTask_ID" = "opt"."CRMQuickOpt_QuickTaskID")))
     LEFT JOIN "public"."sys_CRMQuickTaskOptionTypes" "opttype" ON ((("opttype"."CRMQuickOptType_Code")::"text" = ("opt"."CRMQuickOpt_OptionTypeCode")::"text")))
     LEFT JOIN "public"."CRM_PersonalMessageDrafts" "msg" ON (("msg"."CRMPMsg_ID" = "opt"."CRMQuickOpt_MessageDraftID")))
  WHERE (("opt"."CRMQuickOpt_DecisionStatusCode")::"text" = 'pending'::"text");


