CREATE OR REPLACE VIEW "public"."CRM_SalesPitchImprovementQueue" WITH ("security_invoker"='true') AS
 SELECT "rec"."CRMPitchRec_ID",
    "rec"."CRMPitchRec_StatusCode",
    "rec"."CRMPitchRec_Title",
    "rec"."CRMPitchRec_RecommendationText",
    "rec"."CRMPitchRec_ObjectionHandled",
    "rec"."CRMPitchRec_SuggestedPhrase",
    "rec"."CRMPitchRec_ModeCode",
    "rec"."CRMPitchRec_TradeLane",
    "rec"."CRMPitchRec_ConfidenceScore",
    "analysis"."CRMPitchAnalysis_TargetScope",
    "analysis"."CRMPitchAnalysis_UserID",
    "analysis"."CRMPitchAnalysis_AccountID",
    "rec"."CRMPitchRec_CreatedAt"
   FROM (("public"."CRM_SalesPitchRecommendations" "rec"
     LEFT JOIN "public"."CRM_SalesPitchAnalyses" "analysis" ON (("analysis"."CRMPitchAnalysis_ID" = "rec"."CRMPitchRec_AnalysisID")))
     LEFT JOIN "public"."sys_CRMPitchRecommendationStatuses" "status" ON ((("status"."CRMPitchRecStatus_Code")::"text" = ("rec"."CRMPitchRec_StatusCode")::"text")))
  WHERE ("status"."CRMPitchRecStatus_IsClosed" = false);


