    "CommCall_ConsentEvidenceJSON" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    CONSTRAINT "CK_Comm_CallLogs_ai_disclosure_status" CHECK ((("CommCall_AIDisclosureStatusCode")::"text" = ANY ((ARRAY['unknown'::character varying, 'disclosed'::character varying, 'not_required'::character varying, 'conflict'::character varying])::"text"[]))),
    CONSTRAINT "CK_Comm_CallLogs_confirmed_match_links" CHECK (((("CommCall_MatchedOrgID" IS NULL) AND ("CommCall_MatchedContactID" IS NULL) AND ("CommCall_MatchedLeadID" IS NULL)) OR ((("CommCall_MatchStatusCode")::"text" = 'matched'::"text") AND (("CommCall_MatchMethodCode")::"text" = ANY ((ARRAY['user_review'::character varying, 'approved_action'::character varying, 'approved_action_edited'::character varying])::"text"[]))))),
    CONSTRAINT "CK_Comm_CallLogs_consent_evidence_object" CHECK (("jsonb_typeof"("CommCall_ConsentEvidenceJSON") = 'object'::"text")),
    CONSTRAINT "CK_Comm_CallLogs_match" CHECK ((("CommCall_MatchStatusCode")::"text" = ANY ((ARRAY['matched'::character varying, 'review'::character varying, 'unmatched'::character varying])::"text"[]))),
    CONSTRAINT "CK_Comm_CallLogs_match_confidence" CHECK ((("CommCall_MatchConfidence" IS NULL) OR (("CommCall_MatchConfidence" >= (0)::numeric) AND ("CommCall_MatchConfidence" <= (1)::numeric)))),
    CONSTRAINT "CK_Comm_CallLogs_outcome" CHECK ((("CommCall_OutcomeCode" IS NULL) OR (("CommCall_OutcomeCode")::"text" = ANY ((ARRAY['answered'::character varying, 'missed'::character varying, 'no_answer'::character varying, 'busy'::character varying, 'declined'::character varying, 'voicemail'::character varying, 'failed'::character varying, 'cancelled'::character varying, 'unknown'::character varying])::"text"[])))),
    CONSTRAINT "CK_Comm_CallLogs_recording_consent_status" CHECK ((("CommCall_RecordingConsentStatusCode")::"text" = ANY ((ARRAY['unknown'::character varying, 'not_required'::character varying, 'received'::character varying, 'declined'::character varying, 'conflict'::character varying])::"text"[]))),
    CONSTRAINT "CK_Comm_CallLogs_source_provider" CHECK ((("CommCall_SourceProviderCode" IS NULL) OR (("CommCall_SourceProviderCode")::"text" = ANY ((ARRAY['elevenlabs'::character varying, 'twilio'::character varying, '3cx'::character varying])::"text"[])))),
    CONSTRAINT "CK_Comm_CallLogs_transcript" CHECK ((("CommCall_TranscriptStatusCode")::"text" = ANY ((ARRAY['pending'::character varying, 'partial'::character varying, 'complete'::character varying, 'failed'::character varying, 'unavailable'::character varying, 'unavailable_not_licensed'::character varying, 'expired'::character varying])::"text"[]))),
    CONSTRAINT "CK_Comm_CallLogs_transcription_consent_status" CHECK ((("CommCall_TranscriptionConsentStatusCode")::"text" = ANY ((ARRAY['unknown'::character varying, 'not_required'::character varying, 'received'::character varying, 'declined'::character varying, 'conflict'::character varying])::"text"[]))),
    CONSTRAINT "CK_Comm_CallLogs_transfer" CHECK ((("CommCall_TransferStatusCode")::"text" = ANY ((ARRAY['not_requested'::character varying, 'requested'::character varying, 'accepted'::character varying, 'declined'::character varying, 'failed'::character varying, 'unknown'::character varying])::"text"[])))
);


