CREATE OR REPLACE VIEW "public"."Comm_ConsentSummary" WITH ("security_invoker"='true') AS
 SELECT "consent"."CommConsent_ID",
    "consent"."CommConsent_ChannelCode",
    "consent"."CommConsent_IdentityID",
    "identity"."CommIdentity_DisplayName",
    COALESCE("consent"."CommConsent_NormalizedAddress", "identity"."CommIdentity_NormalizedAddress") AS "CommConsent_NormalizedAddress",
    "consent"."CommConsent_OrgID",
    "org"."Org_Name" AS "CommConsent_OrgName",
    "consent"."CommConsent_ContactID",
    "contact"."OrgContact_FirstName",
    "contact"."OrgContact_LastName",
    "consent"."CommConsent_StatusCode",
    "status"."CommConsentStatus_IsBlock",
    "consent"."CommConsent_LawfulBasis",
    "consent"."CommConsent_Source",
    "consent"."CommConsent_EffectiveAt",
    "consent"."CommConsent_ExpiresAt",
    "consent"."CommConsent_CreatedAt"
   FROM (((("public"."Comm_ConsentPreferences" "consent"
     LEFT JOIN "public"."Comm_Identities" "identity" ON (("identity"."CommIdentity_ID" = "consent"."CommConsent_IdentityID")))
     LEFT JOIN "public"."Org_Master" "org" ON (("org"."Org_id" = "consent"."CommConsent_OrgID")))
     LEFT JOIN "public"."Org_Contacts" "contact" ON (("contact"."OrgContact_ID" = "consent"."CommConsent_ContactID")))
     LEFT JOIN "public"."sys_CommConsentStatuses" "status" ON ((("status"."CommConsentStatus_Code")::"text" = ("consent"."CommConsent_StatusCode")::"text")));


