CREATE OR REPLACE VIEW "public"."Comm_MessageSummary" WITH ("security_invoker"='true') AS
 SELECT "msg"."CommMessage_ID",
    "msg"."CommMessage_ThreadID",
    "thread"."CommThread_Subject",
    "msg"."CommMessage_ChannelCode",
    "msg"."CommMessage_DirectionCode",
    "msg"."CommMessage_StatusCode",
    "msg"."CommMessage_Subject",
    "msg"."CommMessage_BodyPreview",
    "msg"."CommMessage_MessageDate",
    "msg"."CommMessage_ReceivedAt",
    "msg"."CommMessage_SentAt",
    "msg"."CommMessage_DeliveredAt",
    "msg"."CommMessage_ReadAt",
    "msg"."CommMessage_HasAttachments",
    "msg"."CommMessage_IsSpam",
    "msg"."CommMessage_AIIntent",
    "msg"."CommMessage_AIConfidence",
    "mailbox"."CommMailbox_DisplayName",
    "mailbox"."CommMailbox_Address",
    ( SELECT "string_agg"((((("r"."CommRecipient_DisplayNameSnapshot")::"text" || ' <'::"text") || ("r"."CommRecipient_Address")::"text") || '>'::"text"), ', '::"text" ORDER BY "r"."CommRecipient_RecipientTypeCode", "r"."CommRecipient_Address") AS "string_agg"
           FROM "public"."Comm_MessageRecipients" "r"
          WHERE (("r"."CommRecipient_MessageID" = "msg"."CommMessage_ID") AND (("r"."CommRecipient_RecipientTypeCode")::"text" = ANY ((ARRAY['from'::character varying, 'to'::character varying])::"text"[])))) AS "CommMessage_PrincipalRecipients",
    ( SELECT ("count"(*))::integer AS "count"
           FROM "public"."Comm_MessageAttachments" "a"
          WHERE ("a"."CommAttachment_MessageID" = "msg"."CommMessage_ID")) AS "CommMessage_AttachmentCount"
   FROM (("public"."Comm_Messages" "msg"
     JOIN "public"."Comm_Threads" "thread" ON (("thread"."CommThread_ID" = "msg"."CommMessage_ThreadID")))
     LEFT JOIN "public"."Comm_Mailboxes" "mailbox" ON (("mailbox"."CommMailbox_ID" = "msg"."CommMessage_MailboxID")))
  WHERE ("msg"."CommMessage_IsDeleted" = false);


ALTER VIEW "public"."Comm_MessageSummary" OWNER TO "postgres";


