CREATE TABLE IF NOT EXISTS "public"."Customs_DeclarationDocuments" (
    "CUSTD_ID" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "CUSTD_CustomsID" "uuid" NOT NULL,
    "CUSTD_Direction" "text" NOT NULL,
    "CUSTD_SourceSHA256" "text" NOT NULL,
    "CUSTD_IsOfficial" boolean DEFAULT false NOT NULL,
    "CUSTD_ProviderStatus" "text",
    "CUSTD_MRN" "text",
    "CUSTD_FileName" "text" NOT NULL,
    "CUSTD_StorageBucket" "text" DEFAULT 'multideck-generated'::"text" NOT NULL,
    "CUSTD_StoragePath" "text" NOT NULL,
    "CUSTD_MimeType" "text" DEFAULT 'application/pdf'::"text" NOT NULL,
    "CUSTD_FileSizeBytes" bigint NOT NULL,
    "CUSTD_FileSHA256" "text" NOT NULL,
    "CUSTD_RetainUntil" timestamp with time zone,
    "CUSTD_CreatedAt" timestamp with time zone DEFAULT "now"() NOT NULL,
    "CUSTD_CreatedBy" "uuid" NOT NULL,
    "CUSTD_SourceCode" "text" DEFAULT 'multideck_carbone'::"text" NOT NULL,
    "CUSTD_ProviderEventID" "text",
    "CUSTD_ProviderEnvironment" "text" DEFAULT 'sandbox'::"text" NOT NULL,
    "CUSTD_ReceivedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "CK_Customs_DeclarationDocuments_environment" CHECK (("CUSTD_ProviderEnvironment" = ANY (ARRAY['sandbox'::"text", 'production'::"text"]))),
    CONSTRAINT "CK_Customs_DeclarationDocuments_official_retention" CHECK (((NOT "CUSTD_IsOfficial") OR ("CUSTD_RetainUntil" >= ("CUSTD_CreatedAt" + '7 years'::interval)))),
    CONSTRAINT "CK_Customs_DeclarationDocuments_source" CHECK (("CUSTD_SourceCode" = ANY (ARRAY['multideck_carbone'::"text", 'icustoms_webhook'::"text", 'icustoms_provider_recovery'::"text"]))),
    CONSTRAINT "Customs_DeclarationDocuments_CUSTD_Direction_check" CHECK (("CUSTD_Direction" = ANY (ARRAY['import'::"text", 'export'::"text"]))),
    CONSTRAINT "Customs_DeclarationDocuments_CUSTD_FileSHA256_check" CHECK (("CUSTD_FileSHA256" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "Customs_DeclarationDocuments_CUSTD_FileSizeBytes_check" CHECK (("CUSTD_FileSizeBytes" > 0)),
    CONSTRAINT "Customs_DeclarationDocuments_CUSTD_SourceSHA256_check" CHECK (("CUSTD_SourceSHA256" ~ '^[0-9a-f]{64}$'::"text"))
);


ALTER TABLE "public"."Customs_DeclarationDocuments" OWNER TO "postgres";


COMMENT ON TABLE "public"."Customs_DeclarationDocuments" IS 'Private Carbone-rendered CDS declaration PDFs. Accepted snapshots are immutable and retained for seven years.';



COMMENT ON COLUMN "public"."Customs_DeclarationDocuments"."CUSTD_RetainUntil" IS 'Minimum retention date for an accepted declaration PDF. Null only for non-official draft previews.';



COMMENT ON COLUMN "public"."Customs_DeclarationDocuments"."CUSTD_SourceCode" IS 'Immutable document provenance. icustoms_provider_recovery is reserved for a genuine provider PDF recovered for a declaration released before webhook registration; it must never be presented as a webhook delivery.';



