    CONSTRAINT "Customs_InvoiceExtractions_CUSTIE_FileSizeBytes_check" CHECK ((("CUSTIE_FileSizeBytes" > 0) AND ("CUSTIE_FileSizeBytes" <= 10485760))),
    CONSTRAINT "Customs_InvoiceExtractions_CUSTIE_NormalizerVersion_check" CHECK (("CUSTIE_NormalizerVersion" > 0)),
    CONSTRAINT "Customs_InvoiceExtractions_CUSTIE_PageCount_check" CHECK (("CUSTIE_PageCount" >= 0)),
    CONSTRAINT "Customs_InvoiceExtractions_CUSTIE_ResultJSON_check" CHECK (("jsonb_typeof"("CUSTIE_ResultJSON") = 'object'::"text")),
    CONSTRAINT "Customs_InvoiceExtractions_CUSTIE_SHA256_check" CHECK ((("CUSTIE_SHA256")::"text" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "Customs_InvoiceExtractions_CUSTIE_SchemaVersion_check" CHECK (("CUSTIE_SchemaVersion" > 0)),
    CONSTRAINT "Customs_InvoiceExtractions_CUSTIE_StatusCode_check" CHECK ((("CUSTIE_StatusCode")::"text" = ANY ((ARRAY['processing'::character varying, 'ready'::character varying, 'failed'::character varying, 'cancelled'::character varying, 'expired'::character varying])::"text"[]))),
    CONSTRAINT "Customs_InvoiceExtractions_CUSTIE_TimingsJSON_check" CHECK (("jsonb_typeof"("CUSTIE_TimingsJSON") = 'object'::"text")),
    CONSTRAINT "Customs_InvoiceExtractions_CUSTIE_UsageJSON_check" CHECK (("jsonb_typeof"("CUSTIE_UsageJSON") = 'object'::"text"))
);


ALTER TABLE "public"."Customs_InvoiceExtractions" OWNER TO "postgres";


COMMENT ON TABLE "public"."Customs_InvoiceExtractions" IS 'API-only commercial-invoice OCR jobs and normalized cache results. Raw PDFs are temporary private Storage objects.';



COMMENT ON COLUMN "public"."Customs_InvoiceExtractions"."CUSTIE_NormalizerVersion" IS 'Source validation and source-to-PDF rendering contract used before OCR.';



COMMENT ON COLUMN "public"."Customs_InvoiceExtractions"."CUSTIE_ConvertedSHA256" IS 'SHA-256 of the exact prepared PDF sent to OCR.';



COMMENT ON COLUMN "public"."Customs_InvoiceExtractions"."CUSTIE_ConversionJSON" IS 'Source format, conversion strategy, sheet inclusion and operator warnings.';



COMMENT ON COLUMN "public"."Customs_InvoiceExtractions"."CUSTIE_PreviewExpiresAt" IS 'Hard expiry for the private prepared-PDF review object; signed URLs are shorter lived.';



