CREATE OR REPLACE VIEW "public"."DOCB_FieldCatalogSummary" WITH ("security_invoker"='true') AS
 SELECT "ds"."DOCBDS_ID",
    "ds"."DOCBDS_Code",
    "ds"."DOCBDS_Name",
    "ds"."DOCBDS_DataScopeCode",
    "scope"."DOCBSC_Name" AS "DataScopeName",
    "ds"."DOCBDS_SourceTable",
    "ds"."DOCBDS_SourceView",
    "ds"."DOCBDS_IsSystem",
    "ds"."DOCBDS_IsActive",
    "field"."DOCBF_ID",
    "field"."DOCBF_FieldPath",
    "field"."DOCBF_Label",
    "field"."DOCBF_DataType",
    "field"."DOCBF_Description",
    "field"."DOCBF_IsRepeating",
    "field"."DOCBF_IsRequired",
    "field"."DOCBF_IsSensitive",
    "field"."DOCBF_FormatHint",
    "field"."DOCBF_SampleValue",
    "field"."DOCBF_SortOrder",
    "field"."DOCBF_IsActive"
   FROM (("public"."DOCB_FieldCatalog" "field"
     JOIN "public"."DOCB_DataSources" "ds" ON (("ds"."DOCBDS_ID" = "field"."DOCBF_DataSourceID")))
     LEFT JOIN "public"."sys_DocBuilderDataScopes" "scope" ON ((("scope"."DOCBSC_Code")::"text" = ("ds"."DOCBDS_DataScopeCode")::"text")));


ALTER VIEW "public"."DOCB_FieldCatalogSummary" OWNER TO "postgres";


