CREATE OR REPLACE VIEW "public"."DOCB_LibraryPackSummary" WITH ("security_invoker"='true') AS
 SELECT "pack"."DOCBLP_ID",
    "pack"."DOCBLP_Code",
    "pack"."DOCBLP_Name",
    "pack"."DOCBLP_DataScopeCode",
    "scope"."DOCBSC_Name" AS "DataScopeName",
    "pack"."DOCBLP_StatusCode",
    "status"."DOCBST_Name" AS "StatusName",
    "pack"."DOCBLP_OrgOfficeID",
    "office"."Office_Code" AS "OrgOfficeCode",
    "office"."Office_Name" AS "OrgOfficeName",
    "pack"."DOCBLP_LegalEntityID",
    "legal_entity"."LegalEntity_Name" AS "LegalEntityName",
    "pack"."DOCBLP_BrandID",
    "brand"."Brand_Name" AS "BrandName",
    "brand"."Brand_DisplayName" AS "BrandDisplayName",
    "pack"."DOCBLP_CustomerOrgID",
    "customer"."Org_Name" AS "CustomerOrgName",
    "pack"."DOCBLP_LanguageCode",
    "pack"."DOCBLP_Description",
    "pack"."DOCBLP_ModeCodesJSON",
    "pack"."DOCBLP_DirectionCodesJSON",
    "pack"."DOCBLP_CountryCodesJSON",
    "pack"."DOCBLP_IsSystem",
    "pack"."DOCBLP_IsUserEditable",
    "pack"."DOCBLP_IsActive",
    "pack"."DOCBLP_CreatedAt",
    "pack"."DOCBLP_UpdatedAt",
    ( SELECT ("count"(*))::integer AS "count"
           FROM "public"."DOCB_LibraryPackItems" "item"
          WHERE ("item"."DOCBLPI_LibraryPackID" = "pack"."DOCBLP_ID")) AS "ItemCount",
    ( SELECT ("count"(*))::integer AS "count"
           FROM "public"."DOCB_LibraryPackItems" "item"
          WHERE (("item"."DOCBLPI_LibraryPackID" = "pack"."DOCBLP_ID") AND ("item"."DOCBLPI_IsRequired" = true))) AS "RequiredItemCount",
    ( SELECT ("count"(*))::integer AS "count"
           FROM "public"."DOCB_LibraryPackItems" "item"
          WHERE (("item"."DOCBLPI_LibraryPackID" = "pack"."DOCBLP_ID") AND ("item"."DOCBLPI_IsGeneratedByDefault" = true))) AS "GeneratedByDefaultCount"
   FROM (((((("public"."DOCB_LibraryPacks" "pack"
     LEFT JOIN "public"."sys_DocBuilderDataScopes" "scope" ON ((("scope"."DOCBSC_Code")::"text" = ("pack"."DOCBLP_DataScopeCode")::"text")))
     LEFT JOIN "public"."sys_DocBuilderStatuses" "status" ON ((("status"."DOCBST_Code")::"text" = ("pack"."DOCBLP_StatusCode")::"text")))
     LEFT JOIN "public"."cmp_Offices" "office" ON (("office"."Office_ID" = "pack"."DOCBLP_OrgOfficeID")))
     LEFT JOIN "public"."cmp_LegalEntities" "legal_entity" ON (("legal_entity"."LegalEntity_ID" = "pack"."DOCBLP_LegalEntityID")))
     LEFT JOIN "public"."cmp_Brands" "brand" ON (("brand"."Brand_ID" = "pack"."DOCBLP_BrandID")))
     LEFT JOIN "public"."Org_Master" "customer" ON (("customer"."Org_id" = "pack"."DOCBLP_CustomerOrgID")));


