CREATE OR REPLACE VIEW "public"."DOCB_SectionGridSummary" WITH ("security_invoker"='true') AS
 SELECT "section"."DOCBS_ID",
    "section"."DOCBS_Code",
    "section"."DOCBS_Name",
    "section_version"."DOCBSV_ID",
    "section_version"."DOCBSV_VersionNo",
    "row_def"."DOCBSLR_ID",
    "row_def"."DOCBSLR_RowNo",
    "row_def"."DOCBSLR_RowType",
    "cell"."DOCBSLC_ID",
    "cell"."DOCBSLC_ColumnStart",
    "cell"."DOCBSLC_ColumnSpan",
    (("cell"."DOCBSLC_ColumnStart" + "cell"."DOCBSLC_ColumnSpan") - 1) AS "ColumnEnd",
    "block"."DOCBSLB_ID",
    "block"."DOCBSLB_BlockTypeCode",
    "block_type"."DOCBBT_Name" AS "BlockTypeName",
    "block"."DOCBSLB_SortOrder",
    "block"."DOCBSLB_DisplayLabel",
    "field"."DOCBF_FieldPath",
    "field"."DOCBF_Label" AS "FieldLabel",
    "clause"."DOCBCL_Code" AS "ClauseCode",
    "clause"."DOCBCL_Title" AS "ClauseTitle",
    "asset"."DOCBAS_Code" AS "AssetCode",
    "asset"."DOCBAS_Name" AS "AssetName",
    "block"."DOCBSLB_SecurityMarkTypeCode",
    "block"."DOCBSLB_IsRequired",
    "block"."DOCBSLB_BindingJSON",
    "block"."DOCBSLB_StyleJSON",
    "block"."DOCBSLB_ConditionJSON"
   FROM (((((((("public"."DOCB_SectionDefinitions" "section"
     JOIN "public"."DOCB_SectionVersions" "section_version" ON (("section_version"."DOCBSV_SectionID" = "section"."DOCBS_ID")))
     JOIN "public"."DOCB_SectionLayoutRows" "row_def" ON (("row_def"."DOCBSLR_SectionVersionID" = "section_version"."DOCBSV_ID")))
     JOIN "public"."DOCB_SectionLayoutCells" "cell" ON (("cell"."DOCBSLC_RowID" = "row_def"."DOCBSLR_ID")))
     LEFT JOIN "public"."DOCB_SectionLayoutBlocks" "block" ON (("block"."DOCBSLB_CellID" = "cell"."DOCBSLC_ID")))
     LEFT JOIN "public"."sys_DocBuilderBlockTypes" "block_type" ON ((("block_type"."DOCBBT_Code")::"text" = ("block"."DOCBSLB_BlockTypeCode")::"text")))
     LEFT JOIN "public"."DOCB_FieldCatalog" "field" ON (("field"."DOCBF_ID" = "block"."DOCBSLB_FieldCatalogID")))
     LEFT JOIN "public"."DOCB_ClauseLibrary" "clause" ON (("clause"."DOCBCL_ID" = "block"."DOCBSLB_ClauseID")))
     LEFT JOIN "public"."DOCB_AssetLibrary" "asset" ON (("asset"."DOCBAS_ID" = "block"."DOCBSLB_AssetID")));


