CREATE OR REPLACE VIEW "public"."DOCB_TemplatePageSummary" WITH ("security_invoker"='true') AS
 SELECT "template"."DOCBT_ID",
    "template"."DOCBT_Code",
    "template"."DOCBT_Name",
    "template_version"."DOCBTV_ID",
    "template_version"."DOCBTV_VersionNo",
    "page"."DOCBPG_ID",
    "page"."DOCBPG_PageTypeCode",
