CREATE OR REPLACE VIEW "public"."DOCB_TemplateQAIssueSummary" WITH ("security_invoker"='true') AS
 SELECT "qa_run"."DOCBQA_ID",
    "qa_run"."DOCBQA_TemplateID",
    "template"."DOCBT_Code",
    "template"."DOCBT_Name",
    "qa_run"."DOCBQA_TemplateVersionID",
