    "data_source"."DOCBDS_Code" AS "DataSourceCode",
    "data_source"."DOCBDS_Name" AS "DataSourceName",
    "section"."DOCBS_StatusCode",
    "section_status"."DOCBST_Name" AS "SectionStatusName",
    "template_section"."DOCBTS_ConfigOverrideJSON",
    "template_section"."DOCBTS_ConditionJSON",
    "template_section"."DOCBTS_BindingJSON"
   FROM ((((((("public"."DOCB_TemplateSections" "template_section"
     JOIN "public"."DOCB_TemplateVersions" "template_version" ON (("template_version"."DOCBTV_ID" = "template_section"."DOCBTS_TemplateVersionID")))
     JOIN "public"."DOCB_DocumentTemplates" "template" ON (("template"."DOCBT_ID" = "template_version"."DOCBTV_TemplateID")))
     JOIN "public"."DOCB_SectionDefinitions" "section" ON (("section"."DOCBS_ID" = "template_section"."DOCBTS_SectionID")))
     LEFT JOIN "public"."sys_DocBuilderSectionTypes" "section_type" ON ((("section_type"."DOCBSECT_Code")::"text" = ("section"."DOCBS_SectionTypeCode")::"text")))
     LEFT JOIN "public"."sys_DocBuilderDataScopes" "scope" ON ((("scope"."DOCBSC_Code")::"text" = ("section"."DOCBS_DataScopeCode")::"text")))
     LEFT JOIN "public"."DOCB_DataSources" "data_source" ON (("data_source"."DOCBDS_ID" = "section"."DOCBS_DataSourceID")))
     LEFT JOIN "public"."sys_DocBuilderStatuses" "section_status" ON ((("section_status"."DOCBST_Code")::"text" = ("section"."DOCBS_StatusCode")::"text")));


