CREATE OR REPLACE VIEW "public"."DOCSEC_VerificationSummary" WITH ("security_invoker"='true') AS
 SELECT "token"."DOCSECVT_ID",
    "token"."DOCSECVT_PublicCode",
    "token"."DOCSECVT_StatusCode",
    "token_status"."DOCSECTS_Name" AS "TokenStatusName",
    "token_status"."DOCSECTS_IsValidForPublicVerification" AS "TokenIsValidForPublicVerification",
    "token"."DOCSECVT_VerificationURL",
    "token"."DOCSECVT_TargetTable",
    "token"."DOCSECVT_TargetID",
    "token"."DOCSECVT_BLID",
    "bl"."BL_Number" AS "BLNumber",
    "bl"."BL_Status" AS "BLStatus",
    "token"."DOCSECVT_DocumentNumberSnapshot",
    "token"."DOCSECVT_JobDocumentID",
    "job_doc"."JobDoc_Title" AS "JobDocumentTitle",
    "job_doc"."JobDoc_FileName" AS "JobDocumentFileName",
    "token"."DOCSECVT_GeneratedDocumentID",
    "generated"."DOCBGD_FileName" AS "GeneratedFileName",
    "fingerprint"."DOCSECF_ID",
    "fingerprint"."DOCSECF_FileSHA256",
    "fingerprint"."DOCSECF_CanonicalPayloadSHA256",
    "fingerprint"."DOCSECF_FileName" AS "FingerprintFileName",
    "fingerprint"."DOCSECF_IsCurrent" AS "FingerprintIsCurrent",
    "signature"."DOCSECSIG_ID",
    "signature"."DOCSECSIG_AlgorithmCode",
    "signature"."DOCSECSIG_SignedAt",
    "signature"."DOCSECSIG_IsValid" AS "SignatureIsValid",
    "token"."DOCSECVT_ValidFrom",
    "token"."DOCSECVT_ExpiresAt",
    "token"."DOCSECVT_RevokedAt",
    "token"."DOCSECVT_VerificationCount",
    "token"."DOCSECVT_LastVerifiedAt",
    ( SELECT ("count"(*))::integer AS "count"
           FROM "public"."DOCSEC_VerificationEvents" "event"
          WHERE ("event"."DOCSECVE_VerificationTokenID" = "token"."DOCSECVT_ID")) AS "VerificationEventCount",
    ( SELECT ("count"(*))::integer AS "count"
           FROM "public"."DOCSEC_VerificationIssues" "issue"
          WHERE (("issue"."DOCSECI_VerificationTokenID" = "token"."DOCSECVT_ID") AND (("issue"."DOCSECI_Status")::"text" = 'open'::"text"))) AS "OpenIssueCount"
   FROM (((((("public"."DOCSEC_VerificationTokens" "token"
     LEFT JOIN "public"."sys_DocumentSecurityTokenStatuses" "token_status" ON ((("token_status"."DOCSECTS_Code")::"text" = ("token"."DOCSECVT_StatusCode")::"text")))
     LEFT JOIN "public"."BL_Header" "bl" ON (("bl"."BL_id" = "token"."DOCSECVT_BLID")))
     LEFT JOIN "public"."Job_Documents" "job_doc" ON (("job_doc"."JobDoc_ID" = "token"."DOCSECVT_JobDocumentID")))
     LEFT JOIN "public"."DOCB_GeneratedDocuments" "generated" ON (("generated"."DOCBGD_ID" = "token"."DOCSECVT_GeneratedDocumentID")))
     LEFT JOIN "public"."DOCSEC_DocumentFingerprints" "fingerprint" ON (("fingerprint"."DOCSECF_ID" = "token"."DOCSECVT_FingerprintID")))
     LEFT JOIN LATERAL ( SELECT "sig"."DOCSECSIG_ID",
            "sig"."DOCSECSIG_FingerprintID",
            "sig"."DOCSECSIG_SigningKeyID",
            "sig"."DOCSECSIG_AlgorithmCode",
            "sig"."DOCSECSIG_SignatureValue",
            "sig"."DOCSECSIG_ProofJSON",
            "sig"."DOCSECSIG_SignedAt",
            "sig"."DOCSECSIG_SignedBy",
            "sig"."DOCSECSIG_VerifiedAt",
            "sig"."DOCSECSIG_IsValid",
            "sig"."DOCSECSIG_MetadataJSON"
           FROM "public"."DOCSEC_DocumentSignatures" "sig"
          WHERE ("sig"."DOCSECSIG_FingerprintID" = "fingerprint"."DOCSECF_ID")
          ORDER BY "sig"."DOCSECSIG_SignedAt" DESC
         LIMIT 1) "signature" ON (true));


ALTER VIEW "public"."DOCSEC_VerificationSummary" OWNER TO "postgres";


