    "SignatureIsValid",
    "DOCSECVT_ValidFrom",
    "DOCSECVT_ExpiresAt",
    "DOCSECVT_RevokedAt",
    "DOCSECVT_VerificationCount",
    "DOCSECVT_LastVerifiedAt",
