    "bl"."BL_Number" AS "BLNumber",
    "request"."DOCSIGREQ_JobDocumentID",
    "job_doc"."JobDoc_Title" AS "JobDocumentTitle",
    "request"."DOCSIGREQ_GeneratedDocumentID",
    "generated"."DOCBGD_FileName" AS "GeneratedFileName",
    "request"."DOCSIGREQ_ProviderCode",
    "request"."DOCSIGREQ_ExternalEnvelopeID",
    "request"."DOCSIGREQ_StatusCode",
    "status"."DOCSIGS_Name" AS "StatusName",
    "status"."DOCSIGS_IsFinal" AS "StatusIsFinal",
    "status"."DOCSIGS_IsSuccessful" AS "StatusIsSuccessful",
    "request"."DOCSIGREQ_Subject",
    "request"."DOCSIGREQ_ExpiresAt",
    "request"."DOCSIGREQ_SentAt",
    "request"."DOCSIGREQ_CompletedAt",
    ( SELECT ("count"(*))::integer AS "count"
           FROM "public"."DOCSIG_Recipients" "recipient"
          WHERE ("recipient"."DOCSIGRC_RequestID" = "request"."DOCSIGREQ_ID")) AS "RecipientCount",
    ( SELECT ("count"(*))::integer AS "count"
           FROM "public"."DOCSIG_Recipients" "recipient"
          WHERE (("recipient"."DOCSIGRC_RequestID" = "request"."DOCSIGREQ_ID") AND (("recipient"."DOCSIGRC_StatusCode")::"text" = 'signed'::"text"))) AS "SignedRecipientCount",
    ( SELECT ("count"(*))::integer AS "count"
           FROM "public"."DOCSIG_Fields" "field"
          WHERE ("field"."DOCSIGF_RequestID" = "request"."DOCSIGREQ_ID")) AS "SignatureFieldCount"
   FROM (((("public"."DOCSIG_Requests" "request"
     LEFT JOIN "public"."sys_DocumentSignatureStatuses" "status" ON ((("status"."DOCSIGS_Code")::"text" = ("request"."DOCSIGREQ_StatusCode")::"text")))
     LEFT JOIN "public"."BL_Header" "bl" ON (("bl"."BL_id" = "request"."DOCSIGREQ_BLID")))
     LEFT JOIN "public"."Job_Documents" "job_doc" ON (("job_doc"."JobDoc_ID" = "request"."DOCSIGREQ_JobDocumentID")))
     LEFT JOIN "public"."DOCB_GeneratedDocuments" "generated" ON (("generated"."DOCBGD_ID" = "request"."DOCSIGREQ_GeneratedDocumentID")));


ALTER VIEW "public"."DOCSIG_RequestSummary" OWNER TO "postgres";


