CREATE OR REPLACE VIEW "public"."EDI_ExceptionQueue" WITH ("security_invoker"='true') AS
 SELECT "issue"."EDIVI_ID",
    "issue"."EDIVI_MessageID",
    "msg"."EDIMessage_DirectionCode",
    "msg"."EDIMessage_MessageTypeCode",
    "msg"."EDIMessage_StatusCode",
    "msg"."EDIMessage_TradingPartnerID",
    "tp"."EDITP_Name",
    "issue"."EDIVI_SeverityCode",
    "severity"."EDIVS_Name",
    "issue"."EDIVI_IssueCode",
    "issue"."EDIVI_FieldPath",
    "issue"."EDIVI_SegmentRef",
    "issue"."EDIVI_Description",
    "issue"."EDIVI_SuggestedFix",
    "issue"."EDIVI_IsBlocking",
    "issue"."EDIVI_StatusCode",
    "issue"."EDIVI_CreatedAt"
   FROM ((("public"."EDI_ValidationIssues" "issue"
     LEFT JOIN "public"."EDI_Messages" "msg" ON (("msg"."EDIMessage_ID" = "issue"."EDIVI_MessageID")))
     LEFT JOIN "public"."EDI_TradingPartners" "tp" ON (("tp"."EDITP_ID" = "msg"."EDIMessage_TradingPartnerID")))
     LEFT JOIN "public"."sys_EDIValidationSeverities" "severity" ON ((("severity"."EDIVS_Code")::"text" = ("issue"."EDIVI_SeverityCode")::"text")))
  WHERE (("issue"."EDIVI_StatusCode")::"text" = 'open'::"text");


