CREATE OR REPLACE VIEW "public"."FIN_CommissionAccrualSummary" WITH ("security_invoker"='true') AS
 SELECT "i"."FINCommItem_UserID",
    "r"."FINCommRun_PeriodID",
    "i"."FINCommItem_StatusCode",
    ("count"(*))::integer AS "FINComm_ItemCount",
    "sum"("i"."FINCommItem_CommissionAmount") AS "FINComm_TotalCommissionAmount"
   FROM ("public"."FIN_CommissionItems" "i"
     JOIN "public"."FIN_CommissionRuns" "r" ON (("r"."FINCommRun_ID" = "i"."FINCommItem_RunID")))
  GROUP BY "i"."FINCommItem_UserID", "r"."FINCommRun_PeriodID", "i"."FINCommItem_StatusCode";


