CREATE OR REPLACE VIEW "public"."FIN_JobChargeProfitability" WITH ("security_invoker"='true') AS
 WITH "actual" AS (
         SELECT "link"."FINDocLineJob_JobCostingLineID" AS "line_id",
            COALESCE("sum"("link"."FINDocLineJob_LocalNetAmount") FILTER (WHERE (("document"."FINDoc_TypeCode")::"text" = ANY ((ARRAY['sl_invoice'::character varying, 'credit_note'::character varying])::"text"[]))), (0)::numeric) AS "actual_revenue",
            COALESCE("sum"("link"."FINDocLineJob_LocalNetAmount") FILTER (WHERE (("document"."FINDoc_TypeCode")::"text" = ANY ((ARRAY['pl_invoice'::character varying, 'debit_note'::character varying])::"text"[]))), (0)::numeric) AS "actual_cost"
           FROM ("public"."FIN_DocumentLineJobLinks" "link"
             JOIN "public"."FIN_Documents" "document" ON ((("document"."FINDoc_ID" = "link"."FINDocLineJob_DocumentID") AND (("document"."FINDoc_PostingStatusCode")::"text" = 'posted'::"text"))))
          WHERE ("link"."FINDocLineJob_JobCostingLineID" IS NOT NULL)
          GROUP BY "link"."FINDocLineJob_JobCostingLineID"
        ), "balances" AS (
         SELECT "line_1"."JobCostingLine_ID" AS "line_id",
            COALESCE(( SELECT "sum"(("wip"."FINWIP_LocalWIPAmount" - "wip"."FINWIP_RelievedAmount")) AS "sum"
                   FROM "public"."FIN_WIPItems" "wip"
                  WHERE (("wip"."FINWIP_JobCostingLineID" = "line_1"."JobCostingLine_ID") AND (("wip"."FINWIP_StatusCode")::"text" = ANY ((ARRAY['posted'::character varying, 'partially_reversed'::character varying])::"text"[])))), (0)::numeric) AS "open_wip",
            COALESCE(( SELECT "sum"(("accrual"."FINAccrual_LocalAccruedAmount" - "accrual"."FINAccrual_RelievedAmount")) AS "sum"
                   FROM "public"."FIN_Accruals" "accrual"
                  WHERE (("accrual"."FINAccrual_JobCostingLineID" = "line_1"."JobCostingLine_ID") AND (("accrual"."FINAccrual_StatusCode")::"text" = ANY ((ARRAY['posted'::character varying, 'partially_reversed'::character varying])::"text"[])))), (0)::numeric) AS "open_accrual"
           FROM "public"."Job_Costing_Lines" "line_1"
        )
 SELECT "line"."JobCostingLine_ID" AS "FINChargeProfit_JobCostingLineID",
    "line"."Job_ID" AS "FINChargeProfit_JobID",
    "line"."JobCostingLine_Number" AS "FINChargeProfit_LineNo",
    "charge"."RATECharge_Code" AS "FINChargeProfit_ChargeCode",
    "line"."JobCostingLine_Description" AS "FINChargeProfit_Description",
    "line"."JobCostingLine_CostNominalAccountID" AS "FINChargeProfit_CostNominalAccountID",
    "cost_nominal"."FINNom_Code" AS "FINChargeProfit_CostNominalCode",
    "line"."JobCostingLine_RevenueNominalAccountID" AS "FINChargeProfit_RevenueNominalAccountID",
    "revenue_nominal"."FINNom_Code" AS "FINChargeProfit_RevenueNominalCode",
    COALESCE("line"."JobCostingLine_RevenueAmountLocal", (0)::numeric) AS "FINChargeProfit_ExpectedRevenue",
    COALESCE("line"."JobCostingLine_CostAmountLocal", (0)::numeric) AS "FINChargeProfit_ExpectedCost",
    COALESCE("actual"."actual_revenue", (0)::numeric) AS "FINChargeProfit_ActualRevenue",
    COALESCE("actual"."actual_cost", (0)::numeric) AS "FINChargeProfit_ActualCost",
    COALESCE("balances"."open_wip", (0)::numeric) AS "FINChargeProfit_OpenWIP",
    COALESCE("balances"."open_accrual", (0)::numeric) AS "FINChargeProfit_OpenAccrual",
    (COALESCE("actual"."actual_revenue", (0)::numeric) + COALESCE("balances"."open_wip", (0)::numeric)) AS "FINChargeProfit_RecognisedRevenue",
    (COALESCE("actual"."actual_cost", (0)::numeric) + COALESCE("balances"."open_accrual", (0)::numeric)) AS "FINChargeProfit_RecognisedCost",
    (((COALESCE("actual"."actual_revenue", (0)::numeric) + COALESCE("balances"."open_wip", (0)::numeric)) - COALESCE("actual"."actual_cost", (0)::numeric)) - COALESCE("balances"."open_accrual", (0)::numeric)) AS "FINChargeProfit_GrossProfit",
    ((COALESCE("actual"."actual_revenue", (0)::numeric) + COALESCE("balances"."open_wip", (0)::numeric)) - COALESCE("line"."JobCostingLine_RevenueAmountLocal", (0)::numeric)) AS "FINChargeProfit_RevenueMovement",
    ((COALESCE("actual"."actual_cost", (0)::numeric) + COALESCE("balances"."open_accrual", (0)::numeric)) - COALESCE("line"."JobCostingLine_CostAmountLocal", (0)::numeric)) AS "FINChargeProfit_CostMovement",
    "line"."JobCostingLine_DomainCode" AS "FINChargeProfit_DomainCode",
    "line"."JobCostingLine_SourceTable" AS "FINChargeProfit_SourceTable",
    "line"."JobCostingLine_SourceID" AS "FINChargeProfit_SourceID",
    "line"."JobCostingLine_SourceLineID" AS "FINChargeProfit_SourceLineID"
   FROM ((((("public"."Job_Costing_Lines" "line"
     LEFT JOIN "public"."RATE_ChargeCodes" "charge" ON (("charge"."RATECharge_ID" = "line"."JobCostingLine_ChargeCodeID")))
     LEFT JOIN "public"."FIN_NominalAccounts" "cost_nominal" ON (("cost_nominal"."FINNom_ID" = "line"."JobCostingLine_CostNominalAccountID")))
     LEFT JOIN "public"."FIN_NominalAccounts" "revenue_nominal" ON (("revenue_nominal"."FINNom_ID" = "line"."JobCostingLine_RevenueNominalAccountID")))
     LEFT JOIN "actual" ON (("actual"."line_id" = "line"."JobCostingLine_ID")))
     LEFT JOIN "balances" ON (("balances"."line_id" = "line"."JobCostingLine_ID")));


