CREATE OR REPLACE VIEW "public"."FIN_JobFinanceSummary" WITH ("security_invoker"='true') AS
 SELECT "prior"."Job_ID",
    "prior"."Job_Number",
    "prior"."Job_Customer",
    "prior"."Job_CustomerName",
    "prior"."FINJob_LocalRevenue",
    "prior"."FINJob_LocalCost",
    "prior"."FINJob_LocalWIP",
    "prior"."FINJob_LocalAccrual",
    "prior"."FINJob_LocalMargin"
   FROM (( SELECT "j_1"."Job_ID",
            "j_1"."Job_Number",
            "j_1"."Job_Customer",
            "cust"."Org_Name" AS "Job_CustomerName",
            COALESCE("sum"(
                CASE
                    WHEN (("d"."FINDoc_TypeCode")::"text" = ANY (ARRAY[('sl_invoice'::character varying)::"text", ('debit_note'::character varying)::"text"])) THEN "l"."FINDocLineJob_LocalNetAmount"
                    ELSE (0)::numeric
                END), (0)::numeric) AS "FINJob_LocalRevenue",
            COALESCE("sum"(
                CASE
                    WHEN (("d"."FINDoc_TypeCode")::"text" = 'pl_invoice'::"text") THEN "l"."FINDocLineJob_LocalNetAmount"
                    ELSE (0)::numeric
                END), (0)::numeric) AS "FINJob_LocalCost",
            COALESCE(( SELECT "sum"(("w"."FINWIP_LocalWIPAmount" - "w"."FINWIP_RelievedAmount")) AS "sum"
                   FROM "public"."FIN_WIPItems" "w"
                  WHERE ("w"."FINWIP_JobID" = "j_1"."Job_ID")), (0)::numeric) AS "FINJob_LocalWIP",
            COALESCE(( SELECT "sum"(("a"."FINAccrual_LocalAccruedAmount" - "a"."FINAccrual_RelievedAmount")) AS "sum"
                   FROM "public"."FIN_Accruals" "a"
                  WHERE ("a"."FINAccrual_JobID" = "j_1"."Job_ID")), (0)::numeric) AS "FINJob_LocalAccrual",
            COALESCE("sum"(
                CASE
                    WHEN (("d"."FINDoc_TypeCode")::"text" = ANY (ARRAY[('sl_invoice'::character varying)::"text", ('debit_note'::character varying)::"text"])) THEN "l"."FINDocLineJob_LocalNetAmount"
                    ELSE (- "l"."FINDocLineJob_LocalNetAmount")
                END), (0)::numeric) AS "FINJob_LocalMargin"
           FROM ((("public"."Job_Header" "j_1"
             LEFT JOIN "public"."Org_Master" "cust" ON (("cust"."Org_id" = "j_1"."Job_Customer")))
             LEFT JOIN "public"."FIN_DocumentLineJobLinks" "l" ON (("l"."FINDocLineJob_JobID" = "j_1"."Job_ID")))
             LEFT JOIN "public"."FIN_Documents" "d" ON (("d"."FINDoc_ID" = "l"."FINDocLineJob_DocumentID")))
          GROUP BY "j_1"."Job_ID", "j_1"."Job_Number", "j_1"."Job_Customer", "cust"."Org_Name") "prior"
     JOIN "public"."Job_Header" "j" ON (("j"."Job_ID" = "prior"."Job_ID")))
  WHERE ("lower"(("j"."Job_Status")::"text") <> ALL (ARRAY['draft'::"text", 'provisional'::"text"]));


ALTER VIEW "public"."FIN_JobFinanceSummary" OWNER TO "postgres";


COMMENT ON VIEW "public"."FIN_JobFinanceSummary" IS 'Service-bound job finance summary. Invoker rights prevent owner-privilege RLS bypass.';



