CREATE OR REPLACE VIEW "public"."FIN_ROEWorklist" WITH ("security_invoker"='true') AS
 SELECT "FINChargeROE_ID",
    "FINChargeROE_SourceTable",
    "FINChargeROE_SourceID",
    "FINChargeROE_JobID",
    "FINChargeROE_FromCurrencyCode",
    "FINChargeROE_ToCurrencyCode",
    "FINChargeROE_ROETypeCode",
    "FINChargeROE_RateDate",
    "FINChargeROE_Rate",
        CASE
            WHEN ("FINChargeROE_RateDate" < (CURRENT_DATE - 7)) THEN true
            ELSE false
        END AS "FINChargeROE_IsStale",
        CASE
            WHEN (("FINChargeROE_ProviderRateID" IS NULL) AND (("FINChargeROE_ROETypeCode")::"text" = ANY ((ARRAY['system_mid_market'::character varying, 'customs_hmrc'::character varying])::"text"[]))) THEN true
            ELSE false
        END AS "FINChargeROE_MissingProviderRate"
   FROM "public"."FIN_ChargeROEApplications" "a";


