    "ICUSS_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "ICUSS_ApiConnectionID" "uuid",
    "ICUSS_CustomsID" "uuid",
    "ICUSS_JurisdictionCode" character varying(20),
    "ICUSS_DeclarationKind" character varying(40) NOT NULL,
    "ICUSS_CDSID" "uuid",
    "ICUSS_T1ID" "uuid",
    "ICUSS_Status" character varying(40) DEFAULT 'queued'::character varying NOT NULL,
    "ICUSS_IdempotencyKey" character varying(160),
    "ICUSS_iCustomsDeclarationID" character varying(160),
    "ICUSS_iCustomsSubmissionID" character varying(160),
    "ICUSS_HMRCSubmissionID" character varying(160),
    "ICUSS_MRN" character varying(80),
    "ICUSS_LRN" character varying(80),
    "ICUSS_RequestMethod" character varying(20) DEFAULT 'POST'::character varying NOT NULL,
    "ICUSS_RequestPath" character varying(240),
    "ICUSS_RequestHeadersJSON" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "ICUSS_RequestPayloadJSON" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "ICUSS_ResponseStatusCode" integer,
    "ICUSS_ResponseHeadersJSON" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "ICUSS_ResponsePayloadJSON" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "ICUSS_ErrorCode" character varying(120),
    "ICUSS_ErrorMessage" "text",
    "ICUSS_AttemptCount" integer DEFAULT 0 NOT NULL,
    "ICUSS_NextRetryAt" timestamp with time zone,
    "ICUSS_SubmittedAt" timestamp with time zone,
    "ICUSS_AcknowledgedAt" timestamp with time zone,
    "ICUSS_CompletedAt" timestamp with time zone,
    "ICUSS_CreatedAt" timestamp with time zone DEFAULT "now"() NOT NULL,
    "ICUSS_CreatedBy" "uuid",
    "ICUSS_UpdatedAt" timestamp with time zone DEFAULT "now"() NOT NULL,
    "ICUSS_UpdatedBy" "uuid",
    "ICUSS_DeclarationSnapshotJSON" "jsonb",
    "ICUSS_ProviderStatus" "text",
    CONSTRAINT "CK_ICUS_Submissions_declaration_snapshot" CHECK ((("ICUSS_DeclarationSnapshotJSON" IS NULL) OR (("jsonb_typeof"("ICUSS_DeclarationSnapshotJSON") = 'object'::"text") AND ("jsonb_typeof"(("ICUSS_DeclarationSnapshotJSON" -> 'schemaVersion'::"text")) = 'number'::"text") AND (("ICUSS_DeclarationSnapshotJSON" ->> 'schemaVersion'::"text") = '1'::"text") AND ("jsonb_typeof"(("ICUSS_DeclarationSnapshotJSON" -> 'declaration'::"text")) = 'object'::"text") AND ("jsonb_typeof"(("ICUSS_DeclarationSnapshotJSON" -> 'items'::"text")) = 'array'::"text")))),
    CONSTRAINT "ICUS_Submissions_attempt_check" CHECK (("ICUSS_AttemptCount" >= 0)),
    CONSTRAINT "ICUS_Submissions_target_check" CHECK (("num_nonnulls"("ICUSS_CustomsID", "ICUSS_CDSID", "ICUSS_T1ID") = 1))
);


ALTER TABLE "public"."ICUS_Submissions" OWNER TO "postgres";


COMMENT ON COLUMN "public"."ICUS_Submissions"."ICUSS_DeclarationSnapshotJSON" IS 'Immutable server-captured Customs_Declarations and Customs_Items snapshot at the exact submit boundary. Used for accepted official document generation.';



COMMENT ON COLUMN "public"."ICUS_Submissions"."ICUSS_ProviderStatus" IS 'Exact provider lifecycle status before Multideck maps released or cleared to its accepted completion state.';



