CREATE OR REPLACE VIEW "public"."Job_ShipmentSummary" WITH ("security_invoker"='true') AS
 SELECT "j"."Job_ID",
    "j"."Job_Number",
    "j"."Job_Period",
    "j"."Job_Status",
    "j"."Job_Direction",
    "j"."Job_TransportModeSummary",
    "j"."Job_Customer",
    "j"."Job_OrgOfficeID",
    "j"."Job_OriginUNLocode",
    "j"."Job_OriginNameSnapshot",
    "j"."Job_DestinationUNLocode",
    "j"."Job_DestinationNameSnapshot",
    "j"."Job_TrackingStatus",
    "j"."Job_CurrentLocationUNLocode",
    "j"."Job_CurrentLocationNameSnapshot",
    "j"."Job_LastTrackedAt",
    "j"."Job_PredictedDeliveryAt",
    "j"."Job_TrackingRiskScore",
    "j"."Job_CreatedDate",
    ("count"(DISTINCT "r"."JobRoute_ID"))::integer AS "Job_LegCount",
    ("count"(DISTINCT "c"."JobCargo_ID"))::integer AS "Job_CargoLineCount",
    ("count"(DISTINCT "e"."JobContainers_ID"))::integer AS "Job_EquipmentCount",
    ("count"(DISTINCT "d"."JobDoc_ID"))::integer AS "Job_DocumentCount",
    ("count"(DISTINCT "te"."JobTrackEvent_ID"))::integer AS "Job_TrackingEventCount",
    ("count"(DISTINCT "tex"."JobTrackEx_ID") FILTER (WHERE (("tex"."JobTrackEx_Status")::"text" <> 'resolved'::"text")))::integer AS "Job_OpenExceptionCount"
   FROM (((((("public"."Job_Header" "j"
     LEFT JOIN "public"."Job_Routing" "r" ON (("r"."Job_ID" = "j"."Job_ID")))
     LEFT JOIN "public"."Job_Cargo" "c" ON ((("c"."JobCargo_JobID" = "j"."Job_ID") AND (COALESCE("c"."JobCargo_IsDeleted", false) = false))))
     LEFT JOIN "public"."Job_Containers" "e" ON ((("e"."Job_ID" = "j"."Job_ID") AND (COALESCE("e"."JobContainer_IsDeleted", false) = false))))
     LEFT JOIN "public"."Job_Documents" "d" ON ((("d"."JobDoc_JobID" = "j"."Job_ID") AND (COALESCE("d"."JobDoc_IsDeleted", false) = false))))
     LEFT JOIN "public"."Job_TrackingEvents" "te" ON (("te"."JobTrackEvent_JobID" = "j"."Job_ID")))
     LEFT JOIN "public"."Job_TrackingExceptions" "tex" ON ((("tex"."JobTrackEx_JobID" = "j"."Job_ID") AND (("tex"."JobTrackEx_Status")::"text" <> ALL ((ARRAY['resolved'::character varying, 'dismissed'::character varying])::"text"[])))))
  WHERE (COALESCE("j"."Job_IsDeleted", false) = false)
  GROUP BY "j"."Job_ID", "j"."Job_Number", "j"."Job_Period", "j"."Job_Status", "j"."Job_Direction", "j"."Job_TransportModeSummary", "j"."Job_Customer", "j"."Job_OrgOfficeID", "j"."Job_OriginUNLocode", "j"."Job_OriginNameSnapshot", "j"."Job_DestinationUNLocode", "j"."Job_DestinationNameSnapshot", "j"."Job_TrackingStatus", "j"."Job_CurrentLocationUNLocode", "j"."Job_CurrentLocationNameSnapshot", "j"."Job_LastTrackedAt", "j"."Job_PredictedDeliveryAt", "j"."Job_TrackingRiskScore", "j"."Job_CreatedDate";


ALTER VIEW "public"."Job_ShipmentSummary" OWNER TO "postgres";


