CREATE OR REPLACE VIEW "public"."Job_TrackingCurrentStatus" WITH ("security_invoker"='true') AS
 SELECT "j"."Job_ID",
    "j"."Job_Number",
    "j"."Job_Period",
    "j"."Job_Status",
    "j"."Job_TrackingStatus",
    "j"."Job_CurrentLocationUNLocode",
    "j"."Job_CurrentLocationNameSnapshot",
    "j"."Job_LastTrackedAt",
    "j"."Job_PredictedDeliveryAt",
    "j"."Job_TrackingRiskScore",
    "latest_event"."JobTrackEvent_ID" AS "LatestTrackingEventID",
    "latest_event"."JobTrackEvent_NormalizedEventType" AS "LatestTrackingEventType",
    "latest_event"."JobTrackEvent_EventSummary" AS "LatestTrackingSummary",
    "latest_event"."JobTrackEvent_EventTime" AS "LatestTrackingEventTime",
    "latest_event"."JobTrackEvent_SourceType" AS "LatestTrackingSourceType",
    "latest_event"."JobTrackEvent_SourceName" AS "LatestTrackingSourceName",
    "open_exceptions"."OpenExceptionCount",
    "open_exceptions"."HighestOpenExceptionSeverity"
   FROM (("public"."Job_Header" "j"
     LEFT JOIN LATERAL ( SELECT "e"."JobTrackEvent_ID",
            "e"."JobTrackEvent_JobID",
            "e"."JobTrackEvent_JobRouteID",
            "e"."JobTrackEvent_JobCargoID",
            "e"."JobTrackEvent_JobContainerID",
            "e"."JobTrackEvent_SubscriptionID",
            "e"."JobTrackEvent_SourceType",
            "e"."JobTrackEvent_SourceName",
            "e"."JobTrackEvent_SourceEventID",
            "e"."JobTrackEvent_SourceEventCode",
            "e"."JobTrackEvent_NormalizedEventType",
            "e"."JobTrackEvent_EventStatus",
            "e"."JobTrackEvent_EventSummary",
            "e"."JobTrackEvent_EventTime",
            "e"."JobTrackEvent_ReportedAt",
            "e"."JobTrackEvent_ReceivedAt",
            "e"."JobTrackEvent_LocationUNLocode",
            "e"."JobTrackEvent_LocationIATACode",
            "e"."JobTrackEvent_LocationNameSnapshot",
            "e"."JobTrackEvent_CountryCodeSnapshot",
            "e"."JobTrackEvent_Latitude",
            "e"."JobTrackEvent_Longitude",
            "e"."JobTrackEvent_ConfidenceScore",
            "e"."JobTrackEvent_IsException",
            "e"."JobTrackEvent_IsCustomerVisible",
            "e"."JobTrackEvent_DedupeHash",
            "e"."JobTrackEvent_RawPayloadJSON",
            "e"."JobTrackEvent_NormalizedPayloadJSON",
            "e"."JobTrackEvent_CreatedAt"
           FROM "public"."Job_TrackingEvents" "e"
          WHERE ("e"."JobTrackEvent_JobID" = "j"."Job_ID")
          ORDER BY "e"."JobTrackEvent_EventTime" DESC, "e"."JobTrackEvent_ReceivedAt" DESC
         LIMIT 1) "latest_event" ON (true))
     LEFT JOIN LATERAL ( SELECT ("count"(*))::integer AS "OpenExceptionCount",
                CASE
                    WHEN "bool_or"((("x"."JobTrackEx_Severity")::"text" = 'critical'::"text")) THEN 'critical'::"text"
                    WHEN "bool_or"((("x"."JobTrackEx_Severity")::"text" = 'high'::"text")) THEN 'high'::"text"
                    WHEN "bool_or"((("x"."JobTrackEx_Severity")::"text" = 'medium'::"text")) THEN 'medium'::"text"
                    WHEN "bool_or"((("x"."JobTrackEx_Severity")::"text" = 'low'::"text")) THEN 'low'::"text"
                    ELSE NULL::"text"
                END AS "HighestOpenExceptionSeverity"
           FROM "public"."Job_TrackingExceptions" "x"
          WHERE (("x"."JobTrackEx_JobID" = "j"."Job_ID") AND (("x"."JobTrackEx_Status")::"text" <> ALL ((ARRAY['resolved'::character varying, 'dismissed'::character varying])::"text"[])))) "open_exceptions" ON (true))
  WHERE (COALESCE("j"."Job_IsDeleted", false) = false);


