CREATE OR REPLACE VIEW "public"."LOC_UserEffectivePreferences" WITH ("security_invoker"='true') AS
 SELECT "u"."User_ID",
    "u"."Company_ID",
    COALESCE("up"."LOCUserPref_LocaleCode", "p"."LOCProfile_LocaleCode", 'en-GB'::character varying) AS "LocaleCode",
    COALESCE("up"."LOCUserPref_TimeZoneCode", "p"."LOCProfile_TimeZoneCode", 'UTC'::character varying) AS "TimeZoneCode",
    COALESCE("up"."LOCUserPref_DateFormatCode", "p"."LOCProfile_DateFormatCode", "l"."LOCLocale_DefaultDateFormatCode", 'iso_ymd'::character varying) AS "DateFormatCode",
    COALESCE("up"."LOCUserPref_TimeFormatCode", "p"."LOCProfile_TimeFormatCode", "l"."LOCLocale_DefaultTimeFormatCode", '24h_hm'::character varying) AS "TimeFormatCode",
    COALESCE("up"."LOCUserPref_NumberFormatCode", "p"."LOCProfile_NumberFormatCode", "l"."LOCLocale_DefaultNumberFormatCode", 'uk'::character varying) AS "NumberFormatCode",
    COALESCE("up"."LOCUserPref_MeasurementSystemCode", "p"."LOCProfile_MeasurementSystemCode", 'metric'::character varying) AS "MeasurementSystemCode",
    COALESCE("up"."LOCUserPref_PaperSizeCode", "p"."LOCProfile_PaperSizeCode", 'A4'::character varying) AS "PaperSizeCode",
    COALESCE("up"."LOCUserPref_WeekStartCode", "p"."LOCProfile_WeekStartCode", 'monday'::character varying) AS "WeekStartCode",
    COALESCE("up"."LOCUserPref_CurrencyCode", "p"."LOCProfile_CurrencyCode") AS "CurrencyCode",
    COALESCE("up"."LOCUserPref_DisplayTimeZoneModeCode", "p"."LOCProfile_DisplayTimeZoneModeCode", 'source_only_hover'::character varying) AS "DisplayTimeZoneModeCode"
   FROM ((("public"."cmp_Users" "u"
     LEFT JOIN "public"."LOC_UserPreferences" "up" ON ((("up"."User_ID" = "u"."User_ID") AND ("up"."LOCUserPref_IsActive" = true))))
     LEFT JOIN "public"."LOC_LocalisationProfiles" "p" ON (("p"."LOCProfile_ID" = "up"."LOCProfile_ID")))
     LEFT JOIN "public"."sys_LOCLocales" "l" ON ((("l"."LOCLocale_Code")::"text" = (COALESCE("up"."LOCUserPref_LocaleCode", "p"."LOCProfile_LocaleCode", 'en-GB'::character varying))::"text")));


