CREATE OR REPLACE VIEW "public"."MDX_FederationDashboard" WITH ("security_invoker"='true') AS
 SELECT "agreement"."MDXAgreement_ID",
    "agreement"."MDXAgreement_Code",
    "agreement"."MDXAgreement_Name",
    "agreement"."MDXAgreement_StatusCode",
    "agreement"."MDXAgreement_DirectionCode",
    "agreement"."MDXAgreement_LocalRoleCode",
    "agreement"."MDXAgreement_RemoteRoleCode",
    "peer"."CommPeer_ID",
    "peer"."CommPeer_DisplayName",
    "peer"."CommPeer_StatusCode",
    "peer"."CommPeer_TrustLevelCode",
    ("count"("sj"."MDXSharedJob_ID"))::integer AS "MDXAgreement_SharedJobCount",
    ("count"("sj"."MDXSharedJob_ID") FILTER (WHERE (("sj"."MDXSharedJob_StatusCode")::"text" = ANY ((ARRAY['received'::character varying, 'conflict'::character varying])::"text"[]))))::integer AS "MDXAgreement_OpenSharedJobCount",
    "max"("sj"."MDXSharedJob_LastInboundSyncAt") AS "MDXAgreement_LastInboundSyncAt",
    "max"("sj"."MDXSharedJob_LastOutboundSyncAt") AS "MDXAgreement_LastOutboundSyncAt"
   FROM (("public"."MDX_ShareAgreements" "agreement"
     JOIN "public"."Comm_FederationPeers" "peer" ON (("peer"."CommPeer_ID" = "agreement"."MDXAgreement_PeerID")))
     LEFT JOIN "public"."MDX_SharedJobs" "sj" ON ((("sj"."MDXSharedJob_AgreementID" = "agreement"."MDXAgreement_ID") AND ("sj"."MDXSharedJob_IsDeleted" = false))))
  WHERE ("agreement"."MDXAgreement_IsDeleted" = false)
  GROUP BY "agreement"."MDXAgreement_ID", "agreement"."MDXAgreement_Code", "agreement"."MDXAgreement_Name", "agreement"."MDXAgreement_StatusCode", "agreement"."MDXAgreement_DirectionCode", "agreement"."MDXAgreement_LocalRoleCode", "agreement"."MDXAgreement_RemoteRoleCode", "peer"."CommPeer_ID", "peer"."CommPeer_DisplayName", "peer"."CommPeer_StatusCode", "peer"."CommPeer_TrustLevelCode";


ALTER VIEW "public"."MDX_FederationDashboard" OWNER TO "postgres";


