CREATE OR REPLACE VIEW "public"."OBS_OpenExceptionQueue" WITH ("security_invoker"='true') AS
 SELECT "OBSException_ID" AS "ExceptionID",
    "OBSException_ModuleCode" AS "ModuleCode",
    "OBSException_SourceTable" AS "SourceTable",
    "OBSException_SourceID" AS "SourceID",
    "OBSException_SeverityCode" AS "SeverityCode",
    "OBSException_StatusCode" AS "StatusCode",
    "OBSException_Title" AS "Title",
    "OBSException_Message" AS "Message",
    "OBSException_AssignedToUserID" AS "AssignedToUserID",
    "OBSException_DueAt" AS "DueAt",
    "OBSException_CreatedAt" AS "CreatedAt",
    (EXTRACT(epoch FROM ("now"() - "OBSException_CreatedAt")) / 3600.0) AS "AgeHours"
   FROM "public"."OBS_ExceptionQueue" "q"
  WHERE (("OBSException_StatusCode")::"text" = ANY ((ARRAY['queued'::character varying, 'open'::character varying, 'in_progress'::character varying, 'waiting'::character varying])::"text"[]));


