CREATE OR REPLACE VIEW "public"."OBS_RetryQueueDue" WITH ("security_invoker"='true') AS
 SELECT "OBSRetry_ID" AS "RetryID",
    "OBSRetry_ModuleCode" AS "ModuleCode",
    "OBSRetry_SourceTable" AS "SourceTable",
    "OBSRetry_SourceID" AS "SourceID",
    "OBSRetry_StatusCode" AS "StatusCode",
