    "OBSRetry_LastErrorMessage" AS "LastErrorMessage",
    "OBSRetry_CorrelationID" AS "CorrelationID"
   FROM "public"."OBS_RetryQueue" "r"
  WHERE ((("OBSRetry_StatusCode")::"text" = ANY ((ARRAY['queued'::character varying, 'open'::character varying, 'waiting'::character varying])::"text"[])) AND ("OBSRetry_NextAttemptAt" <= "now"()) AND ("OBSRetry_AttemptCount" < "OBSRetry_MaxAttempts"));


