CREATE TABLE IF NOT EXISTS "public"."OPS_LifecycleNotes" (
    "LifecycleNote_ID" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "LifecycleNote_CompanyID" "uuid" NOT NULL,
    "LifecycleNote_SubjectType" "text" NOT NULL,
    "LifecycleNote_SubjectID" "uuid" NOT NULL,
    "LifecycleNote_QuoteID" "uuid",
    "LifecycleNote_JobID" "uuid",
    "LifecycleNote_CustomsID" "uuid",
    "LifecycleNote_Body" "text" NOT NULL,
    "LifecycleNote_AuthorUserID" "uuid",
    "LifecycleNote_AuthorNameSnapshot" "text" NOT NULL,
    "LifecycleNote_CreatedAt" timestamp with time zone DEFAULT "now"() NOT NULL,
    "LifecycleNote_UpdatedAt" timestamp with time zone,
    "LifecycleNote_DeletedAt" timestamp with time zone,
    "LifecycleNote_DeletedByUserID" "uuid",
    CONSTRAINT "CK_OPS_LifecycleNotes_body" CHECK ((("btrim"("LifecycleNote_Body") <> ''::"text") AND ("char_length"("LifecycleNote_Body") <= 4000))),
    CONSTRAINT "CK_OPS_LifecycleNotes_subject" CHECK (((("LifecycleNote_SubjectType" = 'quote'::"text") AND ("LifecycleNote_SubjectID" = "LifecycleNote_QuoteID") AND ("LifecycleNote_JobID" IS NULL) AND ("LifecycleNote_CustomsID" IS NULL)) OR (("LifecycleNote_SubjectType" = 'booking'::"text") AND ("LifecycleNote_SubjectID" = "LifecycleNote_JobID") AND ("LifecycleNote_CustomsID" IS NULL)) OR (("LifecycleNote_SubjectType" = 'customs'::"text") AND ("LifecycleNote_SubjectID" = "LifecycleNote_CustomsID")) OR (("LifecycleNote_SubjectType" = 'company'::"text") AND ("LifecycleNote_QuoteID" IS NULL) AND ("LifecycleNote_JobID" IS NULL) AND ("LifecycleNote_CustomsID" IS NULL)))),
    CONSTRAINT "OPS_LifecycleNotes_LifecycleNote_SubjectType_check" CHECK (("LifecycleNote_SubjectType" = ANY (ARRAY['quote'::"text", 'booking'::"text", 'customs'::"text", 'company'::"text"])))
);


