    CONSTRAINT "RATE_RateSheets_validity_check" CHECK ((("RATESheet_ValidTo" IS NULL) OR ("RATESheet_ValidFrom" IS NULL) OR ("RATESheet_ValidTo" >= "RATESheet_ValidFrom")))
);


