CREATE OR REPLACE VIEW "public"."RPT_MVPDashboardCatalog" WITH ("security_invoker"='true') AS
 SELECT "d"."RPTDash_Code" AS "DashboardCode",
    "d"."RPTDash_Name" AS "DashboardName",
    "d"."RPTDash_TypeCode" AS "DashboardTypeCode",
    "d"."RPTDash_ModuleCode" AS "ModuleCode",
    "d"."RPTDash_Description" AS "DashboardDescription",
    "d"."RPTDash_MinPermissionCode" AS "MinPermissionCode",
    "d"."RPTDash_DefaultRefreshCode" AS "DefaultRefreshCode",
    "w"."RPTWidget_Code" AS "WidgetCode",
    "w"."RPTWidget_Name" AS "WidgetName",
    "w"."RPTWidget_TypeCode" AS "WidgetTypeCode",
    "w"."RPTWidget_MetricCode" AS "MetricCode",
    "w"."RPTWidget_SortOrder" AS "WidgetSortOrder"
   FROM ("public"."RPT_Dashboards" "d"
     LEFT JOIN "public"."RPT_DashboardWidgets" "w" ON (("w"."RPTWidget_DashboardID" = "d"."RPTDash_ID")))
  WHERE (("d"."RPTDash_IsMVP" = true) AND ("d"."RPTDash_IsActive" = true));


ALTER VIEW "public"."RPT_MVPDashboardCatalog" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."RPT_MVPMetricLatest" WITH ("security_invoker"='true') AS
 SELECT DISTINCT ON ("k"."RPTKPI_Code", "r"."RPTKPIResult_OrgOfficeID", "r"."RPTKPIResult_LegalEntityID", "r"."RPTKPIResult_BrandID") "k"."RPTKPI_Code" AS "MetricCode",
    "k"."RPTKPI_Name" AS "MetricName",
    "k"."RPTKPI_CategoryCode" AS "CategoryCode",
    "k"."RPTKPI_ModuleCode" AS "ModuleCode",
    "k"."RPTKPI_Unit" AS "Unit",
    "r"."RPTKPIResult_OrgOfficeID" AS "OrgOfficeID",
    "r"."RPTKPIResult_LegalEntityID" AS "LegalEntityID",
    "r"."RPTKPIResult_BrandID" AS "BrandID",
    "r"."RPTKPIResult_PeriodStartDate" AS "PeriodStartDate",
    "r"."RPTKPIResult_PeriodEndDate" AS "PeriodEndDate",
    "r"."RPTKPIResult_Value" AS "Value",
    "r"."RPTKPIResult_TargetValue" AS "TargetValue",
    "r"."RPTKPIResult_StatusCode" AS "StatusCode",
    "r"."RPTKPIResult_CalculatedAt" AS "CalculatedAt"
   FROM ("public"."RPT_KPIs" "k"
     JOIN "public"."RPT_KPIResults" "r" ON (("r"."RPTKPIResult_KPIID" = "k"."RPTKPI_ID")))
  WHERE ("k"."RPTKPI_IsMVP" = true)
  ORDER BY "k"."RPTKPI_Code", "r"."RPTKPIResult_OrgOfficeID", "r"."RPTKPIResult_LegalEntityID", "r"."RPTKPIResult_BrandID", "r"."RPTKPIResult_PeriodEndDate" DESC, "r"."RPTKPIResult_CalculatedAt" DESC;


ALTER VIEW "public"."RPT_MVPMetricLatest" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."RPT_MVPExecutiveOverview" WITH ("security_invoker"='true') AS
 SELECT "count"(*) FILTER (WHERE (("CategoryCode")::"text" = 'jobs'::"text")) AS "JobMetricCount",
    "count"(*) FILTER (WHERE (("CategoryCode")::"text" = 'profit'::"text")) AS "ProfitMetricCount",
    "count"(*) FILTER (WHERE (("CategoryCode")::"text" = 'wip_accruals'::"text")) AS "WIPAccrualMetricCount",
    "count"(*) FILTER (WHERE (("CategoryCode")::"text" = 'debtors'::"text")) AS "DebtorMetricCount",
    "count"(*) FILTER (WHERE (("CategoryCode")::"text" = 'sales_pipeline'::"text")) AS "SalesMetricCount",
    "count"(*) FILTER (WHERE (("CategoryCode")::"text" = 'quote_conversion'::"text")) AS "QuoteMetricCount",
    "count"(*) FILTER (WHERE (("CategoryCode")::"text" = 'workflow_exceptions'::"text")) AS "WorkflowMetricCount",
    "count"(*) FILTER (WHERE (("CategoryCode")::"text" = 'tracking_exceptions'::"text")) AS "TrackingMetricCount",
    "count"(*) FILTER (WHERE (("CategoryCode")::"text" = 'compliance_alerts'::"text")) AS "ComplianceMetricCount",
    "max"("CalculatedAt") AS "LastCalculatedAt"
   FROM "public"."RPT_MVPMetricLatest";


ALTER VIEW "public"."RPT_MVPExecutiveOverview" OWNER TO "postgres";


