CREATE OR REPLACE VIEW "public"."SEC_CredentialReferenceSummary" WITH ("security_invoker"='true') AS
 SELECT "SECCred_ID" AS "CredentialID",
    "SECCred_Code" AS "CredentialCode",
    "SECCred_Name" AS "CredentialName",
    "SECCred_CredentialTypeCode" AS "CredentialTypeCode",
    "SECCred_StatusCode" AS "StatusCode",
    "SECCred_ModuleCode" AS "ModuleCode",
    "SECCred_ProviderCode" AS "ProviderCode",
    "SECCred_OrgOfficeID" AS "OrgOfficeID",
    "SECCred_VaultProvider" AS "VaultProvider",
    "SECCred_PublicFingerprint" AS "PublicFingerprint",
    "SECCred_ExpiresAt" AS "ExpiresAt",
    "SECCred_RotationDueAt" AS "RotationDueAt",
        CASE
            WHEN (("SECCred_ExpiresAt" IS NOT NULL) AND ("SECCred_ExpiresAt" < "now"())) THEN true
            ELSE false
        END AS "IsExpired",
        CASE
            WHEN (("SECCred_RotationDueAt" IS NOT NULL) AND ("SECCred_RotationDueAt" < "now"())) THEN true
            ELSE false
        END AS "IsRotationOverdue"
   FROM "public"."SEC_CredentialReferences" "c";


