CREATE OR REPLACE VIEW "public"."SEC_UserEffectivePermissions" WITH ("security_invoker"='true') AS
 SELECT "ur"."SECUserRole_UserID" AS "UserID",
    "r"."SECRole_ID" AS "RoleID",
    "r"."SECRole_Code" AS "RoleCode",
    "r"."SECRole_Name" AS "RoleName",
    "p"."SECPerm_ID" AS "PermissionID",
    "p"."SECPerm_Code" AS "PermissionCode",
    "p"."SECPerm_ModuleCode" AS "ModuleCode",
    "p"."SECPerm_ResourceTypeCode" AS "ResourceTypeCode",
    "p"."SECPerm_ActionCode" AS "ActionCode",
    "rp"."SECRolePerm_GrantActionCode" AS "GrantActionCode",
    "ur"."SECUserRole_EffectiveFrom" AS "EffectiveFrom",
    "ur"."SECUserRole_EffectiveTo" AS "EffectiveTo"
   FROM ((("public"."SEC_UserRoles" "ur"
     JOIN "public"."SEC_Roles" "r" ON (("r"."SECRole_ID" = "ur"."SECUserRole_RoleID")))
     JOIN "public"."SEC_RolePermissions" "rp" ON (("rp"."SECRolePerm_RoleID" = "r"."SECRole_ID")))
     JOIN "public"."SEC_Permissions" "p" ON (("p"."SECPerm_ID" = "rp"."SECRolePerm_PermissionID")))
  WHERE ((("ur"."SECUserRole_StatusCode")::"text" = 'active'::"text") AND (("rp"."SECRolePerm_GrantStatusCode")::"text" = 'active'::"text") AND ("r"."SECRole_IsActive" = true) AND ("p"."SECPerm_IsActive" = true) AND ("now"() >= "ur"."SECUserRole_EffectiveFrom") AND (("ur"."SECUserRole_EffectiveTo" IS NULL) OR ("now"() < "ur"."SECUserRole_EffectiveTo")));


ALTER VIEW "public"."SEC_UserEffectivePermissions" OWNER TO "postgres";


