    "TCEEvent_SourceTable" character varying(160),
    "TCEEvent_SourceID" "uuid",
    "TCEEvent_EventKey" character varying(180),
    "TCEEvent_PayloadJSON" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "TCEEvent_ProcessingNotes" "text",
    "TCEEvent_RetryCount" integer DEFAULT 0 NOT NULL,
    "TCEEvent_NextAttemptAt" timestamp with time zone,
