CREATE OR REPLACE VIEW "public"."TCE_OpenMatches" WITH ("security_invoker"='true') AS
 SELECT "match"."TCEMatch_ID",
    "match"."TCEMatch_RunID",
    "run"."TCERun_Number",
    "match"."TCEMatch_SubjectID",
    "subject"."TCESubject_RoleCode",
    "subject"."TCESubject_EntityTypeCode",
    "subject"."TCESubject_Name",
    "subject"."TCESubject_CountryCode",
    "match"."TCEMatch_EntryID",
    "entry"."TCEEntry_PrimaryName",
    "entry"."TCEEntry_ProgramCode",
    "entry"."TCEEntry_RegimeName",
    "source"."TCESource_Name",
    "match"."TCEMatch_ListTypeCode",
    "match"."TCEMatch_StatusCode",
    "match"."TCEMatch_StrengthCode",
    "match"."TCEMatch_RiskLevelCode",
    "match"."TCEMatch_Score",
    "match"."TCEMatch_MatchReason",
    "match"."TCEMatch_CaseID",
    "match"."TCEMatch_CreatedAt"
   FROM ((((("public"."TCE_ScreeningMatches" "match"
     JOIN "public"."TCE_ScreeningRuns" "run" ON (("run"."TCERun_ID" = "match"."TCEMatch_RunID")))
     JOIN "public"."TCE_ScreeningSubjects" "subject" ON (("subject"."TCESubject_ID" = "match"."TCEMatch_SubjectID")))
     LEFT JOIN "public"."TCE_WatchlistEntries" "entry" ON (("entry"."TCEEntry_ID" = "match"."TCEMatch_EntryID")))
     LEFT JOIN "public"."TCE_DataSources" "source" ON (("source"."TCESource_ID" = "match"."TCEMatch_SourceID")))
     LEFT JOIN "public"."sys_TCEMatchStatuses" "status" ON ((("status"."TCEMatchStatus_Code")::"text" = ("match"."TCEMatch_StatusCode")::"text")))
  WHERE (COALESCE("status"."TCEMatchStatus_IsOpen", true) = true);


ALTER VIEW "public"."TCE_OpenMatches" OWNER TO "postgres";


