CREATE OR REPLACE VIEW "public"."TCE_OriginPreferenceQueue" WITH ("security_invoker"='true') AS
 SELECT "pref"."TCEPref_ID",
    "pref"."TCEPref_StatusCode",
    "status"."TCEFTACheckStatus_Name",
    "pref"."TCEPref_JobID",
    "job"."Job_Number",
    "pref"."TCEPref_JobCargoID",
    "fta"."TCEFTA_Code",
    "fta"."TCEFTA_Name",
    "pref"."TCEPref_HSCode",
    "pref"."TCEPref_OriginCountryCode",
    "pref"."TCEPref_DestinationCountryCode",
    "pref"."TCEPref_DutyRateStandardPercent",
    "pref"."TCEPref_DutyRatePreferencePercent",
    "pref"."TCEPref_EstimatedDutySavingAmount",
    "pref"."TCEPref_CurrencyCodeSnapshot",
    "pref"."TCEPref_EvidenceDocumentID",
    "pref"."TCEPref_ReviewedBy",
    "pref"."TCEPref_ReviewedAt",
    "pref"."TCEPref_CreatedAt"
   FROM ((("public"."TCE_PreferenceClaims" "pref"
     LEFT JOIN "public"."sys_TCEFTACheckStatuses" "status" ON ((("status"."TCEFTACheckStatus_Code")::"text" = ("pref"."TCEPref_StatusCode")::"text")))
     LEFT JOIN "public"."Job_Header" "job" ON (("job"."Job_ID" = "pref"."TCEPref_JobID")))
     LEFT JOIN "public"."TCE_FTAAgreements" "fta" ON (("fta"."TCEFTA_ID" = "pref"."TCEPref_FTAID")));


