    "WMSOrder_SupplierReference" character varying(160),
    "WMSOrder_CarrierReference" character varying(160),
    "WMSOrder_EDIMessageID" "uuid",
    "WMSOrder_InboundFromOrgID" "uuid",
    "WMSOrder_OutboundToOrgID" "uuid",
    "WMSOrder_CarrierOrgID" "uuid",
    "WMSOrder_RequestedDate" "date",
    "WMSOrder_AppointmentStartAt" timestamp with time zone,
    "WMSOrder_AppointmentEndAt" timestamp with time zone,
    "WMSOrder_TransportModeCode" character varying(40),
    "WMSOrder_VehicleReg" character varying(60),
    "WMSOrder_ContainerNumber" character varying(20),
    "WMSOrder_SealNumber" character varying(80),
    "WMSOrder_RequiresCustomsRelease" boolean DEFAULT false NOT NULL,
    "WMSOrder_RequiresComplianceRelease" boolean DEFAULT false NOT NULL,
    "WMSOrder_RequiresFinanceRelease" boolean DEFAULT false NOT NULL,
    "WMSOrder_ReleaseGateStatusCode" character varying(60) DEFAULT 'not_checked'::character varying NOT NULL,
    "WMSOrder_Instructions" "text",
    "WMSOrder_MetadataJSON" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "WMSOrder_CreatedAt" timestamp with time zone DEFAULT "now"() NOT NULL,
    "WMSOrder_CreatedBy" "uuid",
    "WMSOrder_UpdatedAt" timestamp with time zone DEFAULT "now"() NOT NULL,
    "WMSOrder_UpdatedBy" "uuid",
    "WMSOrder_IsDeleted" boolean DEFAULT false NOT NULL,
    "WMSOrder_SourceTypeCode" character varying(60) DEFAULT 'manual_exception'::character varying NOT NULL,
    "WMSOrder_SourceReference" character varying(180) NOT NULL,
    "WMSOrder_SourceRecordID" "uuid",
    CONSTRAINT "CK_WMS_Orders_source_type" CHECK ((((("WMSOrder_TypeCode")::"text" = 'inbound'::"text") AND (("WMSOrder_SourceTypeCode")::"text" = ANY ((ARRAY['customer_purchase_order'::character varying, 'asn'::character varying, 'transfer'::character varying, 'return'::character varying, 'manual_exception'::character varying])::"text"[]))) OR ((("WMSOrder_TypeCode")::"text" = 'outbound'::"text") AND (("WMSOrder_SourceTypeCode")::"text" = ANY ((ARRAY['sales_order'::character varying, 'transfer'::character varying, 'return_to_supplier'::character varying, 'disposal'::character varying, 'manual_exception'::character varying])::"text"[])))))
);


