CREATE OR REPLACE VIEW "public"."WMS_BillingEventQueue" WITH ("security_invoker"='true') AS
 SELECT "be"."WMSBillEvent_ID",
    "be"."WMSBillEvent_FacilityID",
    "f"."WMSFacility_Name",
    "be"."WMSBillEvent_CustomerOrgID",
    "org"."Org_Name" AS "CustomerName",
    "be"."WMSBillEvent_OrderID",
    "o"."WMSOrder_OrderNumber",
    "be"."WMSBillEvent_JobID",
    "be"."WMSBillEvent_StatusCode",
    "be"."WMSBillEvent_EventTypeCode",
    "be"."WMSBillEvent_EventDate",
    "be"."WMSBillEvent_Description",
    "be"."WMSBillEvent_Quantity",
    "be"."WMSBillEvent_UnitRate",
    "be"."WMSBillEvent_NetAmount",
    "be"."WMSBillEvent_CurrencyCode"
   FROM ((("public"."WMS_BillingEvents" "be"
     JOIN "public"."WMS_Facilities" "f" ON (("f"."WMSFacility_ID" = "be"."WMSBillEvent_FacilityID")))
     LEFT JOIN "public"."Org_Master" "org" ON (("org"."Org_id" = "be"."WMSBillEvent_CustomerOrgID")))
     LEFT JOIN "public"."WMS_Orders" "o" ON (("o"."WMSOrder_ID" = "be"."WMSBillEvent_OrderID")))
  WHERE (("be"."WMSBillEvent_StatusCode")::"text" = ANY ((ARRAY['ready'::character varying, 'draft'::character varying])::"text"[]));


ALTER VIEW "public"."WMS_BillingEventQueue" OWNER TO "postgres";


