    "be"."WMSBondEntry_ID",
    "be"."WMSBondEntry_EntryReference",
    "be"."WMSBondEntry_DeclarationReference",
    "be"."WMSBondEntry_ProcedureTypeCode",
    "be"."WMSBondEntry_StatusCode",
    "bel"."WMSBondEntryLine_ID",
    "bel"."WMSBondEntryLine_HSCode",
    "bel"."WMSBondEntryLine_CountryOfOriginCode",
    "b"."WMSBalance_ID",
    "b"."WMSBalance_FacilityID",
    "f"."WMSFacility_Name",
    "b"."WMSBalance_CustomerOrgID",
    "org"."Org_Name" AS "CustomerName",
    "i"."WMSItem_SKU",
    "i"."WMSItem_Description",
    "b"."WMSBalance_LocationID",
    "l"."WMSLocation_Code",
    "bil"."WMSBondInvLink_LinkedQuantity",
    "bil"."WMSBondInvLink_RemainingQuantity",
    "b"."WMSBalance_OnHandQuantity",
    "b"."WMSBalance_HeldQuantity",
    "b"."WMSBalance_AvailableQuantity",
    "be"."WMSBondEntry_TotalDutyEstimate",
    "be"."WMSBondEntry_TotalTaxEstimate",
    "be"."WMSBondEntry_CurrencyCode"
   FROM ((((((("public"."WMS_BondedInventoryLinks" "bil"
     JOIN "public"."WMS_BondedEntries" "be" ON (("be"."WMSBondEntry_ID" = "bil"."WMSBondInvLink_EntryID")))
     JOIN "public"."WMS_BondedEntryLines" "bel" ON (("bel"."WMSBondEntryLine_ID" = "bil"."WMSBondInvLink_EntryLineID")))
     JOIN "public"."WMS_InventoryBalances" "b" ON (("b"."WMSBalance_ID" = "bil"."WMSBondInvLink_BalanceID")))
     JOIN "public"."WMS_Facilities" "f" ON (("f"."WMSFacility_ID" = "b"."WMSBalance_FacilityID")))
     JOIN "public"."WMS_Items" "i" ON (("i"."WMSItem_ID" = "b"."WMSBalance_ItemID")))
     LEFT JOIN "public"."Org_Master" "org" ON (("org"."Org_id" = "b"."WMSBalance_CustomerOrgID")))
     LEFT JOIN "public"."WMS_Locations" "l" ON (("l"."WMSLocation_ID" = "b"."WMSBalance_LocationID")));


