CREATE OR REPLACE VIEW "public"."WMS_ExceptionQueue" WITH ("security_invoker"='true') AS
 SELECT "e"."WMSException_ID",
    "e"."WMSException_FacilityID",
    "f"."WMSFacility_Name",
    "e"."WMSException_TypeCode",
    "e"."WMSException_StatusCode",
