    "o"."WMSOrder_OrderNumber",
    "e"."WMSException_JobID",
    "e"."WMSException_WorkflowTaskID",
    "e"."WMSException_RaisedAt",
    "e"."WMSException_ResolvedAt"
   FROM (("public"."WMS_Exceptions" "e"
     JOIN "public"."WMS_Facilities" "f" ON (("f"."WMSFacility_ID" = "e"."WMSException_FacilityID")))
     LEFT JOIN "public"."WMS_Orders" "o" ON (("o"."WMSOrder_ID" = "e"."WMSException_OrderID")))
