CREATE TABLE IF NOT EXISTS "public"."WMS_PurchaseOrders" (
    "WMSPO_ID" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "WMSPO_FacilityID" "uuid" NOT NULL,
    "WMSPO_CustomerOrgID" "uuid" NOT NULL,
    "WMSPO_SupplierOrgID" "uuid",
    "WMSPO_WarehouseOrderID" "uuid",
    "WMSPO_Number" character varying(120) NOT NULL,
    "WMSPO_StatusCode" character varying(30) DEFAULT 'draft'::character varying NOT NULL,
    "WMSPO_SupplierName" character varying(240) NOT NULL,
    "WMSPO_BuyerReference" character varying(160),
    "WMSPO_SupplierReference" character varying(160),
    "WMSPO_IssueDate" "date",
    "WMSPO_ExpectedDeliveryDate" "date",
    "WMSPO_CurrencyCode" character varying(3) DEFAULT 'GBP'::character varying NOT NULL,
    "WMSPO_DeliveryTerms" character varying(180),
    "WMSPO_PaymentTerms" character varying(180),
    "WMSPO_DeliveryAddress" "text",
    "WMSPO_Notes" "text",
    "WMSPO_NetAmount" numeric(18,4) DEFAULT 0 NOT NULL,
    "WMSPO_TaxAmount" numeric(18,4) DEFAULT 0 NOT NULL,
    "WMSPO_TotalAmount" numeric(18,4) DEFAULT 0 NOT NULL,
    "WMSPO_SourceFileName" character varying(240),
    "WMSPO_ExtractionModeCode" character varying(40),
    "WMSPO_ExtractionModel" character varying(120),
    "WMSPO_ExtractionMetadataJSON" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "WMSPO_Version" integer DEFAULT 1 NOT NULL,
    "WMSPO_CreatedAt" timestamp with time zone DEFAULT "now"() NOT NULL,
    "WMSPO_CreatedBy" "uuid",
    "WMSPO_UpdatedAt" timestamp with time zone DEFAULT "now"() NOT NULL,
