    "WMSPO_RecordRoleCode" character varying(50) DEFAULT 'customer_inbound_instruction'::character varying NOT NULL,
    CONSTRAINT "CK_WMS_PurchaseOrders_amounts" CHECK ((("WMSPO_NetAmount" >= (0)::numeric) AND ("WMSPO_TaxAmount" >= (0)::numeric) AND ("WMSPO_TotalAmount" >= (0)::numeric))),
    CONSTRAINT "CK_WMS_PurchaseOrders_currency" CHECK ((("WMSPO_CurrencyCode")::"text" ~ '^[A-Z]{3}$'::"text")),
    CONSTRAINT "CK_WMS_PurchaseOrders_extraction" CHECK (("jsonb_typeof"("WMSPO_ExtractionMetadataJSON") = 'object'::"text")),
    CONSTRAINT "CK_WMS_PurchaseOrders_record_role" CHECK ((("WMSPO_RecordRoleCode")::"text" = 'customer_inbound_instruction'::"text")),
    CONSTRAINT "CK_WMS_PurchaseOrders_status" CHECK ((("WMSPO_StatusCode")::"text" = ANY ((ARRAY['draft'::character varying, 'issued'::character varying, 'part_received'::character varying, 'received'::character varying, 'cancelled'::character varying])::"text"[])))
);


