CREATE OR REPLACE VIEW "public"."Workflow_ApprovalSummary" AS
SELECT
    NULL::"uuid" AS "WorkflowApproval_ID",
    NULL::"uuid" AS "WorkflowApproval_InstanceID",
    NULL::"uuid" AS "WorkflowApproval_TaskID",
