CREATE OR REPLACE VIEW "public"."Workflow_EscalationSummary" WITH ("security_invoker"='true') AS
 SELECT "e"."WorkflowEsc_ID",
    "e"."WorkflowEsc_InstanceID",
    "e"."WorkflowEsc_TaskID",
    "e"."WorkflowEsc_ApprovalID",
    "e"."WorkflowEsc_RecordTypeCode",
    "e"."WorkflowEsc_RecordID",
    "e"."WorkflowEsc_StatusCode",
    "es"."WorkflowEscStatus_IsOpen",
    "e"."WorkflowEsc_SeverityCode",
    "e"."WorkflowEsc_Title",
    "e"."WorkflowEsc_EscalatedAt",
    "e"."WorkflowEsc_EscalatedBy",
    "eb"."User_Email" AS "WorkflowEsc_EscalatedByEmail",
    "e"."WorkflowEsc_EscalatedToUserID",
    "eu"."User_Email" AS "WorkflowEsc_EscalatedToUserEmail",
    "e"."WorkflowEsc_EscalatedToRoleID",
    "e"."WorkflowEsc_EscalatedToQueueID",
    "q"."WorkflowQueue_Name" AS "WorkflowEsc_EscalatedToQueueName",
    "e"."WorkflowEsc_AcknowledgedAt",
    "e"."WorkflowEsc_ResolvedAt"
   FROM (((("public"."Workflow_Escalations" "e"
     LEFT JOIN "public"."sys_WorkflowEscalationStatuses" "es" ON ((("es"."WorkflowEscStatus_Code")::"text" = ("e"."WorkflowEsc_StatusCode")::"text")))
     LEFT JOIN "public"."cmp_Users" "eb" ON (("eb"."User_ID" = "e"."WorkflowEsc_EscalatedBy")))
     LEFT JOIN "public"."cmp_Users" "eu" ON (("eu"."User_ID" = "e"."WorkflowEsc_EscalatedToUserID")))
     LEFT JOIN "public"."Workflow_WorkQueues" "q" ON (("q"."WorkflowQueue_ID" = "e"."WorkflowEsc_EscalatedToQueueID")));


