CREATE OR REPLACE VIEW "public"."org_details_by_type" WITH ("security_invoker"='true') AS
 SELECT "om"."Org_id" AS "org_code",
    "om"."Org_Name",
    "ot"."OrgType_Name" AS "organization_type"
   FROM (("public"."Org_Master" "om"
     JOIN "public"."Org_Master_Type" "omt" ON (("om"."Org_id" = "omt"."Org_ID")))
     JOIN "public"."Org_Types" "ot" ON (("omt"."OrgType_ID" = "ot"."OrgType_ID")));


