CREATE OR REPLACE VIEW "public"."sys_CustomsOptionCatalogue" WITH ("security_invoker"='true') AS
 SELECT "catalog_code",
    "option_code",
    "option_name",
    "option_description",
    "direction",
    "sort_order"
   FROM ( SELECT ("sys_CustomsFormOptions"."CFO_CatalogCode")::"text" AS "catalog_code",
            ("sys_CustomsFormOptions"."CFO_Code")::"text" AS "option_code",
            ("sys_CustomsFormOptions"."CFO_Name")::"text" AS "option_name",
            "sys_CustomsFormOptions"."CFO_Description" AS "option_description",
            ("sys_CustomsFormOptions"."CFO_Direction")::"text" AS "direction",
            "sys_CustomsFormOptions"."CFO_SortOrder" AS "sort_order"
           FROM "public"."sys_CustomsFormOptions"
          WHERE "sys_CustomsFormOptions"."CFO_IsActive"
        UNION ALL
         SELECT 'declaration_category'::"text",
            ("sys_CDSDeclarationCategories"."CDSCAT_Code")::"text" AS "CDSCAT_Code",
            ("sys_CDSDeclarationCategories"."CDSCAT_Name")::"text" AS "CDSCAT_Name",
            "sys_CDSDeclarationCategories"."CDSCAT_Description",
            (COALESCE("sys_CDSDeclarationCategories"."CDSCAT_Direction", 'all'::character varying))::"text" AS "coalesce",
            "sys_CDSDeclarationCategories"."CDSCAT_SortOrder"
           FROM "public"."sys_CDSDeclarationCategories"
          WHERE "sys_CDSDeclarationCategories"."CDSCAT_IsActive"
        UNION ALL
         SELECT 'transport_mode'::"text",
            ("sys_CustomsTransportModes"."CTM_Code")::"text" AS "CTM_Code",
            ("sys_CustomsTransportModes"."CTM_Name")::"text" AS "CTM_Name",
            "sys_CustomsTransportModes"."CTM_Description",
            'all'::"text",
            "sys_CustomsTransportModes"."CTM_SortOrder"
           FROM "public"."sys_CustomsTransportModes"
          WHERE "sys_CustomsTransportModes"."CTM_IsActive"
        UNION ALL
         SELECT 'currency'::"text",
            ("sys_Currency"."Currency_Code")::"text" AS "Currency_Code",
            (COALESCE("sys_Currency"."Currency_Name", "sys_Currency"."Currency_Code"))::"text" AS "coalesce",
            NULL::"text" AS "text",
            'all'::"text",
            0
           FROM "public"."sys_Currency"
          WHERE ("sys_Currency"."Currency_Code" IS NOT NULL)
        UNION ALL
         SELECT 'country'::"text",
            ("RefCountry"."RN_Code")::"text" AS "RN_Code",
            (COALESCE("RefCountry"."RN_Desc", "RefCountry"."RN_Code"))::"text" AS "coalesce",
            NULL::"text" AS "text",
            'all'::"text",
            0
           FROM "public"."RefCountry"
          WHERE (COALESCE("RefCountry"."RN_IsActive", false) AND ("RefCountry"."RN_Code" IS NOT NULL))) "option_row";


ALTER VIEW "public"."sys_CustomsOptionCatalogue" OWNER TO "postgres";


COMMENT ON VIEW "public"."sys_CustomsOptionCatalogue" IS 'Security-invoker catalogue combining Customs form enums with authoritative country, currency, category, and transport reference tables.';



