CREATE TABLE IF NOT EXISTS "quote_api"."customer_response_links" (
    "response_link_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "company_id" "uuid" NOT NULL,
    "quote_id" "uuid" NOT NULL,
    "quote_version_id" "uuid" NOT NULL,
    "recipient_name" character varying(180),
    "recipient_email" character varying(320) NOT NULL,
    "response_origin" character varying(255) NOT NULL,
    "token_hash" character varying(64) NOT NULL,
    "status_code" character varying(30) DEFAULT 'active'::character varying NOT NULL,
    "expires_at" timestamp with time zone,
    "first_opened_at" timestamp with time zone,
    "responded_at" timestamp with time zone,
    "revoked_at" timestamp with time zone,
    "delivery_status_code" character varying(30) DEFAULT 'pending'::character varying NOT NULL,
    "delivery_provider_id" character varying(180),
    "delivery_error" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by" "uuid",
    "competitor_document_id" "uuid",
    "quote_document_id" "uuid",
    "delivery_mode_code" "text" DEFAULT 'standard'::"text" NOT NULL,
    "recipient_source_code" "text" DEFAULT 'saved'::"text" NOT NULL,
    "delivery_mailbox_id" "uuid",
    "follow_up_status_code" character varying(30) DEFAULT 'not_scheduled'::character varying NOT NULL,
    "follow_up_attempt_count" smallint DEFAULT 0 NOT NULL,
    "follow_up_next_attempt_at" timestamp with time zone,
    "follow_up_sent_at" timestamp with time zone,
    "follow_up_delivery_provider_id" "text",
    "follow_up_error" "text",
    "follow_up_lease_token" "uuid",
    "follow_up_lease_expires_at" timestamp with time zone,
    CONSTRAINT "customer_response_links_delivery" CHECK ((("delivery_status_code")::"text" = ANY ((ARRAY['pending'::character varying, 'sent'::character varying, 'failed'::character varying])::"text"[]))),
    CONSTRAINT "customer_response_links_delivery_mode_check" CHECK (("delivery_mode_code" = ANY (ARRAY['standard'::"text", 'simple'::"text"]))),
    CONSTRAINT "customer_response_links_expiry" CHECK ((("expires_at" IS NULL) OR ("expires_at" > "created_at"))),
    CONSTRAINT "customer_response_links_follow_up_attempt_check" CHECK ((("follow_up_attempt_count" >= 0) AND ("follow_up_attempt_count" <= 3))),
    CONSTRAINT "customer_response_links_follow_up_status_check" CHECK ((("follow_up_status_code")::"text" = ANY ((ARRAY['not_scheduled'::character varying, 'pending'::character varying, 'processing'::character varying, 'retryable'::character varying, 'sent'::character varying, 'cancelled'::character varying, 'failed'::character varying])::"text"[]))),
    CONSTRAINT "customer_response_links_origin" CHECK (((("response_origin")::"text" ~ '^https://([a-z0-9]|[a-z0-9][a-z0-9-]{0,61}[a-z0-9])\.multideck\.app$'::"text") OR (("response_origin")::"text" ~ '^https?://(localhost|127\.0\.0\.1):3000$'::"text"))),
    CONSTRAINT "customer_response_links_recipient_source_check" CHECK (("recipient_source_code" = ANY (ARRAY['saved'::"text", 'manual'::"text"]))),
    CONSTRAINT "customer_response_links_status" CHECK ((("status_code")::"text" = ANY ((ARRAY['active'::character varying, 'responded'::character varying, 'expired'::character varying, 'revoked'::character varying])::"text"[]))),
    CONSTRAINT "customer_response_links_token_hash" CHECK ((("token_hash")::"text" ~ '^[0-9a-f]{64}$'::"text"))
);


ALTER TABLE "quote_api"."customer_response_links" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "quote_api"."customer_response_upload_reservations" (
    "reservation_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "response_link_id" "uuid" NOT NULL,
    "idempotency_key" "uuid" NOT NULL,
    "source_ip_hash" character varying(64),
    "blob_name" character varying(1024) NOT NULL,
    "file_size_bytes" bigint NOT NULL,
    "status_code" character varying(20) DEFAULT 'reserved'::character varying NOT NULL,
    "stored_object_id" "uuid",
    "reserved_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "expires_at" timestamp with time zone DEFAULT ("now"() + '00:10:00'::interval) NOT NULL,
    "completed_at" timestamp with time zone,
    CONSTRAINT "customer_response_upload_ip_hash" CHECK ((("source_ip_hash" IS NULL) OR (("source_ip_hash")::"text" ~ '^[0-9a-f]{64}$'::"text"))),
    CONSTRAINT "customer_response_upload_reservations_file_size_bytes_check" CHECK ((("file_size_bytes" > 0) AND ("file_size_bytes" <= 10485760))),
    CONSTRAINT "customer_response_upload_reservations_status_code_check" CHECK ((("status_code")::"text" = ANY ((ARRAY['reserved'::character varying, 'completed'::character varying, 'cancelled'::character varying, 'expired'::character varying])::"text"[])))
);


ALTER TABLE "quote_api"."customer_response_upload_reservations" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "quote_api"."customer_responses" (
    "response_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "company_id" "uuid" NOT NULL,
    "response_link_id" "uuid" NOT NULL,
    "quote_id" "uuid" NOT NULL,
    "quote_version_id" "uuid" NOT NULL,
    "decision_code" character varying(30) NOT NULL,
    "customer_message" "text",
    "competitor_document_id" "uuid",
    "source_ip_hash" character varying(64),
    "user_agent_summary" character varying(500),
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "decline_reason_code" character varying(60),
    CONSTRAINT "customer_responses_decision" CHECK ((("decision_code")::"text" = ANY ((ARRAY['accepted'::character varying, 'declined'::character varying, 'challenged'::character varying])::"text"[]))),
    CONSTRAINT "customer_responses_decline_reason" CHECK ((((("decision_code")::"text" = 'declined'::"text") AND ("decline_reason_code" IS NOT NULL) AND (("decline_reason_code")::"text" = ANY ((ARRAY['cost_too_high'::character varying, 'estimated_times_too_late'::character varying, 'found_cheaper_quote'::character varying, 'research_only'::character varying, 'job_no_longer_needed'::character varying, 'other'::character varying])::"text"[]))) OR ((("decision_code")::"text" <> 'declined'::"text") AND ("decline_reason_code" IS NULL)))),
    CONSTRAINT "customer_responses_ip_hash" CHECK ((("source_ip_hash" IS NULL) OR (("source_ip_hash")::"text" ~ '^[0-9a-f]{64}$'::"text"))),
    CONSTRAINT "customer_responses_message" CHECK (((("decision_code")::"text" = ANY ((ARRAY['accepted'::character varying, 'declined'::character varying])::"text"[])) OR (("customer_message" IS NOT NULL) AND (NULLIF("btrim"("customer_message"), ''::"text") IS NOT NULL))))
);


ALTER TABLE "quote_api"."customer_responses" OWNER TO "postgres";


