    SEQUENCE NAME "report_api"."audit_id_seq"
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);



CREATE TABLE IF NOT EXISTS "report_api"."schedules" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "report_id" "uuid" NOT NULL,
    "owner_id" "uuid" NOT NULL,
    "company_id" "uuid" NOT NULL,
    "frequency" "text" NOT NULL,
    "timezone" "text" NOT NULL,
    "local_time" time without time zone NOT NULL,
    "weekday" integer DEFAULT 1 NOT NULL,
    "monthday" integer DEFAULT 1 NOT NULL,
    "paused" boolean DEFAULT false NOT NULL,
    "next_run_at" timestamp with time zone NOT NULL,
    "last_run_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "schedules_frequency_check" CHECK (("frequency" = ANY (ARRAY['daily'::"text", 'weekly'::"text", 'monthly'::"text"]))),
    CONSTRAINT "schedules_monthday_check" CHECK ((("monthday" >= 1) AND ("monthday" <= 28))),
    CONSTRAINT "schedules_weekday_check" CHECK ((("weekday" >= 0) AND ("weekday" <= 6)))
);


ALTER TABLE "report_api"."schedules" OWNER TO "postgres";


