CREATE POLICY "Allocation watches require Booking access" ON "public"."AI_DexterWatches" AS RESTRICTIVE FOR SELECT TO "authenticated" USING (((("AIDexterWatch_CapabilityCode")::"text" <> 'booking_allocations'::"text") OR "public"."multideck_dexter_can_read_cargo_watch"("AIDexterWatch_CompanyID")));



CREATE POLICY "App read company cargo" ON "public"."Job_Cargo" FOR SELECT TO "authenticated" USING ((EXISTS ( SELECT 1
   FROM "public"."Job_Header" "j"
  WHERE ("j"."Job_ID" = "Job_Cargo"."JobCargo_JobID"))));



CREATE POLICY "App read company colleagues" ON "public"."cmp_Users" FOR SELECT TO "authenticated" USING (("Company_ID" = "public"."app_current_company_id"()));



CREATE POLICY "App read company documents" ON "public"."DOC_StoredObjects" FOR SELECT TO "authenticated" USING ((EXISTS ( SELECT 1
   FROM "public"."cmp_Users" "u"
  WHERE (("u"."User_ID" = "DOC_StoredObjects"."DOCStoredObject_CreatedBy") AND ("u"."Company_ID" = "public"."app_current_company_id"())))));



CREATE POLICY "App read company jobs" ON "public"."Job_Header" FOR SELECT TO "authenticated" USING ("public"."app_user_can_access_office"(COALESCE("Job_OrgOfficeID", "Job_OfficeID")));



CREATE POLICY "App read company offices" ON "public"."cmp_Offices" FOR SELECT TO "authenticated" USING (("Company_ID" = "public"."app_current_company_id"()));



CREATE POLICY "App read company organisations" ON "public"."Org_Master" FOR SELECT TO "authenticated" USING ("public"."app_user_can_access_organisation"("Org_id"));



CREATE POLICY "App read company quote lines" ON "public"."CusQuote_Lines" FOR SELECT TO "authenticated" USING ((EXISTS ( SELECT 1
   FROM "public"."CusQuote_Header" "q"
  WHERE ("q"."CusQuoteHeader_ID" = "CusQuote_Lines"."CusQuoteHeader_ID"))));



CREATE POLICY "App read company quotes" ON "public"."CusQuote_Header" FOR SELECT TO "authenticated" USING ("public"."app_user_can_access_office"(COALESCE("CusQuoteHeader_OrgOfficeID", "OrgOffice_ID")));



CREATE POLICY "App read company report runs" ON "public"."RPT_ReportRuns" FOR SELECT TO "authenticated" USING ((EXISTS ( SELECT 1
   FROM "public"."cmp_Users" "u"
  WHERE (("u"."User_ID" = "RPT_ReportRuns"."RPTReportRun_RequestedBy") AND ("u"."Company_ID" = "public"."app_current_company_id"())))));



CREATE POLICY "App read company routes" ON "public"."Job_Routing" FOR SELECT TO "authenticated" USING ((EXISTS ( SELECT 1
   FROM "public"."Job_Header" "j"
  WHERE ("j"."Job_ID" = "Job_Routing"."Job_ID"))));



CREATE POLICY "App read reports" ON "public"."RPT_ReportDefinitions" FOR SELECT TO "authenticated" USING ("RPTReport_IsActive");



