CREATE POLICY "Dexter owners can read their watch events" ON "public"."AI_DexterWatchEvents" FOR SELECT TO "authenticated" USING ((EXISTS ( SELECT 1
   FROM ("public"."AI_DexterWatches" "watch"
     JOIN "public"."cmp_Users" "workspace_user" ON ((("workspace_user"."User_ID" = "watch"."AIDexterWatch_OwnerUserID") AND ("workspace_user"."Company_ID" = "watch"."AIDexterWatch_CompanyID"))))
  WHERE (("watch"."AIDexterWatch_ID" = "AI_DexterWatchEvents"."AIDexterWatchEvent_WatchID") AND ("workspace_user"."Auth_User_ID" = ( SELECT "auth"."uid"() AS "uid")) AND ("AI_DexterWatchEvents"."AIDexterWatchEvent_OwnerUserID" = "workspace_user"."User_ID") AND ((("watch"."AIDexterWatch_CapabilityCode")::"text" <> 'deals'::"text") OR "public"."multideck_crm_deal_is_visible"((NULLIF(("AI_DexterWatchEvents"."AIDexterWatchEvent_ChangedJSON" ->> 'sourceId'::"text"), ''::"text"))::"uuid"))))));



CREATE POLICY "Dexter owners can read their watches" ON "public"."AI_DexterWatches" FOR SELECT TO "authenticated" USING ((EXISTS ( SELECT 1
   FROM "public"."cmp_Users" "workspace_user"
  WHERE (("workspace_user"."User_ID" = "AI_DexterWatches"."AIDexterWatch_OwnerUserID") AND ("workspace_user"."Auth_User_ID" = ( SELECT "auth"."uid"() AS "uid")) AND ("workspace_user"."Company_ID" = "AI_DexterWatches"."AIDexterWatch_CompanyID") AND ((("AI_DexterWatches"."AIDexterWatch_CapabilityCode")::"text" <> 'deals'::"text") OR ("AI_DexterWatches"."AIDexterWatch_TargetID" IS NULL) OR "public"."multideck_crm_deal_is_visible"("AI_DexterWatches"."AIDexterWatch_TargetID"))))));



CREATE POLICY "Drive files are created inside the company" ON "public"."CRM_DriveFiles" FOR INSERT TO "authenticated" WITH CHECK ((("Company_ID" = "public"."app_current_company_id"()) AND "public"."_crm_drive_has_permission"('CRM.Drive.Write'::"text") AND "public"."_crm_drive_storage_path_allowed"("Company_ID", "DriveFile_StoragePath") AND "public"."_crm_drive_file_path_allowed_v2"("DriveFile_ID", "DriveFile_StoragePath", false) AND (("DriveFile_ThumbnailPath" IS NULL) OR ("public"."_crm_drive_storage_path_allowed"("Company_ID", "DriveFile_ThumbnailPath") AND "public"."_crm_drive_file_path_allowed_v2"("DriveFile_ID", "DriveFile_ThumbnailPath", true))) AND (("DriveFile_FolderID" IS NULL) OR (EXISTS ( SELECT 1
   FROM "public"."CRM_DriveFolders" "folder"
  WHERE (("folder"."DriveFolder_ID" = "CRM_DriveFiles"."DriveFile_FolderID") AND ("folder"."Company_ID" = "public"."app_current_company_id"())))))));



CREATE POLICY "Drive files are edited inside the company" ON "public"."CRM_DriveFiles" FOR UPDATE TO "authenticated" USING ((("Company_ID" = "public"."app_current_company_id"()) AND "public"."_crm_drive_has_permission"('CRM.Drive.Write'::"text"))) WITH CHECK ((("Company_ID" = "public"."app_current_company_id"()) AND "public"."_crm_drive_has_permission"('CRM.Drive.Write'::"text") AND "public"."_crm_drive_storage_path_allowed"("Company_ID", "DriveFile_StoragePath") AND "public"."_crm_drive_file_path_allowed_v2"("DriveFile_ID", "DriveFile_StoragePath", false) AND (("DriveFile_ThumbnailPath" IS NULL) OR ("public"."_crm_drive_storage_path_allowed"("Company_ID", "DriveFile_ThumbnailPath") AND "public"."_crm_drive_file_path_allowed_v2"("DriveFile_ID", "DriveFile_ThumbnailPath", true))) AND (("DriveFile_FolderID" IS NULL) OR (EXISTS ( SELECT 1
   FROM "public"."CRM_DriveFolders" "folder"
  WHERE (("folder"."DriveFolder_ID" = "CRM_DriveFiles"."DriveFile_FolderID") AND ("folder"."Company_ID" = "public"."app_current_company_id"())))))));



CREATE POLICY "Drive files are readable inside the company" ON "public"."CRM_DriveFiles" FOR SELECT TO "authenticated" USING ((("Company_ID" = "public"."app_current_company_id"()) AND "public"."_crm_drive_has_permission"('CRM.Drive.Read'::"text")));



CREATE POLICY "Drive files are removed inside the company" ON "public"."CRM_DriveFiles" FOR DELETE TO "authenticated" USING ((("Company_ID" = "public"."app_current_company_id"()) AND "public"."_crm_drive_has_permission"('CRM.Drive.Write'::"text")));



CREATE POLICY "Drive folders are created inside the company" ON "public"."CRM_DriveFolders" FOR INSERT TO "authenticated" WITH CHECK ((("Company_ID" = "public"."app_current_company_id"()) AND "public"."_crm_drive_has_permission"('CRM.Drive.Write'::"text") AND (("DriveFolder_ParentID" IS NULL) OR "public"."crm_drive_parent_belongs_to_current_company"("DriveFolder_ParentID"))));



CREATE POLICY "Drive folders are edited inside the company" ON "public"."CRM_DriveFolders" FOR UPDATE TO "authenticated" USING ((("Company_ID" = "public"."app_current_company_id"()) AND "public"."_crm_drive_has_permission"('CRM.Drive.Write'::"text"))) WITH CHECK ((("Company_ID" = "public"."app_current_company_id"()) AND "public"."_crm_drive_has_permission"('CRM.Drive.Write'::"text") AND (("DriveFolder_ParentID" IS NULL) OR "public"."crm_drive_parent_belongs_to_current_company"("DriveFolder_ParentID"))));



CREATE POLICY "Drive folders are readable inside the company" ON "public"."CRM_DriveFolders" FOR SELECT TO "authenticated" USING ((("Company_ID" = "public"."app_current_company_id"()) AND "public"."_crm_drive_has_permission"('CRM.Drive.Read'::"text")));



CREATE POLICY "Drive folders are removed inside the company" ON "public"."CRM_DriveFolders" FOR DELETE TO "authenticated" USING ((("Company_ID" = "public"."app_current_company_id"()) AND "public"."_crm_drive_has_permission"('CRM.Drive.Write'::"text")));



