CREATE POLICY "Portal users can read own customer facility access" ON "public"."WMS_CustomerFacilityAccess" FOR SELECT TO "authenticated" USING ((EXISTS ( SELECT 1
   FROM (("public"."Portal_ExternalIdentities" "identity_link"
     JOIN "public"."Portal_Users" "portal_user" ON (("portal_user"."PortalUser_ID" = "identity_link"."PortalIdentity_PortalUserID")))
     JOIN "public"."Portal_UserOrganisations" "user_org" ON (("user_org"."PortalUserOrg_PortalUserID" = "portal_user"."PortalUser_ID")))
  WHERE ((("identity_link"."PortalIdentity_ExternalSubject")::"text" = (( SELECT "auth"."uid"() AS "uid"))::"text") AND (("identity_link"."PortalIdentity_StatusCode")::"text" = 'active'::"text") AND (("portal_user"."PortalUser_StatusCode")::"text" = 'active'::"text") AND (("user_org"."PortalUserOrg_StatusCode")::"text" = 'active'::"text") AND ("user_org"."PortalUserOrg_OrgID" = "WMS_CustomerFacilityAccess"."WMSCustomerFacilityAccess_CustomerOrgID")))));



