CREATE POLICY "Quote readers can read intelligence" ON "public"."CusQuote_Intelligence" FOR SELECT TO "authenticated" USING (("Company_ID" = ( SELECT "profile"."Company_ID"
   FROM "public"."cmp_Users" "profile"
  WHERE (("profile"."Auth_User_ID" = ( SELECT "auth"."uid"() AS "uid")) AND ("profile"."User_AccessStatus" = 'active'::"text") AND (EXISTS ( SELECT 1
           FROM (("public"."cmp_Users_Roles" "user_role"
             JOIN "public"."sys_UserRole_Permissions" "role_permission" ON (("role_permission"."sys_UserRole_ID" = "user_role"."sys_UserRole_ID")))
             JOIN "public"."sys_Permissions" "permission" ON (("permission"."sys_Permission_ID" = "role_permission"."sys_Permission_ID")))
          WHERE (("user_role"."User_ID" = "profile"."User_ID") AND (("permission"."sys_Permission_Value")::"text" = 'Quotes.Read'::"text")))))
 LIMIT 1)));



